        </button>
      ))}
    </Box>
  );
}

runtime.app/chrome/Tabstrip.tsx:
// Tabstrip -- the console's workspace tab strip. Now a thin adapter over the
// shared <TabBar> (#463): it maps the console's index-based API to TabBar's
// generic id-based model (id = the tab's array index) and supplies the
// layout-picker context menu. All the drag/reorder/tear-off/rename behavior lives
// in TabBar, shared with every other page.

import { Pencil } from "lucide-react";
import { TabBar, type TabItem } from "@/shared/ui/layouts/TabBar";
import { Row } from "@/shared/ui/layout/Row";
import { Grid } from "@/shared/ui/layout/Grid";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

export interface Tab {
  /** Stable identity (#463), minted at creation. Survives reorder/close/detach,
   *  so the detached set, persisted order, and re-dock key off it (not the array
   *  index). Optional in the type for legacy/test literals; the store backfills
   *  one on hydration and mints one for every tab it creates. */
  id?: string;
  name: string;
  layout: string;
  state?: "run" | "on" | "idle";
  // Bumped when a tab's sessions are relaunched (e.g. triage re-run) so the panes
  // remount with fresh PTYs. Woven into ConsoleWorkspace's pane key; transient.
  runId?: number;
  // Stable project identity for fleet/triage tabs (#457): the sanitized projectKey
  // (a GitHub node id where possible). The reuse lookup matches on THIS, not the
  // derived `name`, so renaming the project relabels the tab without forking a
  // duplicate "· build"/"· triage" tab (the "two directors" bug). Absent for
  // ad-hoc / manually-named tabs.
  projectKey?: string;
  // Which kind of project tab this is (#457) — pairs with `projectKey` (+ `seq`) in
  // the reuse lookup. Absent for ad-hoc tabs.
  kind?: "build" | "triage";
  // 0-based build-tab sequence for multi-tab fleets (#457): 0 = primary "· build",
  // 1 = "· build 2", … Ignored for triage. Absent ⇒ 0.
  seq?: number;
  // Stable pane IDENTITY ids per grid cell (#1176), minted at fleet/triage launch
  // (`<projectKey>:<streamId>` / `:director` / `<projectKey>:<repo>:triage`). When present,
  // `paneIdFor` keys pane state/PTY/recovery off these instead of the grid position. Manual tabs
  // leave this unset and derive an ephemeral `man:<tabId>:p<idx>` id. Stage 2 populates it.
  paneIds?: string[];
}

const LAYOUTS = ["1×1", "2×1", "1×2", "2×2", "3×2", "3×3"] as const;

interface TabstripProps {
  tabs: Tab[];
  activeIdx?: number;
  onSelect?: (idx: number) => void;
  onClose?: (idx: number) => void;
  onAdd?: () => void;
  onRename?: (idx: number, name: string) => void;
  onChangeLayout?: (idx: number, layout: string) => void;
  onReorder?: (from: number, to: number) => void;
  onTearOff?: (idx: number) => void;
  /** Tab ids to hide from the bar (detached into their own window, #430). */
  hiddenIds?: string[];
}

function LayoutMenu({ layout, onRename, onPick }: {
  layout?: string; onRename: () => void; onPick: (layout: string) => void;
}) {
  return (
    <>
      {/* eslint-disable-next-line no-restricted-syntax -- bespoke context-menu item with hover-swap inline styling (not the .btn kit) */}
      <button
        onClick={onRename}
        style={{
          width: "100%", padding: "7px 12px", background: "transparent", border: "none",
          color: "var(--fg-muted)", fontSize: 11.5, textAlign: "left", cursor: "pointer",
          display: "flex", alignItems: "center", gap: 8,
        }}
        onMouseEnter={(e) => ((e.currentTarget as HTMLButtonElement).style.background = "var(--bg-elev)")}
        onMouseLeave={(e) => ((e.currentTarget as HTMLButtonElement).style.background = "transparent")}
      >
        <Pencil size={12} /> Rename
      </button>
      <Box bg="var(--border-soft)" style={{ height: 1, margin: "0 8px" }} />
      <Box style={{ padding: "6px 12px 10px" }}>
        <Text as="div" size={9.5} tone="dim" style={{ marginBottom: 7, textTransform: "uppercase", letterSpacing: "0.07em" }}>
          Layout
        </Text>
        <Row gap={5} align="stretch" wrap>
          {LAYOUTS.map((l) => {
            const [c, r] = l.split("×").map(Number);
            const current = layout === l;
            return (
              // eslint-disable-next-line no-restricted-syntax -- bespoke layout-swatch button (grid-preview + active-state inline styling, not the .btn kit)
              <button
                key={l}
                className="mono"
                onClick={() => onPick(l)}
                title={l}
                style={{
                  padding: "5px 7px", borderRadius: 4, cursor: "pointer",
                  fontSize: 10,
                  background: current ? "color-mix(in oklch, var(--accent), transparent 85%)" : "var(--bg-elev)",
                  border: "1px solid " + (current ? "var(--accent-dim)" : "var(--border-soft)"),
                  color: current ? "var(--accent)" : "var(--fg-muted)",
                  display: "flex", flexDirection: "column", alignItems: "center", gap: 4,
                }}
              >
                <Grid cols={`repeat(${c}, 8px)`} rows={`repeat(${r}, 5px)`} gap={1.5}>
                  {Array.from({ length: c * r }).map((_, idx) => (
                    <Box key={idx} bg={current ? "var(--accent)" : "var(--border)"} radius={1} />
                  ))}
                </Grid>
                {l}
              </button>
            );
          })}
        </Row>
      </Box>
    </>
  );
}

export function Tabstrip({
  tabs, activeIdx = 0, onSelect, onClose, onAdd, onRename, onChangeLayout, onReorder, onTearOff, hiddenIds = [],
}: TabstripProps) {
  // Identity is the stable tab id; fall back to the array index for legacy/test
  // tabs that predate ids. All console callbacks are index-based, so map back.
  const idOf = (i: number) => tabs[i]?.id ?? String(i);
  const idxOf = (id: string) => tabs.findIndex((_, i) => idOf(i) === id);
  // Detached tabs are hidden from the bar (still in the array, so their place is
  // kept). Reorder positions are in this visible subset → translate to full idx.
  const items: TabItem[] = tabs
    .map((t, i) => ({ id: idOf(i), label: t.name, status: t.state, meta: t.layout }))
    .filter((it) => !hiddenIds.includes(it.id));
  return (
    <TabBar
      tabs={items}
      activeId={idOf(activeIdx)}
      onSelect={(id) => onSelect?.(idxOf(id))}
      onAdd={onAdd}
      onClose={onClose ? (id) => onClose(idxOf(id)) : undefined}
      onRename={onRename ? (id, name) => onRename(idxOf(id), name) : undefined}
      onReorder={onReorder ? (from, to) => onReorder(idxOf(items[from].id), idxOf(items[to].id)) : undefined}
      onTearOff={onTearOff ? (id) => onTearOff(idxOf(id)) : undefined}
      renderMenu={(id, ctx) => (
        <LayoutMenu
          layout={tabs[idxOf(id)]?.layout}
          onRename={ctx.startRename}
          onPick={(l) => { onChangeLayout?.(idxOf(id), l); ctx.close(); }}
        />
      )}
    />
  );
}

runtime.app/console/lib/detachWindow.ts:
// detachWindow -- open a console tab in its own OS window (tab tear-off, #430).
//
// A detached window loads the same app with `?detachTab=<idx>`; App reads that
// (via detachedTabIndex) and renders just that tab's console. State comes from
// the shared persisted store (the new window hydrates the same snapshot); PTY
// sessions are backend-owned by paneId, so the detached panes re-attach to the
// same sessions rather than forking them.

import { WebviewWindow } from "@tauri-apps/api/webviewWindow";

let seq = 0;

/**
 * The detached tab index encoded in a window's URL, or null for the main window.
 * Pure (search is injectable) so it's unit-testable.
 */
/** The detached console tab's stable id (`?detachTab=<id>`), or null for the
 *  main / section windows. Id-based so the window pins to the tab across
 *  reorders. Pure. */
export function detachedTabId(search: string = window.location.search): string | null {
  return new URLSearchParams(search).get("detachTab");
}

/** A detached page-section window's target (`?detach=<page>&section=<id>`), or
 *  null for the main / console-tab windows. Pure. */
export function detachedSection(search: string = window.location.search): { page: string; section: string } | null {
  const p = new URLSearchParams(search);
  const page = p.get("detach");
  const section = p.get("section");
  return page && section ? { page, section } : null;
}

// openDetachedSection (page-section tear-off) moved to shared/ (#1703): it's a
// generic webview helper used by shared/hooks/usePageTabs + the projects feature,
// none of which should reach into app/console. See shared/lib/core/detachSection.

/**
 * Open tab `idx` in its own OS window. Best-effort: logs and swallows failures
 * so a denied/edge case never breaks the drag gesture.
 */
export function openDetachedTab(tabId: string, title?: string, onClose?: () => void): void {
  seq += 1;
  const label = `tab-${tabId}-${seq}`.replace(/[^A-Za-z0-9/:_-]/g, "_");
  // Load the SAME app this window is already running, just with the detach marker.
  // Deriving from window.location is robust across dev (http://localhost:1420) and
  // prod (the asset protocol) — a bare relative "index.html" doesn't reliably
  // resolve under the dev server and yields a blank window.
  const u = new URL(window.location.href);
  u.hash = "";
  u.search = `?detachTab=${encodeURIComponent(tabId)}`;
  try {
    const w = new WebviewWindow(label, {
      url: u.href,
      title: title || "Console",
      width: 960,
      height: 720,
      decorations: false, // use the app's custom titlebar, not the native OS frame
      // #3925: a RUNTIME window does not inherit tauri.conf.json's `dragDropEnabled: false`, so without
      // this its WebView swallows every HTML5 drag event for OS file-drop (the #461 bug).
      dragDropEnabled: false,
    });
    // Re-dock when the detached window closes (best-effort; restart recovers it
    // regardless, since the detached set is session-only).
    if (onClose) w.once("tauri://destroyed", () => onClose());
  } catch (e) {
    console.error("openDetachedTab failed:", e);
  }
}

runtime.app/console/lib/focusQueue.ts:
// Pure logic for the console focus queue — the ordered set of panes (across all
// tabs) that finished a turn (run -> idle) and await a response, cycled through
// with Ctrl+Shift+N or auto-advance on reply. A pane stays queued (even while you
// view it) until you actually send it a response; advancing just moves the cursor,
// switching tabs when the next waiting pane lives on a different tab.

/** A pane's global identity: which tab it's on and its index within that tab. */
export interface QueuedPane {
  tab: number;
  pane: number;
}

// ── Role-aware focus targeting (#392) ─────────────────────────────────────────
//
// Which panes the autofocus queue pulls your attention to. With a director/worker
// fleet, you usually want only the DIRECTOR to surface — workers run dark and
// escalate via bsc-ask (which flips their pane to awaiting-input through the
// coordinator), so genuine worker questions still reach you. A plain console
// (no role) always queues, except under "none".

export type FocusTarget =
  | "director"   // default: the integrator + plain consoles; workers run dark
  | "workers"    // workers + plain consoles (debug worker behavior)
  | "fleet"      // every fleet role (director + workers) + consoles
  | "everything" // every idle pane, whatever its role
  | "none";      // nothing auto-queues (fully manual)

/** The presets, in display order — for a picker control. */
export const FOCUS_TARGETS: FocusTarget[] = ["director", "workers", "fleet", "everything", "none"];

/** Default focus target — surface the director; let workers run dark. */
export const DEFAULT_FOCUS_TARGET: FocusTarget = "director";

/** Human label for a focus target. */
export function focusTargetLabel(t: FocusTarget): string {
  switch (t) {
    case "director": return "Director";
    case "workers": return "Workers";
    case "fleet": return "Director + workers";
    case "everything": return "Everything";
    case "none": return "None";
  }
}

/**
 * Whether a pane that just went idle should join the focus queue, given the active
 * target. A role-less pane (a plain console — `role` undefined/empty) always queues
 * except under "none", so single-console behavior is unchanged for every target but
 * "none". A fleet pane queues only when its role matches the target.
 *
 * @param role the pane's session role (`paneRoles[pid]`), or undefined for a plain console.
 * @param target the active focus target.
 */
export function shouldFocus(role: string | undefined, target: FocusTarget): boolean {
  if (target === "none") return false;
  if (!role) return true;                       // plain console — always queue (except "none")
  switch (target) {
    case "everything": return true;
    case "director":   return role === "director";
    case "workers":    return role === "worker";
    case "fleet":      return role === "director" || role === "worker";
  }
}

// ── Configurable auto-focus modes (#434) ──────────────────────────────────────
//
// Controls WHEN focus auto-advances after you send a message to the active pane.
// Replaces the old `autoAdvanceOnReply` boolean (still exported for back-compat).

export type ConsoleAutoFocusMode =
  | "cycle-on-reply" // advance to the next queued pane each time you reply (was `true`)
  | "off";           // no automatic advance; use Ctrl+Shift+N manually (was `false`)

/** The presets, in display order — for a picker control. */
export const AUTO_FOCUS_MODES: ConsoleAutoFocusMode[] = ["cycle-on-reply", "off"];

/** Default auto-focus mode: cycle on reply (the original behavior). */
export const DEFAULT_AUTO_FOCUS_MODE: ConsoleAutoFocusMode = "cycle-on-reply";

/** Human label for an auto-focus mode. */
export function autoFocusModeLabel(m: ConsoleAutoFocusMode): string {
  switch (m) {
    case "cycle-on-reply": return "Cycle on reply";
    case "off":            return "Off (manual)";
  }
}

const samePane = (a: QueuedPane, b: QueuedPane) => a.tab === b.tab && a.pane === b.pane;

/**
 * Append a pane to the waiting queue, de-duplicated and order-preserving. Returns
 * the same array reference when nothing changes (so the store can skip a needless
 * update).
 *
 * @param queue current waiting queue.
 * @param entry pane that just went idle.
 */
export function enqueue(queue: QueuedPane[], entry: QueuedPane): QueuedPane[] {
  if (entry.pane < 0 || queue.some((q) => samePane(q, entry))) return queue;
  return [...queue, entry];
}

/** Remove a pane (attended, or back to "run"); same reference if not present. */
export function removeFromQueue(queue: QueuedPane[], entry: QueuedPane): QueuedPane[] {
  return queue.some((q) => samePane(q, entry)) ? queue.filter((q) => !samePane(q, entry)) : queue;
}

/**
 * The next pane to move to when cycling the queue, relative to the pane you're on.
 * Round-robins through the waiting panes — the current one is NOT removed (a pane
 * leaves only when you respond to it), so cycling can land back on it later.
 *
 * @param queue waiting panes.
 * @param current the pane you're on (focused, or maximized).
 * @returns the next waiting pane (possibly on another tab), or null when there's
 *   nowhere else to go (empty queue, or the only queued pane is the current one).
 */
export function nextInCycle(queue: QueuedPane[], current: QueuedPane): QueuedPane | null {
  if (queue.length === 0) return null;
  const idx = queue.findIndex((q) => samePane(q, current));
  if (idx === -1) return queue[0];                 // current isn't waiting → first waiting pane
  const next = queue[(idx + 1) % queue.length];
  return samePane(next, current) ? null : next;     // only the current pane is queued → nowhere to go
}

/**
 * Prune the queue to the panes still waiting, across every tab whose live status
 * we have. After #187 every tab's panes stay mounted, so the caller can supply a
 * per-tab waiting set for every tab — a queued entry stays iff its pane appears
 * in its tab's set. Tabs absent from the map (no live data — e.g. an empty
 * workspace mid-transition) leave their entries alone, since we don't want a
 * temporarily-missing tab to silently drop queued panes.
 *
 * @param queue current waiting queue.
 * @param waitingByTab live waiting indices per tab (idle panes that should stay queued).
 * @returns the pruned queue, or the same reference when nothing changed.
 */
export function reconcileQueue(
  queue: QueuedPane[],
  waitingByTab: ReadonlyMap<number, ReadonlySet<number>>,
): QueuedPane[] {
  const pruned = queue.filter((q) => {
    const waiting = waitingByTab.get(q.tab);
    return waiting === undefined || waiting.has(q.pane);
  });
  return pruned.length === queue.length ? queue : pruned;
}

runtime.app/console/lib/idleReaper.ts:
// Idle session reaping (#849) — decide which background console PTYs to reap to bound
// memory when many projects accumulate hidden `claude` processes. PURE decision: given a
// snapshot of live panes + the reaper config + the clock, return the pane ids to reap. The
// hook (useIdleReaper) does the side effects (pty_kill + mark dormant); the store renders a
// dormant placeholder and resumes on focus. Framework-free + unit-tested.
//
// Reaping is non-destructive: a worktree/cwd persists on disk and the pane resumes via the
// existing relaunch path, so a reaped session is recoverable, not lost.

import type { SessionRole } from "@/shared/lib/session/sessionRoles";

/** A live pane the reaper evaluates. */
export interface ReaperPane {
  paneId: string;
  /** Live PTY status: "run" = mid-turn (never reaped), "idle"/"on" = at rest. */
  status: "run" | "on" | "idle";
  role: SessionRole;
  /** Epoch ms of this pane's last activity (last status change / output). */
  lastActivityMs: number;
  /** The pane the user is currently watching — never reaped. */
  focused: boolean;
  /** Already dormant (reaped) — skip; nothing to reap twice. */
  dormant: boolean;
  /** DECLARED maintenance (#4025): this worker emitted `bsc-maintain` — everything it owns is done
   *  and it is standing by for the director to dispatch into. Distinct from ordinary idling, which is
   *  why it gets its own rule below rather than a shorter `workerIdleMs`. */
  maintaining?: boolean;
}

export interface ReaperConfig {
  /** Master switch. */
  enabled: boolean;
  /** Idle threshold (ms) for reapable project/planner sessions. */
  idleMs: number;
  /** Idle threshold (ms) for workers + the director — conservative. `null` ⇒ never reap
   *  them (the default), since they idle legitimately (parked on a dep / the director). */
  workerIdleMs: number | null;
  /** Idle threshold (ms) for the app-owned STUDIO sessions (designer/librarian/architect, #3357).
   *  A studio session deliberately outlives the page that opened it — it stays warm on TerminalHost
   *  so its Glance node can morph into it — so this is how long it may sit with NO surface showing
   *  it before being reclaimed. Separate from `idleMs` because the trigger is different: the studio
   *  reaper counts *unwatched* time (viewer count 0), not time since last output.
   *  OPTIONAL for back-compat: a config persisted before #3357 has no such key, and zustand's
   *  persist replaces the whole object rather than merging, so readers MUST fall back to
   *  {@link DEFAULT_STUDIO_IDLE_MS} rather than trusting it to be present. */
  studioIdleMs?: number;
}

/** Default idle grace before an unwatched studio session is reclaimed (#3357). Also the fallback
 *  for a `ReaperConfig` persisted before the key existed. */
export const DEFAULT_STUDIO_IDLE_MS = 30 * 60 * 1000;

/** The effective studio idle threshold for a config, tolerating a pre-#3357 persisted object. */
export function studioIdleMs(cfg: ReaperConfig): number {
  return cfg.studioIdleMs ?? DEFAULT_STUDIO_IDLE_MS;
}

/** Roles handled conservatively: they idle legitimately mid-fleet, so they're reaped only
 *  under the separate (longer / opt-in) `workerIdleMs`, never the project threshold. */
const CONSERVATIVE_ROLES: ReadonlySet<SessionRole> = new Set<SessionRole>(["worker", "director"]);

/** The idle threshold that applies to a pane by role, or `null` when its role is never
 *  reaped under the current config. */
export function thresholdFor(role: SessionRole, cfg: ReaperConfig): number | null {
  return CONSERVATIVE_ROLES.has(role) ? cfg.workerIdleMs : cfg.idleMs;
}

/** Whether a single pane is reapable right now. Exposed for focused unit tests. */
export function isReapable(pane: ReaperPane, cfg: ReaperConfig, nowMs: number): boolean {
  if (!cfg.enabled) return false;
  if (pane.dormant) return false;       // already reaped
  if (pane.focused) return false;       // the user is watching it
  if (pane.status === "run") return false; // mid-turn — never interrupt active work
  // DECLARED MAINTENANCE (#4025) — reaped IMMEDIATELY, with no threshold.
  //
  // `workerIdleMs` is null by default because a worker "idles legitimately (parked on a dep / the
  // director)" — you cannot tell that apart from a worker that is done, so the safe answer was to reap
  // neither. Maintenance removes the ambiguity: the worker has SAID everything it owns is complete and
  // it is standing by. That is the one idle state where the PTY holds nothing worth keeping — measured
  // at ~413 MB per parked `claude.exe`, 13.7 GB across 34 of them.
  //
  // Deliberately NOT expressed as a shorter `workerIdleMs`: that would also reap a worker parked on a
  // real question, which is exactly the case the null default protects. And no grace period — a
  // dispatch relaunches with the assignment baked in (`actuateWake`), so a reaped maintainer is
  // reachable, which is what makes immediate reaping free rather than a trade.
  if (pane.maintaining) return true;
  const threshold = thresholdFor(pane.role, cfg);
  if (threshold === null) return false; // this role is never reaped under the config
  return nowMs - pane.lastActivityMs >= threshold;
}

/**
 * The pane ids to reap from a snapshot. Selects only idle, non-focused, non-dormant panes
 * whose idle time exceeds the threshold for their role. A `run` (mid-turn) pane, the focused
 * pane, and — by default — workers/director are never selected.
 */
export function panesToReap(panes: readonly ReaperPane[], cfg: ReaperConfig, nowMs: number): string[] {
  return panes.filter((p) => isReapable(p, cfg, nowMs)).map((p) => p.paneId);
}

/** Sensible conservative defaults: on, 30 min for project sessions, workers/director never
 *  reaped (opt-in). Surfaced in Settings; persisted. */
export const DEFAULT_REAPER_CONFIG: ReaperConfig = {
  enabled: true,
  idleMs: 30 * 60 * 1000,
  workerIdleMs: null,
  studioIdleMs: DEFAULT_STUDIO_IDLE_MS,
};

runtime.app/console/lib/jumbleProbe.ts:
// Jumble detection for the Claude CLI's TUI (#1250). Pure so the verdict is unit-testable from
// plain row strings — no xterm in jsdom. The caller (TerminalView) samples the bottom input-box
// rows of a *Claude CLI* session at each settle, runs this, and nudges (requestPaneRedraw, #1221)
// when the chrome is shattered. ONLY for the Claude CLI — an API / bsc-agent session renders its
// own UI, not this box chrome, so the caller must gate on the provider before sampling.

export type JumbleVerdict = "healthy" | "malformed" | "unknown";

// Horizontal box-drawing runs (incl. heavy / double / dashed) make up the input box's top + bottom
// borders — the structure we check for integrity.
const HORIZ = "─━═┄┅┈┉╌╍";
// Any box-drawing character — tells us TUI chrome is present at all (vs. plain output).
const BOX = /[─━═┄┅┈┉╌╍╭╮╰╯┌┐└┘╔╗╚╝│┃║┆┇┊┋]/;

/** Longest contiguous run of horizontal box-drawing characters in a row. */
function longestHorizRun(row: string): number {
  let best = 0;
  let cur = 0;
  for (const ch of row) {
    if (HORIZ.includes(ch)) {
      cur += 1;
      if (cur > best) best = cur;
    } else {
      cur = 0;
    }
  }
  return best;
}

/**
 * Classify the sampled chrome rows of a Claude CLI TUI (the bottom input-box region) as a `healthy`
 * render, a `malformed` (jumbled) one, or `unknown` when there's no chrome to judge.
 *
 * Heuristic: the Claude input box draws a full-width horizontal border (top + bottom). A clean
 * render has at least one long, unbroken run of horizontal box characters; a jumbled redraw
 * overwrites/shifts those cells, shattering the run. So:
 *   - no box-drawing characters at all   → `unknown` (plain output; can't tell — don't nudge)
 *   - box chars present + a long border   → `healthy`
 *   - box chars present but no long border → `malformed`
 *
 * Conservative by design: it only flags `malformed` when chrome IS present but broken, never on
 * ordinary text. The caller applies hysteresis (re-check before firing) to ride out a lone
 * mid-draw frame.
 */
export function probeJumble(rows: string[], cols: number): JumbleVerdict {
  if (cols <= 0 || rows.length === 0) return "unknown";
  if (!rows.some((r) => BOX.test(r))) return "unknown";
  // A healthy border spans most of the width; require half the columns (min 8 for a narrow pane).
  const healthyRun = Math.max(8, Math.floor(cols * 0.5));
  const longest = rows.reduce((m, r) => Math.max(m, longestHorizRun(r)), 0);
  return longest >= healthyRun ? "healthy" : "malformed";
}

runtime.app/console/lib/models.ts:
// Shared LLM-model catalog (#…) — the single source of truth for the console's selectable model
// tiers, so the console (PaneMenu / PaneShell), Settings, and the planner's Permissions stage all
// reference one list instead of duplicating it. Each id maps to a Claude CLI tier alias at launch
// (`opus-4.5` → `claude --model opus`), so a tier tracks the latest model in that family.
import modelsEmbedded from "@data/console/models.json";
import modelDefaultsEmbedded from "@data/console/model-defaults.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

/** A selectable model tier. The trailing version is cosmetic — the harness maps it to a CLI tier
 *  alias (`opus`/`sonnet`/`haiku`), which always resolves to the latest model in that tier. */
export type ModelId = "haiku-4.5" | "sonnet-4.5" | "opus-4.5";

export interface ModelOption {
  id: ModelId;
  /** One-word character of the tier (fast / balanced / deep). */
  tone: string;
  /** Relative-cost glyph. */
  price: string;
}

// The tier DATA is externalized to `@data/console/models.json` (#2146, epic #2027 tail) — editable
// without touching code + part of the exportable config bundle; the config-dir copy (#2047) overlays
// the embedded default via `overlayFile`. This module keeps the TYPES + accessor/derivation helpers.
/** The model tiers offered in the UI, cheapest → most capable. */
export const MODELS: ModelOption[] = overlayFile("console/models.json", modelsEmbedded as ModelOption[]);

export const MODEL_IDS: ModelId[] = MODELS.map((m) => m.id);

/** The default per-pane tier (the store's `defaultModel` seed + PaneShell's fallback), sourced from
 *  `@data/console/model-defaults.json` (#2416) — ONE default instead of scattered `"sonnet-4.5"`
 *  literals. Falls back to the catalog's middle tier if a config-dir edit names an unknown tier. */
export const DEFAULT_MODEL_ID: ModelId =
  MODEL_IDS.find((id) => id === overlayFile("console/model-defaults.json", modelDefaultsEmbedded).defaultTier) ??
  MODEL_IDS[Math.floor(MODEL_IDS.length / 2)];

/** The bare tier name a ModelId maps to ("opus-4.5" → "opus") — also the CLI alias. */
export function modelTier(id: ModelId): string {
  return id.split("-")[0];
}

/** Resolve a tier name back to its ModelId ("opus" → "opus-4.5"); undefined for an unknown tier. */
export function tierToModelId(tier: string): ModelId | undefined {
  return MODELS.find((m) => modelTier(m.id) === tier)?.id;
}

runtime.app/console/lib/paneActivity.ts:
// Per-pane turn-activity gating for the console status dot (#1184).
//
// The status dot's only per-turn signal is a 1.5s silence timer (`QUIET_MS` in TerminalView),
// which can't tell "done" from "working but silent" — so a worker that's thinking, running a long
// silent tool call, or backing off false-idles mid-turn. The fix drives authoritative turn
// boundaries from Claude Code hooks: `bsc-activity run` on UserPromptSubmit (a turn opens) and
// `bsc-activity idle` on Stop/SubagentStop (the turn closes), recorded to `activity.log`.
// `bsc logs pane-activity` (over the `bsc` bridge, #2144) returns the latest state per pane;
// TerminalView polls it and uses the pure helpers here to decide whether a pane's turn is still open.
//
// ADDITIVE / SAFE: the gate only PREVENTS a wrongful idle — a pane whose turn is still open is kept
// "run" past the silence timeout. It never forces idle on its own; a pane still goes idle on the
// authoritative Stop (which records `idle`, closing the turn) or, for non-bash / never-launched
// panes that emit no activity at all, on the silence timer exactly as before (no regression).

/** One pane's latest turn-boundary state, as serialized by `bsc logs pane-activity`
 *  (`logs::PaneActivity` — plain snake_case, no serde rename, so the keys match the struct). */
export interface PaneActivity {
  pane: string;
  /** `"run"` — a turn is open (the agent is working); `"idle"` — the turn closed at a Stop;
   *  `"attn"` (#4005) — Claude Code fired `Notification`, i.e. it is STOPPED waiting on the user
   *  (a permission prompt, or a long input idle). */
  state: "run" | "idle" | "attn";
  /** Epoch-ms timestamp of the event. */
  at: number;
}

/**
 * Whether this pane's turn is still OPEN — i.e. the silence timer must NOT idle it.
 *
 * True only when the latest recorded activity is a `run` (UserPromptSubmit with no following Stop).
 * `undefined` (no activity recorded — a non-bash session, or a pane that hasn't taken a turn yet)
 * is NOT a turn-open signal, so the silence timer stays authoritative and behavior is unchanged.
 */
export function isTurnOpen(activity: PaneActivity | undefined): boolean {
  return activity?.state === "run";
}

/**
 * Is this pane STOPPED waiting on the user (#4005)?
 *
 * Distinct from idle in the way that matters: an idle pane is finished, an `attn` pane is blocked and
 * will stay blocked until a person acts. That is the most actionable state in the cockpit and, before
 * this, the least visible one — a pane awaiting a permission prompt looked exactly like a quiet one.
 *
 * Deliberately NOT turn-open ({@link isTurnOpen} stays false): the agent is not working, so the
 * silence timer should be free to settle the status dot as it always has. This adds a signal; it does
 * not re-gate the existing one.
 */
export function needsAttention(activity: PaneActivity | undefined): boolean {
  return activity?.state === "attn";
}

/**
 * Pick this pane's latest activity record out of the flat per-pane list `bsc logs pane-activity`
 * returns. A small helper so the predicate above and the poller in TerminalView agree on the lookup
 * (and so the gating logic is unit-testable end-to-end without a running poll).
 */
export function paneActivityFor(rows: PaneActivity[] | undefined, paneId: string): PaneActivity | undefined {
  return rows?.find((r) => r.pane === paneId);
}

/** Grace window after an `idle` event during which the turn is still treated as open (#1184). A
 *  fleet WORKER runs under the `bsc-defer` Stop hook: each turn records `idle`, bsc-defer blocks the
 *  stop, and the next turn's UserPromptSubmit reopens `run` a moment later. Without a debounce that
 *  momentary idle un-gates the silence timer and blinks the dot idle→run; the grace covers the gap. */
export const ACTIVITY_IDLE_GRACE_MS = 2500;

/**
 * Debounced turn-open check for the poller. Like {@link isTurnOpen}, but a freshly-`idle` pane is
 * still treated as open for `graceMs` after the idle event — smoothing the worker flicker above.
 * A genuinely done pane (its `idle` older than the grace) releases the gate, so the silence timer
 * idles it as normal. `run` is always open; no activity is never open (non-bash fallback unchanged).
 */
export function isTurnOpenDebounced(
  activity: PaneActivity | undefined,
  now: number,
  graceMs: number = ACTIVITY_IDLE_GRACE_MS,
): boolean {
  if (!activity) return false;
  if (activity.state === "run") return true;
  return now - activity.at < graceMs;
}

