import { Terminal, FolderOpen, GitBranch, GitCompareArrows, History, ShieldCheck, Activity } from "lucide-react";
import type { LucideIcon } from "lucide-react";

// The canonical console-pane VIEW registry: the set of views a pane can show, their icon/label/
// hotkey, and their order. The view switcher itself lives in the PaneMenu dropdown (#1149/#1319) and
// the PaneShell trigger glyph; both read VIEW_DEFS, and useHotkeys maps Alt+digits through VIEW_ORDER.
// (Extracted out of the former ViewTabs tab-strip component — removed once switching moved into the
// menu; the icon-registry migration of these glyphs is tracked separately as the console+icons theme.)
export type ViewKey = "console" | "files" | "branches" | "changes" | "log" | "tools" | "telemetry";

// `group` (#1149) splits the view-switcher dropdown into the working SCREENs (terminal, files,
// git views) and the INSPECT panels (tools & permissions, …) — mirroring the Console-Shell design.
export const VIEW_DEFS: Record<ViewKey, { Icon: LucideIcon; label: string; hint: string; hotkey: string; group: "screen" | "inspect" }> = {
  console:  { Icon: Terminal,   label: "Console",  hint: "claude session",      hotkey: "Alt+1", group: "screen" },
  files:    { Icon: FolderOpen, label: "Files",    hint: "working tree",        hotkey: "Alt+2", group: "screen" },
  branches: { Icon: GitBranch,  label: "Branches", hint: "local + remote refs", hotkey: "Alt+3", group: "screen" },
  changes:  { Icon: GitCompareArrows, label: "Changes", hint: "diff vs HEAD",   hotkey: "Alt+4", group: "screen" },
  log:      { Icon: History,    label: "Log",      hint: "recent commits",      hotkey: "Alt+5", group: "screen" },
  tools:    { Icon: ShieldCheck, label: "Tools & permissions", hint: "mcp + role posture", hotkey: "Alt+6", group: "inspect" },
  telemetry:{ Icon: Activity,   label: "Telemetry · cost", hint: "tokens + spend", hotkey: "Alt+7", group: "inspect" },
};

/** Views in their canonical (hotkey) order — index i ⇒ Alt+(i+1) / Alt+Shift+(i+1). The single
 *  source the view hotkeys (useHotkeys) map digits through, so the keys never drift from VIEW_DEFS. */
export const VIEW_ORDER: ViewKey[] = ["console", "files", "branches", "changes", "log", "tools", "telemetry"];

// Presentational readiness/perms banners rendered above the xterm terminal host
// (extracted from TerminalView, #1645). Pure props in — NO xterm/PTY refs, no
// effects. TerminalView owns the readiness verdict + warnDismissed state and the
// terminal wiring; this only renders the resulting banners.

import { useAppStore } from "@/store";
import { IconButton } from "@/shared/ui/controls/IconButton";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import { SessionReadinessBanner } from "@/app/SessionReadinessBanner";
import { SessionFailure } from "@/app/SessionFailure";
import type { ReadinessCheck } from "@/shared/lib/core/diagnostics";

interface TerminalBannersProps {
  paneId: string;
  /** Verdict-derived critical failures (block the terminal). */
  criticalChecks: ReadinessCheck[];
  /** Verdict-derived non-blocking warnings. */
  warningChecks: ReadinessCheck[];
  /** Re-run the readiness preflight probe. */
  onRetry: () => void;
  /** True once the user has dismissed the warning banner this session. */
  warnDismissed: boolean;
  /** Dismiss the warning banner. */
  onDismissWarn: () => void;
  /** #799 — the pane's assigned profile was edited while running; nudge to relaunch. */
  permsStale: boolean;
}

/**
 * The stacked pane banners: a blocking {@link SessionFailure} for critical
 * prerequisite gaps, else a dismissible {@link SessionReadinessBanner} for
 * warnings, plus the #799 "permissions changed — relaunch" nudge.
 */
export function TerminalBanners({
  paneId,
  criticalChecks,
  warningChecks,
  onRetry,
  warnDismissed,
  onDismissWarn,
  permsStale,
}: TerminalBannersProps) {
  return (
    <>
      {criticalChecks.length > 0 && (
        <SessionFailure critical={criticalChecks} onRetry={onRetry} />
      )}
      {criticalChecks.length === 0 && !warnDismissed && warningChecks.length > 0 && (
        <SessionReadinessBanner
          warnings={warningChecks}
          onDismiss={onDismissWarn}
          onSignInGitHub={
            warningChecks.some((c) => c.id === "gh-auth")
              ? () => useAppStore.getState().navigate({ workspace: "settings", page: "github" }) // #3598/#3602: land on the GitHub settings section, not the last-viewed one
              : undefined
          }
        />
      )}
      {permsStale && (
        <Row className="mono" gap={8} style={{
          padding: "6px 12px",
          fontSize: 11, color: "var(--accent)",
          background: "color-mix(in oklch, var(--accent), transparent 90%)",
          borderBottom: "1px solid color-mix(in oklch, var(--accent), transparent 70%)",
        }}>
          <Text as="span">⟳</Text>
          <Text tone="muted" style={{ flex: 1 }}>
            Permissions changed on the Security page — <b style={{ color: "var(--fg)" }}>relaunch this console</b> to apply.
          </Text>
          <IconButton aria-label="Dismiss" size="sm" onClick={() => useAppStore.getState().clearPanePermsStale(paneId)} />
        </Row>
      )}
    </>
  );
}

