// TerminalHost (#2378, epic #2372) — the app-level owner of every agent terminal. It renders exactly
// ONE <TerminalView> per paneId (hence one xterm instance + one `pty_data_<paneId>` listener), portaled
// into a stable per-pane container <div>. Surfaces don't mount their own terminal — they drop a
// <TerminalSlot paneId> placeholder, and the host RE-PARENTS the pane's container into whichever slot
// currently owns it (the console grid cell OR the Glance dock), parking it in a hidden holding node when
// no surface shows it. Because a re-parent is a plain appendChild MOVE (not a React remount), the xterm
// canvas + scrollback + PTY listener survive the hand-off untouched — so the PTY is never torn down when
// the terminal moves between surfaces.
//
// This replaces the pre-#2378 double-mount: the console cell and the Glance dock each mounted their own
// <TerminalView> for the same paneId and coordinated by hand ("only one is `visible` at a time") to keep
// two xterms from fighting over PTY sizing. One host = one terminal = no coordination hack, no doubled
// renderer memory, no doubled reconnect side-effects, and no double-counted live-agent tally.
import {
  createContext, useCallback, useContext, useEffect, useMemo, useRef, useState, type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import { TerminalView } from "@/app/console/panes/views/TerminalView";
import { isStudioSessionPaneId } from "@/shared/lib/session/systemSessions";

/** The terminal props a slot supplies to the shared <TerminalView>. The console cell is the `primary`
 *  (it owns the launch/data props); the Glance dock is a viewer that supplies only visibility/focus. */
export interface SlotTerminalProps {
  visible: boolean;
  focused?: boolean;
  initialCwd?: string;
  initCmd?: string;
  onCwdChange?: (path: string) => void;
  onStatusChange?: (status: "run" | "idle") => void;
  onFocus?: () => void;
  /** True for the console grid cell — the surface that launches the session and consumes its cwd/status.
   *  The host sources launch/data props from the primary claim so a Glance-owned terminal still reports
   *  cwd/status back to the console; visibility/focus always follow the current owner. */
  primary?: boolean;
  /** True for an off-screen HOLDING claim that exists only to keep the PTY alive (the app-owned session
   *  mounts, #3326/#3357) — it must never take ownership away from a real surface. Ownership is normally
   *  "last claim wins", but a holding claim can register at an arbitrary time (its cwd resolves async), so
   *  without this it could land AFTER a visible dock and park the terminal off-screen. A parked claim owns
   *  the terminal only when it is the ONLY kind of claim left. */
  parked?: boolean;
}

/** The claim that visually HOSTS the terminal: the last non-parked claim, else the last claim (every
 *  remaining claim is a parked holding mount). Pure — exported for the unit test. */
export function ownerClaim<T extends { propsRef: { readonly current: SlotTerminalProps } }>(claims: readonly T[]): T | undefined {
  for (let i = claims.length - 1; i >= 0; i--) if (!claims[i].propsRef.current.parked) return claims[i];
  return claims[claims.length - 1];
}

/** A registered claim on a paneId's terminal. Claims are ordered by registration; the last non-`parked`
 *  claim is the current owner (see {@link ownerClaim}) — the surface that visually hosts + drives the
 *  terminal. `propsRef` is read live at portal-render
 *  time so callback-identity churn never forces a host re-render (only visible/focus changes do, via touch). */
interface Claim {
  slotId: string;
  el: HTMLElement;
  propsRef: { readonly current: SlotTerminalProps };
}

interface HostApi {
  /** Register (or re-register, StrictMode-safe) a slot's claim on a paneId. */
  register(paneId: string, slotId: string, el: HTMLElement, propsRef: { readonly current: SlotTerminalProps }): void;
  /** Drop a slot's claim; ownership falls back to the previous claimant, or the terminal parks/tears down. */
  deregister(paneId: string, slotId: string): void;
  /** Nudge the host to re-read live props (call when a claim's visible/focus changes). */
  touch(): void;
}

const TerminalHostCtx = createContext<HostApi | null>(null);

/** The host API for a <TerminalSlot>. Null when no <TerminalHost> is an ancestor — the slot then renders an
 *  inert placeholder (e.g. a component rendered in isolation in a unit test), never crashing. */
export function useTerminalHost(): HostApi | null {
  return useContext(TerminalHostCtx);
}

export function TerminalHost({ children }: { children: ReactNode }) {
  // paneId → ordered claims (last = owner). Held in a ref (the source of truth); a version counter drives
  // re-renders so we never store DOM els / live callbacks in React state.
  const registryRef = useRef<Map<string, Claim[]>>(new Map());
  // paneId → the stable container that hosts its single <TerminalView>. Created lazily during render so the
  // portal has a target immediately; the effect below parents it into the owner slot (or the holding node).
  const containersRef = useRef<Map<string, HTMLDivElement>>(new Map());
  const holdingRef = useRef<HTMLDivElement>(null);
  const [, bump] = useState(0);
  const rerender = useCallback(() => bump((n) => n + 1), []);

  // Stable API object (identity never changes — `rerender` is stable — so a slot's register effect doesn't
  // re-run on host re-renders). Mutates the registry ref inside the callbacks (which run in effects/events,
  // never during render) then bumps the version to re-render.
  const api = useMemo<HostApi>(() => ({
    register(paneId, slotId, el, propsRef) {
      const map = registryRef.current;
      // Replace any prior claim for this slot (StrictMode remount / element swap), else append as the new owner.
      const next = (map.get(paneId) ?? []).filter((c) => c.slotId !== slotId);
      next.push({ slotId, el, propsRef });
      map.set(paneId, next);
      rerender();
    },
    deregister(paneId, slotId) {
      const map = registryRef.current;
      const claims = map.get(paneId);
      if (!claims) return;
      const next = claims.filter((c) => c.slotId !== slotId);
      if (next.length) map.set(paneId, next);
      else map.delete(paneId);
      rerender();
    },
    touch: rerender,
  }), [rerender]);

  /** The stable container for a paneId, created on first render that needs it. Kept in a ref so the same
   *  node is reused across owner changes — that node (with its xterm inside) is what gets re-parented. */
  const containerFor = (paneId: string): HTMLDivElement => {
    let c = containersRef.current.get(paneId);
    if (!c) {
      c = document.createElement("div");
      c.style.flex = "1";
      c.style.minHeight = "0";
      c.style.display = "flex";
      c.style.flexDirection = "column";
      c.dataset.terminalContainer = paneId;
      containersRef.current.set(paneId, c);
    }
    return c;
  };

  // After every render: park a just-created container in the holding node, re-parent each pane's container
  // into its current owner slot, and drop containers whose pane no longer has any claim (its <TerminalView>
  // stopped rendering, so the xterm was disposed — remove the emptied node).
  useEffect(() => {
    const map = registryRef.current;
    const containers = containersRef.current;
    for (const [paneId, container] of containers) {
      const claims = map.get(paneId);
      const owner = claims && ownerClaim(claims);
      if (owner?.el) {
        if (container.parentElement !== owner.el) owner.el.appendChild(container);
      } else if (map.has(paneId)) {
        // Claimed but the owner has no element yet — hold it (shouldn't happen; defensive).
        if (container.parentElement !== holdingRef.current) holdingRef.current?.appendChild(container);
      } else {
        // No claims left: the portal below stopped rendering (TerminalView unmounted) → drop the node.
        container.remove();
        containers.delete(paneId);
      }
    }
  });

  const activePaneIds = Array.from(registryRef.current.keys());

  return (
    <TerminalHostCtx.Provider value={api}>
      {children}
      {/* Holding node — parked containers live here (display:none) so their TerminalView, and thus the PTY
          + scrollback, stay alive while no surface is showing them. */}
      {/* eslint-disable-next-line no-restricted-syntax -- imperative re-parent target for parked terminals */}
      <div ref={holdingRef} style={{ display: "none" }} aria-hidden />
      {activePaneIds.map((paneId) => {
        const claims = registryRef.current.get(paneId)!;
        const owner = ownerClaim(claims)!;
        // Launch/data props from the primary (console) claim; visibility/focus from the current owner.
        const primaryClaim = claims.find((c) => c.propsRef.current.primary);
        // #3427 — an APP-OWNED session must not launch before its dedicated mount claims it. Its page dock
        // (`DesignerTerminal` and friends) calls `openStudio` and renders its viewer <TerminalSlot> in the
        // SAME commit, while the mount that supplies the launch props only appears after an async
        // `setup_*_workspace` invoke resolves. The viewer therefore always registered first, and with no
        // primary to source from, `TerminalView` mounted with `initialCwd`/`initCmd` UNDEFINED — a one-shot
        // launch, so the primary arriving a tick later never repaired it. `pty_create` then ran with
        // `cwd=<none>`: the shell inherited the app's own working directory instead of the studio
        // workspace, loaded none of its spec CLAUDE.md, skipped `--continue` + the persona kickoff, and
        // (because `ensure_session_settings` is skipped for an empty cwd) ran PERMISSION-LESS with no role
        // gate at all. Waiting one tick for the mount costs nothing visible and makes the launch correct.
        //
        // Scoped to the fixed app-owned ids, each of which HAS such a mount (StudioSessionMount ×4 +
        // DebugSessionMount) that is guaranteed to arrive — a fleet pane's primary is its console grid
        // cell, which may legitimately never mount while Glance shows the terminal, so gating it would
        // hide a working session. And only BEFORE the first render: once a pane has a container its
        // TerminalView stays mounted whatever the claims do, so a mount unmounting later (a tear-off, the
        // idle reaper) can never tear a live PTY down through this path.
        if (!primaryClaim && isStudioSessionPaneId(paneId) && !containersRef.current.has(paneId)) return null;
        const primary = primaryClaim ?? owner;
        const op = owner.propsRef.current;
        const pp = primary.propsRef.current;
        return createPortal(
          <TerminalView
            paneId={paneId}
            visible={op.visible}
            focused={op.focused}
            initialCwd={pp.initialCwd}
            initCmd={pp.initCmd}
            onCwdChange={pp.onCwdChange}
            onStatusChange={pp.onStatusChange}
            onFocus={pp.onFocus}
          />,
          containerFor(paneId),
          paneId,
        );
      })}
    </TerminalHostCtx.Provider>
  );
}

runtime.app/console/terminal/TerminalSlot.tsx:
// TerminalSlot (#2378) — the placeholder a surface drops where an agent terminal should appear. It never
// mounts a <TerminalView> itself; it registers a claim with the app-level <TerminalHost>, which re-parents
// the pane's single terminal container into this slot's element. On unmount the host hands the terminal
// back to the previous claimant (or parks it), so moving between the console cell and the Glance dock never
// tears down the xterm/PTY. With no <TerminalHost> ancestor (a component rendered in isolation) the slot is
// an inert empty box — safe to render anywhere.
import { useEffect, useId, useRef } from "react";
import { useTerminalHost, type SlotTerminalProps } from "./TerminalHost";

export type TerminalSlotProps = { paneId: string } & SlotTerminalProps;

export function TerminalSlot({ paneId, ...props }: TerminalSlotProps) {
  const host = useTerminalHost();
  const elRef = useRef<HTMLDivElement>(null);
  const slotId = useId();
  // Latest props, read live by the host at portal-render time. Callback identity may churn each render, but
  // only mount-time cwd/initCmd and the reactive visible/focus (handled below) actually matter downstream.
  const propsRef = useRef<SlotTerminalProps>(props);
  propsRef.current = props;

  // Claim this paneId's terminal for as long as the slot is mounted. Re-registers if the paneId changes.
  useEffect(() => {
    const el = elRef.current;
    if (!host || !el) return;
    host.register(paneId, slotId, el, propsRef);
    return () => host.deregister(paneId, slotId);
  }, [host, paneId, slotId]);

  // The host reads props live, but must re-render to propagate a visibility/focus change to the shared
  // <TerminalView> (and to re-run the re-parent pass). Nudge it exactly on those two.
  useEffect(() => {
    host?.touch();
  }, [host, props.visible, props.focused]);

  return (
    // eslint-disable-next-line no-restricted-syntax -- imperative re-parent target: the host appendChilds the terminal container here
    <div ref={elRef} style={{ flex: 1, minHeight: 0, display: "flex", flexDirection: "column" }} />
  );
}

runtime.app/console/useTerminalSession.ts:
// Session-readiness state for a terminal pane (#1645). Owns the preflight verdict (#564) that
// TerminalView renders as the SessionFailure / SessionReadinessBanner, the critical/warning splits it
// derives, and the manual retry. The mount-effect launch path sets the verdict via `setReadinessVerdict`
// after its own preflight probe (which runs with the resolved GH token); this hook owns the same probe
// for the user-triggered retry. Kept here (not in lib/) because it carries React state.

import { useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { log } from "@/shared/lib/core/log";
import { interpretDiagnostics, sessionVerdictFromReport, type PrereqStatus, type SessionVerdict } from "@/shared/lib/core/diagnostics";
import { tokenForRepo } from "@/shared/lib/github/repoCredentials";
import { useAppStore } from "@/store";

export function useTerminalSession(paneId: string, initialCwd?: string) {
  // Session readiness verdict (#564). Set after the preflight probe runs in the mount effect (after
  // the GH token is resolved so gh-auth uses the right env), or by `retryReadiness` below.
  const [readinessVerdict, setReadinessVerdict] = useState<SessionVerdict | null>(null);

  // Derive critical + warning lists from the verdict for rendering.
  const criticalChecks = readinessVerdict?.failed.filter((c) => c.severity === "critical") ?? [];
  const warningChecks  = readinessVerdict?.failed.filter((c) => c.severity === "warning")  ?? [];

  function retryReadiness() {
    const cwd = initialCwd ?? "";
    // #3984: say so rather than returning silently. A no-op retry is indistinguishable from one that
    // ran and got the same verdict — which is exactly how the button read while the probe was failing
    // to spawn (#3984): it fired 15 times a boot and looked dead every time.
    if (!cwd) {
      log.warn(`console[${paneId}] readiness retry skipped — this pane has no cwd, so there is nothing to probe`);
      return;
    }
    const ghToken = tokenForRepo(
      useAppStore.getState().paneRepos[paneId],
      useAppStore.getState().repoGithubTokens,
      useAppStore.getState().githubToken,
    );
    const env = ghToken ? { GH_TOKEN: ghToken } : null;
    invoke<PrereqStatus[]>("preflight", { cwd, env })
      .then((prereqs) => setReadinessVerdict(sessionVerdictFromReport(interpretDiagnostics(prereqs))))
      .catch((e) => log.error(`console[${paneId}] preflight retry failed: ${e}`));
  }

  return { setReadinessVerdict, criticalChecks, warningChecks, retryReadiness };
}

runtime.app/KeptMountedPage.tsx:
import { useRef, Suspense, type ReactNode, type CSSProperties } from "react";
import { Box } from "@/shared/ui/layout/Box";

/**
 * Lazy-mount + kept-mounted (CSS-hidden) page idiom, extracted from the 4+ hand-rolled copies
 * across the shell (App.tsx Projects, planner index Design/Planning). A page mounts on its first
 * activation, then STAYS mounted (toggled with `display`) so its local state and live PTY survive
 * a screen/mode switch instead of being torn down.
 *
 * `gate` is the single-owner guard for tear-off pages: latch AND render are both conditioned on it,
 * so when the gate drops (e.g. the page is torn into its own window) the helper returns `null` and
 * fully unmounts — releasing the single PTY for the detached owner. Defaults to `true` (no gate).
 *
 * @param active whether this page is the currently-shown one (drives `display: flex | none`).
 * @param gate   single-owner guard; while false the page never latches and unmounts if already shown.
 * @param keepAlive mount the page (hidden) even if it was never actively shown — and, crucially, UNMOUNT
 *   it again when this drops (unless it was later shown normally). This is the on-demand reachability
 *   hook (#2940): the studio-network pump keeps a target studio session alive only while a commission is
 *   open, reusing this ONE single-owner mount (never a second PTY owner), and lets it tear down after.
 * @param fallback if provided, children are wrapped in `<Suspense>` (for a lazily-imported page).
 * @param style  merged over the flex-column box defaults (e.g. `{ flexDirection: "row" }`).
 */
export function KeptMountedPage({
  active,
  gate = true,
  keepAlive = false,
  fallback,
  style,
  children,
}: {
  active: boolean;
  gate?: boolean;
  keepAlive?: boolean;
  fallback?: ReactNode;
  style?: CSSProperties;
  children: ReactNode;
}) {
  // `everShown` latches ONLY on a real activation — so a page the user actually opened stays mounted
  // for the session (its live PTY survives a mode switch). `keepAlive` mounts without latching, so a
  // session brought up purely to fulfil a commission unmounts (releasing its PTY) when it clears.
  const everShown = useRef(false);
  if (active && gate) everShown.current = true;
  // The single-owner gate dropped, or the page is neither latched-open nor kept-alive → render nothing
  // (and release the PTY).
  if (!gate || !(everShown.current || keepAlive)) return null;

  const body = fallback !== undefined ? <Suspense fallback={fallback}>{children}</Suspense> : children;
  return (
    // minWidth/minHeight:0 keep the flex SHRINK CHAIN intact — a kept-mounted page (e.g. the Design
    // Studio's GraphCanvas) can then shrink WITH the window instead of pinning to its content's intrinsic
    // width and overflowing (which the `.screen-body` clips → the right pane vanishes, #3097). Every flex
    // ancestor from the shrinking element up to the sized ancestor needs it; don't drop these.
    <Box style={{ display: active ? "flex" : "none", flex: 1, flexDirection: "column", minHeight: 0, minWidth: 0, ...style }}>
      {body}
    </Box>
  );
}

runtime.app/navigate.ts:
// navigate (#3602) — ONE place that turns "go here" into the right store mutations, so navigation can
// never forget the page.
//
// WHY THIS EXISTS
// A Workspace switch (`setWorkspace`) and the PAGE within it (which tab/section) are set through
// DIFFERENT mechanisms per workspace — tabbed screens persist an uncontrolled `activePageTab[key]`,
// the rest each own a dedicated field (`projectsPageMode`, `githubTab`, `automationsTab`,
// `settingsSection`). So a caller that just did `setWorkspace("glance")` lands on whatever tab was last
// open, not the one it meant — #3598 was FOUR separate one-off fixes for exactly this (triage-complete
// landing on Glance but not the Network tab / not the project, GitHub-connect banner landing on the
// last settings section, …). `navigate({ workspace, page, drill })` makes "specify the page" STRUCTURAL:
// you name the page in the same call that switches the workspace, and this module knows which knob each
// workspace turns.
import type { AppStore } from "@/store/types";
import type { Workspace } from "@/app/registry";

/** A navigation target: WHERE (workspace) + WHICH page within it + an optional entity to focus.
 *  `workspace` is required — the whole point is that you cannot switch screens without saying which
 *  page, so "land on glance" can never silently mean "…on whatever tab happened to be open". */
export interface NavLoc {
  workspace: Workspace;
  /** The page/tab within the workspace. Omit only for a workspace with no pages (console — its tabs are
   *  index-switched, not a string page) or when the workspace's default page is genuinely what you want. */
  page?: string;
  /** An entity to focus on the landing screen (currently only Glance, which drills into a project). Pass
   *  `null` to clear a drill; omit to leave it untouched. */
  drill?: string | null;
}

/** How each workspace sets its current PAGE — the single source of truth for a workspace's page knob.
 *  Tabbed screens (glance/skills/mcp/security) persist an uncontrolled `activePageTab[key]`; the rest own
 *  a dedicated field. `console` is intentionally absent: its "pages" are indexed tabs switched by
 *  `setActiveTab(idx)`, not a string page — a `navigate` to console carries no `page`. */
const WORKSPACE_PAGE: Partial<Record<Workspace, (s: AppStore, page: string) => void>> = {
  glance: (s, page) => s.setActivePageTab("glance", page),
  skills: (s, page) => s.setActivePageTab("skills", page),
  mcp: (s, page) => s.setActivePageTab("mcp", page),
  security: (s, page) => s.setActivePageTab("security", page),
  projects: (s, page) => s.setProjectsPageMode(page as AppStore["projectsPageMode"]),
  github: (s, page) => s.setGithubTab(page),
  automation: (s, page) => s.setAutomationsTab(page as AppStore["automationsTab"]),
  settings: (s, page) => s.setSettingsSection(page),
};

/** How each workspace focuses an ENTITY. Only Glance drills today; the map keeps the door open. */
const WORKSPACE_DRILL: Partial<Record<Workspace, (s: AppStore, id: string | null) => void>> = {
  glance: (s, id) => s.setGlanceDrill(id),
};

/** Set the page for `workspace` through its own mechanism. Exported so the `bsc navigate` bridge routes
 *  through the SAME map instead of hard-coding one workspace's setter. A workspace with no page
 *  mechanism (console) is a no-op. */
export function dispatchPage(s: AppStore, workspace: Workspace, page: string): void {
  WORKSPACE_PAGE[workspace]?.(s, page);
}

/**
 * Apply a navigation: focus the entity, set the page, THEN switch the workspace — in that order, so the
 * target screen mounts already showing the right page/entity rather than flashing its last-viewed one.
 * Pure over the store (every mutation is a store setter), so it is unit-testable with a fake store.
 */
export function applyNavigation(s: AppStore, loc: NavLoc): void {
  if (loc.drill !== undefined) WORKSPACE_DRILL[loc.workspace]?.(s, loc.drill);
  if (loc.page !== undefined) dispatchPage(s, loc.workspace, loc.page);
  s.setWorkspace(loc.workspace);
}

runtime.app/registry.ts:
// Canonical Workspace registry — the SINGLE source of truth for each top-level Workspace's key,
// display name, and rail icon (a Workspace = a rail destination; see docs/frontend-structure.md).
// The left-nav rail AND the titlebar position crumb both read from here, so a Workspace is named in
// exactly ONE place and the two can never drift: add a Workspace here and it's labeled everywhere
// (rail tooltip + the "you are here" titlebar). Previously the rail's NAV array and App's titlebar
// switch each hardcoded the names independently. (#nav-pass; Screen → Workspace rename #1879)

import { TerminalSquare, Zap, Server, FolderKanban, ShieldCheck, Sparkles, Settings, Network } from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { Github } from "@/shared/ui/icons";

/** Every top-level Workspace key (a rail destination). The store's `activeWorkspace` is one of these. */
// "design" (Design Studio) and "algorithms" (the knowledge graph) were removed as rail Workspaces —
// each is a single page, now a Planner tab (projectsPageMode "designs" / "algorithms"). A persisted
// `activeWorkspace: "design" | "algorithms"` is migrated to projects + the matching page mode.
export type Workspace = "console" | "glance" | "automation" | "mcp" | "github" | "projects" | "skills" | "security" | "settings";

export interface WorkspaceMeta {
  key: Workspace;
  /** The page's display name — the rail tooltip AND the titlebar position crumb. */
  label: string;
  Icon: LucideIcon;
}

/** Rail order is product-defined (#872) and locked by rail.test.tsx; the titlebar reads the
 *  same labels. Adding a screen is one entry here. */
export const WORKSPACES: WorkspaceMeta[] = [
  { key: "console",    label: "Console",     Icon: TerminalSquare },
  { key: "glance",     label: "Glance",      Icon: Network },
  { key: "projects",   label: "Planner",     Icon: FolderKanban },
  { key: "skills",     label: "Skills",      Icon: Sparkles },
  { key: "automation", label: "Automations", Icon: Zap },
  { key: "mcp",        label: "MCP",         Icon: Server },
  { key: "github",     label: "GitHub",      Icon: Github },
  { key: "security",     label: "Security",    Icon: ShieldCheck },
  { key: "settings",   label: "Settings",    Icon: Settings },
];

const BY_KEY = Object.fromEntries(WORKSPACES.map((s) => [s.key, s])) as Record<Workspace, WorkspaceMeta>;

/** The canonical display name for a Workspace — the rail tooltip and the titlebar position crumb.
 *  Falls back to the raw key for an unknown Workspace so an unmapped page is still visibly labeled
 *  (never blank). */
export function workspaceLabel(key: Workspace): string {
  return BY_KEY[key]?.label ?? key;
}

/** The Workspace to actually render for a raw store `activeWorkspace`. The legacy Console page is
 *  opt-in (#2372): when `showConsolePage` is off, a persisted (or just-toggled-off) console-active
 *  workspace falls back to Glance. This is the ONE definition of that redirect — the App shell uses it
 *  for the render + all chrome, and `useHotkeys` uses it to gate the console-pane hotkeys (which read
 *  the raw store value, so without this they'd keep firing while Glance is on screen, #3575). */
export function effectiveWorkspace(raw: Workspace, showConsolePage: boolean): Workspace {
  return !showConsolePage && raw === "console" ? "glance" : raw;
}

runtime.app/SessionFailure.tsx:
// Non-dismissible blocking panel for critical PTY readiness failures (#564).
//
// Shown in place of the terminal when Git Bash, the claude CLI, or git are
// missing from the session shell. The user must install the missing tool and
// retry — the session cannot proceed without these.

import type { ReadinessCheck } from "@/shared/lib/core/diagnostics";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";

interface SessionFailureProps {
  critical: ReadinessCheck[];
  onRetry: () => void;
}

export function SessionFailure({ critical, onRetry }: SessionFailureProps) {
  if (critical.length === 0) return null;

  return (
    <Stack
      role="alert"
      align="center"
      justify="center"
      gap={16}
      style={{
        flex: 1,
        padding: "32px 24px",
        background: "var(--bg-canvas)",
        color: "var(--fg)",
        fontFamily: '"JetBrains Mono", monospace',
        fontSize: 13,
        textAlign: "center",
      }}
    >
      <Text as="div" size={28} style={{ lineHeight: 1 }}>⚠</Text>
      <Text as="div" size={14} weight={600} style={{ color: "var(--danger)" }}>
        Session prerequisites missing
      </Text>
      <Stack
        gap={10}
        style={{
          maxWidth: 480,
          width: "100%",
        }}
      >
        {critical.map((c) => (
          <Stack
            key={c.id}
            gap={6}
            style={{
              background: "var(--bg-panel)",
              border: "1px solid color-mix(in oklch, var(--danger), transparent 75%)",
              borderRadius: 6,
              padding: "10px 14px",
              textAlign: "left",
            }}
          >
            <Text size={12} style={{ color: "var(--danger)" }}>{c.message}</Text>
            {c.installUrl && (
              <a
                href={c.installUrl}
                target="_blank"
                rel="noreferrer"
                style={{
                  color: "var(--info)",
                  fontSize: 11,
                  textDecoration: "none",
                  display: "inline-flex",
                  alignItems: "center",
                  gap: 4,
                }}
              >
                Download ↗
              </a>
            )}
          </Stack>
        ))}
      </Stack>
      {/* eslint-disable-next-line no-restricted-syntax -- bespoke failure-panel button with its own inline styling (not the .btn kit) */}
      <button
        onClick={onRetry}
        style={{
          marginTop: 4,
          padding: "7px 20px",
          borderRadius: 5,
          border: "1px solid var(--border)",
          background: "var(--bg-panel)",
          color: "var(--fg)",
          fontFamily: '"JetBrains Mono", monospace',
          fontSize: 12,
          cursor: "pointer",
        }}
      >
        Retry
      </button>
      <Text as="div" size={11} style={{ color: "var(--fg-dim)", maxWidth: 380 }}>
        Install the missing tools, then click Retry. The session will probe again
        without a full relaunch.
      </Text>
    </Stack>
  );
}

runtime.app/SessionReadinessBanner.tsx:
// Dismissible warn banner for non-critical PTY readiness warnings (#564).
//
// Renders below the pane chrome when `gh`/`gh auth` checks fail — the agent
// shell still works, but GitHub integration is degraded. Each warning gets its
// own install/action link. The user can dismiss the whole banner once they've
// acknowledged it.

import type { ReadinessCheck } from "@/shared/lib/core/diagnostics";
import { Banner } from "@/shared/ui/feedback/Banner";
import { Stack } from "@/shared/ui/layout/Stack";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

interface SessionReadinessBannerProps {
  warnings: ReadinessCheck[];
  onDismiss: () => void;
  /** Called when the user clicks "Sign in to GitHub" for a gh-auth warning. */
  onSignInGitHub?: () => void;
}

export function SessionReadinessBanner({
  warnings,
  onDismiss,
  onSignInGitHub,
}: SessionReadinessBannerProps) {
  if (warnings.length === 0) return null;

  return (
    <Banner
      variant="bar"
      tone="warn"
      loud
      role="alert"
      onDismiss={onDismiss}
      lead={<Text weight={600} style={{ whiteSpace: "nowrap" }}>⚠ GitHub</Text>}
    >
      <Stack gap={3} style={{ flex: 1 }}>
        {warnings.map((w) => (
          <Box as="span" key={w.id} style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
            <Text>{w.message}</Text>
            {w.id === "gh-auth" && onSignInGitHub && (
              // eslint-disable-next-line no-restricted-syntax -- bespoke inline "Sign in" link-button (currentColor border, banner-scoped styling)
              <button
                onClick={onSignInGitHub}
                style={{
                  background: "transparent", border: "1px solid currentColor", color: "currentColor",
                  cursor: "pointer", fontSize: 11, padding: "1px 6px", borderRadius: 3, lineHeight: 1.4,
                }}
              >
                Sign in →
              </button>
            )}
            {w.installUrl && w.id !== "gh-auth" && (
              <a href={w.installUrl} target="_blank" rel="noreferrer"
                style={{ color: "currentColor", fontSize: 11, textDecoration: "underline" }}>
                Install →
              </a>
            )}
          </Box>
        ))}
      </Stack>
    </Banner>
  );
}

// The right inspector of the Algorithms knowledge graph (#2761/#2958) — the focused implementation's
// identity, role, code, and what it builds on / is used by. A concept IS its implementation, so the
// inspector is impl-only (the abstract concept-node view was removed with #2961). Empty state prompts a
// selection; each builds-on / used-by row jumps to that impl.
//
// Visualization pane (#3177/#3199/#3205, epic #3171): when the focused impl has a registered
// visualization (`vizForImpl`), the animation is ALWAYS rendered inline as an auto-playing preview (no
// Code | Visualization toggle) above the code. Clicking it lifts to the workbench (`onExpandViz`), which
// promotes the animation to the full graph canvas (`VizStage`) — mirroring the Components-page try-on.
import { Box } from "@/shared/ui/layout/Box";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import { Eyebrow } from "@/shared/ui/typography/Eyebrow";
import { Chip } from "@/shared/ui/data/Chip";
import { TECH_META, implById, usedByImpl, type KnowledgeGraph, type AlgoImpl } from "./lib/knowledge";
import { VizPreview } from "./viz/VizPanel";
import { useVizForImpl } from "./viz/useVizForImpl";

const PANEL = { width: "100%", height: "100%", borderLeft: "1px solid var(--border)", overflowY: "auto", background: "var(--bg-panel)" } as const;

export function AlgorithmsInspector({ graph, focusedImpl, onSelectImpl, onExpandViz }: {
  graph: KnowledgeGraph;
  /** The focused implementation (#2863) — a node in the per-kit graph, or a free-standing primitive from
   *  the rail. Its code + builds-on / used-by. */
  focusedImpl?: AlgoImpl | null;
  /** Jump to another implementation (#2863) — the per-kit graph navigates impl→impl (builds-on / used-by). */
  onSelectImpl?: (id: string) => void;
  /** Expand the inline visualization to the full graph canvas (#3205) — lifted to the workbench, which
   *  renders `VizStage` in the GraphCanvas overlays slot. Omit ⇒ the inline preview is non-clickable. */
  onExpandViz?: () => void;
}) {
  if (!focusedImpl) {
    return (
      <Box style={PANEL}>
        <Stack gap={12} style={{ padding: 16 }}>
          <Eyebrow size={10}>Implementation</Eyebrow>
          <Text size={12} tone="muted">
            Select an implementation — from the rail or the graph — to see its code and what it builds on
            and is used by. The edge types are keyed in the graph legend.
          </Text>
        </Stack>
      </Box>
    );
  }

  // Key the body on the impl id so the inline preview resets on a fresh mount when the selection changes
  // — the previous impl's pane never leaks into the next one.
  return <ImplInspector key={focusedImpl.id} graph={graph} impl={focusedImpl} onSelectImpl={onSelectImpl} onExpandViz={onExpandViz} />;
}

/** The focused implementation's inspector body — its identity + inline visualization preview + code +
 *  builds-on/used-by. Split out so the preview resets per impl (via the `key`). */
function ImplInspector({ graph, impl, onSelectImpl, onExpandViz }: {
  graph: KnowledgeGraph;
  impl: AlgoImpl;
  onSelectImpl?: (id: string) => void;
  onExpandViz?: () => void;
}) {
  // A concept IS its implementation (#2958), so this is the whole inspector: the impl's code + the impls
  // it builds on (composes, down to the primitive base) and the ones that build on it (the reverse).
  const isPrim = impl.role === "primitive";
  const buildsOn = impl.composes.map((id) => implById(graph, id)).filter((im): im is AlgoImpl => !!im);
  const usedBy = usedByImpl(graph, impl.id);
  const ell = { minWidth: 0, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" } as const;
  const jump = (im: AlgoImpl) => onSelectImpl?.(im.id);

  // The impl's live visualization (#3177), if any. When present it's ALWAYS rendered inline above the
  // code (#3199); impls without one keep exactly today's code-only pane. A stored `vizCode` resolves via
  // the sandbox worker (#3233) — the in-app program shows first, then the stored program replaces it.
  const viz = useVizForImpl(impl);

  return (
    <Box style={PANEL}>
      <Stack gap={12} style={{ padding: 16 }}>
        <Row gap={8} align="center" style={{ minWidth: 0 }}>
          <Box style={{ width: 10, height: 10, borderRadius: 3, background: isPrim ? "var(--violet)" : "var(--accent)", flex: "none" }} />
          <Text weight={600} size={15} style={ell}>{impl.name}</Text>
          <Chip>{impl.role}</Chip>
        </Row>
        <Eyebrow size={10}>{isPrim ? "Language built-in" : "Implementation"} · {TECH_META[impl.tech]?.label ?? impl.tech}</Eyebrow>
        {impl.summary && <Text size={12} tone="muted">{impl.summary}</Text>}
        {/* A primitive is a DESCRIPTOR of a language built-in (#2972) — its std `ref`, not a reimplementation. */}
        {impl.ref && (
          <Row gap={8} align="center" style={{ minWidth: 0 }}>
            <Text mono size="xxs" tone="dim" style={{ letterSpacing: ".06em", textTransform: "uppercase", flex: "none" }}>Built-in</Text>
            <Text as="code" mono size={12} style={ell}>{impl.ref}</Text>
          </Row>
        )}

        {/* The visualization is always rendered inline (#3199) — an auto-playing preview; clicking it
            promotes the animation to the full graph canvas (#3205, via the workbench). Code stays below. */}
        {viz && onExpandViz && <VizPreview viz={viz} onExpand={onExpandViz} />}

        {impl.code && <Box as="pre" className="algo-code mono">{impl.code}</Box>}

        <ImplLinks label="Builds on" glyph="↳" impls={buildsOn} onJump={jump} />
        <ImplLinks label="Used by" glyph="↰" impls={usedBy} onJump={jump} />
      </Stack>
    </Box>
  );
}

/** A labeled list of implementation links (Builds on / Used by) in the per-kit graph (#2863) — each row
 *  jumps to that impl. Renders nothing when the list is empty. */
function ImplLinks({ label, glyph, impls, onJump }: {
  label: string;
  glyph: string;
  impls: AlgoImpl[];
  onJump: (im: AlgoImpl) => void;
}) {
  if (!impls.length) return null;
  const ell = { flex: 1, minWidth: 0, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" } as const;
  return (
    <Stack gap={4}>
      <Text mono size="xxs" tone="dim" style={{ letterSpacing: ".06em", textTransform: "uppercase" }}>{label}</Text>
      {impls.map((im) => (
        <Box as="button" key={im.id} className="algo-relrow" onClick={() => onJump(im)}>
          <Text as="span" tone="dim" size={11}>{glyph}</Text>
          <Text as="span" size={12} style={ell}>{im.name}</Text>
          <Text as="span" mono size="xxs" tone="dim">{im.id}</Text>
        </Box>
      ))}
    </Stack>
  );
}

runtime.features/algorithms/AlgorithmsKitGraph.t:
// The per-kit graph canvas (#2863) — a language kit's OWN graph: nodes are its implementations (a
// concept IS its implementation), wired by `composes` (builds-on) + `pairs` + the ontology's semantic
// relationships lifted onto the concrete impls. World-positioned impl cards over an SVG edge layer
// (GraphCanvas owns the pan/zoom transform) so it reads like every other graph. Selection lights a
// node + its neighbors. The role distinguishes the card (#2980): a primitive is a language built-in
// (#2972) — a violet dashed descriptor chip showing its std `ref` — vs an algorithm's solid card.
import { useMemo } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { graphEdge } from "@/shared/lib/graph/edgePath";
import { KIT_REL_META, NODE_W, NODE_H, type KitGraph, type KitRel, type KnowledgeLayout } from "./lib/knowledge";

interface KitEdgeGeom { id: string; rel: KitRel; from: string; to: string; d: string; arrow: string; arrowStart?: string; labelX: number; labelY: number }

export function AlgorithmsKitGraph({ kit, layout, selected, onSelect }: {
  kit: KitGraph;
  layout: KnowledgeLayout;
  /** The selected implementation id, or null. */
  selected: string | null;
  onSelect: (id: string) => void;
}) {
  // Neighbors of the selection (either direction) + the incident edges — the shared "focus dims the rest".
  const lit = useMemo(() => {
    if (!selected) return null;
    const nodes = new Set<string>([selected]);
    const edges = new Set<string>();
    for (const e of kit.edges) {
      const id = `${e.from}~${e.rel}~${e.to}`;
      if (e.from === selected) { nodes.add(e.to); edges.add(id); }
      if (e.to === selected) { nodes.add(e.from); edges.add(id); }
    }
    return { nodes, edges };
  }, [kit.edges, selected]);

  // Edge geometry — bow parallel edges between the same pair apart so they don't overdraw.
  const geoms = useMemo<KitEdgeGeom[]>(() => {
    const pairKey = (a: string, b: string) => (a < b ? `${a}|${b}` : `${b}|${a}`);
    const counts = new Map<string, number>();
    for (const e of kit.edges) counts.set(pairKey(e.from, e.to), (counts.get(pairKey(e.from, e.to)) ?? 0) + 1);
    const seen = new Map<string, number>();
    return kit.edges.flatMap((e) => {
      const a = layout.pos.get(e.from), b = layout.pos.get(e.to);
      if (!a || !b) return [];
      const key = pairKey(e.from, e.to);
      const n = counts.get(key)!;
      const i = seen.get(key) ?? 0;
      seen.set(key, i + 1);
      const bow = n > 1 ? (i - (n - 1) / 2) * 20 : 0;
      const meta = KIT_REL_META[e.rel];
      const g = graphEdge(
        { x: a.x, y: a.y, w: NODE_W, h: NODE_H },
        { x: b.x, y: b.y, w: NODE_W, h: NODE_H },
        { routing: "anchor", bow, doubleEnded: meta.doubleEnded },
      );
      return [{ id: `${e.from}~${e.rel}~${e.to}`, rel: e.rel, from: e.from, to: e.to, ...g }];
    });
  }, [kit.edges, layout.pos]);

  return (
    <>
      <svg width={layout.world.w} height={layout.world.h} style={{ position: "absolute", left: 0, top: 0, overflow: "visible", pointerEvents: "none" }}>
        {geoms.map((g) => {
          const isLit = !!lit && lit.edges.has(g.id);
          const dim = !!lit && !isLit;
          const stroke = isLit ? "var(--fg-dim)" : "var(--border)";
          return (
            <g key={g.id} style={{ opacity: dim ? 0.14 : 1, transition: "opacity 0.16s ease" }}>
              <path d={g.d} fill="none" stroke={stroke} strokeWidth={isLit ? 1.75 : 1.25}
                strokeDasharray={KIT_REL_META[g.rel].dashed ? "4 4" : undefined} />
              <path d={g.arrow} fill={stroke} />
              {g.arrowStart && <path d={g.arrowStart} fill={stroke} />}
              {isLit && (
                <text className="algo-edgelabel" x={g.labelX} y={g.labelY} textAnchor="middle" dominantBaseline="middle">
                  {KIT_REL_META[g.rel].label}
                </text>
              )}
            </g>
          );
        })}
      </svg>

      {kit.nodes.map((im) => {
        const p = layout.pos.get(im.id);
        if (!p) return null;
        const dim = !!lit && !lit.nodes.has(im.id);
        return (
          <Box
            key={im.id}
            data-impl={im.id}
            className={`algo-node${im.role === "primitive" ? " algo-prim" : ""}${im.id === selected ? " on" : ""}${dim ? " dim" : ""}`}
            style={{ left: p.x, top: p.y, width: NODE_W, height: NODE_H }}
            onClick={(e) => { e.stopPropagation(); onSelect(im.id); }}
          >
            <Box as="span" className="algo-name">{im.name}</Box>
            {/* A primitive is a language built-in (#2972) — show the std ref it names, not its id. */}
            <Box as="span" className="algo-meta mono">{im.role === "primitive" ? (im.ref ?? im.id) : im.id}</Box>
          </Box>
        );
      })}
    </>
  );
}

runtime.features/algorithms/AlgorithmsRail.tsx:
// The Algorithms page left rail (#2899/#4107/#4128) — the SAME structure the Components (Designs) rail
// renders, level for level:
//
//   Designs      kit head        →  folder tree (`groupComponentsByFolder`)  →  component rows
//   Algorithms   LANGUAGE head   →  folder tree (`folderTree`)               →  impl rows
//
// A language kit IS the algorithms analogue of a component kit (`kitImpls`/`kitGraph` are per-`tech`,
// each language has its own graph and its own dot), so the top level is a deliberate 1:1 mapping, not a
// divergence. Below it both rails build their tree with the ONE shared `buildFolderTree` and draw
// folders with the ONE shared `RailFolderRow` — so "the two libraries are presented the same" is
// enforced by construction rather than by two implementations agreeing.
//
// #4128 removed the "Filter by domain" dropdown (#3120). `domain` derives from the same `src` the folder
// path does, only COLLAPSED to a single segment, so surfacing it as a top-level selector offered a
// second, lossier organizer for the axis the folder tree already covers — and implied the library was
// organized by domain. Components never had an equivalent control. Search is the rail's one filter, and
// it matches the folder path (`matchesImpl`), which is how a folder is narrowed to now.
import { type ReactNode, useState } from "react";
import { GraphRail } from "@/shared/ui/layouts/GraphRail";
import { RailRow } from "@/shared/ui/layouts/RailRow";
import { RailFolderRow, RailFolderChildren } from "@/shared/ui/layouts/RailFolderRow";
import { SearchField } from "@/shared/ui/controls/SearchField";
import { ColorSwatch } from "@/shared/ui/controls/ColorSwatch";
import { useRailSections } from "@/shared/hooks/useRailSections";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import {
  groupImplsByLanguage, folderTree, folderImplCount, matchesImpl,
  type AlgoImpl, type AlgoFolderNode, type AlgoLangGroup, type KnowledgeGraph, type Tech,
} from "./lib/knowledge";

export function AlgorithmsRail({ graph, activeTech, selectedImpl, onSelectImpl, onSelectLang }: {
  graph: KnowledgeGraph;
  /** The active language — its head reads `active`, like the Designs rail's active kit. */
  activeTech: Tech;
  /** The selected implementation id (a leaf row). */
  selectedImpl: string | null;
  onSelectImpl: (id: string) => void;
  /** Focus a language (switch the graph to it) — clicking its head. */
  onSelectLang: (tech: Tech) => void;
}) {
  const [query, setQuery] = useState("");
  const folders = useRailSections(); // language + folder open state (default OPEN)
  const groups = groupImplsByLanguage(graph);

  // One language entry: the collapsible language head + its (search-filtered) folder tree. Mirrors
  // `RailTree`'s `renderRailKit`.
  const renderLanguage = (g: AlgoLangGroup) => {
    const open = folders.isOpen(g.key);
    const rows = g.impls.filter((im) => matchesImpl(im, query));

    // One impl row — the leaf, at the same depth every component row sits at in the Designs rail.
    const renderImplRow = (im: AlgoImpl): ReactNode => (
      <RailRow
        key={im.id}
        className="algo-implrow"
        indent={1}
        active={im.id === selectedImpl}
        onClick={() => onSelectImpl(im.id)}
        leading={<Box style={{ width: 8, height: 8, borderRadius: 2, background: im.role === "primitive" ? "var(--violet)" : "var(--accent)" }} />}
        trailing={<Text as="span" mono size="xxs" tone="dim">{im.id}</Text>}
      >
        {im.name}
      </RailRow>
    );

    // One folder of the language's tree: the shared header, its subfolders (recursion), then its direct
    // impl rows. Expand state is namespaced by language so two languages' identically-named folders
    // (`shared/lib/algorithms`) don't share a toggle. A collapsed folder doesn't render its subtree at
    // all, which matters for a harvested library carrying hundreds of impls across dozens of folders.
    const renderFolder = (f: AlgoFolderNode): ReactNode => {
      const fkey = `${g.key}::${f.key}`;
      const fopen = folders.isOpen(fkey);
      return (
        <Box key={f.key} className="algo-implfolder" style={{ marginBottom: 2 }}>
          <RailFolderRow
            className="algo-folderhead"
            label={f.label}
            count={folderImplCount(f)}
            open={fopen}
            onToggle={() => folders.toggle(fkey)}
            ungrouped={f.ungrouped}
            path={f.key}
          />
          {fopen && (
            <RailFolderChildren>
              {f.folders.map(renderFolder)}
              {f.items.map(renderImplRow)}
            </RailFolderChildren>
          )}
        </Box>
      );
    };

    // When this language's impls carry folder paths, render the nested tree; otherwise `tree` is null
    // and the flat impl list renders exactly as it would without folders.
    const tree = folderTree(rows);
    return (
      <Box key={g.key} style={{ marginBottom: 4 }}>
        <RailRow
          className="algo-langhead"
          caret={open}
          active={g.tech === activeTech}
          weight={500}
          title={`language: ${g.label}`}
          onClick={() => { onSelectLang(g.tech); folders.toggle(g.key); }}
          leading={<ColorSwatch color={g.dot} size={7} />}
          trailing={<Text as="span" mono size="xxs" tone="dim">{g.impls.length}</Text>}
        >
          {g.label}
        </RailRow>
        {open && (
          <Box style={{ margin: "2px 0 6px", paddingLeft: 6 }}>
            {tree ? tree.map(renderFolder) : rows.map(renderImplRow)}
            {rows.length === 0 && query.trim() && (
              <Text size={11} tone="dim" as="div" style={{ padding: "6px 10px", fontStyle: "italic" }}>no matches</Text>
            )}
          </Box>
        )}
      </Box>
    );
  };

  return (
    <GraphRail
      tools={
        <SearchField
          value={query}
          onChange={setQuery}
          placeholder="Search algorithms…"
          aria-label="Search"
          style={{ width: "100%" }}
        />
      }
    >
      {groups.map(renderLanguage)}
    </GraphRail>
  );
}

// The Algorithms knowledge-graph page (#2761, epic #2760 · #2863 · #2899) — rendered on the shared
// GraphCanvas + useGraphViewport (the Glance/Teams/Designs stack). Works basically like the Components
// (Designs) page: the LEFT PANE is a language-FOLDER tree (each language a folder, its impls the rows —
// #2899), and the CENTER is that language's OWN graph. A concept IS its implementation (#2958): the
// graph's nodes are the active kit's impls (primitives + algorithms), wired by `composes` (down to the
// primitive base). The active language is driven by rail selection. The inspector shows the selected
// impl's code + what it builds on / is used by. The seed is authored in @data/knowledge and hydrated
// live from the librarian's writable store (#2856).
import { useEffect, useMemo, useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Eyebrow } from "@/shared/ui/typography/Eyebrow";
import { Button } from "@/shared/ui/controls/Button";
import { GraphCanvas, ZoomControls } from "@/shared/ui/layouts/GraphCanvas";
import { GraphLegend } from "@/shared/ui/layouts/GraphLegend";
import { useGraphViewport } from "@/shared/ui/layouts/useGraphViewport";
import { useDragResize } from "@/shared/hooks/useDragResize";
import { useDockEntrance } from "@/shared/hooks/useDockEntrance";
import { useCrumbEntity } from "@/shared/hooks/useCrumbEntity";
import { AlgorithmsKitGraph } from "./AlgorithmsKitGraph";
import { AlgorithmsInspector } from "./AlgorithmsInspector";
import { AlgorithmsRail } from "./AlgorithmsRail";
import { LibrarianTerminal } from "./LibrarianTerminal";
import { VizStage } from "./viz/VizPanel";
import { useVizForImpl } from "./viz/useVizForImpl";
import {
  TECHS, TECH_META, NODE_W, NODE_H, layoutKitGraph, kitGraph, kitTechs, implById,
  KIT_REL_META, KIT_REL_ORDER, type Tech,
} from "./lib/knowledge";
import { useKnowledgeGraph } from "./useKnowledgeGraph";
import "./algorithms.css";

export function AlgorithmsWorkspace() {
  // Live graph (#2856): the seed for an instant first paint, hydrated + kept fresh from the librarian's
  // writable store (`bsc graph dump`) so their curation shows.
  const graph = useKnowledgeGraph();

  // The active language kit (#2899) — driven by the rail's folder selection. Defaults to the first kit.
  const [activeTech, setActiveTech] = useState<Tech>(() => kitTechs(graph)[0] ?? TECHS[0]);
  // The selected implementation (a node in the active kit's graph), shown in the inspector.
  const [selectedImpl, setSelectedImpl] = useState<string | null>(null);
  const focusedImpl = selectedImpl ? implById(graph, selectedImpl) ?? null : null;

  // The visualization take-over (#3205): when expanded, the focused impl's animation covers the graph
  // canvas (rail + inspector stay), mirroring the Components theme try-on. Track WHICH impl is expanded
  // (not a bare boolean) so selecting a different node auto-returns to the graph — `vizExpanded` is the
  // derived "the current selection is the expanded one", no reset effect needed. Its registered viz, if any.
  const [expandedImplId, setExpandedImplId] = useState<string | null>(null);
  const focusedViz = useVizForImpl(focusedImpl);
  const vizExpanded = expandedImplId != null && expandedImplId === selectedImpl;

  // The active language's OWN graph (impls + composes edges, down to the primitive base) + its layout.
  const kit = useMemo(() => kitGraph(graph, activeTech), [graph, activeTech]);
  // Name the active language in the titlebar crumb (#3041).
  useCrumbEntity("algorithms", TECH_META[activeTech]?.label ?? activeTech);
  const kitLayout = useMemo(() => layoutKitGraph(kit), [kit]);

  // The on-graph legend (#2909) — the relationship types ACTUALLY present in this kit's edges, keyed off
  // the same KIT_REL_META the canvas draws with, so it reads relevant to the language on screen.
  const legend = useMemo(() => {
    const present = new Set(kit.edges.map((e) => e.rel));
    const edges = KIT_REL_ORDER.filter((r) => present.has(r)).map((r) => ({ label: KIT_REL_META[r].label, dashed: KIT_REL_META[r].dashed }));
    return <GraphLegend sections={[{ label: "Relationships", edges }]} />;
  }, [kit.edges]);

  const vp = useGraphViewport(kitLayout.world, { contentBounds: () => kitLayout.bounds });
  // Frame the content on mount AND whenever the active language switches (each kit has its own world).
  useEffect(() => { vp.fit(); }, [activeTech]); // eslint-disable-line react-hooks/exhaustive-deps

  // Focus a language from the rail folder head — switch the graph to it; the selection belonged to the
  // old kit, so clear it (mirrors picking a different kit in the Designs rail).
  const selectLang = (t: Tech) => { setActiveTech(t); setSelectedImpl(null); };
  // Select an impl from the rail: switch to ITS language if needed (a cross-folder click), select it,
  // and — when it's already the active kit — pan its node to center.
  const selectImplFromRail = (id: string) => {
    const im = implById(graph, id);
    if (!im) return;
    setSelectedImpl(id);
    if (im.tech !== activeTech) {
      setActiveTech(im.tech); // the [activeTech] fit effect frames the new kit
      return;
    }
    const p = kitLayout.pos.get(id);
    if (p) vp.centerOn(p.x + NODE_W / 2, p.y + NODE_H / 2);
  };

  // The always-on librarian session's dock height (#2787) — a row-resize handle above it; `invert`
  // because the terminal sits AFTER the handle, so dragging up grows it. Mirrors the Teams dock (#2759).
  const term = useDragResize({ initial: 340, min: 140, max: 560, axis: "y", invert: true });
  useDockEntrance(term.setSize, 340); // grow the dock up into place on mount (#2905)

  // Header: the active language + its graph counts (the rail folders are the language switcher now), then
  // the graph nav (zoom/fit).
  const toolbar = (
    <>
      <Eyebrow size={10}>Algorithms</Eyebrow>
      <Text mono size="xxs" tone="dim">
        {TECH_META[activeTech]?.label ?? activeTech} · {kit.nodes.length} impls · {kit.edges.length} links
      </Text>
      <Box style={{ flex: 1 }} />
      <ZoomControls vp={vp} />
      <Button size="sm" variant="ghost" onClick={vp.fit}>Fit</Button>
    </>
  );

  return (
    <GraphCanvas
      profileId="algorithms"
      vp={vp}
      world={kitLayout.world}
      grid
      toolbar={toolbar}
      // In-canvas visualization take-over (#3205): when the user expands a focused impl's inline preview,
      // its animation covers the graph here (like the Designs theme try-on), with a ← Back to graph bar.
      // Otherwise the on-graph relationship legend.
      overlays={vizExpanded && focusedViz && focusedImpl
        ? <VizStage viz={focusedViz} implName={focusedImpl.name} onBack={() => setExpandedImplId(null)} />
        : legend}
      rail={<AlgorithmsRail graph={graph} activeTech={activeTech} selectedImpl={selectedImpl} onSelectImpl={selectImplFromRail} onSelectLang={selectLang} />}
      railResizable
      railWidth={230}
      inspector={<AlgorithmsInspector graph={graph} focusedImpl={focusedImpl} onSelectImpl={setSelectedImpl} onExpandViz={() => setExpandedImplId(selectedImpl)} />}
      inspectorResizable
      // Match the Components (Designs) inspector width and go a touch bigger (#3203), so the two
      // libraries read consistently and the always-inline visualization preview (#3199) has room.
      inspectorWidth={460}
      inspectorMin={300}
      inspectorMax={680}
      onBackgroundClick={() => setSelectedImpl(null)}
      // The always-on knowledge-librarian session (#2787), docked below the graph; the caller owns its
      // height + a `.resize-y` handle (GraphCanvas gives it a flex:none slot), mirroring Teams (#2759).
      dock={
        <Box style={{ display: "flex", flexDirection: "column", minHeight: 0 }}>
          <Box className="resize-y" {...term.handleProps} title="Drag to resize" />
          <LibrarianTerminal height={term.size} />
        </Box>
      }
    >
      <AlgorithmsKitGraph kit={kit} layout={kitLayout} selected={selectedImpl} onSelect={setSelectedImpl} />
    </GraphCanvas>
  );
}

