// The graph layout (#3224) — a pure, deterministic placement of node ids for the SVG GraphView. Split out
// of the renderer so the renderer file exports only its component (fast-refresh) and the layout is
// unit-testable on its own.

/** The svg viewBox is VIEW × VIEW; the layout circle has this radius. */
export const GRAPH_VIEW = 320;
const RADIUS = 116;

const PAD = 38; // inset for the coordinate layout so nodes don't touch the frame edge

/** Place every id evenly on a circle, starting at the top (−90°). Pure + deterministic. */
export function circularLayout(ids: readonly string[]): Record<string, { x: number; y: number }> {
  const cx = GRAPH_VIEW / 2;
  const cy = GRAPH_VIEW / 2;
  const n = Math.max(1, ids.length);
  const pos: Record<string, { x: number; y: number }> = {};
  ids.forEach((id, i) => {
    const t = (i / n) * 2 * Math.PI - Math.PI / 2;
    pos[id] = { x: cx + RADIUS * Math.cos(t), y: cy + RADIUS * Math.sin(t) };
  });
  return pos;
}

/** A spatial layout from the nodes' own `x`/`y` (a road network, a grid) — scaled + padded to fit the
 *  viewBox. Returns `null` unless EVERY node has coordinates (so the caller can fall back to circular). */
export function coordinateLayout(
  nodes: readonly { id: string; x?: number; y?: number }[],
): Record<string, { x: number; y: number }> | null {
  if (nodes.length === 0 || !nodes.every((n) => n.x !== undefined && n.y !== undefined)) return null;
  const xs = nodes.map((n) => n.x as number);
  const ys = nodes.map((n) => n.y as number);
  const minX = Math.min(...xs);
  const minY = Math.min(...ys);
  const spanX = Math.max(...xs) - minX || 1;
  const spanY = Math.max(...ys) - minY || 1;
  const inner = GRAPH_VIEW - 2 * PAD;
  const pos: Record<string, { x: number; y: number }> = {};
  for (const n of nodes) {
    pos[n.id] = {
      x: PAD + (((n.x as number) - minX) / spanX) * inner,
      y: PAD + (((n.y as number) - minY) / spanY) * inner,
    };
  }
  return pos;
}

/** The layout GraphView uses — the nodes' own coordinates when they all carry them (A*'s spatial graph),
 *  else an even circle. */
export function layoutFor(
  nodes: readonly { id: string; x?: number; y?: number }[],
): Record<string, { x: number; y: number }> {
  return coordinateLayout(nodes) ?? circularLayout(nodes.map((n) => n.id));
}

runtime.features/algorithms/viz/renderers/GraphV:
// The `graph` structure renderer (#3224, epic #3220) — a `StructureRenderer<"graph">` that draws a
// GraphFrame as an SVG node-link diagram on a circular layout. Node search state comes from the frame's
// durable `marks` and its start/goal anchors from the separate `roles` field (#3378 — both are static
// colours in graphView.css, and a node may carry one of each); the transient verbs (visit / frontier on a node,
// relax on an edge) are stamped as `data-op` and animate via the designer-authored KitAnimation data
// (`graphViewMotion.ts`). Like the other renderers, it only stamps state — never writes animation CSS.
import { useEffect } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { markStateAttrs, nodeOpStateAttrs, roleStateAttrs } from "../../lib/binding";
import type { GraphFrame } from "../../lib/trace";
import type { StructureRenderer } from "../registry";
import { GRAPH_VIZ_ANIM_CLASSES, ensureGraphViewMotion } from "./graphViewMotion";
import { layoutFor, GRAPH_VIEW as VIEW } from "./graphLayout";
import "./graphView.css";

const NODE_R = 19;

/** An undirected edge key so a relaxed edge matches regardless of endpoint order. */
const edgeKey = (a: string, b: string) => [a, b].slice().sort().join("~");

export const GraphView: StructureRenderer<"graph"> = ({ frame }: { frame: GraphFrame }) => {
  useEffect(() => {
    ensureGraphViewMotion();
  }, []);

  const { nodes, edges, ops, marks, roles } = frame;
  const pos = layoutFor(nodes);
  // The edges relaxed THIS frame (undirected) — stamped data-op="relax" so they flash.
  const relaxed = new Set(
    (ops ?? [])
      .filter((o): o is { op: "relax"; edge: [string, string] } => o.op === "relax")
      .map((o) => edgeKey(o.edge[0], o.edge[1])),
  );
  // A `path` op (Dijkstra / topological result) lights its route — flash each consecutive edge (reuse relax).
  for (const o of ops ?? []) {
    if (o.op === "path") {
      const seq = (o as { nodes: string[] }).nodes;
      for (let i = 0; i < seq.length - 1; i++) relaxed.add(edgeKey(seq[i], seq[i + 1]));
    }
  }
  // Nodes stamp only from node-addressed verbs (visit/frontier); relax animates the EDGE, not its endpoints.
  const nodeOps = (ops ?? []).filter((o) => o.op === "visit" || o.op === "frontier");

  return (
    <Box className={`graph-view ${GRAPH_VIZ_ANIM_CLASSES}`} role="img" aria-label="graph">
      <svg viewBox={`0 0 ${VIEW} ${VIEW}`} className="graph-svg" role="presentation">
        {edges.map((e) => {
          const a = pos[e.from];
          const b = pos[e.to];
          if (!a || !b) return null;
          const on = relaxed.has(edgeKey(e.from, e.to));
          const weighted = e.weight !== undefined && e.weight !== 1;
          return (
            <g key={`${e.from}-${e.to}`}>
              <line className="graph-edge" x1={a.x} y1={a.y} x2={b.x} y2={b.y} {...(on ? { "data-op": "relax" } : {})} />
              {weighted && (
                <text className="graph-weight" x={(a.x + b.x) / 2} y={(a.y + b.y) / 2} textAnchor="middle" dominantBaseline="central">
                  {e.weight}
                </text>
              )}
            </g>
          );
        })}
        {nodes.map((nd) => {
          const p = pos[nd.id];
          if (!p) return null;
          // Three independent axes: the transient verb, the walker's durable state, and the algorithm's
          // durable role. `roles` is stamped separately (#3378) so an explored start node still reads as
          // the origin — `data-mark="visited"` AND `data-role="start"`.
          const attrs = {
            ...nodeOpStateAttrs(nodeOps, nd.id),
            ...markStateAttrs(marks, nd.id),
            ...roleStateAttrs(roles, nd.id),
          };
          return (
            <g key={nd.id} transform={`translate(${p.x} ${p.y})`}>
              <circle className="graph-node" r={NODE_R} {...attrs} />
              <text className="graph-node-label" textAnchor="middle" dominantBaseline="central">
                {nd.label ?? nd.id}
              </text>
            </g>
          );
        })}
      </svg>
    </Box>
  );
};

