runtime.features/algorithms/viz/TracePlayer.tsx:
// The generic trace player (#3176, epic #3171) — the ONE React driver over the streaming engine
// (`makeTraceStream`) and the pluggable renderer registry. It lays the frame's named panels side by side,
// each dispatched to its structure's renderer (or the fallback). Every per-structure renderer (#3178–#3185)
// plugs in via the injected `renderers` map — this component never changes as they land.
//
// CONTROLS (#3207): the animation INFINITE-LOOPS on its own (no play/pause, no scrubber). The only
// controls are STEP THROUGH — ‹ Step / Step › — which pause the loop to study a step, then it auto-resumes
// after a short idle (RESUME_MS). Step forward wraps at the end so you can step around the loop.
//
// Animation TIMING is intentionally simple: a `setInterval` tick that pulls one frame per beat. The
// STRUCTURE animations themselves are the kit's state-triggered motion (#3058), fired by the `data-op` /
// `data-mark` states each renderer stamps (see lib/binding.ts) — not driven from here.

import { createElement, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";
import { Eyebrow } from "@/shared/ui/typography/Eyebrow";
import { Button } from "@/shared/ui/controls/Button";
import { normalizeFrame, type Frame, type StructureFrame } from "../lib/trace";
import { makeTraceStream } from "../lib/traceStream";
import { resolveRenderer, type RendererRegistry } from "./registry";
import { CodeColumn } from "./CodeColumn";
import "./tracePlayer.css";

/** After the user stops stepping, resume the infinite loop this long later (#3207) — long enough to study
 *  a step, short enough that the animation returns to playing on its own (no play button). */
const RESUME_MS = 2500;

export interface TracePlayerProps {
  /** Produces a fresh trace generator from the algorithm's fixed input. MEMOIZE this at the call site
   *  (a stable identity) — a new factory rebuilds the stream (a fresh replay from frame 0). */
  factory: () => Generator<Frame>;
  /** The per-structure renderers to dispatch panels to. Omitted/partial → the fallback renderer covers
   *  any unregistered structure. */
  renderers?: RendererRegistry;
  /** Scrub-back window passed to the stream (frames). Default is the engine's {@link makeTraceStream}. */
  bufferSize?: number;
  /** Playback speed — frames per second. Default 4 (watchable; the viz teaches, it doesn't benchmark). */
  fps?: number;
  /** Start playing on mount (and on every stream re-init) instead of paused (#3199) — the inline preview
   *  is alive like a component thumbnail, no click needed. Default false (the fullscreen player). */
  autoPlay?: boolean;
  /** On reaching the end, seek back to frame 0 and keep playing (#3199) — a continuous loop for the inline
   *  preview. Default false (the fullscreen player stops at the end so the user can scrub). */
  loop?: boolean;
  /** Render the play/step/scrub control bar. Default true; the compact inline preview passes false so it's
   *  just the moving picture (#3199). */
  controls?: boolean;
  /** The trace-program source to show BESIDE the animation, with the current frame's op span highlighted
   *  (#3250). Omit for no code column — the inline preview is far too small for one, and an example with
   *  no runtime source (an in-app program) has nothing honest to show. */
  source?: string;
}

/** One panel: dispatch its frame to the registered renderer for its structure, or the fallback. Uses
 *  `createElement` (not `<Renderer/>`) so the dynamic dispatch isn't read as creating a component during
 *  render (react-hooks/static-components) — `resolveRenderer` returns an EXISTING, stable component. */
function PanelView({ name, frame, renderers }: { name: string; frame: StructureFrame; renderers: RendererRegistry }) {
  const renderer = resolveRenderer(renderers, frame.structure);
  return (
    <Stack gap={6} className="trace-panel">
      <Eyebrow size={10}>
        {name} · {frame.structure}
      </Eyebrow>
      {createElement(renderer, { frame })}
    </Stack>
  );
}

export function TracePlayer({ factory, renderers = {}, bufferSize, fps = 4, autoPlay = false, loop = false, controls = true, source }: TracePlayerProps) {
  const stream = useMemo(() => makeTraceStream(factory, { bufferSize }), [factory, bufferSize]);
  const [frame, setFrame] = useState<Frame | null>(null);
  const [index, setIndex] = useState(-1);
  const [maxIndex, setMaxIndex] = useState(-1); // highest index reached — the scrubber's known extent
  const [playing, setPlaying] = useState(false);

  // Reflect the imperative stream cursor into React state (frame content + index + known extent).
  const sync = useCallback(() => {
    const i = stream.index();
    setIndex(i);
    setFrame(stream.current());
    setMaxIndex((m) => Math.max(m, i));
  }, [stream]);

  // Show the first frame whenever the stream (re)initializes; auto-play when asked (#3199 inline preview).
  useEffect(() => {
    stream.seek(0);
    sync();
    setPlaying(autoPlay);
  }, [stream, sync, autoPlay]);

  // The play loop: pull one frame per beat. At the end, loop back to 0 (#3199 inline preview) or stop.
  useEffect(() => {
    if (!playing) return;
    const id = setInterval(() => {
      const f = stream.next();
      if (f == null) {
        // Reached the end: restart from frame 0 when looping, else stop and hold the final frame.
        if (loop) {
          stream.seek(0);
          sync();
        } else {
          sync();
          setPlaying(false);
        }
      } else {
        sync();
      }
    }, Math.max(1, Math.round(1000 / fps)));
    return () => clearInterval(id);
  }, [playing, stream, sync, fps, loop]);

  // Stepping through the algorithm (#3207): each step PAUSES the infinite loop so the user can study that
  // step, then the loop AUTO-RESUMES after a short idle — so there is no play/pause button, it "just loops".
  const resumeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const clearResume = useCallback(() => {
    if (resumeTimer.current) {
      clearTimeout(resumeTimer.current);
      resumeTimer.current = null;
    }
  }, []);
  // Pause and, when looping, schedule the loop to resume after the user stops stepping.
  const pauseThenResume = useCallback(() => {
    setPlaying(false);
    clearResume();
    if (loop) resumeTimer.current = setTimeout(() => setPlaying(true), RESUME_MS);
  }, [loop, clearResume]);
  useEffect(() => clearResume, [clearResume]); // clear the pending resume on unmount

  const stepForward = useCallback(() => {
    pauseThenResume();
    // Wrap at the end so you can keep stepping through the loop (the viz is infinite).
    //
    // `next() === null` IS the end signal — `atEnd()` must NOT be tested first (#3390). The stream pulls
    // LAZILY, so the generator only reports `done` on the pull AFTER the last frame: while the cursor sits
    // on that last frame nothing has been pulled past it yet, `exhausted` is still false, and `atEnd()`
    // reads FALSE (asserted in traceStream.test.ts). Testing it first therefore fell through to `next()`,
    // which returned null and left the cursor parked — so the first click on the last frame did nothing
    // and the wrap cost a dead click, breaking "infinite stepping". Advancing first and wrapping on the
    // null return uses the same end-detection the play loop already uses.
    if (stream.next() == null) stream.seek(0);
    sync();
  }, [stream, sync, pauseThenResume]);

  const stepBack = useCallback(() => {
    pauseThenResume();
    stream.seek(Math.max(0, stream.index() - 1));
    sync();
  }, [stream, sync, pauseThenResume]);

  const panels = frame ? normalizeFrame(frame) : {};
  const entries = Object.entries(panels);
  const knownSteps = Math.max(0, maxIndex);

  const panelsRow = (
    <Row gap={12} wrap className="trace-panels">
      {entries.length === 0 ? (
        <Text size={12} tone="muted">
          No frames.
        </Text>
      ) : (
        entries.map(([name, panel]) => (
          <PanelView key={name} name={name} frame={panel} renderers={renderers} />
        ))
      )}
    </Row>
  );

  return (
    <Stack gap={12} className="trace-player">
      {/* With a source, the animation and the code sit side by side and step together (#3250); without
          one the panels row stays exactly as it was, so the inline preview's layout is untouched. */}
      {source ? (
        <Row gap={12} className="trace-split">
          <Box className="trace-split-viz">{panelsRow}</Box>
          <CodeColumn source={source} loc={frame?.loc} />
        </Row>
      ) : (
        panelsRow
      )}

      {controls && (
        // Step-through only (#3207): no play/pause, no scrubber — the animation infinite-loops on its own
        // and stepping pauses it to study a step (then it auto-resumes). Step forward wraps at the end.
        <Row gap={8} align="center" className="trace-controls">
          <Button variant="ghost" size="sm" aria-label="Step back" onClick={stepBack} disabled={index <= 0}>
            ‹ Step
          </Button>
          <Button variant="ghost" size="sm" aria-label="Step forward" onClick={stepForward}>
            Step ›
          </Button>
          <Text mono size={11} tone="dim">
            step {index < 0 ? "—" : index + 1}{knownSteps > 0 ? ` / ${knownSteps + 1}` : ""}
          </Text>
        </Row>
      )}
    </Stack>
  );
}

runtime.features/algorithms/viz/useVizForImpl.ts:
// The visualization hook for an implementation (#3233). Resolving a viz is now ASYNC when the impl carries
// a stored `vizCode` (it is compiled + run in the sandbox Web Worker), so the sync `vizForImpl` became this
// hook: the in-app program (trusted, main-thread) shows IMMEDIATELY, and a stored `vizCode` — when the
// worker returns its frames — REPLACES it. A malformed / timed-out `vizCode` falls back to the program.

import { useEffect, useState } from "react";
import type { AlgoImpl } from "../lib/knowledge";
import { programVizForImpl, resolveVizExample, type VizExample } from "./examples/registry";

/**
 * The {@link VizExample} to render for `impl`, or `undefined` when it has none.
 *
 * The in-app program is derived synchronously during render, so an algorithm with an in-app viz never
 * flashes empty. A stored `vizCode` resolves asynchronously via the sandbox and, once ready, replaces the
 * program (it is the durable per-algorithm form). The resolved code-viz is kept KEYED by its code string,
 * so switching implementations never shows a previous impl's stored viz. `null` impl → `undefined`.
 */
export function useVizForImpl(impl: Pick<AlgoImpl, "id" | "name" | "vizCode"> | null): VizExample | undefined {
  // The in-app program — synchronous, trusted, stable identity (a singleton per base name).
  const program = impl ? programVizForImpl(impl) : undefined;
  const vizCode = impl?.vizCode?.trim() ?? "";

  // The sandbox-resolved stored viz, tagged with the code it came from (so it's never used for a different
  // impl before its own resolves). Only the async callback sets state — no synchronous setState-in-effect.
  const [resolved, setResolved] = useState<{ code: string; viz: VizExample | undefined }>({ code: "", viz: undefined });

  useEffect(() => {
    if (!vizCode) return;
    let cancelled = false;
    void resolveVizExample(vizCode).then((viz) => {
      if (!cancelled) setResolved({ code: vizCode, viz });
    });
    return () => {
      cancelled = true;
    };
  }, [vizCode]);

  const codeViz = resolved.code === vizCode ? resolved.viz : undefined;
  return codeViz ?? program;
}

runtime.features/algorithms/viz/vizDataset.ts:
// vizRunToDataset (#2940): extract a plain, component-consumable DATASET from a sandbox VizRun — the
// bridge that lets a librarian ALGORITHM feed a designer COMPONENT's preview (the studio-network payoff).
//
// A VizRun is `{ datatype, input, frames }` where each Frame carries a fresh snapshot of the structure's
// data. The algorithm's OUTPUT is the LAST snapshot frame — a sort's sorted array, a matrix op's
// transformed grid, a graph layout's positioned nodes — falling back to the seed `input` when a run has
// no snapshot frames. The result is normalized so a component preview can bind a data prop straight to it
// (e.g. a `graph` dataset → a ForceGraph's `{ nodes, edges }`), with no per-component adapter.
import type { VizRun } from "./examples/vizProgram";
import type { GraphInput } from "../lib/tracer";

/** A nested tree node (#3790) — a `{ id, label, children? }` forest node, structurally the shared
 *  Tree/TreeExplorerPage `nodes` prop shape (`TreeNodeData`), so it binds directly. */
export interface TreeDatasetNode {
  id: string;
  label: string;
  children?: TreeDatasetNode[];
}

/** A normalized dataset extracted from a run — discriminated by the run's datatype, structurally-cloneable
 *  and directly bindable to a component prop. `graph` covers both the `graph` and `scene` datatypes; `tree`
 *  (#3790) is a NESTED forest (built from a BST's pure shape, not a run — see `datasetForStructure`). */
export type VizDataset =
  | { kind: "array"; data: number[] }
  | { kind: "matrix"; data: number[][] }
  | { kind: "graph"; nodes: GraphInput["nodes"]; edges: GraphInput["edges"] }
  | { kind: "tree"; roots: TreeDatasetNode[] };

// Frames are snapshots; we read the last one that carries the structure's data. Typed loosely here
// (the tracer's Frame union lives module-private) — we only touch the snapshot fields we extract.
type Snapshot = {
  structure?: string;
  data?: number[] | number[][];
  nodes?: GraphInput["nodes"];
  edges?: GraphInput["edges"];
};

/** The last frame that carries a structural snapshot (the algorithm's settled output), or undefined. */
function lastSnapshot(frames: readonly unknown[]): Snapshot | undefined {
  for (let i = frames.length - 1; i >= 0; i--) {
    const f = frames[i] as Snapshot;
    if (f && (f.data !== undefined || f.nodes !== undefined)) return f;
  }
  return undefined;
}

/**
 * Normalize a {@link VizRun} into a {@link VizDataset} a component preview can bind to. Prefers the
 * algorithm's FINAL snapshot (its computed output); falls back to the run's seed `input` so a run that
 * recorded no snapshot frames still yields the shaped data.
 */
export function vizRunToDataset(run: VizRun): VizDataset {
  const snap = lastSnapshot(run.frames);
  switch (run.datatype) {
    case "array": {
      const data = (snap?.data as number[] | undefined) ?? (run.input as number[]);
      return { kind: "array", data: [...(data ?? [])] };
    }
    case "matrix": {
      const data = (snap?.data as number[][] | undefined) ?? (run.input as number[][]);
      return { kind: "matrix", data: (data ?? []).map((row) => [...row]) };
    }
    case "graph":
    case "scene": {
      const seed = run.input as GraphInput;
      const nodes = snap?.nodes ?? seed?.nodes ?? [];
      const edges = snap?.edges ?? seed?.edges ?? [];
      return { kind: "graph", nodes: nodes.map((n) => ({ ...n })), edges: edges.map((e) => ({ ...e })) };
    }
  }
}

runtime.features/algorithms/viz/VizPanel.tsx:
// The Algorithms visualization surface (#3199/#3205). The animation is ALWAYS rendered inline in the
// inspector as a compact, auto-playing, looping preview (like a component thumbnail on the Components
// page). Clicking it does NOT open a modal — mirroring the Components page's theme try-on (#2834), it
// TAKES OVER THE GRAPH CANVAS: the workbench renders `VizStage` in GraphCanvas's `overlays` slot (rail +
// inspector stay), with a "← Back to graph" bar. So this file exports two pieces:
//   • VizPreview — the inline inspector thumbnail (lifts its expand to the workbench).
//   • VizStage   — the full in-canvas animation + editable "your input" field (rendered in overlays).
import { useCallback, useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";
import { Eyebrow } from "@/shared/ui/typography/Eyebrow";
import { Button } from "@/shared/ui/controls/Button";
import { TextField } from "@/shared/ui/controls/Field";
import { InlineError } from "@/shared/ui/feedback/InlineError";
import type { Frame } from "../lib/trace";
import { TracePlayer } from "./TracePlayer";
import type { VizExample } from "./examples/registry";
import "./vizPanel.css";

/** The compact inline preview — a controls-less, auto-playing, looping player wrapped in a clickable
 *  affordance (hover/focus surfaces an expand cue). Activating it lifts to the workbench, which promotes
 *  the animation to the full graph canvas (#3205). */
export function VizPreview({ viz, onExpand }: { viz: VizExample; onExpand: () => void }) {
  return (
    <Box
      className="algo-viz-preview"
      role="button"
      tabIndex={0}
      aria-label="Expand visualization — take a closer look and try your own input"
      title="Expand — take a closer look and try your own input"
      onClick={onExpand}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onExpand();
        }
      }}
    >
      <TracePlayer factory={viz.factory} renderers={viz.renderers} fps={3} autoPlay loop controls={false} />
      <Box as="span" className="algo-viz-expand-cue" aria-hidden>
        ⤢ Expand
      </Box>
    </Box>
  );
}

/**
 * The full in-canvas animation (#3205) — rendered in GraphCanvas's `overlays` slot so it COVERS THE GRAPH
 * (not the rail/inspector) and never pans/zooms, exactly like the Components theme try-on (#2834). A large
 * player with full controls + the editable "provide your own state" input; a valid Run rebuilds the trace
 * from the user's input, an invalid one surfaces the error and keeps the last good run. `← Back to graph`
 * returns to the canvas.
 */
export function VizStage({ viz, implName, onBack }: { viz: VizExample; implName: string; onBack: () => void }) {
  const [text, setText] = useState(viz.input.default);
  const [error, setError] = useState<string | null>(null);
  // The current trace factory: the example default, swapped to a fresh closure on each valid Run. Storing
  // a function in state needs the double-arrow form (useState/set treat a bare function as an initializer/
  // updater) — a new identity re-memoizes the player's stream, i.e. a fresh replay from frame 0.
  const [factory, setFactory] = useState<() => Generator<Frame>>(() => viz.factory);

  const run = useCallback(async () => {
    // Parse is synchronous (surfaces an input error immediately); make is async (#3233) — a stored-vizCode
    // re-run goes through the sandbox worker. On any failure the last good run is kept.
    let parsed: unknown;
    try {
      parsed = viz.input.parse(text);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      return;
    }
    try {
      const nextFactory = await viz.input.make(parsed);
      setFactory(() => nextFactory);
      setError(null);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    }
  }, [text, viz]);

  return (
    // Cover the canvas (inset:0) above the graph; stopPropagation keeps clicks off the canvas pan/deselect
    // wiring (mirrors the Designs try-on overlay). cursor:default — the pannable canvas is covered here.
    <Box
      className="algo-viz-stage"
      role="group"
      aria-label={`Visualization — ${implName}`}
      onMouseDown={(e) => e.stopPropagation()}
      onClick={(e) => e.stopPropagation()}
      style={{
        position: "absolute",
        inset: 0,
        zIndex: 5,
        display: "flex",
        flexDirection: "column",
        background: "var(--bg-canvas, var(--bg))",
        cursor: "default",
      }}
    >
      <Row align="center" gap={12} className="algo-viz-stage-head">
        <Button variant="ghost" onClick={onBack}>
          ← Back to graph
        </Button>
        <Eyebrow size={9.5}>Visualization</Eyebrow>
        <Text weight={600} size={13}>
          {implName}
        </Text>
      </Row>

      <Box className="algo-viz-stage-body">
        {/* The stage is the ONLY surface that pairs the animation with its code (#3250) — it has the room
            for two columns, and the inline preview deliberately stays a bare moving picture. `viz.source`
            is set only for a stored trace-program, so an in-app one simply shows no column. */}
        <TracePlayer factory={factory} renderers={viz.renderers} fps={4} autoPlay loop controls source={viz.source} />
      </Box>

      <Stack gap={8} className="algo-viz-stage-state">
        <Row gap={8} align="end">
          <Box style={{ flex: 1, minWidth: 0 }}>
            <TextField
              label="Your input"
              value={text}
              onChange={setText}
              hint={viz.input.hint}
              spellCheck={false}
              autoComplete="off"
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault();
                  void run();
                }
              }}
            />
          </Box>
          <Button onClick={() => void run()}>Run</Button>
        </Row>
        {error ? (
          <InlineError>{error}</InlineError>
        ) : (
          <Text size={11} tone="dim">
            Edit the input and Run to visualize your own state.
          </Text>
        )}
      </Stack>
    </Box>
  );
}

