runtime.features/automations/lib/cron.ts:
// Minimal, dependency-free 5-field cron support for Automations (#171):
//   minute(0-59) hour(0-23) day-of-month(1-31) month(1-12) day-of-week(0-7, 0|7=Sun)
// Each field accepts `*`, single values, `a,b` lists, `a-b` ranges, and `*/n` /
// `a-b/n` / `a/n` steps. Day-of-month / day-of-week use the standard Vixie
// semantics: when both are restricted a date matches if EITHER matches.

interface CronFields {
  minute: Set<number>;
  hour: Set<number>;
  dom: Set<number>;
  month: Set<number>;
  dow: Set<number>;
  domRestricted: boolean;
  dowRestricted: boolean;
}

/** Parse one field into the set of allowed values, or null if malformed. */
function parseField(field: string, min: number, max: number): Set<number> | null {
  const out = new Set<number>();
  for (const part of field.split(",")) {
    if (part === "") return null;
    const slash = part.split("/");
    if (slash.length > 2) return null;
    let step = 1;
    if (slash.length === 2) {
      step = parseInt(slash[1], 10);
      if (!Number.isInteger(step) || step <= 0) return null;
    }
    const range = slash[0];

    let lo: number, hi: number;
    if (range === "*") {
      lo = min; hi = max;
    } else if (range.includes("-")) {
      const [a, b] = range.split("-");
      lo = parseInt(a, 10); hi = parseInt(b, 10);
      if (!Number.isInteger(lo) || !Number.isInteger(hi)) return null;
    } else {
      lo = parseInt(range, 10);
      if (!Number.isInteger(lo)) return null;
      // `a/n` means from a, stepping, up to max; a bare `a` is just {a}.
      hi = step !== 1 ? max : lo;
    }
    if (lo < min || hi > max || lo > hi) return null;
    for (let v = lo; v <= hi; v += step) out.add(v);
  }
  return out.size ? out : null;
}

/** Parse a 5-field cron expression, or null if invalid. */
export function parseCron(expr: string): CronFields | null {
  const parts = expr.trim().split(/\s+/);
  if (parts.length !== 5) return null;
  const minute = parseField(parts[0], 0, 59);
  const hour = parseField(parts[1], 0, 23);
  const dom = parseField(parts[2], 1, 31);
  const month = parseField(parts[3], 1, 12);
  const dowRaw = parseField(parts[4], 0, 7);
  if (!minute || !hour || !dom || !month || !dowRaw) return null;
  const dow = new Set<number>();
  for (const d of dowRaw) dow.add(d === 7 ? 0 : d); // 7 and 0 both mean Sunday
  return {
    minute, hour, dom, month, dow,
    domRestricted: parts[2] !== "*",
    dowRestricted: parts[4] !== "*",
  };
}

/** Whether a local Date (at minute resolution) matches the parsed fields. */
export function cronMatches(f: CronFields, d: Date): boolean {
  if (!f.minute.has(d.getMinutes())) return false;
  if (!f.hour.has(d.getHours())) return false;
  if (!f.month.has(d.getMonth() + 1)) return false;
  const domOk = f.dom.has(d.getDate());
  const dowOk = f.dow.has(d.getDay());
  if (f.domRestricted && f.dowRestricted) return domOk || dowOk;
  if (f.domRestricted) return domOk;
  if (f.dowRestricted) return dowOk;
  return true;
}

// Search horizon — ~4 years so leap-day-only expressions still resolve. The
// loop breaks on the first match, so this bound only matters for never-matching
// (but syntactically valid) expressions, which then return null.
const CAP_MINUTES = 366 * 4 * 1440;

/** Epoch ms of the next minute strictly after `fromMs` that matches, or null. */
export function nextCronRun(expr: string, fromMs: number): number | null {
  const f = parseCron(expr);
  if (!f) return null;
  let t = Math.floor(fromMs / 60000) * 60000 + 60000;
  for (let i = 0; i < CAP_MINUTES; i++) {
    if (cronMatches(f, new Date(t))) return t;
    t += 60000;
  }
  return null;
}

/** Cheap validity check for UI feedback. */
export function isValidCron(expr: string): boolean {
  return parseCron(expr) !== null;
}

runtime.features/automations/lib/dispatch.ts:
// Fire one automation into its target pane (#937). Extracted from useScheduler so BOTH
// the scheduler tick and the mobile "run now" path dispatch identically — resolve the
// target pane, build the payload, write it, and record the run. No React here; the host
// (PTY write, store record, clock) is injected so it's unit-testable.

import { resolveTargetPane, dispatchPayload, type Automation, type AutomationRun, type TabLike } from "./scheduler";
import { log } from "@/shared/lib/core/log";

export interface DispatchDeps {
  tabs: TabLike[];
  disabledPanes: Record<string, boolean>;
  /** Write into a pane (e.g. invoke("pty_write", …) + a trailing CR is added here). */
  write: (paneId: string, data: string) => Promise<void>;
  recordRun: (id: string, run: AutomationRun) => void;
  now: () => number;
}

/**
 * Dispatch `a` once, recording exactly one run (ok / skipped / fail). Never throws — a
 * write failure is captured as a failed run. Resolves after the run is recorded.
 */
export async function dispatchAutomation(a: Automation, deps: DispatchDeps): Promise<void> {
  const at = deps.now();
  const where = `${a.targetTab} › pane ${a.targetPaneIdx + 1}`;

  const paneId = resolveTargetPane(a.targetTab, a.targetPaneIdx, deps.tabs, deps.disabledPanes);
  if (!paneId) {
    deps.recordRun(a.id, { at, status: "skipped", note: `target ${where} not open` });
    return;
  }

  const payload = dispatchPayload(a);
  if (payload == null) {
    deps.recordRun(a.id, { at, status: "fail", note: "empty command" });
    return;
  }

  try {
    await deps.write(paneId, payload + "\r");
    deps.recordRun(a.id, { at, status: "ok", note: `ran command in ${where}` });
  } catch (e) {
    log.error(`automation ${a.id} dispatch failed: ${e}`);
    deps.recordRun(a.id, { at, status: "fail", note: String(e) });
  }
}

runtime.features/automations/lib/scheduler.ts:
// Pure scheduler core for Automations (#142). No React / no Tauri here — just the
// data model and the deterministic logic (next-run computation, target
// resolution, payload building) so it can be unit-tested in isolation. The tick
// loop and PTY dispatch live in useScheduler; CRUD lives in the store.

import { nextCronRun } from "./cron";
import { clamp } from "@/shared/lib/core/math";

export type Every = "minute" | "hour" | "day" | "weekday";
export type AutomationActionKind = "command";
export type RunStatus = "ok" | "skipped" | "fail";

export interface SimpleWhen {
  kind: "simple";
  every: Every;
  /** "HH:MM" for day/weekday; ":MM" or "MM" for hour; ignored for minute. */
  at: string;
}
export interface CronWhen {
  kind: "cron";
  /** Standard 5-field cron expression. */
  expr: string;
}
export type AutomationWhen = SimpleWhen | CronWhen;

export interface AutomationRun {
  at: number;        // epoch ms
  status: RunStatus;
  note: string;
}

export interface Automation {
  id: string;
  name: string;
  armed: boolean;
  when: AutomationWhen;
  /** Tab resolved at fire time by name (survives reordering); pane by index. */
  targetTab: string;
  targetPaneIdx: number;
  action: AutomationActionKind;
  command?: string;   // action === "command"
  lastRunAt: number | null;
  nextRunAt: number | null;
  runs: AutomationRun[];
}

/** Keep at most this many run records per automation. */
export const MAX_RUNS = 25;

/** Parse the minute component out of an hour spec ("15", ":15", "x:15"). */
function parseMinute(at: string): number {
  const m = at.replace(/^.*:/, "").trim();
  const n = parseInt(m, 10);
  return Number.isFinite(n) ? clamp(n, 0, 59) : 0;
}

/** Parse "HH:MM" into [hours, minutes], clamped; missing parts default to 0. */
function parseHourMinute(at: string): [number, number] {
  const [h, m] = at.split(":");
  const hh = clamp(parseInt(h ?? "0", 10) || 0, 0, 23);
  const mm = clamp(parseInt(m ?? "0", 10) || 0, 0, 59);
  return [hh, mm];
}

function isWeekend(d: Date): boolean {
  const day = d.getDay();
  return day === 0 || day === 6; // Sun or Sat
}

/**
 * The next fire time strictly after `fromMs`, in local time, or null if the
 * spec is unsupported. v1 supports minute/hour/day/weekday; week/month are a
 * follow-up.
 */
export function computeNextRun(when: AutomationWhen, fromMs: number): number | null {
  if (when.kind === "cron") return nextCronRun(when.expr, fromMs);

  const from = new Date(fromMs);

  if (when.every === "minute") {
    // Next whole-minute boundary after `from`.
    return Math.floor(fromMs / 60000) * 60000 + 60000;
  }

  if (when.every === "hour") {
    const mm = parseMinute(when.at);
    const c = new Date(from);
    c.setSeconds(0, 0);
    c.setMinutes(mm);
    if (c.getTime() <= fromMs) c.setHours(c.getHours() + 1);
    return c.getTime();
  }

  if (when.every === "day" || when.every === "weekday") {
    const [hh, mm] = parseHourMinute(when.at);
    const c = new Date(from);
    c.setSeconds(0, 0);
    c.setHours(hh, mm);
    if (c.getTime() <= fromMs) c.setDate(c.getDate() + 1);
    if (when.every === "weekday") {
      while (isWeekend(c)) c.setDate(c.getDate() + 1);
    }
    return c.getTime();
  }

  return null;
}

export interface TabLike { name: string; layout: string }

/** Pane count for a "C×R" layout string. */
export function paneCount(layout: string): number {
  const [c, r] = layout.split("×").map(n => parseInt(n, 10));
  return (c || 0) * (r || 0);
}

/**
 * Resolve an automation's (tab name, pane index) target to a live pane id
 * `t{tabIdx}p{paneIdx}`, or null when the target tab is gone, the pane index is
 * outside the tab's layout, or the pane is disabled. The tab is matched by name
 * so it tracks renamed/reordered tabs.
 */
export function resolveTargetPane(
  targetTab: string,
  targetPaneIdx: number,
  tabs: TabLike[],
  disabledPanes: Record<string, boolean>,
): string | null {
  const tabIdx = tabs.findIndex(t => t.name === targetTab);
  if (tabIdx < 0) return null;
  if (targetPaneIdx < 0 || targetPaneIdx >= paneCount(tabs[tabIdx].layout)) return null;
  const paneId = `t${tabIdx}p${targetPaneIdx}`;
  if (disabledPanes[paneId]) return null;
  return paneId;
}

/**
 * The text payload to write into the target pane for an automation, or null if
 * the command is empty. A trailing carriage return is the caller's responsibility.
 */
export function dispatchPayload(a: Automation): string | null {
  const cmd = (a.command ?? "").trim();
  return cmd.length > 0 ? cmd : null;
}

/** Armed automations whose nextRunAt is due (non-null and ≤ now). */
export function dueAutomations(automations: Automation[], nowMs: number): Automation[] {
  return automations.filter(a => a.armed && a.nextRunAt != null && a.nextRunAt <= nowMs);
}

/** Append a run (capped to MAX_RUNS, newest first). */
export function appendRun(runs: AutomationRun[], run: AutomationRun): AutomationRun[] {
  return [run, ...runs].slice(0, MAX_RUNS);
}

/**
 * Map a planning automation suggestion (#174) to a scheduler {@link Automation} input.
 * A cron `schedule` becomes an **armed** cron trigger; an on-demand suggestion (no
 * schedule) is a saved-but-**unarmed** command the user can arm or run. The command fires
 * into `targetTab`, pane 0 (the project's launched tab).
 */
export function suggestionToAutomation(
  s: { name: string; command: string; schedule?: string },
  targetTab: string,
): Omit<Automation, "id" | "lastRunAt" | "nextRunAt" | "runs"> {
  const when: AutomationWhen = s.schedule
    ? { kind: "cron", expr: s.schedule }
    : { kind: "simple", every: "day", at: "09:00" };
  return {
    name: s.name,
    armed: !!s.schedule,
    when,
    targetTab,
    targetPaneIdx: 0,
    action: "command",
    command: s.command,
  };
}

