          <Box className="head-row">
            <Text as="h3">Schedules</Text>
            <Box as="span" className="hint">{automations.length} total · {armedCount} armed</Box>
          </Box>
        </Box>
        <Box className="scroll">
          {automations.map(a => (
            <Box key={a.id} className={"sched-row" + (a.id === selectedId ? " on" : "")} onClick={() => onSelect(a.id)}>
              <Box className="l1">
                <Box as="span" className={"dot" + (a.armed ? "" : " off")} />
                <Box as="span" className="spacer" />
                <Chip style={{ fontSize: 9.5 }}>{a.action}</Chip>
              </Box>
              <Box className="name">{a.name}</Box>
              <Box className="meta">
                <Text as="span">{a.when.kind === "simple"
                  ? `⏱ every ${a.when.every}${a.when.every !== "minute" ? " · " + a.when.at : ""}`
                  : `⏱ cron · ${a.when.expr}`}</Text>
                <Text as="span">{a.targetTab ? `→ ${a.targetTab} › pane ${a.targetPaneIdx + 1}` : "→ (no target)"}</Text>
              </Box>
            </Box>
          ))}
          <Box pad={[12, 14]}>
            <Button variant="ghost" style={{ width: "100%", justifyContent: "center" }} onClick={onNew}>+ new automation</Button>
          </Box>
        </Box>
      </Card>
    </Box>
  );
}

/** The slide-in editor for the selected schedule — the unified <Pane> drawer (#1824), the same
 *  chrome as the MCP server/hook + Skills drawers. Rendered in the AutomationsWorkspace overlay. */
export function ScheduleDrawer({ selected, onClose, onViewAllHistory }: {
  selected: Automation | null;
  onClose: () => void;
  onViewAllHistory: (id: string) => void;
}) {
  const { updateAutomation, setAutomationArmed, removeAutomation, tabs, paneNames } = useAppStore();
  const sel = selected;
  const close = onClose;

  const tabIdx = sel ? tabs.findIndex(t => t.name === sel.targetTab) : -1;
  const paneOpts = tabIdx >= 0 ? Array.from({ length: paneCount(tabs[tabIdx].layout) }, (_, i) => i) : [];
  const patchSimple = (p: Partial<SimpleWhen>) => {
    if (sel && sel.when.kind === "simple") updateAutomation(sel.id, { when: { ...sel.when, ...p } });
  };
  const setMode = (kind: "simple" | "cron") => {
    if (!sel || kind === sel.when.kind) return;
    updateAutomation(sel.id, {
      when: kind === "cron" ? { kind: "cron", expr: "0 9 * * *" } : { kind: "simple", every: "day", at: "09:00" },
    });
  };

  return (
    <Pane
      flush
      open={!!sel}
      onClose={close}
      onRemove={() => { if (sel) { removeAutomation(sel.id); close(); } }}
      header={sel && (
        <>
          {/* eslint-disable-next-line no-restricted-syntax -- bespoke .name-input Pane-header title input, not a .field stack; TextField would change the header chrome */}
          <input className="name-input" value={sel.name} onChange={e => updateAutomation(sel.id, { name: e.target.value })} />
          <Box as="span" className={"toggle" + (sel.armed ? " on" : "")} title="armed" onClick={() => setAutomationArmed(sel.id, !sel.armed)} />
          <Text as="span" mono size={11} style={{ color: sel.armed ? "var(--success)" : "var(--fg-dim)" }}>{sel.armed ? "armed" : "disarmed"}</Text>
        </>
      )}
      body={sel && (
        <>
          {/* when */}
          <Box className="es"><Box className="es-row">
            <Box className="es-lbl accent">when</Box>
            <Stack gap={8}>
              <SegmentedControl
                options={[
                  { label: "simple", on: sel.when.kind === "simple", onClick: () => setMode("simple") },
                  { label: "cron", on: sel.when.kind === "cron", onClick: () => setMode("cron") },
                ]}
              />
              {sel.when.kind === "simple" ? (
                <Row gap={8} wrap className="mono" style={{ fontSize: 11, color: "var(--fg-muted)" }}>
                  <Text as="span">every</Text>
                  <SelectField style={{ width: 120 }} value={sel.when.every} onChange={v => patchSimple({ every: v as Every })}>
                    {EVERY_OPTS.map(o => <option key={o} value={o}>{o}</option>)}
                  </SelectField>
                  {sel.when.every !== "minute" && (
                    <>
                      <Text as="span">at</Text>
                      <TextField style={{ width: 90 }} value={sel.when.at}
                        placeholder={sel.when.every === "hour" ? ":MM" : "HH:MM"}
                        onChange={v => patchSimple({ at: v })} />
                    </>
                  )}
                </Row>
              ) : (
                <Row gap={8} wrap className="mono" style={{ fontSize: 11, color: "var(--fg-muted)" }}>
                  <Text as="span">cron</Text>
                  <TextField style={{ width: 200 }} value={sel.when.expr} placeholder="0 9 * * *" spellCheck={false}
                    onChange={v => updateAutomation(sel.id, { when: { kind: "cron", expr: v } })} />
                  {isValidCron(sel.when.expr)
                    ? <Text as="span" tone="dim" size={10}>min hour day-of-month month day-of-week</Text>
                    : <Text as="span" tone="danger" size={10}>invalid expression</Text>}
                </Row>
              )}
              <Box className="cron-strip">
                <Box as="span" className="label">next run</Box>
                <Box as="span" className="expr">{sel.armed ? fmtStamp(sel.nextRunAt) : "disarmed"}</Box>
                <Box as="span" style={{ flex: 1 }} />
                <Text as="span">last · <b>{sel.lastRunAt ? fmtStamp(sel.lastRunAt) : "never"}</b></Text>
              </Box>
            </Stack>
          </Box></Box>

          {/* target */}
          <Box className="es"><Box className="es-row">
            <Box className="es-lbl info">target</Box>
            {tabs.length === 0 ? (
              <Box className="hint">No console tabs open — open a console (and a pane) to target.</Box>
            ) : (
              <Grid cols={2} gap={10}>
                <SelectField label="console" value={sel.targetTab} onChange={v => updateAutomation(sel.id, { targetTab: v, targetPaneIdx: 0 })}>
                  {!tabs.some(t => t.name === sel.targetTab) && <option value={sel.targetTab}>{sel.targetTab || "(pick a console)"}</option>}
                  {tabs.map(t => <option key={t.name} value={t.name}>{t.name}</option>)}
                </SelectField>
                <SelectField label="pane" value={String(sel.targetPaneIdx)} onChange={v => updateAutomation(sel.id, { targetPaneIdx: Number(v) })}>
                  {paneOpts.length === 0 && <option value={0}>Pane 1</option>}
                  {paneOpts.map(i => {
                    const nm = paneNames[tabIdx]?.[i];
                    return <option key={i} value={i}>Pane {i + 1}{nm ? ` · ${nm}` : ""}</option>;
                  })}
                </SelectField>
              </Grid>
            )}
          </Box></Box>

          {/* action */}
          <Box className="es"><Box className="es-row">
            <Box className="es-lbl success">action</Box>
            <Stack gap={10}>
              <TextField placeholder="command to run in the target pane…" value={sel.command ?? ""} onChange={v => updateAutomation(sel.id, { command: v })} />
              <Box as="span" className="hint">Typed into the target pane's session, then submitted.</Box>
            </Stack>
          </Box></Box>

          {/* history */}
          <Box className="es" bg="var(--bg-canvas)"><Box className="es-row">
            <Box className="es-lbl muted">history</Box>
            <Box>
              <Row align="baseline" gap={10} style={{ marginBottom: 10 }}>
                <Text as="span" mono size={11} tone="muted">last {sel.runs.length} runs</Text>
                <Box as="span" style={{ flex: 1 }} />
                {sel.runs.length > 0 && <Button variant="ghost" style={{ height: 22, fontSize: 10.5 }} onClick={() => onViewAllHistory(sel.id)}>view all →</Button>}
              </Row>
              {runsTable(sel.runs)}
            </Box>
          </Box></Box>
        </>
      )}
    />
  );
}

runtime.features/automations/store.ts:
// Automations feature store slice (#1309) — schedules, commands, and cron automations. Extracted
// from the former grab-bag `automations` slice (which kept LLM config / active-project state, now
// in store/slices/core.ts). Composed into the app store by store/index.ts.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import { type Automation, type AutomationRun, appendRun, computeNextRun } from "./lib/scheduler";
import type { Schedule, Command } from "@/shared/data/mock";

export interface AutomationsSlice {
  schedules: Schedule[];
  addSchedule: () => void;
  updateSchedule: (id: string, patch: Partial<Schedule>) => void;
  removeSchedule: (id: string) => void;
  commands: Command[];
  addCommand: () => void;
  updateCommand: (id: string, patch: Partial<Command>) => void;
  removeCommand: (id: string) => void;
  automations: Automation[];
  addAutomation: (input: Omit<Automation, "id" | "lastRunAt" | "nextRunAt" | "runs">) => string;
  updateAutomation: (id: string, patch: Partial<Automation>) => void;
  removeAutomation: (id: string) => void;
  setAutomationArmed: (id: string, armed: boolean) => void;
  recordAutomationRun: (id: string, run: AutomationRun) => void;
}

export const createAutomationsSlice: StateCreator<AppStore, [], [], AutomationsSlice> = (set) => ({
  schedules: [],
  addSchedule: () =>
    set((s) => {
      const id = `S-${String(s.schedules.length + 1).padStart(2, "0")}`;
      const newSched: Schedule = {
        id, name: "New schedule", on: false,
        when: "every day · 02:00", target: "",
        action: "command", detail: "",
        lastRun: "—", nextRun: "—",
      };
      return { schedules: [...s.schedules, newSched] };
    }),
  updateSchedule: (id, patch) =>
    set((s) => ({ schedules: s.schedules.map((sc) => (sc.id === id ? { ...sc, ...patch } : sc)) })),
  removeSchedule: (id) =>
    set((s) => ({ schedules: s.schedules.filter((sc) => sc.id !== id) })),

  commands: [],
  addCommand: () =>
    set((s) => {
      const id = `cmd_${Math.random().toString(36).slice(2, 8)}`;
      const newCmd: Command = { id, name: "New command", cmd: "", used: 0, tags: [] };
      return { commands: [...s.commands, newCmd] };
    }),
  updateCommand: (id, patch) =>
    set((s) => ({ commands: s.commands.map((c) => (c.id === id ? { ...c, ...patch } : c)) })),
  removeCommand: (id) =>
    set((s) => ({ commands: s.commands.filter((c) => c.id !== id) })),

  automations: [],
  addAutomation: (input) => {
    // Mint the id outside `set` so the action can return it — callers select the new row via useDraft
    // instead of the fragile "find the last item" lookup the screens used to do.
    const id = `auto_${Math.random().toString(36).slice(2, 8)}`;
    set((s) => {
      const nextRunAt = input.armed ? computeNextRun(input.when, Date.now()) : null;
      const a: Automation = { ...input, id, lastRunAt: null, nextRunAt, runs: [] };
      return { automations: [...s.automations, a] };
    });
    return id;
  },
  updateAutomation: (id, patch) =>
    set((s) => ({
      automations: s.automations.map((a) => {
        if (a.id !== id) return a;
        const next = { ...a, ...patch };
        // Editing the trigger or arming re-derives the next fire time.
        if ("when" in patch || "armed" in patch) {
          next.nextRunAt = next.armed ? computeNextRun(next.when, Date.now()) : null;
        }
        return next;
      }),
    })),
  removeAutomation: (id) =>
    set((s) => ({ automations: s.automations.filter((a) => a.id !== id) })),
  setAutomationArmed: (id, armed) =>
    set((s) => ({
      automations: s.automations.map((a) =>
        a.id === id
          ? { ...a, armed, nextRunAt: armed ? computeNextRun(a.when, Date.now()) : null }
          : a),
    })),
  recordAutomationRun: (id, run) =>
    set((s) => ({
      automations: s.automations.map((a) =>
        a.id === id
          ? { ...a, runs: appendRun(a.runs, run), lastRunAt: run.at, nextRunAt: computeNextRun(a.when, run.at) }
          : a),
    })),
});

runtime.features/automations/useScheduler.ts:
import { useCallback, useEffect } from "react";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { usePoll } from "@/shared/hooks/usePoll";
import { dueAutomations } from "./lib/scheduler";
import { dispatchAutomation } from "./lib/dispatch";

/** How often the scheduler checks for due automations. */
const TICK_MS = 20_000;

/**
 * The Automations runtime (#142): a frontend tick that fires due, armed
 * automations and dispatches them into their target console pane via pty_write,
 * recording each run. Mounted once at the app root, so it runs regardless of the
 * active screen — but only while the app is open (which is also the only time
 * the target panes exist). Each fire reschedules itself (recordAutomationRun
 * recomputes nextRunAt), so a single tick fires a due automation exactly once.
 *
 * The per-automation dispatch is shared with the mobile "run now" path (#937) via
 * {@link dispatchAutomation}.
 */
export function useScheduler() {
  const tick = useCallback(async (isCancelled: () => boolean) => {
    const s = useAppStore.getState();
    const deps = {
      tabs: s.tabs,
      disabledPanes: s.disabledPanes,
      write: (paneId: string, data: string) => invoke<void>("pty_write", { paneId, data }),
      recordRun: s.recordAutomationRun,
      now: () => Date.now(),
    };
    for (const a of dueAutomations(s.automations, Date.now())) {
      if (isCancelled()) return;
      await dispatchAutomation(a, deps);
    }
  }, []);

  // A beat after mount (so the store has hydrated): the first tick. usePoll runs the rest on the
  // fixed interval (immediate:false — the grace tick covers mount, so the first interval tick is at TICK_MS).
  useEffect(() => {
    let cancelled = false;
    const initial = setTimeout(() => void tick(() => cancelled), 1000);
    return () => { cancelled = true; clearTimeout(initial); };
  }, [tick]);

  usePoll(tick, TICK_MS, [], { immediate: false });
}

runtime.features/debug/DebugSessionMount.tsx:
// DebugSessionMount (#3326, epic #3260) — the persistent host that keeps the app-owned DEBUG session's
// terminal ALIVE on the shared TerminalHost while the Settings `debugSession` flag is on, so the in-graph
// morph (the `debugger` node in the base-studio-code Glance graph, #3319/#3322) can show it. Replaces the
// old bespoke `useDebugTerminal` (its own single-mount xterm via `useScreenSession`): the terminal now
// lives on the app-level TerminalHost like every fleet terminal — re-parented INTO the Glance morph when
// the node is opened, and parked HERE (off-screen) when it's closed. The window (#3298) was removed in
// #3327; this is the terminal-architecture half of the migration.
//
// WHY A HIDDEN `primary` SLOT: TerminalHost renders a <TerminalView> for a paneId only WHILE that paneId
// has at least one claim; when the last claim (the morph) deregisters, the view unmounts and the PTY is
// torn down. A fleet terminal survives morph-close because its console GRID CELL is a permanent claim. The
// debug session has no cell — so THIS mount is its permanent `primary` claim. It:
//   • supplies the launch props (cwd + resume initCmd) as the primary, and
//   • sits OFF-SCREEN (not `display:none`, so the parked xterm still fits to a real size) — keeping the
//     PTY warm across morph open/close.
// The Glance morph drops a second, VISIBLE viewer slot (GlanceChatDock) for the same paneId; being the
// last claim it becomes the owner, so the host re-parents the live terminal into the morph on open and
// back here on close.
//
// POSTURE: the debug session is ALWAYS bypass + role-less (the unrestricted maintenance session in the
// base-studio-code source tree). That posture is NOT a store role — it's the `isFullCapabilitySession`
// carve-out in `buildSessionSettings` (bypass) + the absence of a `paneRoles` entry (role-less). So this
// mount only seeds the two ordinary Claude-launch store fields TerminalView reads: the charter and resume.
import { useEffect, useState } from "react";
import { useAppStore } from "@/store";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { Box } from "@/shared/ui/layout/Box";
import { TerminalSlot } from "@/app/console/terminal/TerminalSlot";
import { DEBUG_STUDIO_SESSION_ID } from "@/shared/lib/session/systemSessions";

/** The debug session's stable pane id — one global, app-owned session (excluded from crash recovery via
 *  systemSessions, like the designer/librarian/architect). */
export const DEBUG_PANE_ID = DEBUG_STUDIO_SESSION_ID;

/**
 * ALWAYS launch a FRESH conversation (#3497) — never `--continue`.
 *
 * This pane's cwd is the REPO ROOT, which is the same cwd every other Claude session on the machine
 * uses, and `claude --continue` resumes the most recent conversation for a **directory**, not for a
 * pane. So `--continue` here did not resume "the prior debug conversation" — it resumed whichever
 * unrelated session last ran in this repo (there were three from the same hour when this was found).
 *
 * And it failed SILENTLY in both directions: the charter below is delivered as `--initial-message`
 * FRESH-ONLY, so a resumed launch dropped it and the session was never told to work the request queue.
 * The queue then sat unread with no error anywhere — `activity.log` showed prompts submitted while
 * `audit.log` / `tokens.log` / `perm.log` had nothing at all for this pane.
 *
 * Launching fresh removes the whole class: the pane can never attach to a stranger's conversation, and
 * the charter always arrives. The cost is no continuity across restarts, which is the right trade for
 * a queue worker — it re-reads the queue on every start — and is the direction #3498 is heading anyway
 * (per-request ephemeral sessions, where continuity is explicitly not wanted).
 */
export const DEBUG_INIT_CMD = "claude";

/** The inline charter baked into the launch as `claude --initial-message`. Delivery is `fresh-only`
 *  (`resolveStartupPromptFreshOnly`), which is why {@link DEBUG_INIT_CMD} must never resume: a resumed
 *  launch drops this silently and the session runs with no idea it is the debugger (#3497). Kept
 *  verbatim from the old `useDebugTerminal`. */
export const DEBUG_START_PROMPT =
  "You are the base-studio-code DEBUG session. You have full read/write access to THIS repository and " +
  "run the normal dev workflow. Your job: improve the `bsc ui` surface so the Design Studio's designer " +
  "session never needs permissions outside it. Work the improvement queue — CLAIM the next request with " +
  "`bsc request claim --by \"$BSC_AUDIT_PANE\" --json` (claiming is atomic, so you and the overflow pool " +
  "never take the same one; if it prints nothing the queue is empty), reproduce the cited `bsc` command, " +
  "implement the fix in the owning crate with tests, verify the gate (cargo check + clippy --all-targets " +
  "+ typecheck/lint for any frontend), then `bsc request resolve <id> --note \"<what changed>\"` and rebuild the sidecar with " +
  "`cargo build --release --bin bsc` so the running app picks it up. Do your work in a git worktree under " +
  "`.claude/worktrees/<branch>/` on a branch off develop and open a PR — NEVER commit/push to develop or " +
  "main directly, and never switch the main checkout off develop. Start by claiming a request.";

/** Keeps the debug session's PTY warm on TerminalHost while `debugSession` is on. Renders nothing visible
 *  (the terminal is shown by the Glance morph); returns null when the flag is off or the source tree isn't
 *  on this machine (a shipped binary — the ungated session must never launch against a missing cwd). */
export function DebugSessionMount() {
  const debugSession = useAppStore((s) => s.debugSession);
  // undefined = still resolving; null = no source tree (shipped binary); string = the repo root cwd.
  const [repoRoot, setRepoRoot] = useState<string | null | undefined>(undefined);

  // Resolve the source tree once the session is enabled. None on a machine that didn't build this binary
  // → don't launch (the graph node simply won't open a live terminal).
  useEffect(() => {
    if (!debugSession) { setRepoRoot(undefined); return; }
    let alive = true;
    void safeInvoke<string | null>(
      "debug_repo_root", undefined, null,
      (e: unknown) => console.error("debug_repo_root failed:", e),
    ).then((root) => { if (alive) setRepoRoot(root); });
    return () => { alive = false; };
  }, [debugSession]);

  // Seed the two ordinary Claude-launch store fields TerminalView reads at pty_create: the charter (baked
  // as --initial-message) and the resume flag. Everything else about the debug session's posture comes
  // from the isFullCapabilitySession carve-out, not the store.
  //
  // `paneContinue` is FALSE (#3497). It is the flag TerminalView actually turns into `claude --continue`
  // at pty_create, so it — not just the initCmd — is what made this pane resume. Both had to change:
  // fixing only the initCmd would have left the bug fully intact. See {@link DEBUG_INIT_CMD} for why
  // resuming is wrong here at all (this pane's cwd is the shared repo root, so a resume attaches to
  // whichever unrelated session last ran in this repo, and silently drops the fresh-only charter).
  useEffect(() => {
    if (!debugSession || !repoRoot) return;
    useAppStore.setState((st) => ({
      paneStartupPromptText: { ...st.paneStartupPromptText, [DEBUG_PANE_ID]: DEBUG_START_PROMPT },
      paneContinue:          { ...st.paneContinue, [DEBUG_PANE_ID]: false },
    }));
  }, [debugSession, repoRoot]);

  if (!debugSession || !repoRoot) return null;
  return (
    // Off-screen (NOT display:none, so the hidden xterm still fits to a real size) permanent `primary`
    // claim. The morph's visible viewer slot re-parents the terminal in when the node is opened.
    <Box
      aria-hidden
      style={{
        position: "absolute", left: -99999, top: 0, width: 800, height: 600,
        overflow: "hidden", pointerEvents: "none", display: "flex", flexDirection: "column",
      }}
    >
      {/* `parked` (#3357): a holding claim never takes ownership from a real surface — it owns the terminal
          only as the last claim standing. Behaviour-identical here (the morph is the only other claimant),
          and it keeps every app-owned session mount on the same rule. */}
      <TerminalSlot paneId={DEBUG_PANE_ID} primary parked visible={false} initialCwd={repoRoot} initCmd={DEBUG_INIT_CMD} />
    </Box>
  );
}

runtime.features/debug/index.ts:
// The DEBUG session feature (epic #3260) — an app-owned, full-capability Claude session in the
// base-studio-code SOURCE tree that works the `bsc request` improvement queue (fixing `bsc ui`). It is
// surfaced as the `debugger` node in the base-studio-code Glance graph (#3319/#3322), shown only when the
// Settings `debugSession` flag is on. The separate OS window (#3298) was removed in #3327; the terminal
// now lives on the app-level TerminalHost (#3326) — kept warm by `DebugSessionMount` and shown in the
// in-graph morph when the node is opened.
export { DebugSessionMount, DEBUG_PANE_ID } from "./DebugSessionMount";
// #3535: the standing debug session is the always-on primary; RequestSessionsMount is the paced,
// capped OVERFLOW pool beside it. Inert unless the Settings auto-spawn toggle is on (off by default).
export { RequestSessionsMount } from "./RequestSessionsMount";
export { poolPaneId, poolCharter } from "./requestSession";

runtime.features/debug/requestSession.ts:
// Pure helper for the warm-pool overflow sessions (#3535) — kept out of the component file so it is
// directly testable and so the mount stays a component-only module.
export { poolPaneId } from "@/shared/lib/session/requestSpawn";
import { DEBUG_START_PROMPT } from "./DebugSessionMount";

/**
 * The charter an OVERFLOW pool session launches with (#3535). Unlike the old per-request charter, it names
 * no specific request — an overflow session is a generic worker that CLAIMS the next available request on
 * startup, so it self-coordinates with the standing session and its pool siblings (the claim is atomic,
 * so no two ever take the same one).
 *
 * `--by "$BSC_AUDIT_PANE"` stamps the session's own pane id on the claim, which is how the pool tells a
 * busy session (holds a claim) from an idle one. The closing instruction is deliberate: a request must
 * never be left open with no explanation — "filed and silently unworked" is the failure this whole
 * feature exists to remove — and the resolve note IS the change log the maintainer reads back.
 */
export function poolCharter(): string {
  return (
    `${DEBUG_START_PROMPT}\n\n` +
    `YOU ARE AN OVERFLOW POOL SESSION. Claim the next available request and work ONLY that one:\n` +
    `  bsc request claim --by "$BSC_AUDIT_PANE" --json\n\n` +
    `If it prints a request, that request is yours — reproduce the failing command, implement the fix ` +
    `in the owning crate with tests, verify the gate, then:\n` +
    `  bsc request resolve <id> --note "<what you changed>"\n\n` +
    `The note is the change log — always leave one, even if it turns out NOT to be a defect (resolve it ` +
    `anyway with a note saying why; a request must never be left open with no explanation). Then STOP — ` +
    `your session is done and the pool will close it. If claim prints nothing, the queue is empty: stop.`
  );
}

runtime.features/debug/RequestSessionsMount.tsx:
// RequestSessionsMount (#3535) — the OVERFLOW POOL manager. The standing debug session
// (`DebugSessionMount`) is the always-on primary that self-serves the request queue; this mount sizes the
// overflow beside it: when the pool is busy and there is more CLAIMABLE work it spins up ONE more
// generic-charter debugger, paced (one warming at a time) and hard-capped, and CLOSES each session when
// its claimed request resolves.
//
// It obeys a plan and decides nothing: `planPool` (shared/lib/session/poolPlan) owns the gate, the
// pacing, the cap and the reap. This mount is mechanics — poll the queue, apply the plan (seed a new
// session's charter, close finished ones, publish the live slots for the Glance graph), and LOG when the
// pool is at capacity with work still waiting (#3535).
//
// ── WHAT MAKES THIS SAFE TO SHIP ────────────────────────────────────────────────────────────────────
//  * INERT unless `autoSpawnDebugSessions` is on (off by default); turning it off closes every overflow.
//  * The only role it can start is the plan's — `debugger` — and every pool pane is under the
//    `debug-studio:` prefix, so it is full-capability + role-less like the standing session (#3520).
//  * Sessions launch FRESH (`claude`, never `--continue`) with `paneContinue: false` (#3497): each is
//    generic and must never inherit another conversation.
//  * Bounded: overflow is capped at POOL_CAP - 1, so a never-resolving request can't fill the machine.
import { useEffect, useRef, useState } from "react";
import { useAppStore } from "@/store";
import { bscJson, bscRun } from "@/shared/lib/core/bsc";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { usePoll } from "@/shared/hooks/usePoll";
import { log } from "@/shared/lib/core/log";
import { Box } from "@/shared/ui/layout/Box";
import { TerminalSlot } from "@/app/console/terminal/TerminalSlot";
import { planPool, type PoolSession, type RequestRow } from "@/shared/lib/session/poolPlan";
import { poolPaneId, poolSlotFromPaneId } from "@/shared/lib/session/requestSpawn";
import { DEBUG_INIT_CMD } from "./DebugSessionMount";
import { poolCharter } from "./requestSession";

/** How often to reconcile the pool against the queue. Slow on purpose: a request is not urgent, and this
 *  is also the cadence `pollsWarming` advances at (`poolPlan.MAX_WARM_POLLS` × this ≈ the warm-out grace). */
const POLL_MS = 20_000;

/** Max TOTAL concurrent debuggers INCLUDING the always-on standing session — so overflow is capped at
 *  POOL_CAP - 1. Three is the deliberate starting point (#3535): the standing session + up to two
 *  overflow. A never-resolving request must never be able to fill the machine with debuggers. */
const POOL_CAP = 3;

/** A raw row from `bsc request list --json` (snake_case from the Rust store). */
interface RawRequest {
  id: number;
  status: string;
  claimed_by?: string | null;
}

/** The lowest slot index not used by any kept session — so slots are reused as sessions come and go. */
function lowestFreeSlot(sessions: PoolSession[]): number {
  const used = new Set(sessions.map((s) => poolSlotFromPaneId(s.paneId)).filter((n): n is number => n != null));
  let slot = 0;
  while (used.has(slot)) slot += 1;
  return slot;
}

/**
 * Mounts the overflow debugger pool while auto-spawn is on. Renders nothing visible; each session's
 * terminal is shown by opening its Glance node, exactly like the standing debug session.
 */
export function RequestSessionsMount() {
  const enabled = useAppStore((s) => s.autoSpawnDebugSessions);
  // undefined = still resolving; null = no source tree (shipped binary — never launch into a missing
  // cwd); string = the repo root these sessions work in.
  const [repoRoot, setRepoRoot] = useState<string | null | undefined>(undefined);
  // The overflow sessions this pool tracks (NOT the standing session). Kept in a ref too so the poll
  // reconciles against the latest set without re-subscribing the interval (the ref is synced in an
  // effect, never during render).
  const [sessions, setSessions] = useState<PoolSession[]>([]);
  const sessionsRef = useRef<PoolSession[]>([]);
  useEffect(() => { sessionsRef.current = sessions; }, [sessions]);
  // Throttles the capacity-pressure log to the TRANSITION into at-capacity, not every 20s poll.
  const atCapRef = useRef(false);

  useEffect(() => {
    if (!enabled) { setRepoRoot(undefined); return; }
    let alive = true;
    void safeInvoke<string | null>("debug_repo_root", undefined, null, () => {}).then((root) => {
      if (alive) setRepoRoot(root);
    });
    return () => { alive = false; };
  }, [enabled]);

  // #3522: when the user TURNS auto-spawn on (off→on), review the queue once and drop completed (resolved)
  // requests. Keyed to the transition, never a poll; `bscRun` is fire-and-forget (a missing binary is a
  // no-op).
  const prevEnabled = useRef(enabled);
  useEffect(() => {
    const was = prevEnabled.current;
    prevEnabled.current = enabled;
    if (!was && enabled) void bscRun(null, ["request", "prune"]);
  }, [enabled]);

  // The reconcile loop: ONE planPool per poll (so `pollsWarming` advances once per cycle, not per render).
  // `bscJson` swallows a missing binary/verb and returns the fallback, so a machine without a working
  // `bsc` simply never spawns rather than erroring in a loop.
  usePoll(
    async () => {
      if (!enabled || !repoRoot) return;
      const raw = await bscJson<RawRequest[]>(null, ["request", "list", "--json"], []);
      const requests: RequestRow[] = raw.map((r) => ({ id: r.id, status: r.status, claimedBy: r.claimed_by ?? null }));
      const plan = planPool({ requests, sessions: sessionsRef.current, enabled, cap: POOL_CAP });

      // Capacity pressure (#3535): log only on the transition INTO at-capacity, so it's a signal, not spam.
      if (plan.atCapacity && !atCapRef.current) {
        log.warn(
          `debug pool at capacity (${POOL_CAP} incl. the standing session) — ${plan.waiting} request(s) waiting for a free session`,
          "debug",
        );
      }
      atCapRef.current = plan.atCapacity;

      // Free the store fields of every closed pane, so a stopped slot leaves nothing behind.
      if (plan.close.length) {
        useAppStore.setState((st) => {
          const prompts = { ...st.paneStartupPromptText };
          const cont = { ...st.paneContinue };
          for (const paneId of plan.close) { delete prompts[paneId]; delete cont[paneId]; }
          return { paneStartupPromptText: prompts, paneContinue: cont };
        });
      }

      let next = plan.sessions;
      if (plan.spawn) {
        const paneId = poolPaneId(lowestFreeSlot(next));
        // Seed the launch fields TerminalView reads: the generic charter (baked as --initial-message) and
        // paneContinue=false (#3497 — never resume; each pool session is generic and fresh).
        useAppStore.setState((st) => ({
          paneStartupPromptText: { ...st.paneStartupPromptText, [paneId]: poolCharter() },
          paneContinue: { ...st.paneContinue, [paneId]: false },
        }));
        next = [...next, { paneId, claimedId: null, pollsWarming: 0 }];
      }
      setSessions(next);
    },
    POLL_MS,
    [enabled, repoRoot],
  );

  // Publish the live slots so the Glance graph can render a node per overflow session (#3535). Without
  // this the sessions run with no node — unopenable, unsupervisable, unstoppable.
  const setActiveDebugSlots = useAppStore((s) => s.setActiveDebugSlots);
  useEffect(() => {
    setActiveDebugSlots(sessions.map((s) => poolSlotFromPaneId(s.paneId)).filter((n): n is number => n != null));
  }, [sessions, setActiveDebugSlots]);

  if (!enabled || !repoRoot || !sessions.length) return null;
  return (
    <Box
      aria-hidden
      style={{
        position: "absolute", left: -99999, top: 0, width: 800, height: 600,
        overflow: "hidden", pointerEvents: "none", display: "flex", flexDirection: "column",
      }}
    >
      {sessions.map((s) => (
        <TerminalSlot
          key={s.paneId}
          paneId={s.paneId}
          primary
          parked
          visible={false}
          initialCwd={repoRoot}
          initCmd={DEBUG_INIT_CMD}
        />
      ))}
    </Box>
  );
}

