// Share & import component kits (#2305 slice 1c) — the Design Studio's distribution surface. IMPORT a
// kit from a gist URL / share code, or SHARE the active kit as a no-account copy-paste code and (when
// signed in to GitHub) a one-click public gist. Rides the typed `component-kit` gist envelope (lib/
// kitGist.ts); the store's `importKit` lands the result as a collision-safe user kit.
import { useState } from "react";
import { useAppStore } from "@/store";
import { ModalCard } from "@/shared/ui/overlay/ModalCard";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";
import { SegmentedControl } from "@/shared/ui/controls/SegmentedControl";
import { SearchField } from "@/shared/ui/controls/SearchField";
import { InlineError } from "@/shared/ui/feedback/InlineError";
import { Code } from "@/shared/ui/data/Code";
import type { ComponentRecord, Kit } from "./lib/model";
import { importKitFromGist, kitFromCode, kitShareCode, publishKitToGist, type PublishedKitPin } from "./lib/kitGist";

interface Props {
  /** The active kit (offered for Share); null hides the Share tab's target. */
  kit: Kit | null;
  /** The active kit's components (what Share publishes). */
  components: ComponentRecord[];
  onClose: () => void;
  /** Called with the landed (possibly re-id'd) kit after a successful import. */
  onImported: (kit: Kit) => void;
}

export function KitShareModal({ kit, components, onClose, onImported }: Props) {
  const token = useAppStore((s) => s.githubToken);
  const login = useAppStore((s) => s.githubUser)?.login;
  const importKit = useAppStore((s) => s.importKit);
  const [tab, setTab] = useState<"import" | "share">(kit ? "share" : "import");
  const [ref, setRef] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [publishedUrl, setPublishedUrl] = useState<string | null>(null);
  // The published kit's store pin (#2465): id@version + sha256 — what a blueprint records to
  // reference this exact artifact. `warning` surfaces a local-store refusal (immutability).
  const [publishedPin, setPublishedPin] = useState<PublishedKitPin | null>(null);
  const [publishWarning, setPublishWarning] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  const doImport = async () => {
    const text = ref.trim();
    if (!text || busy) return;
    setBusy(true); setError(null);
    // A gist URL / id → fetch it; anything else is treated as a copy-paste share code.
    const res = /gist|github\.com|^[0-9a-f]{8,}$/i.test(text) ? await importKitFromGist(text, token) : kitFromCode(text);
    setBusy(false);
    if (!res.ok) { setError(res.error); return; }
    onImported(importKit(res.kit, res.components));
    onClose();
  };

  const code = kit ? kitShareCode(kit, components) : "";
  const copy = () => { void navigator.clipboard?.writeText(code); setCopied(true); setTimeout(() => setCopied(false), 1400); };

  const publish = async () => {
    if (!kit || busy) return;
    setBusy(true); setError(null); setPublishedUrl(null); setPublishedPin(null); setPublishWarning(null);
    // `publisher` (#2465): stamp the kit-store identity + register the published bytes in the
    // local versioned kit store, so the share carries a pinnable { id, version, hash } and the
    // gist URL becomes its `source`.
    const res = await publishKitToGist(token, kit, components, { public: true, publisher: login ?? "user" });
    setBusy(false);
    if (!res.ok) { setError(res.error); return; }
    setPublishedUrl(res.url);
    setPublishedPin(res.pin ?? null);
    setPublishWarning(res.warning ?? null);
  };

  return (
    <ModalCard title="Share & import kits" onClose={onClose} width={480}>
        <Box>
          <SegmentedControl label="" options={[
            { label: "↓ Import", on: tab === "import", onClick: () => { setTab("import"); setError(null); } },
            { label: "↑ Share", on: tab === "share", onClick: () => { setTab("share"); setError(null); } },
          ]} />

          {tab === "import" ? (
            <Box style={{ marginTop: 14, display: "flex", flexDirection: "column", gap: 10 }}>
              <Text size={12} tone="muted" style={{ lineHeight: 1.5 }}>Paste a <b style={{ color: "var(--fg)" }}>gist URL</b> or a <b style={{ color: "var(--fg)" }}>share code</b>. A kit is a single portable file — no account needed to import.</Text>
              <SearchField
                value={ref}
                onChange={setRef}
                onKeyDown={(e) => { if (e.key === "Enter") void doImport(); }}
                placeholder="https://gist.github.com/…  or a share code"
                aria-label="Kit gist URL or share code"
                icon={null}
                style={{ height: 34 }}
              />
              {error && <InlineError>{error}</InlineError>}
              <Box style={{ display: "flex", justifyContent: "flex-end" }}>
                <Button variant="primary" size="sm" onClick={doImport} disabled={busy || !ref.trim()}>{busy ? "importing…" : "Import kit"}</Button>
              </Box>
            </Box>
          ) : (
            <Box style={{ marginTop: 14, display: "flex", flexDirection: "column", gap: 12 }}>
              {!kit ? (
                <Text size={12} tone="dim">Select a kit to share it.</Text>
              ) : (
                <>
                  <Text size={12} tone="muted" style={{ lineHeight: 1.5 }}>Sharing <b style={{ color: "var(--fg)" }}>{kit.name}</b> ({components.length} components).</Text>
                  <Box>
                    <Box style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 5 }}>
                      <Text mono size="xxs" tone="dim" style={{ letterSpacing: ".06em", textTransform: "uppercase" }}>Share code (no account)</Text>
                      <Button variant="ghost" size="sm" onClick={copy}>{copied ? "copied ✓" : "copy"}</Button>
                    </Box>
                    <Code maxHeight={90} wrap>{code}</Code>
                  </Box>
                  <Box style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, paddingTop: 4, borderTop: "1px solid var(--border-soft, var(--border))" }}>
                    <Text size={11.5} tone="muted">Publish as a free public GitHub gist{token ? "" : " (sign in to GitHub first)"}.</Text>
                    <Button variant="primary" size="sm" onClick={publish} disabled={busy || !token}>{busy ? "publishing…" : "Publish to gist ↗"}</Button>
                  </Box>
                  {publishedUrl && (
                    <Box style={{ display: "flex", flexDirection: "column", gap: 6, padding: "8px 11px", borderRadius: 8, background: "color-mix(in oklch, var(--success), transparent 90%)", border: "1px solid color-mix(in oklch, var(--success), transparent 70%)" }}>
                      <Box style={{ display: "flex", alignItems: "center", gap: 8 }}>
                        <Text size={11.5} tone="success">Published →</Text>
                        <Text mono size={11} tone="accent" style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{publishedUrl}</Text>
                        <Box style={{ flex: 1 }} />
                        <Button variant="ghost" size="sm" onClick={() => { void navigator.clipboard?.writeText(publishedUrl); }}>copy url</Button>
                      </Box>
                      {publishedPin && (
                        <Text mono size={10} tone="dim" title={publishedPin.hash} style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                          pin {publishedPin.id}@{publishedPin.version} · sha256 {publishedPin.hash.slice(0, 12)}… — in your kit store; blueprints can pin it
                        </Text>
                      )}
                    </Box>
                  )}
                  {publishWarning && <InlineError>{publishWarning}</InlineError>}
                  {error && <InlineError>{error}</InlineError>}
                </>
              )}
            </Box>
          )}
        </Box>
    </ModalCard>
  );
}

runtime.features/designs/lib/analyticsEmit.ts:
// The shipped analytics EMIT runtime (#3816, epic #3809 slice 3) — the fixed, audited code that turns a
// component's #3810 `analytics` manifest (DATA) into a `bsc usage record` (#3812) call when one of its
// actions fires. This is the seam that finally connects the two halves the epic left disconnected: the
// per-node CONTRACT (`ComponentRecord.analytics`) and the per-app SINK (`bsc usage record`).
//
// The load-bearing principle (inherited from #3283): CODE vs DATA. The component DECLARES what it emits;
// THIS runtime — fixed, shipped, never LLM-authored — does the emitting. There is no `track()`/`emit()`
// call in any authored component: emission is derived from the manifest at the render seam, so an app
// composed from instrumented nodes is instrumented BY CONSTRUCTION, uniformly, for free.
//
// It is host-agnostic on purpose: the SINK is injected. A generated app running in a Node/dev process
// spawns `bsc usage record` (the argv `usageRecordArgs` builds); a test collects; a browser logs. Absent
// a sink the whole path is inert — the dev-only / opt-in gate.

import type { AnalyticsEvent } from "./model";

/** What `KitRenderer` reports when a bound handler fires (mirrors its `KitBindings.emit` argument): the
 *  node's component `type`, the action PROP that fired, and the args the underlying handler received. */
export interface ActionFire {
  type: string;
  prop: string;
  args: unknown[];
}

/** A resolved usage event, ready for the sink / the `bsc usage record` CLI. */
export interface UsageRecord {
  event: string;
  props: Record<string, unknown>;
}

/** Where resolved events go. Injected so the runtime is host-agnostic — see the file header. */
export type UsageSink = (rec: UsageRecord) => void;

/** A component-manifest lookup by a node's `type` (the host wires this to the components store; the
 *  shared renderer never reads the store itself). */
export type AnalyticsLookup = (type: string) => AnalyticsEvent[] | undefined;

/**
 * The convention that binds an action PROP to the event a component would declare for it: strip the
 * leading `on`, then PascalCase → snake_case (`onClick` → `click`, `onItemSelected` → `item_selected`,
 * `onFilterChanged` → `filter_changed`). Returns `undefined` for a non-action prop (one that is not
 * `on`-prefixed), which is the same "starts with `on`" shape the `no-analytics` doctor finding uses to
 * decide a component is interactive — so the finding and the runtime agree on what an action is.
 */
export function eventNameForProp(prop: string): string | undefined {
  if (!/^on[A-Z]/.test(prop)) return undefined;
  return prop
    .slice(2) // drop "on"
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1_$2") // acronym boundary: HTMLParser → HTML_Parser
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2") // camel boundary: ItemSelected → Item_Selected
    .toLowerCase();
}

/** A plain data object we can read a payload from — NOT an array and NOT a DOM `Event` (a click's
 *  `MouseEvent` carries no analytics payload, so it must not be mined for prop values). */
function isPlainPayload(v: unknown): v is Record<string, unknown> {
  if (typeof v !== "object" || v === null || Array.isArray(v)) return false;
  if (typeof Event !== "undefined" && v instanceof Event) return false;
  return true;
}

/**
 * Resolve a fired action to the usage event its component DECLARED — or `undefined` when the component
 * declared no matching event. It never invents an undeclared event: the manifest is the authority on
 * what an app reports.
 *
 * `props` are filled from the declared `PropSpec` NAMES, best-effort, from `args[0]` when that is a plain
 * data object (e.g. `onChange(nextValue)` where the value is an object, or a synthetic payload the host
 * passes). A DOM event or a scalar arg yields an EMPTY props map — the runtime records the event name
 * (the "what users do" signal `bsc usage summary` ranks) but does not fabricate a payload it cannot see.
 * This is the same honesty the prop validator publishes about what it can and cannot check.
 */
export function resolveAnalyticsEmit(
  manifest: AnalyticsEvent[] | undefined,
  prop: string,
  args: unknown[],
): UsageRecord | undefined {
  if (!manifest || manifest.length === 0) return undefined;
  const name = eventNameForProp(prop);
  if (!name) return undefined;
  const declared = manifest.find((e) => e.event === name);
  if (!declared) return undefined;

  const props: Record<string, unknown> = {};
  const payload = args[0];
  if (declared.props && isPlainPayload(payload)) {
    for (const p of declared.props) {
      if (Object.prototype.hasOwnProperty.call(payload, p.name)) props[p.name] = payload[p.name];
    }
  }
  return { event: declared.event, props };
}

/**
 * Build the exact argv `bsc usage record` (#3812) accepts, so the emit runtime's data-out shape IS the
 * CLI's input — a Node host can `spawn("bsc", usageRecordArgs(rec))` with no glue. `--props` is omitted
 * when the payload is empty (the CLI treats a missing `--props` as no payload).
 */
export function usageRecordArgs(rec: UsageRecord): string[] {
  const argv = ["usage", "record", "--event", rec.event];
  if (Object.keys(rec.props).length > 0) argv.push("--props", JSON.stringify(rec.props));
  return argv;
}

/**
 * Compose a manifest lookup + a sink into the hook `KitRenderer.emit` expects. A fire that resolves to no
 * declared event is a silent no-op — most action props are not instrumented, and that is fine.
 */
export function makeAnalyticsEmit(lookup: AnalyticsLookup, sink: UsageSink): (fire: ActionFire) => void {
  return (fire) => {
    const rec = resolveAnalyticsEmit(lookup(fire.type), fire.prop, fire.args);
    if (rec) sink(rec);
  };
}

/** Build an {@link AnalyticsLookup} from component records keyed by `name` — the studio host's bridge
 *  from its components store to the manifest-driven runtime. */
export function componentAnalyticsLookup(
  records: Iterable<{ name: string; analytics?: AnalyticsEvent[] }>,
): AnalyticsLookup {
  const byName = new Map<string, AnalyticsEvent[] | undefined>();
  for (const r of records) byName.set(r.name, r.analytics);
  return (type) => byName.get(type);
}

/** A sink that COLLECTS records — for tests and for a host that wants to batch/inspect before shipping. */
export function collectingSink(): UsageSink & { records: UsageRecord[] } {
  const records: UsageRecord[] = [];
  const sink = ((rec: UsageRecord) => {
    records.push(rec);
  }) as UsageSink & { records: UsageRecord[] };
  sink.records = records;
  return sink;
}

/** A sink that logs the `bsc usage record` argv — dev visibility. The real DB write is that CLI running
 *  in the app's OWN session, where `$BSC_USAGE_DB` is wired to the per-project `usage.db`. */
export const consoleUsageSink: UsageSink = (rec) => {
  // A deliberate dev-visibility sink; opt-in, never on by default.
  console.info("[usage] bsc", ...usageRecordArgs(rec));
};

runtime.features/designs/lib/colorHue.ts:
// Colour → OKLCH hue (#2663) — parse a CSS colour to its OKLCH hue in degrees [0,360), or null when
// unparseable. Handles the two forms the design contract's graph-category tokens actually use — hex
// (#rgb / #rrggbb) and oklch(L C H) — enough for designGenBridge to derive the REAL hue set the palette
// generator must avoid (superseding the old fictional even-spacing seed). Not a full CSS colour parser.

/** OKLCH hue (degrees, [0,360)) of a hex or `oklch()` colour string; null if it isn't one of those. */
export function hueOfColor(value: string): number | null {
  const v = value.trim().toLowerCase();
  // oklch(L C H [/ a]) — the hue is the third component; tolerate %/deg suffixes.
  const okl = /^oklch\(\s*[\d.]+%?\s+[\d.]+%?\s+([\d.]+)/.exec(v);
  if (okl) return norm(parseFloat(okl[1]));
  const rgb = hexToRgb(v);
  return rgb ? oklabHue(rgb) : null;
}

function norm(deg: number): number {
  return ((deg % 360) + 360) % 360;
}

/** #rgb / #rrggbb → [r,g,b] each in [0,1]; null otherwise. */
function hexToRgb(hex: string): [number, number, number] | null {
  const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/.exec(hex);
  if (!m) return null;
  const h = m[1];
  const to = (s: string) => parseInt(s.length === 1 ? s + s : s, 16) / 255;
  return h.length === 3
    ? [to(h[0]), to(h[1]), to(h[2])]
    : [to(h.slice(0, 2)), to(h.slice(2, 4)), to(h.slice(4, 6))];
}

/** sRGB [0,1]³ → OKLCH hue (deg). Björn Ottosson's canonical sRGB→linear→OKLab matrices; only the a/b
 *  components are needed for the hue (atan2(b, a)). */
function oklabHue([r, g, b]: [number, number, number]): number {
  const lin = (c: number) => (c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4));
  const R = lin(r), G = lin(g), B = lin(b);
  const l = Math.cbrt(0.4122214708 * R + 0.5363325363 * G + 0.0514459929 * B);
  const m = Math.cbrt(0.2119034982 * R + 0.6806995451 * G + 0.1073969566 * B);
  const s = Math.cbrt(0.0883024619 * R + 0.2817188376 * G + 0.6299787005 * B);
  const a = 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s;
  const bb = 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s;
  return norm((Math.atan2(bb, a) * 180) / Math.PI);
}

runtime.features/designs/lib/componentBridge.ts:
// The frontend ↔ component-library bridge (#2269/#2281). The library is a GLOBAL store, reached — from
// the UI AND from a live session's own shell — through the SAME `bsc ui …` CLI over the generic
// `bsc` bridge (#2114). Global store → every call passes `null` as the projectKey. This is the only
// place the components feature touches Tauri, so the pure model in `model.ts` stays React/Tauri-free.
//
// Two collections: components (`bsc ui …`) and kits (`bsc ui kit …`). Reads use `--full`
// (the complete objects the pane needs). `loadX` returns `null` when the bridge is unreachable (tests /
// web shell / an old bundled `bsc`) so the store keeps its seed rather than blanking it — NOT `bscJson`,
// whose degrade-to-`[]` would blank the seed.
import { bsc, bscRun, bscWrite } from "@/shared/lib/core/bsc";
import type { ComponentRecord, Kit, Role } from "./model";
import { ROLES } from "./model";

/**
 * Project one raw `bsc ui list --full` row into a full {@link ComponentRecord}, defaulting absent
 * optionals to their empty shape so an odd record never crashes hydration. Exported (#3606) so the
 * packaged SEED is assembled through the SAME projection — a seed record then equals `load(push(seed))`
 * by construction, satisfying the #2514 round-trip contract without hand-mirroring these defaults (the
 * server-stamped provenance the two copies differ by — `rev`/`updatedAt`/… — is excluded from the hash).
 */
export function projectComponent(c: Partial<ComponentRecord>): ComponentRecord {
  return {
    id: c.id!,
    // #3725: a suppression tombstone carries only `{id, suppressed}` — fall its name/kitId back to the id
    // so the projection stays total; the reconcile drops it before it's ever rendered anyway.
    name: c.name ?? c.id!,
    kitId: c.kitId ?? "",
    role: (ROLES.includes(c.role as Role) ? c.role : "primitive") as Role,
    // #3048 — the folder path; rides verbatim (never defaulted), like tech/style on a kit. Reads the
    // legacy `group` key too (#4107 slice B): the store holds records written under the old name, and
    // this projection is the ONE place a raw record becomes a Component, so the fallback belongs here
    // rather than scattered across every consumer.
    folder: (c as { folder?: string; group?: string }).folder ?? (c as { group?: string }).group,
    version: c.version ?? "",
    used: typeof c.used === "number" ? c.used : 0,
    tags: c.tags ?? [],
    variants: c.variants?.length ? c.variants : ["default"],
    composes: c.composes ?? [],
    props: c.props ?? [],
    whenUse: c.whenUse ?? [],
    whenNot: c.whenNot ?? [],
    src: c.src ?? "",
    srcText: c.srcText ?? "",
    builtin: c.builtin,
    suppressed: c.suppressed, // #3725 — the tombstone marker; reconcile intercepts it, doctor skips it
    wraps: c.wraps,
    provides: c.provides, // #3660 — the platform specifier this component overrides; rides verbatim (loader reads it)
    rules: c.rules,
    shapes: c.shapes,
    animations: c.animations, // #2942 — MOTION binding (the kit-animation names it plays); rides verbatim
    // #3810 / #3878 — the node's ANALYTICS events and its TESTS, the other two manifests it carries as
    // data. They ride verbatim like `animations`: this projection is an ALLOWLIST, so a field missing here
    // is dropped on every hydrate, and the seed round-trip below (`seed === load(push(seed))`) would break
    // for any record carrying one. Both were declared as contracts before anything populated them, so the
    // gap was invisible until the inspector's Tests tab (#3884) went to read them.
    analytics: c.analytics,
    tests: c.tests,
    spec: c.spec, // #3569 — a page/layout node's renderable GeneralNode skeleton; rides verbatim so the host can render from the store
    seedHash: c.seedHash, // #2483 — must ride the allowlist or the refresh baseline is lost on write-through
    // #3164/#3568 — provenance + change history, surfaced by the inspector History tab. SERVER-MANAGED:
    // the Rust stamp boundary recomputes rev/stamps + history from the PRIOR stored record and discards
    // whatever rides back on a write-through, so passing them here is display-only (never authoritative).
    rev: c.rev,
    updatedAt: c.updatedAt,
    updatedBy: c.updatedBy,
    history: c.history,
  };
}

/** Load every component from the global store via `bsc ui list --full`; `null` when unreachable. */
export async function loadComponents(): Promise<ComponentRecord[] | null> {
  try {
    const out = await bsc(null, ["ui", "list", "--full"]);
    const rows = JSON.parse(out.trim() || "[]") as Partial<ComponentRecord>[];
    // Defensive: keep only well-formed rows (id + name + kitId) — OR a suppression tombstone (#3725), which
    // carries only `{id, suppressed}` and must survive the filter so the reconcile can block the re-seed.
    return (rows ?? [])
      .filter((c): c is ComponentRecord => typeof c.id === "string" && !!c.id && (c.suppressed === true || (!!c.name && !!c.kitId)))
      .map(projectComponent);
  } catch {
    return null;
  }
}

/**
 * Load every component's GRAPH projection via `bsc ui list --graph` (#4072) — `null` when unreachable.
 *
 * The fast half of the Studio's two-phase hydration: 33 KB instead of `--full`'s 1.72 MB (77.6% of
 * which is `srcText` no node reads), so the page paints instead of blocking up to 8s.
 *
 * Every record is stamped `lite` — the projection's empty `srcText`/`props` are DEFAULTS, not values,
 * and consumers that need real source must wait for the full read rather than treat them as real.
 */
export async function loadComponentsGraph(): Promise<ComponentRecord[] | null> {
  try {
    const out = await bsc(null, ["ui", "list", "--graph"]);
    const rows = JSON.parse(out) as Partial<ComponentRecord>[];
    return rows.map((c) => ({ ...projectComponent(c), lite: true as const }));
  } catch {
    return null;
  }
}

/** Load every kit via `bsc ui kit list --full`; `null` when unreachable. */
export async function loadKits(): Promise<Kit[] | null> {
  try {
    const out = await bsc(null, ["ui", "kit", "list", "--full"]);
    const rows = JSON.parse(out.trim() || "[]") as Partial<Kit>[];
    return (rows ?? [])
      // A suppression tombstone (#3725, `{id, suppressed}`) survives the filter so the reconcile blocks the
      // kit's re-seed; its name falls back to the id.
      .filter((k): k is Kit => typeof k.id === "string" && !!k.id && (k.suppressed === true || !!k.name))
      // tech/style (#2487) ride VERBATIM — an absent field must stay absent (never defaulted), so a
      // pre-#2487 copy still hashes to its recorded seedHash and the #2483 reconcile can refresh it.
      .map((k) => ({ id: k.id, name: k.name ?? k.id!, tech: k.tech, style: k.style, stack: k.stack ?? "", dot: k.dot ?? "var(--fg-muted)", animations: k.animations, builtin: k.builtin, suppressed: k.suppressed, seedHash: k.seedHash }));
  } catch {
    return null;
  }
}

/** Write-through a component upsert (`bsc ui set`, JSON on stdin). Fire-and-forget; never throws
 *  (an old bundled `bsc` without the `ui` store verbs (#2469) degrades to cache-only). */
export async function pushComponent(component: ComponentRecord): Promise<void> {
  try { await bscWrite(null, ["ui", "set"], component); } catch { /* store unreachable — cache-only */ }
}
/** Write-through a component removal (`bsc ui remove <id>`). Never throws. */
export async function dropComponent(id: string): Promise<void> {
  try { await bscRun(null, ["ui", "remove", id]); } catch { /* store unreachable — cache-only */ }
}
/** Write-through a kit upsert (`bsc ui kit set`). Never throws. */
export async function pushKit(kit: Kit): Promise<void> {
  try { await bscWrite(null, ["ui", "kit", "set"], kit); } catch { /* store unreachable — cache-only */ }
}
/** Write-through a kit removal (`bsc ui kit remove <id>`). Never throws. */
export async function dropKit(id: string): Promise<void> {
  try { await bscRun(null, ["ui", "kit", "remove", id]); } catch { /* store unreachable — cache-only */ }
}

/** Record a captured preview RUNTIME error to the durable log `bsc ui preview-errors` tails (#3165). The
 *  message (a stack trace) rides on the child's stdin. Fire-and-forget: never throws — an old bundled
 *  `bsc` without the verb just no-ops the observability (the in-pane error banner still shows). Makes a
 *  preview throw — otherwise only ephemeral React state — readable from a session's shell. */
export async function recordPreviewError(id: string, message: string): Promise<void> {
  try { await bsc(null, ["ui", "preview-error", id], message); } catch { /* bridge/binary absent — banner-only */ }
}

runtime.features/designs/lib/componentPreview.ts:
// componentPreview (#2824) — assemble the in-memory files + bootstrap entry for a component's
// build-and-iframe preview. Pure (no esbuild, no DOM) so it's unit-testable; the actual esbuild-wasm
// bundle + iframe live in the shared preview transport.
//
// Two source paths:
//   • BUILT-IN react-ui component → its verbatim `source` from the packaged kit artifact, PLUS the
//     artifact's whole component + `runtime` (@/ dependency-closure) set as in-memory files. esbuild
//     tree-shakes to just what the entry imports; the mem plugin resolves `@/…` to these files and
//     bare imports (react, d3) to esm.sh.
//   • USER-AUTHORED component → its own self-contained implementation source (imports libraries as bare
//     specifiers, which resolve from esm.sh). This is the case that renders arbitrary-library components
//     — a d3 component previews with no install. The store record deliberately omits the artifact-only
//     `source` field (it's a contract catalog, #2794), so we take that source from `comp.source` when
//     present, ELSE from `comp.srcText` WHEN it's a real module rather than the usual usage snippet
//     (`looksBuildableModule`, #2828). A usage-snippet `srcText` (`import { X } from "@/…"; <X …/>`) is
//     NOT buildable — its `…` placeholders don't compile — so it stays an honest empty state.
//     COMPOSING (#3112): a user component may `import` a SIBLING in its kit (`@/<sibling.src>` or a
//     relative path); the transitive closure of the siblings it imports is vendored into the build so it
//     resolves and the component composes real siblings instead of inlining everything. An internal
//     import that resolves to NO sibling still fails buildability (the honest empty state).
//
// The bootstrap imports the component and mounts it with sample props derived from its prop schema, so a
// component with required props still renders something representative (not a curated mock).
import { isLibrarySpec } from "@/shared/lib/graph/nodeUrn";
import { resolveInternalBase } from "@/shared/lib/preview/importPath";
import type { ComponentRecord, PropSpec } from "./model";

/**
 * Resolve a `@bsc/<segment>/<name>` LIBRARY import (#3116) to the preview module it vendors — a `path` the
 * import resolves to within the mem file set + the module `source` (an algorithm's reusable `code`) — or
 * `null` when it doesn't resolve. Param-injected so this pure module never imports the algorithms store; the
 * default (`libraryModuleResolver`) is wired at the call sites. Absent ⇒ no `@bsc/…` handling (byte-identical
 * to pre-#3116 for a component with no library imports).
 */
export type LibraryModuleResolver = (spec: string) => { path: string; source: string } | null;

/** The buildable slice of the packaged kit artifact — each component's verbatim `source` and the
 *  `runtime` (non-component @/ closure), both keyed by their `src/`-relative path. This is exactly the
 *  `source` + `runtime` the `react-ui.json` artifact carries (built by reactUiKit.gen, consumed by
 *  `bsc ui emit`); the frontend already bundles it. */
export interface KitArtifact {
  components: { id: string; src: string; source?: string }[];
  runtime?: Record<string, string>;
}

/** The in-memory file set + entry handed to the esbuild bundler for one component's preview. */
export interface ComponentPreviewBuild {
  /** `src/`-relative path → source, PLUS the synthetic bootstrap entry (keyed {@link PREVIEW_ENTRY}). */
  files: Record<string, string>;
  /** The bootstrap entry's key in `files`. */
  entry: string;
}

/** The synthetic bootstrap entry that mounts the previewed component. */
export const PREVIEW_ENTRY = "__component_preview__.tsx";

/** Drop the `.ts`/`.tsx` extension from a `src/`-relative path so it reads as an import specifier. */
function stripExt(path: string): string {
  return path.replace(/\.(tsx|ts|jsx|js)$/, "");
}

// ── internal-import resolution (#3112) ─────────────────────────────────────────────────────────────
// Small twins of the graph_health scanners — kept LOCAL so componentPreview has no dependency on
// graphHealth (graphHealth imports THIS module). Behavior mirrors `importSpecifiers` /
// `isInternalSpecifier` / `resolveInternalBase` there and the Rust `graph_health.rs` twins. Used to
// vendor a user component's imported SIBLINGS into its preview build so it can compose real components.

/** Every module specifier imported/exported-from in `source` (`import … from "x"`, `import "x"`,
 *  `import("x")`), deduped. A loose regex scan — over-inclusion is harmless (callers only act on the
 *  ones that resolve to a sibling). */
function importSpecs(source: string): string[] {
  const specs = new Set<string>();
  let m: RegExpExecArray | null;
  const fromRe = /\bfrom\s*["']([^"']+)["']/g;
  const importRe = /\bimport\s*\(?\s*["']([^"']+)["']/g;
  while ((m = fromRe.exec(source))) specs.add(m[1]);
  while ((m = importRe.exec(source))) specs.add(m[1]);
  return [...specs];
}

/** Is `clause` — the text between an `import`/`export` keyword and its `from` — erased entirely by the
 *  TypeScript loader? Two spellings qualify: the statement-level keyword (`import type { P } from …`,
 *  `import type * as N from …`) and a named clause where EVERY binding carries the inline modifier
 *  (`import { type P, type Q } from …`).
 *
 *  SYNTACTIC on purpose. A binding that merely happens to name a type (`import { P } from …`) is NOT
 *  erasable — esbuild has no type information and keeps the import — so a MIXED clause (`{ run, type P }`)
 *  keeps the statement and stays a real dependency. Rust twin: `clause_is_type_only`. */
function clauseIsTypeOnly(clause: string): boolean {
  const t = clause.trim();
  // `type` must be its own word — `import { typeGuard }` is a value binding, not a type modifier.
  const typePrefixed = (s: string) => /^type[\s{*]/.test(s);
  if (typePrefixed(t)) return true;
  if (!t.startsWith("{") || !t.endsWith("}")) return false;
  const entries = t.slice(1, -1).split(",").map((e) => e.trim()).filter(Boolean);
  // An empty clause (`import {} from "x"`) survives as a side-effect import, so it is NOT an erasure.
  return entries.length > 0 && entries.every(typePrefixed);
}

/** The specifiers `source` imports ONLY under an erased (type-only) statement (#4076) — the loader drops
 *  them before resolving anything, so they need no sibling, runtime file, library node or npm stub.
 *
 *  A specifier imported BOTH ways (`import type { P } from "./x"` beside `import { run } from "./x"`) is
 *  absent: the value import survives, so the module is still a real dependency. Rust twin:
 *  `erased_specifiers`. Exported so `graphHealth` applies the SAME rule the preview build does — if the
 *  two drift, `doctor` accuses a component the preview renders happily (#3486). */
export function erasedSpecs(source: string): Set<string> {
  const erased = new Set<string>();
  const kept = new Set<string>();
  // `[^;]*?` keeps a clause from spanning a statement boundary and mis-attributing the next import.
  const re = /\b(?:import|export)\b([^;]*?)\bfrom\s*["']([^"']+)["']/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(source))) (clauseIsTypeOnly(m[1]) ? erased : kept).add(m[2]);
  for (const spec of kept) erased.delete(spec);
  return erased;
}

/** Is `spec` an INTERNAL first-party import — a `@/…` alias or a RELATIVE (`./`, `../`) path — as
 *  opposed to a bare npm specifier or an absolute path/URL? Only these resolve against sibling modules. */
function isInternalSpec(spec: string): boolean {
  return spec.startsWith("@/") || spec.startsWith("./") || spec.startsWith("../");
}

/** A user component's own IMPLEMENTATION source — its explicit `source`, else a non-empty `srcText`
 *  (buildability is judged separately). `null` when the record carries neither. */
function ownImplSource(c: ComponentRecord): string | null {
  if (c.source && c.source.trim()) return c.source;
  if (c.srcText && c.srcText.trim()) return c.srcText;
  return null;
}

/** The code-elision marker: U+2026 HORIZONTAL ELLIPSIS. Named rather than inlined so there is ONE place
 *  an encoding round-trip can damage it, and `elisionMarkerIsU2026` asserts its code point — if a tool or
 *  an editor ever rewrites this file as cp1252, the test fails loudly instead of the scanner silently
 *  degrading into a no-op that reports every source as clean. */
const ELISION = "…";

/**
 * Does the code-elision marker appear in real CODE — not inside a string/template literal or a comment?
 * Only then does it stand in for omitted code. The TS twin of Rust `has_code_elision`
 * (bsc-component::graph_health), ported in #3486; the two must move together, because Rust's
 * `is_preview_buildable` deliberately matched whatever THIS file does so `doctor` can never be more
 * permissive than the preview it reports on.
 *
 * The plain substring test this replaced is a MEASURED false-positive generator, not a hypothetical one:
 * the marker is ordinary UI copy (a `placeholder` ending in one) and ordinary doc-comment prose, and
 * over this repo's own `src/shared/ui` it condemned 13 perfectly good components as sketches. Condemning
 * a real component over the ellipsis in its placeholder text is a false accusation someone then has to
 * overrule — so both contexts are skipped.
 */
export function hasCodeElision(src: string): boolean {
  const b = Array.from(src);
  const n = b.length;
  let i = 0;
  while (i < n) {
    const c = b[i];
    if (c === "/" && b[i + 1] === "/") {
      while (i < n && b[i] !== "\n") i += 1;
    } else if (c === "/" && b[i + 1] === "*") {
      i += 2;
      while (i + 1 < n && !(b[i] === "*" && b[i + 1] === "/")) i += 1;
      i = Math.min(i + 2, n);
    } else if (c === '"' || c === "'" || c === "`") {
      i += 1;
      // A backslash escapes the next char, so an escaped quote doesn't end the literal.
      while (i < n && b[i] !== c) i += b[i] === "\\" ? 2 : 1;
      i += 1;
    } else if (c === ELISION) {
      // An ellipsis DIRECTLY after a word character is PROSE, not an elision marker (#3897). JSX TEXT
      // (`>Loading projects…</Text>`) is not quoted, so the string-skip above misses it — ProjectsPage read
      // as "a sketch, not compilable code" over three UI labels while the app mounted it fine. A real
      // marker sits in code position (`{ … }`, or alone on a line). Rust twin: `has_code_elision`.
      let j = i - 1;
      while (j >= 0 && /\s/.test(b[j])) j -= 1;
      if (j >= 0 && /[A-Za-z0-9]/.test(b[j])) { i += 1; continue; }
      return true;
    } else {
      i += 1;
    }
  }
  return false;
}

/**
 * Does `srcText` look like a self-contained, buildable component MODULE rather than a usage snippet?
 *
 * A component STORE record carries only `srcText` (the artifact-only `source` is stripped from the
 * store — it's a contract catalog, #2794). For most records that `srcText` is a usage snippet —
 * `import { X } from "@/…"; <X …/>` — which is NOT buildable here: its `@/` first-party imports have
 * no dependency closure to resolve against (only the built-in kit ships one), and its `…` placeholders
 * don't compile. A designer session CAN instead author a real, self-contained module into `srcText`
 * (importing only bare libraries, which resolve from esm.sh); that one previews.
 *
 * Heuristic (deliberately conservative — false-negative into the honest empty state, never a false
 * "buildable" that always throws): it must declare an `export` for the bootstrap to import, contain no
 * `…` placeholder, and use no `@/` first-party import.
 */
export function looksBuildableModule(srcText: string | undefined): boolean {
  const s = (srcText ?? "").trim();
  if (!s) return false;
  if (!/\bexport\b/.test(s)) return false; // no export ⇒ nothing for the bootstrap to import + mount
  if (hasCodeElision(s)) return false; // a `…` standing in for omitted CODE ⇒ won't compile (#3486)
  if (/["']@\//.test(s)) return false; // `@/` first-party import ⇒ no closure to resolve it against
  return true;
}

/**
 * Sibling-aware buildability (#3112): like {@link looksBuildableModule}, but an internal (`@/`, `./`)
 * import is allowed WHEN it resolves to a vendored sibling — the closure that lets a user-kit component
 * compose real siblings instead of inlining everything. `source` from module `fromRel`; `resolvesToSibling`
 * says whether an internal import spec lands on a sibling the preview will vendor. An internal import that
 * resolves to NOTHING still fails (the honest empty state); `…` placeholders and no-export still fail.
 */
export function isPreviewBuildable(
  source: string,
  fromRel: string,
  resolvesToSibling: (spec: string, fromRel: string) => boolean,
): boolean {
  const s = source.trim();
  if (!s) return false;
  if (!/\bexport\b/.test(s)) return false;
  if (hasCodeElision(s)) return false; // #3486: an ellipsis in COPY is not an elision marker
  const erased = erasedSpecs(s); // #4076: dropped by the loader before it resolves anything
  for (const spec of importSpecs(s)) {
    if (isInternalSpec(spec) && !erased.has(spec) && !resolvesToSibling(spec, fromRel)) return false;
  }
  return true;
}

/** The data-state a preview renders in (#3135/#3555): `loaded` (demo/populated), `empty` (no data),
 *  `loading` (the component's loading/skeleton render), or `error` (its error render). Drives how
 *  {@link samplePropValue} fills props; {@link supportedStates} decides which a component actually has. */
export type PreviewState = "loaded" | "empty" | "loading" | "error";

/** Is `p` a LOADING-family boolean — the toggle that puts a component into its loading/skeleton render
 *  (`loading` / `busy` / `pending` / `isLoading`)? It's ON only in the `loading` state, off otherwise —
 *  fixing the old "every boolean samples to true" quirk that previewed loading-components as skeletons.
 *  Exported (#3191) so the on-visit scan gates its loading-state blank probe on the SAME predicate that
 *  drives the sampled prop, keeping the finding and the render in lockstep. */
export function isLoadingProp(p: PropSpec): boolean {
  const t = (p.type || "").toLowerCase();
  return (t === "boolean" || t.includes("boolean")) && /^(loading|busy|pending|isloading)$/i.test(p.name);
}

/** Is `p` a COLLECTION prop — an array of data (`Row[]`, `array`)? The thing `empty` empties. A collection
 *  is OMITTED in loaded/loading so the component's own demo/default shows (the demo-on-undefined convention,
 *  #3135/#3693 — required collections omit too now); `empty` always passes an explicit `[]`. Exported (#3191)
 *  so the scan gates its empty-state blank probe on the SAME predicate that empties the sampled collection. */
export function isCollectionProp(p: PropSpec): boolean {
  const t = (p.type || "").toLowerCase();
  return t.includes("[]") || t.includes("array");
}

/** Is `t` (a LOWERCASED type) a `Record<K, V>` map object — a data container whose empty literal is `{}`
 *  (distinct from an array's `[]`)? Rust twin: `is_record_type`. */
function isRecordType(t: string): boolean {
  return t.startsWith("record<");
}
/** Is `t` (LOWERCASED) a `Set<T>` / `ReadonlySet<T>`? Empty literal `new Set()`; the `set<` boundary (or an
 *  exact bare `set`) keeps `offset`/`dataset`/`subset` out. Rust twin: `is_set_type`. */
function isSetType(t: string): boolean {
  return t === "set" || t.startsWith("set<") || t.startsWith("readonlyset<");
}
/** Is `t` (LOWERCASED) a `Map<K, V>` / `ReadonlyMap<K, V>`? Empty literal `new Map()`. Rust twin: `is_map_type`. */
function isMapType(t: string): boolean {
  return t === "map" || t.startsWith("map<") || t.startsWith("readonlymap<");
}

/** Is `p` an ERROR-family prop — the thing that puts a component into its error render (`error` / `err` /
 *  `isError` / `hasError`)? Set only in the `error` state, omitted otherwise (#3555). A callback like
 *  `onError` is NOT one (it's a function, excluded by name shape). Exported so the scan/doctor gate the
 *  error-state on the SAME predicate that drives the sampled prop. */
export function isErrorProp(p: PropSpec): boolean {
  const t = (p.type || "").toLowerCase();
  const isFn = t.includes("=>") || t.includes("function") || t.includes("void") || /^on[A-Z]/.test(p.name);
  return !isFn && /^(error|err|isError|hasError)$/i.test(p.name);
}

/**
 * A best-effort sample value (as a JS source literal) for a prop, from its (loosely-typed) schema, or
 * `null` to omit it. Enough to render a component whose required props would otherwise be missing —
 * NOT a curated example. `children` is handled by the caller (it becomes the element's child). `state`
 * (#3135) drives the data-state: `loading` turns on a loading-family boolean; `empty` passes the typed
 * EMPTY literal for a data container (`[]` array, `{}` Record, `new Set()`, `new Map()`); `loaded`
 * (default) / `loading` OMIT a container so a demo-on-undefined component shows its own default demo — the
 * same path object props (`gh`) already take. A required container omits too (#3693), not `[]`.
 */
export function samplePropValue(p: PropSpec, state: PreviewState = "loaded"): string | null {
  if (isLoadingProp(p)) return state === "loading" ? "true" : null;
  const t = (p.type || "").toLowerCase();
  const isFn = t.includes("=>") || t.includes("function") || t.includes("void") || /^on[A-Z]/.test(p.name);
  // #3555: an error-family prop is set ONLY in the error state — a boolean gets `true`, else a sample
  // message — and omitted otherwise so the component renders normally in loaded/loading/empty.
  if (isErrorProp(p)) {
    if (state !== "error") return null;
    return t === "boolean" || t.includes("boolean") ? "true" : JSON.stringify("Something went wrong");
  }
  if (isFn) return "() => {}";
  // Data-container props (#3693): omitted in loaded/loading so the component's own default demo shows; the
  // empty state passes the typed EMPTY literal. BEFORE the string/number branches — a `Record<string, number>`
  // / `Set<string>` type contains "string"/"number" and would otherwise sample as a title-cased string
  // (rendering `Object.values("Lang Totals")` NaN nonsense, or crashing `"Highlight".has(k)`). Required
  // containers omit too, exactly as the object-prop fall-through (`MergeQueue.gh`) already does.
  if (isCollectionProp(p)) return state === "empty" ? "[]" : null;
  if (isRecordType(t)) return state === "empty" ? "{}" : null;
  if (isSetType(t)) return state === "empty" ? "new Set()" : null;
  if (isMapType(t)) return state === "empty" ? "new Map()" : null;
  if (t.includes("reactnode") || t.includes("node")) return JSON.stringify(prettyName(p.name));
  if (t === "string" || t.includes("string")) return JSON.stringify(sampleString(p.name));
  if (t === "number" || t.includes("number")) return numberSample(p.name);
  if (t === "boolean" || t.includes("boolean")) return "true";
  // enum-like unions ("a" | "b") → the first literal.
  const firstLiteral = p.type.match(/"([^"]+)"/);
  if (firstLiteral) return JSON.stringify(firstLiteral[1]);
  return null;
}

/** A readable placeholder from a prop/component name (`whenUse` → "When use"). */
function prettyName(name: string): string {
  const s = name.replace(/([A-Z])/g, " $1").replace(/[-_]/g, " ").trim();
  return s.charAt(0).toUpperCase() + s.slice(1);
}
/** A plausible string sample — a color token for color-ish props, a fraction hint elsewhere. */
function sampleString(name: string): string {
  if (/colou?r|tone|accent|fill|stroke/i.test(name)) return "var(--accent)";
  if (/login|user|author/i.test(name)) return "octocat";
  return prettyName(name);
}
/** A number sample (as a JS source expression, evaluated in the preview iframe). CANVAS-dimension props
 *  (width/height/size) sample with the actual preview FRAME size (`window.innerWidth`/`innerHeight`) so a
 *  sized component — a d3 chart/graph — fills the frame at its orientation instead of the old 3px
 *  placeholder that rendered it as a tiny sample (#2918). STYLE dimensions (stroke/border/font/line
 *  width, gaps, spacing) are guarded out — they are not canvas sizes and must stay small. Everything else
 *  keeps the prior behavior: a 0–1 fraction for ratio-ish names, else a small integer. */
function numberSample(name: string): string {
  const n = name.toLowerCase();
  // Exclude style dimensions so `strokeWidth`/`borderWidth`/`fontSize`/… never become the viewport size.
  const styleDim = /stroke|border|font|line|gap|margin|pad|spacing|weight|gutter|inset|offset/.test(n);
  // A LAYOUT-COLUMN width/height (a fixed sidebar/rail/panel column, flex:none) must NOT be the viewport
  // size — that makes the column eat the whole preview frame (#3693). A fixed 240px keeps two-column layouts
  // intact; a canvas width (`width`/`w`/`chartWidth`) still fills the frame below.
  const layoutDim = /rail|aside|sidebar|drawer|panel|col/.test(n);
  if (!styleDim) {
    const isW = n === "w" || n === "width" || n.endsWith("width");
    const isH = n === "h" || n === "height" || n.endsWith("height");
    if (layoutDim && (isW || isH)) return "240";
    if (isW) return "window.innerWidth";
    if (isH) return "window.innerHeight";
    if (n === "size" || n === "extent") return "Math.min(window.innerWidth, window.innerHeight)";
  }
  return /value|fraction|ratio|progress|percent|opacity/i.test(name) ? "0.6" : "3";
}

/** One sampled prop the preview harness passes: its `name` and its VALUE as a JS-source
 *  literal/expression — exactly what {@link samplePropValue} returns (e.g. `"() => {}"`,
 *  `"window.innerWidth"`, `"\"Label\""`). NOT a JSON value: it's source the iframe evaluates. */
export interface PreviewProp {
  name: string;
  value: string;
}

/** The props (+ their sampled JS-source values) and the child text the bootstrap passes a component in
 *  ONE state — the inspectable form of what {@link bootstrapSource} mounts. `children` is excluded from
 *  `props` (it becomes the element child, carried in `child`). */
export interface PreviewProps {
  props: PreviewProp[];
  child: string | null;
}

/** The props the bootstrap passes `comp` in `state` — each non-`children` prop that samples to a
 *  non-`null` value, in `comp.props` (schema) order. The structured twin of the object literal
 *  {@link bootstrapSource} builds; `bsc ui preview-props` mirrors it (a shared parity fixture pins them). */
export function previewPropList(comp: ComponentRecord, state: PreviewState = "loaded"): PreviewProp[] {
  const out: PreviewProp[] = [];
  for (const p of comp.props) {
    if (p.name === "children") continue;
    const v = samplePropValue(p, state);
    if (v != null) out.push({ name: p.name, value: v });
  }
  return out;
}

/** The child text the bootstrap passes when `comp` declares a `children` prop
 *  (`JSON.stringify(prettyName(name))`), else `null`. State-independent (children never varies by state). */
export function previewChild(comp: ComponentRecord): string | null {
  return comp.props.some((p) => p.name === "children") ? JSON.stringify(prettyName(comp.name)) : null;
}

/** The inspectable props the preview harness passes `comp` in each data-state (#3165) — exactly what
 *  {@link bootstrapSource} mounts, per state. The `bsc ui preview-props` verb replicates this in Rust; a
 *  shared JSON fixture (`previewProps.fixtures.json`) is asserted on BOTH sides to keep them in lockstep.
 *  Covers the original three states only — `error` (#3555) renders via {@link bootstrapSource}'s per-state
 *  path but is NOT part of this cross-language wire contract. */
export function previewProps(comp: ComponentRecord): Record<Exclude<PreviewState, "error">, PreviewProps> {
  const child = previewChild(comp);
  return {
    loaded: { props: previewPropList(comp, "loaded"), child },
    empty: { props: previewPropList(comp, "empty"), child },
    loading: { props: previewPropList(comp, "loading"), child },
  };
}

/**
 * The data-states `comp` MEANINGFULLY supports (#3555), in natural display order — `loading` (has a
 * loading-family prop) → `loaded` (always) → `empty` (has a collection prop) → `error` (has an
 * error-family prop). The single source of truth for "which states does this component have": the state
 * switcher offers exactly these, and {@link previewCycleStates} derives the auto-cycle from them. A plain
 * component with none of those props returns just `["loaded"]` (no state tabs, no cycling — "not all
 * components need them").
 */
export function supportedStates(comp: ComponentRecord): PreviewState[] {
  const has = (pred: (p: PropSpec) => boolean) => comp.props.some(pred);
  const states: PreviewState[] = [];
  if (has(isLoadingProp)) states.push("loading");
  states.push("loaded");
  if (has(isCollectionProp)) states.push("empty");
  if (has(isErrorProp)) states.push("error");
  return states;
}

/** The states the SMALL preview auto-cycles through (#3555): {@link supportedStates} minus `empty` (it
 *  often reads bare — it stays reachable in the expanded try-on + doctor). So a fully-stated component
 *  cycles loading → loaded → error. A component with only `loaded` yields `["loaded"]` → nothing to cycle. */
export function previewCycleStates(comp: ComponentRecord): PreviewState[] {
  return supportedStates(comp).filter((s) => s !== "empty");
}

/**
 * The bootstrap entry source: import the component by `importSpec` and mount it into `#root` with the
 * sample props. Uses `createElement` (not JSX children) so children/props compose without JSX parsing
 * quirks. Resolves the component export by `name`, falling back to the default export. Builds the props
 * from {@link previewPropList} / {@link previewChild} (the SAME source `bsc ui preview-props` inspects).
 */
/** The props object-literal (JS source) `comp` is mounted with in `state`: the sampled props (schema
 *  order), then any resolved preview-data OVERRIDES layered on top (#2940) — a bound prop renders the
 *  algorithm-generated dataset instead of its trivial sample, and a bound prop the sampler OMITTED (an
 *  optional collection) is added. `previewPropList` stays pure, so the Rust parity fixture is unaffected. */
function statePropsLiteral(comp: ComponentRecord, state: PreviewState, previewData: Record<string, string>): string {
  const byName = new Map(previewPropList(comp, state).map((e) => [e.name, e.value] as const));
  for (const [name, value] of Object.entries(previewData)) {
    if (name !== "children") byName.set(name, value);
  }
  return `{ ${[...byName].map(([name, value]) => `${JSON.stringify(name)}: ${value}`).join(", ")} }`;
}

export function bootstrapSource(
  comp: ComponentRecord,
  importSpec: string,
  state: PreviewState = "loaded",
  previewData: Record<string, string> = {},
  liveStates?: PreviewState[],
): string {
  const childText = previewChild(comp);
  const childArg = childText ? `, ${childText}` : "";
  // Role-aware mount wrapper (#3139). A PAGE/LAYOUT is authored for a full viewport (flex:1 / height:100%),
  // so it gets a full-bleed, TOP-LEFT wrapper (no centering, no padding) — its header sits at the top and
  // it fills the natural canvas the frame then scales to fit. A component keeps the centered, padded
  // wrapper so an intrinsic-size primitive reads well. (`height:100%`, not minHeight, so the srcdoc's
  // `max-height:100%` media cap (#2915) resolves.)
  const pageLike = comp.role === "page" || comp.role === "layout";
  const wrapStyle = pageLike
    ? `{ height: "100%", width: "100%", boxSizing: "border-box", overflow: "hidden" }`
    : `{ padding: 20, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center", height: "100%" }`;
  const head = [
    `import { createRoot } from "react-dom/client";`,
    `import { createElement } from "react";`,
    `import * as __mod from "${importSpec}";`,
    `const __C = __mod[${JSON.stringify(comp.name)}] ?? __mod.default;`,
    `if (!__C) throw new Error("preview: no export ${comp.name} (or default) in ${importSpec}");`,
  ];

  // #3567: LIVE-STATE form — embed EVERY state's props once and switch on a `{ __state }` message with a
  // React re-render, NOT a rebuild. The compiled bundle is identical across states (only props differ), so
  // the small preview's auto-cycle (#3555) becomes an instant re-render instead of an esbuild + reload +
  // "building" flash. `null`-guarded so an unknown/missing state falls back to the initial.
  if (liveStates && liveStates.length) {
    const initial = liveStates.includes(state) ? state : liveStates[0];
    const statesLiteral = liveStates
      .map((s) => `${JSON.stringify(s)}: ${statePropsLiteral(comp, s, previewData)}`)
      .join(", ");
    return [
      ...head,
      `const __STATES = { ${statesLiteral} };`,
      `let __state = ${JSON.stringify(initial)};`,
      `const __root = createRoot(document.getElementById("root"));`,
      `function __render(){ __root.render(createElement("div", { style: ${wrapStyle} }, createElement(__C, __STATES[__state] || {}${childArg}))); }`,
      `__render();`,
      `window.addEventListener("message", function (e) { var s = e && e.data && e.data.__state; if (typeof s === "string" && __STATES[s]) { __state = s; __render(); } });`,
      "",
    ].join("\n");
  }

  // Single-state form (the on-visit scan, one state per build — byte-unchanged from before #3567).
  return [
    ...head,
    `createRoot(document.getElementById("root")).render(`,
    `  createElement("div", { style: ${wrapStyle} },`,
    `    createElement(__C, ${statePropsLiteral(comp, state, previewData)}${childArg})));`,
    "",
  ].join("\n");
}

// ── Derived indexes (#4130) ─────────────────────────────────────────────────────────────────────────
//
// Buildability is asked once PER COMPONENT by `analyzeGraphHealth`, which used to answer it by calling
// `componentPreviewFiles` and testing `=== null` — building and discarding a whole preview bundle to read
// one boolean. Over the real 248-component kit that was 1297ms of the page's 1766ms mount, and ~870ms of
// it was re-deriving the SAME module-constant artifact 248 times: `@data/components/react-ui.json` is
// 741 runtime modules + 68 components, all re-seeded into a fresh object with a `stripExt` per key on
// every call.
//
// So the artifact- and sibling-derived state is computed ONCE per input identity and cached in a WeakMap
// (no lifetime management: the entry dies with the array/artifact it keys). `componentBuildable` then
// answers the boolean off those indexes without materializing a file map or walking the import closure.

/** The artifact-derived resolution state — depends ONLY on the artifact, which is a module constant. */
interface ArtifactIndex {
  /** `src` → the artifact component that HAS a source (the built-in lookup, replacing a linear scan). */
  bySrc: Map<string, KitArtifact["components"][number]>;
  /** Extension-stripped keys of the runtime closure + built-in sources — the internal-import target set. */
  bases: Set<string>;
}

const artifactIndexes = new WeakMap<KitArtifact, ArtifactIndex>();

/** {@link ArtifactIndex} for `artifact`, computed once per artifact object. */
function artifactIndex(artifact: KitArtifact): ArtifactIndex {
  const hit = artifactIndexes.get(artifact);
  if (hit) return hit;
  const bySrc = new Map<string, KitArtifact["components"][number]>();
  const bases = new Set<string>();
  for (const path of Object.keys(artifact.runtime ?? {})) bases.add(stripExt(path));
  for (const c of artifact.components) {
    if (!c.source) continue;
    // LAST wins, matching `Object.keys` order over the object the seeding loops build.
    bySrc.set(c.src, c);
    bases.add(stripExt(c.src));
  }
  const idx: ArtifactIndex = { bySrc, bases };
  artifactIndexes.set(artifact, idx);
  return idx;
}

/** The sibling-derived resolution state. Every entry records its OWNER ids, because a component's own
 *  contribution is scoped differently per lookup (`sibByBase` excludes it; the `provides` maps include
 *  it) — owners let a cached, whole-array index answer both without rebuilding per component. */
interface SiblingIndex {
  /** import base (`src` minus extension) → ids of siblings publishing it. */
  baseOwners: Map<string, string[]>;
  /** a `@/…` specifier a sibling `provides` → the ids providing it. */
  provideSpecOwners: Map<string, string[]>;
  /** `${base}.tsx` for a provided specifier → the ids providing it. */
  provideModOwners: Map<string, string[]>;
}

const siblingIndexes = new WeakMap<readonly ComponentRecord[], SiblingIndex>();

/** Record `id` as an owner of `key`. */
function addOwner(m: Map<string, string[]>, key: string, id: string): void {
  const hit = m.get(key);
  if (hit) hit.push(id);
  else m.set(key, [id]);
}

/** {@link SiblingIndex} for `siblings`, computed once per array identity. Callers pass the SAME array
 *  across a sweep (`analyzeGraphHealth` passes its `comps`), which is what makes the cache land. */
function siblingIndex(siblings: readonly ComponentRecord[]): SiblingIndex {
  const hit = siblingIndexes.get(siblings);
  if (hit) return hit;
  const idx: SiblingIndex = { baseOwners: new Map(), provideSpecOwners: new Map(), provideModOwners: new Map() };
  for (const s of siblings) {
    const impl = ownImplSource(s);
    const sp = s.src?.trim();
    if (impl && sp) addOwner(idx.baseOwners, stripExt(sp), s.id);
    const spec = s.provides?.trim();
    const base = spec ? resolveInternalBase(spec, "") : null;
    if (spec && impl && base !== null) {
      addOwner(idx.provideSpecOwners, spec, s.id);
      addOwner(idx.provideModOwners, `${base}.tsx`, s.id);
    }
  }
  return (siblingIndexes.set(siblings, idx), idx);
}

/** Does `key` have an owner OTHER than `exceptId`? — the "excluding the component itself" lookup. */
function ownedByOther(m: Map<string, string[]>, key: string, exceptId: string): boolean {
  const owners = m.get(key);
  return owners !== undefined && owners.some((id) => id !== exceptId);
}

/** Is any key owned by someone other than `exceptId`? — the `size > 0` test, self-exclusive. */
function anyOwnedByOther(m: Map<string, string[]>, exceptId: string): boolean {
  for (const owners of m.values()) if (owners.some((id) => id !== exceptId)) return true;
  return false;
}

/**
 * Would {@link componentPreviewFiles} produce a build for `comp` — WITHOUT producing one?
 *
 * Exactly `componentPreviewFiles(comp, artifact, siblings) !== null`, and pinned to that by a test over
 * the real library. It exists because callers that only need the verdict (graph health, `bsc ui doctor`'s
 * frontend twin, any "is this a spec or an implementation" check) were paying for a full bundle —
 * including the 5 MB artifact re-seed and the transitive sibling import walk — per component.
 *
 * `libResolver` is deliberately NOT a parameter: library vendoring happens AFTER the buildability
 * decision in `componentPreviewFiles`, so it cannot affect the verdict.
 */
export function componentBuildable(
  comp: ComponentRecord,
  artifact: KitArtifact,
  siblings: readonly ComponentRecord[] = [],
): boolean {
  const { bySrc, bases } = artifactIndex(artifact);
  // BUILT-IN: present in the artifact with a source ⇒ always a build (the branch below never returns null).
  if (comp.src && bySrc.has(comp.src)) return true;

  const explicitSource = comp.source && comp.source.trim() ? comp.source : null;
  const userSource = explicitSource ?? (comp.srcText && comp.srcText.trim() ? comp.srcText : null);
  if (userSource === null) return false;
  if (explicitSource !== null) return true; // an explicit `source` is trusted, imports unchecked

  const path = comp.src?.trim() ? comp.src : `user/${comp.id || "component"}.tsx`;
  const sib = siblingIndex(siblings);

  // The component's OWN `provides` contribution — the maps are built over `[comp, ...siblings]`, so it
  // participates alongside the cached sibling entries.
  const ownSpec = comp.provides?.trim();
  const ownImpl = ownImplSource(comp);
  const ownBase = ownSpec ? resolveInternalBase(ownSpec, "") : null;
  const ownProvides = ownSpec && ownImpl && ownBase !== null ? { spec: ownSpec, mod: `${ownBase}.tsx` } : null;

  const hasProvideSpec = (spec: string) =>
    (ownProvides?.spec === spec) || ownedByOther(sib.provideSpecOwners, spec, comp.id) || (sib.provideSpecOwners.get(spec)?.includes(comp.id) ?? false);
  const hasProvideMod = (key: string) =>
    (ownProvides?.mod === key) || (sib.provideModOwners.get(key)?.length ?? 0) > 0;
  const hasSibBase = (base: string) => ownedByOther(sib.baseOwners, base, comp.id);

  const resolvesInternal = (spec: string, fromRel: string): boolean => {
    if (hasProvideSpec(spec)) return true;
    const base = resolveInternalBase(spec, fromRel);
    return base !== null && (bases.has(base) || hasProvideMod(`${base}.tsx`) || hasSibBase(base));
  };

  const providesModNonEmpty = ownProvides !== null || sib.provideModOwners.size > 0;
  const canResolveInternal = providesModNonEmpty || anyOwnedByOther(sib.baseOwners, comp.id) || bases.size > 0;
  return canResolveInternal
    ? isPreviewBuildable(userSource, path, resolvesInternal)
    : looksBuildableModule(userSource);
}

/**
 * Assemble the buildable files + entry for `comp`'s preview, or `null` when there's no buildable source.
 *
 * BUILT-IN (its `src` is in `artifact` with a `source`): hand esbuild the artifact's whole component +
 * `runtime` set (keyed by `src/`-relative path) so `@/…` imports resolve; the entry imports the target
 * via its `@/…` spec. USER-AUTHORED (not in the artifact): its self-contained implementation source —
 * `comp.source` when present, ELSE a `comp.srcText` that {@link looksBuildableModule} — placed at
 * `comp.src` (or a synthetic path) and imported by the entry. A usage-snippet `srcText` yields `null`
 * (the honest empty state).
 *
 * `siblings` (#3112): the OTHER user components in `comp`'s kit. A user component may `import` a sibling
 * (`@/<sibling.src>` or a relative path) — the transitive closure of the siblings it actually imports is
 * VENDORED into the file set (keyed by each sibling's `src`), so a user-kit component can compose real
 * siblings instead of inlining everything. Buildability is then sibling-aware ({@link isPreviewBuildable}):
 * an internal import that resolves to a vendored sibling is allowed; one that resolves to nothing still
 * yields `null`. Omit `siblings` for the pre-#3112 single-module behavior (any `@/` import ⇒ not buildable).
 */
export function componentPreviewFiles(
  comp: ComponentRecord,
  artifact: KitArtifact,
  siblings: readonly ComponentRecord[] = [],
  libResolver?: LibraryModuleResolver,
  state: PreviewState = "loaded",
  previewData: Record<string, string> = {},
  liveStates?: PreviewState[],
): ComponentPreviewBuild | null {
  // #4130: the built-in lookup + the internal-resolution base set come from the cached artifact index,
  // so this and `componentBuildable` read the SAME derivation (and neither re-scans the artifact).
  const artIdx = artifactIndex(artifact);
  const inArtifact = comp.src ? artIdx.bySrc.get(comp.src) : undefined;

  if (inArtifact) {
    const files: Record<string, string> = {};
    for (const [path, src] of Object.entries(artifact.runtime ?? {})) files[path] = src;
    for (const c of artifact.components) if (c.source) files[c.src] = c.source;
    vendorLibraryModules(files, libResolver); // #3116: any `@bsc/…` a built-in references
    const importSpec = `@/${stripExt(inArtifact.src)}`;
    files[PREVIEW_ENTRY] = bootstrapSource(comp, importSpec, state, previewData, liveStates);
    return { files, entry: PREVIEW_ENTRY };
  }

  // User-authored: build from its own implementation source — the explicit `source` when present, else
  // the `srcText`. An explicit `source` is trusted; a `srcText` must look like a real module (#2828).
  const explicitSource = comp.source && comp.source.trim() ? comp.source : null;
  const userSource = explicitSource ?? (comp.srcText && comp.srcText.trim() ? comp.srcText : null);
  if (userSource === null) return null;
  const path = comp.src?.trim() ? comp.src : `user/${comp.id || "component"}.tsx`;

  // #43/#3660: resolve `@/…` imports the way the RUNTIME loader does, so a graph-source primitive (a
  // `provides` component migrated from the app, #3604) BUILDS instead of falsely reporting no-implementation.
  // Three resolution tiers, keyed by the import SPECIFIER (which also sidesteps the `src/`-prefix mismatch a
  // sibling's `src` path carries):
  //   (b) the packaged artifact's built-in sources + runtime closure — the app's real modules, seeded first;
  //   (a) a graph component whose `provides` EQUALS the specifier — its source, seeded AFTER (graph-first
  //       wins, #3660), keyed at the specifier's mem path so `@/X` resolves to it;
  //   (c) a sibling user component by `src` base (the pre-#3112 path).
  const files: Record<string, string> = {};
  for (const [p, src] of Object.entries(artifact.runtime ?? {})) files[p] = src; // (b) runtime closure
  for (const c of artifact.components) if (c.source) files[c.src] = c.source;     // (b) built-in sources
  const artifactBases = artIdx.bases; // #4130: cached — identical to stripExt over the seeded keys

  // (a) `provides` — a `@/X` specifier → a graph-source component's module, keyed at the mem path for `X`.
  const providesMod = new Map<string, string>(); // `${base}.tsx` → source
  const providesSpecs = new Set<string>();        // the `@/…` specifiers the graph provides
  for (const s of [comp, ...siblings]) {
    const spec = s.provides?.trim();
    const impl = ownImplSource(s);
    const base = spec ? resolveInternalBase(spec, "") : null;
    if (!spec || !impl || base === null) continue;
    providesSpecs.add(spec);
    providesMod.set(`${base}.tsx`, impl);
  }

  // (c) sibling user components keyed by their import BASE (`src` minus extension).
  const sibByBase = new Map<string, { src: string; source: string }>();
  for (const s of siblings) {
    if (s.id === comp.id) continue;
    const source = ownImplSource(s);
    const sp = s.src?.trim();
    if (source && sp) sibByBase.set(stripExt(sp), { src: sp, source });
  }

  const resolvesInternal = (spec: string, fromRel: string): boolean => {
    if (providesSpecs.has(spec)) return true; // (a) exact `provides` match
    const base = resolveInternalBase(spec, fromRel);
    return base !== null && (artifactBases.has(base) || providesMod.has(`${base}.tsx`) || sibByBase.has(base)); // (b)/(a)/(c)
  };

  // Buildable? An explicit `source` is trusted; a `srcText` must be a module whose internal imports all
  // resolve (provides / artifact / sibling). `looksBuildableModule` (no `@/` at all) is the fallback when
  // there is nothing to resolve against.
  const canResolveInternal = providesMod.size > 0 || sibByBase.size > 0 || artifactBases.size > 0;
  const buildable = explicitSource !== null
    || (canResolveInternal ? isPreviewBuildable(userSource, path, resolvesInternal) : looksBuildableModule(userSource));
  if (!buildable) return null;

  // Seed the graph-first `provides` overrides (they win over the artifact built-in of the same path), the
  // target's own source, then the transitive closure of SIBLING imports (artifact + provides modules are
  // already seeded; esbuild tree-shakes the unreached).
  for (const [key, src] of providesMod) files[key] = src;
  files[path] = userSource;
  const seenBase = new Set<string>([stripExt(path)]);
  const queue: Array<{ source: string; fromRel: string }> = [{ source: userSource, fromRel: path }];
  while (queue.length) {
    const { source, fromRel } = queue.shift()!;
    for (const spec of importSpecs(source)) {
      const base = resolveInternalBase(spec, fromRel);
      if (base === null || seenBase.has(base)) continue;
      const mod = sibByBase.get(base);
      if (!mod) continue;
      seenBase.add(base);
      files[mod.src] = mod.source;
      queue.push({ source: mod.source, fromRel: mod.src });
    }
  }
  vendorLibraryModules(files, libResolver); // #3116: vendor any `@bsc/…` library imports (recursively)
  files[PREVIEW_ENTRY] = bootstrapSource(comp, `@/${stripExt(path)}`, state, previewData, liveStates);
  return { files, entry: PREVIEW_ENTRY };
}

/**
 * Vendor every `@bsc/<segment>/<name>` LIBRARY import reachable from the current `files` (#3116) — resolve
 * each via `libResolver` and add its module `source` at the `path` the import resolves to, recursing into a
 * vendored module's own library imports (an algorithm that `import`s another). Mutates `files` in place.
 * A no-op when `libResolver` is absent or nothing imports `@bsc/…` — so a component with no library imports
 * yields a byte-identical file set to pre-#3116. A spec that doesn't resolve is simply not added (the build
 * then fails "module not found" — the honest unresolvable-import surface, mirrored in graphHealth).
 */
function vendorLibraryModules(files: Record<string, string>, libResolver?: LibraryModuleResolver): void {
  if (!libResolver) return;
  const seenSpec = new Set<string>();
  const queue: string[] = Object.values(files);
  while (queue.length) {
    const source = queue.shift()!;
    for (const spec of importSpecs(source)) {
      if (!isLibrarySpec(spec) || seenSpec.has(spec)) continue;
      seenSpec.add(spec);
      const mod = libResolver(spec);
      if (!mod || mod.path in files) continue;
      files[mod.path] = mod.source;
      queue.push(mod.source);
    }
  }
}

