// Kit lint rules → eslint preset (#2279) — the auto-firing enforcement a kit ships so an agent building
// an app on it can't quietly re-invent a component. This is the pure spine: the rule model lives in
// model.ts; here are the derivation (from each component's `wraps` hint), the author-declared merge, and
// the emitter that turns a kit's rules into plain eslint config (NO custom plugin — the dogfooded 80%).
//
// Config-level ONLY for now: `forbid-element` → `no-restricted-syntax` (the exact pattern this repo uses
// to force `<Box>`/`<Button>` over raw elements), `forbid-import` → `no-restricted-imports`. The
// generated app extends the emitted preset; every rule message carries the escape hatch so it teaches
// but allows a justified exception. Custom AST plugins, token rules, and non-eslint linters are follow-ups.
import type { ComponentRecord, KitRule } from "./model";

/** The escape-hatch clause every rule message ends with — enforce, but allow a justified exception. */
export const ESCAPE_HATCH = "If truly required, add `// eslint-disable-next-line <rule> -- <reason>`.";

/** The human message for a rule (its own `message`, else a default that names `use` + the escape hatch). */
export function ruleMessage(r: KitRule): string {
  if (r.message) return r.message;
  const base =
    r.kind === "forbid-element"
      ? `Use the kit's <${r.use}> instead of a raw <${r.target}>.`
      : `Import ${r.use} from the kit instead of "${r.target}".`;
  return `${base} ${ESCAPE_HATCH}`;
}

/** Derive the flagship anti-duplication rules from the kit: one `forbid-element` per component that
 *  declares what raw intrinsic it `wraps` ("use <Button> not a raw <button>"). */
export function deriveRules(components: ComponentRecord[]): KitRule[] {
  return components
    .filter((c) => c.wraps)
    .map((c) => ({
      id: `derived:forbid-element:${c.wraps}`,
      kind: "forbid-element" as const,
      target: c.wraps!,
      use: c.name,
      componentId: c.id,
      derived: true,
    }));
}

/** The dedup key for a rule — a kit shouldn't forbid the same target twice. */
const ruleKey = (r: KitRule) => `${r.kind}:${r.target}`;

/** Merge derived + author-declared rules: an authored rule OVERRIDES a derived one for the same
 *  (kind, target), and adds any new ones. Authored wins so a kit can refine a derived message/target. */
export function mergeRules(derived: KitRule[], authored: KitRule[]): KitRule[] {
  const byKey = new Map(derived.map((r) => [ruleKey(r), r]));
  for (const a of authored) byKey.set(ruleKey(a), { ...a, derived: false });
  return [...byKey.values()];
}

/** The full ruleset for a kit's components: the derived anti-duplication rules merged with every
 *  component's author-declared `rules`. */
export function kitRules(components: ComponentRecord[]): KitRule[] {
  const authored = components.flatMap((c) => c.rules ?? []);
  return mergeRules(deriveRules(components), authored);
}

/** The rules a SINGLE component contributes/enforces — its derived `wraps` rule (if any) merged with
 *  its author-declared `rules`. Drives the pane's per-component Rules tab. */
export function componentRules(component: ComponentRecord): KitRule[] {
  return mergeRules(deriveRules([component]), component.rules ?? []);
}

/** The eslint `rules` fragment a kit's ruleset compiles to (only the rules that have entries appear). */
export interface EslintRulesConfig {
  "no-restricted-syntax"?: unknown[];
  "no-restricted-imports"?: unknown[];
}

/** Compile a ruleset into a plain eslint `rules` object — `forbid-element` rules fold into one
 *  `no-restricted-syntax` array (each a JSX-element selector + message); `forbid-import` rules into one
 *  `no-restricted-imports` `paths` list. */
export function toEslintRules(rules: KitRule[]): EslintRulesConfig {
  const syntax = rules
    .filter((r) => r.kind === "forbid-element")
    .map((r) => ({ selector: `JSXOpeningElement[name.name='${r.target}']`, message: ruleMessage(r) }));
  const imports = rules
    .filter((r) => r.kind === "forbid-import")
    .map((r) => ({ name: r.target, message: ruleMessage(r) }));

  const out: EslintRulesConfig = {};
  if (syntax.length) out["no-restricted-syntax"] = ["error", ...syntax];
  if (imports.length) out["no-restricted-imports"] = ["error", { paths: imports }];
  return out;
}

/** The eslint preset a kit ships — a flat-config fragment the generated app extends
 *  (`{ rules: { … } }`). Empty `rules` when the kit declares/derives nothing. */
export function toEslintPreset(components: ComponentRecord[]): { rules: EslintRulesConfig } {
  return { rules: toEslintRules(kitRules(components)) };
}

runtime.features/designs/lib/seed.ts:
// The packaged Component Library seed (#2269) — reset to a CLEAN SLATE (#3543): a single EMPTY kit,
// `base-studio-code`. The designer session fills it (components + all algorithm animations + everything
// needed to create/run the app) via `bsc ui`, and the studio command exports it. This is the concrete
// first move toward "the app's own entire UI as one graph" (endpoint of #3451).
//
// What this replaced: six separately-seeded kits — `react-ui` (generated primitives, gated off #3029),
// `fleet` (#3462), `base` motion (#3451), and the three viz kits (#3194/#3242). Their per-kit assemblers
// were deleted with this change. IMPORTANT: the algorithm-viz MOTION still lives in the shared
// `*_VIZ_ANIMATIONS` consts under `shared/ui/kit/` — the Algorithms graph renderers compile from those
// DIRECTLY, independent of the design kits, so wiping the design library does NOT touch the Algorithms
// feature. The `react-ui.json` artifact is likewise untouched (still consumed by the released-kit store,
// the preview raw-import, and the manifest drift guard).
//
// The wipe: on the next launch `hydrateComponents` reconciles the store toward this seed. Every prior
// PRISTINE packaged kit LEFT the seed, so the #2483 refresh DROPS it (from `app-state.json` and the
// on-disk `bsc` store); the empty `base-studio-code` kit is seeded in its place. (A hand-edited builtin
// is kept with an `orphaned` notice — the designer can delete it, or a hard reset can force-clear.)
import type { ComponentRecord, Kit } from "./model";
import { projectComponent } from "./componentBridge";
import { reconcileSeed, stampSeedHash, type SeedReconcile } from "./seedRefresh";

/** The one packaged kit id — the base-studio-code app's own UI as a single graph (#3543). */
export const BASE_STUDIO_CODE_KIT_ID = "base-studio-code";

/** The single packaged kit — the app's own UI as one graph. `tech: "react"` is load-bearing: packaged
 *  themes bind to the design group by `tech` (never kit id), so keeping it "react" preserves every theme.
 *  `style` is the Components-rail GROUP label; it is deliberately the kit's own name (NOT "studio", which
 *  would collide with the "Studio" app-library snapshot concept — bsc-studio — and confuse users, #3640). */
const baseStudioCodeKit: Kit = stampSeedHash({
  id: BASE_STUDIO_CODE_KIT_ID,
  name: "base-studio-code",
  tech: "react",
  style: "base-studio-code",
  stack: "base-studio-code",
  dot: "var(--accent)",
  animations: [],
  builtin: true,
});

/** The packaged built-in kits — one empty `base-studio-code` kit (#3543). Enumerated by the stamping +
 *  round-trip drift guards. */
export const SEED_KITS: Kit[] = [baseStudioCodeKit];

// The migrated app-page components — the app's own UI authored as graph source under
// `src-tauri/data/components/app/**` (#3604, moving the code UI into the one `base-studio-code` graph).
// Vite-glob-imported (eager) so a newly-migrated page is PACKAGED simply by dropping its `.json` there,
// no seed edit. Each row runs through the SAME `projectComponent` load projection + is stamped
// `builtin`/`seedHash`, so `seed === load(push(seed))` (the #2514 round-trip) holds BY CONSTRUCTION and
// the #2483 reconcile seeds it on first run + tracks it release-to-release.
const migratedApp = import.meta.glob<Partial<ComponentRecord>>("@data/components/app/**/*.json", {
  eager: true,
  import: "default",
});

/** The packaged built-in components — the migrated app pages (#3604); the `base-studio-code` kit fills as
 *  the code UI moves into the graph. Empty until the first page migrated (fleetpage, #3606). */
export const SEED_COMPONENTS: ComponentRecord[] = Object.keys(migratedApp)
  .sort() // deterministic order — glob key order is filesystem-dependent
  .map((path) => stampSeedHash({ ...projectComponent(migratedApp[path]), builtin: true }));

/**
 * Reconcile the store's loaded components with the packaged built-ins (#2483, hash-based refresh — the
 * full verdict table lives on {@link reconcileSeed}): a PRISTINE built-in copy (its content still hashes
 * to its stamped `seedHash`; a legacy no-hash copy counts as pristine) tracks the seed — refreshed when
 * the seed changed, deleted when the built-in left the seed. A USER-EDITED built-in is always kept (store
 * wins), with a notice when the seed diverged. User-authored records are never touched; built-ins the
 * store lacks are re-added. `hydrateComponents` applies the pushes/drops so the store converges.
 *
 * With the seed now empty (#3543), this DROPS every prior pristine packaged component on the next boot.
 */
export function reconcileComponents(loaded: ComponentRecord[]): SeedReconcile<ComponentRecord> {
  // Page records (#3723) are import-based SPECS the app renders through the registry at runtime — not
  // designer-editable content. So the seed is AUTHORITATIVE for them: a diverged store copy (a designer
  // self-contained a page so it would render in the preview sandbox) is forced back to the seed instead
  // of kept — which is what silently shadowed Settings (#3658), then the whole app (#3723).
  return reconcileSeed(loaded, SEED_COMPONENTS, "component", { seedAuthoritative: (r) => r.role === "page" });
}

/** Reconcile loaded kits with the packaged built-in kits (see {@link reconcileComponents}). Drops every
 *  prior pristine packaged kit and seeds the one empty `base-studio-code` kit (#3543). */
export function reconcileKits(loaded: Kit[]): SeedReconcile<Kit> {
  return reconcileSeed(loaded, SEED_KITS, "kit");
}

runtime.features/designs/lib/seedRefresh.ts:
// Hash-based built-in seed refresh (#2483) — the pure decision spine that replaced the frozen
// seed-and-keep reconcile. The store wins ONLY for records the user actually edited; a pristine
// built-in copy tracks the packaged seed release-to-release (the react-ui kit is GENERATED from the
// app's own source, so every release drifts the seed).
//
// The mechanism: every packaged built-in carries a `seedHash` — a small content hash of its
// seed-relevant fields, stamped at seed-assembly time (`makeBuiltinKits`). A store copy whose
// current content still hashes to its recorded `seedHash` is UNMODIFIED (safe to refresh/delete);
// one that no longer does was edited by the user (kept, with an "updated upstream" notice when the
// seed moved too).
//
// Hash exclusions (the "volatile" set, `SEED_HASH_EXCLUDED`):
//   - `seedHash`  — the stamp itself can never feed its own hash.
//   - `builtin`   — provenance, not content (stamped on assembly AND carried by the bridge).
//   - `used`      — the runtime reuse counter; it drifts without a user edit.
//   - `rev` / `updatedAt` / `updatedBy` / `history` (#3606) — SERVER-MANAGED provenance the Rust stamp
//     boundary writes on every `bsc ui set` (a component write-through stamps them). `componentBridge`
//     projects them for the inspector's History tab, so they ride into the loaded record — but they are
//     NOT seed content, so hashing them would make a pristine SEEDED component (pushed → stamped → loaded
//     with a fresh `rev`) mis-hash as user-modified forever. Kits/themes never projected them, so this is
//     the component-seed case the empty `SEED_COMPONENTS` had never exercised.
// Everything else on the record IS seed content — a change to any other field is a user edit (store
// copy) or a new release (seed copy).
//
// THE ROUND-TRIP CONTRACT (#2514). A stamp is only meaningful if the record's seed-relevant content
// survives the push→store→load round-trip byte-for-byte: `bsc ui … set` persists the JSON verbatim
// (key order aside), `… list --full` returns it verbatim, and the bridge projections
// (componentBridge/themeBridge `loadX`) must carry every seed-relevant field WITHOUT normalizing it —
// an absent optional field must stay absent (never defaulted to `""`/`[]`), or the reloaded copy
// hashes differently from its stamp and the reconcile mis-judges a pristine record as user-modified
// forever. This invariant is EXECUTED, not assumed: `seedRoundTrip.test.ts` pushes every packaged
// seed record through the real bridge mapping over a faithful store emulation and asserts the
// reloaded content still hashes to its stamp.
//
// Defense in depth for a stamp that rots anyway (an older hasher, a byte-mangling round-trip in some
// past build): a mismatched `builtin` copy gets a second chance against the CURRENT seed — content
// identical to the seed ⇒ the stamp itself was wrong, re-judged pristine and re-stamped (see the
// verdict table on `reconcileSeed`). Silent keep-forever is impossible: every KEEP of a diverged
// copy surfaces a notice.
//
// Deliberately GENERIC over `{ id, name, builtin?, seedHash? }` (components AND kits today) so the
// same helper can be extracted for the other seed-and-keep stores (personas, orgs, blueprints) later
// — it has no component-specific knowledge beyond the volatile-field list above.

/** The minimum shape the reconcile needs; components, kits, and themes (#2488) all satisfy it. */
export interface SeedRecord {
  id: string;
  /** Display name for the notices — components/kits carry `name`; themes carry `label` instead. */
  name?: string;
  /** Theme display name (#2488) — the notices fall back name → label → id. */
  label?: string;
  /** A packaged built-in. Absent/false ⇒ user-authored (never touched by the reconcile). */
  builtin?: boolean;
  /** A SUPPRESSION tombstone (#3725) — `true` marks this id as a PERMANENTLY removed packaged builtin.
   *  The reconcile skips it (not a record to render) and its presence blocks the seed from re-adding it. */
  suppressed?: boolean;
  /** The content hash stamped when this copy was seeded (#2483). Absent ⇒ a legacy pre-#2483 copy. */
  seedHash?: string;
}

/** The display name a notice carries: `name` (components/kits) → `label` (themes) → the id. */
function displayName(rec: SeedRecord): string {
  return rec.name ?? rec.label ?? rec.id;
}

/** Fields excluded from the seed hash — see the module doc for why each. */
export const SEED_HASH_EXCLUDED = ["seedHash", "builtin", "used", "rev", "updatedAt", "updatedBy", "history"] as const;

/** Deterministic JSON: keys sorted recursively, `undefined` properties dropped (so an absent
 *  optional field and an explicitly-undefined one hash identically). */
export function stableStringify(v: unknown): string {
  if (v === null || typeof v !== "object") return JSON.stringify(v) ?? "null";
  if (Array.isArray(v)) return `[${v.map((x) => (x === undefined ? "null" : stableStringify(x))).join(",")}]`;
  const o = v as Record<string, unknown>;
  const keys = Object.keys(o).filter((k) => o[k] !== undefined).sort();
  return `{${keys.map((k) => `${JSON.stringify(k)}:${stableStringify(o[k])}`).join(",")}}`;
}

/** FNV-1a 32-bit over the text, as 8 hex digits. Not cryptographic — a drift detector, not a
 *  security boundary (the store is the user's own local files). */
export function fnv1a(text: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, "0");
}

/** The seed hash of a record's CURRENT content (volatile fields excluded). */
export function seedHashOf(record: SeedRecord): string {
  const rest: Record<string, unknown> = { ...record };
  for (const k of SEED_HASH_EXCLUDED) delete rest[k];
  return fnv1a(stableStringify(rest));
}

/** Stamp a record with its own content hash — what `makeBuiltinKits` applies to every packaged
 *  built-in at seed-assembly time (the packaged JSON files do NOT bake the field in). */
export function stampSeedHash<T extends SeedRecord>(record: T): T {
  return { ...record, seedHash: seedHashOf(record) };
}

/** What a notice is about. */
export type SeedNoticeType = "component" | "kit" | "theme";

/** A reconcile outcome the user should see (the propagation-surface record, #2483). */
export interface SeedNotice {
  /** `updated-upstream`: the packaged built-in changed but the user's customized copy was kept.
   *  `orphaned`: the built-in left the seed but the user's customized copy was kept.
   *  `reset-to-seed`: a SEED-AUTHORITATIVE record (an import-based page spec, #3723) had a diverged
   *  store copy FORCED back to the packaged seed. The store never wins for these, so a divergence is a
   *  bug (a designer self-contained it for the preview sandbox), not a user edit — surfaced, not silent. */
  kind: "updated-upstream" | "orphaned" | "reset-to-seed";
  type: SeedNoticeType;
  id: string;
  name: string;
}

/** The reconcile verdicts: the final collection + the write-through work to converge the store. */
export interface SeedReconcile<T extends SeedRecord> {
  /** The reconciled collection (loaded order, refreshed in place; missing seeds appended). */
  records: T[];
  /** Records to write through (`bsc ui set` / `kit set`): refreshed + newly-added built-ins. */
  pushes: T[];
  /** Ids to remove from the store (`bsc ui remove` / `kit remove`): deleted built-ins. */
  drops: string[];
  /** The "kept but diverged" outcomes to surface. */
  notices: SeedNotice[];
}

/**
 * Reconcile the store's loaded records with the packaged seed (#2483). Verdict table — for a loaded
 * record with `builtin: true` ("modified" = its content no longer hashes to its recorded `seedHash`;
 * a record with NO `seedHash` is a legacy pre-#2483 copy, grandfathered as UNMODIFIED — all three
 * real rot incidents were pristine copies, so this heals every existing install once):
 *
 * | in seed? | modified? | seed moved (`seed.seedHash !== record.seedHash`)? | verdict |
 * |---|---|---|---|
 * | yes | no  | yes (incl. legacy no-hash) | REFRESH — take the new seed copy, push it |
 * | yes | no  | no                         | keep the store copy (already current) |
 * | yes | yes | yes (incl. legacy… n/a)    | KEEP + `updated-upstream` notice |
 * | yes | yes | no                         | keep (customized, seed unchanged) |
 * | no  | no  |                            | DELETE (drop from store) |
 * | no  | yes |                            | KEEP + `orphaned` notice |
 *
 * Tolerant re-stamp (#2514): before the "modified" KEEP fires for an in-seed record, its content is
 * compared against the CURRENT seed copy's content hash. Identical content ⇒ only the recorded stamp
 * is wrong (an older hasher / a byte-mangling round-trip in a past build stamped it) — the record is
 * re-judged PRISTINE and refreshed to the seed copy (same content, corrected stamp), no notice. A
 * retired record with a wrong stamp has no seed copy to compare against, so it stays on the
 * conservative KEEP + `orphaned` branch — kept, but never silently (the notice is the surface).
 *
 * Non-builtin (user-authored) loaded records pass through untouched, always. Seed records the store
 * lacks are appended + pushed (the original seed-and-keep add).
 *
 * @param loaded the store's records (from the bridge).
 * @param seed   the packaged built-ins, seedHash-stamped (`makeBuiltinKits`).
 * @param type   what the records are (for the notices).
 * @param opts   `seedAuthoritative` (#3723) — records for which the SEED wins unconditionally (an
 *               import-based page spec): a diverged store copy is a bug, not a user edit, so it is
 *               FORCED back to the seed with a `reset-to-seed` notice instead of the customized-KEEP the
 *               verdict table above would apply. Records it doesn't match keep the normal verdicts.
 */
export function reconcileSeed<T extends SeedRecord>(
  loaded: T[],
  seed: T[],
  type: SeedNoticeType,
  opts?: { seedAuthoritative?: (rec: T) => boolean },
): SeedReconcile<T> {
  const seedById = new Map(seed.map((s) => [s.id, s]));
  const records: T[] = [];
  const pushes: T[] = [];
  const drops: string[] = [];
  const notices: SeedNotice[] = [];

  for (const rec of loaded) {
    // #3725: a SUPPRESSION tombstone — a marker that a packaged builtin of this id is permanently removed.
    // It is not a record to render (skip it from `records`), and its presence in `loaded` (hence `have`
    // below) makes the re-seed step SKIP that id, so the builtin never comes back. It stays in the store
    // (never dropped) so the block persists; `unsuppress` (remove it) lets the next hydrate re-seed.
    if (rec.suppressed) continue;
    if (!rec.builtin) {
      records.push(rec); // user-authored — never touched
      continue;
    }
    const seeded = seedById.get(rec.id);
    // Legacy pre-#2483 copies (no seedHash) are grandfathered as unmodified.
    const contentHash = rec.seedHash === undefined ? undefined : seedHashOf(rec);
    let modified = contentHash !== undefined && contentHash !== rec.seedHash;
    if (seeded) {
      const seedContentHash = seeded.seedHash ?? seedHashOf(seeded);
      // Seed-authoritative records (#3723): the store NEVER wins. A store copy whose CONTENT differs
      // from the seed is a divergence bug — e.g. a designer self-contained an import-based page spec so
      // it would render in the preview sandbox, which then silently shadowed the real page (#3658 →
      // #3723) — not a user edit. Force the seed copy back (push it), surfaced via a `reset-to-seed`
      // notice so the override is never silent. A copy already matching the seed is left untouched.
      if (opts?.seedAuthoritative?.(rec)) {
        if (seedHashOf(rec) !== seedContentHash) {
          records.push(seeded);
          pushes.push(seeded);
          notices.push({ kind: "reset-to-seed", type, id: rec.id, name: displayName(rec) });
        } else {
          records.push(rec); // already matches the seed
        }
        continue;
      }
      // Tolerant re-stamp (#2514): content identical to the CURRENT seed ⇒ the recorded stamp is the
      // broken part, not the content — re-judge pristine (the refresh below adopts the seed copy,
      // which is the same content with the corrected stamp).
      if (modified && contentHash === seedContentHash) modified = false;
      const seedMoved = seedContentHash !== rec.seedHash;
      if (!modified && seedMoved) {
        records.push(seeded); // pristine + stale → refresh to the new seed copy
        pushes.push(seeded);
      } else {
        records.push(rec); // current, or customized (store wins)
        if (modified && seedMoved) notices.push({ kind: "updated-upstream", type, id: rec.id, name: displayName(rec) });
      }
    } else if (modified) {
      records.push(rec); // customized copy of a retired built-in — keep, but say so
      notices.push({ kind: "orphaned", type, id: rec.id, name: displayName(rec) });
    } else {
      drops.push(rec.id); // pristine copy of a retired built-in → delete
    }
  }

  // Built-ins the store lacks entirely (first run / newly packaged) — append + push.
  const have = new Set(loaded.map((r) => r.id));
  for (const s of seed) {
    if (have.has(s.id)) continue;
    records.push(s);
    pushes.push(s);
  }

  return { records, pushes, drops, notices };
}

runtime.features/designs/lib/shapePreview.ts:
// shapePreview (#3439 / #3790) — the SHAPE tier of component preview data. A component that declares a
// `DataShape` (e.g. `shapes: ["list"]`) is fed REAL algorithm-generated data with NO per-component
// `PREVIEW_BINDINGS` row. It sits BETWEEN the curated binding and `samplePropValue`:
//
//     curated binding  →  shape-mock (here)  →  samplePropValue
//
// Supported are the shapes whose data can be both PRODUCED (a `datasetForStructure`) and LANDED on a real
// data prop: `list` (an array prop, filled with generic objects that render across the feed / collection
// components), `graph` (NetworkPage's `nodes`[+`edges`] arrays), and `tree` (#3790 — the Tree /
// TreeExplorerPage `nodes` nested forest, from a BST). Layout composites with no data-array prop
// (GraphCanvas `world:object`, MasterDetail render-props) find no target and fall through to
// `samplePropValue`, as #3439's acceptance requires; `linked-list`/`key-value` have no tracer and also fall
// through. Pure + synchronous (the programs run on the main thread) and strictly FAIL-SOFT: any gap returns
// `{}` so the component's own sample shows and a preview is never broken.
import type { VizDataset, PreviewStructure } from "@/features/algorithms";
import { isCollectionProp } from "./componentPreview";
import type { ComponentRecord, DataShape, PropSpec } from "./model";

/** Fetches a real dataset for a structure. INJECTED (not imported) so this module holds no runtime
 *  dependency on the `@/features/algorithms` barrel — importing the barrel value here pulls its
 *  crossGraphAdapter ↔ designs libraryComposition module-init cycle into every unit test. `usePreviewData`
 *  passes the real `datasetForStructure`; tests pass the real one via the deep (barrel-free) path or a stub. */
export type DatasetForStructure = (structure: PreviewStructure) => VizDataset | undefined;

/** Shape → how to source its dataset + how to land it on the component's props. */
interface ShapeTierEntry {
  structure: PreviewStructure;
  /** Map the dataset onto the component's props → `{ propName: value }`, or `null` when the component
   *  has no prop this shape can land on (then the shape falls through). */
  fill: (ds: VizDataset, props: PropSpec[]) => Record<string, unknown> | null;
}

/** Prop names that conventionally hold the primary data collection — preferred over any other array prop
 *  so a component with an incidental array prop (e.g. `columns`) still gets its DATA prop filled. */
const DATA_PROP_NAMES = ["items", "rows", "data", "entries", "records", "list"];

/** The first array-typed prop, preferring the conventional data-prop names. */
function firstArrayProp(props: PropSpec[]): PropSpec | undefined {
  const arrays = props.filter(isCollectionProp);
  return arrays.find((p) => DATA_PROP_NAMES.includes(p.name.toLowerCase())) ?? arrays[0];
}

function arrayProp(props: PropSpec[], name: string): PropSpec | undefined {
  return props.find((p) => p.name.toLowerCase() === name && isCollectionProp(p));
}

export const SHAPE_TIER: Partial<Record<DataShape, ShapeTierEntry>> = {
  list: {
    structure: "array",
    fill: (ds, props) => {
      if (ds.kind !== "array") return null;
      const prop = firstArrayProp(props);
      if (!prop) return null; // render-prop layout (MasterDetail, CardListRow) → fall through
      // Generic, render-SAFE objects: the UNION of the fields the real list components read, so each
      // renders fully and none crashes — CollectionItem { id, title } AND ActivityItem { login, action,
      // target, repo, createdAt } (its Avatar needs a `login`). The algorithm's value rides along as
      // `value`. Fixed strings keep it deterministic (no `new Date()` → no per-render flicker).
      const items = ds.data.map((value, i) => ({
        id: `n${i}`,
        title: `Item ${i + 1}`,
        label: `Item ${i + 1}`,
        login: `user${(i % 8) + 1}`,
        action: "updated",
        target: `item ${i + 1}`,
        repo: "demo/app",
        createdAt: "2026-01-01T00:00:00.000Z",
        value,
      }));
      return { [prop.name]: items };
    },
  },
  graph: {
    structure: "graph",
    fill: (ds, props) => {
      if (ds.kind !== "graph") return null;
      const nodesProp = arrayProp(props, "nodes");
      if (!nodesProp) return null; // GraphCanvas (world:object, children) has no nodes array → fall through
      const out: Record<string, unknown> = {
        // NetworkNodeData { id, label } — label defaults to the id so it always renders.
        [nodesProp.name]: ds.nodes.map((n) => ({ id: n.id, label: n.label ?? n.id })),
      };
      const edgesProp = arrayProp(props, "edges");
      // NetworkEdgeData { from, to }.
      if (edgesProp) out[edgesProp.name] = ds.edges.map((e) => ({ from: e.from, to: e.to }));
      return out;
    },
  },
  tree: {
    structure: "tree",
    fill: (ds, props) => {
      if (ds.kind !== "tree") return null;
      const nodesProp = arrayProp(props, "nodes");
      if (!nodesProp) return null; // a tree layout with no nodes array → fall through
      // ds.roots are already the nested `{ id, label, children }` forest the Tree/TreeExplorerPage nodes prop wants.
      return { [nodesProp.name]: ds.roots };
    },
  },
};

/** The shape-tier preview-data override for `comp` (`{ prop: JS-source literal }`), or `{}` when it
 *  declares no supported shape, its shape can't land on a real prop, or the dataset is unavailable.
 *  `getDataset` sources the real per-structure dataset (see {@link DatasetForStructure}). */
export function shapePreviewData(comp: ComponentRecord, getDataset: DatasetForStructure): Record<string, string> {
  for (const shape of comp.shapes ?? []) {
    const entry = SHAPE_TIER[shape];
    if (!entry) continue;
    const ds = getDataset(entry.structure);
    if (!ds) continue;
    const filled = entry.fill(ds, comp.props);
    if (filled && Object.keys(filled).length > 0) {
      return Object.fromEntries(Object.entries(filled).map(([k, v]) => [k, JSON.stringify(v)]));
    }
  }
  return {};
}

runtime.features/designs/lib/soundKitSelection.t:
// Sound-kit RESOLUTION for the Design Studio (#3412, epic #3071) — the step that turns a blueprint's
// `soundKit` PIN (config, #3372) into the kit a `@bsc/sounds/<id>` import actually resolves against.
//
// #3372 shipped the pin and its store resolution; until now `libraryModules.ts` still resolved every sound
// reference against the first packaged built-in, so a component referencing `@bsc/sounds/click` played the
// STARTER kit's click even when its project pinned a different kit. The picker said the pin took effect and
// it silently did not — a correctness gap whose failure mode is INAUDIBLE, which is why the policy below
// never degrades quietly.
//
// The read side of the pin: the artifact already lives in the global versioned release store (written by
// `resolveSoundKitPin` on blueprint open/import, #3372), so this only READS it —
// `bsc sound release get <id@version> --artifact` — and never fetches, verifies, or writes. A pin whose
// artifact is missing is therefore a genuine, reportable breakage (the resolve step failed or the store was
// tampered with), not a cache miss to paper over.
//
// Pure of React; store access goes through the generic `bsc` bridge (#2114), the same surface a live
// session reaches with `bsc sound release …` from its own shell.
import { bsc } from "@/shared/lib/core/bsc";
import { validateKit, type SoundKit } from "@/features/sounds";
import type { BlueprintSoundKit } from "@/features/planner/stages/blueprints";
import { DEFAULT_SOUND_KIT, type SoundKitSelection } from "./libraryModules";

/** `id@version` — the store ref a pin resolves as. Mirrors `soundKitRef` (planner `soundKitPin.ts`); kept
 *  local so the designs feature reads a pin without reaching into the planner's internals. */
export function pinRef(pin: Pick<BlueprintSoundKit, "id" | "version">): string {
  return `${pin.id}@${pin.version}`;
}

/**
 * Resolve a blueprint's sound-kit pin into the {@link SoundKitSelection} the Design Studio's library
 * resolvers run under (#3412). ONE DEFAULT, TWO LOUD FAILURES:
 *
 *  · no pin ⇒ `{ kind: "default" }` — the packaged starter kit, exactly as before #3412. An unpinned
 *    project's resolution is unchanged.
 *  · pin present + its artifact reads + parses as a valid kit ⇒ `{ kind: "pinned" }`.
 *  · pin present but UNRESOLVABLE — missing artifact, malformed JSON, a structurally invalid kit, or a
 *    bridge failure ⇒ `{ kind: "unresolved" }`, which drops the sound arm entirely so every
 *    `@bsc/sounds/…` surfaces as an unresolvable import. NEVER a silent degrade to the starter kit: the
 *    user cannot hear that the wrong kit loaded.
 *
 * Never throws — a bridge rejection becomes the `unresolved` arm, so a caller wires one code path.
 */
export async function selectSoundKit(pin: BlueprintSoundKit | undefined): Promise<SoundKitSelection> {
  if (!pin) return DEFAULT_SOUND_KIT;
  const ref = pinRef(pin);
  let raw: string;
  try {
    raw = (await bsc(null, ["sound", "release", "get", ref, "--artifact"])).trim();
  } catch (e) {
    return { kind: "unresolved", ref, error: `sound kit ${ref} could not be read from the store: ${String(e)}` };
  }
  // The CLI prints `null` (or nothing) for a ref the store doesn't hold — the pin resolved to no artifact.
  if (!raw || raw === "null") {
    return {
      kind: "unresolved",
      ref,
      error: `sound kit ${ref} is pinned but is not in the local sound-kit store — reopen the blueprint to resolve its pin`,
    };
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    return { kind: "unresolved", ref, error: `sound kit ${ref} artifact is not valid JSON: ${String(e)}` };
  }
  const kit = asSoundKit(parsed);
  if (!kit) {
    return { kind: "unresolved", ref, error: `sound kit ${ref} artifact is not a sound kit (no id / cues)` };
  }
  // A kit whose voices/cues reference missing parts would resolve imports that then fail INSIDE the player
  // module — catch it here so the breakage is reported at the pin, where it can be fixed.
  const problems = validateKit(kit);
  if (problems.length > 0) {
    return { kind: "unresolved", ref, error: `sound kit ${ref} is structurally invalid: ${problems.join("; ")}` };
  }
  return { kind: "pinned", ref, kit };
}

/** Narrow a parsed artifact to a {@link SoundKit} — the shape the store's `validate_artifact` already
 *  enforces on write (a non-empty top-level `cues`), re-checked here because the artifact crossed a
 *  process boundary. Missing optional collections normalize to `[]` so `validateKit` can run. */
function asSoundKit(v: unknown): SoundKit | null {
  if (!v || typeof v !== "object") return null;
  const o = v as Partial<SoundKit>;
  if (typeof o.id !== "string" || !o.id) return null;
  if (!Array.isArray(o.cues) || o.cues.length === 0) return null;
  return {
    ...(o as SoundKit),
    primitives: Array.isArray(o.primitives) ? o.primitives : [],
    voices: Array.isArray(o.voices) ? o.voices : [],
    cues: o.cues,
  };
}

runtime.features/designs/lib/studioVisibility.ts:
// studioVisibility (#3616) — is the Design Studio the page the user is actually LOOKING AT?
//
// DesignsWorkbench lives inside KeptMountedPage, which keeps it MOUNTED (CSS display:none) after the
// first visit so its state + PTY survive a page switch. That means its effects keep running while it's
// hidden — including `useComponentScan`, which esbuild-builds and hidden-iframe-probes all ~154
// components. Left ungated (`useComponentScan(true, …)`) that scan runs FOREVER in the background, pinning
// a WebView renderer near 40% CPU for a page nobody is looking at. Gating the scan on real visibility
// (the same condition the two KeptMountedPage wrappers use — App's `activeWorkspace === "projects"` AND
// the planner's `mode === "designs"`) pauses it when hidden and resumes it (sig-cache intact) on return.

/** True only when the Design Studio is the currently-shown page. `pageMode` is optional because
 *  `projectsPageMode` can be undefined before the projects workspace has picked a page. */
export function designStudioVisible(activeWorkspace: string, projectsPageMode: string | undefined): boolean {
  return activeWorkspace === "projects" && projectsPageMode === "designs";
}

runtime.features/designs/lib/themeBridge.ts:
// The frontend ↔ theme-store bridge (#2488) — the kit-theme collection is a GLOBAL store reached,
// from the UI AND from a live session's own shell, through the SAME `bsc ui theme …` CLI over the
// generic `bsc` bridge (#2114). Mirrors componentBridge.ts: `loadThemes` returns `null` when the
// bridge is unreachable (tests / web shell / an old bundled `bsc`) so the slice keeps its packaged
// seed rather than blanking it; the writes are fire-and-forget.
import { bsc, bscRun, bscWrite } from "@/shared/lib/core/bsc";
import type { KitThemeRecord } from "./themes";
import type { VariantDef } from "@/shared/ui/kit";

/** Load every stored component-variant definition via `bsc ui variants` (#2569); `null` when the bridge
 *  is unreachable (an old bundled `bsc` without the verb) so the app keeps whatever it already applied.
 *  Defensive shape gate: a row must carry string `component`/`variant` and an object `tokens`. */
export async function loadVariants(): Promise<VariantDef[] | null> {
  try {
    const out = await bsc(null, ["ui", "variants"]);
    const rows = JSON.parse(out.trim() || "[]") as Partial<VariantDef>[];
    return (rows ?? []).filter(
      (v): v is VariantDef =>
        typeof v.component === "string" && typeof v.variant === "string" && !!v.tokens && typeof v.tokens === "object",
    );
  } catch {
    return null;
  }
}

/** Load every theme via `bsc ui theme list --full`; `null` when unreachable.
 *
 *  Defensive shape gate: a row must carry `id`, `label`, AND an object `vars`. An OLD bundled `bsc`
 *  (pre-#2488) ignores `--full` and prints the lean `{id, label, description}` projection — those
 *  var-less rows are dropped here, so the hydrate sees an empty store and re-seeds rather than
 *  caching themes whose override maps were lost. */
export async function loadThemes(): Promise<KitThemeRecord[] | null> {
  try {
    const out = await bsc(null, ["ui", "theme", "list", "--full"]);
    const rows = JSON.parse(out.trim() || "[]") as Partial<KitThemeRecord>[];
    return (rows ?? [])
      .filter(
        (t): t is KitThemeRecord =>
          typeof t.id === "string" && !!t.id && typeof t.label === "string" &&
          !!t.vars && typeof t.vars === "object",
      )
      .map((t) => ({
        id: t.id,
        // The design group (#2749) — required + seed-relevant, so it must ride the round-trip
        // verbatim (never defaulted for a current row, or the reloaded copy hashes differently from
        // its stamp). A legacy/pre-#2749 row with no `tech` predates the axis: React is the only
        // design group it could have belonged to, so it materializes under `react` (the reconcile
        // then refreshes a pristine built-in to the seed's `tech` anyway).
        tech: t.tech ?? "react",
        label: t.label,
        description: t.description ?? "",
        // `base` is seed-relevant content and must ride WITHOUT normalizing (#2514 round-trip
        // contract): absent stays absent (never defaulted) so a base-less theme still hashes to its
        // stamp. Spread so the key is omitted entirely when the source row has no `base`.
        ...(t.base !== undefined ? { base: t.base } : {}),
        vars: t.vars,
        builtin: t.builtin,
        seedHash: t.seedHash, // #2483 — must ride or the refresh baseline is lost on write-through
      }));
  } catch {
    return null;
  }
}

/** Write-through a theme upsert (`bsc ui theme set`, JSON on stdin). Never throws (an old bundled
 *  `bsc` without the theme store verbs degrades to cache-only). */
export async function pushTheme(theme: KitThemeRecord): Promise<void> {
  try { await bscWrite(null, ["ui", "theme", "set"], theme); } catch { /* store unreachable — cache-only */ }
}

/** Write-through a theme removal (`bsc ui theme remove <id>`). Never throws. */
export async function dropTheme(id: string): Promise<void> {
  try { await bscRun(null, ["ui", "theme", "remove", id]); } catch { /* store unreachable — cache-only */ }
}

runtime.features/designs/lib/themes.ts:
// The kit-theme collection's pure domain (#2488) — the store-record shape, the packaged seed, and the
// reconcile/ordering helpers. Themes became a designer-writable store collection (`bsc ui theme
// set/remove` over `~/.base-studio-code/themes/`): the PACKAGED registry (`@data/ui/themes.json`, via
// `KIT_THEMES`) seeds it, and the #2483 hash-based `reconcileSeed` keeps the built-ins fresh across
// releases while never clobbering a designer-edited copy. React/Tauri-free (the bridge lives in
// themeBridge.ts) → unit-testable.

import { KIT_THEMES, type KitTheme } from "@/shared/ui/kit";
import { reconcileSeed, stampSeedHash, type SeedReconcile } from "./seedRefresh";

/** A theme as the STORE holds it: the packaged shape plus the seed-tracking provenance (#2483). */
export interface KitThemeRecord extends KitTheme {
  /** A packaged built-in. Absent/false ⇒ designer/user-authored (never touched by the reconcile). */
  builtin?: boolean;
  /** The content hash stamped when this copy was seeded (#2483). */
  seedHash?: string;
}

/** The packaged built-in themes as seed records — `builtin` + `seedHash` stamped at assembly time
 *  (the packaged JSON never bakes them in), mirroring `makeBuiltinKits`. */
export const SEED_THEMES: KitThemeRecord[] = KIT_THEMES.map((t) => stampSeedHash({ ...t, builtin: true }));

/** Reconcile the store's loaded themes with the packaged built-ins (#2483 — the full verdict table
 *  lives on {@link reconcileSeed}): a PRISTINE built-in copy tracks the seed (refreshed/deleted), a
 *  designer-EDITED one is kept (with a notice when the seed diverged), user-authored themes are never
 *  touched, and missing built-ins are re-seeded. `hydrateThemes` applies the pushes/drops. */
export function reconcileThemes(loaded: KitThemeRecord[]): SeedReconcile<KitThemeRecord> {
  return reconcileSeed(loaded, SEED_THEMES, "theme");
}

/** Deterministic display order for the pickers: the packaged registry order first (`default` leads),
 *  then every other (designer-authored) theme sorted by label. The store's on-disk listing order is
 *  filesystem-dependent, so the hydrate normalizes here. */
export function orderThemes(records: KitThemeRecord[]): KitThemeRecord[] {
  const seedRank = new Map(KIT_THEMES.map((t, i) => [t.id, i]));
  const packaged = records
    .filter((r) => seedRank.has(r.id))
    .sort((a, b) => seedRank.get(a.id)! - seedRank.get(b.id)!);
  const authored = records
    .filter((r) => !seedRank.has(r.id))
    .sort((a, b) => a.label.localeCompare(b.label));
  return [...packaged, ...authored];
}

/** The bucket a theme with no `tech` falls into (#2749). `tech` is required, but a corrupt persisted
 *  copy must never crash the page — it groups here, always ordered last. */
export const OTHER_GROUP = "other";

/** A design-group section on the Themes page (#2749): one `tech` group and the themes under it,
 *  mirroring how the Designs rail groups kits by their `tech` axis. */
export interface ThemeGroup {
  /** The design-group slug (`react`, …); {@link OTHER_GROUP} for a theme with no `tech`. */
  tech: string;
  /** The header label (the raw slug — the gallery uppercases it like the Designs `ds-grouphead`). */
  label: string;
  themes: KitThemeRecord[];
}

/** Group themes by their design group (#2749) for the grouped Themes page: one section per `tech`,
 *  themes kept in {@link orderThemes} order within a group, groups ordered by first appearance with
 *  the missing-`tech` bucket forced last. Pure → unit-tested. */
export function groupThemes(records: KitThemeRecord[]): ThemeGroup[] {
  const byTech = new Map<string, KitThemeRecord[]>();
  for (const t of orderThemes(records)) {
    const tech = (t.tech ?? "").trim() || OTHER_GROUP;
    const arr = byTech.get(tech);
    if (arr) arr.push(t);
    else byTech.set(tech, [t]);
  }
  const other = byTech.get(OTHER_GROUP);
  if (other && byTech.size > 1) {
    byTech.delete(OTHER_GROUP);
    byTech.set(OTHER_GROUP, other); // force the defensive bucket last
  }
  return [...byTech].map(([tech, themes]) => ({ tech, label: tech, themes }));
}

runtime.features/designs/lib/uiActivity.ts:
// UI-activity live-focus (#2525) — the Design Studio's read side of the designer session's activity
// stream. When the designer AI mutates the kit store (`bsc ui set/remove` — component / kit / theme),
// the Rust `emit_ui_activity` appends a `ui-touch` line to `ui-activity.log`; this tails that stream
// via `bsc logs tail ui --json` (the same bridge + shape `useCoordLog` uses for coord.log), parses the
// most-recent touch, and drives it into the store (`setAiFocused`) which live-focuses the node AND
// re-hydrates the touched collection so the edit appears without a relaunch.
//
// DS-specific, so it lives in the components feature's lib (not shared/) — modeled on
// `shared/lib/fleet/coordinationLog.ts` `parseCoordLine` + `shared/lib/fleet/useCoordLog.ts`.
import { useRef } from "react";
import { logsTail } from "@/shared/lib/core/logsBridge";
import { usePoll } from "@/shared/hooks/usePoll";
import { useAppStore } from "@/store";

/** One parsed designer activity line: which collection + record the AI just wrote (`ui-touch`) or is
 *  inspecting (`ui-focus`, #3545), and when. */
export interface UiTouch {
  /** `"touch"` = a WRITE (`bsc ui set/remove`) → focus + re-hydrate; `"focus"` = a READ
   *  (`bsc ui get`/`preview-props`, #3545) → focus only, no re-hydrate. */
  kind: "touch" | "focus";
  /** The touched store collection — `"component"` · `"kit"` · `"theme"` (drives which hydrate re-runs). */
  collection: string;
  /** The record id written/removed/read — the node the Design Studio focuses. */
  id: string;
  /** Epoch-ms of the event (0 if the timestamp is unparseable). */
  at: number;
  /** The emitting pane (`$BSC_AUDIT_PANE`, or `?`). */
  pane: string;
}

/**
 * Parse one TSV `ui-activity.log` line into a {@link UiTouch}, or `null` if unrecognized.
 * Columns: `ts \t pane \t <ui-touch|ui-focus> \t <collection> \t <id>` (the `emit_ui_activity` /
 * `emit_ui_focus` shape).
 */
export function parseUiActivityLine(line: string): UiTouch | null {
  const cols = line.replace(/\r?\n$/, "").split("\t");
  if (cols.length < 5) return null;
  const [ts, pane, kind, collection, id] = cols;
  const evKind = kind === "ui-touch" ? "touch" : kind === "ui-focus" ? "focus" : null;
  if (!evKind || !id) return null;
  const parsed = Date.parse(ts);
  const at = Number.isFinite(parsed) ? parsed : 0;
  return { kind: evKind, collection, id, at, pane };
}

/** The most-recent parseable touch in a chronological (oldest-first) line list, or `null`. */
export function latestUiTouch(lines: string[]): UiTouch | null {
  for (let i = lines.length - 1; i >= 0; i--) {
    const touch = parseUiActivityLine(lines[i]);
    if (touch) return touch;
  }
  return null;
}

/** A stable identity for an event, so a poll only re-fires the store on a genuinely NEW one. */
const touchKey = (t: UiTouch) => `${t.at}:${t.kind}:${t.collection}:${t.id}`;

/**
 * Poll the designer activity stream while `active`, driving each NEW `ui-touch` into the store
 * (`setAiFocused`) — the Design Studio live-focus (#2525). Gated: when `active` is false (the designer
 * session isn't booted) the tick early-returns, so there's no bridge cost. Reads oldest-first (like
 * the coord log) and takes the latest touch.
 */
export function useUiActivity(active: boolean, ms = 1500): void {
  const setAiFocused = useAppStore((s) => s.setAiFocused);
  const lastRef = useRef<string>("");
  usePoll(
    async (isCancelled) => {
      if (!active) return;
      const lines = await logsTail("ui", 50, true, null);
      if (isCancelled() || !lines) return;
      const touch = latestUiTouch(lines);
      if (!touch) return;
      const key = touchKey(touch);
      if (key === lastRef.current) return; // already focused this event
      lastRef.current = key;
      // #3545: a WRITE (`touch`) focuses AND re-hydrates the collection (so the edit shows); a READ
      // (`focus`) drives the preview ONLY — nothing changed to reload, and this fires on every `get`.
      setAiFocused(touch.id, touch.collection, { hydrate: touch.kind === "touch" });
    },
    ms,
    [active],
  );
}

runtime.features/designs/lib/useActiveSoundKit.t:
// The ACTIVE sound-kit selection for the Design Studio (#3412) — the React edge that turns the current
// project's blueprint `soundKit` pin into the {@link SoundKitSelection} the library resolvers run under.
//
// Which blueprint's pin? The one the work is under: the ACTIVE PROJECT's blueprint (`projectBlueprintId`)
// when a project is open, else the blueprint being AUTHORED (`activeBlueprintId`) — so the Design Studio
// previews a kit the same way whether you reached it from a project or from the blueprint library.
//
// Resolution is async (a store read across the `bsc` bridge), so the selection starts at the packaged
// default and settles once the artifact lands. That start state is deliberate: it matches the pre-#3412
// behavior for the one frame before the pin resolves, rather than blanking every sound import.
import { useEffect, useState } from "react";
import { useAppStore } from "@/store";
import { log } from "@/shared/lib/core/log";
import { DEFAULT_SOUND_KIT, type SoundKitSelection } from "./libraryModules";
import { selectSoundKit } from "./soundKitSelection";

/**
 * The active blueprint's resolved sound-kit selection (#3412). Re-resolves when the pinned ref changes;
 * an unresolvable pin is logged LOUDLY here (once per ref) and returned as the `unresolved` arm, which
 * makes every `@bsc/sounds/…` fail to resolve rather than quietly playing the starter kit.
 */
export function useActiveSoundKit(): SoundKitSelection {
  const activeProjectId = useAppStore((s) => s.activeProjectId);
  const projectBlueprintId = useAppStore((s) => s.projectBlueprintId);
  const activeBlueprintId = useAppStore((s) => s.activeBlueprintId);
  const blueprints = useAppStore((s) => s.blueprints);

  const blueprintId = (activeProjectId ? projectBlueprintId[activeProjectId] : "") || activeBlueprintId;
  const pin = blueprints.find((b) => b.id === blueprintId)?.soundKit;
  // Key on the REF (not the object) so an unrelated blueprint edit doesn't re-read the store.
  const ref = pin ? `${pin.id}@${pin.version}` : "";

  // The resolved selection is stored WITH the ref it was resolved for, so no state has to be reset when the
  // pin changes or is removed — the read below simply stops matching. That keeps the effect free of a
  // synchronous setState (which would cascade a render on every unpinned mount).
  const [resolved, setResolved] = useState<{ ref: string; sel: SoundKitSelection } | null>(null);

  useEffect(() => {
    if (!pin) return;
    let cancelled = false;
    void selectSoundKit(pin).then((next) => {
      if (cancelled) return;
      if (next.kind === "unresolved") log.error(`Design Studio sound kit: ${next.error}`);
      setResolved({ ref, sel: next });
    });
    return () => { cancelled = true; };
    // `pin` is derived from `ref` — keyed on the ref so a re-read happens only when the PIN itself changes,
    // not on every unrelated blueprint edit.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ref]);

  // No pin ⇒ the packaged default. A pin whose resolution hasn't landed yet ⇒ also the default, for the one
  // frame before it settles (matching pre-#3412 behavior rather than blanking every sound import).
  return ref && resolved?.ref === ref ? resolved.sel : DEFAULT_SOUND_KIT;
}

runtime.features/designs/lib/useComponentScan.ts:
// useComponentScan (#2838, #2908) — the Design Studio's on-visit preview-error scan. While the Studio page
// is mounted (`active`; it lazily mounts on FIRST visit via KeptMountedPage, never at app boot), it
// esbuild-builds each buildable component in the active kit AND runs each build-clean one in a hidden
// iframe (#2908) — throttled to a small concurrency so it never hangs the app — recording
// ok/build-error/runtime-error per component in the store. The graph badges the errors.
//
// The pure spine (which components to scan, the throttle pool, build→run→status derivation) lives in
// `componentScan.ts` and is unit-tested with a mocked bundle + run; this hook only wires it to the real
// esbuild-wasm `bundleComponent` + the DOM `probeComponentRuntime` (neither runs under jsdom) and the
// store, with cancellation.
import { useEffect, useRef } from "react";
import reactUiArtifact from "@data/components/react-ui.json";
import { useAppStore } from "@/store";
import { bundleComponent } from "@/shared/lib/preview/componentBundle";
import { probeComponentRuntime } from "@/shared/lib/preview/componentRuntimeProbe";
import { collectAppCss } from "@/shared/lib/preview/collectAppCss";
import { scannableComponents, pendingScans, scanComponents, durableLogSync, type ComponentScanResult, type ComponentBuildStatus } from "./componentScan";
import { recordPreviewError } from "./componentBridge";
import { type KitArtifact, type LibraryModuleResolver } from "./componentPreview";
import { libraryModuleResolver } from "./libraryModules";
import type { ComponentRecord } from "./model";

/** The packaged kit artifact (built-in `source` + `runtime` closure), same import the single-component
 *  `ComponentPreviewFrame` uses — its `source` survives here (the store SEED strips it, this raw import
 *  keeps it), so a built-in resolves its `@/…` closure at scan time. */
const ARTIFACT = reactUiArtifact as unknown as KitArtifact;

/** How many component builds run at once — a small pool so the sweep stays local + non-blocking. Each
 *  build is a synchronous-ish esbuild-wasm pass; 3 keeps the UI responsive on a large kit. */
const SCAN_CONCURRENCY = 3;

/** How long results buffer before one batched store commit (#4132). Long enough that a burst of builds
 *  collapses into a single render, short enough that badges still stream in visibly during a sweep. */
const SCAN_FLUSH_MS = 150;

/**
 * Scan the active kit's components for preview-build errors while `active`, recording each result in the
 * store (`setComponentBuildStatus`). Re-runs when `comps` changes (a designer edit), re-queuing only the
 * components whose build signature changed; a revisit with no edits is a no-op (all signatures cached).
 *
 * @param active whether the Studio page is currently mounted/visible — gates the scan so it runs on
 *               VISIT (KeptMountedPage first-mount), not at app boot.
 * @param comps  the active kit's components (the scan is kit-scoped, mirroring the graph).
 * @param artifact the packaged kit artifact; defaults to the bundled react-ui one (overridable for tests).
 */
export function useComponentScan(
  active: boolean,
  comps: ComponentRecord[],
  artifact: KitArtifact = ARTIFACT,
  // The library resolver the sweep builds with — the active blueprint's pinned sound kit (#3412) when the
  // caller has project context. It is part of the build, so a kit switch re-queues the affected components.
  libResolver: LibraryModuleResolver = libraryModuleResolver,
): void {
  const applyResults = useAppStore((s) => s.applyComponentScanResults);
  // The signature we last recorded a result for, per component id — survives kit switches + revisits, so
  // an already-built component is never re-bundled unless its source changed.
  const scannedSigs = useRef<Map<string, string>>(new Map());

  useEffect(() => {
    if (!active) return;
    const scannable = scannableComponents(comps, artifact, libResolver);
    const pending = pendingScans(scannable, scannedSigs.current);
    if (pending.length === 0) return;
    const sigById = new Map(pending.map((p) => [p.id, p.sig]));
    // App styles once per sweep (not per component) so each runtime probe renders faithfully.
    const appCss = collectAppCss();

    let cancelled = false;

    // #4132: BATCH the store writes. Results land one at a time (a throttled pool of esbuild passes), and
    // writing each straight through cost two commits per component — ~496 for this kit — every one of
    // which re-rendered the whole graph. Buffer them and flush on a short timer instead: the badges still
    // appear progressively (a sweep takes seconds, the flush window is 150ms) but a visit now costs
    // O(sweep-duration / 150ms) commits rather than O(2N).
    let buffer: ComponentScanResult[] = [];
    let flushTimer: ReturnType<typeof setTimeout> | null = null;
    const flush = () => {
      flushTimer = null;
      if (cancelled || buffer.length === 0) return;
      const batch = buffer;
      buffer = [];
      applyResults(batch);
    };
    const enqueue = (result: ComponentScanResult) => {
      buffer.push(result);
      flushTimer ??= setTimeout(flush, SCAN_FLUSH_MS);
    };

    void scanComponents(
      pending,
      bundleComponent,
      SCAN_CONCURRENCY,
      (id, status, stateBlanks) => {
        if (cancelled) return;
        // Mark the signature only once its result lands, so a cancelled build is re-queued next run
        // (never marked-but-unscanned).
        scannedSigs.current.set(id, sigById.get(id) ?? "");
        // #3540: mirror the render result to the DURABLE log BEFORE overwriting the store status, so the
        // prior status is still readable — `durableLogSync` records a runtime throw and clears a
        // now-resolved error (fire-and-forget; a missing `bsc` no-ops it). This is what makes
        // `bsc ui doctor` see the COMPLETE errored set, not only components a human opened.
        // The durable-log diff still reads the PRIOR status, so it must consult the store PLUS anything
        // already buffered but not yet flushed — otherwise a component scanned twice within one flush
        // window would diff against a stale value.
        // (a manual reverse scan — `findLast` is past this project's tsc lib target)
        let pendingPrior: ComponentBuildStatus | undefined;
        for (let i = buffer.length - 1; i >= 0; i--) if (buffer[i].id === id) { pendingPrior = buffer[i].status; break; }
        const sync = durableLogSync(pendingPrior ?? useAppStore.getState().componentBuildStatus[id], status);
        if (sync !== null) void recordPreviewError(id, sync);
        // Both halves go in one batched entry. `stateBlanks` is always carried (even `[]`) so a fixed
        // component clears its prior blank badge on re-scan.
        enqueue({ id, status, stateBlanks });
      },
      () => cancelled,
      // Runtime probe (#2908): run each build-clean component in a hidden iframe to catch a throw the
      // build can't see (e.g. a d3-force tick). Inconclusive/infra failures resolve ok — never a false badge.
      (js) => probeComponentRuntime(js, appCss),
    );
    return () => {
      // Flush what already landed BEFORE cancelling — those builds really happened, and dropping them
      // would re-queue work whose signature was already marked scanned (a badge that never returns).
      if (flushTimer) clearTimeout(flushTimer);
      if (buffer.length) applyResults(buffer);
      buffer = [];
      cancelled = true;
    };
  }, [active, comps, artifact, libResolver, applyResults]);
}

runtime.features/designs/lib/usePreviewStateCycl:
// usePreviewStateCycle (#3555) — gently auto-cycle a SMALL preview through the states a component actually
// supports (loading → loaded → error; empty is skipped, see `previewCycleStates`). The cycling is the only
// React here; the "which states" decision is the pure `previewCycleStates`. The preview's own build
// opacity-dip reads as a soft crossfade between states, so no animation is needed here.
import { useEffect, useState } from "react";
import type { ComponentRecord } from "./model";
import { previewCycleStates, type PreviewState } from "./componentPreview";

/** Milliseconds each state holds before the cycle advances — calm, not flickery. */
export const PREVIEW_CYCLE_MS = 2800;

/**
 * The data-state a small preview should render right now, auto-advancing through the component's cyclable
 * states on a timer. A component with a single cyclable state (just `loaded`) never advances. Cycling
 * pauses while `paused` (e.g. the pointer is over the preview) so it holds still to be inspected, and
 * resets to the first state when the selected component changes.
 */
export function usePreviewStateCycle(comp: ComponentRecord, paused: boolean): PreviewState {
  const states = previewCycleStates(comp);
  // `comp.id` in the key restarts the cycle on a component switch even when two components share a state set.
  const cycleKey = `${comp.id}|${states.join(",")}`;
  const [st, setSt] = useState({ key: cycleKey, idx: 0 });
  // Reset to the first state when the component / its cyclable set changes — React's guarded
  // adjust-state-during-render pattern (NOT a setState-in-effect), so the cycle restarts cleanly.
  const idx = st.key === cycleKey ? st.idx : 0;
  if (st.key !== cycleKey) setSt({ key: cycleKey, idx: 0 });
  useEffect(() => {
    if (paused || states.length < 2) return undefined;
    const t = setInterval(() => setSt((s) => ({ key: s.key, idx: (s.idx + 1) % states.length })), PREVIEW_CYCLE_MS);
    return () => clearInterval(t);
  }, [cycleKey, paused, states.length]);
  return states[idx % states.length] ?? "loaded";
}

runtime.features/designs/PaletteStrip.tsx:
// PaletteStrip (#2834) — the selected theme's semantic palette shown as labeled swatches at the top of
// the theme try-on center, alongside the big preview: you see the applied result AND the raw palette
// together. Each swatch is the theme's override (a literal colour) or the base default (`var(--token)`),
// grouped surfaces · text · borders · accent · status. Reads like a compact legend.
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Eyebrow } from "@/shared/ui/typography/Eyebrow";
import { ColorSwatch } from "@/shared/ui/controls/ColorSwatch";
import { PALETTE_GROUPS, swatchColor } from "./lib/palette";
import type { KitThemeRecord } from "./lib/themes";

export function PaletteStrip({ theme }: { theme: KitThemeRecord }) {
  const vars = theme.vars ?? {};
  return (
    <Box
      className="ds-palette"
      style={{ display: "flex", gap: 20, flexWrap: "wrap", alignItems: "flex-start", flex: "none", padding: "10px 16px", borderBottom: "1px solid var(--border-soft)", background: "var(--bg-elev)" }}
    >
      {PALETTE_GROUPS.map((g) => (
        <Box key={g.label} style={{ display: "flex", flexDirection: "column", gap: 5 }}>
          <Eyebrow size={9}>{g.label}</Eyebrow>
          <Box style={{ display: "flex", gap: 6 }}>
            {g.tokens.map((t) => {
              const overridden = t.token in vars;
              return (
                <Box
                  key={t.token}
                  title={`${t.token}${overridden ? ` · ${vars[t.token]}` : " · base default"}`}
                  style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 3 }}
                >
                  <ColorSwatch className="ds-swatch" color={swatchColor(vars, t.token)} size={24} radius={5} style={{ border: "1px solid var(--border)" }} />
                  <Text mono size={9} tone="dim">{t.name}</Text>
                </Box>
              );
            })}
          </Box>
        </Box>
      ))}
    </Box>
  );
}

runtime.features/designs/PaletteToggle.tsx:
// PaletteToggle (#3706) — the theme try-on top-bar control. Shows the applied theme's label and
// toggles the PaletteStrip (the theme's raw swatch band), which is now HIDDEN by default so the
// specimen owns the full preview height. A pressed toggle (`aria-pressed`) — the caret + accent label
// read the open state — so the raw palette is opt-in rather than permanently costing a strip.
import { Button } from "@/shared/ui/controls/Button";
import { Text } from "@/shared/ui/typography/Text";

export function PaletteToggle({ label, open, onToggle }: {
  /** The applied theme's label (e.g. "Nord"). */
  label: string;
  /** Whether the palette strip is currently shown. */
  open: boolean;
  /** Flip the palette strip's visibility. */
  onToggle: () => void;
}) {
  return (
    <Button
      variant="ghost"
      size="sm"
      aria-pressed={open}
      onClick={onToggle}
      title={open ? "Hide the theme palette" : "Show the theme palette — the theme's raw semantic swatches"}
      style={open ? { background: "var(--bg-elev2)" } : undefined}
    >
      <Text as="span" size="xxs" tone="dim" aria-hidden="true">{open ? "▾" : "▸"}</Text>
      <Text as="span" mono size="xxs" tone={open ? "accent" : "muted"}>{label}</Text>
    </Button>
  );
}

runtime.features/designs/PlannerComponentsPane.t:
// Planner Components pane (#2314) — the UI-Kit blueprint's `test_ui` stage body. A project-scoped lens
// on the proven-component library (direction 1a of the Planner Components Pane design), docked in the
// planner's focused pane. A Components ⇄ Full UI toggle: inspect one component in isolation (list +
// inline-expand preview/props/guidance + pull-into-plan / request / open-in-studio hand-offs) or the
// whole app assembled from the kit (highlighted, with a legend). Reuses the global `bsc ui`
// store + the shared specimen renderer; "Open in studio" hands off to the Design Studio workspace (#2308).
import { useEffect, useMemo, useRef, useState } from "react";
import { useAppStore } from "@/store";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";
import { SegmentedControl } from "@/shared/ui/controls/SegmentedControl";
import { Toggle } from "@/shared/ui/controls/Toggle";
import { SearchField } from "@/shared/ui/controls/SearchField";
import { StatusDot } from "@/shared/ui/feedback/StatusDot";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { RoleDot, KitChip } from "./kitChrome";
import { ROLE_COLOR, matchesQuery, NO_COMPONENTS_TITLE, type ComponentRecord, type Role } from "./lib/model";
import "./plannerComponentsPane.css";

type Mode = "components" | "full";
/** Role order for assembling a representative screen (structure first, primitives last). */
const ROLE_RANK: Record<Role, number> = { page: 0, layout: 1, composite: 2, primitive: 3, service: 4 };
/** How many kit components the Full-UI view assembles. */
const ASSEMBLE_MAX = 6;
const TOAST_MS = 1900;

/** A lightweight, non-interactive thumbnail for the list + assembly views (#2824): a framed role dot.
 *  The LIVE render (esbuild + iframe) is the Design Studio's single-component surface — too heavy to run
 *  per list item — so this pane shows a compact role marker (the name/role already label each row) and
 *  links to the studio. Renders NO component-name text (the row owns that). */
function Specimen({ comp, height }: { comp: ComponentRecord; scale?: number; height?: number }) {
  return (
    <Box style={{ display: "flex", alignItems: "center", justifyContent: "center", width: "100%", height: height ?? "100%", minHeight: 40, padding: 10, pointerEvents: "none", borderRadius: 8, background: "var(--bg-elev, var(--bg-soft))", border: "1px dashed var(--border-soft)" }}>
      <RoleDot role={comp.role} size={12} />
    </Box>
  );
}

export function PlannerComponentsPane() {
  const components = useAppStore((s) => s.components);
  const kits = useAppStore((s) => s.kits);
  const navigate = useAppStore((s) => s.navigate);

  const [kitId, setKitId] = useState(() => kits[0]?.id ?? "");
  const [mode, setMode] = useState<Mode>("components");
  const [query, setQuery] = useState("");
  const [openId, setOpenId] = useState<string | null>(null);
  const [highlight, setHighlight] = useState(true);
  const [toast, setToast] = useState<string | null>(null);
  const toastTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  useEffect(() => () => { if (toastTimer.current) clearTimeout(toastTimer.current); }, []);

  const flash = (msg: string) => {
    setToast(msg);
    if (toastTimer.current) clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(null), TOAST_MS);
  };

  const kit = kits.find((k) => k.id === kitId) ?? kits[0];
  const inKit = useMemo(() => components.filter((c) => c.kitId === kitId), [components, kitId]);
  const list = useMemo(() => inKit.filter((c) => matchesQuery(c, query)), [inKit, query]);
  // The whole-app assembly: structure-first, capped — the "app built from this kit".
  const assembled = useMemo(
    () => [...inKit].sort((a, b) => ROLE_RANK[a.role] - ROLE_RANK[b.role]).slice(0, ASSEMBLE_MAX),
    [inKit],
  );

  // The Design Studio is now a Planner tab (#move-to-planner): open the Planner Workspace on its "designs"
  // page rather than a standalone rail Workspace.
  const openInStudio = () => navigate({ workspace: "projects", page: "designs" });

  if (!kit) {
    return (
      <Box className="pcp-root">
        <EmptyState
          size="sm"
          title={NO_COMPONENTS_TITLE}
          description="The proven-component library is empty — seed a kit to browse it here."
        />
      </Box>
    );
  }

  return (
    <Box className="pcp-root">
      {/* ── header ── */}
      <Box className="pcp-head">
        <Box className="pcp-headrow">
          <Text weight={600} size={13}>Components</Text>
          <Box style={{ display: "flex", alignItems: "center", gap: 6 }}>
            <Text mono size="xxs" tone="dim">ACTIVE KIT{kits.length > 1 ? "S" : ""}</Text>
            {kits.map((k) => (
              <KitChip key={k.id} kit={k} on={k.id === kitId} className="pcp-kitchip" title={k.stack}
                onClick={() => { setKitId(k.id); setOpenId(null); }} />
            ))}
          </Box>
        </Box>
        <Box className="pcp-toggle">
          <SegmentedControl
            label=""
            options={[
              { label: "▤ Components", on: mode === "components", onClick: () => setMode("components") },
              { label: "▦ Full UI", on: mode === "full", onClick: () => setMode("full") },
            ]}
          />
        </Box>
      </Box>

      {mode === "components" ? (
        <>
          {/* search */}
          <Box className="pcp-search">
            <SearchField
              value={query}
              onChange={setQuery}
              placeholder="Search components this app needs…"
              aria-label="Search components"
              inputStyle={{ fontSize: 12 }}
              trailing={<Text mono size="xxs" tone="dim">{list.length}/{inKit.length}</Text>}
            />
          </Box>

          {/* list */}
          <Box className="pcp-scroll pcp-list">
            {list.map((c) => {
              const open = openId === c.id;
              return (
                <Box key={c.id} className="pcp-item">
                  <Box as="button" className={`pcp-row${open ? " on" : ""}`} onClick={() => setOpenId(open ? null : c.id)}>
                    <Box className="pcp-thumb"><Specimen comp={c} scale={0.5} /></Box>
                    <Box style={{ flex: 1, minWidth: 0 }}>
                      <Box style={{ display: "flex", alignItems: "center", gap: 7 }}>
                        <RoleDot role={c.role} size={7} />
                        <Text weight={600} size={12.5}>{c.name}</Text>
                      </Box>
                      <Text mono size="xxs" tone="dim" as="div" style={{ marginTop: 3 }}>{kit.name} · {c.role}</Text>
                    </Box>
                    <Text as="span" className="pcp-status">in library ✓</Text>
                  </Box>

                  {open && (
                    <Box className="pcp-detail">
                      <Box className="pcp-preview">
                        <Specimen comp={c} scale={0.85} height={126} />
                        <Text as="span" className="pcp-preview-tag">read-only preview</Text>
                      </Box>
                      <Box style={{ padding: "12px 14px" }}>
                        <Text mono size="xxs" tone="dim" as="div" style={{ letterSpacing: ".06em", textTransform: "uppercase", marginBottom: 7 }}>Props</Text>
                        <Box style={{ display: "flex", flexDirection: "column", gap: 5, marginBottom: 13 }}>
                          {c.props.slice(0, 4).map((p) => (
                            <Box key={p.name} className="pcp-proprow">
                              <Text mono tone="muted" size={11.5}>{p.name}</Text><Text mono tone="accent" size={10.5}>{p.type}</Text>
                            </Box>
                          ))}
                          {c.props.length === 0 && <Text mono size={11} tone="dim">No public props.</Text>}
                        </Box>
                        <Box style={{ display: "flex", gap: 12, marginBottom: 14 }}>
                          <Box style={{ flex: 1 }}>
                            <Text size={10} tone="success" as="div" style={{ marginBottom: 4 }}>✓ Use when</Text>
                            <Text size={11} tone="muted" style={{ lineHeight: 1.5 }}>{c.whenUse[0] ?? "—"}</Text>
                          </Box>
                          <Box style={{ flex: 1 }}>
                            <Text size={10} tone="danger" as="div" style={{ marginBottom: 4 }}>✗ Avoid</Text>
                            <Text size={11} tone="muted" style={{ lineHeight: 1.5 }}>{c.whenNot[0] ?? "—"}</Text>
                          </Box>
                        </Box>
                        <Box className="pcp-actions">
                          <Button variant="primary" size="sm" onClick={() => flash(`“${c.name}” added to the plan`)} style={{ flex: 1 }}>Pull into plan</Button>
                          <Button variant="ghost" size="sm" onClick={openInStudio}>Open in studio ↗</Button>
                        </Box>
                      </Box>
                    </Box>
                  )}
                </Box>
              );
            })}
            {list.length === 0 && (
              <Text size={11.5} tone="dim" as="div" style={{ padding: "10px 2px", fontStyle: "italic" }}>No components match “{query}”.</Text>
            )}
            <Box as="button" className="pcp-req" onClick={() => flash("Requested a new component — handed off to Design studio")}>
              <Text as="span" tone="dim">＋</Text> Request a new component
            </Box>
          </Box>
        </>
      ) : (
        <>
          <Box className="pcp-full-head">
            <Text size={11.5} tone="muted">Assembled from <b style={{ color: "var(--fg)" }}>{assembled.length}</b> kit components</Text>
            <Box style={{ display: "flex", alignItems: "center", gap: 7 }}>
              <Toggle size="sm" on={highlight} onClick={() => setHighlight((h) => !h)} role="switch" ariaChecked={highlight} />
              <Text size={11} tone="muted">highlight</Text>
            </Box>
          </Box>
          <Box className="pcp-scroll pcp-full">
            <Box className="pcp-assembled">
              {assembled.map((c, i) => (
                <Box key={c.id} className={`pcp-cell${highlight ? " hl" : ""}`} style={{ padding: 8 }}>
                  {highlight && <Box as="span" className="pcp-cell-tag" style={{ background: ROLE_COLOR[c.role] }}>{i + 1}</Box>}
                  <Box style={{ display: "flex", justifyContent: "center", overflow: "hidden" }}>
                    <Specimen comp={c} scale={0.8} />
                  </Box>
                </Box>
              ))}
            </Box>
            <Box style={{ marginTop: 12, display: "flex", flexDirection: "column", gap: 6 }}>
              <Text mono size="xxs" tone="dim" style={{ letterSpacing: ".06em", textTransform: "uppercase", marginBottom: 2 }}>Legend</Text>
              {assembled.map((c, i) => (
                <Box as="button" key={c.id} className="pcp-legend-row" onClick={() => { setMode("components"); setOpenId(c.id); }}>
                  <Box as="span" className="pcp-legend-n" style={{ background: ROLE_COLOR[c.role] }}>{i + 1}</Box>
                  <Text size={12} weight={500}>{c.name}</Text>
                  <Text mono size="xxs" tone="dim">{c.role}</Text>
                </Box>
              ))}
            </Box>
          </Box>
        </>
      )}

      {toast && (
        <Box className="pcp-toast">
          <StatusDot color="var(--success)" size={7} />
          <Text size={12}>{toast}</Text>
        </Box>
      )}
    </Box>
  );
}

runtime.features/designs/RailTree.tsx:
// The Design Studio rail tree (#2717) — extracted from DesignStudio.tsx, mirroring how `GraphView` and
// `Inspector` are their own components. Renders the kits→components tree: technology → style group
// headers (default OPEN) down to the collapsible kit heads and their search-filtered component rows.
// Pure presentational — all selection/expand state lives in the parent (`DesignStudio`) and is threaded
// through props. The rows/headers now render through the shared RailRow / RailGroupHeader nav primitives
// (#2789); the `ds-grouphead`/`ds-kithead`/`ds-comprow` classes remain only as selector/test hooks (the
// styling is the canonical shared look, no longer their own CSS).
//
// #4128 lifted the folder LEVEL out of here into `shared/`: the folder glyph + header row are now
// `RailFolderRow`, and the tree they render is built by the shared `buildFolderTree`. Both are used
// verbatim by the Algorithms rail, so the two library rails are the same rail rather than lookalikes.
import { type ReactNode } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { ColorSwatch } from "@/shared/ui/controls/ColorSwatch";
import { RailRow } from "@/shared/ui/layouts/RailRow";
import { RailGroupHeader } from "@/shared/ui/layouts/RailGroupHeader";
import { RailFolderRow, RailFolderChildren } from "@/shared/ui/layouts/RailFolderRow";
import { RoleDot } from "./kitChrome";
import type { ComponentRecord, Kit } from "./lib/model";
import { type KitTreeNode, type ComponentFolder, groupComponentsByFolder, folderComponentCount } from "./lib/kitGroups";
import { byTier } from "./lib/compositionLayout";

interface RailTreeProps {
  /** The technology → style rail hierarchy (from `groupKits`). */
  railTree: KitTreeNode[];
  /** Per-key expand state (kit id or group key → open) + its setter. */
  expanded: Record<string, boolean>;
  setExpanded: (updater: (e: Record<string, boolean>) => Record<string, boolean>) => void;
  /** The active kit (its head shows `.active`). */
  kitId: string;
  setKitId: (id: string) => void;
  /** The focused component id (its row shows `.on` when in the active kit). */
  compId: string | null;
  /** The full component library (rows are filtered per-kit by `match`). */
  components: ComponentRecord[];
  /** The search-filter predicate (`matchesQuery(c, query)`). */
  match: (c: ComponentRecord) => boolean;
  /** Focus a component row. */
  selectComp: (c: ComponentRecord) => void;
  /** The current search query — drives the "no matches" placeholder. */
  query: string;
}

export function RailTree({ railTree, expanded, setExpanded, kitId, setKitId, compId, components, match, selectComp, query }: RailTreeProps) {
  // One rail kit entry: the collapsible kit head + its (search-filtered) component rows. Under the
  // #2506 single-kit style merge this IS the style header — `label` shows the style name instead of
  // the kit name (the kit identity stays in the tooltip), and no separate kit row renders.
  const renderRailKit = (k: Kit, label?: string) => {
    const open = !!expanded[k.id];
    const inKit = components.filter((c) => c.kitId === k.id);
    const rows = inKit.filter(match).sort(byTier); // Pages on top, like the graph (#2976)
    // One component row — shared by the flat list and the per-group nesting (#3048).
    const renderCompRow = (c: ComponentRecord) => (
      <RailRow
        key={c.id}
        className="ds-comprow"
        indent={1}
        active={c.id === compId && k.id === kitId}
        onClick={() => selectComp(c)}
        leading={<RoleDot role={c.role} size={7} glow={3} />}
        trailing={<Text mono size="xxs" tone="dim" style={{ padding: "1px 5px", background: "var(--bg-soft)", borderRadius: 4 }}>×{c.used}</Text>}
      >
        {c.name}
      </RailRow>
    );
    // One folder of the kit's tree (#3582): a collapsible header (default OPEN), its subfolders
    // (recursion), then its direct component rows. Expand state is namespaced by kit so two kits'
    // identically-named folders (`shared/ui`) don't share a toggle. Mirrors a file explorer:
    // subfolders list before a folder's own files. Rendered as a readable RailRow (#3632) — a folder
    // glyph + caret + `weight:500`, the same fg-muted→fg row look as the leaves — NOT the dim uppercase
    // micro-label it used to wear (which was hard to read for what is the browsable tree here).
    const renderFolder = (f: ComponentFolder): ReactNode => {
      const fkey = `${k.id}::${f.key}`;
      const open = expanded[fkey] ?? true;
      return (
        <Box key={f.key} className="ds-compfolder" style={{ marginBottom: 2 }}>
          <RailFolderRow
            className="ds-compfolderhead"
            label={f.label}
            count={folderComponentCount(f)}
            open={open}
            onToggle={() => setExpanded((e) => ({ ...e, [fkey]: !(e[fkey] ?? true) }))}
            ungrouped={f.ungrouped}
            path={f.key}
          />
          {open && (
            <RailFolderChildren>
              {f.folders.map(renderFolder)}
              {f.items.map(renderCompRow)}
            </RailFolderChildren>
          )}
        </Box>
      );
    };
    // When this kit's components carry `group` folder paths, render them as a nested folder tree
    // (#3582); otherwise `folders` is null and the flat list renders EXACTLY as before (zero regression).
    const folders = groupComponentsByFolder(rows);
    return (
      <Box key={k.id} style={{ marginBottom: 4 }}>
        <RailRow
          className="ds-kithead"
          caret={open}
          active={k.id === kitId}
          weight={500}
          title={label ? `${label} · ${k.name} — ${k.stack}` : k.stack}
          onClick={() => { setKitId(k.id); setExpanded((e) => ({ ...e, [k.id]: !e[k.id] })); }}
          leading={<ColorSwatch color={k.dot} size={7} />}
          trailing={<Text mono size="xxs" tone="dim">{inKit.length}</Text>}
        >
          {label ?? k.name}
        </RailRow>
        {open && (
          <Box style={{ margin: "2px 0 6px", paddingLeft: 6 }}>
            {folders ? folders.map(renderFolder) : rows.map(renderCompRow)}
            {rows.length === 0 && query && (
              <Text size={11} tone="dim" as="div" style={{ padding: "6px 10px", fontStyle: "italic" }}>no matches</Text>
            )}
          </Box>
        )}
      </Box>
    );
  };
  // A rail tree node: a kit entry, or a collapsible tech/style group header (default OPEN — its
  // expand state shares the `expanded` record under the group's stable key). A single-kit style
  // group (#2506) renders as the kit entry labelled with the style — the style header IS the kit.
  const renderRailNode = (n: KitTreeNode): ReactNode => {
    if (n.kind === "kit") return renderRailKit(n.kit);
    if (n.kit) return renderRailKit(n.kit, n.label);
    const open = expanded[n.key] ?? true;
    return (
      <Box key={n.key} style={{ marginBottom: 4 }}>
        <RailGroupHeader
          className="ds-grouphead"
          collapsible
          open={open}
          onToggle={() => setExpanded((e) => ({ ...e, [n.key]: !(e[n.key] ?? true) }))}
          count={n.count}
          title={`${n.level === "tech" ? "technology" : "visual language"}: ${n.label}`}
        >
          {n.label}
        </RailGroupHeader>
        {open && <Box className="ds-groupkids">{n.children.map(renderRailNode)}</Box>}
      </Box>
    );
  };

  return <>{railTree.map(renderRailNode)}</>;
}

runtime.features/designs/store.ts:
// Components feature store slice (#2269) — the proven-component library, a WRITE-THROUGH cache over the
// GLOBAL component store (reached via `bsc ui` — see lib/componentBridge.ts, #2281). The planner's
// `test_ui` pane and (later) the full Design Studio page share ONE library. On boot `hydrateComponents`
// loads both collections through the bridge and reconciles the packaged built-ins with the hash-based
// seed refresh (#2483, lib/seedRefresh.ts): pristine built-in copies track the seed (refreshed/deleted),
// user-edited ones are kept with a notice, and missing built-ins are re-seeded. A no-op that keeps the
// seed when the bridge is unreachable (tests, the web shell, an old bundled `bsc`).
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import type { ComponentRecord, Kit } from "./lib/model";
import type { ComponentBuildStatus, RuntimeStateCategory, ComponentScanResult } from "./lib/componentScan";
import type { PreviewState } from "./lib/componentPreview";
import type { KitConsumer, KitChange, Dispatch } from "./lib/propagation";
import type { SeedNotice } from "./lib/seedRefresh";
import type { DesignDirective } from "./lib/designerQueue";
import { DEFAULT_MAX_TURNS, DRIVER, DESIGNER } from "./lib/designerLoopDrive";
import { bsc, bscRun } from "@/shared/lib/core/bsc";
import { kitUsageId, makeChange, planPropagation, dispatchKey } from "./lib/propagation";
import { SEED_COMPONENTS, SEED_KITS, reconcileComponents, reconcileKits } from "./lib/seed";
import { SEED_THEMES, reconcileThemes, orderThemes, type KitThemeRecord } from "./lib/themes";
import { loadComponents, loadComponentsGraph, loadKits, pushComponent, dropComponent, pushKit, dropKit } from "./lib/componentBridge";
import { loadThemes, pushTheme, dropTheme, loadVariants } from "./lib/themeBridge";
import { loadKitUsage, pushKitUsage, dropKitUsage } from "./lib/kitUsageBridge";
import { setActiveKitThemes, applyVariantsToRoot, applyContributionsToRoot, applyAnimationsToRoot, kitAnimations, type DesignContributionOverlay } from "@/shared/ui/kit";

/** Merge fresh kit-change dispatches into the queue, deduped by `dispatchKey` — shared by the two
 *  change-origins: the desktop `setComponent` edit and the `ui-touch`/CLI-edit diff (#2810). Exported
 *  for the unit test. */
export function mergeDispatches(current: Dispatch[], fresh: Dispatch[]): Dispatch[] {
  const seen = new Set(current.map(dispatchKey));
  const add = fresh.filter((d) => !seen.has(dispatchKey(d)));
  return add.length ? [...current, ...add] : current;
}

/** Has a component's PUBLIC CONTRACT (what consumers depend on) changed — props, variants, or version?
 *  The gate for firing propagation from a `ui-touch` diff, so the 65 components a designer DIDN'T edit
 *  don't queue noise on every touch. Exported for the unit test. */
export function contractChanged(before: ComponentRecord, after: ComponentRecord): boolean {
  return (
    JSON.stringify([before.props, before.variants, before.version]) !==
    JSON.stringify([after.props, after.variants, after.version])
  );
}

export interface ComponentsSlice {
  /** The proven-component library — the typed seed until the global store lands, then its contents. */
  components: ComponentRecord[];
  /** The kits (technology-scoped namespaces) the components belong to. */
  kits: Kit[];
  /** Hydrate the library from the global `bsc ui` store on boot. No-op (keeps the seed) when the
   *  bridge is unreachable. Applies the hash-based seed refresh (#2483): pushes refreshed/added
   *  built-ins, drops deleted ones, and surfaces the kept-but-diverged outcomes as `seedNotices`. */
  hydrateComponents: () => Promise<void>;

  /** The kit THEME collection (#2488) — the packaged registry until the designer-writable theme
   *  store hydrates, then its contents (ordered: built-ins in registry order, then authored). The
   *  Settings picker + the Design Studio preview switcher read this; `themeById`/`ThemeScope`
   *  resolve against the same set via `setActiveKitThemes`. */
  kitThemes: KitThemeRecord[];
  /** Hydrate the theme collection from the global `bsc ui theme` store on boot (#2488), mirroring
   *  `hydrateComponents`: no-op (keeps the packaged seed) when the bridge is unreachable; reconciles
   *  built-ins via the #2483 seed refresh (theme notices ride the same `seedNotices` surface) and
   *  syncs the result into the shared theme resolvers. */
  hydrateThemes: () => Promise<void>;
  /** Hydrate the data-defined component variants from the global `bsc ui variants` store (#2569) and
   *  compile them into the live managed `<style>` — so an LLM-authored variant renders without a
   *  relaunch. Re-run on boot and on a `ui-touch` "variant" write. No-op when the bridge is unreachable. */
  hydrateVariants: () => Promise<void>;

  /** Design contributions (#2656) — the token overlays downloaded blueprints contribute (their
   *  reconciled + generated categories, #2646/#2650/#2636). PERSISTED + applied on boot: a
   *  compose-don't-mutate layer the running app follows, never written into the shared contract. */
  designContributions: DesignContributionOverlay[];
  /** Register/replace a blueprint's contribution (upsert by `source`) + apply it live. */
  addDesignContribution: (overlay: DesignContributionOverlay) => void;
  /** Drop a source's contribution + re-apply the rest (e.g. the blueprint is removed). */
  removeDesignContribution: (source: string) => void;
  /** Built-ins kept through a seed divergence (#2483): the user's customized copy survived an
   *  upstream update, or a retired built-in was kept because it was customized. Recomputed on each
   *  hydrate (not persisted). No longer surfaced in a UI pane — the in-Studio SeedNoticesCard was
   *  removed (#2948); the reconcile still tracks these for `dismissSeedNotice`/future surfacing. */
  seedNotices: SeedNotice[];
  /** Dismiss one seed notice (by type + id). */
  dismissSeedNotice: (type: SeedNotice["type"], id: string) => void;

  /** The consumer index (#2277) — which projects use which kit; the edges a kit CHANGE fans out over.
   *  A write-through cache over the global `bsc ui usage` store. */
  kitUsage: KitConsumer[];
  /** Hydrate the consumer index on boot (no-op keeping the persisted cache when unreachable). */
  hydrateKitUsage: () => Promise<void>;
  /** Record that a project uses a kit (idempotent by (projectKey, kitId)); pushes through the bridge. */
  addKitUsage: (projectKey: string, kitId: string) => void;
  /** Remove a project→kit consumer edge; pushes the removal through the bridge. */
  removeKitUsage: (projectKey: string, kitId: string) => void;

  /** Upsert a component (the change ORIGIN, #2277): write it through to the store AND — when it EDITS an
   *  existing component — emit a classified {@link KitChange} (prop/variant diff), fan it out over the
   *  consumer index (`kitUsage`), and queue the resulting `kitDispatches`. An author-declared class
   *  overrides the derived one. Adding a brand-new component is not a "change" (no diff to fan out). */
  setComponent: (component: ComponentRecord, changeOverride?: Partial<Pick<KitChange, "class" | "summary" | "migration">>) => void;
  /** Import a whole kit + its components (from a gist / share code, #2305 slice 1c) as a USER kit:
   *  collision-safe (a colliding kit or component id is freshly minted so a packaged built-in can never
   *  be clobbered), write-through to the `bsc ui` store. Returns the (possibly re-id'd) kit. */
  importKit: (kit: Kit, components: ComponentRecord[]) => Kit;
  /** The pending fan-out — the planned per-consumer dispatches a kit change produced (notify-only by
   *  default; issue/assign only for breaking + opted-in consumers). Drained by the delivery slice. */
  kitDispatches: Dispatch[];
  /** Dismiss a queued dispatch (once delivered / acknowledged), keyed by (projectKey, change.id). */
  dismissKitDispatch: (projectKey: string, changeId: string) => void;
  /** Auto-apply kit changes (#2944, default ON #2968) — when ON (default) a designer change propagates
   *  to its consumers without the approval gate; when OFF the KitChangesBanner presents it for the user
   *  to approve. Surfaced in Planner settings; persisted. */
  autoApplyKitChanges: boolean;
  setAutoApplyKitChanges: (on: boolean) => void;
  /** Remove ALL of a kit change's queued dispatches at once (#2951) — the KitChangesBanner's Approve
   *  (after delivering to any live consumer) and Dismiss both call this, so confirming a change
   *  actually clears it from the queue instead of leaving it to the drain (which only fires for a live
   *  consumer, so a non-live one's change would never leave — and reappear after a restart). */
  dismissKitChange: (changeId: string) => void;

  /** The Design Studio's SELECTED kit + component (#3274). Lifted out of `DesignsWorkbench`'s local
   *  `useState` because two surfaces now need it: the user clicking a node, and `bsc navigate component
   *  <kit> <component>` steering the app so a capture can target something. While it was local state
   *  nothing outside the UI could select a component, so `bsc shot` could only photograph whatever
   *  happened to be on screen.
   *
   *  TRANSIENT — deliberately NOT persisted. `designsCompId` starting null on each boot is what keeps
   *  the Inspector hidden-when-empty (#3090, restoring #2705); persisting it would reopen the app
   *  pre-focused and quietly undo that. `designsKitId` empty ⇒ the workbench falls back to the first
   *  kit, exactly as the old lazy `useState(() => kits[0]?.id)` did. */
  designsKitId: string;
  /** `null` ⇒ nothing focused (the Inspector hides unless the AI is working a node). */
  designsCompId: string | null;
  /** Select a kit; clears the component selection (a component belongs to exactly one kit). */
  setDesignsKit: (id: string) => void;
  setDesignsComp: (id: string | null) => void;

  /** The preview's DATA-STATE axis (#3717) — `loaded` (demo) · `empty` (no data) · `loading` (skeleton).
   *  In the STORE (not local to the workbench) so BOTH the state SegmentedControl AND `bsc navigate
   *  component --state <s>` drive one value — the latter lets an external session (the overnight loop)
   *  deliberately capture a specific render via `bsc shot frame`. TRANSIENT (not persisted): it resets to
   *  `loaded` each boot, so a stale state never survives to be "leftover" on the next render. */
  designsPreviewState: PreviewState;
  setDesignsPreviewState: (s: PreviewState) => void;

  /** The library id the designer AI most-recently touched (#2525) — a component/kit/theme id from a
   *  `bsc ui set/remove` mutation the `useUiActivity` poll observed. The Design Studio live-focuses it
   *  (pulsing `.working` node + auto-pan). `null` when idle or the designer session ended. */
  aiFocusedId: string | null;
  /** Record a designer `ui-touch` (#2525): set {@link aiFocusedId} to the touched id AND re-pull the
   *  touched collection so the AI's edit appears live (hydrate is otherwise one-shot at boot) —
   *  `hydrateComponents` always, plus `hydrateThemes` for a `theme` touch. A `null` id clears the
   *  focus (session end) without re-hydrating. */
  /** Live-focus the node Claude is on (#2525). `opts.hydrate` (default true) re-pulls the collection so a
   *  WRITE's edit shows; a READ-focus (#3545 `ui-focus`) passes `false` — the preview follows Claude's
   *  inspection without a library refetch on every `get`. */
  setAiFocused: (id: string | null, collection?: string, opts?: { hydrate?: boolean }) => void;

  /** Per-component preview-BUILD status (#2838) — component id → ok | error(message), populated lazily
   *  by the on-visit `useComponentScan` sweep (esbuild-builds each buildable component in the active
   *  kit, throttled). The Design Studio graph badges the `error` entries. TRANSIENT: not persisted (a
   *  fresh scan repopulates on each visit), so it never goes stale on disk. */
  componentBuildStatus: Record<string, ComponentBuildStatus>;
  /** Record one component's build outcome — the scan's per-result write (upsert by id). */
  setComponentBuildStatus: (id: string, status: ComponentBuildStatus) => void;

  /** Per-component RUNTIME data-state blanks (#3191) — component id → the render-confirmed
   *  `empty-empty-state` / `empty-loading-state` categories, populated by the same on-visit scan. The
   *  Design Studio graph folds these into its health badges (`nodeHealth`). TRANSIENT: not persisted (a
   *  fresh scan repopulates on each visit). */
  componentStateHealth: Record<string, RuntimeStateCategory[]>;
  /** Record one component's data-state blanks — the scan's per-result write (upsert by id; `[]` clears). */
  setComponentStateHealth: (id: string, categories: RuntimeStateCategory[]) => void;

  /** Apply a BATCH of scan results in ONE commit (#4132) — the scan's real write path.
   *
   *  The two per-result setters above wrote twice per component, so a 248-component sweep produced ~496
   *  store commits, and the Studio (which subscribes to both maps) re-rendered its whole graph on each
   *  one — the measured churn was 125 `[render] designs update` commits at ~24ms. Both maps move together
   *  in a single `set` so a flush is one commit and one render, whatever its size. An empty batch is a
   *  no-op rather than an identity-breaking commit. */
  applyComponentScanResults: (results: readonly ComponentScanResult[]) => void;

  /** The OVERNIGHT designer-loop run (#3304, epic #3260) — `null` when off, which is ALWAYS the boot
   *  state: deliberately absent from `partialize`, so an autonomous token-spending run can never
   *  auto-start or survive a restart. Only {@link startDesignerOvernight} (a user click) sets it. */
  designerOvernight: DesignerOvernightRun | null;
  /** Opt in: open a `driver ↔ designer` loop carrying the run's ceilings and enter queue mode. A no-op
   *  when a run is already active, or when `bsc loop new` fails (the bridge/binary is absent) — a run
   *  without a real loop behind it would drive nothing, so we stay OFF rather than pretend. */
  startDesignerOvernight: (opts?: { maxTurns?: number; budget?: number }) => Promise<void>;
  /** Ask the run to halt: flag it `stopping` (which stops the pump dispatching on its very next read)
   *  and issue the out-of-band `bsc loop stop`. The local run state is NOT cleared here — the pump
   *  clears it via {@link endDesignerOvernight} once the loop is observably gone, and re-issues the
   *  stop each tick until then, so a swallowed CLI failure retries instead of stranding a live loop. */
  stopDesignerOvernight: () => Promise<void>;
  /** Leave overnight mode locally (the pump, once its loop is confirmed closed/absent). */
  endDesignerOvernight: () => void;
  /** Install the ranked directive queue built once at run start (`buildDesignerQueue`). */
  setDesignerOvernightQueue: (queue: DesignDirective[]) => void;
  /** Advance the queue cursor — one dispatched directive (the cursor IS the turn count). */
  advanceDesignerOvernight: () => void;
}

/** A live overnight run's state. The ceilings are mirrored from the ones handed to `bsc loop new`, so
 *  the pump stops dispatching at the same point the loop store would independently close the loop. */
export interface DesignerOvernightRun {
  /** The `bsc loop` this run drives — the pump ignores any other open loop. */
  loopId: number;
  /** Directive ceiling: the pump stops once `cursor` reaches it (see `decideOvernightAction`). */
  maxTurns: number;
  /** Cost ceiling in USD handed to `bsc loop --budget` (0 = unlimited). */
  budget: number;
  /** Directives dispatched so far — the queue cursor AND the turn count. */
  cursor: number;
  /** The ranked queue, built once at run start so `queue[cursor]` stays stable as findings are fixed. */
  queue: DesignDirective[];
  /** A halt has been requested — dispatch nothing; keep re-issuing `bsc loop stop` until it lands. */
  stopping: boolean;
  startedAt: number;
}

/** The default cost ceiling handed to `bsc loop --budget`. HONEST CAVEAT: the loop store sums the
 *  per-turn `--cost` values, and only the designer can report what its own turn cost — so this bites
 *  only when turns actually carry `--cost`. {@link DEFAULT_MAX_TURNS} is the ceiling that always
 *  applies, which is why it is passed unconditionally. */
export const DEFAULT_OVERNIGHT_BUDGET = 10;

/** The seed the overnight loop opens with — the driver speaks first, so this is context, not a task. */
const OVERNIGHT_SEED =
  "Overnight design run: the driver dispatches one ranked directive per turn from the design system's own " +
  "measured gaps. Make ONE change per turn via `bsc ui`, ground it with a fresh `bsc shot`, and record it.";

export const createComponentsSlice: StateCreator<AppStore, [], [], ComponentsSlice> = (set, get) => ({
  components: SEED_COMPONENTS,
  kits: SEED_KITS,

  hydrateComponents: async () => {
    // #2975: auto-apply ON ⇒ no pending review queue. `kitDispatches` is persisted (durable across
    // restarts), so drop any queued requests on boot when the setting is enabled — they're ignored.
    if (get().autoApplyKitChanges && get().kitDispatches.length > 0) set({ kitDispatches: [] });
    // ── PHASE 1 (#4072): paint from the GRAPH projection ────────────────────────────────────────
    // `--full` is 1.72 MB over 321 components and measured up to 8040ms, which is what the Studio
    // page blocked on; the projection is 33 KB. Rendering the graph needs nothing else, so set the
    // records and let the page paint while phase 2 runs.
    //
    // NO reconcile here, deliberately. `reconcileComponents` decides which built-ins are stale and
    // PUSHES the fixed copies back to the store — fed lite records it would write their empty
    // `srcText` over real source. Phase 1 only ever sets state; phase 2 owns convergence.
    const graph = await loadComponentsGraph();
    if (graph?.length) set({ components: graph });
    // ── PHASE 2: the full-fidelity read, off the critical path ──────────────────────────────────
    const [loadedC, loadedK] = await Promise.all([loadComponents(), loadKits()]);
    // Compile each KIT's MOTION library (#2942) into the managed <style> — on boot (useAppBoot calls
    // this) and on a `ui-touch` write (setAiFocused re-runs it), mirroring the variant apply.
    if (!loadedC && !loadedK) { applyAnimationsToRoot(kitAnimations(get().kits)); return; } // seed
    const rc = reconcileComponents(loadedC ?? []);
    const rk = reconcileKits(loadedK ?? []);
    // Replace only OUR notice types — theme notices (#2488) belong to hydrateThemes, which may have
    // already run (the two hydrates race on boot).
    set((s) => ({
      components: rc.records,
      kits: rk.records,
      seedNotices: [...s.seedNotices.filter((n) => n.type === "theme"), ...rk.notices, ...rc.notices],
    }));
    applyAnimationsToRoot(kitAnimations(rk.records));
    // Converge the store to the verdicts (#2483): push refreshed + missing built-ins (stamped with the
    // new seedHash), drop pristine copies of retired built-ins. User records are never pushed/dropped.
    for (const c of rc.pushes) void pushComponent(c);
    for (const id of rc.drops) void dropComponent(id);
    for (const k of rk.pushes) void pushKit(k);
    for (const id of rk.drops) void dropKit(id);
  },

  kitThemes: SEED_THEMES,

  hydrateThemes: async () => {
    const loaded = await loadThemes();
    if (!loaded) return; // bridge unreachable — keep the packaged seed (already the active set)
    const rt = reconcileThemes(loaded);
    const records = orderThemes(rt.records);
    set((s) => ({
      kitThemes: records,
      seedNotices: [...s.seedNotices.filter((n) => n.type !== "theme"), ...rt.notices],
    }));
    // Sync the shared resolvers (themeById/themeVars/ThemeScope/applyThemeToRoot) to the same set.
    setActiveKitThemes(records);
    // Converge the store (#2483): materialize refreshed + missing built-ins, drop pristine retirees.
    for (const t of rt.pushes) void pushTheme(t);
    for (const id of rt.drops) void dropTheme(id);
  },

  hydrateVariants: async () => {
    const defs = await loadVariants();
    if (defs) applyVariantsToRoot(defs); // bridge unreachable (null) → keep the current managed <style>
  },

  designContributions: [],
  addDesignContribution: (overlay) =>
    set((s) => {
      const next = [...s.designContributions.filter((o) => o.source !== overlay.source), overlay];
      applyContributionsToRoot(next);
      return { designContributions: next };
    }),
  removeDesignContribution: (source) =>
    set((s) => {
      const next = s.designContributions.filter((o) => o.source !== source);
      applyContributionsToRoot(next);
      return { designContributions: next };
    }),

  seedNotices: [],

  dismissSeedNotice: (type, id) =>
    set((s) => ({ seedNotices: s.seedNotices.filter((n) => !(n.type === type && n.id === id)) })),

  kitUsage: [],

  hydrateKitUsage: async () => {
    const loaded = await loadKitUsage();
    if (loaded) set({ kitUsage: loaded }); // bridge unreachable → keep the persisted cache
  },

  addKitUsage: (projectKey, kitId) => {
    if (!projectKey || !kitId) return;
    let added = false;
    set((s) => {
      if (s.kitUsage.some((u) => u.projectKey === projectKey && u.kitId === kitId)) return {};
      added = true;
      return { kitUsage: [...s.kitUsage, { projectKey, kitId }] };
    });
    if (added) void pushKitUsage(projectKey, kitId);
  },

  removeKitUsage: (projectKey, kitId) => {
    set((s) => ({ kitUsage: s.kitUsage.filter((u) => !(u.projectKey === projectKey && u.kitId === kitId)) }));
    void dropKitUsage(kitUsageId(projectKey, kitId));
  },

  kitDispatches: [],
  autoApplyKitChanges: true, // #2968: default ON — designer changes apply without confirmation; toggle OFF in Planner settings to gate them
  setAutoApplyKitChanges: (on) =>
    // #2975: enabling auto-apply IGNORES the pending review queue — drop the queued requests so they
    // don't linger (the banner already hides when ON; this also stops the drain re-delivering them).
    set((s) => ({ autoApplyKitChanges: on, kitDispatches: on ? [] : s.kitDispatches })),
  dismissKitChange: (changeId) =>
    set((s) => ({ kitDispatches: s.kitDispatches.filter((d) => d.change.id !== changeId) })),

  setComponent: (component, changeOverride) => {
    const before = get().components.find((c) => c.id === component.id);
    set((s) => ({
      components: s.components.some((c) => c.id === component.id)
        ? s.components.map((c) => (c.id === component.id ? component : c))
        : [...s.components, component],
    }));
    void pushComponent(component);
    if (!before) return; // a brand-new component isn't a change to fan out
    const dispatches = planPropagation(makeChange(component, before, changeOverride), get().kitUsage);
    if (dispatches.length) set((s) => ({ kitDispatches: mergeDispatches(s.kitDispatches, dispatches) }));
  },

  importKit: (kit, components) => {
    const freshId = (base: string, taken: Set<string>): string => {
      if (!taken.has(base)) return base;
      let n = 2;
      while (taken.has(`${base}-${n}`)) n++;
      return `${base}-${n}`;
    };
    const kitId = freshId(kit.id, new Set(get().kits.map((k) => k.id)));
    // An import is user-owned: never a built-in, and never carrying a seed baseline (#2483) — a stale
    // seedHash from an exported built-in must not ride along.
    const newKit: Kit = { ...kit, id: kitId, builtin: false, seedHash: undefined };
    const compIds = new Set(get().components.map((c) => c.id));
    const newComps: ComponentRecord[] = components.map((c) => {
      const id = freshId(c.id, compIds);
      compIds.add(id);
      return { ...c, id, kitId, builtin: false, seedHash: undefined };
    });
    set((s) => ({ kits: [...s.kits, newKit], components: [...s.components, ...newComps] }));
    void pushKit(newKit);
    for (const c of newComps) void pushComponent(c);
    return newKit;
  },

  dismissKitDispatch: (projectKey, changeId) =>
    set((s) => ({ kitDispatches: s.kitDispatches.filter((d) => !(d.projectKey === projectKey && d.change.id === changeId)) })),

  // #3274: empty kit ⇒ the workbench falls back to the first kit (matching the old lazy useState);
  // null component ⇒ Inspector hidden-when-empty (#3090). Neither is persisted.
  designsKitId: "",
  designsCompId: null,
  setDesignsKit: (id) => set({ designsKitId: id, designsCompId: null }),
  setDesignsComp: (id) => set({ designsCompId: id }),
  designsPreviewState: "loaded",
  setDesignsPreviewState: (s) => set({ designsPreviewState: s }),

  aiFocusedId: null,

  setAiFocused: (id, collection, opts) => {
    set({ aiFocusedId: id });
    if (!id) return; // a clear (session end) — no re-pull
    // #3545: a READ-focus (`ui-focus`) drives the preview only — nothing changed, and this fires on every
    // `get`, so a re-hydrate here would refetch the whole library every ~1.5s poll. Writes still hydrate.
    if (opts?.hydrate === false) return;
    // Re-hydrate the touched collection so the AI's edit shows without a relaunch (#2483/#2514/#2525).
    // A designer session edits via the CLI (`bsc ui set` / `set-token` / `define-variant`), which lands
    // here as a `ui-touch` — the desktop `setComponent` fan-out never runs for it. So DIFF the reloaded
    // library against the pre-hydration snapshot and fan out each component whose contract changed, so a
    // CLI edit propagates exactly like a desktop edit (#2810). Deduped by `dispatchKey`.
    const before = get().components;
    // `Promise.resolve(...)` so a test that stubs `hydrateComponents` with a plain `vi.fn()` (returns
    // undefined, not a promise) doesn't throw on `.then` — the diff simply sees no change.
    void Promise.resolve(get().hydrateComponents()).then(() => {
      const s = get();
      const fresh = s.components.flatMap((after) => {
        const b = before.find((x) => x.id === after.id);
        return b && contractChanged(b, after) ? planPropagation(makeChange(after, b), s.kitUsage) : [];
      });
      if (fresh.length) set((st) => ({ kitDispatches: mergeDispatches(st.kitDispatches, fresh) }));
    });
    if (collection === "theme") void get().hydrateThemes();
    if (collection === "variant") void get().hydrateVariants();
  },

  componentBuildStatus: {},

  setComponentBuildStatus: (id, status) =>
    set((s) => ({ componentBuildStatus: { ...s.componentBuildStatus, [id]: status } })),

  componentStateHealth: {},

  setComponentStateHealth: (id, categories) =>
    set((s) => ({ componentStateHealth: { ...s.componentStateHealth, [id]: categories } })),

  applyComponentScanResults: (results) => {
    if (results.length === 0) return; // never commit an empty flush
    set((s) => {
      const componentBuildStatus = { ...s.componentBuildStatus };
      const componentStateHealth = { ...s.componentStateHealth };
      for (const r of results) {
        componentBuildStatus[r.id] = r.status;
        componentStateHealth[r.id] = r.stateBlanks;
      }
      return { componentBuildStatus, componentStateHealth };
    });
  },

  designerOvernight: null,

  startDesignerOvernight: async (opts) => {
    if (get().designerOvernight) return; // never stack two runs onto one designer session
    const maxTurns = Math.max(1, Math.trunc(opts?.maxTurns ?? DEFAULT_MAX_TURNS));
    const budget = Math.max(0, opts?.budget ?? DEFAULT_OVERNIGHT_BUDGET);
    // The ceilings go to the LOOP STORE too, which enforces them inside `say` — a DURABLE backstop that
    // outlives this process: if the app is killed mid-run, the loop still closes itself once the ceiling
    // is hit, and a closed loop rejects every further turn. The store-side turn cap is deliberately
    // LOOSER than the pump's (`maxTurns` counts DIRECTIVES; the loop counts every turn, driver AND
    // designer — so ~2 per directive), because the pump should be what stops a healthy run; the store
    // ceiling is the net under it, not the thing that fires first.
    const args = [
      "loop", "new", DRIVER, DESIGNER,
      "--seed", OVERNIGHT_SEED,
      "--until", "false",
      "--max-turns", String(maxTurns * 2 + 2),
    ];
    if (budget > 0) args.push("--budget", String(budget));
    let loopId: number | null;
    try {
      const printed = (await bsc(null, args)).trim().match(/\d+/); // `bsc loop new` prints the new id
      loopId = printed ? Number(printed[0]) : null;
    } catch {
      loopId = null; // bridge/binary absent
    }
    if (loopId === null || !Number.isFinite(loopId)) return; // stay OFF rather than fake a run
    set({ designerOvernight: { loopId, maxTurns, budget, cursor: 0, queue: [], stopping: false, startedAt: Date.now() } });
  },

  stopDesignerOvernight: async () => {
    const run = get().designerOvernight;
    if (!run) return;
    set({ designerOvernight: { ...run, stopping: true } }); // halts dispatch before the CLI round-trip
    await bscRun(null, ["loop", "stop", String(run.loopId)]);
  },

  endDesignerOvernight: () => set({ designerOvernight: null }),

  setDesignerOvernightQueue: (queue) =>
    set((s) => (s.designerOvernight ? { designerOvernight: { ...s.designerOvernight, queue } } : {})),

  advanceDesignerOvernight: () =>
    set((s) => (s.designerOvernight ? { designerOvernight: { ...s.designerOvernight, cursor: s.designerOvernight.cursor + 1 } } : {})),
});

