// ThemesMenu (#2834) — the right-pane theme navigator for the Design Studio's theme try-on. In preview
// mode the inspector is replaced by this menu: the themes grouped by their design group (#2749's `tech`,
// the same axis the left kits rail groups by), each row a live mini-swatch + label + surface glyph.
// Selecting a row drives the center preview's retint (`onSelect` → the studio's `kitTheme`). Reuses the
// shared rail scaffold (GraphRail · RailGroupHeader · RailRow) so it reads exactly like the components
// rail — just mirrored into the right pane (border flipped to the left edge).
import { useMemo, useState } from "react";
import { GraphRail } from "@/shared/ui/layouts/GraphRail";
import { RailGroupHeader } from "@/shared/ui/layouts/RailGroupHeader";
import { RailRow } from "@/shared/ui/layouts/RailRow";
import { ColorSwatch } from "@/shared/ui/controls/ColorSwatch";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { ThemeScope } from "@/shared/ui/kit";
import { groupThemes, type KitThemeRecord } from "./lib/themes";

/** A live 3-bar palette chip for a theme: surface · accent · text, read through a <ThemeScope> so it
 *  reflects the theme's own token overrides (an empty-`vars` base theme inherits the current tokens). */
function ThemeSwatch({ id }: { id: string }) {
  return (
    <ThemeScope theme={id} style={{ display: "inline-flex", gap: 2, padding: 0, borderRadius: 3 }}>
      <ColorSwatch color="var(--bg-panel)" size={9} />
      <ColorSwatch color="var(--accent)" size={9} />
      <ColorSwatch color="var(--fg)" size={9} />
    </ThemeScope>
  );
}

/** The right-pane themes menu. Grouped by design group (#2749); selecting a row retints the preview. */
export function ThemesMenu({ themes, activeId, onSelect }: {
  themes: KitThemeRecord[];
  /** The currently-applied theme id — its row shows the canonical `.on` selection wash. */
  activeId: string;
  /** Apply a theme (drives the center preview's `themeVars`/surface). */
  onSelect: (id: string) => void;
}) {
  const groups = useMemo(() => groupThemes(themes), [themes]);
  // Collapse state per design group (default OPEN, like the Designs rail's tech groups).
  const [collapsed, setCollapsed] = useState<Record<string, boolean>>({});
  return (
    <GraphRail
      label="Themes"
      count={themes.length}
      // Mirror the left rail into the right pane: drop the default right border, add the left edge so it
      // reads as the inspector column (the components rail keeps its border on the right).
      style={{ borderRight: "none", borderLeft: "1px solid var(--border)" }}
    >
      {groups.map((g) => {
        const open = !collapsed[g.tech];
        return (
          <Box key={g.tech} data-tech={g.tech}>
            <RailGroupHeader
              className="tm-grouphead"
              collapsible
              open={open}
              onToggle={() => setCollapsed((c) => ({ ...c, [g.tech]: !c[g.tech] }))}
              count={g.themes.length}
              title={`design group: ${g.label}`}
            >
              {g.label}
            </RailGroupHeader>
            {open && g.themes.map((t) => (
              <RailRow
                key={t.id}
                active={t.id === activeId}
                onClick={() => onSelect(t.id)}
                leading={<ThemeSwatch id={t.id} />}
                trailing={
                  <Text as="span" mono size="xxs" tone="dim" title={`${t.base ?? "dark"} surface`}>
                    {(t.base ?? "dark") === "light" ? "◑" : "◐"}
                  </Text>
                }
                title={`${t.label} — ${t.base ?? "dark"} surface`}
                data-theme-id={t.id}
              >
                {t.label}
              </RailRow>
            ))}
          </Box>
        );
      })}
    </GraphRail>
  );
}

runtime.features/designs/useDesignerLoopPump.ts:
// The designer-loop PUMP (#3292/#3304, epic #3260) — the app-side driver that keeps the live Design Studio
// session iterating on a `bsc loop`. It is to a designer loop what `useDirectorPump` is to a fleet: poll →
// decide (a pure decider) → actuate. It drives the LIVE PTY (not a headless agent) because the designer
// live-restyles the RUNNING app — the actor has to be the running session.
//
// TWO MODES over one poll:
//  · INTERACTIVE (#3292, the default) — on the DRIVER's turn post "continue" and inject a GENERIC
//    next-change prompt; the human picks what gets worked on by talking to the session.
//  · OVERNIGHT / QUEUE (#3304) — opt-in, started from the banner. The run carries a ranked directive
//    queue built ONCE from the design system's own measured gaps (`buildDesignerQueue` over
//    `bsc ui components --coverage` + `bsc ui resolve`), and each driver turn captures a fresh
//    `bsc shot`, posts the directive as the driver's turn (shot attached), injects it, and advances the
//    cursor. It stops on the directive ceiling or when the queue drains.
//
// One tick: find the open `driver ↔ designer` loop (`bsc loop list`), read its turns (`bsc loop show`), and
// decide. On a stall either mode re-injects; otherwise it waits — the turn-flip the designer causes by
// recording is the "prompt me again" signal, so the pump never floods.
//
// STOPPING (the property that matters most for an unattended run). Four independent brakes, so no single
// failure leaves a loop spending money:
//  1. `bsc loop stop` — the banner's Stop pill, out-of-band, reachable at any time.
//  2. The pump's own ceiling — `decideOvernightAction` returns `stop` at the directive cap or on a drained
//     queue, and the pump then requests the halt. Because that verdict is recomputed every tick from
//     durable state, a swallowed CLI error simply RETRIES on the next tick rather than being lost.
//  3. The loop store's `--max-turns`/`--budget`, enforced inside `say` — durable, and it outlives this
//     process, so even a killed app cannot leave the loop runnable.
//  4. The run state is never persisted, so overnight mode cannot auto-start or survive a restart.
// The local run state is cleared only once the loop is OBSERVABLY gone, so a "stopping" run never silently
// hands its still-open loop back to the interactive path (which has no ceiling of its own).

import { useRef } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import { useAppStore } from "@/store";
import { bscJson, bscRun } from "@/shared/lib/core/bsc";
import { injectPrompt } from "@/shared/lib/fleet/paneInject";
import { DESIGN_STUDIO_SESSION_ID } from "@/shared/lib/session/systemSessions";
import {
  decideOvernightAction, driverSay, pickDesignerLoop,
  DEFAULT_NUDGE_MS, DRIVER, DESIGNER, type LoopRow, type LoopTurn,
} from "./lib/designerLoopDrive";
import { buildDesignerQueue, parseCoverage, parseResolve, type DesignDirective } from "./lib/designerQueue";
import { publishDesignerLoopState } from "./useDesignerLoopState";

const POLL_MS = 3000;

/** Frames in a MOTION directive's grounding burst — "a few frames across an animation" (#3261). */
const BURST_FRAMES = 6;

/** Capture the preview's real pixels for this turn; `null` when the app can't snapshot (never fatal —
 *  an ungrounded turn is worse than no turn, but a stalled RUN is worse than both, so we proceed). */
async function captureShot(burst: boolean): Promise<string | null> {
  const args = ["shot", "preview"];
  if (burst) args.push("--frames", String(BURST_FRAMES));
  const res = await bscJson<{ path?: string; frames?: { path?: string }[] } | null>(null, args, null);
  if (!res) return null;
  if (typeof res.path === "string") return res.path; // single frame → { path, w, h }
  const first = res.frames?.[0]?.path; //                burst      → { frames: [ … ] }
  return typeof first === "string" ? first : null;
}

/** Build the run's ranked queue from the design system's OWN measured gaps. Both reports are tolerated as
 *  absent (`parseCoverage`/`parseResolve` yield `null`), in which case the queue is just motion + polish. */
async function buildQueue(components: { id: string; name: string; role?: string }[], round: number): Promise<DesignDirective[]> {
  const [cov, res] = await Promise.all([
    bscJson<unknown>(null, ["ui", "components", "--coverage"], null),
    bscJson<unknown>(null, ["ui", "resolve"], null),
  ]);
  return buildDesignerQueue({ coverage: parseCoverage(cov), resolve: parseResolve(res), components, round });
}

/** Drive the open designer loop from the long-lived Design Studio workspace (mounted in `DesignsWorkbench`).
 *  A no-op whenever there is no open `driver ↔ designer` loop, so it costs one lightweight `bsc loop list`
 *  poll while idle. */
export function useDesignerLoopPump(): void {
  const inFlight = useRef(false); // one actuation at a time — a slow inject must not double-fire
  const lastInjectAt = useRef(0);

  usePoll(
    async (isCancelled) => {
      if (inFlight.current) return;
      const loops = await bscJson<LoopRow[]>(null, ["loop", "list", "--open", "--json"], []);
      if (isCancelled()) return;
      const loop = pickDesignerLoop(loops);
      // Read the run FRESH each tick (not off a render closure) so a Stop lands on the very next tick.
      const s = useAppStore.getState();
      const run = s.designerOvernight;
      if (!loop) {
        lastInjectAt.current = 0; // no active loop → reset the stall clock
        publishDesignerLoopState(null); // #3850: the banner's only source — collapse it to the idle pill
        if (run) s.endDesignerOvernight(); // the run's loop is closed/gone → leave overnight mode
        return;
      }
      // The pump drives ONLY a loop this app started (#3850). A run whose loop is no longer THE open loop
      // is over. An ORPHAN open loop — CLI-created, or one that outlived a restart — is deliberately NOT
      // adopted: #3304's fourth brake is that run state is never persisted, so overnight mode cannot
      // auto-start or survive a restart, and adopting an orphan would resume spending money after one. The
      // banner still shows it with a reachable Stop, and the loop's own durable --max-turns/--budget apply.
      const overnight = run && run.loopId === loop.id ? run : null;
      if (run && !overnight) s.endDesignerOvernight();

      // Drive ONLY a loop this app started. An orphan is published above (observable + stoppable) but never
      // adopted — see the note on `overnight` for why that brake matters.
      if (!overnight) return;

      // A halt was requested — dispatch NOTHING and keep re-issuing the stop until the loop is observably
      // gone (the branch above then clears the run). Idempotent, so retrying costs nothing.
      if (overnight.stopping) {
        await bscRun(null, ["loop", "stop", String(loop.id)]);
        return;
      }

      const show = await bscJson<{ turns: LoopTurn[]; total_cost?: number } | null>(
        null, ["loop", "show", String(loop.id), "--json"], null,
      );
      if (isCancelled() || !show) return;
      const turns = show.turns ?? [];
      // #3850: publish what this read already knows — the banner renders it instead of running its own
      // `loop list` + `loop show`. Published for EVERY open loop, including an orphan we won't drive, so
      // the pill (and its Stop) stays reachable for the one case the human is the only brake for.
      publishDesignerLoopState({
        id: loop.id,
        changes: turns.filter((t) => t.participant === DESIGNER).length,
        cost: show.total_cost ?? 0,
      });

      // Build the queue ONCE per run, before the first dispatch. Building it once (rather than per turn) is
      // what makes `queue[cursor]` mean what `decideOvernightAction` says it means: a rebuilt queue shrinks
      // as findings are fixed, which would slide the cursor over unfixed work.
      if (overnight.queue.length === 0) {
        const comps = s.components.filter((c) => c.kitId === s.designsKitId);
        const queue = await buildQueue(comps, 0);
        if (isCancelled()) return;
        if (queue.length === 0) {
          await s.stopDesignerOvernight(); // nothing to work on — a good, immediate end
          return;
        }
        s.setDesignerOvernightQueue(queue);
        return; // dispatch on the next tick, against the installed queue
      }

      const action = decideOvernightAction({
        loop, turns, now: Date.now(), lastInjectAt: lastInjectAt.current, nudgeAfterMs: DEFAULT_NUDGE_MS,
        queue: overnight.queue, cursor: overnight.cursor, maxTurns: overnight.maxTurns,
      });

      if (action.kind === "wait" || action.kind === "idle") return;
      if (action.kind === "stop") {
        await s.stopDesignerOvernight(); // budget reached or queue drained
        return;
      }

      inFlight.current = true;
      try {
        if (action.kind === "direct") {
          // Ground the turn in real pixels BEFORE prompting, so the driver's turn records the state the
          // directive is being given against (the shot is the ground truth, not the description).
          const shot = await captureShot(action.burst);
          if (isCancelled()) return;
          const say = ["loop", "say", String(loop.id), "--as", DRIVER, driverSay(action.directive)];
          if (shot) say.push("--shot", shot);
          await bscRun(null, say);
          if (isCancelled()) return;
          await injectPrompt(DESIGN_STUDIO_SESSION_ID, action.prompt);
          lastInjectAt.current = Date.now();
          useAppStore.getState().advanceDesignerOvernight();
          return;
        }
        // The only other actuation is `nudge` — re-prompt the same (still-designer) turn WITHOUT posting a
        // driver turn, so a stall recovery doesn't skew the transcript's alternation.
        await injectPrompt(DESIGN_STUDIO_SESSION_ID, action.prompt);
        lastInjectAt.current = Date.now();
      } finally {
        inFlight.current = false;
      }
    },
    POLL_MS,
    [],
  );
}

runtime.features/designs/useDesignerLoopState.ts:
// The ONE owner of "the current designer loop" (#3850) — published by the pump, read by the banner.
//
// Both consumers used to derive it independently: the banner ran `bsc loop list` + `bsc loop show`, and the
// pump ran the same two. Four process spawns per cycle for one fact, showing up in the #3842 perf log as
// identical-duration pairs. The duplication was a SYMPTOM — shared derived state with no owner, so every
// consumer re-derived it.
//
// The PUMP is the owner, because it already reads both and reads them freshest. It publishes here; the
// banner subscribes and makes no `bsc` calls at all. Four spawns per cycle become two.
//
// Why the pump doesn't just consume a shared snapshot the other way round: its decision depends on seeing
// the turn flip PROMPTLY. Driving off state that could be a poll-interval stale would let it dispatch the
// next directive before the designer's turn landed — the exact flooding the pump's turn-order signal exists
// to prevent. So the actor keeps its own read and shares the result; the display follows the actor.
//
// Deliberately a module-level observable rather than a Zustand slice: one producer, one consumer, ephemeral
// polled state — and the store's own rule is that persisted app state is not a cache for derived reads.

import { useSyncExternalStore } from "react";

/** The open designer loop as the banner needs to render it. `null` when no loop is open. */
export interface DesignerLoopState {
  id: number;
  /** The designer's recorded turns — each one a shot-paired change. */
  changes: number;
  cost: number;
}

let current: DesignerLoopState | null = null;
const listeners = new Set<() => void>();

/** Publish the loop state observed this tick. Called by the pump — the one reader of `bsc loop`.
 *  Skips notifying when nothing changed, so a steady loop doesn't re-render the banner every tick. */
export function publishDesignerLoopState(next: DesignerLoopState | null): void {
  const same = current === next
    || (!!current && !!next && current.id === next.id
        && current.changes === next.changes && current.cost === next.cost);
  if (same) return;
  current = next;
  for (const fn of listeners) fn();
}

function subscribe(onChange: () => void): () => void {
  listeners.add(onChange);
  return () => { listeners.delete(onChange); };
}

/** Subscribe to the published loop state. The banner's only source.
 *
 *  `useSyncExternalStore` rather than useState + useEffect: this IS an external store, and the effect
 *  form had to re-sync with a synchronous `setState` on mount to cover a publish that landed while the
 *  component was unmounted — which is both a cascading-render smell and still racy (a publish between
 *  render and subscribe is lost). This has neither problem, and `publishDesignerLoopState` only swaps
 *  `current` when a value actually changed, so the snapshot identity is stable enough to read directly. */
export function useDesignerLoopState(): DesignerLoopState | null {
  return useSyncExternalStore(subscribe, () => current);
}

runtime.features/designs/usePreviewData.ts:
// usePreviewData (#2940 / #3439) — resolves a component's preview data into the override map
// `ComponentPreviewFrame` feeds `componentPreviewFiles`, in the resolution order
//
//     curated binding (#2940)  →  shape tier (#3439)  →  samplePropValue (the component's own sample)
//
// 1. A curated `PREVIEW_BINDINGS` row runs the bound librarian algorithm's `vizCode` in the sandbox,
//    normalizes it (`vizRunToDataset`), shapes it for the prop (`adaptDataset`) — ASYNC.
// 2. Otherwise, if the component declares a supported `DataShape`, the SHAPE TIER feeds it real
//    algorithm-generated data with no per-component row (`shapePreviewData`) — SYNC (the trace programs
//    run on the main thread).
// 3. Otherwise `{}` → the component's own sample shows.
//
// Fail-SOFT throughout: a missing impl/`vizCode`, a sandbox error, an unusable dataset, or a shape with
// no landable prop all resolve to `{}`, so a preview is never broken.
import { useEffect, useMemo, useState } from "react";
import { KNOWLEDGE, implById, runInSandbox, vizRunToDataset, datasetForStructure } from "@/features/algorithms";
import type { ComponentRecord } from "./lib/model";
import { bindingFor, adaptDataset } from "./lib/previewBindings";
import { shapePreviewData } from "./lib/shapePreview";

const EMPTY: Record<string, string> = {};

/** The preview-data override map for `comp` (`{ prop: JS-source literal }`), or `{}` until/unless a bound
 *  algorithm or a supported shape resolves. Safe to pass straight to `componentPreviewFiles(..., previewData)`. */
export function usePreviewData(comp: ComponentRecord): Record<string, string> {
  const binding = bindingFor(comp.kitId, comp.name);
  const [data, setData] = useState<Record<string, string>>(EMPTY);

  // Shape tier (#3439): SYNC — only when there is NO curated binding (that path wins). The trace programs
  // run on the main thread, so this needs no effect; memoized on the component identity that determines it.
  const shapeData = useMemo(
    () => (binding ? EMPTY : shapePreviewData(comp, datasetForStructure)),
    // eslint-disable-next-line react-hooks/exhaustive-deps -- comp identity (kitId/name/shapes/props) determines it
    [binding, comp.kitId, comp.name],
  );

  // Key the resolve on the identity that determines the result — the bound algorithm + prop. A different
  // component (no binding) resets to EMPTY synchronously below via the early clear.
  const key = binding ? `${binding.algorithm}:${binding.prop}` : "";

  useEffect(() => {
    /* eslint-disable react-hooks/set-state-in-effect -- intentional reset: clear stale data when the
       bound component changes or its algorithm has no runnable vizCode (mirrors ComponentPreviewFrame). */
    if (!binding) { setData(EMPTY); return; }
    const impl = implById(KNOWLEDGE, binding.algorithm);
    const vizCode = impl?.vizCode?.trim();
    if (!vizCode) { setData(EMPTY); return; }
    /* eslint-enable react-hooks/set-state-in-effect */

    let cancelled = false;
    void runInSandbox(vizCode)
      .then((run) => {
        if (cancelled) return;
        const value = adaptDataset(vizRunToDataset(run), binding.adapter);
        setData(value == null ? EMPTY : { [binding.prop]: JSON.stringify(value) });
      })
      .catch(() => { if (!cancelled) setData(EMPTY); });

    return () => { cancelled = true; };
    // `key` captures the binding's algorithm+prop; `comp.kitId`/`comp.name` feed `binding` above.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);

  return binding ? data : shapeData;
}

runtime.features/github/store.ts:
// GitHub feature store slice (#1309) — connection state, token (+ repo-scoped tokens), user, repos,
// active repo, and the page mode. Extracted from the former grab-bag `github` slice (whose residual
// — app-chrome + tunnel state — is now store/slices/shell.ts). Composed by store/index.ts.
import type { StateCreator } from "zustand";
import type { AppStore, GithubUser, GithubRepo } from "@/store/types";
import type { GithubState, MinimalGhProject } from "@/shared/lib/github/githubState";
import { pushGithubState } from "@/shared/lib/github/githubStateBridge";

export interface GithubSlice {
  githubConnected: boolean;
  githubToken: string;
  // The last-known GitHub board state (#2446): the minimal per-project records from the most recent
  // successful projects fetch + when it landed. Persisted (the fast-paint cache — survives restart
  // and renders as a stale-marked overlay while logged out / pre-refresh) and mirrored into the
  // bsc-project store so the durable copy is `bsc`-reachable. `null` until a fetch ever lands.
  // Deliberately NOT cleared by disconnectGithub — surviving the logged-out state is its point.
  githubState: GithubState | null;
  /** Overwrite the records wholesale (a fresh fetch), stamping `fetchedAt` and mirroring to bsc. */
  setGithubState: (records: MinimalGhProject[]) => void;
  // Repo-scoped GitHub credentials (#158): per-`owner/name` fine-grained token; persisted, never
  // logged. A request targeting that repo uses it instead of the global PAT.
  repoGithubTokens: Record<string, string>;
  setRepoGithubToken: (repo: string, token: string | null) => void;
  githubUser: GithubUser | null;
  githubRepos: GithubRepo[];
  activeRepoName: string;
  githubPageMode: "summary" | "projects" | "repos";
  setGithubPageMode: (v: "summary" | "projects" | "repos") => void;
  setGithubToken: (token: string) => void;
  setGithubUser: (user: GithubUser | null) => void;
  setGithubRepos: (repos: GithubRepo[]) => void;
  setActiveRepo: (name: string) => void;
  setGithubConnected: (connected: boolean) => void;
  disconnectGithub: () => void;
  markGithubTokenInvalid: () => void;
}

export const createGithubSlice: StateCreator<AppStore, [], [], GithubSlice> = (set) => ({
  githubConnected: false,
  githubToken: "",
  githubState: null,
  setGithubState: (records) => {
    const next: GithubState = { records, fetchedAt: Date.now() };
    set({ githubState: next });
    void pushGithubState(next); // mirror the durable copy into the bsc-project store (#2446)
  },
  repoGithubTokens: {},
  setRepoGithubToken: (repo, token) =>
    set((s) => {
      const next = { ...s.repoGithubTokens };
      if (token && token.trim()) next[repo] = token.trim();
      else delete next[repo];
      return { repoGithubTokens: next };
    }),
  githubUser: null,
  githubRepos: [],
  activeRepoName: "",
  githubPageMode: "summary",
  setGithubPageMode: (v) => set({ githubPageMode: v }),
  setGithubToken: (token) => set({ githubToken: token }),
  setGithubUser: (user) => set({ githubUser: user }),
  setGithubRepos: (repos) => set({ githubRepos: repos }),
  setActiveRepo: (name) => set({ activeRepoName: name }),
  setGithubConnected: (connected) => set({ githubConnected: connected }),
  disconnectGithub: () => set({
    githubConnected: false,
    githubToken: "",
    repoGithubTokens: {},
    githubUser: null,
    githubRepos: [],
    activeRepoName: "",
  }),
  // A request returned 401 (token expired/revoked) — flip to disconnected so the UI prompts a
  // reconnect instead of 401-looping; cached user/repos stay for context until reconnect.
  markGithubTokenInvalid: () => set((s) => (s.githubConnected ? { githubConnected: false } : {})),
});

runtime.features/glance/GlanceCanvas.tsx:
// Glance canvas (#2206) — the transform-based project-network graph: SVG dependency edges + project
// node cards. Renders the WORLD-LAYER content (grid + edges + nodes); the pan/zoom viewport frame is
// owned by the shared GraphCanvas template + useGraphViewport in the parent (#2208). Node = project;
// edge = dependency contract. The fixed hint/legend overlays are GlanceOverlays (drawn over, untransformed).
import { useCallback, useMemo, useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { GlanceStreamMorph } from "./GlanceStreamMorph";
import { GlancePreviewMorph } from "./GlancePreviewMorph";
import type { PreviewSource } from "@/shared/lib/preview/previewSource";
import type { PreviewReview } from "./usePreviewReview";
import { ROLE_COLOR, LIFECYCLE_META, HEALTH_META, ACTIVITY_META, EDGE_META, LIBRARY_META, MCP_META, SERVICE_META, isBandNode, bandNodeMeta, nodeStateWord, showsBuildingPulse, libraryGraphOf, isLibraryEdge, NW, NH, edgeGeom, type GraphModel, type GHealth, type GLibraryGraph } from "./lib/glanceGraph";
import { partAroundPanel, type MorphRect } from "./lib/glancePush";
import { unionRects } from "./lib/morphGrid";
import type { DockPlan } from "./GlanceChatDock";
import { archetypeById, hueColor } from "@/features/teams";
import { GlanceNode } from "./GlanceNode";

const ERR = "var(--graph-health-error)";
// The legend lists the states a node can actually READ as. `complete` leads (#4048): the rest of the
// column is a severity ramp — running clean → degraded → failing — and complete is the one entry that
// is not on it at all. It is the terminal, best outcome, so it belongs at the top rather than tucked
// between "fine" and "degrading".
//
// `off` has no row (#4042): it is the ABSENCE of a live session — deactivated, never launched, or
// structural furniture — and the node conveys it by dimming rather than by a colour, so a swatch would
// key something nothing paints.
//
// `modifying` (#4052) sits directly under `complete` because it IS complete's colour — the pair reads
// "on its way" above "arrived", and only the swatch's motion separates them. Putting anything between
// them would break that reading.
const HEALTH_ROWS: GHealth[] = ["complete", "modifying", "healthy", "warning", "error"];

// The neighbour-parting motion is driven off the SAME easing + duration as the panel's grow (the
// `.glance-card` transition in glance.css) — keep these in sync — so the panel growing and the graph
// parting read as one coordinated motion instead of two clocks racing (the old .2s vs .4s mismatch).
const MORPH_EASE = ".4s cubic-bezier(.22, .61, .36, 1)";

const REST_N = 0.14, REST_E = 0.06;
// The L0 second column: LIFECYCLE (#4066). The lifecycle chip (#4062) is a COLOURED label on every
// classified node — five accents that mean nothing without a key, which is exactly what a legend is
// for. (#4064 briefly put ACTIVITY here instead: a plain word with no colour mapping, so the column
// taught nothing a reader could not already read off the card.)
//
// Derived from LIFECYCLE_META rather than a second hand-maintained list, so the legend cannot drift
// from what the nodes actually paint.
const LIFECYCLE_ROWS_L0: [string, string][] =
  Object.values(LIFECYCLE_META).map((m) => [m.label, m.color]);
const EDGE_ROWS_L0: [string, string, string][] = [
  [EDGE_META.api.label, EDGE_META.api.color, EDGE_META.api.dash],
  [EDGE_META.data.label, EDGE_META.data.color, EDGE_META.data.dash],
  [EDGE_META.events.label, EDGE_META.events.color, EDGE_META.events.dash],
  [EDGE_META["uses-kit"].label, EDGE_META["uses-kit"].color, EDGE_META["uses-kit"].dash], // #2571 kit-consumer edge
  [EDGE_META.requires.label, EDGE_META.requires.color, EDGE_META.requires.dash],           // #3119 cross-graph library edge
  [EDGE_META["uses-mcp"].label, EDGE_META["uses-mcp"].color, EDGE_META["uses-mcp"].dash], // #3786 external mcp-contract edge
  ["cycle", "var(--graph-health-error)", "7 6"],
];
// The fenced-band node dimensions (#3119 + #3786) — the library flavours (kit/algorithm/sound) + the
// external contracts (mcp + service), each its own accent + glyph. Shown as a distinct legend column at
// L0 (not while drilled into a fleet). The `uses-mcp`/`uses-service` edges share the "contracts with"
// label, so they get ONE edge legend row (uses-mcp above); the node dimensions distinguish them here.
const LIBRARY_GRAPHS: GLibraryGraph[] = ["ui", "algo", "sound"];
const LIBRARY_ROWS: [string, string, string][] = [
  ...LIBRARY_GRAPHS.map((g): [string, string, string] => [LIBRARY_META[g].kindLabel, LIBRARY_META[g].color, LIBRARY_META[g].marker]),
  [MCP_META.kindLabel, MCP_META.color, MCP_META.marker],         // #3786 external mcp-contract node
  [SERVICE_META.kindLabel, SERVICE_META.color, SERVICE_META.marker], // #3786 Phase 2 external service-contract node
];
// Fleet-drill (L1) legend: the role colour buckets read as agent FUNCTION groups; the edge rows are the
// Org relationship archetypes actually present in the drilled fleet (#2561).
const ROLE_ROWS_L1: [string, string][] = [["orchestrate", ROLE_COLOR.infra], ["build", ROLE_COLOR.service], ["verify", ROLE_COLOR.data], ["flow", ROLE_COLOR.client]];
const ARCH_DASH: Record<string, string> = { solid: "", dashed: "6 5", dotted: "2 4", gated: "", resource: "4 4" };

interface CanvasProps {
  model: GraphModel;
  /** True during a pan-drag — suppresses the click that ends it (from the shared viewport). */
  dragMoved: React.MutableRefObject<boolean>;
  focus: { nodes: Set<string>; edges: Set<string> } | null;
  selNodeId: string | null;
  selEdgeId: string | null;
  /** True while DRILLED INTO A FLEET (L1) — the graph is showing worker/director agents rather than
   *  the project network. Only the fleet's own nodes carry a live session, so it gates the
   *  building pulse (#4015): a PROJECT node on L0 must never animate.
   *
   *  An explicit prop rather than inferring from `n.category`: a project whose lifecycle was never
   *  classified has no category either, so the inference would quietly animate exactly the L0 nodes
   *  it was meant to exclude. */
  fleet?: boolean;
  onHoverNode: (id: string | null) => void;
  onHoverEdge: (id: string | null) => void;
  onSelectNode: (id: string) => void;
  onSelectEdge: (id: string) => void;
  /** The graph's current zoom (`vp.view.scale`) — threaded to the terminal morph so its corner-resize
   *  converts a screen-pixel drag into world units. */
  zoom?: number;
  /** The live agents whose terminals are morphed open IN the graph (#2534 → MULTI, #3361) — each an
   *  oversized node grown into its GRID SLOT. Empty = none open. `slot` is computed by the workspace
   *  from the grid anchored on the FIRST opened node, so two morphs can never overlap. */
  chats?: { nodeId: string; paneId: string; name: string; role?: string; slot: MorphRect }[];
  /** Collapse ONE morph back into its node (keeps its PTY alive). */
  onCloseChat?: (nodeId: string) => void;
  /** END one open session (#3049) — kill its PTY + drop the cell from the live set, so a soft-locked
   *  agent is fully torn down and triage can be relaunched. */
  onEndChat?: (nodeId: string) => void;
  /** A resize drag on any morph — resizes the grid's SHARED cell, so every open morph moves as one. */
  onResizeCell?: (w: number, h: number) => void;
  /** Per-worker owned issues (#4102) — `planFor(nodeId)` yields that stream's Plan-screen data, or
   *  undefined for a node that owns none (studio / debug sessions). Resolved ONCE at the workspace so
   *  opening six morphs costs no extra queries. */
  planFor?: (nodeId: string) => DockPlan | undefined;
  /** The PREVIEW node morphed open (#2623) — the finished app rendered IN the graph, at its node's
   *  world coords. `source` is null until the verify-build produces one. Null = none open. */
  preview?: { nodeId: string; name: string; source: PreviewSource | null; building?: boolean; onBuild?: () => void; review?: PreviewReview } | null;
  onClosePreview?: () => void;
}

/** The world-layer content — placed inside GraphCanvas's transformed world box. */
export function GlanceCanvas(p: CanvasProps) {
  const { model, focus } = p;
  // The node whose terminal is morphed open (#2534) — resolved from the live model so its world coords
  // (and thus the card's position) always track the current graph.
  // The open morphs, resolved against the live model so each card's return box tracks its node (#3361).
  const chats = p.chats ?? [];
  const openChats = chats.flatMap((c) => {
    const node = model.nodes.find((n) => n.id === c.nodeId);
    return node ? [{ ...c, node }] : [];
  });
  const openChatIds = useMemo(() => new Set(openChats.map((c) => c.nodeId)), [openChats]);
  // The PREVIEW node morphed open (#2623) — resolved from the live model so its card tracks the graph.
  const previewNode = p.preview ? model.nodes.find((n) => n.id === p.preview!.nodeId) ?? null : null;
  // A node/edge click: suppressed after a pan-drag, and stopPropagation so it doesn't bubble to the
  // backdrop deselect (Glance nodes aren't [data-node]) (#2232).
  const click = (fn: () => void) => (e: React.MouseEvent) => { e.stopPropagation(); if (!p.dragMoved.current) fn(); };

  // The open terminal panel's world box (#2662, reported by the morph) — the graph PARTS around it in
  // four rigid curtains (#2671): every neighbour clears the panel by construction (no clipping) and each
  // curtain keeps its spacing (no node-into-node clipping). Edges of shifted nodes follow.
  // #3361: each open morph reports its own world box; the graph parts around their UNION — one region,
  // so the four-curtain model is unchanged whether one morph is open or six. Keyed by paneId so a
  // morph's report replaces its own previous one; it reports null the instant it starts collapsing, so
  // the neighbours part back in step with the shrink rather than a full exit animation later.
  const [morphRects, setMorphRects] = useState<Record<string, MorphRect | null>>({});
  const reportRect = useCallback((paneId: string) => (rect: MorphRect | null) => {
    setMorphRects((prev) => (prev[paneId] === rect ? prev : { ...prev, [paneId]: rect }));
  }, []);
  const morphRect = useMemo(
    () => unionRects(Object.values(morphRects).filter((r): r is MorphRect => !!r)),
    [morphRects],
  );
  const nodeById = useMemo(() => new Map(model.nodes.map((n) => [n.id, n])), [model.nodes]);
  const pushMap = useMemo(() => {
    if (!morphRect) return new Map<string, { dx: number; dy: number }>();
    return partAroundPanel(model.nodes, morphRect, openChatIds);
  }, [morphRect, model.nodes, openChatIds]);

  // The dimension(s) present in the fenced band (#3119 + #3786) — library graphs (kit/algo/sound) AND/OR
  // the external MCP contract — drive its accent + header. A single-dimension band reads in that
  // dimension's colour + name (kit-only stays cyan "UI KITS", byte-identical to #3007; mcp-only reads
  // amber "MCP SERVERS"); a mixed band is neutral "LIBRARIES".
  const bandDims = useMemo(() => {
    const s = new Set<string>();
    for (const n of model.nodes) {
      const g = libraryGraphOf(n);
      if (g) s.add(g);
      else if (n.kind === "mcp") s.add("mcp");
      else if (n.kind === "service") s.add("service");
    }
    return [...s];
  }, [model.nodes]);
  const soleDim = bandDims.length === 1 ? bandDims[0] : null;
  const bandMeta = soleDim === "mcp" ? MCP_META : soleDim === "service" ? SERVICE_META : soleDim ? LIBRARY_META[soleDim as GLibraryGraph] : null;
  const bandColor = bandMeta ? bandMeta.color : "var(--fg-muted)";
  const bandLabel = bandMeta ? bandMeta.bandLabel : "LIBRARIES";

  return (
    <>
      {/* The dotted graph-paper backdrop is owned by the shared GraphCanvas (an infinite viewport
          grid, `grid gridSize={28}` in GlanceWorkspace) — #2418, same as the org designer (#2389). */}

      {/* edges */}
      <svg width={model.worldW} height={model.worldH} style={{ position: "absolute", left: 0, top: 0, overflow: "visible" }}>
        {/* The fenced LIBRARY band (#3007, generalized #3119) — drawn FIRST so it sits behind the edges +
            nodes. A faint wash, a dashed divider at the fence, and a small header label, mirroring the
            Design Studio composition swimlanes so the lifted library nodes read as a distinct top zone.
            Colour + label follow the dimension(s) present (kit-only ⇒ cyan "UI KITS", unchanged). */}
        {model.kitBand && (
          <g className="glance-kit-band" style={{ pointerEvents: "none" }}>
            <rect x={0} y={model.kitBand.y0} width={model.worldW} height={model.kitBand.y1 - model.kitBand.y0} className="glance-kit-band-bg" style={{ fill: bandColor }} />
            <line x1={0} y1={model.kitBand.y1} x2={model.worldW} y2={model.kitBand.y1} className="glance-kit-band-divider" style={{ stroke: bandColor }} />
            <text x={16} y={model.kitBand.y0 + 22} className="glance-kit-band-label" style={{ fill: bandColor }}>{bandLabel}</text>
          </g>
        )}
        {model.edges.map((e) => {
          const meta = EDGE_META[e.kind];
          // A fleet-drill (L1) edge is fully styled by its Org relationship archetype (#2561/#2565) —
          // colour by hue, dash by the archetype's style — so `kind` is vestigial at L1; a project (L0)
          // edge keeps the kind colour + dash.
          const arch = e.archetype ? archetypeById(e.archetype) : undefined;
          const inFocus = focus ? focus.edges.has(e.id) : true;
          // A cyclical archetype (iterates, #2578) is a DELIBERATE loop — keep the archetype's hue (not
          // the red hazard tint) but the animated cycle dash, so it reads as an intentional iteration loop.
          const loop = e.isCycle && !!arch?.cyclical;
          // A LIBRARY edge (#3119) is tinted by its TARGET node's graph accent — uses-kit→ui cyan,
          // requires→algo violet / →sound pink — so a mixed band's edges read per-dimension. For a
          // `uses-kit` edge the target is a kit node ⇒ ui ⇒ KIT_COLOR == meta.color (byte-identical).
          const libGraph = isLibraryEdge(e.kind) ? libraryGraphOf(nodeById.get(e.to) ?? {}) : undefined;
          const libColor = libGraph ? LIBRARY_META[libGraph].color : undefined;
          const color = loop ? hueColor(arch!.hue) : e.isCycle ? "var(--graph-health-error)" : arch ? hueColor(arch.hue) : (libColor ?? meta.color);
          const width = (e.isCycle ? 2.3 : arch ? 1.8 : meta.w) + (inFocus && focus ? 0.7 : 0);
          const dash = e.isCycle ? "7 6" : arch ? (ARCH_DASH[arch.style] ?? "") : meta.dash;
          const opacity = e.isCycle ? (focus ? (inFocus ? 1 : 0.4) : 0.95) : (focus ? (inFocus ? 1 : REST_E) : 0.82);
          // When either endpoint is pushed aside by the open panel (#2662), re-route the edge to the
          // displaced node boxes so it stays attached; else use the model's precomputed path.
          const dF = pushMap.get(e.from), dT = pushMap.get(e.to);
          let d = e.d, arrow = e.arrow;
          if (morphRect && (dF || dT)) {
            const F = nodeById.get(e.from), T = nodeById.get(e.to);
            if (F && T) {
              const g = edgeGeom({ x: F.x + (dF?.dx ?? 0), y: F.y + (dF?.dy ?? 0), id: e.from },
                                 { x: T.x + (dT?.dx ?? 0), y: T.y + (dT?.dy ?? 0), id: e.to }, e.isCycle, e.kind);
              d = g.d; arrow = g.arrow;
            }
          }
          // Ease the path only while a panel is open (WebView2/Chromium animates `d`); off otherwise so
          // normal graph updates (drill/layout) don't animate. Matched to the panel's grow (MORPH_EASE)
          // so a re-routed edge tracks its parting endpoints in lockstep with the panel (#2671).
          const pathTween = morphRect ? `d ${MORPH_EASE}` : undefined;
          return (
            <g key={e.id} opacity={opacity} onMouseEnter={() => p.onHoverEdge(e.id)} onMouseLeave={() => p.onHoverEdge(null)} onClick={click(() => p.onSelectEdge(e.id))} style={{ cursor: "pointer", transition: "opacity .18s" }}>
              <path d={d} stroke="transparent" strokeWidth={16} fill="none" />
              {/* stroke/fill via `style` (not the SVG attribute) so the `var(--graph-*)` token RESOLVES —
                  CSS custom properties don't resolve in SVG presentation attributes (#2618). */}
              <path d={d} strokeWidth={width} strokeDasharray={dash} fill="none" strokeLinecap="round"
                style={{ stroke: color, transition: pathTween, ...(e.isCycle ? { animation: "glance-dashmove .75s linear infinite" } : {}) }} />
              <path d={arrow} style={{ fill: color, transition: pathTween }} />
            </g>
          );
        })}
      </svg>

      {/* nodes */}
      {model.nodes.map((n) => {
        // A shared-RESOURCE node (#3322) — a library a session stewards, NOT an agent. A distinct dashed
        // card (⬡ + "resource") in a muted tone, so it never reads as a worker/agent node.
        if (n.resource) {
          const selected = p.selNodeId === n.id;
          const inFocus = focus ? focus.nodes.has(n.id) : true;
          const push = pushMap.get(n.id);
          const accent = "var(--fg-muted)";
          const border = selected ? "var(--accent)" : focus && inFocus ? accent : "var(--border-soft)";
          return (
            <Box key={n.id} data-glance-node={n.id} onMouseEnter={() => p.onHoverNode(n.id)} onMouseLeave={() => p.onHoverNode(null)} onClick={click(() => p.onSelectNode(n.id))}
              style={{ position: "absolute", left: n.x, top: n.y, width: NW, height: NH, cursor: "pointer",
                transform: push ? `translate(${push.dx}px, ${push.dy}px)` : undefined,
                zIndex: selected ? 6 : inFocus ? 3 : 1, opacity: focus ? (inFocus ? 1 : REST_N) : 1, transition: `opacity .18s ease, transform ${MORPH_EASE}` }}>
              <Box style={{ width: "100%", height: "100%", background: "var(--bg-soft)", border: `1.5px dashed ${border}`,
                borderRadius: 9, padding: "10px 12px", display: "flex", flexDirection: "column", justifyContent: "center",
                boxShadow: selected ? "0 0 0 4px color-mix(in oklch, var(--accent) 18%, transparent)" : "0 2px 8px rgba(0,0,0,.35)" }}>
                <Box style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <Text as="span" style={{ color: accent, flex: "none", fontSize: 12, lineHeight: 1 }}>⬡</Text>
                  <Text as="span" mono size={13} weight={600} style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{n.slug}</Text>
                </Box>
                <Text as="span" mono size={10} style={{ marginTop: 9, textTransform: "uppercase", letterSpacing: ".5px", color: accent }}>resource</Text>
              </Box>
            </Box>
          );
        }
        // A fenced-BAND node reads distinctly — a dashed card in its dimension's accent, with the glyph
        // (◆/∑/♪ for a cross-graph LIBRARY node #2571/#3119; ⇄ for an external MCP-CONTRACT node #3786), the
        // kind word (kit/algorithm/sound/mcp), and the count of consuming projects (the edges INTO it) — so
        // it never looks like a project node. The `ui` case is byte-identical to the pre-#3119 kit card
        // (cyan · ◆ · "kit"). An mcp node additionally shows its `appType` (api/serverless).
        if (isBandNode(n)) {
          const lib = bandNodeMeta(n);
          const consumers = model.edges.reduce((acc, e) => acc + (e.to === n.id ? 1 : 0), 0);
          const selected = p.selNodeId === n.id;
          const inFocus = focus ? focus.nodes.has(n.id) : true;
          const push = pushMap.get(n.id);
          const border = selected ? "var(--accent)" : (focus && inFocus ? lib.color : `color-mix(in oklch, ${lib.color} 45%, transparent)`);
          return (
            <Box key={n.id} data-glance-node={n.id} onMouseEnter={() => p.onHoverNode(n.id)} onMouseLeave={() => p.onHoverNode(null)} onClick={click(() => p.onSelectNode(n.id))}
              style={{ position: "absolute", left: n.x, top: n.y, width: NW, height: NH, cursor: "pointer",
                transform: push ? `translate(${push.dx}px, ${push.dy}px)` : undefined,
                zIndex: selected ? 6 : inFocus ? 3 : 1, opacity: focus ? (inFocus ? 1 : REST_N) : 1, transition: `opacity .18s ease, transform ${MORPH_EASE}` }}>
              <Box style={{ width: "100%", height: "100%", background: "var(--bg-elev)", border: `1.5px dashed ${border}`,
                borderRadius: 9, padding: "10px 12px", display: "flex", flexDirection: "column", justifyContent: "center",
                boxShadow: selected ? "0 0 0 4px color-mix(in oklch, var(--accent) 18%, transparent)" : "0 2px 8px rgba(0,0,0,.45)", transition: "border-color .15s, box-shadow .15s" }}>
                <Box style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <Text as="span" style={{ color: lib.color, flex: "none", fontSize: 11, lineHeight: 1 }}>{lib.marker}</Text>
                  <Text as="span" mono size={13} weight={600} style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{n.slug}</Text>
                </Box>
                <Box style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 9 }}>
                  {/* The kind word — and for an external CONTRACT node (mcp/service) its appType
                      (api/serverless/…), the contract endpoint type (#3786). Library/kit nodes carry no
                      appType, so they read just the kind word. */}
                  <Text as="span" mono size={10} style={{ textTransform: "uppercase", letterSpacing: ".5px", color: lib.color, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                    {n.appType ? `${lib.kindLabel} · ${n.appType}` : lib.kindLabel}
                  </Text>
                  <Box style={{ flex: 1 }} />
                  <Text as="span" mono size={10} weight={500} tone="dim" style={{ flex: "none" }}>{consumers} app{consumers === 1 ? "" : "s"}</Text>
                </Box>
              </Box>
            </Box>
          );
        }
        // The lower-left accent chip. At L1 it names the agent's FUNCTION group; at L0 it carries the
        // project's DISCOVERED LIFECYCLE intent (#4062).
        //
        // An L0 project with no discovered lifecycle gets NOTHING — not a default, and never a
        // fallback to `role`, which would resurrect the hash-per-id microservices tier. #4052 deleted
        // the previous chip precisely because it always produced a value, so every unclassified
        // project wore a confident label. Blank is the honest render.
        const lifecycle = !p.fleet && n.lifecycle ? LIFECYCLE_META[n.lifecycle] : undefined;
        const role = p.fleet ? ROLE_COLOR[n.role] : lifecycle?.color;
        // Axis 1 — HEALTH (#2541): the top-left dot renders the ROLLED-UP health (worst of self + deps).
        const health = HEALTH_META[n.rollupHealth];
        const inherited = n.healthInherited;                 // lit only by a downstream dep → muted, no pulse
        const isError = n.rollupHealth === "error";
        const degraded = isError || n.rollupHealth === "warning";
        // The user-deactivated node (#3239): render it greyed + calm — the OFF health wins over the live
        // status word (a building/live node still reads "off") and mutes every activity pulse.
        const isOff = n.rollupHealth === "off";
        // Axis 2 — ACTIVITY (#2541): the bottom-right word. A degraded node swaps in its HEALTH word
        // (#3957) — `warning`/`error` — not its reason. This slot is one word wide (108px, nowrap,
        // ellipsis), so a reason never overflowed; it TRUNCATED, and
        // "waiting on 2 upstreams to land (domain-model…" rendered as "waiting on 2 upstre…", which
        // reads as garbage rather than a status. Substituting the reason made sense when reasons were
        // short fault titles, but `applyStallHealth` appends a duration and #3931's `heldReason` names
        // every unlanded upstream. Nothing is lost: the dot carries the colour, the `title` below
        // carries the full reason on hover, and GlanceInspector renders it in a REASON tile.
        const ownDegraded = n.health === "warning" || n.health === "error";
        const bottomText = nodeStateWord(n);
        const bottomColor = isOff || degraded ? health.color : "var(--fg-muted)";
        // #4015 — the BUILDING pulse, gated to fleet (L1) nodes. Suppressed on a deactivated node
        // (which is meant to read calm) and on an errored one (its own error pulse is the thing to
        // look at; two competing animations on one node read as noise).
        const pulseBuilding = showsBuildingPulse(n, { fleet: !!p.fleet, isOff, isError });
        // #4018 — the activity WORD stops pulsing once the whole NODE does. Two opacity animations,
        // one inside the other, on the same beat: the word is the smaller, weaker cue and it just
        // muddies the node breath that has replaced it.
        //
        // Gated on `pulseBuilding` rather than switching `ACTIVITY_META.building.pulse` off, because
        // that flag is global: an L0 PROJECT node does NOT get the node pulse (it is fleet-only), so
        // flipping it there would silently strip the only motion an L0 building node has — a change
        // to the project network, which is exactly what this work is not meant to touch.
        const bottomPulse = !isOff && !degraded && !pulseBuilding && ACTIVITY_META[n.activity].pulse;

        const selected = p.selNodeId === n.id;
        const inFocus = focus ? focus.nodes.has(n.id) : true;
        const isCycle = model.cycleNodeIds.has(n.id);
        // A node in a mutual-dependency HAZARD cycle tints red; a node in an intentional iteration LOOP
        // (all its cycle edges cyclical, #2578) tints with the loop archetype's hue instead — not a fault.
        const hazardCycle = isCycle && model.edges.some((e) => e.isCycle && (e.from === n.id || e.to === n.id) && !archetypeById(e.archetype ?? "")?.cyclical);
        const loopHue = isCycle && !hazardCycle
          ? hueColor(archetypeById(model.edges.find((e) => e.isCycle && (e.from === n.id || e.to === n.id) && archetypeById(e.archetype ?? "")?.cyclical)?.archetype ?? "")?.hue ?? 300)
          : undefined;
        // ERROR highlights the whole node red (#2541) — the origin (own error) full-strength, an inherited
        // (downstream) error softer, so the eye lands on the source. Beats the cycle tint; selection wins.
        const border = selected ? "var(--accent)"
          : n.preview ? "var(--accent)"  // the ▷ preview node (#2623) — the finished-app surface, accented
          : isOff ? "var(--border-soft)"  // #3239: a deactivated node reads calm — a muted, neutral border
          : isError ? (inherited ? `color-mix(in oklch, ${ERR} 42%, transparent)` : ERR)
          : hazardCycle ? `color-mix(in oklch, ${ERR} 55%, transparent)`
          : loopHue ? `color-mix(in oklch, ${loopHue} 55%, transparent)`
          : (focus && inFocus ? "var(--border)" : "var(--border-soft)");
        const boxShadow = selected ? "0 0 0 4px color-mix(in oklch, var(--accent) 18%, transparent)"
          : isError && !inherited ? `0 0 0 3px color-mix(in oklch, ${ERR} 22%, transparent), 0 2px 8px rgba(0,0,0,.45)`
          : "0 2px 8px rgba(0,0,0,.45)";
        // Pushed clear of the open terminal panel, if it overlaps (#2662) — the panel makes room.
        const push = pushMap.get(n.id);
        // A deactivated node (#3239) is dimmed in place — muted, but a touch more visible while selected so
        // its open details pane (where it's turned back on) still reads as the focus.
        const offOpacity = isOff ? (selected ? 0.72 : 0.42) : 1;
        return (
          <Box key={n.id} data-glance-node={n.id} onMouseEnter={() => p.onHoverNode(n.id)} onMouseLeave={() => p.onHoverNode(null)} onClick={click(() => p.onSelectNode(n.id))}
            style={{ position: "absolute", left: n.x, top: n.y, width: NW, height: NH, cursor: "pointer",
              transform: push ? `translate(${push.dx}px, ${push.dy}px)` : undefined,
              // Part in lockstep with the panel's grow (MORPH_EASE), so the two are one motion (#2671).
              zIndex: selected ? 6 : isError && !inherited ? 5 : inFocus ? 3 : 1, opacity: focus ? (inFocus ? offOpacity : REST_N) : offOpacity, transition: `opacity .18s ease, transform ${MORPH_EASE}` }}>
            <GlanceNode
              n={n}
              border={border}
              boxShadow={boxShadow}
              healthColor={health.color}
              healthPulse={health.pulse}
              healthPulseMs={health.pulseMs}
              healthGlow={health.glow}
              inherited={!!inherited}
              roleColor={role}
              roleLabel={p.fleet ? (n.roleLabel ?? n.role) : lifecycle?.label}
              bottomText={bottomText}
              bottomColor={bottomColor}
              bottomPulse={bottomPulse}
              isOff={isOff}
              degraded={degraded}
              ownDegraded={ownDegraded}
              // #4032 — which authored motion plays. Only `building` remains (#4046 removed the
              // attention ring with its health state).
              state={pulseBuilding ? "building" : null}
            />
          </Box>
        );
      })}

      {/* A live agent's terminal, morphed open IN the graph (#2534): an oversized node grown at the
          clicked node's world coords, so it pans/zooms/scales with the canvas. No portal, no scrim. */}
      {p.onCloseChat && openChats.map((c) => (
        // Keyed by paneId (#3049/#3361): a morph's identity is its session, so opening or closing a
        // SIBLING never remounts it — its terminal keeps its TerminalHost claim and its pending exit
        // timer is only ever cancelled by its own unmount.
        <GlanceStreamMorph
          key={c.paneId}
          node={c.node} slot={c.slot} paneId={c.paneId} name={c.name} role={c.role} zoom={p.zoom}
          plan={p.planFor?.(c.nodeId)}
          onRect={reportRect(c.paneId)}
          onResizeCell={p.onResizeCell}
          onClose={() => p.onCloseChat!(c.nodeId)}
          onEnd={p.onEndChat ? () => p.onEndChat!(c.nodeId) : undefined}
        />
      ))}

      {/* The PREVIEW node, morphed open into the finished application IN the graph (#2623). */}
      {previewNode && p.preview && p.onClosePreview && (
        <GlancePreviewMorph node={previewNode} source={p.preview.source} name={p.preview.name} building={p.preview.building} onBuild={p.preview.onBuild} review={p.preview.review} onClose={p.onClosePreview} />
      )}
    </>
  );
}

/** The fixed hint + legend overlays — drawn over the canvas, not transformed. Drill-aware (#2561): the
 *  ROLE + EDGE columns speak the fleet's Org grammar (agent FUNCTION groups + relationship archetypes)
 *  when a project is drilled, and the project-network vocabulary at the root. `archetypes` are the
 *  distinct archetype ids present in the drilled fleet. */
export function GlanceOverlays({ drill = false, archetypes = [] }: { drill?: boolean; archetypes?: string[] } = {}) {
  // L1 keys the agent FUNCTION buckets; L0 keys the LIFECYCLE accents (#4066).
  const roleRows = drill ? ROLE_ROWS_L1 : LIFECYCLE_ROWS_L0;
  const edgeRows: [string, string, string][] = drill
    ? [
        ...archetypes.map((a): [string, string, string] => {
          const ar = archetypeById(a);
          return ar ? [ar.label, hueColor(ar.hue), ARCH_DASH[ar.style] ?? ""] : [a, "var(--fg-muted)", ""];
        }),
        ["cycle", "var(--graph-health-error)", "7 6"],
      ]
    : EDGE_ROWS_L0;
  return (
    <>
      {/* hint */}
      <Box style={{ position: "absolute", left: 16, bottom: 16, pointerEvents: "none" }}>
        <Text as="div" mono size={10.5} tone="dim" style={{ lineHeight: 1.7 }}>drag to pan · scroll to zoom<br />click node → {drill ? "open agent" : "enter"} · click edge → {drill ? "relationship" : "contract"}</Text>
      </Box>

      {/* legend */}
      <Box style={{ position: "absolute", right: 16, bottom: 16, background: "color-mix(in oklch, var(--bg-elev) 85%, transparent)", backdropFilter: "blur(8px)",
        border: "1px solid var(--border)", borderRadius: 9, padding: "12px 14px", pointerEvents: "none", display: "flex", gap: 22 }}>
        <Box>
          <Text as="div" mono size={9.5} tone="dim" style={{ letterSpacing: "1px", marginBottom: 8 }}>HEALTH</Text>
          <Box style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            {HEALTH_ROWS.map((h) => (
              <Box key={h} style={{ display: "flex", alignItems: "center", gap: 7 }}>
                {/* The swatch ANIMATES when the state does (#4052) — otherwise `complete` and
                    `modifying`, which deliberately share one blue, would be two identical dots and the
                    legend would teach nothing about the pair. Motion is the whole difference on the
                    node, so it has to be the difference here too. */}
                <Box style={{ width: 8, height: 8, borderRadius: "50%", background: HEALTH_META[h].color, flex: "none",
                  animation: HEALTH_META[h].pulse ? `glance-softpulse ${HEALTH_META[h].pulseMs ?? 1400}ms ease-in-out infinite` : "none" }} />
                <Text as="span" mono size={10} tone="muted">{HEALTH_META[h].label}</Text>
              </Box>
            ))}
          </Box>
        </Box>
        <Box>
          <Text as="div" mono size={9.5} tone="dim" style={{ letterSpacing: "1px", marginBottom: 8 }}>{drill ? "FUNCTION" : "LIFECYCLE"}</Text>
          <Box style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            {roleRows.map(([label, color]) => (
              <Box key={label} style={{ display: "flex", alignItems: "center", gap: 7 }}>
                {/* A DOT, not a bar (#4068). This column keys a NODE property — the lifecycle chip at
                    L0, the agent's function group at L1 — and a short line reads as a RELATIONSHIP,
                    which is precisely what the EDGE column directly below means and draws with real
                    lines. Matching the health dot puts both node-property columns in one shape. */}
                <Box style={{ width: 8, height: 8, borderRadius: "50%", background: color, flex: "none" }} />
                <Text as="span" mono size={10} tone="muted">{label}</Text>
              </Box>
            ))}
          </Box>
        </Box>
        <Box>
          <Text as="div" mono size={9.5} tone="dim" style={{ letterSpacing: "1px", marginBottom: 8 }}>{drill ? "RELATIONSHIP" : "EDGE"}</Text>
          <Box style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            {edgeRows.map(([label, color, dash]) => (
              <Box key={label} style={{ display: "flex", alignItems: "center", gap: 7 }}>
                <svg width={14} height={2} style={{ flex: "none", overflow: "visible" }}><line x1={0} y1={1} x2={14} y2={1} strokeWidth={2} strokeDasharray={dash} style={{ stroke: color }} /></svg>
                <Text as="span" mono size={10} style={{ color: label === "cycle" ? "var(--cycle)" : "var(--fg-muted)" }}>{label}</Text>
              </Box>
            ))}
          </Box>
        </Box>
        {/* The cross-graph LIBRARY node dimensions (#3119) — the fenced-band flavours (kit/algorithm/sound),
            each its own accent + glyph. L0 only (a drilled fleet has no library band). */}
        {!drill && (
          <Box>
            <Text as="div" mono size={9.5} tone="dim" style={{ letterSpacing: "1px", marginBottom: 8 }}>LIBRARY</Text>
            <Box style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              {LIBRARY_ROWS.map(([label, color, marker]) => (
                <Box key={label} style={{ display: "flex", alignItems: "center", gap: 7 }}>
                  <Text as="span" style={{ color, flex: "none", width: 9, textAlign: "center", fontSize: 9, lineHeight: 1 }}>{marker}</Text>
                  <Text as="span" mono size={10} tone="muted">{label}</Text>
                </Box>
              ))}
            </Box>
          </Box>
        )}
      </Box>
    </>
  );
}

runtime.features/glance/GlanceChatDock.tsx:
// Glance agent stream dock (#2369) — presents a LIVE fleet agent's real PTY stream + its logs, docked
// at the bottom of the Glance page. Opened from the inspector's "Open stream" button for a live drilled
// agent. This is the step that lets the console page retire (#2205 direction): the graph, not a tab
// grid, hosts the terminal.
//
// Reuse-first + zero reinvention: the "Stream" tab drops a <TerminalSlot> for the agent's identity pane
// id (`<project>:<stream>`). Since #2378 there is exactly ONE terminal per agent — owned by the app-level
// TerminalHost — and the slot RE-PARENTS it into the dock while it's open (parked back to the console cell
// on close), so the dock inherits everything the console has (scrollback bounding, the capped
// hidden-buffer, reconnect-not-respawn) with NO second xterm and no PTY-sizing coordination hack. The
// "Logs" tab is the shared sessionLog surface.
import { useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";
import { IconButton } from "@/shared/ui/controls/IconButton";
import { TerminalSlot } from "@/app/console/terminal/TerminalSlot";
import { GlanceSessionLog } from "./GlanceSessionLog";
import { GlancePlanScreen, planScreenIssues } from "./GlancePlanScreen";
import type { StreamProgress } from "./lib/streamProgress";

type DockTab = "stream" | "logs" | "plan";

/** The worker's owned work (#4102), resolved once at the workspace and threaded down. Passed in rather
 *  than fetched here on purpose: every open morph mounts its own dock, so a fetch at this level would be
 *  one query per open node — the fan-out this feature was explicitly built to avoid. Undefined ⇒ the
 *  node is not a fleet worker (a studio/debug session), so the Plan tab is omitted entirely. */
export interface DockPlan {
  /** Issue refs this worker owns, in PLAN order. */
  refs: readonly string[];
  /** ref (unprefixed) → closed. Empty when GitHub is unavailable. */
  states: ReadonlyMap<string, boolean>;
  progress?: StreamProgress;
  /** The state overlay could not be fetched — the list still renders. */
  unresolved?: boolean;
  loading?: boolean;
}

export function GlanceChatDock({
  paneId, name, role, plan, onClose, onEnd,
}: {
  paneId: string;
  name: string;
  role?: string;
  /** This worker's owned issues (#4102). Undefined ⇒ no Plan tab. */
  plan?: DockPlan;
  /** Collapse the dock back into its node — the PTY stays ALIVE (the agent is untouched). */
  onClose: () => void;
  /** END the session — kill the PTY so a stuck / soft-locked agent is fully torn down and triage can
   *  be relaunched cleanly (#3049). Undefined ⇒ the End-session button is omitted. */
  onEnd?: () => void;
}) {
  const [tab, setTab] = useState<DockTab>("stream");

  return (
    // Fills its container (#2401): the morph panel owns the frame (border/radius/shadow) + sizing, so
    // this is a plain fill — height:100%, no bottom-dock border. (Was a fixed 40vh bottom dock.)
    <Box style={{
      height: "100%", minHeight: 0, flex: 1,
      background: "var(--bg-panel)",
      display: "flex", flexDirection: "column", minWidth: 0,
    }}>
      <Row justify="between" align="center" style={{ padding: "7px 12px", borderBottom: "1px solid var(--border)", flex: "none" }}>
        <Row gap="sm" align="baseline" style={{ minWidth: 0 }}>
          <Text mono size="md" weight={600} style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{name}</Text>
          {role && <Text mono size="xs" tone="dim" style={{ flex: "none" }}>{role}</Text>}
          <Text mono size="xs" tone="dim" style={{ flex: "none" }}>· live</Text>
        </Row>
        <Row gap="sm" align="center" style={{ flex: "none" }}>
          {/* Plan sits beside Stream and Logs only when this node HAS a plan — a studio or debug
              session owns no issues, and an always-empty tab would read as a bug. */}
          {((plan ? ["stream", "logs", "plan"] : ["stream", "logs"]) as DockTab[]).map((t) => (
            <Button key={t} size="sm" variant={tab === t ? "primary" : "ghost"} onClick={() => setTab(t)}>
              {t === "stream" ? "Stream" : t === "logs" ? "Logs" : "Plan"}
            </Button>
          ))}
          {/* END the session (#3049) — kills the PTY (distinct from the ✕, which only collapses the
              morph and keeps the agent alive). For a soft-locked fleet this fully tears a stuck agent
              down so "Relaunch fleet" can restart triage cleanly. */}
          {onEnd && (
            <Button size="sm" variant="ghost" danger onClick={onEnd} title="Kill this agent's session so triage can be relaunched">
              End session
            </Button>
          )}
          <IconButton aria-label="Collapse stream (agent stays alive)" onClick={onClose}>×</IconButton>
        </Row>
      </Row>

      <Box style={{ flex: 1, minHeight: 0, position: "relative" }}>
        {/* The terminal stays MOUNTED across tab switches (only hidden) so its PTY is never torn down;
            `visible` gates its render/fit exactly like a background console pane. */}
        <Box style={{ position: "absolute", inset: 0, display: tab === "stream" ? "flex" : "none", flexDirection: "column" }}>
          {/* The live PTY stream IS the interaction surface (#3523): a Claude CLI session has its own TUI
              input (and its own "working" state) inside the terminal, so the dock adds no second input —
              click into the terminal and type at Claude's prompt directly. The separate "message the
              agent" box was a redundant affordance over the same PTY. */}
          <Box style={{ flex: 1, minHeight: 0, display: "flex", flexDirection: "column" }}>
            {/* Viewer slot (not primary): the host re-parents the agent's single terminal here while the
                dock is open. `visible` gates its render/fit exactly like a background console pane. */}
            <TerminalSlot paneId={paneId} visible={tab === "stream"} focused={false} />
          </Box>
        </Box>
        {tab === "logs" && (
          <Box style={{ position: "absolute", inset: 0 }}>
            <GlanceSessionLog paneId={paneId} />
          </Box>
        )}
        {tab === "plan" && plan && (
          <Box style={{ position: "absolute", inset: 0, overflow: "hidden" }}>
            <GlancePlanScreen
              issues={planScreenIssues(plan.refs, plan.states)}
              progress={plan.progress}
              unresolved={plan.unresolved}
              loading={plan.loading}
            />
          </Box>
        )}
      </Box>
    </Box>
  );
}

runtime.features/glance/GlanceInspector.tsx:
// Glance inspector (#2206) — the right dock, in one of two modes. PROJECT (node): status · role · cycle
// warning · depends-on / depended-on-by (clickable); clicking the project drills into its live agent
// network (L2, #2223/#2228). CONTRACT (edge): kind · cycle warning · consumer→provider · strength ·
// surface · description. Read-only view over the graph model.
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Grid } from "@/shared/ui/layout/Grid";
import { Text } from "@/shared/ui/typography/Text";
import { SectionLabel } from "@/shared/ui/layout/SectionLabel";
import { Button } from "@/shared/ui/controls/Button";
import { IconButton } from "@/shared/ui/controls/IconButton";
import { Toggle } from "@/shared/ui/controls/Toggle";
import { StatusDot } from "@/shared/ui/feedback/StatusDot";
import { StatTile } from "@/shared/ui/data/StatTile";
import { ROLE_COLOR, HEALTH_META, ACTIVITY_META, EDGE_META, isBandNode, bandNodeMeta, libIdOfNode, mcpIdOfNode, serviceIdOfNode, type GraphModel, type GNode, type GEdge } from "./lib/glanceGraph";
import { archetypeById, formById, hueColor } from "@/features/teams";

const FAULT_COLOR = "var(--graph-health-error)";

// Fills its (drag-resizable) wrapper column in GraphCanvas — the width is owned by the layout, not here.
const PANEL: React.CSSProperties = { flex: 1, minWidth: 0, background: "var(--bg-elev)", borderLeft: "1px solid var(--border)", display: "flex", flexDirection: "column", zIndex: 15 };
const CARD: React.CSSProperties = { flex: 1, background: "var(--bg-soft)", border: "1px solid var(--border)", borderRadius: 8, padding: "10px 12px" };
// The section micro-label, on the shared SectionLabel (#2420) with this inspector's tracking/rhythm.
const LABEL = (t: string) => <SectionLabel size={9.5} style={{ letterSpacing: "1px", margin: "20px 0 9px" }}>{t}</SectionLabel>;
const CYCLE_BG = "rgba(242,85,95,.08)", CYCLE_BD = "rgba(242,85,95,.28)";
// Iteration-loop (cyclical archetype, #2578) accents — violet, so a deliberate loop reads distinct from
// the red mutual-dependency hazard.
const LOOP_FG = "#c77dff", LOOP_TX = "#d9b3ff", LOOP_BG = "rgba(199,125,255,.08)", LOOP_BD = "rgba(199,125,255,.30)";

interface InspectorProps {
  model: GraphModel;
  selType: "node" | "edge" | null;
  selId: string | null;
  onSelectNode: (id: string) => void;
  onClose: () => void;
  /** When provided (the L1 project network, #2253), the CONTRACT view offers "remove link" — the edge is
   *  a user-drawn project relationship, so its `id` is the ProjectLink id. */
  onRemoveEdge?: (id: string) => void;
  /** The selected project's auto-triage toggle state (#2265). Undefined ⇒ don't render the control
   *  (a drilled fleet node, or an edge). */
  autoTriageOn?: boolean;
  /** Flip the selected project's auto-triage toggle (#2265). */
  onToggleAutoTriage?: (on: boolean) => void;
  /** Whether the selected node is currently OFF/deactivated (#3239). Undefined ⇒ don't render the
   *  activate/deactivate control (a drilled fleet node, or an edge). */
  offOn?: boolean;
  /** Turn the selected node off (deactivate, greyed) or back on (#3239). */
  onToggleOff?: (off: boolean) => void;
  /** Open the selected agent's REAL PTY stream in the dock (#2369). Provided only for a drilled, LIVE
   *  agent node — its presence is what renders the "Open stream" action. */
  onOpenStream?: (nodeId: string) => void;
  /** Resume the selected AGENT node's session (#glance-resume). Provided for a drilled fleet node: the
   *  workspace jumps to its Console pane when live, else relaunches that one agent. Its presence renders
   *  the node "Resume" action in this details pane. */
  onResumeNode?: (nodeId: string) => void;
  /** Whether the selected agent node has a live session (#glance-resume) — drives the resume action's
   *  wording (jump into an already-running pane vs relaunch a dormant one). */
  nodeLive?: boolean;
}

// Render a library-node blurb, wrapping `backtick`-delimited spans in <code> — so the ui kit's `bsc ui`
// keeps its inline-code styling (byte-identical to the pre-#3119 kit blurb) while algo/sound blurbs stay
// plain. #3119.
function blurbNodes(s: string): React.ReactNode[] {
  return s.split("`").map((seg, i) => (i % 2 ? <code key={i}>{seg}</code> : seg));
}

function DepRow({ node, kind, color, onClick }: { node: GNode; kind: string; color: string; onClick: () => void }) {
  return (
    <Row gap={9} align="center" onClick={onClick} style={{ padding: "8px 10px", borderRadius: 7, cursor: "pointer", background: "var(--bg)", border: "1px solid var(--border)", marginBottom: 5 }}>
      <StatusDot color={ROLE_COLOR[node.role]} size={8} />
      <Text as="span" mono size={12} style={{ flex: 1 }}>{node.slug}</Text>
      <Text as="span" mono size={9.5} style={{ textTransform: "uppercase", letterSpacing: ".5px", color }}>{kind}</Text>
    </Row>
  );
}

function Header({ title, onClose }: { title: string; onClose: () => void }) {
  return (
    <Row align="center" justify="between" style={{ padding: "14px 16px", borderBottom: "1px solid var(--border)" }}>
      <Text as="span" mono size={10.5} tone="dim" style={{ letterSpacing: "1.5px" }}>{title}</Text>
      <IconButton aria-label="close inspector" onClick={onClose}>×</IconButton>
    </Row>
  );
}

export function GlanceInspector({ model, selType, selId, onSelectNode, onClose, onRemoveEdge, autoTriageOn, onToggleAutoTriage, offOn, onToggleOff, onOpenStream, onResumeNode, nodeLive }: InspectorProps) {
  if (selType === "node" && selId) {
    const n = model.nodes.find((x) => x.id === selId);
    if (!n) return null;

    // A fenced-BAND node — a cross-graph LIBRARY node (#2571 kit → #3119) OR an external CONTRACT node
    // (#3786: an `mcp` server or a `service`): the node id + the projects that CONSUME it (the edges into
    // it), each clickable to hop to that project. A band node has no health/activity/role of its own, so
    // the project tiles are replaced by a scoped panel. The `ui` case is byte-identical to the pre-#3119
    // kit panel (header "UI KIT" · ◆ · "ui kit" · "uses kit"); an mcp/service node reads its panel title ·
    // glyph · appType · "contracts with".
    if (isBandNode(n)) {
      const lib = bandNodeMeta(n);
      const consumers = model.edges.filter((e) => e.to === n.id);
      return (
        <Box style={PANEL}>
          <Header title={lib.panelTitle} onClose={onClose} />
          <Box style={{ flex: 1, overflowY: "auto", padding: "18px 16px" }}>
            <Text as="div" mono size={19} weight={700} style={{ letterSpacing: "-.4px" }}>{n.slug}</Text>
            {/* The node id — plus, for an external contract node (mcp/service), its appType (#3786): the
                contract endpoint type. Library/kit nodes carry no appType. */}
            <Text as="div" mono size={11} tone="dim" style={{ marginTop: 4 }}>
              {n.kind === "mcp" ? mcpIdOfNode(n.id) : n.kind === "service" ? serviceIdOfNode(n.id) : libIdOfNode(n.id)}{n.appType ? ` · ${n.appType}` : ""}
            </Text>

            <Grid cols={2} gap={8} style={{ marginTop: 16 }}>
              <StatTile k="KIND" v={
                <Row gap={7} align="center">
                  <Text as="span" style={{ color: lib.color, flex: "none" }}>{lib.marker}</Text>
                  <Text as="span" mono size={12.5} weight={500} style={{ color: lib.color }}>{lib.panelTitle.toLowerCase()}</Text>
                </Row>
              } />
              <StatTile k="CONSUMERS" v={
                <Text as="span" mono size={12.5} weight={500} tone="muted">{consumers.length} project{consumers.length === 1 ? "" : "s"}</Text>
              } />
            </Grid>

            <Row gap={9} align="start" style={{ marginTop: 14, background: `color-mix(in oklch, ${lib.color} 8%, transparent)`, border: `1px solid color-mix(in oklch, ${lib.color} 30%, transparent)`, borderRadius: 8, padding: "10px 12px" }}>
              <Text as="span" style={{ color: lib.color, flex: "none" }}>{lib.marker}</Text>
              <Text as="span" size={11.5} style={{ lineHeight: 1.5, color: "var(--fg-muted)" }}>{blurbNodes(lib.blurb)}</Text>
            </Row>

            {LABEL("CONSUMED BY")}
            {consumers.length === 0 ? <Text as="div" mono size={11} tone="dim">— no consumers</Text>
              : consumers.map((e) => {
                  const consumer = model.nodes.find((x) => x.id === e.from);
                  return consumer ? <DepRow key={e.id} node={consumer} kind={lib.edgeLabel} color={lib.color} onClick={() => onSelectNode(e.from)} /> : null;
                })}
          </Box>
        </Box>
      );
    }

    const health = HEALTH_META[n.rollupHealth];   // axis 1 — rolled-up health (dot colour)
    const activity = ACTIVITY_META[n.activity];   // axis 2 — the lifecycle word
    const faults = n.faults ?? 0;
    const deps = model.edges.filter((e) => e.from === n.id);
    const rdeps = model.edges.filter((e) => e.to === n.id);
    const inCycle = model.cycleNodeIds.has(n.id);
    // A deliberate iteration LOOP (all this node's cycle edges cyclical, #2578) vs a mutual-dependency
    // HAZARD — the note is positive (a converging feedback loop) rather than a deadlock warning.
    const cycleLoop = inCycle && !model.edges.some((e) => e.isCycle && (e.from === n.id || e.to === n.id) && !archetypeById(e.archetype ?? "")?.cyclical);
    // An L1 (fleet) edge labels + colours by its Org archetype (Manages/Oversees/Peers…); an L0 edge by kind.
    const kindOf = (e: GEdge) => (e.isCycle ? "cycle" : e.archetype ? (archetypeById(e.archetype)?.label ?? e.archetype) : EDGE_META[e.kind].label.split(" ")[0]);
    const colorOf = (e: GEdge) => (e.isCycle ? "var(--graph-health-error)" : e.archetype ? hueColor(archetypeById(e.archetype)?.hue ?? 0) : EDGE_META[e.kind].color);

    return (
      <Box style={PANEL}>
        <Header title="PROJECT" onClose={onClose} />
        <Box style={{ flex: 1, overflowY: "auto", padding: "18px 16px" }}>
          <Text as="div" mono size={19} weight={700} style={{ letterSpacing: "-.4px" }}>{n.slug}</Text>

          {/* HEALTH (axis 1) / ACTIVITY (axis 2) / ROLE as shared metric tiles (#2420/#2541). The health
              value is the ROLLED-UP health; an inherited (downstream) health is flagged so the user
              knows the cause is a dependency, not this node. */}
          <Grid cols={2} gap={8} style={{ marginTop: 16 }}>
            <StatTile k="HEALTH" v={
              <Row gap={7} align="center">
                <StatusDot color={health.color} size={9} style={{ boxShadow: health.pulse ? `0 0 8px ${health.color}` : "none" }} />
                <Text as="span" mono size={12.5} weight={500} style={{ color: health.color }}>{n.rollupHealth}{n.healthInherited ? " · downstream" : ""}</Text>
              </Row>
            } />
            <StatTile k="ACTIVITY" v={
              <Text as="span" mono size={12.5} weight={500} tone="muted">{activity.label}</Text>
            } />
          </Grid>
          <Grid cols={2} gap={8} style={{ marginTop: 8 }}>
            <StatTile k="ROLE" v={
              <Text as="span" mono size={11} style={{ color: ROLE_COLOR[n.role], background: `color-mix(in oklch, ${ROLE_COLOR[n.role]} 12%, transparent)`, border: `1px solid color-mix(in oklch, ${ROLE_COLOR[n.role]} 30%, transparent)`, borderRadius: 5, padding: "3px 8px" }}>{n.roleLabel ?? n.role}</Text>
            } />
            {n.reason
              ? <StatTile k="REASON" v={<Text as="span" mono size={11} style={{ color: health.color, lineHeight: 1.4 }}>{n.reason}</Text>} />
              : <Box />}
          </Grid>

          {/* PROGRESS (#4118) — the focused worker's owned-issue completion, the same counts its node
              draws. The node's bar is a glance; this is where the user comes for the number, so it
              carries `done/total` plus the remaining count rather than a bare fill.
              Absent when the stream owns no issues — the same rule the node follows: a bar for a node
              with no work would state something false. */}
          {n.progress && n.progress.total > 0 && (
            <Box style={{ marginTop: 8 }}>
              <StatTile k="PROGRESS" v={
                <Box>
                  <Row gap={8} align="baseline">
                    <Text as="span" mono size={12.5} weight={600} style={{ color: "var(--graph-health-complete)" }}>
                      {n.progress.done}/{n.progress.total}
                    </Text>
                    <Text as="span" mono size={11} tone="muted">
                      {n.progress.done === n.progress.total
                        ? "every owned issue closed"
                        : `${n.progress.total - n.progress.done} open`}
                    </Text>
                  </Row>
                  <Box aria-hidden style={{ marginTop: 6, height: 5, borderRadius: 3, overflow: "hidden",
                    background: "color-mix(in oklch, var(--fg-muted) 26%, transparent)" }}>
                    <Box style={{ width: `${(n.progress.done / n.progress.total) * 100}%`, height: "100%",
                      borderRadius: 3, background: "var(--graph-health-complete)", transition: "width .3s ease" }} />
                  </Box>
                </Box>
              } />
            </Box>
          )}

          {/* Activate / deactivate this node (#3239): the manual OFF toggle. Turning it off greys the node
              on the network (health `off`) over any live status; turning it on restores its derived status.
              Persisted, so it continues from the last session. Only on the L0 project network (onToggleOff
              supplied) — a drilled fleet node has none. */}
          {onToggleOff && (
            <Box style={{ marginTop: 14, background: "var(--bg-soft)", border: "1px solid var(--border)", borderRadius: 8, padding: "11px 12px" }}>
              <Row justify="between" align="center" gap={10}>
                <Box style={{ minWidth: 0 }}>
                  <Text as="div" mono size={12} weight={600} style={{ color: offOn ? "var(--graph-health-off)" : "var(--fg)" }}>
                    {offOn ? "Node is off" : "Node is active"}
                  </Text>
                  <Text as="div" size={10.5} tone="dim" style={{ lineHeight: 1.4, marginTop: 2 }}>
                    {offOn ? "greyed on the graph — deactivated" : "shown with its live status"}
                  </Text>
                </Box>
                <Button variant={offOn ? "primary" : "ghost"} onClick={() => onToggleOff(!offOn)}
                  aria-label={offOn ? "turn node on" : "turn node off"} style={{ flex: "none" }}>
                  {offOn ? "Turn on" : "Turn off"}
                </Button>
              </Row>
            </Box>
          )}

          {inCycle && (cycleLoop
            ? <Row gap={9} align="start" style={{ marginTop: 14, background: LOOP_BG, border: `1px solid ${LOOP_BD}`, borderRadius: 8, padding: "10px 12px" }}>
                <Text as="span" style={{ color: LOOP_FG, flex: "none" }}>⟳</Text>
                <Text as="span" size={11.5} style={{ lineHeight: 1.5, color: LOOP_TX }}>In a deliberate iteration loop — cycles with its counterpart (findings ⟳ revisions) until it converges. Not a hazard.</Text>
              </Row>
            : <Row gap={9} align="start" style={{ marginTop: 14, background: CYCLE_BG, border: `1px solid ${CYCLE_BD}`, borderRadius: 8, padding: "10px 12px" }}>
                <Text as="span" style={{ color: "var(--graph-health-error)", flex: "none" }}>▲</Text>
                <Text as="span" size={11.5} style={{ lineHeight: 1.5, color: "var(--cycle-soft)" }}>In a cross-project dependency cycle — coordinate release order before shipping to avoid a deadlock.</Text>
              </Row>
          )}

          {/* PERSONA (#2561): the agent identity at this fleet node — who is at the terminal (name · model ·
              skills · charter), the "quick means" to see the assigned persona alongside its role. */}
          {n.persona && (
            <>
              {LABEL("PERSONA")}
              <Box style={{ background: "var(--bg-soft)", border: "1px solid var(--border)", borderRadius: 8, padding: "11px 12px" }}>
                <Row justify="between" align="center">
                  <Text as="span" mono size={13} weight={600}>{n.persona.name}</Text>
                  {n.persona.model && <Text as="span" mono size={10} tone="dim">{n.persona.model}</Text>}
                </Row>
                <Text as="div" size={10.5} tone="dim" style={{ marginTop: 3 }}>
                  role {n.persona.role} · {n.persona.skills.length} skill{n.persona.skills.length === 1 ? "" : "s"}
                </Text>
                {n.persona.responsibilities.length > 0 && (
                  <Box style={{ marginTop: 8 }}>
                    {n.persona.responsibilities.map((r, i) => (
                      <Text key={i} as="div" size={11} tone="muted" style={{ lineHeight: 1.5 }}>• {r}</Text>
                    ))}
                  </Box>
                )}
              </Box>
            </>
          )}

          {/* COMMUNICATION SURFACE (#2563): who this agent talks to and how — one card per relationship
              from the fleet-as-Org projection, with the forms it SENDS (→) / RECEIVES (←) + transports. */}
          {n.persona?.comms && n.persona.comms.length > 0 && (
            <>
              {LABEL("COMMUNICATION")}
              <Box style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                {n.persona.comms.map((c, i) => (
                  <Box key={i} style={{ background: "var(--bg-soft)", border: `1px solid color-mix(in oklch, ${hueColor(c.hue)} 30%, transparent)`, borderRadius: 8, padding: "9px 11px" }}>
                    <Row justify="between" align="center">
                      <Text as="span" mono size={11.5} weight={600}>{c.withName}</Text>
                      <Text as="span" mono size={9.5} style={{ color: hueColor(c.hue), textTransform: "uppercase", letterSpacing: ".5px" }}>{c.archetypeLabel}</Text>
                    </Row>
                    {([["→", c.sends], ["←", c.receives]] as const).map(([dir, forms]) => forms.length > 0 && (
                      <Row key={dir} gap={6} align="baseline" style={{ marginTop: 5 }}>
                        <Text as="span" mono size={10} tone="dim" style={{ width: 12, flex: "none" }}>{dir}</Text>
                        <Text as="span" mono size={10} tone="muted" style={{ lineHeight: 1.5 }}>
                          {forms.map((f) => f.label + (f.transport ? ` (${f.transport})` : "")).join(" · ")}
                        </Text>
                      </Row>
                    ))}
                  </Box>
                ))}
              </Box>
            </>
          )}

          {/* FAULT-health (#2265): unresolved runtime faults + the per-project auto-triage toggle. Only
              shown on the project network (onToggleAutoTriage supplied) — a drilled fleet node has neither. */}
          {onToggleAutoTriage && (
            <>
              {LABEL("RUNTIME FAULTS")}
              <Box style={{ background: faults > 0 ? "rgba(242,85,95,.08)" : "var(--bg-soft)", border: `1px solid ${faults > 0 ? "rgba(242,85,95,.28)" : "var(--border)"}`, borderRadius: 8, padding: "11px 12px" }}>
                <Row gap={9} align="center">
                  {faults > 0
                    ? <Text as="span" style={{ color: FAULT_COLOR, flex: "none" }}>●</Text>
                    : <Text as="span" tone="dim" style={{ flex: "none" }}>○</Text>}
                  <Text as="span" mono size={13} weight={600} style={{ color: faults > 0 ? "var(--cycle-soft)" : "var(--fg-muted)" }}>
                    {faults > 0 ? `${faults} unresolved` : "no open faults"}
                  </Text>
                </Row>
                <Row justify="between" align="center" style={{ marginTop: 11 }}>
                  <Box style={{ minWidth: 0 }}>
                    <Text as="div" mono size={11} weight={500}>auto-triage</Text>
                    <Text as="div" size={10.5} tone="dim" style={{ lineHeight: 1.4, marginTop: 2 }}>
                      {autoTriageOn ? "routes a fix into the director" : "surface-only — no auto-dispatch"}
                    </Text>
                  </Box>
                  <Toggle on={!!autoTriageOn} size="sm" onClick={() => onToggleAutoTriage(!autoTriageOn)} role="switch" ariaChecked={!!autoTriageOn} />
                </Row>
              </Box>
            </>
          )}

          {LABEL("AGENTS")}
          <Text as="div" size={11.5} tone="muted" style={{ lineHeight: 1.5 }}>Click this project to drill into its live agent network (director · workers · triage).</Text>

          {LABEL(n.persona ? "RELATES TO" : "DEPENDS ON")}
          {deps.length === 0 ? <Text as="div" mono size={11} tone="dim">— foundational, no upstream deps</Text>
            : deps.map((e) => <DepRow key={e.id} node={model.nodes.find((x) => x.id === e.to)!} kind={kindOf(e)} color={colorOf(e)} onClick={() => onSelectNode(e.to)} />)}

          {LABEL(n.persona ? "RELATED FROM" : "DEPENDED ON BY")}
          {rdeps.length === 0 ? <Text as="div" mono size={11} tone="dim">— leaf, nothing depends on it</Text>
            : rdeps.map((e) => <DepRow key={e.id} node={model.nodes.find((x) => x.id === e.from)!} kind={kindOf(e)} color={colorOf(e)} onClick={() => onSelectNode(e.from)} />)}

          {/* Open the agent's REAL live PTY stream in the dock (#2369) — only for a live drilled agent. */}
          {/* Resume this AGENT's session (#glance-resume) — jumps to its Console pane when live, else
              relaunches that one agent (claude --continue). Primary action for a drilled fleet node. */}
          {onResumeNode && (
            <Button variant="primary" onClick={() => onResumeNode(selId)} style={{ width: "100%", marginTop: 18 }}>
              {nodeLive ? "Open session ↗" : "▶ Resume session"}
            </Button>
          )}
          {/* Peek the agent's REAL live PTY stream inline in the graph (#2369) — only for a live drilled agent. */}
          {onOpenStream && (
            <Button variant={onResumeNode ? "ghost" : "primary"} onClick={() => onOpenStream(selId)} style={{ width: "100%", marginTop: onResumeNode ? 8 : 18 }}>Open stream ↗</Button>
          )}
        </Box>
      </Box>
    );
  }

  if (selType === "edge" && selId) {
    const e = model.edges.find((x) => x.id === selId);
    if (!e) return null;
    const meta = EDGE_META[e.kind];
    // A fleet-drill (L1) edge is an Org RELATIONSHIP (archetype → communication forms); an L0 edge is a
    // project contract. Resolve the archetype so the chip/colour/forms speak the org grammar (#2561).
    const arch = e.archetype ? archetypeById(e.archetype) : undefined;
    // A cyclical archetype (iterates, #2578) is a deliberate LOOP — keep the archetype label + hue, not
    // the red "cycle" hazard chip.
    const loop = e.isCycle && !!arch?.cyclical;
    const kindColor = loop ? hueColor(arch!.hue) : e.isCycle ? "var(--graph-health-error)" : arch ? hueColor(arch.hue) : meta.color;
    const chipLabel = loop ? arch!.label : e.isCycle ? "cycle" : arch ? arch.label : meta.label;
    const from = model.nodes.find((x) => x.id === e.from)!, to = model.nodes.find((x) => x.id === e.to)!;
    return (
      <Box style={PANEL}>
        <Header title={arch ? "RELATIONSHIP" : "CONTRACT INSPECTOR"} onClose={onClose} />
        <Box style={{ flex: 1, overflowY: "auto", padding: "18px 16px" }}>
          <Text as="span" mono size={11} style={{ color: loop ? kindColor : e.isCycle ? "var(--cycle)" : kindColor, background: `color-mix(in oklch, ${kindColor} 12%, transparent)`, border: `1px solid color-mix(in oklch, ${kindColor} 32%, transparent)`, borderRadius: 6, padding: "5px 10px" }}>{chipLabel}</Text>

          {loop && (
            <Row gap={9} align="start" style={{ marginTop: 14, background: LOOP_BG, border: `1px solid ${LOOP_BD}`, borderRadius: 8, padding: "11px 12px" }}>
              <Text as="span" style={{ color: LOOP_FG, flex: "none" }}>⟳</Text>
              <Text as="span" size={11.5} style={{ lineHeight: 1.5, color: LOOP_TX }}>An iteration loop — {from.slug} and {to.slug} cycle deliberately (findings ⟳ revisions) until it converges. Not a dependency hazard.</Text>
            </Row>
          )}
          {e.isCycle && !loop && (
            <Row gap={9} align="start" style={{ marginTop: 14, background: CYCLE_BG, border: `1px solid ${CYCLE_BD}`, borderRadius: 8, padding: "11px 12px" }}>
              <Text as="span" style={{ color: "var(--graph-health-error)", flex: "none" }}>▲</Text>
              <Text as="span" size={11.5} style={{ lineHeight: 1.5, color: "var(--cycle-soft)" }}>This edge closes a cycle. Two projects depend on each other — releasing either in isolation can deadlock the other.</Text>
            </Row>
          )}

          <Row gap={12} align="center" style={{ marginTop: 20 }}>
            <Box onClick={() => onSelectNode(e.from)} style={{ ...CARD, cursor: "pointer" }}>
              <Text as="div" mono size={9} tone="dim" style={{ letterSpacing: ".8px", marginBottom: 6 }}>CONSUMER</Text>
              <Row gap={7} align="center"><StatusDot color={ROLE_COLOR[from.role]} size={8} /><Text as="span" mono size={12}>{from.slug}</Text></Row>
            </Box>
            <Text as="span" tone="dim">→</Text>
            <Box onClick={() => onSelectNode(e.to)} style={{ ...CARD, cursor: "pointer" }}>
              <Text as="div" mono size={9} tone="dim" style={{ letterSpacing: ".8px", marginBottom: 6 }}>PROVIDER</Text>
              <Row gap={7} align="center"><StatusDot color={ROLE_COLOR[to.role]} size={8} /><Text as="span" mono size={12}>{to.slug}</Text></Row>
            </Box>
          </Row>

          <Box style={{ ...CARD, marginTop: 16, flex: "unset" }}>
            <Text as="div" mono size={9.5} tone="dim" style={{ letterSpacing: ".8px", marginBottom: 6 }}>STRENGTH</Text>
            <Text as="span" mono size={11} style={{ color: e.hard ? "var(--graph-health-warning)" : "var(--fg-muted)" }}>{e.hard ? "hard" : "soft"}</Text>
          </Box>

          {arch ? (
            <>
              {/* The Org communication FORMS this archetype expands into (#2561) — what flows each way and
                  the `bsc-*` transport that carries it at runtime. */}
              {LABEL("COMMUNICATION")}
              <Box style={{ background: "var(--bg)", border: "1px solid var(--border)", borderRadius: 8, padding: "6px 12px" }}>
                {[...arch.forward.map((id) => ({ id, dir: "→" })), ...arch.backward.map((id) => ({ id, dir: "←" }))].map(({ id, dir }, i) => {
                  const f = formById(id);
                  if (!f) return null;
                  return (
                    <Row key={`${id}-${i}`} gap={8} align="center" style={{ padding: "5px 0" }}>
                      <Text as="span" mono size={11} tone="dim" style={{ width: 12 }}>{dir}</Text>
                      <Text as="span" mono size={11.5} weight={500} style={{ flex: 1 }}>{f.label}</Text>
                      {f.transport && <Text as="span" mono size={10} style={{ color: kindColor }}>{f.transport}</Text>}
                    </Row>
                  );
                })}
              </Box>

              {LABEL("DESCRIPTION")}
              <Text as="div" size={12} style={{ lineHeight: 1.6, color: "var(--fg-muted)" }}>{arch.blurb}</Text>
            </>
          ) : (
            <>
              {LABEL("SURFACE")}
              <Box style={{ background: "var(--bg)", border: "1px solid var(--border)", borderRadius: 8, padding: "12px 13px" }}>
                <Text as="span" mono size={11.5} tone="muted" style={{ lineHeight: 1.7 }}>{meta.surface}</Text>
              </Box>

              {LABEL("DESCRIPTION")}
              <Text as="div" size={12} style={{ lineHeight: 1.6, color: "var(--fg-muted)" }}>
                {e.isCycle
                  ? `${from.slug} and ${to.slug} depend on each other. This back-edge closes the loop — treat as a release-ordering hazard.`
                  : `${from.slug} consumes ${to.slug} over a ${meta.label.toLowerCase()}. ${e.hard ? "Hard dependency: a breaking change here blocks the consumer." : "Soft dependency: degrades gracefully."}`}
              </Text>
            </>
          )}

          {onRemoveEdge && (
            <Box style={{ marginTop: 22 }}>
              <Button variant="ghost" onClick={() => { onRemoveEdge(e.id); onClose(); }}>✕ remove link</Button>
            </Box>
          )}
        </Box>
      </Box>
    );
  }

  return null;
}

