// The fleet/project NODE card (#4032) — extracted from the inline JSX in `GlanceCanvas`'s node map so
// it is a real component the designer can reach, and so its live states are authored MOTION DATA
// (`@/shared/ui/kit/glanceNodeAnimations`) rather than a raw keyframe in `glance.css` plus an inline
// `boxShadow`.
//
// ── THE STATE VOCABULARY ────────────────────────────────────────────────────────────────────────
// Three states, three motions, and the differences are deliberate:
//   · building  BREATHES — the worker is working (#4015)
//   · attention RINGS    — it is blocked on a PERSON, the one state that needs someone (#4005)
//   · complete  is STILL — finished; motion means "look at this", and this needs nothing (#4027)
//
// The first two come from the compiled kit CSS, bound to `data-node-state`. The third is the ABSENCE
// of an animation, which is why there is no `complete` entry in the motion data.
//
// ── WHAT STAYED IN THE CANVAS ───────────────────────────────────────────────────────────────────
// Everything positional and model-derived: layout, the border precedence chain (selected → preview →
// off → error → cycle → focus), the health rollup, push offsets. Those are graph CONCERNS, not node
// presentation, and threading them out would have made this a worse component, not a more reusable
// one. This owns the card's body: its states, its dot, its two label rows.
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import type { GNode } from "./lib/glanceGraph";
import { GLANCE_NODE_ANIM_CLASSES, ensureGlanceNodeMotion } from "./glanceNodeMotion";

/** Which live state the node's motion should express, or `null` for a still node. */
export type GlanceNodeState = "building" | null;

export interface GlanceNodeProps {
  n: GNode;
  /** Precomputed by the canvas — the border precedence chain it owns. */
  border: string;
  boxShadow: string;
  /** Health dot colour + whether it pulses (axis 1). */
  healthColor: string;
  healthPulse: boolean;
  /** Pulse CHARACTER (#4052) — an alarm (fast + haloed, `error`) vs a breath (slow + bare,
   *  `modifying`). Both optional so the alarm stays the default and `error` renders unchanged. */
  healthPulseMs?: number;
  healthGlow?: boolean;
  /** Lit only by a DOWNSTREAM dep — dimmed, never pulses, so the eye lands on the fault's ORIGIN. */
  inherited: boolean;
  /** The lower-left FUNCTION chip — fleet (L1) nodes only (#4052). Both absent ⇒ the slot renders
   *  nothing at all, which is how an L0 project node reads now that the lifecycle axis is gone. */
  roleColor?: string;
  roleLabel?: string;
  /** Axis-2 word + its colour, and whether it pulses (suppressed while the NODE itself animates). */
  bottomText: string;
  bottomColor: string;
  bottomPulse: boolean;
  /** The user-deactivated / degraded reads, which suppress the completion marker. */
  isOff: boolean;
  degraded: boolean;
  ownDegraded: boolean;
  /** The live motion state, or null. */
  state: GlanceNodeState;
  /** Owned-issue completion (#4050), or 0 for "no bar". Presentational only. */
}

/** How far past the fill edge the colour keeps bleeding, in percentage points (#4123).
 *
 *  This is the whole idea: the fill does not STOP anywhere. It thins out across this band, so the eye
 *  reads "about this far along" and cannot read a boundary off it. Too small and it is a line with a
 *  soft edge (a measurement); too large and a half-done node is indistinguishable from an empty one.
 *  16 keeps the two ends legible at the node's ~186px width while leaving nothing crisp in between. */
const FADE_PCT = 16;

/**
 * The node's background: its own completion, as a left-to-right wash that fades out (#4123).
 *
 * Returns the plain panel colour at zero — a node with no work, or none finished, must look exactly
 * like a node that has never been measured. Inventing a visible 0% sliver would put a mark on every
 * node in the graph and say nothing.
 *
 * Layered OVER `--bg-elev` rather than replacing it, so the node keeps its surface (and its contrast
 * with the canvas) at every fill level.
 */
export function nodeFill(fill: number): string {
  if (fill <= 0) return "var(--bg-elev)";
  const tint = (pct: number) => `color-mix(in oklch, var(--graph-health-complete) ${pct}%, transparent)`;
  const edge = Math.min(100, fill * 100);
  const soft = Math.max(0, edge - FADE_PCT);
  // Strongest at the origin, already thinning by the fade band, gone by the edge — an estimate with no
  // boundary to misread. `100%` is clamped by `edge`, so a complete node is washed end to end.
  return [
    `linear-gradient(90deg, ${tint(20)} 0%, ${tint(11)} ${soft}%, transparent ${edge}%)`,
    "var(--bg-elev)",
  ].join(", ");
}

export function GlanceNode(p: GlanceNodeProps) {
  const { n } = p;
  // Progress is the NODE'S OWN FILL (#4123) — not a bar drawn on it.
  //
  // It was a discrete widget twice over: a 2px hairline, then a 5px track with `done/total` beside it.
  // Both were wrong for what this number IS. Completion here is COARSE — the refs are a planning
  // artifact, "done" is whatever evidence happened to be reachable, and nobody sizes a decision off
  // the third digit. A precise-looking readout on every node invites reading it precisely, and it
  // competes with the health dot and activity word for the same glance.
  //
  // So the whole node fills, left to right, and the fill FADES rather than ending at a line — a soft
  // edge reads as an estimate, a hard one reads as a measurement. The exact counts still exist, in the
  // inspector, where someone has asked for them.
  const progress = n.progress;
  const fill = progress && progress.total > 0 ? Math.max(0, Math.min(1, progress.done / progress.total)) : 0;
  // Idempotent + cheap (one string compare after the first call). Done HERE rather than at the canvas
  // so the component carries its own motion: anything that renders a node gets the CSS, and nothing
  // has to remember to mount it.
  ensureGlanceNodeMotion();
  return (
    <Box
      // The applying classes + the state attribute ARE the binding: the compiled kit CSS scopes each
      // animation to `[data-node-state="…"]`, so a designer reading the record sees which state each
      // animation belongs to without any class bookkeeping here.
      className={GLANCE_NODE_ANIM_CLASSES}
      data-node-state={p.state ?? undefined}
      // The exact numbers stay reachable on hover without occupying the node.
      title={progress && progress.total > 0 ? `${progress.done}/${progress.total} issues complete` : undefined}
      style={{ width: "100%", height: "100%", background: nodeFill(fill), border: `1px solid ${p.border}`,
        borderRadius: 9, padding: "10px 12px", display: "flex", flexDirection: "column", justifyContent: "center",
        boxShadow: p.boxShadow, transition: "border-color .15s, box-shadow .15s",
        // `relative` so the progress bar can sit on the bottom edge; `overflow: hidden` keeps it inside
        // the rounded corners.
        position: "relative", overflow: "hidden" }}>
      <Box style={{ display: "flex", alignItems: "center", gap: 8 }}>
        {/* Axis-1 health DOT. Restored in #4040 with the glow gone — health is a colour, and without
            this the node had no colour surface for it at all. An INHERITED dot is dimmed and never
            pulses, so the eye lands on the ORIGIN of a fault rather than everything downstream
            (#2541). */}
        <Box title={`${n.rollupHealth}${p.inherited ? " (downstream)" : ""}`}
          style={{ width: 8, height: 8, borderRadius: "50%", background: p.healthColor, flex: "none", opacity: p.inherited ? 0.5 : 1,
            boxShadow: p.healthPulse && !p.inherited && p.healthGlow !== false ? `0 0 8px ${p.healthColor}` : "none",
            animation: p.healthPulse && !p.inherited ? `glance-softpulse ${p.healthPulseMs ?? 1400}ms ease-in-out infinite` : "none" }} />
        <Text as="span" mono size={13} weight={600} style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{n.slug}</Text>
        {/* The APP-TYPE discriminator (#3786/#3802) — a subtle mono micro-label on the title line: what
            KIND of app this endpoint is (api/serverless/cli/…). Gated on a non-default classification,
            so an unclassified project (appType absent, or "application") renders byte-identical. */}
        {n.appType && n.appType !== "application" && (
          <Text as="span" mono size={8.5} title={`app type: ${n.appType}`}
            style={{ flex: "none", textTransform: "uppercase", letterSpacing: ".4px", color: "var(--fg-muted)", opacity: 0.7,
              border: "1px solid var(--border-soft)", borderRadius: 4, padding: "1px 4px", lineHeight: 1.3 }}>{n.appType}</Text>
        )}
      </Box>
      {/* The axis-2 row. #4058 briefly stripped this from L0 project nodes; #4060 restored it — that
          change was meant to clean up the LEGEND, not the nodes. The word stays on every node at both
          levels; only the legend's L0 ACTIVITY column is gone. */}
      <Box style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 9 }}>
        {p.roleLabel && (
          <Text as="span" mono size={10} style={{ textTransform: "uppercase", letterSpacing: ".5px", color: p.roleColor }}>{p.roleLabel}</Text>
        )}
        <Box style={{ flex: 1 }} />
        {/* #4027 — the FINISHED marker. Static and to the LEFT of the word, so a completed node is
            legible at a glance without reading its label. */}
        {n.activity === "complete" && !p.isOff && !p.degraded && (
          <Text as="span" mono size={10} weight={600} aria-hidden
            style={{ color: "var(--graph-health-healthy)", marginRight: 4, flex: "none" }}>✓</Text>
        )}
        {/* Axis-2 activity word, or the fault reason when degraded. */}
        <Text as="span" mono size={10} weight={500} title={p.ownDegraded && n.reason ? n.reason : n.activity === "complete" ? n.reason : undefined}
          style={{ color: p.bottomColor, maxWidth: 108, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis",
            animation: p.bottomPulse ? "glance-softpulse 1.4s ease-in-out infinite" : "none" }}>{p.bottomText}</Text>
      </Box>
    </Box>
  );
}

runtime.features/glance/glanceNodeMotion.ts:
// The `glance-node` kit's MOTION wiring (#4032, epic #2942) — compiles the authored animation DATA
// into CSS once and injects it into a managed <style>. Mirrors `ensureGraphViewMotion` on its own
// style id; the animation data itself lives in `@/shared/ui/kit/glanceNodeAnimations` so the designer
// and this renderer read ONE definition.
import { animClassName, compileAnimationsCss, kitAnimations } from "@/shared/ui/kit";
import { GLANCE_NODE_KIT_ID, GLANCE_NODE_ANIMATIONS } from "@/shared/ui/kit/glanceNodeAnimations";

export { GLANCE_NODE_KIT_ID, GLANCE_NODE_ANIMATIONS };

/** The applying classes the node carries so the state-scoped rules match it. */
export const GLANCE_NODE_ANIM_CLASSES: string = GLANCE_NODE_ANIMATIONS.map((a) =>
  animClassName({ kit: GLANCE_NODE_KIT_ID, name: a.name }),
).join(" ");

/** The compiled motion CSS — produced ONCE from the authored data. Pure. */
export const GLANCE_NODE_MOTION_CSS: string = compileAnimationsCss(
  kitAnimations([{ id: GLANCE_NODE_KIT_ID, animations: GLANCE_NODE_ANIMATIONS }]),
);

const STYLE_ID = "bsc-glance-node-animations";

/** Inject the compiled node motion CSS into a dedicated managed `<style>` (idempotent). `doc` param'd
 *  for tests. */
export function ensureGlanceNodeMotion(doc: Document = document): void {
  if (!GLANCE_NODE_MOTION_CSS) return;
  let el = doc.getElementById(STYLE_ID) as HTMLStyleElement | null;
  if (!el) {
    el = doc.createElement("style");
    el.id = STYLE_ID;
    doc.head.appendChild(el);
  }
  if (el.textContent !== GLANCE_NODE_MOTION_CSS) el.textContent = GLANCE_NODE_MOTION_CSS;
}

runtime.features/glance/GlancePlanScreen.tsx:
// A worker's PLAN — the issues it owns (#4102).
//
// The third screen of an open agent node, beside Stream and Logs. Stream shows what the agent is
// SAYING and Logs what it EMITTED; neither answers "what is this worker actually responsible for".
// That question was only answerable by reading its kickoff or the plan.db by hand.
//
// ── WHERE THE DATA COMES FROM ───────────────────────────────────────────────────────────────────
// Ownership is LOCAL: `AgentStream.issues` carries the refs, so the list renders with no network and
// no token. GitHub is an OVERLAY supplying only open/closed (#2444: render local-first, never
// token-gate). A disconnected user still sees exactly which issues are theirs — they just don't get
// the state chips, and the screen says so rather than showing a silent, confident zero.
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import { normalizeRef } from "./lib/fleetPlanProgress";
import type { StreamProgress } from "./lib/streamProgress";

export interface PlanScreenIssue {
  /** As stored, e.g. `#3898` — shown verbatim so it matches the plan and the board. */
  ref: string;
  /** `true` closed, `false` open, `undefined` when the overlay could not resolve it. */
  closed?: boolean;
}

/** Join a stream's refs to the overlay. Pure + exported so the join is testable without a render.
 *
 *  Order is the PLAN's order, not sorted by state: the plan sequences a worker's work, and re-sorting
 *  it (done-first, say) would quietly hide that sequence. */
export function planScreenIssues(
  refs: readonly string[],
  states: ReadonlyMap<string, boolean>,
): PlanScreenIssue[] {
  const seen = new Set<string>();
  const out: PlanScreenIssue[] = [];
  for (const ref of refs) {
    const key = normalizeRef(ref);
    if (seen.has(key)) continue;      // a ref listed twice is one issue, not two
    seen.add(key);
    out.push({ ref, closed: states.get(key) });
  }
  return out;
}

/** `3/7` — the same counts the node's bar renders, so the two can never disagree. */
export function progressLabel(p: StreamProgress | undefined): string {
  return p && p.total > 0 ? `${p.done}/${p.total}` : "";
}

export function GlancePlanScreen({
  issues, progress, unresolved, loading,
}: {
  issues: readonly PlanScreenIssue[];
  progress?: StreamProgress;
  /** The overlay is unavailable (no token / fetch failed), so states are unknown. */
  unresolved?: boolean;
  loading?: boolean;
}) {
  if (issues.length === 0) {
    return (
      <Box style={{ padding: "18px 16px" }}>
        <Text as="div" size={12.5} tone="muted" style={{ lineHeight: 1.6, maxWidth: 380 }}>
          This worker owns no issues in the plan. It runs as a standing agent — the director assigns it
          work directly rather than from a planned list.
        </Text>
      </Box>
    );
  }

  const label = progressLabel(progress);

  return (
    <Box style={{ display: "flex", flexDirection: "column", height: "100%", minHeight: 0 }}>
      <Row justify="between" align="center" style={{ padding: "8px 12px", borderBottom: "1px solid var(--border)", flex: "none" }}>
        <Text mono size="xs" tone="dim">OWNED ISSUES</Text>
        {label ? <Text mono size="xs" tone="dim">{label}</Text> : null}
      </Row>

      {/* The bar is repeated here deliberately: at graph zoom the node's own 3px edge fill is often
          unreadable, and this screen is where a user comes for the detail. Same counts, one source. */}
      {progress && progress.total > 0 ? (
        <Box aria-hidden style={{ height: 3, background: "var(--border)", flex: "none" }}>
          <Box style={{
            width: `${(progress.done / progress.total) * 100}%`, height: "100%",
            background: "var(--accent)", transition: "width 220ms ease",
          }} />
        </Box>
      ) : null}

      <Box style={{ flex: 1, minHeight: 0, overflowY: "auto" }}>
        {issues.map((i) => {
          // Three distinct states, and they must LOOK distinct: closed, open, and unknown. Rendering
          // "unknown" as open would be the same class of confident-wrong the progress bar avoids.
          const glyph = i.closed === undefined ? "·" : i.closed ? "✓" : "○";
          const color = i.closed === undefined
            ? "var(--fg-muted)"
            : i.closed ? "var(--accent)" : "var(--fg)";
          return (
            <Row
              key={i.ref}
              gap="sm"
              align="center"
              style={{ padding: "6px 12px", borderBottom: "1px solid var(--border-subtle, var(--border))" }}
            >
              <Text as="span" mono size="xs" aria-hidden style={{ color, flex: "none", width: 12 }}>{glyph}</Text>
              <Text
                as="span" mono size="xs"
                style={{ flex: "none", color, textDecoration: i.closed ? "line-through" : undefined }}
              >
                {i.ref}
              </Text>
              <Text as="span" size="xs" tone="dim" style={{ flex: "none" }}>
                {i.closed === undefined ? (loading ? "checking…" : "state unknown") : i.closed ? "closed" : "open"}
              </Text>
            </Row>
          );
        })}
      </Box>

      {unresolved ? (
        <Box style={{ padding: "8px 12px", borderTop: "1px solid var(--border)", flex: "none" }}>
          <Text as="div" size="xs" tone="dim" style={{ lineHeight: 1.5 }}>
            Connect GitHub to see which of these are closed. The list above is the plan and is always accurate.
          </Text>
        </Box>
      ) : null}
    </Box>
  );
}

runtime.features/glance/GlancePreviewMorph.tsx:
// GlancePreviewMorph (#2623) — the PREVIEW node growing in place into the running application, IN the
// graph. Mirrors GlanceStreamMorph (#2534): a world-layer child at the node's world coords that pans /
// zooms / scales WITH the graph, no portal, no scrim. Where the stream morph hosts the agent terminal,
// this hosts the finished app — a sandboxed iframe for a web/bundle (incl. a wgpu/wasm build) PreviewSource,
// a "running in its own window" state for a native app (launched on the desktop via WSLg/host, slice 4),
// or a placeholder until the verify-build (slice 3) produces one. Esc / outside-click / ✕ shrinks it back.
import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";
import { previewRender, type PreviewSource } from "@/shared/lib/preview/previewSource";
import type { ReviewFinding, ReviewSeverity } from "@/shared/lib/preview/previewReview";
import type { PreviewReview } from "./usePreviewReview";
import { NW, NH } from "./lib/glanceGraph";

const SEV_COLOR: Record<ReviewSeverity, string> = {
  blocker: "var(--danger, #e5484d)",
  issue: "var(--warning, #f5a623)",
  polish: "var(--fg-muted)",
};

const EXIT_MS = 420;
/** ~4× a node — the app wants room. World units (renders at world-size × zoom). */
const CARD_W = 720, CARD_H = 460;

export function GlancePreviewMorph({ node, source, name, building, onBuild, review, onClose }: {
  /** The preview node's world box (origin + return). */
  node: { x: number; y: number };
  /** What the verify-build produced, or null while the app hasn't been built yet. */
  source: PreviewSource | null;
  name: string;
  /** A verify-build is in flight. */
  building?: boolean;
  /** Kick the verify-build (#2623) — resolve the stack, build + serve, produce a PreviewSource. */
  onBuild?: () => void;
  /** The reviewer loop (#2623 slice 5b) — capture a shot, review it, confirm/dismiss its findings. */
  review?: PreviewReview;
  onClose: () => void;
}) {
  const [open, setOpen] = useState(false);
  const closingRef = useRef(false);

  useLayoutEffect(() => {
    const id = requestAnimationFrame(() => setOpen(true));
    return () => cancelAnimationFrame(id);
  }, []);

  const close = () => {
    if (closingRef.current) return;
    closingRef.current = true;
    setOpen(false);
    window.setTimeout(onClose, EXIT_MS);
  };

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") close(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Outside-click closes (a press-release that stayed put; a drag pans the graph). Mirrors the stream morph.
  useEffect(() => {
    let start: { x: number; y: number } | null = null;
    const onDown = (e: MouseEvent) => {
      start = (e.target as HTMLElement)?.closest(".glance-card") ? null : { x: e.clientX, y: e.clientY };
    };
    const onUp = (e: MouseEvent) => {
      if (!start) return;
      const moved = Math.abs(e.clientX - start.x) + Math.abs(e.clientY - start.y);
      start = null;
      if (moved <= 4) close();
    };
    window.addEventListener("mousedown", onDown, true);
    window.addEventListener("mouseup", onUp, true);
    return () => {
      window.removeEventListener("mousedown", onDown, true);
      window.removeEventListener("mouseup", onUp, true);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const cx = node.x + NW / 2, cy = node.y + NH / 2;
  const box = open
    ? { left: cx - CARD_W / 2, top: cy - CARD_H / 2, width: CARD_W, height: CARD_H }
    : { left: node.x, top: node.y, width: NW, height: NH };

  const render = source ? previewRender(source) : null;

  return (
    <Box
      className={`glance-card${open ? " open" : ""}`}
      role="dialog" aria-label={`${name} preview`}
      onMouseDown={(e) => e.stopPropagation()}
      onClick={(e) => e.stopPropagation()}
      style={{ position: "absolute", left: box.left, top: box.top, width: box.width, height: box.height, zIndex: 20 }}
    >
      <Box className="glance-card-body" style={{ display: "flex", flexDirection: "column", overflow: "hidden" }}>
        <Box style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 10px", borderBottom: "1px solid var(--border)", flex: "none" }}>
          <Text as="span" style={{ color: "var(--accent)" }}>▷</Text>
          <Text as="span" mono size={12} weight={600} style={{ flex: 1, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{name} · preview</Text>
          {source && review?.canCapture ? (
            <Box
              as="button"
              onClick={() => { if (!review.busy) void review.captureAndReview(); }}
              title="Capture this view and review it with Claude"
              style={{
                background: "none", border: "1px solid var(--border)", borderRadius: 5, padding: "2px 8px",
                color: review.busy ? "var(--fg-muted)" : "var(--accent)", cursor: review.busy ? "default" : "pointer",
                fontSize: 11, whiteSpace: "nowrap",
              }}
            >
              {review.busy ? "…reviewing" : "◉ Review"}
            </Box>
          ) : null}
          <Box as="button" onClick={close} title="Close (Esc)" style={{ background: "none", border: "none", color: "var(--fg-muted)", cursor: "pointer", fontSize: 14, lineHeight: 1 }}>✕</Box>
        </Box>
        <Box style={{ flex: 1, minHeight: 0, position: "relative", background: "var(--bg)" }}>
          {render?.mode === "iframe" ? (
            <iframe
              title={`${name} preview`}
              sandbox="allow-scripts allow-same-origin allow-forms allow-popups"
              src={render.src}
              srcDoc={render.srcDoc}
              style={{ width: "100%", height: "100%", border: "none", background: "#fff" }}
            />
          ) : render?.mode === "external" ? (
            <Box style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 12, padding: 24 }}>
              <Text as="div" size={22} aria-hidden>▶</Text>
              <Text as="div" size={13} weight={600} style={{ textAlign: "center" }}>{render.label} is running</Text>
              <Text as="div" size={12.5} tone="muted" style={{ textAlign: "center", maxWidth: 320, lineHeight: 1.6 }}>
                It's a native app, so it opened in its own window on your desktop. Interact with it there; close its window when you're done.
              </Text>
              {onBuild ? <Button variant="ghost" onClick={onBuild}>↻ Rebuild &amp; relaunch</Button> : null}
            </Box>
          ) : (
            <Box style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 14, padding: 24 }}>
              <Text as="div" size={12.5} tone="muted" style={{ textAlign: "center", maxWidth: 340, lineHeight: 1.6 }}>
                {building ? "Building your app — this runs its real build, then serves it here." : "Your finished application renders here."}
              </Text>
              {building ? (
                <Box aria-hidden bg="color-mix(in oklch, var(--accent), transparent 75%)" radius={2} style={{ height: 3, width: 160, overflow: "hidden" }}>
                  <Box bg="var(--accent)" style={{ height: "100%", width: "30%", animation: "scan 1.1s linear infinite" }} />
                </Box>
              ) : onBuild ? (
                <Button variant="primary" onClick={onBuild}>▷ Build to preview</Button>
              ) : null}
            </Box>
          )}
        </Box>
        {review && (review.findings.length > 0 || review.error) ? (
          <ReviewStrip review={review} />
        ) : null}
      </Box>
    </Box>
  );
}

/** The confirm-gated review inbox — pending findings (confirm/dismiss) + a confirmed tally — as a strip
 *  under the preview. Routing confirmed findings to the fleet is slice 5d. */
function ReviewStrip({ review }: { review: PreviewReview }) {
  return (
    <Box style={{ flex: "none", maxHeight: 132, overflowY: "auto", borderTop: "1px solid var(--border)", background: "var(--bg-elevated, var(--bg))" }}>
      {review.error ? (
        <Text as="div" size={11.5} style={{ color: "var(--danger, #e5484d)", padding: "6px 10px" }}>{review.error}</Text>
      ) : null}
      {review.pending.map((f) => (
        <Box key={f.id} style={{ display: "flex", alignItems: "flex-start", gap: 8, padding: "6px 10px", borderBottom: "1px solid var(--border)" }}>
          <SevDot f={f} />
          <Box style={{ flex: 1, minWidth: 0 }}>
            <Text as="div" size={12} weight={600}>{f.title}</Text>
            {f.detail ? <Text as="div" size={11.5} tone="muted" style={{ lineHeight: 1.5 }}>{f.detail}</Text> : null}
          </Box>
          <Box as="button" onClick={() => review.confirm(f.id)} title="Confirm — route this to the fleet"
            style={{ background: "none", border: "none", color: "var(--accent)", cursor: "pointer", fontSize: 13 }}>✓</Box>
          <Box as="button" onClick={() => review.dismiss(f.id)} title="Dismiss"
            style={{ background: "none", border: "none", color: "var(--fg-muted)", cursor: "pointer", fontSize: 13 }}>✕</Box>
        </Box>
      ))}
      {review.confirmed.length > 0 ? (
        <Box style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 10px" }}>
          <Text as="span" size={11.5} tone="muted" style={{ flex: 1 }}>✓ {review.confirmed.length} confirmed</Text>
          <Button variant="primary" onClick={() => { void review.dispatch(); }}>→ Route to fleet</Button>
        </Box>
      ) : null}
      {review.routed.length > 0 ? (
        <Text as="div" size={11.5} tone="muted" style={{ padding: "6px 10px" }}>
          ✦ {review.routed.length} routed to the fleet — the director will pick them up.
        </Text>
      ) : null}
      {review.pending.length === 0 && review.confirmed.length === 0 && review.routed.length === 0 && !review.error ? (
        <Text as="div" size={11.5} tone="muted" style={{ padding: "6px 10px" }}>No findings — this screen looks good.</Text>
      ) : null}
    </Box>
  );
}

function SevDot({ f }: { f: ReviewFinding }) {
  return <Box aria-hidden title={f.severity} style={{ flex: "none", width: 8, height: 8, marginTop: 4, borderRadius: "50%", background: SEV_COLOR[f.severity] }} />;
}

