runtime.features/glance/lib/agentStall.ts:
// Agent-health watchdog (#2541) — the piece that GENERATES the Glance "warning" from live agent state,
// not from a crash. A `bsc-wait` (an EXPECTED pause for the user) is calm while it's fresh — the project
// reads activity "waiting". But once a wait OVERSTAYS its welcome (no instructions for N minutes), it's a
// stall the user should be pulled to: it escalates the project to health "warning" (orange dot) with a
// duration reason ("<note> · Nm"), which the existing dot+reason pipeline renders for free.
//
// Deliberately NOT routed through errordb / the fault-triage fix loop (#2265): a "no instructions" stall
// needs the USER to act, not a fix dispatched to the director. It's an ephemeral, derived health overlay
// (like liveness, #2263) — it clears the instant the agent resumes. Pure; `now` is injected for testing.
import type { ProjectLite } from "./glanceData";
import type { GHealth, GActivity, GRawNode } from "./glanceGraph";
import { fleetPaneId } from "@/app/console/lib/paneIdentity";

/** A `bsc-wait` parked longer than this escalates from the calm "waiting" activity to an orange
 *  "warning" health. 10 min — long enough that a normal think/confirm pause stays calm. Overridable per
 *  call so a Settings field can drive it later (#2541 follow-up). */
export const STALL_WARN_MS = 10 * 60_000;

/** The minimal waiting-session shape the watchdog reads — a projection of `CoordState.waiting`. */
export interface WaitLite { session: string; reason: string; at: number }

/** The project (plan) key that owns a session/pane id — everything before the first ':' (pane ids are
 *  `<key>:<stream>` / `<key>:director` / `<key>:<repo>:triage`, all prefixed by the plan key, #2409). */
export function projectKeyOfSession(session: string): string {
  const i = session.indexOf(":");
  return i < 0 ? session : session.slice(0, i);
}

/**
 * Keep only the waits whose session still EXISTS (#3429) — the liveness guard the L0 watchdog was missing.
 *
 * `CoordState.waiting` is a replay of the coord log: an entry is cleared only by a LATER event from that
 * same session, and killing a pane emits none. So a wait parked by a long-dead agent stayed outstanding
 * forever while `now - w.at` only grew, pinning its project orange permanently — a `warning` that no longer
 * described anything. A session that no longer exists cannot be waiting on the user.
 *
 * `livePaneIds` is the same pruned set the L1 overlay reads (tab membership minus ended/disabled panes), so
 * both layers decide "does this session exist?" from one signal. Pure.
 */
export function liveWaits(waiting: WaitLite[], livePaneIds: ReadonlySet<string>): WaitLite[] {
  return waiting.filter((w) => livePaneIds.has(w.session));
}

const worse = (a: GHealth, b: GHealth): boolean => a === "error" && b !== "error";

/**
 * Escalate PARKED agents onto the Glance node axes (#2541 watchdog). Per project the OLDEST outstanding
 * `bsc-wait` decides: while it's under `warnMs` the project reads a calm activity "waiting"; once it
 * exceeds `warnMs` it escalates to health "warning" with a "<note> · Nm" reason. Only ever ESCALATES
 * health (never downgrades an already-worse state). Pure.
 *
 * Apply BEFORE the errordb fault overlay (`applyFaultHealth`) so a real error still beats a stall.
 */
export function applyStallHealth(projects: ProjectLite[], waiting: WaitLite[], now: number, warnMs = STALL_WARN_MS): ProjectLite[] {
  if (waiting.length === 0) return projects;
  const oldest = new Map<string, WaitLite>();
  for (const w of waiting) {
    const key = projectKeyOfSession(w.session);
    const prev = oldest.get(key);
    if (!prev || w.at < prev.at) oldest.set(key, w);
  }
  return projects.map((p) => {
    const w = oldest.get(p.id);
    if (!w) return p;
    const elapsed = now - w.at;
    if (elapsed < warnMs) return { ...p, activity: "waiting" }; // fresh, expected pause — stays calm
    const minutes = Math.max(1, Math.floor(elapsed / 60_000));
    const note = w.reason?.trim() || "no instructions";
    const health: GHealth = worse(p.health ?? "healthy", "warning") ? (p.health as GHealth) : "warning";
    return { ...p, activity: "waiting", health, reason: `${note} · ${minutes}m` };
  });
}

/** The live signals a fleet-drill (L1) node reads to lift off its planned rest state (#3252). All keyed by
 *  the node's PANE id (`fleetPaneId` → `<project>:<stream>` / `<project>:director`). */
export interface FleetLiveSignals {
  /** Launched-tab membership — the session cell exists + is openable (`livePaneIds`). */
  livePaneIds: ReadonlySet<string>;
  /** Per-pane run status — `"run"` while the session is actively working (the console's aggregate state). */
  paneStatus: Record<string, string>;
  /** Parked `bsc-wait` sessions (from `CoordState.waiting`). */
  waiting: WaitLite[];
  /** Panes STOPPED at a permission prompt / input wait (#4005) — Claude Code's `Notification` hook,
   *  recorded as `bsc-activity attn` and read back from `bsc logs pane-activity`. Keyed by pane id.
   *  Nothing else in the app could see this state: such a pane is not `run` and has no `bsc-wait`, so
   *  it fell through to plain `idle` and looked identical to a session that had simply finished. */
  attention?: ReadonlySet<string>;
  /** Sessions PARKED IN MAINTENANCE (#4010) — `bsc-maintain` (#1957): every owned issue is done, the
   *  worker stays alive and ready for the director to dispatch into. Keyed by pane id.
   *
   *  Modelled explicitly rather than left to fall through to `idle`, because a parked session's TUI is
   *  still alive: whether it reads `run` is a timing accident, and on the wrong side of that accident a
   *  finished worker keeps the building outline forever. */
  maintaining?: ReadonlySet<string>;
  /** Panes the auto-end marked FINISHED (#4027) — `bsc-done` → `endedPanes`, valued by the verdict
   *  plan.db gave (`done` / `needs-attention` / `blocked`), not the worker's say-so. Keyed by pane id.
   *
   *  Needed here because `livePaneIds` EXCLUDES ended panes, so without this an ended worker falls
   *  through to `off` — indistinguishable from one that never launched. */
  ended?: Record<string, { state: string }>;
  /** Epoch now — injected (impure in render). */
  now: number;
  /** Stall threshold; a wait beyond it escalates to `warning`. Defaults to {@link STALL_WARN_MS}. */
  warnMs?: number;
  /** QUARANTINED panes (#3916) — the warden hard-paused these: it killed the PTY and marked why. Keyed
   *  by pane id, valued by the summary the warden recorded. Until now quarantine was invisible in Glance
   *  (grep found no handling outside `resumeProject`'s comments), so a hard-paused worker read as a plain
   *  `off` node — indistinguishable from one that was simply never launched. */
  quarantined?: Record<string, { summary?: string }>;
  /** HELD streams (#3931) — the dependency gate refused to start these because an upstream has not
   *  landed. Keyed by STREAM id (not pane id: there is no pane, that is the point). Same argument as
   *  quarantine: a held stream has no session, so it fell through to a plain `off` node and was
   *  indistinguishable from one that was never planned — the user could not tell "waiting its turn"
   *  from "broken". A `deadlocked` stream is an ERROR (it can never start on its own); an ordinary
   *  held one stays `off` but now carries the reason that explains itself. */
  held?: Record<string, { reason: string; deadlocked: boolean }>;
}

/**
 * Overlay the LIVE session state onto a project's fleet-drill (L1) agent nodes (#3252, the #2541 axes) —
 * the agent twin of the L0 {@link applyStallHealth}. Each node is keyed by its pane id
 * `fleetPaneId(projectKey, node.id)`, and its OWN health/activity is set from what its session is doing NOW:
 *
 *   - not launched (NO session exists)           → off · idle
 *   - launched + running (`paneStatus === "run"`) → healthy · building
 *   - launched + parked on a fresh `bsc-wait`    → healthy · waiting
 *   - that wait overstayed `warnMs`              → warning · waiting (reason "<note> · Nm")
 *   - launched but quiet (between prompts)       → idle · idle  (it EXISTS but is not working)
 *
 * The `preview` node (not an agent) is left untouched. The director gets the same treatment via
 * `<project>:director`, so it finally moves off idle. Pure — apply to `rawNodes` BEFORE `buildGraph` so the
 * dependency rollup + inherited-health recompute over the live values.
 */
export function applyFleetLiveStatus(nodes: GRawNode[], projectKey: string, sig: FleetLiveSignals): GRawNode[] {
  const warnMs = sig.warnMs ?? STALL_WARN_MS;
  const waitByPane = new Map(sig.waiting.map((w) => [w.session, w] as const));
  return nodes.map((n) => {
    if (n.preview) return n; // not an agent — its own healthy/live state stands
    const paneId = fleetPaneId(projectKey, n.id);
    // FINISHED BY THE PLAN (#4124) — every issue this node owns is done.
    //
    // Completion was derived ONLY from runtime session signals: an `ended` verdict of `done`, or an
    // explicit maintenance park. Both are ephemeral — they describe a session, and a session ends. The
    // issues do not: a worker that finished its lane last week still finished it, whether or not
    // anything is running now. So the two QUIET branches below (no session / live but idle) read this
    // first, and a node whose work is done stops reporting `idle`, which is what a node with nothing to
    // do also reports. Live-WORKING and blocked-on-a-person states still outrank it: what a session is
    // doing right now is the more urgent fact, and a worker parked on a question is still parked.
    // Two sources, because neither is complete alone. The PLAN says every owned issue is closed. A
    // `maintain` record says the worker itself declared it finished and stood by (#1957) — durable
    // evidence it got there, and for a fleet whose plan.db carries no issue rows it is the ONLY
    // evidence. Measured: 34 panes have emitted `maintain`.
    const finished =
      (!!n.progress && n.progress.total > 0 && n.progress.done >= n.progress.total) ||
      !!sig.maintaining?.has(paneId);
    const asFinished = (reason: string) =>
      ({ ...n, health: "complete" as GHealth, activity: "complete" as GActivity, reason });
    // QUARANTINE FIRST (#3916): the warden kills the PTY when it quarantines, so a quarantined pane is
    // never in `livePaneIds` and would otherwise fall through to `off` — reading as "never launched"
    // rather than "hard-paused, here is why". It must outrank every other state: this is the one the
    // user has to act on, and Resume deliberately refuses to relaunch it.
    const q = sig.quarantined?.[paneId];
    if (q) {
      return {
        ...n,
        health: "error" as GHealth,
        activity: "idle" as GActivity,
        reason: q.summary?.trim() || "quarantined by the warden",
      };
    }
    // HELD BY THE DEPENDENCY GATE (#3931) — checked before the plain `off` fall-through for exactly the
    // reason quarantine is: a held stream has no pane, so it would render as an anonymous dark node and
    // the user would have no way to tell "waiting on its upstream" from "never planned". A DEADLOCK is
    // an error the user must fix (the plan's `dependsOn` has a cycle, so it can never start on its own);
    // an ordinary hold is not a fault, so it keeps `off` health and just explains itself.
    const h = sig.held?.[n.id];
    if (h && !sig.livePaneIds.has(paneId)) {
      return {
        ...n,
        health: (h.deadlocked ? "error" : "off") as GHealth,
        activity: "waiting" as GActivity,
        reason: h.reason,
      };
    }
    // FINISHED (#4027) — above the `off` fall-through on purpose, and for the same reason quarantine
    // and held are: `livePaneIds` excludes ended panes, so a worker that completed every issue it owned
    // would render as `off` — exactly what a NEVER-LAUNCHED node looks like. The one state that has
    // earned a distinct reading would be the one state that loses it.
    //
    // Only a `done` verdict reads complete. `needs-attention` / `blocked` are endings too, but they are
    // endings that want a person — they keep falling through to the states that say so.
    const endState = sig.ended?.[paneId]?.state;
    if (endState === "done") {
      return { ...n, health: "complete" as GHealth, activity: "complete" as GActivity, reason: "every owned issue complete" };
    }

    // NOT LAUNCHED — there is no session behind this node. That is `off`, not `idle`: the two states
    // were indistinguishable while both rendered idle, so a node with no session read as one that was
    // merely quiet, and its empty log view looked like a broken log rather than an absent session.
    // `off` = no session exists · `idle` = a session exists but is not working · `healthy` = working.
    if (!sig.livePaneIds.has(paneId)) {
      // #4124: `off` is "never launched". A worker that finished everything and whose session has since
      // been reclaimed is not that, and rendering it identically loses the one state that was earned.
      return finished
        ? asFinished("every owned issue complete — no session running")
        : { ...n, health: "off" as GHealth, activity: "idle" as GActivity };
    }
    // BLOCKED ON A PERSON (#4005) — a `bsc-wait` park, or a session stopped at a permission prompt.
    //
    // A wait used to read `healthy` (green, calm) for ten minutes and only then flip to `warning`.
    // Both readings were wrong in the same way: green says "nothing to do" about a session that is
    // waiting on YOU, and orange says "something is degrading" about a normal hand-off. It is neither
    // — it is a request, so it gets its own health. The elapsed-time note is kept, because how long it
    // has been waiting is still worth knowing; it is just no longer the thing that makes it visible.
    const wait = waitByPane.get(paneId);
    if (wait) {
      const elapsed = sig.now - wait.at;
      const note = wait.reason?.trim() || "no instructions";
      const minutes = Math.max(1, Math.floor(elapsed / 60_000));
      const reason = elapsed >= warnMs ? `${note} · ${minutes}m` : note;
      // #4046 — `healthy` health, `waiting` activity. Nothing is WRONG with a worker parked on a
      // question; it is doing a thing called waiting. The reason string still says what it waits on.
      return { ...n, health: "healthy" as GHealth, activity: "waiting" as GActivity, reason };
    }
    if (sig.attention?.has(paneId)) {
      return {
        ...n,
        health: "healthy" as GHealth,
        activity: "waiting" as GActivity,
        reason: "stopped for you — permission prompt or awaiting input",
      };
    }
    // PARKED IN MAINTENANCE (#4010) — before the run->building branch, deliberately. A maintaining
    // worker's session is still alive, so `paneStatus` may well read "run"; checked after, it would
    // keep the building outline forever despite having finished everything it owns.
    //
    // It stays BELOW the wait/attention branches: a park needs a person, standing-by does not. The
    // RECLAIMED case (session gone) is handled at the liveness gate instead, via `finished` — putting
    // this whole branch above that gate would have let maintenance outrank a `bsc-wait`.
    //
    // It renders as the PLAIN node — no outline, no pulse — because there is nothing for anyone to do
    // about it. The explanation rides in `reason`, which the hover title and the inspector's REASON
    // tile both show, so the state is still discoverable without being loud.
    if (sig.maintaining?.has(paneId)) {
      // #4027: `complete`, not `idle`. A worker standing by having finished everything it owns and one
      // that happens to be quiet are different facts, and they used to render as the same word.
      return { ...n, health: "complete" as GHealth, activity: "complete" as GActivity, reason: "maintenance — owned issues complete, standing by for dispatch" };
    }
    if (sig.paneStatus[paneId] === "run") return { ...n, health: "healthy" as GHealth, activity: "building" as GActivity };
    // Launched, but not working: the session EXISTS and is quiet ⇒ `idle` on both axes. It used to read
    // `healthy` here ("subtly live"), which collided with a genuinely working session — and left `idle`
    // free to be misread as the no-session state. Health now tracks existence + work, not mere launch.
    // #4042 — `healthy`, not `idle`: the session EXISTS and nothing is wrong, which is what healthy
    // means. The activity word still says `idle`, so "at rest" is not lost — the two axes just stop
    // saying the same thing twice.
    // #4124: a live session with nothing left to do is COMPLETE, not merely quiet. `idle` is the word
    // for "a session exists and is not working", which is true here but is the least of what is true.
    return finished
      ? asFinished("every owned issue complete")
      : { ...n, health: "healthy" as GHealth, activity: "idle" as GActivity };
  });
}

runtime.features/glance/lib/fleetIssueState.ts:
// Resolving a fleet's issue states WITHOUT a React render (#4103).
//
// #4102 put the GitHub overlay behind `useFleetIssueState`, a hook — which is right for the graph, and
// useless to the three places that decide whether a worker is FINISHED: the progress-gated relaunch
// (`resumeProjectFleet`), the dependency gate (`useFleetHeld`) and the publish-time prune
// (`usePlanPublish`). Those run in async callbacks, not renders.
//
// So the fetch lives here as a plain async function and the hook sits on top of it. One query builder,
// one parse, two entry points — a second copy would be the thing that eventually disagrees about
// whether an issue is closed.
import { githubGraphql } from "@/shared/lib/github/github";
import { groupRefsByRepo, buildIssueStateQuery, parseIssueStates } from "./issueStateQuery";
import { normalizeRef } from "./fleetPlanProgress";

/** Same window the hook uses — served from the backend's ETag cache, so the gate and the graph do not
 *  each spend a call. */
const MAX_AGE_SECS = 120;

/** A stream as this needs it — structural, so a caller does not have to hand over a whole `AgentStream`. */
export interface RefBearingStream {
  repo?: string;
  issues?: readonly string[];
}

/**
 * The refs GitHub reports CLOSED, returned in each stream's OWN ref spelling.
 *
 * That spelling is the whole point. `streamComplete` asks `stream.issues.every((r) => done.has(r))`,
 * and a stream stores `"#3898"` while the GitHub response carries the number `3898`. A set of
 * normalized refs would therefore match NOTHING and every stream would read as unfinished — the exact
 * silent failure #4103 is about, reintroduced from the other side. Emitting the original strings makes
 * the formats agree by construction rather than by convention.
 *
 * Returns an EMPTY set on any failure (no token, offline, a GraphQL error). That is deliberate and
 * matches the pre-existing rule these gates already follow: absent evidence must under-report
 * completion, never over-report it. Claiming a stream finished because a fetch failed would skip a
 * worker that still has work.
 */
export async function resolveClosedRefs(
  streams: readonly RefBearingStream[],
): Promise<Set<string>> {
  const out = new Set<string>();
  const query = buildIssueStateQuery(groupRefsByRepo(streams));
  if (!query) return out;                    // nothing addressable ⇒ no request at all
  try {
    const states = parseIssueStates(await githubGraphql<unknown>(query, null, { maxAgeSecs: MAX_AGE_SECS }));
    for (const s of streams) {
      for (const ref of s.issues ?? []) {
        if (states.get(normalizeRef(ref)) === true) out.add(ref);
      }
    }
  } catch {
    return new Set();                        // fail CLOSED — under-report, never over-report
  }
  return out;
}

runtime.features/glance/lib/fleetPlanProgress.ts:
// Per-worker issue progress, derived from the FLEET PLAN (#4102).
//
// ── WHY THIS EXISTS ALONGSIDE `streamProgress.ts` ────────────────────────────────────────────────
// #4050 derived progress entirely from plan.db's `issues` table: it partitioned `bsc plan list` by
// each issue's `stream` field. That is correct wherever those rows exist — and invisible wherever they
// do not. Measured on the live store (`plans/studio-code.db`): 40 `fleet_streams`, 40 `features`, and
// ZERO `issues`. So every stream got `total: 0`, and `GlanceNode`'s (correct) `total > 0` guard hid a
// bar it had no data for. The bars had simply never had an input.
//
// Ownership was not missing, only stored elsewhere: a stream carries its own work as GitHub refs in
// `AgentStream.issues` (`["#3898","#3979"]`) — 60 refs across 24 of the 40 streams. That is the
// authoritative ownership record, it is already in memory via the fleet plan, and it needs no network.
//
// ── THE SPLIT: OWNERSHIP IS LOCAL, DONE-NESS IS EVIDENCE ─────────────────────────────────────────
// So `total` comes from the plan (always available, always right) and `done` comes from whatever
// evidence exists that a ref is finished — plan.db statuses where rows were authored, GitHub
// open/closed otherwise. Unioning them means a project with a populated plan.db keeps working exactly
// as it did under #4050, while one without it stops rendering a permanently empty graph.
//
// Keeping `total` off plan.db is the actual fix. A denominator that silently drops to zero does not
// look broken — it looks like a fleet that owns no work.

import type { StreamProgress } from "./streamProgress";

/** The minimum shape this needs from a fleet stream — kept structural so the pure fn does not drag in
 *  the whole `AgentStream` (and so tests can state a stream in one line). */
export interface OwningStream {
  id: string;
  /** Issue refs this stream owns, e.g. `["#3898"]`. */
  issues: readonly string[];
}

/** Normalise a ref for comparison: `#3898`, `3898` and ` #3898 ` are the same issue.
 *
 *  Worth doing rather than trusting equality — the refs come from three places (the plan's stored
 *  strings, plan.db's `ref` column, GitHub's numeric `number`) and a formatting mismatch between any
 *  two would show as a bar stuck at 0/N, which is exactly the failure this file exists to end. */
export function normalizeRef(ref: string | number): string {
  return String(ref).trim().replace(/^#/, "");
}

/**
 * Per-stream `done / total` for a fleet.
 *
 * `total` is what the stream OWNS. `done` counts its refs present in `doneRefs` — so a ref that is
 * done but owned by nobody cannot inflate anyone's progress, and a stream owning nothing yields
 * `total: 0`, which the node renders as NO bar (deliberately: an empty bar and a zero-progress bar
 * say different things, and only one of them is true).
 *
 * Pure. `doneRefs` may hold refs in either form; both sides are normalised.
 */
export function fleetPlanProgress(
  streams: readonly OwningStream[],
  doneRefs: ReadonlySet<string>,
  /** When set, ALSO emit this node id carrying the union of EVERY stream's refs (#4122).
   *
   *  The director is not a stream — it owns no lane — so a per-stream map leaves its node with no
   *  progress at all. But it is the one agent responsible for the whole board, so its bar is the
   *  project's: every issue any worker owns, de-duplicated, because two streams naming one ref is one
   *  piece of work and double-counting would make the director's denominator disagree with the sum of
   *  its workers'. */
  aggregateId?: string,
): Map<string, StreamProgress> {
  const done = new Set<string>();
  for (const r of doneRefs) done.add(normalizeRef(r));

  const out = new Map<string, StreamProgress>();
  for (const s of streams) {
    // De-duplicate within a stream: a ref listed twice would push `done` past `total` and render a bar
    // over 100%. `progressFraction` clamps the fill, but the "3/2" label beside it would still be wrong.
    const refs = new Set(s.issues.map(normalizeRef));
    let d = 0;
    for (const r of refs) if (done.has(r)) d += 1;
    out.set(s.id, { done: d, total: refs.size });
  }

  if (aggregateId) {
    // Union across streams, then count — NOT a sum of the per-stream rows, which would double-count a
    // ref two streams both claim.
    const all = new Set<string>();
    for (const s of streams) for (const r of s.issues) all.add(normalizeRef(r));
    let d = 0;
    for (const r of all) if (done.has(r)) d += 1;
    out.set(aggregateId, { done: d, total: all.size });
  }
  return out;
}

/**
 * Combine the ref-derived progress with plan.db's own, per stream.
 *
 * A stream that owns refs uses the ref-derived numbers — that is the fix, and its denominator cannot
 * silently collapse to zero. A stream that owns NONE falls back to plan.db's entry, which preserves
 * #4050 exactly where it already worked: a project whose planner run authored issue rows carrying a
 * `stream` field, but whose stream records never listed the refs, still shows the bar it showed before.
 *
 * Neither source is dropped, so this cannot regress a project that was working.
 */
export function mergeStreamProgress(
  fromRefs: ReadonlyMap<string, StreamProgress>,
  fromPlanDb: ReadonlyMap<string, StreamProgress>,
): Map<string, StreamProgress> {
  const out = new Map<string, StreamProgress>(fromPlanDb);
  for (const [id, p] of fromRefs) {
    // `total === 0` means "owns no refs", which is not evidence of anything — let plan.db answer.
    if (p.total > 0) out.set(id, p);
  }
  return out;
}

/**
 * Union the done-evidence sources into the set `fleetPlanProgress` consumes.
 *
 * Both are partial and neither is authoritative alone: plan.db knows only what a planner run authored
 * (nothing, for a hand-assembled fleet), and GitHub knows only what a token could reach (nothing, when
 * disconnected). A ref that either source calls finished IS finished — treating one as authoritative
 * would make progress vanish the moment that source is the empty one, which is the bug being fixed.
 */
export function unionDone(...sources: ReadonlyArray<Iterable<string> | undefined>): Set<string> {
  const out = new Set<string>();
  for (const src of sources) {
    if (!src) continue;
    for (const r of src) out.add(normalizeRef(r));
  }
  return out;
}

runtime.features/glance/lib/glanceData.ts:
// Glance data adapter (#2206) — bridges the app's REAL project list into the graph model. Nodes come
// from the user's projects; the TOPOLOGY (roles · edge kinds · dependencies · status) is clearly-marked
// SAMPLE until a real cross-project dependency model exists (epic #2205, slice 4). Isolated here so
// wiring real edges later is a drop-in — the page + graph core never change.
import sampleGraphEmbedded from "@data/glance/sample-graph.json";
import type { GRawNode, GRawEdge, GRole, GHealth, GActivity } from "./glanceGraph";
import { kitNodeId, usesKitEdgeId, libraryNodeId, requiresEdgeId, mcpNodeId, usesMcpEdgeId, serviceNodeId, usesServiceEdgeId } from "./glanceGraph";
import { isProjectContract, type ProjectLink } from "./projectLinks";
// Cross-feature types only, via the barrel (#1309 boundary): the consumer index (`kitUsage`) whose
// (projectKey, kitId) edges the kit nodes are built from, plus the kit→library `requires` roll-up
// (`resolveKitLibraryRefs`, #3133) the caller resolves and hands in as plain data.
import type { KitConsumer, KitLibraryRef } from "@/features/designs";
// The project's application architecture (#3786/#3802) — the contract endpoint-type discriminator carried
// onto each project node. `import type` is erased at build (no runtime edge to the planner).
import type { AppType } from "@/features/planner";

export interface GlanceData { rawNodes: GRawNode[]; rawEdges: GRawEdge[]; sample: boolean }

/** A minimal project as the adapter needs it — id + display name, plus the two axes the caller has
 *  resolved (#2541): `health` (idle/healthy/warning/error) and `activity` (the lifecycle word), with an
 *  optional `reason` (the fault title) shown when health is degraded. `appType` (#3786) is the project's
 *  application architecture — the contract endpoint-type discriminator, absent ⇒ read as "application". */
export interface ProjectLite { id: string; name: string; role?: GRole; lifecycle?: string; health?: GHealth; activity?: GActivity; reason?: string; faults?: number; appType?: AppType; /** Issue completion (#4118) — carried onto the L0 node so a project shows the same bar a worker does. */ progress?: { done: number; total: number } }

/** A UI kit as the adapter needs it (#2571) — id + display name, so a kit node reads the kit's NAME
 *  (falling back to the id). The store's `Kit[]` is structurally assignable, so the caller passes it as-is. */
export interface KitLite { id: string; name: string }

/** An MCP server as the adapter needs it (#3786) — id + name + its per-server project scope + transport,
 *  so an mcp node reads the server's NAME and derives its `appType` from the transport. The store's
 *  `McpServer[]` is structurally assignable, so the caller passes it as-is. A server with an EMPTY
 *  `projects` list is GLOBAL (every session gets it) — not a specific contract, so it is skipped. */
export interface McpLite { id: string; name: string; projects: string[]; transport?: "stdio" | "http" }

/** The packaged SAMPLE project network — the spec's example (roles · edge kinds · a dependency CYCLE:
 *  reporting → analytics → reporting · hazards). No longer an auto-fallback for an empty app (#2272 — an
 *  unseeded Glance shows a REAL empty state, not the mock); kept as the seed of the curated app-state
 *  DEMO (#2272 slice 4). Marked `sample`. The nodes/edges live in `@data/glance/sample-graph.json`
 *  (#2419) — a plain embedded import, NOT config-dir-overlaid, because the demo snapshot is built on
 *  this spine and must stay byte-deterministic (stable gist bytes). */
export const SAMPLE_GRAPH: GlanceData = {
  sample: true,
  rawNodes: sampleGraphEmbedded.rawNodes as GRawNode[],
  rawEdges: sampleGraphEmbedded.rawEdges as GRawEdge[],
};

/** Build the Glance graph from the REAL project list: every project a node (its resolved role/status, or
 *  a derived role + idle). Cross-project dependency EDGES are NOT fabricated — the only project↔project
 *  edges are the user-drawn relationships (#2253), so an un-wired project is simply an isolated node. On
 *  top, one UI-KIT node per distinct `bsc ui` kit in use (#2571), edged to every consuming project so the
 *  network shows which projects SHARE a kit. Zero projects yields an EMPTY graph (`sample: false`) — the
 *  workspace renders a real empty state (#2272), no mock.
 *
 *  On top of that, the generalized CROSS-GRAPH library dimension (#3133): a project transitively `requires`
 *  every algorithm / sound node the components of its kits import, so the fenced band carries real library
 *  dependencies (the logistics example: a route-planner project → its `algo:` dijkstra node), not just kits.
 *
 *  On top of THAT, the external CONTRACT dimension (#3786): (Phase 1) one auto-derived node per MCP server
 *  SCOPED to ≥1 project in this graph, edged from each consuming project — mirroring the kit dimension; a
 *  GLOBAL server (`projects: []`) is skipped. (Phase 2) plus EXPLICIT, planner-declared contracts — a
 *  stored `ProjectLink` whose `target` is a `service` or `mcp` endpoint becomes an external band node
 *  edged from `from`, DEDUPED against the Phase-1 auto-mcp nodes by node id. A project's `appType` (#3802)
 *  is surfaced on its node as the endpoint-type discriminator.
 *
 *  @param kitUsage    the consumer index (`kitUsage`) — (projectKey, kitId) edges (from `@/features/designs`).
 *  @param kits        the kit library, so a kit node reads the kit's NAME (else its id).
 *  @param libraryRefs the kit→library `requires` roll-up (`resolveKitLibraryRefs`, #3133) — resolved by the
 *                     CALLER and memoized on the component list, because deriving it scans component source;
 *                     this function must stay cheap (it re-runs on every project-status tick).
 *  @param mcpServers  the MCP server store (#3786) — a scoped server (`projects` non-empty) becomes one
 *                     external contract node edged from each consuming project; a global server is skipped. */
export function buildGlanceData(
  projects: ProjectLite[],
  links: ProjectLink[] = [],
  kitUsage: KitConsumer[] = [],
  kits: KitLite[] = [],
  libraryRefs: KitLibraryRef[] = [],
  mcpServers: McpLite[] = [],
): GlanceData {
  const rawNodes: GRawNode[] = projects.map((p) => ({
    id: p.id,
    slug: p.name || p.id,
    // `role` survives as the curated-only accent (a demo project may declare one); the default is
    // benign and the old hash-per-id tier is GONE.
    role: p.role ?? "service",
    // #4062 — the DISCOVERED lifecycle intent, passed through UNDEFAULTED: an unclassified project
    // must render no chip at all rather than a confident guess (the #4052 lesson).
    lifecycle: p.lifecycle,
    health: p.health ?? "off",      // #2541 axis 1 — resolved by the caller from faults/liveness;
                                    // #4042: the default is `off` (nothing live behind it), not a second grey
    activity: p.activity ?? "idle", // #2551 axis 2 — RESTING default; `building` is derived from live agents, not a fallback
    // #4118 — issue completion, so an L0 project node draws the same bar a drilled worker does. This
    // list is EXPLICIT (not a spread), so a new field is dropped unless it is named here; that is how
    // the bar could be wired end-to-end and still never appear on the board.
    progress: p.progress,
    reason: p.reason,                  // the fault title shown when health is degraded
    faults: p.faults,                  // #2265: unresolved runtime-fault count (inspector)
    appType: p.appType,                // #3786/#3802: the contract endpoint-type discriminator (absent ⇒ "application", rendered plain)
    // `kind` is left ABSENT here (⇒ "project", #2571) so a project node's shape is byte-identical to before.
  }));
  // The project↔project contracts (#2253) — the real edges, filtered to PROJECT-target links between two
  // nodes that still exist. No fabricated topology; an un-wired project is simply an isolated node. A
  // contract whose target is an external service / mcp server (#3786 Phase 2) is NOT a project edge — it
  // is lifted into the band below.
  const ids = new Set(rawNodes.map((n) => n.id));
  const rawEdges: GRawEdge[] = links
    .filter((l) => isProjectContract(l) && ids.has(l.from) && ids.has(l.to))
    .map((l) => ({ id: l.id, from: l.from, to: l.to, kind: l.kind }));

  // The UI-KIT dimension (#2571): one node per DISTINCT kit that has ≥1 consumer AMONG the current
  // projects, edged from every consuming project to the shared kit node. The edge follows the graph's
  // consumer→provider convention (`from depends on to`): the PROJECT consumes the kit, so `from` is the
  // project and `to` is the kit — which lays the shared kit foundational and keeps a kit's `idle` health
  // from ever rolling up into a project. A stale usage row for a project not in this graph is skipped, so
  // a kit node is never emitted without a visible edge.
  const kitName = new Map(kits.map((k) => [k.id, k.name]));
  const consumersByKit = new Map<string, string[]>();
  for (const u of kitUsage) {
    if (!ids.has(u.projectKey)) continue;                    // consumer must be a project node in this graph
    const arr = consumersByKit.get(u.kitId) ?? [];
    if (!arr.includes(u.projectKey)) arr.push(u.projectKey); // dedupe a duplicate (projectKey, kitId)
    consumersByKit.set(u.kitId, arr);
  }
  for (const [kitId, consumers] of consumersByKit) {
    rawNodes.push({
      id: kitNodeId(kitId),
      slug: kitName.get(kitId) ?? kitId,
      kind: "kit",
      role: "infra",   // a kit is a shared foundational dependency; `category` absent ⇒ the canvas draws it as a kit
      health: "off",  // #4042 — a kit never RUNS, so it has no runtime health; `off` is now exactly that
      activity: "idle",
    });
    for (const projectKey of consumers) {
      rawEdges.push({ id: usesKitEdgeId(projectKey, kitId), from: projectKey, to: kitNodeId(kitId), kind: "uses-kit" });
    }
  }

  // The generalized CROSS-GRAPH LIBRARY dimension (#3133, epic #3114) — the same fenced band, now carrying
  // ALGORITHM + SOUND nodes with `requires` edges. The dependency is TRANSITIVE and derived, never authored:
  // a project consumes a kit (`kitUsage`), that kit's components import `@bsc/algorithms/…` / `@bsc/sounds/…`
  // (`resolveKitLibraryRefs`), therefore the project requires those library nodes. Edge direction matches the
  // kit dimension (consumer→provider), so a library node lands foundational in the band alongside the kits
  // and its `idle` health never rolls up into a project.
  //
  // Emitted AFTER the kit loop and gated on `consumersByKit`, so: a project with no library-importing kit is
  // byte-identical to before, and a library node never appears without ≥1 visible edge.
  const refsByKit = new Map<string, KitLibraryRef[]>();
  for (const ref of libraryRefs) {
    const arr = refsByKit.get(ref.kitId) ?? [];
    arr.push(ref);
    refsByKit.set(ref.kitId, arr);
  }
  const seenLibNode = new Set<string>();
  const seenReqEdge = new Set<string>();
  for (const [kitId, consumers] of consumersByKit) {
    for (const ref of refsByKit.get(kitId) ?? []) {
      const nodeId = libraryNodeId(ref.graph, ref.id);
      if (!seenLibNode.has(nodeId)) {
        // Deduped ACROSS kits: two kits requiring `fibonacci` share ONE band node (that sharing is the point
        // — the band shows a library node's full consumer set).
        seenLibNode.add(nodeId);
        rawNodes.push({
          id: nodeId,
          slug: ref.label || ref.id,
          kind: "library",
          library: ref.graph,  // the band/legend/inspector colour + kind word (algorithm · sound)
          role: "infra",       // a shared foundational dependency, like a kit
          health: "off",      // #4042 — a library never runs; `off` = no live session behind this node
          activity: "idle",
        });
      }
      for (const projectKey of consumers) {
        // Deduped per (project, node): a project consuming two kits that both require `fibonacci` draws ONE
        // edge, not a doubled one.
        const id = requiresEdgeId(projectKey, nodeId);
        if (seenReqEdge.has(id)) continue;
        seenReqEdge.add(id);
        rawEdges.push({ id, from: projectKey, to: nodeId, kind: "requires" });
      }
    }
  }

  // The external MCP-CONTRACT dimension (#3786, Phase 1 inter-app contracts) — the SAME shape as the kit
  // loop, mapped onto the MCP server store: one node per server SCOPED to ≥1 project in this graph, edged
  // from every consuming project. A server with an EMPTY `projects` list is GLOBAL (every session gets it),
  // so it is NOT a specific contract and is skipped. A scoped project not in this graph is skipped, so an
  // mcp node is never emitted without a visible edge. Deduped per (project, server) like the kit loop. Edge
  // direction follows the consumer→provider convention (project consumes the server), so the mcp node lands
  // foundational in the band and its `idle` health never rolls up into a project. The mcp node's `appType`
  // is derived from its transport — http ⇒ `api`, stdio (local) ⇒ `serverless` (the user's framing: "an
  // mcp server, which can be serverless").
  const consumersByMcp = new Map<string, string[]>();   // serverId → consuming project keys (in this graph)
  const mcpById = new Map<string, McpLite>();
  for (const s of mcpServers) {
    if (s.projects.length === 0) continue;               // global — not a specific contract, skip
    for (const projectKey of s.projects) {
      if (!ids.has(projectKey)) continue;                // consumer must be a project node in this graph
      const arr = consumersByMcp.get(s.id) ?? [];
      if (!arr.includes(projectKey)) arr.push(projectKey); // dedupe a duplicate (projectKey, serverId)
      consumersByMcp.set(s.id, arr);
      mcpById.set(s.id, s);
    }
  }
  for (const [serverId, consumers] of consumersByMcp) {
    const s = mcpById.get(serverId)!;
    rawNodes.push({
      id: mcpNodeId(serverId),
      slug: s.name || serverId,
      kind: "mcp",
      role: "infra",   // an external contract is a shared foundational dependency; `category` absent ⇒ the canvas draws it as an mcp node
      appType: s.transport === "http" ? "api" : "serverless", // http endpoint ⇒ api · stdio (local) ⇒ serverless
      health: "off",  // #4042 — an external contract never runs; `off` = no live session behind this node
      activity: "idle",
    });
    for (const projectKey of consumers) {
      rawEdges.push({ id: usesMcpEdgeId(projectKey, serverId), from: projectKey, to: mcpNodeId(serverId), kind: "uses-mcp" });
    }
  }

  // EXPLICIT, PLANNER-DECLARED external contracts (#3786 Phase 2) — a stored contract whose `target` is a
  // `service` or `mcp` endpoint (not another project) becomes an external BAND node edged from `from`. This
  // GENERALIZES the Phase-1 auto-derived mcp nodes (which come from the McpServer scope) to contracts the
  // planner declares directly via `bsc project link add … --target-type`. DEDUPED against the auto-mcp
  // nodes by node id: an explicit mcp contract to a server already in the scope reuses the ONE existing
  // node (`mcp:<serverId>`) and its edge id collides, so neither node nor edge is doubled. A `service`
  // target has no auto-derivation, so it always mints its own node. Additive + data-gated: no
  // external-target contracts ⇒ nothing added (byte-identical to Phase 1).
  const seenBandNodeId = new Set(rawNodes.map((n) => n.id)); // includes the auto-mcp nodes emitted above
  const seenEdgeId = new Set(rawEdges.map((e) => e.id));
  for (const l of links) {
    const t = l.target;
    if (!t || (t.type !== "service" && t.type !== "mcp")) continue; // project targets are drawn above
    if (!ids.has(l.from)) continue;                                 // the consumer must be a project in this graph
    const nodeId = t.type === "mcp" ? mcpNodeId(l.to) : serviceNodeId(l.to);
    if (!seenBandNodeId.has(nodeId)) {
      seenBandNodeId.add(nodeId);
      rawNodes.push({
        id: nodeId,
        slug: t.name || l.to,
        kind: t.type,        // "mcp" | "service"
        role: "infra",       // an external contract is a shared foundational dependency
        appType: t.appType,  // the planner-declared endpoint type (absent ⇒ rendered plain)
        health: "off",      // #4042 — an external contract never runs; `off` = no live session behind it
        activity: "idle",
      });
    }
    const edgeId = t.type === "mcp" ? usesMcpEdgeId(l.from, l.to) : usesServiceEdgeId(l.from, l.to);
    if (!seenEdgeId.has(edgeId)) {
      seenEdgeId.add(edgeId);
      rawEdges.push({ id: edgeId, from: l.from, to: nodeId, kind: t.type === "mcp" ? "uses-mcp" : "uses-service" });
    }
  }

  return { rawNodes, rawEdges, sample: false };
}

runtime.features/glance/lib/glanceFleet.ts:
// Glance fleet drill (#…) — the L1 graph you get by clicking a project on the L0 project network: that
// project's FLEET as a graph in the same Glance node/edge language (director + workers + a reviewer,
// wired by coordination edges), so the drill reads as one recursive graph zooming in. The topology is a
// deterministic SAMPLE per project until a real per-project fleet-plan feed lands (mirrors glanceData's
// sample project topology) — isolated here so wiring the real fleet later is a drop-in.
import type { GRawNode, GRawEdge, GRole, GEdgeKind, GNodeComm } from "./glanceGraph";
import type { GlanceData, ProjectLite } from "./glanceData";
import { hashAbs } from "./hash";
import type { FleetPlan } from "@/features/planner/fleet/planFleet";
import type { Persona } from "@/features/personas";
import { archetypeById, positionComms, type Team, type Position, type Relationship } from "@/features/teams";
import type { BlueprintTeam } from "@/features/planner/stages/blueprintTypes";

/** Session-role → Glance colour bucket, grouped by agent FUNCTION (#2561): ORCHESTRATE (planner ·
 *  director) = infra, BUILD (worker) = service, VERIFY (reviewer · tester · juror) = data, FLOW (issuer ·
 *  triage · documentor · designer — intake, routing, docs, UI) = client. The bucket drives the colour;
 *  the real session role rides as `roleLabel` + the legend reads the function-group names at L1. */
const ROLE_TO_GROLE: Record<string, GRole> = {
  planner: "infra", director: "infra", debugger: "infra",
  worker: "service",
  reviewer: "data", tester: "data", juror: "data",
  issuer: "client", triage: "client", documentor: "client", designer: "client",
};
const gRole = (role?: string): GRole => (role && ROLE_TO_GROLE[role]) || "service";

/** Fleet coordination kind → Org relationship ARCHETYPE (#2561, interim map until fleets are authored as
 *  Orgs). The archetype names the relationship (Oversees a review, Stewards a shared resource, Peers on a
 *  handoff) and expands into the communication forms shown in the edge inspector. The director hub is a
 *  `manages` relationship; plain `dependsOn` is a lateral `peers` seam. */
const KIND_TO_ARCHETYPE: Record<string, string> = {
  handoff: "peers", blocking: "peers", sequence: "peers", review: "oversees", notify: "peers", shared: "peers", mutex: "stewards",
};

/** Resolve the persona surfaced on a fleet node (#2561): who is at this terminal. */
function nodePersona(p: Persona | undefined): GRawNode["persona"] {
  return p ? { name: p.name, role: p.role, model: p.model, skills: p.skills ?? [], responsibilities: p.responsibilities ?? [] } : undefined;
}

/**
 * Project a {@link FleetPlan} into a real {@link Org} (#2563) — the "fleet as Org" bridge. Streams (+ an
 * enabled director) become POSITIONS (personas referenced by id); coordination becomes RELATIONSHIPS
 * tagged with their archetype, in ARCHETYPE-NATIVE direction: the director MANAGES each stream, a typed
 * edge maps its kind (producer→consumer), a plain `dependsOn` is a lateral peer seam. Reusing the Org
 * model lets the drill derive each agent's communication surface (`positionComms`) from ONE source of
 * truth — the foundation for later authoring the fleet as an Org. Pure + exported for testing.
 */
export function fleetToOrg(fleet: FleetPlan, team?: BlueprintTeam): Team {
  const positions: Position[] = fleet.streams.map((s) => ({ nodeId: s.id, kind: "agent", personaId: s.persona, label: s.name || s.id }));
  if (fleet.director?.enabled) positions.push({ nodeId: "director", kind: "agent", personaId: "director", label: "director" });
  const posIds = new Set(positions.map((p) => p.nodeId));
  // Authored-team archetype overlay (#2572): a `persona→persona` pair the blueprint team wired with an
  // archetype OVERRIDES the coordination-derived archetype for that pair — so the authored design's
  // semantics drive the drill wherever the team authored them. Empty (no team) ⇒ pure derived, unchanged.
  const authored = teamArchetypeByPersonaPair(team);
  const personaOf = new Map<string, string | undefined>(fleet.streams.map((s) => [s.id, s.persona]));
  personaOf.set("director", "director");
  const archOf = (from: string, to: string, derived: string): string => {
    const pf = personaOf.get(from), pt = personaOf.get(to);
    return (pf && pt && authored.get(`${pf}|${pt}`)) || derived;
  };
  const relationships: Relationship[] = [];
  const seen = new Set<string>();
  const rel = (from: string, to: string, archetype: string) => {
    if (from === to || !posIds.has(from) || !posIds.has(to)) return;
    const k = `${from}|${to}`;
    if (seen.has(k)) return;
    seen.add(k);
    relationships.push({ id: `r${relationships.length}`, archetype, from, to });
  };
  if (fleet.director?.enabled) for (const s of fleet.streams) rel("director", s.id, archOf("director", s.id, "manages")); // manager → report
  for (const e of fleet.edges ?? []) rel(e.from, e.to, archOf(e.from, e.to, KIND_TO_ARCHETYPE[e.kind] ?? "peers"));        // producer → consumer
  for (const s of fleet.streams) for (const dep of s.dependsOn) rel(dep, s.id, archOf(dep, s.id, "peers"));                // upstream ↔ dependent

  // Phase 2 (#2575): ADD the team's authored relationships that have no derived edge, INSTANTIATED onto
  // the streams by persona — a team rel posA→posB becomes every {posA-persona stream} × {posB-persona
  // stream} pair with the team's archetype. `rel` dedups vs the derived edges above (a pair with both
  // keeps its slice-3-overlaid archetype), so this only ADDS authored relationships the coordination
  // didn't wire. Nodes stay the fleet streams (identity + liveness preserved).
  if (team) {
    const streamsByPersona = new Map<string, string[]>();
    for (const s of fleet.streams) if (s.persona) {
      const arr = streamsByPersona.get(s.persona);
      if (arr) arr.push(s.id); else streamsByPersona.set(s.persona, [s.id]);
    }
    const personaOfPos = new Map(team.positions.map((p) => [p.nodeId, p.personaId]));
    for (const tr of team.relationships) {
      const pa = personaOfPos.get(tr.from), pb = personaOfPos.get(tr.to);
      if (!pa || !pb) continue;
      for (const sa of streamsByPersona.get(pa) ?? []) for (const sb of streamsByPersona.get(pb) ?? []) rel(sa, sb, tr.archetype);
    }
  }
  return { id: "fleet", name: "Fleet", positions, relationships };
}

/** A `personaFrom|personaTo → archetype` lookup from a blueprint {@link BlueprintTeam}'s authored
 *  relationships (#2572) — so the fleet projection can override a coordination pair's archetype with the
 *  team's authored one when the two streams' personas match (direction included). Empty for no team. */
function teamArchetypeByPersonaPair(team?: BlueprintTeam): Map<string, string> {
  const m = new Map<string, string>();
  if (!team) return m;
  const personaOf = new Map(team.positions.map((p) => [p.nodeId, p.personaId]));
  for (const r of team.relationships) {
    const pf = personaOf.get(r.from), pt = personaOf.get(r.to);
    if (pf && pt) m.set(`${pf}|${pt}`, r.archetype);
  }
  return m;
}

/** Convert a blueprint {@link BlueprintTeam} into a standalone {@link Org} (#2572) — the team is already
 *  `{positions, relationships}`, so this just stamps the library-identity fields. Exported for phase 2
 *  (rendering the drill from the authored team directly). */
export function teamToOrg(team: BlueprintTeam): Team {
  return { id: "team", name: "Team", positions: team.positions, relationships: team.relationships };
}

/** A minimal persona for a node with no matching persona entry (e.g. the director hub) — so its comms
 *  surface still renders. */
const fallbackPersona = (name: string, role: string): NonNullable<GRawNode["persona"]> => ({ name, role, skills: [], responsibilities: [] });

/** Org relationship archetype → a representative Glance edge `kind` (#2565). For a fleet-drill (L1) edge
 *  the `kind` is largely vestigial — the edge is coloured + labelled by its ARCHETYPE now (#2561), and
 *  `kind` drives only the `hard` flag (unshown at L1); the archetype is the real identity. */
const ARCHETYPE_TO_KIND: Record<string, GEdgeKind> = {
  manages: "api", oversees: "data", consults: "events", peers: "api", serves: "events", stewards: "data",
};

/**
 * Render a Glance fleet graph FROM an {@link Org} (#2565) — the ONE source that drives the drill's nodes,
 * edges, AND comms. Positions → nodes (persona resolved + its communication surface via `positionComms`);
 * relationships → edges. Direction: a Glance edge is "from depends on to" — the INVERSE of an org
 * relationship's archetype-native direction (a report depends on its manager, a consumer on its producer)
 * — so each relationship maps to a Glance edge REVERSED. Pure + exported: the org may be projected from a
 * running fleet (below) or, later, sourced from a blueprint's authored `team`.
 */
export function buildOrgFleetData(org: Team, personas: Persona[]): GlanceData {
  const personaById = new Map(personas.map((p) => [p.id, p]));
  const rawNodes: GRawNode[] = org.positions.map((pos) => {
    const persona = pos.personaId ? personaById.get(pos.personaId) : undefined;
    const role = persona?.role ?? (pos.nodeId === "director" ? "director" : "worker");
    const p = nodePersona(persona) ?? fallbackPersona(pos.label ?? persona?.name ?? pos.nodeId, role);
    p.comms = projectComms(org, pos, personas); // who this agent talks to + how (#2563)
    // Rests at idle (#2551) — a planned position isn't "building" until its session is actually live.
    // A `resource` position (a library, not an agent) is marked so the canvas draws it distinctly (#3322)
    // instead of the persona-less "worker" fallback role reading as an agent node.
    return { id: pos.nodeId, slug: pos.label ?? persona?.name ?? pos.nodeId, role: gRole(role), roleLabel: role, health: "off" as const, activity: "idle" as const, persona: p, resource: pos.kind === "resource" || undefined };
  });
  const ids = new Set(rawNodes.map((n) => n.id));
  const rawEdges: GRawEdge[] = [];
  const seen = new Set<string>();
  for (const r of org.relationships) {
    // A CYCLICAL archetype (iterates, #2578) is a deliberate feedback LOOP — emit BOTH directions so the
    // shared graph-core cycle primitive (`mutualPairs`) detects it and renders it as a bowed loop; every
    // other archetype maps to ONE reversed edge (Glance "from depends on to" inverts the org direction).
    const dirs: [string, string][] = archetypeById(r.archetype)?.cyclical
      ? [[r.to, r.from], [r.from, r.to]]
      : [[r.to, r.from]];
    for (const [from, to] of dirs) {
      if (from === to || !ids.has(from) || !ids.has(to)) continue;
      const k = `${from}|${to}`;
      if (seen.has(k)) continue;
      seen.add(k);
      rawEdges.push({ from, to, kind: ARCHETYPE_TO_KIND[r.archetype] ?? "api", archetype: r.archetype });
    }
  }
  return { rawNodes, rawEdges, sample: false };
}

/** Build a project's REAL fleet as a Glance graph — project the {@link FleetPlan} into an Org (#2563) and
 *  render from it (#2565), so the drill's nodes / edges / comms all flow from ONE source (the Org). The
 *  layout is topology-identical to the pre-#2565 inline builder. Returns `sample:false`. */
export function buildRealFleetData(fleet: FleetPlan, personas: Persona[], team?: BlueprintTeam): GlanceData {
  return buildOrgFleetData(fleetToOrg(fleet, team), personas);
}

/** The fleet-drill's PREVIEW node id (#2623) — a reserved, non-agent node, so it never collides with a
 *  stream id (stream ids are slugs; this carries the structural `:` + reserved tail, like `:director`). */
export const PREVIEW_NODE_ID = "__preview__";

/**
 * Add the PREVIEW node to a fleet-drill graph when the project is COMPLETE (#2623) — the surface the user
 * clicks to render the finished application in the graph (it morphs open the app preview the way an agent
 * node morphs open its terminal). Not an agent: no persona/edges, marked `preview`, and rendered
 * distinctly by the canvas. Idempotent (never doubles) and a no-op while the project is still building, so
 * the node appears exactly when there's something to preview. Pure.
 */
export function withPreviewNode(data: GlanceData, complete: boolean): GlanceData {
  if (!complete || data.rawNodes.some((n) => n.preview)) return data;
  const preview: GRawNode = {
    id: PREVIEW_NODE_ID, slug: "preview", role: "client", roleLabel: "preview",
    health: "healthy", activity: "live", preview: true,
  };
  return { ...data, rawNodes: [...data.rawNodes, preview] };
}

/** Pare an org {@link positionComms} summary down to the glance node's {@link GNodeComm} shape (labels +
 *  transports only) — keeping the glance model decoupled from the Org form types. */
function projectComms(org: Team, pos: Position, personas: Persona[]): GNodeComm[] {
  return positionComms(org, pos, personas).map((c) => ({
    withName: c.counterpartName,
    archetypeLabel: c.archetypeLabel,
    hue: c.hue,
    sends: c.sends.map((f) => ({ label: f.label, transport: f.transport })),
    receives: c.receives.map((f) => ({ label: f.label, transport: f.transport })),
  }));
}

/**
 * Whether a fleet node has a LIVE terminal to open — the check that decides if clicking it morphs the
 * node into its in-graph terminal (#2534). A node is openable iff its identity pane id
 * (`<project>:<stream>` or `<project>:director`) is a live CELL of a launched fleet tab — the durable,
 * symmetric truth for BOTH workers and the DIRECTOR (#2542). Both are cells in the build tab, so both
 * open. This replaced the earlier per-pane runtime signals (roster / paneStatus / paneClaudeActive),
 * which covered workers but never the director: it isn't a stream (off the roster) and sits at "idle"
 * between prompts, so no transient runtime signal was true at click time. `livePaneIds` is the set of
 * pane ids that are cells of an open tab, minus ended/disabled panes. Pure.
 */
export function nodeHasLiveSession(paneId: string, livePaneIds: ReadonlySet<string>): boolean {
  return livePaneIds.has(paneId);
}

/**
 * Every live session pane that belongs to a project — its director + workers — so the whole fleet can be
 * ended at once (#3052). A fleet pane id is `<projectKey>:<streamId>` (fleetPaneId), so the project's
 * panes are exactly those with the `<projectKey>:` prefix. The trailing `:` makes the match EXACT: a
 * project keyed `cli` never captures `cli-typer`'s panes. Pure; the caller kills each returned pane.
 */
export function livePanesForProject(projectKey: string, livePaneIds: ReadonlySet<string>): string[] {
  if (!projectKey) return [];
  const prefix = `${projectKey}:`;
  return [...livePaneIds].filter((pid) => pid.startsWith(prefix));
}

/** Build a project's fleet as a Glance graph: a director (infra hub), 2–4 workers (service), a reviewer
 *  (data), and an auditor (data) in a CYCLICAL loop with the reviewer (#2578). Edges are "depends on":
 *  each worker depends on the director's direction (api), the reviewer oversees each worker's output
 *  (data), and the auditor ⟳ reviewer edge is a deliberate iteration loop (findings ⟳ revisions). All
 *  clearly `sample` until a real fleet feed replaces it. */
export function buildFleetData(project: ProjectLite): GlanceData {
  const workers = 2 + (hashAbs(project.id) % 3); // 2..4
  const rawNodes: GRawNode[] = [
    { id: "director", slug: "director", role: "infra", roleLabel: "director", health: "healthy", activity: "building" },
    { id: "reviewer", slug: "reviewer", role: "data", roleLabel: "reviewer", health: "off", activity: "review" },
    { id: "auditor", slug: "auditor", role: "data", roleLabel: "auditor", health: "off", activity: "review" },
  ];
  // The auditor ⟳ reviewer iteration loop (#2578): both directions so `mutualPairs` reads it as a cycle.
  const rawEdges: GRawEdge[] = [
    { from: "auditor", to: "reviewer", kind: "data", archetype: "iterates" },
    { from: "reviewer", to: "auditor", kind: "data", archetype: "iterates" },
  ];
  for (let i = 1; i <= workers; i++) {
    const id = `worker-${i}`;
    rawNodes.push({ id, slug: `worker ${i}`, role: "service", roleLabel: "worker", health: hashAbs(id + project.id) % 2 ? "healthy" : "off", activity: "building" });
    rawEdges.push({ from: id, to: "director", kind: "api", archetype: "manages" });   // the director manages the worker
    rawEdges.push({ from: "reviewer", to: id, kind: "data", archetype: "oversees" }); // the reviewer oversees the worker's output
  }
  return { rawNodes, rawEdges, sample: true };
}

runtime.features/glance/lib/glanceGraph.ts:
// Glance — the workspace project-network graph model (#2206, epic #2205). Pure (no React/Tauri): turns
// a raw {nodes, edges} project graph into a laid-out, cycle-aware model the canvas renders. Ported from
// the user's "Relationship graph interaction spec" (Glance Network) buildModel — generalized to take
// the graph as input (the real project list feeds it via glanceData.ts) instead of hardcoded data.
//
// The graph is a DEPENDENCY DAG: `from depends on to`. Layers flow left→right by dependency depth
// (a foundational project with no deps sits at layer 0). Mutual pairs (a↔b) are CYCLES — surfaced as
// coordination hazards. This is the DAG/graph layout in the "layout follows data structure" sense
// (#2204): the same layered algorithm the Org designer uses, on a different domain.
import { neighborSpotlight } from "@/shared/lib/graph/spotlight";
import { mutualPairs } from "@/shared/lib/graph/cycles";
import { layerDag } from "@/shared/lib/graph/layers";
import { orderLayers } from "@/shared/lib/graph/order";
import { graphEdge } from "@/shared/lib/graph/edgePath";
import { layoutBand } from "@/shared/lib/graph/crossGraph";
import type { NodeGraph } from "@/shared/lib/graph/nodeUrn";
// Cross-feature TYPE only, via the barrel (#1309 boundary) — the project's application architecture
// (#3786/#3802), surfaced on each project node as the contract endpoint-type discriminator. `import type`
// is erased at build, so this adds no runtime edge to the planner (no cycle, HMR-safe).
import type { AppType } from "@/features/planner";

export type GRole = "infra" | "service" | "data" | "client";
/** Axis 1 — HEALTH (#2541): the top-left dot colour + the attention/propagation signal. An escalation
 *  ladder that rolls UP the dependency chain (a node shows the worst of itself + everything it depends
 *  on). `healthy` never propagates — only `warning`/`error` do. Sourced from the worst unresolved
 *  `bsc errors` FaultLevel; this REPLACES the old separate fault badge. `off` (#3239) is the one MANUAL
 *  value — the user has deactivated the node from its details pane; it renders greyed, wins over the live
 *  status ("if it's not idle then it should be off"), and — being rank 0 — never propagates and never
 *  inherits a downstream error (see {@link rollUpHealth}).
 *
 *  `modifying` (#4052) is the rung that was missing: `healthy` says nothing is WRONG and `complete` says
 *  the work is DONE, but neither said the work is IN FLIGHT. It replaces the LIFECYCLE category axis,
 *  which had degenerated to one boolean — across the local hubs NO project carried a discovered
 *  lifecycle, so `resolveProjectCategory` always fell through to `isDraft ? greenfield : maintain`, and
 *  six legend rows rendered two values. (The same degeneration removed the blueprint category in #3785.)
 *  Now L0 projects read on the SAME two axes as fleet nodes instead of a third, mostly-dead one. */
export type GHealth = "healthy" | "warning" | "error" | "off" | "complete" | "modifying";
/**
 * Does this node carry the BUILDING pulse (#4015)?
 *
 * A worker actively building breathes; one parked in maintenance sits still. That is the whole
 * distinction, and an animation carries it without inventing a health state — a colour would have to
 * compete with the health axis, which already means something else — and without changing the node's
 * static appearance at all.
 *
 * `fleet` gates it to the DRILLED fleet (L1). A project node on L0 must never animate, however busy
 * the project is — an L0 project in flight says so on the health axis (`modifying`, #4052), which is
 * still. The gate is an explicit flag rather than anything derived from the node, so a data change can
 * never quietly start animating the L0 layer.
 *
 * Suppressed on a deactivated node (meant to read calm) and on an errored one (its own error pulse is
 * the thing to look at; two competing animations on one node read as noise).
 *
 * Pure + exported so the gating is testable — the animation is an inline style, and what matters is
 * WHICH nodes get it, not the frames.
 */
export function showsBuildingPulse(
  n: { activity: GActivity },
  ctx: { fleet: boolean; isOff: boolean; isError: boolean },
): boolean {
  return ctx.fleet && !ctx.isOff && !ctx.isError && n.activity === "building";
}

/** Axis 2 — ACTIVITY (#2541): the bottom-right lifecycle word — what the project is doing right now.
 *  `idle` is the RESTING default (#2551): a triaged project with nothing running reads idle, NOT
 *  building — `building` means agents are ACTUALLY running (derived from live sessions, never a
 *  fallback). `planning` surfaces ONLY when the user has re-opened the planner on an already-triaged
 *  project (a re-edit state). `waiting` = an EXPECTED blocked state (an agent parked for the user,
 *  `bsc-wait`) — calm, not alarming; it lives here, not on the health axis. */
export type GActivity = "idle" | "planning" | "building" | "waiting" | "review" | "live" | "complete";
/** A Glance edge's kind. The project-network contracts (`api`/`data`/`events`) plus the CROSS-GRAPH
 *  LIBRARY edges: `uses-kit` (a project consumes a `bsc ui` kit, #2571) and the generalized `requires`
 *  (#3119, epic #3114) — a project/page pulls in an ALGORITHM or a SOUND library node — plus the EXTERNAL
 *  CONTRACT edges (#3786): `uses-mcp` (an MCP server) and `uses-service` (a third-party service). Every
 *  band edge ({@link isBandEdge}) routes vertically into the fenced band; the project contracts flow
 *  left→right. */
export type GEdgeKind = "api" | "data" | "events" | "uses-kit" | "requires" | "uses-mcp" | "uses-service";
/** A Glance node's KIND (#2571 → generalized #3119 → external contracts #3786). A PROJECT (the default), a
 *  UI-KIT node (`kit`, the `ui` library graph — kept as-is so existing fixtures + persisted ids are
 *  unaffected), a generalized cross-graph `library` node (an algorithm / sound, carrying
 *  {@link GRawNode.library}), an `mcp` contract node (an external MCP server a project uses, #3786 Phase 1
 *  auto-derived + Phase 2 planner-declared), or a `service` contract node (a third-party service a project
 *  contracts with, #3786 Phase 2). ABSENT ⇒ `"project"`. A non-project node's id is namespaced (`kit:` /
 *  `algo:` / `sound:` / `mcp:` / `service:`, see {@link libraryNodeId} / {@link mcpNodeId} /
 *  {@link serviceNodeId}) so it can never collide with a project key (a `[a-z0-9-]` slug — no colon). */
export type GNodeKind = "project" | "kit" | "library" | "mcp" | "service";

/** The cross-graph LIBRARY dimensions a band node can belong to (#3119) — reuses A's {@link NodeGraph}
 *  (algorithms · UI kits · sounds). A `kit` node is the `ui` case (kept for back-compat); a generalized
 *  `library` node names its graph via {@link GRawNode.library}. */
export type GLibraryGraph = NodeGraph; // "algo" | "ui" | "sound"

/** UI-KIT node/edge accent (#2571) — a distinct cyan that stands apart from the lifecycle-category
 *  palette (teal/indigo/bronze/slate/magenta/gold), the health dots, and the iteration-loop violet, so a
 *  kit node + its `uses-kit` edges read as a separate relationship dimension. */
export const KIT_COLOR = "#22d3ee";
/** Algorithm-library accent (#3119) — violet. */
export const ALGO_COLOR = "#a78bfa";
/** Sound-library accent (#3119) — pink. */
export const SOUND_COLOR = "#f472b6";
/** MCP-contract accent (#3786) — amber, distinct from the library dimensions (cyan kit / violet algo /
 *  pink sound) so an external-contract node + its `uses-mcp` edges read as their own dimension. MCP nodes
 *  are dashed band cards with no health dot, so this never blurs with the warning-health orange. */
export const MCP_COLOR = "#f59e0b";
/** External-SERVICE accent (#3786 Phase 2) — indigo, distinct from every other band dimension (cyan kit /
 *  violet algo / pink sound / amber mcp) AND from the health palette (blue/green/orange/red), so a
 *  third-party service node + its `uses-service` edges read as their own contract dimension. Like the mcp
 *  node it is a dashed band card with no health dot. */
export const SERVICE_COLOR = "#818cf8";

/** The presentation row shared by every fenced-BAND node (#3119 + #3786) — the accent colour, the node
 *  glyph + kind word, the band header, the inspector panel title, the consumer-edge label, and the
 *  inspector blurb. Used per library-graph ({@link LIBRARY_META}) and for the MCP dimension ({@link MCP_META}). */
export type BandMeta = {
  color: string; marker: string; kindLabel: string; bandLabel: string; panelTitle: string; edgeLabel: string; blurb: string;
};

/** Per-library-graph presentation (#3119). The `ui` row is EXACTLY the pre-#3119 kit treatment
 *  (cyan · ◆ · "kit" · "UI KITS" · "UI KIT" · "uses kit"), so a kit-only graph stays byte-identical. */
export const LIBRARY_META: Record<GLibraryGraph, BandMeta> = {
  ui: {
    color: KIT_COLOR, marker: "◆", kindLabel: "kit", bandLabel: "UI KITS", panelTitle: "UI KIT", edgeLabel: "uses kit",
    blurb: "A shared `bsc ui` kit. Every project below consumes it — a design-system dependency, so a breaking kit change fans out to them all.",
  },
  algo: {
    color: ALGO_COLOR, marker: "∑", kindLabel: "algorithm", bandLabel: "ALGORITHMS", panelTitle: "ALGORITHM", edgeLabel: "requires",
    blurb: "A shared algorithm from the algorithms graph. Every project above requires it — a cross-graph library dependency, so the reference implementation is reused, not re-coded.",
  },
  sound: {
    color: SOUND_COLOR, marker: "♪", kindLabel: "sound", bandLabel: "SOUNDS", panelTitle: "SOUND", edgeLabel: "requires",
    blurb: "A shared sound cue from the sounds graph. Every project above requires it — a cross-graph library dependency.",
  },
};

/** MCP-contract node presentation (#3786) — an external MCP server a project uses. Rendered in the same
 *  fenced top band as the library dimensions, but distinct (amber · ⇄ · "mcp" · "MCP SERVERS") so it reads
 *  as an EXTERNAL wire contract rather than a bundled library. This is Phase 1 of the inter-app contract
 *  model — the endpoint-type discriminator lives on the consuming project's `appType`. */
export const MCP_META: BandMeta = {
  color: MCP_COLOR, marker: "⇄", kindLabel: "mcp", bandLabel: "MCP SERVERS", panelTitle: "MCP SERVER", edgeLabel: "contracts with",
  blurb: "An external MCP server this project contracts with — a wire contract to a tool/data server, scoped to the projects that use it (a global built-in is not a specific contract, so it is not drawn here).",
};

/** External-SERVICE contract node presentation (#3786 Phase 2) — a third-party service (a payments API, a
 *  SaaS backend, another team's endpoint) a project's planner has DECLARED it depends on. Rendered in the
 *  same fenced top band as the mcp + library dimensions, but distinct (indigo · ☁ · "service" ·
 *  "SERVICES") so it reads as an external, planner-declared wire contract. Its endpoint type lives on the
 *  node's `appType`. */
export const SERVICE_META: BandMeta = {
  color: SERVICE_COLOR, marker: "☁", kindLabel: "service", bandLabel: "SERVICES", panelTitle: "SERVICE", edgeLabel: "contracts with",
  blurb: "An external service this project contracts with — a third-party endpoint (a payments API, a SaaS backend, another team's service) the planner declared as a dependency, so the relationship is visible and downstream agents know the contract.",
};

/** Namespace prefix for a KIT node id (#2571). */
export const KIT_NODE_PREFIX = "kit:";
/** graph → the namespace prefix for a library node id (#3119). `ui` stays `kit:` so {@link kitNodeId}
 *  and every persisted `kit:<id>` node id are unchanged; algo/sound get their own namespaces. */
export const LIBRARY_NODE_PREFIX: Record<GLibraryGraph, string> = { ui: KIT_NODE_PREFIX, algo: "algo:", sound: "sound:" };
/** The stable, collision-proof id of a library node in `graph` (#3119). `libraryNodeId("ui", x)` is
 *  exactly {@link kitNodeId}`(x)`. */
export const libraryNodeId = (graph: GLibraryGraph, libId: string): string => `${LIBRARY_NODE_PREFIX[graph]}${libId}`;
/** The stable, collision-proof id of the graph node for a `bsc ui` kit (#2571). */
export const kitNodeId = (kitId: string): string => `${KIT_NODE_PREFIX}${kitId}`;
/** The kit id behind a `kit:<kitId>` node id (identity for anything already bare). */
export const kitIdOfNode = (nodeId: string): string =>
  nodeId.startsWith(KIT_NODE_PREFIX) ? nodeId.slice(KIT_NODE_PREFIX.length) : nodeId;
/** The in-graph library id behind a library node id (#3119), stripping whichever graph prefix matches. */
export const libIdOfNode = (nodeId: string): string => {
  for (const p of Object.values(LIBRARY_NODE_PREFIX)) if (nodeId.startsWith(p)) return nodeId.slice(p.length);
  return nodeId;
};
/** Stable id for a project→kit `uses-kit` edge (#2571) — prefixed so it can never collide with a
 *  {@link projectLinkId} (`from>to:kind`). */
export const usesKitEdgeId = (projectKey: string, kitId: string): string => `usekit:${projectKey}>${kitId}`;
/** Stable id for a project→library `requires` edge (#3119) — prefixed so it never collides with a
 *  {@link projectLinkId} or a {@link usesKitEdgeId}. `toNodeId` is the target library node id. */
export const requiresEdgeId = (fromKey: string, toNodeId: string): string => `req:${fromKey}>${toNodeId}`;

/** Namespace prefix for an MCP-contract node id (#3786) — its own namespace so it never collides with a
 *  project key or a library node id (`kit:`/`algo:`/`sound:`). */
export const MCP_NODE_PREFIX = "mcp:";
/** The stable, collision-proof id of the graph node for an MCP server (#3786). */
export const mcpNodeId = (serverId: string): string => `${MCP_NODE_PREFIX}${serverId}`;
/** The MCP server id behind an `mcp:<serverId>` node id (identity for anything already bare). */
export const mcpIdOfNode = (nodeId: string): string =>
  nodeId.startsWith(MCP_NODE_PREFIX) ? nodeId.slice(MCP_NODE_PREFIX.length) : nodeId;
/** Stable id for a project→mcp `uses-mcp` edge (#3786) — prefixed so it never collides with a
 *  {@link projectLinkId}, a {@link usesKitEdgeId}, or a {@link requiresEdgeId}. */
export const usesMcpEdgeId = (projectKey: string, serverId: string): string => `usemcp:${projectKey}>${serverId}`;

/** Namespace prefix for an external-SERVICE contract node id (#3786 Phase 2) — its own namespace so it
 *  never collides with a project key or another band node id (`kit:`/`algo:`/`sound:`/`mcp:`). */
export const SERVICE_NODE_PREFIX = "service:";
/** The stable, collision-proof id of the graph node for an external service (#3786 Phase 2). `serviceId`
 *  is the contract's `to` endpoint (the service name/slug the planner declared). */
export const serviceNodeId = (serviceId: string): string => `${SERVICE_NODE_PREFIX}${serviceId}`;
/** The service id behind a `service:<serviceId>` node id (identity for anything already bare). */
export const serviceIdOfNode = (nodeId: string): string =>
  nodeId.startsWith(SERVICE_NODE_PREFIX) ? nodeId.slice(SERVICE_NODE_PREFIX.length) : nodeId;
/** Stable id for a project→service `uses-service` edge (#3786 Phase 2) — prefixed so it never collides
 *  with a {@link projectLinkId}, a {@link usesKitEdgeId}, a {@link requiresEdgeId}, or a {@link usesMcpEdgeId}. */
export const usesServiceEdgeId = (projectKey: string, serviceId: string): string => `usesvc:${projectKey}>${serviceId}`;

/** Is `n` a cross-graph LIBRARY node (#3119) — a lifted band node, not a project? True for a legacy `kit`
 *  node (the `ui` graph) or a generalized `library` node (algo/sound/ui). */
export const isLibraryNode = (n: { kind?: GNodeKind }): boolean => n.kind === "kit" || n.kind === "library";
/** The library graph a node belongs to (#3119): `kit` ⇒ `"ui"` (back-compat), a `library` node ⇒ its
 *  `library` field (defaulting to `"ui"`), else undefined (a project). */
export const libraryGraphOf = (n: { kind?: GNodeKind; library?: GLibraryGraph }): GLibraryGraph | undefined =>
  n.kind === "kit" ? "ui" : n.kind === "library" ? (n.library ?? "ui") : undefined;
/** Is `kind` a cross-graph LIBRARY edge (#3119) — a `uses-kit` (ui) or generalized `requires` edge? These
 *  route VERTICALLY into the fenced band and are excluded from the project-network layout. */
export const isLibraryEdge = (kind: GEdgeKind): boolean => kind === "uses-kit" || kind === "requires";

/** Is `n` a fenced-BAND node (#3786) — ANY lifted non-project node: a library node (kit/algorithm/sound)
 *  OR an external contract node (`mcp` / `service`). These are lifted OUT of the project DAG into the top
 *  band. */
export const isBandNode = (n: { kind?: GNodeKind }): boolean =>
  isLibraryNode(n) || n.kind === "mcp" || n.kind === "service";
/** Is `kind` a BAND edge (#3786) — a library edge OR an external-contract edge (`uses-mcp`/`uses-service`).
 *  These route VERTICALLY into the fenced band and are excluded from the project-network layout. */
export const isBandEdge = (kind: GEdgeKind): boolean =>
  isLibraryEdge(kind) || kind === "uses-mcp" || kind === "uses-service";
/** The band presentation ({@link BandMeta}) for a fenced-band node (#3786) — the MCP row for an `mcp`
 *  contract node, the SERVICE row for a `service` contract node, else the library-graph row for a
 *  kit/algorithm/sound node. */
export const bandNodeMeta = (n: { kind?: GNodeKind; library?: GLibraryGraph }): BandMeta =>
  n.kind === "mcp" ? MCP_META : n.kind === "service" ? SERVICE_META : LIBRARY_META[libraryGraphOf(n) ?? "ui"];

/** One communication form on a fleet node's comms surface (#2563) — a typed interaction + its `bsc-*`
 *  runtime transport, pared from the Org model so the glance node model stays decoupled from it. */
export interface GNodeCommForm { label: string; transport?: string }
/** A fleet node's communication surface with ONE counterpart (#2563), derived from the fleet-as-Org
 *  projection: the archetype, the other agent, and the forms this node SENDS / RECEIVES across it. */
export interface GNodeComm { withName: string; archetypeLabel: string; hue: number; sends: GNodeCommForm[]; receives: GNodeCommForm[] }

/** The agent identity behind a fleet node (#2561) — the persona surfaced on the drill node + inspector,
 *  so the user sees WHO is at that terminal (name · role · model · skills · charter), not just a role. */
export interface GNodePersona {
  name: string;
  role: string;
  model?: string;
  skills: string[];
  responsibilities: string[];
  /** The agent's communication surface (#2563) — who it talks to and how, one entry per relationship,
   *  derived from the fleet-as-Org projection. Absent until computed (fleet drill only). */
  comms?: GNodeComm[];
}

/** Severity rank for the health rollup — only `warning`/`error` (rank ≥ 1) propagate up dependency
 *  edges; everything else is "no problem" (rank 0) and stays put. */
// `complete` is rank 0 — finished is not a problem, so it must never propagate up a dependency edge
// and light a parent that is perfectly fine. `modifying` (#4052) is rank 0 for the same reason: work
// being IN FLIGHT is the normal state of a live project, and a dependency that is merely busy must
// never make its dependents look degraded.
export const HEALTH_RANK: Record<GHealth, number> = { healthy: 0, complete: 0, modifying: 0, warning: 1, error: 2, off: 0 };

/** A project node as supplied by the data adapter (before layout). */
export interface GRawNode {
  id: string;
  /** Owned-issue completion (#4050) — `done / total` for this node's stream. Absent for a node with no
   *  stream, or before the first read lands. PRESENTATIONAL ONLY: it never feeds health or activity,
   *  so a stale or missing read can never change what state the node reports. */
  progress?: { done: number; total: number };
  /** Display name (defaults to id). */
  slug?: string;
  role: GRole;
  /** The DISCOVERED lifecycle intent (#4062) — the L0 project node's accent chip. Absent for an
   *  unclassified project (⇒ no chip; see {@link LIFECYCLE_META}) and for fleet-drill (L1) nodes,
   *  which show their function group there instead. */
  lifecycle?: string;
  /** Axis 1 — the node's OWN health (before the dependency rollup). #2541. */
  health: GHealth;
  /** Axis 2 — the lifecycle word shown bottom-right. #2541. */
  activity: GActivity;
  /** When health is `warning`/`error`, the short reason (the `Fault.title` that set it) shown in place
   *  of the activity word, so the user sees WHY the dot changed. #2541. */
  reason?: string;
  /** Optional director id (for the node badge / inspector). */
  director?: string;
  /** Display label for the role when the mapped `role` category isn't the real thing — e.g. a fleet
   *  agent's actual session role ("worker" / "reviewer" / "director"), from its persona. The `role`
   *  category still drives the colour; this is the text shown on the card + inspector. */
  roleLabel?: string;
  /** Unresolved runtime-fault count for the project (#2265), from `bsc errors` — surfaced in the
   *  inspector. The count's worst LEVEL drives `health` (#2541); absent/0 ⇒ healthy/idle. */
  faults?: number;
  /** The agent identity at this node (#2561) — set for fleet-drill (L1) nodes, absent for project (L0)
   *  nodes. The inspector renders it as the persona card. */
  persona?: GNodePersona;
  /** The PREVIEW node (#2623) — not an agent: the surface that renders the finished application in the
   *  graph when the project is complete. Clicking it morphs open the app preview (`GlancePreviewMorph`)
   *  the way an agent node morphs open its terminal. The canvas renders it distinctly (▷). */
  preview?: boolean;
  /** A shared-RESOURCE node (#3322) — a team position of `kind:"resource"` (a library a session stewards,
   *  not an agent). The canvas renders it as a distinct dashed card so it never reads as a worker/agent. */
  resource?: boolean;
  /** The node KIND (#2571 → generalized #3119) — `"kit"` for a UI-kit node, `"library"` for a generalized
   *  cross-graph library node (algorithm / sound), else a PROJECT node. ABSENT ⇒ `"project"` so existing
   *  nodes/tests are unaffected; the canvas + inspector render a library node distinctly (its graph glyph
   *  · kind word · consumer count). */
  kind?: GNodeKind;
  /** The library graph this node belongs to (#3119) — set on a generalized `library` node to say which
   *  cross-graph dimension it is (`algo`/`sound`/`ui`). A legacy `kit` node leaves this ABSENT (it is
   *  implicitly `ui`). Absent on a project. */
  library?: GLibraryGraph;
  /** The project's APPLICATION ARCHITECTURE (#3786/#3802) — the contract endpoint-type discriminator:
   *  application/api/serverless/static/desktop/mobile/cli/library. Set on a PROJECT node from
   *  `planClassification[key].appType` (absent ⇒ "application"/unknown, rendered plain); on an `mcp`
   *  contract node from its transport (http ⇒ api, stdio ⇒ serverless) or a planner-declared `--app-type`;
   *  and on a `service` contract node from the planner-declared `--app-type` (#3786 Phase 2). Absent on
   *  library/kit nodes. */
  appType?: AppType;
}
/** A dependency edge: `from` depends on `to`, over a contract of `kind`. Optional stable `id` (a
 *  user-drawn project link carries its own; sample/derived edges fall back to a positional id).
 *  `archetype` (#2561) is the Org relationship archetype id for a fleet-drill (L1) edge — Manages /
 *  Oversees / Peers / … — which drives the edge colour + the communication forms shown in the inspector;
 *  absent for project (L0) edges, which keep the `kind` vocabulary. */
export interface GRawEdge { from: string; to: string; kind: GEdgeKind; id?: string; archetype?: string }

export interface GNode extends GRawNode {
  slug: string; layer: number; x: number; y: number;
  /** Health after the up-the-chain rollup (#2541): the worst of this node's own `health` and every node
   *  it (transitively) depends on. This is what the top-left dot renders. */
  rollupHealth: GHealth;
  /** True when `rollupHealth` is worse than the node's OWN `health` — i.e. the node is only lit because
   *  of a downstream dependency. Renders as a MUTED dot (the origin keeps the full/pulsing treatment). */
  healthInherited: boolean;
}
export interface GEdge {
  id: string; from: string; to: string; kind: GEdgeKind;
  /** A hard dependency (api/data) blocks the consumer on a breaking change; events are soft. */
  hard: boolean;
  isCycle: boolean;
  /** Org relationship archetype id for a fleet-drill (L1) edge (#2561) — drives colour + the inspector's
   *  communication forms. Absent for project (L0) edges. */
  archetype?: string;
  /** SVG path + arrowhead in world coordinates. */
  d: string; arrow: string;
}

export interface GraphModel {
  nodes: GNode[];
  edges: GEdge[];
  /** Mutual-dependency pairs (a↔b) — the coordination hazards. */
  cyclePairs: [string, string][];
  cycleNodeIds: Set<string>;
  worldW: number;
  worldH: number;
  /** The fenced LIBRARY band across the top (#3007, generalized #3119) — the vertical zone [`y0`, `y1`]
   *  the lifted library nodes occupy (UI kits AND/OR algorithms/sounds), with `y1` the fence divider below
   *  them. ABSENT when the graph has no library nodes, so a project-only graph is unchanged. The canvas
   *  draws a tinted backdrop + divider + a header label (the graph's name for a single-dimension band —
   *  "UI KITS"/"ALGORITHMS"/"SOUNDS" — else "LIBRARIES"). The field name stays `kitBand` for persist/test
   *  stability. */
  kitBand?: { y0: number; y1: number };
}

/**
 * Project LIFECYCLE INTENT → accent colour + label (#4062) — the L0 project node's lower-left chip.
 *
 * The vocabulary is `Lifecycle` (`planner/lib/classifyConfig.ts`), DISCOVERED per project by the
 * planner at the Discovery stage (`bsc plan classify set`). Typed structurally rather than importing
 * the planner's type, so the graph model stays free of a cross-feature value import.
 *
 * ── NO DEFAULT, EVER ────────────────────────────────────────────────────────────────────────────
 * A project with no discovered lifecycle renders NOTHING here. This is the entire lesson of #4052,
 * which deleted the previous incarnation: `resolveProjectCategory` ended in `isDraft ? greenfield :
 * maintain`, so every unclassified project wore a confident label and six of them carried one bit of
 * real information between them. `lifecycleOf`'s `?? "greenfield"` default exists for STAGE GATING,
 * where a missing value must not hide a stage — it is exactly wrong for display, where a blank slot
 * is honest and a defaulted label is a lie that looks like data.
 */
export const LIFECYCLE_META: Record<string, { label: string; color: string }> = {
  greenfield: { label: "greenfield", color: "var(--graph-lifecycle-greenfield)" }, // build from a pitch
  transform:  { label: "transform",  color: "var(--graph-lifecycle-transform)" },  // restructure existing repos
  harden:     { label: "harden",     color: "var(--graph-lifecycle-harden)" },     // improve in place
  maintain:   { label: "maintain",   color: "var(--graph-lifecycle-maintain)" },   // keep a shipped system running
  harvest:    { label: "harvest",    color: "var(--graph-lifecycle-harvest)" },    // extract data out of sources (#4062)
};

/** Role → accent colour (drives the node left-border + role chip + legend). */
export const ROLE_COLOR: Record<GRole, string> = {
  infra: "var(--graph-kind-infra)", service: "var(--graph-kind-service)", data: "var(--graph-kind-data)", client: "var(--graph-kind-client)",
};
/** Axis 1 — HEALTH → the top-left dot colour + whether it pulses (#2541). Blue = finished, green =
 *  active & fine, orange = warning, red = error/fatal (pulses; the node to look at).
 *
 *  A pulse also has a CHARACTER (#4052), because two states now pulse for opposite reasons. `error`
 *  is an ALARM — fast, and haloed so it carries across the graph. `modifying` is a BREATH — slower and
 *  bare, so a busy project reads as alive without competing with a broken one for the eye. Both
 *  fields default to the alarm shape, so `error` is untouched. */
export const HEALTH_META: Record<GHealth, { label: string; color: string; pulse: boolean; pulseMs?: number; glow?: boolean }> = {
  // #4034 — the worker FINISHED. Blue, the palette's most alive colour, which was previously spent
  // on `idle` (a resting node) while the state that had actually achieved something had none.
  // Never pulses: complete is STILL, the same reason its activity carries no motion (#4032).
  complete: { label: "complete", color: "var(--graph-health-complete)", pulse: false },
  // #4052 — work IN FLIGHT. Deliberately COMPLETE'S OWN BLUE, separated by motion alone: modifying is
  // "on its way to complete", so sharing the hue is the point, and still-vs-breathing carries the rest.
  // Every hue freed by deleting the lifecycle palette crowded an existing health colour anyway (teal
  // 19° from healthy, slate 7° from complete, violet 27°, pink 35°) — the same too-close-to-blue
  // objection that ruled out a purple attention state. So this state costs the palette no new hue.
  modifying: { label: "modifying", color: "var(--graph-health-modifying)", pulse: true, pulseMs: 2600, glow: false },
  healthy: { label: "healthy", color: "var(--graph-health-healthy)", pulse: false },
  warning: { label: "warning", color: "var(--graph-health-warning)", pulse: false },
  error: { label: "error", color: "var(--graph-health-error)", pulse: true },
  // #3239 — the user-deactivated node: a muted grey dot, never pulsing. The manual "turned off" state.
  // #4042 — `off` now means "NO LIVE SESSION behind this node", which covers all three ways that
  // happens: the user deactivated it, it was never launched, or it is structural furniture (a kit, a
  // library, an external contract) that never runs at all. Those used to be `idle`, a second grey
  // that looked identical to this one — and the dimming has always actually meant this.
  off: { label: "off", color: "var(--graph-health-off)", pulse: false },
};
/**
 * The node's bottom-right STATE WORD (#3957) — axis 2's one-word slot.
 *
 * Precedence: a user-deactivated node reads `off` (that wins over any live status, #3239); a node whose
 * OWN health is degraded reads its health word (`warning`/`error`); otherwise its activity word.
 *
 * It deliberately does NOT return the node's `reason`. It used to: #2541 swapped the reason in "so the
 * user sees WHY the dot changed", which worked while reasons were short fault titles. They aren't — 
 * `applyStallHealth` appends a duration and #3931's `heldReason` names every unlanded upstream. The slot
 * is 108px, nowrap, ellipsis, so a sentence never overflowed, it TRUNCATED:
 * "waiting on 2 upstreams to land (domain-model…" rendered as "waiting on 2 upstre…", which reads as
 * garbage rather than a status. The reason is still on hover (`title`) and in the inspector's REASON
 * tile, both of which can actually display it.
 *
 * `rollupHealth` decides `off` (the deactivation is a rollup concern); `health` decides degraded (a node
 * must not read `warning` because a DEPENDENCY is degraded). Pure.
 */
export function nodeStateWord(n: { health: GHealth; rollupHealth?: GHealth; activity: GActivity }): string {
  // #4034 — no `off` WORD. A deactivated node is already dimmed in place (`offOpacity`, #3239) and
  // that IS the signal; spending the one word slot on it meant a node that was off AND complete read
  // "off" and lost the more useful fact. The dimming carries deactivation, the word carries what the
  // node IS.
  if (n.health === "warning" || n.health === "error") return HEALTH_META[n.health].label;
  return ACTIVITY_META[n.activity].label;
}

/** Axis 2 — ACTIVITY → the bottom-right lifecycle word (#2541). Colour is the health axis's job; this
 *  is just the label + whether it animates (a live app / building fleet reads as active). */
export const ACTIVITY_META: Record<GActivity, { label: string; pulse: boolean }> = {
  idle: { label: "idle", pulse: false },
  planning: { label: "planning", pulse: false },
  building: { label: "building", pulse: true },
  waiting: { label: "waiting", pulse: false },
  review: { label: "in review", pulse: false },
  live: { label: "live", pulse: true },
  // #4027 — the worker FINISHED. On the lifecycle axis, not health: health is the perpendicular
  // axis and already means something else, and "finished" is a lifecycle fact.
  //
  // Never pulses, deliberately — that completes the vocabulary: building BREATHES (#4015),
  // attention RINGS (#4005), complete is STILL. Motion means "look at this"; a finished worker is
  // the one state with nothing to do about it.
  complete: { label: "complete", pulse: false },
};
/** Project-network (L0) edge kind → label · colour · dash · line width · the relationship "surface"
 *  blurb (#2561 relabel). The relationships a user draws between PROJECTS — a build/runtime **dependency**,
 *  a **data flow** (one project consumes another's data — connectors/pipelines/migration), or an async
 *  **event stream** — NOT the microservice "API contract" framing this replaced. (The internal key `api`
 *  is kept for data/persist stability; only the user-facing label reads "depends on".) Fleet-drill (L1)
 *  edges speak the Org archetype grammar instead — see `glanceFleet`. */
export const EDGE_META: Record<GEdgeKind, { label: string; color: string; dash: string; w: number; surface: string }> = {
  api: { label: "depends on", color: "var(--graph-edge-api)", dash: "", w: 1.8, surface: "build & runtime dependency" },
  data: { label: "data flow", color: "var(--graph-edge-data)", dash: "", w: 1.8, surface: "consumes a data feed · schema-locked" },
  events: { label: "event stream", color: "var(--graph-edge-events)", dash: "6 5", w: 1.7, surface: "async messages · at-least-once" },
  // The kit-consumer dimension (#2571): a project CONSUMES a shared `bsc ui` kit — a design-system
  // dependency drawn to the shared kit node. Dashed cyan so it reads apart from the project edges.
  "uses-kit": { label: "uses kit", color: KIT_COLOR, dash: "4 4", w: 1.6, surface: "consumes a shared bsc ui kit · design-system dependency" },
  // The generalized cross-graph LIBRARY dimension (#3119, epic #3114): a project/page REQUIRES a node in
  // ANOTHER graph — an algorithm or a sound cue. Dashed like `uses-kit` so it reads as a library
  // dependency; the canvas tints each edge by the TARGET node's graph colour (LIBRARY_META), so this
  // static `color` is only a neutral fallback (e.g. the legend swatch).
  requires: { label: "requires", color: "var(--fg-muted)", dash: "4 4", w: 1.6, surface: "requires a shared library node (algorithm / sound) · cross-graph dependency" },
  // The external MCP-CONTRACT dimension (#3786): a project CONTRACTS WITH a scoped MCP server — a wire
  // contract to an external tool/data server, drawn to the shared mcp node. Tight-dotted amber so it reads
  // apart from the kit/library edges.
  "uses-mcp": { label: "contracts with", color: MCP_COLOR, dash: "2 3", w: 1.6, surface: "contracts with a scoped external MCP server · a wire contract (Phase 1 inter-app contracts)" },
  // The external SERVICE-CONTRACT dimension (#3786 Phase 2): a project CONTRACTS WITH a third-party
  // service its planner declared — a wire contract to an external endpoint, drawn to the shared service
  // node. Tight-dotted indigo so it reads apart from the mcp + kit/library edges.
  "uses-service": { label: "contracts with", color: SERVICE_COLOR, dash: "2 3", w: 1.6, surface: "contracts with an external service · a planner-declared wire contract (Phase 2 inter-app contracts)" },
};

// Node box + spacing in world (design) coordinates.
export const NW = 186, NH = 66;
const COLGAP = 252, ROWGAP = 102;

// The fenced LIBRARY band across the top (#3007, generalized #3119). Library nodes (UI kits + algorithms +
// sounds) are LIFTED out of the project dependency DAG into a single row here, so they read as a separate
// library dimension instead of an intermixed project column (mirrors the Design Studio composition
// swimlanes). The band math is A's shared `layoutBand`; these tune its top pad + fence clearance.
const KIT_TOP_PAD = 40;   // y of the library cards' top edge inside the band
const KIT_BAND_GAP = 34;  // clearance from the library cards' bottom down to the fence divider

/** Bezier path + arrowhead between two node boxes (F depends on T). Cycle back-edges bow to separate the
 *  two directions. Ported from the spec's edgeGeom. `kind` picks the router (#3007, generalized #3119): a
 *  LIBRARY edge (`uses-kit`/`requires`) runs VERTICALLY (a project below → its library node in the top
 *  band), so it uses the DEFAULT perimeter-anchor router; every project edge keeps the layered side-port
 *  routing. */
export function edgeGeom(F: { x: number; y: number; id: string }, T: { x: number; y: number; id: string }, isCycle: boolean, kind?: GEdgeKind): { d: string; arrow: string } {
  // The shared graph line-type (#2222) with SIDE-PORT routing (#2226) — Glance's PROJECT network is a
  // layered left→right DAG, so edges leave the right edge / enter the left at the vertical middle for a
  // clean columnar flow (the perimeter-anchor router read messy here). Cycle back-edges bow apart
  // (deterministic sign by id order) so the two directions of a↔b don't overlap. A LIBRARY edge is
  // vertical (the band sits above the network), so side ports would meet the wrong faces — route it with
  // the perimeter-anchor DEFAULT (omit `routing: "ports"`) so each card faces the other.
  const bow = isCycle ? (F.id < T.id ? -46 : 46) : 0;
  const opts = kind && isBandEdge(kind) ? { bow } : { bow, routing: "ports" as const };
  const { d, arrow } = graphEdge({ x: F.x, y: F.y, w: NW, h: NH }, { x: T.x, y: T.y, w: NW, h: NH }, opts);
  return { d, arrow };
}

/** The nodes + edges to KEEP lit when something is focused (hovered/selected), so the rest dims. Null
 *  means "nothing focused — everything lit." A node lights itself + its neighbors + connecting edges;
 *  an edge lights its two endpoints; `showCycle` lights every cycle edge + its nodes. Pure. */
export function focusSets(
  model: GraphModel,
  activeNodeId: string | null,
  activeEdgeId: string | null,
  showCycle: boolean,
): { nodes: Set<string>; edges: Set<string> } | null {
  if (activeNodeId) {
    const sp = neighborSpotlight(model.edges, activeNodeId);
    return { nodes: sp.litNodes, edges: sp.litEdges };
  }
  if (activeEdgeId) {
    const e = model.edges.find((x) => x.id === activeEdgeId);
    return e ? { nodes: new Set([e.from, e.to]), edges: new Set([e.id]) } : null;
  }
  if (showCycle) {
    const nodes = new Set<string>(), edges = new Set<string>();
    for (const e of model.edges) if (e.isCycle) { edges.add(e.id); nodes.add(e.from); nodes.add(e.to); }
    return { nodes, edges };
  }
  return null;
}

/**
 * Roll HEALTH up the dependency chain (#2541): each node's effective health is the WORST of its own
 * health and every node it (transitively) depends on — so a foundational service's error surfaces on
 * everything downstream that depends on it. Only `warning`/`error` (rank ≥ 1) propagate; `idle`/`healthy`
 * never override the dependent's own resting state. Cycle-safe (a per-start visited set). Pure.
 *
 * Returns, per node id, the rolled-up `health` and whether it is `inherited` (worse than the node's own
 * health — i.e. lit only because of a dependency, so the dot renders muted, not as the origin).
 */
export function rollUpHealth(
  nodes: { id: string; health: GHealth }[],
  edges: { from: string; to: string }[],
): Map<string, { health: GHealth; inherited: boolean }> {
  const own = new Map(nodes.map((n) => [n.id, n.health]));
  const deps = new Map<string, string[]>(nodes.map((n) => [n.id, []]));
  for (const e of edges) deps.get(e.from)?.push(e.to); // `from depends on to`
  const worstFrom = (start: string): GHealth => {
    // A user-deactivated node stays `off` (#3239): the deliberate mute wins over any downstream error,
    // so an off node never lights up because of a dependency. (`off` is rank 0, so it also never
    // propagates OUT — a node depending on an off node is unaffected.)
    if (own.get(start) === "off") return "off";
    let worst: GHealth = own.get(start) ?? "off";
    const seen = new Set<string>([start]);
    const stack = [...(deps.get(start) ?? [])];
    while (stack.length) {
      const id = stack.pop()!;
      if (seen.has(id)) continue;
      seen.add(id);
      const h: GHealth = own.get(id) ?? "off";   // #4042: no own health ⇒ nothing live behind it
      if (HEALTH_RANK[h] > HEALTH_RANK[worst]) worst = h;
      for (const d of deps.get(id) ?? []) stack.push(d);
    }
    return worst;
  };
  const out = new Map<string, { health: GHealth; inherited: boolean }>();
  for (const n of nodes) {
    const eff = worstFrom(n.id);
    out.set(n.id, { health: eff, inherited: HEALTH_RANK[eff] > HEALTH_RANK[own.get(n.id) ?? "off"] });
  }
  return out;
}

/** Lay out the PROJECT network (kits excluded, #3007) with the layered left→right DAG engine — a plain
 *  GRID when there are no project dependency edges, else longest-path layering + barycenter ordering.
 *  Mutates each project node's `layer`/`x`/`y` in place. `byId` indexes ALL nodes; `cycleEdge` is the set
 *  of mutual-pair edge ids to exclude from layering. This is the pre-#3007 `buildGraph` body verbatim,
 *  scoped to `projNodes`/`projEdges` (so a project-only graph is byte-identical to before). */
function layoutProjectNetwork(projNodes: GNode[], projEdges: GEdge[], byId: Record<string, GNode>, cycleEdge: ReadonlySet<string>): void {
  // No dependency edges (real projects before a cross-project relationship model exists): a plain GRID so
  // the cards read as a network of peers instead of stacking in one column. Skip the layering.
  if (projEdges.length === 0) {
    const cols = Math.max(1, Math.round(Math.sqrt(projNodes.length)));
    projNodes.forEach((n, i) => { n.layer = 0; n.x = 70 + (i % cols) * COLGAP; n.y = 70 + Math.floor(i / cols) * ROWGAP; });
    return;
  }

  // Longest-path layering via the shared layerer (#2214). Glance is a DEPENDS-ON DAG (from depends on
  // to → the dependency `to` must sit at a LOWER layer), so we hand `layerDag` the edges REVERSED — its
  // "from → deeper" convention then puts each dependency below its dependent. Cycle (mutual-pair) edges
  // are excluded so the loop can't diverge.
  const reversed = projEdges.map((e) => ({ id: e.id, from: e.to, to: e.from }));
  const layer = layerDag(projNodes.map((n) => n.id), reversed, cycleEdge);
  projNodes.forEach((n) => (n.layer = layer[n.id]));

  // Crossing reduction via the shared barycenter orderer (#2418) with glance's tunables: every edge
  // endpoint pulls (both directions, cycle edges included), 6 snapshot sweeps.
  const nb = new Map<string, string[]>(projNodes.map((n) => [n.id, []]));
  projEdges.forEach((e) => { nb.get(e.from)!.push(e.to); nb.get(e.to)!.push(e.from); });
  const order = orderLayers(projNodes.map((n) => n.id), (id) => layer[id], (id) => nb.get(id)!, { passes: 6, sweep: "snapshot" });

  const maxCount = Math.max(1, ...[...order.values()].map((a) => a.length));
  const Cy = 70 + (maxCount - 1) * ROWGAP / 2;
  for (const [L, arr] of order) {
    arr.forEach((id, i) => {
      byId[id].x = 70 + L * COLGAP;
      byId[id].y = Cy + (i - (arr.length - 1) / 2) * ROWGAP;
    });
  }
}

/** Build the laid-out, cycle-aware graph model from raw nodes + edges. Deterministic. */
export function buildGraph(rawNodes: GRawNode[], rawEdges: GRawEdge[]): GraphModel {
  const nodes: GNode[] = rawNodes.map((n) => ({ ...n, slug: n.slug ?? n.id, layer: 0, x: 0, y: 0, rollupHealth: n.health, healthInherited: false }));
  const byId: Record<string, GNode> = {};
  nodes.forEach((n) => (byId[n.id] = n));

  const edges: GEdge[] = rawEdges
    .filter((e) => byId[e.from] && byId[e.to] && e.from !== e.to)
    .map((e, i) => ({ id: e.id ?? "e" + i, from: e.from, to: e.to, kind: e.kind, archetype: e.archetype, hard: e.kind !== "events", isCycle: false, d: "", arrow: "" }));

  // Cycle detection: mutual pairs (a→b AND b→a) — the shared graph-core primitive (#2217).
  const { pairs: cyclePairs, edgeIds: cycleEdge, nodeIds: cycleNodeIds } = mutualPairs(edges);
  edges.forEach((e) => { if (cycleEdge.has(e.id)) e.isCycle = true; });

  // Roll health up the dependency edges (#2541) — every node now carries its effective (rolled) health.
  // Band nodes (kits/algorithms/sounds AND mcp contracts, #3786) are always `idle` and never propagate, so
  // the `uses-kit` / `requires` / `uses-mcp` edges have no effect here (#3007/#3119/#3786).
  const rolled = rollUpHealth(nodes, edges);
  nodes.forEach((n) => { const r = rolled.get(n.id)!; n.rollupHealth = r.health; n.healthInherited = r.inherited; });

  // #3007 (generalized #3119 → external contracts #3786) — LIFT every non-project BAND node (UI kits
  // AND/OR algorithms/sounds AND/OR mcp contracts) out of the dependency DAG into their own fenced band
  // across the top, so they read as a separate dimension, not an intermixed project column. The PROJECT
  // network lays out with ONLY the project nodes + project edges (the existing engine, unchanged); the band
  // nodes then sit in a single row above it and every project node shifts down to clear the band.
  const bandNodes = nodes.filter(isBandNode);
  const projNodes = nodes.filter((n) => !isBandNode(n));
  const projEdges = edges.filter((e) => !isBandEdge(e.kind));

  layoutProjectNetwork(projNodes, projEdges, byId, cycleEdge);

  let kitBand: { y0: number; y1: number } | undefined;
  if (bandNodes.length > 0) {
    // A single library row across the TOP, laid out by A's shared band helper (#3119) — evenly spaced and
    // centred over the project span [70, projMaxX], the step capped at one column gap so a couple of nodes
    // cluster in the middle instead of stretching the full width. `layer = -1` marks them as band nodes
    // (outside the project layering). This is behaviour-preserving for the kit-only case (#3007).
    const projMaxX = projNodes.length ? Math.max(...projNodes.map((n) => n.x)) : 70;
    const band = layoutBand(bandNodes.length, { spanX0: 70, spanX1: projMaxX, topPad: KIT_TOP_PAD, nodeH: NH, gap: KIT_BAND_GAP, maxStep: COLGAP });
    bandNodes.forEach((k, i) => { k.layer = -1; k.x = band.positions[i].x; k.y = band.positions[i].y; });

    // The fence sits a gap below the library cards' bottom; the project network shifts down by that much
    // so the layout's own 70px top pad becomes the clean gap between the divider and the first project row.
    kitBand = { y0: band.y0, y1: band.y1 };
    projNodes.forEach((n) => (n.y += band.dividerY));
  }

  let maxX = 0, maxY = 0;
  nodes.forEach((n) => { maxX = Math.max(maxX, n.x); maxY = Math.max(maxY, n.y); });
  const worldW = maxX + NW + 80, worldH = maxY + NH + 90;

  // Edge geometry LAST — after both the project layout and the library-band shift — so every endpoint is
  // final. `e.kind` routes LIBRARY edges (`uses-kit`/`requires`) vertically (perimeter-anchor); project
  // edges keep side ports.
  edges.forEach((e) => Object.assign(e, edgeGeom(byId[e.from], byId[e.to], e.isCycle, e.kind)));

  return { nodes, edges, cyclePairs, cycleNodeIds, worldW, worldH, kitBand };
}

runtime.features/glance/lib/glancePush.ts:
// Node-parting geometry (#2671, supersedes the #2666 d3-force relaxation) — when the terminal morph GROWS
// in the graph (#2534/#2662), the neighbourhood PARTS to make room in four rigid "curtains" (left/right/
// up/down), split by the panel's aspect-scaled diagonals. Each curtain translates as ONE block by the
// clearance its most-penetrating member needs, so:
//   1. every neighbour clears the panel BY CONSTRUCTION — a hard guarantee the old soft, alpha-scaled
//      force could not make (it settled at equilibrium with residual penetration → the visible clipping);
//   2. nodes never clip INTO each other either — a curtain shifts RIGIDLY, so members keep their exact
//      relative spacing (the whole region slides aside, like curtains parting), and orthogonal curtains
//      move away from their shared diagonal.
// Closed-form + deterministic (no simulation, no tuning knobs): the same rect always yields the same
// offsets — no jitter — and it's cheap enough to recompute live during a resize drag. Pure (React/DOM-
// free) so the clearance guarantee + the rigid spacing are unit-tested in isolation. The canvas animates
// each node's offset AND the panel's grow off one matched easing, so the two read as a single motion.
import { NW, NH } from "./glanceGraph";

/** The expanded panel's world box — reported by the morph, consumed by the canvas. */
export interface MorphRect { left: number; top: number; w: number; h: number }

/** Clearance (world px) every neighbour keeps from the expanded terminal panel. */
export const PUSH_MARGIN = 36;

type Dir = "left" | "right" | "up" | "down";

/**
 * Per-node box offset so the graph PARTS to make room for the open panel `rect` — the four-curtain model.
 * Each neighbour is assigned to a curtain by which side of the panel it sits on (the panel's aspect-scaled
 * diagonals decide the dominant axis), then every curtain translates as one rigid block by the largest
 * clearance any of its members needs. Result: the panel is cleared by construction (no node clips into it)
 * and every curtain keeps its internal spacing (no node clips into a neighbour). Returns a
 * `nodeId → {dx,dy}` map of the NON-ZERO shifts only. Pure + deterministic.
 *
 * `rect` is the region to clear. Since #3361 that is the whole OCCUPIED GRID REGION (the bounding box of
 * every open morph's slot), not a single free-floating panel — the four-curtain model is indifferent to
 * how large the region is, so parting around N morphs is the same computation as parting around one.
 *
 * `exclude` are the nodes sitting UNDER the region — the grown nodes themselves — which must not be
 * pushed. Accepts one id or a set (the multi-morph case).
 */
export function partAroundPanel(
  nodes: { id: string; x: number; y: number }[],
  rect: MorphRect,
  exclude?: string | ReadonlySet<string>,
): Map<string, { dx: number; dy: number }> {
  const excluded = typeof exclude === "string" ? new Set([exclude]) : exclude;
  const out = new Map<string, { dx: number; dy: number }>();
  const cx0 = rect.left + rect.w / 2, cy0 = rect.top + rect.h / 2;
  const hx = rect.w / 2, hy = rect.h / 2;
  // The Minkowski-expanded forbidden box for a node CENTRE: the panel grown by the node's half-extent +
  // the margin. A node centre inside this box means its card overlaps the panel (within the margin).
  const fx0 = rect.left - NW / 2 - PUSH_MARGIN, fx1 = rect.left + rect.w + NW / 2 + PUSH_MARGIN;
  const fy0 = rect.top - NH / 2 - PUSH_MARGIN, fy1 = rect.top + rect.h + NH / 2 + PUSH_MARGIN;

  // Pass 1 — assign each node to a curtain and record the max clearance that curtain must provide.
  const need: Record<Dir, number> = { left: 0, right: 0, up: 0, down: 0 };
  const dirOf = new Map<string, Dir>();
  for (const n of nodes) {
    if (excluded?.has(n.id)) continue;
    const cx = n.x + NW / 2, cy = n.y + NH / 2;
    // Wedge by the panel's diagonals, scaled to its aspect: whichever axis the node is more displaced
    // along (relative to the panel's half-size) wins, so the split lines run corner-to-corner.
    const dir: Dir =
      Math.abs(cx - cx0) / hx >= Math.abs(cy - cy0) / hy
        ? (cx < cx0 ? "left" : "right")
        : (cy < cy0 ? "up" : "down");
    dirOf.set(n.id, dir);
    // If this node overlaps the panel, the distance to slide it out of the forbidden box along its
    // curtain's OWN axis (always positive for an overlapper, since its centre is inside the box).
    if (cx > fx0 && cx < fx1 && cy > fy0 && cy < fy1) {
      const exit = dir === "left" ? cx - fx0 : dir === "right" ? fx1 - cx : dir === "up" ? cy - fy0 : fy1 - cy;
      if (exit > need[dir]) need[dir] = exit;
    }
  }

  // Pass 2 — every member of a curtain takes that curtain's block shift (rigid → spacing preserved).
  const vec: Record<Dir, { dx: number; dy: number }> = {
    left: { dx: -need.left, dy: 0 }, right: { dx: need.right, dy: 0 },
    up: { dx: 0, dy: -need.up }, down: { dx: 0, dy: need.down },
  };
  for (const n of nodes) {
    const dir = dirOf.get(n.id);
    if (!dir) continue;
    const v = vec[dir];
    if (v.dx || v.dy) out.set(n.id, v);
  }
  return out;
}

runtime.features/glance/lib/hash.ts:
// The glance sample-data hash (#2421) — the one home for the private copies glanceData.ts and
// glanceFleet.ts each carried, derived from the shared `hashString` (shared/lib/core/format.ts)
// instead of re-implementing the loop.
//
// NOT plain `hashString`: the glance copies truncated each step with `| 0` (signed) and took a
// final `Math.abs`, while `hashString` truncates with `>>> 0` (unsigned). The per-step low 32 bits
// track identically either way (the 2^32 offset vanishes mod 2^32 under `* 31 + c`), so the two
// differ only in the FINAL reduction: when the sign bit is set, `Math.abs(h | 0)` = 2^32 − hashString.
// Reinterpreting `hashString`'s result as signed and abs-ing it therefore reproduces the historical
// values EXACTLY — which matters because the sample role / worker-count / status assignments
// (`hashAbs(id) % n`) must stay stable for existing projects.
import { hashString } from "@/shared/lib/core/format";

/** Stable small hash of a string → non-negative int (deterministic sample role/status/count
 *  assignment). Same outputs as the former private `hash()` copies — see the header. */
export function hashAbs(s: string): number {
  return Math.abs(hashString(s) | 0);
}

runtime.features/glance/lib/issueStateQuery.ts:
// The GitHub overlay for a fleet's owned issue refs (#4102) — pure query construction + parsing.
//
// ── ONE CALL PER REPO, NOT ONE PER ISSUE ────────────────────────────────────────────────────────
// A drilled fleet owns ~60 refs. Asking GitHub for each one is 60 requests to render one graph — the
// N-per-node fan-out that has repeatedly cost this app real time (#3908/#3912/#3944/#3954), and the
// exact shape #4102 promises not to reintroduce. GraphQL takes aliased field selections, so every ref
// in a repo is resolvable in ONE query:
//
//   query { r0: repository(owner:"o", name:"n") { i3898: issue(number:3898) { number state } … } }
//
// ── WHY NOT `GET /issues?state=all` ─────────────────────────────────────────────────────────────
// It is paginated and returns PULL REQUESTS alongside issues (REST models a PR as an issue), so a
// fleet ref matching a PR number would report the wrong state. Asking for the exact numbers cannot
// make that mistake.
//
// Pure: no fetch, no store. The hook owns the lifecycle; this owns the contract.

import { normalizeRef } from "./fleetPlanProgress";

/** `owner/name`, as a fleet stream stores it. */
export interface RepoRefs {
  repo: string;
  /** Normalised issue numbers owned in this repo. */
  numbers: string[];
}

/** Group refs by their owning repo, so each repo becomes one query. Refs are normalised and
 *  de-duplicated — two streams in a repo commonly own overlapping work, and asking twice wastes the
 *  budget this batching exists to protect. Streams with no repo or no refs are skipped. */
export function groupRefsByRepo(
  streams: readonly { repo?: string; issues?: readonly string[] }[],
): RepoRefs[] {
  const byRepo = new Map<string, Set<string>>();
  for (const s of streams) {
    const repo = s.repo?.trim();
    if (!repo || !repo.includes("/")) continue;
    for (const ref of s.issues ?? []) {
      const n = normalizeRef(ref);
      // Only numeric refs are addressable as `issue(number:)`. A cross-repo ref like `owner/x#5` or a
      // free-text placeholder is dropped rather than sent as a malformed query that fails the whole
      // batch — one bad ref must not blank out every other stream's progress.
      if (!/^\d+$/.test(n)) continue;
      let set = byRepo.get(repo);
      if (!set) byRepo.set(repo, (set = new Set()));
      set.add(n);
    }
  }
  return [...byRepo].map(([repo, numbers]) => ({ repo, numbers: [...numbers].sort() }));
}

/** GraphQL aliases must match `/^[_A-Za-z][_0-9A-Za-z]*$/`, so both levels are prefixed rather than
 *  interpolated raw — an alias starting with a digit is a syntax error that fails the whole query. */
const repoAlias = (i: number) => `r${i}`;
const issueAlias = (n: string) => `i${n}`;

/**
 * Build one query covering every repo/ref pair.
 *
 * Returns `null` when there is nothing to ask — the caller must not spend a request (nor show a
 * spinner) for a fleet that owns no addressable refs.
 *
 * Owner/name are split and embedded as quoted literals. They come from the fleet plan rather than
 * user input, but they are still validated as GitHub name characters so a malformed repo string
 * cannot inject query text.
 */
export function buildIssueStateQuery(groups: readonly RepoRefs[]): string | null {
  const parts: string[] = [];
  groups.forEach((g, i) => {
    const [owner, name] = g.repo.split("/");
    if (!owner || !name || !/^[\w.-]+$/.test(owner) || !/^[\w.-]+$/.test(name)) return;
    if (g.numbers.length === 0) return;
    const fields = g.numbers.map((n) => `${issueAlias(n)}: issue(number: ${n}) { number state }`).join(" ");
    parts.push(`${repoAlias(i)}: repository(owner: "${owner}", name: "${name}") { ${fields} }`);
  });
  return parts.length ? `query { ${parts.join(" ")} }` : null;
}

/** One issue as the overlay knows it. */
export interface IssueState {
  ref: string;
  closed: boolean;
}

/**
 * Parse the aliased response into `ref → closed`.
 *
 * Tolerant by construction: GitHub returns `null` for an alias whose issue does not exist (a stale
 * ref, or one belonging to a repo the token cannot see) and sends partial `data` ALONGSIDE `errors`
 * rather than failing the batch. Skipping the nulls means one dead ref costs its own state and
 * nothing else's — which matters because these refs are hand-maintained in the plan.
 */
export function parseIssueStates(data: unknown): Map<string, boolean> {
  const out = new Map<string, boolean>();
  if (!data || typeof data !== "object") return out;
  for (const repo of Object.values(data as Record<string, unknown>)) {
    if (!repo || typeof repo !== "object") continue;
    for (const issue of Object.values(repo as Record<string, unknown>)) {
      if (!issue || typeof issue !== "object") continue;
      const { number, state } = issue as { number?: unknown; state?: unknown };
      if (typeof number !== "number" || typeof state !== "string") continue;
      out.set(normalizeRef(number), state.toUpperCase() === "CLOSED");
    }
  }
  return out;
}

/** The refs the overlay reports as DONE — the set `fleetPlanProgress` consumes. */
export function closedRefs(states: ReadonlyMap<string, boolean>): Set<string> {
  const out = new Set<string>();
  for (const [ref, closed] of states) if (closed) out.add(ref);
  return out;
}

runtime.features/glance/lib/morphGrid.ts:
// The Glance morph GRID (#3361, directional placement #3367) — pure, React-free geometry + placement
// for the in-graph terminal morphs, so the layout is unit-testable without rendering a terminal.
//
// THE MODEL: morphs stay IN the graph (a node grows into its live session in place — that is the whole
// point of the morph, #2534). What changes is that a morph no longer free-floats at its own node's
// coords, where two open morphs would sit on top of each other. Instead each occupies a discrete cell of
// a lattice, so non-overlap is guaranteed by construction rather than by a soft push-apart relaxation.
//
// THE FIRST OPENED NODE DEFINES THE GRID. Its morph lands exactly where a single morph lands today —
// centred on its own node — and that box becomes cell (0,0). The origin is derived from the ANCHOR NODE
// (an id) rather than frozen as raw coords, so the grid tracks the graph if the layout recomputes (the
// live-status overlays rebuild the model every poll).
//
// THE LATTICE IS SIGNED (#3367). Cells extend every way from the anchor — (-1,0) is one cell LEFT,
// (0,-1) one cell UP.
//
// PLACEMENT IS UNIFORMITY-FIRST, DIRECTION SECOND (#3525). #3367 placed each node in the free cell whose
// direction from the anchor best matched its node's direction. That kept a lone node on its own side but
// let the block spread into a sparse, non-square arrangement — three left-hand nodes could sit in a
// 1×3 column with gaps rather than collapsing into a tight tile. A newly opened node now first looks for
// the cell that keeps the OPEN BLOCK most uniform — a compact, near-square rectangle with no interior
// holes — and only uses direction to break ties BETWEEN equally-compact cells. So the block still leans
// toward the side its nodes sit on (a left-heavy graph opens a left-leaning block), but it always reads
// as a tidy tile grid rather than a scatter. The trade is deliberate: an individual left-hand node may
// land in the anchor's own column when that is what completes the square, because a uniform block beats
// a strictly-sided but ragged one.
import type { MorphRect } from "./glancePush";
import { NW, NH } from "./glanceGraph";

/** A cell's DEFAULT size, in WORLD units (it renders at world-size × the current zoom). Matches the
 *  pre-grid single-morph card, so opening one node is visually unchanged. */
export const CELL_W = 760, CELL_H = 520;
/** Resize bounds for the shared cell (world units). A resize drives EVERY cell — a per-morph size would
 *  break the non-overlap guarantee the grid exists to provide. */
export const CELL_MIN_W = 380, CELL_MIN_H = 280, CELL_MAX_W = 1600, CELL_MAX_H = 1100;
/** Gutter between cells, world units — wide enough that two cards read as separate panels. */
export const GRID_GAP = 28;
/** How far out the placement search looks for a free cell. Ring 6 spans 169 cells — far past any
 *  plausible number of simultaneously open sessions, so this is a termination guard, not a cap. */
export const MAX_RING = 6;
/** The most cells a compact block can be off a perfect square before direction stops mattering — unused
 *  as a tunable now that compactness is lexicographically primary (#3525); kept exported for callers/tests
 *  that referenced the old direction-vs-distance trade. */
export const RING_PENALTY = 0.35;

/** The shared cell size — mutated as one by any morph's resize handles. */
export interface CellSize { w: number; h: number }

export const DEFAULT_CELL: CellSize = { w: CELL_W, h: CELL_H };

/** A lattice position. SIGNED: a negative col is LEFT of the anchor, a negative row is ABOVE it. */
export interface GridCell { col: number; row: number }

/** Which node holds which cell. */
export interface MorphPlacement extends GridCell { nodeId: string }

/** As much of a node as the grid geometry needs. */
export interface GridAnchorNode { x: number; y: number }

/**
 * Cell (0,0)'s top-left, in world coords: the cell CENTRED on the anchor node — byte-identical to the
 * pre-grid morph's own box (`node.x + NW/2 - CARD_W/2`). This is what makes opening the first node look
 * exactly as it always has; the grid only becomes visible from the second morph on.
 */
export function gridOrigin(anchor: GridAnchorNode, cell: CellSize = DEFAULT_CELL): { x: number; y: number } {
  return { x: anchor.x + NW / 2 - cell.w / 2, y: anchor.y + NH / 2 - cell.h / 2 };
}

/** The world box of a lattice cell. Signed, so `col: -1` sits one full cell + gap to the LEFT. */
export function cellRect(anchor: GridAnchorNode, at: GridCell, cell: CellSize = DEFAULT_CELL): MorphRect {
  const o = gridOrigin(anchor, cell);
  return {
    left: o.x + at.col * (cell.w + GRID_GAP),
    top: o.y + at.row * (cell.h + GRID_GAP),
    w: cell.w,
    h: cell.h,
  };
}

/** Every cell at Chebyshev distance `r` from the origin — the square "ring" at radius r. Ring 0 is the
 *  origin itself; ring 1 is the eight neighbours. Deterministically ordered (by col, then row). */
export function ringCells(r: number): GridCell[] {
  if (r <= 0) return [{ col: 0, row: 0 }];
  const out: GridCell[] = [];
  for (let col = -r; col <= r; col++) {
    for (let row = -r; row <= r; row++) {
      if (Math.max(Math.abs(col), Math.abs(row)) === r) out.push({ col, row });
    }
  }
  return out;
}

/** How well a cell's direction from the origin matches the unit vector (ux,uy): the cosine of the angle
 *  between them, in [-1, 1]. The origin cell has no direction, so it scores 0. */
function alignment(at: GridCell, ux: number, uy: number): number {
  const len = Math.hypot(at.col, at.row);
  if (len === 0) return 0;
  return (at.col * ux + at.row * uy) / len;
}

const key = (at: GridCell) => `${at.col},${at.row}`;

/** The two numbers that make a placement UNIFORM (#3525), for the occupied set INCLUDING the candidate.
 *  Compared lexicographically, smaller = more uniform:
 *   1. `maxDim` — the longer side of the bounding box. Minimising it caps how far the block can stretch
 *      in any one direction, so N cells collapse toward a √N-square instead of a long strip.
 *   2. `holes` — empty cells inside that box (`area − filled`). With `maxDim` fixed, the fewest holes
 *      wins, so a candidate that fills a gap always beats one that opens the block up. */
function uniformity(cells: readonly GridCell[]): { maxDim: number; holes: number } {
  let minC = Infinity, maxC = -Infinity, minR = Infinity, maxR = -Infinity;
  for (const c of cells) {
    if (c.col < minC) minC = c.col;
    if (c.col > maxC) maxC = c.col;
    if (c.row < minR) minR = c.row;
    if (c.row > maxR) maxR = c.row;
  }
  const w = maxC - minC + 1, h = maxR - minR + 1;
  return { maxDim: Math.max(w, h), holes: w * h - cells.length };
}

/**
 * Place `nodeId` in the free cell that keeps the open block most UNIFORM, breaking ties by `delta` — its
 * node's world offset FROM THE ANCHOR NODE (#3525, was direction-first in #3367).
 *
 * For each free cell the candidate occupied set is scored by {@link uniformity} (compact, hole-free
 * first); among equally-uniform cells the one whose direction best matches `delta` wins, so the block
 * still leans toward the side its nodes sit on. This is what makes N morphs collapse into a tidy tile
 * grid (a 2×2, then 3×3, …) rather than the sparse strips direction-first could leave — while a
 * left-heavy graph still opens a left-leaning block.
 *
 * The FIRST placement is always the anchor itself at (0,0). A `delta` of zero — the anchor node itself
 * re-opening — takes (0,0) back when free; every other node is scored, so a freed centre is filled only
 * when it is also the most uniform choice.
 *
 * Placed morphs are NEVER moved: placement decides where a morph goes when it OPENS. Re-ranking every
 * morph on each open would make a terminal being read jump, which is worse than an imperfect
 * arrangement. Re-placing an already-placed node is a no-op.
 */
export function placeByDirection(
  placements: readonly MorphPlacement[],
  nodeId: string,
  delta: { dx: number; dy: number },
  maxRing: number = MAX_RING,
): MorphPlacement[] {
  if (placements.some((p) => p.nodeId === nodeId)) return placements.slice();
  if (placements.length === 0) return [{ nodeId, col: 0, row: 0 }];

  const taken = new Set(placements.map(key));
  const len = Math.hypot(delta.dx, delta.dy);

  // The anchor node re-opening (zero delta) belongs at the centre when it is free — the block was built
  // around (0,0). Otherwise it falls through to the uniform scoring like any node.
  if (len === 0 && !taken.has(key({ col: 0, row: 0 }))) {
    return [...placements, { nodeId, col: 0, row: 0 }];
  }
  const ux = len === 0 ? 0 : delta.dx / len;
  const uy = len === 0 ? 0 : delta.dy / len;
  const occupied = placements.map((p) => ({ col: p.col, row: p.row }));

  // Score every free cell out to `maxRing`. Compactness is lexicographically PRIMARY: a smaller longer
  // side wins, then fewer holes, so the block collapses toward a square with no gaps. Direction only
  // separates cells that are equally uniform, and a deterministic (col,row) order settles the rest so
  // the same graph always lays out identically.
  // From ring 0: the origin is a candidate too, so a centre freed by the anchor's morph closing gets
  // filled when that keeps the block compact (it is normally `taken`, hence skipped). The zero-delta
  // anchor re-open above already claimed a free (0,0), so this only reconsiders it for other nodes.
  let best: { cell: GridCell; maxDim: number; holes: number; align: number } | null = null;
  for (let r = 0; r <= maxRing; r++) {
    for (const c of ringCells(r)) {
      if (taken.has(key(c))) continue;
      const { maxDim, holes } = uniformity([...occupied, c]);
      const align = alignment(c, ux, uy);
      const better =
        !best
        || maxDim < best.maxDim
        || (maxDim === best.maxDim && holes < best.holes)
        || (maxDim === best.maxDim && holes === best.holes && align > best.align + 1e-9)
        || (maxDim === best.maxDim && holes === best.holes && Math.abs(align - best.align) <= 1e-9
            && (c.col < best.cell.col || (c.col === best.cell.col && c.row < best.cell.row)));
      if (better) best = { cell: c, maxDim, holes, align };
    }
  }
  // Every ring out to maxRing is full — refuse rather than overlap. Unreachable in practice (169 cells).
  return best ? [...placements, { nodeId, ...best.cell }] : placements.slice();
}

/** Drop `nodeId`'s placement. The survivors keep their cells — closing one morph never moves another. */
export function releaseCell(placements: readonly MorphPlacement[], nodeId: string): MorphPlacement[] {
  return placements.filter((p) => p.nodeId !== nodeId);
}

/** The node ids currently holding a cell, in placement order. */
export function occupants(placements: readonly MorphPlacement[]): string[] {
  return placements.map((p) => p.nodeId);
}

/**
 * The bounding box of every open morph — the single region the graph parts around. Null when none are
 * open (so the neighbours snap back).
 *
 * Unions the boxes the morphs REPORT rather than deriving them from placements: a morph releases its box
 * the instant it starts collapsing, several hundred ms before it unmounts, so the graph parts back in
 * step with the shrink instead of lagging a full exit animation behind it.
 */
export function unionRects(rects: readonly MorphRect[]): MorphRect | null {
  if (rects.length === 0) return null;
  const left = Math.min(...rects.map((r) => r.left));
  const top = Math.min(...rects.map((r) => r.top));
  const right = Math.max(...rects.map((r) => r.left + r.w));
  const bottom = Math.max(...rects.map((r) => r.top + r.h));
  return { left, top, w: right - left, h: bottom - top };
}

/** Clamp a proposed shared cell size to the resize bounds. */
export function clampCell(w: number, h: number): CellSize {
  return {
    w: Math.min(Math.max(w, CELL_MIN_W), CELL_MAX_W),
    h: Math.min(Math.max(h, CELL_MIN_H), CELL_MAX_H),
  };
}

runtime.features/glance/lib/projectLinks.ts:
// Project relationships / inter-app contracts (#2253 → #3786 Phase 2) — a Glance L0 network edge:
// `from` (a project) depends on / consumes `to` over a contract of `kind` (Glance's api/data/events).
// #3786 Phase 2 generalizes the TARGET: `to` can be another project (the default), an external `service`,
// or an `mcp` server, described by an optional `target` descriptor. The editable source of truth for the
// project network's edges — a write-through cache over the global `bsc project link` store (the same CLI
// an agent uses to learn what its project consumes). Pure model.
import type { GEdgeKind } from "./glanceGraph";
// Cross-feature TYPE only, via the barrel (#1309 boundary) — the endpoint's application architecture,
// the same `AppType` vocabulary a project is classified by. `import type` is erased at build (no cycle).
import type { AppType } from "@/features/planner";

/** What a contract's `to` endpoint IS (#3786 Phase 2): another `project` (the default), an external
 *  `service`, or an `mcp` server. */
export type ContractTargetType = "project" | "service" | "mcp";

/** The endpoint a contract points at (#3786 Phase 2). Present only for a NON-project contract (an external
 *  service / mcp server) — a plain project↔project link leaves `target` absent (byte-compatible with the
 *  pre-#3786 shape). `name`/`url`/`appType` are optional descriptors of the external endpoint. */
export interface ContractTarget {
  type: ContractTargetType;
  name?: string;
  url?: string;
  appType?: AppType;
}

export interface ProjectLink {
  id: string;
  from: string;
  to: string;
  kind: GEdgeKind;
  /** The target endpoint (#3786). ABSENT ⇒ a project↔project link (`{ type: "project" }`) — kept absent
   *  so a legacy project link's persisted/wire shape is byte-identical. Present for a `service` / `mcp`
   *  contract, carrying the endpoint descriptor Glance draws as an external contract node. */
  target?: ContractTarget;
}

/** Deterministic id for a link, so adding the same edge twice is idempotent. Target-agnostic (the id is
 *  the same shape whatever the target endpoint is), matching the Rust `link_id`. */
export const projectLinkId = (from: string, to: string, kind: GEdgeKind): string => `${from}>${to}:${kind}`;

/** True when a contract points at another PROJECT (the default) — i.e. it draws as a normal L0
 *  project→project edge, not an external band contract node. A missing/`project` target is a project
 *  contract. */
export const isProjectContract = (l: ProjectLink): boolean => !l.target || l.target.type === "project";

runtime.features/glance/lib/projectLinksBridge.t:
// The frontend ↔ project-links bridge (#2253 → #3786 Phase 2) — the Glance L0 contracts are a GLOBAL
// store reached through `bsc project link …` (the same CLI an agent uses to learn what its project
// consumes / contracts with). The Zustand `projectLinks` slice is a write-through cache: `loadProjectLinks`
// hydrates it on boot, and each add/remove pushes through here. Contracts are global (no project key), so
// every call passes null. #3786 threads the optional `target` endpoint (a service / mcp server) through
// load + add.
import { bsc, bscRun } from "@/shared/lib/core/bsc";
import type { ProjectLink, ContractTarget, ContractTargetType } from "./projectLinks";
import type { AppType } from "@/features/planner";

const KINDS = ["api", "data", "events"];
const TARGET_TYPES: ContractTargetType[] = ["project", "service", "mcp"];

/** Coerce a raw `target` blob from the CLI into a {@link ContractTarget}, or `undefined` for a trivial
 *  project endpoint (no descriptors) — so a legacy project link stays byte-identical (no `target`) in the
 *  cache. Returns `undefined` on any malformed/unknown target so the link degrades to a project contract. */
function coerceTarget(raw: unknown): ContractTarget | undefined {
  if (typeof raw !== "object" || raw === null) return undefined;
  const r = raw as Record<string, unknown>;
  const type = TARGET_TYPES.includes(r.type as ContractTargetType) ? (r.type as ContractTargetType) : "project";
  const name = typeof r.name === "string" && r.name ? r.name : undefined;
  const url = typeof r.url === "string" && r.url ? r.url : undefined;
  const appType = typeof r.appType === "string" && r.appType ? (r.appType as AppType) : undefined;
  // A bare project endpoint carries no contract detail → leave `target` absent (byte-compat).
  if (type === "project" && !name && !url && !appType) return undefined;
  return { type, ...(name ? { name } : {}), ...(url ? { url } : {}), ...(appType ? { appType } : {}) };
}

/**
 * Load every contract via `bsc project link list --json`. Returns `null` when the bridge is unreachable
 * (no Tauri host / old binary) so the caller keeps its persisted cache rather than blanking it. NOT
 * `bscJson` — its degrade-to-`[]` would clobber the cache on a transient failure.
 */
export async function loadProjectLinks(): Promise<ProjectLink[] | null> {
  try {
    const out = await bsc(null, ["project", "link", "list", "--json"]);
    const rows = JSON.parse(out.trim() || "[]") as Record<string, unknown>[];
    return (rows ?? [])
      .filter(
        (l) =>
          typeof l.id === "string" && !!l.id && !!l.from && !!l.to && typeof l.kind === "string" && KINDS.includes(l.kind as string),
      )
      .map((l): ProjectLink => {
        const target = coerceTarget(l.target);
        return {
          id: l.id as string,
          from: l.from as string,
          to: l.to as string,
          kind: l.kind as ProjectLink["kind"],
          ...(target ? { target } : {}),
        };
      });
  } catch {
    return null;
  }
}

/** Write-through an add (`bsc project link add`), threading the optional `target` endpoint (#3786) as the
 *  `--target-type`/`--name`/`--url`/`--app-type` flags. Fire-and-forget; never throws (degrades to
 *  cache-only when the bridge/binary is absent). The store computes the id itself, so the printed id is
 *  unused. */
export async function pushProjectLink(from: string, to: string, kind: string, target?: ContractTarget): Promise<void> {
  const flags: string[] = [];
  if (target && target.type !== "project") flags.push("--target-type", target.type);
  if (target?.name) flags.push("--name", target.name);
  if (target?.url) flags.push("--url", target.url);
  if (target?.appType) flags.push("--app-type", target.appType);
  try { await bscRun(null, ["project", "link", "add", from, to, kind, ...flags]); } catch { /* bridge absent — cache-only */ }
}

/** Write-through a removal (`bsc project link remove <id>`). Never throws (see {@link pushProjectLink}). */
export async function dropProjectLink(id: string): Promise<void> {
  try { await bscRun(null, ["project", "link", "remove", id]); } catch { /* bridge absent — cache-only */ }
}

runtime.features/glance/lib/resumeProject.ts:
// resumeProjectFleet (#glance-resume) — one-click "bring this project's fleet back to life" from the
// Glance graph. It is the progress-gated relaunch the Planner runs (usePlanPublish.launchTriage),
// distilled to what a RESUME of an already-published, already-launched project needs — no publish, no
// sandbox, no quarantine dialog, no UI-pairing re-seed. A project only reaches the Glance network once
// its fleet/triage has launched (useGlanceProjects.filterTriaged), so its worktrees + each worker's
// CLAUDE.local.md already exist on disk; the resume therefore does NOT re-run ensure_worktree (which
// would overwrite the worker scope with a thinner one) — it lets fleetStartProject derive each worker's
// cwd from the existing worktree and resumes the session via `claude --continue` (fleetStartProject
// sets paneContinue on a re-run of an existing build tab).
//
// fleetStartProject itself navigates to the Console and focuses the build tab, so the caller doesn't.

import { useAppStore } from "@/store";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { log } from "@/shared/lib/core/log";
import { bscJson } from "@/shared/lib/core/bsc";
import { parseFleetFile, withDerivedStreamIssues, type FleetPlan } from "@/features/planner/fleet/planFleet";
import { pruneCompletedStreams, doneIssueRefs } from "@/shared/lib/fleet/streamCompletion";
import { resolveClosedRefs } from "./fleetIssueState";
import { publishFleetRoster } from "@/shared/lib/fleet/fleetRoster";
import type { PlanIssue } from "@/features/planner/issues/planIssues";
import { buildWorkerScope } from "@/features/planner/fleet/workerScope";
import { isAgentWorktreeCwd } from "@/shared/lib/core/projectPaths";
import { parseDependencyManifest, depsForRepo } from "@/features/planner/issues/dependencies";
import { partitionByDeps, heldReason, sessionDoneStreams, type LandedEvidence } from "@/shared/lib/fleet/streamGate";
import { readCoordState } from "@/shared/lib/fleet/useCoordLog";
import { ensureClaudeRunning } from "@/shared/lib/session/ensureClaudeRunning";

export interface ResumeResult {
  ok: boolean;
  /** A user-facing failure reason when `ok` is false. */
  error?: string;
  /** An informational summary of what was (or wasn't) launched — maintenance/no-repo streams. */
  note?: string;
  /** Sessions deliberately NOT relaunched, with why (#3916). The caller SURFACES these — opens their
   *  nodes so the user sees the problem — rather than resuming past them silently. */
  blocked?: BlockedStream[];
  /** Streams HELD by the dependency gate (#3931) — not started because an upstream hasn't landed.
   *  Distinct from `blocked`: nothing is wrong with these, they are simply not their turn yet, so the
   *  caller reports them without opening error nodes. */
  held?: BlockedStream[];
}

/** A session a resume refused to relaunch, and why (#3916). */
export interface BlockedStream {
  streamId: string;
  paneId: string;
  reason: string;
}

/**
 * Is there genuinely NOTHING for a project resume to start (#3923)? True only when every pane is already
 * live or is quarantined — the two states a resume must not touch (a live one is running; a quarantined
 * one is surfaced, never relaunched, #3916).
 *
 * This replaced a guard that bailed on the FIRST live pane, which made ▶ Resume permanently inert once a
 * single node had been resumed on its own: the "turn them all back on" button just switched screens. A
 * live pane is safe to include in the relaunch — `pty_create` reconnects to an existing session and
 * returns before spawning, so it never re-sends `claude --continue` to a running agent.
 */
export function nothingToResume(
  paneIds: readonly string[],
  livePaneIds: ReadonlySet<string>,
  quarantined: Record<string, unknown>,
): boolean {
  if (paneIds.length === 0) return false; // no tab yet ⇒ there IS work (build it)
  return paneIds.every((pid) => livePaneIds.has(pid) || !!quarantined[pid]);
}

/**
 * Split the streams a resume WOULD launch into those that can actually run and those that cannot (#3916).
 * Pure — the IO (worktree existence) is probed by the caller and injected — so the whole rule is
 * exhaustively testable, like {@link planResumeLaunch} beside it.
 *
 * Two blocking conditions, both of which must SURFACE rather than be silently worked around:
 *  · QUARANTINED — the warden hard-paused this worker. Resume used to call `clearProjectQuarantine`,
 *    wiping the warden floor so a prior run's denied command couldn't re-pause it; that discarded the
 *    exact signal the user needs. A quarantined worker now stays quarantined and becomes visible.
 *  · WORKTREE MISSING — #3614: the boot-GC reclaims a merged+clean worktree and the boot reconcile marks
 *    that worker ended. Relaunching it would spawn a session into a NON-EXISTENT cwd — the burst of
 *    doomed sessions that jams the backend. Never launch it; report it.
 */
/**
 * The panes that FINISHED (#4029) — the two ways a worker ends well:
 *   · `bsc-maintain` → `paneMaintaining` (declared: everything I own is done, standing by)
 *   · `bsc-done` → `endedPanes` with a `done` VERDICT, which comes from plan.db owned-issue status
 *     rather than the worker's say-so.
 *
 * `needs-attention` / `blocked` endings are deliberately NOT here: those are endings that want a
 * person, so they stay resumable and keep reporting themselves.
 *
 * Exported so both the project resume and the single-node resume ask the same question — the
 * single-node path had its own hole, and two independent notions of "finished" would drift.
 */
export function completedPanes(store: {
  paneMaintaining: Record<string, boolean>;
  endedPanes: Record<string, { state: string } | undefined>;
}): ReadonlySet<string> {
  const out = new Set<string>();
  for (const [paneId, on] of Object.entries(store.paneMaintaining)) if (on) out.add(paneId);
  for (const [paneId, info] of Object.entries(store.endedPanes)) if (info?.state === "done") out.add(paneId);
  return out;
}

export function partitionResumable(
  streams: Array<{ id: string }>,
  projectKey: string,
  probes: {
    quarantined: Record<string, { summary?: string } | undefined>;
    missingWorktreePanes: ReadonlySet<string>;
    /** Panes that FINISHED (#4029) — declared maintenance, or auto-ended with a `done` verdict. */
    completePanes?: ReadonlySet<string>;
  },
): { resumable: Array<{ id: string }>; blocked: BlockedStream[]; complete: Array<{ id: string }> } {
  const resumable: Array<{ id: string }> = [];
  const blocked: BlockedStream[] = [];
  const complete: Array<{ id: string }> = [];
  for (const st of streams) {
    const paneId = `${projectKey}:${st.id}`;
    const q = probes.quarantined[paneId];
    if (q) {
      blocked.push({ streamId: st.id, paneId, reason: q.summary?.trim() || "quarantined by the warden" });
      continue;
    }
    if (probes.missingWorktreePanes.has(paneId)) {
      blocked.push({ streamId: st.id, paneId, reason: "its worktree is gone and could not be rebuilt (no repo clone?)" });
      continue;
    }
    // FINISHED (#4029) — left alone. Relaunching a worker that has completed everything it owns undoes
    // the reclaim (#4025) and puts an agent back on the model for no reason. It is woken by the thing
    // that has actual work for it: a director `bsc-assign`, which relaunches with the assignment baked
    // in. That is the point of reclaiming it — it comes back FOR A REASON, not because a button was
    // pressed.
    //
    // Its OWN bucket, not `blocked`: blocked means "needs attention" and is reported to the user as
    // such, so filing completions there would make a healthy finished fleet look broken.
    if (probes.completePanes?.has(paneId)) {
      complete.push(st);
      continue;
    }
    resumable.push(st);
  }
  return { resumable, blocked, complete };
}

/**
 * Decide, from a project's fleet plan and its current plan.db issue statuses, exactly which streams to
 * (re)launch on a resume — the SAME progress-gated rule the Planner uses (#1004/#1957): a stream whose
 * every owned issue is done relaunches into MAINTENANCE (stays alive, ready for the director) rather than
 * being skipped; a stream with outstanding work relaunches ACTIVE; a stream with no resolvable repo can't
 * spawn a worktree so it's dropped with a note. Pure (no IO) so it's exhaustively unit-testable.
 */
export function planResumeLaunch(
  fleet: FleetPlan,
  dbIssues: Array<{ ref?: string; stream?: string; status?: string }>,
  /** Refs some OTHER evidence source reports finished — today the GitHub overlay (#4103), in each
   *  stream's own ref spelling. Unioned with plan.db's terminal rows: either source calling a ref done
   *  makes it done, because neither is complete on its own. plan.db knows only what a planner run
   *  authored (nothing, for a hand-assembled fleet); GitHub knows only what a token could reach.
   *  Optional so this stays PURE and exhaustively unit-testable. */
  extraDone: ReadonlySet<string> = new Set(),
): { launchPlan: FleetPlan; maintenanceIds: Set<string>; noRepo: string[]; note?: string } {
  const done = new Set([...doneIssueRefs(dbIssues as PlanIssue[]), ...extraDone]);
  const { active, maintenance } = pruneCompletedStreams(fleet.streams, done);
  const maintenanceIds = new Set(maintenance.map((s) => s.id));
  // A stream with no repo stays visible in the plan but can't get a worktree — drop it here and report it.
  const withRepo = [...active, ...maintenance].filter((st) => st.repo);
  const noRepo = [...active, ...maintenance].filter((st) => !st.repo).map((st) => st.id);
  // Enrich each launched stream's issue list from plan.db (a stream can reach launch with an empty
  // issues[] even though issues name it as their owning stream) so its worker/kickoff sees its tasks.
  const launchable = withDerivedStreamIssues(withRepo, dbIssues);
  const launchPlan: FleetPlan = { ...fleet, streams: launchable };

  const notes: string[] = [];
  if (noRepo.length > 0) {
    notes.push(`${noRepo.length} stream${noRepo.length === 1 ? "" : "s"} (${noRepo.join(", ")}) skipped — no repo assigned`);
  }
  if (maintenance.length > 0) {
    notes.push(`${maintenance.length} completed worker${maintenance.length === 1 ? "" : "s"} `
      + `(${maintenance.map((s) => s.id).join(", ")}) relaunching into maintenance`
      + (active.length > 0 ? `; ${active.length} active` : ""));
  }
  return { launchPlan, maintenanceIds, noRepo, note: notes.length ? notes.join(". ") + "." : undefined };
}

/**
 * Resume a project's whole fleet from the Glance graph. Loads the fleet (a caller-supplied plan when
 * available, else the store mirror, else the project's plan.db), progress-gates it against plan.db issue
 * statuses, clears a stale warden quarantine floor, ensures the director has its standing protocol, and
 * relaunches via `fleetStartProject` — which reopens the `· build` tab (director + one pane per
 * outstanding stream, resuming each with `claude --continue`) and switches to the Console.
 *
 * `fleet` lets the drilled-project caller pass the fleet it already loaded (useProjectFleet) so the
 * resume doesn't re-read plan.db for it. Returns a ResumeResult; a false `ok` carries a user-facing reason.
 */
export async function resumeProjectFleet(opts: {
  projectName: string;
  projectKey: string;
  fleet?: FleetPlan | null;
}): Promise<ResumeResult> {
  const { projectName, projectKey } = opts;
  const store = useAppStore.getState();

  // Guard the #905/#1819 hazard: with no base dir loaded, fleetStartProject would derive every worker's
  // cwd as the user's home. It's loaded well before the user reaches Glance, so this only trips on a
  // race — surface it rather than launch sessions at the wrong dir.
  if (!store.bscBaseDir) {
    return { ok: false, error: "Workspace is still loading — try Resume again in a moment." };
  }

  // 1. Resolve the fleet: caller-supplied → store mirror → the project's own plan.db.
  let fleet: FleetPlan | null = opts.fleet ?? store.planFleet[projectKey] ?? null;
  if (!fleet || fleet.streams.length === 0) {
    const raw = await bscJson<unknown | null>(projectKey, ["plan", "fleet", "get", "--full", "--json"], null);
    fleet = raw ? parseFleetFile(JSON.stringify(raw)) : null;
  }
  if (!fleet || (fleet.streams.length === 0 && !fleet.director.enabled)) {
    return { ok: false, error: "No planned fleet to resume for this project." };
  }
  // Capture the narrowed fleet in a const so its non-null type survives the awaits below.
  const resolvedFleet = fleet;

  // 2. Progress-gate against plan.db.
  const dbIssues = await bscJson<PlanIssue[]>(projectKey, ["plan", "list", "--full", "--json"], []);
  // #4103: plan.db's `issues` table is EMPTY for a fleet assembled outside a full planner run (measured:
  // 40 streams, 0 issue rows), so `doneIssueRefs` returned nothing and NO stream ever read as complete —
  // a relaunch restarted finished workers and maintenance mode (#1957) never engaged. The stream's own
  // refs are the ownership record; GitHub says which are closed. One batched query per repo.
  const closedRefs = await resolveClosedRefs(resolvedFleet.streams);
  const { launchPlan, maintenanceIds, noRepo, note: gateNote } =
    planResumeLaunch(resolvedFleet, dbIssues ?? [], closedRefs);
  if (launchPlan.streams.length === 0 && !launchPlan.director.enabled) {
    return {
      ok: false,
      error: noRepo.length > 0
        ? `No workers to resume — ${noRepo.length} stream${noRepo.length === 1 ? "" : "s"} (${noRepo.join(", ")}) need a repo assigned.`
        : "No workers to resume.",
    };
  }

  // 2b. THE DEPENDENCY GATE (#3931). Until now a resume started every stream at once — 38 simultaneous
  //     `claude --continue` sessions on the live fleet, which is both the lag the user feels and simply
  //     wrong: a stream whose upstream hasn't landed has nothing to build against. `dependsOn` already
  //     carries the graph (plan.db, 37 of 38 populated); this is the launch-time consumer #1039 left
  //     missing. Nothing PARKS — a held stream is never started, and a started one never waits — so
  //     #1039's objection (a parked worker is a worker not working) still stands.
  //
  //     `fleet_landed_streams` is the durable evidence: one `git branch --merged HEAD` per repo. See
  //     streamGate.ts for why the issue-keyed and session-keyed latches are BOTH empty on every live
  //     project and would hang the fleet if trusted alone.
  const [mergedBranches, coord] = await Promise.all([
    safeInvoke<string[]>("fleet_landed_streams", { projectKey }, []),
    readCoordState(),
  ]);
  const evidence: LandedEvidence = {
    doneIssues: new Set([...doneIssueRefs((dbIssues ?? []) as PlanIssue[]), ...closedRefs]),
    mergedBranches: new Set(mergedBranches ?? []),
    // Tier 3: a worker that finished its lane parks in MAINTENANCE (#1957, `bsc-maintain`) — the one
    // per-session completion signal that is actually populated in the live log (34 events, each keyed
    // `<projectKey>:<streamId>`). `readCoordState` returns null on a read failure, in which case tier 3
    // contributes nothing and tiers 1-2 still decide: a failed read must withhold evidence, never
    // fabricate it, or a transient log error would release the whole fleet at once.
    sessionDone: sessionDoneStreams(coord?.state.maintaining ?? [], projectKey),
  };
  const gate = partitionByDeps(launchPlan.streams, evidence);
  // A landed stream relaunches into MAINTENANCE rather than build. This is the same rule
  // `pruneCompletedStreams` applies via issues — extended with branch evidence, which is what makes it
  // work at all on a 0-issue fleet (where nothing was ever routed to maintenance and every stream
  // relaunched into a build it had already finished).
  for (const st of gate.landed) maintenanceIds.add(st.id);
  const heldIds = new Set(gate.held.map((h) => h.streamId));
  const held: BlockedStream[] = gate.held.map((h) => ({
    streamId: h.streamId, paneId: `${projectKey}:${h.streamId}`, reason: heldReason(h),
  }));
  launchPlan.streams = launchPlan.streams.filter((st) => !heldIds.has(st.id));
  if (launchPlan.streams.length === 0 && !launchPlan.director.enabled) {
    const cycle = gate.held.some((h) => h.deadlocked);
    return {
      ok: false,
      error: cycle
        ? "Nothing can start — the fleet's dependsOn graph has a cycle."
        : `Nothing can start yet — all ${held.length} stream${held.length === 1 ? " is" : "s are"} waiting on an upstream.`,
      held,
    };
  }

  // 3. Partition (#3916). Resume relaunches what can actually RUN and SURFACES what cannot, instead of
  //    steamrolling both. This deliberately replaces the old `clearProjectQuarantine` call, which wiped
  //    the warden floor so a prior run's denied command couldn't re-pause a worker — that silently
  //    discarded the one signal the user has to act on.
  const candidateStreams = launchPlan.streams;
  const paneOf = (id: string) => `${projectKey}:${id}`;
  // RECREATE a reclaimed worktree rather than refuse it (#3920). #3614's boot-GC reclaims a merged+clean
  // worktree and the boot reconcile marks that worker ended; #3916 then (correctly) refused to spawn into
  // the missing cwd, which meant a project whose worktrees had all been reclaimed could never resume at
  // all. But nothing is lost in that state: the repo clone and every stream BRANCH still exist, and
  // `ensure_worktree` explicitly reuses a leftover branch — so the worker comes back on its own history.
  // Seed the SAME scope the Planner's launch seeds (`buildWorkerScope` + the repo's locked deps, #1111),
  // or the rebuilt worker would return with a thinner CLAUDE.local.md than it had.
  const depManifest = parseDependencyManifest(
    JSON.stringify(await bscJson<unknown>(projectKey, ["plan", "deps", "get", "--json"], {}) ?? {}),
  ).dependencies;
  const worktreePaths: Record<string, string> = {};
  const unrecoverable = new Set<string>();
  await Promise.all(candidateStreams.map(async (st) => {
    const paneId = paneOf(st.id);
    if (store.quarantinedPanes[paneId]) return;          // quarantine is surfaced, never rebuilt
    const cwd = store.paneCwds[paneId];
    // #3937: reuse a persisted cwd ONLY when it still looks like this agent's own worktree. "The
    // directory exists" is not enough: while a worktree was missing the pane's shell sat in the
    // fallback ancestor (`worktrees/<key>`) and OSC 7 reported that ancestor back into `paneCwds`,
    // so the stored path became one that both exists and is wrong — and an existence check passes
    // for it forever. The shape check re-derives instead, which repairs an already-poisoned pane.
    if (cwd && st.repo && !isAgentWorktreeCwd(cwd, st.repo, st.id)) {
      log.warn(`resume: ${paneId} had a cwd outside its own worktree (${cwd}) — re-deriving (#3937)`);
    } else if (cwd && await safeInvoke<boolean>("dir_exists", { path: cwd }, true)) {
      worktreePaths[st.id] = cwd;                        // still there and still ours — reuse verbatim
      return;
    }
    if (!st.repo) { unrecoverable.add(paneId); return; } // no repo ⇒ no worktree is possible
    const scopeMd = buildWorkerScope(st, depsForRepo(depManifest, st.repo), maintenanceIds.has(st.id));
    const path = await safeInvoke<string>("ensure_worktree",
      { projectKey, repo: st.repo, agentId: st.id, scopeMd }, "");
    if (path) worktreePaths[st.id] = path;
    else unrecoverable.add(paneId);                      // clone missing / git failed — surface it
  }));
  const { resumable, blocked, complete } = partitionResumable(candidateStreams, projectKey, {
    quarantined: store.quarantinedPanes,
    missingWorktreePanes: unrecoverable,
    completePanes: completedPanes(store),
  });
  if (resumable.length === 0 && !launchPlan.director.enabled) {
    return {
      ok: false,
      error: blocked.length > 0
        ? `Nothing resumable — ${blocked.length} session${blocked.length === 1 ? "" : "s"} need attention.`
        : complete.length > 0
          // Not an error state dressed as one: everything finished. Say that, and say what wakes them.
          ? `Nothing to resume — all ${complete.length} worker(s) are complete. The director wakes one when it dispatches work.`
          : "No workers to resume.",
      blocked,
      held,
    };
  }
  // Only the resumable streams launch; the blocked ones keep their quarantine/ended state untouched.
  const resumableIds = new Set(resumable.map((st) => st.id));
  launchPlan.streams = launchPlan.streams.filter((st) => resumableIds.has(st.id));

  // 3b. Clear the ENDED flag for exactly the panes we are relaunching (#3916). Without this the whole
  //     resume was a no-op: `TerminalView` bails before `pty_create` when `endedPanes[paneId]` is set,
  //     and `endedPanes` is persisted — so a worker ended by completion (#920) or by the boot-GC
  //     worktree reconcile (#3614) could never be revived by a project resume. Cleared BEFORE
  //     `fleetStartProject` so the remount it triggers already sees a clean flag.
  store.clearEndedPanes([...resumableIds].map(paneOf));

  // 4. Give the director its standing protocol (bsc-fleet roster + worker Q&A) at the hub.
  if (launchPlan.director.enabled) {
    await safeInvoke("ensure_director_protocol", { projectKey }, undefined, (e) => console.error("director protocol failed:", e));
  }

  // 5. Relaunch. The director's cwd is the hub (resolved authoritatively); each worker's cwd is derived
  //    by fleetStartProject from the EXISTING worktree (no ensure_worktree re-seed — that would overwrite
  //    the worker's CLAUDE.local.md). fleetStartProject reuses the project's build tab in place, bumps its
  //    runId to remount, and switches to the Console.
  const hubPath = await safeInvoke<string>("project_dir_path", { projectKey }, "");
  // #905: hand the AUTHORITATIVE cwds (hub + each rebuilt/reused worktree) to the launch so no pane
  // falls back to a bscBaseDir-derived guess.
  const roster = store.fleetStartProject(projectName, launchPlan, projectKey, { hubPath: hubPath || undefined, worktreePaths });
  publishFleetRoster(projectKey, roster);

  // 6. Revive any pane whose PTY is still alive but idle (#3998).
  //
  //    `fleetStartProject` issues no Tauri commands — it bumps the tab's `runId` and rewrites store
  //    state. That re-keys the pane SLOTS, but `TerminalView` is portal-hosted by `paneId`, so a pane
  //    that never left the tab does not remount, never calls `pty_create`, and never runs the
  //    `claude --continue` this resume just resolved for it. Panes that DID unmount (ended/dormant,
  //    cleared in 3b above) remount and are handled by the reconnect branch in `TerminalView`.
  //
  //    Awaited so the caller's `ok` genuinely means the resume was attempted; the probe itself is one
  //    batched call regardless of how many panes are listed.
  await ensureClaudeRunning([...resumableIds].map(paneOf));
  const notes = [gateNote, complete.length > 0
    ? `${complete.length} complete worker${complete.length === 1 ? "" : "s"} left alone — the director wakes them on dispatch`
    : undefined, held.length > 0
    ? `${held.length} stream${held.length === 1 ? "" : "s"} held — waiting on an upstream to land`
    : undefined].filter(Boolean);
  return { ok: true, note: notes.length ? notes.join(". ") + "." : undefined, blocked, held };
}

runtime.features/glance/lib/streamProgress.ts:
// Per-stream issue progress (#4050) — how far through its owned work each fleet worker is.
//
// ── WHY ISSUES, AND NOT "PROGRESS THROUGH THE CURRENT ISSUE" ─────────────────────────────────────
// Because `done / owned` is a FACT. An agent does not emit a percentage-complete, so a bar measuring
// progress within a task would be an estimate dressed as a measurement — and a confidently wrong one,
// which is worse than no bar at all.
//
// ── ONE READ, PARTITIONED IN MEMORY ─────────────────────────────────────────────────────────────
// `OwnedIssue` carries its `stream`, and its own doc names this use: read a project's issues ONCE and
// partition by stream here, rather than querying per stream. Per-node reads are the N-per-pane fan-out
// shape that has repeatedly cost real time in this app (#3908 / #3912 / #3944 / #3954).

import { TERMINAL_GOOD, type OwnedIssue } from "@/shared/lib/fleet/workerEnd";

/** One stream's completion, as counts — never a pre-computed ratio, so a caller can render "3/7" as
 *  readily as a bar and neither has to reconstruct the other. */
export interface StreamProgress {
  done: number;
  total: number;
}

/**
 * Partition a project's issues into per-stream `done / total`.
 *
 * Issues with no `stream` are skipped: unowned work belongs to no worker, so counting it would make
 * every node's denominator wrong in the same invisible way.
 *
 * Done-ness is `TERMINAL_GOOD` (`complete` | `verified`) — the SAME set `classifyWorkerEnd` uses for
 * its verdict. A second definition here would eventually disagree with the card that says "finished".
 */
export function streamProgress(issues: readonly OwnedIssue[]): Map<string, StreamProgress> {
  const out = new Map<string, StreamProgress>();
  for (const i of issues) {
    const stream = i.stream?.trim();
    if (!stream) continue;
    const cur = out.get(stream) ?? { done: 0, total: 0 };
    cur.total += 1;
    if (TERMINAL_GOOD.has(i.status)) cur.done += 1;
    out.set(stream, cur);
  }
  return out;
}

/**
 * Refs of the issues plan.db considers FINISHED (#4102).
 *
 * Same `TERMINAL_GOOD` definition `streamProgress` counts with, exposed as refs so plan.db's evidence
 * can be unioned with the GitHub overlay into one done-set (`unionDone`). Deliberately NOT a second
 * notion of done-ness — `streamCompletion.ts` already made the point that a divergent definition
 * eventually disagrees with the card that says "finished".
 */
export function planDbDoneRefs(issues: readonly OwnedIssue[]): Set<string> {
  const out = new Set<string>();
  for (const i of issues) if (TERMINAL_GOOD.has(i.status)) out.add(i.ref);
  return out;
}

/** The fill fraction, clamped to 0..1. `total === 0` ⇒ 0 (and the caller should render NO bar at all —
 *  an empty bar and a zero-progress bar say different things, and only one of them is true). */
export function progressFraction(p: StreamProgress | undefined): number {
  if (!p || p.total <= 0) return 0;
  return Math.max(0, Math.min(1, p.done / p.total));
}

/**
 * Attach each node's stream progress. A fleet node's id IS its stream id, which is what lets this be a
 * plain map lookup rather than another join.
 *
 * Returns the SAME array when nothing matched, so a project with no plan store (or a read that has not
 * landed yet) does not invalidate the memo that renders the graph.
 */
export function withStreamProgress<T extends { id: string; progress?: StreamProgress }>(
  nodes: readonly T[],
  byStream: ReadonlyMap<string, StreamProgress>,
): T[] {
  if (byStream.size === 0) return [...nodes];
  return nodes.map((n) => {
    const p = byStream.get(n.id);
    return p ? { ...n, progress: p } : n;
  });
}

runtime.features/glance/lib/studioProject.ts:
// The synthetic "base-studio-code" default project (#3319) — the app's OWN app-owned studio sessions
// surfaced in the Glance graph. It is not a real planner project on disk: it's a fixed L0 node whose
// drilled-in graph is the STUDIO NETWORK team (`org-planning-studio`, completed in #3317), rendered
// through the existing Team→Glance adapter (`buildOrgFleetData`). The debugger node is gated by the
// Settings `debugSession` toggle via #3317's pure augmentation. Pure + React-free so it's unit-testable.
import { augmentStudioNetworkForDebug, augmentStudioNetworkForRequests, STUDIO_NETWORK_ID, type Team } from "@/features/teams";
import { poolSlotFromNodeId, poolPaneId } from "@/shared/lib/session/requestSpawn";
import type { Persona } from "@/features/personas";
import {
  DEBUG_STUDIO_SESSION_ID, DESIGN_STUDIO_SESSION_ID,
  ALGORITHMS_STUDIO_SESSION_ID, TEAMS_STUDIO_SESSION_ID, SOUND_STUDIO_SESSION_ID,
  INTEGRATION_STUDIO_SESSION_ID,
} from "@/shared/lib/session/systemSessions";
import { buildOrgFleetData } from "./glanceFleet";
import type { GlanceData, ProjectLite } from "./glanceData";
import type { GHealth, GActivity, GRawNode } from "./glanceGraph";

/** The synthetic project's id. Namespaced with a colon so it can NEVER collide with a real project slug
 *  (`projectSlug` is `[a-z0-9-]`, no colon). */
export const BASE_STUDIO_PROJECT_ID = "app:base-studio-code";

/** The base-studio-code default project's L0 node — always present in the Glance network (the app's own
 *  project), infra role + maintain lifecycle. Drilling it renders the studio sessions (see below). */
export const BASE_STUDIO_PROJECT: ProjectLite = {
  id: BASE_STUDIO_PROJECT_ID,
  name: "base-studio-code",
  role: "infra",
  health: "off",
  activity: "idle",
};

/**
 * The base-studio-code project's drilled graph — the Studio Network team's positions (the app-owned
 * studio sessions) as nodes and its relationships as edges, with the debugger node included IFF the
 * Settings debug toggle is on. Returns `null` when the team isn't present (so the caller falls back to
 * the empty/sample graph rather than crashing). Pure.
 */
export function buildStudioFleetData(
  teams: readonly Team[],
  personas: Persona[],
  debugOn: boolean,
  /** #3535: live overflow-pool SLOT indices — each becomes its own openable node. */
  poolSlots: readonly number[] = [],
): GlanceData | null {
  const team = teams.find((t) => t.id === STUDIO_NETWORK_ID);
  if (!team) return null;
  const withDebug = augmentStudioNetworkForDebug(team, debugOn);
  return buildOrgFleetData(augmentStudioNetworkForRequests(withDebug, poolSlots), personas);
}

/**
 * The stable, app-owned session pane id for each base-studio-code studio graph node (#3319) — the studio
 * analogue of `fleetPaneId`. The node ids are the Studio Network team position ids
 * (`data/teams/orgs/planning-studio.json`), and each maps to its ONE app-owned session's fixed id
 * (`systemSessions.ts`). Because these ids are STABLE, opening a node re-uses the SAME session (its host
 * re-mounts it, `claude --continue`) rather than spawning a duplicate — the "reuse if it exists, create
 * if not" the studio sessions want. The `resource` nodes (libraries) and the dynamic `planner` session
 * have no fixed session, so they return null. Pure.
 */
const STUDIO_NODE_SESSION: Record<string, string> = {
  designer: DESIGN_STUDIO_SESSION_ID,
  librarian: ALGORITHMS_STUDIO_SESSION_ID,
  architect: TEAMS_STUDIO_SESSION_ID,
  "sound-designer": SOUND_STUDIO_SESSION_ID,
  integrator: INTEGRATION_STUDIO_SESSION_ID,
  debugger: DEBUG_STUDIO_SESSION_ID,
};
export function studioPaneIdForNode(nodeId: string): string | null {
  // #3535: an overflow-pool session is DYNAMIC — one node per live pool slot — so it cannot live in the
  // fixed map above. Without this branch such a node resolves to no pane, which means it cannot be
  // opened, cannot report live status, and is a session the user can neither watch nor stop.
  const slot = poolSlotFromNodeId(nodeId);
  if (slot !== null) return poolPaneId(slot);
  return STUDIO_NODE_SESSION[nodeId] ?? null;
}

/** Where a studio node's session is HOSTED, so the graph can open/reveal it (#glance-resume). Since #3357
 *  ALL FOUR app-owned studio sessions live on the shared TerminalHost — the debugger via
 *  `DebugSessionMount`, the designer/librarian/architect via `StudioSessionHosts` — so every one of them is
 *  openable INLINE via the Glance `morph`: the host re-parents the single live terminal into the morph and
 *  hands it back to the studio's page dock on close, never spawning a second session. (Before #3357 the
 *  three studios ran their own single-mount xterm, which could not be re-parented, so they had to open on
 *  their workspace page instead — the `page` variant, kept for a future non-morphable node.) Null for a
 *  node with no openable session (the libraries, the dynamic planner). Pure. */
export type StudioNodeHome =
  | { kind: "morph" }
  | { kind: "page"; pageMode: "designs" | "algorithms" | "teams" };
export function studioNodeHome(nodeId: string): StudioNodeHome | null {
  // #3535: an overflow-pool session opens exactly like the studios it is one of.
  if (poolSlotFromNodeId(nodeId) !== null) return { kind: "morph" };
  switch (nodeId) {
    case "debugger":
    case "designer":
    case "librarian":
    case "architect":
    case "sound-designer":
      return { kind: "morph" };
    default: return null;
  }
}

/**
 * Whether a base-studio-code studio node's session is currently ACTIVE (#glance-resume) — so the node
 * reflects a running session rather than a planned position. The DEBUGGER is live while the Settings
 * `debugSession` flag is on (its node only exists then anyway); the designer/librarian/architect are live
 * while their stable-id session is mounted + running (a live `paneClaudeActive` or a `run`/`on`
 * paneStatus). Pure so the liveness rule is unit-testable; the workspace passes the store signals.
 */
export function studioSessionLive(
  nodeId: string,
  signals: { debugSession: boolean; paneClaudeActive: Record<string, boolean>; paneStatus: Record<string, string | undefined> },
): boolean {
  const sid = studioPaneIdForNode(nodeId);
  if (!sid) return false;
  if (nodeId === "debugger") return signals.debugSession;
  return !!signals.paneClaudeActive[sid] || signals.paneStatus[sid] === "run" || signals.paneStatus[sid] === "on";
}

/** The store signals {@link applyStudioLiveStatus} reads — the same set {@link studioSessionLive} takes. */
export interface StudioLiveSignals {
  debugSession: boolean;
  paneClaudeActive: Record<string, boolean>;
  paneStatus: Record<string, string | undefined>;
}

/**
 * Overlay the LIVE session state onto the base-studio-code project's studio nodes (#3421) — the studio
 * twin of `applyFleetLiveStatus`, and it exists because the two key their nodes DIFFERENTLY.
 *
 * A fleet node's pane id is `fleetPaneId(projectKey, nodeId)` (`<project>:<stream>`); a studio node's is
 * its STABLE app-owned session id from {@link studioPaneIdForNode} (`DESIGN_STUDIO_SESSION_ID`, …). Running
 * the fleet overlay over studio nodes therefore looked up `base-studio-code:designer`, which never exists,
 * so no studio node was ever found live. That mis-keying was invisible while an unmatched node fell through
 * to the raw `idle/idle` default (a plausible resting state) — #3415 made an unlaunched node read `off`,
 * which pinned every studio node `off` no matter what its session was doing.
 *
 * Health follows the #3415 model — existence AND work, not mere launch:
 *
 *   - no session mounted                          → off · idle
 *   - mounted but quiet                           → idle · idle
 *   - mounted + working (`paneStatus === "run"`)  → healthy · building
 *
 * A node with NO fixed session (the `resource` libraries, the dynamic planner) is left untouched: it has no
 * runtime state of its own, so forcing it `off` would misreport a library as a dead session. Pure — apply to
 * `rawNodes` BEFORE `buildGraph` so the rollup recomputes over the live values.
 */
export function applyStudioLiveStatus(nodes: GRawNode[], signals: StudioLiveSignals): GRawNode[] {
  return nodes.map((n) => {
    if (n.preview) return n; // not a session node — its own state stands
    const sid = studioPaneIdForNode(n.id);
    if (!sid) return n; // a library/resource or the dynamic planner — no session to report on
    if (!studioSessionLive(n.id, signals)) {
      return { ...n, health: "off" as GHealth, activity: "idle" as GActivity };
    }
    return signals.paneStatus[sid] === "run"
      ? { ...n, health: "healthy" as GHealth, activity: "building" as GActivity }
      : { ...n, health: "off" as GHealth, activity: "idle" as GActivity };
  });
}

runtime.features/glance/lib/useFleetHeld.ts:
// useFleetHeld (#3931 slice 4) — which of a drilled project's streams the dependency gate is holding,
// so the Glance node can SAY SO instead of rendering as an anonymous dark node.
//
// Same probe the resume runs (`fleet_landed_streams` + the coord `maintaining` list + plan.db issues),
// evaluated read-only: this hook never launches anything. It is scoped to the DRILLED project and
// re-runs on coord-log changes, so a stream that gets released stops being marked held without a poll.

import { useState } from "react";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { bscJson } from "@/shared/lib/core/bsc";
import { useLogStream } from "@/shared/hooks/useLogStream";
import { readCoordState } from "@/shared/lib/fleet/useCoordLog";
import { doneIssueRefs } from "@/shared/lib/fleet/streamCompletion";
import { resolveClosedRefs } from "./fleetIssueState";
import { partitionByDeps, heldReason, sessionDoneStreams, type GateStream, type LandedEvidence } from "@/shared/lib/fleet/streamGate";
import type { PlanIssue } from "@/features/planner/issues/planIssues";

/** Stream id → why it is held. Empty when nothing is gated (the common case once a fleet is flowing). */
export type HeldMap = Record<string, { reason: string; deadlocked: boolean }>;

/**
 * Held streams for `projectKey`. Returns an empty map when there is no project, no fleet, or no stream
 * declares a `dependsOn` — the last check is what keeps this off the git probe entirely for the many
 * fleets that have no dependency graph at all.
 */
export function useFleetHeld(projectKey: string | null, streams: readonly GateStream[] | undefined): HeldMap {
  const [held, setHeld] = useState<HeldMap>({});
  const hasDeps = !!streams?.some((s) => (s.dependsOn ?? []).length > 0);

  useLogStream("coord", async (isCancelled) => {
    if (!projectKey || !streams || !hasDeps) { setHeld({}); return; }
    const [merged, dbIssues, coord, closedRefs] = await Promise.all([
      safeInvoke<string[]>("fleet_landed_streams", { projectKey }, []),
      bscJson<PlanIssue[]>(projectKey, ["plan", "list", "--full", "--json"], []),
      readCoordState(),
      // #4103: plan.db's issue rows are empty for a hand-assembled fleet, so the done-set was empty and
      // the gate held streams whose upstreams had actually landed. GitHub is the other evidence source.
      resolveClosedRefs(streams),
    ]);
    if (isCancelled()) return;
    const evidence: LandedEvidence = {
      doneIssues: new Set([...doneIssueRefs(dbIssues ?? []), ...closedRefs]),
      mergedBranches: new Set(merged ?? []),
      // A failed coord read contributes no session evidence rather than fabricating it — the same rule
      // the resume and the pump follow. Over-reporting held is safe here (it is display only); claiming
      // a stream landed when the log could not be read is not.
      sessionDone: sessionDoneStreams(coord?.state.maintaining ?? [], projectKey),
    };
    const { held: h } = partitionByDeps(streams, evidence);
    setHeld(Object.fromEntries(h.map((x) => [x.streamId, { reason: heldReason(x), deadlocked: x.deadlocked }])));
  }, [projectKey, hasDeps, streams?.length]);

  return held;
}

runtime.features/glance/lib/useFleetIssueState.t:
// The drilled fleet's issue states, overlaid from GitHub (#4102).
//
// Scoped to the DRILLED project and batched into ONE query per repo (see `issueStateQuery.ts`), so the
// cost is bounded by what the user is actually looking at and stops entirely when they leave the drill
// — the same discipline `useStreamProgress` documents.
//
// ── LOCAL-FIRST, NEVER TOKEN-GATED (#2444) ──────────────────────────────────────────────────────
// With no token this returns an empty map and NOTHING breaks: issue OWNERSHIP comes from the fleet
// plan, so the plan screen still lists every worker's issues and the progress bar simply shows no
// completions yet. The overlay adds state; it is never the reason the list is empty.
import { useMemo } from "react";
import { githubGraphql } from "@/shared/lib/github/github";
import { useGithubQuery } from "@/shared/lib/github/useGithubQuery";
import { groupRefsByRepo, buildIssueStateQuery, parseIssueStates, closedRefs } from "./issueStateQuery";

/** Issue open/closed moves at human speed — a worker closing one is a minutes-scale event. Served from
 *  the backend's ETag cache within this window, so a re-drill costs no network call at all. */
const MAX_AGE_SECS = 120;

export interface FleetIssueState {
  /** ref (unprefixed, e.g. `3898`) → closed. Empty while loading, without a token, or on error. */
  states: Map<string, boolean>;
  /** Just the closed refs — what `fleetPlanProgress` consumes. */
  done: Set<string>;
  loading: boolean;
  /** Set when the overlay could not be fetched. The caller still renders the list; this only explains
   *  absent state chips, so a disconnected user is told why rather than shown a silent zero. */
  error: string | null;
}

/**
 * Resolve open/closed for every issue ref owned by `streams`.
 *
 * `streams` should be the drilled project's fleet (or empty when not drilled — then nothing is fetched).
 */
export function useFleetIssueState(
  streams: readonly { repo?: string; issues?: readonly string[] }[],
): FleetIssueState {
  // The query is derived, not stored, and keyed by its own text: two renders yielding the same refs
  // produce the same string, so `useGithubQuery` does not refetch on every parent re-render.
  const query = useMemo(() => buildIssueStateQuery(groupRefsByRepo(streams)), [streams]);

  const { data, loading, error } = useGithubQuery<unknown>(
    () => githubGraphql<unknown>(query!, null, { maxAgeSecs: MAX_AGE_SECS }),
    [query],
    // A fleet with no addressable refs must not spend a request — nor show a spinner for an answer
    // that would be empty either way.
    !!query,
  );

  return useMemo(() => {
    const states = parseIssueStates(data);
    return { states, done: closedRefs(states), loading, error };
  }, [data, loading, error]);
}

runtime.features/glance/lib/useGlanceFaults.ts:
// useGlanceFaults (#2265) — the unresolved runtime-fault count per project, for the Glance node
// FAULT-health badge. Polls each project's errordb (`bsc errors list --unresolved --json`, #2260) on a
// slow cadence and returns a `{ projectKey → count }` map the workspace merges into the graph nodes.
// Orthogonal to the liveness "live/down" status (#2263): this reads `bsc errors`, that reads
// heartbeats, so the two merge into the node without touching each other.
//
// Degrades to an empty map when a project has no errordb yet (bscJson swallows the reject) — a project
// with zero faults simply shows no badge.
import { useEffect, useRef, useState } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { unresolvedCount, worstFault, type FaultLite } from "@/shared/lib/fleet/faultTriage";

const POLL_MS = 20_000;

interface FaultRow {
  fingerprint: string;
  level: string;
  title: string;
  count: number;
  resolved_at?: number | null;
}

/** The per-project fault summary the health axis reads (#2541): the total unresolved `count`, plus the
 *  worst open fault's `level` (drives the dot colour) and `title` (the bottom-right reason text). */
export interface GlanceFault { count: number; level: FaultLite["level"]; title: string }

/** Unresolved-fault summaries keyed by project plan key. `keys` is the current Glance project set; the
 *  map only carries projects with at least one unresolved fault (absent ⇒ healthy/idle). */
export function useGlanceFaults(keys: string[]): Record<string, GlanceFault> {
  const [counts, setCounts] = useState<Record<string, GlanceFault>>({});
  // Stable join so the poll re-subscribes only when the actual key SET changes, not every render (the
  // parent passes a fresh array each time).
  const keyList = keys.slice().sort();
  const joined = keyList.join("�");
  const keysRef = useRef(keyList);
  useEffect(() => { keysRef.current = keyList; }, [keyList]);

  usePoll(async (isCancelled) => {
    if (isCancelled()) return;
    const targets = keysRef.current;
    if (targets.length === 0) { setCounts({}); return; }
    // #3912: ONE in-process read for the whole set. This was a `Promise.all` of a `bsc errors list`
    // SUBPROCESS per project — at 28 projects on a 20s cadence, ~21 concurrent spawns three times a
    // minute, measured as the single largest consumer of the Tauri command queue (15,806s of invoke
    // time in 72 minutes, p50 8.4s). `src-tauri` already links `errordb`, so the spawns bought nothing.
    // A project absent from the map has no error.db or no open faults — the same "no badge" outcome
    // the per-project read produced by degrading to [].
    const byKey = await safeInvoke<Record<string, FaultRow[]>>("fault_rows_batch", { projectKeys: targets }, {});
    if (isCancelled()) return;
    const entries = targets.map((key): [string, GlanceFault | null] => {
      const faults: FaultLite[] = (byKey?.[key] ?? []).map((r) => ({
        fingerprint: r.fingerprint,
        level: r.level === "warn" || r.level === "fatal" ? r.level : "error",
        title: r.title,
        count: r.count,
        resolvedAt: r.resolved_at ?? null,
      }));
      const worst = worstFault(faults);
      return [key, worst ? { count: unresolvedCount(faults), level: worst.level, title: worst.title } : null];
    });
    setCounts(Object.fromEntries(entries.filter((e): e is [string, GlanceFault] => e[1] !== null)));
  }, POLL_MS, [joined]); // re-subscribe when the key SET changes (via the stable join)

  return counts;
}

runtime.features/glance/lib/useGlanceProjects.ts:
// useGlanceProjects (#2206) — the REAL project set for the Glance network: the user's PUBLISHED GitHub
// projects (projectsV2, the same query the Planner list runs) MERGED with local DRAFTS. Everything is
// keyed by the PLAN key (the name-derived slug, #2409 — NOT the GitHub node id) so each project appears
// once and drilling into it resolves its fleet from `planFleet` (which is plan-key-keyed). Published
// projects win on a key collision (they carry the real open/shipped status). Falls back to just drafts
// when there's no token / before the fetch lands, so the page is never blocked on the network.
//
// #2339 — the network showed a DIFFERENT set on every visit. Two causes, both fixed here:
//   1. RACE. `useGithubQuery` re-inits to `{ data: null }` on every mount and the Rail unmounts/remounts
//      Glance on leave/return, so each visit rendered drafts-only → then flipped to drafts+published once
//      the async fetch (variable latency) landed. The PERSISTED last-known board state (#2446 — the
//      `githubState` store field, which also survives an app restart) seeds the merge on a revisit, so
//      it renders the last-known network immediately, then refreshes.
//   2. DEDUP GAP. Drafts were keyed by their stable id but published by a different derivation; when
//      the two keys differed the SAME project became TWO nodes. The merge resolves a published project
//      onto its matching draft via a slug(title)→draftKey map, so legacy-keyed drafts collapse too.
// #2409: the plan key IS the name-derived slug (`projectSlug(title)`) — the node-id alias is retired.
import { useEffect, useMemo, useState } from "react";
import { useAppStore } from "@/store";
import { githubGraphql } from "@/shared/lib/github/github";
import { useGithubQuery } from "@/shared/lib/github/useGithubQuery";
import { toMinimalGhProjects, minimalToGhProject, filterRecordsToLocal } from "@/shared/lib/github/githubState";
import { useProjectProgressRows } from "./useProjectProgress";
import { fetchProjectsWithProbe } from "@/shared/lib/github/githubProbe";
import { PROJECTS_QUERY, type GhProject } from "@/features/planner/list/published/publishedModel";
import { projectSlug } from "@/shared/lib/core/projectPaths";
import { usePoll } from "@/shared/hooks/usePoll";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import type { GRole, GHealth, GActivity } from "./glanceGraph";
import type { ProjectLite } from "./glanceData";
import type { GlanceFault } from "./useGlanceFaults";
import { projectKeyOfSession } from "./agentStall";
// #3966: the SAME durable-projects bridge the Projects page reads, so the two surfaces cannot
// disagree about which local projects exist. Type-only + the reader; the bridge already degrades to
// `null` when it is unreachable, which we treat as "keep the cache".
import { listDbProjects, type DbProject } from "@/features/planner";

// #2541 — GitHub board status NO LONGER drives a Glance node's status. The old `ghStatus` (open ⇒
// planning, shipped ⇒ done) is gone; health + activity are derived from runtime signals only.

/** Store shapes the merge reads — mirrored structurally so the pure fn stays decoupled from the slices.
 *  A draft MAY declare curated axes (#2284/#2541) — a demo/tagged project keeps its authored colouring. */
type DraftMap = Record<string, { title: string; pitch: string; createdAt: number; role?: GRole; health?: GHealth; activity?: GActivity; reason?: string }>;

/** Stable empty published set — a fresh `[]` each render would needlessly re-run the merge memo. */
const NO_PUBLISHED: GhProject[] = [];

/** Stable empty DB set — same memo-stability reason as {@link NO_PUBLISHED}. */
const NO_DB_PROJECTS: DbProject[] = [];

/**
 * Union the durable projects DB into the store's draft map (#3966).
 *
 * `localDraftProjects` is a persisted CACHE, written by `addDraftProject` at creation time — and it is
 * reset wholesale by `resetProjectData` and delete/rekey-scoped by `projectScopedMaps`. So a project
 * that predates the map, survives a reset, or is created by a path that never calls `addDraftProject`
 * is absent from it FOREVER, while `projects.db` still has the row and every other surface still shows
 * it. That is how a triaged, openable project had no Glance node at all.
 *
 * The CACHE wins on fields it has — it carries the curated axes the DB row has no column for — and the
 * DB fills what the cache is missing, including whole rows.
 *
 * STATE FILTER — deliberately WIDER than `mergeDbDrafts` (the Projects page's equivalent), and the
 * first cut of this function got that wrong. That helper feeds a DRAFTS-ONLY list, where `created` and
 * `published` projects are excluded because they render in other sections of the same page. Glance has
 * no other section: its node set is drafts ∪ local-published ∪ GitHub-published, so a `created` project
 * — one that has been scaffolded but never published — belongs to NO source and silently vanishes from
 * the graph. That is what happened to a triaged project whose state had advanced `drafted` → `created`.
 *
 * `published` stays out on purpose: `mergeGlanceProjects` already overrides a draft with the published
 * entry on a key collision, so admitting it buys nothing.
 *
 * Pure + exported for direct unit testing, like {@link mergeGlanceProjects}.
 */
export function mergeDbIntoDrafts(drafts: DraftMap, dbRows: DbProject[]): DraftMap {
  const out: DraftMap = { ...drafts };
  for (const r of Array.isArray(dbRows) ? dbRows : []) {
    if (r.state === "published") continue;
    const ex = out[r.key];
    out[r.key] = ex
      // Keep every curated axis (role/health/activity/reason) — the DB row has none of them,
      // so a spread-with-DB-second would silently strip a demo project's authored colouring.
      ? { ...ex, title: ex.title || r.title, pitch: ex.pitch || r.pitch, createdAt: ex.createdAt || r.createdAt }
      : { title: r.title, pitch: r.pitch, createdAt: r.createdAt || r.updatedAt || 0 };
  }
  return out;
}

/** A published hub from the LOCAL inventory (#2445): `key` is the hub FOLDER key — the same key the
 *  drill / `planFleet` / `fleetPaneStreams` resolve against — with the `.title` display name. */
export interface LocalPublishedLite { key: string; title: string }

/** The `list_local_projects` fields the seed reads (camelCase wire format, #789). */
interface LocalProjectWire { key: string; title: string; published: boolean }

// The last-fetched local published inventory (#2445) — module-level so it survives the Glance
// workspace unmount/remount the Rail does on every leave/return: a revisit renders the published
// nodes immediately, then refreshes. (The GitHub-side equivalent is the PERSISTED `githubState`
// store field, #2446.)
let localPublishedCache: LocalPublishedLite[] | null = null;

// The last-fetched durable projects DB rows (#3966) — module-level for the same reason as
// `localPublishedCache`: the Rail unmounts/remounts the Glance workspace on every leave/return, and a
// revisit should render the full node set immediately rather than flashing a cache-only graph first.
let dbProjectsCache: DbProject[] | null = null;

/**
 * Merge local drafts with published GitHub projects into the Glance node set, keyed by the PLAN key so each
 * project is exactly ONE node. Pure + exported for direct unit testing (#2339).
 *
 * Dedup (#2409): a published project's plan key IS `projectSlug(title)` — with one bridge for
 * grandfathered drafts: a draft whose legacy key differs from its title-slug is found via a
 * slug(title)→draftKey map, so the published board collapses onto it rather than spawning a second node.
 */
export function mergeGlanceProjects(
  drafts: DraftMap,
  published: GhProject[],
  localPublished: LocalPublishedLite[] = [],
): ProjectLite[] {
  const byKey = new Map<string, ProjectLite>();
  // slug(title) → draft key, so a published project collapses onto a legacy-keyed draft.
  const draftKeyByTitle = new Map<string, string>();
  // Drafts first; a published project on the same plan key overrides it below.
  for (const [id, d] of Object.entries(drafts)) {
    // A draft may DECLARE its Glance axes (#2284/#2541 — health + activity + reason); else both axes
    // REST at idle (#2551) and the runtime overlays light them up: liveness → live (#2263), running
    // agents → building (#2551), bsc-wait → waiting, faults → warning/error (#2541). A declared value
    // wins so a demo/tagged project keeps its curated colouring.
    byKey.set(id, {
      id, name: d.title, role: d.role,
      health: d.health ?? "off",
      activity: d.activity ?? "idle",
      reason: d.reason,
    });
    draftKeyByTitle.set(projectSlug(d.title), id);
  }
  // Local published hubs (#2445) — the OFFLINE seed: a published project always has a node, keyed by
  // its hub folder key (what the drill resolves), even when the GitHub set is absent (logged out /
  // fetch not landed). A GitHub record below OVERLAYS it. GitHub board status NO LONGER sets the node
  // status (#2541) and a published hub RESTS at idle (#2551) until a runtime overlay lights it up; a
  // draft-declared axis still wins for curated colouring.
  // Collapse the LEGACY + name-slug hub FOLDERS of the SAME project into ONE node (#2409 grandfathering
  // leaves both on disk with the same title — e.g. `Beautiful_Emails` + `beautiful-emails`): group by the
  // canonical `projectSlug(title)`, preferring the folder whose key already IS that slug (what planFleet +
  // the drill resolve against), so a project isn't DUPLICATED on the network.
  const localByTitleKey = new Map<string, LocalPublishedLite>();
  for (const lp of localPublished) {
    const tk = projectSlug(lp.title);
    const cur = localByTitleKey.get(tk);
    if (!cur || (lp.key === tk && cur.key !== tk)) localByTitleKey.set(tk, lp);
  }
  for (const [tk, lp] of localByTitleKey) {
    // Collapse onto a matching draft (a legacy-keyed draft) if one exists; else key by the chosen folder.
    const key = draftKeyByTitle.get(tk) ?? lp.key;
    const prior = byKey.get(key);
    const d = drafts[key];
    byKey.set(key, { id: key, name: lp.title, role: prior?.role, health: d?.health ?? "off", activity: d?.activity ?? "idle", reason: d?.reason });
    draftKeyByTitle.set(tk, key);
  }
  for (const p of published) {
    // The plan key derives from the name (#2409): a matching draft's key (covers grandfathered
    // legacy-keyed drafts) else `projectSlug(title)` — the key `planFleet` + the drill resolve
    // against (NEVER the node id). Preserve any axis already set by a collapsed draft/local hub; the
    // GitHub record contributes only name (+ dedup), never status (#2541).
    const titleKey = projectSlug(p.title);
    const key = draftKeyByTitle.get(titleKey) ?? titleKey;
    const prior = byKey.get(key);
    byKey.set(key, { id: key, name: p.title, role: prior?.role, health: prior?.health ?? "off", activity: prior?.activity ?? "idle", reason: prior?.reason });
  }
  return [...byKey.values()];
}

/** One project's liveness as the `project_liveness` Tauri command reports it (#2263, camelCase). */
interface ProjectLiveness { projectKey: string; live: boolean }

/** How often to poll backend liveness (ms). Comfortably below the backend's 45s window so a project
 *  going silent surfaces (and its "app down" alert records) within ~one interval. */
const LIVENESS_POLL_MS = 10_000;

/**
 * Overlay backend liveness onto the merged node set (#2263/#2541): a project whose key is in `liveKeys`
 * is detected RUNNING → activity `"live"` and health `"healthy"` (a running app is active & fine — the
 * fault overlay below can still escalate it to warning/error). Every other project keeps its merged
 * axes, so liveness lapsing naturally RESETS on the next poll. Additive + pure.
 */
export function applyLiveness(projects: ProjectLite[], liveKeys: ReadonlySet<string>): ProjectLite[] {
  if (liveKeys.size === 0) return projects;
  return projects.map((p) => (liveKeys.has(p.id) ? { ...p, activity: "live", health: p.health === "off" ? "healthy" : p.health } : p));
}

/**
 * Overlay RUNNING-AGENT activity onto the node set (#2551) — the `building` state. A project with a live
 * agent PTY reads activity `building` + health `healthy` (active & fine). This is what makes `building`
 * mean agents are ACTUALLY running — NOT a resting default — so a triaged project with nothing running
 * stays `idle`. Applied after liveness so active agent work (the more current signal) wins over a bare
 * `live` app. The fault overlay still escalates health to warning/error on top. Pure.
 */
export function applyRunningActivity(projects: ProjectLite[], buildingKeys: ReadonlySet<string>): ProjectLite[] {
  if (buildingKeys.size === 0) return projects;
  return projects.map((p) => (buildingKeys.has(p.id) ? { ...p, activity: "building", health: p.health === "off" ? "healthy" : p.health } : p));
}

/**
 * Overlay the `modifying` HEALTH state (#4052) — the project has work IN FLIGHT.
 *
 * Two signals, either sufficient:
 *   · a LIVE FLEET — an agent session is running against the project right now (`activeKeys`);
 *   · OPEN ISSUES — its plan store has issues that are not yet done (`openIssueKeys`).
 *
 * Either alone is real. A fleet running on a fully-closed board is still modifying the project; a
 * project with eight open issues and nothing running is mid-build, just paused. Requiring both would
 * have made `modifying` mean "building", which the ACTIVITY axis already says — and says better,
 * because it clears the moment the panes close. `modifying` is the durable fact and survives a restart.
 *
 * DOES NOT outrank a problem. `warning`/`error` are left exactly as they are: a project can be busy and
 * broken at the same time, and the broken half is the one the user has to see. (Both are applied later
 * anyway — `applyStallHealth`/`applyFaultHealth` in the workspace — so they also win by ordering.)
 *
 * DOES lift the DERIVED `off`. Dormancy (`applyDormantHealth`) greys every project with no live session,
 * which would otherwise swallow the open-issues signal whole — a paused project with unfinished planned
 * work is not "nothing here". Only the derived resting state is lifted: the user's MANUAL off toggle
 * (#3239) is `applyOffHealth`, applied outermost in `GlanceWorkspace`, so a deactivated node still goes
 * grey no matter what this returns. That layering is what makes lifting `off` here safe.
 *
 * `complete` → `modifying` is deliberate: work having RESUMED on a finished project is precisely the
 * transition worth showing, and leaving it blue-and-still would say the opposite.
 *
 * Pure + exported for direct unit testing, like the other overlays here.
 */
/**
 * Attach each project's issue completion to its node (#4118).
 *
 * The counts were already read — `useProjectProgress` has fetched them since #4052 — but only their
 * BOOLEAN shadow was used (does this project have open issues, for the `modifying` colour) and the
 * numbers were discarded. So an L0 project node had no progress at all, which is why the bars looked
 * missing on the board even after the L1 drill worked: they had never existed at this level.
 *
 * A project absent from `byKey` is left untouched rather than given `0/0` — the node draws no bar for
 * either, but only one of them is a claim.
 */
export function withProjectProgress<T extends { id: string; progress?: { done: number; total: number } }>(
  projects: readonly T[],
  byKey: ReadonlyMap<string, { done: number; total: number }>,
): T[] {
  if (byKey.size === 0) return [...projects];
  return projects.map((p) => {
    const hit = byKey.get(p.id);
    return hit ? { ...p, progress: hit } : p;
  });
}

export function applyModifyingHealth(
  projects: ProjectLite[],
  activeKeys: ReadonlySet<string>,
  openIssueKeys: ReadonlySet<string>,
): ProjectLite[] {
  if (activeKeys.size === 0 && openIssueKeys.size === 0) return projects;
  return projects.map((p) => {
    if (p.health === "warning" || p.health === "error") return p;
    return activeKeys.has(p.id) || openIssueKeys.has(p.id) ? { ...p, health: "modifying" } : p;
  });
}

/** The set of project keys with a LIVE agent session (#2551): any launched pane that is still a live CELL
 *  of an open tab, or any pane with an authoritative `run`/`on` status (covers the director, a session not
 *  a stream). The project key is the pane id's prefix (before the first ':'). Pure.
 *
 *  `livePaneIds` — NOT `fleetPaneStreams` (#3429). The roster map is only cleared by `closeTab`; `killPane`
 *  leaves it populated, so a fleet ended via "End sessions" kept reading `building`/`healthy` here until the
 *  tab itself was closed. `livePaneIds` is the same pruned set the L1 overlay reads (tab membership minus
 *  `endedPanes`/`disabledPanes`), so both layers answer "does a session exist?" from one signal. */
export function deriveBuildingKeys(
  livePaneIds: ReadonlySet<string>,
  paneStatus: Record<string, string | undefined>,
): Set<string> {
  const keys = new Set<string>();
  for (const paneId of livePaneIds) keys.add(projectKeyOfSession(paneId));
  for (const [paneId, st] of Object.entries(paneStatus)) if (st === "run" || st === "on") keys.add(projectKeyOfSession(paneId));
  return keys;
}

/**
 * Overlay DORMANCY onto the node set (#3429) — the L0 half of the #3415 existence rule, and the first
 * question the stack asks rather than the last. A project with no live agent session AND no detected app
 * liveness has nothing running at all: it reads `off · idle`.
 *
 * Until this existed, L0 could only ESCALATE. Every overlay lifted a project off the merge default
 * (`health: "off"`, `idle` until #4042), and nothing ever established that there was nothing to lift — so "dormant" and
 * "has a session, currently quiet" both rendered `idle`, exactly the ambiguity #3415 removed at L1:
 *
 *   no session exists → `off` · a session exists but is quiet → `idle` · working → `healthy`
 *
 * (`off` at L0 previously meant ONLY the user's manual toggle, #3239. That still wins outright — it is
 * applied outermost — this just makes the derived resting state honest about the same word.)
 *
 * Applied BEFORE `applyFaultHealth`: a dormant project with an unresolved fault still reads warning/error,
 * because an unfixed error does not stop being real just because nobody is currently working on it.
 *
 * `curated` nodes survive dormancy for exactly the same reason (#2284/#2541 — "curated colouring wins";
 * fixed in #3513): a draft that DECLARES its own health/activity is making a statement, and greying it
 * out the moment nothing happens to be running discards that in favour of a resting state nobody asked
 * about. Curated-ness is passed IN rather than inferred from the value, because by this point in the
 * pipeline a non-default `health` is equally likely to be a declaration or something an earlier overlay
 * derived — the two are indistinguishable here, and only the merge knows which. Pure.
 */
export function applyDormantHealth(
  projects: ProjectLite[],
  activeKeys: ReadonlySet<string>,
  curatedKeys: ReadonlySet<string> = new Set(),
): ProjectLite[] {
  return projects.map((p) =>
    activeKeys.has(p.id) || curatedKeys.has(p.id) ? p : { ...p, health: "off", activity: "idle" },
  );
}

/**
 * Overlay the fault summary onto the node set (#2541) — the HEALTH axis. A project with an open fault
 * escalates to `warning` (warn) or `error` (error/fatal), carrying the worst fault's title as the
 * `reason` (shown bottom-right in place of the activity word) and its count. Applied LAST so a fault
 * beats a healthy/live resting state — a live app that's throwing errors still reads red. Pure.
 */
export function applyFaultHealth(projects: ProjectLite[], faults: Record<string, GlanceFault>): ProjectLite[] {
  return projects.map((p) => {
    const f = faults[p.id];
    if (!f) return p;
    const health: GHealth = f.level === "warn" ? "warning" : "error";
    return { ...p, health, reason: f.title, faults: f.count };
  });
}

/**
 * Overlay the user's manual OFF toggle onto the node set (#3239) — the one caller-driven HEALTH value.
 * A project the user has deactivated (its id is truthy in `off`) reads health `off` and drops its fault
 * `reason`, so the node greys and reads "off" regardless of what it was doing. Applied OUTERMOST (after
 * liveness/running/stall/fault) so the deliberate mute WINS over every derived status — "if it's not idle
 * then it should be off". Sparse map (absent ⇒ on); pure. Keyed by the project id (== the node id).
 */
export function applyOffHealth(projects: ProjectLite[], off: Record<string, boolean>): ProjectLite[] {
  return projects.map((p) => (off[p.id] ? { ...p, health: "off", reason: undefined } : p));
}

/** Poll the backend for the set of currently-live project keys (#2263). Polling also DRIVES backend
 *  down-detection: the sweep records an "app down" fault for any project that has just gone silent. */
export function useProjectLiveness(enabled = true): ReadonlySet<string> {
  const [liveKeys, setLiveKeys] = useState<ReadonlySet<string>>(() => new Set());
  usePoll(
    async (isCancelled) => {
      if (!enabled) return;
      const rows = await safeInvoke<ProjectLiveness[]>("project_liveness", undefined, []);
      if (isCancelled()) return;
      // Tolerate a null/non-array return (no collector, a stubbed invoke) — no live keys, no throw.
      const list = Array.isArray(rows) ? rows : [];
      const next = new Set(list.filter((r) => r.live).map((r) => r.projectKey));
      // Only replace the set when membership actually changed, so a steady state doesn't churn renders.
      setLiveKeys((prev) => (sameKeys(prev, next) ? prev : next));
    },
    LIVENESS_POLL_MS,
    [enabled],
  );
  return liveKeys;
}

/** Two key sets are equal iff same size and every member shared. */
function sameKeys(a: ReadonlySet<string>, b: ReadonlySet<string>): boolean {
  if (a.size !== b.size) return false;
  for (const k of a) if (!b.has(k)) return false;
  return true;
}

/**
 * Keep only TRIAGED projects (#2541) — the drafted→triaged gate. A project appears on the Glance
 * network ONLY once its triage/fleet has been launched (its key is in `triaged`), so a mere draft or a
 * published-but-never-worked hub is filtered out. "Once the nodes are here, it's because they're
 * working." Pure + exported for direct testing.
 */
export function filterTriaged(projects: ProjectLite[], triaged: Record<string, number>): ProjectLite[] {
  return projects.filter((p) => triaged[p.id] !== undefined);
}

export function useGlanceProjects(enabled = true): ProjectLite[] {
  const drafts = useAppStore((s) => s.localDraftProjects);
  const triagedProjects = useAppStore((s) => s.triagedProjects);
  // Running-agent signals (#2551): the launched roster + authoritative pane statuses → the `building`
  // activity. A project with a live agent pane reads `building`; nothing running → it rests at `idle`.
  // Launched-tab membership (#3429) — the same pruned "this session exists" signal the L1 overlay reads
  // (`GlanceWorkspace.livePaneIds`): a pane is live only while it is a CELL of an open tab and has not
  // been ended or disabled. Replaces `fleetPaneStreams`, which `killPane` never clears.
  const consoleTabs = useAppStore((s) => s.tabs);
  const endedPanes = useAppStore((s) => s.endedPanes);
  const disabledPanes = useAppStore((s) => s.disabledPanes);
  const livePaneIds = useMemo(() => {
    const live = new Set<string>();
    for (const t of consoleTabs) for (const pid of t.paneIds ?? []) {
      if (pid && !endedPanes[pid] && !disabledPanes[pid]) live.add(pid);
    }
    return live;
  }, [consoleTabs, endedPanes, disabledPanes]);
  const paneStatus = useAppStore((s) => s.paneStatus);
  const githubState = useAppStore((s) => s.githubState);
  const setGithubState = useAppStore((s) => s.setGithubState);
  // The per-project classification (#3786/#3802): the planner-set `appType` (application architecture) —
  // surfaced on each Glance project node as the contract endpoint-type discriminator. Absent for an
  // unclassified project ⇒ the node renders plain (no type badge).
  const planClassification = useAppStore((s) => s.planClassification);
  const liveKeys = useProjectLiveness(enabled);
  // #4052 — the OPEN-ISSUES half of `modifying`, in ONE spawn for every project (never one per node).
  const { openKeys: openIssueKeys, byKey: projectProgress } = useProjectProgressRows(enabled);

  // The local published inventory (#2445): the on-disk hubs carrying `.published`, so a published
  // project has a Glance node even with no GitHub connection. Seeded from the module cache on a
  // revisit (no flash), refreshed once per mount.
  const [localPublished, setLocalPublished] = useState<LocalPublishedLite[]>(() => localPublishedCache ?? []);
  useEffect(() => {
    if (!enabled) return;
    let cancelled = false;
    void safeInvoke<LocalProjectWire[]>("list_local_projects", undefined, []).then((list) => {
      if (cancelled) return;
      const pub = (Array.isArray(list) ? list : [])
        .filter((lp) => lp?.published)
        .map((lp) => ({ key: lp.key, title: lp.title }));
      localPublishedCache = pub;
      setLocalPublished(pub);
    });
    return () => { cancelled = true; };
  }, [enabled]);

  // #3966: the durable project list, from the same bridge the Projects page uses. `listDbProjects`
  // returns null on ANY failure (bridge absent, old bundled `bsc` without the verb, bad payload) — we
  // keep the previous rows in that case, so a degraded environment falls back to the store cache
  // exactly as before rather than dropping nodes.
  const [dbProjects, setDbProjects] = useState<DbProject[]>(() => dbProjectsCache ?? NO_DB_PROJECTS);
  useEffect(() => {
    if (!enabled) return;
    let cancelled = false;
    void listDbProjects().then((rows) => {
      if (cancelled || !rows) return;
      dbProjectsCache = rows;
      setDbProjects(rows);
    });
    return () => { cancelled = true; };
  }, [enabled]);

  // githubGraphql (not a raw invoke) so the read goes through the backend TTL cache (#2447):
  // a Glance revisit within the window is served with no network call. Past the window, the
  // light updatedAt probe (#2448) diffs against the persisted records first — when no board
  // moved, the heavy `items(first:100)` re-POST is skipped and the records are re-served (the
  // persist effect below re-stamps fetchedAt).
  const published = useGithubQuery<GhProject[]>(
    () => fetchProjectsWithProbe({
      fetchHeavy: () =>
        githubGraphql<{ viewer?: { projectsV2?: { nodes: GhProject[] } } }>(PROJECTS_QUERY, null)
          .then((d) => d.viewer?.projectsV2?.nodes ?? []),
      records: useAppStore.getState().githubState?.records,
    }),
    [], enabled,
  );

  // Persist the freshest published set (#2446, superseding the module-level #2339 cache): a fresh fetch
  // overwrites the store's `githubState` records+fetchedAt (and mirrors into the bsc-project store), so
  // the last-known board state survives the Glance remount AND an app restart. Written in an effect (not
  // during render) so it stays a clean side effect; the merge below reads it synchronously as a fallback.
  useEffect(() => { if (published.data) setGithubState(toMinimalGhProjects(published.data)); }, [published.data, setGithubState]);

  // Precedence (#2446): live fetch > persisted records > local-inventory-only. The persisted fallback
  // renders the last-known set immediately (no drafts-only flash), then refreshes when the fetch lands —
  // FILTERED to projects that still exist locally (a draft or a published hub): a record whose hub was
  // deleted must not resurrect a node. That matches how the merge treats GitHub-only projects — they
  // render only while the LIVE fetch vouches for them.
  const effectivePublished = useMemo<GhProject[]>(() => {
    if (published.data) return published.data;
    if (!githubState?.records.length) return NO_PUBLISHED;
    const locals = [
      ...Object.entries(drafts).map(([key, d]) => ({ key, title: d.title })),
      ...localPublished,
    ];
    return filterRecordsToLocal(githubState.records, locals).map(minimalToGhProject);
  }, [published.data, githubState, drafts, localPublished]);

  const buildingKeys = useMemo(() => deriveBuildingKeys(livePaneIds, paneStatus), [livePaneIds, paneStatus]);
  // Everything that counts as "this project has something running" (#3429): a live agent session OR a
  // detected running app. Anything outside this set is dormant and reads `off` rather than resting at
  // `idle` — see `applyDormantHealth`.
  const activeKeys = useMemo(() => new Set([...buildingKeys, ...liveKeys]), [buildingKeys, liveKeys]);
  // The CURATED nodes (#2284/#2541) — drafts that declare their own Glance axes. Dormancy leaves these
  // alone (#3513): a declared health/activity is a statement, not a resting state to be overwritten.
  const curatedKeys = useMemo(
    () => new Set(Object.entries(drafts).filter(([, d]) => d.health || d.activity).map(([k]) => k)),
    [drafts],
  );
  // #3966: the draft set the graph is actually built from — the store cache UNIONED with the durable
  // projects DB. Computed once and used for BOTH the merge and the `isDraft` signal below, so a
  // DB-only project is a draft for colouring purposes exactly as a cached one is.
  const effectiveDrafts = useMemo(() => mergeDbIntoDrafts(drafts, dbProjects), [drafts, dbProjects]);
  return useMemo(
    // Merge (drafts + local published + GitHub published), FILTER to triaged/working projects (#2541 —
    // a draft/plan never shows), then overlay activity from real signals: liveness → `live` (#2263),
    // running agents → `building` (#2551); a project with nothing running at all reads `off` (#3429).
    // (Stall → `waiting`/warn and faults → error are overlaid later in the workspace.)
    // …then the `modifying` health state (#4052) LAST, so it can lift the resting `off` that dormancy
    // just derived. It is the only overlay here that reads issue counts.
    () => withProjectProgress(applyModifyingHealth(
      applyDormantHealth(
        applyRunningActivity(
          applyLiveness(
            filterTriaged(
              mergeGlanceProjects(effectiveDrafts, effectivePublished, localPublished).map((p) => ({
                ...p,
                appType: planClassification[p.id]?.appType, // #3786/#3802 — the contract endpoint-type discriminator (absent ⇒ plain)
                // #4062 — the discovered lifecycle intent. NOT `lifecycleOf`: that applies the
                // stage-gating default, and an unclassified project must show no chip at all.
                lifecycle: planClassification[p.id]?.lifecycle,
              })),
              triagedProjects,
            ),
            liveKeys,
          ),
          buildingKeys,
        ),
        activeKeys,
        curatedKeys,
      ),
      activeKeys,
      openIssueKeys,
    ), projectProgress),
    [effectiveDrafts, effectivePublished, localPublished, triagedProjects, liveKeys, buildingKeys, activeKeys, curatedKeys, planClassification, openIssueKeys, projectProgress],
  );
}

runtime.features/glance/lib/useProjectComplete.t:
// useProjectComplete (#2623) — whether a project's BUILD has finished, for the fleet-drill's preview node.
// Polls the project's plan.db issues and derives `projectComplete` (every planned issue complete/verified).
// A null/empty key is never complete. The Glance workspace passes the DRILLED project so the ▷ preview node
// appears exactly when there's a finished app to render.
import { useState } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import { bscJson } from "@/shared/lib/core/bsc";
import { projectComplete } from "@/shared/lib/fleet/streamCompletion";
import type { PlanIssue } from "@/features/planner/issues/planIssues";

const POLL_MS = 20000;

export function useProjectComplete(projectKey: string | null): boolean {
  const [complete, setComplete] = useState(false);
  usePoll(async (isCancelled) => {
    if (!projectKey) { setComplete(false); return; }
    const issues = await bscJson<PlanIssue[]>(projectKey, ["plan", "list", "--full", "--json"], []);
    if (isCancelled()) return;
    setComplete(projectComplete(issues));
  }, POLL_MS, [projectKey]);
  return complete;
}

runtime.features/glance/lib/useProjectFleet.ts:
// useProjectFleet (#…) — load a project's fleet plan straight from ITS plan.db. The `bsc` bridge scopes
// $BSC_PLAN_DB by the project key, so this reads the SAME `bsc plan fleet get --full --json` blob the
// planner poll reads — but for ANY project, not just the active one the store's `planFleet` mirrors. That
// is what makes the Glance drill show a project's REAL fleet instead of the sample. Returns null while
// loading and when a project has no planned fleet. Parsed via the shared `parseFleetFile`.
import { useEffect, useState } from "react";
import { bscJson } from "@/shared/lib/core/bsc";
import { parseFleetFile, type FleetPlan } from "@/features/planner/fleet/planFleet";

export function useProjectFleet(projectKey: string | null): FleetPlan | null {
  // Store the loaded fleet WITH the key it's for, so a cleared/changed drill just returns null (no
  // stale fleet, no synchronous setState-in-effect reset).
  const [loaded, setLoaded] = useState<{ key: string; fleet: FleetPlan | null }>({ key: "", fleet: null });
  useEffect(() => {
    if (!projectKey) return;
    let cancelled = false;
    bscJson<unknown | null>(projectKey, ["plan", "fleet", "get", "--full", "--json"], null)
      .then((raw) => { if (!cancelled) setLoaded({ key: projectKey, fleet: raw ? parseFleetFile(JSON.stringify(raw)) : null }); })
      .catch(() => { if (!cancelled) setLoaded({ key: projectKey, fleet: null }); });
    return () => { cancelled = true; };
  }, [projectKey]);
  return projectKey && loaded.key === projectKey ? loaded.fleet : null;
}

runtime.features/glance/lib/useProjectProgress.t:
// Every local project's issue completion (#4052) — the OPEN-ISSUES half of the L0 `modifying` health
// state.
//
// ONE SPAWN FOR ALL PROJECTS. `bsc project progress --json` walks the hubs and counts each plan.db
// inside a single process; the alternative — `bsc plan list` per project — is the N-per-pane fan-out
// shape that has cost this app whole seconds before (#3908 / #3912 / #3944 / #3954). With ~29 hubs
// locally that is 29 process spawns per poll versus one, which is the difference between a background
// read and a visible stall.
//
// Distinct from `useStreamProgress`, which reads ONE drilled project's issues and partitions them per
// STREAM for the L1 progress bars. This one is per PROJECT and spans all of them — different scope,
// different question, and it must keep working when nothing is drilled at all.
import { useEffect, useMemo, useState } from "react";
import { bscJson } from "@/shared/lib/core/bsc";
import { usePoll } from "@/shared/hooks/usePoll";

/** One project's issue counts, as the CLI reports them. */
export interface ProjectProgressRow {
  key: string;
  done: number;
  total: number;
}

/** Issue counts move at human speed — a worker closing one is a minutes-scale event — and this drives a
 *  colour, not a number on screen. A fast poll would spend a spawn to re-read an unchanged answer. */
export const PROJECT_PROGRESS_POLL_MS = 30_000;

/**
 * Project keys with at least one issue NOT yet done.
 *
 * A project the CLI omits (no plan.db, or a plan store with no issues table) is simply absent from the
 * set — never assumed to have open work. Guessing the busy state from a missing read would light up
 * every unplanned hub on the board, and a wrong signal here is worse than none: the whole point of the
 * state is that it means something.
 *
 * The read failing likewise keeps the LAST GOOD answer rather than clearing, so a transient spawn
 * failure doesn't make every project blink out of `modifying` and back.
 */
export function useProjectProgress(enabled = true): ReadonlySet<string> {
  return useProjectProgressRows(enabled).openKeys;
}

/** The same ONE read, exposing the COUNTS as well (#4118) — the L0 project nodes draw a `done/total`
 *  bar from them, where before this hook's only consumer was the `modifying` colour and the numbers
 *  were thrown away. Still one spawn for every project. */
export function useProjectProgressRows(enabled = true): {
  openKeys: ReadonlySet<string>;
  byKey: ReadonlyMap<string, { done: number; total: number }>;
} {
  const [rows, setRows] = useState<ProjectProgressRow[]>([]);

  // Stop accumulating when Glance is not mounted/enabled — and drop what we had, so a re-enable
  // re-reads rather than rendering a possibly-stale board.
  useEffect(() => {
    if (!enabled) setRows([]);
  }, [enabled]);

  usePoll(async (isCancelled) => {
    if (!enabled) return;
    const next = await bscJson<ProjectProgressRow[] | null>(null, ["project", "progress", "--json"], null);
    if (isCancelled() || !Array.isArray(next)) return;   // read failed ⇒ keep the last good answer
    setRows(next);
  }, PROJECT_PROGRESS_POLL_MS, [enabled]);

  return useMemo(
    () => ({
      openKeys: openIssueKeys(rows),
      // Only rows with real work: a `total` of 0 means "no data" as much as "nothing planned", and the
      // node treats an absent entry and a 0/0 entry identically (no bar) — so omitting them keeps the
      // map honest about what it actually knows.
      byKey: new Map(rows.filter((r) => r.total > 0).map((r) => [r.key, { done: r.done, total: r.total }])),
    }),
    [rows],
  );
}

/** The set of keys with unfinished work: `done < total`. `total === 0` is NOT open work — a planned
 *  project with zero issues has nothing in flight, and counting it would make the state meaningless for
 *  every hub that was scaffolded and abandoned. Pure + exported for direct unit testing. */
export function openIssueKeys(rows: readonly ProjectProgressRow[]): ReadonlySet<string> {
  const out = new Set<string>();
  for (const r of rows ?? []) {
    if (r && typeof r.key === "string" && r.total > 0 && r.done < r.total) out.add(r.key);
  }
  return out;
}

runtime.features/glance/lib/useStreamProgress.ts:
// The drilled project's per-stream issue progress (#4050).
//
// ONE read per project on a slow cadence, partitioned in memory — never one read per node. That
// fan-out shape has cost real time in this app before (#3908 / #3912 / #3944 / #3954), and a graph of
// twenty workers would make twenty spawns of the same query.
//
// Scoped to the DRILLED project because that is the only fleet whose nodes are on screen: the cost is
// bounded by what the user is actually looking at, and it stops entirely when they leave the drill.
//
// It cannot piggyback on `useWorkerAutoEnd`'s read of the same data — that one is event-gated on panes
// that just went idle, so it says nothing while a fleet is steadily working, which is exactly when a
// progress bar is worth having.
import { useEffect, useState } from "react";
import { bscJson } from "@/shared/lib/core/bsc";
import { usePoll } from "@/shared/hooks/usePoll";
import type { OwnedIssue } from "@/shared/lib/fleet/workerEnd";
import { streamProgress, planDbDoneRefs, type StreamProgress } from "./streamProgress";

/** Issue counts move at human speed — a worker closing one is a minutes-scale event, so a fast poll
 *  would spend spawns to re-read an unchanged answer. */
export const PROGRESS_POLL_MS = 20_000;

/** What one poll of plan.db yields. #4102 added `doneRefs`: the same read now also feeds the
 *  ref-based progress path, which needs to know WHICH issues are finished rather than just how many —
 *  so plan.db statuses and the GitHub overlay can be unioned into one done-set. One read, two shapes;
 *  a second hook over the same query would be the fan-out this file's header warns about. */
export interface PlanDbProgress {
  byStream: Map<string, StreamProgress>;
  /** Refs of issues plan.db considers finished (`complete` | `verified`). */
  doneRefs: Set<string>;
}

const EMPTY: PlanDbProgress = { byStream: new Map(), doneRefs: new Set() };

/** Per-stream `done / total` for `projectKey` plus its done refs, or empty when not drilled / no plan
 *  store. */
export function useStreamProgress(projectKey: string | null): PlanDbProgress {
  const [state, setState] = useState<PlanDbProgress>(EMPTY);

  // Clear on a project switch so the previous fleet's numbers never render against this one's nodes.
  useEffect(() => { setState(EMPTY); }, [projectKey]);

  usePoll(async (isCancelled) => {
    if (!projectKey) return;
    const issues = await bscJson<OwnedIssue[] | null>(projectKey, ["plan", "list", "--full", "--json"], null);
    if (isCancelled() || !issues) return;   // read failed / no plan.db ⇒ keep the last good answer
    setState({ byStream: streamProgress(issues), doneRefs: planDbDoneRefs(issues) });
  }, PROGRESS_POLL_MS, [projectKey]);

  return state;
}

runtime.features/glance/usePreviewReview.ts:
// usePreviewReview (#2623 slice 5b) — the reviewer loop's actuator for the open preview node. Owns the
// display-capture stream, turns a "Capture & review" click into a shot → Claude review (5c) → findings
// merged into the confirm-gated inbox (5a store), and exposes confirm/dismiss. Findings live in the store
// keyed by project so the strip re-renders; the stream is a ref (one OS "share" pick, reused per shot).

import { useCallback, useEffect, useRef, useState } from "react";
import { useAppStore } from "@/store";
import { resolveLlmConfig } from "@/shared/lib/core/llmConfig";
import { startPreviewCapture, grabFrame, stopCapture, screenCaptureAvailable } from "@/shared/lib/preview/captureFrame";
import { reviewShot } from "@/shared/lib/preview/reviewShot";
import { injectPrompt } from "@/shared/lib/fleet/paneInject";
import {
  mergeFindings,
  setFindingStatus,
  pendingFindings,
  confirmedFindings,
  routedFindings,
  reviewDispatchPrompt,
  type PreviewShot,
  type ReviewFinding,
} from "@/shared/lib/preview/previewReview";

const EMPTY: ReviewFinding[] = [];
const errText = (e: unknown): string => (e instanceof Error ? e.message : String(e));

/** A readable screen label from a shot id (`<key>:<seq>` → "Screen N") for the dispatch prose. */
function screenLabel(shotId: string): string {
  const seq = Number(shotId.split(":").pop());
  return Number.isFinite(seq) ? `Screen ${seq + 1}` : shotId;
}

export interface PreviewReview {
  findings: ReviewFinding[];
  pending: ReviewFinding[];
  confirmed: ReviewFinding[];
  /** Findings already routed to the fleet (a tally; they don't re-dispatch). */
  routed: ReviewFinding[];
  /** Screen capture is available in this webview (gate the capture button). */
  canCapture: boolean;
  /** A capture + review is in flight. */
  busy: boolean;
  /** The last capture/review/dispatch failure, or null. */
  error: string | null;
  /** Capture the current preview frame and review it — folds new findings into the inbox. */
  captureAndReview: () => Promise<void>;
  confirm: (id: string) => void;
  dismiss: (id: string) => void;
  /** Route all confirmed findings to the project's director (bsc-issue → bsc-assign) and mark them routed. */
  dispatch: () => Promise<void>;
}

export function usePreviewReview(projectKey: string | null): PreviewReview {
  const findings = useAppStore((s) => (projectKey ? s.reviewFindings[projectKey] : undefined) ?? EMPTY);
  const streamRef = useRef<MediaStream | null>(null);
  const seqRef = useRef(0);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // End the OS "sharing" stream when the preview closes / the hook unmounts.
  useEffect(() => () => { stopCapture(streamRef.current); streamRef.current = null; }, []);

  const captureAndReview = useCallback(async () => {
    if (!projectKey || busy) return;
    setError(null);
    setBusy(true);
    try {
      if (!streamRef.current) streamRef.current = await startPreviewCapture();
      const image = await grabFrame(streamRef.current);
      const seq = seqRef.current++;
      const shot: PreviewShot = { id: `${projectKey}:${seq}`, label: `Screen ${seq + 1}`, image };
      const found = await reviewShot(resolveLlmConfig(useAppStore.getState()), shot, seq);
      const store = useAppStore.getState();
      store.setReviewFindings(projectKey, mergeFindings(store.reviewFindings[projectKey] ?? [], found));
    } catch (e) {
      setError(errText(e));
      // A failure often means the user stopped sharing — drop the stream so the next try re-prompts.
      stopCapture(streamRef.current);
      streamRef.current = null;
    } finally {
      setBusy(false);
    }
  }, [projectKey, busy]);

  const setStatus = useCallback((id: string, status: ReviewFinding["status"]) => {
    if (!projectKey) return;
    const store = useAppStore.getState();
    store.setReviewFindings(projectKey, setFindingStatus(store.reviewFindings[projectKey] ?? [], id, status));
  }, [projectKey]);

  const dispatch = useCallback(async () => {
    if (!projectKey) return;
    const store = useAppStore.getState();
    const confirmed = confirmedFindings(store.reviewFindings[projectKey] ?? []);
    if (confirmed.length === 0) return;
    // The director is where the fleet's coordination runs — no live fleet, nowhere to route.
    if (store.findFleetTabIdx(projectKey) < 0) {
      setError("No running fleet — launch it first so the director can pick up the review.");
      return;
    }
    setError(null);
    try {
      await injectPrompt(`${projectKey}:director`, reviewDispatchPrompt(confirmed, screenLabel));
      let next = store.reviewFindings[projectKey] ?? [];
      for (const f of confirmed) next = setFindingStatus(next, f.id, "routed");
      store.setReviewFindings(projectKey, next);
    } catch (e) {
      setError(errText(e));
    }
  }, [projectKey]);

  return {
    findings,
    pending: pendingFindings(findings),
    confirmed: confirmedFindings(findings),
    routed: routedFindings(findings),
    canCapture: screenCaptureAvailable(),
    busy,
    error,
    captureAndReview,
    confirm: useCallback((id: string) => setStatus(id, "confirmed"), [setStatus]),
    dismiss: useCallback((id: string) => setStatus(id, "dismissed"), [setStatus]),
    dispatch,
  };
}

runtime.features/mcp/graphPlatform.ts:
// The mcp feature's graph-platform surface (#3656, epic #3604) — the feature-internal modules a graph-loaded
// MCP page imports but does NOT redraw: the install/version/catalog/telemetry logic, the `./shared` grab-bag
// (the useGhProjects hook + the drawer/row/card helpers), and the install-status hook. Registered HERE,
// inside the feature, because the shell must not reach a feature's internals (#1545). The mcp host calls this
// synchronously before the graph page loads. Mirrors the fleet/automations/security/github/skills platforms.
// (`@/features/mcp` — the barrel with HooksView/telemetry — is registered by the AUTOMATIONS platform; these
// are the mcp INTERNALS, a disjoint set of specifiers.)
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
import * as McpInstall from "./lib/mcpInstall";
import * as McpCatalogView from "./lib/mcpCatalogView";
import * as McpServers from "./lib/mcpServers";
import * as Hooks from "./lib/hooks";
import * as McpTelemetry from "./lib/mcpTelemetry";
import * as Shared from "./shared";
import * as UseMcpInstallStatus from "./useMcpInstallStatus";

let done = false;

/** Register the mcp page's injected graph-platform modules by the specifiers it imports. Idempotent. */
export function registerMcpPlatform(): void {
  if (done) return;
  done = true;
  registerAppModule("@/features/mcp/lib/mcpInstall", McpInstall);
  registerAppModule("@/features/mcp/lib/mcpCatalogView", McpCatalogView);
  registerAppModule("@/features/mcp/lib/mcpServers", McpServers);
  registerAppModule("@/features/mcp/lib/hooks", Hooks);
  registerAppModule("@/features/mcp/lib/mcpTelemetry", McpTelemetry);
  registerAppModule("@/features/mcp/shared", Shared);
  registerAppModule("@/features/mcp/useMcpInstallStatus", UseMcpInstallStatus);
}

