// Hook-fire telemetry (#865 PR 2) — parse + aggregate the hook-fire log for the Hook
// Analytics tab. Mirrors skillTelemetry.ts. The log lives at ~/.base-studio-code/hooks.log,
// one TSV line per fire: `ts \t pane \t event \t hook \t outcome` (#1743 prepended the pane
// column). Legacy lines written before #1743 have no pane (`ts \t event \t hook \t outcome`)
// and are still tolerated — the parser detects the shape by column count. Read newest-first via
// `bsc logs tail hook`. `outcome` is "allow" | "block" (PreToolUse decisions) or "ok"
// (PostToolUse / non-gating events). Pure + unit-tested; the hook wrappers that EMIT these
// lines are wired separately (PR 3).

import { dayKey } from "@/shared/lib/core/format";

export type HookOutcome = "allow" | "block" | "ok";

export interface HookFire {
  /** epoch ms */
  ts: number;
  /** PreToolUse | PostToolUse | Stop | … */
  event: string;
  /** the hook's name */
  hook: string;
  outcome: HookOutcome;
}

/** Parse the TSV hook-fire log into records, skipping malformed lines. */
export function parseHookLog(text: string): HookFire[] {
  const out: HookFire[] = [];
  for (const line of text.split("\n")) {
    if (!line.trim()) continue;
    const parts = line.split("\t");
    // #1743: new lines carry a leading pane column (5 fields: ts·pane·event·hook·outcome); legacy
    // lines have none (4 fields: ts·event·hook·outcome). Detect by column count and offset the field
    // reads. The pane isn't surfaced here (the analytics don't break down by session), so it's read
    // past, not stored.
    const b = parts.length >= 5 ? 1 : 0;
    const [tsRaw, event, hook, outcomeRaw] = [parts[0], parts[b + 1], parts[b + 2], parts[b + 3]];
    const ts = Number(tsRaw);
    if (!Number.isFinite(ts) || !event || !hook) continue;
    const outcome: HookOutcome = outcomeRaw === "block" ? "block" : outcomeRaw === "allow" ? "allow" : "ok";
    out.push({ ts, event, hook, outcome });
  }
  return out;
}

export interface DayBucket { day: string; allows: number; blocks: number; }
export interface HookCount { hook: string; event: string; fires: number; }
export interface PreHookSplit { hook: string; allows: number; blocks: number; }

export interface HookAnalytics {
  /** total fires in the window */
  total: number;
  /** PreToolUse fires denied (outcome === "block") */
  blocks: number;
  /** PreToolUse fires allowed (outcome === "allow") */
  allows: number;
  /** allows / (allows + blocks), 0–100; 100 when no PreToolUse decisions */
  allowRate: number;
  /** per-day allow (allow + ok) vs block counts, oldest→newest, length === days */
  daily: DayBucket[];
  /** fires per hook, descending */
  perHook: HookCount[];
  /** PreToolUse hooks only: allows vs blocks, descending by total */
  perPreHook: PreHookSplit[];
}

const DAY_MS = 86_400_000;

/**
 * Aggregate hook fires into the analytics the Hook Analytics tab renders. Only fires within
 * the last `days` (relative to `now`) are counted. `daily` always has exactly `days` buckets
 * (zero-filled), oldest→newest, so the chart has a stable x-axis.
 */
export function aggregateHookTelemetry(fires: HookFire[], now: Date, days = 14): HookAnalytics {
  const end = now.getTime();
  const start = end - days * DAY_MS;
  const inWindow = fires.filter((f) => f.ts >= start && f.ts <= end);

  // Stable daily buckets (oldest→newest), keyed by local day.
  const daily: DayBucket[] = [];
  const idxByDay = new Map<string, number>();
  for (let i = days - 1; i >= 0; i--) {
    const key = dayKey(end - i * DAY_MS);
    idxByDay.set(key, daily.length);
    daily.push({ day: key, allows: 0, blocks: 0 });
  }

  let blocks = 0;
  let allows = 0;
  const perHookMap = new Map<string, HookCount>();
  const perPreMap = new Map<string, PreHookSplit>();

  for (const f of inWindow) {
    if (f.outcome === "block") blocks++;
    else if (f.outcome === "allow") allows++;

    const bucket = idxByDay.get(dayKey(f.ts));
    if (bucket != null) {
      if (f.outcome === "block") daily[bucket].blocks++;
      else daily[bucket].allows++;
    }

    const hk = perHookMap.get(f.hook) ?? { hook: f.hook, event: f.event, fires: 0 };
    hk.fires++;
    perHookMap.set(f.hook, hk);

    if (f.event === "PreToolUse") {
      const ph = perPreMap.get(f.hook) ?? { hook: f.hook, allows: 0, blocks: 0 };
      if (f.outcome === "block") ph.blocks++;
      else ph.allows++;
      perPreMap.set(f.hook, ph);
    }
  }

  const perHook = [...perHookMap.values()].sort((a, b) => b.fires - a.fires);
  const perPreHook = [...perPreMap.values()].sort((a, b) => (b.allows + b.blocks) - (a.allows + a.blocks));
  const decided = allows + blocks;

  return {
    total: inWindow.length,
    blocks,
    allows,
    allowRate: decided > 0 ? Math.round((allows / decided) * 100) : 100,
    daily,
    perHook,
    perPreHook,
  };
}

runtime.features/mcp/lib/mcpCatalogView.ts:
// Catalog/installed derivation for the MCP screen. Pure (no React/Tauri): splits the catalog into
// the always-available "Built-in tools" set vs the downloadable browse list, dedupes already-
// installed servers, and free-text filters. Shared by the screen's installed + catalog views.

import { MCP_CATALOG, type CatalogItem } from "@/shared/data/mcpCatalog";
import { BUILTIN_MCP_SERVERS, type McpServer } from "./mcpServers";

/** Catalog entries for the built-in servers (#1196) — shown as always-available, never downloadable. */
export const builtInCatalog: CatalogItem[] = MCP_CATALOG.filter(
  c => c.builtIn || BUILTIN_MCP_SERVERS.some(b => b.name.toLowerCase() === c.name.toLowerCase()),
);

/** Lowercased names of the installed servers, for catalog dedupe. */
export function installedNameSet(servers: McpServer[]): Set<string> {
  return new Set(servers.map(e => e.name.toLowerCase()));
}

/** The downloadable/browsable catalog: every entry that isn't built-in (those live in the
 *  Built-in tools section) and isn't already installed. */
export function browsableCatalog(servers: McpServer[]): CatalogItem[] {
  const installed = installedNameSet(servers);
  return MCP_CATALOG.filter(c => !c.builtIn && !installed.has(c.name.toLowerCase()));
}

/** Count for the Catalog tab badge: catalog entries not yet installed (built-ins included, matching
 *  the original badge). */
export function catalogTabCount(servers: McpServer[]): number {
  const installed = installedNameSet(servers);
  return MCP_CATALOG.filter(c => !installed.has(c.name.toLowerCase())).length;
}

/** Free-text filter over a catalog list by name + description (empty query → unchanged). */
export function filterCatalog(items: CatalogItem[], query: string): CatalogItem[] {
  const q = query.trim().toLowerCase();
  return q ? items.filter(c => c.name.toLowerCase().includes(q) || c.desc.toLowerCase().includes(q)) : items;
}

runtime.features/mcp/lib/mcpInstall.ts:
// Shared helpers for downloadable (first-party) MCP servers — the bridge between a
// catalog entry's GitHub download link and the on-disk install path its run config
// points at. Pure (no React/Tauri) so the MCP screen, the planner-assign path,
// and the planning-page panel all resolve `{dir}` the same way.

import { MCP_CATALOG } from "@/shared/data/mcpCatalog";
import { mcpInstallDir } from "@/shared/lib/core/projectPaths";

/** Repo slug from a GitHub link: the last non-empty path segment. */
export function repoNameFromLink(link: string): string {
  return link.replace(/\/+$/, "").split("/").pop() ?? "";
}

/** The catalog download link for a server name, if it's a downloadable (first-party)
 *  server that installs from source; `undefined` for built-in/remote servers. */
export function catalogLink(name: string): string | undefined {
  return MCP_CATALOG.find((c) => c.name === name)?.link;
}

/** The repo slug (== install dir name) for a downloadable server, or "" if it isn't one.
 *  This is the `name` arg `mcp_clone` / `mcp_build` / `mcp_status` take. */
export function mcpRepoName(name: string): string {
  const link = catalogLink(name);
  return link ? repoNameFromLink(link) : "";
}

/** The on-disk install dir for a downloadable server, or "" if it isn't downloadable
 *  or `baseDir` is empty. `~/.base-studio-code/mcp/<repo>`. */
export function mcpDirForServer(name: string, baseDir: string): string {
  const link = catalogLink(name);
  return link && baseDir ? mcpInstallDir(baseDir, repoNameFromLink(link)) : "";
}

/**
 * Substitute the `{dir}` placeholder in a server def's `args` with its real on-disk
 * install path. No-op when the def has no `{dir}`, the server isn't downloadable, or
 * `baseDir` is empty — so a literal `{dir}` never reaches a launched config (the bug
 * the planner-assign path had: it skipped this and launched `--directory {dir}`).
 */
export function resolveMcpInstallDir<T extends { args?: string }>(def: T, name: string, baseDir: string): T {
  const dir = mcpDirForServer(name, baseDir);
  if (dir && def.args?.includes("{dir}")) {
    return { ...def, args: def.args.replace("{dir}", dir) };
  }
  return def;
}

runtime.features/mcp/lib/mcpServers.ts:
// MCP server model + per-session resolution + `.mcp.json` payload + catalog templates.
//
// An MCP server is an external process (stdio) or endpoint (http) Claude connects to.
// Pure (no React / Tauri) so it's shared by the store, the MCP screen, and TerminalView.
// Split out of the former unified `extensions.ts` (mcp + hook discriminated union).

import builtinServersEmbedded from "@data/mcp/builtin-servers.json";
import catalogTemplatesEmbedded from "@data/mcp/catalog-templates.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

export type McpTransport = "stdio" | "http";

/** A user-configured MCP server. Scoped per-server via {@link McpServer.projects}. */
export interface McpServer {
  id: string;
  name: string;
  enabled: boolean;
  /** `[]` = every project (global); otherwise the project ids it applies to. */
  projects: string[];
  transport: McpTransport;
  command?: string;   // stdio binary
  args?: string;      // stdio args (space-split at write time)
  url?: string;       // http endpoint
  env?: Array<[string, string]>;
}

/**
 * Built-in MCP servers (#1196) — shipped compiled in the app bundle (native sidecars), so they're
 * **always available** with no download/build/Docker and need no store entry. `command` is a marker
 * the Rust side rewrites to the bundled binary's absolute path when writing `.mcp.json` (Claude Code
 * spawns `.mcp.json` commands directly, with no PATH/shell-rc). They behave like a global, enabled
 * server: the planner/director see them, and every session (incl. workers) gets them by default.
 *
 * The DATA is externalized to `@data/mcp/builtin-servers.json` (#2146, epic #2027 tail) — editable
 * without touching code + part of the exportable config bundle; the config-dir copy (#2047) overlays
 * the embedded default via `overlayFile`.
 */
export const BUILTIN_MCP_SERVERS: McpServer[] = overlayFile("mcp/builtin-servers.json", builtinServersEmbedded as McpServer[]);

/** Prepend the built-in servers, skipping any a user entry already shadows by name (case-insensitive).
 *  Tolerates a nameless entry (malformed persisted state, #2515) — it shadows nothing.
 *  `onlyEnabled` limits the prepended built-ins to the enabled ones — the GLOBAL set every session
 *  gets. A DISABLED built-in (a per-stream channel, #3146: `channel-mock`) is catalog-present but NOT
 *  global; it reaches a session only by explicit stream assignment ({@link resolveStreamMcp}). */
function withBuiltins(servers: McpServer[], onlyEnabled = false): McpServer[] {
  const taken = new Set(servers.map(s => s.name?.toLowerCase()).filter((n): n is string => !!n));
  const builtins = BUILTIN_MCP_SERVERS.filter(b => (!onlyEnabled || b.enabled) && !taken.has(b.name.toLowerCase()));
  return [...builtins, ...servers];
}

/**
 * The enabled servers that apply to a session in `projectId`: a server applies when it is
 * enabled AND either global (`projects` empty) or scoped to this project. An empty
 * `projectId` (no project) yields only global servers. ENABLED built-in servers (#1196 —
 * research/compliance) are always included (global by construction); a DISABLED built-in (a marketing
 * channel, #3146) is deliberately NOT global — it's per-stream-assignable only, so the whole fleet
 * never gets `send_email`.
 */
export function resolveMcpServers(all: McpServer[], projectId: string): McpServer[] {
  return withBuiltins(
    all.filter(e => e.enabled && (e.projects.length === 0 || (!!projectId && e.projects.includes(projectId)))),
    true,
  );
}

/**
 * Every **downloaded** server, regardless of the enable toggle or project scope (#1054). The
 * planner sees all installed servers — so a freshly downloaded one (which lands disabled) is
 * available immediately, and the planner can call it while planning and decide which workers need
 * it. The director gets the same set since it coordinates the whole fleet. "Downloaded" = has a
 * runnable config (`toMcpPayload` non-null: stdio with a command, http with a url); half-configured
 * entries are skipped so a broken `.mcp.json` line never reaches a session.
 */
export function resolveAllInstalledMcp(all: McpServer[]): McpServer[] {
  // Built-in servers (#1196) are always "installed" — the planner/director see them by default.
  return withBuiltins(all).filter(e => toMcpPayload(e) !== null);
}

/**
 * A worker's servers (#1054): the fleet-wide baseline — {@link resolveMcpServers} (enabled global +
 * this-project servers, the #876 behavior every worker shares) — PLUS any server the worker's
 * stream explicitly assigned by name (`stream.mcp`, case-insensitive). Stream assignment is intent,
 * so an assigned extra is included regardless of the enable toggle / project scope, as long as it
 * has a runnable config (`toMcpPayload` non-null). This is how the planner gives one worker the
 * extra tools its lane needs without handing them to the whole fleet, while project-wide tools
 * (a DB everyone touches) still ride the baseline.
 */
export function resolveStreamMcp(all: McpServer[], streamMcp: string[] = [], projectId = ""): McpServer[] {
  const base = resolveMcpServers(all, projectId);
  const baseIds = new Set(base.map(e => e.id));
  const assigned = new Set(streamMcp.map(n => n.toLowerCase()));
  // Assignable candidates = the store's servers PLUS the bundled built-ins — so a per-stream CHANNEL
  // (a disabled built-in like `channel-mock`, #3146) can be handed to just the marketer stream, not
  // the whole fleet, exactly as a downloaded server is. A name already in the base isn't re-added.
  const candidates = [...BUILTIN_MCP_SERVERS, ...all];
  const extra = candidates.filter(
    e => toMcpPayload(e) !== null && !!e.name && assigned.has(e.name.toLowerCase()) && !baseIds.has(e.id),
  );
  return [...base, ...extra];
}

// ── Backend payload ───────────────────────────────────────────────────────────
// Shape handed to `ensure_session_settings`; field names match the Rust struct.

export interface McpServerPayload {
  name: string;
  transport: McpTransport;
  command?: string;
  args: string[];
  url?: string;
  env: Array<[string, string]>;
}

/** An MCP server → its `.mcp.json` payload, or null if it's incomplete
 *  (stdio without a command, http without a url). */
export function toMcpPayload(e: McpServer): McpServerPayload | null {
  if (e.transport === "http") {
    if (!e.url) return null;
    return { name: e.name, transport: "http", args: [], url: e.url, env: e.env ?? [] };
  }
  if (!e.command) return null;
  return {
    name: e.name,
    transport: "stdio",
    command: e.command,
    args: (e.args ?? "").split(/\s+/).filter(Boolean),
    env: e.env ?? [],
  };
}

/** The `$BSC_AGENT_MCP` config bsc-agent reads (#1078 P3) — its MCP client is **stdio-only**, so
 *  http servers are dropped; `env` becomes a plain object (matching the Rust `McpServerCfg`). */
export interface BscAgentMcpCfg {
  name: string;
  command: string;
  args: string[];
  env: Record<string, string>;
}

export function toBscAgentMcp(payloads: McpServerPayload[]): BscAgentMcpCfg[] {
  return payloads
    .filter((p) => p.transport === "stdio" && !!p.command)
    .map((p) => ({
      name: p.name,
      command: p.command as string,
      args: p.args,
      env: Object.fromEntries(p.env),
    }));
}

// ── Catalog templates ─────────────────────────────────────────────────────────
// Pre-filled config for well-known catalog entries (keyed by catalog item name).
// Unknown names fall back to a blank stdio server the user completes.
//
// The DATA is externalized to `@data/mcp/catalog-templates.json` (#2419, epic #2027 tail) — editable
// without touching code + part of the exportable config bundle; the config-dir copy (#2047) overlays
// the embedded default via `overlayFile`. What the entries mean:
// - First-party servers (#858) — downloaded to ~/.base-studio-code/mcp/<repo>, so the command runs
//   the built entrypoint from there. `{dir}` is replaced with the resolved clone path when the entry
//   is added (addFromCatalog); the user downloads + builds via the card.
// - `python -m uv` (not a bare `uv`): uv is installed as a Python module and its console-script shim
//   often isn't on PATH on a fresh machine — `python -m uv` runs without any PATH setup (#887).
// - Built-in native servers (#1005 Compliance, #1196 Research): no download/build/Docker.
//   `bsc-compliance-mcp` / `bsc-research-mcp` are markers the Rust side rewrites to the bundled
//   binary's absolute path when writing .mcp.json. Kept in the templates so the planner's
//   `<mcp_assign name="…" />` path also resolves them to the native binary.
// - Well-known third-party servers (Postgres/Slack/Sentry/…) — pruned from the browse catalog (#870)
//   but kept here so the planner's `<mcp_assign name="…" />` (planExtensions.ts) still resolves them
//   to a working config.
// (`as unknown` for the `env` pairs: JSON can't express the `[string, string]` tuple type.)
const MCP_CATALOG_TEMPLATES: Record<string, Partial<McpServer>> =
  overlayFile("mcp/catalog-templates.json", catalogTemplatesEmbedded as unknown as Record<string, Partial<McpServer>>);

/** A ready-to-add MCP server (minus id) for a catalog entry — disabled + global
 *  by default; the caller assigns the id and the user fills any blank config. */
export function mcpFromCatalog(name: string): Omit<McpServer, "id"> {
  const t = MCP_CATALOG_TEMPLATES[name] ?? { transport: "stdio" as McpTransport, command: "", args: "" };
  return {
    name,
    enabled: false,
    projects: [],
    transport: t.transport ?? "stdio",
    command: t.command,
    args: t.args,
    url: t.url,
    env: t.env,
  };
}

/** A blank custom MCP server, ready for the add-custom form. */
export function blankMcpServer(): Omit<McpServer, "id"> {
  return { name: "", enabled: false, projects: [], transport: "stdio", command: "", args: "", env: [] };
}

runtime.features/mcp/lib/mcpTelemetry.ts:
// MCP-call telemetry (#879) — parse + aggregate the MCP tool-call log for the MCP Analytics
// tab. Mirrors hookTelemetry.ts. The log lives at ~/.base-studio-code/mcp.log, one TSV line
// per call: `ts \t pane \t server \t tool \t outcome \t ms \t detail` (#1743 prepended the pane
// column). Legacy lines written before #1743 have no pane (`ts \t server \t tool \t outcome \t
// ms [\t detail]`) and are still tolerated — the parser detects the shape by column count.
// Read newest-first via `bsc logs tail mcp`. `outcome` is "ok" | "warn" | "fail"; `ms` is the round-trip latency of the
// call (the agent invoking the MCP tool → the server's response). A "warn" is a successful but
// slow / rate-limited call, so it counts toward SUCCESS (only "fail" is an error). Pure +
// unit-tested; the hook pair that EMITS these lines is wired separately (PR 2).

import { dayKey } from "@/shared/lib/core/format";

export type McpOutcome = "ok" | "warn" | "fail";

export interface McpCall {
  /** epoch ms */
  ts: number;
  /** the MCP server name (the `<server>` in `mcp__<server>__<tool>`) */
  server: string;
  /** the tool name */
  tool: string;
  outcome: McpOutcome;
  /** round-trip latency of the call, in ms */
  ms: number;
  /** optional human detail (error text / "slow · rate-limited") shown in the call log */
  detail: string;
}

/** Parse the TSV MCP-call log into records, skipping malformed lines. */
export function parseMcpLog(text: string): McpCall[] {
  const out: McpCall[] = [];
  for (const line of text.split("\n")) {
    if (!line.trim()) continue;
    const parts = line.split("\t");
    // #1743: new lines carry a leading pane column (7 fields: ts·pane·server·tool·outcome·ms·detail);
    // legacy lines have none (5–6 fields: ts·server·tool·outcome·ms[·detail]). Detect by column count
    // and offset the field reads so both shapes parse. The pane isn't surfaced here (the analytics
    // don't break down by session), so it's read past, not stored.
    const b = parts.length >= 7 ? 1 : 0;
    const [tsRaw, server, tool, outcomeRaw, msRaw] = [parts[0], parts[b + 1], parts[b + 2], parts[b + 3], parts[b + 4]];
    const ts = Number(tsRaw);
    if (!Number.isFinite(ts) || !server || !tool) continue;
    const outcome: McpOutcome = outcomeRaw === "fail" ? "fail" : outcomeRaw === "warn" ? "warn" : "ok";
    const ms = Number(msRaw);
    out.push({
      ts, server, tool, outcome,
      ms: Number.isFinite(ms) ? ms : 0,
      detail: parts.slice(b + 5).join("\t").trim(),
    });
  }
  return out;
}

export interface McpDayBucket { day: string; ok: number; error: number; }
export interface McpServerCount { server: string; calls: number; }
export interface McpServerSplit { server: string; ok: number; errors: number; }

export interface McpAnalytics {
  /** total calls in the window */
  total: number;
  /** failed calls (outcome === "fail") */
  errors: number;
  /** successful calls (ok + warn) */
  ok: number;
  /** ok / total, 0–100; 100 when there are no calls */
  successRate: number;
  /** distinct servers with at least one call in the window */
  activeServers: number;
  /** active servers whose error rate is at/below the healthy threshold */
  healthyServers: number;
  /** per-day ok (ok + warn) vs error counts, oldest→newest, length === days */
  daily: McpDayBucket[];
  /** calls per server, descending */
  perServer: McpServerCount[];
  /** ok (ok + warn) vs error per server, descending by total */
  perServerSplit: McpServerSplit[];
  /** recent calls, newest first (for the call-results log) */
  recent: McpCall[];
}

const DAY_MS = 86_400_000;
/** A server is "healthy" when at most this fraction of its calls failed. */
const HEALTHY_ERR_RATE = 0.1;

/**
 * Aggregate MCP calls into the analytics the MCP Analytics tab renders. Only calls within the
 * last `days` (relative to `now`) are counted. `daily` always has exactly `days` buckets
 * (zero-filled), oldest→newest, so the chart has a stable x-axis. `recent` is the newest
 * `recentLimit` calls for the call-results log.
 */
export function aggregateMcpTelemetry(calls: McpCall[], now: Date, days = 14, recentLimit = 100): McpAnalytics {
  const end = now.getTime();
  const start = end - days * DAY_MS;
  const inWindow = calls.filter((c) => c.ts >= start && c.ts <= end);

  const daily: McpDayBucket[] = [];
  const idxByDay = new Map<string, number>();
  for (let i = days - 1; i >= 0; i--) {
    const key = dayKey(end - i * DAY_MS);
    idxByDay.set(key, daily.length);
    daily.push({ day: key, ok: 0, error: 0 });
  }

  let errors = 0;
  const perServerMap = new Map<string, McpServerCount>();
  const perSplitMap = new Map<string, McpServerSplit>();

  for (const c of inWindow) {
    const isErr = c.outcome === "fail";
    if (isErr) errors++;

    const bucket = idxByDay.get(dayKey(c.ts));
    if (bucket != null) {
      if (isErr) daily[bucket].error++;
      else daily[bucket].ok++;
    }

    const sc = perServerMap.get(c.server) ?? { server: c.server, calls: 0 };
    sc.calls++;
    perServerMap.set(c.server, sc);

    const sp = perSplitMap.get(c.server) ?? { server: c.server, ok: 0, errors: 0 };
    if (isErr) sp.errors++; else sp.ok++;
    perSplitMap.set(c.server, sp);
  }

  const perServer = [...perServerMap.values()].sort((a, b) => b.calls - a.calls);
  const perServerSplit = [...perSplitMap.values()].sort((a, b) => (b.ok + b.errors) - (a.ok + a.errors));
  const healthyServers = perServerSplit.filter((s) => {
    const t = s.ok + s.errors;
    return t > 0 && s.errors / t <= HEALTHY_ERR_RATE;
  }).length;
  const total = inWindow.length;
  const ok = total - errors;
  // Recent calls newest-first: the log is read newest-first, but guard for any order.
  const recent = [...inWindow].sort((a, b) => b.ts - a.ts).slice(0, recentLimit);

  return {
    total,
    errors,
    ok,
    successRate: total > 0 ? Math.round((ok / total) * 100) : 100,
    activeServers: perServerMap.size,
    healthyServers,
    daily,
    perServer,
    perServerSplit,
    recent,
  };
}

runtime.features/mcp/lib/mcpVersioning.ts:
// Version/install status of a downloadable (first-party) MCP server (#885). Pure (no React/Tauri)
// so the status type + its derivation are unit-testable and shared by the screen's install hook.

import { catalogLink } from "./mcpInstall";
import type { McpServer } from "./mcpServers";

/** Install/version status of a downloadable MCP server (#885). */
export type McpStat =
  | "checking" | "current" | "outdated" | "needs-build"
  | "downloading" | "building" | "updating" | "error";

/** The shape `mcp_check_update` resolves to: whether the clone exists, is built, and is behind. */
export interface McpCheckResult {
  downloaded: boolean;
  built: boolean;
  updateAvailable: boolean;
}

/** Map a backend `mcp_check_update` result to the row status shown on an installed server (#885):
 *  not cloned (or not yet built) → needs-build, behind its remote → outdated, else current. */
export function deriveCheckStat(r: McpCheckResult): McpStat {
  return !r.downloaded ? "needs-build" : r.updateAvailable ? "outdated" : !r.built ? "needs-build" : "current";
}

/** The names of installed servers that are downloadable (first-party, install-from-source) — the
 *  ones the version check runs against. */
export function installedDownloadableNames(servers: McpServer[]): string[] {
  return servers.filter(e => catalogLink(e.name)).map(e => e.name);
}

