import { useEffect, useMemo, useState } from "react";
import { ColorSwatch } from "@/shared/ui/controls/ColorSwatch";
import { logsTail } from "@/shared/lib/core/logsBridge";
import { useAppStore } from "@/store";
import { parseMcpLog, aggregateMcpTelemetry, type McpAnalytics, type McpCall } from "./lib/mcpTelemetry";
import { StatCard, StackedDayBars, TelemetryPanel, ItemBars, SplitBar } from "@/shared/ui/charts";
import { Grid } from "@/shared/ui/layout/Grid";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Skeleton, SkeletonChart } from "@/shared/ui/feedback/Skeleton";
import { CardEmpty } from "@/shared/ui/feedback/CardStates";
import { fmtClock } from "@/shared/lib/core/format";

// MCP Analytics tab (#879) — KPI cards + 3 charts + a call-results log over the MCP tool-call
// telemetry (~/.base-studio-code/mcp.log via `bsc logs tail mcp` + mcpTelemetry.ts). The over-time chart +
// KPI cards are shared primitives (StackedDayBars / StatCard); the per-server/results charts stay local.
// Transport per server is joined from the live extensions store; the rest comes from the parsed log.
// Empty until the bsc-mcp hook pair emits calls (PR 2) — renders a clean zero state.

const DAYS = 14;

const fmtMs = (ms: number) => (ms >= 1000 ? `${(ms / 1000).toFixed(1)}s` : `${Math.round(ms)}ms`);

/** A stack of shimmer bar-rows (label line + track) — a loading placeholder for a per-server bar card (#2246). */
function SkeletonBars({ rows = 4 }: { rows?: number }) {
  return (
    <Stack gap={14}>
      {Array.from({ length: rows }).map((_, i) => (
        <Box key={i}>
          <Skeleton h={11} w="40%" style={{ marginBottom: 6 }} />
          <Skeleton h={8} radius={4} />
        </Box>
      ))}
    </Stack>
  );
}

export function McpAnalyticsTab() {
  // Transport per server, joined by name from the live store (the log carries only the name).
  // Derived via useMemo so the selector returns a stable object (a fresh map each render would
  // trip useSyncExternalStore's snapshot-stability check → infinite loop).
  const mcpServers = useAppStore((s) => s.mcpServers);
  const transportByServer = useMemo(() => {
    const m: Record<string, string> = {};
    for (const e of mcpServers) m[e.name] = e.transport ?? "stdio";
    return m;
  }, [mcpServers]);

  const [an, setAn] = useState<McpAnalytics | null>(null);
  const [filter, setFilter] = useState<"all" | "ok" | "errors">("all");
  useEffect(() => {
    let cancelled = false;
    logsTail("mcp", 8000)
      .then((lines) => { if (!cancelled) setAn(aggregateMcpTelemetry(parseMcpLog((lines ?? []).join("\n")), new Date(), DAYS)); });
    return () => { cancelled = true; };
  }, []);

  const recent = useMemo(() => {
    const list = an?.recent ?? [];
    if (filter === "errors") return list.filter((c) => c.outcome === "fail");
    if (filter === "ok") return list.filter((c) => c.outcome !== "fail");
    return list;
  }, [an, filter]);

  // The card LAYOUT always renders (#2246) — each async card body shows a loading skeleton (while the
  // log query is in flight) or a compact empty state (no telemetry yet), rather than a page-wide
  // "Loading…" line that hides the whole surface.
  const loading = an === null;
  const maxServerCalls = an ? Math.max(1, ...an.perServer.map((s) => s.calls)) : 1;
  const errCount = an ? an.recent.filter((c) => c.outcome === "fail").length : 0;

  return (
    <Box style={{ padding: "4px 0 12px" }}>
      {/* KPI cards */}
      <Grid cols={4} gap={8} style={{ marginBottom: 12 }}>
        <StatCard k="Total calls" v={an?.total ?? 0} sub={`last ${DAYS} days`} loading={loading} />
        <StatCard k="Errors" v={an?.errors ?? 0} sub="failed calls" tone="danger" loading={loading} />
        <StatCard k="Success rate" v={`${an?.successRate ?? 0}%`} sub={`${an?.ok ?? 0} ok`} tone="success" loading={loading} />
        <StatCard k="Active servers" v={an?.activeServers ?? 0} sub={`${an?.healthyServers ?? 0} healthy`} loading={loading} />
      </Grid>

      {/* Calls over time */}
      {loading ? (
        <Box style={{ marginBottom: 10 }}>
          <TelemetryPanel title="Calls over time" hint="daily tool calls · ok vs error"><SkeletonChart height={160} /></TelemetryPanel>
        </Box>
      ) : an.total === 0 ? (
        <Box style={{ marginBottom: 10 }}>
          <TelemetryPanel title="Calls over time" hint="daily tool calls · ok vs error">
            <CardEmpty title="No calls yet" hint="Daily tool-call volume appears once agents use these servers." />
          </TelemetryPanel>
        </Box>
      ) : (
        <StackedDayBars
          data={an.daily.map((d) => ({ day: d.day, upper: d.ok, lower: d.error }))}
          title="Calls over time" subtitle="daily tool calls · ok vs error"
          upperLabel="ok" lowerLabel="error"
        />
      )}

      <Grid cols={2} gap={10} style={{ marginBottom: 10 }}>
        {/* Calls per server */}
        <TelemetryPanel
          title="Calls per server"
          right={<>
            <Row inline gap={5} className="mono" style={{ fontSize: 9.5, color: "var(--fg-muted)" }}><ColorSwatch color="var(--info)" />http</Row>
            <Row inline gap={5} className="mono" style={{ fontSize: 9.5, color: "var(--fg-muted)" }}><ColorSwatch color="var(--violet, oklch(0.70 0.12 300))" />stdio</Row>
          </>}
        >
          {loading ? <SkeletonBars /> : (
            <ItemBars
              rows={an.perServer.map((s) => {
                const transport = transportByServer[s.server] ?? "stdio";
                return {
                  key: s.server, label: s.server, meta: transport, value: s.calls, fraction: s.calls / maxServerCalls,
                  color: transport === "http" ? "var(--info)" : "var(--violet, oklch(0.70 0.12 300))",
                };
              })}
              empty={<Text as="span" className="hint">No MCP calls recorded yet.</Text>}
            />
          )}
        </TelemetryPanel>

        {/* Success vs errors */}
        <TelemetryPanel title="Success vs errors" hint="per server">
          {loading ? <SkeletonBars rows={3} /> : (
            <Stack gap={14}>
              {an.perServerSplit.length === 0 && <Text as="span" className="hint">No calls yet.</Text>}
              {an.perServerSplit.map((p) => (
                <SplitBar key={p.server} label={p.server} a={p.ok} b={p.errors} aLabel="ok" bLabel="err" />
              ))}
            </Stack>
          )}
          <Box style={{ marginTop: 14, paddingTop: 12, borderTop: "1px solid var(--border-soft)", fontSize: 10.5, color: "var(--fg-dim)", lineHeight: 1.5 }}>
            Parsed from <Text as="span" mono tone="muted">~/.base-studio-code/mcp.log</Text> via <Text as="span" mono tone="muted">mcpTelemetry.ts</Text> — one line per call (ts · server · tool · outcome · ms).
          </Box>
        </TelemetryPanel>
      </Grid>

      {/* Call results log */}
      <Box pad={[14, 16]} bg="var(--bg-panel)" border="soft" radius={8}>
        <Row align="baseline" gap={10} style={{ marginBottom: 12 }}>
          <Text as="h3" mono size="sm" weight={600} style={{ margin: 0, color: "var(--fg)" }}>Call results</Text>
          <Text as="span" size={10.5} tone="dim">what servers returned to agents</Text>
          <Spacer />
          {errCount > 0 && <Text as="span" mono size={10} tone="danger">{errCount} errors</Text>}
          <Row inline align="stretch" style={{ border: "1px solid var(--border-soft)", borderRadius: 6, overflow: "hidden" }}>
            {(["all", "ok", "errors"] as const).map((f) => (
              // eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled segmented filter (custom bg/color/border container); Button or SegmentedControl would change the rendering
              <button
                key={f}
                onClick={() => setFilter(f)}
                className="mono"
                style={{
                  fontSize: 10, padding: "3px 9px", border: 0, cursor: "pointer",
                  background: filter === f ? "var(--bg-elev2)" : "transparent",
                  color: filter === f ? "var(--fg)" : "var(--fg-dim)",
                }}
              >{f === "all" ? "All" : f === "ok" ? "OK" : "Errors"}</button>
            ))}
          </Row>
        </Row>
        {loading ? (
          <Stack gap={6}>
            {Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} h={22} radius={5} />)}
          </Stack>
        ) : recent.length === 0 ? (
          <Text as="span" className="hint">No calls recorded yet — the MCP call log fills as agents use these servers.</Text>
        ) : (
          <Stack>
            {recent.map((c, i) => <CallRow key={i} c={c} />)}
          </Stack>
        )}
      </Box>
    </Box>
  );
}

function CallRow({ c }: { c: McpCall }) {
  const dot = c.outcome === "fail" ? "var(--danger)" : c.outcome === "warn" ? "var(--accent)" : "var(--success)";
  const label = c.outcome === "fail" ? "fail" : c.outcome === "warn" ? "warn" : "ok";
  return (
    <Row className="mono" gap={10} style={{ padding: "6px 0", borderTop: "1px solid var(--border-soft)", fontSize: 10.5 }}>
      <Box as="span" style={{ color: "var(--fg-dim)", width: 56 }}>{fmtClock(c.ts, { seconds: true })}</Box>
      <Box as="span" style={{ color: "var(--fg)", whiteSpace: "nowrap" }}>{c.server}<Text as="span" tone="muted">.{c.tool}</Text></Box>
      <Box as="span" style={{ flex: 1, color: "var(--fg-dim)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{c.detail && `→ ${c.detail}`}</Box>
      <Text as="span" tone="muted">{c.ms ? fmtMs(c.ms) : "—"}</Text>
      <Row inline justify="end" gap={5} style={{ color: dot, width: 44 }}>
        <Box as="span" bg={dot} radius={99} style={{ width: 6, height: 6}} />{label}
      </Row>
    </Row>
  );
}

runtime.features/mcp/McpGraphHost.tsx:
// The MCP page host (#3656, epic #3604) — renders the MCP (servers) workspace FROM THE GRAPH. The page + its
// Analytics tab are sourced from the components graph (the authored `mcppage` node + the `mcp-analytics`
// sibling, seeded from `data/components/app/**`), not bundled files. It registers the mcp feature's injected
// platform surface (the install/catalog/telemetry logic + the ./shared helpers), then mounts `mcppage`
// through the runtime loader. Mirrors the fleet/automations/security/github/skills hosts.
//
// `pageOverride` (a torn-off single tab, DetachedWindow) forwards to the graph component as a prop —
// GraphComponent spreads props onto the loaded component, and the graph `McpWorkspace` reads it.
//
// The CSS still ships as a normal bundled import here (the loader can't resolve a CSS side-effect import, so
// it was stripped from the graph source): the host owns the stylesheet the graph page's classes need.
import { GraphComponent } from "@/shared/lib/runtime/GraphComponent";
import { GraphPageFallback } from "@/shared/lib/runtime/GraphPageFallback";
import { registerMcpPlatform } from "./graphPlatform";
import "./mcp.css";

// Register at module load — before the workspace ever renders — so the injected modules are in the registry
// when the graph page's compiled `require()` runs. Idempotent.
registerMcpPlatform();

export function McpGraphHost({ pageOverride }: { pageOverride?: string } = {}) {
  // Fallback offers Reload-to-apply / Re-seed (#3648/#3652) when the source isn't in the library yet.
  return (
    <GraphComponent
      id="mcppage"
      props={pageOverride ? { pageOverride } : undefined}
      fallback={<GraphPageFallback page="MCP" icon="⧉" />}
    />
  );
}

runtime.features/mcp/shared.tsx:
// Shared chrome for the MCP servers screen + the Hooks view (#mcp-hooks-split). These two
// features manage independent models (McpServer / Hook) but render identical row/drawer chrome:
// the GitHub-projects fetch, the enable toggle, the scope chips, the project-assignment field,
// and the env-var editor. Kept here so neither feature owns the other's vocabulary.

import { useState, useEffect } from "react";
import { StatusDot } from "@/shared/ui/feedback/StatusDot";
import { IconButton } from "@/shared/ui/controls/IconButton";
import { CardListRow } from "@/shared/ui/data/CardListRow";
import { Chip } from "@/shared/ui/data/Chip";
import { ColorSwatch } from "@/shared/ui/controls/ColorSwatch";
import { Banner } from "@/shared/ui/feedback/Banner";
import { Button } from "@/shared/ui/controls/Button";
import { Field, TextField } from "@/shared/ui/controls/Field";
import { Row } from "@/shared/ui/layout/Row";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { invoke } from "@tauri-apps/api/core";
import type { CatalogItem } from "@/shared/data/mcpCatalog";
import type { GhProjectRef } from "@/shared/lib/github/types";

export type Scope = "global" | "project";

/** A GitHub Project (subset of the GraphQL `projectsV2` node). */
export type GhProject = GhProjectRef;

/** The minimal shape the shared chrome needs from a managed item (server or hook). */
export interface ManagedItem {
  id: string;
  name: string;
  enabled: boolean;
  projects: string[];
  env?: Array<[string, string]>;
}

const PROJECTS_QUERY = `{
  viewer {
    projectsV2(first: 50) {
      nodes { id title number }
    }
  }
}`;

/** The user's GitHub Projects, fetched once when a token exists. No token / empty / failure all
 *  collapse to "global only" — never a crash. */
export function useGhProjects(githubToken: string): GhProject[] {
  const [projects, setProjects] = useState<GhProject[]>([]);
  useEffect(() => {
    if (!githubToken) return;
    let cancelled = false;
    invoke<{ viewer: { projectsV2: { nodes: GhProject[] } } }>("github_graphql", {
      token: githubToken,
      query: PROJECTS_QUERY,
      variables: null,
    })
      .then(data => { if (!cancelled) setProjects(data?.viewer?.projectsV2?.nodes ?? []); })
      .catch(() => { if (!cancelled) setProjects([]); });
    return () => { cancelled = true; };
  }, [githubToken]);
  return projects;
}

/** The enable/disable pill toggle on a row. */
export function ToggleSwitch({ on, onToggle }: { on: boolean; onToggle: () => void }) {
  return (
    <Box
      className={"toggle" + (on ? " on" : "")}
      title={on ? "enabled" : "disabled"}
      onClick={ev => { ev.stopPropagation(); onToggle(); }}
    />
  );
}

/** The scope summary chips on a row: off / global / named-projects. */
export function scopeChips(e: { enabled: boolean; projects: string[] }, projects: GhProject[]) {
  if (!e.enabled) return <Chip style={{ color: "var(--fg-dim)" }}>off</Chip>;
  if (e.projects.length === 0) return <Chip tone="success"><StatusDot style={{ marginRight: 4 }} />global</Chip>;
  const named = e.projects
    .map(pid => projects.find(p => p.id === pid))
    .filter(Boolean) as GhProject[];
  if (named.length === 0) {
    // Scoped to project ids we couldn't resolve (no token / not in the list).
    return <Box as="span" className="ptag muted">{e.projects.length} project{e.projects.length === 1 ? "" : "s"}</Box>;
  }
  return (
    <>
      {named.slice(0, 2).map(p => (
        <Box as="span" key={p.id} className="ptag"><Box as="span" className="pdot" bg="var(--accent-dim)" />{p.title}</Box>
      ))}
      {named.length > 2 && <Box as="span" className="ptag muted">+{named.length - 2}</Box>}
    </>
  );
}

/** The project-assignment drawer field: a global toggle + a per-project multi-select. `[]` projects
 *  = global (every project); otherwise the chosen project ids. */
export function ProjectAssignment({ item, projects, onSet }: {
  item: { projects: string[] };
  projects: GhProject[];
  onSet: (ids: string[]) => void;
}) {
  const isGlobal = item.projects.length === 0;
  const toggleProject = (pid: string) => {
    const next = item.projects.includes(pid)
      ? item.projects.filter(x => x !== pid)
      : [...item.projects, pid];
    onSet(next);
  };
  return (
    <Field label="project assignment">
      <Banner tone="success" style={isGlobal ? undefined : { opacity: 0.6 }} lead={<Box as="span" bg="var(--success)" style={{ width: 7, height: 7, borderRadius: "50%"}} />}>
        <Text weight={600} tone={isGlobal ? "success" : "muted"}>Global (all projects)</Text>
        <Spacer />
        <Box
          className={"toggle" + (isGlobal ? " on" : "")}
          title={isGlobal ? "global" : "scoped to projects"}
          onClick={() => onSet(isGlobal ? (projects[0] ? [projects[0].id] : []) : [])}
        />
      </Banner>

      {!isGlobal && (
        <>
          {projects.length === 0
            ? <Box className="hint" style={{ marginTop: 6 }}>No projects — global only. Connect GitHub in Settings to scope per project.</Box>
            : (
              <Box className="proj-multi" style={{ marginTop: 6 }}>
                {projects.map(p => {
                  const sel = item.projects.includes(p.id);
                  return (
                    <Box key={p.id} className={"pm-row" + (sel ? " on" : "")} onClick={() => toggleProject(p.id)}>
                      <Box className="check">{sel ? "✓" : ""}</Box>
                      <Box>
                        <Text as="div" className="pname">{p.title}</Text>
                        <Text as="div" className="pbranch">#{p.number}</Text>
                      </Box>
                      <Box className="pside"><ColorSwatch color="var(--accent-dim)" size={8} /></Box>
                    </Box>
                  );
                })}
              </Box>
            )}
          {projects.length > 0 && (
            <Row gap={8} style={{ marginTop: 4 }}>
              <Text as="span" className="hint">{item.projects.length} of {projects.length} projects</Text>
              <Spacer />
              <Box as="span" className="hint" style={{ cursor: "pointer", color: "var(--accent-dim)" }} onClick={() => onSet(projects.map(p => p.id))}>select all</Box>
              <Box as="span" className="hint" style={{ cursor: "pointer", color: "var(--accent-dim)" }} onClick={() => onSet([])}>make global</Box>
            </Row>
          )}
        </>
      )}
      <Box className="hint" style={{ marginTop: 6 }}>Global applies to every project; otherwise only the projects you pick.</Box>
    </Field>
  );
}

/** One row in an Installed list. Kind-specific bits (`desc`, the optional `aside` control) are
 *  passed in; the row chrome (health dot, name, tag, scope chips, enable toggle) is shared. */
export function InstalledRow({ name, tagCls, tagLabel, desc, scopeChip, aside, on, selected, onSelect, onToggle }: {
  name: string;
  tagCls: string;
  tagLabel: string;
  desc: React.ReactNode;
  scopeChip: React.ReactNode;
  aside?: React.ReactNode;
  on: boolean;
  selected: boolean;
  onSelect: () => void;
  onToggle: () => void;
}) {
  return (
    <CardListRow
      selected={selected}
      off={!on}
      onClick={onSelect}
      lead={<Box className={"health " + (on ? "" : "off")} />}
      title={name || "Untitled"}
      badge={<Chip tone={tagCls === "green" ? "success" : tagCls === "info" ? "info" : tagCls === "amber" ? "accent" : "neutral"}>{tagLabel}</Chip>}
      subtitle={desc}
      trailing={
        <>
          <Box className="row-stats">
            <Box className="row-chips">{scopeChip}</Box>
            <Box>—</Box>
          </Box>
          {aside}
          <ToggleSwitch on={on} onToggle={onToggle} />
        </>
      }
    />
  );
}

/** One catalog card. The action button (download vs. add) is passed in by the feature. */
export function CatalogCard({ item, action }: { item: CatalogItem; action: React.ReactNode }) {
  return (
    <Box className="cat-card">
      <Box className="cat-head">
        <Box className="cat-icon">{item.icon}</Box>
        <Box style={{ flex: 1, minWidth: 0 }}>
          <Text as="div" className="cat-name">{item.name}</Text>
          <Text as="div" className="cat-by">{item.by}</Text>
        </Box>
      </Box>
      <Text as="div" className="cat-desc">{item.desc}</Text>
      {item.install && <Box className="hint" style={{ marginTop: 6, fontSize: 10 }}>{item.install}</Box>}
      <Box className="cat-foot">
        <Text as="span" className="hint">{item.by.startsWith("@modelcontextprotocol") ? "official MCP" : (item.by === "first-party" || item.link) ? "first-party" : "third-party"}</Text>
        <Box className="spacer" />
        {action}
      </Box>
    </Box>
  );
}

/** The env-var key/value editor drawer field (shared by servers + hooks). */
export function EnvEditor({ env, onChange }: { env: Array<[string, string]>; onChange: (env: Array<[string, string]>) => void }) {
  return (
    <Field label="environment">
      <Box className="kv-list">
        {env.map(([k, v], i) => (
          <Box className="kv-row" key={i}>
            {/* eslint-disable-next-line no-restricted-syntax -- inline kv-row key input (.input.k, part of a key/value/remove row); TextField's .field wrapper would change layout */}
            <input
              className="input k"
              value={k}
              onChange={ev => onChange(env.map((row, j) => j === i ? [ev.target.value, row[1]] : row))}
            />
            {/* eslint-disable-next-line no-restricted-syntax -- inline kv-row value input (part of a key/value/remove row); TextField's .field wrapper would change layout */}
            <input
              className="input"
              value={v}
              onChange={ev => onChange(env.map((row, j) => j === i ? [row[0], ev.target.value] : row))}
            />
            <IconButton aria-label="remove" size="xs" onClick={() => onChange(env.filter((_, j) => j !== i))} />
          </Box>
        ))}
        <Button
          variant="ghost"
          style={{ height: 24, fontSize: 10.5, width: "fit-content" }}
          onClick={() => onChange([...env, ["", ""]])}
        >+ env var</Button>
      </Box>
    </Field>
  );
}

/** The config drawer body, shared by servers + hooks: name + stat block + project assignment +
 *  the feature's own config fields (`children`) + env editor. */
export function DrawerBody({ item, kindLabel, projects, onName, onSetProjects, onSetEnv, children }: {
  item: ManagedItem;
  kindLabel: string;
  projects: GhProject[];
  onName: (name: string) => void;
  onSetProjects: (ids: string[]) => void;
  onSetEnv: (env: Array<[string, string]>) => void;
  children: React.ReactNode;
}) {
  return (
    <>
      <TextField label="name" value={item.name} onChange={onName} />

      <Box className="dr-stat">
        <Text as="div" className="k">status</Text><Text as="div" className="v" style={{ color: item.enabled ? "var(--success)" : "var(--fg-dim)" }}>{item.enabled ? "enabled" : "disabled"}</Text>
        <Text as="div" className="k">kind</Text><Text as="div" className="v">{kindLabel}</Text>
        <Text as="div" className="k">last used</Text><Text as="div" className="v">—</Text>
        <Text as="div" className="k">calls (24h)</Text><Text as="div" className="v">—</Text>
      </Box>

      <ProjectAssignment item={item} projects={projects} onSet={onSetProjects} />
      {children}
      <EnvEditor env={item.env ?? []} onChange={onSetEnv} />
    </>
  );
}

