runtime.features/personas/lib/persona.ts:
// Personas (#2094) — the CRUD-able BEHAVIORAL identity of an agent, split from the ROLE (its
// permission floor, `sessionRoles.ts`). A persona is the named composition the user authors: a start
// prompt + attached skills + a default model, running under a referenced role. Many personas → one
// role (e.g. Reviewer, Juror, Documentor all sit on a read-only floor with very different prompts +
// skills). Pure model (no React/Tauri) so it's unit-testable and the store seeds from it directly.
//
// This is view/CRUD-first (#2094 Part B, relocated to the Planner workspace): the persona is the
// user-facing agent template. Wiring personas into fleet-stream launch + console launch (so picking a
// persona resolves role + prompt + skills + model in one step) is the follow-up phase.
import type { SessionRole } from "@/shared/lib/session/sessionRoles";
import { overlayGlob, overlayRaw } from "@/shared/lib/core/configOverrides";
import { slugify } from "@/shared/lib/core/format";
import workerProtocolMd from "@data/fleet/worker-protocol.md?raw";
import directorProtocolMd from "@data/fleet/director-protocol.md?raw";

export interface Persona {
  /** Stable, opaque id (slug for built-ins, minted for user personas). */
  id: string;
  /** Display name — "Documentor". */
  name: string;
  /** One-line description of the job this persona does. */
  blurb: string;
  /** The permission floor this persona runs under — the ONLY link to the role gate (#219). Many
   *  personas may reference the same role; the role bounds capabilities, the persona shapes behavior. */
  role: SessionRole;
  /** The start prompt / protocol injected at launch (prose). Empty is allowed (falls back to the
   *  role's own kickoff assembly downstream). */
  startPrompt: string;
  /** Attached skill ids (the Skills library, #636) written into the session's .claude/skills/. */
  skills: string[];
  /** The position's charter — what it is accountable for (#2193). One facet of the org abstraction,
   *  orthogonal to skills (capability) and role (permission); optional, so pre-#2193 personas are
   *  unaffected. Feeds the generated start prompt + the Org designer's position inspector. */
  responsibilities?: string[];
  /** Default model id for this persona (empty = the session/global default). */
  model?: string;
  /** This identity is meant to run as a POOL of interchangeable instances (#2199) — a swarm of N agents
   *  doing the same job. In the Org designer, a set of positions on a pooled persona that share the same
   *  external relationships collapses into ONE stacked card (drill in to see the members). Purely a
   *  designer/consolidation hint today; the fleet still launches N real agents. Optional — unset = 1:1. */
  pooled?: boolean;
  /** A packaged persona: seeded from code, restored on refresh. Can be cloned + edited (edits persist
   *  as an overlay) but not deleted; user-authored personas have `builtin` unset. */
  builtin?: boolean;
}

/** A packaged persona definition, as authored under `src-tauri/data/personas/*.json` (#2185). It is a
 *  {@link Persona} plus two load-time-only fields: `order` (display order in the library) and
 *  `protocolFile` (a config-relative markdown path whose prose supplies the start prompt for the two
 *  personas that have a real runtime protocol — worker/director). Both are stripped during assembly. */
interface PersonaDef extends Omit<Persona, "builtin"> {
  /** Display order in the library (ascending); absent sorts as 0. */
  order?: number;
  /** Config-relative markdown file (e.g. "fleet/worker-protocol.md") whose text fills an empty
   *  `startPrompt` — the single source of truth for the worker/director protocol prose. */
  protocolFile?: string;
}

// The built-in personas live as one JSON file per persona under src-tauri/data/personas/ (#2185) —
// the same externalized-config pattern as blueprints/skills/roles (#2027/#2047), so the packaged set
// is editable without a rebuild (config-dir overlay) and rides the export/import config bundle.
const personaModules = import.meta.glob<{ default: PersonaDef }>("@data/personas/*.json", { eager: true });

/** The runtime protocol prose for the personas that reference a `protocolFile`, keyed by that path.
 *  Resolved ONCE from the shared `@data/fleet/*-protocol.md` (imported `?raw`) with the config-dir
 *  overlay applied — so the worker/director personas and the fleet's CLAUDE.local.md draw the exact
 *  same prose from one source, no duplication (the #2027 drift-killer). */
const PROTOCOL_PROSE: Record<string, string> = {
  "fleet/worker-protocol.md": overlayRaw("fleet/worker-protocol.md", workerProtocolMd).trim(),
  "fleet/director-protocol.md": overlayRaw("fleet/director-protocol.md", directorProtocolMd).trim(),
};

/** Assemble the packaged persona library from the per-persona JSON defs: overlay the config-dir copies,
 *  order them, resolve any `protocolFile` prose into an empty start prompt, and stamp `builtin`. */
export function makeBuiltinPersonas(): Persona[] {
  return overlayGlob<PersonaDef>("personas", personaModules)
    .map(([, def]) => def)
    .sort((a, b) => (a.order ?? 0) - (b.order ?? 0))
    .map(({ order: _order, protocolFile, ...p }) => ({
      ...p,
      skills: p.skills ?? [],
      startPrompt: p.startPrompt || (protocolFile ? PROTOCOL_PROSE[protocolFile] ?? "" : ""),
      builtin: true,
    }));
}

/** The packaged personas — one per role, so the tab is populated + honest on day one. `documentor`
 *  (#1555) is the identity for the `documentor` role: read-only on git/GitHub with a DOC_GLOBS write
 *  carve-out, so it reconciles prose docs after a change lands but can never touch code. The
 *  worker/director carry the real fleet protocol prose (resolved from `@data/fleet/*-protocol.md`);
 *  the rest are short seeds. */
export const BUILTIN_PERSONAS: Persona[] = makeBuiltinPersonas();

/** Slugify a persona name into an id fragment (user personas mint `persona-<slug>-<n>` in the store). */
export function personaSlug(name: string): string {
  return slugify(name) || "persona";
}

/** A blank user persona seeded onto a role — the "new persona" template. */
export function blankPersona(id: string, role: SessionRole = "reviewer"): Persona {
  return { id, name: "New persona", blurb: "", role, startPrompt: "", skills: [] };
}

/** Keep only the keys of a persisted persona that carry a real value — so a copy seeded by an OLDER app
 *  (which never wrote a newly-packaged field like `pooled`) doesn't MASK the built-in's value for it. An
 *  absent field comes across as `undefined`; without this, `{...base, ...saved}` would overwrite
 *  `base.pooled` with that `undefined`. Real values (incl. `false`/`""`) are kept, so genuine user edits
 *  still win. */
function definedFields(p: Persona): Partial<Persona> {
  return Object.fromEntries(Object.entries(p).filter(([, v]) => v !== undefined)) as Partial<Persona>;
}

/** Merge the packaged built-ins with the persisted set: every built-in is present (re-seeded if the
 *  persisted copy dropped it), user edits to a built-in are preserved, and user-authored personas are
 *  kept. Keyed by id; built-in identity is restored so a stale persisted `builtin:false` can't turn a
 *  packaged persona into a deletable one. */
export function reconcilePersonas(persisted: Persona[]): Persona[] {
  const byId = new Map(persisted.map((p) => [p.id, p]));
  const out: Persona[] = BUILTIN_PERSONAS.map((base) => {
    const saved = byId.get(base.id);
    byId.delete(base.id);
    if (!saved) return base;
    // Keep user edits (name/blurb/prompt/skills/model) but force builtin identity + role-reference.
    // `definedFields` means a field the persisted copy never had (a newly-packaged facet like `pooled`)
    // inherits the built-in rather than being masked by an absent-value `undefined`.
    // An EMPTY saved `startPrompt` also inherits the packaged prose rather than clobbering it — the
    // upgrade path: a built-in seeded empty by an older app (worker/director) picks up its newly-wired
    // protocol prose, and since an empty prompt already falls back to the role kickoff downstream,
    // "clearing" a built-in's prompt was never meaningful anyway.
    return {
      ...base, ...definedFields(saved), id: base.id, builtin: true,
      startPrompt: saved.startPrompt?.trim() ? saved.startPrompt : base.startPrompt,
    };
  });
  // Whatever remains is user-authored (never builtin).
  for (const p of byId.values()) out.push({ ...p, builtin: false });
  return out;
}

runtime.features/personas/lib/personaBridge.ts:
// The frontend ↔ persona store bridge (#2094). The desktop Personas library and every live console
// session + the planner share ONE global store (`~/.base-studio-code/personas/<id>.json`), reached
// here — and from a session's own shell — through the SAME `bsc persona …` CLI, over the generic `bsc`
// bridge (#2114). Personas are GLOBAL (no project key) so every call passes `null` as the projectKey.
// This is the only place the personas feature touches Tauri, so the pure model in `persona.ts` stays
// React/Tauri-free.
//
// Source-of-truth: the persona store. The Zustand slice is a write-through cache — `loadPersonas`
// hydrates it on boot (then `reconcilePersonas` re-seeds the packaged built-ins), and each library
// mutation pushes through here. Written verbatim: the store never imposes a schema, so a persona
// round-trips byte-for-byte.
import { bsc, bscRun, bscWrite } from "@/shared/lib/core/bsc";
import type { Persona } from "./persona";

/**
 * Load every persona from the store via `bsc persona list --full`. Returns `null` when the bridge is
 * unreachable (no Tauri host — tests, the web shell, or an old binary) so the caller keeps its seeded
 * in-memory built-ins rather than blanking the library. NOT `bscJson` (its degrade-to-fallback would
 * return an empty array, which would then blank the seeded set).
 */
export async function loadPersonas(): Promise<Persona[] | null> {
  try {
    const out = await bsc(null, ["persona", "list", "--full"]);
    const rows = JSON.parse(out.trim() || "[]") as Partial<Persona>[];
    // Defensive: keep only well-formed rows (id + name + role), defaulting the rest so an odd file
    // never crashes hydration.
    return (rows ?? [])
      .filter((p): p is Persona => typeof p.id === "string" && !!p.id)
      .map((p) => ({
        id: p.id, name: p.name ?? "Untitled", blurb: p.blurb ?? "",
        role: p.role ?? "reviewer", startPrompt: p.startPrompt ?? "", skills: p.skills ?? [],
        responsibilities: p.responsibilities, model: p.model, pooled: p.pooled, builtin: p.builtin,
      }));
  } catch {
    return null;
  }
}

/** Write-through a persona upsert (`bsc persona set` reads the JSON on stdin). Fire-and-forget; never
 *  throws, so an old bundled `bsc` without the `persona` subcommand degrades to store-only silently. */
export async function pushPersona(persona: Persona): Promise<void> {
  try { await bscWrite(null, ["persona", "set"], persona); } catch { /* store unreachable — cache-only */ }
}

/** Write-through a persona removal (`bsc persona remove <id>`). Never throws (see {@link pushPersona}). */
export async function dropPersona(id: string): Promise<void> {
  try { await bscRun(null, ["persona", "remove", id]); } catch { /* store unreachable — cache-only */ }
}

runtime.features/personas/PersonaEditor.tsx:
// PersonaEditor (#2199) — the shared editor for one persona's facets (name · blurb · role+tiers ·
// responsibilities · start prompt · model · skills), extracted from PersonasPanel so BOTH the Personas
// tab and the Org designer's position inspector drive the same fields + the same `updatePersona`. It
// edits the SHARED persona identity (a persona used by N positions changes everywhere) — callers that
// need to surface that show their own "shared · used in N" note. `compact` collapses the long start
// prompt (for the narrow Org inspector).
import { useState } from "react";
import { useAppStore } from "@/store";
import { ROLE_DEFAULTS, type SessionRole } from "@/shared/lib/session/sessionRoles";
import { MODEL_IDS } from "@/app/console/lib/models";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { SectionLabel } from "@/shared/ui/layout/SectionLabel";
import { Button } from "@/shared/ui/controls/Button";
import { IconButton } from "@/shared/ui/controls/IconButton";
import { TextField, TextArea, SelectField } from "@/shared/ui/controls/Field";
import { Checkbox } from "@/shared/ui/controls/Checkbox";
import { RoleTierChips } from "@/shared/ui/data/RoleTierChips";
import type { Persona } from "./lib/persona";

const ROLES = Object.keys(ROLE_DEFAULTS) as SessionRole[];

export function PersonaEditor({ persona, compact = false }: { persona: Persona; compact?: boolean }) {
  const skills = useAppStore((s) => s.skills);
  const updatePersona = useAppStore((s) => s.updatePersona);
  const [showPrompt, setShowPrompt] = useState(!compact);

  const resp = persona.responsibilities ?? [];
  const setResp = (next: string[]) => updatePersona(persona.id, { responsibilities: next });
  const toggleSkill = (skillId: string) => {
    const has = persona.skills.includes(skillId);
    updatePersona(persona.id, { skills: has ? persona.skills.filter((s) => s !== skillId) : [...persona.skills, skillId] });
  };

  return (
    <Stack gap={16}>
      <TextField label="Name" value={persona.name} onChange={(v) => updatePersona(persona.id, { name: v })} />
      <TextField label="What it does" value={persona.blurb} onChange={(v) => updatePersona(persona.id, { blurb: v })} placeholder="One line — the job this persona does" />

      <Box>
        <SelectField label="Role — the permission floor (edited on Security)" value={persona.role} onChange={(v) => updatePersona(persona.id, { role: v as SessionRole })}>
          {ROLES.map((r) => <option key={r} value={r}>{r}</option>)}
        </SelectField>
        <Box style={{ marginTop: 6 }}><RoleTierChips role={persona.role} /></Box>
      </Box>

      {/* responsibilities — an editable charter list */}
      <Box>
        <SectionLabel size={9.5} style={{ marginBottom: 6 }} right={<Button variant="ghost" onClick={() => setResp([...resp, ""])}>+ add</Button>}>
          responsibilities · {resp.length}
        </SectionLabel>
        <Stack gap={5}>
          {resp.map((r, i) => (
            <Row key={i} gap={6} align="center">
              <TextField value={r} onChange={(v) => setResp(resp.map((x, j) => (j === i ? v : x)))} placeholder="What this persona is accountable for" style={{ flex: 1 }} />
              <IconButton aria-label="remove responsibility" onClick={() => setResp(resp.filter((_, j) => j !== i))}>×</IconButton>
            </Row>
          ))}
        </Stack>
      </Box>

      {/* start prompt — collapsible in compact mode */}
      <Box>
        {compact && (
          <SectionLabel size={9.5} style={{ marginBottom: 6 }} right={<Button variant="ghost" onClick={() => setShowPrompt((v) => !v)}>{showPrompt ? "hide" : "edit"}</Button>}>
            start prompt
          </SectionLabel>
        )}
        {showPrompt && (
          <TextArea
            label={compact ? undefined : "Start prompt"}
            value={persona.startPrompt}
            onChange={(v) => updatePersona(persona.id, { startPrompt: v })}
            placeholder="The protocol/prose injected at launch. Empty falls back to the role's own kickoff."
            style={{ width: "100%", minHeight: compact ? 110 : 150, resize: "vertical", fontFamily: "var(--mono)", fontSize: 12, lineHeight: 1.55 }}
          />
        )}
      </Box>

      <SelectField label="Default model" value={persona.model ?? ""} onChange={(v) => updatePersona(persona.id, { model: v || undefined })}>
        <option value="">session default</option>
        {MODEL_IDS.map((id) => <option key={id} value={id}>{id}</option>)}
        {persona.model && !(MODEL_IDS as string[]).includes(persona.model) && <option value={persona.model}>{persona.model} (custom)</option>}
      </SelectField>

      {/* pooled — a swarm of interchangeable instances; collapses to one stacked card in the Org designer */}
      <Row gap={9} align="start" onClick={() => updatePersona(persona.id, { pooled: !persona.pooled })} style={{ cursor: "pointer" }}>
        <Box style={{ marginTop: 1 }}><Checkbox checked={!!persona.pooled} aria-label="pooled persona" /></Box>
        <Box style={{ minWidth: 0 }}>
          <Text as="div" size={12.5} weight={500}>Pooled — a swarm of interchangeable instances</Text>
          <Text as="div" size={10.5} tone="dim" style={{ marginTop: 2 }}>Identical instances of this persona collapse into one stacked card in the Org designer; drill in to see the pool.</Text>
        </Box>
      </Row>

      <Box>
        <SectionLabel size={9.5} style={{ marginBottom: 6 }}>attached skills · {persona.skills.length}</SectionLabel>
        {skills.length === 0 ? (
          <Text as="div" size={11} tone="dim">No skills in the library yet — author them on the Skills page.</Text>
        ) : (
          <Row gap={6} wrap>
            {skills.map((sk) => {
              const on = persona.skills.includes(sk.id);
              return (
                <Box as="button" key={sk.id} onClick={() => toggleSkill(sk.id)} className="mono"
                  style={{ cursor: "pointer", padding: "2px 9px", borderRadius: 99, fontSize: 10.5,
                    color: on ? "var(--accent)" : "var(--fg-muted)",
                    border: "1px solid " + (on ? "var(--accent)" : "var(--border)"),
                    background: on ? "color-mix(in oklch, var(--accent), transparent 88%)" : "transparent" }}>
                  {on ? "✓ " : ""}{sk.name}
                </Box>
              );
            })}
          </Row>
        )}
      </Box>
    </Stack>
  );
}

