// PersonaSummary (#2186) — the read-only identity card for the persona a stream launches as. The
// Streams pane lets you PICK a persona (the persona picker) but never showed WHAT you picked:
// a persona's blurb, default model, attached skills, and start prompt were invisible behind the
// dropdown label. This surfaces that identity so you can see exactly what the agent will BE before
// launch. Presentational + read-only — editing a persona still happens on the Personas tab.
import { useAppStore } from "@/store";
import type { Persona } from "./lib/persona";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { SectionLabel } from "@/shared/ui/layout/SectionLabel";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";
import { Chip } from "@/shared/ui/data/Chip";
import { Code } from "@/shared/ui/data/Code";

export function PersonaSummary({ persona, flat = false }: {
  persona: Persona;
  /** Drop the framed panel wrapper and render just the fields — for composing inside a card that
   *  already supplies the frame (the Streams-pane Persona card, #2189). */
  flat?: boolean;
}) {
  // Resolve attached skill ids → names from the live Skills library; fall back to the raw id when a
  // referenced skill isn't in the library (a stale/planned reference) so nothing silently disappears.
  const skills = useAppStore((s) => s.skills);
  const skillNames = persona.skills.map((id) => skills.find((sk) => sk.id === id)?.name ?? id);
  const body = (
    <Stack gap={8}>
        {persona.blurb && (
          <Text as="div" mono size={10} tone="muted" style={{ lineHeight: 1.5 }}>{persona.blurb}</Text>
        )}

        <Row gap={8} wrap align="center">
          <SectionLabel size={9.5}>model</SectionLabel>
          <Text as="span" mono size={9.5} tone={persona.model ? "accent" : "dim"}>
            {persona.model || "session default"}
          </Text>
        </Row>

        <Box>
          <SectionLabel size={9.5} style={{ marginBottom: 5 }}>
            skills · {skillNames.length}
          </SectionLabel>
          {skillNames.length === 0 ? (
            <Text as="div" mono size={9.5} tone="dim">none attached</Text>
          ) : (
            <Row gap={5} wrap>
              {skillNames.map((name, i) => (
                <Chip key={persona.skills[i]}>{name}</Chip>
              ))}
            </Row>
          )}
        </Box>

        <details>
          <summary className="mono" style={{ cursor: "pointer", fontSize: 10, color: "var(--fg-dim)", userSelect: "none" }}>
            Start prompt
          </summary>
          {persona.startPrompt ? (
            <Code style={{ marginTop: 6 }}>{persona.startPrompt}</Code>
          ) : (
            <Text as="div" mono size={9.5} tone="dim" style={{ marginTop: 6, lineHeight: 1.5 }}>
              No start prompt — falls back to the {persona.role} role's own kickoff assembly at launch.
            </Text>
          )}
        </details>
    </Stack>
  );
  if (flat) return body;
  return (
    <Box bg="var(--bg-panel)" radius={5} pad={[9, 10]} style={{ marginTop: 8, border: "1px solid var(--border-soft)" }}>
      {body}
    </Box>
  );
}

runtime.features/personas/store.ts:
// Personas feature store slice (#2094) — the CRUD-able agent-identity library, a WRITE-THROUGH cache
// over the global persona store (`~/.base-studio-code/personas/`, reached via `bsc persona` — see
// personaBridge.ts). The desktop UI, live sessions, and the planner share ONE store. On boot
// `hydratePersonas` loads through the bridge + reconciles the packaged built-ins; every mutation below
// pushes through. The persisted `personas` in app-state is just a fast first-paint cache; hydrate is
// authoritative. Behavior identity only: the ROLE it references (permissions) lives in `sessionRoles.ts`.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import type { SessionRole } from "@/shared/lib/session/sessionRoles";
import type { ModelId } from "@/app/console/lib/models";
import { BUILTIN_PERSONAS, blankPersona, personaSlug, reconcilePersonas, type Persona } from "./lib/persona";
import { loadPersonas, pushPersona, dropPersona } from "./lib/personaBridge";

export interface PersonasSlice {
  /** The persona library — packaged built-ins (reconciled on load) + user-authored. */
  personas: Persona[];
  /** Hydrate the library from the global persona store on boot (#2094): load via the bridge, reconcile
   *  the packaged built-ins, and push any newly-seeded built-in back so the store has it. No-op (keeps
   *  the seeded set) when the bridge is unreachable — tests, the web shell, or an old binary. */
  hydratePersonas: () => Promise<void>;
  /** Create a user persona (optionally on a given role) and return its new id. */
  addPersona: (role?: SessionRole) => string;
  /** Clone any persona (incl. a built-in) into a new editable user persona; returns the new id. */
  clonePersona: (id: string) => string;
  /** Patch a persona's editable fields (name/blurb/prompt/skills/model/role). Built-ins keep their
   *  builtin identity; only user personas can be deleted. */
  updatePersona: (id: string, patch: Partial<Omit<Persona, "id" | "builtin">>) => void;
  /** Remove a USER persona (built-ins are not deletable — no-op). */
  removePersona: (id: string) => void;
  /** Adopt a persona onto a console PANE (#2094 wire-up): stamp its role (the permission floor),
   *  model, and start prompt onto the pane so the pane's NEXT launch runs as that persona, and mark
   *  perms stale so the "relaunch to apply" nudge shows. Skills are attached to the persona but not
   *  applied here yet (the per-session skill-override path is a refinement). No-op for an unknown id. */
  applyPersonaToPane: (paneId: string, personaId: string) => void;
}

/** Mint a fresh, collision-free user-persona id from a name (or a generic seed). */
function mintPersonaId(existing: Persona[], name: string): string {
  const base = `persona-${personaSlug(name)}`;
  if (!existing.some((p) => p.id === base)) return base;
  let n = 2;
  while (existing.some((p) => p.id === `${base}-${n}`)) n++;
  return `${base}-${n}`;
}

export const createPersonasSlice: StateCreator<AppStore, [], [], PersonasSlice> = (set, get) => ({
  personas: BUILTIN_PERSONAS,

  hydratePersonas: async () => {
    const loaded = await loadPersonas();
    if (!loaded) return; // bridge unreachable — keep the seeded built-ins
    const reconciled = reconcilePersonas(loaded);
    set({ personas: reconciled });
    // Converge the store — the source of truth a session/planner reads — with the reconciled library.
    // Push a built-in that the store lacks (first run / a newly-packaged persona) OR whose stored copy
    // drifted from the packaged prose (the #2185 upgrade path: worker/director seeded empty by an older
    // app now carry their real fleet protocol). User edits are preserved by reconcile, so only genuine
    // drift re-pushes.
    const loadedById = new Map(loaded.map((p) => [p.id, p]));
    for (const p of reconciled) {
      const before = loadedById.get(p.id);
      if (!before || (p.builtin && before.startPrompt !== p.startPrompt)) void pushPersona(p);
    }
  },

  addPersona: (role = "reviewer") => {
    const id = mintPersonaId(get().personas, "new persona");
    const persona = blankPersona(id, role);
    set((s) => ({ personas: [...s.personas, persona] }));
    void pushPersona(persona);
    return id;
  },

  clonePersona: (id) => {
    const src = get().personas.find((p) => p.id === id);
    if (!src) return id;
    const name = `${src.name} copy`;
    const newId = mintPersonaId(get().personas, name);
    const clone: Persona = { ...src, id: newId, name, builtin: false };
    set((s) => ({ personas: [...s.personas, clone] }));
    void pushPersona(clone);
    return newId;
  },

  updatePersona: (id, patch) => {
    let updated: Persona | undefined;
    set((s) => ({
      personas: s.personas.map((p) => {
        if (p.id !== id) return p;
        updated = { ...p, ...patch, id: p.id, builtin: p.builtin };
        return updated;
      }),
    }));
    if (updated) void pushPersona(updated);
  },

  removePersona: (id) => {
    const target = get().personas.find((p) => p.id === id);
    if (!target || target.builtin) return; // built-ins are not deletable
    set((s) => ({ personas: s.personas.filter((p) => p.id !== id) }));
    void dropPersona(id);
  },

  applyPersonaToPane: (paneId, personaId) => {
    const persona = get().personas.find((p) => p.id === personaId);
    if (!persona) return;
    set((s) => ({
      paneRoles: { ...s.paneRoles, [paneId]: persona.role },
      paneModels: persona.model ? { ...s.paneModels, [paneId]: persona.model as ModelId } : s.paneModels,
      paneStartupPromptText: persona.startPrompt
        ? { ...s.paneStartupPromptText, [paneId]: persona.startPrompt }
        : s.paneStartupPromptText,
      // Settings.json (the role gate) is read at session start — flag the pane so it shows the
      // "relaunch to apply" nudge, exactly like a profile edit (#799).
      panePermsStale: { ...s.panePermsStale, [paneId]: true },
    }));
  },
});

runtime.features/planner/blueprints/blueprintCat:
// Blueprints-page registry layer (#609) — the editor's palette metadata. The per-stage
// metadata (icon + hue + title + blurb) is single-sourced from the stage's own JSON in
// the prompts data layer (#1603): real stages carry `icon`/`hue` on their SECTION_DEF, and
// the discovery dimensions that double as palette kinds carry them on `discovery.json`'s
// `dimensions`. STAGE_KINDS is DERIVED from those here — no hand-maintained duplicate. Pure;
// the editor reads this for glyphs/hues/blurbs/dispositions; the runtime (#584 gateRule/
// stageStatus) is unchanged.

import { STAGE_DEFS } from "../stages/blueprints";

// ── hue helpers (oklch accents; share L/C, vary hue) ──────────────────────────
export const hue = (h: number): string => `oklch(0.74 0.11 ${h})`;
export const tint = (h: number, a: number): string => `oklch(0.74 0.11 ${h} / ${a})`;

// ── stage kinds: the palette of stages a blueprint can contain ────────────────
// `glyph` is the Material/Lucide icon name (for the editor `<Ic>`); `h` is the accent hue.
interface StageKindMeta { title: string; glyph: string; h: number; blurb: string }

/** Built at load from the stage JSON data layer: every real stage (a SECTION_DEF with an
 *  `icon`/`hue`) + every discovery dimension that doubles as a palette kind (an enriched
 *  `discovery.json` dimension). A stage's title/blurb come from its `name`/`blurb`, so the
 *  palette stays consistent with the stage bar (#1603 reconciled the former divergences). */
function buildStageKinds(): Record<string, StageKindMeta> {
  const out: Record<string, StageKindMeta> = {};
  for (const [key, def] of Object.entries(STAGE_DEFS)) {
    if (def.icon && typeof def.hue === "number") {
      out[key] = { title: def.name, glyph: def.icon, h: def.hue, blurb: def.blurb };
    }
  }
  for (const dim of STAGE_DEFS.discovery?.dimensions ?? []) {
    if (dim.icon && typeof dim.hue === "number") {
      out[dim.key] = { title: dim.title, glyph: dim.icon, h: dim.hue, blurb: dim.blurb ?? "" };
    }
  }
  return out;
}

export const STAGE_KINDS: Record<string, StageKindMeta> = buildStageKinds();

export function stageKind(key: string): StageKindMeta {
  return STAGE_KINDS[key] ?? { title: key, glyph: "category", h: 250, blurb: "" };
}

/** The kinds offered in the editor's "add stage" palette — a CURATED subset of {@link STAGE_KINDS},
 *  NOT every entry. The map also carries icon/metadata for stages that arrive via blueprints or
 *  STAGE_DEFS but aren't hand-addable (the data-platform pipeline stages and the lifecycle stages
 *  seeded by their category's built-in), so an imported blueprint resolves a real icon for every
 *  stage without those flooding the palette. */
export const STAGE_KIND_KEYS = [
  "discovery", "deployment", "users", "ui", "stack", "architecture", "schema", "api",
  "streams", "automations", "skills", "security",
  "observability", "infra", "cicd", "docs",
];

// ── output dispositions: what happens to a stage's artifact ───────────────────
interface DispositionMeta { title: string; glyph: string; h: number; desc: string }

export const DISPOSITIONS: Record<string, DispositionMeta> = {
  "plan-file":  { title: "Plan file",       glyph: "description", h: 70,  desc: "Written to the plan directory." },
  issues:       { title: "GitHub issues",   glyph: "task_alt",    h: 230, desc: "Published as tracked issues." },
  milestones:   { title: "Milestones",      glyph: "flag",        h: 295, desc: "Synced to repo milestones." },
  "skill-index":{ title: "Skill index",     glyph: "extension",   h: 70,  desc: "Upserted into Skills library." },
  knowledge:    { title: "Knowledge store", glyph: "psychology",  h: 195, desc: "Injected into agent prompts." },
  scratch:      { title: "Scratch",         glyph: "edit_note",   h: 250, desc: "Working note — not published." },
};
export const DISPOSITION_KEYS = Object.keys(DISPOSITIONS);

/** Default disposition for a stage kind. */
export function defaultDisposition(key: string): string {
  if (key === "streams") return "issues";
  if (key === "skills") return "skill-index";
  if (key === "discovery") return "knowledge";
  return "plan-file";
}

// ── import source (#923) ──
// The import screen pulls real blueprint gists from a source GitHub account; the mock community
// catalog (+ its preview/fork flow) was removed. Configurable sources land later (#598). For now
// the default source is the maintainer's account.
export const DEFAULT_GIST_SOURCE = "kevinthelago";

/** Whether an imported blueprint is OUT OF DATE with its upstream gist (#955): the gist's current
 *  `updated_at` is strictly newer than the one recorded locally at import/sync. Both are GitHub
 *  `updated_at` timestamps. Unknown on either side ⇒ can't tell ⇒ not stale (treat as current).
 *  Drives whether the import page renders an "Update" button instead of "✓ Imported". */
export function gistUpdateAvailable(currentUpdatedAt?: string, importedUpdatedAt?: string): boolean {
  if (!currentUpdatedAt || !importedUpdatedAt) return false;
  const cur = new Date(currentUpdatedAt).getTime();
  const imp = new Date(importedUpdatedAt).getTime();
  return isFinite(cur) && isFinite(imp) && cur > imp;
}

