// UI-kit pins (#2465) — the blueprint↔kit-store link. A blueprint REFERENCES a UI kit as a
// lockfile entry (`Blueprint.uiKit = { id, version, hash, source? }`, exact pins only) against the
// GLOBAL versioned kit store (`~/.base-studio-code/kits/<id>/<version>/`, the Rust `bsc ui release`
// CLI), so one copy serves every blueprint that pins it and the same kit is never downloaded twice.
//
//  · PACKAGED_UI_KIT_PIN — the packaged `bsc/react-ui` kit's pin (id/version/hash read from the
//    generated `@data/ui/react-ui-kit.meta.json` sidecar). Default-pinned onto every NEW blueprint
//    (`addBlueprint`); it resolves against the store's embedded fallback, so it needs no fetch.
//  · resolveUiKitPin — the resolve flow on blueprint open/import: local store lookup → fetch the
//    typed gist ONLY when `id@version` is missing → verify sha256 BEFORE the store write (a
//    mismatch is rejected loudly and nothing is stored). Never re-fetches an existing id@version.
//  · importKitByGistUrl — the authoring picker's import path: fetch a `component-kit` gist, derive
//    its store identity, add it to the store (trust-on-first-import; the returned pin then locks
//    the exact bytes for everyone downstream).
//
// Pure of React; store access goes through the generic `bsc` bridge (#2114), the same surface a
// live session reaches with `bsc ui release …` from its own shell.

import packagedKitMeta from "@data/ui/react-ui-kit.meta.json";
import { bsc, bscJson } from "@/shared/lib/core/bsc";
import { sha256Hex } from "@/shared/lib/core/sha256";
import { log } from "@/shared/lib/core/log";
import { fetchGistManifestText } from "@/features/planner/lib/gist/gist";
import { parseManifest } from "@/features/planner/lib/gist/manifest";
import type { Blueprint, BlueprintUiKit } from "../stages/blueprints";

/** A kit-store entry's manifest, as `bsc ui release list|get|add` emit it. */
export interface KitStoreManifest {
  id: string;
  version: string;
  sha256: string;
  kind: "component-kit" | "design-files";
  /** The typed-gist URL it was fetched from, or `"packaged"` for the embedded default. */
  source?: string;
}

/** The packaged default kit's pin — a FRESH object per call (pins live inside blueprint JSON, so
 *  handing out one shared instance would alias state across blueprints). */
export function packagedUiKitPin(): BlueprintUiKit {
  return { id: packagedKitMeta.id, version: packagedKitMeta.version, hash: packagedKitMeta.sha256 };
}

/** `id@version` — the store ref a pin resolves as. */
export function kitRef(pin: Pick<BlueprintUiKit, "id" | "version">): string {
  return `${pin.id}@${pin.version}`;
}

/** Every kit in the local store (incl. the packaged default). Empty when the bridge is absent. */
export async function listStoreKits(): Promise<KitStoreManifest[]> {
  return bscJson<KitStoreManifest[]>(null, ["ui", "release", "list"], []);
}

/** One store entry's manifest, or null when `id@version` isn't in the store. */
export async function getStoreKit(pin: Pick<BlueprintUiKit, "id" | "version">): Promise<KitStoreManifest | null> {
  return bscJson<KitStoreManifest | null>(null, ["ui", "release", "get", kitRef(pin)], null);
}

export type UiKitResolution =
  /** `cached` — the id@version was already in the store (zero downloads). */
  | { ok: true; cached: boolean }
  | { ok: false; error: string };

/**
 * Resolve a blueprint's UI-kit pin against the local store (#2465): store hit ⇒ done (an existing
 * `id@version` is NEVER re-fetched — immutable versions make the local copy valid forever); miss ⇒
 * fetch the typed gist at `pin.source`, verify its sha256 against `pin.hash` BEFORE anything is
 * written, and only then add it to the store. A hash mismatch (or a missing source) is a loud
 * `{ ok: false }` and the store is untouched. The `--sha256` handed to `bsc ui release add` makes the
 * Rust store re-verify, so the no-write-on-mismatch guarantee holds even if this caller is wrong.
 */
export async function resolveUiKitPin(pin: BlueprintUiKit, token = ""): Promise<UiKitResolution> {
  if (await getStoreKit(pin)) return { ok: true, cached: true };
  if (!pin.source) {
    return { ok: false, error: `UI kit ${kitRef(pin)} is not in the local kit store and the pin has no source to fetch it from` };
  }
  const raw = await fetchGistManifestText(pin.source, token);
  if (!raw.ok) return raw;
  const hash = await sha256Hex(raw.text);
  if (hash !== pin.hash.toLowerCase()) {
    return {
      ok: false,
      error: `UI kit ${kitRef(pin)} REJECTED: fetched content hashes to ${hash} but the pin expects ${pin.hash} — refusing to store it`,
    };
  }
  try {
    await bsc(
      null,
      ["ui", "release", "add", pin.id, pin.version, "--kind", "component-kit", "--sha256", pin.hash, "--source", pin.source],
      raw.text,
    );
  } catch (e) {
    return { ok: false, error: `UI kit ${kitRef(pin)} could not be stored: ${String(e)}` };
  }
  return { ok: true, cached: false };
}

/**
 * Fire-and-forget resolve for a blueprint being OPENED or IMPORTED — the store-slice wire point.
 * No pin ⇒ no-op (blueprints without one are unaffected); a failure is logged loudly (the
 * authoring picker additionally surfaces it inline).
 */
export function resolveBlueprintUiKit(bp: Pick<Blueprint, "name" | "uiKit"> | undefined, token = ""): void {
  const pin = bp?.uiKit;
  if (!pin) return;
  void resolveUiKitPin(pin, token).then(
    (res) => {
      if (!res.ok) log.error(`blueprint "${bp?.name ?? "?"}": ${res.error}`);
    },
    // Fire-and-forget: an unexpected throw must land in the log, never as an unhandled rejection (#2515).
    (e) => log.error(`blueprint "${bp?.name ?? "?"}": UI-kit resolve failed: ${String(e)}`),
  );
}

/** The store-identity block a published kit gist carries in its payload (`payload.store`). */
export interface KitStoreIdentity {
  id: string;
  version: string;
}

const STORE_ID_RE = /^[a-z0-9][a-z0-9-]*\/[a-z0-9][a-z0-9-]*$/;
const slug = (s: string): string =>
  s.toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-+|-+$/g, "") || "kit";

/** Derive a fetched kit gist's store identity: the stamped `payload.store` when present + valid
 *  (what `publishKitToGist` writes since #2465), else `<gist-owner>/<manifest-id>` slugs with the
 *  envelope's own version — so pre-#2465 kit gists stay importable. Exported for tests. */
export function deriveKitIdentity(
  manifest: { id?: unknown; version?: unknown; payload?: unknown },
  owner?: string,
): KitStoreIdentity {
  const store = (manifest.payload as { store?: { id?: unknown; version?: unknown } } | undefined)?.store;
  const stamped = typeof store?.id === "string" ? store.id : "";
  const id = STORE_ID_RE.test(stamped)
    ? stamped
    : `${slug(owner ?? "gist")}/${slug(typeof manifest.id === "string" ? manifest.id : "kit")}`;
  const version =
    (typeof store?.version === "string" && store.version) ||
    (typeof manifest.version === "string" && manifest.version) ||
    "1.0.0";
  return { id, version };
}

export type KitImportResult =
  | { ok: true; pin: BlueprintUiKit }
  | { ok: false; error: string };

/**
 * Import a kit by gist URL into the global store, returning the pin to record on the blueprint
 * (#2465, the authoring picker's import path). Fetch → validate it IS a `component-kit` manifest →
 * derive the store identity → add to the store (the store enforces id@version immutability — a
 * conflict with different content is surfaced, not overwritten) → pin `{ id, version, hash, source }`.
 */
export async function importKitByGistUrl(url: string, token = ""): Promise<KitImportResult> {
  const raw = await fetchGistManifestText(url, token);
  if (!raw.ok) return raw;
  const parsed = parseManifest(raw.text);
  if (!parsed.ok) return parsed;
  if (parsed.manifest.kind !== "component-kit") {
    return { ok: false, error: `that gist holds a '${parsed.manifest.kind}', not a component kit` };
  }
  const { id, version } = deriveKitIdentity(parsed.manifest, raw.owner);
  const hash = await sha256Hex(raw.text);
  try {
    await bsc(null, ["ui", "release", "add", id, version, "--kind", "component-kit", "--source", url], raw.text);
  } catch (e) {
    return { ok: false, error: `could not add ${id}@${version} to the kit store: ${String(e)}` };
  }
  return { ok: true, pin: { id, version, hash, source: url } };
}

runtime.features/planner/bodies/bodyPrimitives.t:
// Shared presentational primitives for the planner focused-pane bodies — the single home for the
// reusable, cross-body components (Card, Readiness, ModeChip, EntityChip, SourceHead, Kv). Used by
// the data-collection panes (Targets, Source legitimacy, Mapping, …) and renamed from
// DataCollectionPrimitives.tsx in #1635 to reflect that it is the shared body-primitives module.
// Token-styled inline to match the other focused bodies (SourceBody etc.); transcribed from
// collection/panes.jsx.

import type { ReactNode } from "react";
import { type CollectMode, type CollectSource, modeHue } from "./dataCollection";
import { MONO as mono } from "./bodyStyles";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

/** scrape / fetch pill. */
export function ModeChip({ mode }: { mode: CollectMode }) {
  const h = modeHue(mode);
  return (
    <Box as="span" pad={[1, 7]} bg={`color-mix(in oklch, oklch(0.74 0.12 ${h}), transparent 88%)`} radius={99} style={{
      display: "inline-flex", alignItems: "center", gap: 4,
      fontFamily: mono, fontSize: 9.5, whiteSpace: "nowrap",
      color: `oklch(0.78 0.11 ${h})`,
      border: `1px solid color-mix(in oklch, oklch(0.74 0.12 ${h}), transparent 72%)`,
    }}>
      <Box as="span">{mode === "scrape" ? "🕸" : "⤓"}</Box>{mode}
    </Box>
  );
}

/** A Data Model entity name chip. */
export function EntityChip({ name }: { name: string }) {
  return (
    <Box as="span" pad={[1, 6]} bg="var(--bg-elev2)" border="soft" radius={4} style={{ fontFamily: mono, fontSize: 9.5, color: "var(--fg-muted)",
    }}>{name}</Box>
  );
}

/** A titled section card (the pane's building block). `accent` rings it in the accent hue. */
export function Card({ label, hint, badge, accent, children }: {
  label: string; hint?: string; badge?: ReactNode; accent?: boolean; children: ReactNode;
}) {
  return (
    <Box pad={[10, 12]} bg="var(--bg-panel)" radius={8} style={{
      border: "1px solid " + (accent ? "color-mix(in oklch, var(--accent), transparent 72%)" : "var(--border-soft)"),
    }}>
      <Row gap={8} style={{ marginBottom: 9 }}>
        <Text as="span" mono size={9.5} tone="dim" style={{ textTransform: "uppercase", letterSpacing: ".07em" }}>{label}</Text>
        {badge}
        <Spacer />
        {hint && <Text as="span" mono size={9.5} tone="dim">{hint}</Text>}
      </Row>
      {children}
    </Box>
  );
}

/** A compact list-item card (mono title row + optional meta line) for the stage bodies' simple
 *  lists (skills, automations). `badge` sits inline after the title; `highlight` rings it in the
 *  accent hue (e.g. a freshly-authored skill). */
export function ListItemCard({ title, meta, badge, highlight }: {
  title: ReactNode; meta?: ReactNode; badge?: ReactNode; highlight?: boolean;
}) {
  return (
    <Box pad={[8, 10]} bg={highlight ? "var(--accent-soft)" : "var(--bg-canvas)"} radius={6} style={{
      border: highlight ? "1px solid var(--accent)" : "1px solid var(--border-soft)",
    }}>
      <Row gap={6}>
        <Text as="div" mono size={11} style={{ color: "var(--fg)" }}>{title}</Text>
        {badge}
      </Row>
      {meta != null && <Text as="div" mono size={9.5} tone="dim" style={{ marginTop: 3 }}>{meta}</Text>}
    </Box>
  );
}

/** Source row header: mode chip · label · location. */
export function SourceHead({ s, right }: { s: CollectSource; right?: ReactNode }) {
  return (
    <Row gap={8}>
      <ModeChip mode={s.mode} />
      <Text as="span" size={12.5} weight={600} style={{ fontFamily: "var(--sans)", color: "var(--fg)" }}>{s.label}</Text>
      {s.loc && <Text as="span" mono size={9.5} tone="dim" style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{s.loc}</Text>}
      <Spacer />
      {right}
    </Row>
  );
}

export interface ReadyCheck { id: string; label: string; ok: boolean; block?: boolean; detail?: string }

/** The gate-readiness card: per-check ✓ / ✕ / ○ with a count and an optional tail note. */
export function Readiness({ checks, tail }: { checks: ReadyCheck[]; tail?: ReactNode }) {
  const ok = checks.filter((c) => c.ok).length;
  return (
    <Card label="readiness" accent hint={ok === checks.length ? "gate met" : `${ok}/${checks.length}`}>
      <Stack gap={5}>
        {checks.map((c) => {
          const color = c.ok ? "var(--success)" : c.block ? "var(--danger)" : "var(--fg-dim)";
          return (
            <Row key={c.id} gap={8} style={{ fontFamily: mono, fontSize: 11 }}>
              <Text as="span" style={{ color, width: 12 }}>{c.ok ? "✓" : c.block ? "✕" : "○"}</Text>
              <Text as="span" tone="muted">{c.label}</Text>
              <Spacer />
              {c.detail && <Text as="span" size={9.5} style={{ color: c.block ? "var(--danger)" : "var(--fg-dim)" }}>{c.detail}</Text>}
            </Row>
          );
        })}
      </Stack>
      {tail && <Box style={{ marginTop: 9, paddingTop: 9, borderTop: "1px solid var(--border-soft)", fontFamily: mono, fontSize: 10, color: "var(--fg-dim)", lineHeight: 1.5 }}>{tail}</Box>}
    </Card>
  );
}

/** key→value cell used in the scope grid. */
export function Kv({ k, v }: { k: string; v?: string }) {
  return (
    <Stack gap={2}>
      <Text as="span" mono size={8.5} tone="dim" style={{ textTransform: "uppercase", letterSpacing: ".06em" }}>{k}</Text>
      <Text as="span" mono size={10.5} tone="muted">{v || "—"}</Text>
    </Stack>
  );
}

runtime.features/planner/bodies/bodyStyles.ts:
// Shared inline-style constants for the planner focused-pane bodies (#1635).
//
// The bodies under bodies/ are token-styled inline (no CSS modules) and historically each
// re-declared the same handful of style objects. These are the ones that were byte-identical
// across multiple bodies — extracted here so there is a single source of truth.
//
// NOTE: only TRULY-identical style objects live here. ScanViews keeps its own `grpLabel`
// (fontSize 10 / letterSpacing .08em) because it differs from this one (fontSize 9.5 / .06em),
// and the per-body component helpers (Card/Field/Seg/Toggle/…) differ in props + markup between
// bodies and are deliberately NOT consolidated.

import type { CSSProperties } from "react";

/** The mono font token (`var(--mono)`), referenced inline across every planner body. */
export const MONO = "var(--mono)";

/**
 * Uppercase, dim, tracked group/section label — the standard field/section caption used by the
 * Deploy, Source, Integration, and Integrations bodies.
 */
export const grpLabel: CSSProperties = {
  fontFamily: MONO, fontSize: 9.5, color: "var(--fg-dim)", textTransform: "uppercase", letterSpacing: ".06em",
};

/** A small, dim mono caption (hints, inline meta). */
export const monoSm: CSSProperties = { fontFamily: MONO, fontSize: 10, color: "var(--fg-dim)" };

// CollapsibleCard — a generic framed, collapsible section card for the focused planner bodies
// (#…). The whole header row toggles (chevron affordance, mirroring the deploy `Card` and the
// repo/stream rows); collapsed by default so a pane of these reads as a tidy stack of headers the
// user opens on demand. Unlike the numbered deploy `Card` (deployPrimitives), this takes a plain
// icon + title, so it fits any section (coordination, shared deps, …).
import { useState } from "react";
import { MONO } from "./bodyStyles";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Row } from "@/shared/ui/layout/Row";
import { Spacer } from "@/shared/ui/layout/Spacer";

export function CollapsibleCard({ title, hint, icon, iconTone, right, tone, defaultOpen = false, children }: {
  title: string;
  hint?: string;
  /** A small leading glyph (e.g. "◎"). */
  icon?: string;
  /** Colour for the icon glyph only, leaving the border soft — for accenting a card (e.g. the
   *  hero Kickoff card) without tinting its frame. Falls back to `tone`, then the dim default. */
  iconTone?: string;
  /** Right-aligned control/summary in the header row. */
  right?: React.ReactNode;
  /** Border accent color; defaults to the soft border. */
  tone?: string;
  defaultOpen?: boolean;
  children: React.ReactNode;
}) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <Box radius="lg" bg="var(--bg-panel)" pad={[13, 14]} style={{
      border: "1px solid " + (tone ? `color-mix(in oklch, ${tone}, transparent 78%)` : "var(--border-soft)"),
    }}>
      <Row
        onClick={() => setOpen((o) => !o)}
        gap={9}
        style={{ marginBottom: open ? 12 : 0, cursor: "pointer", userSelect: "none" }}
      >
        {icon && (
          <Box as="span" radius={6} bg="var(--bg-elev)" border="soft" style={{
            width: 20, height: 20, flex: "0 0 20px", display: "flex", alignItems: "center", justifyContent: "center",
            fontFamily: MONO, fontSize: 11, color: iconTone ?? tone ?? "var(--fg-dim)",
          }}>{icon}</Box>
        )}
        <Text as="span" size={13} weight={600} style={{ fontFamily: "var(--sans)", color: "var(--fg)" }}>{title}</Text>
        {hint && <Text as="span" mono size={9.5} tone="dim">{hint}</Text>}
        <Spacer />
        {right}
        <Text as="span" tone="dim" mono size={11} style={{ width: 12, textAlign: "center" }}>{open ? "▾" : "▸"}</Text>
      </Row>
      {open && children}
    </Box>
  );
}

runtime.features/planner/bodies/connectorForm.ts:
// connectorForm — the spec-driven connector form + per-source card for SourceBody (#1637).
//
// Split out of SourceBody.tsx: every PURE presentational piece that renders a declared
// source from its ConnectionSpec lives here — the field/secret inputs, the status badges, the scan
// bar/result, and the collapsible SourceCard that drives the spec → connect form. These take props
// only (no store, no invoke/listen) — the connection lifecycle lives in sourceConnection.ts.
//
// SECURITY BOUNDARY (the design's payoff): a secret field's value lives ONLY in local component
// state and is "saved to the device keychain" on connect — it is NEVER written into the persisted
// SourceConfig and never shared with the planning agent, which sees only a redacted handle + the
// discovered object inventory.

import {
  connector, isConnected,
  type DeclaredSource, type SpecField, type SourceStatus, type RuntimeConnectorView,
} from "../lib/sourceConfig";
import { MONO, grpLabel } from "./bodyStyles";
import { Chip } from "@/shared/ui/data/Chip";
import { InlineError } from "@/shared/ui/feedback/InlineError";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Grid } from "@/shared/ui/layout/Grid";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

export const STATUS_DOT: Record<SourceStatus, string> = {
  declared: "var(--fg-dim)",
  connecting: "var(--accent)",
  scanning: "var(--accent)",
  scanned: "var(--success)",
  error: "var(--danger)",
};

/** READ-ONLY badge — every source is read-only; the design repeats this as the core reassurance.
 *  Folded onto the shared color-mix Chip (#2160) — same shape as InfoChip below. */
function ReadOnlyPill() {
  return (
    <Chip color="var(--success)" fontSize={9} padding="2px 7px" borderAlpha={74} style={{ whiteSpace: "nowrap" }}>READ-ONLY</Chip>
  );
}

/** A small mono badge tile, e.g. "QB". */
function Badge({ text }: { text: string }) {
  return (
    <Box as="span" pad={[2, 5]} bg="var(--bg-canvas)" border radius="sm" style={{
      fontFamily: MONO, fontSize: 10, color: "var(--fg-muted)", whiteSpace: "nowrap",
    }}>{text}</Box>
  );
}

/** A labeled, non-secret text field — its value is persisted into the source's config. */
function Field({ field, value, onChange }: { field: SpecField; value: string; onChange: (v: string) => void }) {
  return (
    <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
      <Text as="span" mono size={10} tone="muted">
        {field.label}{field.optional && <Text as="span" tone="dim"> · optional{field.hint ? `, ${field.hint}` : ""}</Text>}
      </Text>
      {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled field input (local Field component; not the shared .input/.field) */}
      <input
        value={value}
        placeholder={field.placeholder}
        onChange={(e) => onChange(e.target.value)}
        style={{
          height: 30, padding: "0 11px", background: "var(--bg-elev)", border: "1px solid var(--border)",
          borderRadius: "var(--r-md)", outline: "none", fontFamily: MONO, fontSize: 12.5, color: "var(--fg)",
        }}
      />
    </label>
  );
}

/** A secret field — masked, reveal-toggle, value held ONLY in local state (keychain-bound). */
function SecretField({ field, value, revealed, onChange, onReveal, testid }: {
  field: SpecField; value: string; revealed: boolean; onChange: (v: string) => void; onReveal: () => void; testid?: string;
}) {
  return (
    <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
      <Text as="span" mono size={10} tone="muted">
        {field.label} <Text as="span" tone="accent">●</Text> <Text as="span" tone="dim">secret</Text>
      </Text>
      <Row gap={8}>
        {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled secret input (masked, keychain-bound; not the shared .input) */}
        <input
          type={revealed ? "text" : "password"}
          value={value}
          aria-label={field.label}
          data-testid={testid}
          onChange={(e) => onChange(e.target.value)}
          style={{
            flex: 1, minWidth: 0, height: 32, padding: "0 11px", background: "var(--bg-elev)",
            border: "1px solid var(--accent-dim)", borderRadius: "var(--r-md)", outline: "none",
            fontFamily: MONO, fontSize: 13, letterSpacing: revealed ? 0 : ".06em", color: "var(--fg)",
          }}
        />
        {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled reveal toggle (custom dimensions, no .icon-btn hover state) */}
        <button
          onClick={onReveal} title={revealed ? "Hide" : "Reveal"} aria-label={`${revealed ? "Hide" : "Reveal"} ${field.label}`}
          style={{
            width: 34, height: 32, flex: "0 0 34px", display: "flex", alignItems: "center", justifyContent: "center",
            background: "var(--bg-elev)", border: "1px solid var(--border)", borderRadius: "var(--r-md)", cursor: "pointer", fontSize: 13,
          }}
        >👁</button>
      </Row>
    </label>
  );
}

/** Info / boundary chip ("🛡 Credentials stay on this device …"). */
function InfoChip({ children, color = "var(--info)" }: { children: React.ReactNode; color?: string }) {
  return (
    <Chip color={color} alignSelf="flex-start" gap={6} padding="3px 9px" bgAlpha={89} borderAlpha={76}>{children}</Chip>
  );
}

/** Indeterminate scan bar (the only place the pane animates — a genuinely live op). */
function ScanBar() {
  return (
    <Box bg="var(--bg-elev)" radius={99} style={{ height: 5, overflow: "hidden", position: "relative" }}>
      <Box bg="var(--accent)" radius={99} style={{ position: "absolute", top: 0, left: 0, height: "100%", width: "30%", animation: "scan 1.3s ease-in-out infinite" }} />
    </Box>
  );
}

/** The discovered-object grid + behaviors a scanned source surfaces. */
function ScanResult({ src, dataModelName }: { src: DeclaredSource; dataModelName: string }) {
  return (
    <>
      <Grid cols={2} gap={6}>
        {(src.objects ?? []).map((o) => (
          <Row key={o.name} justify="between" style={{ background: "var(--bg-elev)", border: "1px solid var(--border-soft)", borderRadius: "var(--r-sm)", padding: "5px 9px" }}>
            <Text as="span" size={11.5} tone="muted">{o.name}</Text>
            <Text as="span" mono size={11.5} style={{ color: "var(--fg)" }}>{o.count.toLocaleString()}</Text>
          </Row>
        ))}
      </Grid>
      {(src.behaviors ?? []).length > 0 && (
        <Row gap={8} wrap style={{ background: "color-mix(in oklch, var(--violet), transparent 92%)", border: "1px solid color-mix(in oklch, var(--violet), transparent 80%)", borderRadius: "var(--r-sm)", padding: "6px 10px" }}>
          <Text as="span" mono size={9} style={{ letterSpacing: ".06em", color: "var(--violet)" }}>BEHAVIORS</Text>
          {(src.behaviors ?? []).map((b) => <Text as="span" key={b.label} size={11.5} tone="muted">⚙ {b.label}</Text>)}
        </Row>
      )}
      <Text as="div" mono size={10} style={{ color: "var(--violet)" }}>→ feeds the «{dataModelName}» Data Model</Text>
    </>
  );
}

/** One declared source's collapsible card — header + a spec/state-driven body. */
export function SourceCard({
  src, runtime, dataModelName, expanded, revealed, secrets,
  onToggle, onField, onSecret, onReveal, onEnv, onConnect, onRetry, onRemove,
}: {
  src: DeclaredSource;
  /** Agent-authored runtime connector list (#1980) — resolves the source's real connector identity. */
  runtime?: readonly RuntimeConnectorView[];
  dataModelName: string;
  expanded: boolean;
  revealed: boolean;
  secrets: Record<string, string>;
  onToggle: () => void;
  onField: (key: string, v: string) => void;
  onSecret: (key: string, v: string) => void;
  onReveal: (key: string) => void;
  onEnv: (env: "production" | "sandbox") => void;
  onConnect: () => void;
  onRetry: () => void;
  onRemove: () => void;
}) {
  const c = connector(src.connectorId, runtime);
  const spec = c.spec;
  const connected = isConnected(src);
  const borderColor = src.status === "error" ? "color-mix(in oklch, var(--danger), transparent 62%)"
    : src.status === "scanned" ? "var(--border-soft)"
    : src.status === "declared" ? "color-mix(in oklch, var(--accent), transparent 72%)"
    : "color-mix(in oklch, var(--accent), transparent 64%)";

  // Connectable once every required (non-optional) field has a value — secrets from local state.
  const filled = (f: SpecField) => f.optional || (f.secret ? !!secrets[f.key]?.trim() : !!src.fields[f.key]?.trim());
  const canConnect = spec.auth === "oauth" || spec.auth === "upload" || spec.fields.every(filled);

  return (
    <Box data-testid={`source-card-${src.uid}`} bg="var(--bg-panel)" radius="lg" style={{ border: `1px solid ${borderColor}`, overflow: "hidden" }}>
      {/* header */}
      <Row onClick={onToggle} gap={9} style={{ padding: "11px 13px", background: "var(--bg-elev)", cursor: "pointer" }}>
        <Box as="span" bg={STATUS_DOT[src.status]} radius={99} style={{ width: 8, height: 8, flex: "0 0 8px", animation: (src.status === "connecting" || src.status === "scanning") ? "pulse 1.2s ease-in-out infinite" : undefined }} />
        <Badge text={c.badge} />
        <Box as="span" style={{ fontSize: 13.5, fontWeight: 600, color: "var(--fg)", flex: 1, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
          {c.name}{src.instance && <Text as="span" mono size={10.5} tone="muted" weight={400}> · {src.instance}</Text>}
        </Box>
        {src.status === "error" ? (
          <Box as="span" pad={[2, 7]} bg="color-mix(in oklch, var(--danger), transparent 88%)" radius={99} style={{ fontFamily: MONO, fontSize: 9, color: "var(--danger)", border: "1px solid color-mix(in oklch, var(--danger), transparent 72%)"}}>FAILED</Box>
        ) : <ReadOnlyPill />}
        <Text as="span" tone="dim" size={11}>{expanded ? "▾" : "▸"}</Text>
      </Row>

      {expanded && (
        <Stack gap={10} style={{ padding: "12px 13px" }}>
          {/* declared / not connected → the spec-driven connect form */}
          {src.status === "declared" && (
            <>
              <InfoChip>🛡 Credentials stay on this device — the planning agent never sees them</InfoChip>
              {spec.auth === "oauth" ? (
                <>
                  {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled OAuth connect button */}
                  <button data-testid={`connect-${src.uid}`} onClick={onConnect} style={{
                    alignSelf: "flex-start", display: "inline-flex", alignItems: "center", gap: 9, fontFamily: "var(--sans)", fontSize: 13, fontWeight: 600,
                    color: "var(--accent)", background: "color-mix(in oklch, var(--accent), transparent 91%)", border: "1px solid var(--accent-dim)", borderRadius: "var(--r-md)", padding: "10px 16px", cursor: "pointer",
                  }}>⟳ {spec.oauthLabel} ↗</button>
                  {spec.envs && (
                    <Stack gap={5}>
                      <Box as="span" style={grpLabel}>environment</Box>
                      <Row gap={7} align="stretch">
                        {(["production", "sandbox"] as const).map((env) => {
                          const on = (src.env ?? "production") === env;
                          return (
                            // eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled environment toggle
                            <button key={env} onClick={() => onEnv(env)} style={{
                              fontFamily: MONO, fontSize: 11, cursor: "pointer", borderRadius: "var(--r-sm)", padding: "5px 11px",
                              color: on ? "var(--fg)" : "var(--fg-dim)", background: on ? "var(--bg-elev2)" : "var(--bg-elev)", border: "1px solid " + (on ? "var(--border)" : "var(--border-soft)"),
                            }}>{on ? "◉" : "○"} {env[0].toUpperCase() + env.slice(1)}</button>
                          );
                        })}
                      </Row>
                    </Stack>
                  )}
                </>
              ) : spec.auth === "upload" ? (
                // eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled upload connect button
                <button data-testid={`connect-${src.uid}`} onClick={onConnect} style={{
                  alignSelf: "flex-start", fontFamily: "var(--sans)", fontSize: 13, fontWeight: 600, color: "var(--accent)",
                  background: "color-mix(in oklch, var(--accent), transparent 91%)", border: "1px solid var(--accent-dim)", borderRadius: "var(--r-md)", padding: "9px 15px", cursor: "pointer",
                }}>Choose file… ↗</button>
              ) : (
                <>
                  {spec.fields.map((f) => f.secret ? (
                    <SecretField key={f.key} field={f} value={secrets[f.key] ?? ""} revealed={revealed} onChange={(v) => onSecret(f.key, v)} onReveal={() => onReveal(f.key)} testid={`secret-${src.uid}`} />
                  ) : (
                    <Field key={f.key} field={f} value={src.fields[f.key] ?? ""} onChange={(v) => onField(f.key, v)} />
                  ))}
                  {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled save-and-connect button */}
                  <button data-testid={`connect-${src.uid}`} onClick={onConnect} disabled={!canConnect} style={{
                    alignSelf: "flex-start", fontFamily: "var(--sans)", fontSize: 12.5, fontWeight: 600, color: "oklch(0.20 0.04 70)",
                    background: "var(--accent)", border: "none", borderRadius: "var(--r-md)", padding: "8px 15px", cursor: canConnect ? "pointer" : "not-allowed", opacity: canConnect ? 1 : 0.45,
                  }}>Save &amp; connect →</button>
                </>
              )}
              <Box style={{ fontFamily: MONO, fontSize: 9.5, color: "var(--fg-dim)", lineHeight: 1.5, borderTop: "1px dashed var(--border-soft)", paddingTop: 9 }}>
                will contribute → {spec.contributes}
              </Box>
            </>
          )}

          {/* connecting / validating */}
          {src.status === "connecting" && (
            <>
              <Text as="div" size={12.5} tone="accent">Validating {c.name} credentials…</Text>
              <ScanBar />
              <Text as="div" mono size={9} tone="dim">checking scopes · read-only</Text>
            </>
          )}

          {/* connected + scanning */}
          {src.status === "scanning" && (
            <>
              <InfoChip color="var(--success)">🔑 saved to keychain</InfoChip>
              {src.handle && <InfoChip>↗ planner sees: «{src.handle}»</InfoChip>}
              <Text as="div" size={12.5} tone="accent">scanning… discovering objects</Text>
              <ScanBar />
            </>
          )}

          {/* connected (scanned) */}
          {src.status === "scanned" && (
            <>
              <Row gap={8} wrap>
                <InfoChip color="var(--success)">🔑 saved to keychain</InfoChip>
                {src.handle && <InfoChip>↗ shared: «{src.handle}»</InfoChip>}
              </Row>
              <ScanResult src={src} dataModelName={dataModelName} />
            </>
          )}

          {/* error / auth failed */}
          {src.status === "error" && (
            <>
              <InlineError pad={[8, 10]} radius="md" borderFade={78}>
                <Stack gap={3}>
                  <Text as="span" mono size={10.5} tone="danger">✕ {src.error ?? "connection failed"}</Text>
                  <Text as="span" mono size={9} tone="dim">check the connection details and try again</Text>
                </Stack>
              </InlineError>
              <Row gap={8} align="stretch">
                {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled retry button */}
                <button data-testid={`retry-${src.uid}`} onClick={onRetry} style={{ fontFamily: "var(--sans)", fontSize: 11, fontWeight: 600, color: "var(--danger)", background: "color-mix(in oklch, var(--danger), transparent 90%)", border: "1px solid color-mix(in oklch, var(--danger), transparent 72%)", borderRadius: "var(--r-md)", padding: "5px 12px", cursor: "pointer" }}>↻ retry</button>
                {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled remove-source button */}
                <button onClick={onRemove} style={{ fontFamily: "var(--sans)", fontSize: 11, color: "var(--fg-dim)", background: "transparent", border: "1px solid var(--border-soft)", borderRadius: "var(--r-md)", padding: "5px 12px", cursor: "pointer" }}>remove source</button>
              </Row>
              <Text as="span" mono size={9} tone="dim">⚠ gate held until resolved</Text>
            </>
          )}

          {/* a connected source can always be removed (collapsed footer affordance) */}
          {connected && (
            // eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled remove-source affordance
            <button onClick={onRemove} style={{ alignSelf: "flex-start", fontFamily: MONO, fontSize: 9.5, color: "var(--fg-dim)", background: "transparent", border: "1px solid var(--border-soft)", borderRadius: "var(--r-md)", padding: "3px 10px", cursor: "pointer" }}>remove source</button>
          )}
        </Stack>
      )}
    </Box>
  );
}

runtime.features/planner/bodies/dataCollection.t:
// Source-mode atoms for the planner focused-pane bodies — the `scrape` vs `fetch` vocabulary
// and the declared-source shape that `bodyPrimitives.tsx` renders (ModeChip / SourceHead).
//
// Pure types + one helper; React-free by design (the primitives that consume them are the
// React half).
//
// History: this module used to also carry the JSON contracts for a data-COLLECTION pane
// system (Targets · Licensing · Acquire · Extract · Map · Clean · Load) plus a
// `parseStageJson` loader, all keyed to a `useStageJson.ts` hook that was never written.
// None of it ever had a consumer; removed in #3244. If those panes get built, the contracts
// should be re-derived from the panes that actually need them rather than restored wholesale.

export type CollectMode = "scrape" | "fetch";

/** One declared external source (a site to scrape or an API/dataset to fetch). */
export interface CollectSource {
  id: string;
  mode: CollectMode;
  label: string;
  /** URL / endpoint / dataset identifier. */
  loc?: string;
  /** Free-text kind ("website", "REST API", "CSV dataset", …). */
  type?: string;
  /** Data Model entity names this source is expected to populate. */
  feeds?: string[];
  /** Crawl/fetch bounds — keeps acquisition bounded. */
  scope?: { start?: string; pattern?: string; bound?: string };
}

/** Mode chip hue (matches the design: scrape=230, fetch=175). */
export function modeHue(mode: CollectMode): number {
  return mode === "scrape" ? 230 : 175;
}

runtime.features/planner/bodies/deployPrimitives:
// Shared presentational primitives for the Deploy stage body (#1636) — extracted verbatim from
// DeployView.tsx. These are the Deploy-pane-LOCAL form helpers (Card/Field/Seg/Toggle/Select) and
// inline style objects (prop/chip). Their signatures deliberately differ from the cross-body
// primitives in bodyPrimitives.tsx (e.g. this Card is numbered/done-aware) and so are NOT merged.

import { useState } from "react";
import { Toggle as Switch } from "@/shared/ui/controls/Toggle";
import { Row } from "@/shared/ui/layout/Row";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { MONO, grpLabel, monoSm } from "./bodyStyles";

export const prop: React.CSSProperties = { fontFamily: MONO, fontSize: 9, color: "var(--accent)" };
export const chip: React.CSSProperties = {
  padding: "1px 7px", borderRadius: 99, fontFamily: MONO, fontSize: 9, background: "var(--bg-elev2)",
  color: "var(--fg-muted)", border: "1px solid var(--border-soft)", whiteSpace: "nowrap",
};

/** A collapsible card with a numbered (or ✓-when-done) tile, title, optional accent + right slot.
 *  Collapsed by default (#1421 follow-up) — the whole header row is the toggle, mirroring the
 *  repo/source cards' chevron affordance; pass `defaultOpen` to start expanded (e.g. an untargeted
 *  Target card that still needs input). */
export function Card({ n, title, hint, right, accent, done, defaultOpen = false, children }: {
  n: string; title: string; hint?: string; right?: React.ReactNode; accent?: string; done?: boolean;
  defaultOpen?: boolean; children: React.ReactNode;
}) {
  const [open, setOpen] = useState(defaultOpen);
  const tileColor = done ? "var(--success)" : accent ?? "var(--fg-dim)";
  return (
    <Box style={{
      borderRadius: "var(--r-lg)", padding: "13px 14px",
      border: "1px solid " + (done ? "color-mix(in oklch, var(--success), transparent 58%)" : accent ? `color-mix(in oklch, ${accent}, transparent 78%)` : "var(--border-soft)"),
      // Confirmed (done) cards read as outline-only — green border, no green background fill (#1498).
      background: "var(--bg-panel)",
    }}>
      <Row
        onClick={() => setOpen((o) => !o)}
        gap={9}
        style={{ marginBottom: open ? 12 : 0, cursor: "pointer", userSelect: "none" }}
      >
        <Box as="span" bg={done ? "color-mix(in oklch, var(--success), transparent 80%)" : "var(--bg-elev)"} radius={6} style={{
          width: 20, height: 20, flex: "0 0 20px", display: "flex", alignItems: "center", justifyContent: "center",
          fontFamily: MONO, fontSize: 9, color: tileColor,
          border: "1px solid " + (done ? "var(--success)" : accent ? `color-mix(in oklch, ${accent}, transparent 65%)` : "var(--border-soft)"),
        }}>{done ? "✓" : n}</Box>
        <Text as="span" size={13} weight={600} style={{ fontFamily: "var(--sans)", color: "var(--fg)" }}>{title}</Text>
        {hint && <Box as="span" style={monoSm}>{hint}</Box>}
        <Spacer />
        {right}
        <Text as="span" mono size={11} tone="dim" style={{ width: 12, textAlign: "center" }}>{open ? "▾" : "▸"}</Text>
      </Row>
      {open && children}
    </Box>
  );
}

/** Group divider — "A · HOW IT SHIPS", colored rule. */
export function Divider({ label, color }: { label: string; color: string }) {
  return (
    <Row gap={10} style={{ marginTop: 2 }}>
      <Text as="span" mono size={9.5} weight={600} style={{ color, letterSpacing: ".1em" }}>{label}</Text>
      <Box as="span" bg="var(--border-soft)" style={{ flex: 1, height: 1}} />
    </Row>
  );
}

export function Seg<T extends string>({ value, options, onChange }: { value: T; options: readonly T[]; onChange: (v: T) => void }) {
  return (
    <Box border="soft" radius="md" style={{ display: "inline-flex", overflow: "hidden" }}>
      {options.map((o, i) => (
        // eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled segmented cell (Deploy-local primitive); Button/.btn would change rendering
        <button key={o} onClick={() => onChange(o)} style={{
          height: 22, padding: "0 9px", border: 0, borderLeft: i ? "1px solid var(--border-soft)" : "none", cursor: "pointer",
          fontFamily: MONO, fontSize: 9.5, background: value === o ? "var(--bg-elev2)" : "transparent", color: value === o ? "var(--fg)" : "var(--fg-dim)",
        }}>{o}</button>
      ))}
    </Box>
  );
}

export function Field({ label, value, onChange }: { label: string; value: string; onChange: (v: string) => void }) {
  return (
    <label style={{ display: "flex", flexDirection: "column", gap: 4, flex: 1, minWidth: 0 }}>
      <Box as="span" style={grpLabel}>{label}</Box>
      {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled input (Deploy-local primitive w/ grpLabel layout); TextField's .field wrapper differs */}
      <input value={value} onChange={(e) => onChange(e.target.value)} style={{
        height: 26, padding: "0 8px", background: "var(--bg-canvas)", border: "1px solid var(--border-soft)",
        borderRadius: "var(--r-sm)", outline: "none", fontFamily: MONO, fontSize: 11, color: "var(--fg)",
      }} />
    </label>
  );
}

export function Toggle({ on, onClick, label, value }: { on: boolean; onClick: () => void; label: string; value?: string }) {
  return (
    <Row gap={9}>
      <Switch on={on} onClick={onClick} size="sm" tone="success" />
      <Text as="span" mono size={10} style={{ color: on ? "var(--fg)" : "var(--fg-muted)", lineHeight: 1.3 }}>{label}</Text>
      <Spacer />
      {value && <Text as="span" mono size={9.5} style={{ color: on ? "var(--fg-muted)" : "var(--fg-dim)" }}>{value}</Text>}
    </Row>
  );
}

/** A small native <select>, styled to match the card's fields (#1192). */
export function Select<T extends string>({ label, value, options, onChange }: { label: string; value: T | ""; options: readonly T[]; onChange: (v: T) => void }) {
  return (
    <label style={{ display: "flex", flexDirection: "column", gap: 4, flex: 1, minWidth: 0 }}>
      <Box as="span" style={grpLabel}>{label}</Box>
      {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled select (Deploy-local primitive w/ grpLabel layout); SelectField's .field wrapper differs */}
      <select value={value} onChange={(e) => onChange(e.target.value as T)} style={{
        height: 28, padding: "0 8px", background: "var(--bg-canvas)", border: "1px solid var(--border-soft)",
        borderRadius: "var(--r-sm)", outline: "none", fontFamily: MONO, fontSize: 11, color: "var(--fg)",
      }}>
        <option value="" disabled>—</option>
        {options.map((o) => <option key={o} value={o}>{o}</option>)}
      </select>
    </label>
  );
}

runtime.features/planner/bodies/deployShipSectio:
// The Deploy stage's per-repo "ship" sections (#1636) — extracted verbatim from DeployView.tsx.
// Every repo owns its OWN CI/CD pipeline, environments, config/secrets, and rollout+health; this
// renders them inside an expanded RepoDeployCard once a target is set. Behavior-preserving move.

import {
  PIPE_TRIGGERS, RELEASE_STRATEGIES,
  serviceChecks, finalStageName, serviceMode,
  type DeployService, type ReleaseStrategy,
} from "../lib/deployConfig";
import { MONO, grpLabel, monoSm } from "./bodyStyles";
import { chip, Card, Seg, Toggle } from "./deployPrimitives";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

/** The per-repo ship sections (#1421) — every repo owns its OWN pipeline, environments,
 *  config/secrets, and rollout. Rendered inside each {@link RepoDeployCard} once a target is set. */
export function ServiceDeploySections({ svc, setSvc }: {
  svc: DeployService; setSvc: (patch: Partial<DeployService>) => void;
}) {
  const ck = (id: string) => serviceChecks(svc).find((c) => c.id === id)?.ok ?? false;
  return (
    <>
      {/* 2 · CI/CD pipeline */}
      <Card n="02" title="CI / CD pipeline" accent="var(--accent)" done={ck("pipeline")} right={<Text as="span" style={chip}>{svc.pipeline.provider}</Text>}>
        <Stack gap={6}>
          {svc.pipeline.stages.map((st, i) => {
            const isFinal = i === svc.pipeline.stages.length - 1;
            const stageName = isFinal && (["deploy", "publish", "package"] as string[]).includes(st.name) ? finalStageName(svc) : st.name;
            return (
              <Stack key={st.id} gap={6}>
                <Stack gap={8} style={{ padding: "11px 12px", borderRadius: "var(--r-md)", background: "var(--bg-elev)", border: "1px solid " + (st.gate ? "var(--accent-dim)" : "var(--border-soft)") }}>
                  <Row gap={6}>
                    <Box as="span" bg={st.gate ? "var(--accent)" : i === 0 ? "var(--info)" : "var(--success)"} radius={99} style={{ width: 7, height: 7}} />
                    <Text as="span" mono size={11} style={{ color: "var(--fg)", textTransform: "uppercase", letterSpacing: ".04em" }}>{stageName}</Text>
                    <Spacer />
                    {st.gate && <Box as="span" style={{ ...chip, fontSize: 7.5, color: "var(--accent)", borderColor: "var(--accent-dim)", background: "color-mix(in oklch, var(--accent), transparent 85%)" }}>⛒ gate</Box>}
                  </Row>
                  <Text as="span" mono size={8.5} tone="dim" style={{ lineHeight: 1.35 }}>{st.cmd || "—"}</Text>
                  <Seg value={st.trigger} options={PIPE_TRIGGERS}
                    onChange={(v) => setSvc({ pipeline: { ...svc.pipeline, stages: svc.pipeline.stages.map((x) => x.id === st.id ? { ...x, trigger: v } : x) } })} />
                </Stack>
                {i < svc.pipeline.stages.length - 1 && (
                  <Text as="span" mono size={13} style={{ alignSelf: "center", color: svc.pipeline.stages[i + 1].gate ? "var(--accent)" : "var(--fg-dim)" }}>{svc.pipeline.stages[i + 1].gate ? "⟱" : "↓"}</Text>
                )}
              </Stack>
            );
          })}
        </Stack>
      </Card>

      {/* 3 · Environments */}
      <Card n="03" title="Environments" hint="branch → env" done={ck("envs")}>
        <Stack gap={6}>
          {svc.envs.map((e, i) => (
            <Stack key={e.id} gap={6}>
              <Row gap={9} style={{ padding: "9px 11px", borderRadius: "var(--r-md)", background: "var(--bg-elev)", border: "1px solid var(--border-soft)" }}>
                <Box as="span" bg={e.id === "prod" ? "var(--success)" : "var(--fg-dim)"} radius={99} style={{ width: 7, height: 7, flex: "0 0 7px"}} />
                <Text as="span" mono size={11} style={{ color: "var(--fg)", width: 52 }}>{e.name}</Text>
                <Box as="span" style={{ ...chip, fontSize: 7.5, ...(e.auto ? {} : { color: "var(--accent)", borderColor: "var(--accent-dim)" }) }}>{e.auto ? "auto" : "manual"}</Box>
                <Box as="span" pad={[1, 6]} bg="var(--bg-canvas)" border="soft" radius={3} style={{ fontFamily: MONO, fontSize: 8.5, color: "var(--info)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>⎇ {e.branch}</Box>
                <Spacer />
                <Text as="span" mono size={8.5} tone="dim" style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", maxWidth: "42%" }}>{e.url || "—"}</Text>
              </Row>
              {i < svc.envs.length - 1 && <Text as="span" mono size={11} tone="dim" style={{ alignSelf: "center" }}>↓</Text>}
            </Stack>
          ))}
        </Stack>
      </Card>

      {/* 4 · Config & secrets */}
      <Card n="04" title="Config & secrets" hint={svc.config.vault} done={ck("secrets")}>
        {svc.config.config.length === 0 && svc.config.secrets.length === 0 ? (
          <Text as="span" style={monoSm}>No config or secrets yet — the planner proposes them per environment.</Text>
        ) : (
          <>
            {/* Horizontal scroll so long values / many env columns scroll WITHIN the card instead of
                overflowing the pane (#1421 follow-up); the table keeps a readable minimum width. */}
            <Box style={{ overflowX: "auto", margin: "0 -2px" }}>
            <table style={{ minWidth: 320, width: "100%", borderCollapse: "collapse", fontFamily: MONO, fontSize: 10.5 }}>
              <thead><tr style={{ color: "var(--fg-dim)", textAlign: "left" }}><th style={{ padding: "3px 6px", fontWeight: 400 }}>variable</th>{svc.envs.map((e) => <th key={e.id} style={{ padding: "3px 6px", fontWeight: 400 }}>{e.name}</th>)}</tr></thead>
              <tbody>
                {svc.config.config.map((row) => (
                  <tr key={row.key} style={{ borderTop: "1px solid var(--border-soft)" }}>
                    <td style={{ padding: "4px 6px", color: "var(--fg)" }}><Box as="span" bg="var(--info)" radius={2} style={{ display: "inline-block", width: 6, height: 6, marginRight: 6 }} />{row.key}</td>
                    {svc.envs.map((e) => <td key={e.id} title={row[e.id] || undefined} style={{ padding: "4px 6px", color: "var(--fg-muted)", maxWidth: 160, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{row[e.id] || "—"}</td>)}
                  </tr>
                ))}
                {svc.config.secrets.map((row) => (
                  <tr key={row.key} style={{ borderTop: "1px solid var(--border-soft)" }}>
                    <td style={{ padding: "4px 6px", color: "var(--fg)" }}><Box as="span" bg="var(--violet)" radius={2} style={{ display: "inline-block", width: 6, height: 6, marginRight: 6 }} />{row.key}</td>
                    {svc.envs.map((e) => (
                      <td key={e.id} style={{ padding: "4px 6px" }}>
                        {row[e.id]
                          ? <Text as="span" style={{ color: "var(--violet)" }}>••••✓</Text>
                          // eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled pill button in a table cell; Button/.btn would change rendering
                          : <button onClick={() => setSvc({ config: { ...svc.config, secrets: svc.config.secrets.map((s) => s.key === row.key ? { ...s, [e.id]: true } : s) } })}
                              style={{ padding: "1px 7px", borderRadius: 99, cursor: "pointer", fontFamily: MONO, fontSize: 9, color: "var(--danger)", background: "transparent", border: "1px solid color-mix(in oklch, var(--danger), transparent 60%)" }}>+ wire</button>}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
            </Box>
            <Text as="div" mono size={9} tone="dim" style={{ marginTop: 8 }}>🔒 secret values live in the vault, never here — only wiring state is shown.</Text>
          </>
        )}
      </Card>

      {/* 5 · Rollout & health — CLOUD ONLY (#2023): the rollout strategy (recreate/rolling/blue-green/
          canary), health probe, and migrate-with-deploy are running-cloud-service concerns; a local
          build (library publish / application package) ships via its pipeline's publish/package stage,
          so this card is hidden for local mode. Boxed as a collapsible card like the others (#1421). */}
      {serviceMode(svc) === "cloud" && (
        <Card n="05" title="Rollout & health" hint={svc.release.strategy || undefined} done={ck("release")}>
          <Stack gap={12}>
          <Row gap={10} wrap>
            <Text as="span" style={{ ...grpLabel }}>rollout</Text>
            <Row wrap gap={5} align="stretch">
              {RELEASE_STRATEGIES.map((s) => {
                const on = svc.release.strategy === s.id;
                return (
                  // eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled pill toggle button; Button/.btn would change rendering
                  <button key={s.id} onClick={() => setSvc({ release: { ...svc.release, strategy: s.id as ReleaseStrategy } })} style={{
                    fontFamily: MONO, fontSize: 9, padding: "3px 8px", borderRadius: 99, cursor: "pointer",
                    background: on ? "color-mix(in oklch, var(--accent), transparent 86%)" : "var(--bg-elev)",
                    border: "1px solid " + (on ? "var(--accent)" : "var(--border-soft)"), color: on ? "var(--accent)" : "var(--fg-dim)",
                  }}>{s.label}</button>
                );
              })}
            </Row>
            <Spacer />
            <Toggle on={svc.release.autoRollback} onClick={() => setSvc({ release: { ...svc.release, autoRollback: !svc.release.autoRollback } })} label="auto-rollback" />
          </Row>
          <Row wrap gap={14} align="stretch">
            <Toggle on={svc.health.probeOn} onClick={() => setSvc({ health: { ...svc.health, probeOn: !svc.health.probeOn } })} label="health probe" value={svc.health.probe} />
            <Toggle on={svc.release.migrateWithDeploy} onClick={() => setSvc({ release: { ...svc.release, migrateWithDeploy: !svc.release.migrateWithDeploy } })} label="migrate with deploy" />
          </Row>
          </Stack>
        </Card>
      )}
    </>
  );
}

runtime.features/planner/bodies/deployTargetSect:
// The Deploy stage's target editor (#1636) — extracted verbatim from DeployView.tsx. Owns the
// per-repo TARGET selection: the host/stack meta row, the Cloud · Local mode toggle, and the two
// bodies behind it — CloudBody (platform dropdown → workload → region/build/runtime → container
// orchestration) and LocalBody (a Library publish or a build-and-run-here Application + optional
// port-forward). Behavior-preserving move; no markup/style/handler changes.

import { useState } from "react";
import {
  PLATFORMS, platform, WORKLOAD, ORCHESTRATORS, REPLICA_OPTIONS,
  PUBLISH_REGISTRIES, PUBLISH_TRIGGERS, PORT_FORWARD_METHODS,
  hostMeta, serviceMode, serviceTargetDefined,
  type DeployService, type Workload,
  type DeployMode, type LocalKind, type PublishRegistry, type PublishTrigger, type PortForwardMethod,
} from "../lib/deployConfig";
import { MONO, grpLabel, monoSm } from "./bodyStyles";
import { prop, chip, Card, Seg, Field, Toggle, Select } from "./deployPrimitives";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Grid } from "@/shared/ui/layout/Grid";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

/** Cloud body (#1192) — today's card: platform dropdown → workload → region/build/runtime →
 *  containerization & orchestration for container workloads. Unchanged from the original. */
function CloudBody({ svc, setSvc }: { svc: DeployService; setSvc: (patch: Partial<DeployService>) => void }) {
  const [open, setOpen] = useState(false);
  const pickPlatform = (pid: string) => {
    setOpen(false);
    if (svc?.platform === pid) { setSvc({ platform: "", proposed: false }); return; }
    const p = platform(pid);
    const wl: Workload = svc && p.kinds.includes(svc.workload) ? svc.workload : (p.kinds[0] ?? "static");
    setSvc({ platform: pid, proposed: false, workload: wl });
  };
  const selPlat = svc.platform ? platform(svc.platform) : null;
  const isContainer = svc.workload === "container";
  const canContainerize = platform(svc.platform).kinds.includes("container");

  return (
    <>
          {/* platform dropdown */}
          <Text as="div" style={{ ...grpLabel, marginBottom: 8 }}>platform</Text>
          <Box style={{ position: "relative" }}>
            {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled dropdown trigger button; Button/.btn would change rendering */}
            <button onClick={() => setOpen((v) => !v)} style={{
              width: "100%", display: "flex", alignItems: "center", gap: 9, padding: "9px 11px", cursor: "pointer",
              borderRadius: "var(--r-md)", background: "var(--bg-elev)", border: "1px solid " + (open ? "var(--accent-dim)" : "var(--border-soft)"),
            }}>
              <Text size={14} style={{ width: 16, textAlign: "center", color: selPlat ? `oklch(0.78 0.12 ${selPlat.h})` : "var(--fg-dim)" }}>{selPlat?.glyph ?? "▢"}</Text>
              <Text mono size={11} style={{ color: selPlat ? "var(--fg)" : "var(--fg-dim)" }}>{selPlat?.name ?? "Select a platform…"}</Text>
              <Box as="span" style={{ flex: 1 }} />
              <Text as="span" style={monoSm}>{PLATFORMS.length} options</Text>
              <Box as="span" style={{ fontFamily: MONO, fontSize: 10, color: "var(--fg-dim)", display: "inline-block", transform: open ? "rotate(180deg)" : "rotate(0deg)", transition: "transform .14s" }}>▾</Box>
            </button>
            {open && (
              <Box pad={5} bg="var(--bg-elev)" border radius="md" style={{
                position: "absolute", top: "calc(100% + 5px)", left: 0, right: 0, zIndex: 30, maxHeight: 236, overflowY: "auto", boxShadow: "0 14px 40px rgba(0,0,0,.55)",
              }}>
                {PLATFORMS.map((p) => {
                  const on = svc.platform === p.id;
                  return (
                    // eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled dropdown option button; Button/.btn would change rendering
                    <button key={p.id} onClick={() => pickPlatform(p.id)} style={{
                      width: "100%", display: "flex", alignItems: "center", gap: 10, padding: "7px 9px", cursor: "pointer",
                      borderRadius: "var(--r-sm)", border: "1px solid " + (on ? "color-mix(in oklch, var(--accent), transparent 62%)" : "transparent"),
                      background: on ? "color-mix(in oklch, var(--accent), transparent 88%)" : "transparent",
                    }}>
                      <Text size={14} style={{ width: 18, textAlign: "center", color: `oklch(0.78 0.12 ${p.h})` }}>{p.glyph}</Text>
                      <Text mono size={10.5} style={{ color: on ? "var(--fg)" : "var(--fg-muted)" }}>{p.name}</Text>
                      <Box as="span" pad={[1, 6]} border="soft" radius={99} style={{ fontFamily: MONO, fontSize: 8, color: "var(--fg-dim)"}}>{p.kinds.join(" · ")}</Box>
                      <Box as="span" style={{ flex: 1 }} />
                      {on && <Text mono size={10} tone="accent">✓</Text>}
                    </button>
                  );
                })}
              </Box>
            )}
          </Box>

          {svc.platform ? (
            <>
              {/* workload */}
              <Row gap={7} wrap align="stretch" style={{ margin: "11px 0" }}>
                {platform(svc.platform).kinds.map((k) => {
                  const on = svc.workload === k;
                  return (
                    // eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled pill toggle button; Button/.btn would change rendering
                    <button key={k} onClick={() => setSvc({ workload: k })} style={{
                      padding: "2px 9px", borderRadius: 99, cursor: "pointer", fontFamily: MONO, fontSize: 9.5,
                      border: "1px solid " + (on ? WORKLOAD[k].c : "var(--border-soft)"), color: on ? WORKLOAD[k].c : "var(--fg-dim)", background: "transparent",
                    }}>{WORKLOAD[k].label}</button>
                  );
                })}
              </Row>
              {/* fields */}
              <Row gap={8} align="stretch">
                <Field label="region" value={svc.region} onChange={(v) => setSvc({ region: v })} />
                <Field label={isContainer ? "image" : "build cmd"} value={svc.build} onChange={(v) => setSvc({ build: v })} />
                {isContainer
                  ? <Field label="runtime" value={svc.runtime} onChange={(v) => setSvc({ runtime: v })} />
                  : <Field label="output dir" value={svc.output} onChange={(v) => setSvc({ output: v })} />}
              </Row>

              {/* containerization & orchestration */}
              <Box pad={[11, 12]} bg={isContainer ? "color-mix(in oklch, var(--violet), transparent 95%)" : "var(--bg-canvas)"} radius="md" style={{
                marginTop: 11,
                border: "1px solid " + (isContainer ? "color-mix(in oklch, var(--violet), transparent 80%)" : "var(--border-soft)"),
              }}>
                <Row gap={7} style={{ marginBottom: isContainer ? 10 : 0 }}>
                  <Text size={11} style={{ color: isContainer ? "var(--violet)" : "var(--fg-dim)" }}>⬢</Text>
                  <Text mono size={9.5} style={{ color: "var(--fg)" }}>Containerization &amp; orchestration</Text>
                  <Spacer />
                  {isContainer
                    ? <Box as="span" style={{ ...chip, fontSize: 7.5, color: "var(--violet)", borderColor: "color-mix(in oklch, var(--violet), transparent 72%)", background: "color-mix(in oklch, var(--violet), transparent 86%)" }}>distributed</Box>
                    : <Box as="span" style={{ ...chip, fontSize: 7.5 }}>{WORKLOAD[svc.workload].label}</Box>}
                </Row>
                {isContainer ? (
                  <>
                    <Grid cols={2} gap={8} style={{ marginBottom: 10 }}>
                      <Stack gap={4}>
                        <Text as="span" style={grpLabel}>engine · image</Text>
                        <Box as="span" pad={[5, 8]} bg="var(--bg-elev)" border="soft" radius="sm" style={{ fontFamily: MONO, fontSize: 10, color: "var(--fg)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>Docker · {svc.runtime && svc.runtime !== "—" ? svc.runtime : "base image"}</Box>
                      </Stack>
                      <Field label="image registry" value={svc.registry ?? (svc.repo ? `ghcr.io/${svc.repo}` : "")} onChange={(v) => setSvc({ registry: v })} />
                    </Grid>
                    <Row gap={8} style={{ marginBottom: 9 }}>
                      <Text as="span" style={{ ...grpLabel, flex: "0 0 62px" }}>orchestrator</Text>
                      <Seg value={svc.orchestrator ?? "k8s"} options={ORCHESTRATORS.map((o) => o.id)} onChange={(v) => setSvc({ orchestrator: v })} />
                    </Row>
                    <Row gap={8}>
                      <Text as="span" style={{ ...grpLabel, flex: "0 0 62px" }}>replicas</Text>
                      <Seg value={svc.replicas ?? "3"} options={REPLICA_OPTIONS} onChange={(v) => setSvc({ replicas: v })} />
                      <Spacer />
                      <Text mono size={8} tone="dim">nodes share the workload</Text>
                    </Row>
                  </>
                ) : (
                  <Row gap={9} style={{ marginTop: 9 }}>
                    <Text mono size={9} tone="dim" style={{ lineHeight: 1.45, flex: 1 }}>
                      Not containerized — this <b style={{ color: "var(--fg-muted)" }}>{WORKLOAD[svc.workload].label}</b> service deploys without a container image or orchestrator.
                    </Text>
                    {canContainerize && (
                      // eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled pill CTA button; Button/.btn would change rendering
                      <button onClick={() => setSvc({ workload: "container" })} style={{
                        fontFamily: MONO, fontSize: 8.5, color: "var(--violet)", padding: "4px 10px", borderRadius: 99, cursor: "pointer", whiteSpace: "nowrap", flex: "0 0 auto",
                        background: "color-mix(in oklch, var(--violet), transparent 88%)", border: "1px solid color-mix(in oklch, var(--violet), transparent 72%)",
                      }}>containerize →</button>
                    )}
                  </Row>
                )}
              </Box>
            </>
          ) : (
            <Row gap={8} style={{ marginTop: 13, border: "1px dashed color-mix(in oklch, var(--accent), transparent 60%)", borderRadius: "var(--r-md)", padding: "11px 13px", fontFamily: MONO, fontSize: 10, color: "var(--accent)", background: "color-mix(in oklch, var(--accent), transparent 93%)" }}>
              <Text>↑</Text><Text>no target for <b>{svc.id}</b> yet — choose a platform from the list above</Text>
            </Row>
          )}
    </>
  );
}

/** Local body (#1192) — a Library (publish to a registry) or an Application (build + run here),
 *  with an optional port-forward for a locally-running app. No cloud-host / region fields. */
function LocalBody({ svc, setSvc }: { svc: DeployService; setSvc: (patch: Partial<DeployService>) => void }) {
  const kind: LocalKind = svc.localKind ?? "application";
  const pf = svc.portForward ?? { enabled: false, port: "", method: "cloudflared" as PortForwardMethod };
  const setPf = (patch: Partial<typeof pf>) => setSvc({ portForward: { ...pf, ...patch } });
  return (
    <>
      {/* Kind sub-toggle */}
      <Text as="div" style={{ ...grpLabel, marginBottom: 8 }}>kind</Text>
      <Box style={{ marginBottom: 11 }}>
        <Seg<LocalKind> value={kind} options={["library", "application"] as const}
          onChange={(v) => setSvc({ localKind: v, proposed: false })} />
      </Box>

      {kind === "library" ? (
        <>
          <Row gap={8} align="stretch" style={{ marginBottom: 9 }}>
            <Select label="publish registry" value={svc.publishRegistry ?? ""} options={PUBLISH_REGISTRIES}
              onChange={(v) => setSvc({ publishRegistry: v as PublishRegistry })} />
            <Field label="package name" value={svc.packageName ?? ""} onChange={(v) => setSvc({ packageName: v })} />
          </Row>
          <Row gap={8} align="stretch">
            <Field label="build cmd" value={svc.build === "—" ? "" : svc.build} onChange={(v) => setSvc({ build: v })} />
            <Select label="publish trigger" value={svc.publishTrigger ?? ""} options={PUBLISH_TRIGGERS}
              onChange={(v) => setSvc({ publishTrigger: v as PublishTrigger })} />
          </Row>
        </>
      ) : (
        <>
          <Row gap={8} align="stretch" style={{ marginBottom: 9 }}>
            <Field label="build target(s)" value={svc.buildTargets ?? ""} onChange={(v) => setSvc({ buildTargets: v })} />
            <Field label="build cmd" value={svc.build === "—" ? "" : svc.build} onChange={(v) => setSvc({ build: v })} />
          </Row>
          <Row gap={8} align="stretch">
            <Field label="output artifact" value={svc.artifact ?? ""} onChange={(v) => setSvc({ artifact: v })} />
            <Field label="run command" value={svc.runCmd ?? ""} onChange={(v) => setSvc({ runCmd: v })} />
          </Row>

          {/* Port forwarding — expose a locally-running app remotely */}
          <Box pad={[11, 12]} bg={pf.enabled ? "color-mix(in oklch, var(--info), transparent 94%)" : "var(--bg-canvas)"} radius="md" style={{
            marginTop: 11,
            border: "1px solid " + (pf.enabled ? "color-mix(in oklch, var(--info), transparent 78%)" : "var(--border-soft)"),
          }}>
            <Toggle on={pf.enabled} onClick={() => setPf({ enabled: !pf.enabled })}
              label="Port forwarding" value={pf.enabled ? `:${pf.port || "NNNN"} via ${pf.method}` : "expose this app remotely"} />
            {pf.enabled && (
              <Row gap={8} align="stretch" style={{ marginTop: 10 }}>
                <Field label="port" value={pf.port} onChange={(v) => setPf({ port: v })} />
                <Select label="method" value={pf.method} options={PORT_FORWARD_METHODS}
                  onChange={(v) => setPf({ method: v as PortForwardMethod })} />
              </Row>
            )}
          </Box>
        </>
      )}
    </>
  );
}

/** The selected service's target editor (#1192): host/stack meta + the cloud·local mode toggle +
 *  the Cloud or Local body. Extracted (#1399) so the merged Repositories & Deployment pane can
 *  expand it inline under each repo, while the standalone Deploy stage keeps its service tabs. */
export function ServiceTargetEditor({ svc, setSvc }: {
  svc: DeployService; setSvc: (patch: Partial<DeployService>) => void;
}) {
  const mode: DeployMode = serviceMode(svc);
  const targeted = serviceTargetDefined(svc);
  // Collapsed-header summary of the chosen target (platform / local kind), or a prompt when unset.
  const targetHint = targeted
    ? (mode === "local" ? (svc.localKind ?? "local") : (platform(svc.platform).name || "target set"))
    : "not set";
  return (
    <>
      {/* selected service meta — bare identity line (#1421 follow-up, 1a): what this repo IS, not a
          config field, so it stays above the numbered cards rather than inside one. */}
      <Row gap={7} wrap>
        {(() => { const h = hostMeta(svc.host); return (
          <Box as="span" style={{ ...chip, display: "inline-flex", alignItems: "center", gap: 5, color: h.color }}>
            <Box as="span" bg={h.color} radius={99} style={{ width: 6, height: 6}} />{h.domain}
          </Box>
        ); })()}
        {hostMeta(svc.host).kind !== "cloud" && (
          <Box as="span" style={{ ...chip, color: "var(--violet)", borderColor: "color-mix(in oklch, var(--violet), transparent 72%)", background: "color-mix(in oklch, var(--violet), transparent 86%)" }}>self-hosted</Box>
        )}
        <Box as="span" style={{ ...chip, color: "var(--info)" }}>⎇ {svc.repo || "—"}/{svc.path}</Box>
        <Box as="span" style={chip}>{svc.stack}</Box>
        <Spacer />
        {svc.proposed && <Box as="span" style={prop}>✦ proposed</Box>}
      </Row>

      {/* 01 · Target & build — mode + platform/region/build (+ containerization for cloud). Starts
          open only while no target is set, so an unconfigured repo surfaces the picker immediately. */}
      <Card n="01" title="Target & build" hint={targetHint} done={targeted} defaultOpen={!targeted}>
        {/* Cloud · Local mode toggle (#1192) */}
        <Row gap={9} style={{ marginBottom: 12 }}>
          <Text as="span" style={grpLabel}>mode</Text>
          <Seg<DeployMode> value={mode} options={["cloud", "local"] as const}
            onChange={(v) => setSvc({ mode: v, proposed: false })} />
          <Spacer />
          <Text mono size={8.5} tone="dim">
            {mode === "cloud" ? "ships to a hosted platform" : "a library or a build-and-run-here app"}
          </Text>
        </Row>

        {mode === "cloud" ? <CloudBody svc={svc} setSvc={setSvc} /> : <LocalBody svc={svc} setSvc={setSvc} />}
      </Card>
    </>
  );
}

