// The focused MCP Servers stage (#878, split from FocusedBodies.tsx #1757): the project's MCP
// servers as one expandable card each — transport + install status, an enable toggle, the launch
// command, and the fleet scope it's granted to. A first-party server downloads on assign; its
// "build" button runs the toolchain build (uv/pnpm) before the fleet can use it. An enabled,
// project-scoped server reaches the director AND every worker.
import { useState } from "react";
import { useExpandable } from "@/shared/hooks/useExpandable";
import type { McpServer } from "@/features/planner/pane/projectPaneData";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Code } from "@/shared/ui/data/Code";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import type { McpHandlers } from "./focusedHandlers";

const MCP_TRANSPORT: Record<string, { c: string; label: string }> = {
  stdio: { c: "oklch(0.72 0.10 230)", label: "stdio" },
  http:  { c: "oklch(0.80 0.14 70)",  label: "http" },
};
const MCP_STATUS: Record<McpServer["status"], { c: string; dot: string; label: string }> = {
  ready:       { c: "var(--success)", dot: "on",   label: "ready" },
  downloaded:  { c: "var(--fg-muted)", dot: "idle", label: "downloaded · build to run" },
  available:   { c: "var(--fg-dim)",  dot: "idle", label: "available · download to run" },
  downloading: { c: "var(--info)",    dot: "run",  label: "downloading…" },
  building:    { c: "var(--info)",    dot: "run",  label: "building…" },
  error:       { c: "var(--danger)",  dot: "",     label: "build failed" },
};

export function McpsBody({ servers, onToggle, onBuild, onAdd, onRemove }: McpHandlers & {
  servers?: McpServer[];
}) {
  const list = servers ?? [];
  const { open, toggle: toggleOpen } = useExpandable();
  const [draft, setDraft] = useState("");

  const ready = list.filter((s) => s.enabled && s.status === "ready").length;
  const errored = list.filter((s) => s.enabled && s.status === "error").length;
  const busy = (s: McpServer) => s.status === "downloading" || s.status === "building";

  const tile = (v: React.ReactNode, k: string, c?: string) => (
    <Box pad={[8, 11]} bg="var(--bg-canvas)" border="soft" radius={8} style={{ flex: 1}}>
      <Text as="div" mono size={18} weight={600} style={{ color: c ?? "var(--fg)" }}>{v}</Text>
      <Box className="mono" style={{ fontSize: 9, color: "var(--fg-dim)", textTransform: "uppercase", letterSpacing: ".05em", marginTop: 1 }}>{k}</Box>
    </Box>
  );

  return (
    <Stack gap={12}>
      <Row gap={8} align="stretch">
        {tile(<>{ready}<Text as="span" size={11} tone="dim"> / {list.length}</Text></>, "ready", "var(--success)")}
        {tile(list.filter((s) => s.enabled).length, "enabled")}
        {tile(errored, errored === 1 ? "needs attention" : "need attention", errored ? "var(--danger)" : undefined)}
      </Row>

      {list.length === 0 && (
        <EmptyState iconVariant="dashed" icon="⊕" title="No MCP servers yet — assign one below or have the planner add it" />
      )}

      <Stack gap={8}>
        {list.map((s) => {
          const tr = MCP_TRANSPORT[s.transport] ?? MCP_TRANSPORT.stdio;
          const stat = MCP_STATUS[s.status];
          const isOpen = open.has(s.id);
          const isErr = s.enabled && s.status === "error";
          return (
            <Box key={s.id} bg="var(--bg-canvas)" radius={9} style={{ overflow: "hidden",
              border: "1px solid " + (isErr ? "color-mix(in oklch, var(--danger), transparent 60%)" : isOpen ? "var(--border)" : "var(--border-soft)"),
              opacity: s.enabled ? 1 : 0.72,
            }}>
              <Row gap={10} style={{ padding: "10px 12px" }}>
                <Box as="span" className="mono" radius={6} style={{
                  width: 24, height: 24, display: "grid", placeItems: "center", flex: "0 0 24px",
                  fontSize: 12, color: tr.c,
                  border: `1px solid color-mix(in oklch, ${tr.c}, transparent 55%)`,
                }}>{(s.name[0] ?? "?").toUpperCase()}</Box>
                <Stack gap={3} onClick={() => toggleOpen(s.id)} style={{ flex: 1, minWidth: 0, cursor: "pointer" }}>
                  <Row gap={7}>
                    <Box as="span" className="mono-value">{s.name}</Box>
                    {s.official && <Text as="span" className="chip" size={8}>official</Text>}
                    {!s.official && s.downloadable && <Text as="span" className="chip" size={8}>first-party</Text>}
                    <Text as="span" className="chip" size={8} style={{ color: tr.c, borderColor: `color-mix(in oklch, ${tr.c}, transparent 70%)` }}>{tr.label}</Text>
                  </Row>
                  {s.desc && <Box as="span" className="mono" style={{ fontSize: 9.5, color: "var(--fg-dim)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{s.desc}</Box>}
                </Stack>
                <Stack align="end" gap={5}>
                  <Row gap={5}>
                    <Box as="span" className={"sdot " + stat.dot} style={s.status === "error" ? { background: "var(--danger)" } : undefined} />
                    <Text as="span" mono size={9.5} style={{ color: stat.c }}>{stat.label}</Text>
                  </Row>
                  <Box as="span" className={"toggle" + (s.enabled ? " on" : "")} title={s.enabled ? "granted to the fleet" : "disabled"} onClick={() => onToggle?.(s.id)} />
                </Stack>
              </Row>

              {isErr && s.err && (
                <Row gap={7} style={{ padding: "0 12px 10px" }}>
                  <Text as="span" mono size={9.5} tone="danger">⚠ {s.err}</Text>
                  <Spacer />
                  {/* eslint-disable-next-line no-restricted-syntax -- bespoke `.mini` button, not a `.btn`-family control */}
                  <button className="mini" onClick={() => onBuild?.(s)}>retry build</button>
                </Row>
              )}

              {isOpen && (
                <Box style={{ padding: "10px 12px 12px", borderTop: "1px solid var(--border-soft)" }}>
                  <Text as="div" mono size={9} tone="dim" style={{ marginBottom: 4 }}>command</Text>
                  <Code style={{
                    background: "var(--bg-elev)", borderRadius: 6, padding: "6px 9px",
                    marginBottom: 11, whiteSpace: "nowrap",
                  }}><Text as="span" tone="accent">$ </Text>{s.cmd || "—"}</Code>

                  <Text as="div" mono size={9} tone="dim" style={{ marginBottom: 6 }}>scope · {s.scope}</Text>
                  {s.agents.length > 0 ? (
                    <Row gap={6} wrap align="stretch" style={{ marginBottom: 11 }}>
                      {s.agents.map((id) => (
                        <Box as="span" key={id} className="mono" pad={[2, 8]} bg="var(--bg-elev)" border="soft" radius={99} style={{ fontSize: 9.5, color: "var(--fg)"}}>@{id}</Box>
                      ))}
                    </Row>
                  ) : (
                    <Text as="div" mono size={9.5} tone="dim" style={{ marginBottom: 11 }}>not wired yet — enable to grant the fleet access</Text>
                  )}

                  <Row gap={7} align="stretch">
                    {s.downloadable && s.status !== "ready" && (
                      // eslint-disable-next-line no-restricted-syntax -- bespoke `.mini accent` button, not a `.btn`-family control
                      <button className="mini accent" disabled={busy(s)} onClick={() => onBuild?.(s)}>
                        {s.status === "downloading" ? "downloading…" : s.status === "building" ? "building…" : s.status === "available" ? "download + build" : "build"}
                      </button>
                    )}
                    <Spacer />
                    {/* eslint-disable-next-line no-restricted-syntax -- bespoke `.mini` button, not a `.btn`-family control */}
                    <button className="mini" onClick={() => onRemove?.(s.id)}>remove</button>
                  </Row>
                </Box>
              )}
            </Box>
          );
        })}
      </Stack>

      <Row gap={7} align="stretch">
        {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline add-row input (flex Row + Enter handler); TextField's .field wrapper would change layout */}
        <input
          className="input"
          placeholder="＋ add an MCP server — catalog name, command, or remote URL"
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter" && draft.trim()) { onAdd?.(draft.trim()); setDraft(""); } }}
          style={{ flex: 1, height: 28, fontSize: 10.5 }}
        />
        {/* eslint-disable-next-line no-restricted-syntax -- bespoke `.mini accent` button, not a `.btn`-family control */}
        <button className="mini accent" disabled={!draft.trim()} onClick={() => { if (draft.trim()) { onAdd?.(draft.trim()); setDraft(""); } }}>add</button>
      </Row>
    </Stack>
  );
}

// Repositories & Deployment — the merged "Deployment" stage pane (#1399), rebuilt to the per-repo
// card design (#1421, design/Claude design_ deployment section/Deployment.dc.html). The Default
// blueprint folds Deploy INTO Repos (#1383), so THIS is the deployment surface every project lands
// on — it must BE the design. One collapsible RepoDeployCard per repo, with the repo's git identity
// (branch · ahead/behind · language · agents · visibility) folded into the card's collapsed row and
// its full ship plan (target & build · pipeline · environments · config & secrets · rollout) inside.
// The header carries the "N of M repos deploy-ready" counter; the project-wide locked dependency
// manifest follows as a tail (it gates separately, #1127).
//
// Controlled — reads a DeployConfig + the linked repos and calls onDeployChange / onLinkRepo /
// per-repo visibility. Reuses RepoDeployCard + ServiceDeploySections from DeployView (one design,
// shared with the standalone Deploy stage), so there's no header gate/ship pill (#1403).

import { useState } from "react";
import { type DeployConfig, type DeployService } from "../lib/deployConfig";
import { RepoDeployCard } from "./DeployView";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import type { Repo } from "../pane/projectPane.types";

const MONO = "var(--mono)";

/** A stream avatar — initial + a deterministic hue from the stream id (agents are arbitrary stream
 *  ids here, not the design's fixed roster). */
function Avatar({ id, sz = 16 }: { id: string; sz?: number }) {
  let hue = 0;
  for (let i = 0; i < id.length; i++) hue = (hue * 31 + id.charCodeAt(i)) % 360;
  return (
    <Box as="span" bg={`oklch(0.7 0.13 ${hue})`} radius={99} style={{
      width: sz, height: sz, color: "#0b0d10",
      fontFamily: MONO, fontSize: sz * 0.5, fontWeight: 700, display: "inline-flex", alignItems: "center",
      justifyContent: "center", border: "1.5px solid var(--bg-canvas)",
    }}>{(id[0] ?? "?").toUpperCase()}</Box>
  );
}

export function DeploymentBody({
  repos, deploy, onDeployChange, onLinkRepo,
}: {
  repos?: Repo[];
  deploy?: DeployConfig;
  onDeployChange?: (next: DeployConfig) => void;
  onLinkRepo?: (r: string) => void;
}) {
  const [linking, setLinking] = useState(false);
  const [linkInput, setLinkInput] = useState("");
  // Which repo's deploy-target editor is expanded — `null` = all collapsed, the initial state (#1403).
  // Clicking a repo toggles its own editor; opening one also points `selService` at it so the tail
  // pipeline's final-stage label reflects the repo being edited.
  const [openRepo, setOpenRepo] = useState<string | null>(null);
  const list = repos ?? [];
  const d = deploy;

  const set = (patch: Partial<DeployConfig>) => d && onDeployChange?.({ ...d, ...patch });
  const serviceForRepo = (repoId: string) => d?.services.find((s) => s.repo === repoId);
  const setSvcFor = (svcId: string, patch: Partial<DeployService>) =>
    d && set({ services: d.services.map((s) => (s.id === svcId ? { ...s, ...patch } : s)) });

  // ── link affordance ──
  const submitLink = () => { const v = linkInput.trim(); if (v.includes("/")) { onLinkRepo?.(v); setLinkInput(""); setLinking(false); } };
  const linkAffordance = onLinkRepo && (
    linking ? (
      <Row gap={6}>
        {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled input in a flex link row; TextField's .field wrapper would change layout */}
        <input
          // eslint-disable-next-line jsx-a11y/no-autofocus -- intentional: focus the repo-link field when it opens
          autoFocus aria-label="Link a repository" value={linkInput} placeholder="owner/repo"
          onChange={(e) => setLinkInput(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter") submitLink(); else if (e.key === "Escape") { setLinking(false); setLinkInput(""); } }}
          style={{ flex: 1, height: 26, padding: "0 8px", borderRadius: 6, background: "var(--bg-canvas)", border: "1px solid var(--border-soft)", color: "var(--fg)", fontFamily: MONO, fontSize: 10, outline: "none" }}
        />
        {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled button (custom accent/height); Button/.btn would change rendering */}
        <button disabled={!linkInput.includes("/")} onClick={submitLink} style={{
          height: 26, padding: "0 11px", borderRadius: 6, border: "1px solid var(--accent-dim)",
          background: linkInput.includes("/") ? "var(--accent)" : "var(--bg-elev)", color: linkInput.includes("/") ? "#0b0d10" : "var(--fg-dim)",
          fontFamily: MONO, fontSize: 9.5, cursor: "pointer",
        }}>link</button>
        {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled button (custom mono/height); Button/.btn would change rendering */}
        <button onClick={() => { setLinking(false); setLinkInput(""); }} style={{ height: 26, padding: "0 10px", borderRadius: 6, border: "1px solid var(--border-soft)", background: "transparent", color: "var(--fg-muted)", fontFamily: MONO, fontSize: 9.5, cursor: "pointer" }}>cancel</button>
      </Row>
    ) : (
      // eslint-disable-next-line no-restricted-syntax -- bespoke full-width dashed "add" affordance (not a `.btn`); Button would change rendering
      <button type="button" onClick={() => setLinking(true)} style={{
        width: "100%", border: "1px dashed var(--border)", borderRadius: 8, padding: 14, display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
        background: "transparent", color: "var(--fg-dim)", fontFamily: MONO, fontSize: 10.5, cursor: "pointer",
      }}>＋ link another repository</button>
    )
  );

  // ── per-repo git identity shown in the collapsed card row (ahead/behind · language · agents) ──
  const repoMeta = (r: Repo) => (
    <>
      {(r.ahead > 0 || r.behind > 0) && (
        <Text as="span" mono size={8.5}>
          {r.ahead > 0 && <Text as="span" tone="success">↑{r.ahead} </Text>}
          {r.behind > 0 && <Text as="span" style={{ color: "var(--info)" }}>↓{r.behind}</Text>}
        </Text>
      )}
      {r.lang && <Box as="span" pad={[1, 7]} bg="var(--bg-elev2)" border="soft" radius={99} style={{ fontFamily: MONO, fontSize: 8, color: "var(--fg-muted)"}}>{r.lang}</Box>}
      {r.agents.length > 0 && (
        <Box as="span" style={{ display: "inline-flex", alignItems: "center" }}>
          {r.agents.map((id, i) => <Box as="span" key={id} style={{ marginLeft: i ? -5 : 0 }}><Avatar id={id} sz={14} /></Box>)}
        </Box>
      )}
    </>
  );

  // The focused pane's phase header already titles this stage (+ gate pill), so the body renders no
  // header of its own (#1430 follow-up) — just the per-repo cards.
  const total = list.length;

  // ── body — one per-repo card (RepoDeployCard) with the repo's git identity folded into its row;
  //    each repo is a self-contained deployable unit (#1421). Project-wide locked deps as a tail. ──
  let body: React.ReactNode;
  if (total === 0) {
    body = (
      <>
        <Stack align="center" gap={12} style={{ border: "1px dashed var(--border)", borderRadius: "var(--r-lg)", padding: "40px 24px", textAlign: "center", background: "var(--bg-canvas)" }}>
          <Text as="span" size={26} style={{ opacity: 0.5 }}>⎇</Text>
          <Text as="span" size={13} weight={600} style={{ fontFamily: "var(--sans)", color: "var(--fg)" }}>No repositories linked</Text>
          <Text as="span" mono size={10.5} tone="muted" style={{ maxWidth: 380, lineHeight: 1.6 }}>Deployment is configured per repository — each repo carries its own pipeline, environments and secrets. Link one to define how it ships.</Text>
        </Stack>
        {linkAffordance}
      </>
    );
  } else {
    body = (
      <>
        <Stack gap={9}>
          {list.map((r) => {
            const svc = serviceForRepo(r.id);
            if (!svc) {
              // A linked repo whose deploy service isn't seeded yet (config out of sync) — show its
              // identity so it's not dropped; the service seeds when the plan is next saved.
              return (
                <Row key={r.id} gap={9} style={{ background: "var(--bg-elev)", border: "1px solid var(--border-soft)", borderRadius: "var(--r-lg)", padding: "11px 13px" }}>
                  <Box as="span" bg={r.cloned ? "var(--success)" : "var(--fg-dim)"} radius={99} style={{ width: 7, height: 7, flex: "0 0 7px"}} />
                  <Text as="span" mono size={12} style={{ color: "var(--fg)" }}>{r.id}</Text>
                  {repoMeta(r)}
                  <Spacer />
                  <Text as="span" mono size={8.5} tone="dim">deploy seeds on save</Text>
                </Row>
              );
            }
            return (
              <RepoDeployCard
                key={r.id}
                svc={svc}
                setSvc={(patch) => setSvcFor(svc.id, patch)}
                open={openRepo === r.id}
                onToggle={() => setOpenRepo(openRepo === r.id ? null : r.id)}
                meta={repoMeta(r)}
              />
            );
          })}
          {linkAffordance}
        </Stack>
      </>
    );
  }

  return (
    <Stack gap={12}>
      {body}
    </Stack>
  );
}

runtime.features/planner/bodies/ScanViews.tsx:
// ScanViews — the scanned-result visualizations for the Source stage (#1209).
// One read-only scan, three ways to read it: a Graph of the inferred Data Model (entities +
// fields + ref edges), a dense List, and a Process view of the captured behaviors (business
// processes, automations by kind, derived logic). Renders the view-model from sourceConfig.ts
// (scanEntities / scanEdges / aggregatePlatform) — i.e. the derived model (#1205) + the structured
// behavior scan (#1209 backend). Hi-fi implementation of design/Source connection pane kickoff
// "Source Scan Views".

import { useMemo, useState } from "react";
import { useExpandable } from "@/shared/hooks/useExpandable";
import {
  scanEntities, scanEdges, aggregatePlatform, isMultiSource, downstreamImpact,
  type SourceConfig, type ScanViewEntity, type ScanViewField,
  type ScanAutomation, type ScanAutomationKind,
} from "../lib/sourceConfig";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

const MONO = "var(--mono)";
type View = "graph" | "list" | "process";

const grpLabel: React.CSSProperties = {
  fontFamily: MONO, fontSize: 10, color: "var(--fg-dim)", textTransform: "uppercase", letterSpacing: ".08em",
};

/** A field's type chip — ref / enum distinctive; everything else a calm plain chip. */
function TypeChip({ f }: { f: ScanViewField }) {
  if (f.type === "ref") {
    return <Box as="span" style={chip("var(--info)")}>→ {f.refLabel ?? f.ref}</Box>;
  }
  if (f.type === "enum") return <Box as="span" style={chip("var(--violet)")}>enum</Box>;
  return (
    <Box as="span" pad={[1, 6]} bg="var(--bg-elev2)" border="soft" radius={99} style={{ fontFamily: MONO, fontSize: 8.5, color: "var(--fg-muted)"}}>
      {f.type}
    </Box>
  );
}
function chip(color: string): React.CSSProperties {
  return {
    fontFamily: MONO, fontSize: 8.5, color, whiteSpace: "nowrap",
    background: `color-mix(in oklab, ${color}, transparent 88%)`,
    border: `1px solid color-mix(in oklab, ${color}, transparent 76%)`,
    borderRadius: 99, padding: "1px 6px",
  };
}

/** Segmented Graph · List · Process toggle. */
function Toggle({ view, onView, small }: { view: View; onView: (v: View) => void; small?: boolean }) {
  const fs = small ? 11.5 : 12;
  const items: [View, string][] = [["graph", "⬡ Graph"], ["list", "≣ List"], ["process", "⤳ Process"]];
  return (
    <Box pad={3} bg="var(--bg-elev)" border="soft" radius="md" style={{ display: "inline-flex", gap: 2, flex: "none" }}>
      {items.map(([v, label]) => {
        const on = v === view;
        return (
          <Box as="span" key={v} data-testid={`scan-view-${v}`} onClick={() => onView(v)} bg={on ? "var(--bg-elev2)" : "transparent"} radius="sm" style={{
            padding: small ? "4px 10px" : "5px 12px", fontSize: fs, cursor: "pointer",
            fontWeight: on ? 600 : 400, color: on ? "var(--fg)" : "var(--fg-dim)",
          }}>{label}</Box>
        );
      })}
    </Box>
  );
}

// ── Graph view ──────────────────────────────────────────────────────────────────────────────
const NODE_W = 216;

function nodeHeight(e: ScanViewEntity, multi: boolean): number {
  return 34 + (multi ? 22 : 0) + e.fields.length * 27 + 2;
}

function Graph({ entities, multi }: { entities: ScanViewEntity[]; multi: boolean }) {
  const edges = useMemo(() => scanEdges(entities), [entities]);
  const layout = useMemo(() => {
    const incoming = new Map<string, number>();
    edges.forEach((e) => incoming.set(e.to, (incoming.get(e.to) ?? 0) + 1));
    let hub = entities[0];
    let best = -1;
    for (const e of entities) {
      const c = incoming.get(e.key) ?? 0;
      if (c > best) { best = c; hub = e; }
    }
    const sats = entities.filter((e) => e.key !== hub.key);
    const GAP = 18, TOP = 20, LEFTX = 24, RIGHTX = 24 + NODE_W + 150;
    const boxes = new Map<string, { x: number; y: number; w: number; h: number }>();
    let y = TOP;
    for (const s of sats) {
      const h = nodeHeight(s, multi);
      boxes.set(s.key, { x: RIGHTX, y, w: NODE_W, h });
      y += h + GAP;
    }
    const rightTotal = Math.max(y - GAP, TOP);
    const hubH = nodeHeight(hub, multi);
    boxes.set(hub.key, { x: LEFTX, y: Math.max(TOP, TOP + (rightTotal - TOP - hubH) / 2), w: NODE_W, h: hubH });
    const width = RIGHTX + NODE_W + 24;
    const height = Math.max(rightTotal, boxes.get(hub.key)!.y + hubH) + 24;
    return { boxes, hubKey: hub.key, width, height };
  }, [entities, edges, multi]);

  const edgePath = (aKey: string, bKey: string) => {
    const a = layout.boxes.get(aKey)!;
    const b = layout.boxes.get(bKey)!;
    const goesRight = b.x >= a.x;
    const sx = a.x + (goesRight ? a.w : 0), sy = a.y + a.h / 2;
    const tx = b.x + (goesRight ? 0 : b.w), ty = b.y + b.h / 2;
    const mx = (sx + tx) / 2;
    return { d: `M${sx},${sy} C${mx},${sy} ${mx},${ty} ${tx},${ty}`, lx: mx, ly: (sy + ty) / 2, label: "" };
  };

  return (
    <Box bg="radial-gradient(circle at 1px 1px, var(--bg-elev) 1px, transparent 0) 0 0 / 22px 22px, var(--bg-canvas)" style={{ position: "relative", overflow: "auto", maxHeight: 560}}>
      <Box style={{ position: "relative", width: layout.width, height: layout.height }}>
        {/* type legend */}
        <Row gap={6} style={{ position: "absolute", top: 10, left: 10, zIndex: 5, background: "var(--bg-panel)", border: "1px solid var(--border-soft)", borderRadius: "var(--r-md)", padding: "5px 9px" }}>
          <Text mono size={8.5} tone="dim" style={{ letterSpacing: ".06em" }}>TYPES</Text>
          <Box as="span" style={chip("var(--info)")}>ref</Box>
          <Box as="span" style={chip("var(--violet)")}>enum</Box>
          <Box as="span" pad={[1, 6]} bg="var(--bg-elev2)" border="soft" radius={99} style={{ fontFamily: MONO, fontSize: 8.5, color: "var(--fg-muted)"}}>string</Box>
          <Text mono size={8.5} tone="success">🔑 identity</Text>
        </Row>

        {/* edges */}
        <svg style={{ position: "absolute", inset: 0, width: "100%", height: "100%", overflow: "visible", pointerEvents: "none" }}>
          <defs>
            <marker id="sv-arrow" markerWidth="9" markerHeight="9" refX="6.5" refY="3" orient="auto">
              <path d="M0,0 L6.5,3 L0,6 Z" fill="var(--info)" />
            </marker>
          </defs>
          {edges.map((e, i) => {
            const p = edgePath(e.from, e.to);
            return <path key={i} d={p.d} fill="none" stroke="var(--info)" strokeWidth={1.5} markerEnd="url(#sv-arrow)" opacity={0.6} />;
          })}
        </svg>
        {edges.map((e, i) => {
          const p = edgePath(e.from, e.to);
          return (
            <Box key={i} style={{ position: "absolute", left: p.lx - 40, top: p.ly - 8, width: 80, textAlign: "center", fontFamily: MONO, fontSize: 9, color: "var(--info)", pointerEvents: "none" }}>
              <Box as="span" pad={[1, 5]} bg="var(--bg-canvas)" radius="sm">{e.label}</Box>
            </Box>
          );
        })}

        {/* nodes */}
        {entities.map((e) => {
          const box = layout.boxes.get(e.key)!;
          const isHub = e.key === layout.hubKey;
          return (
            <Box key={e.key} data-testid={`scan-node-${e.key}`} bg="var(--bg-panel)" radius="lg" style={{
              position: "absolute", left: box.x, top: box.y, width: NODE_W, border: `1px solid ${isHub ? "var(--info)" : "var(--border-soft)"}`, overflow: "hidden",
              boxShadow: isHub ? "0 0 0 4px color-mix(in oklab, var(--info), transparent 92%)" : undefined,
            }}>
              <Row gap={8} style={{ padding: "9px 11px", background: "var(--bg-elev)", borderBottom: "1px solid var(--border-soft)", borderLeft: `3px solid ${e.srcColor}` }}>
                <Box as="span" style={{ fontSize: 13, fontWeight: 600, flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{e.label}</Box>
                <Text mono size={9} tone="dim">{e.count.toLocaleString()}</Text>
              </Row>
              {multi && e.source && (
                <Row gap={5} style={{ padding: "4px 11px", borderBottom: "1px solid var(--border-soft)" }}>
                  <Box as="span" bg={e.srcColor} radius={99} style={{ width: 6, height: 6}} />
                  <Text mono size={8.5} tone="dim">{e.source}</Text>
                </Row>
              )}
              {e.fields.map((f) => (
                <Row key={f.key} gap={7} style={{ padding: "5px 11px", borderTop: "1px solid var(--border-soft)" }}>
                  {f.identity && <Text size={9} tone="success">🔑</Text>}
                  <Box as="span" style={{ fontFamily: MONO, fontSize: 10.5, color: "var(--fg)", flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{f.key}</Box>
                  <TypeChip f={f} />
                </Row>
              ))}
            </Box>
          );
        })}
      </Box>
    </Box>
  );
}

// ── List view ───────────────────────────────────────────────────────────────────────────────
function List({ entities, multi }: { entities: ScanViewEntity[]; multi: boolean }) {
  const { open, toggle } = useExpandable(entities.slice(0, 2).map((e) => e.key));
  return (
    <Stack gap={8} style={{ padding: "12px 14px 14px" }}>
      {entities.map((e) => {
        const expanded = open.has(e.key);
        const oneliner = `${e.fields.length} fields · ` + e.fields.slice(0, 4).map((f) => f.key + (f.identity ? "🔑" : "") + (f.ref ? `→${f.refLabel ?? f.ref}` : "")).join(", ");
        return (
          <Box key={e.key} data-testid={`scan-list-${e.key}`} bg="var(--bg-panel)" border="soft" radius="lg" style={{ overflow: "hidden" }}>
            <Row onClick={() => toggle(e.key)} gap={9} style={{ padding: "9px 12px", background: "var(--bg-elev)", cursor: "pointer" }}>
              <Text tone="dim" size={10}>{expanded ? "▾" : "▸"}</Text>
              <Text size={13} weight={600}>{e.label}</Text>
              <Text mono size={9.5} tone="dim">{e.key}</Text>
              <Spacer />
              <Text mono size={9.5} tone="muted">{e.count.toLocaleString()} rows · {e.fields.length} fields</Text>
              {multi && e.source && (
                <Box as="span" pad={[2, 7]} bg="var(--bg-elev2)" border="soft" radius={99} style={{ display: "inline-flex", alignItems: "center", gap: 5, fontFamily: MONO, fontSize: 9, color: "var(--fg-muted)"}}>
                  <Box as="span" bg={e.srcColor} radius={99} style={{ width: 6, height: 6}} />{e.source}
                </Box>
              )}
            </Row>
            {expanded ? (
              <Stack>
                {e.fields.map((f) => (
                  <Row key={f.key} gap={9} style={{ padding: "6px 12px", borderTop: "1px solid var(--border-soft)" }}>
                    <Box as="span" style={{ width: 14, textAlign: "center" }}>{f.identity && <Text size={9} tone="success">🔑</Text>}</Box>
                    <Text mono size={11} style={{ color: "var(--fg)", minWidth: 128 }}>{f.key}</Text>
                    {f.type === "ref" ? <Box as="span" style={chip("var(--info)")}>ref → {f.refLabel ?? f.ref}</Box> : f.type === "enum" ? <Box as="span" style={chip("var(--violet)")}>enum{f.enumValues && f.enumValues.length ? ` · ${f.enumValues.join(" · ")}` : ""}</Box> : (
                      <Box as="span" pad={[1, 6]} bg="var(--bg-elev2)" border="soft" radius={99} style={{ fontFamily: MONO, fontSize: 8.5, color: "var(--fg-muted)"}}>{f.type}</Box>
                    )}
                    <Spacer />
                    {f.required && <Text mono size={8.5} tone="accent">required</Text>}
                  </Row>
                ))}
              </Stack>
            ) : (
              <Box pad={[7, 12]} style={{ borderTop: "1px solid var(--border-soft)", fontFamily: MONO, fontSize: 10, color: "var(--fg-dim)", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{oneliner}</Box>
            )}
          </Box>
        );
      })}
    </Stack>
  );
}

// ── Process view ────────────────────────────────────────────────────────────────────────────
const KIND_LABEL: Record<ScanAutomationKind, string> = {
  validation: "Validation", workflow: "Workflow", flow: "Flow", processBuilder: "Process Builder", recurring: "Recurring", other: "Other",
};
const KIND_ORDER: ScanAutomationKind[] = ["validation", "workflow", "flow", "processBuilder", "recurring", "other"];

function Process({ cfg, multi }: { cfg: SourceConfig; multi: boolean }) {
  const p = useMemo(() => aggregatePlatform(cfg), [cfg]);
  const groups = useMemo(() => {
    const by = new Map<ScanAutomationKind, ScanAutomation[]>();
    for (const a of p.automations) { const arr = by.get(a.kind) ?? []; arr.push(a); by.set(a.kind, arr); }
    return KIND_ORDER.filter((k) => by.has(k)).map((k) => ({ kind: k, legacy: k === "processBuilder", items: by.get(k)! }));
  }, [p]);
  const empty = p.businessProcesses.length === 0 && p.automations.length === 0 && p.derivedLogic.length === 0;
  if (empty) {
    return <Text as="div" size={12} tone="dim" style={{ padding: "20px 16px" }}>No automations, processes, or derived logic captured for this source.</Text>;
  }
  return (
    <Stack gap={16} style={{ padding: "13px 16px 16px" }}>
      {p.businessProcesses.length > 0 && (
        <Stack gap={9}>
          <Text as="div" style={grpLabel}>business processes</Text>
          {p.businessProcesses.map((bp, i) => (
            <Stack key={i} gap={10} style={{ background: "var(--bg-panel)", border: "1px solid var(--border-soft)", borderRadius: "var(--r-lg)", padding: 12 }}>
              <Row gap={9} wrap>
                <Text size={13} weight={600}>{bp.name}</Text>
                <Text mono size={9} tone="dim">on {bp.object || "—"}</Text>
                <Box as="span" style={chip(bp.active ? "var(--success)" : "var(--fg-dim)")}>{bp.active ? "active" : "inactive"}</Box>
                <Spacer />
                {multi && <SrcBadge source={bp.source} />}
              </Row>
              <Row gap={7} wrap>
                {bp.steps.map((s, j) => (
                  <Box as="span" key={j} style={{ display: "inline-flex", alignItems: "center", gap: 7 }}>
                    <Box as="span" pad={[5, 11]} bg="var(--bg-elev2)" border="soft" radius="md" style={{ fontFamily: MONO, fontSize: 11, color: "var(--fg)"}}>{s}</Box>
                    {j < bp.steps.length - 1 && <Text tone="dim" size={12}>→</Text>}
                  </Box>
                ))}
              </Row>
            </Stack>
          ))}
        </Stack>
      )}

      {groups.length > 0 && (
        <Stack gap={9}>
          <Text as="div" style={grpLabel}>automations · by kind</Text>
          {groups.map((g) => (
            <Stack key={g.kind} gap={7}>
              <Row gap={8}>
                <Box as="span" style={chip("var(--accent)")}>{KIND_LABEL[g.kind]}</Box>
                {g.legacy && <Box as="span" style={chip("var(--danger)")}>⚠ legacy · migrate this</Box>}
              </Row>
              {g.items.map((a, i) => (
                <Stack key={i} gap={8} style={{ background: "var(--bg-elev)", border: "1px solid var(--border-soft)", borderRadius: "var(--r-md)", padding: "9px 11px" }}>
                  <Row gap={8} wrap>
                    <Text size={12} weight={500}>{a.name}</Text>
                    {a.object && <Text mono size={9} tone="dim">on {a.object}</Text>}
                    <Spacer />
                    {multi && <SrcBadge source={a.source} />}
                  </Row>
                  <Row gap={7} wrap>
                    {a.trigger && <><Text mono size={9} tone="dim">trigger</Text><Tok>{a.trigger}</Tok><Arr /></>}
                    {a.condition && <><Text mono size={9} tone="dim">if</Text><Tok>{a.condition}</Tok><Arr /></>}
                    {a.actions.map((ac, j) => (
                      <Box as="span" key={j} pad={[3, 8]} bg="color-mix(in oklab, var(--accent), transparent 90%)" radius="sm" style={{ fontFamily: MONO, fontSize: 10, color: "var(--accent)", border: "1px solid color-mix(in oklab, var(--accent), transparent 80%)"}}>{ac}</Box>
                    ))}
                  </Row>
                </Stack>
              ))}
            </Stack>
          ))}
        </Stack>
      )}

      {p.derivedLogic.length > 0 && (
        <Stack gap={9}>
          <Text as="div" style={grpLabel}>derived logic</Text>
          {p.derivedLogic.map((d, i) => (
            <Stack key={i} gap={7} style={{ background: "var(--bg-elev)", border: "1px solid var(--border-soft)", borderRadius: "var(--r-md)", padding: "9px 11px" }}>
              <Row gap={8} wrap>
                <Box as="span" style={chip("var(--violet)")}>{d.kind}</Box>
                <Text mono size={11} style={{ color: "var(--fg)" }}>{d.name}</Text>
                {d.object && <Text mono size={9} tone="dim">on {d.object}</Text>}
                <Spacer />
                {multi && <SrcBadge source={d.source} />}
              </Row>
              {d.expression && <Box pad={[7, 10]} bg="var(--bg-canvas)" border="soft" radius="sm" style={{ fontFamily: MONO, fontSize: 11, color: "var(--fg-muted)", overflowX: "auto" }}>{d.expression}</Box>}
            </Stack>
          ))}
        </Stack>
      )}
    </Stack>
  );
}
function Tok({ children }: { children: React.ReactNode }) {
  return <Box as="span" pad={[3, 8]} bg="var(--bg-elev2)" border="soft" radius="sm" style={{ fontFamily: MONO, fontSize: 10, color: "var(--fg)"}}>{children}</Box>;
}
function Arr() { return <Text tone="dim">→</Text>; }
function SrcBadge({ source }: { source: string }) {
  if (!source) return null;
  return (
    <Box as="span" style={{ display: "inline-flex", alignItems: "center", gap: 5, fontFamily: MONO, fontSize: 9, color: "var(--fg-muted)" }}>
      <Box as="span" bg="var(--fg-dim)" radius={99} style={{ width: 6, height: 6}} />{source}
    </Box>
  );
}

// ── main ────────────────────────────────────────────────────────────────────────────────────
export function ScanViews({ cfg, dataModelName, version = 1 }: { cfg: SourceConfig; dataModelName: string; version?: number }) {
  const entities = useMemo(() => scanEntities(cfg), [cfg]);
  const multi = useMemo(() => isMultiSource(cfg), [cfg]);
  const impact = useMemo(() => downstreamImpact(cfg), [cfg]);
  const [view, setView] = useState<View>(entities.length > 6 ? "list" : "graph");

  if (entities.length === 0) return null;

  return (
    <Box data-testid="scan-views" bg="var(--bg-panel)" border="soft" radius="lg" style={{ overflow: "hidden" }}>
      {/* recap header + toggle */}
      <Row justify="between" gap={14} style={{ padding: "12px 14px", borderBottom: "1px solid var(--border-soft)" }}>
        <Stack gap={4} style={{ minWidth: 0 }}>
          <Row gap={8}>
            <Text size={14} weight={600}>Scanned result</Text>
            <Box as="span" style={chip("var(--success)")}>READ-ONLY</Box>
          </Row>
          <Text as="div" size={11.5} tone="muted" style={{ lineHeight: 1.4 }}>
            <Text mono size={10.5} style={{ color: "var(--violet)" }}>⬡ {dataModelName} · v{version}</Text>
            {" · "}seeds <b style={{ color: "var(--fg)" }}>{impact.entities} {impact.entities === 1 ? "entity" : "entities"} · {impact.fields} fields</b> into features + structure
            {impact.behaviors > 0 && <> · <b style={{ color: "var(--fg)" }}>{impact.behaviors} behaviors</b> carried over</>}
          </Text>
        </Stack>
        <Toggle view={view} onView={setView} />
      </Row>

      {view === "graph" && <Graph entities={entities} multi={multi} />}
      {view === "list" && <List entities={entities} multi={multi} />}
      {view === "process" && <Process cfg={cfg} multi={multi} />}
    </Box>
  );
}

runtime.features/planner/bodies/SharedDependenci:
// Shared dependencies — the FOCUSED stream's slice of the per-repo → per-stream dependency surface
// (#1429 / #2191). Formerly a fleet-wide section listing every shared repo; now scoped to the one
// focused stream and shown inside its inspector card stack (StreamFocusCards). For the focused
// stream it answers: is my repo shared (built by 2+ streams), with WHICH other streams, and what deps
// do *I* declare (with the cross-stream version-locks) + the repo's registries. A single-owner repo
// gets a one-line note (deps stay agent-managed). Pure presentational — reads the fleet streams
// (data.agents) + the locked manifest (dependencies + registries) and computes via
// sharedRepoDependencies(). Design: design/Streams Pane Redesign/Streams Pane.dc.html.

import {
  sharedRepoDependencies, type PlanDependency, type DependencyRegistry, type StreamDependency,
} from "../issues/dependencies";
import type { Agent } from "../pane/projectPane.types";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Chip } from "@/shared/ui/data/Chip";

const MONO = "var(--mono)";
const NPM = "#cb3837";
const ecoColor = (eco: string) => (eco === "cargo" ? "var(--warn)" : NPM);

/** A small dynamic-colour badge — delegates to the shared <Chip> (its `color` path) so the
 *  translucent color-mix pill styling lives in the shared primitive, not hand-rolled here. */
function pill(text: string, color: string, opts: { fs?: number; tint?: number } = {}) {
  const t = opts.tint ?? 86;
  return (
    <Chip color={color} radius={4} padding="2px 6px" fontSize={opts.fs ?? 8.5}
      bgAlpha={t} borderAlpha={t - 14} style={{ fontWeight: 600, whiteSpace: "nowrap" }}>
      {text}
    </Chip>
  );
}

/** One declared dependency + the cross-stream version-lock it participates in. */
function DepRow({ d, registries }: { d: StreamDependency; registries: Record<string, DependencyRegistry> }) {
  const isPrivate = !!(d.source && registries[d.source]);
  const verColor = d.version ? "var(--fg-dim)" : "var(--warn)";
  const ecoC = isPrivate ? "var(--violet)" : ecoColor(d.ecosystem);
  return (
    <Row align="baseline" gap={8}>
      <Chip color={ecoC} radius={4} padding="2px 5px" fontSize={8} bgAlpha={84} borderAlpha={70} style={{ flexShrink: 0, fontWeight: 600 }}>{d.ecosystem}</Chip>
      <Box style={{ flex: 1, minWidth: 0 }}>
        <Text mono weight={600} size={10.5} style={{ color: "var(--fg)" }}>{d.name}</Text>
        <Text mono weight={500} size={10.5} style={{ color: verColor }}>{d.version ? `@${d.version}` : "@latest"}</Text>
        {d.sharedWith.length > 0 && <Box as="span" style={{ marginLeft: 6 }}>{pill(`↔ shared · ${d.sharedWith.join(", ")}`, "var(--success)")}</Box>}
        {isPrivate && <Box as="span" style={{ marginLeft: 6 }}>{pill("private", "var(--violet)")}</Box>}
        {d.dev && <Box as="span" style={{ marginLeft: 6 }}>{pill("dev", "var(--violet)")}</Box>}
        {d.why && <Text as="div" weight={500} size={9.5} tone="dim" style={{ fontFamily: "var(--sans)", marginTop: 1 }}>{d.why}</Text>}
      </Box>
    </Row>
  );
}

/** The focused stream's shared-dependency slice (#2191). Rendered inside the stream inspector's
 *  "Shared dependencies" card. `a` is the focused stream; `agents` is the whole fleet (to detect which
 *  streams share the repo); `dependencies` + `registries` are the locked manifest. */
export function StreamSharedDeps({ a, agents = [], dependencies = [], registries = {} }: {
  a: Agent;
  agents?: Agent[];
  dependencies?: PlanDependency[];
  registries?: Record<string, DependencyRegistry>;
}) {
  // repo → the streams building it (from the fleet), keyed the same way sharedRepoDependencies expects.
  const repoStreams: Record<string, string[]> = {};
  for (const s of agents) { if (s.repo) (repoStreams[s.repo] ??= []).push(s.id ?? s.name); }
  const nameOf = (id: string) => agents.find((x) => (x.id ?? x.name) === id)?.name ?? id;

  const view = sharedRepoDependencies(dependencies, registries, repoStreams).find((v) => v.repo === a.repo);

  // Single-owner (or unbuilt) repo — nothing to reconcile; this stream owns its deps outright.
  if (!view) {
    return (
      <Row gap={7} style={{ padding: "8px 10px", background: "var(--bg-elev)", border: "1px solid var(--border-soft)", borderRadius: 7 }}>
        <Text mono size={11} tone="dim">◴</Text>
        <Text mono weight={500} size={9.5} tone="dim">
          {a.repo ? `${a.repo} is yours alone — its deps stay agent-managed.` : "No repo assigned to this stream."}
        </Text>
      </Row>
    );
  }

  const me = a.id ?? a.name;
  const others = view.streams.filter((s) => s !== me).map(nameOf);
  const mine = view.byStream.find((g) => g.stream === me);

  return (
    <Stack gap={11}>
      {/* which repo, and who this stream shares it with */}
      <Row gap={8} wrap align="baseline">
        <Text mono weight={600} size={11} style={{ color: "var(--fg)" }}>{view.repo}</Text>
        <Box as="span" pad={[2, 6]} bg="var(--bg-elev2)" border radius={4} style={{ fontFamily: MONO, fontWeight: 500, fontSize: 9, color: "var(--fg-muted)" }}>{view.streams.length} streams</Box>
        {others.length > 0 && <Text mono weight={500} size={9.5} tone="dim">shared with {others.join(", ")}</Text>}
      </Row>

      {/* registries the repo's deps reference */}
      {view.registries.length > 0 && (
        <Row wrap gap={6} align="center">
          <Text mono weight={600} size={8} tone="dim" style={{ letterSpacing: ".08em", textTransform: "uppercase" }}>registries</Text>
          {view.registries.map((g) => g.private
            ? <Box as="span" key={g.key}>{pill(`${g.url} · ${g.scope ?? ""} · auth ${g.auth ?? "—"}`, "var(--violet)", { tint: 86 })}</Box>
            : <Box as="span" key={g.key}>{pill(`${g.name} · public`, NPM, { tint: 88 })}</Box>)}
        </Row>
      )}

      {/* THIS stream's declared deps (or the orchestrator/empty note) */}
      {!mine || mine.empty ? (
        <Text as="div" mono weight={500} size={9.5} tone="dim" style={{ lineHeight: 1.5 }}>
          No build deps of your own — you hold the reconciled lock for this repo.
        </Text>
      ) : (
        <Stack gap={8} style={{ paddingLeft: 12, borderLeft: `1px solid color-mix(in oklch, ${a.color ?? "var(--accent)"}, transparent 80%)` }}>
          {mine.deps.map((d, j) => <DepRow key={d.name + j} d={d} registries={registries} />)}
        </Stack>
      )}

      <Text as="div" weight={500} size={9.5} tone="dim" style={{ fontFamily: "var(--sans)", lineHeight: 1.5 }}>
        Per-stream deps reconcile into the repo's single <Text mono tone="muted">package.json</Text> / <Text mono tone="muted">Cargo.toml</Text> and are inlined into every agent on the repo.
      </Text>
    </Stack>
  );
}

runtime.features/planner/bodies/sourceConnection:
// sourceConnection — the per-source connection state machine for SourceBody (#1637).
//
// Split out of SourceBody.tsx: the `useSourceConnection` hook owns the per-source lifecycle
// (declared → connecting → scanning → scanned / error), the OAuth browser-flow launch + completion
// listen, the live read-only scan (with sample-shape fallback), and the secret-masking local state.
// It is the ONLY home for the invoke/listen calls that drive a source forward; the presentational
// card lives in connectorForm.tsx and the container in SourceBody.tsx.
//
// SECURITY BOUNDARY: a secret's value lives ONLY in `secrets` (local React state) and is saved to
// the OS keychain on connect — it is NEVER written into the persisted SourceConfig and never shared
// with the planning agent, which sees only a redacted handle + the discovered object inventory.

import { useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { safeInvoke, fireInvoke } from "@/shared/lib/core/safeInvoke";
import { listen } from "@tauri-apps/api/event";
import { openUrl } from "@tauri-apps/plugin-opener";
import { useAppStore } from "@/store";
import {
  connector, redactedHandle, sampleScan,
  type SourceConfig, type DeclaredSource, type DiscoveredField, type PlatformScanView,
} from "../lib/sourceConfig";

export interface SourceConnection {
  /** Secret field values — LOCAL ONLY, keyed by source uid → field key. Never persisted. */
  secrets: Record<string, Record<string, string>>;
  /** Source uids whose secret field is currently revealed (un-masked). */
  revealed: Set<string>;
  /** Patch one source by uid, reading the latest config from the store (safe across timeouts). */
  patchSource: (uid: string, patch: Partial<DeclaredSource>) => void;
  /** Update a non-secret field value (persisted into the source's config). */
  setField: (uid: string, key: string, v: string) => void;
  /** Update a secret field value (local only). */
  setSecret: (uid: string, key: string, v: string) => void;
  /** Toggle the reveal state of a source's secret field. */
  toggleReveal: (uid: string) => void;
  /** Connect a source — OAuth flow or save-secrets-then-scan for credential connectors. */
  connect: (uid: string) => void;
  /** Reset an errored source back to declared so the user can retry. */
  retry: (uid: string) => void;
  /** Revoke a source's on-device secrets (called when the source is removed, #1194). */
  revokeSecrets: (uid: string) => void;
}

/**
 * The per-source connection state machine + secret-masking state for the Source body.
 *
 * @param pid     the project key (store + keychain scope)
 * @param cfg     the current SourceConfig (the render-time snapshot the actions close over)
 * @param persist writes a new SourceConfig back to the store
 */
export function useSourceConnection(
  pid: string,
  cfg: SourceConfig,
  persist: (next: SourceConfig) => void,
): SourceConnection {
  const [revealed, setRevealed] = useState<Set<string>>(new Set());
  // Secret field values — LOCAL ONLY, keyed by source uid → field key. Never persisted.
  const [secrets, setSecrets] = useState<Record<string, Record<string, string>>>({});

  // Patch one source by uid, reading the latest config from the store (safe across timeouts).
  const patchSource = (uid: string, patch: Partial<DeclaredSource>) => {
    const latest = useAppStore.getState().planSourceConfig[pid] ?? cfg;
    persist({ ...latest, sources: latest.sources.map((s) => (s.uid === uid ? { ...s, ...patch } : s)) });
  };

  function setField(uid: string, key: string, v: string) {
    patchSource(uid, { fields: { ...(cfg.sources.find((s) => s.uid === uid)?.fields ?? {}), [key]: v } });
  }
  function setSecret(uid: string, key: string, v: string) {
    setSecrets((p) => ({ ...p, [uid]: { ...(p[uid] ?? {}), [key]: v } }));
  }
  function toggleReveal(uid: string) {
    setRevealed((p) => { const n = new Set(p); if (n.has(uid)) n.delete(uid); else n.add(uid); return n; });
  }

  function revokeSecrets(uid: string) {
    // Revoke any on-device secrets for this source's connector fields (#1194).
    const src = cfg.sources.find((s) => s.uid === uid);
    if (src) {
      for (const f of connector(src.connectorId).spec.fields) {
        if (f.secret) fireInvoke("source_delete_secret", { project: pid, sourceUid: uid, field: f.key });
      }
    }
  }

  // Run the live read-only scan; on a non-live result or error, fall back to the sample shape so
  // the pane stays demonstrable until every connector's live transport / OAuth app is in place.
  async function runScan(uid: string, connectorId: string, fields: Record<string, string>, fallbackHandle: string) {
    try {
      const res = await invoke<{ live: boolean; instance?: string; handle?: string; objects?: { name: string; count: number; fields?: DiscoveredField[] }[]; behaviors?: { label: string }[]; platform?: PlatformScanView }>(
        "data_platform_scan",
        { connectorId, project: pid, sourceUid: uid, fields },
      );
      if (res?.live) {
        patchSource(uid, {
          status: "scanned",
          handle: res.handle || fallbackHandle,
          ...(res.instance ? { instance: res.instance } : {}),
          objects: res.objects ?? [],
          behaviors: res.behaviors ?? [],
          platform: res.platform,
        });
        return;
      }
    } catch { /* fall through to the sample shape */ }
    const scan = sampleScan(connectorId);
    patchSource(uid, { status: "scanned", objects: scan.objects, behaviors: scan.behaviors });
  }

  // OAuth connect: kick off the browser authorization-code flow, then scan once the token lands in
  // the keychain. If OAuth isn't configured (no client id) the begin call returns no URL and we
  // degrade to the sample shape so the pane still works.
  function oauthConnect(uid: string, src: DeclaredSource, c: ReturnType<typeof connector>) {
    const fallbackHandle = redactedHandle({ ...src, instance: src.instance || c.name });
    patchSource(uid, { status: "connecting" });
    void (async () => {
      let begin: { authorizeUrl?: string } | null = null;
      try {
        begin = await invoke<{ authorizeUrl: string }>("source_oauth_begin", {
          connectorId: src.connectorId, project: pid, sourceUid: uid, env: src.env ?? "production",
        });
      } catch { /* not configured / unavailable */ }
      if (!begin?.authorizeUrl) {
        patchSource(uid, { status: "scanning", secretSaved: false, handle: fallbackHandle, instance: src.instance || c.name });
        void runScan(uid, src.connectorId, { ...(src.fields ?? {}) }, fallbackHandle);
        return;
      }
      await openUrl(begin.authorizeUrl).catch(() => {});
      const unlisten = await listen<{ sourceUid: string; ok: boolean; instance?: string; realm?: string; error?: string }>(
        "source-oauth-complete",
        (ev) => {
          const p = ev.payload;
          if (p.sourceUid !== uid) return;
          unlisten();
          if (!p.ok) { patchSource(uid, { status: "error", error: p.error ?? "authorization failed" }); return; }
          // Capture non-secret instance metadata into the config (the token stays in the keychain).
          const fields = { ...(useAppStore.getState().planSourceConfig[pid]?.sources.find((s) => s.uid === uid)?.fields ?? {}) };
          if (p.instance) fields.instanceUrl = p.instance;
          if (p.realm) fields.realm = p.realm;
          const handle = redactedHandle({ ...src, instance: p.instance || c.name });
          patchSource(uid, { status: "scanning", secretSaved: true, instance: p.instance || c.name, handle, fields });
          void runScan(uid, src.connectorId, fields, handle);
        },
      );
    })();
  }

  // Connect: OAuth connectors run the browser flow; credential connectors save each secret to the
  // OS keychain (#1194) — it leaves component state for the device's secure store, never written to
  // the config or shared with the planner — then scan.
  function connect(uid: string) {
    const src = cfg.sources.find((s) => s.uid === uid);
    if (!src) return;
    const c = connector(src.connectorId);
    if (c.spec.auth === "oauth") { oauthConnect(uid, src, c); return; }

    const fallbackHandle = redactedHandle({ ...src, instance: src.instance || c.name });
    const fieldsSnapshot = { ...(src.fields ?? {}) };
    const draft = secrets[uid] ?? {};
    const saved = Object.entries(draft).filter(([, v]) => v.trim());
    const saves = saved.map(([field, value]) =>
      safeInvoke("source_save_secret", { project: pid, sourceUid: uid, field, value }, undefined)
    );

    patchSource(uid, { status: "connecting" });
    // Drop the local secret draft — it's on the device keychain now, never re-shown.
    setSecrets((p) => { const n = { ...p }; delete n[uid]; return n; });
    setRevealed((p) => { const n = new Set(p); n.delete(uid); return n; });

    void Promise.all(saves).then(() => {
      patchSource(uid, { status: "scanning", secretSaved: saved.length > 0, handle: fallbackHandle, instance: src.instance || c.name });
      void runScan(uid, src.connectorId, fieldsSnapshot, fallbackHandle);
    });
  }
  function retry(uid: string) {
    patchSource(uid, { status: "declared", error: undefined });
  }

  return { secrets, revealed, patchSource, setField, setSecret, toggleReveal, connect, retry, revokeSecrets };
}

runtime.features/planner/bodies/StreamFocusCards:
// StreamFocusCards (#2189) — the focused stream rebuilt as a stack of collapsible cards (the
// "Streams Pane Redesign"). Replaces the monolithic StreamCard/AgentEditor with one CollapsibleCard
// each for Persona · Kickoff · Scope · Model & flow. Persona + Kickoff are default-open (they were
// buried before), and the persona pairing is ALWAYS shown — "Worker (default)" when a stream launches
// with no persona assigned. Uses the app's abstracted primitives (CollapsibleCard, Seg, Chip, Code,
// SelectField, RoleChip) + the #2186 PersonaSummary (rendered flat inside the Persona card).
import { useState } from "react";
import type { Flow, Agent } from "@/features/planner/pane/projectPaneData";
import { type ModelId, modelTier, tierToModelId } from "@/app/console/lib/models";
import { CollapsibleCard } from "./collapsibleCard";
import { StreamSharedDeps } from "./SharedDependencies";
import type { PlanDependency, DependencyRegistry } from "@/features/planner/issues/dependencies";
import { RoleChip, Seg } from "@/features/planner/pane/focusedPrimitives";
import { PersonaSummary } from "@/features/personas";
import { Chip } from "@/shared/ui/data/Chip";
import { Code } from "@/shared/ui/data/Code";
import { SelectField } from "@/shared/ui/controls/Field";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { SectionLabel } from "@/shared/ui/layout/SectionLabel";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";
import { useAppStore } from "@/store";

export function StreamFocusCards({ a, agents, dependencies, registries, onFlow, onModel, onPersona }: {
  a: Agent;
  /** The whole fleet — used to compute the focused stream's shared-dependency slice (#2191). */
  agents?: Agent[];
  dependencies?: PlanDependency[];
  registries?: Record<string, DependencyRegistry>;
  onFlow?: (streamId: string, flow: Flow) => void;
  onModel?: (streamId: string, model: ModelId | undefined) => void;
  onPersona?: (streamId: string, personaId: string | undefined) => void;
}) {
  const personas = useAppStore((s) => s.personas);
  const assigned = personas.find((p) => p.id === a.persona);
  // Unassigned ⇒ display the packaged Worker persona so the pairing is never blank; the header still
  // reads "Worker (default)" and the picker value stays "" so nothing is written onto the stream.
  const display = assigned ?? personas.find((p) => p.id === "persona-worker");

  // Local echo of model/flow, resynced when the focused stream changes — adjusted DURING render
  // (React's recommended alternative to a sync effect), which also avoids a set-state-in-effect lint.
  const [flow, setFlow] = useState<Flow>(a.flow);
  const [model, setModel] = useState<ModelId | undefined>(a.model);
  const [lastId, setLastId] = useState(a.id);
  if (a.id !== lastId) { setLastId(a.id); setFlow(a.flow); setModel(a.model); }

  const personaName = assigned ? assigned.name : "Worker (default)";
  const personaRole = display?.role ?? "worker";

  return (
    <Stack gap={12} style={{ marginTop: 14 }}>
      {/* PERSONA — the behavioral identity this stream launches as. */}
      <CollapsibleCard
        title="Persona"
        icon="☺"
        defaultOpen
        right={
          <Row gap={7} align="center">
            <Text as="span" size={11} tone="muted">{personaName}</Text>
            <RoleChip role={personaRole} mute />
          </Row>
        }
      >
        <Stack gap={12}>
          {onPersona && (
            <SelectField
              label="launches as"
              hint="the role sets the permission floor"
              value={a.persona ?? ""}
              onChange={(v) => onPersona(a.id, v || undefined)}
            >
              <option value="">worker (default)</option>
              {personas.map((p) => <option key={p.id} value={p.id}>{p.name} · {p.role}</option>)}
            </SelectField>
          )}
          {display && <PersonaSummary persona={display} flat />}
        </Stack>
      </CollapsibleCard>

      {/* KICKOFF — the exact first message the worker receives at launch (the hero card). */}
      <CollapsibleCard
        title="Kickoff"
        icon="➤"
        iconTone="var(--accent)"
        defaultOpen
        right={a.authoredPrompt ? <Chip color="var(--accent)">authored</Chip> : <Chip>generated</Chip>}
      >
        <Stack gap={11}>
          {a.authoredPrompt && (
            <Text as="div" mono size={10} tone="muted" style={{ lineHeight: 1.5 }}>
              Launches from an authored kickoff script — <Box as="span" className="glob">{a.authoredPrompt}</Box>. The generated default below is the fallback.
            </Text>
          )}
          <Code>{a.kickoff}</Code>
          <details>
            <summary className="mono" style={{ cursor: "pointer", fontSize: 10, color: "var(--fg-dim)", userSelect: "none" }}>
              Lane context — CLAUDE.local.md
            </summary>
            <Code style={{ marginTop: 6 }}>{a.scope}</Code>
          </details>
        </Stack>
      </CollapsibleCard>

      {/* SCOPE — repo · owned globs · issues. */}
      <CollapsibleCard title="Scope" icon="⎇" right={<Text as="span" mono size={9.5} tone="dim">{a.repo}</Text>}>
        <Row className="mono" gap={6} wrap style={{ fontSize: 9.5, color: "var(--fg-muted)" }}>
          <Text as="span" style={{ color: "var(--info)" }}>⎇ {a.repo}</Text>
          <Text as="span" tone="dim">·</Text>
          <Box as="span">owns</Box>
          {a.owns.map((o) => <Box as="span" key={o} className="glob">{o}</Box>)}
          {a.issues.map((i) => <Text as="span" key={i} tone="accent">{i}</Text>)}
        </Row>
      </CollapsibleCard>

      {/* SHARED DEPENDENCIES — this stream's slice: is its repo shared, with whom, and the deps it
          declares. Only meaningful with a fleet of 2+ streams (sharing is impossible with one). */}
      {(agents?.length ?? 0) >= 2 && (
        <CollapsibleCard title="Shared dependencies" icon="⇄">
          <StreamSharedDeps a={a} agents={agents} dependencies={dependencies} registries={registries} />
        </CollapsibleCard>
      )}

      {/* MODEL & FLOW — the per-stream launch knobs. */}
      <CollapsibleCard
        title="Model & flow"
        icon="⚙"
        right={<Text as="span" mono size={9.5} tone="dim">{model ? modelTier(model) : "default model"} · {flow.autonomy}</Text>}
      >
        <Stack gap={14}>
          <Stack gap={6}>
            <SectionLabel size={9.5}>model</SectionLabel>
            <Row gap={8} align="center">
              <Seg
                options={["default", "haiku", "sonnet", "opus"]}
                value={model ? modelTier(model) : "default"}
                onChange={(v) => { const m = v === "default" ? undefined : tierToModelId(v); setModel(m); onModel?.(a.id, m); }}
              />
              <Text as="span" mono size={9} tone="dim">
                {model ? `claude --model ${modelTier(model)}` : "uses the global default"}
              </Text>
            </Row>
          </Stack>
          <Stack gap={9}>
            <SectionLabel size={9.5}>flow</SectionLabel>
            <Row gap={8} align="center">
              <Text as="span" mono size={10} tone="muted" style={{ flex: "0 0 64px" }}>autonomy</Text>
              <Seg options={["continuous", "checkpoint", "confirm"]} value={flow.autonomy}
                onChange={(v) => { const next = { ...flow, autonomy: v }; setFlow(next); onFlow?.(a.id, next); }} />
            </Row>
            <Row gap={8} align="center">
              <Text as="span" mono size={10} tone="muted" style={{ flex: "0 0 64px" }}>push</Text>
              <Seg options={["auto-PR", "push-confirm", "commit-only", "none"]} value={flow.push}
                onChange={(v) => { const next = { ...flow, push: v }; setFlow(next); onFlow?.(a.id, next); }} />
            </Row>
            <Row gap={8} align="center">
              <Text as="span" mono size={10} tone="muted" style={{ flex: "0 0 64px" }}>gate</Text>
              <Seg options={["soft", "hard"]} value={flow.gate}
                onChange={(v) => { const next = { ...flow, gate: v }; setFlow(next); onFlow?.(a.id, next); }} />
              <Text as="span" mono size={9} tone="dim">
                {flow.gate === "hard" ? "blocks on violation" : "warns, continues"}
              </Text>
            </Row>
          </Stack>
        </Stack>
      </CollapsibleCard>
    </Stack>
  );
}

runtime.features/planner/bodies/StreamsBody.tsx:
// The unified "Streams" stage (#1392 / #1914 / #2053 / #2189) — ONE cohesive pane built AROUND the
// dependency graph. The graph IS the fleet: every node is a stream, and because a stream and its
// worker are 1:1, selecting a node opens its inspector below — a stack of collapsible cards
// (Persona · Kickoff · Scope · Model & flow, #2189) rather than one dense card. Fleet-wide controls
// Coordination sits below as a secondary collapsible card; the focused stream's shared-dependency
// slice now lives inside its inspector (#2191). (Replaced the graph + always-open Fleet-roster +
// Coordination-card stack, which listed each stream twice.)
import { useState } from "react";
import type { ProjectPaneData } from "@/features/planner/pane/projectPaneData";
import { type RelFocus, type Topology } from "@/features/planner/relationship/relationshipGraph";
import { StreamFocusCards } from "./StreamFocusCards";
import { PlanBody } from "./FocusedPlanBody";
import { CoordinationControls } from "./FocusedPermissionsBody";
import { CollapsibleCard } from "./collapsibleCard";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import type { FleetHandlers } from "./focusedHandlers";

export function StreamsBody({ data, fleet, ...handlers }: FleetHandlers & {
  data?: ProjectPaneData;
  fleet?: boolean;
}) {
  const [focus, setFocus] = useState<RelFocus>(null);
  const focusedStream = focus?.type === "agent" ? focus.id : undefined;
  const agents = data?.agents ?? [];
  const focusedAgent = agents.find((a) => a.id === focusedStream);
  const topology = (data?.topology ?? "hybrid") as Topology;
  return (
    <>
      {/* The dependency graph — the centerpiece, always first + visible. Selecting a node focuses its
          stream (spotlight ↔ card), which opens its inspector below. */}
      <PlanBody data={data} focus={focus} onFocus={setFocus} />

      {fleet && (agents.length === 0 ? (
        <EmptyState size="sm" icon="◎" iconVariant="dashed"
          title="No fleet yet — plan the work streams first"
          style={{ flex: "none", marginTop: 18 }} />
      ) : focusedAgent ? (
        // The focused stream (1:1 with its worker) as a collapsible-card stack — persona · kickoff ·
        // scope · shared deps · model & flow.
        <StreamFocusCards
          a={focusedAgent}
          agents={agents}
          dependencies={data?.dependencies}
          registries={data?.registries}
          onFlow={handlers.onFlow}
          onModel={handlers.onModel}
          onPersona={handlers.onPersona}
        />
      ) : (
        <Text as="div" mono size={10} tone="dim" style={{ marginTop: 14, textAlign: "center", padding: "14px 0" }}>
          Select a stream in the graph to see its persona, kickoff &amp; config.
        </Text>
      ))}

      {fleet && agents.length > 0 && (
        <Stack gap={10} style={{ marginTop: 14 }}>
          {/* Fleet-wide controls — secondary to the graph, collapsible. (Shared dependencies moved
              into the focused stream's inspector, #2191.) */}
          <CollapsibleCard title="Coordination" icon="◎" hint={topology}>
            <CoordinationControls data={data} onTopology={handlers.onTopology} onDirectorDrive={handlers.onDirectorDrive} />
          </CollapsibleCard>
        </Stack>
      )}
    </>
  );
}

runtime.features/planner/bodies/TransformationsB:
// TransformationsBody — right-pane body for the "transformations" planning stage (#2509): the
// BOTTOM-UP CONFIRM QUEUE (the settled presentation model). Rows group by composition tier
// (Tier 0 · primitives → … → pages); only the CURRENT tier (the lowest with pending work) is
// actionable — higher tiers render collapsed/locked until it's confirmed, so composites are
// generated against confirmed primitives and nothing is built on unreviewed foundations. An item
// is pending or confirmed, NOTHING ELSE: the one action is Confirm (no reject/exclude — changes
// are described conversationally to the planner and the item re-presents). When a row carries a
// render `spec` it renders live through the #1852 KitRenderer (defensively — a bad spec falls
// back to a "spec present" chip, never a pane crash); a kitContribution (gap-fill) row frames that
// preview as a "Proposed component" (#2509 slice d) — the NEW component the user is deciding to
// build — vs a plain migration preview, which renders the existing kit target. Once every row is confirmed the final
// synthetic "Completed UI" card shows; signing it off is the NORMAL stage confirm in the footer.

import { Component, type ReactNode } from "react";
import { useAppStore } from "@/store";
import { bscRun } from "@/shared/lib/core/bsc";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Text } from "@/shared/ui/typography/Text";
import { Chip } from "@/shared/ui/data/Chip";
import { Button } from "@/shared/ui/controls/Button";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { KitRenderer, validateGeneralNode, type GeneralNode } from "@/shared/ui/spec";
import { Card } from "./bodyPrimitives";
import {
  tierGroups, nextPendingTier, tierLabel, specNodeCount, verbMeta, type TransformationRow,
} from "../lib/transformations";

const EMPTY_ROWS: TransformationRow[] = [];

/** Error boundary around the live spec render: a spec that VALIDATES but still crashes at render
 *  time (renderer/spec drift) degrades to the fallback chip instead of taking down the pane. */
class SpecBoundary extends Component<{ fallback: ReactNode; children?: ReactNode }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError() {
    return { failed: true };
  }
  render() {
    return this.state.failed ? this.props.fallback : this.props.children;
  }
}

/** The live component preview: validate first (the same contract `bsc ui validate` enforces),
 *  render through KitRenderer inside the boundary, and fall back to a "spec present (n nodes)"
 *  chip on ANY failure. Read-only — no bindings are wired (the planner owns edits, #2382). */
function SpecPreview({ id, spec }: { id: string; spec: object }) {
  const fallback = (
    <Box data-testid={`transformation-spec-fallback-${id}`} style={{ alignSelf: "flex-start" }}>
      <Chip tone="neutral" size="xs">spec present ({specNodeCount(spec)} nodes)</Chip>
    </Box>
  );
  if (validateGeneralNode(spec).length > 0) return fallback;
  return (
    <SpecBoundary fallback={fallback}>
      <Box data-testid={`transformation-spec-${id}`} pad={[8, 8]} bg="var(--bg-canvas)" border="soft" radius={6}>
        <KitRenderer node={spec as GeneralNode} />
      </Box>
    </SpecBoundary>
  );
}

/** One queue item: verb + title, provenance, target, delta, invariants, owns, live preview, and —
 *  when it's pending in the CURRENT tier — the single Confirm action. */
function TransformationItem({ row, actionable, onConfirm }: {
  row: TransformationRow;
  actionable: boolean;
  onConfirm: (id: string) => void;
}) {
  const evidence = row.provenance?.evidence ?? [];
  const recipe = row.provenance?.recipe;
  const confirmed = row.confirmed === true;
  return (
    <Box
      data-testid={`transformation-${row.id}`}
      pad={[8, 10]} bg="var(--bg-canvas)" border="soft" radius={6}
    >
      <Stack gap={5}>
        <Row gap={7}>
          {/* The taxonomy blurb rides as the tooltip (#2509 slice b — verb metadata is @data). */}
          <Chip tone="accent" size="xs" title={verbMeta(row.verb).blurb}>{row.verb}</Chip>
          <Text as="span" size={12} weight={600} style={{ color: "var(--fg)" }}>{row.title}</Text>
          <Spacer />
          {confirmed ? (
            <Chip tone="success" size="xs" dot>confirmed</Chip>
          ) : actionable ? (
            <Button
              size="sm" variant="primary"
              data-testid={`transformation-confirm-${row.id}`}
              onClick={() => onConfirm(row.id)}
            >
              Confirm
            </Button>
          ) : (
            <Chip tone="neutral" size="xs">pending</Chip>
          )}
        </Row>
        {(recipe || evidence.length > 0 || row.kitContribution) && (
          <Row gap={6}>
            <Text as="span" mono size={9.5} tone="dim" title={evidence.join("\n")}>
              {recipe ? `recipe: ${recipe}` : "ad hoc"}
              {evidence.length > 0 ? ` · ${evidence.length} evidence` : ""}
            </Text>
            {row.kitContribution && <Chip tone="info" size="xs">kit contribution</Chip>}
          </Row>
        )}
        <Text as="div" size={11} tone="muted" style={{ lineHeight: 1.5 }} title={(row.target.files ?? []).join("\n")}>
          {row.target.description}
        </Text>
        <Text as="div" mono size={10.5} style={{ color: "var(--fg)", lineHeight: 1.5 }}>
          Δ {row.delta}
        </Text>
        {row.invariants.length > 0 && (
          <Stack gap={2}>
            {row.invariants.map((inv, i) => (
              <Row key={i} gap={6}>
                <Text as="span" mono size={9.5} tone="dim" style={{ width: 10, flex: "0 0 auto" }}>⛨</Text>
                <Text as="span" mono size={9.5} tone="muted">{inv}</Text>
              </Row>
            ))}
          </Stack>
        )}
        {row.owns.length > 0 && (
          <Text
            as="div" mono size={9.5} tone="dim" title={row.owns.join("\n")}
            style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}
          >
            owns {row.owns.join(" · ")}
          </Text>
        )}
        {row.spec &&
          (row.kitContribution ? (
            // A gap-fill row proposes a NEW kit component — frame its live preview as a proposal
            // (distinct from a plain migration preview, which renders the EXISTING kit target).
            <Stack gap={3}>
              <Text
                as="div" mono size={9.5} tone="dim"
                data-testid={`transformation-proposed-${row.id}`}
              >
                Proposed component
              </Text>
              <SpecPreview id={row.id} spec={row.spec} />
            </Stack>
          ) : (
            <SpecPreview id={row.id} spec={row.spec} />
          ))}
      </Stack>
    </Box>
  );
}

export function TransformationsBody({ projectId }: { projectId?: string }) {
  const pid = projectId ?? "";
  const rows = useAppStore((s) => s.planTransformations[pid]) ?? EMPTY_ROWS;
  const setPlanTransformations = useAppStore((s) => s.setPlanTransformations);

  if (rows.length === 0) {
    return (
      <EmptyState
        iconVariant="dashed" icon="⇄" title="No transformations yet"
        description="The planner decomposes the modification request via bsc plan transformation add."
      />
    );
  }

  const groups = tierGroups(rows);
  const pendingTier = nextPendingTier(rows);
  const allConfirmed = pendingTier === null;
  const maxTier = groups[groups.length - 1].tier;

  // The ONE action (#2509): confirm — durable via the bsc bridge, optimistic locally (the poll's
  // change-guard preserves the flip until plan.db reflects it).
  const onConfirm = (id: string) => {
    void bscRun(pid, ["plan", "transformation", "confirm", id]);
    setPlanTransformations(pid, rows.map((r) => (r.id === id ? { ...r, confirmed: true } : r)));
  };

  return (
    <Stack gap={8}>
      {groups.map((g) => {
        const locked = pendingTier !== null && g.tier > pendingTier;
        const confirmedCount = g.rows.filter((r) => r.confirmed === true).length;
        return (
          <Box key={g.tier} data-testid={`transformation-tier-${g.tier}`}>
            <Card
              label={tierLabel(g.tier, maxTier)}
              hint={locked ? `confirm tier ${pendingTier} first` : `${confirmedCount}/${g.rows.length} confirmed`}
              accent={g.tier === pendingTier}
            >
              {locked ? (
                // Locked tier: collapsed — its items are generated against the tier below, so they
                // aren't reviewable until that foundation is confirmed.
                <Text as="div" mono size={10} tone="dim">
                  {g.rows.length} item{g.rows.length === 1 ? "" : "s"} · locked
                </Text>
              ) : (
                <Stack gap={6}>
                  {g.rows.map((row) => (
                    <TransformationItem
                      key={row.id} row={row}
                      actionable={g.tier === pendingTier}
                      onConfirm={onConfirm}
                    />
                  ))}
                </Stack>
              )}
            </Card>
          </Box>
        );
      })}

      {/* The final synthetic item: the assembled UI. Shown once every row is confirmed; signing it
          off is the NORMAL stage confirm (the footer's approve & continue) — no extra machinery. */}
      {allConfirmed && (
        <Box data-testid="transformations-complete">
          <Card label="Completed UI" accent>
            <Text as="div" size={11} tone="muted" style={{ lineHeight: 1.55 }}>
              Every tier is confirmed — the assembled UI (pages composed on the confirmed
              foundations) is ready. Approve the stage to sign off the completed UI.
            </Text>
          </Card>
        </Box>
      )}

      <Text as="div" mono size={9.5} tone="dim" style={{ lineHeight: 1.5 }}>
        Want changes? Describe them to the planner — the item re-presents.
      </Text>
    </Stack>
  );
}

runtime.features/planner/data/dataModel.ts:
// Canonical Data Model authoring (#780) — the TS side of the data-platform substrate.
//
// JSON-compatible with the Rust `bsc_data::schema` types (crates/data, #781): the same
// wire shape round-trips, so the planner / this UI author a model and the DuckDB store
// materializes it. Field names match the Rust serde output exactly (`type`, `ref`,
// `enum_values`); `id` is TS-library bookkeeping only and the Rust store ignores it
// (serde drops unknown fields).
//
// Pure (no React/Tauri) so the validation + edit transforms are unit-testable and the
// store can seed from it directly — mirrors how blueprints.ts works.
//
// SCOPE: this module owns the SHAPE (`DataModel`/`Entity`/`Field`) and the SHAPING OPS over it —
// it is NOT the canonical Data Model. The canonical model is the per-project DuckDB store in
// crates/data, reached via `bsc data model get` / `bsc data model set` (#1446); the Source pane
// derives a model from a scan (`lib/dataModelDerivation.ts`) and persists it there.
//
// The edit transforms (`addEntity` / `updateEntity` / `removeEntity` / `addField` / `updateField` /
// `removeField` / `toggleIdentity`) are the PENDING SHAPING SURFACE — the intended implementation of
// "the user shapes the derived result" — and have no UI caller yet (#3249). They are deliberately
// kept: not dead code (#3244).

export type FieldType = "string" | "number" | "bool" | "date" | "money" | "ref" | "enum";

/** Entity/field keys become SQL identifiers in the store, which whitelists exactly this
 *  shape (`ddl::quote_ident`). Surfacing it here lets the editor flag a bad key before a
 *  load would be rejected. */
export const SAFE_IDENT = /^[A-Za-z_][A-Za-z0-9_]*$/;

export interface Field {
  key: string;
  label?: string;
  type: FieldType;
  required?: boolean;
  /** Target entity key when `type === "ref"`. */
  ref?: string;
  /** Allowed values when `type === "enum"`. */
  enum_values?: string[];
  /** Declarative validation rule id, read by the quality gate (#783). */
  validate?: string;
}

export interface Entity {
  key: string;
  label?: string;
  fields: Field[];
  /** Field keys forming the natural / merge identity — used by the director to merge
   *  records across sources (#785). */
  identity: string[];
}

export interface DataModel {
  /** TS library id; ignored by the Rust store. */
  id: string;
  name: string;
  version: number;
  entities: Entity[];
}

/** A fresh, empty model. */
export function emptyDataModel(id: string, name = "Untitled model"): DataModel {
  return { id, name, version: 1, entities: [] };
}

/**
 * Structural validation, independent of any data — mirrors the Rust `DataModel::check`
 * plus identifier safety. Returns the list of problems (empty ⇒ valid) for the editor to
 * surface; a model with problems shouldn't be loaded.
 */
export function checkDataModel(m: DataModel): string[] {
  const problems: string[] = [];
  const seenEntities = new Set<string>();
  for (const e of m.entities) {
    if (!e.key.trim()) problems.push("an entity has an empty key");
    else if (!SAFE_IDENT.test(e.key)) problems.push(`entity key "${e.key}" is not a safe identifier`);
    if (seenEntities.has(e.key)) problems.push(`duplicate entity key "${e.key}"`);
    seenEntities.add(e.key);

    const seenFields = new Set<string>();
    for (const f of e.fields) {
      if (!f.key.trim()) problems.push(`${e.key}: a field has an empty key`);
      else if (!SAFE_IDENT.test(f.key)) problems.push(`${e.key}.${f.key}: not a safe identifier`);
      if (seenFields.has(f.key)) problems.push(`${e.key}: duplicate field key "${f.key}"`);
      seenFields.add(f.key);

      if (f.type === "ref") {
        if (!f.ref) problems.push(`${e.key}.${f.key}: ref field has no target entity`);
        else if (!m.entities.some((x) => x.key === f.ref)) problems.push(`${e.key}.${f.key}: ref to unknown entity "${f.ref}"`);
      }
    }
    for (const id of e.identity) {
      if (!e.fields.some((f) => f.key === id)) problems.push(`${e.key}: identity field "${id}" is not a field`);
    }
  }
  return problems;
}

// ── pure edit transforms (return a new model) ─────────────────────────────────

const mapEntity = (m: DataModel, key: string, fn: (e: Entity) => Entity): DataModel => ({
  ...m,
  entities: m.entities.map((e) => (e.key === key ? fn(e) : e)),
});

export function addEntity(m: DataModel, key: string): DataModel {
  return { ...m, entities: [...m.entities, { key, label: "", fields: [], identity: [] }] };
}

export function updateEntity(m: DataModel, key: string, patch: Partial<Pick<Entity, "key" | "label">>): DataModel {
  return mapEntity(m, key, (e) => ({ ...e, ...patch }));
}

export function removeEntity(m: DataModel, key: string): DataModel {
  return { ...m, entities: m.entities.filter((e) => e.key !== key) };
}

export function addField(m: DataModel, entityKey: string, field: Field): DataModel {
  return mapEntity(m, entityKey, (e) => ({ ...e, fields: [...e.fields, field] }));
}

export function updateField(m: DataModel, entityKey: string, fieldKey: string, patch: Partial<Field>): DataModel {
  return mapEntity(m, entityKey, (e) => ({
    ...e,
    fields: e.fields.map((f) => (f.key === fieldKey ? { ...f, ...patch } : f)),
  }));
}

export function removeField(m: DataModel, entityKey: string, fieldKey: string): DataModel {
  return mapEntity(m, entityKey, (e) => ({
    ...e,
    fields: e.fields.filter((f) => f.key !== fieldKey),
    identity: e.identity.filter((id) => id !== fieldKey),
  }));
}

/** Toggle whether a field is part of the entity's merge identity. */
export function toggleIdentity(m: DataModel, entityKey: string, fieldKey: string): DataModel {
  return mapEntity(m, entityKey, (e) => ({
    ...e,
    identity: e.identity.includes(fieldKey) ? e.identity.filter((id) => id !== fieldKey) : [...e.identity, fieldKey],
  }));
}

/** Starter library — one canonical CRM model so the page isn't empty and the wire format
 *  is demonstrated end-to-end. */
export function seedDataModels(): DataModel[] {
  return [
    {
      id: "dm-crm",
      name: "CRM Core",
      version: 1,
      entities: [
        {
          key: "account", label: "Account", identity: ["id"],
          fields: [
            { key: "id", type: "string", required: true },
            { key: "name", type: "string", required: true },
            { key: "industry", type: "string" },
            { key: "annual_revenue", type: "money" },
          ],
        },
        {
          key: "contact", label: "Contact", identity: ["id"],
          fields: [
            { key: "id", type: "string", required: true },
            { key: "full_name", type: "string", required: true },
            { key: "email", type: "string" },
            { key: "account", type: "ref", ref: "account" },
          ],
        },
      ],
    },
  ];
}

runtime.features/planner/fleet/agentFlow.ts:
// Per-agent execution flow (#297): how a planned stream behaves at runtime —
// whether it pauses for confirmation or runs continuously, and what/when it
// pushes to GitHub. Set in the planning phase, the flow drives three launch-time
// concerns: which git/gh writes auto-approve (permissions), how the kickoff's
// autonomy + push paragraph reads, and whether the agent emits a coordination
// wake at its pause points.
//
// Pure (no React/Tauri) so it can be unit-tested and shared by the planner UI,
// the tag/fleet.json parsers, and the launch path.

/** How the agent handles underspecified decisions. */
export type FlowAutonomy = "continuous" | "checkpoint" | "confirm";
/** What and whether the agent pushes to GitHub. */
export type FlowPush = "auto-pr" | "self-merge" | "push-confirm" | "commit-only" | "none";
/** Which event fires a push attempt. */
export type FlowTrigger = "per-issue" | "per-stage" | "on-green";
/** How a "confirm"/"push-confirm" pause is enforced. */
export type FlowGate = "soft" | "hard";

export interface AgentFlow {
  /** continuous = never pause; checkpoint = pause at stage/PR boundaries; confirm = ask before non-trivial decisions. */
  autonomy: FlowAutonomy;
  /** auto-pr = commit+push+open PR on green; self-merge = run full gate, rebase onto develop, re-gate, push develop directly (no PR); push-confirm = commit+test then wait; commit-only = commit, don't push; none = no git/gh. */
  push: FlowPush;
  /** When a push fires: per owned issue, per pipeline stage, or whenever the gate is green. */
  trigger: FlowTrigger;
  /** soft = kickoff instructs the agent to pause and ask; hard = the push command isn't auto-approved so the pane prompts. */
  gate: FlowGate;
}

export const FLOW_AUTONOMY: readonly FlowAutonomy[] = ["continuous", "checkpoint", "confirm"];
export const FLOW_PUSH: readonly FlowPush[] = ["auto-pr", "self-merge", "push-confirm", "commit-only", "none"];
export const FLOW_TRIGGER: readonly FlowTrigger[] = ["per-issue", "per-stage", "on-green"];
export const FLOW_GATE: readonly FlowGate[] = ["soft", "hard"];

/** The default flow a freshly-planned stream gets (confirmed with the user). */
export const DEFAULT_FLOW: AgentFlow = {
  autonomy: "continuous",
  push: "auto-pr",
  trigger: "per-issue",
  gate: "hard",
};

/** Coerce one raw value to a member of `allowed`, falling back when absent/invalid. */
function coerce<T extends string>(raw: unknown, allowed: readonly T[], fallback: T): T {
  if (typeof raw !== "string") return fallback;
  const v = raw.trim().toLowerCase();
  return (allowed as readonly string[]).includes(v) ? (v as T) : fallback;
}

/**
 * Build a complete, valid {@link AgentFlow} from arbitrary/partial input (a tag's
 * attributes or a `fleet.json` object). Every field falls back to {@link DEFAULT_FLOW},
 * so the result is always launch-safe. Unknown keys are ignored.
 */
export function normalizeFlow(input: Record<string, unknown> | null | undefined): AgentFlow {
  const o = input ?? {};
  return {
    autonomy: coerce(o.autonomy, FLOW_AUTONOMY, DEFAULT_FLOW.autonomy),
    push:     coerce(o.push,     FLOW_PUSH,     DEFAULT_FLOW.push),
    trigger:  coerce(o.trigger,  FLOW_TRIGGER,  DEFAULT_FLOW.trigger),
    gate:     coerce(o.gate,     FLOW_GATE,     DEFAULT_FLOW.gate),
  };
}

/**
 * Like {@link normalizeFlow} but returns `undefined` when the input names none of
 * the four flow fields — so a stream that never specified a flow stays `flow:
 * undefined` (the launch path applies {@link DEFAULT_FLOW}) instead of being
 * silently materialized. Preserves backward-compat for pre-flow plans.
 */
export function flowOrUndefined(input: Record<string, unknown> | null | undefined): AgentFlow | undefined {
  const o = input ?? {};
  const named = ["autonomy", "push", "trigger", "gate"].some(
    (k) => typeof o[k] === "string" && (o[k] as string).trim() !== "",
  );
  return named ? normalizeFlow(o) : undefined;
}

/** The effective flow for a stream, applying {@link DEFAULT_FLOW} when unset. */
export function resolveFlow(flow: AgentFlow | undefined): AgentFlow {
  return flow ?? DEFAULT_FLOW;
}

runtime.features/planner/fleet/commonsGate.ts:
// Director-owned commons gating for the fleet (#851). Two pure transforms applied to a FleetPlan at
// launch (and usable in the planner/UI), built on the stack-derived commons set
// (`commonsGlobsForStack`):
//
//   1. excludeCommonsFromStreams — strip every commons path from each feature stream's `owns`, so no
//      feature stream owns `.gitignore` / `package.json` / CI config (the single-owner rule, by
//      construction). The director owns the commons.
//   2. gateStreamsOnCommons — Phase 0: every feature stream `dependsOn` the COMMONS sentinel, so the
//      director scaffolds + lands the complete commons on develop BEFORE feature workers build
//      against them. Workers start against complete commons and never need to touch them.
//
// Pure (no store/IO) so it's exhaustively unit-testable; `fleetStartProject` calls these with the
// project's stack to wire the director's writeGlobs + the feature gating.

import type { FleetPlan, AgentStream } from "./planFleet";
import { excludeCommonsFromOwns } from "@/shared/lib/session/commons";
import { matchGlob } from "@/shared/lib/session/sessionRoles";

/**
 * Reserved stream id the feature streams depend on for "the director has scaffolded + landed the
 * commons" (#851 Phase 0). It is NOT a real stream — the DIRECTOR satisfies it (it owns the commons)
 * — so it never collides with a planner-authored stream id and the coordinator treats it as the
 * commons-landed latch. Workers carry it in `dependsOn` purely as the launch/coordination gate.
 */
export const COMMONS_STREAM_ID = "commons";

/** Strip every commons path from each feature stream's `owns` (the owns-exclusion). Pure; returns a
 *  new array. A stream that already excludes the commons is unchanged. */
export function excludeCommonsFromStreams(streams: AgentStream[], commons: string[]): AgentStream[] {
  return streams.map((s) => {
    const owns = excludeCommonsFromOwns(s.owns, commons, matchGlob);
    return owns.length === s.owns.length ? s : { ...s, owns };
  });
}

/**
 * Phase 0 gating (#851 step 3): make every feature stream depend on the commons being landed, so the
 * director scaffolds them first and feature workers are released only afterward. Adds {@link
 * COMMONS_STREAM_ID} to each stream's `dependsOn` (deduped). A no-op when there is no director to own
 * the commons (a director-less fleet has no commons steward, so nothing gates) or when there are no
 * commons. Pure; returns new stream objects only where the dep was added.
 */
export function gateStreamsOnCommons(streams: AgentStream[], commons: string[], hasDirector: boolean): AgentStream[] {
  if (!hasDirector || commons.length === 0) return streams;
  return streams.map((s) =>
    s.dependsOn.includes(COMMONS_STREAM_ID) ? s : { ...s, dependsOn: [...s.dependsOn, COMMONS_STREAM_ID] },
  );
}

/**
 * Apply both commons transforms to a fleet plan for the given commons set: exclude the commons from
 * every feature stream's `owns`, then gate each on the commons-landed sentinel (when a director
 * exists). Returns a new plan; the director and other fields pass through untouched.
 */
export function applyCommonsGate(fleet: FleetPlan, commons: string[]): FleetPlan {
  const excluded = excludeCommonsFromStreams(fleet.streams, commons);
  const gated = gateStreamsOnCommons(excluded, commons, fleet.director.enabled);
  return { ...fleet, streams: gated };
}

runtime.features/planner/fleet/directorDrive.ts:
// Director drive mode (#366) -- how the project's async-integrator "director" session is
// driven once the fleet is running. The director is a plain Claude session that, after its
// kickoff, idles forever; this config + the runtime pump (useDirectorPump) decide when to
// re-prompt it so it actually reviews/merges worker PRs and resolves coordination events.
// Pure + unit-tested; mirrors agentFlow.ts (the per-stream flow config pattern).
import { parseCoordLine, type CoordEvent, type CoordRef, type AskingSession, type ReceivedBrief, type OpenRequest } from "@/shared/lib/fleet/coordination";

/**
 * - `event`     -- re-prompt the director whenever workers post new coordination events
 *                  (landed / blocked / waiting / failed), but only while it is idle.
 * - `heartbeat` -- re-prompt on a fixed interval (a periodic fleet sweep), idle-gated.
 * - `manual`    -- never auto-prompt; the user pokes it from the Coordination inbox.
 * - `off`       -- the director is never driven (a static session).
 */
export type DirectorDrive = "event" | "heartbeat" | "manual" | "off";

export const DIRECTOR_DRIVES: DirectorDrive[] = ["event", "heartbeat", "manual", "off"];
export const DEFAULT_DIRECTOR_DRIVE: DirectorDrive = "event";

/** Default heartbeat cadence and the post-inject cooldown (guards the inject-then-run race). */
export const DEFAULT_HEARTBEAT_MS = 10 * 60 * 1000;
export const INJECT_COOLDOWN_MS = 6000;

/** How often an IDLE director is re-told about outstanding questions (#4019).
 *
 *  Shorter than {@link DEFAULT_HEARTBEAT_MS} on purpose: a worker is PARKED for every second of
 *  this, so ten minutes of silence is ten minutes of a stalled agent. Long enough that a director
 *  working through a batch is not interrupted mid-thought each time it draws breath. */
export const ASK_REMINDER_MS = 3 * 60 * 1000;

/** Coerce a raw fleet.json value into a known drive mode (default when unrecognized). */
export function normalizeDirectorDrive(raw: unknown): DirectorDrive {
  if (typeof raw !== "string") return DEFAULT_DIRECTOR_DRIVE;
  const v = raw.trim().toLowerCase();
  // Accept the longer alias the planner prose uses for the event mode.
  if (v === "event-driven") return "event";
  return (DIRECTOR_DRIVES as string[]).includes(v) ? (v as DirectorDrive) : DEFAULT_DIRECTOR_DRIVE;
}

/** Apply the default when the drive is unset. */
export function resolveDirectorDrive(drive: DirectorDrive | undefined): DirectorDrive {
  return drive ?? DEFAULT_DIRECTOR_DRIVE;
}

/** Short human label for a coordination ref, for the injected prompt. */
function refLabel(ref: CoordRef): string {
  switch (ref.kind) {
    case "issue":     return `#${ref.number}`;
    case "contract":  return `contract:${ref.name}`;
    case "file":      return `file:${ref.path}`;
    case "predicate": return `predicate:${ref.expr}`;
    case "session":   return `session:${ref.id}`;
  }
}

/** The director's standing instruction, appended to every injected prompt so the prompt is
 *  self-contained regardless of what the kickoff said. Single line (no newlines -- the pump
 *  submits it by writing the text + a carriage return to the director's stdin). */
const DIRECTOR_ACTION =
  "Review the open PRs on the build branches and merge the green ones; for each, run " +
  "`bsc-merged <ref>` (then `bsc-closed <ref>` when you close its issue) so any parked " +
  // #4015: "unblock anyone blocked or waiting" used to be unactionable prose — the director had no
  // way to SEE who was blocked. `bsc logs waiting` is that queue (parked waits, unanswered asks, open
  // change requests, and panes stopped at a permission prompt), so the sweep names the command and
  // what to do with each kind. The pump already surfaces asks and requests as they arrive; this is
  // the backstop for ones that landed mid-turn or before this director launched.
  "workers wake. Then run `$BSC_BIN logs waiting` and clear the queue: answer a `wait`/`ask` with " +
  "`bsc-answer <pane>`, close a `request` with `bsc plan request resolve <id> --note \"<what you did>\"`. " +
  "A `permission` row needs the USER, not you — leave it. Keep the milestones/board current. " +
  "If nothing needs doing, say so and stop.";

/** Build the event-driven injection summarizing the fresh worker events. Single line. */
export function eventDirectorPrompt(events: CoordEvent[]): string {
  const segs: string[] = [];
  const asks = events.filter((e) => e.type === "ask") as Array<{ session: string; question: string }>;
  const landed = events.filter((e) => e.type === "landed").map((e) => refLabel((e as { ref: CoordRef }).ref));
  const failed = events.filter((e) => e.type === "failed").map((e) => refLabel((e as { ref: CoordRef }).ref));
  const blocked = events.filter((e) => e.type === "blocked") as Array<{ session: string; deps: CoordRef[] }>;
  const waiting = events.filter((e) => e.type === "waiting") as Array<{ session: string }>;
  if (asks.length)    segs.push(`${asks.length} awaiting your answer — ${asks.map((a) => `${a.session} asks: "${a.question}"`).join("; ")}`);
  if (landed.length)  segs.push(`${landed.length} landed (${landed.join(", ")})`);
  if (blocked.length) segs.push(`${blocked.length} blocked (${blocked.map((b) => `${b.session} on ${b.deps.map(refLabel).join("+")}`).join("; ")})`);
  if (waiting.length) segs.push(`${waiting.length} waiting (${waiting.map((w) => w.session).join(", ")})`);
  if (failed.length)  segs.push(`${failed.length} failed (${failed.join(", ")})`);
  const summary = segs.length ? segs.join("; ") : "new activity";
  const askAction = asks.length
    ? `Answer each asking worker with \`bsc-answer <session>\` (e.g. \`echo "use cursor pagination" | bsc-answer ${asks[0].session}\`) — that resumes them automatically; do not leave them parked. `
    : "";
  return `[coordinator] New worker activity: ${summary}. ${askAction}${DIRECTOR_ACTION}`;
}

/** Build the periodic heartbeat injection (a generic fleet sweep). Single line. */
export function heartbeatDirectorPrompt(): string {
  return `[coordinator] Heartbeat -- sweep the fleet. ${DIRECTOR_ACTION}`;
}

/** Stable key for a pending ask (session + when), so the pump surfaces each ask once. */
export function askKey(a: { session: string; at: number }): string {
  return `${a.session}@${a.at}`;
}

/**
 * Prompt that surfaces unanswered worker questions to the director (#369). Driven by the
 * live `asking` table (state), not edge events, so a pending question is delivered even if
 * it was logged before the pump saw the director or across an app restart. Single line.
 */
export function pendingAskPrompt(asks: AskingSession[]): string {
  const list = asks
    .map((a) => `${a.session} asks: "${a.question}" (answer with bsc-answer ${a.session})`)
    .join("; ");
  return `[coordinator] ${asks.length} worker question(s) awaiting your answer: ${list}. For each, pipe your one-line answer into bsc-answer <session> on stdin; that resumes the worker automatically. Do not leave them parked, and do not ask the user yourself.`;
}

/** Stable key for a received brief (planner + when), so the pump surfaces each brief once. */
export function briefKey(b: { from: string; at: number }): string {
  return `${b.from}@${b.at}`;
}

/**
 * Prompt that surfaces the planner's mid-build plan updates to the director (#2377). Driven
 * by the live `briefs` table (state), not edge events, so a brief is delivered even if it was
 * logged before the pump saw the director or across an app restart — the same restart-safe,
 * must-not-drop posture as {@link pendingAskPrompt}. Each brief may carry a `ref` (a new/
 * updated #issue, contract, or file) the director routes onward via `bsc-assign`. Single line.
 */
export function pendingBriefPrompt(briefs: ReceivedBrief[]): string {
  const list = briefs
    .map((b) => `"${b.body}"${b.ref ? ` [${refLabel(b.ref)}]` : ""}`)
    .join("; ");
  return `[coordinator] The planner pushed ${briefs.length} mid-build plan update(s): ${list}. Reconcile the running plan with each: update the board/issues to match, and route any new or changed work to the owning worker with bsc-assign (open a fresh issue via bsc-issue first when a brief introduces a new #ref). Do not ask the user.`;
}

/** Stable key for an open project request, so the pump surfaces each one once. Keyed on the plan.db
 *  ROW ID, not session+time: the id is the thing the director resolves by, and it is what
 *  `request-resolved` carries, so the key prunes exactly when the request is answered. */
export function requestKey(r: { id: string }): string {
  return `req:${r.id}`;
}

/**
 * Prompt that surfaces open worker->director change requests (#4001).
 *
 * Same restart-safe, must-not-drop posture as {@link pendingAskPrompt}: driven by the live `requests`
 * table, so a request filed before the pump saw the director still lands. It names BOTH of the
 * director's moves explicitly — resolve it, or escalate a genuine tooling gap — because the whole
 * two-lane design (#4000) depends on the director being the escalation point rather than the worker.
 */
export function pendingRequestPrompt(requests: OpenRequest[]): string {
  const list = requests
    .map((r) => `#${r.id} from ${r.from || "a worker"}: "${r.text}"`)
    .join("; ");
  return `[coordinator] ${requests.length} worker change-request(s) awaiting you: ${list}. For each: do the thing if it is yours (branches, board, issues, worktrees are all in your remit), then close it with bsc plan request resolve <id> --note "<what you did>" — the note is the answer the worker reads back. If it is genuinely a gap in the base-studio-code TOOLING rather than this project, escalate it with bsc request new "<gap>" and then resolve the project request noting that you did. Do not ask the user, and do not leave one open.`;
}

/**
 * Should an idle director be re-told about outstanding work (#4019)?
 *
 * The pump delivers each ask/request exactly ONCE (its `surfaced` guard), which is right for not
 * re-queueing every tick — but it makes a single missed delivery final. If the director was mid-turn,
 * or simply did not act, nothing ever says it again and the worker waits forever. Measured: 44 asks
 * against 20 answers.
 *
 * This is the backstop, and it is deliberately NOT wired into that guard: the immediate delivery stays
 * exactly as it was. Gated on `idle` because the whole point is to spend the moment the director has
 * nothing else to do, and rate-limited so a director that keeps ignoring it is nagged at a sane
 * interval rather than on every tick.
 */
export function shouldRemind(inp: { idle: boolean; pending: number; now: number; lastRemindAt: number; everyMs: number }): boolean {
  if (!inp.idle || inp.pending === 0) return false;
  return inp.lastRemindAt === 0 || inp.now - inp.lastRemindAt >= inp.everyMs;
}

/**
 * The reminder itself. Names the same verbs the sweep does, so the director never has to work out what
 * to do with it, and states plainly that a worker is parked on each one — the cost of ignoring it.
 */
export function idleReminderPrompt(asks: AskingSession[], requests: OpenRequest[]): string {
  const segs: string[] = [];
  if (asks.length > 0) {
    segs.push(`${asks.length} unanswered question(s): ` +
      asks.map((a) => `${a.session} asks "${a.question}"`).join("; ") +
      ` — answer each with \`bsc-answer <session>\` (pipe your one-line answer in on stdin)`);
  }
  if (requests.length > 0) {
    segs.push(`${requests.length} open change request(s): ` +
      requests.map((r) => `#${r.id} from ${r.from || "a worker"} "${r.text}"`).join("; ") +
      ` — close each with \`bsc plan request resolve <id> --note "<what you did>"\``);
  }
  return `[coordinator] You are idle and this is still outstanding. ${segs.join(". ")}. ` +
    `A worker is PARKED on every one of these until you respond, so clear them before anything else. Do not ask the user.`;
}

/** Coordination events the director should act on (worker-originated asks). Its own
 *  merge/close/wake events are excluded so it is never re-prompted by its own actions. */
const DIRECTOR_RELEVANT = new Set(["landed", "blocked", "waiting", "failed"]);

export interface DirectorTickInput {
  /** All coord.log lines, oldest-first. */
  lines: string[];
  /** How many lines have already been consumed. */
  cursor: number;
  drive: DirectorDrive;
  /** Whether the director pane is idle (safe to inject without interrupting a turn). */
  idle: boolean;
  now: number;
  /** Timestamp of the last injection (0 = never). Gates the heartbeat cadence + cooldown. */
  lastInjectAt: number;
  heartbeatMs: number;
  cooldownMs: number;
}

export interface DirectorTickResult {
  /** The prompt to write to the director's stdin, or null to do nothing this tick. */
  inject: string | null;
  /** New cursor -- events left unconsumed (cursor held) are retried next tick. */
  cursor: number;
  lastInjectAt: number;
}

/**
 * Decide whether to re-prompt the director this tick. Pure: the hook supplies the live
 * inputs (log lines, idle status, clock) and actuates the returned `inject` via pty_write.
 *
 * Event mode holds the cursor when the director is busy or within the cooldown so the
 * pending events are retried once it frees up -- no event is dropped, none double-fires.
 */
export function decideDirectorAction(inp: DirectorTickInput): DirectorTickResult {
  const { lines, cursor, drive, idle, now, lastInjectAt, heartbeatMs, cooldownMs } = inp;
  const end = lines.length;

  if (drive === "off" || drive === "manual") {
    return { inject: null, cursor: end, lastInjectAt };
  }

  if (drive === "heartbeat") {
    if (idle && (lastInjectAt === 0 || now - lastInjectAt >= heartbeatMs)) {
      return { inject: heartbeatDirectorPrompt(), cursor: end, lastInjectAt: now };
    }
    return { inject: null, cursor: end, lastInjectAt };
  }

  // event-driven
  const fresh = lines.slice(cursor)
    .map(parseCoordLine)
    .filter((e): e is CoordEvent => e !== null && DIRECTOR_RELEVANT.has(e.type));
  if (fresh.length === 0) return { inject: null, cursor: end, lastInjectAt };
  if (!idle || now - lastInjectAt < cooldownMs) {
    // Busy or cooling down -- hold the cursor so these events are retried when ready.
    return { inject: null, cursor, lastInjectAt };
  }
  return { inject: eventDirectorPrompt(fresh), cursor: end, lastInjectAt: now };
}

runtime.features/planner/fleet/fleetAssignee.ts:
// Resolve the GitHub assignee for a published issue (#847). A worker/stream is an agent
// session, not a GitHub user, so the assignee is a human/collaborator login configured per
// stream (`AgentStream.assignee`), falling back to the account running the publish. The
// `stream:<id>` label stays as the agent-ownership marker; this drives the first-class
// GitHub assignee field. Pure + unit-tested; the publish flow applies it best-effort.

import type { AgentStream } from "./planFleet";

/**
 * The GitHub login to assign an issue to, given its owning stream id.
 *
 * - The owning stream's configured `assignee`, when set and non-empty.
 * - Otherwise the publishing account (`viewerLogin`) — so issues are never left unassigned.
 * - `null` only when there's no stream login AND no viewer login (assignment is then skipped).
 *
 * Trims whitespace; an all-whitespace stream assignee is treated as unset.
 */
export function resolveIssueAssignee(
  streamId: string | undefined,
  streams: readonly AgentStream[],
  viewerLogin: string,
): string | null {
  const stream = streamId ? streams.find((s) => s.id === streamId) : undefined;
  const streamLogin = stream?.assignee?.trim();
  if (streamLogin) return streamLogin;
  const viewer = viewerLogin.trim();
  return viewer || null;
}

