}

runtime.features/planner/fleet/lib/fleetCost.ts:
// Fleet cost & energy (#2237) — pure aggregation of per-pane token/cost telemetry over the live worker
// roster. COST is real (priced from each transcript's actual model by `bsc logs cost`); ENERGY is a
// clearly-labeled DIRECTIONAL ESTIMATE (tokens × a per-model-tier coefficient), never metered.
//
// The groupBy-and-total is the generic `groupTotals` (#3465) — the reusable "roll rows up per key +
// overall in one pass" algorithm this panel was a source for. The Wh-per-token energy estimate is
// likewise the generic `estimateEnergyWh` node (#3462, `llmEnergy.ts`) — this panel was its source,
// so the local copy is gone and it's delegated + re-exported (#3607).
import { groupTotals } from "@/shared/lib/algorithms/groupTotals";
import { estimateEnergyWh } from "@/shared/lib/algorithms/llmEnergy";

/** The per-pane rollup shape from `bsc logs cost --full` (subset used here; keys = the Rust struct). */
export interface TokenUsage {
  pane: string;
  model: string;
  input_tokens: number;
  output_tokens: number;
  cache_creation_tokens: number;
  cache_read_tokens: number;
  cost_usd: number;
}

/** Minimal roster shape — just the pane id + display name (LiveWorker is a superset). */
export interface CostWorkerLike { id: string; name: string }

export interface WorkerCost {
  id: string; name: string; model: string;
  input: number; output: number; cache: number; totalTokens: number;
  costUsd: number;
  /** Estimated Wh — directional, not metered. */
  energyWh: number;
}

export interface FleetCost {
  workers: WorkerCost[];
  totalTokens: number; totalInput: number; totalOutput: number; totalCache: number;
  totalCostUsd: number;
  /** Estimated total Wh (directional). */
  totalEnergyWh: number;
  byModel: Array<{ model: string; tokens: number; costUsd: number; energyWh: number }>;
  hasData: boolean;
}

// ── Energy estimate ────────────────────────────────────────────────────────────
// `estimateEnergyWh` is the generic algorithms-graph node (`llmEnergy.ts`, #3462): tokens × a
// per-model-tier coefficient, directional not metered. It's re-exported here so this panel and its
// test still resolve it from one place, while the single implementation lives in the graph (#3607).
export { estimateEnergyWh };

/** Average grid carbon intensity (kg CO₂ per kWh) — a rough global figure for the CO₂ estimate. */
export const CO2_KG_PER_KWH = 0.40;

/** Join per-pane usage to the live roster and roll up per-worker + fleet totals + a by-model split. */
export function aggregateFleetCost(workers: CostWorkerLike[], usage: Map<string, TokenUsage>): FleetCost {
  const list: WorkerCost[] = [];
  for (const w of workers) {
    const u = usage.get(w.id);
    if (!u) continue;
    const cache = u.cache_creation_tokens + u.cache_read_tokens;
    list.push({
      id: w.id, name: w.name, model: u.model,
      input: u.input_tokens, output: u.output_tokens, cache,
      totalTokens: u.input_tokens + u.output_tokens + cache,
      costUsd: u.cost_usd,
      energyWh: estimateEnergyWh(u.model, u.input_tokens, u.output_tokens),
    });
  }
  list.sort((a, b) => b.costUsd - a.costUsd);

  // The groupBy-by-model + every fleet total is the generic `groupTotals` (#3465), one pass over the
  // rolled-up rows — so a fleet total can never disagree with the sum of its per-model breakdown. The
  // JOIN + per-row rollup above (usage → worker cost) stays here: it is the app-specific projection,
  // and a graph algorithm cannot know a TokenUsage.
  const { totals, groups } = groupTotals(list, (c) => c.model, {
    totalTokens: (c) => c.totalTokens,
    totalInput: (c) => c.input,
    totalOutput: (c) => c.output,
    totalCache: (c) => c.cache,
    totalCostUsd: (c) => c.costUsd,
    totalEnergyWh: (c) => c.energyWh,
  });

  return {
    workers: list,
    ...totals,
    byModel: groups
      .map((g) => ({ model: g.key, tokens: g.totals.totalTokens, costUsd: g.totals.totalCostUsd, energyWh: g.totals.totalEnergyWh }))
      .sort((a, b) => b.costUsd - a.costUsd),
    hasData: list.length > 0,
  };
}

runtime.features/planner/fleet/lib/fleetHealth.t:
// Fleet health & errors (#2240) — a pure unifier of the fleet's ERROR signals that exist but weren't
// surfaced: permission denials (`bsc logs perm`), coordination stalls/deadlocks (`coordinationSummary`),
// warden quarantine trips, and auto-end needs-attention/blocked verdicts. Produces one recent-errors
// feed + counts. No fabrication — every item is a real recorded signal.
//
// The merge itself is the generic `mergeFeeds` (#3465) — the reusable "K streams → one recent-first
// feed with a pinned class + per-kind counts" algorithm this panel was the source for.
import { mergeFeeds, feedStream } from "@/shared/lib/algorithms/streamMerge";

/** One `bsc logs perm --json` row (subset). `summary` is already human-readable (e.g. "scope block src/App.tsx"). */
export interface PermEvent { ts_ms: number; session: string; summary: string }
/** Warden quarantine (store `quarantinedPanes` value). */
export interface QuarantineLike { streamId: string; summary: string; at: number; acknowledged?: boolean }
/** Auto-end verdict (store `endedPanes` value). */
export interface EndedLike { state: "done" | "needs-attention" | "blocked"; streamId: string; summary: string; at: number }
/** A coordination BlockedView (subset) — stalled = a failed dep; deadlocked = a wait-for cycle. */
export interface BlockedLike { session: string; stalled: boolean; deadlocked: boolean; deps: { ref: string; status: string }[] }

export type HealthKind = "deadlock" | "stalled" | "quarantine" | "blocked" | "attention" | "denied";

export interface HealthItem {
  kind: HealthKind;
  /** The worker/agent the item is about (resolved name, else the raw id). */
  label: string;
  /** The one-line reason. */
  detail: string;
  /** Sort key (epoch ms; live coord issues use Infinity so they pin to the top). */
  sortKey: number;
  /** true = red (error), false = amber (warning). */
  danger: boolean;
}

export interface FleetHealth {
  items: HealthItem[];
  counts: Record<HealthKind, number>;
  total: number;
  hasIssues: boolean;
}

/** Display label per kind. */
export const HEALTH_LABEL: Record<HealthKind, string> = {
  deadlock: "deadlock", stalled: "stalled", quarantine: "quarantined",
  blocked: "blocked", attention: "needs attention", denied: "denied",
};

export interface HealthInput {
  perm: PermEvent[];
  quarantined: Record<string, QuarantineLike>;
  ended: Record<string, EndedLike>;
  blocked: BlockedLike[];
  /** paneId → worker display name, to humanize ids. */
  nameByPane: Map<string, string>;
  /** Cap on the number of recent permission denials shown. Default 8. */
  permLimit?: number;
}

/** The kind set, in badge order — passed to `mergeFeeds` so `counts` carries a zero for every one. */
const HEALTH_KINDS: HealthKind[] = ["deadlock", "stalled", "quarantine", "blocked", "attention", "denied"];

/** The per-item payload the feed carries beyond `{ kind, pinned, sortKey }`. */
type HealthPayload = { label: string; detail: string; danger: boolean };

/**
 * Merge every error signal into one recent-first feed + counts. Pure.
 *
 * Delegates the merge to the generic `mergeFeeds` (#3465): this function is now the DOMAIN part —
 * which signal sources exist and how each projects to a kind/label/detail — while the ordering, the
 * pin-above-recency rule, and the per-kind count are the shared algorithm. The stalls/deadlocks are
 * `pinned` (a live problem sits above the time sort), replacing the `sortKey: Infinity` sentinel the
 * hand-written version used, which left two live items with no defined order between them.
 */
export function buildFleetHealth(input: HealthInput): FleetHealth {
  const name = (id: string, fallback: string) => input.nameByPane.get(id) ?? fallback;
  const recentPerm = [...input.perm].sort((a, b) => b.ts_ms - a.ts_ms).slice(0, input.permLimit ?? 8);

  const { items, counts, total, hasItems } = mergeFeeds<HealthKind, HealthPayload>(
    [
      // Coordination stalls / deadlocks — LIVE, so they PIN above the time sort.
      feedStream(input.blocked, (b) => {
        if (!b.stalled && !b.deadlocked) return null;
        const failed = b.deps.filter((d) => d.status === "failed").map((d) => d.ref).join(", ");
        return {
          kind: b.deadlocked ? "deadlock" : "stalled", pinned: true, sortKey: 0,
          label: name(b.session, b.session),
          detail: b.deadlocked ? "in a wait-for cycle — no producer will satisfy it" : `stalled on ${failed || "a failed dependency"}`,
          danger: true,
        };
      }),
      // Warden quarantine trips.
      feedStream(Object.entries(input.quarantined), ([pane, q]) => ({
        kind: "quarantine", pinned: false, sortKey: q.at, label: name(pane, q.streamId), detail: q.summary, danger: true,
      })),
      // Auto-end verdicts that need eyes (done is not an error → dropped by returning null).
      feedStream(Object.entries(input.ended), ([pane, e]) =>
        e.state === "done" ? null : {
          kind: e.state === "blocked" ? "blocked" : "attention", pinned: false, sortKey: e.at,
          label: name(pane, e.streamId), detail: e.summary, danger: e.state === "blocked",
        }),
      // Recent permission denials.
      feedStream(recentPerm, (p) => ({
        kind: "denied", pinned: false, sortKey: p.ts_ms, label: name(p.session, p.session), detail: p.summary, danger: false,
      })),
    ],
    HEALTH_KINDS,
  );

  return { items, counts, total, hasIssues: hasItems };
}

runtime.features/planner/fleet/planFleet.ts:
// The parallel-execution (fleet) plan — the agent streams, director, topology, and
// relationship graph a project's fleet describes, plus the parser that turns the
// planner-written JSON (stored in plan.db, #1805) into a typed {@link FleetPlan}.
//
// Pure (no React / xterm / Tauri) so it can be unit-tested in isolation and shared
// between the planner UI, the store, and the fleet helpers. Split out of the former
// planStages.ts (#1615), which conflated this fleet machinery with the discovery
// topic-file helpers; those now live in stages/planTopics.ts.

import type { AgentFlow } from "./agentFlow";
import { flowOrUndefined } from "./agentFlow";
import { MODEL_IDS, type ModelId } from "@/app/console/lib/models";
import { type DirectorDrive, normalizeDirectorDrive, DEFAULT_DIRECTOR_DRIVE } from "./directorDrive";
import { type IntegrationStrategy, normalizeStrategy } from "../lib/integrationStrategy";
import {
  type Topology, type RelationshipArtifact, type AgentRelationship,
  type EdgeKind, type Hardness, type Via, type ArtifactKind,
} from "../relationship/relationshipGraph";

const TOPOLOGIES: Topology[] = ["director", "peer", "hybrid"];
const EDGE_KINDS: EdgeKind[] = ["handoff", "blocking", "sequence", "review", "notify", "mutex", "shared"];
const HARDNESSES: Hardness[] = ["blocking", "soft", "notify"];
const ARTIFACT_KINDS: ArtifactKind[] = ["schema", "contract", "types", "tokens", "fixture", "other"];

/** Coerce a raw fleet.json `topology` value (default "hybrid"). */
export function normalizeTopology(raw: unknown): Topology {
  return typeof raw === "string" && (TOPOLOGIES as string[]).includes(raw.trim().toLowerCase())
    ? (raw.trim().toLowerCase() as Topology) : "hybrid";
}

function parseArtifacts(raw: unknown): RelationshipArtifact[] {
  if (!Array.isArray(raw)) return [];
  const out: RelationshipArtifact[] = [];
  for (const a of raw) {
    if (!a || typeof a !== "object") continue;
    const o = a as Record<string, unknown>;
    const id = typeof o.id === "string" ? o.id.trim() : "";
    const producer = typeof o.producer === "string" ? o.producer.trim() : "";
    if (!id || !producer) continue;
    const kind = typeof o.kind === "string" && (ARTIFACT_KINDS as string[]).includes(o.kind) ? o.kind as ArtifactKind : "other";
    out.push({
      id, producer, kind,
      name: typeof o.name === "string" && o.name.trim() ? o.name.trim() : id,
      consumers: Array.isArray(o.consumers) ? o.consumers.filter((c): c is string => typeof c === "string") : [],
      status: o.status === "ready" ? "ready" : o.status === "pending" ? "pending" : undefined,
    });
  }
  return out;
}

function parseEdges(raw: unknown): AgentRelationship[] {
  if (!Array.isArray(raw)) return [];
  const out: AgentRelationship[] = [];
  for (const e of raw) {
    if (!e || typeof e !== "object") continue;
    const o = e as Record<string, unknown>;
    const from = typeof o.from === "string" ? o.from.trim() : "";
    const to = typeof o.to === "string" ? o.to.trim() : "";
    if (!from || !to) continue;
    out.push({
      id: typeof o.id === "string" && o.id.trim() ? o.id.trim() : `${from}>${to}`,
      from, to,
      kind: typeof o.kind === "string" && (EDGE_KINDS as string[]).includes(o.kind) ? o.kind as EdgeKind : "blocking",
      hardness: typeof o.hardness === "string" && (HARDNESSES as string[]).includes(o.hardness) ? o.hardness as Hardness : "blocking",
      via: o.via === "director" ? "director" : ("direct" as Via),
      artifact: typeof o.artifact === "string" && o.artifact.trim() ? o.artifact.trim() : undefined,
      note: typeof o.note === "string" && o.note.trim() ? o.note.trim() : undefined,
    });
  }
  return out;
}

/** The fleet section key. The fleet plan is DB-owned (plan.db, #1018/#1805) — surfaced by the poll
 *  under this stem (NOT a `fleet.json` file), not a rendered plan topic; parsed into the fleet store
 *  and shown in its own Fleet card. See {@link parseFleetFile}. */
export const FLEET_KEY = "fleet";

/**
 * One parallel work stream — a single Claude session with a focused role, a repo,
 * the files/globs it OWNS (its conflict boundary), the issues it owns, the streams
 * it must follow (interface-first), and the kickoff script that seeds it.
 */
export interface AgentStream {
  id: string;
  name: string;
  repo: string;
  /** Path globs this stream owns; no other stream should write inside them. */
  owns: string[];
  /** Issue refs this stream owns (e.g. `#12`). */
  issues: string[];
  /** Ids of streams that must land before this one starts. */
  dependsOn: string[];
  /** Shell commands this stream's session may auto-run without prompting (#1572) — the
   *  toolchain the planner grants it (e.g. `["cargo", "wasm-pack"]`), on top of the
   *  posture-scaled safe baseline. Seeds the generated profile's `commands`; written as
   *  `Bash(<cmd> *)` allow rules at launch. Unset/empty ⇒ baseline + mandatory only. */
  commands?: string[];
  /** Relpath of the kickoff script the fleet launch seeds this session with. */
  prompt?: string;
  /** Id of the AgentProfile this stream's session launches under (#289). */
  profile?: string;
  /** Id of the PERSONA this stream launches as (#2094): a live reference resolved at fleet launch to
   *  the stream's ROLE (overriding the default `worker`), start prompt, skills, and model. Unset ⇒ a
   *  plain worker (the historical default). Lets a fleet mix e.g. a documentor / reviewer stream with
   *  workers — the persona is the behavioral identity, the role it references is the permission floor. */
  persona?: string;
  /** Per-agent execution flow (#297): autonomy + GitHub push policy. Unset ⇒ DEFAULT_FLOW at launch. */
  flow?: AgentFlow;
  /** Per-agent LLM model (#…) — launches this stream's session under `claude --model <tier>`.
   *  Unset ⇒ the global `defaultModel` (so the director/baseline stays on the global choice). */
  model?: ModelId;
  /** Per-stream integration-strategy override (#378). Unset ⇒ the fleet default. */
  strategy?: IntegrationStrategy;
  /** GitHub login this stream's issues are assigned to at publish (#847). A worker is an
   *  agent session, not a GitHub user, so this maps the stream to a human/collaborator
   *  login. Unset ⇒ the publishing account (viewer). The `stream:<id>` label remains the
   *  agent-ownership marker; this is the first-class GitHub assignee. */
  assignee?: string;
  /** MCP servers (catalog names) the planner assigned to THIS worker (#1054). At fleet launch
   *  the worker gets these (case-insensitive) on top of any global servers; the planner + director
   *  always see every installed server. Unset/empty ⇒ the worker gets only global servers. */
  mcp?: string[];
  /** Skill task-group ids the planner assigned to THIS stream (#1338, parallel to {@link mcp}).
   *  At fleet launch the group ids are expanded (via the global skills.db) into this worker's
   *  skill set, on top of the project-resolved skills and any groups toggled onto the session.
   *  Unset/empty ⇒ the worker gets only its project-resolved skills. */
  groupIds?: string[];
}

/** Optional async-integrator session that coordinates the fleet from the project root. */
export interface FleetDirector { enabled: boolean; role?: string; drive?: DirectorDrive; }

/** The full parallel-execution plan for a project (persisted in plan.db, #1805). */
export interface FleetPlan {
  /** Optimal number of worker sessions to run concurrently. */
  recommended: number;
  /** Why that many — the planner's justification. */
  reasoning: string;
  streams: AgentStream[];
  director: FleetDirector;
  /** Project-default integration strategy (#378). Unset ⇒ DEFAULT_STRATEGY. */
  strategy?: IntegrationStrategy;
  /** Coordination topology (#…): director-orchestrated, peer mesh, or hybrid (per-edge). */
  topology?: Topology;
  /** Produced contracts/schemas one stream hands to others. */
  artifacts?: RelationshipArtifact[];
  /** Typed relationship edges between streams (beyond plain `dependsOn`). */
  edges?: AgentRelationship[];
}

/** An empty fleet — the default before the planner has designed one. */
export function emptyFleet(): FleetPlan {
  return { recommended: 0, reasoning: "", streams: [], director: { enabled: false, drive: DEFAULT_DIRECTOR_DRIVE } };
}

/**
 * Enrich each stream's `issues` from the plan.db issues that name it as their owning `stream` (#2615),
 * when the stream itself carries none. `AgentStream.issues` and `PlanIssue.stream` are meant to MIRROR
 * each other, but a stream can reach launch with an empty `issues[]` — so a worker gets a placeholder
 * kickoff instead of its real work. Deriving from the issues at launch means a worker always launches
 * with its concrete task list. A stream that already lists its issues is untouched (its authored order
 * wins). Pure + generic over the issue shape (`{ ref, stream }`) so it's unit-testable.
 */
export function withDerivedStreamIssues<T extends { id: string; issues: string[] }>(
  streams: T[],
  issues: ReadonlyArray<{ ref?: string; stream?: string }>,
): T[] {
  const byStream = new Map<string, string[]>();
  for (const iss of issues) {
    if (!iss.stream || !iss.ref) continue;
    const arr = byStream.get(iss.stream);
    if (arr) arr.push(iss.ref); else byStream.set(iss.stream, [iss.ref]);
  }
  return streams.map((s) => (s.issues.length > 0 ? s : { ...s, issues: byStream.get(s.id) ?? [] }));
}

/** Coerce a JSON value into a string[]. Accepts an array (strings kept, others
 *  stringified) or a single comma-separated string; anything else → []. */
function toStringArray(v: unknown): string[] {
  if (Array.isArray(v)) {
    return v.map(x => (typeof x === "string" ? x : String(x))).map(s => s.trim()).filter(Boolean);
  }
  if (typeof v === "string") {
    return v.split(",").map(s => s.trim()).filter(Boolean);
  }
  return [];
}

/** Coerce a JSON value into a non-negative integer; non-numeric → 0. */
function coerceNum(v: unknown): number {
  const n = typeof v === "number" ? v : typeof v === "string" ? Number(v) : NaN;
  return Number.isFinite(n) && n >= 0 ? Math.floor(n) : 0;
}

/**
 * Parse the FleetPlan JSON (the planner writes it to plan.db, #1805; surfaced by the poll
 * as stem {@link FLEET_KEY}) into a {@link FleetPlan}. Tolerant of partial/malformed
 * input: returns `null` only when the text is blank or not a JSON object; otherwise
 * fills sensible defaults. A stream missing an `id` (genuinely unkeyable) is dropped; a repo-less
 * stream DEFAULTS to the project's sole repo (`repos`, when there's exactly one) and otherwise stays
 * VISIBLE with an empty `repo` so it isn't silently hidden from the plan (#2611). `dependsOn`
 * accepts either `dependsOn` or `depends_on`.
 */
export function parseFleetFile(raw: string, repos: string[] = []): FleetPlan | null {
  if (!raw || !raw.trim()) return null;
  let obj: unknown;
  try { obj = JSON.parse(raw); } catch { return null; }
  if (!obj || typeof obj !== "object" || Array.isArray(obj)) return null;
  const o = obj as Record<string, unknown>;

  const streams: AgentStream[] = [];
  const rawStreams = Array.isArray(o.streams) ? o.streams : [];
  for (const s of rawStreams) {
    if (!s || typeof s !== "object") continue;
    const so = s as Record<string, unknown>;
    const id   = typeof so.id === "string" ? so.id.trim() : "";
    if (!id) continue;  // no id ⇒ genuinely unkeyable, drop
    // #2611: default a repo-less stream to the project's SOLE repo (the common single-repo case). If the
    // repo still can't be resolved (multi-repo / unassigned), KEEP the stream with an empty repo so it
    // stays VISIBLE in the planner graph flagged as needing a repo — silently dropping it hid streams
    // from the plan AND from launch. The launch path (usePlanPublish) skips a repo-less stream so it
    // never aborts the fleet or spawns a broken worktree.
    let repo = typeof so.repo === "string" ? so.repo.trim() : "";
    if (!repo && repos.length === 1) repo = repos[0];
    const prompt = typeof so.prompt === "string" && so.prompt.trim() ? so.prompt.trim() : undefined;
    // MCP servers (catalog names) the planner assigned to this worker (#1054); undefined when none
    // so the field round-trips cleanly. Carried through to fleetStartProject's per-worker resolution.
    const mcp = toStringArray(so.mcp);
    // Per-agent flow (#297) arrives in EITHER shape (#1804): NESTED as `so.flow`
    // ({autonomy,push,trigger,gate} — the canonical `bsc-plan fleet set` / fleet.json
    // form, matching the store model) OR FLAT as top-level `so.autonomy`/`so.push`/
    // `so.trigger`/`so.gate` (what the `<agent_assign>` tag attrs and legacy flat
    // fleet.json emit). Prefer a named nested object; else assemble from the flat
    // fields; else leave undefined so genuinely-unset streams still get DEFAULT_FLOW
    // at launch (we must NOT silently materialize a flow here).
    const nestedFlow = so.flow && typeof so.flow === "object" && !Array.isArray(so.flow)
      ? (so.flow as Record<string, unknown>) : null;
    const flow = flowOrUndefined(nestedFlow)
      ?? flowOrUndefined({ autonomy: so.autonomy, push: so.push, trigger: so.trigger, gate: so.gate });
    streams.push({
      id,
      name: typeof so.name === "string" && so.name.trim() ? so.name.trim() : id,
      repo,
      owns:      toStringArray(so.owns),
      issues:    toStringArray(so.issues),
      dependsOn: toStringArray(so.dependsOn ?? so.depends_on),
      commands:  ((cs) => cs.length ? cs : undefined)(toStringArray(so.commands)),
      prompt,
      mcp: mcp.length ? mcp : undefined,
      profile: typeof so.profile === "string" && so.profile.trim() ? so.profile.trim() : undefined,
      // Persona reference (#2094) — the stream's behavioral identity, resolved to role/prompt/skills/
      // model at fleet launch. Kept verbatim (an id); an unknown id just resolves to no persona.
      persona: typeof so.persona === "string" && so.persona.trim() ? so.persona.trim() : undefined,
      flow,
      // Per-agent model (#…) — the tier this stream's session launches under (`claude --model`).
      // Round-trips through plan.db (the planner / agent editor / `bsc-plan fleet set` may set it);
      // validated against the known tiers so a stray value falls back to the global default rather
      // than being passed verbatim to the CLI. Without this parse the selection is dropped on reload.
      model: (typeof so.model === "string" && (MODEL_IDS as readonly string[]).includes(so.model.trim()))
        ? (so.model.trim() as ModelId) : undefined,
      strategy: normalizeStrategy(so.strategy),
      assignee: typeof so.assignee === "string" && so.assignee.trim() ? so.assignee.trim() : undefined,
    });
  }

  const dir = (o.director && typeof o.director === "object" && !Array.isArray(o.director))
    ? (o.director as Record<string, unknown>) : {};
  const director: FleetDirector = {
    enabled: dir.enabled === true || dir.enabled === "true",
    role: typeof dir.role === "string" && dir.role.trim() ? dir.role.trim() : undefined,
    drive: normalizeDirectorDrive(dir.drive),
  };

  return {
    recommended: coerceNum(o.recommended),
    reasoning: typeof o.reasoning === "string" ? o.reasoning : "",
    streams,
    director,
    strategy: normalizeStrategy(o.strategy),
    topology: o.topology !== undefined ? normalizeTopology(o.topology) : undefined,
    artifacts: parseArtifacts(o.artifacts),
    edges: parseEdges(o.edges),
  };
}

runtime.features/planner/fleet/streamPersona.ts:
// Stream ⇄ persona resolution (#2094) — a fleet stream may reference a PERSONA (its behavioral
// identity); at launch the persona resolves the stream's role (overriding the default `worker`),
// start prompt, skills, and model. This module is the pure resolution: look up the persona and build
// its role-aware kickoff. `buildStreamPrompt` (the historical worker kickoff) stays for persona-less
// streams; a persona stream gets THIS kickoff instead, so a read-only reviewer/documentor stream isn't
// handed the worker's "own your globs, open a PR" prose.
import type { Persona } from "@/features/personas";
import { roleCapability, hasScopedWriteCarveOut } from "@/shared/lib/session/sessionRoles";
import { resolveFlow } from "./agentFlow";
import { flowKickoffText } from "./flowKickoff";
import { strategySettings, DEFAULT_STRATEGY, type IntegrationStrategy } from "@/features/planner/lib/integrationStrategy";
import type { AgentStream } from "./planFleet";
import personaKickoffEmbedded from "@data/fleet/persona-kickoff.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";
import { fillTemplate } from "@/shared/lib/core/template";

// The kickoff PROSE (the role-agnostic scope paragraph, the read-only closing, and the owns/issues
// fallbacks) is externalized to `@data/fleet/persona-kickoff.json` (#2416) — editable without touching
// code + part of the exportable config bundle; the config-dir copy (#2047) overlays the embedded
// default via `overlayFile`. This module keeps only the interpolation (`{{STREAM_NAME}}`/`{{BRANCH}}`/
// `{{ISSUES}}`/`{{OWNS}}`/`{{CLOSING}}`) and the role/flow resolution that computes the closing.
const KICKOFF_PROSE = overlayFile("fleet/persona-kickoff.json", personaKickoffEmbedded);

/** The persona a stream references, or `undefined` (no reference, or an unknown/stale id). */
export function resolveStreamPersona(personas: Persona[], stream: AgentStream): Persona | undefined {
  return stream.persona ? personas.find((p) => p.id === stream.persona) : undefined;
}

/** Whether a role may write files or push — drives whether the kickoff carries the worker autonomy/push
 *  prose or the read-only "report, don't commit" instruction. Includes the scoped-write carve-out
 *  (#851/#1555) so a documentor (code:"none" + DOC_GLOBS) is briefed to WRITE its docs and open a
 *  flow-governed docs PR, not treated as a read-only reviewer. */
function roleWrites(role: Persona["role"]): boolean {
  const cap = roleCapability(role);
  return cap.code === "write" || cap.git === "write" || hasScopedWriteCarveOut(cap);
}

/**
 * The kickoff for a persona stream: the persona's own start prompt (its identity/behavior) followed by
 * the role-AGNOSTIC scope facts every stream needs (its worktree branch, assigned issues, owned paths,
 * contracts + checkpoint discipline), then either the worker autonomy/push paragraph (writing roles) or
 * the read-only reporting instruction (reviewer/juror/…). So a documentor/reviewer stream is briefed as
 * itself, not as a code-writing worker.
 */
export function personaStreamPrompt(
  persona: Persona, stream: AgentStream, strategy?: IntegrationStrategy,
): string {
  const owns   = stream.owns.length   ? stream.owns.join(", ")   : KICKOFF_PROSE.ownsFallback;
  const issues = stream.issues.length ? stream.issues.join(", ") : KICKOFF_PROSE.issuesFallback;
  const intro = persona.startPrompt.trim();
  const strat = strategy ?? DEFAULT_STRATEGY;
  const closing = roleWrites(persona.role)
    ? (() => {
        const effFlow = { ...resolveFlow(stream.flow), push: stream.flow?.push ?? strategySettings(strat).integrate };
        const kick = flowKickoffText(effFlow, stream.id);
        return `${kick.autonomy} ${kick.push}`;
      })()
    : KICKOFF_PROSE.readOnlyClosing;
  return (
    (intro ? `${intro}\n\n` : "") +
    fillTemplate(KICKOFF_PROSE.scope, {
      STREAM_NAME: stream.name,
      BRANCH: stream.id,
      ISSUES: issues,
      OWNS: owns,
      CLOSING: closing,
    })
  );
}

runtime.features/planner/fleet/teamFleet.ts:
// Team → fleet (#3101 / #3102): a project's TEAM (its persona-relationship graph, `blueprint.team`)
// seeds the fleet's ROLE-ACTOR streams. A team agent position bound to a lifecycle-role persona —
// curator, documentor, reviewer, tester, juror, issuer — becomes a fleet stream that launches WITH the
// fleet (at the project hub; the launch composition + hub cwd land in A-2), so "an actor is present if
// it's in the project's team" (#3101).
//
// WORKERS are deliberately NOT seeded here: a worker needs `owns` globs + `issues` only the planner can
// size, so worker/engineer positions stay planner-owned. The DIRECTOR is its own launch slot
// (`FleetDirector`), TRIAGE is per-repo, and the standing Studio roles (designer/architect/librarian) +
// the planner aren't fleet members — so none of those seed either. The MARKETER is opt-in (#2431): it
// only seeds when a team explicitly places one (Fleet Alpha does, #3143), never by default elsewhere.
//
// Pure (no React/Tauri) so it's unit-testable; the launch path (`usePlanPublish`, A-2) composes the
// result into the `FleetPlan` before `fleetStartProject`.
import type { BlueprintTeam } from "../stages/blueprintTypes";
import type { Persona } from "@/features/personas";
import type { SessionRole } from "@/shared/lib/session/sessionRoles";
import type { AgentStream } from "./planFleet";

/** The lifecycle role-actors a team position may seed into the fleet — project-wide singletons with no
 *  owned globs/issues (unlike a worker). One session each; deduped by role so a team never launches two
 *  curators/documentors/… and a planner-authored stream for a role always wins over the team's. */
export const SEEDABLE_TEAM_ROLES: ReadonlySet<SessionRole> = new Set<SessionRole>([
  "curator", "documentor", "reviewer", "tester", "juror", "issuer", "marketer",
]);

/** Slug a team position's `nodeId` into a fleet stream id: lowercase, `[a-z0-9-]`, collapsed — so it is
 *  safe as a pane-id tail (`<key>:<id>`) and a git branch name. Empty → `"role"`. */
function streamIdFromNode(nodeId: string): string {
  return (
    nodeId.toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/-{2,}/g, "-").replace(/^-+|-+$/g, "") || "role"
  );
}

/**
 * Derive the extra fleet streams a project's TEAM contributes — one per team agent position whose
 * persona is a {@link SEEDABLE_TEAM_ROLES} lifecycle actor, deduped by role against BOTH the planner's
 * existing streams and each other (these roles are singletons). Deterministic (positions in author
 * order). Returns `[]` for no team / no seedable positions.
 *
 * Each derived stream carries only its `persona` reference (which resolves role/prompt/skills/model at
 * launch) with empty `owns`/`issues`/`dependsOn` and an empty `repo` — a role-actor runs project-wide at
 * the hub, not inside a per-stream repo worktree (the launch routes it there in A-2).
 *
 * @param team      the project's blueprint team (positions + relationships), or undefined
 * @param personas  the persona library (resolves a position's `personaId` → its role/name)
 * @param existing  the planner's fleet streams — a role already covered by one is NOT re-seeded
 */
export function teamRoleStreams(
  team: BlueprintTeam | undefined,
  personas: Persona[],
  existing: ReadonlyArray<Pick<AgentStream, "persona">>,
): AgentStream[] {
  if (!team || team.positions.length === 0) return [];
  const byId = new Map(personas.map((p) => [p.id, p]));
  // Roles already present among the planner's streams (via each stream's persona) — never double a role.
  const covered = new Set<SessionRole>();
  for (const s of existing) {
    const role = s.persona ? byId.get(s.persona)?.role : undefined;
    if (role) covered.add(role);
  }
  const out: AgentStream[] = [];
  const seenIds = new Set<string>();
  for (const pos of team.positions) {
    if (pos.kind !== "agent" || !pos.personaId) continue;
    const persona = byId.get(pos.personaId);
    if (!persona || !SEEDABLE_TEAM_ROLES.has(persona.role)) continue;
    if (covered.has(persona.role)) continue; // a planner stream (or an earlier team position) owns this role
    covered.add(persona.role);
    let id = streamIdFromNode(pos.nodeId);
    while (seenIds.has(id)) id = `${id}-1`; // guard a pathological nodeId-slug collision
    seenIds.add(id);
    out.push({
      id,
      name: pos.label?.trim() || persona.name || persona.role,
      repo: "", // hub-scoped: runs at the project hub (A-2), not a repo worktree
      owns: [],
      issues: [],
      dependsOn: [],
      persona: persona.id,
    });
  }
  return out;
}

