import { useState } from "react";
import { githubRequest } from "@/shared/lib/github/github";
import { useGithubQuery } from "@/shared/lib/github/useGithubQuery";
import { ProjectsHeader } from "../list/ProjectsHeader";
import { useActiveProject, QueryBanner } from "./useActiveProjectGithub";
import {
  buildGantt, tickIntervalWeeks, tickLabel, windowStartFrom,
  WINDOW_PRESETS, DEFAULT_WINDOW_WEEKS,
  type GhMilestone,
} from "./roadmapGantt";
import { StatCard } from "@/shared/ui/charts";
import { SkeletonChart } from "@/shared/ui/feedback/Skeleton";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Grid } from "@/shared/ui/layout/Grid";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Card } from "@/shared/ui/data/Card";
import { Text } from "@/shared/ui/typography/Text";
import { Box } from "@/shared/ui/layout/Box";
import { Button } from "@/shared/ui/controls/Button";

function BurnDown({ open, closed }: { open: number; closed: number }) {
  const total = open + closed;
  if (total === 0) {
    return (
      <Text as="div" mono size={11} tone="dim" style={{ padding: "20px 0" }}>
        No issue data available.
      </Text>
    );
  }
  // Simple two-point chart: total issues created vs closed
  const W = 1140, H = 120, PAD = { l: 36, r: 20, t: 14, b: 24 };
  const innerW = W - PAD.l - PAD.r;
  const innerH = H - PAD.t - PAD.b;
  const x0 = PAD.l, x1 = PAD.l + innerW;
  const yVal = (v: number) => PAD.t + (1 - v / total) * innerH;
  const idealPath = `M ${x0} ${yVal(total)} L ${x1} ${yVal(0)}`;
  const actualPath = `M ${x0} ${yVal(total)} L ${x1} ${yVal(open)}`;

  return (
    <svg width={W} height={H} style={{ width: "100%", maxWidth: W, display: "block" }}>
      {[0, Math.round(total / 2), total].map(v => (
        <g key={v}>
          <line x1={PAD.l} y1={yVal(v)} x2={W - PAD.r} y2={yVal(v)} stroke="var(--border-soft)" strokeDasharray="2 3" />
          <text x={PAD.l - 4} y={yVal(v) + 3} textAnchor="end" fontFamily="var(--mono)" fontSize="9" fill="var(--fg-dim)">{v}</text>
        </g>
      ))}
      <path d={idealPath} fill="none" stroke="var(--fg-dim)" strokeDasharray="3 4" strokeWidth="1.5" />
      <path d={actualPath} fill="none" stroke="var(--accent)" strokeWidth="2" />
      <circle cx={x0} cy={yVal(total)} r="3" fill="var(--accent)" />
      <circle cx={x1} cy={yVal(open)} r="3" fill="var(--accent)" />
      <text x={x1 - 2} y={yVal(open) - 6} textAnchor="end" fontFamily="var(--mono)" fontSize="9" fill="var(--accent)">open · {open}</text>
      <text x={x1 - 2} y={yVal(0) - 6} textAnchor="end" fontFamily="var(--mono)" fontSize="9" fill="var(--fg-dim)">ideal · 0</text>
    </svg>
  );
}

export function Roadmap() {
  const project = useActiveProject();

  // Filters: time window (clamps the Gantt so milestones aren't spread across the
  // project's whole history) and milestone state.
  const [windowWeeks, setWindowWeeks] = useState<number | null>(DEFAULT_WINDOW_WEEKS);
  const [stateFilter, setStateFilter] = useState<"all" | "open" | "closed">("all");

  // Use the primary repo; fall back to any repo derived from board items.
  const effectiveRepo = project.repo || project.repos[0] || "";

  const { data, loading, error } = useGithubQuery<GhMilestone[]>(
    () => githubRequest<GhMilestone[]>(
      `repos/${effectiveRepo}/milestones?state=all&per_page=20&sort=due_on&direction=asc`,
    ),
    [effectiveRepo],
    !!effectiveRepo,
  );
  const milestones = Array.isArray(data) ? data : [];

  // Apply the state filter, then build the windowed Gantt. Stats reflect the
  // filtered set so the cards match what the chart shows.
  const now = new Date();
  const filtered = stateFilter === "all" ? milestones : milestones.filter(m => m.state === stateFilter);
  const { rows, totalWeeks, todayWeek, origin } = buildGantt(filtered, windowStartFrom(windowWeeks, now), now);
  const tickInterval = tickIntervalWeeks(totalWeeks);
  const tickCount    = Math.ceil(totalWeeks / tickInterval) + 1;

  const totalOpen   = filtered.reduce((s, m) => s + m.open_issues, 0);
  const totalClosed = filtered.reduce((s, m) => s + m.closed_issues, 0);
  const totalIssues = totalOpen + totalClosed;
  const velocity = totalIssues > 0 ? (totalClosed / Math.max(todayWeek, 1)).toFixed(1) : "—";

  // Skeleton the stat values only on the FIRST load (keep them during a refetch). #2248.
  const isLoading = loading && milestones.length === 0;
  const stats = [
    { k: "open issues",   v: String(totalOpen),           sub: `of ${totalIssues} total`,  tone: "accent"  },
    { k: "milestones",    v: String(filtered.length),     sub: `${filtered.filter(m => m.state === "closed").length} closed`, tone: "info" },
    { k: "velocity",      v: `${velocity}/wk`,            sub: "issues closed per week",   tone: "success" },
    { k: "repo",          v: effectiveRepo.split("/")[1] || "—", sub: effectiveRepo || "no repo", tone: "fg" },
  ] as const;

  return (
    <>
      <ProjectsHeader project={project} />
      <section style={{ flex: 1, overflow: "auto", padding: "18px 24px" }}>
        <Box style={{ maxWidth: 1240, margin: "0 auto" }}>
          <QueryBanner error={error} style={{ marginBottom: 16 }} />

          {/* Stat cards */}
          <Grid cols={4} gap={10} style={{ marginBottom: 18 }}>
            {stats.map(({ k, v, sub, tone }) => (
              <StatCard key={k} k={k} v={v} sub={sub} tone={tone} loading={isLoading && k !== "repo"} />
            ))}
          </Grid>

          {/* Gantt */}
          <Card style={{ padding: "16px 20px" }}>
            <Row gap={10} wrap style={{ marginBottom: 14 }}>
              <Text as="h3" style={{ margin: 0 }}>Milestones · weeks</Text>
              <Box as="span" className="hint">
                {loading ? "loading…"
                  : `${rows.length} shown${milestones.length !== rows.length ? ` of ${milestones.length}` : ""}`}
              </Box>
              <Spacer />
              {(() => {
                const chip = (active: boolean, label: string, onClick: () => void) => (
                  <Button
                    key={label}
                    onClick={onClick}
                    style={{
                      height: 22, fontSize: 10, padding: "0 8px",
                      background: active ? "var(--bg-elev2)" : "var(--bg-elev)",
                      borderColor: active ? "var(--accent-dim)" : "var(--border-soft)",
                      color: active ? "var(--accent)" : "var(--fg-muted)",
                    }}
                  >{label}</Button>
                );
                return (
                  <>
                    <Text mono size={9.5} tone="dim">state</Text>
                    <Row gap={4} align="stretch">
                      {(["all", "open", "closed"] as const).map(s => chip(stateFilter === s, s, () => setStateFilter(s)))}
                    </Row>
                    <Text mono size={9.5} tone="dim" style={{ marginLeft: 6 }}>window</Text>
                    <Row gap={4} align="stretch">
                      {WINDOW_PRESETS.map(p => chip(windowWeeks === p.weeks, p.label, () => setWindowWeeks(p.weeks)))}
                    </Row>
                  </>
                );
              })()}
            </Row>

            {loading && rows.length === 0 && <SkeletonChart height={160} />}

            {!loading && rows.length === 0 && (
              <EmptyState size="sm" iconVariant="dashed" icon="○"
                title="No milestones yet"
                description={`No milestones found for ${effectiveRepo || "this project"}.`}
                style={{ padding: "22px 12px" }} />
            )}

            {rows.length > 0 && (
              <>
                {/* Week header */}
                <Grid cols="230px 1fr" gap={14} style={{ marginBottom: 8 }}>
                  <Box />
                  <Box style={{ position: "relative", height: 24 }}>
                    {Array.from({ length: tickCount }, (_, i) => {
                      const week = i * tickInterval;
                      if (week > totalWeeks) return null;
                      const pct = (week / totalWeeks) * 100;
                      return (
                        <Box key={i} className="mono" style={{
                          position: "absolute", left: `${pct}%`,
                          top: 0, paddingLeft: 4, paddingTop: 4,
                          borderLeft: i === 0 ? "none" : "1px dashed var(--border-soft)",
                          fontSize: 10, color: "var(--fg-dim)",
                          whiteSpace: "nowrap",
                        }}>
                          {tickLabel(week, origin, tickInterval)}
                        </Box>
                      );
                    })}
                    {todayWeek < totalWeeks && (
                      <Box style={{
                        position: "absolute", top: 0, bottom: -300,
                        left: `${(todayWeek / totalWeeks) * 100}%`,
                        width: 0, borderLeft: "1.5px dashed var(--accent)", zIndex: 2,
                      }}>
                        <Box as="span" className="mono" style={{ position: "absolute", top: -2, left: 4, fontSize: 9.5, color: "var(--accent)" }}>today</Box>
                      </Box>
                    )}
                  </Box>
                </Grid>

                {/* Milestone rows */}
                <Stack gap={8}>
                  {rows.map(m => (
                    <Grid key={m.id} cols="230px 1fr" gap={14} align="center">
                      <Box>
                        <Row gap={6} align="baseline">
                          <Text mono size={11} tone="accent">M{m.id}</Text>
                          <Text as="span" size={12} style={{ fontFamily: "var(--sans)", color: "var(--fg)" }}>{m.title}</Text>
                        </Row>
                        <Text as="div" mono size={9.5} tone="dim" style={{ marginTop: 3 }}>
                          due {m.dueLabel}
                        </Text>
                      </Box>
                      <Box style={{ position: "relative", height: 32 }}>
                        {Array.from({ length: tickCount }, (_, i) => {
                          const week = i * tickInterval;
                          if (week > totalWeeks) return null;
                          return (
                            <Box key={i} bg="var(--border-soft)" style={{ position: "absolute", top: 0, bottom: 0, left: `${(week / totalWeeks) * 100}%`, width: 1}} />
                          );
                        })}
                        <Row style={{
                          position: "absolute", top: 4, bottom: 4,
                          left: `${(m.startWeek / totalWeeks) * 100}%`,
                          width: `${(m.lengthWeeks / totalWeeks) * 100}%`,
                          borderRadius: 5, overflow: "hidden",
                          background:
                            m.state === "done"     ? "color-mix(in oklch, var(--success), transparent 60%)"
                            : m.state === "doing"  ? "color-mix(in oklch, var(--accent), transparent 70%)"
                            : m.state === "upcoming" ? "color-mix(in oklch, var(--info), transparent 80%)"
                            : "var(--bg-elev2)",
                          border: "1px solid " + (
                            m.state === "done"     ? "color-mix(in oklch, var(--success), transparent 40%)"
                            : m.state === "doing"  ? "var(--accent-dim)"
                            : m.state === "upcoming" ? "color-mix(in oklch, var(--info), transparent 60%)"
                            : "var(--border-soft)"
                          ),
                        }}>
                          {m.pct > 0 && (
                            <Box bg="color-mix(in oklch, var(--accent), transparent 40%)" style={{
                              position: "absolute", inset: 0, width: `${m.pct * 100}%`,
                            }} />
                          )}
                          <Box as="span" className="mono" pad={[0, 10]} style={{
                            position: "relative",
                            fontSize: 10.5,
                            color: m.state === "backlog" ? "var(--fg-muted)" : "var(--fg)",
                            whiteSpace: "nowrap",
                          }}>
                            {m.lengthWeeks}w · {m.pct > 0 ? `${Math.round(m.pct * 100)}% done` : m.state}
                          </Box>
                        </Row>
                      </Box>
                    </Grid>
                  ))}
                </Stack>
              </>
            )}
          </Card>

          {/* Burn-down */}
          <Card style={{ padding: "16px 20px", marginTop: 14 }}>
            <Row gap={10} align="baseline" style={{ marginBottom: 14 }}>
              <Text as="h3" style={{ margin: 0 }}>Issue progress</Text>
              <Box as="span" className="hint">{totalIssues} total · {totalClosed} closed · {totalOpen} remaining</Box>
            </Row>
            <BurnDown open={totalOpen} closed={totalClosed} />
          </Card>
        </Box>
      </section>
    </>
  );
}

runtime.features/planner/github/roadmapGantt.ts:
// Pure Gantt/timeline model for the Projects → Roadmap tab.
//
// Kept free of React / Tauri imports so the windowing and bar math can be unit
// tested in isolation. The Roadmap view feeds it GitHub milestones plus a
// selected time window; it returns positioned rows and the axis scale.

// The milestone shape is the canonical one in shared/lib/github/types (#1528); re-exported here so
// existing importers (Roadmap.tsx, the tests) keep their `from "./roadmapGantt"` import.
import type { GhMilestone } from "@/shared/lib/github/types";
export type { GhMilestone };

const WEEK_MS = 7 * 24 * 3600 * 1000;

export interface GanttRow {
  id: string;
  title: string;
  startWeek: number;
  lengthWeeks: number;
  pct: number;
  state: "done" | "doing" | "upcoming" | "backlog";
  creator: string;
  dueLabel: string;
}

export interface GanttModel {
  rows: GanttRow[];
  totalWeeks: number;
  todayWeek: number;
  origin: Date;
}

/** Time-window presets for the Roadmap filter. `weeks: null` = all time. */
export const WINDOW_PRESETS: { label: string; weeks: number | null }[] = [
  { label: "8w",  weeks: 8 },
  { label: "28w", weeks: 28 },
  { label: "1y",  weeks: 52 },
  { label: "all", weeks: null },
];

/** Default window — bounds the timeline on first load so it isn't spread across
 *  the project's entire history. */
export const DEFAULT_WINDOW_WEEKS = 28;

export function weeksBetween(a: Date, b: Date): number {
  return Math.max(0, Math.ceil((b.getTime() - a.getTime()) / WEEK_MS));
}

/** The start of a window `weeks` before `now`, or null for all-time. */
export function windowStartFrom(weeks: number | null, now: Date = new Date()): Date | null {
  return weeks == null ? null : new Date(now.getTime() - weeks * WEEK_MS);
}

export function tickIntervalWeeks(totalWeeks: number): number {
  if (totalWeeks <= 16)  return 1;
  if (totalWeeks <= 52)  return 4;
  if (totalWeeks <= 130) return 8;
  return 13;
}

export function tickLabel(weekIndex: number, origin: Date, interval: number): string {
  if (interval <= 1) return `w${weekIndex + 1}`;
  const d = new Date(origin.getTime() + weekIndex * WEEK_MS);
  return d.toLocaleDateString("en-US", { month: "short", year: "2-digit" });
}

function milestoneEnd(m: GhMilestone): Date {
  return m.due_on ? new Date(m.due_on) : new Date(new Date(m.created_at).getTime() + 14 * 24 * 3600 * 1000);
}

/**
 * Build the Gantt model for the given milestones, scaled to a time window.
 *
 * `windowStart` (from {@link windowStartFrom}) clamps the timeline's left edge:
 * milestones whose end falls entirely before it are dropped, and the axis origin
 * is pinned to the window edge (or the earliest kept milestone, whichever is
 * later) so a few far-apart due dates can't squash everything into slivers. Bars
 * that began before the window are clamped to start at the edge. Pass `null` for
 * all time. `now` is injectable for testing.
 */
export function buildGantt(
  milestones: GhMilestone[],
  windowStart: Date | null,
  now: Date = new Date(),
): GanttModel {
  const items = milestones.map(m => ({ m, start: new Date(m.created_at), end: milestoneEnd(m) }));
  const kept = windowStart
    ? items.filter(x => x.end.getTime() >= windowStart.getTime())
    : items;

  if (kept.length === 0) return { rows: [], totalWeeks: 8, todayWeek: 0, origin: now };

  const earliestStart = kept.reduce((a, b) => (a.start < b.start ? a : b)).start;
  // Pin the origin to the window edge when it's later than the earliest kept
  // start; otherwise start at the earliest milestone (no empty left margin).
  const origin = windowStart && windowStart.getTime() > earliestStart.getTime() ? windowStart : earliestStart;
  const horizon = kept.reduce((a, b) => (a.end > b.end ? a : b)).end;
  const totalWeeks = Math.max(weeksBetween(origin, horizon) + 1, 8);
  const todayWeek = weeksBetween(origin, now);

  const rows: GanttRow[] = kept.map(({ m, start, end }) => {
    // Clamp a bar that began before the window to the visible left edge.
    const effStart = start.getTime() < origin.getTime() ? origin : start;
    const startWeek = weeksBetween(origin, effStart);
    const lengthWeeks = Math.max(1, weeksBetween(effStart, end));
    const total = m.open_issues + m.closed_issues;
    const pct = total > 0 ? m.closed_issues / total : 0;
    const state: GanttRow["state"] =
      m.state === "closed" ? "done"
      : pct > 0 ? "doing"
      : startWeek <= todayWeek ? "upcoming"
      : "backlog";
    const dueLabel = m.due_on
      ? new Date(m.due_on).toLocaleDateString("en-US", { month: "short", day: "numeric" })
      : "no due date";

    return { id: String(m.number), title: m.title, startWeek, lengthWeeks, pct, state, creator: m.creator?.login ?? "", dueLabel };
  });

  return { rows, totalWeeks, todayWeek, origin };
}

