// The dependency manifest (#1111/#1127): the authoritative, planner-owned list of the libraries every
// repo depends on, defined ONCE during planning so the fleet doesn't each add/redefine deps in
// parallel worktrees and collide at integration. The planner records it via `bsc-plan deps set` into
// plan.db (#1191 — was a raw `dependencies.json`); the poll reflects the stored manifest into the
// DEPENDENCIES section, the Dependencies gate reads its count, publish pre-populates each repo's real
// `package.json` / `Cargo.toml` from it, and each worker's CLAUDE.local.md inlines the locked set with
// a "don't touch the manifests" guardrail. This module stays a pure + tolerant manifest model (it
// parses the same shape whether it arrives from plan.db or a legacy file) — no React/Tauri.
//
// BARREL (#2148): the model was decomposed into colocated sibling modules; this file preserves the
// original public API so every importer keeps working unchanged. Each concern lives in its own module:
//   · dependencyTypes           — the manifest types + section key
//   · dependencyParse           — parsing + the per-repo / per-ecosystem selectors
//   · dependencySources         — grouping deps by their source registry (Deploy pane, #1127)
//   · dependencyStreams         — the per-stream shared-dependencies view (Streams pane, #1429)
//   · dependencyManifests       — the publish-time package.json / Cargo.toml writers
//   · dependencyRegistryConfig  — the .npmrc / .cargo/config.toml writers
//   · dependencyWorkerBlock     — the CLAUDE.local.md locked-deps block

export {
  DEPENDENCIES_KEY,
  type DependencyEcosystem,
  type PlanDependency,
  type DependencyRegistry,
  type DependencyManifest,
} from "@/features/planner/issues/dependencyTypes";

export {
  parseDependencyManifest,
  parseDependenciesFile,
  depsForRepo,
  bucketByEcosystem,
} from "@/features/planner/issues/dependencyParse";

export {
  type DependencySourceGroup,
  groupDependenciesBySource,
} from "@/features/planner/issues/dependencySources";

export {
  type StreamDependency,
  type StreamDepGroup,
  type SharedRepoDeps,
  sharedRepoDependencies,
  unlockedSharedRepos,
} from "@/features/planner/issues/dependencyStreams";

export {
  mergeIntoPackageJson,
  mergeIntoCargoToml,
} from "@/features/planner/issues/dependencyManifests";

export {
  buildNpmrc,
  buildCargoConfig,
} from "@/features/planner/issues/dependencyRegistryConfig";

export {
  buildWorkerDependencyBlock,
} from "@/features/planner/issues/dependencyWorkerBlock";

runtime.features/planner/issues/dependencyManife:
// ── Manifest writers (publish-time scaffold seed, #1111) ──────────────────────────
// Additive + never-clobber: an existing pinned version always wins over the planned one, so
// re-publishing or seeding a hand-edited manifest never downgrades or fights a real dependency.

import type { PlanDependency } from "@/features/planner/issues/dependencyTypes";

/** A crate/package name reduced to a valid bare identifier for a generated manifest. */
function safePkgName(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9_-]+/g, "-").replace(/^-+|-+$/g, "") || "app";
}

/**
 * Merge the npm dependencies into a `package.json`, returning the pretty-printed JSON (or `null`
 * when there are none to add). `existing` is the current file content (or null/empty for a fresh
 * repo — a minimal private package is generated). An npm dep already present in the manifest keeps
 * its pinned version; only genuinely missing deps are added.
 */
export function mergeIntoPackageJson(existing: string | null, pkgName: string, deps: PlanDependency[]): string | null {
  const npm = deps.filter((d) => d.ecosystem === "npm");
  if (!npm.length) return null;

  let json: Record<string, unknown> = {};
  if (existing && existing.trim()) {
    try {
      const parsed: unknown = JSON.parse(existing);
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) json = parsed as Record<string, unknown>;
    } catch { /* unparseable — treat as fresh rather than clobber blindly */ return null; }
  } else {
    json = { name: safePkgName(pkgName), version: "0.1.0", private: true };
  }

  const ensure = (field: "dependencies" | "devDependencies") => {
    const cur = json[field];
    return (cur && typeof cur === "object" && !Array.isArray(cur)) ? { ...(cur as Record<string, string>) } : {};
  };
  const runtime = ensure("dependencies");
  const development = ensure("devDependencies");

  for (const d of npm) {
    const target = d.dev ? development : runtime;
    if (target[d.name] === undefined) target[d.name] = d.version ?? "*"; // never clobber a pinned version
  }
  if (Object.keys(runtime).length) json.dependencies = sortedRecord(runtime);
  if (Object.keys(development).length) json.devDependencies = sortedRecord(development);

  return JSON.stringify(json, null, 2) + "\n";
}

function sortedRecord(r: Record<string, string>): Record<string, string> {
  return Object.fromEntries(Object.keys(r).sort().map((k) => [k, r[k]]));
}

/** A single Cargo dependency line. A dep with a non-default `source` takes the table form so cargo
 *  resolves it against the named registry: `name = { version = "x", registry = "src" }`. */
function cargoDepLine(d: PlanDependency): string {
  const ver = d.version ?? "*";
  return d.source
    ? `${d.name} = { version = "${ver}", registry = "${d.source}" }`
    : `${d.name} = "${ver}"`;
}

/**
 * Merge the cargo dependencies into a `Cargo.toml`, returning the file content (or `null` when
 * there are none to add). With no existing manifest a minimal valid one is generated (`[package]`
 * + `[dependencies]`); with an existing one, missing deps are appended to its `[dependencies]` /
 * `[dev-dependencies]` table (a dep already named in the file is left untouched — never clobbered).
 * Line-oriented on purpose: it adds without re-serializing, so hand-written formatting/comments
 * survive.
 */
export function mergeIntoCargoToml(existing: string | null, crateName: string, deps: PlanDependency[]): string | null {
  const cargo = deps.filter((d) => d.ecosystem === "cargo");
  if (!cargo.length) return null;

  if (!existing || !existing.trim()) {
    const runtime = cargo.filter((d) => !d.dev);
    const development = cargo.filter((d) => d.dev);
    const out = [
      "[package]",
      `name = "${safePkgName(crateName)}"`,
      `version = "0.1.0"`,
      `edition = "2021"`,
      "",
      "[dependencies]",
      ...runtime.map(cargoDepLine),
    ];
    if (development.length) out.push("", "[dev-dependencies]", ...development.map(cargoDepLine));
    return out.join("\n") + "\n";
  }

  // Append-only into the existing file: add a missing dep under its table, creating the table if needed.
  const named = new Set(
    [...existing.matchAll(/^\s*([A-Za-z0-9_-]+)\s*=/gm)].map((m) => m[1].toLowerCase()),
  );
  let out = existing.replace(/\s*$/, "\n");
  const addToTable = (header: string, table: PlanDependency[]) => {
    const missing = table.filter((d) => !named.has(d.name.toLowerCase()));
    if (!missing.length) return;
    const lines = missing.map(cargoDepLine);
    const headerRe = new RegExp(`^\\[${header.replace(/[-]/g, "\\$&")}\\]\\s*$`, "m");
    const m = headerRe.exec(out);
    if (m) {
      // Insert right after the table header.
      const insertAt = m.index + m[0].length;
      out = out.slice(0, insertAt) + "\n" + lines.join("\n") + out.slice(insertAt);
    } else {
      out = out.replace(/\n*$/, "\n") + `\n[${header}]\n` + lines.join("\n") + "\n";
    }
    missing.forEach((d) => named.add(d.name.toLowerCase()));
  };
  addToTable("dependencies", cargo.filter((d) => !d.dev));
  addToTable("dev-dependencies", cargo.filter((d) => d.dev));
  return out;
}

// Parsing + basic selectors for the dependency manifest (#1111/#1127). Pure + tolerant: it parses the
// same shape whether it arrives from plan.db or a legacy `dependencies.json`, and the selectors below
// slice the parsed list per-repo / per-ecosystem for the writers and the worker block.

import type {
  DependencyEcosystem,
  DependencyManifest,
  DependencyRegistry,
  PlanDependency,
} from "@/features/planner/issues/dependencyTypes";

function str(v: unknown): string | undefined {
  return typeof v === "string" && v.trim() ? v.trim() : undefined;
}

/**
 * Parse a stored dependency manifest (the plan.db blob, or a legacy `dependencies.json`) into the
 * full manifest (#1127). Accepts a bare JSON array of dependency
 * objects (the #1111 form, ⇒ no registries), or `{ "dependencies": [...], "registries": {...} }`.
 * Tolerant: bad JSON ⇒ empty manifest; a dependency without a name or a recognized ecosystem
 * (`npm` | `cargo`) is dropped; duplicates (same repo+ecosystem+name) are de-duped, first write
 * winning; a registry without a string `url` is dropped.
 */
export function parseDependencyManifest(raw: string): DependencyManifest {
  const empty: DependencyManifest = { dependencies: [], registries: {} };
  const t = (raw ?? "").trim();
  if (!t) return empty;
  let data: unknown;
  try { data = JSON.parse(t); } catch { return empty; }
  const obj = (data && typeof data === "object" && !Array.isArray(data)) ? data as Record<string, unknown> : null;
  const arr: unknown[] = Array.isArray(data)
    ? data
    : (obj && Array.isArray(obj.dependencies)) ? obj.dependencies as unknown[] : [];

  const dependencies: PlanDependency[] = [];
  const seen = new Set<string>();
  for (const item of arr) {
    if (!item || typeof item !== "object") continue;
    const o = item as Record<string, unknown>;
    const name = str(o.name);
    const eco = str(o.ecosystem)?.toLowerCase();
    if (!name || (eco !== "npm" && eco !== "cargo")) continue;
    const repo = str(o.repo);
    const key = `${repo ?? "*"}|${eco}|${name.toLowerCase()}`;
    if (seen.has(key)) continue;
    seen.add(key);
    dependencies.push({
      repo,
      ecosystem: eco,
      name,
      version: str(o.version),
      dev: o.dev === true,
      why: str(o.why),
      source: str(o.source),
      stream: str(o.stream),
    });
  }

  const registries: Record<string, DependencyRegistry> = {};
  const regRaw = obj && obj.registries && typeof obj.registries === "object" && !Array.isArray(obj.registries)
    ? obj.registries as Record<string, unknown> : {};
  for (const [k, v] of Object.entries(regRaw)) {
    if (!v || typeof v !== "object") continue;
    const r = v as Record<string, unknown>;
    const url = str(r.url);
    if (!url) continue;
    registries[k] = { url, scope: str(r.scope), auth: str(r.auth) };
  }
  return { dependencies, registries };
}

/** Parse just the dependency list (#1111 back-compat — the count/gate/seeding callers). */
export function parseDependenciesFile(raw: string): PlanDependency[] {
  return parseDependencyManifest(raw).dependencies;
}

/** The dependencies that apply to a given repo: those tagged with that `owner/repo`, plus the
 *  ecosystem-wide ones (no `repo`). */
export function depsForRepo(deps: PlanDependency[], fullName: string): PlanDependency[] {
  return deps.filter((d) => !d.repo || d.repo === fullName);
}

/** Split a repo's deps into npm / cargo buckets (for the manifest writers + the worker block). */
export function bucketByEcosystem(deps: PlanDependency[]): Record<DependencyEcosystem, PlanDependency[]> {
  return {
    npm: deps.filter((d) => d.ecosystem === "npm"),
    cargo: deps.filter((d) => d.ecosystem === "cargo"),
  };
}

runtime.features/planner/issues/dependencyRegist:
// ── Registry config writers (#1127) ──────────────────────────────────────────────
// Generate the source/registry config so a private dependency is fetchable from the first commit.
// Only the registries a repo's deps actually reference are emitted; public-only repos get nothing.

import type {
  DependencyEcosystem,
  DependencyRegistry,
  PlanDependency,
} from "@/features/planner/issues/dependencyTypes";

/** The `//host[/path]/` key npm's `.npmrc` uses for an auth token, derived from a registry URL. */
function npmrcHostKey(url: string): string {
  return url.replace(/^https?:/i, "").replace(/\/?$/, "/");
}

/** The registry KEYs (sorted, deterministic) that a repo's deps of one ecosystem reference and that
 *  are actually defined in the registries map. */
function usedRegistries(registries: Record<string, DependencyRegistry>, deps: PlanDependency[], eco: DependencyEcosystem): string[] {
  const used = new Set(deps.filter((d) => d.ecosystem === eco && d.source && registries[d.source]).map((d) => d.source!));
  return [...used].sort();
}

/**
 * Build a repo's `.npmrc` from the registries its npm deps reference (#1127): a scoped registry as
 * `@scope:registry=<url>`, an unscoped one as the default `registry=<url>`, plus a `${SECRET}` auth
 * token line when the registry declares one. Returns null when no npm dep uses a private source.
 */
export function buildNpmrc(registries: Record<string, DependencyRegistry>, deps: PlanDependency[]): string | null {
  const keys = usedRegistries(registries, deps, "npm");
  if (!keys.length) return null;
  const lines: string[] = [];
  for (const key of keys) {
    const r = registries[key];
    lines.push(r.scope ? `${r.scope}:registry=${r.url}` : `registry=${r.url}`);
    if (r.auth) lines.push(`${npmrcHostKey(r.url)}:_authToken=\${${r.auth}}`);
  }
  return lines.join("\n") + "\n";
}

/**
 * Build a repo's `.cargo/config.toml` from the registries its cargo deps reference (#1127) — one
 * `[registries.<name>]` table with the index URL each. Returns null when no cargo dep uses a private
 * source. (Cargo reads the token from `CARGO_REGISTRIES_<NAME>_TOKEN`, kept out of the file.)
 */
export function buildCargoConfig(registries: Record<string, DependencyRegistry>, deps: PlanDependency[]): string | null {
  const keys = usedRegistries(registries, deps, "cargo");
  if (!keys.length) return null;
  const lines: string[] = [];
  for (const key of keys) lines.push(`[registries.${key}]`, `index = "${registries[key].url}"`, "");
  return lines.join("\n").replace(/\n+$/, "\n");
}

runtime.features/planner/issues/dependencySource:
// Group locked deps by the source (registry) each is pulled from (#1127) — the Deploy pane surface.

import type {
  DependencyEcosystem,
  DependencyRegistry,
  PlanDependency,
} from "@/features/planner/issues/dependencyTypes";

/** A source (registry) the project pulls from, with the deps fetched through it (#1127 UI). The
 *  public default per ecosystem is synthesized when a dep carries no `source`. */
export interface DependencySourceGroup {
  /** Stable key — the registry key, or `"npm"` / `"cargo"` for the ecosystem default. */
  key: string;
  name: string;
  /** True when this source is a non-default (private) registry. */
  private: boolean;
  url: string;
  scope?: string;
  /** Auth-token secret name (private sources only). */
  auth?: string;
  deps: PlanDependency[];
}

const PUBLIC_SOURCE: Record<DependencyEcosystem, { name: string; url: string }> = {
  npm:   { name: "npm registry", url: "registry.npmjs.org" },
  cargo: { name: "crates.io",    url: "crates.io" },
};

/** Group locked deps BY the source each is pulled from (#1127): one group per non-default registry
 *  referenced, plus one per ecosystem-default for deps without a `source`. Sorted defaults-first
 *  then by name, so the view is deterministic. Pure. */
export function groupDependenciesBySource(
  deps: PlanDependency[],
  registries: Record<string, DependencyRegistry>,
): DependencySourceGroup[] {
  const groups = new Map<string, DependencySourceGroup>();
  for (const dep of deps) {
    const reg = dep.source ? registries[dep.source] : undefined;
    // A dep whose `source` isn't a known registry falls back to the ecosystem's public default.
    const key = reg ? dep.source! : dep.ecosystem;
    let g = groups.get(key);
    if (!g) {
      g = reg
        ? { key, name: dep.source!, private: true, url: reg.url, scope: reg.scope, auth: reg.auth, deps: [] }
        : { key, name: PUBLIC_SOURCE[dep.ecosystem].name, private: false, url: PUBLIC_SOURCE[dep.ecosystem].url, deps: [] };
      groups.set(key, g);
    }
    g.deps.push(dep);
  }
  return [...groups.values()].sort((a, b) =>
    a.private === b.private ? a.name.localeCompare(b.name) : a.private ? 1 : -1);
}

runtime.features/planner/issues/dependencyStream:
// ── Shared-dependencies view (#1429) — the Streams pane surface ───────────────────────
// When 2+ streams build the same repo, each declares its OWN deps and they're reconciled into the
// repo's single lock. The pane shows them per repo → per stream, flags version-locked overlaps, and
// omits single-owner repos (their deps stay agent-managed — no parallel collision).

import type {
  DependencyRegistry,
  PlanDependency,
} from "@/features/planner/issues/dependencyTypes";
import {
  type DependencySourceGroup,
  groupDependenciesBySource,
} from "@/features/planner/issues/dependencySources";

/** A dep in the per-stream view + the cross-stream version-lock it participates in (#1429). */
export interface StreamDependency extends PlanDependency {
  /** Other streams on the SAME repo declaring the same package — a version-lock overlap. Empty ⇒ this
   *  stream alone declares it. Derived, not stored. */
  sharedWith: string[];
}

/** One stream's declared deps within a shared repo. */
export interface StreamDepGroup {
  stream: string;
  /** True when this stream owns no build deps (e.g. a director that just holds the reconciled lock). */
  empty: boolean;
  deps: StreamDependency[];
}

/** A repo built by 2+ streams: its per-stream declared deps (with shared overlaps derived), any
 *  unattributed repo-level deps, and the registries its deps reference. */
export interface SharedRepoDeps {
  repo: string;
  /** The streams building this repo (2+, in the order given). */
  streams: string[];
  byStream: StreamDepGroup[];
  /** Deps tagged to the repo but no stream (apply to every stream on it). */
  repoLevel: StreamDependency[];
  /** The source groups (public + private registries) the repo's deps reference. */
  registries: DependencySourceGroup[];
  /** Total declared deps across the repo. */
  total: number;
}

/**
 * Build the Streams pane's Shared-dependencies view (#1429): for every repo that 2+ streams build,
 * group its deps by the declaring stream and derive the cross-stream version-lock ("shared")
 * overlaps (same ecosystem+name declared by 2+ streams). A repo with a single owning stream is
 * OMITTED — its deps stay agent-managed. A multi-stream repo with no deps yet IS included (the
 * gate-blocking empty state). `repoStreams` maps each repo → the streams building it (from the
 * fleet, director included). Pure + deterministic (repos + streams sorted by the input order /
 * name). */
export function sharedRepoDependencies(
  deps: PlanDependency[],
  registries: Record<string, DependencyRegistry>,
  repoStreams: Record<string, string[]>,
): SharedRepoDeps[] {
  const out: SharedRepoDeps[] = [];
  for (const repo of Object.keys(repoStreams).sort()) {
    const streams = repoStreams[repo];
    if (!streams || streams.length < 2) continue; // single-owner / unbuilt repos excluded
    const repoDeps = deps.filter((d) => d.repo === repo);

    // name → set of streams that declare it (for the version-lock derivation).
    const declarers = new Map<string, Set<string>>();
    for (const d of repoDeps) {
      if (!d.stream) continue;
      const k = `${d.ecosystem}|${d.name.toLowerCase()}`;
      let s = declarers.get(k);
      if (!s) { s = new Set(); declarers.set(k, s); }
      s.add(d.stream);
    }
    const sharedFor = (d: PlanDependency): string[] => {
      const all = declarers.get(`${d.ecosystem}|${d.name.toLowerCase()}`);
      return all ? [...all].filter((x) => x !== d.stream).sort() : [];
    };

    const byStreamMap = new Map<string, StreamDependency[]>(streams.map((s) => [s, []]));
    const repoLevel: StreamDependency[] = [];
    for (const d of repoDeps) {
      const sd: StreamDependency = { ...d, sharedWith: sharedFor(d) };
      if (d.stream && byStreamMap.has(d.stream)) byStreamMap.get(d.stream)!.push(sd);
      else if (d.stream) { byStreamMap.set(d.stream, [sd]); }   // a declarer not in repoStreams — keep it
      else repoLevel.push(sd);
    }
    const byStream: StreamDepGroup[] = [...byStreamMap.keys()].map((s) => {
      const sd = byStreamMap.get(s)!;
      return { stream: s, empty: sd.length === 0, deps: sd };
    });
    out.push({
      repo, streams,
      byStream,
      repoLevel,
      registries: groupDependenciesBySource(repoDeps, registries),
      total: repoDeps.length,
    });
  }
  return out;
}

/** Repos that have 2+ streams but NO locked deps yet — the gate-blocking shared repos (#1429). The
 *  Streams dependency gate requires every multi-stream repo to have ≥1 locked dep; this lists the
 *  ones still missing. Empty ⇒ the (conditional) dependency gate is satisfied. */
export function unlockedSharedRepos(
  deps: PlanDependency[],
  repoStreams: Record<string, string[]>,
): string[] {
  return Object.keys(repoStreams)
    .filter((r) => (repoStreams[r]?.length ?? 0) >= 2 && !deps.some((d) => d.repo === r))
    .sort();
}

// The dependency manifest (#1111/#1127): the authoritative, planner-owned list of the libraries every
// repo depends on, defined ONCE during planning so the fleet doesn't each add/redefine deps in
// parallel worktrees and collide at integration. The planner records it via `bsc-plan deps set` into
// plan.db (#1191 — was a raw `dependencies.json`); the poll reflects the stored manifest into the
// DEPENDENCIES section, the Dependencies gate reads its count, publish pre-populates each repo's real
// `package.json` / `Cargo.toml` from it, and each worker's CLAUDE.local.md inlines the locked set with
// a "don't touch the manifests" guardrail. This module stays a pure + tolerant manifest model (it
// parses the same shape whether it arrives from plan.db or a legacy file) — no React/Tauri.

/** The dependency-manifest section key. The stored manifest (`{ dependencies, registries }`) is
 *  DB-owned (#1191): the poll mirrors `plan_get_deps` here. Surfaced by the poll like `features.json`;
 *  not rendered as a plan section. The legacy `dependencies.json` file shares this key during the
 *  one-time import. */
export const DEPENDENCIES_KEY = "dependencies";

/** A package-manager ecosystem the manifest can target. */
export type DependencyEcosystem = "npm" | "cargo";

/** One locked dependency: which repo + ecosystem it belongs to, its name + version, and why. */
export interface PlanDependency {
  /** `owner/repo` this applies to. Absent ⇒ applies to every repo of its ecosystem. */
  repo?: string;
  /** The package manager this dependency installs through. */
  ecosystem: DependencyEcosystem;
  /** Package / crate name. */
  name: string;
  /** Version range (npm: `^1.2.0`) or version (cargo: `1.2`). Absent ⇒ `*` / latest. */
  version?: string;
  /** A development-only dependency (devDependencies / [dev-dependencies]). */
  dev?: boolean;
  /** One-line rationale — surfaced in the worker manifest so the choice is legible. */
  why?: string;
  /** The registry this is fetched from (#1127) — a KEY into the manifest's `registries` map. Absent
   *  ⇒ the ecosystem's public default (npm registry / crates.io). A non-public source generates the
   *  registry config (`.npmrc` / `.cargo/config.toml`) at publish. */
  source?: string;
  /** The fleet STREAM that declared this dep (#1429). When 2+ streams build the same repo, deps are
   *  declared per stream and reconciled into the repo's single lock; the Streams pane surfaces them
   *  per stream and flags version-locked overlaps. Absent ⇒ a repo-level (unattributed) dep. */
  stream?: string;
}

/** A non-default registry a dependency is fetched from (#1127). The `auth` token's VALUE lives in the
 *  host vault — only its secret NAME is recorded here (and as a deploy secret). */
export interface DependencyRegistry {
  /** Registry base URL (npm) / index URL (cargo). */
  url: string;
  /** npm scope this registry serves (e.g. `@acme`). Absent ⇒ the npm default registry. Ignored by cargo. */
  scope?: string;
  /** Name of the auth-token secret (value lives in the host vault; recorded as a deploy secret). */
  auth?: string;
}

/** The full dependency manifest (#1127): the locked libraries plus the non-default registries they
 *  come from, keyed by the `source` each dependency references. */
export interface DependencyManifest {
  dependencies: PlanDependency[];
  registries: Record<string, DependencyRegistry>;
}

runtime.features/planner/issues/dependencyWorker:
// The worker-context dependency block (#1111): the locked set for ONE repo, inlined into its
// CLAUDE.local.md as the single authority every worker reads.

import type { PlanDependency } from "@/features/planner/issues/dependencyTypes";
import { bucketByEcosystem } from "@/features/planner/issues/dependencyParse";

/**
 * Render the locked dependency set for ONE repo as the worker-context block inlined into its
 * CLAUDE.local.md (#1111) — the single authority every worker reads, with the guardrail that the
 * manifests are planner-owned and new deps route through the director. Returns "" when the repo has
 * no locked deps (nothing to inline).
 */
export function buildWorkerDependencyBlock(deps: PlanDependency[]): string {
  if (!deps.length) return "";
  const { npm, cargo } = bucketByEcosystem(deps);
  const fmt = (d: PlanDependency) => {
    const ver = d.version ? `@${d.version}` : "";
    const dev = d.dev ? " *(dev)*" : "";
    const src = d.source ? ` *(from \`${d.source}\` registry)*` : "";
    const why = d.why ? ` — ${d.why}` : "";
    return `  - \`${d.name}${ver}\`${dev}${src}${why}`;
  };
  const hasSource = deps.some((d) => d.source);
  const lines = ["## Dependencies (locked by the planner)", ""];
  if (npm.length) lines.push("**npm** (`package.json`):", ...npm.map(fmt), "");
  if (cargo.length) lines.push("**cargo** (`Cargo.toml`):", ...cargo.map(fmt), "");
  lines.push(
    "These are already present in the repo's manifests — installing them is enough. **Do NOT add to or",
    "edit `package.json` / `Cargo.toml`** (the role gate blocks it): redefining deps in parallel",
    "worktrees is exactly what collides at integration. If you genuinely need a new dependency, request",
    "it from the director (`bsc-ask`) rather than adding it yourself.",
  );
  if (hasSource) {
    lines.push(
      "",
      "Private-registry sources are already wired in `.npmrc` / `.cargo/config.toml` (their auth tokens",
      "come from the environment) — don't reconfigure them.",
    );
  }
  return lines.join("\n");
}

runtime.features/planner/issues/featureList.ts:
// The feature list (#…): the authoritative artifact of the Features stage. Each entry is a
// capability AND a fleet stream, carrying a dependency DAG (`dependsOn`). The planner writes them to
// plan.db (surfaced by the poll as the `features` section); the Features board renders it and the
// gate signal reads it. Issues are generated FROM features at publish — `featuresToPlanIssues`.
// Pure + tolerant of partial/malformed input — no React/Tauri.

import type { PlanIssue } from "./planIssues";
import { slugify } from "@/shared/lib/core/format";

export interface PlanFeature {
  /** Stable slug / stream id (kebab-case). */
  slug: string;
  /** Capability name ("Invite teammates", "Geometry kernel"). Not just user-facing — a feature can
   *  be foundational (others depend on it). */
  name: string;
  /** What it does + when, in the user's terms. */
  behavior?: string;
  /** Done-when checklist a building agent verifies against. */
  acceptance?: string[];
  /** The build approach — the shape of the solution. */
  approach?: string;
  /** Specific libraries / services / frameworks. */
  tools?: string[];
  /** Feature slugs this feature builds on — the coarse roadmap DAG (#plan-db). Must stay acyclic. */
  dependsOn?: string[];
  /** What it stores/reads. */
  data?: string;
  /** The fleet stream that owns it (defaults to the slug — a feature IS a stream). */
  stream?: string;
  /** Algorithm impl ids from the GLOBAL `bsc graph` store this capability needs (#4080) — the plan →
   *  algorithms-graph edge, so a worker is pointed at the reference implementation instead of re-coding
   *  it. DECLARED intent (the planner names them at Features time), not derived fact. */
  requires?: string[];
}

function str(v: unknown): string | undefined {
  return typeof v === "string" && v.trim() ? v.trim() : undefined;
}
function strArray(v: unknown): string[] | undefined {
  if (!Array.isArray(v)) return undefined;
  const out = v.filter((x): x is string => typeof x === "string" && x.trim().length > 0).map((s) => s.trim());
  return out.length ? out : undefined;
}
/** Parse `features.json` (a JSON array of feature objects) into a clean list. Tolerant: bad JSON
 *  ⇒ []; entries missing both slug and name are dropped; duplicate slugs are de-duped; a missing
 *  slug is derived from the name, and stream defaults to the slug. */
export function parseFeaturesFile(raw: string): PlanFeature[] {
  if (!raw.trim()) return [];
  let data: unknown;
  try { data = JSON.parse(raw); } catch { return []; }
  if (!Array.isArray(data)) return [];
  const out: PlanFeature[] = [];
  const seen = new Set<string>();
  for (const item of data) {
    if (!item || typeof item !== "object") continue;
    const o = item as Record<string, unknown>;
    const name = str(o.name) ?? "";
    const slug = str(o.slug) ?? slugify(name, 60);
    if (!slug || !name || seen.has(slug)) continue;
    seen.add(slug);
    out.push({
      slug, name,
      behavior: str(o.behavior),
      acceptance: strArray(o.acceptance),
      approach: str(o.approach),
      tools: strArray(o.tools),
      dependsOn: strArray(o.dependsOn ?? o.depends_on),
      // Both spellings, like `dependsOn` — the store emits camelCase, but a hand-written or older
      // payload may carry snake, and silently dropping it would lose the reference entirely.
      requires: strArray(o.requires ?? o.requires_),
      data: str(o.data),
      stream: str(o.stream) ?? slug,
    });
  }
  return out;
}

/** A feature is fully defined once it has a name, behavior, and ≥1 acceptance criterion — enough
 *  for the Plan stage to decompose it into agent-ready issues. */
export function featureDefined(f: PlanFeature): boolean {
  return !!f.name && !!f.behavior && (f.acceptance?.length ?? 0) > 0;
}

/** The Features-gate summary: how many capabilities exist, and whether ALL are fully defined. */
export function featuresSummary(features: PlanFeature[]): { count: number; allConfirmed: boolean } {
  return { count: features.length, allConfirmed: features.length > 0 && features.every(featureDefined) };
}

/**
 * Whether the Features stage may COMPLETE (#plan-db): every feature populated AND the user has
 * confirmed the set. The user-confirm is the boundary that stops a single fully-populated feature
 * from auto-advancing the stage — the planner works titles-first, then the user confirms at the end.
 */
export function featuresGateComplete(summary: { allConfirmed: boolean }, userConfirmed: boolean): boolean {
  return summary.allConfirmed && userConfirmed;
}

/** Whether to OFFER the one-click confirm: every feature is populated but the user hasn't confirmed
 *  yet. While features are still being populated, no confirm is offered (the gate stays closed). */
export function featuresAwaitingConfirm(summary: { allConfirmed: boolean }, userConfirmed: boolean): boolean {
  return summary.allConfirmed && !userConfirmed;
}

/** The extra prose (beyond acceptance/owns/dependsOn, which `renderIssueBody` adds) for a feature's
 *  published issue: its behavior + approach + data + tools. */
function featureBody(f: PlanFeature): string | undefined {
  const parts: string[] = [];
  if (f.behavior?.trim()) parts.push(f.behavior.trim());
  if (f.approach?.trim()) parts.push(`## Approach\n${f.approach.trim()}`);
  if (f.data?.trim()) parts.push(`## Data\n${f.data.trim()}`);
  if (f.tools?.length) parts.push(`## Tools\n${f.tools.map((t) => `- ${t}`).join("\n")}`);
  return parts.join("\n\n").trim() || undefined;
}

/**
 * Project features into the issues published from them (#plan-db) — ONE issue per feature. Issues
 * aren't authored during planning; this is what publish (and the structure card) generate from the
 * DB features. The feature's slug becomes the issue `ref`, so a `dependsOn` between features is a
 * `dependsOn` between issues; acceptance carries over; behavior/approach/data/tools become the
 * body. `owns`/`labels` are left to the fleet (assigned to the stream in the Permissions stage).
 */
export function featuresToPlanIssues(features: PlanFeature[]): PlanIssue[] {
  return features.map((f) => ({
    ref: f.slug,
    title: f.name || f.slug,
    acceptance: f.acceptance ?? [],
    owns: [],
    dependsOn: f.dependsOn ?? [],
    labels: [],
    stream: f.stream ?? f.slug,
    body: featureBody(f),
  }));
}

/**
 * Find a cycle in the feature dependency DAG (#plan-db) — a cycle is a planning deadlock and holds
 * the Features gate. Returns the slugs on the first cycle found (e.g. `["a","b","a"]`) or `[]` when
 * acyclic. Edges to unknown slugs are ignored (a dangling dep isn't a cycle). Iterative-style DFS
 * with a colour map; self-deps (`a → a`) count.
 */
export function featureDependencyCycle(features: PlanFeature[]): string[] {
  const bySlug = new Map(features.map((f) => [f.slug, f]));
  const color = new Map<string, 1 | 2>(); // 1 = on the current path, 2 = fully explored
  const path: string[] = [];
  let found: string[] = [];

  const visit = (slug: string): boolean => {
    if (color.get(slug) === 2) return false;
    if (color.get(slug) === 1) {
      found = path.slice(path.indexOf(slug)).concat(slug); // back-edge → extract the cycle
      return true;
    }
    color.set(slug, 1);
    path.push(slug);
    for (const dep of bySlug.get(slug)?.dependsOn ?? []) {
      if (bySlug.has(dep) && visit(dep)) return true;
    }
    path.pop();
    color.set(slug, 2);
    return false;
  };

  for (const f of features) {
    if (color.get(f.slug) !== 2 && visit(f.slug)) break;
  }
  return found;
}

runtime.features/planner/issues/planFeatures.ts:
// Per-repo feature plans (#177). The planner's per-repo pass can now go down to the
// FEATURE level: for each repo it writes one plan section per feature, namespaced
// `repo__{short}__feat__{slug}`, carrying the feature's approach and (optionally)
// acceptance criteria. At publish each feature section becomes one real GitHub issue.
//
// Rather than thread a parallel "feature" object through the structure builder and the
// publisher, a feature section is converted into a synthetic {@link PlanIssue}: it then
// flows through the exact same granular-issue machinery (#311) — structure nodes,
// milestone pinning, labels, and the GitHub-link overlay — with no special-casing
// downstream.
//
// Pure (no React/Tauri) so the parsing is unit-testable and shared between Planning.tsx
// and its tests.

import { parseTopicKey } from "../stages/planTopics";
import type { PlanIssue } from "./planIssues";

/** The repo-tier topic prefix that marks a section as a feature (`feat__{slug}`). */
export const FEATURE_PREFIX = "feat__";

/** Label applied to every feature-derived issue so they're filterable on GitHub. */
export const FEATURE_LABEL = "type:feature";

/** True when a section key is a per-repo feature section (`repo__{short}__feat__{slug}`). */
export function isFeatureKey(key: string): boolean {
  const info = parseTopicKey(key);
  return info.tier === "repo" && info.repo !== null && info.topic.startsWith(FEATURE_PREFIX)
    && info.topic.length > FEATURE_PREFIX.length;
}

/** The feature slug for a feature key, or null when the key isn't a feature section. */
export function featureSlug(key: string): string | null {
  if (!isFeatureKey(key)) return null;
  return parseTopicKey(key).topic.slice(FEATURE_PREFIX.length);
}

/** Title-case a slug (`login-form` → "Login form") as the fallback feature title. */
function humanizeSlug(slug: string): string {
  const words = slug.split(/[-_\s]+/).filter(Boolean);
  if (words.length === 0) return "Feature";
  return words.map((w, i) => (i === 0 ? w.charAt(0).toUpperCase() + w.slice(1) : w)).join(" ");
}

export interface ParsedFeature {
  /** Feature title — the section's first heading, else the humanized slug. */
  title: string;
  /** The feature's approach/body, with the leading title heading stripped. */
  body: string;
  /** Acceptance items pulled from `- [ ]` checkbox lines, if any. */
  acceptance: string[];
}

/**
 * Parse a feature section's markdown into its structured parts. Tolerant of how the
 * planner writes it:
 *
 * - **Title** — the first markdown heading (`# …`), else the humanized `slug`. A
 *   leading heading used as the title is dropped from the body (a deeper/later heading
 *   is kept).
 * - **Acceptance** — every `- [ ]` / `- [x]` checkbox line becomes an acceptance item
 *   and is lifted out of the body (so {@link renderIssueBody} renders one clean
 *   checklist instead of duplicating it).
 *
 * Everything else is preserved as the body (the approach).
 */
export function parseFeatureSection(content: string, slug: string): ParsedFeature {
  let title = "";
  const acceptance: string[] = [];
  const bodyLines: string[] = [];
  let sawContent = false;

  for (const raw of content.split(/\r?\n/)) {
    const line = raw.trim();

    // The FIRST heading, before any other content, is the feature title.
    const hm = line.match(/^#{1,6}\s+(.+?)\s*$/);
    if (hm && !title && !sawContent) {
      title = hm[1].trim();
      continue;
    }

    const am = line.match(/^[-*]\s+\[[ xX]?\]\s+(.+?)\s*$/);
    if (am) {
      acceptance.push(am[1].trim());
      continue;
    }

    if (line) sawContent = true;
    bodyLines.push(raw);
  }

  if (!title) title = humanizeSlug(slug);
  return { title, body: bodyLines.join("\n").trim(), acceptance };
}

// ── Discovery rubric (#490) ────────────────────────────────────────────────────

/**
 * Result of the per-feature behavior discovery rubric (#490). The hard gate is
 * `complete` — a feature with `complete = false` is not converted to issues.
 * `missingEdgeCases` is a softer warning: the body has content but lacks any
 * signals of edge/error/empty-state handling.
 */
export interface DiscoveryResult {
  /** true when the hard-gate requirements are met (behavior + acceptance). */
  complete: boolean;
  /** true when the feature body is absent or too brief to carry behavioral intent. */
  missingBehavior: boolean;
  /** true when no acceptance criteria are present. */
  missingAcceptance: boolean;
  /** true when the body lacks keywords suggesting edge/error/empty handling. */
  missingEdgeCases: boolean;
}

const EDGE_RE =
  /\b(error|empty|invalid|fail|edge|missing|not found|no results|loading|cancel|timeout|conflict|reject|403|404|500)\b/i;

/**
 * Score a parsed feature against the behavior-discovery rubric (#490).
 * Hard gate (blocks issue generation): `missingBehavior || missingAcceptance`.
 * Soft warning: `missingEdgeCases` (encouraged but not blocking).
 */
export function featureDiscoveryComplete(feature: ParsedFeature): DiscoveryResult {
  const missingBehavior    = feature.body.trim().length === 0;
  const missingAcceptance  = feature.acceptance.length === 0;
  const missingEdgeCases   = !missingBehavior && !EDGE_RE.test(feature.body);
  const complete           = !missingBehavior && !missingAcceptance;
  return { complete, missingBehavior, missingAcceptance, missingEdgeCases };
}

/** A section as the converter needs it — just its key and raw content. */
export interface FeatureSectionInput {
  k: string;
  content: string;
}

/**
 * Resolve a repo short name (`web`, the name without its owner) to the matching full
 * `owner/repo` from `repos`, case-insensitively. Returns undefined when none matches —
 * the synthetic issue then has no `repo` and publish files it under the default repo.
 */
function resolveRepo(short: string, repos: string[]): string | undefined {
  const lc = short.toLowerCase();
  return repos.find((full) => (full.split("/")[1] ?? full).toLowerCase() === lc);
}

/**
 * Convert every per-repo feature section into a synthetic {@link PlanIssue}. The hard
 * discovery gate (#490) is applied: features missing behavior or acceptance are skipped
 * and do NOT become issues. Use {@link incompleteFeatureSections} to surface the blocked
 * features in the UI. Non-feature sections are ignored.
 */
export function featureSectionsToIssues(sections: FeatureSectionInput[], repos: string[]): PlanIssue[] {
  const out: PlanIssue[] = [];
  for (const s of sections) {
    const slug = featureSlug(s.k);
    if (!slug) continue;
    const short = parseTopicKey(s.k).repo as string; // isFeatureKey guarantees non-null
    const parsed = parseFeatureSection(s.content, slug);
    // Hard gate: no issues for features that haven't completed behavior discovery.
    if (!featureDiscoveryComplete(parsed).complete) continue;
    out.push({
      ref: `feat:${short}:${slug}`,
      title: parsed.title,
      acceptance: parsed.acceptance,
      owns: [],
      dependsOn: [],
      labels: [FEATURE_LABEL],
      repo: resolveRepo(short, repos),
      body: parsed.body || undefined,
    });
  }
  return out;
}

/** One feature that failed the discovery gate — surfaced as a UI warning. */
export interface IncompleteFeature {
  key: string;
  title: string;
  reasons: string[];
}

/**
 * Return feature sections that failed the discovery gate (#490), with human-readable
 * reasons. Use this to surface "N features are blocking issue generation" in the UI.
 */
export function incompleteFeatureSections(sections: FeatureSectionInput[]): IncompleteFeature[] {
  const out: IncompleteFeature[] = [];
  for (const s of sections) {
    const slug = featureSlug(s.k);
    if (!slug) continue;
    const parsed = parseFeatureSection(s.content, slug);
    const result = featureDiscoveryComplete(parsed);
    if (result.complete) continue;
    const reasons: string[] = [];
    if (result.missingBehavior)    reasons.push("no approach / behavior described");
    if (result.missingAcceptance)  reasons.push("no acceptance criteria");
    out.push({ key: s.k, title: parsed.title, reasons });
  }
  return out;
}

runtime.features/planner/issues/planIssues.ts:
// Granular, agent-ready issues (#311). The planner decomposes each phase into
// self-contained issues, and each carries everything an agent needs to execute
// WITHOUT asking: a concrete title, acceptance criteria (the done-when), the
// files/dirs it owns, its dependencies, labels, and its milestone. These drive
// the GitHub-structure view and the publish flow (one real issue each), replacing
// the bare one-tracker-per-phase model.
//
// Written by the planner as `issues.json` (a JSON array) and via inline
// <plan_issue .../> tags. Pure (no React/Tauri) so it's unit-testable and shared
// by the parser, validator, structure builder, and publisher.

/** Execution-status lifecycle (#plan-db), mirrored from plan.db. A worker moves its issue
 *  open → in_progress → complete (pushed/PR'd); the director then checks CI and moves it
 *  complete → verified (green) or failed (red). `blocked` ⇒ waiting on an unmet dependency.
 *  Mirrors the Rust `STATUSES` in `crates/plandb`. */
export type PlanIssueStatus = "open" | "in_progress" | "blocked" | "complete" | "verified" | "failed";

export const PLAN_ISSUE_STATUSES: PlanIssueStatus[] = ["open", "in_progress", "blocked", "complete", "verified", "failed"];

/** One decomposed unit of work — becomes exactly one GitHub issue. */
export interface PlanIssue {
  /** Stable planner-local ref (e.g. "F1", "auth-login"). Used for dependsOn links
   *  and dedup; NOT the GitHub number (assigned at publish). */
  ref: string;
  /** Concrete, imperative title (e.g. "Add POST /sessions endpoint"). */
  title: string;
  /** Acceptance criteria — the done-when checklist an agent verifies against. */
  acceptance: string[];
  /** Files/dirs this issue owns, so the agent knows exactly where to work. */
  owns: string[];
  /** Refs of issues that must land before this one starts. */
  dependsOn: string[];
  /** Labels to apply (e.g. "scope:core", "area:api"). */
  labels: string[];
  /** Repo (owner/name) for a multi-repo project; undefined ⇒ the default repo. */
  repo?: string;
  /** Owning fleet stream id, if assigned (mirrors AgentStream.issues). */
  stream?: string;
  /** Ref of the parent feature this is a sub-issue of (#…). A feature is a parent issue; its
   *  decomposed work items carry the feature's ref here. Undefined ⇒ a top-level issue (a
   *  feature parent, or an unparented issue). Published as a GitHub sub-issue under its parent. */
  parent?: string;
  /** Extra prose/context beyond the acceptance list. */
  body?: string;
  /** Execution status from plan.db (#plan-db) — set by workers/director during the build.
   *  Absent on a freshly-planned issue (treated as "open"). */
  status?: PlanIssueStatus;
}

const toStr = (v: unknown): string => (typeof v === "string" ? v.trim() : "");
const toStrArray = (v: unknown): string[] =>
  Array.isArray(v) ? v.map(toStr).filter(Boolean) : [];

/**
 * Parse the planner's `issues.json` (a JSON array of issue objects) into a clean
 * {@link PlanIssue}[]. Tolerant: bad JSON ⇒ `[]`; entries missing `ref` or `title`
 * are dropped (the minimum an issue needs to be addressable). Mirrors
 * {@link parseFleetFile}'s defensiveness.
 */
export function parseIssuesFile(raw: string): PlanIssue[] {
  if (!raw || !raw.trim()) return [];
  let data: unknown;
  try { data = JSON.parse(raw); } catch { return []; }
  const arr = Array.isArray(data) ? data : Array.isArray((data as { issues?: unknown })?.issues) ? (data as { issues: unknown[] }).issues : [];
  const out: PlanIssue[] = [];
  for (const item of arr) {
    if (!item || typeof item !== "object") continue;
    const o = item as Record<string, unknown>;
    const ref = toStr(o.ref) || toStr(o.id);
    const title = toStr(o.title);
    if (!ref || !title) continue;
    out.push({
      ref,
      title,
      acceptance: toStrArray(o.acceptance),
      owns:       toStrArray(o.owns),
      dependsOn:  toStrArray(o.dependsOn ?? o.depends_on),
      labels:     toStrArray(o.labels),
      repo:       toStr(o.repo) || undefined,
      stream:     toStr(o.stream) || undefined,
      parent:     toStr(o.parent) || undefined,
      body:       toStr(o.body) || undefined,
      status:     (PLAN_ISSUE_STATUSES as string[]).includes(toStr(o.status)) ? (toStr(o.status) as PlanIssueStatus) : undefined,
    });
  }
  return out;
}

export interface IssueTreeNode {
  issue: PlanIssue;
  children: PlanIssue[];
}

/**
 * Group issues into the feature → sub-issue tree (#…). A root is an issue with no `parent`, or
 * whose `parent` doesn't resolve to another issue (orphans degrade to roots, never lost). Every
 * other issue nests under its parent's `ref`. Children keep their `issues.json` order.
 */
export function issueTree(issues: PlanIssue[]): IssueTreeNode[] {
  const byRef = new Map(issues.map((i) => [i.ref, i]));
  const roots: PlanIssue[] = [];
  const childrenOf = new Map<string, PlanIssue[]>();
  for (const i of issues) {
    if (i.parent && i.parent !== i.ref && byRef.has(i.parent)) {
      const list = childrenOf.get(i.parent) ?? [];
      list.push(i);
      childrenOf.set(i.parent, list);
    } else {
      roots.push(i);
    }
  }
  return roots.map((issue) => ({ issue, children: childrenOf.get(issue.ref) ?? [] }));
}

/**
 * The parent→child GitHub node-id pairs to link as sub-issues (#…), given the node ids known by
 * issue ref (created or pre-existing). Only pairs where BOTH ends resolve are returned — an
 * unresolved end (parent/child not created this run) is simply not linked. Self-parents skipped.
 */
export function subIssueLinks(
  issues: PlanIssue[],
  nodeByRef: Record<string, string>,
): { parent: string; child: string }[] {
  const out: { parent: string; child: string }[] = [];
  for (const i of issues) {
    if (!i.parent || i.parent === i.ref) continue;
    const child = nodeByRef[i.ref];
    const parent = nodeByRef[i.parent];
    if (child && parent) out.push({ parent, child });
  }
  return out;
}

export interface IssueValidation {
  ok: boolean;
  /** Refs used more than once (ambiguous dependency targets). */
  duplicateRefs: string[];
  /** `{ ref, dependsOn }` where the dependency ref doesn't exist. */
  danglingDependencies: { ref: string; dependsOn: string }[];
  /** Issues with no acceptance criteria — not agent-ready (a warning, not fatal). */
  missingAcceptance: string[];
}

/**
 * Validate a decomposed issue set. `ok` is true when there are no duplicate refs and
 * no dangling dependencies — the agent-ready gate (missing acceptance is surfaced but
 * doesn't fail validation).
 */
export function validateIssues(issues: PlanIssue[]): IssueValidation {
  const seen = new Map<string, number>();
  for (const i of issues) seen.set(i.ref, (seen.get(i.ref) ?? 0) + 1);
  const duplicateRefs = [...seen.entries()].filter(([, n]) => n > 1).map(([r]) => r);

  const refs = new Set(issues.map((i) => i.ref));
  const danglingDependencies: { ref: string; dependsOn: string }[] = [];
  for (const i of issues) {
    for (const dep of i.dependsOn) {
      if (!refs.has(dep)) danglingDependencies.push({ ref: i.ref, dependsOn: dep });
    }
  }

  const missingAcceptance = issues.filter((i) => i.acceptance.length === 0).map((i) => i.ref);

  return {
    ok: duplicateRefs.length === 0 && danglingDependencies.length === 0,
    duplicateRefs,
    danglingDependencies,
    missingAcceptance,
  };
}

/**
 * Render a {@link PlanIssue} as a GitHub issue body — the agent-facing contract:
 * the acceptance checklist, the owned paths, and the dependency list, so whoever
 * picks it up has everything without re-deriving it from the plan.
 */
export function renderIssueBody(issue: PlanIssue): string {
  const parts: string[] = [];
  if (issue.body) parts.push(issue.body.trim());
  if (issue.acceptance.length) {
    parts.push("## Acceptance criteria\n" + issue.acceptance.map((a) => `- [ ] ${a}`).join("\n"));
  }
  if (issue.owns.length) {
    parts.push("## Owns\n" + issue.owns.map((o) => `- \`${o}\``).join("\n"));
  }
  if (issue.dependsOn.length) {
    parts.push("## Depends on\n" + issue.dependsOn.map((d) => `- ${d}`).join("\n"));
  }
  parts.push("---\n_Auto-generated by the base-studio-code planner._");
  // Hidden ref marker (#plan-db) — see {@link refMarker}.
  parts.push(refMarker(issue.ref));
  return parts.join("\n\n");
}

/**
 * The hidden HTML-comment marker that carries an issue's planner-local `ref` through a publish.
 * Invisible in GitHub's rendered issue view, but present in the raw body — so the GitHub→plan.db
 * recovery path can reconstruct the ref (and therefore the `dependsOn` links, which reference
 * planner refs), which GitHub doesn't persist natively. The single enabler for lossless recovery.
 */
export function refMarker(ref: string): string {
  return `<!-- bsc:ref=${ref} -->`;
}

/** Extract the planner-local ref from a published issue body's {@link refMarker}, or undefined. */
export function parseRefMarker(body: string): string | undefined {
  const m = /<!--\s*bsc:ref=([^\s>]+)\s*-->/.exec(body ?? "");
  return m ? m[1].trim() : undefined;
}

runtime.features/planner/issues/recoverIssues.ts:
// GitHub → plan.db recovery (#plan-db). The mirror of the publish flow: where publish maps each
// PlanIssue to a GitHub issue (body = acceptance/owns/dependsOn, `stream:<id>` label, hidden ref
// marker), recovery inverts it — reconstructing PlanIssue[] from a repo's issues so a lost or
// machine-switched plan.db can be rehydrated from the durable GitHub store.
//
// Pure (no React/Tauri) so the reverse-parse is unit-testable and round-trips against
// renderIssueBody. The orchestration (gh fetch + `bsc plan add`) lives in Planning.tsx.

import { parseRefMarker, type PlanIssue, type PlanIssueStatus } from "./planIssues";

/** The subset of a GitHub REST issue object recovery reads (`GET repos/{repo}/issues`). */
export interface GitHubIssueLike {
  number: number;
  title: string;
  body?: string | null;
  /** "open" | "closed". */
  state?: string;
  labels?: Array<{ name?: string } | string>;
  /** Present ⇒ this row is a pull request, not an issue (the /issues endpoint returns both). */
  pull_request?: unknown;
}

/**
 * Reverse of {@link renderIssueBody}: pull the prose body + acceptance/owns/dependsOn back out of a
 * published issue body. Tolerant of formatting drift — unknown sections are ignored, the `---`
 * footer and the hidden ref marker are stripped, and a bare body with no sections still recovers.
 */
function parseIssueBody(raw: string): Pick<PlanIssue, "body" | "acceptance" | "owns" | "dependsOn"> {
  const text = (raw ?? "").replace(/<!--\s*bsc:ref=[^>]*-->/g, "").trim();
  const acceptance: string[] = [];
  const owns: string[] = [];
  const dependsOn: string[] = [];
  const prose: string[] = [];
  let section: "body" | "acceptance" | "owns" | "depends" | "other" = "body";

  for (const lineRaw of text.split(/\r?\n/)) {
    const line = lineRaw.trim();
    const heading = /^##\s+(.+)$/.exec(line);
    if (heading) {
      const t = heading[1].toLowerCase();
      section = t.startsWith("acceptance") ? "acceptance"
        : t.startsWith("owns") ? "owns"
        : t.startsWith("depends") ? "depends"
        : "other";
      continue;
    }
    // The auto-gen footer ends the meaningful content.
    if (line === "---" || line.startsWith("_Auto-generated")) { section = "other"; continue; }

    const bullet = /^[-*]\s+(.*)$/.exec(line);
    if (section === "acceptance" && bullet) {
      acceptance.push(bullet[1].replace(/^\[[ xX]\]\s*/, "").trim()); // drop the checkbox
    } else if (section === "owns" && bullet) {
      owns.push(bullet[1].replace(/`/g, "").trim());                  // drop the code ticks
    } else if (section === "depends" && bullet) {
      dependsOn.push(bullet[1].trim());
    } else if (section === "body") {
      prose.push(lineRaw);
    }
  }

  const body = prose.join("\n").trim();
  return {
    body: body || undefined,
    acceptance: acceptance.filter(Boolean),
    owns: owns.filter(Boolean),
    dependsOn: dependsOn.filter(Boolean),
  };
}

/**
 * Reconstruct one {@link PlanIssue} from a GitHub issue. Ref comes from the hidden marker (falling
 * back to `#<number>` so it stays addressable); stream from the `stream:<id>` label;
 * acceptance/owns/dependsOn from the body. GitHub is only open/closed, so a
 * closed issue maps to `verified` (merged + CI green at close) and an open one to `open` — the
 * director can refine an open issue via its linked PR + CI later (the same live-verify signal).
 */
export function recoverIssue(gh: GitHubIssueLike, repoFullName: string): PlanIssue {
  const labelNames = (gh.labels ?? [])
    .map((l) => (typeof l === "string" ? l : l?.name ?? ""))
    .filter(Boolean);
  const streamLabel = labelNames.find((n) => n.startsWith("stream:"));
  const stream = streamLabel ? streamLabel.slice("stream:".length) || undefined : undefined;
  const labels = labelNames.filter((n) => !n.startsWith("stream:"));

  const rawBody = gh.body ?? "";
  const ref = parseRefMarker(rawBody) ?? `#${gh.number}`;
  const status: PlanIssueStatus = gh.state === "closed" ? "verified" : "open";

  return {
    ref,
    title: (gh.title ?? "").trim(),
    stream,
    labels,
    repo: repoFullName,
    status,
    ...parseIssueBody(rawBody),
  };
}

/**
 * Recover every PlanIssue from a repo's GitHub issues. Pull requests (the /issues endpoint returns
 * them too) and titleless rows are dropped.
 */
export function recoverIssues(ghIssues: GitHubIssueLike[], repoFullName: string): PlanIssue[] {
  return (ghIssues ?? [])
    .filter((g) => g && !g.pull_request && (g.title ?? "").trim())
    .map((g) => recoverIssue(g, repoFullName));
}

runtime.features/planner/lib/classifyConfig.ts:
// Project classification (#3783/#3784) — the planner's discovery output that shapes the plan:
// which UI surface the `ui` stage renders, and which optional stages (source / mcp / skills) the
// project actually needs. Written by the planner during discovery via `bsc plan classify set`,
// polled into the store, and read by the UI-stage body + the stage-visibility signals.
//
// Every field is OPTIONAL: an unclassified project (the planner hasn't run `classify` yet) coerces
// to `{}`, and each read site applies its own non-regressing default (uiMode → "custom", the
// needs-flags → their stage's prior default). So adding classification never hides a pane that
// showed before the planner classified.

/** The two UI-stage surfaces (#3783). "custom" = the in-app designer preview (PreviewPaneShell —
 *  the navigable shell the designer commissions); "external" = the Claude-Design drop-files intake
 *  (FileIntakePane). */
export type UiMode = "custom" | "external";

/** The project's APPLICATION ARCHITECTURE (#3802/#3784) — what KIND of app it is, the axis the
 *  Projects list facets by AND the axis that selects which stages run (#3784). A flat taxonomy
 *  grounded in the deploy model (cloud `workload` + local `localKind`): a general application, a
 *  desktop/mobile app, a backend API, serverless functions, a static site, a CLI tool, a published
 *  library, or an MCP server. Unset ⇒ read as "application". */
export type AppType =
  | "application" | "desktop" | "mobile" | "api" | "serverless" | "static" | "cli" | "library" | "mcp-server";

/** The valid `AppType` tokens, for the coerce below + facet iteration. */
export const APP_TYPES: AppType[] = ["application", "api", "serverless", "static", "desktop", "mobile", "cli", "library", "mcp-server"];

/** The project's LIFECYCLE INTENT (#3784) — what this planning run is FOR. Discovered by the
 *  planner (existing repos to restructure ⇒ transform; from a pitch ⇒ greenfield; …) rather than
 *  chosen up front: lifecycle left the blueprint model in #3785, so discovery is its only home.
 *  Unset ⇒ read as "greenfield", the create-a-project default — see {@link lifecycleOf}, and note
 *  that DISPLAY must not apply that default (#4062).
 *
 *  `harvest` (#4062) — the project exists to EXTRACT DATA FROM SOURCES: pulling an existing system's
 *  data out, rather than restructuring code (`transform`) or keeping something running (`maintain`).
 *  The name is the app's established one for exactly this shape — `bsc ui harvest`, algorithm harvest,
 *  both "extract from what already exists". */
export type Lifecycle = "greenfield" | "transform" | "harden" | "maintain" | "harvest";

/** The valid `Lifecycle` tokens, for the coerce below. Mirrored by `LIFECYCLES` in
 *  `crates/plandb/src/validate.rs`, which rejects an unknown token at `bsc plan classify set` —
 *  keep the two in lockstep or the planner can write a value the app cannot read. */
export const LIFECYCLES: Lifecycle[] = ["greenfield", "transform", "harden", "maintain", "harvest"];

/** The app types that carry a USER INTERFACE — the ones for which the `ui` stage is meaningful.
 *  Everything else (an API, serverless functions, a CLI, a library, an MCP server) has no screens
 *  to design, so the UI stage does not apply to it (#3784). */
const UI_BEARING: AppType[] = ["application", "desktop", "mobile", "static"];

export interface ClassifyConfig {
  /** Which surface the `ui` stage renders. Unset → the body defaults to "custom". */
  uiMode?: UiMode;
  /** The project's application architecture (#3802/#3784). Unset → read as "application". */
  appType?: AppType;
  /** The project's lifecycle intent (#3784). Unset → read as "greenfield". */
  lifecycle?: Lifecycle;
  /** A desk-research market assessment is worth doing → show the `market` stage (#3806). */
  needsMarket?: boolean;
  /** The project connects to an external system → show the `source` stage. */
  needsSource?: boolean;
  /** The project uses MCP servers → show the `mcps` stage. */
  needsMcp?: boolean;
  /** The project needs attached skills → show the `skills` stage. */
  needsSkills?: boolean;
  /** The project needs cron automations → show the `automations` stage. */
  needsAutomations?: boolean;
}

/** Coerce a `bsc plan classify get` blob into a typed config — a light structural check (the CLI
 *  validates hard at write). A non-object reads as null; unknown/mistyped fields are dropped, so a
 *  partial blob (e.g. only `uiMode`) coerces cleanly. */
export function coerceClassifyConfig(raw: unknown): ClassifyConfig | null {
  if (typeof raw !== "object" || raw === null) return null;
  const r = raw as Record<string, unknown>;
  const cfg: ClassifyConfig = {};
  if (r.uiMode === "custom" || r.uiMode === "external") cfg.uiMode = r.uiMode;
  if (typeof r.appType === "string" && (APP_TYPES as string[]).includes(r.appType)) cfg.appType = r.appType as AppType;
  if (typeof r.lifecycle === "string" && (LIFECYCLES as string[]).includes(r.lifecycle)) cfg.lifecycle = r.lifecycle as Lifecycle;
  if (typeof r.needsMarket === "boolean") cfg.needsMarket = r.needsMarket;
  if (typeof r.needsSource === "boolean") cfg.needsSource = r.needsSource;
  if (typeof r.needsMcp === "boolean") cfg.needsMcp = r.needsMcp;
  if (typeof r.needsSkills === "boolean") cfg.needsSkills = r.needsSkills;
  if (typeof r.needsAutomations === "boolean") cfg.needsAutomations = r.needsAutomations;
  return cfg;
}

/** The project's app type, with the unclassified default applied. */
export function appTypeOf(cfg: ClassifyConfig | undefined | null): AppType {
  return cfg?.appType ?? "application";
}

/** The project's lifecycle intent, with the unclassified default applied. */
export function lifecycleOf(cfg: ClassifyConfig | undefined | null): Lifecycle {
  return cfg?.lifecycle ?? "greenfield";
}

/** Does this project have screens to design? Drives whether the `ui` stage applies (#3784).
 *
 *  An UNCLASSIFIED project reads as "application" ⇒ true, so turning this on never hides a UI
 *  stage that showed before the planner classified — the same non-regressing rule every other
 *  classification read site follows. */
export function appTypeHasUi(cfg: ClassifyConfig | undefined | null): boolean {
  return UI_BEARING.includes(appTypeOf(cfg));
}

/** Project the classification into the flat gate-signal bag (#3784) — one boolean per app type
 *  (`appType:api`, `appType:mcp-server`, …) and per lifecycle (`lifecycle:transform`, …), plus the
 *  derived `hasUserInterface`.
 *
 *  Exposing the taxonomy as signals rather than a single string is what the {@link
 *  import("../stages/stageGate").PlanSignals} bag supports (numbers/booleans only) — and it lets a
 *  cloud-distributed stage key its `appliesWhen` on an app type without the app shipping code for it. */
export function classifySignals(cfg: ClassifyConfig | undefined | null): Record<string, boolean> {
  const appType = appTypeOf(cfg);
  const lifecycle = lifecycleOf(cfg);
  const out: Record<string, boolean> = { hasUserInterface: appTypeHasUi(cfg) };
  for (const t of APP_TYPES) out[`appType:${t}`] = t === appType;
  for (const l of LIFECYCLES) out[`lifecycle:${l}`] = l === lifecycle;
  return out;
}

runtime.features/planner/lib/dataModelDerivation:
// Migration SOURCE → canonical Data Model derivation (#1205, "data dictates structure") — the pure
// helper that turns a scan into the project's Data Model: one entity per discovered object (deduped
// across sources), fields from the discovered columns (or a default `id` identity), with relationships
// resolved from connector-declared lookups (#1219) or inferred by name (#1209). This is what
// `features`/`structure` design over — the Source pane persists it to the project's DuckDB store via
// `bsc data model set --refined` (#1446), NOT to any file. Split out of sourceValidate.ts (#1712);
// the type model lives in sourceSpecs.ts.

import type { DataModel, Entity, Field, FieldType } from "@/features/planner/data/dataModel";
import type { DiscoveredField, SourceConfig } from "./sourceSpecs";

const fieldName = (f: string | DiscoveredField): string => (typeof f === "string" ? f : f.name);
const fieldMeta = (f: string | DiscoveredField): { type?: FieldType; enumValues?: string[]; ref?: string } =>
  typeof f === "string" ? {} : { type: f.type, enumValues: f.enumValues, ref: f.ref };

/** Slug a source object/column name into a safe Data Model key (matches dataModel.ts SAFE_IDENT). */
export function safeKey(raw: string): string {
  const s = raw.trim().toLowerCase().replace(/[^a-z0-9_]+/g, "_").replace(/^_+|_+$/g, "");
  return /^[a-z_]/.test(s) ? s : `e_${s}`;
}

/** Build a Data Model from the scanned sources — entities from discovered objects, fields from
 *  their columns (or a default `id` key), deduped by entity key. */
export function deriveDataModel(cfg: SourceConfig, id = "dm-source"): DataModel {
  const entities: Entity[] = [];
  const seen = new Set<string>();
  for (const s of cfg.sources) {
    if (s.status !== "scanned") continue;
    for (const o of s.objects ?? []) {
      const key = safeKey(o.name) || "entity";
      if (seen.has(key)) continue; // one entity per object name, across sources
      seen.add(key);
      const fseen = new Set<string>();
      const cols = (o.fields ?? [])
        .map((f) => ({ key: safeKey(fieldName(f)), meta: fieldMeta(f) }))
        .filter((c) => c.key && !fseen.has(c.key) && (fseen.add(c.key), true));
      const fields: Field[] = cols.length
        ? cols.map((c) => ({
            key: c.key,
            type: c.meta.type ?? "string",
            ...(c.meta.enumValues && c.meta.enumValues.length ? { enum_values: c.meta.enumValues } : {}),
            ...(c.meta.ref ? { ref: safeKey(c.meta.ref) } : {}),
          }))
        : [{ key: "id", type: "string" as const, required: true }];
      const identity = fields.some((f) => f.key === "id") ? ["id"] : fields[0] ? [fields[0].key] : [];
      entities.push({ key, label: o.name, fields, identity });
    }
  }
  // Resolve relationships. A connector-declared lookup (#1219, e.g. Salesforce AccountId → Account)
  // wins when its target was scanned — it's exact, and its field key (`accountid`) wouldn't match by
  // name. Otherwise infer (#1209): a field whose key matches another entity's key is a `ref` to it
  // (e.g. Contact.account → Account). Either gives the graph its edges and the list its ref chips.
  const entityKeys = new Set(entities.map((e) => e.key));
  for (const e of entities) {
    for (const f of e.fields) {
      if (f.ref && entityKeys.has(f.ref)) {
        f.type = "ref";
        delete f.enum_values; // a ref isn't an enum
      } else if (f.key !== e.key && entityKeys.has(f.key)) {
        f.type = "ref";
        f.ref = f.key;
        delete f.enum_values;
      } else if (f.ref) {
        // Declared ref to an object that wasn't scanned — drop the dangling link, keep a plain field.
        delete f.ref;
        if (f.type === "ref") f.type = "string";
      }
    }
  }
  return { id, name: cfg.dataModelName || "Source Data Model", version: 1, entities };
}

runtime.features/planner/lib/deployCoerce.ts:
// Planner deploy channel (#919/#1421) — coerce the planner's lenient/partial deploy config JSON into
// a full DeployConfig, and parse the `<deploy_config>` tag body. Pure (no React/Tauri). Split out of
// deployConfig.ts (#1639).
//
// The planner emits a lenient/partial shape, one service per repo, each carrying its own
// environments/pipeline/config/secrets/release/health; we overlay it onto seeded defaults so the gate
// can clear from the planner's output. Defensive: any missing piece falls back to a sensible default;
// the caller try/catches bad JSON and the planner re-emits.

import { repoShortName } from "@/shared/lib/core/projectPaths";
import { platform, type Workload } from "./deployPlatforms";
import {
  PIPE_TRIGGERS, PUBLISH_REGISTRIES, PUBLISH_TRIGGERS, PORT_FORWARD_METHODS,
  type DeployEnvironment, type Pipeline, type DeployConfigBlock, type DeployConfigRow, type DeploySecretRow,
  type ReleasePolicy, type HealthPolicy, type PipeTrigger,
  type DeployMode, type LocalKind, type PublishRegistry, type PublishTrigger, type PortForward, type PortForwardMethod,
} from "./deployEnv";
import { defaultDeployConfig, defaultService, type DeployService, type DeployConfig } from "./deployServices";

type Raw = Record<string, unknown>;
const asArr = (v: unknown): Raw[] => Array.isArray(v) ? v.filter((x): x is Raw => !!x && typeof x === "object") : [];
const asStr = (v: unknown, d = ""): string => typeof v === "string" ? v : d;
const asBool = (v: unknown, d: boolean): boolean => typeof v === "boolean" ? v : d;

/** Coerce a service's environment ladder (accepts `environments` or `envs`). */
function coerceEnvs(o: Raw, base: DeployEnvironment[]): DeployEnvironment[] {
  const raw = asArr(o.environments).length ? asArr(o.environments) : asArr(o.envs);
  const envs = (raw.length ? raw : base).map((e, i) => {
    const name = asStr(e.name) || base[i]?.name || `env-${i + 1}`;
    return { id: asStr(e.id) || name, name, branch: asStr(e.branch, "main"), url: asStr(e.url), auto: asBool(e.auto, true) };
  });
  return envs.length ? envs : base;
}

/** Coerce a service's pipeline. */
function coercePipeline(o: Raw, base: Pipeline): Pipeline {
  const rawPipe = (o.pipeline && typeof o.pipeline === "object" ? o.pipeline : {}) as Raw;
  const rawStages = asArr(rawPipe.stages);
  return {
    provider: asStr(rawPipe.provider, base.provider),
    stages: (rawStages.length ? rawStages : base.stages).map((st, i) => {
      const trig = asStr(st.trigger) as PipeTrigger;
      return {
        id: asStr(st.id) || asStr(st.name) || `stage-${i + 1}`,
        name: asStr(st.name) || `stage-${i + 1}`,
        trigger: PIPE_TRIGGERS.includes(trig) ? trig : "push",
        gate: asBool(st.gate, false), cmd: asStr(st.cmd),
      };
    }),
  };
}

/** Coerce a service's config block. A secret may carry `envs: ["dev","prod"]` OR per-env booleans;
 *  an unspecified secret defaults to wired in every env (so the planner needn't enumerate). */
function coerceConfigBlock(o: Raw, envs: DeployEnvironment[]): DeployConfigBlock {
  const config: DeployConfigRow[] = asArr(o.config).map((r) => {
    const row: DeployConfigRow = { key: asStr(r.key) };
    for (const e of envs) row[e.id] = asStr(r[e.id]);
    return row;
  });
  const secrets: DeploySecretRow[] = asArr(o.secrets).map((r) => {
    const listed = Array.isArray(r.envs) ? new Set((r.envs as unknown[]).map((x) => String(x))) : null;
    const row: DeploySecretRow = { key: asStr(r.key) };
    for (const e of envs) {
      row[e.id] = listed ? (listed.has(e.id) || listed.has(e.name)) : (typeof r[e.id] === "boolean" ? (r[e.id] as boolean) : true);
    }
    return row;
  });
  return { config, secrets, vault: asStr((o.config as Raw)?.vault) || asStr(o.vault, "host vault") };
}

function coerceRelease(o: Raw, base: ReleasePolicy): ReleasePolicy {
  const rawRel = (o.release && typeof o.release === "object" ? o.release : {}) as Raw;
  return {
    // Preserve ANY non-empty strategy the planner authored — not just the four cloud-rollout enum
    // values (#2021). A release-artifact deploy (GitHub Pages/Releases, npm publish, packaging) has a
    // legitimate free-text strategy; the old enum-only check dropped it to "" and silently jammed the
    // deploy gate (the poll's coercion disagreed with `normalizeDeployConfig`, which the gate trusts).
    strategy: asStr(rawRel.strategy),
    autoRollback: asBool(rawRel.autoRollback, base.autoRollback),
    keep: typeof rawRel.keep === "number" ? rawRel.keep : base.keep,
    migrateWithDeploy: asBool(rawRel.migrateWithDeploy, base.migrateWithDeploy),
  };
}

function coerceHealth(o: Raw, base: HealthPolicy): HealthPolicy {
  const rawHealth = (o.health && typeof o.health === "object" ? o.health : {}) as Raw;
  return {
    probe: asStr(rawHealth.probe, base.probe), probeOn: asBool(rawHealth.probeOn, !!asStr(rawHealth.probe)),
    slo: asStr(rawHealth.slo), sloOn: asBool(rawHealth.sloOn, !!asStr(rawHealth.slo)),
    alerts: asStr(rawHealth.alerts), alertsOn: asBool(rawHealth.alertsOn, !!asStr(rawHealth.alerts)),
  };
}

/** Coerce one planner-emitted service object onto the seeded default for its repo. */
function coerceService(s: Raw, base: DeployService, idx: number): DeployService {
  const repo = asStr(s.repo, base.repo);
  const id = asStr(s.id) || (repo ? repoShortName(repo) : `service-${idx + 1}`);
  const plat = platform(asStr(s.platform));
  const wl = asStr(s.workload) as Workload;
  const workload: Workload = plat.kinds.includes(wl) ? wl : (plat.kinds[0] ?? "static");
  const reps = typeof s.replicas === "number" ? String(s.replicas) : asStr(s.replicas);
  const mode: DeployMode = asStr(s.mode) === "local" ? "local" : "cloud";
  const rawKind = asStr(s.localKind);
  const localKind: LocalKind | undefined = rawKind === "library" || rawKind === "application" ? rawKind : (mode === "local" ? "application" : undefined);
  const rawReg = asStr(s.publishRegistry);
  const publishRegistry = (PUBLISH_REGISTRIES as readonly string[]).includes(rawReg) ? (rawReg as PublishRegistry) : undefined;
  const rawTrig = asStr(s.publishTrigger);
  const publishTrigger = (PUBLISH_TRIGGERS as readonly string[]).includes(rawTrig) ? (rawTrig as PublishTrigger) : undefined;
  const pf = (s.portForward && typeof s.portForward === "object" ? s.portForward : null) as Raw | null;
  const rawMethod = pf ? asStr(pf.method) : "";
  const portForward: PortForward | undefined = pf
    ? { enabled: asBool(pf.enabled, false), port: asStr(pf.port), method: (PORT_FORWARD_METHODS as readonly string[]).includes(rawMethod) ? (rawMethod as PortForwardMethod) : "cloudflared" }
    : undefined;
  const envs = coerceEnvs(s, base.envs);
  return {
    id, repo, path: asStr(s.path, "."), stack: asStr(s.stack, "—"),
    platform: asStr(s.platform), workload, proposed: false,
    region: asStr(s.region, "—"), build: asStr(s.build, "—"),
    output: asStr(s.output, "dist"), runtime: asStr(s.runtime, "—"),
    host: asStr(s.host) || base.host || "github",
    registry: asStr(s.registry) || undefined,
    orchestrator: asStr(s.orchestrator) || undefined,
    replicas: reps || undefined,
    mode,
    localKind: mode === "local" ? localKind : (localKind || undefined),
    publishRegistry,
    packageName: asStr(s.packageName) || undefined,
    publishTrigger,
    buildTargets: asStr(s.buildTargets) || undefined,
    artifact: asStr(s.artifact) || undefined,
    runCmd: asStr(s.runCmd) || undefined,
    portForward,
    envs,
    pipeline: coercePipeline(s, base.pipeline),
    config: coerceConfigBlock(s, envs),
    release: coerceRelease(s, base.release),
    health: coerceHealth(s, base.health),
  };
}

export function coerceDeployConfig(raw: unknown, repos: string[] = []): DeployConfig {
  const o = (raw && typeof raw === "object" ? raw : {}) as Raw;
  const base = defaultDeployConfig(repos);
  const rawServices = asArr(o.services);
  // A config saved before the per-repo rework (#1421) carries environments/pipeline/config/secrets/
  // release/health at the TOP LEVEL, shared across services; the per-repo model wants them ON each
  // service. Fold the top-level set into a service that lacks its own, so a migrated legacy config
  // stays deploy-ready (its `release.strategy` etc. reach each service) instead of resetting to empty
  // defaults and silently blocking the gate (#1438). A service's own fields always win.
  const legacyTop: Raw = {
    environments: o.environments ?? o.envs, pipeline: o.pipeline,
    config: o.config, secrets: o.secrets, release: o.release, health: o.health,
  };
  const services: DeployService[] = (rawServices.length ? rawServices : base.services as unknown as Raw[]).map((s, i) =>
    coerceService({ ...legacyTop, ...(s as Raw) }, base.services[i] ?? defaultService(asStr((s as Raw).repo)), i),
  );
  return { services };
}

/** Parse the body of a `<deploy_config>` tag into a DeployConfig. Forgiving on two fronts (#919):
 *  (1) stray prose/tags around the JSON (e.g. a leaked `</parameter>`) — we extract the outermost
 *  `{ … }` object; (2) the planner CLI's terminal line-WRAPS the big JSON block, injecting raw
 *  newlines + indent that can land INSIDE string values (invalid JSON). When a clean parse fails we
 *  collapse newline-spanning whitespace to a single space and retry, which repairs the wraps
 *  (`"fly  \n  app"` → `"fly app"`). Returns null only if neither parse works. */
export function parseDeployConfigTag(body: string, repos: string[] = []): DeployConfig | null {
  const json = body.match(/\{[\s\S]*\}/)?.[0];
  if (!json) return null;
  const tryParse = (s: string): unknown => { try { return JSON.parse(s); } catch { return undefined; } };
  // Raw newlines are only ever wrap artifacts inside a JSON string (real string newlines are escaped
  // `\n`), so collapsing them is safe; between tokens it's just whitespace JSON ignores anyway.
  const parsed = tryParse(json) ?? tryParse(json.replace(/[ \t]*[\r\n]+[ \t]*/g, " "));
  if (parsed === undefined || parsed === null) return null;
  try {
    return coerceDeployConfig(parsed, repos);
  } catch {
    return null;
  }
}

