// Deployment & infrastructure config (#919; per-repo rework #1421) — the data model behind the
// planner's Deployment stage (right after Repos). Pure (no React/Tauri) so the readiness checks that
// drive the stage gate are unit-testable.
//
// Split into focused modules (#1639); this barrel re-exports the full public surface so importers
// don't churn:
//   - deployPlatforms.ts — the deploy-target catalog (platforms, workloads, git hosts, orchestrators)
//   - deployEnv.ts       — per-service building blocks (envs, pipeline, config/secrets, release,
//                          health, local-mode option lists) + the default builders
//   - deployServices.ts  — the DeployService/DeployConfig model + readiness checks + gate + issues
//   - deployCoerce.ts    — the planner channel (coerceDeployConfig + parseDeployConfigTag)

export * from "./deployPlatforms";
export * from "./deployEnv";
export * from "./deployServices";
export * from "./deployCoerce";

runtime.features/planner/lib/deployEnv.ts:
// Per-service deploy building blocks (#919; per-repo rework #1421; local mode #1192) — the
// environment ladder, CI/CD pipeline, config/secrets block, release policy, and health policy that
// each DeployService owns, plus the ship-mode option lists and the sensible default a fresh service
// starts from.
//
// The DATA (option lists + defaults) is externalized to `@data/deploy/taxonomy.json` (#2027 P1) —
// the single source, editable without touching code and part of the exportable app-config bundle.
// This module keeps only the TYPES + the accessor/const names + the default BUILDERS (which return a
// fresh deep copy of the JSON default each call, since callers mutate them). Pure (no React/Tauri).

import taxonomyEmbedded from "@data/deploy/taxonomy.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

// The config-dir copy (#2047) overlays the embedded default — editable without a rebuild.
const taxonomy = overlayFile("deploy/taxonomy.json", taxonomyEmbedded);

/** How a service ships (#1192). `cloud` = a hosted platform; `local` = a published library or a
 *  build-and-run-here application (CLI / desktop / local server). A monorepo can mix the two. */
export type DeployMode = "cloud" | "local";
/** A local service is either a published library or a built application (#1192). */
export type LocalKind = "library" | "application";

/** Package registries a local LIBRARY can publish to (#1192). */
export type PublishRegistry = "npm" | "crates.io" | "PyPI" | "internal";
export const PUBLISH_REGISTRIES = taxonomy.publishRegistries as readonly PublishRegistry[];
/** When a library's publish workflow fires (#1192). */
export type PublishTrigger = "on-tag" | "manual";
export const PUBLISH_TRIGGERS = taxonomy.publishTriggers as readonly PublishTrigger[];

/** How a locally-running deployment is exposed remotely (#1192). `cloudflared` is the default —
 *  we already run a Cloudflare relay for the mobile tunnel. */
export type PortForwardMethod = "cloudflared" | "ngrok" | "tailscale" | "LAN";
export const PORT_FORWARD_METHODS = taxonomy.portForwardMethods as readonly PortForwardMethod[];

/** Optional remote exposure for a local Application / server (#1192). */
export interface PortForward {
  enabled: boolean;
  /** Port to expose (string so the field stays free-form, e.g. "8080"). */
  port: string;
  method: PortForwardMethod;
}

export interface DeployEnvironment {
  id: string;
  name: string;
  branch: string;
  url: string;
  /** Auto-deploy on push to `branch` (vs manual promotion). */
  auto: boolean;
  proposed?: boolean;
}

export type PipeTrigger = "push" | "tag" | "on-green" | "manual";
export const PIPE_TRIGGERS = taxonomy.pipeTriggers as PipeTrigger[];

export interface PipelineStage {
  id: string;
  name: string;
  trigger: PipeTrigger;
  /** Blocks promotion until green. */
  gate: boolean;
  cmd: string;
}
export interface Pipeline {
  provider: string;
  stages: PipelineStage[];
}

export interface DeployConfigRow { key: string; [env: string]: string }
export interface DeploySecretRow { key: string; [env: string]: boolean | string }
export interface DeployConfigBlock {
  config: DeployConfigRow[];
  /** Secrets are tracked by NAME + per-env "wired" flag — values never live here. */
  secrets: DeploySecretRow[];
  vault: string;
}

export type ReleaseStrategy = "recreate" | "rolling" | "blue-green" | "canary";
export const RELEASE_STRATEGIES = taxonomy.releaseStrategies as { id: ReleaseStrategy; label: string; desc: string }[];
export interface ReleasePolicy {
  /** The rollout/release strategy. {@link RELEASE_STRATEGIES} are the KNOWN cloud-rollout options the
   *  picker offers, but the field accepts ANY non-empty string — a release-artifact deploy (GitHub
   *  Pages/Releases, npm publish, packaging) legitimately carries a free-text strategy like
   *  `github-release (tag on main → …)` that isn't one of the four. `""` = unset. */
  strategy: string;
  autoRollback: boolean;
  keep: number;
  migrateWithDeploy: boolean;
}

export interface HealthPolicy {
  probe: string; probeOn: boolean;
  slo: string; sloOn: boolean;
  alerts: string; alertsOn: boolean;
}

// The sensible defaults a fresh service's deploy plan starts from (from `@data/deploy/taxonomy.json`).
// Each builder returns a fresh DEEP COPY so callers can mutate their service's config independently.
const clone = <T>(v: T): T => structuredClone(v);

/** A sensible default environment ladder a repo's deploy plan starts from. */
export function defaultEnvs(): DeployEnvironment[] {
  return clone(taxonomy.defaults.envs) as DeployEnvironment[];
}
/** A sensible default pipeline a repo's deploy plan starts from. */
export function defaultPipeline(): Pipeline {
  return clone(taxonomy.defaults.pipeline) as Pipeline;
}
export function defaultRelease(): ReleasePolicy {
  return clone(taxonomy.defaults.release) as ReleasePolicy;
}
export function defaultHealth(): HealthPolicy {
  return clone(taxonomy.defaults.health) as HealthPolicy;
}

runtime.features/planner/lib/deployPlatforms.ts:
// Deploy target catalog (#919; per-repo rework #1421) — the platforms a service can ship to, the
// workload kinds, the git hosts a repo can live on, and the container orchestration options.
//
// The DATA is externalized to `@data/deploy/taxonomy.json` (#2027 P1) — the single source, editable
// without touching code and part of the exportable app-config bundle. This module keeps only the
// TYPES + accessor helpers over that data (no React/Tauri, so it stays unit-testable).

import taxonomyEmbedded from "@data/deploy/taxonomy.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

// The config-dir copy (#2047) overlays the embedded default — editable without a rebuild.
const taxonomy = overlayFile("deploy/taxonomy.json", taxonomyEmbedded);

/** Workload kind a service deploys as. */
export type Workload = "static" | "serverless" | "container" | "service";

export interface DeployPlatform {
  id: string;
  name: string;
  /** Workload kinds this platform supports. */
  kinds: Workload[];
  /** oklch hue for the platform tile glyph. */
  h: number;
  glyph: string;
}

/** Platform catalog — the deploy targets a service can pick (from `@data/deploy/taxonomy.json`). */
export const PLATFORMS: DeployPlatform[] = taxonomy.platforms as DeployPlatform[];

export function platform(id: string): DeployPlatform {
  return PLATFORMS.find((p) => p.id === id) ?? { id, name: id, h: 250, glyph: "■", kinds: [] };
}

export const WORKLOAD: Record<Workload, { label: string; c: string }> =
  taxonomy.workloads as Record<Workload, { label: string; c: string }>;

/** A git host a project's repos can live on — a project may span clouds or a self-hosted server. */
export interface GitHost { key: string; domain: string; label: string; kind: "cloud" | "self-hosted"; color: string }
export const HOSTS: Record<string, GitHost> = taxonomy.gitHosts as Record<string, GitHost>;
export function hostMeta(id: string | undefined): GitHost {
  return HOSTS[id ?? "github"] ?? HOSTS.github;
}

/** Orchestrators a distributed (container) workload can run under. */
export const ORCHESTRATORS: { id: string; label: string }[] = taxonomy.orchestrators;
/** Replica-count options for a container workload (string so "auto" fits the same control). */
export const REPLICA_OPTIONS: readonly string[] = taxonomy.replicaOptions;

runtime.features/planner/lib/deployServices.ts:
// The deployable-unit model (#919; per-repo rework #1421; local mode #1192) — one DeployService per
// linked repo, the project-wide DeployConfig that aggregates them, the readiness checks that drive
// the stage gate, the default/normalize seeders, and the `stream:deploy` issue preview. Pure (no
// React/Tauri) so the gate logic is unit-testable. Split out of deployConfig.ts (#1639).
//
// One DeployConfig per project (store slice `planDeployConfig`) holding ONE DeployService per linked
// repo. Each service is a fully self-contained deployable unit — it owns its OWN environments,
// pipeline, config/secrets, release, and health. The `deploymentDefined` gate signal is
// `services.length > 0 && services.every(serviceReady)`; the pane shows "N of M repos deploy-ready".

import { repoShortName } from "@/shared/lib/core/projectPaths";
import type { ReadinessCheck } from "./readiness";
import { platform, WORKLOAD, type Workload } from "./deployPlatforms";
import {
  defaultEnvs, defaultPipeline, defaultRelease, defaultHealth,
  type DeployEnvironment, type Pipeline, type DeployConfigBlock,
  type ReleasePolicy, type HealthPolicy,
  type DeployMode, type LocalKind, type PublishRegistry, type PublishTrigger, type PortForward,
} from "./deployEnv";

/** A deployable unit — one per linked repo (or sub-path). Each owns its OWN environments, pipeline,
 *  config/secrets, release, and health (#1421): every repo is a self-contained deployable unit. */
export interface DeployService {
  id: string;
  repo: string;
  path: string;
  stack: string;
  platform: string;
  workload: Workload;
  /** True until the user accepts/edits the planner's proposed target. */
  proposed: boolean;
  region: string;
  build: string;
  output: string;
  runtime: string;
  /** Git host the repo lives on (key into {@link HOSTS}) — display only; defaults to github. */
  host?: string;
  /** Container image registry for a container workload. Absent ⇒ derived `ghcr.io/<repo>`. */
  registry?: string;
  /** Orchestrator id for a distributed container workload (see {@link ORCHESTRATORS}). */
  orchestrator?: string;
  /** Replica count for a container workload — a {@link REPLICA_OPTIONS} value ("auto" allowed). */
  replicas?: string;
  // ── Local mode (#1192) — a library or a build-and-run-here app. Absent `mode` ⇒ "cloud". ──
  /** Whether the service ships to a cloud platform or as a local artifact. Defaults to "cloud". */
  mode?: DeployMode;
  /** For a local service: library (published) vs application (built + run). */
  localKind?: LocalKind;
  /** Library: the registry it publishes to. */
  publishRegistry?: PublishRegistry;
  /** Library: the published package name. */
  packageName?: string;
  /** Library: when the publish workflow fires. */
  publishTrigger?: PublishTrigger;
  /** Application: target platform(s) to build for (OS/arch or "desktop installer"). */
  buildTargets?: string;
  /** Application: the produced artifact (e.g. a binary or installer name). */
  artifact?: string;
  /** Application: how to run the built artifact. */
  runCmd?: string;
  /** Optional remote exposure for a locally-running application. */
  portForward?: PortForward;
  // ── Per-repo deploy plan (#1421) — every repo carries its own full ship config. ──
  envs: DeployEnvironment[];
  pipeline: Pipeline;
  config: DeployConfigBlock;
  release: ReleasePolicy;
  health: HealthPolicy;
}

/** Default mode for a service whose `mode` is unset (legacy configs) — cloud. */
export function serviceMode(s: DeployService): DeployMode {
  return s.mode ?? "cloud";
}

/** A local service's `target` check passes once its mode-appropriate fields are set: a library needs
 *  a publish registry + package name; an application needs build targets + an artifact (#1192). */
export function localTargetDefined(s: DeployService): boolean {
  if (s.localKind === "library") return !!s.publishRegistry && !!(s.packageName && s.packageName.trim());
  if (s.localKind === "application") return !!(s.buildTargets && s.buildTargets.trim()) && !!(s.artifact && s.artifact.trim());
  return false;
}

/** A service has a defined deploy target — a cloud platform, or its local fields (#1192). */
export function serviceTargetDefined(s: DeployService): boolean {
  return serviceMode(s) === "local" ? localTargetDefined(s) : !!s.platform;
}

export interface DeployConfig {
  services: DeployService[];
}

/** Seed one proposed service (deployable unit) for a repo, with its own env ladder / pipeline /
 *  config / release / health the planner can refine. */
export function defaultService(repo: string): DeployService {
  const short = repo ? repoShortName(repo) : "app";
  return {
    id: short, repo, path: ".", stack: "—",
    platform: "", workload: "static", proposed: true,
    region: "—", build: "—", output: "dist", runtime: "—", host: "github",
    mode: "cloud",
    envs: defaultEnvs(),
    pipeline: defaultPipeline(),
    config: { config: [], secrets: [], vault: "host vault" },
    release: defaultRelease(),
    health: defaultHealth(),
  };
}

/** Seed a config for a project from its linked repos — one proposed service per repo. */
export function defaultDeployConfig(repos: string[]): DeployConfig {
  return { services: (repos.length ? repos : [""]).map(defaultService) };
}

/** Backfill a possibly-OLD-shape config (#1421/#1425 migration). Pre-rework configs kept `envs` /
 *  `pipeline` / `config` / `release` / `health` at the TOP level (shared across services); the
 *  per-repo rework moved them ONTO each service. A persisted old config therefore has services with
 *  none of those fields, and the per-service readers (`serviceChecks` → `s.config.secrets`) crash on
 *  it. Ensure every service owns its sub-configs — from the service, else the legacy top-level, else
 *  the defaults — and drop the `undefined`/empty case to a fresh config. Self-heals on the next save. */
export function normalizeDeployConfig(d: DeployConfig | undefined, repos: string[] = []): DeployConfig {
  if (!d || !Array.isArray(d.services) || d.services.length === 0) return defaultDeployConfig(repos);
  const legacy = d as Partial<{ envs: DeployEnvironment[]; pipeline: Pipeline; config: DeployConfigBlock; release: ReleasePolicy; health: HealthPolicy }>;
  return {
    services: d.services.map((s) => ({
      ...s,
      envs: Array.isArray(s.envs) ? s.envs : (legacy.envs ?? defaultEnvs()),
      pipeline: s.pipeline?.stages ? s.pipeline : (legacy.pipeline ?? defaultPipeline()),
      config: s.config?.secrets ? s.config : (legacy.config ?? { config: [], secrets: [], vault: "host vault" }),
      release: s.release && s.release.strategy !== undefined ? s.release : (legacy.release ?? defaultRelease()),
      health: s.health ?? legacy.health ?? defaultHealth(),
    })),
  };
}

/** The pipeline's final stage label adapts to a service's mode (#1192): cloud ships (`deploy`), a
 *  library publishes (`publish`), a local app packages (`package`). The gating `test` stays put. */
export function finalStageName(s: DeployService | undefined): "deploy" | "publish" | "package" {
  if (s && serviceMode(s) === "local") return s.localKind === "library" ? "publish" : "package";
  return "deploy";
}

/** The readiness checks for ONE service (repo) — every one `ok` ⇒ this repo is deploy-ready. Checks
 *  are MODE-AWARE (#2023): GitHub (Actions/environments/secrets) is a mandatory baseline, so BOTH
 *  modes gate on target + CI/CD pipeline + environments + config-secrets. Only the cloud
 *  instance-replacement **release/rollout** strategy (recreate/rolling/blue-green/canary) is
 *  cloud-only — a local build (library publish / application package) has no rollout, so that check
 *  is omitted for local mode (its shipping is the pipeline's publish/package stage instead). */
export function serviceChecks(s: DeployService): ReadinessCheck[] {
  const prodSecrets = s.config.secrets.length === 0 || s.config.secrets.every((row) => !!row.prod);
  const checks: ReadinessCheck[] = [
    { id: "target",   label: "Deploy target set",          ok: serviceTargetDefined(s),     detail: serviceMode(s) === "local" ? (s.localKind ?? "local") : (platform(s.platform).name || "—") },
    { id: "envs",     label: "Environment ladder defined", ok: s.envs.length >= 2,           detail: `${s.envs.length} environments` },
    { id: "pipeline", label: "CI/CD pipeline staged",      ok: s.pipeline.stages.length >= 2, detail: s.pipeline.provider },
    { id: "secrets",  label: "Secrets wired for every env", ok: prodSecrets,                 detail: prodSecrets ? "all set" : "missing prod" },
  ];
  if (serviceMode(s) === "cloud") {
    checks.push({ id: "release", label: "Release & rollback strategy", ok: !!s.release.strategy, detail: s.release.strategy || "—" });
  }
  return checks;
}

/** Whether a single repo's deploy plan is complete (all its checks pass). */
export function serviceReady(s: DeployService): boolean {
  return serviceChecks(s).every((c) => c.ok);
}

/** How many of the project's repos are fully deploy-ready (drives "N of M repos deploy-ready"). */
export function readyServiceCount(d: DeployConfig | undefined): number {
  return d ? d.services.filter(serviceReady).length : 0;
}

/** The `deploymentDefined` gate signal: at least one repo, and EVERY repo's deploy plan complete. */
export function deploymentDefined(d: DeployConfig | undefined): boolean {
  return !!d && d.services.length > 0 && d.services.every(serviceReady);
}

/** A deployment task this config will generate as a `stream:deploy` issue at publish. */
export interface DeployIssue { text: string; tag: string; blocking: boolean }

/** Preview the `stream:deploy` issues ONE service generates at publish — its deploy/publish/package
 *  workflow, non-prod env provisioning, prod secret wiring (blocking while unset), and (for anything
 *  that RUNS) a prod health check. */
export function serviceIssues(s: DeployService): DeployIssue[] {
  const out: DeployIssue[] = [];
  if (!serviceTargetDefined(s)) return out;
  if (serviceMode(s) === "local") {
    out.push(s.localKind === "library"
      ? { text: `Add ${s.publishRegistry ?? "registry"} publish workflow for ${s.id} (${s.packageName || s.id})`, tag: "all", blocking: false }
      : { text: `Add package + build workflow for ${s.id} → ${s.buildTargets || "local artifact"}`, tag: "all", blocking: false });
  } else {
    out.push({ text: `Add ${platform(s.platform).name} deploy workflow for ${s.id} → ${WORKLOAD[s.workload].label}`, tag: "all", blocking: false });
  }
  for (const e of s.envs.filter((e) => e.id !== "prod" && e.name !== "prod" && e.id !== "dev" && e.name !== "dev")) {
    out.push({ text: `Provision ${s.id} ${e.name} environment + secrets`, tag: e.name, blocking: false });
  }
  const unwired = s.config.secrets.filter((row) => !row.prod);
  if (unwired.length) {
    out.push({ text: `Wire ${s.id} prod secrets (${unwired.map((r) => r.key).join(", ")})`, tag: "prod", blocking: true });
  }
  if (!(serviceMode(s) === "local" && s.localKind === "library")) {
    out.push({ text: `Add ${s.id} prod health check + auto-rollback`, tag: "prod", blocking: false });
  }
  return out;
}

/** Preview every `stream:deploy` issue this project's deploy plan generates — across all repos. */
export function deployIssues(d: DeployConfig): DeployIssue[] {
  return d.services.flatMap(serviceIssues);
}

runtime.features/planner/lib/dropFiles.ts:
// Drag-and-drop folder traversal (#831). A dropped FOLDER does not appear in
// `DataTransfer.files` — it's a `FileSystemDirectoryEntry` reachable only via
// `DataTransferItem.webkitGetAsEntry()`. This walks each dropped entry recursively and
// collects every file with its relative path (so the folder structure is preserved under
// `design/`). The DOM entry API is callback-based; this promisifies + flattens it. Kept
// behind a minimal interface so it's unit-testable with fakes (no real DataTransfer needed).

/** The slice of `FileSystemEntry` (+ its file/directory subtypes) we use. Lets tests
 *  supply plain fakes instead of a real DOM entry tree. */
export interface FsEntryLike {
  isFile: boolean;
  isDirectory: boolean;
  name: string;
  file?(onSuccess: (f: File) => void, onError?: (e: unknown) => void): void;
  createReader?(): {
    readEntries(onSuccess: (entries: FsEntryLike[]) => void, onError?: (e: unknown) => void): void;
  };
}

/** A collected file plus its path relative to the drop root (e.g. `icons/home.svg`). */
export interface DroppedFile {
  file: File;
  path: string;
}

/** Recursively collect files from one dropped entry, preserving its relative path under
 *  `prefix`. A file yields one entry; a directory is read in batches (`readEntries` returns
 *  `[]` when exhausted) and recursed into. Unknown entries yield nothing. */
export async function collectEntry(entry: FsEntryLike, prefix = ""): Promise<DroppedFile[]> {
  if (entry.isFile && entry.file) {
    const fileFn = entry.file.bind(entry);
    const file = await new Promise<File>((resolve, reject) => fileFn(resolve, reject));
    return [{ file, path: prefix + entry.name }];
  }
  if (entry.isDirectory && entry.createReader) {
    const reader = entry.createReader();
    const out: DroppedFile[] = [];
    const childPrefix = `${prefix}${entry.name}/`;
    // readEntries yields the directory in batches; call until it returns an empty batch.
    for (;;) {
      const batch = await new Promise<FsEntryLike[]>((resolve, reject) =>
        reader.readEntries(resolve, reject),
      );
      if (batch.length === 0) break;
      for (const child of batch) out.push(...(await collectEntry(child, childPrefix)));
    }
    return out;
  }
  return [];
}

/** Collect every file from a set of dropped entries, folders walked recursively. */
export async function collectDroppedEntries(entries: FsEntryLike[]): Promise<DroppedFile[]> {
  const all = await Promise.all(entries.map((e) => collectEntry(e)));
  return all.flat();
}

runtime.features/planner/lib/fileIntake.ts:
// File-intake pipeline core (#604). Pure helpers for the drag-and-drop intake: classify
// a dropped file into a coarse KIND (a routing hint for the planner) and build the
// `intake.json` manifest the planner reads to route files to the right repo/stage.
// Free of React/Tauri so it's unit-testable; the drop-zone screen + Rust writes wrap it.

/** Coarse classification — a hint, not a contract. The planner does the real routing. */
export type IntakeKind = "image" | "vector" | "markup" | "style" | "component" | "data" | "doc" | "other";

/** One staged file in the intake manifest. */
export interface IntakeEntry {
  /** Original file name (also the relpath under `.intake/`). */
  name: string;
  /** Coarse kind (routing hint). */
  kind: IntakeKind;
  /** Byte size. */
  size: number;
  /** MIME type if the browser provided one. */
  mime?: string;
  /** #2097 — content hash of the staged file, so a re-drop of an edited file is detectable. */
  hash: string;
  /** #2097 — the `hash` value at the last time this file was ROUTED to the project (on triage).
   *  Undefined ⇒ never routed. `hash !== routedHash` ⇒ new or changed since the last route. */
  routedHash?: string;
}

const EXT_KIND: Record<string, IntakeKind> = {
  png: "image", jpg: "image", jpeg: "image", gif: "image", webp: "image", avif: "image", bmp: "image", ico: "image",
  svg: "vector",
  html: "markup", htm: "markup",
  css: "style", scss: "style", sass: "style", less: "style",
  jsx: "component", tsx: "component", vue: "component", svelte: "component",
  json: "data", yaml: "data", yml: "data", toml: "data", csv: "data",
  md: "doc", mdx: "doc", txt: "doc", pdf: "doc",
};

/** Classify a file by extension first, then MIME family. Unknown ⇒ "other". */
export function classifyFile(name: string, mime?: string): IntakeKind {
  const ext = name.includes(".") ? name.slice(name.lastIndexOf(".") + 1).toLowerCase() : "";
  if (ext && EXT_KIND[ext]) return EXT_KIND[ext];
  if (mime) {
    if (mime === "image/svg+xml") return "vector";
    if (mime.startsWith("image/")) return "image";
    if (mime === "text/html") return "markup";
    if (mime === "text/css") return "style";
    if (mime === "application/json") return "data";
    if (mime.startsWith("text/")) return "doc";
  }
  return "other";
}

/** Whether a file should be staged via the binary (base64) write vs text. Images,
 *  vectors-as-binary, fonts, pdfs, and anything non-text go binary; markup/style/
 *  component/data/doc are text. */
export function isBinaryKind(kind: IntakeKind): boolean {
  return kind === "image" || kind === "other";
}

/** A fast, deterministic content hash (FNV-1a, 32-bit → hex) — enough to detect a file changed
 *  between drops; not cryptographic. Text files hash their text; binary files hash their base64. */
export function hashContent(content: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < content.length; i++) {
    h ^= content.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, "0");
}

/** Build one manifest entry from a file's metadata + its content hash. */
export function intakeEntry(name: string, size: number, hash: string, mime?: string): IntakeEntry {
  return { name, kind: classifyFile(name, mime), size, hash, ...(mime ? { mime } : {}) };
}

/** Merge new entries into an existing manifest, de-duping by name (newest content wins), preserving
 *  order (existing first, then new names). A re-dropped file keeps its prior `routedHash` so the
 *  change vs the last route is preserved (a new `hash` different from `routedHash` ⇒ needs routing). */
export function mergeIntake(existing: IntakeEntry[], added: IntakeEntry[]): IntakeEntry[] {
  const byName = new Map(existing.map((e) => [e.name, e]));
  for (const e of added) {
    const prev = byName.get(e.name);
    byName.set(e.name, prev ? { ...e, routedHash: prev.routedHash } : e);
  }
  return [...byName.values()];
}

/** The staged files that are new or changed since their last route (`hash !== routedHash`). */
export function changedDesignFiles(entries: IntakeEntry[]): IntakeEntry[] {
  return entries.filter((e) => e.hash !== e.routedHash);
}

/** Stamp every entry as routed at its current content (`routedHash = hash`) — called after a route. */
export function markRouted(entries: IntakeEntry[]): IntakeEntry[] {
  return entries.map((e) => ({ ...e, routedHash: e.hash }));
}

/** #2097 — the design-routing lead prepended to a triage prompt when design files changed, mirroring
 *  `renderTriageDelta`. Empty when nothing changed (so triage does its normal issue pass untouched).
 *  `routeInstruction` is the UI stage's `routePrompt` (the classify-and-route directive). */
export function renderDesignDelta(changed: IntakeEntry[], routeInstruction: string): string {
  if (changed.length === 0) return "";
  const names = changed.map((e) => e.name).join(", ");
  return (
    `DESIGN ROUTING: ${changed.length} design file(s) changed since the last route — ${names}. ` +
    `Route ONLY these changed files (the rest are already in place): ${routeInstruction} ` +
    `Then continue with the issue triage below. `
  );
}

/** Serialize the manifest exactly as it's stored (stable, pretty, trailing newline). */
export function serializeIntake(entries: IntakeEntry[]): string {
  return JSON.stringify(entries, null, 2) + "\n";
}

/** Parse a stored `intake.json` tolerantly (bad/blank ⇒ []). */
export function parseIntake(raw: string): IntakeEntry[] {
  if (!raw || !raw.trim()) return [];
  try {
    const j: unknown = JSON.parse(raw);
    if (!Array.isArray(j)) return [];
    return j.filter((e): e is IntakeEntry => !!e && typeof e === "object" && typeof (e as IntakeEntry).name === "string")
      .map((e) => ({
        name: e.name, kind: e.kind ?? "other", size: typeof e.size === "number" ? e.size : 0,
        hash: typeof e.hash === "string" ? e.hash : "", ...(e.routedHash ? { routedHash: e.routedHash } : {}),
        ...(e.mime ? { mime: e.mime } : {}),
      }));
  } catch {
    return [];
  }
}

/** Where intake stages files within the project hub — a visible `design/` directory so
 *  dropped design assets are easy to find (#829), not a hidden `.intake/`. */
export const INTAKE_DIR = "design";
export const INTAKE_MANIFEST = "design/intake.json";

/** The built-in pipeline id (matches its PIPELINE_LIB entry + screen registration). */
export const FILE_INTAKE_ID = "file-intake";

// The file-intake "Route" instruction now lives in the UI stage's DATA
// (`src-tauri/data/stages/ui.json` → `routePrompt`), read via `STAGE_DEFS.ui.routePrompt` — not
// hardcoded here, so the prompt is editable alongside the rest of the stage (#604).

runtime.features/planner/lib/gist/gist.ts:
// Gist transport for extensions (#598 M2). Publish an extension manifest as a gist
// (one shareable URL, free hosting) and install it back by URL. Reading a public/secret
// gist needs no auth; publishing needs a token with the `gist` scope. Pure helpers
// (id parsing, file selection) are split out so they're unit-testable without Tauri.

import { invoke } from "@tauri-apps/api/core";
import { parseManifest, type ExtensionManifest, type ValidateResult } from "./manifest";

/** The file name an extension's manifest is published under inside a gist. */
export const MANIFEST_FILENAME = "extension.json";

/**
 * Extract a gist id from anything the user might paste: a gist web URL
 * (`gist.github.com/<user>/<id>` or `/<id>`), an API URL (`api.github.com/gists/<id>`),
 * or a bare id. Returns null when no plausible id is present.
 */
export function gistIdFromUrl(input: string): string | null {
  const s = input.trim();
  if (!s) return null;
  // Bare id (hex, ≥ 8 chars) — accept as-is.
  if (/^[0-9a-f]{8,}$/i.test(s)) return s;
  // Last path segment that looks like a gist id.
  const m = s.match(/gist(?:\.github\.com|s)[/:]([^/\s?#]+\/)?([0-9a-f]{8,})/i);
  if (m) return m[2];
  // Fallback: the final path-ish chunk if it's id-shaped.
  const tail = s.split(/[/?#]/).filter(Boolean).pop() ?? "";
  return /^[0-9a-f]{8,}$/i.test(tail) ? tail : null;
}

/** Shape of the relevant bits of the GitHub gist API response. */
interface GistApiResponse {
  id?: string;
  html_url?: string;
  description?: string | null;
  updated_at?: string;
  owner?: { login?: string } | null;
  files?: Record<string, { content?: string; raw_url?: string; filename?: string }>;
  history?: GistHistoryItem[];
}

/** One blueprint gist from a source user's gists (#923). */
export interface BlueprintGistItem {
  id: string;
  /** Blueprint name, parsed from the gist description (`blueprint: <name>`, set by publishGist). */
  name: string;
  description: string;
  owner: string;
  htmlUrl: string;
  updatedAt: string;
}

/** List a GitHub user's BLUEPRINT gists (#923). A gist is a blueprint when its description carries
 *  the `blueprint:` prefix publishGist writes (`${kind}: ${name}`) — the list endpoint omits file
 *  content, so the description is the reliable signal. No auth needed for public gists; `token`
 *  raises the rate limit + surfaces the user's secret gists. Empty on error. */
export async function listBlueprintGists(user: string, token = ""): Promise<BlueprintGistItem[]> {
  if (!user.trim()) return [];
  let gists: GistApiResponse[];
  try {
    gists = (await invoke("github_request", { token, path: `users/${user}/gists?per_page=100`, maxAgeSecs: 60, force: false })) as GistApiResponse[];
  } catch {
    return [];
  }
  if (!Array.isArray(gists)) return [];
  return gists
    .filter((g) => !!g.id && (g.description ?? "").trim().toLowerCase().startsWith("blueprint:"))
    .map((g) => {
      const description = (g.description ?? "").trim();
      return {
        id: g.id!,
        name: description.replace(/^blueprint:\s*/i, "").trim() || "(untitled blueprint)",
        description,
        owner: g.owner?.login ?? user,
        htmlUrl: g.html_url ?? "",
        updatedAt: g.updated_at ?? "",
      };
    });
}

interface GistHistoryItem {
  version?: string;
  committed_at?: string;
  change_status?: { total?: number; additions?: number; deletions?: number };
  user?: { login?: string } | null;
}

/** One published revision of a gist (newest first). */
export interface GistRevision {
  /** Full commit sha of this revision (use with installFromGistRevision). */
  version: string;
  committedAt: string;
  additions: number;
  deletions: number;
  login: string;
}

/** Pick the manifest file's content from a gist's files: prefer {@link MANIFEST_FILENAME},
 *  else the first `.json` file. Returns null when none is present. */
export function pickManifestContent(files: GistApiResponse["files"]): string | null {
  if (!files) return null;
  const named = files[MANIFEST_FILENAME];
  if (named?.content) return named.content;
  const firstJson = Object.values(files).find((f) => f.filename?.toLowerCase().endsWith(".json") && f.content);
  return firstJson?.content ?? null;
}

export interface PublishResult { id: string; htmlUrl: string }

/**
 * Publish a manifest as a gist (secret by default). Returns the gist id + web URL to
 * share. Throws on failure (no token / `gist` scope missing / network).
 */
export async function publishGist(
  token: string, manifest: ExtensionManifest, opts: { public?: boolean; description?: string } = {},
): Promise<PublishResult> {
  const files = { [MANIFEST_FILENAME]: JSON.stringify(manifest, null, 2) };
  const description = opts.description ?? `${manifest.kind}: ${manifest.name}`;
  const res = (await invoke("gist_create", { token, files, description, public: opts.public ?? false })) as GistApiResponse;
  if (!res.id || !res.html_url) throw new Error("gist_create returned no id/url");
  return { id: res.id, htmlUrl: res.html_url };
}

/**
 * Update an EXISTING gist's manifest in place (#970) — PATCH so re-publishing a blueprint that's
 * already on a gist updates the original instead of minting a duplicate. Throws on failure (bad
 * token / not the owner / network).
 */
export async function updateGist(
  token: string, id: string, manifest: ExtensionManifest, opts: { description?: string } = {},
): Promise<PublishResult> {
  const files = { [MANIFEST_FILENAME]: JSON.stringify(manifest, null, 2) };
  const description = opts.description ?? `${manifest.kind}: ${manifest.name}`;
  const res = (await invoke("gist_update", { token, id, files, description })) as GistApiResponse;
  if (!res.id || !res.html_url) throw new Error("gist_update returned no id/url");
  return { id: res.id, htmlUrl: res.html_url };
}

/** A gist's manifest file fetched VERBATIM — the exact bytes the publisher wrote, before any
 *  parsing. The kit-store integrity path (#2465) hashes these bytes, so it must see the raw text,
 *  not a re-serialization. `owner` is the gist owner's login when the API reports one. */
export type GistTextResult =
  | { ok: true; text: string; owner?: string }
  | { ok: false; error: string };

/**
 * Fetch a gist's manifest file content verbatim (no auth needed for public/secret gists; `token`
 * raises rate limits / reads a private gist). The raw-text layer both `installFromGist` (parse +
 * validate) and the kit-store fetch (hash-before-accept, #2465) share.
 */
export async function fetchGistManifestText(ref: string, token = ""): Promise<GistTextResult> {
  const id = gistIdFromUrl(ref);
  if (!id) return { ok: false, error: "that doesn't look like a gist URL or id" };
  let gist: GistApiResponse | null;
  try {
    gist = (await invoke("github_request", { token, path: `gists/${id}`, maxAgeSecs: 0, force: true })) as GistApiResponse | null;
  } catch (e) {
    return { ok: false, error: `couldn't fetch the gist: ${String(e)}` };
  }
  // A missing/404 gist can come back as null rather than a throw (#2515) — that's a soft
  // "not found", never a TypeError.
  const content = pickManifestContent(gist?.files);
  if (!content) return { ok: false, error: "no extension manifest found in that gist" };
  return { ok: true, text: content, ...(gist?.owner?.login ? { owner: gist.owner.login } : {}) };
}

/**
 * Install from a gist URL/id: fetch the gist (no auth needed for public/secret), pull
 * its manifest file, and validate it. `token` is optional (used only to raise rate
 * limits / read a private gist).
 */
export async function installFromGist(ref: string, token = ""): Promise<ValidateResult> {
  const raw = await fetchGistManifestText(ref, token);
  return raw.ok ? parseManifest(raw.text) : raw;
}

/** Map a gist's API `history` into our GistRevision list (newest first). Pure. */
export function toRevisions(history: GistHistoryItem[] | undefined): GistRevision[] {
  return (history ?? [])
    .filter((h): h is GistHistoryItem & { version: string } => typeof h.version === "string")
    .map((h) => ({
      version: h.version,
      committedAt: h.committed_at ?? "",
      additions: h.change_status?.additions ?? 0,
      deletions: h.change_status?.deletions ?? 0,
      login: h.user?.login ?? "unknown",
    }));
}

/** Fetch a gist's revision history (newest first). Empty on error. */
export async function gistRevisions(id: string, token = ""): Promise<GistRevision[]> {
  try {
    const gist = (await invoke("github_request", { token, path: `gists/${id}`, maxAgeSecs: 0, force: true })) as GistApiResponse;
    return toRevisions(gist.history);
  } catch {
    return [];
  }
}

/** Install the manifest as it existed at a specific gist revision (sha). */
export async function installFromGistRevision(id: string, sha: string, token = ""): Promise<ValidateResult> {
  let gist: GistApiResponse;
  try {
    gist = (await invoke("github_request", { token, path: `gists/${id}/${sha}`, maxAgeSecs: 0, force: true })) as GistApiResponse;
  } catch (e) {
    return { ok: false, error: `couldn't fetch that revision: ${String(e)}` };
  }
  const content = pickManifestContent(gist.files);
  if (!content) return { ok: false, error: "no extension manifest at that revision" };
  return parseManifest(content);
}

runtime.features/planner/lib/gist/manifest.ts:
// Extension manifest envelope (#598) — the single wrapper every distributable thing
// ships in: blueprints today, MCP / skills / app-state later. One envelope means one
// install / validate / store path regardless of kind. Pure (no React/Tauri) so it's
// shared by the importer, the share-code path, and (later) the gist layer.

/** Bump only on a breaking envelope change; an app refuses a NEWER manifest it can't read. */
export const MANIFEST_VERSION = 1;

/** Distributable kinds. `blueprint` (shared today), `app-state` (#2272 — the app-wide demo/state
 *  snapshot), `component-kit` (#2305), `sound-kit` (#3372 — a shareable sound kit, the sounds twin of
 *  `component-kit`) and `studio` (#2891 — the app-library snapshot bundle) are live; `mcp`/`skill` are
 *  reserved. (The legacy code-bearing `pipeline` kind was removed in #2271 — a dead concept.) NOTE: the
 *  type union and the `KINDS` array MUST stay in sync (validateManifest checks membership against
 *  `KINDS`). */
export type ExtensionKind =
  | "blueprint" | "mcp" | "skill" | "app-state" | "component-kit" | "sound-kit" | "studio";
const KINDS: ExtensionKind[] = [
  "blueprint", "mcp", "skill", "app-state", "component-kit", "sound-kit", "studio",
];

/** Capabilities a code-bearing extension may request (declared + user-approved at
 *  install, enforced by the sandbox). Reserved for future code-bearing kinds; the
 *  current data-only kinds (blueprint/mcp/skill) declare none. */
export type Capability = "read-signals" | "write-files" | "render" | "network";

/** The wire/file/share-code envelope. `payload` is the kind-specific object. */
export interface ExtensionManifest<P = unknown> {
  /** Envelope version (see MANIFEST_VERSION). */
  manifest: number;
  kind: ExtensionKind;
  /** Stable extension id (slug). */
  id: string;
  name: string;
  /** Author-set version string (semver-ish); used for update prompts + integrity. */
  version: string;
  author?: string;
  description?: string;
  /** Minimum app version that can run this (string compare is the caller's job). */
  minAppVersion?: string;
  /** Requested capabilities — empty/absent for data-only kinds. */
  capabilities?: Capability[];
  /** Optional content hash (e.g. sha256), recorded at install so silent gist edits can't slip in.
   *  Absent unless the producer sets it. */
  integrity?: string;
  payload: P;
}

export interface WrapMeta {
  author?: string;
  description?: string;
  minAppVersion?: string;
  capabilities?: Capability[];
  integrity?: string;
}

/** Build an envelope around a kind-specific payload. */
export function wrapExtension<P>(
  kind: ExtensionKind, id: string, name: string, version: string, payload: P, meta: WrapMeta = {},
): ExtensionManifest<P> {
  const m: ExtensionManifest<P> = { manifest: MANIFEST_VERSION, kind, id, name, version, payload };
  if (meta.author) m.author = meta.author;
  if (meta.description) m.description = meta.description;
  if (meta.minAppVersion) m.minAppVersion = meta.minAppVersion;
  if (meta.capabilities && meta.capabilities.length) m.capabilities = meta.capabilities;
  if (meta.integrity) m.integrity = meta.integrity;
  return m;
}

export type ValidateResult =
  | { ok: true; manifest: ExtensionManifest }
  | { ok: false; error: string };

/**
 * Validate an unknown value as an ExtensionManifest. Checks the envelope only (not the
 * kind-specific payload — kind handlers do that). Refuses a manifest version newer than
 * this app understands so a future format can't be half-applied.
 */
export function validateManifest(value: unknown): ValidateResult {
  if (!value || typeof value !== "object") return { ok: false, error: "not an object" };
  const o = value as Record<string, unknown>;
  if (typeof o.manifest !== "number") return { ok: false, error: "missing manifest version" };
  if (o.manifest > MANIFEST_VERSION) {
    return { ok: false, error: `manifest v${o.manifest} is newer than this app supports (v${MANIFEST_VERSION}) — update to install` };
  }
  if (typeof o.kind !== "string" || !KINDS.includes(o.kind as ExtensionKind)) {
    return { ok: false, error: `unknown kind '${String(o.kind)}'` };
  }
  if (typeof o.id !== "string" || !o.id.trim()) return { ok: false, error: "missing id" };
  if (typeof o.name !== "string" || !o.name.trim()) return { ok: false, error: "missing name" };
  if (typeof o.version !== "string" || !o.version.trim()) return { ok: false, error: "missing version" };
  if (!("payload" in o)) return { ok: false, error: "missing payload" };
  return { ok: true, manifest: o as unknown as ExtensionManifest };
}

/** Parse a JSON string into a validated manifest (tolerant of bad JSON). */
export function parseManifest(text: string): ValidateResult {
  let v: unknown;
  try { v = JSON.parse(text); } catch (e) { return { ok: false, error: `invalid JSON: ${String(e)}` }; }
  return validateManifest(v);
}

// ── Share code (copy-paste transport) ─────────────────────────────────────────
// A single opaque string carrying the whole manifest — the no-account, no-network
// path. Unicode-safe base64url of the JSON (no compression; manifests are small).

function toBase64Url(s: string): string {
  const bytes = new TextEncoder().encode(s);
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}
function fromBase64Url(code: string): string {
  const b64 = code.replace(/-/g, "+").replace(/_/g, "/");
  const bin = atob(b64);
  return new TextDecoder().decode(Uint8Array.from(bin, (c) => c.charCodeAt(0)));
}

/** Encode a manifest as a shareable code string. */
export function encodeShareCode(m: ExtensionManifest): string {
  return toBase64Url(JSON.stringify(m));
}

/** Decode + validate a share-code string back into a manifest. */
export function decodeShareCode(code: string): ValidateResult {
  let json: string;
  try { json = fromBase64Url(code.trim()); } catch (e) { return { ok: false, error: `bad share code: ${String(e)}` }; }
  return parseManifest(json);
}

runtime.features/planner/lib/integrationStrategy:
import type { FlowPush } from "../fleet/agentFlow";

/** Fleet integration strategy (#378): a named preset that selects how workers integrate
 *  and how the director behaves. Chosen at the fleet level (project default) and
 *  overridable per stream. */
export type IntegrationStrategy = "self-merge" | "pr-ci" | "manual";
export type DirectorMode = "watchdog" | "integrator";
export type WorkerTest = "full" | "owned" | "none";

export const INTEGRATION_STRATEGIES: IntegrationStrategy[] = ["self-merge", "pr-ci", "manual"];
export const DEFAULT_STRATEGY: IntegrationStrategy = "self-merge";

export interface StrategySettings {
  /** What the worker runs before integrating. */
  test: WorkerTest;
  /** The worker push policy this strategy maps onto (a FlowPush value). */
  integrate: FlowPush;
  /** How the director behaves under this strategy. */
  director: DirectorMode;
}

export const STRATEGY_SETTINGS: Record<IntegrationStrategy, StrategySettings> = {
  "self-merge": { test: "full", integrate: "self-merge",  director: "watchdog" },
  "pr-ci":      { test: "full", integrate: "auto-pr",     director: "integrator" },
  "manual":     { test: "full", integrate: "commit-only", director: "integrator" },
};

/** Coerce arbitrary input to a valid strategy or undefined. */
export function normalizeStrategy(v: unknown): IntegrationStrategy | undefined {
  if (typeof v !== "string") return undefined;
  const t = v.trim();
  return (INTEGRATION_STRATEGIES as string[]).includes(t) ? (t as IntegrationStrategy) : undefined;
}

/** Resolve the effective strategy for a stream: per-stream override, else fleet default, else DEFAULT_STRATEGY. */
export function resolveStrategy(
  streamStrategy: IntegrationStrategy | undefined,
  fleetStrategy: IntegrationStrategy | undefined,
): IntegrationStrategy {
  return streamStrategy ?? fleetStrategy ?? DEFAULT_STRATEGY;
}

export function strategySettings(s: IntegrationStrategy): StrategySettings {
  return STRATEGY_SETTINGS[s];
}

runtime.features/planner/lib/lintPlan.ts:
// Plan gap scanner (#528/#534 → #897). `findPlanGaps` flags empty files / unresolved
// placeholders in a stage's section content. Originally the lint-plan stage module's check; the
// stage engine + its dispatch wrapper were removed in #897 (Phase 4c/cleanup), and the
// placeholder check now lives in the declarative stage gate (Phase 4b — Planning computes a
// `hasPlanGaps` signal from this). Pure; no React/Tauri.

// Deliberate "fill this in later" markers a finished plan section shouldn't contain. Only the
// explicit dev markers — NOT ellipsis ("..."/"…") or the bare word "placeholder", which are normal
// prose and false-positived the gate (#918).
const PLACEHOLDER_RE = /\b(TODO|TBD|FIXME|XXX|TKTK)\b/i;

/** Gaps in a stage's artifacts: empty files or unresolved placeholders. Pure. */
export function findPlanGaps(artifacts: Record<string, string>): string[] {
  const gaps: string[] = [];
  for (const [file, content] of Object.entries(artifacts)) {
    const text = (content ?? "").trim();
    if (!text) gaps.push(`${file}: empty`);
    else if (PLACEHOLDER_RE.test(text)) gaps.push(`${file}: unresolved placeholder`);
  }
  return gaps;
}

runtime.features/planner/lib/marketConfig.ts:
// Market stage (#2430) — the pure data model behind the planner's market-research stage: the
// scored six-dimension rubric (problem severity × frequency × reachable market × competitive gap ×
// timing × moat), the competitor landscape, and the go/caution/no-go verdict. The planner produces
// the assessment by desk research only (never user polls) and records it with `bsc plan market set`
// (validated at write); the poll reflects the plan.db blob into `planMarketConfig`, and the
// `marketDefined` gate signal derives from it here. Pure (no React/Tauri) so it's unit-testable.
//
// The scoring RUBRIC (dimension labels/blurbs + per-blueprint-CATEGORY weights) is `@data`
// (`@data/market/rubric.json`, per the config-externalization standard #2027): greenfield weighs
// reachable-market/timing, transform/harden weigh severity/gap — the frontend computes the weighted
// total; the planner stores only the raw 1-5 scores.

import rubricEmbedded from "@data/market/rubric.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

/** The six rubric dimensions, in canonical display order. */
export const MARKET_DIMENSIONS = [
  "problemSeverity", "problemFrequency", "reachableMarket", "competitiveGap", "timing", "moat",
] as const;
export type MarketDimensionId = (typeof MARKET_DIMENSIONS)[number];

/** One scored rubric cell: an integer 1-5 with its rationale and ≥1 cited source (the citation
 *  discipline — every quantitative claim carries a fetched source, or the artifact is fiction). */
export interface MarketDimensionScore {
  score: number;
  rationale: string;
  sources: string[];
}

export type MarketRecommendation = "go" | "caution" | "no-go";

export interface MarketVerdict {
  recommendation: MarketRecommendation;
  rationale: string;
}

/** One competitor row of the landscape matrix (all fields but the name optional). */
export interface MarketCompetitor {
  name: string;
  pricing?: string;
  segment?: string;
  source?: string;
}

/** The `bsc plan market set` payload (#2430). `sizing` is a free key→value block (e.g. TAM/SAM/SOM
 *  figures) rendered generically; `null` from `bsc plan market get` means unset. */
export interface MarketConfig {
  summary: string;
  scores: Partial<Record<MarketDimensionId, MarketDimensionScore>>;
  sizing?: Record<string, string>;
  competitors?: MarketCompetitor[];
  verdict?: MarketVerdict;
}

// ── rubric (@data/market/rubric.json) ─────────────────────────────────────────

export interface MarketRubricDimension {
  id: string;
  label: string;
  blurb: string;
}

/** dimension id → weight (each category's table sums to 1). */
export type MarketWeights = Record<string, number>;

export interface MarketRubric {
  dimensions: MarketRubricDimension[];
  /** blueprint category (greenfield/transform/harden/maintain) → per-dimension weights. */
  weights: Record<string, MarketWeights>;
}

// The config-dir copy (#2047) overlays the embedded default — editable without a rebuild.
export const MARKET_RUBRIC: MarketRubric = overlayFile("market/rubric.json", rubricEmbedded as MarketRubric);

/** Resolve the weight table for a blueprint category; unknown/absent categories fall back to
 *  greenfield (the default lifecycle), then to equal weights so the total is always computable. */
export function marketWeights(category?: string): MarketWeights {
  const table = (category && MARKET_RUBRIC.weights[category]) || MARKET_RUBRIC.weights.greenfield;
  if (table) return table;
  return Object.fromEntries(MARKET_DIMENSIONS.map((id) => [id, 1 / MARKET_DIMENSIONS.length]));
}

/** The rubric's display metadata for one dimension (label/blurb), tolerant of a stale rubric file. */
export function marketDimensionMeta(id: MarketDimensionId): MarketRubricDimension {
  return MARKET_RUBRIC.dimensions.find((d) => d.id === id) ?? { id, label: id, blurb: "" };
}

// ── gate + scoring ────────────────────────────────────────────────────────────

const isRecord = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v);

/** An integer 1..5 — the only valid rubric score. */
function validScore(n: unknown): n is number {
  return typeof n === "number" && Number.isInteger(n) && n >= 1 && n <= 5;
}

function validDimension(s: MarketDimensionScore | undefined): boolean {
  return !!s
    && validScore(s.score)
    && typeof s.rationale === "string" && s.rationale.trim().length > 0
    && Array.isArray(s.sources) && s.sources.some((src) => typeof src === "string" && src.trim().length > 0);
}

/**
 * The `marketDefined` gate signal (#2430): all six dimensions scored (integer 1-5, non-empty
 * rationale, ≥1 non-empty source each) and a verdict present. A defensive re-check of what
 * `bsc plan market set` validates at write — a stale/partial blob never clears the gate.
 */
export function marketDefined(cfg: MarketConfig | null | undefined): boolean {
  if (!cfg || !isRecord(cfg.scores)) return false;
  if (!MARKET_DIMENSIONS.every((id) => validDimension(cfg.scores[id]))) return false;
  const v = cfg.verdict;
  return !!v
    && (["go", "caution", "no-go"] as const).includes(v.recommendation)
    && typeof v.rationale === "string" && v.rationale.trim().length > 0;
}

/**
 * The 0-100 weighted total: the weighted mean of each valid dimension's score×20. Weights are
 * normalized over the dimensions actually scored (so a not-quite-1 weight sum never skews the
 * scale); an all-zero weight table falls back to an equal-weight mean. Unscored config → 0.
 */
export function weightedMarketScore(cfg: MarketConfig | null | undefined, weights: MarketWeights): number {
  if (!cfg || !isRecord(cfg.scores)) return 0;
  const scored = MARKET_DIMENSIONS.filter((id) => validScore(cfg.scores[id]?.score));
  if (scored.length === 0) return 0;
  const wsum = scored.reduce((acc, id) => acc + (weights[id] ?? 0), 0);
  const weightOf = (id: MarketDimensionId) => (wsum > 0 ? (weights[id] ?? 0) / wsum : 1 / scored.length);
  const total = scored.reduce((acc, id) => acc + weightOf(id) * cfg.scores[id]!.score * 20, 0);
  return Math.round(total);
}

/** One dimension's contribution (in points of the 0-100 total, assuming weights sum to 1) —
 *  the per-row "weighted contribution" figure the rubric table shows. */
export function marketContribution(cfg: MarketConfig | null | undefined, id: MarketDimensionId, weights: MarketWeights): number {
  const s = cfg?.scores?.[id];
  if (!s || !validScore(s.score)) return 0;
  return (weights[id] ?? 0) * s.score * 20;
}

/** Coerce the `bsc plan market get` blob into a typed config — a light structural check (the CLI
 *  validates hard at write); anything that isn't an object with a `scores` object is rejected. */
export function coerceMarketConfig(raw: unknown): MarketConfig | null {
  if (!isRecord(raw) || !isRecord(raw.scores)) return null;
  return raw as unknown as MarketConfig;
}

runtime.features/planner/lib/mcpContext.ts:
// The planner's live extensions.md (#1054). The planner + director are exposed to EVERY installed
// MCP server (so the planner can call them while planning — e.g. research sources for a skill — and
// decide which workers need them); each worker gets only the servers its stream was assigned, on
// top of the global baseline. This renders that guidance from the actual installed set, replacing
// the static catalogue the Rust setup used to write. Pure (no React/Tauri) so it's unit-testable
// and shared by the launch path; the counterpart to blueprintSkills.buildSkillContext.

import { type McpServer } from "@/features/mcp";
import { MCP_CATALOG, type CatalogItem } from "@/shared/data/mcpCatalog";
import { writeProjectFile } from "@/shared/lib/core/projectFiles";

/** A one-line description for a server name — its catalog blurb if known, else a generic note. */
function describe(name: string, catalog: CatalogItem[]): string {
  const hit = catalog.find((c) => c.name.toLowerCase() === name.toLowerCase());
  return hit?.desc ?? "(custom server — see the MCP screen for its config)";
}

/**
 * Render the planner's extensions.md from the installed servers it is exposed to. `servers` is the
 * runnable installed set (see {@link resolveAllInstalledMcp}); `catalog` supplies descriptions.
 */
export function buildMcpContext(servers: McpServer[], catalog: CatalogItem[] = MCP_CATALOG): string {
  const available = servers.length
    ? servers.map((s) => `- **${s.name}** — ${describe(s.name, catalog)}`).join("\n")
    : "_No MCP servers installed yet. Browse and download one from the MCP screen; it appears here automatically._";
  return `# Extensions (MCP servers)

These MCP servers are installed and **exposed to you (the planner) right now** — you can call their
tools directly while planning (for example, to research real sources before authoring a skill). The
director sees the same set.

## Available now

${available}

## Assigning servers to workers

Each worker sees the **global** servers plus only the servers you assign to its stream. Assign by
adding the server name to that stream's \`mcp\` list in the fleet plan, e.g. \`"mcp": ["Research"]\`
(written with \`bsc plan fleet set\`). Use this to give one worker a tool its lane needs without
handing it to the whole fleet; for a tool every worker needs, scope it project-wide with
\`bsc plan mcp add <name>\` instead.

## Installing more

Some servers are **built in** (e.g. **Research**) — always available, no install needed. Others
install from source: browse and download them in the MCP screen, and a downloaded server shows up
here automatically and becomes assignable. Never invent secret env values; the user fills any
tokens/keys in the MCP screen.
`;
}

/** Write the project hub's extensions.md from the installed servers (#1054). */
export async function writeProjectMcpContext(args: { projectKey: string; servers: McpServer[] }): Promise<void> {
  await writeProjectFile(args.projectKey, "extensions.md", buildMcpContext(args.servers));
}

runtime.features/planner/lib/mcpPaneData.ts:
// Pure mapping from the MCP-servers store → the planning page's MCP pane view-model (#878).
// Joins each MCP server scoped to a project with its catalog metadata (description, transport,
// first-party/official, download link) and an optional install-state map, so the pane is a
// dumb view. No React/Tauri — unit-tested.
//
// `McpServerDef` is the stored data model (lib/mcpServers); `McpServer` is the pane view-model.

import type { McpServer as McpServerDef } from "@/features/mcp";
import { MCP_CATALOG } from "@/shared/data/mcpCatalog";
import { catalogLink } from "@/features/mcp";
import type { McpServer } from "../pane/projectPane.types";
import type { FleetPlan } from "../fleet/planFleet";

/** Per-server install lifecycle the pane tracks (seeded by a disk probe, advanced by the
 *  download/build buttons). Keyed by server id. */
export type McpInstallState = Record<string, McpServer["status"]>;

/** An MCP server applies to a project when it's global (`projects: []`) or scoped to it. */
function appliesToProject(e: McpServerDef, projectKey: string): boolean {
  return e.projects.length === 0 || e.projects.includes(projectKey);
}

/** The catalog entry for a server name (description / official flag), if any. */
function catalogMeta(name: string): { desc: string; official: boolean } {
  const c = MCP_CATALOG.find((x) => x.name === name);
  return {
    desc: c?.desc ?? "",
    // "official" = built by the MCP org; first-party (kevinthelago) servers are NOT official.
    official: !!c && c.by.startsWith("@modelcontextprotocol"),
  };
}

/** The launch command line shown in the pane: `command args` for stdio, the URL for http. */
function commandLine(e: McpServerDef): string {
  if (e.transport === "http") return e.url ?? "";
  return [e.command, e.args].filter(Boolean).join(" ").trim();
}

/**
 * Build the MCP pane view-model for a project: every MCP server that applies to it,
 * joined with catalog metadata, fleet reach, and install state.
 *
 * A project-scoped enabled server reaches the whole fleet (director + every worker) via the
 * launch wiring, so `scope` is "fleet" and `agents` is every fleet stream id (plus the
 * director). `status` comes from `installState` for downloadable servers (default
 * "available" until probed/built); a remote/built-in server is always "ready".
 */
export function buildMcpServers(
  servers: McpServerDef[],
  projectKey: string,
  fleet: FleetPlan | undefined,
  installState: McpInstallState = {},
): McpServer[] {
  const fleetAgents = (fleet?.streams ?? []).map((s) => s.id);
  const directorOn = fleet?.director.enabled ?? false;
  const agents = directorOn ? ["director", ...fleetAgents] : fleetAgents;

  return servers
    .filter((e) => appliesToProject(e, projectKey))
    .map((e) => {
      const { desc, official } = catalogMeta(e.name);
      const downloadable = !!catalogLink(e.name);
      // Remote/built-in servers are "ready" once enabled; downloadable ones follow their
      // install lifecycle (probe/build), defaulting to "available" until known.
      const status: McpServer["status"] = downloadable
        ? (installState[e.id] ?? "available")
        : "ready";
      return {
        id: e.id,
        name: e.name,
        transport: e.transport ?? "stdio",
        cmd: commandLine(e),
        desc,
        enabled: e.enabled,
        official,
        downloadable,
        status,
        // Only an enabled server actually reaches the fleet; a disabled one is configured
        // but not granted, so it has no scope yet.
        scope: e.enabled ? "fleet" : "—",
        agents: e.enabled ? agents : [],
        tools: [],
      };
    });
}

