runtime.features/planner/lib/repoReadme.ts:
// README generation (#848 / #1710): turn whatever plan content exists at publish into a thorough,
// badge-topped README. Pure + unit-tested; `handlePublish` applies the output (a planner that
// authored a richer README is preferred over this at publish). Stack-aware Getting-started commands
// come from the shared matcher in `stackTopics.ts`.

import { gettingStartedCmds } from "./stackTopics";

/** The repo's short name — the segment after the last `/`. */
function shortName(fullName: string): string {
  const i = fullName.lastIndexOf("/");
  return i >= 0 ? fullName.slice(i + 1) : fullName;
}

/** A planned feature, reduced to what the README renders. */
export interface ReadmeFeature {
  name: string;
  behavior?: string;
}

export interface ReadmeOpts {
  /** `owner/repo`. */
  fullName: string;
  /** Concise repo description / tagline (the project goal's first line). */
  description: string;
  /** The full goal prose → the Overview section (falls back to `description`). */
  goal?: string;
  /** The scope section text → a Scope section (omitted when absent). */
  scope?: string;
  /** The architecture section text → an Architecture section (omitted when absent). */
  architecture?: string;
  /** The planned features → a bulleted Features section (omitted when empty). */
  features?: ReadmeFeature[];
  /** The stack section text (verbatim, for the Tech stack section). */
  stackText?: string;
  /** Workflow filenames under `.github/workflows/` (e.g. `["ci.yml"]`) → CI status badges. */
  workflows?: string[];
  /** Default branch the badges point at. */
  defaultBranch?: string;
}

/**
 * Build a thorough README with badges, driven by whatever plan content is available at publish.
 * Sections render only when their input is present (graceful fallbacks), in this order: Overview
 * (full goal), Scope, Features, Tech stack, Architecture, Getting started, Contributing, License.
 * Badges: one CI status badge per workflow file, plus license + last-commit shields.
 */
export function buildReadme(opts: ReadmeOpts): string {
  const { fullName, description, goal, scope, architecture, features = [], stackText, workflows = [], defaultBranch = "main" } = opts;
  const [owner, repo] = fullName.split("/");
  const name = shortName(fullName);
  const clean = (s?: string) => (s ?? "").trim();

  const badges: string[] = [];
  for (const wf of workflows) {
    const label = wf.replace(/\.ya?ml$/i, "");
    badges.push(`[![${label}](https://github.com/${owner}/${repo}/actions/workflows/${wf}/badge.svg)](https://github.com/${owner}/${repo}/actions/workflows/${wf})`);
  }
  badges.push(`![License](https://img.shields.io/github/license/${owner}/${repo})`);
  badges.push(`![Last commit](https://img.shields.io/github/last-commit/${owner}/${repo})`);

  const lines = [
    `# ${name}`,
    "",
    badges.join(" "),
    "",
    description || "_A base-studio-code project._",
    "",
    "## Overview",
    "",
    clean(goal) || description || "Describe what this project does and who it's for.",
    "",
  ];

  if (clean(scope)) {
    lines.push("## Scope", "", clean(scope), "");
  }

  const feats = features.filter((f) => f && f.name && f.name.trim());
  if (feats.length) {
    lines.push("## Features", "");
    for (const f of feats) {
      const b = clean(f.behavior);
      lines.push(b ? `- **${f.name.trim()}** — ${b}` : `- **${f.name.trim()}**`);
    }
    lines.push("");
  }

  if (clean(stackText)) {
    lines.push("## Tech stack", "", clean(stackText), "");
  }

  if (clean(architecture)) {
    lines.push("## Architecture", "", clean(architecture), "");
  }

  lines.push(
    "## Getting started",
    "",
    "```bash",
    `git clone https://github.com/${owner}/${repo}.git`,
    `cd ${name}`,
    ...gettingStartedCmds(clean(stackText)),
    "```",
    "",
    "## Contributing",
    "",
    "See [CONTRIBUTING.md](CONTRIBUTING.md) and our [Code of Conduct](CODE_OF_CONDUCT.md).",
    "",
    "## License",
    "",
    "See [LICENSE](LICENSE).",
    "",
    "---",
    "",
    "_Scaffolded by base-studio-code._",
  );
  void defaultBranch; // reserved for branch-pinned badges if needed later
  return lines.join("\n");
}

runtime.features/planner/lib/sourceCatalog.ts:
// Migration SOURCE catalog (#source-pane) — connector resolution behind the planner's Source stage:
// the per-connector resolver/colors, the sample scan inventory, the pitch→proposal keyword scan, and
// the redacted handle the planner is allowed to see. Split out of sourceConfig.ts (#1638); the type
// model lives in sourceSpecs.ts and the gate/derivation helpers in sourceGate.ts /
// dataModelDerivation.ts / sourceScanViews.ts.
//
// The native pre-built connectors were removed (#1976): the agent authors every connector as a
// runtime REST preset (#1235), so there is no static `CONNECTORS` catalog. {@link connector}
// resolves any id to a generic fallback shape so a declared runtime source still renders.

import type { Connector, DeclaredSource, DiscoveredObject, SourceBehavior } from "./sourceSpecs";

/** One agent-authored runtime connector as the backend surfaces it (#1980) — the live, app-wide
 *  list the Source pane polls (`data_runtime_connectors`). Mirrors the Rust `RuntimeConnectorView`
 *  (serde camelCase). Metadata only; the secret + resources stay backend-side. */
export interface RuntimeConnectorView {
  id: string;
  label: string;
  category: string;
  /** Declared auth method — one of `oauth` / `token` / `apikey` / `basic` (`RUNTIME_AUTH_KINDS`). */
  auth: string;
}

/** Human auth blurb for a runtime connector's declared auth method (the {@link Connector.authLabel}). */
const RUNTIME_AUTH_LABEL: Record<string, string> = {
  oauth: "OAuth", token: "token", apikey: "API key", basic: "Basic auth",
};

/** Resolve a connector by id (#1980). When `runtime` carries an agent-authored connector with that
 *  id, its real `label` / `auth` / `category` are used; otherwise — and for an unknown id — a generic
 *  fallback shape so any declared source still renders. Both keep the simple token form (no fields ⇒
 *  a one-click connect + sample scan); the full per-auth connect form is Phase 5b. */
export function connector(id: string, runtime?: readonly RuntimeConnectorView[]): Connector {
  const rt = runtime?.find((r) => r.id === id);
  if (rt) {
    const name = rt.label || id;
    return {
      id, name, badge: name.slice(0, 2).toUpperCase(),
      authLabel: RUNTIME_AUTH_LABEL[rt.auth] ?? rt.auth ?? "custom",
      category: rt.category || undefined,
      spec: { auth: "token", fields: [], contributes: "—" },
    };
  }
  return {
    id, name: id, badge: id.slice(0, 2).toUpperCase(), authLabel: "custom",
    spec: { auth: "token", fields: [], contributes: "—" },
  };
}

// ── Scan visualizations (#1209) — per-source accent color ─────────────────────────────────────

/** A per-source accent color for multi-source provenance (matches the design's SF/QB/QBO mapping). */
export function connectorColor(connectorId: string): string {
  const map: Record<string, string> = {
    salesforce: "var(--info)", quickbase: "var(--accent)", quickbooks: "var(--success)",
    hubspot: "var(--violet)", monday: "var(--accent)", dynamics365: "var(--info)",
    netsuite: "var(--success)", "sap-odata": "var(--info)", sql: "var(--accent)",
  };
  if (map[connectorId]) return map[connectorId];
  const palette = ["var(--info)", "var(--accent)", "var(--success)", "var(--violet)"];
  let h = 0;
  for (const c of connectorId) h = (h * 31 + c.charCodeAt(0)) >>> 0;
  return palette[h % palette.length];
}

// ── Sample scan (#source-pane) — the discovered inventory a connect surfaces. Until the native
//    read-only connectors land (separate backend work), the hi-fi pane uses these per-connector
//    samples so every state is demonstrable; the SHAPE is what a real scan returns. ──────────────
const SAMPLE_SCANS: Record<string, { objects: DiscoveredObject[]; behaviors: SourceBehavior[] }> = {
  quickbooks: {
    objects: [{ name: "Customers", count: 2940 }, { name: "Invoices", count: 18220 }, { name: "Items", count: 430 }, { name: "Payments", count: 12118 }],
    behaviors: [{ label: "recurring-invoice rule" }],
  },
  quickbase: {
    objects: [{ name: "Projects", count: 1204 }, { name: "Tickets", count: 8991 }, { name: "Vendors", count: 310 }],
    behaviors: [{ label: "2 form rules" }, { label: "1 Pipeline (auto-assign)" }],
  },
  salesforce: {
    objects: [{ name: "Accounts", count: 3120 }, { name: "Contacts", count: 9840 }, { name: "Opportunities", count: 2210 }],
    behaviors: [{ label: "validation rules" }, { label: "Flows / Process Builder" }],
  },
};

/** The inventory a scan of `connectorId` discovers (sample data, see above). */
export function sampleScan(connectorId: string): { objects: DiscoveredObject[]; behaviors: SourceBehavior[] } {
  return SAMPLE_SCANS[connectorId] ?? {
    objects: [{ name: "Records", count: 0 }],
    behaviors: [],
  };
}

// ── Propose sources from the pitch (#1349) ───────────────────────────────────────────────────────
// The Source stage's "Confirm N sources" banner is seeded from the planner's pitch BEFORE any live
// `<source_config>` tag arrives: a keyword scan over the pitch prose maps mentioned legacy systems to
// connector ids. This makes the stage open with the user CONFIRMING the obvious migration
// sources rather than hunting the catalog. The match is conservative (word-boundary aliases) so an
// unrelated mention doesn't propose a source; the user can always edit the selection or add more.

/** Per-connector aliases matched (case-insensitive, word-boundary) against the pitch prose. */
const PITCH_ALIASES: Record<string, string[]> = {
  quickbooks: ["quickbooks", "qbo", "quick books"],
  quickbase: ["quickbase", "quick base"],
  salesforce: ["salesforce", "sfdc"],
  hubspot: ["hubspot", "hub spot"],
  monday: ["monday.com", "monday com", "monday"],
  dynamics365: ["dynamics 365", "dynamics365", "dynamics", "d365"],
  netsuite: ["netsuite", "net suite"],
  "sap-odata": ["sap odata", "sap"],
  sql: ["postgres", "postgresql", "mysql", "mariadb", "sql server", "sqlserver", "oracle db", "sql database"],
  rest: ["openapi", "swagger", "rest api"],
  csv: ["csv export", "csv file", "spreadsheet export"],
};

/** Escape a literal alias for use inside a RegExp. */
function escapeRe(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/** Connector ids to propose from a planner pitch: any id whose alias appears in the prose
 *  (word-boundary, case-insensitive), deduped and in {@link PITCH_ALIASES} order. With the static
 *  catalog gone (#1976) the alias table is the source of proposable ids. Empty for an empty/blank
 *  pitch or one that mentions no known system. */
export function proposeFromPitch(pitch: string | undefined): string[] {
  const text = (pitch ?? "").toLowerCase();
  if (!text.trim()) return [];
  const ids: string[] = [];
  for (const [id, aliases] of Object.entries(PITCH_ALIASES)) {
    const hit = aliases.some((a) => new RegExp(`(^|[^a-z0-9])${escapeRe(a)}([^a-z0-9]|$)`, "i").test(text));
    if (hit) ids.push(id);
  }
  return ids;
}

/** A redacted handle the planner may see for a connected source — instance + env, never a credential. */
export function redactedHandle(s: DeclaredSource): string {
  const c = connector(s.connectorId);
  const inst = s.instance || c.name;
  const env = s.env ? ` · ${s.env}` : "";
  return `${inst}${env} · held by app`;
}

runtime.features/planner/lib/sourceConfig.ts:
// Migration SOURCE config (#source-pane, design/Source connection pane kickoff) — the data model
// behind the planner's Source stage (right after Repos): the legacy systems a project migrates FROM,
// connected READ-ONLY so the planner can scan them into a Data Model. Pure (no React/Tauri) so the
// catalog, the per-connector ConnectionSpec, and the readiness checks that drive the stage gate are
// unit-testable. Mirrors the deployConfig.ts shape.
//
// One SourceConfig per project (store slice `planSourceConfig`). The Source pane edits it; the
// `sourcesConnected` gate signal (Planning.tsx) is `allSourcesConnected(config)`.
//
// SECURITY BOUNDARY: a connector's SECRET field values NEVER live in this config (they go to the OS
// keychain on the device and are never persisted here or shared with the planning agent). The config
// keeps only non-secret fields, a redacted `handle`, and the discovered (not extracted) inventory.
//
// This module is the PUBLIC SURFACE (#1638). The implementation is split across focused modules that
// this file re-exports so importers don't churn:
//   - sourceSpecs.ts          — the type model (auth/field specs, discovered-inventory shapes, SourceConfig)
//   - sourceCatalog.ts        — the connector catalog + resolution, presets, samples, pitch proposal, colors
//   - sourceGate.ts           — connection counts/readiness + the gate signals (#1712)
//   - dataModelDerivation.ts  — the canonical Data Model derivation (#1712)
//   - sourceScanViews.ts      — the Graph / List / Process scan view-models (#1712)

export type {
  AuthMethod, SpecField, ConnectionSpec, Connector,
  DiscoveredField, DiscoveredObject, SourceBehavior,
  ScanAutomationKind, ScanAutomation, ScanBusinessProcess, ScanDerivedKind, ScanDerivedLogic, PlatformScanView,
  SourceStatus, DeclaredSource, SourceConfig,
} from "./sourceSpecs";
export { defaultSourceConfig, newDeclaredSource } from "./sourceSpecs";

// The native pre-built connectors were removed (#1976): there is no static catalog or backend preset
// catalog, so `connector(id)` resolves any id to a generic fallback shape (a one-click token connector).
export {
  connector, connectorColor, sampleScan, proposeFromPitch, redactedHandle,
} from "./sourceCatalog";
export type { RuntimeConnectorView } from "./sourceCatalog";

export {
  isConnected, connectedCount, allSourcesConnected, sourceChecks,
  migrationActive, dataModelSignals, downstreamImpact,
} from "./sourceGate";
export { deriveDataModel } from "./dataModelDerivation";
export type { ScanViewField, ScanViewEntity } from "./sourceScanViews";
export { scanEntities, scanEdges, aggregatePlatform, isMultiSource } from "./sourceScanViews";

runtime.features/planner/lib/sourceDiscovery.ts:
// Discovery-declared integrations → the Source pane's proposals (#4054).
//
// The pane's "Confirm N sources" banner used to be seeded by scanning the PITCH for keywords
// (`proposeFromPitch`). That was the best signal available when it was written, and it no longer is:
// since #4024 the planner records the integrations the user actually CONFIRMED in conversation, each
// with a `direction`, and `direction: "source"` means exactly "data migrates FROM this" — which is what
// the Source pane exists to offer.
//
// Guessing from keywords when the answer has been stated is the wrong input: the scan can omit a system
// the user named and propose one they never mentioned. These helpers are pure so the precedence and the
// direction filter are unit-testable without the pane.

/** One declared integration as `bsc plan discovery integration list --json` emits it (camelCase wire,
 *  matching the Rust `PlanIntegration`). Every field but `id` may be absent. */
export interface DeclaredIntegration {
  id: string;
  name?: string;
  /** `source` = data migrates FROM it | `runtime` = the built app talks to it while running. */
  direction?: string;
  docs?: string;
  baseUrl?: string;
  /** The auth SCHEME in prose ("OAuth2 client credentials"). Never a secret. */
  auth?: string;
  purpose?: string;
}

/** The `direction` the Source pane cares about — a migration source, not a runtime dependency. */
export const SOURCE_DIRECTION = "source";

/**
 * The migration sources among `rows`, in declaration order.
 *
 * Filters defensively rather than trusting the caller's `--direction` flag: a runtime integration must
 * NEVER reach the Source pane. That is the entire point of the split — a payment API is not something
 * you migrate off, and offering it as one sends the user down a pointless connect-and-scan path.
 * Rows without a usable `id` are dropped (they cannot be keyed), and duplicate ids collapse to the
 * first, so a re-declared integration proposes once.
 */
export function migrationSources(rows: readonly DeclaredIntegration[]): DeclaredIntegration[] {
  const seen = new Set<string>();
  const out: DeclaredIntegration[] = [];
  for (const r of rows ?? []) {
    const id = (r?.id ?? "").trim();
    if (!id || r?.direction !== SOURCE_DIRECTION || seen.has(id)) continue;
    seen.add(id);
    out.push({ ...r, id });
  }
  return out;
}

/**
 * The connector ids to seed the pre-declare banner with, and where they came from.
 *
 * **Discovery wins.** The pitch scan survives only as the fallback for a project whose Discovery
 * predates #4024 (or that never worked the `integrations` topic) — so a proposal is traceable to a
 * decision whenever one exists, and the older behaviour is preserved exactly where it isn't. Pure.
 */
export function proposedSourceIds(
  declared: readonly DeclaredIntegration[],
  fromPitch: readonly string[],
): { ids: string[]; origin: "discovery" | "pitch" | "none" } {
  const sources = migrationSources(declared);
  if (sources.length > 0) return { ids: sources.map((s) => s.id), origin: "discovery" };
  const pitch = (fromPitch ?? []).filter(Boolean);
  return pitch.length > 0 ? { ids: [...pitch], origin: "pitch" } : { ids: [], origin: "none" };
}

/**
 * The non-secret connect fields Discovery already captured for `id`, ready to seed a newly declared
 * source — so an agent authoring its connector starts from the vendor reference the user gave instead
 * of a blank form.
 *
 * ONLY `baseUrl` and `docs` cross: both are plain URLs. `auth` is deliberately excluded even though it
 * is a prose scheme rather than a credential — `DeclaredSource.fields` is the connect-form's value bag,
 * and a scheme string is not a field value. Nothing secret exists on this path to begin with.
 */
export function connectFieldsFor(
  id: string,
  declared: readonly DeclaredIntegration[],
): Record<string, string> {
  const row = migrationSources(declared).find((r) => r.id === id);
  if (!row) return {};
  const fields: Record<string, string> = {};
  const baseUrl = (row.baseUrl ?? "").trim();
  const docs = (row.docs ?? "").trim();
  if (baseUrl) fields.baseUrl = baseUrl;
  if (docs) fields.docs = docs;
  return fields;
}

runtime.features/planner/lib/sourceGate.ts:
// Migration SOURCE gate (#source-pane) — the pure readiness/gate helpers that drive the Source
// stage: connection counts + readiness checks, the `sourcesConnected` gate signal, and the
// Data Model gate signals derived from the live scan state (so the gate reflects scan progress
// without a round-trip to the store). Split out of sourceValidate.ts (#1712); the Data Model derivation
// lives in dataModelDerivation.ts and the type model in sourceSpecs.ts.

import type { ReadinessCheck } from "./readiness";
import { deriveDataModel } from "./dataModelDerivation";
import type { DeclaredSource, SourceConfig } from "./sourceSpecs";

/** A source counts as "connected" once it is scanning or fully scanned (authorized, secret on device). */
export function isConnected(s: DeclaredSource): boolean {
  return s.status === "scanning" || s.status === "scanned";
}

/** How many declared sources are connected. */
export function connectedCount(cfg: SourceConfig): number {
  return cfg.sources.filter(isConnected).length;
}

/** The `sourcesConnected` gate signal: ≥1 source declared and EVERY one fully scanned (no pending or
 *  errored source). An empty set can't pass (nothing to migrate from ⇒ the stage shouldn't apply). */
export function allSourcesConnected(cfg: SourceConfig | undefined): boolean {
  return !!cfg && cfg.sources.length > 0 && cfg.sources.every((s) => s.status === "scanned");
}

/** Readiness checks driving the in-pane banner: every declared source scanned, none errored. */
export function sourceChecks(cfg: SourceConfig): ReadinessCheck[] {
  const total = cfg.sources.length;
  const scanned = cfg.sources.filter((s) => s.status === "scanned").length;
  const errored = cfg.sources.filter((s) => s.status === "error").length;
  return [
    { id: "declared", label: "Declare the systems you're migrating from", ok: total > 0, detail: `${total} source${total !== 1 ? "s" : ""}` },
    { id: "connected", label: "Connect & scan every source", ok: total > 0 && scanned === total, detail: `${scanned}/${total} connected` },
    { id: "healthy", label: "No connection errors", ok: errored === 0, detail: errored ? `${errored} failed` : "all healthy" },
  ];
}

/** Whether a migration source is active for the project (≥1 declared source) — drives the `source`
 *  stage's `migrationSourceEnabled` so the stage applies. */
export function migrationActive(cfg: SourceConfig | undefined): boolean {
  return !!cfg && cfg.sources.length > 0;
}

/** The Data Model gate signals derived from the live scan state (feeds derivePlanStageState), so the
 *  source stage's gate reflects scan progress without reading back the canonical model. The canonical
 *  Data Model itself lives in the project's DuckDB store (`bsc data model get`, #1446) — these are
 *  progress booleans about the scan, not a read of that store. */
export function dataModelSignals(cfg: SourceConfig | undefined): { sourceReachable: boolean; modelInferred: boolean; schemaRefined: boolean } {
  if (!cfg) return { sourceReachable: false, modelInferred: false, schemaRefined: false };
  return {
    sourceReachable: cfg.sources.some((s) => s.status === "scanning" || s.status === "scanned"),
    modelInferred: cfg.sources.some((s) => s.status === "scanned"),
    schemaRefined: allSourcesConnected(cfg),
  };
}

/** The downstream-impact recap: what the scanned sources seed into features + structure. */
export function downstreamImpact(cfg: SourceConfig): { entities: number; fields: number; behaviors: number } {
  const m = deriveDataModel(cfg);
  const behaviors = cfg.sources.reduce((n, s) => {
    const p = s.platform;
    return n + (p ? p.automations.length + p.businessProcesses.length + p.derivedLogic.length : s.behaviors?.length ?? 0);
  }, 0);
  return { entities: m.entities.length, fields: m.entities.reduce((n, e) => n + e.fields.length, 0), behaviors };
}

runtime.features/planner/lib/sourceScanViews.ts:
// Migration SOURCE scan visualizations (#1209) — the view-models behind the Source pane's Graph /
// List / Process views: the entities (with record counts, source provenance, fields + inferred refs)
// the Graph + List views render, the ref edges for the Graph, the aggregated structured behaviors the
// Process view renders, and the multi-source provenance flag. Built from the derived Data Model and
// the scanned objects. Split out of sourceValidate.ts (#1712); the derivation lives in
// dataModelDerivation.ts and the per-source colors in sourceCatalog.ts.

import type { FieldType } from "@/features/planner/data/dataModel";
import { deriveDataModel, safeKey } from "./dataModelDerivation";
import { connectorColor } from "./sourceCatalog";
import type { PlatformScanView, SourceConfig } from "./sourceSpecs";

export interface ScanViewField { key: string; type: FieldType; required: boolean; identity: boolean; ref?: string; refLabel?: string; enumValues?: string[] }
export interface ScanViewEntity { key: string; label: string; count: number; source: string; srcColor: string; fields: ScanViewField[] }

/** The entities (with record counts, source provenance, fields + inferred refs) the Graph + List
 *  views render — built from the derived model and the scanned objects. */
export function scanEntities(cfg: SourceConfig): ScanViewEntity[] {
  const model = deriveDataModel(cfg);
  const labelByKey = new Map(model.entities.map((e) => [e.key, e.label ?? e.key]));
  const meta = new Map<string, { count: number; source: string }>();
  for (const s of cfg.sources) {
    if (s.status !== "scanned") continue;
    for (const o of s.objects ?? []) {
      const k = safeKey(o.name) || "entity";
      if (!meta.has(k)) meta.set(k, { count: o.count, source: s.connectorId }); // first wins (matches dedup)
    }
  }
  return model.entities.map((e) => {
    const m = meta.get(e.key) ?? { count: 0, source: "" };
    return {
      key: e.key,
      label: e.label ?? e.key,
      count: m.count,
      source: m.source,
      srcColor: connectorColor(m.source),
      fields: e.fields.map((f) => ({
        key: f.key, type: f.type, required: !!f.required, identity: e.identity.includes(f.key),
        ref: f.ref, refLabel: f.ref ? labelByKey.get(f.ref) ?? f.ref : undefined,
        enumValues: f.enum_values,
      })),
    };
  });
}

/** All ref relationships as edges for the Graph view. */
export function scanEdges(entities: ScanViewEntity[]): { from: string; to: string; label: string }[] {
  const keys = new Set(entities.map((e) => e.key));
  const edges: { from: string; to: string; label: string }[] = [];
  for (const e of entities) {
    for (const f of e.fields) {
      if (f.ref && keys.has(f.ref)) edges.push({ from: e.key, to: f.ref, label: `${f.key} → ${f.refLabel ?? f.ref}` });
    }
  }
  return edges;
}

/** The aggregated structured behaviors (across scanned sources) the Process view renders. */
export function aggregatePlatform(cfg: SourceConfig): PlatformScanView {
  const out: PlatformScanView = { automations: [], businessProcesses: [], derivedLogic: [] };
  for (const s of cfg.sources) {
    if (s.status !== "scanned" || !s.platform) continue;
    out.automations.push(...s.platform.automations);
    out.businessProcesses.push(...s.platform.businessProcesses);
    out.derivedLogic.push(...s.platform.derivedLogic);
  }
  return out;
}

/** Whether ≥2 distinct connector sources fed the scan (drives per-source provenance badges). */
export function isMultiSource(cfg: SourceConfig): boolean {
  return new Set(cfg.sources.filter((s) => s.status === "scanned").map((s) => s.connectorId)).size > 1;
}

runtime.features/planner/lib/sourceSpecs.ts:
// Migration SOURCE specs (#source-pane) — the pure type model behind the planner's Source stage:
// the per-connector connection contract (auth + form fields), the discovered inventory shape a scan
// returns, the structured behavior scan, and the per-project SourceConfig the Source pane edits.
// Split out of sourceConfig.ts (#1638); the connector catalog lives in sourceCatalog.ts and the
// gate/derivation/scan-view helpers in sourceGate.ts / dataModelDerivation.ts / sourceScanViews.ts.
// sourceConfig.ts re-exports them all.
//
// SECURITY BOUNDARY: a connector's SECRET field values NEVER live in this config (they go to the OS
// keychain on the device and are never persisted here or shared with the planning agent). The config
// keeps only non-secret fields, a redacted `handle`, and the discovered (not extracted) inventory.

import type { FieldType } from "@/features/planner/data/dataModel";

/** How a connector authenticates — drives which card the per-source ConnectionSpec renders. */
export type AuthMethod = "oauth" | "token" | "password" | "basic" | "apiKey" | "open" | "upload";

/** One input a connector's form collects. A `secret` field is masked, kept on-device, and never
 *  written into {@link DeclaredSource.fields}. */
export interface SpecField {
  key: string;
  label: string;
  /** Masked + keychain-bound; never persisted to the config or shared with the planner. */
  secret?: boolean;
  /** Optional field — absence doesn't block connecting (e.g. an app id that just scopes the scan). */
  optional?: boolean;
  hint?: string;
  placeholder?: string;
}

/** The per-connector connection contract — the same surface renders a different page from this. */
export interface ConnectionSpec {
  auth: AuthMethod;
  /** Form fields for token/password/basic/apiKey connectors (empty for oauth/upload). */
  fields: SpecField[];
  /** OAuth button label, e.g. "Connect to Salesforce" (oauth connectors only). */
  oauthLabel?: string;
  /** Show a Production / Sandbox environment toggle (oauth connectors). */
  envs?: boolean;
  /** One-line "will contribute →" summary of what a scan pulls in (objects + behaviors). */
  contributes: string;
}

/** A catalog connector the user can declare as a source. */
export interface Connector {
  id: string;
  name: string;
  /** Two/three-char mono badge, e.g. "QB". */
  badge: string;
  /** Catalog auth blurb, e.g. "OAuth" / "token" / "API key". */
  authLabel: string;
  spec: ConnectionSpec;
  /** Coarse grouping for the catalog UI (#1288) — `crm`, `erp`, `work`, … ; absent for the
   *  dedicated core connectors. */
  category?: string;
  /** A packaged generic-REST vendor preset (#1288), vs a dedicated connector. */
  preset?: boolean;
}

/** A discovered field: name + an inferred type + (for enums) the observed values (#1219). */
export interface DiscoveredField { name: string; type?: FieldType; enumValues?: string[]; ref?: string }
/** An object/table the scan discovered in a connected source (a count, not extracted rows).
 *  `fields` accepts bare column names (older fixtures) or typed {@link DiscoveredField}s (the live
 *  scan) — used to seed the derived Data Model's entity fields + types. */
export interface DiscoveredObject { name: string; count: number; fields?: (string | DiscoveredField)[] }
/** A behavior (business rule / automation) the scan found — these shape the target app, not just data. */
export interface SourceBehavior { label: string }

// ── Structured behavior scan (the Process visualization, #1209) ──────────────────────────────
// Mirrors the Rust `bsc_data::PlatformScan` (serde camelCase). The scan returns this alongside the
// flat `behaviors` labels; the Process view renders the detail (trigger → condition → actions, etc.).
export type ScanAutomationKind = "validation" | "workflow" | "flow" | "processBuilder" | "recurring" | "other";
export interface ScanAutomation {
  source: string; kind: ScanAutomationKind; name: string; object: string;
  active: boolean; trigger: string; condition: string; actions: string[];
}
export interface ScanBusinessProcess { source: string; name: string; object: string; active: boolean; steps: string[] }
export type ScanDerivedKind = "formula" | "code";
export interface ScanDerivedLogic { source: string; kind: ScanDerivedKind; name: string; object?: string; expression: string }
export interface PlatformScanView {
  automations: ScanAutomation[];
  businessProcesses: ScanBusinessProcess[];
  derivedLogic: ScanDerivedLogic[];
}

/** The lifecycle of one declared source. `declared` = chosen, not yet authorized; `connecting` =
 *  validating credentials; `scanning` = authorized, discovering objects; `scanned` = inventory in
 *  hand; `error` = auth/connection failed (holds the gate). */
export type SourceStatus = "declared" | "connecting" | "scanning" | "scanned" | "error";

/** A source the user declared they're migrating from. */
export interface DeclaredSource {
  uid: string;
  connectorId: string;
  /** Friendly instance label once connected, e.g. "Acme Co". */
  instance?: string;
  env?: "production" | "sandbox";
  status: SourceStatus;
  /** Non-secret field values (keyed by ConnectionSpec field key). SECRETS ARE NEVER STORED HERE. */
  fields: Record<string, string>;
  /** Redacted handle the planner is allowed to see ("Acme Co · Production · held by app"). */
  handle?: string;
  /** A secret was saved to the device keychain (we keep the flag, never the value). */
  secretSaved?: boolean;
  objects?: DiscoveredObject[];
  behaviors?: SourceBehavior[];
  /** The structured behavior scan (automations / processes / derived logic) for the Process view (#1209). */
  platform?: PlatformScanView;
  /** Failure reason for the error state, e.g. "token rejected (401)". */
  error?: string;
}

export interface SourceConfig {
  /** The canonical Data Model every connected source feeds, e.g. "Acme Core". */
  dataModelName: string;
  /** Connector ids the planner proposed from the pitch (the pre-declare ★ banner); cleared once acted on. */
  proposed: string[];
  sources: DeclaredSource[];
}

/** A fresh, empty source config. */
export function defaultSourceConfig(): SourceConfig {
  return { dataModelName: "", proposed: [], sources: [] };
}

/** A new declared source for `connectorId` (status `declared`, no fields yet). */
export function newDeclaredSource(connectorId: string, uid: string): DeclaredSource {
  return { uid, connectorId, status: "declared", fields: {} };
}

runtime.features/planner/lib/stackTopics.ts:
// Stack detection (#848 / #1710): the single regex-based matcher over a project's stack-section
// prose. Two consumers share it — `deriveTopics` (→ GitHub repo topics) and `gettingStartedCmds`
// (→ the README's install/run commands). Kept as TS (RegExp literals, not JSON) so the patterns
// stay first-class and case-insensitive whole-word matching is expressible.

/**
 * Test a stack-pattern against already-lowercased stack text. Centralizes the match step so both
 * the topic map and the getting-started toolchains run through one place.
 */
function matchesStack(lowerText: string, re: RegExp): boolean {
  return re.test(lowerText);
}

// Curated stack-keyword → GitHub-topic-slug map. Matched case-insensitively as whole words
// against the stack section text, so prose like "React 18 + TypeScript, Rust (Tauri)" yields
// `react`, `typescript`, `rust`, `tauri`. Lowercase-hyphenated per the topic-hygiene guide.
export const STACK_TOPICS: [RegExp, string][] = [
  [/\breact\b/, "react"], [/\bnext\.?js\b/, "nextjs"], [/\bvue\b/, "vue"], [/\bsvelte\b/, "svelte"],
  [/\bangular\b/, "angular"], [/\btypescript\b/, "typescript"], [/\bjavascript\b/, "javascript"],
  [/\bnode(\.?js)?\b/, "nodejs"], [/\bdeno\b/, "deno"], [/\bbun\b/, "bun"], [/\bvite\b/, "vite"],
  [/\brust\b/, "rust"], [/\btauri\b/, "tauri"], [/\bgo(lang)?\b/, "go"], [/\bpython\b/, "python"],
  [/\bdjango\b/, "django"], [/\bflask\b/, "flask"], [/\bfastapi\b/, "fastapi"], [/\bruby\b/, "ruby"],
  [/\brails\b/, "rails"], [/\bjava\b/, "java"], [/\bspring\b/, "spring-boot"], [/\bkotlin\b/, "kotlin"],
  [/\bswift\b/, "swift"], [/\bc\+\+\b/, "cpp"], [/\bc#\b/, "csharp"], [/\b\.net\b/, "dotnet"],
  [/\bpostgres(ql)?\b/, "postgresql"], [/\bmysql\b/, "mysql"], [/\bsqlite\b/, "sqlite"],
  [/\bmongo(db)?\b/, "mongodb"], [/\bredis\b/, "redis"], [/\bduckdb\b/, "duckdb"],
  [/\bgraphql\b/, "graphql"], [/\bdocker\b/, "docker"], [/\bkubernetes\b|\bk8s\b/, "kubernetes"],
  [/\btailwind\b/, "tailwindcss"], [/\bexpo\b/, "expo"], [/\breact native\b/, "react-native"],
];

// Toolchain → install/run commands, matched against the stack text the same way as STACK_TOPICS.
// First entry whose pattern hits contributes its commands; multiple may match (e.g. Tauri → both
// npm and cargo). Falls back to a generic comment when nothing is recognized.
const STACK_TOOLCHAINS: [RegExp, string[]][] = [
  [/\bnode(\.?js)?\b|\bnpm\b|\bvite\b|\breact\b|\bnext\b|\btypescript\b|\btauri\b/, ["npm install", "npm run dev"]],
  [/\bcargo\b|\brust\b|\btauri\b/, ["cargo build", "cargo run"]],
  [/\bpython\b|\bdjango\b|\bflask\b|\bfastapi\b/, ["pip install -r requirements.txt"]],
  [/\bgo(lang)?\b/, ["go mod download", "go run ."]],
];

/**
 * Derive GitHub repo topics from the stack section text, plus any explicit extras. Whole-word,
 * case-insensitive; deduped; lowercase-hyphenated; capped at GitHub's 20-topic limit. NB: these
 * are GitHub *repo topics*, distinct from the planner's discovery "topics".
 */
export function deriveTopics(stackText: string, extra: string[] = []): string[] {
  const found: string[] = [];
  const text = stackText.toLowerCase();
  for (const [re, topic] of STACK_TOPICS) {
    if (matchesStack(text, re)) found.push(topic);
  }
  const clean = (t: string) => t.trim().toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-+|-+$/g, "");
  const all = [...found, ...extra.map(clean)].filter(Boolean);
  return [...new Set(all)].slice(0, 20);
}

/**
 * A stack-aware Getting-started body. Detects the toolchain from the stack text and emits the
 * right install/run commands (npm / cargo / pip / go), falling back to a generic comment when
 * nothing is recognized. Returns the lines *inside* the ```bash fence (clone is added by the caller).
 */
export function gettingStartedCmds(stackText: string): string[] {
  const s = stackText.toLowerCase();
  const out: string[] = [];
  for (const [re, cmds] of STACK_TOOLCHAINS) {
    if (matchesStack(s, re)) out.push(...cmds);
  }
  return out.length ? out : ["# install dependencies and run the project's build/test/dev commands"];
}

