import { useRef } from "react";
import { useClickOutside } from "@/shared/hooks/useClickOutside";
import { MoreHorizontal, Check, Link2, Trash2 } from "lucide-react";
import { PlanGateRow } from "../pane/PlanStageBar";
import { IconBox } from "@/shared/ui/data/IconBox";
import { Ic } from "@/shared/ui/icons";
import { Button } from "@/shared/ui/controls/Button";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { blueprintHue, type BpItem } from "./blueprintLibrary.helpers";

/** A compact blueprint card for the right rail — the blueprint's own hued icon tile + name + ⋯
 *  menu, then a stages / visibility meta row and an optional gist link. */
export function BlueprintCard({ b, onUse, onDelete, activeId, menuOpenId, setMenuOpenId }: {
  b: BpItem;
  onUse: (id: string) => void;
  onDelete: (b: BpItem) => void;
  activeId?: string;
  menuOpenId: string | null;
  setMenuOpenId: (id: string | null) => void;
}) {
  const isActive = b.id === activeId;
  const menuId = "bp:" + b.id;
  const isOpen = menuOpenId === menuId;
  const menuRef = useRef<HTMLDivElement>(null);
  useClickOutside(menuRef, () => setMenuOpenId(null), isOpen);

  const hue = blueprintHue(b.h);

  return (
    <Box
      className="bp-rail-card"
      onClick={() => onUse(b.id)}
      title={isActive ? "Selected — new projects use this blueprint" : "Select this blueprint for new projects"}
      pad={[12, 13]} bg={isActive ? "var(--bg-elev2)" : "var(--bg-elev)"} radius={9} style={{
        border: "1px solid " + (isActive ? "var(--accent)" : "var(--border-soft)"), cursor: "pointer", position: "relative",
      }}>
      <Row className="bp-rail-card-head" gap={9}>
        <IconBox size={30} radius={8} background={`color-mix(in oklch, ${hue}, transparent 88%)`} border={`1px solid color-mix(in oklch, ${hue}, transparent 70%)`} color={hue}><Ic n={b.icon} size={15} /></IconBox>
        <Row className="bp-rail-card-titlewrap" gap={7} style={{ flex: 1, minWidth: 0 }}>
          <Box as="span" className="bp-rail-card-title" style={{ fontFamily: "var(--sans)", fontSize: 13, fontWeight: 600, color: "var(--fg)", minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{b.name}</Box>
        </Row>
        {/* eslint-disable-next-line no-restricted-syntax, jsx-a11y/no-static-element-interactions, jsx-a11y/click-events-have-key-events -- click-outside menu needs a real DOM ref (Box isn't forwardRef); onClick only stops row-click propagation, not a control */}
        <div ref={menuRef} className="bp-rail-card-menu" style={{ position: "relative" }} onClick={e => e.stopPropagation()}>
          <Button
            variant="ghost"
            style={{ height: 22, width: 22, padding: 0, display: "flex", alignItems: "center", justifyContent: "center" }}
            onClick={() => setMenuOpenId(isOpen ? null : menuId)}
            title="More options"
          ><MoreHorizontal size={13} /></Button>
          {isOpen && (
            <Box className="menu" style={{ minWidth: 158 }}>
              {/* eslint-disable-next-line no-restricted-syntax -- dropdown menu item (.menu-item), not a .btn-family button */}
              <button className="menu-item" onClick={() => { setMenuOpenId(null); onUse(b.id); }}>
                <Check size={12} /> use for new projects
              </button>
              {!b.builtIn && (
                <>
                  <Box style={{ borderTop: "1px solid var(--border-soft)", margin: "4px 0" }} />
                  {/* eslint-disable-next-line no-restricted-syntax -- dropdown menu item (.menu-item), not a .btn-family button */}
                  <button className="menu-item danger" onClick={() => { setMenuOpenId(null); onDelete(b); }}>
                    <Trash2 size={12} /> delete blueprint
                  </button>
                </>
              )}
            </Box>
          )}
        </div>
      </Row>
      {/* What this blueprint is FOR (#3840). Every packaged blueprint carries a `desc` and
          `buildBlueprintItems` maps it onto `pitch`, but the card never showed it — so the picker
          offered cards distinguished only by name + glyph. WRAPS deliberately (unlike the title,
          which stays single-line + ellipsis): the whole point is reading what you are choosing. */}
      {b.pitch.trim() && (
        <Text as="div" className="bp-rail-card-desc" size={11.5} tone="muted"
          style={{ marginTop: 7, lineHeight: 1.5, whiteSpace: "normal", overflowWrap: "anywhere" }}>
          {b.pitch}
        </Text>
      )}
      {/* Gated-stage progression (#blueprints): one segment per enabled, applicable section,
          colored by gate status — a preview of the lifecycle this blueprint walks through. */}
      <Box className="bp-rail-card-gates" style={{ marginTop: 9 }}>
        <PlanGateRow sections={b.sections} signals={{}} />
      </Box>
      {b.gistLabel && (
        <Row className="bp-rail-card-gist mono" gap={5} style={{ marginTop: 7, fontSize: 9, color: "var(--info)" }}>
          <Link2 size={10} />{b.gistLabel}
        </Row>
      )}
    </Box>
  );
}

runtime.features/planner/list/blueprintLibrary.h:
// ── Blueprint display helpers (#…): the blueprint's OWN hued icon tile, a visibility
// pill (draft / private gist / public gist), and a shortened gist link. ────────────────────────
//
// The tile used to be keyed off the lifecycle `category`, which #3785 removed from the model — and
// which had degenerated anyway: every packaged blueprint was `greenfield`, so all six cards drew the
// same glyph, the same hue, and the same meaningless "greenfield" badge. A blueprint is a
// goal/domain route now, so it carries its own `icon`/`h` (CRM → hub, HR → group, …) and the card
// renders those, exactly as the setup page already did.
import { timeAgoMs, truncate } from "@/shared/lib/core/format";
import type { Blueprint, BlueprintGist, BlueprintStage } from "../stages/blueprints";

/** The fallback accent hue for a blueprint that declares no `h` — matches the setup page's `?? 70`. */
export const DEFAULT_BLUEPRINT_HUE = 70;

/** A blueprint's accent colour, from its own hue. */
export function blueprintHue(h?: number): string {
  return `oklch(0.75 0.13 ${h ?? DEFAULT_BLUEPRINT_HUE})`;
}

/** The icon NAME a blueprint's tile renders (an `<Ic>` glyph). A blueprint that declares none falls
 *  back to `category` — the generic grid glyph, which is what `Ic` itself resolves an unknown name
 *  to, made explicit here so the fallback is visible at the call site rather than a surprise.
 *  (Deliberately NOT the name's initial: `Ic` renders SVG paths, never letters, so an initial would
 *  silently resolve to this same generic glyph anyway.) */
export function blueprintIcon(b: Pick<Blueprint, "icon">): string {
  return b.icon ?? "category";
}
export function prettyGist(g?: BlueprintGist): string | undefined {
  if (!g) return undefined;
  if (g.url) {
    const s = g.url.replace(/^https?:\/\//, "").replace(/^www\./, "");
    return truncate(s, 32, 30);
  }
  return g.id ? `gist · ${g.id.slice(0, 7)}` : undefined;
}

/** A blueprint surfaced in the Projects page — a saved library or built-in blueprint. */
export interface BpItem {
  id: string;          // library blueprint id
  name: string;
  pitch: string;
  icon: string;        // the blueprint's own `<Ic>` glyph name
  h?: number;          // the blueprint's own accent hue
  stages: number;
  sections: BlueprintStage[];   // the blueprint's sections — drives the gate-row preview
  builtIn?: boolean;   // a code-owned app template (can't be deleted)
  gistLabel?: string;
  updatedLabel: string;
  sort: number;        // recency key (epoch ms)
}

/** Build the blueprint list surfaced in the rail: ALL blueprints — the built-in app templates AND
 *  the user's saved library — so a blueprint can be SELECTED for the next project right here
 *  (#blueprints). */
export function buildBlueprintItems(blueprints: Blueprint[]): BpItem[] {
  const items: BpItem[] = [];
  for (const b of blueprints) {
    const hasGist = !!b.gist?.id;
    const sortMs = b.updatedAt ? new Date(b.updatedAt).getTime() : 0;
    items.push({
      id: b.id, name: b.name,
      pitch: b.pitch ?? b.desc ?? "",
      icon: blueprintIcon(b), h: b.h,
      stages: b.sections.length, sections: b.sections,
      builtIn: b.origin === "built-in",
      gistLabel: hasGist ? prettyGist(b.gist) : undefined,
      updatedLabel: timeAgoMs(sortMs), sort: sortMs,
    });
  }
  return items;
}

