runtime.features/planner/list/projectRepos.ts:
// Resolve which repos are linked to a project for the planning UI (#833). Pure + testable.
//
// There are two regimes:
// - **Published** project (a GitHub board exists → `activeProjectId`): use the board's repos,
//   falling back to the locally-linked set if the board hasn't loaded yet.
// - **Unpublished** project (no board yet): use the linked+cloned repos persisted under the
//   title-derived `effectiveProjectId`. The linked set is DB-owned (`bsc plan repo add` → plan.db,
//   reflected into `projectLocalRepos` by the section poll), so it survives a restart.
//
// KEY MISMATCH (#881): historically, linked repos were written under TWO keys — the name-derived
// `effectiveProjectId` (the planning link + auto-clone path) and the GitHub node id
// `activeProjectId` (the published-project + header path). New writes all use the one
// name-derived key (#2409), but persisted stores still carry node-id-keyed entries, so reading
// only one key dropped links written under the other — they vanished on restart → relink. We read
// the local set from BOTH keys (deduped) so a grandfathered link survives regardless of which key
// wrote it.

/** Deduped union of the persisted local links under every given key. Exported so the planning
 *  page reads the cloned/linked set under the same dual keys (avoids the #881 mismatch). */
export function localReposFor(projectLocalRepos: Record<string, string[]>, ...keys: (string | null | undefined)[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const key of keys) {
    if (!key) continue;
    for (const r of projectLocalRepos[key] ?? []) if (!seen.has(r)) { seen.add(r); out.push(r); }
  }
  return out;
}

export function effectiveProjectRepos(
  activeProjectId: string | null | undefined,
  effectiveProjectId: string,
  activeProjectRepos: string[],
  projectLocalRepos: Record<string, string[]>,
): string[] {
  // Links may be stored under either the node id or the title key — read both.
  const local = localReposFor(projectLocalRepos, effectiveProjectId, activeProjectId);
  if (activeProjectId) {
    // Published: the board's repos are authoritative once loaded; until then, the persisted
    // local links (under either key) stand in so they don't vanish during the load gap.
    return activeProjectRepos.length > 0 ? activeProjectRepos : local;
  }
  return local;
}

runtime.features/planner/list/projectScan.ts:
import { invoke } from "@tauri-apps/api/core";
import { DEFAULT_MAX_AGE_SECS } from "@/shared/lib/github/github";

/** Minimal shape of a ProjectV2 item needed to resolve its repository. */
export interface ProjectItemNode {
  content?: { repository?: { nameWithOwner?: string } | null } | null;
}

/**
 * Unique `owner/name` repositories referenced by a project's items.
 *
 * Repos are derived from the issues on the project board rather than the
 * project-level `repositories` field: that field only reflects repos a user has
 * explicitly linked in the GitHub UI and is therefore frequently incomplete,
 * whereas every issue carries the repository it lives in.
 */
export function reposFromItems(nodes: ReadonlyArray<ProjectItemNode>): string[] {
  return [...new Set(
    nodes
      .map(n => n.content?.repository?.nameWithOwner)
      .filter((r): r is string => !!r),
  )];
}

// Lightweight query — only the fields needed to resolve repos, so the tab-open
// scan stays cheap even when the heavier board view isn't mounted.
const PROJECT_REPOS_QUERY = `
query($id: ID!) {
  node(id: $id) {
    ... on ProjectV2 {
      items(first: 100) {
        nodes { content { ... on Issue { repository { nameWithOwner } } } }
      }
    }
  }
}`;

interface ReposQueryResult {
  node?: { items?: { nodes?: ProjectItemNode[] } } | null;
}

/**
 * Resolves the full set of repositories linked to a GitHub Project by scanning
 * its items. Returns `owner/name` strings (empty if the project has no issues).
 *
 * @param token - GitHub token for the GraphQL request.
 * @param projectId - ProjectV2 node id.
 */
export async function scanProjectRepos(token: string, projectId: string): Promise<string[]> {
  // `maxAgeSecs` routes the read through the backend TTL cache (#2447) so re-opening the tab
  // within the window doesn't re-POST the items scan. Raw invoke (not `githubGraphql`) because
  // this lib takes its token explicitly instead of reaching into the store.
  const data = await invoke<ReposQueryResult>("github_graphql", {
    token, query: PROJECT_REPOS_QUERY, variables: { id: projectId }, maxAgeSecs: DEFAULT_MAX_AGE_SECS,
  });
  return reposFromItems(data.node?.items?.nodes ?? []);
}

/**
 * Reads the on-disk plan sections for a project (the markdown the planner's
 * Claude session writes), keyed by section name. Mirrors the planner's own poll
 * so the plan can be refreshed without entering the planner.
 *
 * @param projectKey - the planning session key (the project title for projects
 *   opened from the list), matching the directory where plan files are stored.
 */
export async function scanPlanStages(projectKey: string): Promise<Record<string, string>> {
  return invoke<Record<string, string>>("read_plan_stages", { projectKey });
}

runtime.features/planner/list/projectsDbBridge.t:
// The Projects page ↔ `bsc project db` bridge (#2995) — drafts get a durable home in the projects DB,
// reached through the generic `bsc` bridge, so a draft survives a restart even when the fragile
// `localDraftProjects` cache misses. Mirrors projectLinksBridge/graphBridge discipline: `listDbProjects`
// returns `null` when the bridge is unreachable (the web shell, the tests, or an OLD bundled `bsc`
// without the `project db` verb) so the page keeps its persisted cache rather than blanking it, and
// every read is shape-gated before it's trusted. The write helpers are fire-and-forget (they degrade
// to cache-only when the bridge/binary is absent) — this is a strictly ADDITIVE, dual-write layer over
// the existing store draft map, never a replacement for it.
import { bscJson, bscWrite, bscRun } from "@/shared/lib/core/bsc";

/** A row of the durable projects DB (`bsc project db list`). `blueprint`/`category` may be null;
 *  `state` ∈ `drafted|planning|published|created`. */
export interface DbProject {
  key: string;
  title: string;
  pitch: string;
  blueprint: string | null;
  category: string | null;
  state: string;
  createdAt: number;
  updatedAt: number;
  /** When the project was TRIAGED (epoch ms), `null` if never, ABSENT on a pre-#4088 binary (#4088).
   *  Gates the Glance network — `projects.db` is the source; the store keeps an in-memory cache
   *  hydrated from here. Optional so an older sidecar's payload still shape-gates cleanly. */
  triagedAt?: number | null;
}

/** Shape-gate ONE raw list row into a {@link DbProject}, or `null` to drop it. `key` + `state` are the
 *  load-bearing identity/lifecycle fields (a row missing either is garbage); the rest are coerced with
 *  safe defaults so a partial payload can't crash the caller. */
function toDbProject(raw: unknown): DbProject | null {
  if (!raw || typeof raw !== "object") return null;
  const o = raw as Record<string, unknown>;
  if (typeof o.key !== "string" || !o.key) return null;
  if (typeof o.state !== "string" || !o.state) return null;
  return {
    key: o.key,
    title: typeof o.title === "string" ? o.title : "",
    pitch: typeof o.pitch === "string" ? o.pitch : "",
    blueprint: typeof o.blueprint === "string" ? o.blueprint : null,
    category: typeof o.category === "string" ? o.category : null,
    state: o.state,
    createdAt: typeof o.createdAt === "number" ? o.createdAt : 0,
    updatedAt: typeof o.updatedAt === "number" ? o.updatedAt : 0,
    // Absent on a pre-#4088 binary — `null` reads as "not triaged", which is the safe default: it
    // hides an unknown project from Glance rather than inventing a triage that never happened.
    triagedAt: typeof o.triagedAt === "number" ? o.triagedAt : null,
  };
}

/**
 * Read every row via `bsc project db list --json`. Returns `null` on ANY failure — an unreachable
 * bridge, an old `bsc` without the verb, non-JSON output, or a payload that isn't an array — so a
 * degraded environment keeps rendering the persisted draft cache rather than blanking it. Each row is
 * shape-gated; unrecognizable rows are silently dropped.
 */
export async function listDbProjects(): Promise<DbProject[] | null> {
  try {
    const rows = await bscJson<unknown>(null, ["project", "db", "list", "--json"], null);
    if (!Array.isArray(rows)) return null;
    return rows.map(toDbProject).filter((r): r is DbProject => r !== null);
  } catch {
    return null;
  }
}

/**
 * Upsert a draft into the projects DB (`bsc project db add`, one JSON object on stdin). Idempotent by
 * key (an existing key is updated), fire-and-forget, and degrades silently when the bridge/binary is
 * absent — the caller has already written the store draft map, so this is the durable mirror.
 */
export async function addDbProject(p: {
  key: string;
  title: string;
  pitch?: string;
  blueprint?: string | null;
  category?: string | null;
  state?: string;
}): Promise<void> {
  await bscWrite(null, ["project", "db", "add"], p);
}

/** Remove a draft from the projects DB (`bsc project db remove <key>`). Fire-and-forget; degrades
 *  silently (the store draft map is cleared separately by the caller). */
export async function removeDbProject(key: string): Promise<void> {
  await bscRun(null, ["project", "db", "remove", key]);
}

/** Advance a DB row's lifecycle state (`bsc project db state <key> <state>`). Fire-and-forget;
 *  degrades silently. (Provided for completeness; the Phase-1 draft flow uses add/remove.) */
export async function setDbProjectState(key: string, state: string): Promise<void> {
  await bscRun(null, ["project", "db", "state", key, state]);
}

/** Stamp a project TRIAGED in the durable store (#4088) — `bsc project triaged set`. Idempotent: an
 *  already-triaged project keeps its first timestamp. Fire-and-forget; degrades silently when the
 *  bridge or an older binary can't serve it, exactly like the other writers here. */
export async function setDbTriaged(key: string): Promise<void> {
  if (!key) return;
  try {
    await bscRun(null, ["project", "triaged", "set", key]);
  } catch {
    /* bridge unreachable — the in-memory marker still gates this session */
  }
}

runtime.features/planner/list/ProjectSetupPage.t:
// ProjectSetupPage (#3802) — the create-a-project setup PAGE. It sits BETWEEN the projects list and
// the planner: name the project, pick the blueprint (locked at creation, #3785), then "start
// planning →". Recast from the old `BlueprintPickerModal` — same guts (the blueprint library as
// selectable `BlueprintCard`s), but the shared inline `Pane` (a full-height header/body frame, #1824)
// so the create flow reads list → setup → planner. The back/cancel/start actions live in the pane
// header (no footer); the content is TOP-aligned. The composer (`ProjectsList`) runs the collision
// check + create + bind via `onStart`; the blueprint is the one consent point (frozen at creation).
//
// The gist-import affordance is no longer a modal (#3802): a persistent right-side `CloudBlueprints`
// column lists the not-yet-downloaded gist blueprints beside the local ones, with inline download.
// A downloaded blueprint drops into the left column, already selectable (`setSelected(newId)`).
import { useMemo, useState } from "react";
import { useAppStore } from "@/store";
import { uid, DEFAULT_BLUEPRINT_ID, type Blueprint, type BlueprintStage, type BlueprintDesign } from "../stages/blueprints";
import { type PreviewBlueprint } from "../blueprints/BlueprintModals";
import { DesignReconcileModal } from "@/features/designs";
import { reconcileDesign } from "@/shared/ui/kit";
import { DEFAULT_GIST_SOURCE } from "../blueprints/blueprintCatalog";
import { manifestToBlueprint, bundledSkillsFromManifest } from "../blueprints/blueprintShare";
import { installFromGist, gistIdFromUrl } from "@/features/planner/lib/gist/gist";
import { Pane } from "@/shared/ui/overlay/Pane";
import { useDragResize } from "@/shared/hooks/useDragResize";
import { BackButton } from "@/shared/ui/controls/BackButton";
import { Button } from "@/shared/ui/controls/Button";
import { TextField } from "@/shared/ui/controls/Field";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { BlueprintCard } from "./BlueprintCard";
import { buildBlueprintItems } from "./blueprintLibrary.helpers";
import { CloudBlueprints } from "./CloudBlueprints";

export interface ProjectSetupPageProps {
  /** ← back to the projects list (also the header "cancel"). */
  onBack: () => void;
  /** Start planning with the entered name + chosen blueprint. The composer runs the name-collision
   *  check, then the create + bind (the blueprint is LOCKED once the project is created). */
  onStart: (title: string, bpId: string) => void;
}

export function ProjectSetupPage({ onBack, onStart }: ProjectSetupPageProps) {
  const {
    blueprints, activeBlueprintId, removeBlueprint, setBlueprintStages, updateBlueprintMeta,
    importBlueprint, installBundledSkills, githubToken, githubUser, removeDesignContribution,
  } = useAppStore();

  const [title, setTitle] = useState("");
  const [selected, setSelected] = useState<string>(activeBlueprintId || DEFAULT_BLUEPRINT_ID);
  const [menuOpenId, setMenuOpenId] = useState<string | null>(null);
  const [reconcileTarget, setReconcileTarget] = useState<{ source: string; label: string; missing: string[]; themeRef?: string } | null>(null);

  const items = useMemo(() => buildBlueprintItems(blueprints), [blueprints]);
  // Gist ids already in the library — the cloud column hides these ("not yet downloaded" only).
  const downloadedGistIds = useMemo(
    () => new Set(blueprints.filter((b) => b.gist?.id).map((b) => b.gist!.id!)),
    [blueprints],
  );
  // The cloud column is drag-resizable (the Skills/rail pattern). invert: the column sits AFTER the
  // handle, so it grows as the pointer moves left.
  const cloudDrag = useDragResize({ initial: 340, min: 280, max: 560, axis: "x", invert: true });
  const canStart = title.trim().length > 0 && !!selected;
  const start = () => { if (canStart) onStart(title.trim(), selected); };

  function deleteBlueprint(id: string) {
    removeBlueprint(id);
    removeDesignContribution(id);
    if (selected === id) setSelected(DEFAULT_BLUEPRINT_ID);
  }

  // ── Import a blueprint from a gist (ported verbatim from BlueprintPickerModal) ─────────────────
  const freshSections = (s: BlueprintStage[]): BlueprintStage[] => s.map((x) => ({ ...x, uid: uid("sec") }));
  async function resolveBlueprintImport(ref: string): Promise<PreviewBlueprint> {
    const r = await installFromGist(ref, githubToken);
    if (!r.ok) throw new Error(r.error);
    const bpRes = manifestToBlueprint(r.manifest);
    if (!bpRes.ok) throw new Error(bpRes.error);
    const bp = bpRes.blueprint;
    return {
      name: bp.name, icon: bp.icon ?? bp.name[0]?.toUpperCase() ?? "B", h: bp.h ?? 70,
      sections: bp.sections, blueprint: bp,
      bundled: bundledSkillsFromManifest(r.manifest), gistId: gistIdFromUrl(ref) ?? undefined,
    };
  }
  function reconcileImportedDesign(source: string, label: string, design: BlueprintDesign | undefined) {
    const r = reconcileDesign(design);
    if (!r.complete) setReconcileTarget({ source, label, missing: r.missingCategories, themeRef: r.themeRef });
  }
  function importBlueprintPreview(preview: PreviewBlueprint, opts: { updatedAt?: string } = {}) {
    if (preview.bundled?.length) installBundledSkills(preview.bundled);
    const base = preview.blueprint;
    const gId = preview.gistId;
    const existing = gId ? blueprints.find((b) => b.gist?.id === gId) : undefined;
    if (existing) {
      setBlueprintStages(existing.id, freshSections(base?.sections ?? preview.sections));
      updateBlueprintMeta(existing.id, {
        ...(base?.name ? { name: base.name } : {}),
        gist: {
          ...(existing.gist ?? { state: "synced" }), state: "synced", id: gId,
          author: preview.author ?? existing.gist?.author, rev: preview.rev ?? existing.gist?.rev ?? "r1",
          updatedAt: opts.updatedAt ?? existing.gist?.updatedAt, behind: false,
        },
      });
      reconcileImportedDesign(existing.id, base?.name ?? existing.name, base?.design);
      setSelected(existing.id);
      return;
    }
    const bp: Blueprint = {
      ...(base ?? { id: "tmp", name: preview.name, desc: "Imported from gist.", sections: preview.sections }),
      icon: preview.icon, h: preview.h, origin: "imported", tags: ["imported"],
      gist: { state: "synced", id: gId, author: preview.author, rev: preview.rev ?? "r1", public: true, updatedAt: opts.updatedAt },
    };
    const newId = importBlueprint(bp);
    reconcileImportedDesign(newId, bp.name, bp.design);
    setSelected(newId);
  }

  // The cloud column's inline download: resolve the gist → import into the library (which selects
  // the new blueprint, so it lands in the left column ready to use). Rejections surface on the row.
  const downloadBlueprint = (gistId: string) => resolveBlueprintImport(gistId).then((p) => importBlueprintPreview(p));

  return (
    <>
      <Pane
        mode="inline"
        flush
        className="project-setup"
        header={
          <>
            <BackButton
              variant="text" label="projects" aria-label="Back to projects" onClick={onBack} className="mono"
              style={{ background: "none", border: "none", padding: 0, color: "var(--fg-muted)", cursor: "pointer", fontSize: 12 }}
            />
            <Box as="span" style={{ width: 1, height: 16, background: "var(--border-soft)" }} />
            <Text as="span" size={14} weight={600} style={{ color: "var(--fg)" }}>New project</Text>
            <Box as="span" style={{ flex: 1 }} />
            <Text as="span" size={11} tone="dim" style={{ marginRight: 2 }}>
              {canStart ? "ready" : "name + pick a blueprint"}
            </Text>
            <Button variant="ghost" onClick={onBack}>cancel</Button>
            <Button variant="primary" disabled={!canStart} onClick={start}>start planning →</Button>
          </>
        }
      >
        {/* body — two columns, content TOP-aligned: the setup form on the left, the persistent
            "Cloud blueprints" column on the right. Each column scrolls on its own. */}
        <Row align="stretch" style={{ flex: 1, minWidth: 0, minHeight: 0, overflow: "hidden" }}>
          <Box style={{ flex: 1, minWidth: 0, minHeight: 0, overflowY: "auto", padding: "22px 22px 28px" }}>
            <Box style={{ maxWidth: 640 }}>
              {/* project name — the page's PRIMARY action, given emphasis to match (#3840). It used to
                  render as an ordinary field, visually equal to everything under it, despite naming
                  something that is LOCKED at creation. Now an accent-framed step-1 block with a larger
                  input. Autofocused: a dedicated setup page whose first action is naming the project
                  should focus that field on open, not make the user hunt for it. */}
              <Box
                className="setup-name"
                pad={[16, 18]} radius={10} bg="var(--bg-elev)"
                style={{ border: "1px solid color-mix(in oklch, var(--accent), transparent 62%)" }}
              >
                <Row gap={8} align="center" style={{ marginBottom: 10 }}>
                  <Text as="span" mono size={9.5} tone="dim"
                    style={{ letterSpacing: "0.08em", textTransform: "uppercase" }}>step 1</Text>
                  <Text as="span" size={13} weight={600} style={{ color: "var(--fg)" }}>Name the project</Text>
                </Row>
                <TextField
                  label="Project name"
                  aria-label="Project name"
                  // eslint-disable-next-line jsx-a11y/no-autofocus -- single-purpose setup page; naming is the first action
                  autoFocus
                  hint="The name IS the project — it names its files, sessions, and GitHub project, and is locked once created."
                  placeholder="Name your project…"
                  value={title}
                  onChange={setTitle}
                  onKeyDown={(e) => { if (e.key === "Enter") start(); }}
                  style={{ height: 42, fontSize: 15 }}
                />
              </Box>

              {/* blueprint selection — the selectable local card list, defaulting to the active/Default
                  blueprint. Gist import lives in the right column (no button here). */}
              <Row gap={8} align="center" style={{ margin: "24px 0 10px" }}>
                <Text as="span" mono size={9.5} tone="dim"
                  style={{ letterSpacing: "0.08em", textTransform: "uppercase" }}>step 2</Text>
                <Text as="span" size={13} weight={600} style={{ color: "var(--fg)" }}>Pick a blueprint</Text>
                <Text as="span" size={11} tone="muted">seeds the plan · locked at creation</Text>
              </Row>

              {items.length === 0 ? (
                <Text as="div" mono size={11} tone="dim" style={{ lineHeight: 1.6, padding: "6px 2px" }}>
                  No blueprints yet. Download one from the cloud column, or generate one from a triaged project.
                </Text>
              ) : (
                <Stack gap={9}>
                  {items.map((b) => (
                    <BlueprintCard
                      key={b.id}
                      b={b}
                      onUse={setSelected}
                      onDelete={(bp) => deleteBlueprint(bp.id)}
                      activeId={selected}
                      menuOpenId={menuOpenId}
                      setMenuOpenId={setMenuOpenId}
                    />
                  ))}
                </Stack>
              )}
            </Box>
          </Box>

          {/* splitter — drag to resize the cloud column. */}
          <Box className="resize-x" {...cloudDrag.handleProps} title="Drag to resize" />

          {/* right — the persistent, resizable cloud-blueprint column (not-yet-downloaded gists + inline download). */}
          <Box style={{ flex: `0 0 ${cloudDrag.size}px`, width: cloudDrag.size, minWidth: 0, minHeight: 0, display: "flex", overflow: "hidden" }}>
            <CloudBlueprints
              defaultSource={githubUser?.login ?? DEFAULT_GIST_SOURCE}
              token={githubToken}
              downloadedGistIds={downloadedGistIds}
              onDownload={downloadBlueprint}
            />
          </Box>
        </Row>
      </Pane>

      {/* design reconcile — fires AFTER a download completes if the imported blueprint's design is
          missing kit pieces (this is NOT an import modal; it stays). */}
      {reconcileTarget && (
        <DesignReconcileModal
          source={reconcileTarget.source}
          label={reconcileTarget.label}
          missingCategories={reconcileTarget.missing}
          themeRef={reconcileTarget.themeRef}
          onClose={() => setReconcileTarget(null)}
        />
      )}
    </>
  );
}

