}

runtime.features/planner/pane/FocusedShell.tsx:
// Focused planner pane (#652) — the presentational shell around a single stage: the
// navigable stepper, the stage header with gate pill, lock/done banners, and the footer
// advance bar. Pure presentational (props in, callbacks out); the stage model + footer
// logic live in focusedPlan.ts. Styling: projectPane.css, scoped under .fp.
import { BackButton } from "@/shared/ui/controls/BackButton";
import { Button } from "@/shared/ui/controls/Button";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { connectorKind, type Stage, type GatePill, type FooterKind } from "../stages/focusedPlan";
import { stageKind } from "../blueprints/blueprintCatalog";
import { ProgressionRail, type RailNode } from "./ProgressionRail";
import type { StagePrompt } from "../session/plannerConductor";

/** Format one unmet requirement: "resolve the discovery topics (3 of 5)". */
function reasonText(u: { label: string; detail?: string }): string {
  return u.detail ? `${u.label} (${u.detail})` : u.label;
}

/**
 * The Stage Guidance card (#2862) — the panel that pairs the gate's REQUIREMENTS with the suggested
 * next-step PROMPT. Shows the unmet requirements inline (`stage.unmet`) while the gate is blocking, and
 * the single current-step prompt (#2859) with a legible Inject button. Once the gate passes it collapses
 * to a "Gate ready" row. Renders nothing when there's neither a requirement nor a prompt.
 *
 * DISCLOSURE (#3257): `open` is the gate-pill toggle state — `false` collapses the card entirely (the
 * default in the focused pane, so the surface stays clean until the user opens the gate). `undefined`
 * keeps it always-shown (the pre-#3257 behavior, for any caller that doesn't wire the toggle).
 */
export function StageGuidanceCard({ stage, pill, prompt, onInject, open }: {
  stage: Stage;
  pill: GatePill;
  /** The current-step prompt for this stage (#2859) — absent when the stage has none. */
  prompt?: StagePrompt;
  onInject?: (text: string) => void;
  /** Disclosure state (#3257) — `false` hides the card; the gate pill toggles it. `undefined` ⇒ shown. */
  open?: boolean;
}) {
  if (open === false) return null; // collapsed by the gate-pill toggle (#3257)
  const unmet = stage.unmet ?? [];
  const showReqs = pill !== "pass" && unmet.length > 0;
  const showPrompt = !!prompt && !!onInject;
  if (!showReqs && !showPrompt) return null;
  const ready = pill === "pass";
  return (
    <Box className={"stage-guide " + pill} role="group" aria-label="Stage guidance">
      <Box className="sg-head">
        <Box as="span" className="sg-dot" />
        <Text as="span" className="sg-title">{ready ? "Gate ready" : "What’s still needed"}</Text>
      </Box>
      {showReqs && (
        <ul className="sg-reqs">
          {unmet.map((u, i) => (
            <li key={i}>{u.label}{u.detail && <Text as="span" tone="dim"> — {u.detail}</Text>}</li>
          ))}
        </ul>
      )}
      {showPrompt && (
        <Box className="sg-prompt">
          <Text as="div" className="sg-eyebrow">Suggested next step</Text>
          <Text as="div" className="sg-plabel">{prompt!.label}</Text>
          <Text as="div" className="sg-ptext">{prompt!.text}</Text>
          <Button variant="primary" size="sm" className="sg-inject" onClick={() => onInject!(prompt!.text)}>
            Inject →
          </Button>
        </Box>
      )}
    </Box>
  );
}

/**
 * The sequenced rail (#668): one node per stage joined by connectors. Solid connectors trace the
 * in-sequence path walked so far; the current node pulses (accent ring); a banked-ahead node (gate
 * met out of sequence) is green-ringed, reached by a dashed connector. `highlight` pulses stages the
 * user still has to finish.
 *
 * A thin adapter over the shared {@link ProgressionRail} (#1869): it maps each {@link Stage} to a
 * rail node (the stage's status IS the rail status), labels it with the stage name, shows the stage
 * icon (✓ once done — the card look we standardized on), and hands the rail the focused-plan
 * {@link connectorKind} so the dashed banked / solid walked / dim upcoming connectors are preserved.
 */
export function Stepper({ stages, selectedIdx, onSelect, highlight }: {
  stages: Stage[]; selectedIdx: number; onSelect: (i: number) => void; highlight?: Set<string>;
}) {
  const nodes: RailNode[] = stages.map((p) => ({
    key: p.key,
    status: p.status,
    icon: stageKind(p.key).glyph,
    label: p.name,
    title: p.name,
  }));
  return (
    <ProgressionRail
      nodes={nodes}
      variant="stepper"
      selectedIdx={selectedIdx}
      onSelect={onSelect}
      highlight={highlight}
      connectorKind={(_, i) => connectorKind(stages, i)}
    />
  );
}

/** Eyebrow + title + blurb + a SLIM gate status pill for the focused stage. The pill is at-a-glance
 *  status (pass/wait, with a hover tooltip of what's left, #805); when `onToggleGate` is wired (#3257) it
 *  DOUBLES as the disclosure control for the {@link StageGuidanceCard} — a clickable chip with a caret
 *  that reflects `open`. Absent ⇒ a static status chip (the pre-#3257 behavior). The requirement DETAIL +
 *  the suggested prompt live in the guidance card (#2862). */
export function StageHeader({ stage, pill, open, onToggleGate }: {
  stage: Stage;
  pill: GatePill;
  /** Whether the guidance card is open (#3257) — reflected on the pill (caret + `.open`). */
  open?: boolean;
  /** When set, the gate pill TOGGLES the guidance card (#3257); absent ⇒ a static status chip. */
  onToggleGate?: () => void;
}) {
  const unmet = stage.unmet ?? [];
  const tip = pill !== "pass" && unmet.length > 0 ? "Still needed: " + unmet.map(reasonText).join("; ") : undefined;
  const cls = "ph-gate " + pill + (open ? " open" : "");
  return (
    <Box className="ph-head">
      <Box className="ph-title">
        <h2>{stage.name}</h2>
        {onToggleGate ? (
          // eslint-disable-next-line no-restricted-syntax -- bespoke `.ph-gate` toggle chip (styled by the `.fp .ph-gate` CSS, not the .btn kit)
          <button type="button" className={cls} title={tip} aria-expanded={!!open} aria-label="Toggle gate details" onClick={onToggleGate}>
            <Box as="span" className="gd" />
            gate
            <Box as="span" className="ph-caret" aria-hidden>{open ? "▾" : "▸"}</Box>
          </button>
        ) : (
          <Box as="span" className={cls} title={tip}>
            <Box as="span" className="gd" />
            gate
          </Box>
        )}
      </Box>
      <p className="ph-blurb">{stage.blurb}</p>
    </Box>
  );
}

/** Shown when browsing a not-yet-reachable stage. */
export function LockBanner({ activeName }: { activeName: string }) {
  return (
    <Box className="lock-banner">
      🔒 <Box as="span"><b>Locked.</b> Complete <b>{activeName}</b> to unlock this stage. Previewing only.</Box>
    </Box>
  );
}

/** Shown when reviewing a completed stage. */
export function DoneBanner() {
  return (
    <Box className="lock-banner" bg="color-mix(in oklch,var(--success),transparent 91%)" style={{ borderColor: "color-mix(in oklch,var(--success),transparent 72%)" }}>
      ✓ <Text as="span" tone="muted"><b style={{ color: "var(--success)" }}>Completed.</b> Edits here re-open the stage for review.</Text>
    </Box>
  );
}

const FOOTER_LABEL: Record<FooterKind, string> = {
  "back-to-current": "↩ back to current",
  "jump-to-current": "jump to current →",
  "approve-continue": "approve & continue →",
  "route-design": "◈ route design to project →",
  "publish": "⎇ Publish to GitHub",
};

/** The advance bar: back · progress · the context-sensitive primary action. */
export function StageFooter({ stage, action, published, publishLabel, onBack, onPrimary, onSkip }: {
  stage: Stage;
  action: { kind: FooterKind; enabled: boolean; canSkip?: boolean; skipEnabled?: boolean };
  /** The project already has a GitHub board — the publish action re-syncs it ("Update GitHub", #823). */
  published?: boolean;
  /** Override the publish action's label (#3280) — e.g. "Commit plan" when committing offline
   *  (there's no GitHub board to update). */
  publishLabel?: string;
  onBack: () => void;
  onPrimary: () => void;
  /** Skip the active stage (#921/#2854) — rendered only when `action.skipEnabled` (the stage is
   *  skippable now, or gate-override is on). A required stage shows no Skip at all. */
  onSkip?: () => void;
}) {
  const primaryLabel =
    action.kind === "approve-continue" && !action.enabled ? "gate blocking…"
    // An explicit publishLabel WINS over the "Update GitHub" re-sync default (#3280): offline there's no
    // board to update, so the caller's "Recommit plan" must show even when `published` is true.
    : action.kind === "publish" && publishLabel ? publishLabel
    : action.kind === "publish" && published ? "⟳ Update GitHub"
    : FOOTER_LABEL[action.kind];
  const primary = action.kind === "approve-continue" || action.kind === "route-design" || action.kind === "publish";
  // When the gate is blocking the advance button, the tooltip says what's still needed (#805).
  const unmet = stage.unmet ?? [];
  const stillNeeded = unmet.length > 0 ? "Still needed: " + unmet.map(reasonText).join("; ") : "";
  const blockedTip =
    action.kind === "approve-continue" && !action.enabled && stillNeeded ? stillNeeded : undefined;
  // Skip tooltip (#2854): Skip only renders when actionable, so no "how to enable" case — an
  // intrinsically-skippable/optional stage is the ordinary skip; a stage skippable only because
  // gate-override is on warns it bypasses the gate.
  const skipTip = stage.skippable
    ? "This stage is skippable — skip it and continue without completing its gate."
    : "⚠ Gate override: skip past this required stage without meeting its gate.";
  return (
    <Box className="ph-foot">
      <BackButton variant="text" label="back" className="nav-btn" disabled={stage.index === 0} onClick={onBack} aria-label="Back" />
      <Box as="span" className="prog">stage {stage.index + 1} of {stage.total}</Box>
      <Box as="span" style={{ flex: 1 }} />
      {/* The Skip control renders only when the active stage is skippable now, or gate-override is on
          (#2854) — a required stage like Discovery shows none, not a disabled ghost. */}
      {action.skipEnabled && onSkip && (
        // eslint-disable-next-line no-restricted-syntax -- bespoke `.nav-btn` footer button (styled by the `.fp .nav-btn` CSS, not the .btn kit)
        <button
          className="nav-btn"
          onClick={onSkip}
          title={skipTip}
        >
          skip stage →
        </button>
      )}
      {/* eslint-disable-next-line no-restricted-syntax -- bespoke `.nav-btn` footer button (styled by the `.fp .nav-btn` CSS, not the .btn kit) */}
      <button
        className={"nav-btn" + (primary ? " primary" : "")}
        disabled={!action.enabled}
        onClick={onPrimary}
        title={blockedTip}
      >
        {primaryLabel}
      </button>
    </Box>
  );
}

runtime.features/planner/pane/McpDownloadModal.t:
// Download-confirmation modal for MCP servers a plan pulls in automatically (#1055). The blueprint
// a project uses, and the servers the planner assigns, can reference first-party MCP servers that
// install from source. Rather than silently cloning third-party code, we surface this modal — each
// server with its description and a link to its GitHub repo — and only download on the user's
// confirmation. Presentational + self-contained (the parent owns the clone/build + status) so it's
// unit-testable; styled to match the blueprint modals.

import { ModalCard } from "@/shared/ui/overlay/ModalCard";
import { Chip } from "@/shared/ui/data/Chip";
import { Button } from "@/shared/ui/controls/Button";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Card } from "@/shared/ui/data/Card";

export type McpDownloadStatus = "pending" | "downloading" | "building" | "ready" | "error";

/** One server queued for download — catalog metadata + its live install status. */
export interface McpDownloadItem {
  name: string;
  repo: string;
  /** GitHub repo link (the source the user is consenting to install). */
  link: string;
  desc?: string;
  install?: string;
  status: McpDownloadStatus;
}

const STATUS_LABEL: Record<McpDownloadStatus, string> = {
  pending: "",
  downloading: "downloading…",
  building: "building…",
  ready: "✓ installed",
  error: "failed",
};

const STATUS_COLOR: Record<McpDownloadStatus, string> = {
  pending: "var(--fg-dim)",
  downloading: "var(--accent)",
  building: "var(--accent)",
  ready: "var(--success)",
  error: "var(--danger)",
};

/**
 * @param items   the servers queued for download, with live status
 * @param onConfirm  download all still-pending/failed servers (parent runs clone+build)
 * @param onCancel   dismiss — skip the un-downloaded servers (and close when all are done)
 */
export function McpDownloadModal({ items, onConfirm, onCancel }: {
  items: McpDownloadItem[];
  onConfirm: () => void;
  onCancel: () => void;
}) {
  const busy = items.some((i) => i.status === "downloading" || i.status === "building");

  const anyActionable = items.some((i) => i.status === "pending" || i.status === "error");
  const allDone = items.length > 0 && items.every((i) => i.status === "ready");

  return (
    <Box className="bp-page" style={{ position: "fixed", inset: 0 }}>
      <ModalCard
        icon={<Text as="span" size={15}>↓</Text>} title="Download MCP servers"
        sub="Your plan uses these MCP servers — review the source, then install."
        ariaLabel="Download MCP servers"
        onClose={onCancel} busy={busy} width={560}
        foot={
          <>
            <Box as="span" className="hint">Downloads from GitHub into <Text as="span" mono>~/.base-studio-code/mcp/</Text>. Skip to install later from the MCP screen.</Box>
            <Box as="span" style={{ flex: 1 }} />
            {allDone ? (
              <Button variant="primary" onClick={onCancel}>Done</Button>
            ) : (
              <>
                <Button variant="ghost" onClick={onCancel} disabled={busy}>Cancel</Button>
                <Button variant="primary" onClick={onConfirm} disabled={busy || !anyActionable}>
                  {busy ? "Downloading…" : "Download all"}
                </Button>
              </>
            )}
          </>
        }
      >
        <Stack gap={10}>
          {items.map((it) => (
            <Card key={it.name} style={{ padding: 13 }}>
              <Row gap={9} style={{ marginBottom: 6 }}>
                <Text as="span" mono size={13} weight={600} style={{ color: "var(--fg)" }}>{it.name}</Text>
                <Chip>first-party</Chip>
                <Box as="span" style={{ flex: 1 }} />
                {it.status !== "pending" && (
                  <Text as="span" mono size={10.5} style={{ color: STATUS_COLOR[it.status] }}>{STATUS_LABEL[it.status]}</Text>
                )}
              </Row>
              {it.desc && <Box className="hint" style={{ marginBottom: 6 }}>{it.desc}</Box>}
              <a className="mono" href={it.link} target="_blank" rel="noreferrer" style={{ fontSize: 11, color: "var(--accent)", wordBreak: "break-all" }}>{it.link}</a>
              {it.install && <Box className="hint" style={{ marginTop: 6, fontSize: 10 }}>{it.install}</Box>}
            </Card>
          ))}
        </Stack>
      </ModalCard>
    </Box>
  );
}

runtime.features/planner/pane/PlanStageBar.tsx:
// The planning progress bar — one segment per ENABLED blueprint SECTION (in declared
// order), each a track with a fill sized by that section's progress and colored by its
// status. Driven entirely by the blueprint's sections + the signal bag (#…): no
// PLAN_STAGES enum, so a custom / cloud-distributed section renders here too. Keeps the
// half-clipped "tucked under the divider" look from #508: the 12px pills sit in a 6px
// clipping strip, so only their top rounded half shows.

import { stageStatus, type BlueprintStage } from "../stages/blueprints";
import type { PlanSignals } from "../stages/stageGate";
import { stageKind } from "../blueprints/blueprintCatalog";
import { ProgressionRail, type RailNode, type RailStatus } from "./ProgressionRail";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";

function fillColor(status: string): string {
  switch (status) {
    case "complete":    return "var(--accent)";
    case "in-progress": return "color-mix(in oklch, var(--accent), transparent 45%)";
    case "locked":      return "var(--border)";
    default:            return "var(--bg-elev2)";
  }
}

export function PlanStageBar({ sections, signals, blocked, highlight }: {
  sections: BlueprintStage[];
  signals: PlanSignals;
  /** Section keys with an unpassed gate pipeline (#532). */
  blocked?: Set<string>;
  /** Section keys to flag for attention (e.g. a locked-Triage click); they pulse. */
  highlight?: Set<string>;
}) {
  // N/A sections (e.g. UI when the project needs no UI) are hidden entirely.
  const segments = sections
    .filter((s) => s.enabled)
    .map((section) => ({ section, ...stageStatus(section, sections, signals) }))
    .filter((s) => s.status !== "na");

  return (
    <Row align="start" gap={6} style={{ height: 6, overflow: "hidden", padding: "0 24px", flex: "0 0 auto" }}>
      {segments.map(({ section, status, fraction }) => {
        const isBlocked = blocked?.has(section.key) ?? false;
        const isHighlit = highlight?.has(section.key) ?? false;
        const pct = Math.round((status === "complete" ? 1 : fraction) * 100);
        return (
          <Box
            key={section.key}
            className={isHighlit ? "attn-pulse" : undefined}
            title={`${section.name} — ${status}${isBlocked ? " · gate blocked" : ""}${isHighlit ? " · incomplete" : ""}`}
            bg={isHighlit ? "color-mix(in oklch, var(--danger), transparent 70%)" : "var(--bg-elev2)"} radius={6} style={{
              flex: 1, height: 12, overflow: "hidden", position: "relative",
            }}
          >
            <Box bg={isBlocked ? "var(--danger)" : fillColor(status)} radius={6} style={{ position: "absolute", inset: 0, width: `${pct}%`}} />
          </Box>
        );
      })}
    </Row>
  );
}

/** Map the blueprint section render-status onto the rail's unified status set. "in-progress" (the
 *  current/available stage) becomes "active" — rendered as a static accent ring on the card (the
 *  stepper variant is what pulses it). "complete"/"locked" pass through; "na" is filtered upstream. */
function railStatus(status: string): RailStatus {
  return status === "complete" ? "complete" : status === "locked" ? "locked" : "active";
}

/**
 * A compact gated-icon progression for cards (#blueprints): one node per enabled, applicable
 * section, showing that stage's icon, status-colored, joined by connectors — a preview of the
 * lifecycle this blueprint walks through. A thin adapter over the shared {@link ProgressionRail}
 * (#1869): it maps the blueprint's sections (via {@link stageStatus}) into rail nodes. Each node's
 * `title` carries the stage name + blurb + gate (the on-hover help text).
 *
 * The icon is resolved through the built-in stage→icon map ({@link stageKind}, keyed by
 * `section.key`) — exactly like every other blueprint surface (the editor, StageSummary, the catalog
 * preview). It is deliberately NOT the per-section `glyph` string: an imported / authored blueprint's
 * sections carry untrusted (or empty) glyph values, so reading the map keyed by the stage's identity
 * guarantees a real icon for every known stage and a `category` fallback otherwise — never a blank.
 */
export function PlanGateRow({ sections, signals }: {
  sections: BlueprintStage[];
  signals: PlanSignals;
}) {
  const nodes: RailNode[] = sections
    .filter((s) => s.enabled)
    .map((section) => ({ section, ...stageStatus(section, sections, signals) }))
    .filter((s) => s.status !== "na")
    .map(({ section, status }) => ({
      key: section.key,
      status: railStatus(status),
      icon: stageKind(section.key).glyph,
      title: `${section.name} · ${status}\n${section.blurb}${section.gate ? `\nGate: ${section.gate}` : ""}`,
    }));
  if (nodes.length === 0) return null;
  return (
    <Box style={{ marginTop: 11 }}>
      <ProgressionRail nodes={nodes} variant="compact" />
    </Box>
  );
}

runtime.features/planner/pane/ProgressionRail.ts:
// ProgressionRail (#1869) — the ONE horizontal status-rail behind both planner surfaces:
// the blueprint-card gate preview (`PlanGateRow`) and the focused-pane sequenced stepper
// (`Stepper`). It renders a row of status-colored, icon-bearing nodes joined by connectors.
//
// The visual language is the blueprint card's (the look we standardized on, #1869): a 24px
// rounded-SQUARE node showing the stage's icon (✓ once done), status-colored — complete = filled
// success, ahead = success-ringed (banked out of sequence), active = accent-ringed (pulses only in
// the interactive stepper), skipped = info-tinted, locked/upcoming = dim. Pure presentational:
// callers map their own model (blueprint sections via `stageStatus`, or focused-plan `Stage`s) into
// `RailNode[]` and pass it in. CSS in progressionRail.css (imported here so every consumer gets it).

import { Fragment, type ReactNode } from "react";
import { Ic } from "../blueprints/blueprintIcons";
import { Box } from "@/shared/ui/layout/Box";
import type { ConnectorKind } from "../stages/focusedPlan";
import "./progressionRail.css";

/** The unified node state. The focused-pane `StageStatus` IS this set; the blueprint card maps its
 *  narrower `stageStatus` ("in-progress" → "active") into it. */
export type RailStatus = "complete" | "ahead" | "active" | "skipped" | "locked" | "upcoming";

export interface RailNode {
  key: string;
  status: RailStatus;
  /** Icon glyph NAME (resolved by the caller through the stage→icon map, `stageKind`) — rendered as
   *  inline SVG via {@link Ic}. A done node (complete/ahead) shows ✓ instead. */
  icon: string;
  /** Hover tooltip for the node. */
  title?: string;
  /** Label rendered beneath the node — shown in the `stepper` variant only. */
  label?: string;
}

/** A done node shows the ✓; any other state shows its stage icon (the card look — the ring color,
 *  not a distinct glyph, carries active/skipped/locked/upcoming). */
function nodeContent(n: RailNode): ReactNode {
  return n.status === "complete" || n.status === "ahead" ? "✓" : <Ic n={n.icon} size={13} />;
}

/** The card's 2-state connector: the segment AFTER a completed node is solid (success), else dim.
 *  The stepper passes its own richer `connectorKind` (solid/partial/dashed/dim, #668). */
function defaultConnector(nodes: RailNode[], i: number): ConnectorKind {
  return nodes[i].status === "complete" ? "solid" : "dim";
}

/**
 * @param nodes        the rail's nodes, in order
 * @param variant      "compact" = inline card preview (no labels, static); "stepper" = labeled,
 *                     interactive, the active node pulses
 * @param selectedIdx  the highlighted (selected) node — stepper navigation
 * @param onSelect     click handler; when omitted the rail is non-interactive (card preview)
 * @param highlight    node keys to flag for attention (they pulse red) — e.g. incomplete phases
 * @param connectorKind  per-gap connector style; defaults to the card's complete→solid/else→dim
 */
export function ProgressionRail({
  nodes,
  variant = "compact",
  selectedIdx,
  onSelect,
  highlight,
  connectorKind,
}: {
  nodes: RailNode[];
  variant?: "compact" | "stepper";
  selectedIdx?: number;
  onSelect?: (i: number) => void;
  highlight?: Set<string>;
  connectorKind?: (nodes: RailNode[], i: number) => ConnectorKind;
}) {
  if (nodes.length === 0) return null;
  const conn = connectorKind ?? defaultConnector;
  const rail = (
    <Box className={`prail ${variant}`}>
      {nodes.map((n, i) => {
        const segClass =
          `prail-seg ${n.status}` +
          (i === selectedIdx ? " sel" : "") +
          (highlight?.has(n.key) ? " attn" : "");
        const inner = (
          <>
            <Box as="span" className={`prail-node ${n.status}`}>{nodeContent(n)}</Box>
            {variant === "stepper" && <Box as="span" className="prail-label">{n.label}</Box>}
          </>
        );
        return (
          <Fragment key={n.key}>
            {onSelect ? (
              // eslint-disable-next-line no-restricted-syntax -- bespoke `.prail-seg` rail-node button (status-computed class, styled by progressionRail.css, not the .btn kit)
              <button type="button" className={segClass} title={n.title ?? n.label} onClick={() => onSelect(i)}>
                {inner}
              </button>
            ) : (
              <Box as="span" className={segClass} title={n.title}>
                {inner}
              </Box>
            )}
            {i < nodes.length - 1 && <Box as="span" className={"prail-conn " + conn(nodes, i)} />}
          </Fragment>
        );
      })}
    </Box>
  );
  // The stepper sits in a bordered strip below the pane header; the compact card preview is bare.
  return variant === "stepper" ? <Box className="prail-wrap">{rail}</Box> : rail;
}

runtime.features/planner/pane/ProjectPane.tsx:
// ProjectPane — planning-page right visualizer pane.
// v5: stage-focused one-at-a-time view (#652) with real data (#674).
// Ported from design/project-pane-v4/recommended; now wraps in a 7-stage stepper
// so the planning workflow is one focused stage at a time.
import { useState } from "react";
import { Pane } from "@/shared/ui/overlay/Pane";
import { ModalScrim } from "@/shared/ui/overlay/ModalScrim";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import "./projectPane.css";
import type { Flow, ContextFile, ProjectPaneData, McpServer } from "./projectPaneData";
import { type ModelId } from "@/app/console/lib/models";
import { hasStageGuidance, type Stage, type GatePill, type FooterKind } from "../stages/focusedPlan";
import {
  Stepper as FocusedStepper,
  StageHeader as FocusedStageHeader,
  StageGuidanceCard as FocusedStageGuidance,
  LockBanner as FocusedLockBanner,
  StageFooter as FocusedStageFooter,
} from "./FocusedShell";
import type { StagePrompt } from "../session/plannerConductor";
import type { DeployConfig } from "../lib/deployConfig";
import { type Topology } from "../relationship/relationshipGraph";
import { type DirectorDrive } from "../fleet/directorDrive";
import { FocusedStageBody } from "./FocusedBodies";
import { KindDot } from "./focusedPrimitives";
export function ProjectPane({
  data,
  projectId,
  onFlow,
  onModel,
  onPersona,
  // focused mode: one-stage sequenced rail (#652) — the only render mode (#1061)
  focus,
  onLinkRepo,
  onTopology,
  onDirectorDrive,
  onToggleMcp,
  onBuildMcp,
  onAddMcp,
  onRemoveMcp,
  onDeployChange,
  onInject,
}: {
  data?: ProjectPaneData;
  projectId?: string;
  onFlow?: (streamId: string, flow: Flow) => void;
  /** Permissions stage: set a stream's per-agent LLM model (undefined ⇒ global default) (#…). */
  onModel?: (streamId: string, model: ModelId | undefined) => void;
  onPersona?: (streamId: string, personaId: string | undefined) => void;
  /** The sequenced-rail focused mode (#652) — the sole render path (#1061 removed the legacy
   *  staged/flat view + its hardcoded PLAN_STAGES gate). */
  focus?: {
    stages: Stage[];
    selectedIdx: number;
    activeIdx: number;
    onSelect: (i: number) => void;
    pill: GatePill;
    footer: { kind: FooterKind; enabled: boolean; canSkip?: boolean; skipEnabled?: boolean };
    onBack: () => void;
    onPrimary: () => void;
    /** Skip the active stage (#921/#2854) — rendered only when `footer.skipEnabled` (the stage is
     *  skippable now, or gate-override is on); a required stage shows no Skip. */
    onSkip?: () => void;
    /** The project already has a GitHub board — the publish action reads as "Update GitHub" (#823). */
    published?: boolean;
    /** Override the footer publish label (#3280) — e.g. "Commit plan" when publishing offline. */
    publishLabel?: string;
    /** The selected stage's injectable prompts + inject handler — drives the header "?" helper (#…),
     *  replacing the removed auto-injecting conductor. */
    promptHelp?: { prompt: StagePrompt; onInject: (text: string) => void };
    /** The project's live required-context topics (#1061) — the Context body lists each by name
     *  with written/missing state so the user sees exactly which files the gate still needs. */
    requiredContext?: string[];
  };
  /** Callback to link a repository from the focused repos body (#677). */
  onLinkRepo?: (repo: string) => void;
  /** Set the project's coordination topology (#…) — director / peer / hybrid. */
  onTopology?: (t: Topology) => void;
  /** Set the director's drive mode (#…) — event / heartbeat / manual / off. */
  onDirectorDrive?: (d: DirectorDrive) => void;
  /** MCP stage (#878): toggle a server's fleet grant, download+build it, add a new one
   *  (catalog name / command / URL), or remove it. */
  onToggleMcp?: (id: string) => void;
  onBuildMcp?: (s: McpServer) => void;
  onAddMcp?: (input: string) => void;
  onRemoveMcp?: (id: string) => void;
  /** Deploy stage (#919): persist the edited deployment config. */
  onDeployChange?: (next: DeployConfig) => void;
  /** Inject a prompt into the live planner terminal (#1986) — threaded to the Source body so the
   *  "+ Add a source" affordance nudges the planner to author the connector. Same seam as the
   *  per-stage "?" prompt helper (`sendPrompt` in Planning.tsx). */
  onInject?: (text: string) => void;
}) {
  // Context file viewer modal — its scrim (ModalScrim) owns Escape + backdrop dismiss.
  const [viewing, setViewing] = useState<ContextFile | null>(null);
  // The stage-guidance disclosure (#3257) — the gate detail + Inject button are HIDDEN by default and
  // revealed by clicking the gate pill. Stored as WHICH stage's gate is open, so navigating to another
  // stage auto-collapses (derived, no reset effect); `null` ⇒ none open.
  const [openGateIdx, setOpenGateIdx] = useState<number | null>(null);

  // The context-file viewer modal — shared by BOTH the focused and full-pane renders so
  // clicking an md file opens it in either (the focused pane previously had no viewer, #…).
  const viewerModal = viewing && (
    <ModalScrim onDismiss={() => setViewing(null)} style={{ padding: 24 }}>
      <Stack style={{
        width: "min(720px, 92vw)", maxHeight: "84vh",
        background: "var(--bg-panel)", border: "1px solid var(--border-soft)",
        borderRadius: 10, boxShadow: "0 16px 50px rgba(0,0,0,.45)", overflow: "hidden",
      }}>
        <Row gap={8} style={{
          padding: "12px 14px",
          borderBottom: "1px solid var(--border-soft)", background: "var(--bg-elev)",
        }}>
          <KindDot kind={viewing.kind} />
          <Text as="span" mono size={12} style={{ flex: 1, color: "var(--fg)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{viewing.name}</Text>
          <Text as="span" mono size={9.5} tone="dim">{viewing.tok} · {viewing.scope}</Text>
          <Text as="span" mono onClick={() => setViewing(null)} size={13} tone="muted" style={{ cursor: "pointer", padding: "0 2px 0 8px" }}>✕</Text>
        </Row>
        <pre className="mono" style={{
          margin: 0, padding: "14px 16px", overflow: "auto", flex: 1,
          fontSize: 11, lineHeight: 1.55, color: "var(--fg-muted)",
          whiteSpace: "pre-wrap", wordBreak: "break-word",
        }}>{viewing.content || "(empty)"}</pre>
      </Stack>
    </ModalScrim>
  );

  // Focused mode: sequenced-rail one-stage view (#652)
  if (focus) {
    const selected = focus.stages[focus.selectedIdx];
    const active   = focus.stages[focus.activeIdx];
    const isLocked = focus.selectedIdx > focus.activeIdx;
    // The gate pill toggles the guidance card ONLY when there's guidance to reveal (#3257); otherwise it
    // stays a plain status chip. Open iff THIS stage is the open one (auto-collapses on stage change).
    const canToggleGate = hasStageGuidance(selected, focus.pill, focus.promptHelp?.prompt, focus.promptHelp?.onInject);
    const gateOpen = openGateIdx === focus.selectedIdx;
    return (
      <Pane mode="inline" bare className="pp fp">
        <FocusedStepper stages={focus.stages} selectedIdx={focus.selectedIdx} onSelect={focus.onSelect} />
        <FocusedStageHeader stage={selected} pill={focus.pill} open={gateOpen} onToggleGate={canToggleGate ? () => setOpenGateIdx(gateOpen ? null : focus.selectedIdx) : undefined} />
        {isLocked && <FocusedLockBanner activeName={active?.name ?? ""} />}
        <FocusedStageGuidance stage={selected} pill={focus.pill} prompt={focus.promptHelp?.prompt} onInject={focus.promptHelp?.onInject} open={gateOpen} />
        <Box className="pp-scroll">
          <FocusedStageBody stage={selected} data={data} projectId={projectId} onLinkRepo={onLinkRepo} onView={setViewing}
            onFlow={onFlow} onModel={onModel} onPersona={onPersona} onTopology={onTopology} onDirectorDrive={onDirectorDrive}
            onToggleMcp={onToggleMcp} onBuildMcp={onBuildMcp} onAddMcp={onAddMcp} onRemoveMcp={onRemoveMcp} onDeployChange={onDeployChange} requiredContext={focus.requiredContext} onInject={onInject} />
        </Box>
        <FocusedStageFooter stage={selected} action={focus.footer} published={focus.published} publishLabel={focus.publishLabel} onBack={focus.onBack} onPrimary={focus.onPrimary} onSkip={focus.onSkip} />
        {viewerModal}
      </Pane>
    );
  }

  return null;
}

// projectPane.types -- the shared render-shape contract for the planning right
// pane (ProjectPane v2, #356). One source of truth for the data shapes the pane
// renders, so the section sub-issues (#337/#341/#343/#352/#349/...) build on the
// same types instead of redefining them. Pure type module (no React / Tauri),
// imported by both ProjectPane.tsx (the view) and projectPaneData.ts (the adapter
// that maps the real plan store into these shapes); projectPaneData re-exports
// them for back-compat with existing import sites.

import type { DirectorDrive } from "../fleet/directorDrive";
import type { IntegrationStrategy } from "../lib/integrationStrategy";
import type { ModelId } from "@/app/console/lib/models";
import type { PlanFeature } from "../issues/featureList";
import type { DeployConfig } from "../lib/deployConfig";
import type { PlanDependency, DependencyRegistry } from "../issues/dependencies";
import type { Topology, RelationshipArtifact, AgentRelationship } from "../relationship/relationshipGraph";

export type Posture = "allow" | "ask" | "deny";
export type Perm = Record<string, Posture>;
export interface Flow { autonomy: string; push: string; gate: string }

/** An MCP server as the planning page's MCP pane renders it (#878) — the project's MCP
 *  extensions joined with catalog metadata and on-disk install state. A project-scoped
 *  enabled server reaches the whole fleet (director + every worker) via the launch wiring,
 *  so `scope` describes that reach and `agents` lists the fleet ids it's granted to. */
export interface McpServer {
  /** Extension id (stable key for toggle/build/remove). */
  id: string;
  name: string;
  transport: "stdio" | "http";
  /** The launch command (stdio: `command args`) or remote URL (http). */
  cmd: string;
  /** One-line description from the catalog, or "" for a custom server. */
  desc: string;
  enabled: boolean;
  /** Built by the @modelcontextprotocol org (vs. a first-party or custom server). */
  official: boolean;
  /** A downloadable first-party server (installs from source); drives download/build. */
  downloadable: boolean;
  /** Resolved install lifecycle for a downloadable server (else "n/a"):
   *  not-downloaded → "available", downloaded-not-built → "downloaded",
   *  built → "ready", a failed build → "error". A remote/built-in server is "ready". */
  status: "available" | "downloaded" | "ready" | "error" | "building" | "downloading";
  /** Human scope label: "fleet" (director + all workers) or "—" when not yet wired. */
  scope: string;
  /** Fleet agent ids this server is granted to (the whole fleet for a project server). */
  agents: string[];
  /** Tools the server exposes, if known (discovered at launch; usually empty pre-run). */
  tools: string[];
  /** Why the build failed, when `status === "error"`. */
  err?: string;
}

export interface Agent {
  id: string;
  name: string;
  role: string;
  status: string;
  repo: string;
  color: string;
  initial: string;
  owns: string[];
  issues: string[];
  focus?: boolean;
  preset: string;
  perm: Perm;
  flow: Flow;
  /** Per-agent LLM model override (#…); undefined ⇒ inherits the global `defaultModel`. */
  model?: ModelId;
  /** The persona this stream launches as (#2094) — its id; drives role/prompt/skills/model at launch. */
  persona?: string;
  /** Per-stream integration-strategy override (#378); undefined ⇒ inherits the fleet default. */
  strategy?: IntegrationStrategy;
  ctx: number;
  /** #2053 kickoff preview — the exact first message this worker receives at launch (the generated
   *  `buildStreamPrompt`), so the user can SEE it before launching. When `authoredPrompt` is set the
   *  real kickoff is that doc instead; this stays the generated fallback for reference. */
  kickoff: string;
  /** #2053 — the worker's lane context (`buildWorkerScope`) written as its CLAUDE.local.md lead:
   *  owned globs, issues, contract dependencies. Shown collapsed under the kickoff. */
  scope: string;
  /** #2053 — the relpath of a planner-AUTHORED kickoff doc (`stream.prompt`), when present. Its
   *  content wins over `kickoff` at launch; surfaced so the card can tag "authored · <path>". */
  authoredPrompt?: string;
}

export interface RepoBranch { n: string; issue: number; state: string; ahead: number; behind: number }
export interface Repo {
  id: string;
  branch: string;
  ahead: number;
  behind: number;
  agents: string[];
  primary: boolean;
  branches: RepoBranch[];
  /** Whether the repo has been cloned into the project hub (from the clone state). */
  cloned?: boolean;
  /** GitHub repo metadata, when known (absent during planning). */
  lang?: string;
  desc?: string;
}

export interface SubItem { t: string; done: boolean }
export interface Issue {
  n: number | string;
  t: string;
  state: string;
  owner: string;
  ac: number;
  branch: string;
  deps: (number | string)[];
  sub: SubItem[];
  /** Owning repo (`owner/name`). Optional for back-compat with the repo-first shape. */
  repo?: string;
}
export interface Epic { id: string; title: string; pct: number; issues: Issue[] }
export interface Milestone { id: string; title: string; repo: string; pct: number; state: string; epics: Epic[] }

export interface ContextFile { name: string; kind: string; tok: string; pinned: boolean; scope: string; content: string }

export interface PaneAutomation { name: string; command: string; schedule?: string }
export interface PaneSkill { name: string; kind: "skill" | "kb"; desc?: string; /** Authored by the current planning session (#1056) — rendered first + highlighted. */ isNew?: boolean }

export interface ProjectPaneData {
  agents: Agent[];
  repos: Repo[];
  /** Repo-first structure (repo → milestone → epic → issue). */
  structure: Milestone[];
  context: ContextFile[];
  /** The async-integrator director config (#366), surfaced for the planning UI. */
  director: { enabled: boolean; role?: string; drive: DirectorDrive };
  /** Project-default integration strategy (#378); undefined ⇒ DEFAULT_STRATEGY. */
  fleetStrategy?: IntegrationStrategy;
  /** Cron automations the planner has proposed for this project (#674). */
  automations?: PaneAutomation[];
  /** Reusable skills/knowledge attached to the project's blueprint (#674). */
  skills?: PaneSkill[];
  /** MCP servers configured for this project (#878) — rendered in the MCP stage. */
  mcpServers?: McpServer[];
  /** User-facing capabilities defined in the Features stage (#…); each is a fleet stream. */
  features?: PlanFeature[];
  /** The deployment & infrastructure config (#919) — the Deploy stage pane's editable state. */
  deploy?: DeployConfig;
  /** The locked dependency manifest (#1127/#1133) — authored in the Deploy stage; surfaced in the
   *  Deploy pane so the user sees the libraries each repo depends on and where they're sourced. */
  dependencies?: PlanDependency[];
  /** Non-default registries the dependencies are fetched from (#1133), keyed by `source`. */
  registries?: Record<string, DependencyRegistry>;
  /** Agent-coordination topology (#…) — the effective director/peer/hybrid mode, the
   *  Permissions stage configures it and the Structure graph reflects it. */
  topology?: Topology;
  /** Declared produced artifacts (schemas/contracts) one stream hands to others. */
  relationshipArtifacts?: RelationshipArtifact[];
  /** Typed relationship edges between streams — the Structure relationship graph. */
  relationships?: AgentRelationship[];
}

// projectPaneAgents -- maps fleet streams + agent profiles + flows into the
// ProjectPane `Agent` cards (posture, kickoff preview, lane scope). Extracted from
// projectPaneData (#2151); pure, no logic changes.

import type { Tier, ToolKey } from "@/features/security";
import { resolveFlow } from "../fleet/agentFlow";
import { resolveStrategy } from "../lib/integrationStrategy";
import { depsForRepo } from "../issues/dependencies";
import { buildWorkerScope } from "../fleet/workerScope";
import { buildStreamPrompt } from "@/store/helpers";
import { resolveStreamPersona, personaStreamPrompt } from "../fleet/streamPersona";
import type { AgentProfile } from "@/features/security";
import type { Posture, Perm, Agent } from "./projectPane.types";
import type { BuildProjectPaneInput } from "./projectPaneInput";

const AGENT_HUES = [230, 70, 50, 145, 195, 300, 350, 110, 20, 260];
function agentColor(index: number): string {
  const hue = AGENT_HUES[index % AGENT_HUES.length];
  return "oklch(0.74 0.13 " + hue + ")";
}

function initialFor(id: string): string {
  const m = id.match(/[a-z0-9]/i);
  return m ? m[0].toUpperCase() : "?";
}

function mapPush(push: string): string {
  return push === "auto-pr" ? "auto-PR" : push;
}

const DEFAULT_PERM: Perm = {
  read: "allow", edit: "ask", create: "ask", run: "ask", net: "deny", push: "ask", pkg: "deny",
};

function derivePerm(profile: AgentProfile | undefined, push: string): Perm {
  const tier = (k: ToolKey, fallback: Posture): Posture =>
    (profile?.tools?.[k] as Tier | undefined) ?? fallback;
  const pushPosture: Posture =
    push === "none" ? "deny" :
    push === "auto-pr" ? "allow" :
    "ask";
  if (!profile) {
    return { ...DEFAULT_PERM, push: pushPosture };
  }
  const net: Posture = profile.net.allow.length > 0 ? "allow"
    : (profile.tools?.web as Tier | undefined) ?? "deny";
  return {
    read:   tier("read", "ask"),
    edit:   tier("edit", "ask"),
    create: tier("write", "ask"),
    run:    tier("bash", "ask"),
    net,
    push:   pushPosture,
    pkg:    "deny",
  };
}

export function buildAgents(input: BuildProjectPaneInput): Agent[] {
  const streams = input.fleet?.streams ?? [];
  return streams.map((s, i) => {
    // The worker's posture is its ROLE's profile (Autonomous trusted), shown read-only — no
    // per-stream perm/preset overrides anymore. An explicit `s.profile` override still resolves.
    const profile = input.profiles.find(p => p.id === (s.profile ?? "pf_auto"));
    const flow = resolveFlow(s.flow);
    // #2053: compute the exact kickoff + lane context this stream will launch with, so the card can
    // preview them (pure — the same builders fleetStartProject / write_worker_context use).
    const strategy = resolveStrategy(s.strategy, input.fleet?.strategy);
    const scope = buildWorkerScope(s, depsForRepo(input.dependencies ?? [], s.repo), false, input.uiPairing);
    // #2094: a stream may launch AS a persona — its role + persona-identity kickoff drive the row +
    // preview (matching fleetStartProject). No persona ⇒ the plain worker role + kickoff.
    const persona = resolveStreamPersona(input.personas ?? [], s);
    return {
      id: s.id,
      name: s.name.startsWith("@") ? s.name : "@" + s.id,
      role: persona?.role ?? "worker",
      status: "idle",
      repo: s.repo,
      color: agentColor(i),
      initial: initialFor(s.id),
      owns: s.owns,
      issues: s.issues,
      preset: profile ? profile.name : "Autonomous (trusted)",
      perm: derivePerm(profile, flow.push),
      flow: { autonomy: flow.autonomy, push: mapPush(flow.push), gate: flow.gate },
      model: s.model,
      persona: s.persona,
      strategy: s.strategy,
      ctx: s.owns.length,
      kickoff: persona ? personaStreamPrompt(persona, s, strategy) : buildStreamPrompt(s, strategy),
      scope,
      authoredPrompt: s.prompt,
    };
  });
}

runtime.features/planner/pane/projectPaneContext:
// projectPaneContext -- maps the project's plan section files into the ProjectPane
// `ContextFile` cards (kind, token size, pinned state). Extracted from
// projectPaneData (#2151); pure, no logic changes.

import type { ContextFile } from "./projectPane.types";
import type { BuildProjectPaneInput } from "./projectPaneInput";

export function buildContext(input: BuildProjectPaneInput): ContextFile[] {
  // When the project has an explicit pinned set (user toggles in the pane),
  // it drives `pinned`; otherwise fall back to the confirmed-section default.
  const explicitPins = input.pinned ? new Set(input.pinned) : undefined;
  // Skip empty section files — a created-but-unwritten section would otherwise show as a
  // ghost 0.0k context file (#654). Also skip the deprecated `issues` / `issues-phase<n>`
  // sections: issues are no longer an authored plan file — they're generated from the feature
  // DAG at GitHub-publish time (#plan-db), so a stale (often near-empty) issues section must
  // not resurface as a ghost context card.
  return input.sections.filter(s =>
    s.content.trim().length > 0 && s.k !== "issues" && !s.k.startsWith("issues-phase"),
  ).map(s => {
    const kind = s.k === "claude" ? "claude"
      : s.k.includes("spec") ? "spec"
      : "doc";
    const tok = (s.content.length / 1000).toFixed(1) + "k";
    // The displayed filename is the canonical KEY (+ .md) so it matches the on-disk file
    // (`stack.md`), not the human title ("Tech stack.md") which would mislead (#803). The
    // global project guidance file is the uppercase `CLAUDE.md` on disk.
    const name = s.k === "claude" ? "CLAUDE.md" : s.k + ".md";
    return {
      name,
      kind,
      tok,
      pinned: explicitPins ? explicitPins.has(name) : s.state === "confirmed",
      scope: "project",
      content: s.content,
    };
  });
}

runtime.features/planner/pane/projectPaneData.ts:
// projectPaneData -- maps the real plan store (fleet streams, agent profiles,
// decomposed issues, sections, linked repos) into the shapes the
// ProjectPane (v2) renders. Pure (no React / Tauri) so the mapping is unit-testable,
// keeping the pane a dumb view. ProjectPane re-imports these interfaces, so this
// module is the single source of truth for the pane data contract; the pane
// falls back to its own sample consts when a project has none of this yet.
//
// The per-domain mapping steps live in colocated sibling modules (#2151):
//   projectPaneAgents / projectPaneRepos / projectPaneStructure /
//   projectPaneContext / projectPaneRelationships. This file is the thin
//   composition that calls them and owns the public data contract.

import { resolveDirectorDrive } from "../fleet/directorDrive";
import { buildMcpServers } from "../lib/mcpPaneData";

// The render-shape contract lives in projectPane.types (#356, the shared pane
// types). This adapter re-exports those shapes so existing import sites that reach
// for them via "./projectPaneData" keep working.
import type { ProjectPaneData } from "./projectPane.types";
import type { BuildProjectPaneInput } from "./projectPaneInput";

import { buildAgents } from "./projectPaneAgents";
import { buildRepos } from "./projectPaneRepos";
import { buildStructure } from "./projectPaneStructure";
import { buildContext } from "./projectPaneContext";
import { effectiveStreams, deriveRelationships } from "./projectPaneRelationships";

export type { BuildProjectPaneInput } from "./projectPaneInput";
export type {
  Posture, Perm, Flow, Agent, RepoBranch, Repo, SubItem, Issue, Epic, Milestone,
  ContextFile, ProjectPaneData, PaneAutomation, PaneSkill, McpServer,
} from "./projectPane.types";

/**
 * Build the ProjectPane render data from the real plan store. Robust to missing
 * pieces: no fleet -> no agents and no repo->agent links; no issues -> empty
 * structure; no sections -> empty context. The pane treats an all-empty result as
 * a signal to fall back to its illustrative sample data.
 */
export function buildProjectPaneData(input: BuildProjectPaneInput): ProjectPaneData {
  return {
    agents: buildAgents(input),
    repos: buildRepos(input),
    structure: buildStructure(input),
    context: buildContext(input),
    director: {
      enabled: input.fleet?.director.enabled ?? false,
      role: input.fleet?.director.role,
      drive: resolveDirectorDrive(input.directorDriveOverride ?? input.fleet?.director.drive),
    },
    fleetStrategy: input.fleet?.strategy,
    automations: (input.automations ?? []).map(a => ({ name: a.name, command: a.command, schedule: a.schedule })),
    skills: input.skills ?? [],
    mcpServers: buildMcpServers(input.mcpServers ?? [], input.projectKey ?? "", input.fleet, input.mcpInstallState),
    features: input.features ?? [],
    deploy: input.deployConfig,
    dependencies: input.dependencies ?? [],
    registries: input.registries ?? {},
    // Coordination topology: the user's per-project override wins over the planner's
    // fleet.json default, falling back to hybrid (#…).
    topology: input.topologyOverride ?? input.fleet?.topology ?? "hybrid",
    relationshipArtifacts: input.fleet?.artifacts ?? [],
    // Use the planner's explicit typed edges when present; otherwise DERIVE them so the
    // graph shows for any planned fleet. The derivation aggregates the granular ISSUE
    // dependency tree (issues.json — the same data the seam graph uses) up to the stream
    // level, so the relationship graph has the same dependency depth (and thus phase
    // layers) as the seam graph, plus any explicit stream-level `dependsOn` (#…).
    relationships: input.fleet?.edges?.length
      ? input.fleet.edges
      : deriveRelationships(effectiveStreams(input), input.issues),
  };
}

runtime.features/planner/pane/projectPaneInput.t:
// projectPaneInput -- the input contract for the ProjectPane data adapter. Lives
// in its own module so the per-domain mapping helpers (projectPaneAgents/Repos/
// Structure/Context/Relationships) and the thin projectPaneData composition can
// all share it without a circular import back through projectPaneData.

import type { AgentProfile } from "@/features/security";
import type { FleetPlan } from "../fleet/planFleet";
import type { PlanIssue } from "../issues/planIssues";
import type { Section } from "../github/ghStructure";
import type { NodeProgress } from "../github/ghProgress";
import type { PaneAutomation, PaneSkill } from "./projectPane.types";
import type { PlanFeature } from "../issues/featureList";
import type { DeployConfig } from "../lib/deployConfig";
import type { PlanDependency, DependencyRegistry } from "../issues/dependencies";
import type { McpInstallState } from "../lib/mcpPaneData";
import type { McpServer as McpServerDef } from "@/features/mcp";

export interface BuildProjectPaneInput {
  fleet?: FleetPlan;
  profiles: AgentProfile[];
  /** The persona library (#2094) — resolves a stream's `persona` reference to its role/kickoff/model
   *  for the agent projection (the row's role + kickoff preview). */
  personas?: import("@/features/personas").Persona[];
  issues: PlanIssue[];
  repos: string[];
  /** Full_names cloned into the project hub (clone state) — drives each repo's `cloned`. */
  clonedNames?: string[];
  /** Cron automations proposed for the project (#674). */
  automations?: PaneAutomation[];
  /** Skills/knowledge attached to the project's blueprint, pre-resolved (#674). */
  skills?: PaneSkill[];
  /** The full MCP-servers store + the project key, to build the MCP pane (#878). */
  mcpServers?: McpServerDef[];
  projectKey?: string;
  /** Per-server install lifecycle (probe + build button), keyed by extension id (#878). */
  mcpInstallState?: McpInstallState;
  /** Features defined in the Features stage (parsed from features.json) (#…). */
  features?: PlanFeature[];
  /** Per-project coordination-topology override (#…) — set in the Permissions pane,
   *  wins over the planner's `fleet.json` topology. */
  topologyOverride?: import("../relationship/relationshipGraph").Topology;
  /** Per-project director-drive override (#…) — set in the Permissions pane, wins over
   *  `fleet.json`'s `director.drive`. */
  directorDriveOverride?: import("../fleet/directorDrive").DirectorDrive;
  /** The project's deployment & infrastructure config (#919) — the Deploy stage pane's state. */
  deployConfig?: DeployConfig;
  /** The locked dependency manifest (#1127/#1133) — surfaced in the Deploy pane. */
  dependencies?: PlanDependency[];
  registries?: Record<string, DependencyRegistry>;
  /** The project's {kit, theme} pairing (#2489) — inlined into each agent card's scope preview as
   *  the UI-palette lock block, matching what the launch path builds. */
  uiPairing?: import("../fleet/workerScope").WorkerUiPairing;
  sections: Section[];
  /** Context-file names the project has explicitly pinned in the pane (from the
   *  store). When present it drives each context file's `pinned` instead of the
   *  confirmed-section default. */
  pinned?: string[];
  /** Live GitHub issue-progression overlay (#393 Layer 2), keyed by structure node
   *  id (`issue:{repo}:{ref}`). When present it drives each issue's done-state and
   *  the milestone/epic percentages — reflecting what is actually CLOSED on GitHub
   *  — falling back to the static done/closed label when a node has no live data
   *  (#429). The same overlay the GitHubStructureCard renders, built by
   *  {@link buildProgressOverlay}. */
  progress?: Record<string, NodeProgress>;
}

runtime.features/planner/pane/projectPaneRelatio:
// projectPaneRelationships -- derives the cross-stream relationship graph for the
// ProjectPane: the streams to render (authored fleet, else feature-derived) and the
// blocking edges aggregated from the issue dependency tree. Extracted from
// projectPaneData (#2151); pure, no logic changes.

import type { AgentStream } from "../fleet/planFleet";
import type { AgentRelationship } from "../relationship/relationshipGraph";
import type { PlanIssue } from "../issues/planIssues";
import type { BuildProjectPaneInput } from "./projectPaneInput";

/**
 * The streams to render the relationship graph from: the authored fleet when it exists, otherwise
 * derived straight from the features (#plan-db). A feature IS a stream — slug = id, `dependsOn` =
 * the edges — so the stream graph shows in the Structure pane as soon as features are defined,
 * instead of staying blank until the Permissions stage authors `fleet.json`.
 */
export function effectiveStreams(input: BuildProjectPaneInput): AgentStream[] {
  if (input.fleet?.streams?.length) return input.fleet.streams;
  return (input.features ?? []).map((f) => ({
    id: f.slug,
    name: f.name || f.slug,
    repo: input.repos[0] ?? "",
    owns: [],
    issues: [],
    dependsOn: f.dependsOn ?? [],
  }));
}

/**
 * Derive cross-stream blocking edges. A dependency between two ISSUES owned by different
 * streams (issue I in stream A `dependsOn` issue J in stream B) becomes a stream edge B→A.
 * This captures the full dependency structure the seam graph shows, aggregated to streams —
 * so the swimlane layers (its "phases") match. Explicit stream-level `dependsOn` is merged in.
 */
export function deriveRelationships(streams: AgentStream[], issues: PlanIssue[]): AgentRelationship[] {
  const streamIds = new Set(streams.map((s) => s.id));
  const norm = (r: string) => String(r).replace(/^#/, "").trim();
  // issue ref → owning stream id (the stream's declared issue list, then PlanIssue.stream).
  const ownerOf = new Map<string, string>();
  for (const s of streams) for (const ref of s.issues ?? []) ownerOf.set(norm(ref), s.id);
  for (const i of issues) if (i.stream && streamIds.has(i.stream)) ownerOf.set(norm(i.ref), i.stream);

  const seen = new Set<string>();
  const out: AgentRelationship[] = [];
  const add = (from: string | undefined, to: string) => {
    if (!from || !streamIds.has(from) || !streamIds.has(to) || from === to) return;
    const key = `${from}>${to}`;
    if (seen.has(key)) return;
    seen.add(key);
    out.push({ id: key, from, to, kind: "blocking", hardness: "blocking", via: "direct" });
  };
  // cross-stream edges from the issue dependency tree
  for (const i of issues) {
    const to = ownerOf.get(norm(i.ref));
    if (!to) continue;
    for (const dep of i.dependsOn ?? []) add(ownerOf.get(norm(dep)), to);
  }
  // plus any explicit stream-level dependsOn
  for (const s of streams) for (const dep of s.dependsOn ?? []) add(norm(dep), s.id);
  return out;
}

runtime.features/planner/pane/projectPaneRepos.t:
// projectPaneRepos -- maps the linked-repo list + fleet streams into the
// ProjectPane `Repo` cards (clone state, per-stream planned branches). Extracted
// from projectPaneData (#2151); pure, no logic changes.

import type { Repo } from "./projectPane.types";
import type { BuildProjectPaneInput } from "./projectPaneInput";

export function buildRepos(input: BuildProjectPaneInput): Repo[] {
  const streams = input.fleet?.streams ?? [];
  const cloned = new Set(input.clonedNames ?? []);
  const firstIssueNum = (refs: string[]): number => {
    for (const r of refs) { const n = parseInt(String(r).replace(/^#/, ""), 10); if (Number.isFinite(n)) return n; }
    return 0;
  };
  return input.repos.map((fullName, i) => ({
    id: fullName,
    branch: "main",
    ahead: 0,
    behind: 0,
    agents: streams.filter(s => s.repo === fullName).map(s => s.id),
    primary: i === 0,
    cloned: cloned.has(fullName),
    // The planned work for this repo: one branch per stream that owns it (branch = stream
    // id; the issues it owns ride along). Pre-launch these are PLANNED branches; once the
    // fleet runs the live git state replaces them.
    branches: streams.filter(s => s.repo === fullName).map(s => ({
      n: s.id, issue: firstIssueNum(s.issues ?? []), state: "draft", ahead: 0, behind: 0,
    })),
  }));
}

runtime.features/planner/pane/projectPaneStructu:
// projectPaneStructure -- maps decomposed plan issues (+ the live GitHub progress
// overlay) into the ProjectPane repo-first `Milestone` structure. Extracted from
// projectPaneData (#2151); pure, no logic changes.

import type { PlanIssue } from "../issues/planIssues";
import type { Issue, Milestone } from "./projectPane.types";
import type { BuildProjectPaneInput } from "./projectPaneInput";

/** Shared issue derivation for the repo-first structure builder: how an issue
 *  attributes to a repo, whether it's closed (live overlay → static label
 *  fallback), the render shape, and a closed-fraction helper. */
function issueHelpers(input: BuildProjectPaneInput) {
  const { repos, progress } = input;
  const firstAgent = input.fleet?.streams[0]?.id ?? "";
  // Attribute each issue to a repo: its explicit `repo`, else the first publish repo.
  const fallbackRepo = repos[0] ?? "";
  const repoOf = (p: PlanIssue): string => p.repo || fallbackRepo;

  // An issue is done when the live GitHub overlay (#393 Layer 2) marks its
  // structure node closed, falling back to a static done/closed label on the plan
  // issue (#429). The node id mirrors buildGhStructure: `issue:{repo}:{ref}`.
  const staticClosed = (p: PlanIssue): boolean =>
    p.labels.some(l => /^(done|closed)$/i.test(l));
  const issueClosed = (p: PlanIssue): boolean =>
    progress?.[`issue:${repoOf(p)}:${p.ref}`]?.done ?? staticClosed(p);
  const toIssue = (p: PlanIssue): Issue => ({
    n: p.ref,
    t: p.title,
    state: issueClosed(p) ? "done" : "backlog",
    owner: p.stream || firstAgent || "",
    ac: p.acceptance.length,
    branch: p.ref,
    deps: p.dependsOn,
    // Acceptance sub-items: when the live overlay marks the issue closed, treat
    // every acceptance criterion as met so the drill-in checklist agrees with the
    // issue's done state; otherwise leave them open (the overlay tracks per-issue,
    // not per-criterion, state).
    sub: p.acceptance.map(a => ({ t: a, done: issueClosed(p) })),
    repo: repoOf(p),
  });
  const pct = (group: PlanIssue[]): number =>
    group.length ? group.filter(issueClosed).length / group.length : 0;
  return { repoOf, issueClosed, toIssue, pct };
}

/**
 * Repo-first structure (#497, #1912): one milestone per repo carrying every issue
 * that attributes to it (its `repo`, or the default repo when unset), with a single
 * closed/total/pct rollup. Milestone phases were removed (#1912), so issues are no
 * longer grouped by roadmap phase — just by repo.
 */
export function buildStructure(input: BuildProjectPaneInput): Milestone[] {
  const { issues, repos } = input;
  if (issues.length === 0) return [];
  const { repoOf, toIssue, pct } = issueHelpers(input);

  const repoOrder: string[] = [...repos];
  for (const p of issues) {
    const r = repoOf(p);
    if (!repoOrder.includes(r)) repoOrder.push(r);
  }

  const out: Milestone[] = [];
  for (const repo of repoOrder) {
    const repoIssues = issues.filter(p => repoOf(p) === repo);
    if (repoIssues.length === 0) continue;
    const fraction = pct(repoIssues);
    out.push({
      id: `${repo}#M1`,
      title: "Issues",
      repo,
      pct: fraction,
      state: "doing",
      epics: [{ id: `${repo}#E1`, title: "Issues", pct: fraction, issues: repoIssues.map(toIssue) }],
    });
  }
  return out;
}

runtime.features/planner/preview/claudeDesignBri:
// Claude Design brief (#634). Once the UI stage has defined its screens, the planner
// hands the user a kickoff prompt to paste into Claude Design: it asks for polished,
// drop-in components for each screen and tells the user to export them back into the
// file-intake stage, where the planner routes them to the UI repo. Pure + testable.

export interface DesignBriefOpts { projectName?: string; stack?: string }

/** Build the Claude Design kickoff prompt for a set of declared screens. */
export function buildClaudeDesignBrief(screens: string[], opts: DesignBriefOpts = {}): string {
  const list = screens.length
    ? screens.map((s) => `- **${s}**`).join("\n")
    : "- (no screens defined yet — define them in the UI stage first)";
  const project = opts.projectName ? ` for ${opts.projectName}` : "";
  const stackLine = opts.stack ? `\nTarget stack: **${opts.stack}** — build components that fit it.` : "";
  return `# Design brief${project}

Design these screens as polished, production-ready UI components:

${list}
${stackLine}

## Guidelines
- A clean, modern aesthetic — consistent spacing, a clear type scale, and reusable color tokens.
- Cover each screen's states: **default, empty, loading, error**.
- Build each screen as a **self-contained component (one file per screen)** so it can drop straight into the codebase.
- Note the responsive behavior and the key interactions for each screen.

## When you're done
Export each screen's code/assets and **drag them into the planner's "Drop files" stage** — the planner will route them into the UI repo for you.`;
}

runtime.features/planner/preview/previewBundle.t:
// Preview transport (#528/#530): bundle a UI skeleton (in-memory files) with
// esbuild-wasm and produce the srcdoc for a sandboxed iframe. React/three are kept
// external and resolved in the iframe via an esm.sh import-map (the chosen approach).
//
// The esbuild call is isolated; the path resolution, bootstrap, and srcdoc assembly
// are pure so they're unit-testable without the wasm runtime.

// Type-only import — the esbuild-wasm runtime is dynamically imported in
// ensureEsbuild() so the module's load-time invariant (which fails under jsdom)
// never runs in tests, and the pure helpers below stay importable.
import type * as Esbuild from "esbuild-wasm";
import wasmURL from "esbuild-wasm/esbuild.wasm?url";
import importmapEmbedded from "@data/ui/preview-importmap.json";
import { PREVIEW_SHIM_NAMESPACE, shimModuleFor, scanStubImports, previewCspMeta } from "@/shared/lib/preview/previewShims";

/** esm.sh import-map for the externals (pinned; `deps` params keep React deduped) — the pins live in
 *  `@data/ui/preview-importmap.json` (#2419; ONE source, also read by streamingRuntime.ts), a plain
 *  embedded import like its `@data/ui/*` neighbors. */
export const DEFAULT_IMPORTMAP: Record<string, string> = importmapEmbedded;

/** Bare specifiers left external — resolved in the iframe by the import-map (derived from its keys
 *  so the two can never drift). */
export const PREVIEW_EXTERNALS = Object.keys(DEFAULT_IMPORTMAP);

const BOOTSTRAP_ENTRY = "__preview_bootstrap__.jsx";

/** The synthetic entry that mounts the skeleton's screen component into #root. */
export function bootstrapSource(screenEntry: string): string {
  const spec = screenEntry.startsWith(".") ? screenEntry : `./${screenEntry}`;
  return `import { createRoot } from "react-dom/client";\nimport Screen from "${spec}";\ncreateRoot(document.getElementById("root")).render(<Screen />);\n`;
}

/** Resolve a relative import against its importer's directory. Pure. */
export function resolveMemPath(importer: string, spec: string): string {
  const fromDir = importer.includes("/") ? importer.slice(0, importer.lastIndexOf("/")) : "";
  const parts = (fromDir ? fromDir.split("/") : []).concat(spec.split("/"));
  const out: string[] = [];
  for (const p of parts) {
    if (p === "" || p === ".") continue;
    if (p === "..") out.pop();
    else out.push(p);
  }
  return out.join("/");
}

/** Look up an in-memory file, trying common extensions. Pure. */
export function lookupMem(files: Record<string, string>, path: string): { contents: string; loader: "jsx" | "tsx" } | null {
  for (const ext of ["", ".tsx", ".ts", ".jsx", ".js", "/index.tsx", "/index.jsx"]) {
    const key = path + ext;
    if (files[key] != null) {
      const loader: "jsx" | "tsx" = key.endsWith(".tsx") || key.endsWith(".ts") ? "tsx" : "jsx";
      return { contents: files[key], loader };
    }
  }
  return null;
}

let initPromise: Promise<typeof Esbuild> | null = null;
function ensureEsbuild(): Promise<typeof Esbuild> {
  if (!initPromise) {
    initPromise = import("esbuild-wasm").then(async (m) => {
      await m.initialize({ wasmURL, worker: true });
      return m;
    });
  }
  return initPromise;
}

function inMemoryPlugin(files: Record<string, string>): Esbuild.Plugin {
  const stubExports = scanStubImports(files, (s) => PREVIEW_EXTERNALS.includes(s)); // #3696 — names per stubbed package
  return {
    name: "preview-mem",
    setup(build) {
      build.onResolve({ filter: /.*/ }, (args) => {
        if (args.kind === "entry-point") return { path: BOOTSTRAP_ENTRY, namespace: "mem" };
        if (PREVIEW_EXTERNALS.includes(args.path)) return { path: args.path, external: true };
        if (args.path.startsWith(".")) return { path: resolveMemPath(args.importer, args.path), namespace: "mem" };
        // #3696: any OTHER bare import resolves to a bundled-in LOCAL shim/stub (never esm.sh at large), so a
        // skeleton that pulls in a native/npm package still bundles + renders instead of failing to resolve.
        return { path: args.path, namespace: PREVIEW_SHIM_NAMESPACE };
      });
      build.onLoad({ filter: /.*/, namespace: PREVIEW_SHIM_NAMESPACE }, (args) => ({ contents: shimModuleFor(args.path, stubExports.get(args.path)), loader: "js" }));
      build.onLoad({ filter: /.*/, namespace: "mem" }, (args) => {
        const hit = lookupMem(files, args.path);
        if (!hit) return { errors: [{ text: `preview: module not found: ${args.path}` }] };
        return { contents: hit.contents, loader: hit.loader };
      });
    },
  };
}

/**
 * Bundle a UI skeleton into a single ESM module that mounts `screenEntry` into #root.
 * `files` is relpath → source (the .ui-skeleton folder, in memory). React/three stay
 * external. Throws on a build error (caller surfaces it).
 */
export async function bundleSkeleton(files: Record<string, string>, screenEntry: string): Promise<string> {
  const esbuild = await ensureEsbuild();
  const withBootstrap = { ...files, [BOOTSTRAP_ENTRY]: bootstrapSource(screenEntry) };
  const result = await esbuild.build({
    entryPoints: [BOOTSTRAP_ENTRY],
    bundle: true,
    format: "esm",
    write: false,
    jsx: "automatic",
    logLevel: "silent",
    plugins: [inMemoryPlugin(withBootstrap)],
  });
  return result.outputFiles?.[0]?.text ?? "";
}

/**
 * Assemble the sandboxed-iframe srcdoc: import-map for the externals + the bundle as a
 * module, with error/ready signals posted to the parent. Pure.
 */
export function buildPreviewSrcDoc(bundleJs: string, importmap: Record<string, string> = DEFAULT_IMPORTMAP): string {
  return `<!doctype html><html><head><meta charset="utf-8" />
${previewCspMeta()}
<style>html,body,#root{margin:0;height:100%;background:var(--bg, #0d0d0f);font-family:Inter,system-ui,sans-serif;color:#eee}</style>
<script type="importmap">${JSON.stringify({ imports: importmap })}</script>
</head><body><div id="root"></div>
<script>
  window.addEventListener("error", (e) => parent.postMessage({ __preview: "error", message: String(e.message) }, "*"));
  window.addEventListener("unhandledrejection", (e) => parent.postMessage({ __preview: "error", message: String(e.reason) }, "*"));
</script>
<script type="module">
${bundleJs}
parent.postMessage({ __preview: "ready" }, "*");
</script>
</body></html>`;
}

runtime.features/planner/preview/PreviewPaneShel:
// PreviewPaneShell — the modular, streaming-capable replacement for PlanPreviewPane
// (#581). Routes preview chunks through the renderer registry; the imperative surface
// receives updates directly (zero React re-renders on the hot path). React state is
// limited to { activeKind, rendStatus, briefCopied } — chrome only.
//
// External behavior is identical to PlanPreviewPane: reads stagePreview + run state
// from the store, shows the same approval UI, and uses StageScreenFrame chrome.

import { useState, useEffect, useRef } from 'react';
import { Chip } from "@/shared/ui/data/Chip";
import { Button } from "@/shared/ui/controls/Button";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { invoke } from '@tauri-apps/api/core';
import { safeInvoke } from '@/shared/lib/core/safeInvoke';
import { useAppStore } from '../../../store';
import { StageScreenFrame } from './StageScreenFrame';
import { dispatchRenderPreview, RENDER_PREVIEW_ID } from './renderPreview';
import { buildClaudeDesignBrief } from './claudeDesignBrief';
import { getRenderer } from './registry';
import type { RendererHandle } from './registry';
import type { RenderableChunk, RenderableKind, PreviewStatus } from './types';
import type { StageScreenProps } from './stageScreens';

const EMPTY: string[] = [];

const DEMO_FILES: Record<string, string> = {
  'Demo.jsx':
`export default function Demo() {
  return (
    <div style={{ padding: 40, fontFamily: "Inter, system-ui, sans-serif" }}>
      <h1 style={{ color: "#e0a050", margin: 0 }}>Preview pane</h1>
      <p style={{ color: "#bbb", maxWidth: 460, lineHeight: 1.6 }}>
        The render-preview pipeline bundled this skeleton (esbuild-wasm) and rendered it
        in a sandboxed iframe, pulling React from esm.sh. The UI stage will render your
        generated screens here.
      </p>
    </div>
  );
}`,
};

export function PreviewPaneShell({ projectKey, onClose }: StageScreenProps) {
  const preview = useAppStore((s) => s.stagePreview[projectKey] ?? null);
  const run = useAppStore((s) => s.stageRuns[projectKey]?.[RENDER_PREVIEW_ID]);
  const declared = useAppStore((s) => s.uiScreens[projectKey]) ?? EMPTY;
  const approvedList = useAppStore((s) => s.uiApproved[projectKey]) ?? EMPTY;
  const setUiScreenApproved = useAppStore((s) => s.setUiScreenApproved);

  const stageStatus = run?.status ?? 'idle';
  // React state: chrome-only signals. Imperative surface mutates containerRef directly.
  const [rendStatus, setRendStatus] = useState<PreviewStatus>({ status: 'ready' });
  const [activeKind, setActiveKind] = useState<RenderableKind | null>(null);
  const [briefCopied, setBriefCopied] = useState(false);

  // Imperative surface: the renderer mounts into this div and owns its DOM children.
  const containerRef = useRef<HTMLDivElement>(null);
  const handleRef = useRef<RendererHandle | null>(null);
  // Stable ref so the cleanup effect doesn't capture stale kind state.
  const activeKindRef = useRef<RenderableKind | null>(null);

  // Route new store previews → renderer imperatively.
  // This effect is the ONLY path by which content enters the surface; it never calls
  // setState for the chunk itself, so a high-frequency stream causes zero React renders.
  useEffect(() => {
    if (!preview || !containerRef.current) return;
    const chunk: RenderableChunk = {
      kind: 'react-bundle',
      payload: { srcDoc: preview.srcDoc },
      mode: preview.mode,
      source: preview.screen ?? 'preview',
      final: true,
    };
    const renderer = getRenderer(chunk.kind);
    if (!renderer) return;

    if (handleRef.current && activeKindRef.current === chunk.kind) {
      // Same kind → update the persistent surface in place; no unmount/remount.
      handleRef.current.update(chunk);
    } else {
      // Different kind (or first chunk) → teardown current surface and mount new one.
      handleRef.current?.teardown();
      handleRef.current = renderer.mount(containerRef.current, chunk);
      handleRef.current.onStatus(setRendStatus);
      activeKindRef.current = chunk.kind;
      setActiveKind(chunk.kind); // one React render to show the surface
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [preview]);

  // Teardown on unmount.
  useEffect(() => () => { handleRef.current?.teardown(); }, []);

  const currentScreen = preview?.screen;
  const currentApproved = !!currentScreen && approvedList.includes(currentScreen);
  const approvedCount = declared.filter((s) => approvedList.includes(s)).length;

  const renderDemo = () => void dispatchRenderPreview({
    projectKey, artifacts: DEMO_FILES, entry: 'Demo.jsx', mode: '2d',
  });

  const loadSkeleton = async () => {
    try {
      await safeInvoke('sync_design_to_skeleton', { projectKey }, undefined); // #1373: pull dropped design into the skeleton first
      const files = await invoke<[string, string][]>('read_ui_skeleton', { projectKey });
      if (files.length > 0) {
        await dispatchRenderPreview({
          projectKey, artifacts: Object.fromEntries(files), mode: '2d',
        });
      }
    } catch (_) { /* silently ignore disk errors */ }
  };

  const frameError = rendStatus.status === 'error' ? (rendStatus.message ?? '') : '';
  const statusLabel = stageStatus === 'running' ? 'building…' : frameError ? 'error' : stageStatus;
  const statusColor =
    frameError || stageStatus === 'fail' ? 'var(--danger)'
    : stageStatus === 'ok'               ? 'var(--success)'
    : 'var(--fg-dim)';

  return (
    <StageScreenFrame
      label="preview"
      badge={preview && <Chip style={{ fontSize: 9 }}>{preview.mode}</Chip>}
      statusLabel={statusLabel}
      statusColor={statusColor}
      onClose={onClose}
      actions={
        <>
          {preview && currentScreen && (
            <Button
              size="sm"
              variant={currentApproved ? 'default' : 'ghost'}
              onClick={() => setUiScreenApproved(projectKey, currentScreen, !currentApproved)}
              title={currentApproved ? `${currentScreen} approved — click to revoke` : `Approve ${currentScreen}`}
              style={currentApproved ? { color: 'var(--success)', borderColor: 'var(--success)' } : undefined}
            >
              {currentApproved ? '✓ approved' : 'approve'}
            </Button>
          )}
          {preview && <Button variant="ghost" size="sm" onClick={renderDemo} title="Rebuild">↻</Button>}
        </>
      }
      footer={declared.length > 0 && (
        <Box pad={[8, 12]} style={{ borderTop: '1px solid var(--border-soft)', maxHeight: 180, overflow: 'auto' }}>
          <Row gap={8} style={{ fontFamily: 'var(--mono)', fontSize: 10, color: 'var(--fg-muted)', marginBottom: 6 }}>
            <Text as="span">screens</Text>
            <Button
              variant="ghost"
              size="sm"
              title="Copy a Claude Design prompt for these screens"
              onClick={() => {
                void navigator.clipboard?.writeText(buildClaudeDesignBrief(declared));
                setBriefCopied(true);
                setTimeout(() => setBriefCopied(false), 1600);
              }}
            >{briefCopied ? '✓ copied' : '✦ Claude Design brief'}</Button>
            <Box as="span" style={{ flex: 1 }} />
            <Text as="span" style={{ color: approvedCount === declared.length ? 'var(--success)' : 'var(--fg-dim)' }}>
              {approvedCount}/{declared.length} approved
            </Text>
          </Row>
          <Stack gap={2}>
            {declared.map((s) => {
              const ok = approvedList.includes(s);
              return (
                <Button
                  key={s}
                  variant="ghost"
                  size="sm"
                  onClick={() => setUiScreenApproved(projectKey, s, !ok)}
                  title={ok ? `${s} approved — click to revoke` : `Approve ${s}`}
                  style={{ display: 'flex', alignItems: 'center', gap: 8, justifyContent: 'flex-start', textAlign: 'left', fontFamily: 'var(--mono)', fontSize: 11 }}
                >
                  <Text as="span" style={{ color: ok ? 'var(--success)' : 'var(--fg-dim)' }}>{ok ? '✓' : '○'}</Text>
                  <Text as="span" style={{ color: s === currentScreen ? 'var(--accent)' : 'var(--fg)' }}>{s}</Text>
                </Button>
              );
            })}
          </Stack>
        </Box>
      )}
    >
      <Stack style={{ flex: 1, minHeight: 0 }}>
        {stageStatus === 'fail' ? (
          <Box pad={16} style={{ fontFamily: 'var(--mono)', fontSize: 11, color: 'var(--danger)', whiteSpace: 'pre-wrap', overflow: 'auto' }}>
            {run?.message || 'Preview failed to build.'}
          </Box>
        ) : (
          <>
            {/* Persistent imperative surface — always in the DOM so containerRef is stable.
                Hidden when no renderer is active; the empty-state overlay covers it. */}
            {/* eslint-disable-next-line no-restricted-syntax -- preview renderer mount ref + conditional display */}
            <div
              ref={containerRef}
              style={{ flex: 1, display: activeKind ? 'flex' : 'none', minHeight: 0 }}
            />
            {!activeKind && (
              <Stack gap={12} align="center" justify="center" style={{ flex: 1, padding: 24, textAlign: 'center' }}>
                <Text as="div" size={11.5} tone="muted" mono>
                  {stageStatus === 'running' ? 'Bundling…' : 'No preview yet'}
                </Text>
                <Box className="hint" style={{ maxWidth: 280 }}>
                  The UI stage renders generated screens here via the render-preview pipeline.
                </Box>
                <Row gap={8} align="stretch">
                  <Button onClick={loadSkeleton} disabled={stageStatus === 'running'}>load from skeleton →</Button>
                  <Button variant="ghost" onClick={renderDemo} disabled={stageStatus === 'running'}>demo</Button>
                </Row>
              </Stack>
            )}
          </>
        )}
      </Stack>
    </StageScreenFrame>
  );
}

runtime.features/planner/preview/registry.ts:
// Renderer registry and handle interfaces for the preview feed consumer (#581).
// Each renderer is keyed by one or more RenderableKinds. The registry is module-level
// so renderers self-register on import; the shell calls getRenderer(kind) to dispatch.

import type { RenderableKind, RenderableChunk, PreviewStatus } from './types';

/**
 * An imperative handle to a mounted renderer surface. The shell holds this ref and
 * calls update() for every arriving chunk — zero React re-renders on the hot path.
 */
export interface RendererHandle {
  /** Deliver a new chunk to the surface imperatively (no React setState). */
  update(chunk: RenderableChunk): void;
  /** Subscribe to renderer-reported status changes (called once after mount). */
  onStatus(cb: (s: PreviewStatus) => void): void;
  /** Remove the surface from the container and clean up all listeners. */
  teardown(): void;
}

/**
 * A pluggable renderer: declares the kind(s) it handles, mounts a surface into a
 * container element, and returns a handle for imperative updates.
 */
export interface PreviewRenderer {
  kind: RenderableKind | RenderableKind[];
  mount(container: HTMLElement, initial: RenderableChunk): RendererHandle;
}

const REGISTRY = new Map<RenderableKind, PreviewRenderer>();

/** Register a renderer for its declared kind(s). Last registration wins (idempotent). */
export function registerRenderer(renderer: PreviewRenderer): void {
  const kinds: RenderableKind[] = Array.isArray(renderer.kind) ? renderer.kind : [renderer.kind];
  for (const k of kinds) REGISTRY.set(k, renderer);
}

/** Look up the renderer for a kind. Returns undefined when none is registered. */
export function getRenderer(kind: RenderableKind): PreviewRenderer | undefined {
  return REGISTRY.get(kind);
}

/** True when a renderer is registered for the given kind. */
export function hasRenderer(kind: RenderableKind): boolean {
  return REGISTRY.has(kind);
}

/** Test helper — reset the registry between cases. */
export function _resetRegistry(): void {
  REGISTRY.clear();
}

runtime.features/planner/preview/renderers/canva:
// image / video-frame renderer (#581 PV-canvas).
//
// Blits the newest chunk to a persistent <canvas> element in the container. No iframe
// needed — images are safe host-side. Each update() call draws over the previous frame;
// the canvas stays mounted across updates with zero re-renders.
//
// Payload shape: { dataUrl: string; width?: number; height?: number }
//   dataUrl — a data: URI (JPEG, PNG, WebP, etc.) or an object URL.
//   width / height — optional natural dimensions hint; canvas auto-sizes to the image.

import type { PreviewRenderer, RendererHandle } from '../registry';
import type { RenderableChunk, PreviewStatus } from '../types';
import { registerRenderer } from '../registry';

type CanvasPayload = { dataUrl: string; width?: number; height?: number };

function createCanvasRenderer(): PreviewRenderer {
  return {
    kind: ['image', 'video-frame'],

    mount(container: HTMLElement, initial: RenderableChunk): RendererHandle {
      const canvas = document.createElement('canvas');
      canvas.style.cssText = 'display:block;width:100%;height:100%;object-fit:contain;background:#0d0d0f';
      container.style.cssText = 'display:flex;flex:1;min-height:0';
      container.appendChild(canvas);

      const ctx = canvas.getContext('2d');
      let statusCb: ((s: PreviewStatus) => void) | undefined;

      function blit(chunk: RenderableChunk) {
        const p = chunk.payload as CanvasPayload | null;
        if (!p?.dataUrl || !ctx) return;
        const img = new Image();
        img.onload = () => {
          canvas.width = p.width ?? img.naturalWidth;
          canvas.height = p.height ?? img.naturalHeight;
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
          statusCb?.({ status: 'ready' });
        };
        img.onerror = () => {
          statusCb?.({ status: 'error', message: `failed to load image: ${p.dataUrl.slice(0, 60)}` });
        };
        img.src = p.dataUrl;
      }

      blit(initial);

      const handle: RendererHandle = {
        update: blit,
        onStatus(cb) { statusCb = cb; },
        teardown() {
          if (container.contains(canvas)) container.removeChild(canvas);
        },
      };
      return handle;
    },
  };
}

export const canvasRenderer = createCanvasRenderer();
registerRenderer(canvasRenderer);

runtime.features/planner/preview/renderers/gltfR:
// glTF / scene renderer (#581 PV-gltf).
//
// Mounts a persistent iframe that runs three.js (loaded from esm.sh via import-map)
// and receives glTF data via postMessage. The iframe stays mounted between updates;
// each render_gltf command replaces the previous model without reloading the runtime.
//
// Payload shape: { url?: string; base64?: string }
//   url    — a URL the iframe can fetch (same-origin or CORS-enabled).
//   base64 — raw glTF JSON or binary GLB, base64-encoded.
//            The iframe constructs a data URI: data:model/gltf+json;base64,<base64>.

import type { PreviewRenderer, RendererHandle } from '../registry';
import type { RenderableChunk, PreviewStatus } from '../types';
import { registerRenderer } from '../registry';
import { buildGltfRuntimeHtml } from '../streamingRuntime';

type GltfPayload = { url?: string; base64?: string };

function createGltfRenderer(): PreviewRenderer {
  return {
    kind: ['gltf', 'scene'],

    mount(container: HTMLElement, initial: RenderableChunk): RendererHandle {
      const iframe = document.createElement('iframe');
      iframe.title = 'glTF preview';
      // allow-scripts: run three.js; no host access.
      iframe.setAttribute('sandbox', 'allow-scripts');
      iframe.style.cssText = 'flex:1;width:100%;height:100%;border:none;background:#0d0d0f';
      container.style.cssText = 'display:flex;flex:1;min-height:0';
      container.appendChild(iframe);

      let statusCb: ((s: PreviewStatus) => void) | undefined;
      let runtimeReady = false;
      let pendingChunk: RenderableChunk | null = null;

      // Bootstrap the three.js runtime.
      iframe.srcdoc = buildGltfRuntimeHtml();

      function sendGltf(payload: GltfPayload) {
        iframe.contentWindow?.postMessage(
          { __preview_cmd: 'render_gltf', url: payload.url, base64: payload.base64 },
          '*',
        );
      }

      function onMsg(e: MessageEvent) {
        const d = e.data as { __preview?: string; message?: unknown } | null;
        if (!d || typeof d !== 'object') return;
        if (d.__preview === 'runtime_ready') {
          runtimeReady = true;
          if (pendingChunk) {
            sendGltf(pendingChunk.payload as GltfPayload);
            pendingChunk = null;
          }
        } else if (d.__preview === 'ready') {
          statusCb?.({ status: 'ready' });
        } else if (d.__preview === 'error') {
          statusCb?.({ status: 'error', message: String(d.message ?? '') });
        }
      }
      window.addEventListener('message', onMsg);

      // Apply initial chunk once runtime is ready.
      const initPayload = initial.payload as GltfPayload;
      if (initPayload.url || initPayload.base64) {
        if (runtimeReady) {
          sendGltf(initPayload);
        } else {
          pendingChunk = initial;
        }
      }

      const handle: RendererHandle = {
        update(chunk: RenderableChunk) {
          const p = chunk.payload as GltfPayload;
          if (!runtimeReady) {
            pendingChunk = chunk;
          } else {
            sendGltf(p);
          }
        },
        onStatus(cb) { statusCb = cb; },
        teardown() {
          window.removeEventListener('message', onMsg);
          if (container.contains(iframe)) container.removeChild(iframe);
        },
      };
      return handle;
    },
  };
}

export const gltfRenderer = createGltfRenderer();
registerRenderer(gltfRenderer);

runtime.features/planner/preview/renderers/htmlR:
// html / react-bundle renderer (#581 PV-registry + PV-stream).
//
// Phase 1 (PV-registry): wraps the current srcDoc-swap path — same behavior as
// PlanPreviewPane/PreviewFrame, but routed through the registry. The iframe DOM node
// is persistent; srcdoc is set imperatively (no React re-render on update).
//
// Phase 2 (PV-stream): streaming-capable path kicks in when the payload carries
// `bundleJs` instead of (or in addition to) `srcDoc`. The iframe stays mounted and
// receives chunks via postMessage to a thin resident runtime, enabling zero-reload
// incremental updates. See streamingRuntime.ts for the in-frame protocol.
//
// Payload shapes:
//   { srcDoc: string }                         — full HTML srcdoc (current producer)
//   { bundleJs: string, importmap?: Record }   — streaming path (future producer)

import type { PreviewRenderer, RendererHandle } from '../registry';
import type { RenderableChunk, PreviewStatus } from '../types';
import { registerRenderer } from '../registry';
import { buildStreamingFrameHtml } from '../streamingRuntime';
import { DEFAULT_IMPORTMAP } from '../previewBundle';

type HtmlPayload =
  | { srcDoc: string; bundleJs?: never }
  | { bundleJs: string; importmap?: Record<string, string>; srcDoc?: never };

function applyHtmlPayload(
  iframe: HTMLIFrameElement,
  streamingReady: boolean,
  payload: HtmlPayload,
): void {
  if (payload.bundleJs != null) {
    // Streaming path: post bundle to resident runtime (no srcdoc swap, no reload).
    iframe.contentWindow?.postMessage(
      { __preview_cmd: 'render_bundle', bundleJs: payload.bundleJs, importmap: payload.importmap ?? DEFAULT_IMPORTMAP },
      '*',
    );
  } else if (payload.srcDoc != null) {
    if (streamingReady) {
      // Runtime is live — deliver as full-document replace inside the frame.
      iframe.contentWindow?.postMessage(
        { __preview_cmd: 'render_srcdoc', html: payload.srcDoc },
        '*',
      );
    } else {
      // Fallback: direct srcdoc assignment (same as legacy PreviewFrame behavior).
      iframe.srcdoc = payload.srcDoc;
    }
  }
}

function createHtmlRenderer(): PreviewRenderer {
  return {
    kind: ['react-bundle', 'html'],

    mount(container: HTMLElement, initial: RenderableChunk): RendererHandle {
      const iframe = document.createElement('iframe');
      iframe.title = 'UI preview';
      iframe.setAttribute('sandbox', 'allow-scripts');
      iframe.style.cssText = 'flex:1;width:100%;height:100%;border:none;background:var(--bg-canvas,#0d0d0f)';
      container.style.cssText = 'display:flex;flex:1;min-height:0';
      container.appendChild(iframe);

      let statusCb: ((s: PreviewStatus) => void) | undefined;
      let streamingReady = false;
      // Queue a chunk delivered before the runtime has signalled ready.
      let pendingChunk: RenderableChunk | null = null;

      const payload = initial.payload as HtmlPayload;
      const useStreaming = payload.bundleJs != null;

      if (useStreaming) {
        // Bootstrap the persistent streaming runtime.
        iframe.srcdoc = buildStreamingFrameHtml(payload.importmap ?? DEFAULT_IMPORTMAP);
        pendingChunk = initial; // apply once runtime_ready arrives
      } else if (payload.srcDoc != null) {
        iframe.srcdoc = payload.srcDoc;
      }

      function onMsg(e: MessageEvent) {
        const d = e.data as { __preview?: string; message?: unknown } | null;
        if (!d || typeof d !== 'object') return;
        if (d.__preview === 'runtime_ready') {
          streamingReady = true;
          if (pendingChunk) {
            applyHtmlPayload(iframe, true, pendingChunk.payload as HtmlPayload);
            pendingChunk = null;
          }
        } else if (d.__preview === 'ready') {
          statusCb?.({ status: 'ready' });
        } else if (d.__preview === 'error') {
          statusCb?.({ status: 'error', message: String(d.message ?? '') });
        }
      }
      window.addEventListener('message', onMsg);

      const handle: RendererHandle = {
        update(chunk: RenderableChunk) {
          const p = chunk.payload as HtmlPayload;
          if (!streamingReady && p.bundleJs != null) {
            pendingChunk = chunk;
          } else {
            applyHtmlPayload(iframe, streamingReady, p);
          }
        },
        onStatus(cb) { statusCb = cb; },
        teardown() {
          window.removeEventListener('message', onMsg);
          if (container.contains(iframe)) container.removeChild(iframe);
        },
      };
      return handle;
    },
  };
}

export const htmlRenderer = createHtmlRenderer();
registerRenderer(htmlRenderer);

runtime.features/planner/preview/renderPreview.t:
// render-preview pipeline (#528/#531) — the flagship builtin. Reads the UI stage's
// skeleton artifacts, bundles them (previewBundle #530), and surfaces the iframe
// srcdoc so PlanPreviewPane renders the mock UI live in the planning page.
//
// 2D and 3D share one transport: a 3D skeleton just renders an r3f <Canvas>
// (react-three-fiber is externalized + resolved via esm.sh), so `mode` only tunes the
// pane chrome. The dispatch glue runs the stage module through the engine (#529) and
// writes the result to the store; #533 wires the triggers (tag / watch / manual).

import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { bundleSkeleton, buildPreviewSrcDoc } from "./previewBundle";
import { type StageContext, type StageRunResult } from "./stageRun";
import { registerStageModule } from "./stageCommands";

export type PreviewMode = "2d" | "3d";
export interface PreviewOutput { srcDoc: string; mode: PreviewMode; screen?: string }

export const RENDER_PREVIEW_ID = "render-preview";

/** Pick the screen entry: ctx.entry if it's a real file, else the first source file. */
export function resolveEntry(artifacts: Record<string, string>, entry?: string): string | null {
  if (entry && artifacts[entry] != null) return entry;
  const src = Object.keys(artifacts).filter((k) => /\.(jsx|tsx|js|ts)$/.test(k));
  return src[0] ?? null;
}

/** The render-preview stage helper: bundle the UI skeleton into an iframe srcDoc. Runs by
 *  direct dispatch (#897 Phase 4c removed the generic engine); never throws. */
export async function renderPreviewHandler(ctx: StageContext): Promise<StageRunResult> {
  const artifacts = ctx.artifacts as Record<string, string>;
  const entry = resolveEntry(artifacts, ctx.entry);
  if (!entry) return { status: "fail", message: "render-preview: no screen file in the skeleton" };
  const mode: PreviewMode = ctx.mode === "3d" ? "3d" : "2d";
  const js = await bundleSkeleton(artifacts, entry);
  const srcDoc = buildPreviewSrcDoc(js);
  return { status: "ok", output: { srcDoc, mode } satisfies PreviewOutput };
}

/**
 * Run render-preview for a project and reflect the result in the store: the bundled
 * srcdoc (→ the preview pane) and the run status. Calls the handler directly.
 */
export async function dispatchRenderPreview(args: {
  projectKey: string; stageId?: string; artifacts: Record<string, string>; entry?: string; mode?: PreviewMode; screen?: string;
}): Promise<StageRunResult> {
  const store = useAppStore.getState();
  store.setStageRun(args.projectKey, RENDER_PREVIEW_ID, { status: "running", lastRun: null });
  const ctx: StageContext = {
    projectKey: args.projectKey, stageId: args.stageId ?? "ui", artifacts: args.artifacts,
    entry: args.entry, mode: args.mode,
  };
  let result: StageRunResult;
  try { result = await renderPreviewHandler(ctx); }
  catch (e) { result = { status: "fail", message: String(e) }; }
  if (result.status === "ok" && result.output) {
    // Tag the stored preview with the screen so the pane's approve button targets it (#546).
    store.setStagePreview(args.projectKey, { ...(result.output as PreviewOutput), screen: args.screen ?? args.entry });
  }
  store.setStageRun(args.projectKey, RENDER_PREVIEW_ID, { status: result.status, lastRun: Date.now(), message: result.message });
  return result;
}

// Register render-preview as the first command module. Its `run` reads the project's
// .ui-skeleton and dispatches a render for the requested screen/mode — the behavior the
// <ui_preview> tag triggers today. Richer commands (save/confirm/persist, navigation)
// are render-preview's OWN later behavior; the bus stays generic. Idempotent on import.
registerStageModule({
  id: RENDER_PREVIEW_ID,
  async command(cmd, ctx) {
    if (cmd !== "run") return; // other commands are this stage module's future behavior
    const screen = ctx.args.screen || undefined;
    const mode: PreviewMode = ctx.args.mode === "3d" ? "3d" : "2d";
    const files = await invoke<[string, string][]>("read_ui_skeleton", { projectKey: ctx.projectKey });
    if (files.length === 0) return;
    await dispatchRenderPreview({
      projectKey: ctx.projectKey, artifacts: Object.fromEntries(files), entry: screen, mode, screen,
    });
  },
});

runtime.features/planner/preview/stageCommands.t:
// Stage command bus — the thin router between Claude's standardized commands and a stage
// module's OWN behavior. A stage module is a self-contained plugin: it owns its state,
// result keying/accumulation, navigation, and persistence (it calls writeProjectFile
// inside its own save/confirm). The framework owns nothing here but the routing.
//
// A stage module registers itself here (registerStageModule) and the framework routes the
// standardized commands into it — never a module's internals. Pure + framework-free so it's
// unit-testable in isolation. (The render-preview module is the live consumer.)

export type StageCommand =
  | "run" | "save" | "confirm" | "restart" | "prev" | "next" | "goto" | "delete";

export const STAGE_COMMANDS: StageCommand[] =
  ["run", "save", "confirm", "restart", "prev", "next", "goto", "delete"];

export function isStageCommand(value: string): value is StageCommand {
  return (STAGE_COMMANDS as string[]).includes(value);
}

/** What a command handler receives: the project + free-form args parsed from the tag
 *  (e.g. `screen`, `mode`, `index`, `rid`). The pipeline interprets them. */
export interface StageCommandCtx {
  projectKey: string;
  args: Record<string, string>;
}

export type StageCommandHandler =
  (cmd: StageCommand, ctx: StageCommandCtx) => Promise<void> | void;

/** A stage module's command surface. One registration per stage id; the handler is the
 *  stage module's behavior for every command it supports (it may ignore ones it doesn't). */
export interface StageModule {
  id: string;
  command: StageCommandHandler;
}

const MODULES = new Map<string, StageModule>();

/** Register (or replace) a stage module's command module. Idempotent — last wins. */
export function registerStageModule(module: StageModule): void {
  MODULES.set(module.id, module);
}
export function hasStageModule(id: string): boolean {
  return MODULES.has(id);
}

export interface StageDispatchResult {
  ok: boolean;
  error?: string;
}

/**
 * Route a command to its stage module's module. Never throws: an unknown stage module or a
 * handler that throws resolves to a structured failure, so the tag-dispatch layer (and
 * any loop over commands) is safe to await.
 */
export async function dispatchStageCommand(
  id: string, cmd: StageCommand, ctx: StageCommandCtx,
): Promise<StageDispatchResult> {
  const mod = MODULES.get(id);
  if (!mod) return { ok: false, error: `no stage module registered for "${id}"` };
  try {
    await mod.command(cmd, ctx);
    return { ok: true };
  } catch (e) {
    return { ok: false, error: String(e) };
  }
}

/** Test helper — reset the module registry between cases. */
export function _resetStageModules(): void {
  MODULES.clear();
}

runtime.features/planner/preview/stageRun.ts:
// Stage-run types for the in-app stage helpers (render-preview, file-intake).
//
// The generic "stage engine" (handler registry + runner + trigger dispatch + gate
// predicate) was removed in #897 Phase 4c — there was never a production trigger pump,
// and the three remaining behaviors run by DIRECT dispatch (see their modules). What's
// left here is just the shared run-state shapes those dispatches + the store use.

/** What a stage helper receives: the stage's identity + its read-only artifacts. */
export interface StageContext {
  projectKey: string;
  stageId: string;
  /** Stage artifacts as relpath → contents (read-only). */
  artifacts: Readonly<Record<string, string>>;
  /** The artifact a focused run targets (e.g. the screen for render-preview). */
  entry?: string;
  /** Free-form mode the handler reads (render-preview uses "2d" | "3d"). */
  mode?: string;
}

export type StageOutcome = "ok" | "fail" | "blocked";
export type StageStatus = "idle" | "running" | StageOutcome;

export interface StageRunResult {
  status: StageOutcome;
  message?: string;
  /** Handler-specific payload (e.g. render-preview returns the iframe srcDoc). */
  output?: unknown;
}

export interface StageRunState {
  status: StageStatus;
  /** epoch ms of the last completed run; stamped by the caller. */
  lastRun: number | null;
  message?: string;
}

runtime.features/planner/preview/StageScreenFram:
// StageScreenFrame — the shared chrome for a stage module's "second screen" in the
// planning page. Every registered stage screen (render-preview today; generators
// later) composes this so they get consistent chrome and run-status for free and only
// supply their own body. Sections own the page; stage modules own their surface — this is
// the surface's frame.
//
// Layout: the fixed-width pane shell, a header (▸ label · badge · spacer · status ·
// actions · close), a body slot (`children`), and an optional footer slot.

import type { ReactNode } from "react";
import { IconButton } from "@/shared/ui/controls/IconButton";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

export function StageScreenFrame({
  label, badge, statusLabel, statusColor, actions, onClose, footer, fullWidth, bare, children,
}: {
  /** The ▸ title, e.g. "preview". */
  label: string;
  /** A small badge after the label (e.g. the preview's 2d/3d mode tag). */
  badge?: ReactNode;
  /** Run-status text + color (right-aligned), typically derived from the stage run. */
  statusLabel?: string;
  statusColor?: string;
  /** Stage-specific header controls, rendered after the status, before close. */
  actions?: ReactNode;
  /** When provided, renders a dismiss affordance (stage-bound screens omit it). */
  onClose?: () => void;
  /** Stage-specific footer (e.g. the declared-screens approval list). */
  footer?: ReactNode;
  /** Fill the parent pane instead of the fixed 420px "second screen" width (e.g. the file
   *  intake surface, which is a full-width stage body). */
  fullWidth?: boolean;
  /** Hide the header bar entirely — for a bare, full-pane surface (e.g. the file-intake drop box). */
  bare?: boolean;
  /** The screen body. */
  children: ReactNode;
}) {
  return (
    <section style={{
      ...(fullWidth ? { flex: 1, minWidth: 0 } : { flex: "0 0 auto", width: 420, borderLeft: "1px solid var(--border-soft)" }),
      display: "flex", flexDirection: "column", minHeight: 0, overflow: "hidden", background: "var(--bg-panel)",
    }}>
      {!bare && (
        <Row className="mono" gap={8} style={{
          padding: "10px 14px", borderBottom: "1px solid var(--border-soft)",
          fontSize: 11, color: "var(--fg-muted)",
        }}>
          <Text as="span" tone="accent">▸ {label}</Text>
          {badge}
          <Box as="span" style={{ flex: 1 }} />
          {statusLabel && <Text as="span" size={10} style={{ color: statusColor ?? "var(--fg-dim)" }}>{statusLabel}</Text>}
          {actions}
          {onClose && <IconButton aria-label="Close" onClick={onClose} />}
        </Row>
      )}

      <Stack style={{ flex: 1, minHeight: 0 }}>
        {children}
      </Stack>

      {footer}
    </section>
  );
}

runtime.features/planner/preview/stageScreens.ts:
// Stage "second screens" — the render-surface registry for the planning page.
//
// Sections are static and own the planning UI; *stage modules* are how capability is added
// (builtin or external). A stage module may declare a second screen: a render surface that
// appears in the planning page when the module's STAGE is the current (reached) one.
// The planning page reads the active blueprint directly, finds the current stage's
// enabled modules, and renders whichever of them registered a screen here.
//
// Keyed by stage id so builtin and external modules alike can plug a screen in.
// React lives here (not in the pure stageRun), mirroring how renderPreview's
// handler is pure but its surface, PlanPreviewPane, is a component.

import type { ComponentType } from "react";
// Preview module: import renderers (side-effects) + the new shell component (#581).
import "./renderers/htmlRenderer";
import "./renderers/gltfRenderer";
import "./renderers/canvasRenderer";
import { PreviewPaneShell } from "./PreviewPaneShell";
import { RENDER_PREVIEW_ID } from "./renderPreview";
import { FileIntakePane } from "../bodies/FileIntakePane";
import { FILE_INTAKE_ID } from "../lib/fileIntake";

/** Props every pipeline second screen receives. `onClose`, when provided, renders a
 *  dismiss affordance (stage-driven screens omit it — they're bound to the stage). */
export interface StageScreenProps {
  projectKey: string;
  /** The current (reached) section's key — screens bound to a section use it;
   *  section-agnostic screens (render-preview) ignore it. */
  stageKey?: string;
  /** The current section's plan markdown, when available. */
  stageContent?: string;
  onClose?: () => void;
}

export type StageScreenComponent = ComponentType<StageScreenProps>;

const STAGE_SCREENS: Record<string, StageScreenComponent> = {
  // Modular streaming feed consumer (#581): PreviewPaneShell routes chunks through the
  // renderer registry; renderer side-effects above register html/gltf/canvas renderers.
  [RENDER_PREVIEW_ID]: PreviewPaneShell,
  // Drag-and-drop file intake (#604): stage design/any files for the planner to route.
  [FILE_INTAKE_ID]: FileIntakePane,
};

/** The second screen for a stage id, or undefined when it has none. */
export function stageScreen(id: string): StageScreenComponent | undefined {
  return STAGE_SCREENS[id];
}

/** Whether a stage module declares a second screen. */
export function hasStageScreen(id: string): boolean {
  return id in STAGE_SCREENS;
}

/** Register (or replace) a stage module's second screen. Lets external stage modules plug a
 *  render surface into the planning page. Idempotent — last registration wins. */
export function registerStageScreen(id: string, screen: StageScreenComponent): void {
  STAGE_SCREENS[id] = screen;
}

runtime.features/planner/preview/streamingRuntim:
// Thin resident in-frame runtimes for streaming renderers (#581 PV-stream / PV-gltf).
// Each runtime is a self-contained HTML string baked into a persistent iframe.
// The host sends commands via postMessage; the runtime signals back via parent.postMessage.
//
// Delivery contract:
//   host → frame: { __preview_cmd: 'render_bundle', bundleJs: string, importmap?: Record<string,string> }
//                 { __preview_cmd: 'render_gltf',   url?: string, base64?: string }
//   frame → host: { __preview: 'ready' | 'error' | 'runtime_ready', message?: string }

import { DEFAULT_IMPORTMAP } from './previewBundle';

/**
 * Builds the srcdoc for the streaming html/react-bundle iframe. The thin runtime:
 * - Signals `{ __preview: 'runtime_ready' }` once loaded.
 * - On `render_bundle`: clears #root, creates a blob URL from bundleJs, dynamically
 *   imports it (React + esm.sh externals resolved via import-map), then signals ready.
 * - Falls back to `render_srcdoc` for a full document replace (legacy support).
 */
export function buildStreamingFrameHtml(importmap: Record<string, string> = DEFAULT_IMPORTMAP): string {
  const im = JSON.stringify({ imports: importmap });
  return `<!doctype html><html><head><meta charset="utf-8"/>
<style>html,body,#root{margin:0;height:100%;background:var(--bg,#0d0d0f);font-family:Inter,system-ui,sans-serif;color:#eee}</style>
<script type="importmap">${im}</script>
</head><body><div id="root"></div>
<script>
var _bscRoot=null;
window.addEventListener('message',async function(e){
  var d=e.data;
  if(!d)return;
  if(d.__preview_cmd==='render_bundle'){
    try{
      if(_bscRoot){try{_bscRoot.unmount();}catch(_){}_bscRoot=null;}
      document.getElementById('root').innerHTML='';
      var blob=new Blob([d.bundleJs],{type:'text/javascript'});
      var url=URL.createObjectURL(blob);
      await import(url);
      URL.revokeObjectURL(url);
      parent.postMessage({__preview:'ready'},'*');
    }catch(err){
      parent.postMessage({__preview:'error',message:String(err)},'*');
    }
  }
  // Legacy full-document replace — for srcDoc payloads without extracted bundleJs.
  if(d.__preview_cmd==='render_srcdoc'){
    try{document.open();document.write(d.html);document.close();}catch(err){
      parent.postMessage({__preview:'error',message:String(err)},'*');
    }
  }
});
parent.postMessage({__preview:'runtime_ready'},'*');
</script></body></html>`;
}

/**
 * Builds the srcdoc for the streaming glTF iframe. The thin runtime:
 * - Loads three.js + GLTFLoader from esm.sh and sets up a scene with orbit controls.
 * - On `render_gltf`: loads the model from a URL or base64 data URI, auto-fits the
 *   camera, and auto-rotates. Replaces the previous model on each call.
 */
export function buildGltfRuntimeHtml(): string {
  const threeUrl = DEFAULT_IMPORTMAP['three'] ?? 'https://esm.sh/three@0.169.0';
  const loaderUrl = `${threeUrl.replace(/\?.*$/, '')}/examples/jsm/loaders/GLTFLoader.js`;
  const controlsUrl = `${threeUrl.replace(/\?.*$/, '')}/examples/jsm/controls/OrbitControls.js`;
  const im = JSON.stringify({ imports: { three: threeUrl } });
  return `<!doctype html><html><head><meta charset="utf-8"/>
<style>html,body,canvas{margin:0;width:100%;height:100%;display:block;background:#0d0d0f;overflow:hidden}</style>
<script type="importmap">${im}</script>
</head><body>
<canvas id="c"></canvas>
<script type="module">
import*as THREE from 'three';
import{GLTFLoader}from'${loaderUrl}';
import{OrbitControls}from'${controlsUrl}';

const canvas=document.getElementById('c');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});
renderer.setPixelRatio(devicePixelRatio);
renderer.setSize(innerWidth,innerHeight);
renderer.outputColorSpace=THREE.SRGBColorSpace;

const scene=new THREE.Scene();
scene.background=new THREE.Color(0x0d0d0f);
const camera=new THREE.PerspectiveCamera(45,innerWidth/innerHeight,0.001,1000);
camera.position.set(0,1.5,3);

const ambient=new THREE.AmbientLight(0xffffff,0.8);
const dir=new THREE.DirectionalLight(0xffffff,1.2);
dir.position.set(2,4,3);
scene.add(ambient,dir);

const controls=new OrbitControls(camera,renderer.domElement);
controls.enableDamping=true;
controls.dampingFactor=0.05;

let model=null;
const loader=new GLTFLoader();

window.addEventListener('message',function(e){
  const d=e.data;
  if(d?.__preview_cmd!=='render_gltf')return;
  const url=d.url||('data:model/gltf+json;base64,'+d.base64);
  loader.load(url,function(gltf){
    if(model)scene.remove(model);
    model=gltf.scene;
    scene.add(model);
    const box=new THREE.Box3().setFromObject(model);
    const size=box.getSize(new THREE.Vector3()).length();
    const center=box.getCenter(new THREE.Vector3());
    model.position.sub(center);
    camera.near=size/100;camera.far=size*100;
    camera.position.set(0,size*0.4,size*1.2);
    camera.updateProjectionMatrix();
    controls.update();
    parent.postMessage({__preview:'ready'},'*');
  },undefined,function(err){
    parent.postMessage({__preview:'error',message:String(err)},'*');
  });
});

window.addEventListener('resize',function(){
  renderer.setSize(innerWidth,innerHeight);
  camera.aspect=innerWidth/innerHeight;
  camera.updateProjectionMatrix();
});

(function animate(){requestAnimationFrame(animate);controls.update();renderer.render(scene,camera);})();
parent.postMessage({__preview:'runtime_ready'},'*');
</script></body></html>`;
}

runtime.features/planner/preview/types.ts:
// Core types for the modular streaming preview feed consumer (#581).

/** The set of renderable content kinds the registry dispatches on. */
export type RenderableKind =
  | 'react-bundle'
  | 'html'
  | 'gltf'
  | 'scene'
  | 'image'
  | 'video-frame';

/**
 * A chunk arriving from the preview feed. One-shots are streams of length 1
 * (`final: true`). The `payload` is opaque to the shell; each renderer knows
 * its own payload shape.
 */
export interface RenderableChunk {
  kind: RenderableKind;
  /** Opaque label identifying the producer; chrome-only, never affects routing. */
  source?: string;
  /** Display mode hint, passed to the pane chrome (e.g. "2d" | "3d"). */
  mode?: string;
  /** Monotonically increasing sequence number for ordering. */
  seq?: number;
  /** True when this is the final chunk in the stream. */
  final?: boolean;
  /** Renderer-specific payload (opaque to the shell). */
  payload: unknown;
}

/** Renderer-reported surface status, forwarded to the pane chrome. */
export interface PreviewStatus {
  status: 'building' | 'ready' | 'error';
  message?: string;
}

runtime.features/planner/ProjectsGraphHost.tsx:
// The Projects page host (#3874, epic #3604) — renders the Projects workspace FROM THE GRAPH. The page is
// sourced from the components graph (the `projectspage` node, seeded from `data/components/app/**`), not a
// bundled file. It registers the planner-list feature's injected platform surface (the card/rail/setup-page/
// modal components + the draft / local-published / projects.db derivations), then mounts `projectspage`
// through the runtime loader. Mirrors the fleet/automations/security/github/skills/mcp hosts.
//
// The CSS still ships as a normal bundled import here: the loader cannot resolve a CSS side-effect import,
// so it was stripped from the graph source and the host owns the stylesheet the page's classes need.
//
// MOUNTED (#3874). Both `<ProjectsList />` sites in `features/planner/index.tsx` — the tear-off
// (`pageOverride`) path and the normal one — now render this host instead.
//
// HOW THE FLIP WAS VERIFIED, and why it had to be. The loader's compile step is esbuild-wasm and
// BROWSER-ONLY, so no headless check can prove this page renders — the epic accepted that verification here
// is real-Chromium or nothing. It was done against the RUNNING app (`bsc shot take` on a `tauri dev`
// instance), and that is what caught the one real defect: `ProjectsList` reaches
// `./published/ProjectRow` through a RE-EXPORT (`export { ProjectRow } from …`), which esbuild compiles to
// the same `require` an import produces. `graphPlatform` didn't register it and the seed test's import scan
// only matched `import … from`, so the page compiled, failed to resolve, and rendered its fallback — with a
// green suite. Both are fixed; the scan now covers `export … from` too.
import { GraphComponent } from "@/shared/lib/runtime/GraphComponent";
import { GraphPageFallback } from "@/shared/lib/runtime/GraphPageFallback";
import { registerProjectsPlatform } from "./list/graphPlatform";
import "./projectsScreen.css";

export function ProjectsGraphHost() {
  // Registered at FIRST RENDER, not module load — unlike the other hosts, and deliberately.
  //
  // `graphPlatform` imports the planner-list siblings, which transitively import the planner barrel, which
  // imports this host. Registering in module scope therefore ran `registerProjectsPlatform()` *during* that
  // cycle, before `graphPlatform`'s own `let done` was initialised — a real `ReferenceError: Cannot access
  // 'done' before initialization`, caught by the seed test. Planner is the only feature whose barrel is deep
  // enough in its own import graph for this to bite.
  //
  // Render-time is still early enough: React renders this parent before the `GraphComponent` child whose
  // compiled `require()` reads the registry. Idempotent, so re-renders cost nothing.
  registerProjectsPlatform();

  // Fallback offers Reload-to-apply / Re-seed (#3648/#3652) when the source isn't in the library yet.
  return (
    <GraphComponent
      id="projectspage"
      fallback={<GraphPageFallback page="Projects" icon="◧" />}
    />
  );
}

runtime.features/planner/relationship/relationsh:
// Agent-relationship graph (#…) — the typed coordination graph over the fleet's
// streams: who produces which artifact, who consumes it, and how each relationship
// is coordinated (director-relayed vs direct peer). Pure (no React/Tauri) so the
// layering + cycle detection are unit-testable; the visualization lives in
// RelationshipGraphView.tsx and the authoring controls in the Structure/Permissions
// focused panes. Mirrors the design prototype (design/bsc · model()).
import { neighborSpotlight } from "@/shared/lib/graph/spotlight";
import { findBackEdges } from "@/shared/lib/graph/cycles";
import { layerDag } from "@/shared/lib/graph/layers";

/** Fleet coordination topology. `director` = hub-and-spoke (every edge routes through
 *  the director), `peer` = mesh (every edge is a direct handoff), `hybrid` = per-edge. */
export type Topology = "director" | "peer" | "hybrid";

/** Relationship kind. The "ordering" kinds (handoff/blocking/sequence/review) impose a
 *  build order and participate in cycle detection + layering; the rest are annotations. */
export type EdgeKind = "handoff" | "blocking" | "sequence" | "review" | "notify" | "mutex" | "shared";

/** Hardness of a relationship: hard wait · proceed-against-a-stub · fire-and-forget. */
export type Hardness = "blocking" | "soft" | "notify";

/** How a relationship is coordinated. */
export type Via = "director" | "direct";

export type ArtifactKind = "schema" | "contract" | "types" | "tokens" | "fixture" | "other";

/** A produced contract/schema/types another stream consumes — the coord `contract:<id>` ref. */
export interface RelationshipArtifact {
  id: string;
  name: string;
  kind: ArtifactKind;
  producer: string;           // stream id
  consumers: string[];        // stream ids
  status?: "pending" | "ready";
}

/** A typed relationship edge between two streams. */
export interface AgentRelationship {
  id: string;
  from: string;               // upstream stream id
  to: string;                 // downstream stream id
  kind: EdgeKind;
  artifact?: string;          // RelationshipArtifact.id for handoff/shared
  hardness: Hardness;
  via: Via;
  note?: string;
}

/** Minimal stream shape the graph needs (a projection of AgentStream). */
export interface RelStream {
  id: string;
  role?: string;
  repo?: string;
  owns?: string[];
}

/** An edge with its effective `via` resolved against the fleet topology. */
export interface ResolvedEdge extends AgentRelationship { viaEff: Via }

export interface RelationshipGraph {
  streams: RelStream[];
  artifacts: RelationshipArtifact[];
  edges: ResolvedEdge[];
  /** Stream ids, in declaration order. */
  sids: string[];
  /** Topological layer per stream id (0 = a source). Back-edges are excluded so a cycle
   *  doesn't blow up the layering. */
  layerOf: Record<string, number>;
  /** True when an ordering-edge cycle exists (a coordination deadlock). */
  hasCycle: boolean;
  /** Ids of the edges that close a cycle (the back-edges) — rendered red + block the gate. */
  cycleEdgeIds: Set<string>;
}

/** Ordering kinds — they impose build order, so they drive cycle detection + layering. */
const ORDERING: ReadonlySet<EdgeKind> = new Set<EdgeKind>(["handoff", "blocking", "sequence", "review"]);

/** Resolve an edge's effective `via` against the topology (director/peer force it; hybrid keeps it). */
export function effectiveVia(topology: Topology, via: Via): Via {
  return topology === "director" ? "director" : topology === "peer" ? "direct" : via;
}

/**
 * Build the relationship graph from the fleet's streams, declared artifacts, and edges,
 * under a coordination topology. Detects ordering cycles (DFS back-edges) and assigns
 * topological layers (shared longest-path layerer, excluding back-edges so a cycle can't
 * explode the layout).
 */
export function buildRelationshipGraph(
  streams: RelStream[],
  artifacts: RelationshipArtifact[],
  edges: AgentRelationship[],
  topology: Topology,
): RelationshipGraph {
  const sids = streams.map((s) => s.id);
  const resolved: ResolvedEdge[] = edges.map((e) => ({ ...e, viaEff: effectiveVia(topology, e.via) }));

  // ── cycle detection FIRST (DFS back-edges over ordering edges) — shared graph-core primitive (#2217) ──
  const { backEdgeIds: cycleEdgeIds, hasCycle } = findBackEdges(sids, resolved.filter((e) => ORDERING.has(e.kind)));

  // ── layering over ordering edges, EXCLUDING back-edges (keeps it a DAG) — shared layerer (#2214) ──
  const layerOf = layerDag(sids, resolved.filter((e) => ORDERING.has(e.kind)), cycleEdgeIds);

  return { streams, artifacts, edges: resolved, sids, layerOf, hasCycle, cycleEdgeIds };
}

// ── display metadata (shared by the view + the inspector) ──────────────────────

export const EDGE_KIND_META: Record<EdgeKind, { color: string; label: string; glyph: string }> = {
  handoff:  { color: "var(--accent)",        label: "handoff",  glyph: "⤚" },
  blocking: { color: "var(--info)",          label: "blocking", glyph: "⏸" },
  sequence: { color: "var(--fg-dim)",        label: "sequence", glyph: "→" },
  notify:   { color: "var(--fg-muted)",      label: "notify",   glyph: "◇" },
  mutex:    { color: "var(--danger)",        label: "mutex",    glyph: "⚠" },
  shared:   { color: "var(--violet)",        label: "shared",   glyph: "↔" },
  review:   { color: "oklch(0.70 0.14 350)", label: "review",   glyph: "✓" },
};

export const ARTIFACT_COLOR: Record<ArtifactKind, string> = {
  schema: "var(--success)", contract: "var(--info)", types: "var(--violet)",
  tokens: "var(--accent)", fixture: "var(--fg-muted)", other: "var(--fg-muted)",
};

export const DIRECTOR_COLOR = "oklch(0.70 0.14 350)";

export const ROLE_COLOR: Record<string, string> = {
  worker: "var(--accent)", tester: "var(--success)", reviewer: "var(--violet)",
  planner: "var(--info)", director: DIRECTOR_COLOR,
};

/** Dash + width per hardness (solid hard, dashed soft, dotted notify). */
export function hardStyle(h: Hardness): { dash: string; w: number } {
  return h === "blocking" ? { dash: "", w: 2.0 } : h === "soft" ? { dash: "6 4", w: 1.6 } : { dash: "2 4", w: 1.4 };
}

/** Human label for a hardness (the inspector + tooltips). */
export function hardLabel(h: Hardness): string {
  return h === "blocking" ? "hard wait" : h === "soft" ? "stub & reconcile" : "fire & forget";
}

/** Resting opacity per edge kind — handoff/blocking read bold, quieter kinds recede (swimlanes). */
export function restOpacity(kind: EdgeKind): number {
  return kind === "handoff" || kind === "blocking" ? 0.95 : kind === "sequence" ? 0.55 : kind === "notify" ? 0.4 : 0.5;
}

/** The one-line runtime note for an edge — how the relationship is enforced at fleet time. */
export function runtimeNote(e: ResolvedEdge): string {
  const map: Record<EdgeKind, string> = {
    // #3931: these used to advertise `bsc-blocked --on`, a command removed with #1039 and never
    // replaced — an agent that tried to run it got "command not found". Enforcement is now the LAUNCH
    // gate: `${e.to}` is not started until `${e.from}` lands, and a started worker never parks.
    handoff:  `${e.to} starts once ${e.from} lands contract:${e.artifact ?? "…"} (launch gate).`,
    blocking: `${e.to} is held at launch until ${e.from}'s work lands (launch gate).`,
    shared:   "co-owned interface — both streams notified on change.",
    review:   `${e.to}'s output reviewed before merge (role/flow gate).`,
    notify:   `event only — pings ${e.to}, never blocks.`,
    mutex:    "serialized — validated against owns[] glob overlap.",
    sequence: "pure ordering via dependsOn.",
  };
  return (e.viaEff === "director" ? "[via director] " : "[peer latch] ") + (map[e.kind] || "");
}

/** What the user is focused on — a stream lane, an edge, or an artifact. */
export type RelFocus = { type: "agent" | "edge" | "art"; id: string } | null;

export interface Spotlight {
  active: boolean;
  focusId?: string;
  focusType?: "agent" | "edge" | "art";
  /** Stream ids drawn bright; everything else dims. */
  brightStreams: Set<string>;
  /** Edge ids drawn lit. */
  litEdges: Set<string>;
  /** Artifact ids drawn lit. */
  litArtifacts: Set<string>;
}

/**
 * Resolve the spotlight for a focus (hover or pinned): which streams/edges/artifacts to
 * brighten and which to dim. An agent focus lights itself + its neighbors and every edge it
 * touches; an edge lights its endpoints; an artifact lights its producer + consumers and its
 * handoff edges. Pure — drives the swimlane opacities and is unit-testable.
 */
export function computeSpotlight(g: RelationshipGraph, focus: RelFocus): Spotlight {
  if (!focus) return { active: false, brightStreams: new Set(), litEdges: new Set(), litArtifacts: new Set() };
  const brightStreams = new Set<string>();
  const litEdges = new Set<string>();
  const litArtifacts = new Set<string>();
  if (focus.type === "agent") {
    const sp = neighborSpotlight(g.edges, focus.id);
    sp.litNodes.forEach((n) => brightStreams.add(n));
    sp.litEdges.forEach((id) => litEdges.add(id));
    for (const a of g.artifacts) if (a.producer === focus.id || a.consumers.includes(focus.id)) litArtifacts.add(a.id);
  } else if (focus.type === "edge") {
    const e0 = g.edges.find((e) => e.id === focus.id);
    if (e0) { brightStreams.add(e0.from); brightStreams.add(e0.to); litEdges.add(e0.id); if (e0.kind === "handoff" && e0.artifact) litArtifacts.add(e0.artifact); }
  } else {
    const a0 = g.artifacts.find((a) => a.id === focus.id);
    if (a0) {
      brightStreams.add(a0.producer); a0.consumers.forEach((c) => brightStreams.add(c)); litArtifacts.add(a0.id);
      for (const e of g.edges) if (e.kind === "handoff" && e.artifact === focus.id) litEdges.add(e.id);
    }
  }
  return { active: true, focusId: focus.id, focusType: focus.type, brightStreams, litEdges, litArtifacts };
}

runtime.features/planner/relationship/Relationsh:
// RelationshipGraphView — the SWIMLANE visualization of the agent-relationship graph:
// one lane per stream (ordered by build phase), phase columns advancing left→right, the
// stream's "station" node at its phase, artifact tokens (diamonds) on the producer lane
// flowing to consumers, and typed/hardness-styled connectors. At rest only handoff/
// blocking read bold; hover or click a stream to spotlight just its relationships (the
// rest dim). Pure presentational — focus + hover are lifted to the caller. Ported from
// design/bsc · Agent Relationships - Swimlanes · lanes().

import {
  EDGE_KIND_META, ARTIFACT_COLOR, ROLE_COLOR, hardStyle, restOpacity, computeSpotlight,
  type RelationshipGraph, type RelFocus, type RelStream,
} from "./relationshipGraph";

const PAD = 16, LH = 58, TOP = 30, NH = 30;
const LABEL_X = 14;   // left inset of the label text
const LABEL_PAD = 14; // gap between the longest label and the divider / first node
const MIN_GUTTER = 96;
const ID_FONT = '600 11px "JetBrains Mono", ui-monospace, monospace';
const REPO_FONT = '400 7.5px "JetBrains Mono", ui-monospace, monospace';
// Station-node sizing — the rect is measured to fit its id so the text never overflows it.
const NODE_FONT = '600 10.5px "JetBrains Mono", ui-monospace, monospace';
const NODE_TEXT_X = 22;   // id text inset (after the role dot)
const NODE_PAD_R = 13;    // right padding inside the node rect
const MIN_NODE_W = 72;
const COL_GAP = 46;       // gap after a node before the next phase column (fits artifact tokens)
const MIN_COL = 124;

// Measure rendered text width. Uses a shared canvas (accurate for the real font); falls back
// to a monospace estimate when canvas isn't available (jsdom / SSR), which is exact enough for
// the mono font. Memoizes the 2d context so we probe getContext at most once.
let _ctx: CanvasRenderingContext2D | null | undefined;
function measureText(text: string, font: string): number {
  if (_ctx === undefined) {
    try { _ctx = document.createElement("canvas").getContext("2d"); }
    catch { _ctx = null; }
  }
  if (_ctx) { _ctx.font = font; return _ctx.measureText(text).width; }
  const px = parseFloat(font) || 11;
  return text.length * px * 0.6; // monospace advance ≈ 0.6em
}

/** Width the left gutter must be to fit the widest "id + ⎇ repo" label across all streams. */
function measureGutter(streams: RelStream[]): number {
  let w = 0;
  for (const s of streams) {
    const idW = measureText(s.id, ID_FONT);
    const repoW = s.repo ? measureText(`⎇ ${s.repo}`, REPO_FONT) : 0;
    w = Math.max(w, idW, repoW);
  }
  return Math.max(MIN_GUTTER, Math.ceil(LABEL_X + w + LABEL_PAD));
}

/** Width the station-node rect must be to fit the widest stream id (role dot + id + padding). */
function measureNodeWidth(streams: RelStream[]): number {
  let w = 0;
  for (const s of streams) w = Math.max(w, measureText(s.id, NODE_FONT));
  return Math.max(MIN_NODE_W, Math.ceil(NODE_TEXT_X + w + NODE_PAD_R));
}

function Arrow({ x, y, ang, c, op }: { x: number; y: number; ang: number; c: string; op: number }) {
  const s = 5.2;
  const p = (a: number) => `${(x + s * Math.cos(ang + a)).toFixed(1)},${(y + s * Math.sin(ang + a)).toFixed(1)}`;
  return <polygon points={`${x.toFixed(1)},${y.toFixed(1)} ${p(Math.PI - 0.42)} ${p(Math.PI + 0.42)}`} fill={c} opacity={op} />;
}

export function RelationshipGraphView({ graph, focus, hover, onFocusAgent, onInspectEdge, onInspectArtifact, onHover }: {
  graph: RelationshipGraph;
  /** Pinned focus (a click). */
  focus: RelFocus;
  /** Transient hover (takes precedence over the pin for the spotlight). */
  hover: string | null;
  onFocusAgent: (id: string) => void;
  onInspectEdge: (id: string) => void;
  onInspectArtifact: (id: string) => void;
  onHover: (id: string | null) => void;
}) {
  const { streams, artifacts, edges, sids, layerOf, cycleEdgeIds } = graph;
  // Size the left label gutter to the widest measured "id + ⎇ repo" so the phase track (and
  // the station-node rects) always start clear of the labels — nothing overlaps the text.
  const LW = measureGutter(streams);
  // Size the node rect to the widest id, and space the phase columns to fit a node + its
  // artifact token, so the text never overflows its rect nor the next column.
  const NW = measureNodeWidth(streams);
  const COL = Math.max(MIN_COL, NW + COL_GAP);
  const order = [...streams].sort((a, b) => (layerOf[a.id] - layerOf[b.id]) || a.id.localeCompare(b.id));
  // Lane vertical center = the band's center (the band is LH-8 tall starting at TOP+i*LH), so
  // the station-node rect, its edges, and the labels all align to the middle of the row.
  const laneY: Record<string, number> = {};
  order.forEach((s, i) => { laneY[s.id] = TOP + i * LH + (LH - 8) / 2; });
  const maxL = Math.max(0, ...sids.map((id) => layerOf[id] ?? 0));
  const nodeX = (id: string) => LW + PAD + (layerOf[id] ?? 0) * COL;
  const colX = (l: number) => LW + PAD + l * COL;
  const W = LW + PAD + maxL * COL + NW + 110;
  const H = TOP + order.length * LH + 12;

  const sp = computeSpotlight(graph, hover ? { type: "agent", id: hover } : focus);
  const laneOp = (id: string) => (sp.active ? (sp.brightStreams.has(id) ? 1 : 0.16) : 1);
  const edgeOp = (e: typeof edges[number]) => (sp.active ? (sp.litEdges.has(e.id) ? 1 : 0.05) : restOpacity(e.kind));

  const els: React.ReactNode[] = [];

  // phase column guides
  for (let l = 0; l <= maxL; l++) {
    const x = colX(l);
    els.push(<text key={`pl${l}`} x={x + NW / 2} y={16} textAnchor="middle" fontFamily="var(--mono)" fontSize={8} fill="var(--fg-dim)">phase {l}</text>);
    els.push(<line key={`pg${l}`} x1={x + NW / 2} y1={22} x2={x + NW / 2} y2={H - 6} stroke="var(--border-soft)" strokeWidth={1} strokeDasharray="2 5" opacity={0.5} />);
  }
  // divider between the stream-label gutter and the phase track
  els.push(<line key="gutter-div" x1={LW + 4} y1={TOP - 4} x2={LW + 4} y2={H - 6} stroke="var(--border-soft)" strokeWidth={1} opacity={0.7} />);

  // lane bands + labels (hover/click targets)
  order.forEach((s, i) => {
    const y = TOP + i * LH;
    const rc = ROLE_COLOR[s.role ?? ""] ?? "var(--fg-dim)";
    const isFocus = sp.active && sp.focusType === "agent" && sp.focusId === s.id;
    els.push(
      <g key={`lane${s.id}`} onMouseEnter={() => onHover(s.id)} onMouseLeave={() => onHover(null)} onClick={() => onFocusAgent(s.id)} style={{ cursor: "pointer" }} opacity={laneOp(s.id)}>
        <rect x={2} y={y} width={W - 4} height={LH - 8} rx={7} fill={i % 2 ? "color-mix(in oklch, var(--bg-canvas), transparent 25%)" : "var(--bg-canvas)"} stroke={isFocus ? rc : "var(--border-soft)"} strokeWidth={isFocus ? 1.4 : 1} />
        <rect x={2} y={y} width={3.5} height={LH - 8} rx={2} fill={rc} />
        <text x={LABEL_X} y={y + (LH - 8) / 2 - 2} fontFamily="var(--mono)" fontSize={11} fontWeight={600} fill="var(--fg)">{s.id}</text>
        {s.repo && <text x={LABEL_X} y={y + (LH - 8) / 2 + 11} fontFamily="var(--mono)" fontSize={7.5} fill="var(--fg-dim)">⎇ {s.repo}</text>}
      </g>,
    );
  });

  // non-handoff edges (lane-to-lane connectors)
  for (const e of edges) {
    if (e.kind === "handoff" && e.artifact) continue;
    const fy = laneY[e.from], ty = laneY[e.to];
    if (fy == null || ty == null) continue;
    const fx = nodeX(e.from) + NW, tx = nodeX(e.to);
    const km = EDGE_KIND_META[e.kind], hs = hardStyle(e.hardness), cyc = cycleEdgeIds.has(e.id), on = sp.active && sp.litEdges.has(e.id);
    const stroke = cyc ? "var(--danger)" : km.color;
    const w = (cyc ? 2.4 : hs.w) + (on ? 0.8 : 0);
    const op = cyc ? Math.max(edgeOp(e), 0.85) : edgeOp(e);
    const sx = tx >= fx ? fx : nodeX(e.from), ex2 = tx >= fx ? tx : nodeX(e.to) + NW, dir = tx >= fx ? 1 : -1;
    els.push(<path key={`le${e.id}`} d={`M${sx},${fy} C${sx + 40 * dir},${fy} ${ex2 - 40 * dir},${ty} ${ex2},${ty}`} stroke={stroke} strokeWidth={w} strokeDasharray={cyc ? "" : hs.dash} fill="none" opacity={op} onClick={() => onInspectEdge(e.id)} style={{ cursor: "pointer" }} />);
    els.push(<Arrow key={`laa${e.id}`} x={ex2} y={ty} ang={dir > 0 ? 0 : Math.PI} c={stroke} op={op} />);
  }

  // handoffs via artifact tokens
  for (const a of artifacts) {
    const py = laneY[a.producer]; if (py == null) continue;
    const px = nodeX(a.producer) + NW + 26;
    const ac = ARTIFACT_COLOR[a.kind] ?? "var(--accent)", rdy = a.status === "ready";
    const on = sp.active && sp.litArtifacts.has(a.id);
    const aop = sp.active ? (on ? 1 : 0.07) : 0.95;
    els.push(<line key={`pt${a.id}`} x1={nodeX(a.producer) + NW} y1={py} x2={px - 10} y2={py} stroke="var(--accent)" strokeWidth={2} opacity={aop} />);
    a.consumers.forEach((c, ci) => {
      const cy2 = laneY[c]; if (cy2 == null) return;
      const cxn = nodeX(c);
      const eid = edges.find((e) => e.from === a.producer && e.to === c && e.kind === "handoff")?.id;
      els.push(<path key={`ht${a.id}${ci}`} d={`M${px},${py} C${px + 26},${py} ${cxn - 28},${cy2} ${cxn},${cy2}`} stroke="var(--accent)" strokeWidth={on ? 2.8 : 2} fill="none" opacity={aop} onClick={eid ? () => onInspectEdge(eid) : undefined} style={eid ? { cursor: "pointer" } : undefined} />);
      els.push(<Arrow key={`hta${a.id}${ci}`} x={cxn} y={cy2} ang={0} c="var(--accent)" op={aop} />);
    });
    const r = on ? 9.5 : 8;
    els.push(<polygon key={`ldia${a.id}`} points={`${px},${py - r} ${px + r},${py} ${px},${py + r} ${px - r},${py}`} fill={rdy ? "color-mix(in oklch, var(--success), transparent 50%)" : "var(--bg-elev)"} stroke={on ? "var(--accent)" : ac} strokeWidth={on ? 2 : 1.6} opacity={aop} onClick={() => onInspectArtifact(a.id)} style={{ cursor: "pointer" }} />);
    els.push(<text key={`ldt${a.id}`} x={px} y={py - 12} textAnchor="middle" fontFamily="var(--mono)" fontSize={8} fill={on ? "var(--accent)" : "var(--fg-muted)"} opacity={sp.active ? (on ? 1 : 0.2) : 0.95} style={{ pointerEvents: "none" }}>{a.name}</text>);
  }

  // lane "station" nodes
  for (const s of order) {
    const rc = ROLE_COLOR[s.role ?? ""] ?? "var(--fg-dim)", x = nodeX(s.id), y = laneY[s.id] - NH / 2;
    const isFocus = sp.active && sp.focusType === "agent" && sp.focusId === s.id;
    els.push(
      <g key={`node${s.id}`} onMouseEnter={() => onHover(s.id)} onMouseLeave={() => onHover(null)} onClick={() => onFocusAgent(s.id)} style={{ cursor: "pointer" }} opacity={laneOp(s.id)}>
        <rect x={x} y={y} width={NW} height={NH} rx={6} fill={isFocus ? "color-mix(in oklch, var(--accent), transparent 82%)" : "var(--bg-elev)"} stroke={isFocus ? "var(--accent)" : "var(--border)"} strokeWidth={isFocus ? 1.8 : 1} />
        <circle cx={x + 12} cy={y + NH / 2} r={4} fill={rc} />
        <text x={x + 22} y={y + NH / 2 + 3.4} fontFamily="var(--mono)" fontSize={10.5} fontWeight={600} fill="var(--fg)">{s.id}</text>
      </g>,
    );
  }

  return (
    // eslint-disable-next-line no-restricted-syntax -- scroll container wrapping the measured SVG graph
    <div style={{ overflow: "auto", maxHeight: 440, border: "1px solid var(--border-soft)", borderRadius: 8, background: "var(--bg-panel)" }}>
      <svg width={Math.max(W, 640)} height={H} style={{ display: "block" }} data-testid="relationship-graph-svg" onMouseLeave={() => onHover(null)}>
        {els}
      </svg>
    </div>
  );
}

// RelationshipInspector — the detail panel under the swimlane graph. Spells out the
// focused stream / edge / artifact's relationships in words, with the runtime mechanism
// for each (the coord ref it blocks on, hardness, via). Ported from design/bsc ·
// Agent Relationships - Swimlanes · inspector().

import type { ReactNode } from "react";
import { Chip } from "@/shared/ui/data/Chip";
import { ColorSwatch } from "@/shared/ui/controls/ColorSwatch";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import {
  EDGE_KIND_META, ARTIFACT_COLOR, ROLE_COLOR, DIRECTOR_COLOR, hardLabel, runtimeNote,
  type RelationshipGraph, type RelFocus,
} from "./relationshipGraph";

const mono = "var(--mono)";

// Folded onto the shared color-mix Chip (#2160) — radius 99, no fontWeight; the knobs reproduce it exactly.
function Pill({ text, c }: { text: string; c: string }) {
  return (
    <Chip color={c} bgAlpha={86} borderAlpha={62} fontSize={8} padding="1px 7px" style={{ whiteSpace: "nowrap" }}>{text}</Chip>
  );
}

function RelRow({ glyph, c, head, detail, onClick }: { glyph: string; c: string; head: string; detail?: ReactNode; onClick?: () => void }) {
  return (
    <Row onClick={onClick} gap={9} align="baseline" style={{ padding: "6px 9px", borderRadius: 6, background: "var(--bg-panel)", border: "1px solid var(--border-soft)", cursor: onClick ? "pointer" : "default" }}>
      <Box as="span" style={{ flex: "0 0 16px", textAlign: "center", fontFamily: mono, fontSize: 11, color: c }}>{glyph}</Box>
      <Box style={{ flex: 1, minWidth: 0 }}>
        <Text as="div" size={10.5} style={{ fontFamily: mono, color: "var(--fg)" }}>{head}</Text>
        {detail && <Text as="div" size={8.5} tone="dim" style={{ fontFamily: mono, marginTop: 2, lineHeight: 1.45 }}>{detail}</Text>}
      </Box>
    </Row>
  );
}

function Head({ title, sub, c }: { title: string; sub?: string; c?: string }) {
  return (
    <Row gap={9} style={{ marginBottom: 11 }}>
      <ColorSwatch color={c ?? "var(--accent)"} size={8} />
      <Text as="span" size={12.5} weight={600} style={{ fontFamily: mono, color: "var(--fg)" }}>{title}</Text>
      {sub && <Text as="span" size={9} tone="dim" style={{ fontFamily: mono }}>{sub}</Text>}
    </Row>
  );
}

export function RelationshipInspector({ graph, focus, onFocusAgent, onInspectArtifact, onInspectEdge }: {
  graph: RelationshipGraph;
  focus: RelFocus;
  onFocusAgent: (id: string) => void;
  onInspectArtifact: (id: string) => void;
  onInspectEdge: (id: string) => void;
}) {
  const { streams, artifacts, edges, cycleEdgeIds } = graph;

  if (!focus) {
    const hcount = edges.filter((e) => e.kind === "handoff").length;
    return (
      <Box>
        <Text as="div" size={9} tone="dim" style={{ fontFamily: mono, textTransform: "uppercase", letterSpacing: ".08em", marginBottom: 9 }}>relationship inspector</Text>
        <Row gap={10} style={{ padding: "14px", borderRadius: 8, background: "var(--bg-panel)", border: "1px dashed var(--border)" }}>
          <Text as="span" size={18} style={{ opacity: 0.4 }}>⤚</Text>
          <Box>
            <Text as="div" size={10.5} tone="muted" style={{ fontFamily: mono }}>Hover a stream to spotlight its relationships.</Text>
            <Text as="div" size={9} tone="dim" style={{ fontFamily: mono, marginTop: 3 }}>
              Click to pin · click an artifact or edge to inspect it. {streams.length} streams · {artifacts.length} contracts · {hcount} handoffs.
            </Text>
          </Box>
        </Row>
      </Box>
    );
  }

  if (focus.type === "art") {
    const a = artifacts.find((x) => x.id === focus.id);
    if (!a) return null;
    const ac = ARTIFACT_COLOR[a.kind], rdy = a.status === "ready";
    const ce = edges.filter((e) => e.kind === "handoff" && e.artifact === a.id);
    return (
      <Box>
        <Head title={`contract:${a.id}`} sub={a.kind} c={ac} />
        <Stack gap={6}>
          <RelRow glyph="▲" c="var(--accent)" head={`produced by ${a.producer}`} detail={`publishes the ${a.kind} · status ${rdy ? "ready" : "pending"}`} onClick={() => onFocusAgent(a.producer)} />
          {a.consumers.map((c) => {
            const e = ce.find((x) => x.to === c);
            return <RelRow key={c} glyph="⤓" c="var(--accent)" head={`${c} consumes it`} detail={`held at launch until contract:${a.id} lands${e ? ` · ${hardLabel(e.hardness)} · via ${e.viaEff}` : ""}`} onClick={() => onFocusAgent(c)} />;
          })}
          <Text as="div" size={8.5} tone="dim" style={{ fontFamily: mono, marginTop: 2 }}>
            {rdy ? "● ready — parked consumers have been satisfied & woken." : `○ pending — consumers wait until ${a.producer} lands it.`}
          </Text>
        </Stack>
      </Box>
    );
  }

  if (focus.type === "edge") {
    const e = edges.find((x) => x.id === focus.id);
    if (!e) return null;
    const km = EDGE_KIND_META[e.kind], cyc = cycleEdgeIds.has(e.id);
    return (
      <Box>
        <Head title={`${e.from} → ${e.to}`} sub={e.kind} c={cyc ? "var(--danger)" : km.color} />
        <Row gap={6} wrap align="stretch" style={{ marginBottom: 10 }}>
          <Pill text={km.label} c={km.color} />
          <Pill text={hardLabel(e.hardness)} c="var(--info)" />
          <Pill text={`via ${e.viaEff}`} c={e.viaEff === "director" ? DIRECTOR_COLOR : "var(--fg-muted)"} />
          {e.artifact && <Pill text={`contract:${e.artifact}`} c="var(--accent)" />}
        </Row>
        <Box pad={[8, 10]} bg="var(--bg-panel)" border="soft" radius={6} style={{ fontFamily: mono, fontSize: 9, color: "var(--fg-muted)", lineHeight: 1.6}}>
          {runtimeNote(e)}
        </Box>
        {cyc && <Text as="div" size={9} tone="danger" style={{ fontFamily: mono, marginTop: 8 }}>⚠ part of a dependency cycle — this blocks the structure gate.</Text>}
      </Box>
    );
  }

  // agent
  const a = streams.find((s) => s.id === focus.id);
  if (!a) return null;
  const rc = ROLE_COLOR[a.role ?? ""] ?? "var(--fg-dim)";
  const produces = artifacts.filter((x) => x.producer === a.id);
  const consumes = artifacts.filter((x) => x.consumers.includes(a.id));
  const others = edges.filter((e) => (e.from === a.id || e.to === a.id) && e.kind !== "handoff");
  const rows: ReactNode[] = [];
  produces.forEach((x) => rows.push(<RelRow key={`p${x.id}`} glyph="▲" c="var(--accent)" head={`produces contract:${x.id}`} detail={`→ ${x.consumers.join(", ") || "no consumers"} · ${x.status === "ready" ? "ready" : "pending"}`} onClick={() => onInspectArtifact(x.id)} />));
  consumes.forEach((x) => {
    const e = edges.find((ed) => ed.from === x.producer && ed.to === a.id && ed.kind === "handoff");
    rows.push(<RelRow key={`co${x.id}`} glyph="⤓" c="var(--accent)" head={`waits on contract:${x.id}`} detail={`from ${x.producer} · ${e ? `${hardLabel(e.hardness)} · via ${e.viaEff}` : ""} · ${x.status === "ready" ? "satisfied" : "pending"}`} onClick={() => onInspectArtifact(x.id)} />);
  });
  others.forEach((e) => {
    const out = e.from === a.id, other = out ? e.to : e.from, km = EDGE_KIND_META[e.kind];
    let phrase: string;
    if (e.kind === "blocking") phrase = out ? `blocks ${other}` : `blocks on ${other}`;
    else if (e.kind === "sequence") phrase = out ? `runs before ${other}` : `runs after ${other}`;
    else if (e.kind === "shared") phrase = `co-owns interface with ${other}`;
    else if (e.kind === "mutex") phrase = `mutex (serialized) with ${other}`;
    else if (e.kind === "review") phrase = out ? `reviews ${other}` : `reviewed by ${other}`;
    else phrase = out ? `notifies ${other}` : `notified by ${other}`;
    rows.push(<RelRow key={`o${e.id}`} glyph={km.glyph} c={cycleEdgeIds.has(e.id) ? "var(--danger)" : km.color} head={phrase} detail={`${km.label} · ${hardLabel(e.hardness)} · via ${e.viaEff}`} onClick={() => onInspectEdge(e.id)} />);
  });
  return (
    <Box>
      <Head title={a.id} sub={`${a.role ?? "stream"} · ⎇ ${a.repo ?? ""}`} c={rc} />
      {(a.owns?.length ?? 0) > 0 && (
        <Row gap={5} wrap align="stretch" style={{ marginBottom: 11 }}>
          {a.owns!.map((o) => <Box as="span" key={o} pad={[1, 6]} bg="var(--bg-elev)" border="soft" radius={3} style={{ fontFamily: mono, fontSize: 8.5, color: "var(--fg-muted)" }}>{o}</Box>)}
        </Row>
      )}
      <Text as="div" size={9} tone="dim" style={{ fontFamily: mono, textTransform: "uppercase", letterSpacing: ".08em", marginBottom: 8 }}>relationships ({rows.length})</Text>
      {rows.length ? <Stack gap={6}>{rows}</Stack> : <Text as="div" size={9.5} tone="dim" style={{ fontFamily: mono }}>No cross-stream relationships.</Text>}
    </Box>
  );
}

runtime.features/planner/session/draftTitle.ts:
// Commit a DRAFT project's title edit (#1222) — the pure guard, extracted from Planning.tsx so
// it's unit-testable. The draft record (localDraftProjects[key].title, persisted) is the source of
// truth a reopen reads, so persisting the edit there is what makes it survive. The FROZEN key is
// kept — renames are display-only (#2409): the on-disk folder keeps its birth-slug.

import { projectSlug } from "@/shared/lib/core/projectPaths";

export type DraftCommit =
  | { kind: "revert" }                       // empty → restore the saved title
  | { kind: "noop" }                         // unchanged
  | { kind: "error"; message: string }       // collides with another project
  | { kind: "commit"; title: string };       // persist the new title

/**
 * Decide what blurring/Entering the draft title input should do, given the raw input, the saved
 * draft title, and the OTHER projects' keys (drafts + published aliases) for the duplicate guard.
 * Empty reverts; unchanged no-ops; a name that slugifies onto another project's key errors;
 * otherwise commit the trimmed title.
 */
export function planDraftCommit(raw: string, saved: string, otherKeys: ReadonlySet<string>): DraftCommit {
  const next = raw.trim();
  if (!next) return { kind: "revert" };
  if (next === saved) return { kind: "noop" };
  // Keys are name-derived slugs (#2409): a title whose slug lands on another project's key would
  // make two names resolve to ONE hub at reopen — block it here.
  if (otherKeys.has(projectSlug(next))) {
    return { kind: "error", message: "Another project already uses that name." };
  }
  return { kind: "commit", title: next };
}

runtime.features/planner/session/GitHubStructure:
// GitHub structure card, split out of Planning.tsx (#1332).
//
// A live map of the GitHub objects this plan produces. Each node mirrors a real GitHub primitive
// (repository, project board, milestone, issue) and carries a status that the publish flow updates
// in place so the user can watch each object get created.
import type { GhNode, GhRepoNode, GhStructure } from "../github/ghStructure";
import { Card } from "@/shared/ui/data/Card";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

export type GhItemStatus = "planned" | "running" | "created" | "exists" | "skipped" | "error";
export interface GhItemState { status: GhItemStatus; detail?: string; url?: string; }
export type GhStatusMap = Record<string, GhItemState>;

const GH_STATUS_GLYPH: Record<GhItemStatus, { icon: string; color: string }> = {
  planned: { icon: "○", color: "var(--fg-dim)" },
  running: { icon: "⟳", color: "var(--accent)" },
  created: { icon: "✓", color: "var(--success)" },
  exists:  { icon: "=", color: "var(--info)" },
  skipped: { icon: "–", color: "var(--fg-dim)" },
  error:   { icon: "✗", color: "var(--danger)" },
};

function GhItemRow({ node, state }: { node: GhNode; state: GhItemState }) {
  const g = GH_STATUS_GLYPH[state.status];
  return (
    <Row className="mono" align="baseline" gap={8} style={{
      fontSize: 10.5,
      opacity: state.status === "planned" ? 0.6 : 1,
    }}>
      <Box as="span" style={{ width: 11, textAlign: "center", flexShrink: 0, color: g.color }}>{g.icon}</Box>
      <Box as="span" style={{
        color: state.status === "error" ? "var(--danger)" : "var(--fg)",
        overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap",
      }}>{node.label}</Box>
      {state.url ? (
        <a href={state.url} target="_blank" rel="noreferrer"
          style={{ color: "var(--fg-dim)", fontSize: 9.5, textDecoration: "none" }}
          title={state.url}>
          {state.detail ?? "open"} ↗
        </a>
      ) : state.detail ? (
        <Text as="span" tone="dim" size={9.5}>· {state.detail}</Text>
      ) : null}
    </Row>
  );
}

function GhGroup({ title, count, nodes, status, empty }: {
  title: string; count?: number; nodes: GhNode[]; status: GhStatusMap; empty?: string;
}) {
  return (
    <Stack gap={5}>
      <Row className="mono" gap={6} style={{
        fontSize: 9.5, textTransform: "uppercase",
        letterSpacing: ".06em", color: "var(--fg-muted)",
      }}>
        <Box as="span">{title}</Box>
        {count !== undefined && <Text as="span" tone="dim">{count}</Text>}
      </Row>
      {nodes.length === 0
        ? <Text as="div" mono size={10} tone="dim" style={{ opacity: 0.6, paddingLeft: 19 }}>{empty}</Text>
        : (
          <Stack gap={3} style={{ paddingLeft: 8 }}>
            {nodes.map(n => (
              <GhItemRow key={n.id} node={n} state={status[n.id] ?? { status: "planned" }} />
            ))}
          </Stack>
        )
      }
    </Stack>
  );
}

// Repositories group: each repo row owns its phase tracking issues, indented
// beneath it with a connector so issue ownership is clear at a glance.
function GhReposGroup({ repos, status }: { repos: GhRepoNode[]; status: GhStatusMap }) {
  return (
    <Stack gap={5}>
      <Row className="mono" gap={6} style={{
        fontSize: 9.5, textTransform: "uppercase",
        letterSpacing: ".06em", color: "var(--fg-muted)",
      }}>
        <Box as="span">Repositories</Box>
        <Text as="span" tone="dim">{repos.length}</Text>
      </Row>
      {repos.length === 0
        ? <Text as="div" mono size={10} tone="dim" style={{ opacity: 0.6, paddingLeft: 19 }}>
            none linked — ask Claude to create or link repositories
          </Text>
        : (
          <Stack gap={8} style={{ paddingLeft: 8 }}>
            {repos.map(r => (
              <Stack key={r.node.id} gap={3}>
                <GhItemRow node={r.node} state={status[r.node.id] ?? { status: "planned" }} />
                {r.issues.length > 0 && (
                  <Stack gap={2} style={{
                    paddingLeft: 14, marginLeft: 5,
                    borderLeft: "1px solid var(--border-soft)",
                  }}>
                    {r.issues.map(iss => (
                      <GhItemRow key={iss.id} node={iss} state={status[iss.id] ?? { status: "planned" }} />
                    ))}
                  </Stack>
                )}
              </Stack>
            ))}
          </Stack>
        )
      }
    </Stack>
  );
}

export function GitHubStructureCard({ structure, status }: { structure: GhStructure; status: GhStatusMap }) {
  return (
    <Card tone="var(--info)" style={{ padding: "12px 14px", flexShrink: 0 }}>
      <Stack gap={12}>
        <Text as="div" mono size={10} style={{
          color: "var(--info)", textTransform: "uppercase", letterSpacing: ".06em",
        }}>
          github structure
        </Text>
        <GhGroup title="Project board" nodes={[structure.project]} status={status} />
        <GhReposGroup repos={structure.repos} status={status} />
        {structure.streams.length > 0 && (
          <GhGroup
            title="Agents"
            count={structure.streams.length}
            nodes={structure.streams.map(s => ({ id: s.id, label: `${s.label} · stream:${s.id.replace(/^stream:/, "")}` }))}
            status={status}
          />
        )}
      </Stack>
    </Card>
  );
}

runtime.features/planner/session/InjectionGateBa:
// The plan-injection provenance banner (#1107). Surfaces the markers the deterministic scan flagged
// in the planner's authored sections, at the planning pane's top, so the user reviews them before
// the plan seeds the fleet. Acknowledge-to-clear by default; the hard-gate setting turns the ack off
// and demands the flagged content be removed.

import { type InjectionGate, injectionSignature } from "../lib/planInjection";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

const MONO = "var(--mono)";
const CAT_LABEL: Record<string, string> = {
  override: "instruction override", exfiltration: "exfiltration",
  perms: "permission bypass", destructive: "destructive git/gh", ci: "CI / hook tampering",
};

export function InjectionGateBanner({ gate, onAcknowledge }: {
  gate: InjectionGate;
  onAcknowledge: (signature: string) => void;
}) {
  if (gate.findings.length === 0) return null;
  const blocked = gate.mode === "blocked";
  const cleared = gate.cleared;
  const color = blocked ? "var(--danger)" : cleared ? "var(--success)" : "var(--accent)";
  const n = gate.findings.length;

  return (
    <Box data-testid="injection-banner" bg={`color-mix(in oklch, ${color}, transparent 90%)`} radius="md" style={{
      flex: "0 0 auto", margin: "10px 12px 0", overflow: "hidden",
      border: `1px solid color-mix(in oklch, ${color}, transparent 60%)`,
    }}>
      <Row gap={8} style={{ padding: "8px 11px" }}>
        <Text as="span" size={13} style={{ color }}>{blocked ? "⛔" : cleared ? "✓" : "⚠"}</Text>
        <Text as="span" size={11} weight={600} style={{ fontFamily: MONO, color }}>
          {n} possible prompt-injection marker{n !== 1 ? "s" : ""} in the plan
        </Text>
        <Box as="span" style={{ flex: 1 }} />
        <Text as="span" size={9} tone="dim" style={{ fontFamily: MONO }}>
          {blocked ? "hard-block" : cleared ? "reviewed" : "review to publish"}
        </Text>
      </Row>

      <Stack gap={4} style={{ padding: "0 11px 9px", maxHeight: 160, overflowY: "auto" }}>
        {gate.findings.map((f, i) => (
          <Text as="div" key={`${f.file}-${f.line}-${i}`} size={9.5} tone="muted" style={{ fontFamily: MONO, lineHeight: 1.45 }}>
            <Text as="span" style={{ color: "var(--info)" }}>{f.file}:{f.line}</Text>
            {" · "}<Text as="span" style={{ color }}>{CAT_LABEL[f.category] ?? f.category}</Text>
            <Text as="div" tone="dim" style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{f.context}</Text>
          </Text>
        ))}
      </Stack>

      <Row gap={8} style={{ padding: "8px 11px", borderTop: `1px solid color-mix(in oklch, ${color}, transparent 70%)` }}>
        <Text as="span" size={9} tone="dim" style={{ fontFamily: MONO, flex: 1, lineHeight: 1.5 }}>
          {blocked
            ? "These read like instructions injected from reviewed content. Remove them from the plan to publish (hard-block is on in Settings)."
            : "Confirm none of these is an instruction smuggled in from a reviewed repo or page before it seeds the fleet."}
        </Text>
        {!blocked && !cleared && (
          // eslint-disable-next-line no-restricted-syntax -- bespoke inline-styled banner ack button (accent-fill, banner-scoped styling, not the .btn kit)
          <button
            data-testid="injection-ack"
            onClick={() => onAcknowledge(injectionSignature(gate.findings))}
            style={{
              flex: "0 0 auto", fontFamily: MONO, fontSize: 10, fontWeight: 600, color: "oklch(0.20 0.04 70)",
              background: "var(--accent)", border: "none", borderRadius: "var(--r-sm)", padding: "5px 11px", cursor: "pointer", whiteSpace: "nowrap",
            }}
          >I&apos;ve reviewed these</button>
        )}
      </Row>
    </Box>
  );
}

runtime.features/planner/session/planAutopilot.t:
// Planning autopilot (#682, Phase 1) — the PURE decision core that drives a planning
// session to a complete plan with a SIMULATED user. The live runner (PTY + Claude + store
// actions) wires these into the real session; this module is React/Tauri-free and fully
// unit-testable.
//
// The planning loop has three actors: the planner (Claude, autonomous), the user (simulated
// here), and the app (confirms sections, advances, publishes). The driver decides, each
// tick, what the user/app should do next given the planning state.

import type { Stage } from "../stages/focusedPlan";
import autopilotSimEmbedded from "@data/planner/autopilot-sim.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";
import { fillTemplate } from "@/shared/lib/core/template";

// The simulated-user PROSE (system prompt, user-turn template, canned replies) is externalized to
// `@data/planner/autopilot-sim.json` (#2416) — editable without touching code + part of the exportable
// config bundle; the config-dir copy (#2047) overlays the embedded default via `overlayFile`. This
// module keeps only the interpolation (`{{PITCH}}` / `{{PLANNER_OUTPUT}}`) and the strategy logic.
const SIM_PROSE = overlayFile("planner/autopilot-sim.json", autopilotSimEmbedded);

/** How the simulated user answers the planner. Phase 1 wires `llm`; the rest are Phase 2. */
export type AutopilotStrategy = "llm" | "scripted" | "random" | "none";

/** The next thing the driver should do. */
export type AutopilotAction =
  | { kind: "publish" }                  // the plan is complete → publish (MOCKED in the harness)
  | { kind: "done" }                     // finished (already published / nothing left)
  | { kind: "confirm"; keys: string[] }  // confirm the active stage's sections → advances its gate
  | { kind: "reply" }                    // planner is awaiting input → send a simulated-user reply
  | { kind: "wait" }                     // planner is still working → poll again next tick
  | { kind: "stall"; reason: string };   // no progress / cap hit → stop

/** Everything the driver needs to decide, computed by the runner from the live plan state. */
export interface AutopilotContext {
  /** Whole plan is publishable (planStagesComplete over the blueprint). */
  planReady: boolean;
  /** Whether publish has already fired (so we don't loop on it). */
  published: boolean;
  /** The active stage's confirmable section keys, NON-EMPTY only when the stage has produced
   *  enough to confirm (its required content exists). Empty ⇒ the stage still needs work. */
  confirmKeys: string[];
  /** The planner finished its turn and is waiting for input (idle-detected by the runner). */
  plannerAwaiting: boolean;
  /** Tick counter + hard cap — the ultimate runaway guard. */
  iteration: number;
  maxIterations: number;
  /** Consecutive ticks with no forward progress while idle — the stall guard. */
  idleStreak: number;
  maxIdle: number;
  /** Whether to (mock-)publish on completion. The Settings FEATURE stops at a publishable
   *  plan for review (false); the dev harness mock-publishes (true). (#682) */
  autoPublish: boolean;
}

/**
 * Decide the next autopilot action from the current planning state. Priority:
 * cap → publish/done → (while the planner waits) confirm-if-ready else reply → stall-if-stuck
 * → wait. Pure + deterministic.
 */
export function decideAutopilotAction(ctx: AutopilotContext): AutopilotAction {
  if (ctx.iteration >= ctx.maxIterations) {
    return { kind: "stall", reason: `hit the ${ctx.maxIterations}-iteration cap` };
  }
  if (ctx.planReady) {
    if (!ctx.autoPublish) return { kind: "done" }; // feature: stop at a publishable plan for review
    return ctx.published ? { kind: "done" } : { kind: "publish" };
  }
  // Stall on no forward progress — checked BEFORE the await branch so a non-responding user
  // (the `none` strategy) stalls instead of replying-with-nothing forever (#682, Phase 2).
  if (ctx.idleStreak >= ctx.maxIdle) {
    return { kind: "stall", reason: `no progress for ${ctx.idleStreak} ticks` };
  }
  if (ctx.plannerAwaiting) {
    // Stage has its required content → confirm it (which advances the gate). Otherwise the
    // planner's turn is done but the stage isn't ready, so answer its questions to continue.
    return ctx.confirmKeys.length > 0 ? { kind: "confirm", keys: ctx.confirmKeys } : { kind: "reply" };
  }
  return { kind: "wait" };
}

/**
 * The system + user prompt for the simulated-user (`llm` strategy): a product owner being
 * interviewed by the planner. Decisive, concrete, consistent with the pitch, no questions back.
 */
export function buildUserSimPrompt(pitch: string, plannerOutput: string): { system: string; user: string } {
  return {
    system: SIM_PROSE.system,
    user: fillTemplate(SIM_PROSE.userTemplate, {
      PITCH: pitch.trim(),
      PLANNER_OUTPUT: plannerOutput.trim(),
    }),
  };
}

/** Canned fuzz replies for the `random` strategy (Phase 2) — deliberately noisy/terse. */
const RANDOM_REPLIES: string[] = SIM_PROSE.randomReplies;

/**
 * A non-LLM simulated-user reply (Phase 2 strategies). `none` sends nothing (stall test);
 * `random` returns canned fuzz; `scripted` is a generic affirmative; `llm` is handled async
 * by the runner via {@link buildUserSimPrompt} and returns null here.
 */
export function staticReply(strategy: AutopilotStrategy, seed: number): string | null {
  switch (strategy) {
    case "none": return null;
    case "random": return RANDOM_REPLIES[Math.abs(Math.trunc(seed)) % RANDOM_REPLIES.length];
    case "scripted": return SIM_PROSE.scriptedReply;
    case "llm": return null;
  }
}

/** Progress fraction (0..1) over the visible stages — how far the plan got. */
export function autopilotProgress(stages: Stage[]): { done: number; total: number; fraction: number } {
  const total = stages.length;
  const done = stages.filter((p) => p.status === "complete" || p.status === "ahead").length;
  return { done, total, fraction: total ? done / total : 0 };
}

/** Outcome of an autopilot run — what the runner reports + the transcript inspector shows. */
export interface AutopilotResult {
  completed: boolean;
  published: boolean;
  iterations: number;
  progress: { done: number; total: number; fraction: number };
  stalledReason?: string;
}

runtime.features/planner/session/planAutopilotRu:
// Planning autopilot runner (#682, Phase 1b) — the live loop that drives a real planning
// session with the simulated user, built on the pure core (planAutopilot.ts).
//
// `autopilotTick` runs ONE step (read state → decide → execute) and is pure of timers/React,
// so it's unit-testable with injected deps. `usePlanAutopilot` runs it on a guarded interval
// and is the thin, manual-test wiring. Publish is MOCKED via deps — the harness never mutates
// real GitHub.

import { useEffect, useRef, useState } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import {
  decideAutopilotAction, buildUserSimPrompt, staticReply, type AutopilotResult, type AutopilotStrategy,
} from "./planAutopilot";

/** The live planning state the runner reads each tick (computed by the host component). */
export interface AutopilotSnapshot {
  planReady: boolean;
  /** Active stage's confirmable section keys — non-empty only when the stage is ready. */
  confirmKeys: string[];
  /** Planner finished its turn and is awaiting input (idle-detected by the host). */
  plannerAwaiting: boolean;
  /** The planner produced new output since the last tick — forward progress, resets idle. */
  working: boolean;
  /** (Mock-)publish on completion vs stop at a publishable plan for review (#682). */
  autoPublish: boolean;
  progress: { done: number; total: number; fraction: number };
}

/** Injected effects — the host wires these to the real session/store (or fakes, in tests). */
export interface AutopilotDeps {
  pitch: string;
  /** How the simulated user answers: `llm` (Claude), or `scripted`/`random`/`none` (Phase 2). */
  strategy: AutopilotStrategy;
  snapshot: () => AutopilotSnapshot;
  /** The planner's output since the last reply (for the user-sim). */
  pendingOutput: () => string;
  /** Generate a simulated-user reply (the llm strategy → a Claude completion). */
  userSim: (system: string, user: string) => Promise<string>;
  /** Send a line of input to the planner session. */
  sendReply: (text: string) => void;
  /** Confirm the given sections + advance the stage. */
  confirm: (keys: string[]) => void;
  /** MOCKED publish — record only; never touch real GitHub. */
  mockPublish: () => void;
  log: (e: AutopilotLogEntry) => void;
}

export interface AutopilotLogEntry { tick: number; action: string; detail?: string }

export interface AutopilotRunState {
  iteration: number;
  idleStreak: number;
  published: boolean;
  finished: boolean;
  result?: AutopilotResult;
}

export const initRunState = (): AutopilotRunState =>
  ({ iteration: 0, idleStreak: 0, published: false, finished: false });

/** Runaway + stall guards. */
export const MAX_ITERATIONS = 60;
export const MAX_IDLE = 6;

const finish = (state: AutopilotRunState, snap: AutopilotSnapshot, completed: boolean, stalledReason?: string): AutopilotResult =>
  ({ completed, published: state.published, iterations: state.iteration, progress: snap.progress, stalledReason });

/**
 * Run one autopilot tick: snapshot the plan → decide → execute the action. Returns the next
 * run state. Timer-/React-free so it's directly unit-testable with injected {@link AutopilotDeps}.
 */
export async function autopilotTick(state: AutopilotRunState, deps: AutopilotDeps): Promise<AutopilotRunState> {
  if (state.finished) return state;
  const snap = deps.snapshot();
  // Active planner output is forward progress — never count it as idle.
  const idle = snap.working ? 0 : state.idleStreak;
  const action = decideAutopilotAction({
    planReady: snap.planReady,
    published: state.published,
    confirmKeys: snap.confirmKeys,
    plannerAwaiting: snap.plannerAwaiting,
    iteration: state.iteration,
    maxIterations: MAX_ITERATIONS,
    idleStreak: idle,
    maxIdle: MAX_IDLE,
    autoPublish: snap.autoPublish,
  });
  const next: AutopilotRunState = { ...state, iteration: state.iteration + 1, idleStreak: idle };

  switch (action.kind) {
    case "reply": {
      // `llm` asks Claude; the other strategies use a canned reply (`none` sends nothing,
      // which lets idle climb to a stall — the "no response" test). (#682, Phase 2)
      let reply: string | null;
      if (deps.strategy === "llm") {
        const { system, user } = buildUserSimPrompt(deps.pitch, deps.pendingOutput());
        reply = await deps.userSim(system, user);
      } else {
        reply = staticReply(deps.strategy, state.iteration);
      }
      if (reply !== null) {
        deps.sendReply(reply);
        deps.log({ tick: state.iteration, action: "reply", detail: reply.slice(0, 80) });
        next.idleStreak = 0;
      } else {
        deps.log({ tick: state.iteration, action: "reply", detail: "(none — sent nothing)" });
        next.idleStreak = idle + 1;
      }
      break;
    }
    case "confirm":
      deps.confirm(action.keys);
      deps.log({ tick: state.iteration, action: "confirm", detail: action.keys.join(", ") });
      next.idleStreak = 0;
      break;
    case "publish":
      deps.mockPublish();
      deps.log({ tick: state.iteration, action: "publish (mocked)" });
      next.published = true;
      break;
    case "done":
      next.finished = true;
      next.result = finish(state, snap, true);
      deps.log({ tick: state.iteration, action: "done" });
      break;
    case "stall":
      next.finished = true;
      next.result = finish(state, snap, false, action.reason);
      deps.log({ tick: state.iteration, action: "stall", detail: action.reason });
      break;
    case "wait":
      next.idleStreak = idle + 1;
      break;
  }
  return next;
}

/**
 * The thin React wiring: while `enabled`, runs {@link autopilotTick} on a guarded interval
 * (no overlapping ticks) until the run finishes/stalls. Driven entirely by the Settings
 * toggle — enabling it kicks off the planner from wherever it currently is; disabling stops
 * it; re-enabling starts a fresh run. Manual-test-only — the testable logic lives in
 * `autopilotTick`.
 */
export function usePlanAutopilot(deps: AutopilotDeps, opts: { enabled: boolean; tickMs?: number }) {
  const { enabled, tickMs = 3500 } = opts;
  const [state, setState] = useState<AutopilotRunState>(initRunState());
  const stateRef = useRef(state);
  const depsRef = useRef(deps);
  const ticking = useRef(false);
  const wasEnabled = useRef(false);
  stateRef.current = state;
  depsRef.current = deps;

  // A fresh enable starts a fresh run (resets the autopilot's counters; the planner stays
  // wherever it is, so the run picks up from any point in the planning process).
  useEffect(() => {
    if (enabled && !wasEnabled.current) setState(initRunState());
    wasEnabled.current = enabled;
  }, [enabled]);

  // No immediate first tick: the interval-only original waited `tickMs` before the first step, so
  // `{ immediate: false }`. The reentrancy/finished guard stays inside the callback (no overlapping
  // ticks); disabling stops the run (the callback no-ops until deps re-subscribe on re-enable).
  usePoll(() => {
    if (!enabled || ticking.current || stateRef.current.finished) return;
    ticking.current = true;
    void autopilotTick(stateRef.current, depsRef.current)
      .then(setState)
      .catch((e) => {
        depsRef.current.log({ tick: stateRef.current.iteration, action: "error", detail: String(e) });
      })
      .finally(() => { ticking.current = false; });
  }, tickMs, [enabled, tickMs], { immediate: false });

  return { running: enabled && !state.finished, state };
}

runtime.features/planner/session/planBoardProjec:
// planBoardProjection (#2498) — the pure builder behind the `plan` store_state domain: the
// stage/gate board the mobile Planner page renders. COMPLEMENTS the existing `plan_state`
// frame (files + transcript, usePlannerTunnelSync) rather than duplicating it: this payload
// carries the DERIVED board — the focused-pane stage list with per-stage status + unmet gate
// reasons (the same `stagesFrom` output the desktop stepper renders), confirmed/skipped sets,
// the fleet streams, and the deploy/market summaries. Pure (no React/Tauri) so the shape is
// unit-testable from fixtures.

import type { Stage } from "../stages/focusedPlan";
import type { FleetPlan } from "../fleet/planFleet";
import { deploymentDefined, type DeployConfig } from "../lib/deployConfig";
import { marketDefined, type MarketConfig } from "../lib/marketConfig";

export interface PlanBoardStage {
  key: string;
  name: string;
  glyph: string;
  status: Stage["status"];
  /** Gate fill 0..1. */
  fraction: number;
  optional?: boolean;
  /** The still-unmet gate requirements (empty once the gate passes). */
  unmet: { label: string; detail?: string }[];
}

export interface PlanBoardStream {
  id: string;
  name: string;
  repo: string;
  issues: number;
  dependsOn: string[];
  persona?: string;
}

export interface PlanBoardPayload {
  projectId: string;
  title: string;
  currentStage: string;
  /** "complete" | "in_progress" | "starting" — the same label plan_status carries. */
  statusLabel: string;
  /** The active stage's gate passed — the user-only confirm is what advances it. */
  gateReady: boolean;
  planComplete: boolean;
  stages: PlanBoardStage[];
  confirmed: string[];
  skipped: string[];
  streams: PlanBoardStream[];
  directorEnabled: boolean;
  deploy: { defined: boolean; services: { id: string; repo: string; platform: string; workload: string }[] };
  market: { defined: boolean; summary: string; recommendation?: string };
}

export function buildPlanBoardPayload(input: {
  projectId: string;
  title: string;
  currentStage: string;
  statusLabel: string;
  gateReady: boolean;
  planComplete: boolean;
  stages: Stage[];
  confirmed: ReadonlySet<string> | string[];
  skipped: ReadonlySet<string> | string[];
  fleet?: FleetPlan;
  deploy?: DeployConfig;
  market?: MarketConfig;
}): PlanBoardPayload {
  return {
    projectId: input.projectId,
    title: input.title,
    currentStage: input.currentStage,
    statusLabel: input.statusLabel,
    gateReady: input.gateReady,
    planComplete: input.planComplete,
    stages: input.stages.map((s) => ({
      key: s.key, name: s.name, glyph: s.glyph, status: s.status,
      fraction: s.fraction, optional: s.optional, unmet: s.unmet ?? [],
    })),
    confirmed: [...input.confirmed].sort(),
    skipped: [...input.skipped].sort(),
    streams: (input.fleet?.streams ?? []).map((st) => ({
      id: st.id, name: st.name, repo: st.repo,
      issues: st.issues.length, dependsOn: st.dependsOn, persona: st.persona,
    })),
    directorEnabled: input.fleet?.director?.enabled ?? false,
    deploy: {
      defined: deploymentDefined(input.deploy),
      services: (input.deploy?.services ?? []).map((sv) => ({
        id: sv.id, repo: sv.repo, platform: sv.platform, workload: sv.workload,
      })),
    },
    market: {
      defined: marketDefined(input.market),
      summary: input.market?.summary ?? "",
      recommendation: input.market?.verdict?.recommendation,
    },
  };
}

runtime.features/planner/session/plannerConducto:
// The planning conductor (#…): drives the planner step by step. Instead of front-loading the
// whole spec, the app injects ONE prompt at a time — the active stage's prompt for orientation,
// then each of its substeps in turn, AND for a loop substep (the feature workshop) it steps
// through the items one by one as each completes. This file is the pure decision ("what to
// inject next"); the wiring (pty_write + idle timing + the injected-once guard + building the
// ConductorState) lives in Planning.tsx. No React/Tauri — unit-testable.
import type { BlueprintStage, ModelCapabilityTier } from "../stages/blueprints";
import { resolveStagePrompt } from "../stages/blueprints";
import { activeSubstep } from "../stages/planSubsteps";

export interface StagePrompt {
  /** Human label for the picker row (the stage name, or a substep's label/key). */
  label: string;
  /** The full prompt text to inject when the user picks it. */
  text: string;
}

/**
 * The SINGLE most relevant prompt for a stage's CURRENT step (#2859), surfaced in the focused pane's
 * "?" helper — one prompt at a time instead of the whole list. The active step is the first
 * not-yet-finished substep ({@link activeSubstep}); when the stage has no substeps (or they're all
 * finished) it's the stage's own overview prompt (adapted to the driving model's capability `tier`
 * via {@link resolveStagePrompt}, #1854 Phase a). Returns null when the stage has no prompt at all.
 *
 * `done` = the substep keys already resolved (a section file written / a step confirmed); `loopDone`
 * = whether the stage's loop substep (the feature workshop) is complete. Pure + unit-tested.
 */
export function activeStagePrompt(
  section: BlueprintStage | undefined,
  done: Set<string>,
  loopDone = false,
  tier?: ModelCapabilityTier,
): StagePrompt | null {
  if (!section) return null;
  const active = activeSubstep(section.substeps, done, loopDone);
  if (active?.prompt?.trim()) return { label: active.label || active.key, text: active.prompt };
  const overview = resolveStagePrompt(section, tier);
  return overview.trim() ? { label: `${section.name} — overview`, text: overview } : null;
}

export interface Injection {
  /** Stable id for the injected-once guard. Forms: `${stage}:_stage`, `${stage}:${substep}`,
   *  or `${stage}:${substep}:${itemId}` for one iteration of a loop substep. */
  id: string;
  prompt: string;
}

export interface LoopItem {
  id: string;
  label: string;
  /** Whether this item is fully done (e.g. a feature with behavior + acceptance). */
  done: boolean;
}

export interface ConductorState {
  /** Static substep keys considered complete — a confirmed discovery section, or a synthetic
   *  marker like "propose" (set once the feature list exists). */
  doneSubsteps: Set<string>;
  /** Ordered items for each loop substep, keyed by the substep key (e.g. "features"). */
  loops: Record<string, LoopItem[]>;
}

/**
 * The next prompt to inject for the active stage, or null if nothing is pending right now.
 *
 * Order per stage: the stage's `prompt` first (orientation), then each substep in turn. A static
 * substep is injected once and blocks until `state.doneSubsteps` marks it complete. A LOOP substep
 * (e.g. the feature workshop) injects its instructions once, then steps through `state.loops[key]`
 * one undone item at a time — injecting a concise pointer per item and waiting for it to finish
 * before advancing. `injected` is the set of ids already sent, so each step fires exactly once.
 */
export function nextInjection(
  section: BlueprintStage | undefined,
  injected: Set<string>,
  state: ConductorState,
  tier?: ModelCapabilityTier,
): Injection | null {
  if (!section) return null;

  const stageId = `${section.key}:_stage`;
  // The stage-orientation prompt adapts to the driving model's capability tier (#1854 Phase a);
  // absent a tier/variant this resolves to the base `prompt` — today's behavior.
  if (!injected.has(stageId)) return { id: stageId, prompt: resolveStagePrompt(section, tier) };

  for (const sub of section.substeps ?? []) {
    if (sub.loop) {
      // Kick the loop off once (its instructions), then walk the items one at a time.
      const loopId = `${section.key}:${sub.key}`;
      if (!injected.has(loopId)) return { id: loopId, prompt: sub.prompt };
      const next = (state.loops[sub.key] ?? []).find((it) => !it.done);
      if (next) {
        const itemId = `${loopId}:${next.id}`;
        return injected.has(itemId) ? null : { id: itemId, prompt: `Next: ${next.label}` };
      }
      continue; // loop kicked off, every item done (or none yet) → move to the next substep
    }
    // Static substep: inject once, then wait until it's marked done.
    if (!state.doneSubsteps.has(sub.key)) {
      const id = `${section.key}:${sub.key}`;
      return injected.has(id) ? null : { id, prompt: sub.prompt };
    }
  }
  return null;
}

/**
 * Collapse a (possibly multi-line, bulleted) step prompt to a SINGLE line for the CLI input.
 * Claude's input bar doesn't submit a multi-line paste on a lone Enter — but single-line text +
 * `\r` does (the path the pitch/reply already use). Flattening makes the inject actually send
 * instead of just sitting pasted. Bullets/newlines become inline spaces.
 */
export function flattenPrompt(prompt: string): string {
  return prompt.replace(/\s*\n\s*/g, " ").replace(/\s+/g, " ").trim();
}

export interface DeliverySignals {
  /** Output grew since the inject — the universal "planner engaged" fallback. */
  outputGrew: boolean;
  /** Section file stems that now have content (e.g. "goal", "stack"). */
  sectionKeys: Set<string>;
  /** Feature slugs the planner has begun defining (behavior/acceptance present). */
  startedFeatures: Set<string>;
  /** Whether features.json has any entries yet (for the "propose" step). */
  featuresExist: boolean;
}

/**
 * Whether an injected step has been DELIVERED — the planner acted on it (so we stop re-injecting).
 * Uses the strongest signal available for the step (its artifact appeared), and falls back to
 * `outputGrew` (the planner responded at all) for steps with no measurable artifact: the stage
 * orientation prompts (`:_stage`), informational stages, and the open-ended dimensions loop.
 * Note: delivered ≠ done — a step can land and still be in-progress; advancement is governed
 * separately by the gate / confirmation in {@link nextInjection}.
 */
export function isStepDelivered(stepId: string, s: DeliverySignals): boolean {
  const [stage, sub, item] = stepId.split(":");
  if (sub && sub !== "_stage" && !item) {
    if (s.sectionKeys.has(sub)) return true;                 // a discovery substep's file appeared
    if (sub === "propose" && s.featuresExist) return true;   // the feature list exists
  } else if (stage === "features" && sub === "features" && item) {
    if (s.startedFeatures.has(item)) return true;            // this feature began being defined
  }
  return s.outputGrew;                                       // universal fallback
}

runtime.features/planner/session/plannerIntro.ts:
// Planner introduction kickoff selection (#1240). Pure helpers so mode selection + pitch
// composition are unit-testable; the Rust `planner_intro_prompt` command returns the per-mode
// template text, and the launch bakes the composed result as a fresh-only startup prompt.

import type { BlueprintMode } from "../stages/blueprints";

export type PlannerIntroMode = "new" | "existing";

/**
 * Whether the planner should take the "existing repos" orientation — for BOTH the intro greeting
 * and the generated CLAUDE.md spec (`setup_workspaces`). True when the project is already saved OR
 * the blueprint's lifecycle is `operate` (transform / harden / maintain — work against existing
 * repos). #1286: keying off the blueprint **mode**, not just save-state, fixes an operate-mode
 * project on a fresh draft — or right after a greenfield→transform lifecycle switch — being
 * mis-oriented as a new greenfield one. (A saved greenfield project is unchanged: still "existing".)
 */
export function plannerTreatAsExisting({ isSaved, mode }: { isSaved: boolean; mode?: BlueprintMode }): boolean {
  return isSaved || mode === "operate";
}

/** Pick the intro mode from the session signals — mirrors the planner.rs CLAUDE.md branch
 *  (an existing project, else a new greenfield project). */
export function plannerIntroMode({ isExisting }: { isExisting: boolean }): PlannerIntroMode {
  return isExisting ? "existing" : "new";
}

/** Compose the startup prompt: the mode's intro, plus the user's pitch for a NEW project so the
 *  planner acknowledges it instead of asking what they're building, plus (for the one-shot
 *  `bsc-agent` runtime) the FIRST active stage's directive so a weak local model actually BEGINS the
 *  stage instead of greeting and then waiting to be advanced (#qwen). An empty intro (e.g. the
 *  command failed) yields `""` so the launch falls back to its plain `initCmd`.
 *
 *  `firstStageDirective` is omitted for Claude Code, which receives each stage's directive via the
 *  app's runtime injection as it advances — there the greeting is deliberately greeting-only. */
export function composePlannerIntro(
  intro: string, mode: PlannerIntroMode, pitch: string, firstStageDirective?: string,
): string {
  if (!intro.trim()) return "";
  let out = intro;
  if (mode === "new" && pitch.trim()) {
    out += `\n\n---\nThe user has already shared this pitch — acknowledge it and reflect your understanding back instead of asking what they're building:\n\n${pitch.trim()}`;
  }
  if (firstStageDirective?.trim()) {
    out += `\n\n---\nThe app drives this plan one stage at a time. Your FIRST stage is below — after you greet the user, BEGIN it now (don't wait to be advanced):\n\n${firstStageDirective.trim()}`;
  }
  return out;
}

runtime.features/planner/session/plannerLaunch.t:
// plannerLaunch — how the PLANNER session launches under the selected LLM provider / fleet harness.
//
// The planner is plan-only (role gate #219) and, like the fleet, can run on either Claude Code or the
// model-agnostic `bsc-agent` runtime (#1078). When the effective harness is bsc-agent — because the
// user chose it, OR because the provider is local/ollama which Claude Code can't drive — the planner
// launches `bsc-agent` with the SAME context, prompt, state, and permissions a Claude planner gets:
//   • context — `bsc-agent` composes its system prompt from the planning dir's CLAUDE.md chain +
//     CLAUDE.local.md + skills (compose_system), identical to what Claude Code loads.
//   • state   — the per-session BSC_* env (plan.db / data.db / skills.db + their CLIs) is wired by
//     pty_create's wire_bsc_env for every pane regardless of harness.
//   • prompt  — the planner intro is baked as the agent's task (BscAgentAdapter.launch_command).
//   • perms   — BSC_AGENT_PERMS carries the plan-only role gate (its analogue of the claude
//     settings.json deny rules), and BSC_AGENT_MCP the planner's MCP servers.
//
// Pure + React-free so both planner launch sites (initial mount + restart) share one definition.

import { resolveLlmConfig, bscAgentEnv, effectiveHarness } from "@/shared/lib/core/llmConfig";
import { roleCapability, bscAgentPerms, sessionScopes } from "@/shared/lib/session/sessionRoles";
import { resolveAllInstalledMcp, toBscAgentMcp, toSessionPayloads } from "@/features/mcp";
import type { AppStore } from "@/store/types";

/** The harness-dependent fields of the planner's `pty_create` call. */
export interface PlannerLaunch {
  /** Console provider id passed to pty_create — `"bsc-agent"` selects the runtime + its session
   *  file; `undefined` keeps Claude Code, the default. */
  providerId?: string;
  /** The fallback init command (used only if no startup prompt is baked). */
  initCmd: string;
  /** GH token env + the planner role's `BSC_SCOPES` store-scope doc (#2470) plus, for bsc-agent,
   *  the BSC_AGENT_* provider/model/base-url/perms/MCP vars. */
  env: Record<string, string>;
  /** Whether the intro is suppressed on a resumed session (#1240). Claude keeps the fresh-only
   *  greeting; bsc-agent (a one-shot agent loop, not a REPL) always bakes the intro as its task. */
  startupPromptFreshOnly: boolean;
  /** Request conversation resume — the backend ANDs it with "history actually exists", so a fresh
   *  project is unaffected (Claude resumes via `--continue`; bsc-agent via its $BSC_AGENT_SESSION
   *  continuity). */
  continueSession?: boolean;
}

/**
 * Resolve how the planner session launches for the current provider + fleet harness.
 *
 * @param s      the app-store snapshot (reads `llmProvider`, `fleetHarness`, `mcpServers`)
 * @param ghEnv  the GitHub token env already resolved for the planner (`GH_TOKEN` / `GITHUB_TOKEN`)
 */
export function plannerLaunchConfig(s: AppStore, ghEnv: Record<string, string>): PlannerLaunch {
  const harness = effectiveHarness(s.llmProvider, s.fleetHarness ?? "claude");
  // Store scopes (#2470, defense-in-depth): the planner role's per-store access tiers (ui: read) for
  // the store CLIs' runtime write check — on BOTH harnesses (the launch-time deny rules are the
  // boundary; this guards accidents + the bsc-agent runtime).
  const scopes = JSON.stringify(sessionScopes(roleCapability("planner")));
  if (harness !== "bsc-agent") {
    return {
      providerId: undefined,
      initCmd: "claude --continue 2>/dev/null || claude",
      env: { ...ghEnv, BSC_SCOPES: scopes },
      startupPromptFreshOnly: true,
      // Defensive (#2396): request resume explicitly. With the fresh-only intro guard a baked prompt
      // only ever fires when there's no history (where resume is a no-op), but if a caller ever bakes
      // a prompt onto a cwd WITH history this resumes it instead of silently forking a fresh session.
      continueSession: true,
    };
  }
  // The planner sees every installed MCP server (#1054); pass them to the runtime as $BSC_AGENT_MCP.
  const plannerMcp = toSessionPayloads(resolveAllInstalledMcp(s.mcpServers), []).mcp;
  const bscMcp = toBscAgentMcp(plannerMcp);
  const env: Record<string, string> = {
    ...ghEnv,
    ...bscAgentEnv(resolveLlmConfig(s)),
    // Plan-only role gate (#219) for the bsc-agent runtime: deny code writes + the mutating git/gh
    // commands the planner role forbids — the runtime's analogue of the claude settings.json denies.
    BSC_AGENT_PERMS: JSON.stringify(bscAgentPerms(roleCapability("planner"))),
    BSC_SCOPES: scopes,
  };
  if (bscMcp.length > 0) env.BSC_AGENT_MCP = JSON.stringify(bscMcp);
  return {
    providerId: "bsc-agent",
    initCmd: "bsc-agent", // fallback only; the baked intro prompt always wins
    env,
    startupPromptFreshOnly: false,
    continueSession: true,
  };
}

// plannerSandbox (#1988) — the opt-in WSL2-sandbox launch overrides shared by BOTH planner launch
// sites (the initial mount in usePlannerTerminal AND the restart in usePlanningSession), so they can't
// drift apart (the restart path used to skip the sandbox entirely). When the sandbox toggle is on AND
// the planner runs on bsc-agent — the only runtime baked into the sealed distro — the hub is relocated
// into the distro (setup_sandbox_hub) and the session spawns INSIDE it; otherwise it's the host launch.
//
// The launch reads the toggle only at spawn time, so flipping it while a planner is OPEN does nothing
// to the live session — Planning.tsx restarts the open planner on a flip so it converts.

import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { useAppStore } from "@/store";

/** Whether a planner `pty_create` should spawn into the sandbox: the toggle is on, the harness is
 *  bsc-agent (baked into the distro), and there's a host hub to relocate. Pure — unit-testable. */
export function wantsSandboxLaunch(
  sandboxConsoles: boolean,
  providerId: string | undefined,
  planningDir: string,
): boolean {
  return sandboxConsoles && providerId === "bsc-agent" && !!planningDir;
}

/** Resolve the `cwd` + `wslDistro` for a planner `pty_create`. When the sandbox is wanted, relocate the
 *  hub into the distro (`setup_sandbox_hub`) and spawn at the distro cwd; on failure — or when not
 *  wanted — fall back to the host hub (no distro). Reads the current `sandboxConsoles` from the store. */
export async function resolvePlannerSandbox(
  providerId: string | undefined,
  planningDir: string,
  projectKey: string,
): Promise<{ cwd: string; wslDistro: string | undefined }> {
  const wants = wantsSandboxLaunch(useAppStore.getState().sandboxConsoles, providerId, planningDir);
  const sandboxHub = wants
    ? await safeInvoke<string | null>(
        "setup_sandbox_hub", { key: projectKey }, null,
        (e: unknown) => console.error("sandbox hub setup failed (falling back to host):", e),
      )
    : null;
  return { cwd: sandboxHub ?? planningDir, wslDistro: sandboxHub ? "bsc-agent-sandbox" : undefined };
}

