          <Chip tone="accent">● {isExisting ? "expanding" : "drafting"}</Chip>
        </Row>
        {autopilotRunning && (
          <Text as="div" size={12} tone="accent" style={{ marginTop: 4 }}>
            ⚙ auto-planning · {autopilotProgressPct}%
