// Pure helpers for the planner's section-by-section discovery loop.
//
// Free of React / xterm / Tauri imports so the message building can be unit-tested in isolation.
// All planner stream-tag PARSING has been removed — every planner artifact is now written via a
// `bsc plan …` command and reflected by the section poll (the tag→bsc migration, #2007–#2017).

// The `<plan_focus>` stream tag was removed (#2017): the "active topic" card-highlight it drove was
// dropped in the focused-pane redesign (#652), so it fed a discarded state value. The stepper follows
// the live session off the section files the planner writes, not a tag.

/**
 * The message injected into Claude's PTY when the user confirms a section in the
 * UI. It is the "advance to the next section" signal for the discovery loop.
 */
export function buildSectionConfirmMessage(sectionTitle: string): string {
  return `[The user confirmed the "${sectionTitle}" section in the planner UI — continue to the next section.]`;
}

/**
 * The message injected into Claude's PTY when the user deliberately SKIPS an optional stage in the
 * planner UI (#921). It tells the planner to stop any work on that stage and move on — the stage is
 * optional and the user chose not to do it.
 */
export function buildSectionSkipMessage(sectionTitle: string): string {
  return `[The user chose to SKIP the optional "${sectionTitle}" section in the planner UI — do not work on it; continue to the next section.]`;
}

// Startup scripts moved to plan.db (#2010) — the planner records per-repo kickoff/triage prompt
// docs with `bsc plan startup add`; the section poll resolves each `path` via `scriptDocRelpath`
// (below) and auto-assigns it. (The `<startup_script>` stream tag + its parser are gone.)

/**
 * Build the unified-store relpath for a script the planner wrote to its project
 * dir. `sanitizedKey` is the on-disk project folder (sanitize_project_key). A
 * path already rooted at `projects/` is returned untouched; otherwise it is
 * resolved under the project hub. Backslashes are normalized to posix and any
 * leading slashes stripped so the result satisfies read_document's path guards.
 */
export function scriptDocRelpath(sanitizedKey: string, path: string): string {
  const clean = path.replace(/\\/g, "/").replace(/^\/+/, "");
  if (clean.startsWith("projects/")) return clean;
  return `projects/${sanitizedKey}/${clean}`;
}

runtime.features/planner/session/planningTermina:
// Planner terminal/ANSI helpers, split out of Planning.tsx (#1332): the ANSI-escape stripper and
// a viewport-content probe used to avoid re-sending an already-pasted prompt. (The xterm TERM_THEME
// lives in @/app/console/lib/terminalConstants — the single home shared by every terminal, #3246.)
import type { Terminal } from "@xterm/xterm";

// Covers all common VT/ANSI escape sequences:
//   CSI  \x1b [ <0x20-0x3f>* <0x40-0x7e>   — includes private ?/>/< params
//   OSC  \x1b ] <text> (\x07 | \x1b\)       — BEL or ST terminator
//   Char-set  \x1b [()][…]
//   Other C1  \x1b <any single byte>         — fallback: ESC + one char
// eslint-disable-next-line no-control-regex
const ANSI_RE = /\x1b(?:\[[\x20-\x3f]*[\x40-\x7e]|\][^\x07\x1b]*(?:\x07|\x1b\\)|[()][0-9A-Za-z]|[\x40-\x7e])/g;

export function stripAnsi(s: string): string {
  return (
    s
      .replace(ANSI_RE, "")  // remove escape sequences
      .replace(/\r/g, "")    // remove lone carriage returns (spinner overwrites)
      // eslint-disable-next-line no-control-regex -- intentional: strip bare ESC bytes from PTY output
      .replace(/\x1b/g, "")  // remove any leftover bare ESC bytes
  );
}

// Read the visible terminal rows (where Claude's input bar lives) and report whether they already
// contain `snippet` — so a re-send doesn't duplicate a prompt that was pasted but never submitted.
// Heuristic: a normalized substring match over the viewport. Best-effort; never throws.
export function terminalShows(term: Terminal | null, snippet: string): boolean {
  if (!term || !snippet.trim()) return false;
  try {
    const buf = term.buffer.active;
    let text = "";
    for (let i = 0; i < term.rows; i++) {
      text += " " + (buf.getLine(buf.baseY + i)?.translateToString(true) ?? "");
    }
    const norm = (s: string) => s.replace(/\s+/g, " ").trim().toLowerCase();
    return norm(text).includes(norm(snippet));
  } catch {
    return false;
  }
}

runtime.features/planner/session/projectTitle.ts:
/** The project's display title — used for the fleet/triage tab name and the published GitHub
 *  structure. Resolution order:
 *  1. an explicit planning title,
 *  2. a published project's real name (`activeProjectName`) — a named/published project should
 *     show its NAME, not a heuristic derived from its goal prose,
 *  3. the first real sentence of the goal prose, with markdown heading lines (e.g. `# Goal`)
 *     skipped so the heading never leaks as the title (was naming triage tabs "# Goal"),
 *  4. a default.
 *
 *  Single source of truth for the two call sites (`Planning.tsx` + `usePlanPublish.ts`) that used
 *  to hand-roll this and drift. */
export function deriveProjectTitle(
  planningTitle: string,
  goalContent: string,
  activeProjectName: string,
): string {
  const goalSentence = goalContent
    .replace(/^\s*#.*$/gm, "")            // drop markdown heading lines (e.g. "# Goal")
    .split(/[.!?\n]/)
    .map((s) => s.trim())
    .find(Boolean) ?? "";
  return planningTitle || activeProjectName || goalSentence || "New project";
}

