runtime.features/planner/session/publishSteps.ts:
// Publish steps (#1749) — the six sequential phases of `handlePublish`, extracted from
// usePlanPublish.ts so each is independently unit-testable. The logic is verbatim; the only change is
// that the GitHub API (`gql/rest/post/put/patch`), the per-node status callback (`upd`), and the
// store/`invoke` side-effects are INJECTED rather than captured from the hook's closure. The hook
// (usePlanPublish) is now a thin orchestrator that wires these together.
//
// Every step is fail-soft in the same places it was inline: a per-node failure records an "error"
// status via `upd` and continues; fail-CLOSED branches (couldn't verify existing milestones/issues)
// are preserved exactly so a transient read failure never risks duplicate creation.

import { resolveRepoPublic } from "@/store/slices/plan";
import type { GhStatusMap, GhItemState } from "./GitHubStructureCard";
import { parseFeaturesFile, featuresToPlanIssues } from "../issues/featureList";
import { depsForRepo, mergeIntoPackageJson, mergeIntoCargoToml, buildNpmrc, buildCargoConfig, type parseDependencyManifest } from "../issues/dependencies";
import { resolveIssueAssignee } from "../fleet/fleetAssignee";
import type { AgentStream } from "../fleet/planFleet";
import { deriveTopics, buildReadme, communityFiles, type ScaffoldFile } from "../lib/repoScaffold";
import { renderIssueBody, subIssueLinks, type PlanIssue } from "../issues/planIssues";
import { BSC_ISSUE_LABEL, BSC_ISSUE_LABEL_COLOR, withProvenanceLabel } from "@/shared/lib/github/issueProvenance";

/** The injected GitHub transport — the same closures handlePublish built over `invoke`. */
export interface GhApi {
  gql: (query: string, variables: unknown) => Promise<Record<string, unknown>>;
  rest: <T>(path: string) => Promise<T>;
  post: <T>(path: string, body: unknown) => Promise<T>;
  put: (path: string, body: unknown) => Promise<unknown>;
  patch: (path: string, body: unknown) => Promise<unknown>;
}

/** Patch a single GitHub-structure node's live status (drives the GitHubStructureCard). */
export type Upd = (id: string, patch: Partial<GhItemState>) => void;

type DepManifest = ReturnType<typeof parseDependencyManifest>;

// ── 1. Repositories — verify each exists; create if missing ───────────────────
export async function publishRepositories(
  api: GhApi,
  upd: Upd,
  opts: {
    repos: string[];
    projectDesc: string;
    repoPublic: Parameters<typeof resolveRepoPublic>[0];
    reposPublic: Parameters<typeof resolveRepoPublic>[1];
    effectiveProjectId: string;
  },
): Promise<{ repoNodeIds: Record<string, string>; viewerLogin: string }> {
  const { repos, projectDesc, repoPublic, reposPublic, effectiveProjectId } = opts;
  const repoNodeIds: Record<string, string> = {};
  let viewerLogin = "";
  try {
    const v = await api.gql(`{ viewer { login } }`, null) as { viewer?: { login?: string } };
    viewerLogin = v.viewer?.login ?? "";
  } catch { /* non-fatal: fall back to org repo path */ }

  for (const fullName of repos) {
    const id = `repo:${fullName}`;
    const [owner, name] = fullName.split("/");
    upd(id, { status: "running" });
    try {
      const existing = await api.rest<{ node_id: string; html_url: string }>(`repos/${fullName}`).catch(() => null);
      if (existing?.node_id) {
        repoNodeIds[fullName] = existing.node_id;
        upd(id, { status: "exists", detail: "on github", url: existing.html_url });
      } else {
        const path = owner.toLowerCase() === viewerLogin.toLowerCase() ? "user/repos" : `orgs/${owner}/repos`;
        const created = await api.post<{ node_id: string; html_url: string }>(path, {
          // Per-repo visibility (#1227): the repo's own toggle wins, else the project default,
          // else private. Existing repos are detected above and never re-created, so this
          // governs creation only.
          name, private: !resolveRepoPublic(repoPublic, reposPublic, effectiveProjectId, fullName), description: projectDesc,
        });
        repoNodeIds[fullName] = created.node_id;
        upd(id, { status: "created", detail: "created", url: created.html_url });
      }
    } catch (e) {
      upd(id, { status: "error", detail: String(e) });
    }
  }
  return { repoNodeIds, viewerLogin };
}

// ── 1b. Repo presentation (#848, #1114): description (every repo), stack topics, a plan-built
//        README with CI/version badges, community-health files, and the locked dependency
//        manifests/registry config. Files are created only when ABSENT; failures are surfaced
//        in the card detail, not fatal. ──
export async function scaffoldRepositories(
  api: GhApi,
  upd: Upd,
  opts: {
    repos: string[];
    projectDesc: string;
    projectTitle: string;
    goalContent: string;
    stackText: string;
    scopeText: string;
    archText: string;
    features: { name: string; behavior?: string }[];
    planDependencies: DepManifest["dependencies"];
    registries: DepManifest["registries"];
  },
): Promise<void> {
  const { repos, projectDesc, projectTitle, goalContent, stackText, scopeText, archText, features, planDependencies, registries } = opts;
  const topics = deriveTopics(stackText);
  for (const fullName of repos) {
    const id = `scaffold:${fullName}`;
    upd(id, { status: "running" });
    try {
      // Always (re)apply the description — a create sets it, but a pre-existing repo never had it.
      let descOk = true;
      if (projectDesc) await api.patch(`repos/${fullName}`, { description: projectDesc }).catch(() => { descOk = false; });
      let topicsOk = true;
      if (topics.length) await api.put(`repos/${fullName}/topics`, { names: topics }).catch(() => { topicsOk = false; });
      // CI badges reference the repo's actual workflow files (graceful — none yet ⇒ none).
      const wfs = await api.rest<{ name: string }[]>(`repos/${fullName}/contents/.github/workflows`).catch(() => []);
      const workflows = (Array.isArray(wfs) ? wfs : []).map(w => w.name).filter(n => /\.ya?ml$/i.test(n));
      const files: ScaffoldFile[] = [
        { path: "README.md", content: buildReadme({
          fullName, description: projectDesc, goal: goalContent, scope: scopeText,
          architecture: archText, features, stackText, workflows,
        }) },
        ...communityFiles(projectTitle),
      ];
      let wrote = 0;
      for (const f of files) {
        const path = `repos/${fullName}/contents/${f.path}`;
        const exists = await api.rest<{ sha?: string }>(path).then(r => !!r?.sha).catch(() => false);
        if (exists) continue; // don't clobber an existing file
        const content = btoa(unescape(encodeURIComponent(f.content)));
        await api.put(path, { message: `docs: scaffold ${f.path}`, content }).catch(() => {});
        wrote++;
      }

      // Dependency manifests (#1111/#1127): seed package.json / Cargo.toml from the locked manifest —
      // and the registry config (.npmrc / .cargo/config.toml) for any private SOURCE — so the fleet
      // inherits identical, complete, fetchable deps from the base branch and never adds its own. An
      // ADDITIVE MERGE for the manifests — a pre-existing pinned version always wins, so we read the
      // current file, merge, and only write on a real change.
      let manifests = 0;
      const repoDeps = depsForRepo(planDependencies, fullName);
      if (repoDeps.length) {
        const shortRepo = fullName.split("/")[1] ?? fullName;
        const seedManifest = async (file: string, merge: (existing: string | null) => string | null) => {
          const path = `repos/${fullName}/contents/${file}`;
          const cur = await api.rest<{ sha?: string; content?: string }>(path).catch(() => null);
          const existing = cur?.content ? decodeURIComponent(escape(atob(cur.content.replace(/\s/g, "")))) : null;
          const merged = merge(existing);
          if (merged === null || merged === existing) return; // nothing to add / no change
          const content = btoa(unescape(encodeURIComponent(merged)));
          await api.put(path, { message: `chore: seed ${file} from the locked dependency manifest`, content, ...(cur?.sha ? { sha: cur.sha } : {}) }).catch(() => {});
          manifests++;
        };
        await seedManifest("package.json", (e) => mergeIntoPackageJson(e, shortRepo, repoDeps));
        await seedManifest("Cargo.toml", (e) => mergeIntoCargoToml(e, shortRepo, repoDeps));
        // Registry config for private sources — generated wholesale (not merged): create it only when
        // absent so a hand-tuned .npmrc / .cargo config is never clobbered.
        await seedManifest(".npmrc", (e) => (e === null ? buildNpmrc(registries, repoDeps) : null));
        await seedManifest(".cargo/config.toml", (e) => (e === null ? buildCargoConfig(registries, repoDeps) : null));
      }

      const bits = [
        projectDesc ? (descOk ? "description" : "description failed") : null,
        topics.length ? (topicsOk ? `${topics.length} topics` : "topics failed") : null,
        wrote ? `${wrote} file${wrote === 1 ? "" : "s"}` : null,
        manifests ? `${manifests} manifest${manifests === 1 ? "" : "s"}` : null,
      ].filter(Boolean);
      upd(id, (wrote || manifests)
        ? { status: "created", detail: bits.join(" · ") }
        : { status: "exists", detail: bits.length ? `${bits.join(" · ")} · files present` : "already scaffolded" });
    } catch (e) {
      upd(id, { status: "error", detail: String(e) });
    }
  }
}

// ── 2. Project board — reuse existing or create a Projects v2 board ───
// Returns the resolved projectId and, when a board was newly created, the `created` board so the
// caller can perform the store writes (setActiveProjectMeta / key alias / mark_published / draft drop).
export async function ensureProjectBoard(
  api: GhApi,
  upd: Upd,
  opts: {
    activeProjectId: string | null;
    activeProjectNumber: number | null | undefined;
    repos: string[];
    viewerLogin: string;
    projectTitle: string;
    repoNodeIds: Record<string, string>;
  },
): Promise<{ projectId: string | undefined; created?: { id: string; number: number; url: string } }> {
  const { activeProjectId, activeProjectNumber, repos, viewerLogin, projectTitle, repoNodeIds } = opts;
  let projectId: string | undefined = activeProjectId ?? undefined;
  let created: { id: string; number: number; url: string } | undefined;
  const id = "project";
  upd(id, { status: "running" });
  try {
    if (projectId) {
      upd(id, { status: "exists", detail: activeProjectNumber ? `#${activeProjectNumber}` : "linked" });
    } else {
      const ownerLogin = repos[0]?.split("/")[0] || viewerLogin;
      if (!ownerLogin) throw new Error("no owner to create project under");
      const ownerData = await api.gql(
        `query($login:String!){ repositoryOwner(login:$login){ id } }`,
        { login: ownerLogin },
      ) as { repositoryOwner?: { id?: string } };
      const ownerId = ownerData.repositoryOwner?.id;
      if (!ownerId) throw new Error(`could not resolve owner '${ownerLogin}'`);
      const createdRes = await api.gql(
        `mutation($ownerId:ID!,$title:String!){
             createProjectV2(input:{ownerId:$ownerId,title:$title}){ projectV2 { id number url } }
           }`,
        { ownerId, title: projectTitle },
      ) as { createProjectV2?: { projectV2?: { id: string; number: number; url: string } } };
      const pv = createdRes.createProjectV2?.projectV2;
      if (!pv) throw new Error("project not created");
      projectId = pv.id;
      created = pv;
      upd(id, { status: "created", detail: `#${pv.number}`, url: pv.url });
    }
    // Link every repo to the board (idempotent server-side).
    for (const fullName of repos) {
      const repoNodeId = repoNodeIds[fullName];
      if (projectId && repoNodeId) {
        await api.gql(
          `mutation($p:ID!,$r:ID!){ linkProjectV2ToRepository(input:{projectId:$p,repositoryId:$r}){ repository { id } } }`,
          { p: projectId, r: repoNodeId },
        ).catch(() => { /* already linked — ignore */ });
      }
    }
  } catch (e) {
    upd(id, { status: "error", detail: String(e) });
  }
  return { projectId, created };
}

// ── 3. Issues — generated from the FEATURES (one issue per feature, #plan-db): added to the board,
//      assigned to its stream's login, with feature sub-issues nested. No milestones (#1912).
//      Idempotent, fail-CLOSED on a repo whose existing-issue fetch fails. ──
/**
 * The LOCAL half of publish (#3280): parse the features section into `PlanIssue`s and materialize them
 * into plan.db, so the fleet/director have issues to coordinate on WITHOUT any GitHub round-trip. Used
 * both by `createIssues` (before the GitHub push) and by the GitHub-less commit path.
 *
 * Idempotent — `upsertIssue` keys on `ref`, so committing locally and later publishing over the same
 * rows never duplicates. Returns the parsed issues for the caller (createIssues then pushes them).
 */
export async function materializeIssues(
  featuresContent: string,
  hooks: { upsertIssue: (iss: PlanIssue) => Promise<void> },
): Promise<PlanIssue[]> {
  const planIssues = featuresToPlanIssues(parseFeaturesFile(featuresContent));
  for (const iss of planIssues) {
    await hooks.upsertIssue(iss);
  }
  return planIssues;
}

export async function createIssues(
  api: GhApi,
  upd: Upd,
  opts: {
    repos: string[];
    featuresContent: string;
    projectId: string | undefined;
    streams: AgentStream[];
    viewerLogin: string;
  },
  hooks: { upsertIssue: (iss: PlanIssue) => Promise<void> },
): Promise<void> {
  const { repos, featuresContent, projectId, streams, viewerLogin } = opts;
  // The LOCAL half — materialize into plan.db — is shared with the GitHub-less commit path (#3280).
  const planIssues = await materializeIssues(featuresContent, hooks);
  for (const [repoIdx, fullName] of repos.entries()) {
    // Check what already exists BEFORE creating so a re-sync never duplicates. Fail CLOSED: if we
    // can't fetch the repo's issues, skip creating here.
    let existingTitles: string[];
    try {
      const existing = await api.rest<{ title: string }[]>(`repos/${fullName}/issues?state=all&per_page=100`);
      existingTitles = existing.map(i => i.title);
    } catch {
      for (const iss of planIssues) upd(`issue:${fullName}:${iss.ref}`, { status: "error", detail: "couldn't verify existing issues — skipped" });
      continue;
    }

    // Issues for THIS repo: its declared `repo`, or the default (first) repo.
    const mine = planIssues.filter(iss => iss.repo ? iss.repo === fullName : repoIdx === 0);
    // Ensure every label this repo uses exists (422 if present — harmless).
    // Provenance label first (#738) — every app-created issue carries it.
    await api.post(`repos/${fullName}/labels`, { name: BSC_ISSUE_LABEL, color: BSC_ISSUE_LABEL_COLOR }).catch(() => {});
    for (const name of [...new Set(mine.flatMap(iss => iss.labels))]) {
      await api.post(`repos/${fullName}/labels`, { name, color: "0e8a16" }).catch(() => {});
    }
    // Ensure each owning stream's `stream:<id>` label up front so issues are created ALREADY tagged
    // (#2397). Labeling at creation — where the real GitHub number is in hand — avoids the fragile
    // post-hoc "label by the plan's predicted number" pass, whose numbers 404 when an issue failed to
    // post or the numbering drifted.
    for (const label of new Set(mine.map(iss => iss.stream).filter(Boolean).map(s => `stream:${s}`))) {
      await api.post(`repos/${fullName}/labels`, { name: label, color: "5319e7" }).catch(() => {});
    }
    // ref → created GitHub node id, so feature parents + their sub-issues can be linked.
    const nodeByRef: Record<string, string> = {};
    for (const iss of mine) {
      const id = `issue:${fullName}:${iss.ref}`;
      if (existingTitles.includes(iss.title)) { upd(id, { status: "exists", detail: "already exists" }); continue; }
      upd(id, { status: "running" });
      try {
        const body: Record<string, unknown> = { title: iss.title, body: renderIssueBody(iss) };
        // Tag the owning stream at creation (#2397) so ownership is correct without a number-matching
        // pass. Provenance stamp (#738) rides along.
        const labels = iss.stream ? [...iss.labels, `stream:${iss.stream}`] : iss.labels;
        body.labels = withProvenanceLabel(labels);
        const issue = await api.post<{ number: number; node_id: string; html_url: string }>(`repos/${fullName}/issues`, body);
        if (issue.node_id) nodeByRef[iss.ref] = issue.node_id;
        if (projectId && issue.node_id) {
          await api.gql(`mutation($p:ID!,$c:ID!){ addProjectV2ItemById(input:{projectId:$p,contentId:$c}){ item { id } } }`, { p: projectId, c: issue.node_id }).catch(() => {});
        }
        // Assign the issue to its owning stream's GitHub login (#847), defaulting to the publishing
        // account. Done AFTER the issue exists, so an invalid / no-access login (a 422) is skipped
        // gracefully and never loses the issue.
        const assignee = resolveIssueAssignee(iss.stream, streams, viewerLogin);
        if (assignee) {
          await api.post(`repos/${fullName}/issues/${issue.number}/assignees`, { assignees: [assignee] }).catch(() => {});
        }
        upd(id, { status: "created", detail: `#${issue.number}`, url: issue.html_url });
      } catch (e) {
        upd(id, { status: "error", detail: String(e) });
      }
    }
    // Nest each feature's sub-issues under their parent (#…) via GraphQL addSubIssue. Best-effort +
    // idempotent: only links pairs created in THIS run; an already-linked pair (or an API that
    // doesn't support sub-issues) errors harmlessly.
    for (const { parent, child } of subIssueLinks(mine, nodeByRef)) {
      await api.gql(
        `mutation($p:ID!,$c:ID!){ addSubIssue(input:{issueId:$p,subIssueId:$c}){ issue { id } } }`,
        { p: parent, c: child },
      ).catch(() => {});
    }
  }
}

// ── 4. Stream labels — a best-effort RECONCILIATION pass (#2397). Issues created in this publish are
//      already tagged `stream:<id>` at creation (createIssues); this pass re-applies the label to any
//      PRE-EXISTING issues the stream owns, resolvable by number. Resilient: a plan-ref number that
//      never became a real issue (a post that failed, or numbering that drifted) 404s — that issue is
//      SKIPPED, never aborting the stream or surfacing the 404 as a publish error. Idempotent. ──
export async function applyStreamLabels(
  api: GhApi,
  upd: Upd,
  opts: { streams: AgentStream[] },
): Promise<void> {
  for (const st of opts.streams) {
    const id    = `stream:${st.id}`;
    const label = `stream:${st.id}`;
    upd(id, { status: "running" });
    try {
      // Create the label (the request 422s if it already exists — harmless).
      await api.post(`repos/${st.repo}/labels`, { name: label, color: "5319e7" }).catch(() => {});
      const nums = st.issues
        .map(ref => parseInt(ref.replace(/[^0-9]/g, ""), 10))
        .filter(n => Number.isFinite(n) && n > 0);
      let applied = 0;
      let skipped = 0;
      for (const n of nums) {
        // Per-issue resilience: a 404 (the number isn't a real issue) skips just that one.
        const ok = await api.post(`repos/${st.repo}/issues/${n}/labels`, { labels: [label] })
          .then(() => true).catch(() => false);
        if (ok) applied++; else skipped++;
      }
      const skipNote = skipped > 0 ? ` · ${skipped} skipped (no matching issue)` : "";
      upd(id, applied > 0
        ? { status: "created", detail: `${applied} issue${applied === 1 ? "" : "s"} labeled${skipNote}` }
        : { status: "exists",  detail: `label ready${nums.length ? skipNote : " · no numbered issues"}` });
    } catch (e) {
      upd(id, { status: "error", detail: String(e) });
    }
  }
}

/** Seed every GitHub-structure node as "planned" so the card shows the full structure upfront. */
export function seedPublishStatus(opts: { repos: string[]; streams: AgentStream[] }): GhStatusMap {
  const { repos, streams } = opts;
  const status: GhStatusMap = {};
  status["project"] = { status: "planned" };
  repos.forEach(r => { status[`repo:${r}`] = { status: "planned" }; });
  streams.forEach(st => { status[`stream:${st.id}`] = { status: "planned" }; });
  return status;
}

runtime.features/planner/session/renameProject.t:
// Rename a PUBLISHED project (#1226) — the pure decision + the apply step, extracted from
// Planning.tsx so the guard + the GitHub-board update are unit-testable. Renaming updates the
// board title + the local display name but KEEPS the frozen session key / on-disk folder (#2409:
// renames are display-only — the folder keeps its birth-slug; reopening under the new name goes
// through the reopen-mismatch modal, which can do the real on-disk move).

import { projectSlug } from "@/shared/lib/core/projectPaths";

/** Update a published GitHub Project (V2) board title; leaves milestones/issues untouched. */
export const RENAME_PROJECT_MUTATION = `
  mutation RenameProject($projectId: ID!, $title: String!) {
    updateProjectV2(input: { projectId: $projectId, title: $title }) {
      projectV2 { id title }
    }
  }
`;

export type RenamePlan =
  | { kind: "noop" }
  | { kind: "error"; message: string }
  | { kind: "rename"; title: string };

/**
 * Decide what a rename commit should do, given the raw input, the current name + project id, and
 * the OTHER projects' frozen keys (for the duplicate guard). Trimmed empty / unchanged / no-id all
 * no-op; a name that slugifies onto another project's key is an error; otherwise rename.
 */
export function planRename(
  raw: string,
  currentName: string,
  projectId: string | null,
  otherKeys: ReadonlySet<string>,
): RenamePlan {
  const next = raw.trim();
  if (!next || next === currentName || !projectId) return { kind: "noop" };
  // Keys are name-derived slugs (#2409): a rename whose slug lands on another project's key would
  // make the two names resolve to ONE hub at reopen — block it here.
  if (otherKeys.has(projectSlug(next))) {
    return { kind: "error", message: "Another project already uses that name." };
  }
  return { kind: "rename", title: next };
}

export interface RenameDeps {
  /** The GitHub GraphQL bridge (injected for tests). */
  graphql: (query: string, variables: Record<string, unknown>) => Promise<unknown>;
  /** Update local project meta (name/repo/number/repos). */
  setMeta: (id: string, name: string, repo: string, number: number, repos: string[]) => void;
  repo: string;
  number: number;
  repos: string[];
}

/**
 * Apply a planned rename: update LOCAL state first (graceful — the planner reflects the rename even
 * if GitHub is unreachable, mirroring how delete removes locally on a GitHub failure), then push the
 * board title. Returns an error message when the GitHub update failed (local is already updated and
 * the rename is retryable), else `null`.
 */
export async function applyRename(projectId: string, title: string, deps: RenameDeps): Promise<string | null> {
  deps.setMeta(projectId, title, deps.repo, deps.number, deps.repos);
  try {
    await deps.graphql(RENAME_PROJECT_MUTATION, { projectId, title });
    return null;
  } catch {
    return "Renamed locally; the GitHub board update failed — edit again to retry.";
  }
}

// useCtxRequired (#1775, extracted from Planning.tsx) — the dynamic Context required-set
// (#1019/#1028): polled from plan.db, baseline-seeded once per project/session. The Context gate
// reads it; context files gate on GENERATION (the file exists), not confirmation, so there's
// nothing to confirm/mirror. Returns the live required-topic list.
import { useState, useEffect, useRef } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import { bscJson, bscRun } from "@/shared/lib/core/bsc";
import { DISCOVERY_BASELINE } from "../stages/planStageDerive";
import type { BlueprintStage } from "../stages/blueprints";

export function useCtxRequired(effectiveProjectId: string, planSecs: BlueprintStage[]): string[] {
  const [ctxRequired, setCtxRequired] = useState<string[]>([]);
  const ctxRequiredJsonRef = useRef<string>("");
  const ctxSeededRef = useRef<Set<string>>(new Set());

  // #1019: clear the cached manifest on a project switch so a stale set never bleeds across.
  useEffect(() => { setCtxRequired([]); ctxRequiredJsonRef.current = ""; }, [effectiveProjectId]);

  // #1028: poll the Context required-set from plan.db and seed the baseline once per project. The
  // gate reads it to check each required topic's `context/<topic>.md` exists.
  usePoll((isCancelled) => {
    if (!effectiveProjectId) return;
    const tick = async () => {
      try {
        // `bsc plan discovery list --json` emits the required-topic string array (the same `Vec<String>`
        // the old `plan_list_discovery` command returned); bscJson degrades to [] when plan.db is absent.
        const m = await bscJson<string[]>(effectiveProjectId, ["plan", "discovery", "list", "--json"], []);
        if (isCancelled()) return;
        // Seed the baseline once per project/session if the set is empty — a deterministic floor before
        // the planner runs `bsc-plan context require`. The blueprint's context section `requires`
        // overrides the universal baseline (blueprint seeding).
        if ((m?.length ?? 0) === 0 && !ctxSeededRef.current.has(effectiveProjectId)) {
          ctxSeededRef.current.add(effectiveProjectId);
          const requires = planSecs.find(s => s.key === "discovery")?.requires ?? DISCOVERY_BASELINE;
          for (const t of requires) {
            await bscRun(effectiveProjectId, ["plan", "discovery", "require", t]);
          }
          return; // next tick reads the seeded set
        }
        const j = JSON.stringify(m ?? []);
        if (j !== ctxRequiredJsonRef.current) {
          ctxRequiredJsonRef.current = j;
          setCtxRequired(m ?? []);
        }
      } catch { /* plan.db not created until the planner/seed touches context — ignore */ }
    };
    return tick();
  }, 2000, [effectiveProjectId, planSecs]);

  return ctxRequired;
}

runtime.features/planner/session/useDesignRouteS:
// useDesignRouteState (#2121) — polls a project's staged design manifest (`design/intake.json`) and
// reports whether any files are staged (`hasFiles`) and whether any staged file has CHANGED since it
// was last routed (content-hash diff via `changedDesignFiles`). Drives the UI stage's conditional
// footer: it offers "route design to project" ONLY when files are staged and the design is
// missing/stale (#2860); with nothing staged it reverts to "approve & continue". Read-only +
// non-fatal — a missing manifest reports no files, nothing changed.
import { useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { usePoll } from "@/shared/hooks/usePoll";
import { parseIntake, changedDesignFiles, INTAKE_DIR } from "../lib/fileIntake";

/** The staged-design snapshot the UI stage footer reads (#2860). */
export interface DesignRouteState {
  /** At least one design file is staged in `design/intake.json`. */
  hasFiles: boolean;
  /** At least one staged file differs from its last-routed hash (new or edited since routed). */
  changed: boolean;
}

/**
 * Whether the UI stage's footer should offer "route design to project" (#2860). True only when the
 * project needs a UI, there ARE staged files to route (`hasFiles`), AND either the design isn't
 * routed yet (`ui` section unconfirmed) or a staged file changed since the last route. **No staged
 * files ⇒ false** — the fix for the dead route button on a fresh UI stage with nothing to route.
 * Pure — unit-tested.
 */
export function uiNeedsRouting(requiresUi: boolean, uiConfirmed: boolean, design: DesignRouteState): boolean {
  return requiresUi && design.hasFiles && (!uiConfirmed || design.changed);
}

/**
 * @param projectKey  the project hub key whose `design/intake.json` is polled.
 * @param active      only poll while the UI stage is relevant (blueprint enables `ui`); false → idle.
 * @returns whether any files are staged and whether any staged file is unrouted/stale.
 */
export function useDesignRouteState(projectKey: string, active: boolean): DesignRouteState {
  const [state, setState] = useState<DesignRouteState>({ hasFiles: false, changed: false });
  usePoll(async (isCancelled) => {
    if (!active || !projectKey) { setState({ hasFiles: false, changed: false }); return; }
    try {
      const files = await invoke<[string, string][]>("read_project_files", { projectKey, subdir: INTAKE_DIR });
      if (isCancelled()) return;
      const manifest = files.find(([rel]) => rel === "intake.json")?.[1];
      const entries = manifest ? parseIntake(manifest) : [];
      setState({ hasFiles: entries.length > 0, changed: changedDesignFiles(entries).length > 0 });
    } catch {
      if (!isCancelled()) setState({ hasFiles: false, changed: false });
    }
  }, 2500, [projectKey, active]);
  return state;
}

runtime.features/planner/session/usePlanConfirma:
// usePlanConfirmations (#1775, extracted from Planning.tsx) — the stage gate-confirm/skip logic:
//   • pendingConfirm — the active stage's drafted sections that "approve & continue" confirms in one
//     click (plus the Features one-click once every feature is populated).
//   • confirmStageKeys — the single stage-completion primitive (#1068): confirm each pending section
//     + tell the planner to continue. Shared by the manual button, the autopilot, and auto-complete.
//   • auto-advance effect (#1068) — when the global flag is on, confirm the ready set after a beat.
//   • onSkipStage (#921) — skip the active optional stage + tell the planner to move on.
import { useMemo, useCallback, useEffect, useRef } from "react";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import { titleForTopic, FEATURES_KEY } from "../stages/planTopics";
import { buildSectionConfirmMessage, buildSectionSkipMessage } from "./planningSession";
import { stageConfirmKeys } from "../stages/planStageDerive";
import { featuresAwaitingConfirm } from "../issues/featureList";
import { shouldAutoCompleteGate } from "../stages/focusedPlan";
import type { stagesFrom } from "../stages/focusedPlan";
import type { Section } from "../github/ghStructure";
import type { BlueprintStage } from "../stages/blueprints";

type Stages = ReturnType<typeof stagesFrom>;

export function usePlanConfirmations(opts: {
  stages: Stages;
  focusActiveIdx: number;
  sections: Section[];
  planSecs: BlueprintStage[];
  confirmedSet: Set<string>;
  featureState: Parameters<typeof featuresAwaitingConfirm>[0];
  featureCycle: string[];
  effectiveProjectId: string;
  paneId: string;
  confirmPlanStage: (projectId: string, key: string) => void;
  skipPlanStage: (projectId: string, key: string) => void;
  autoCompleteGates: boolean;
  /** autoPlanWithClaude && llmHasKey — the autopilot is running (and owns confirmation). */
  autoPlanActive: boolean;
}) {
  const {
    stages, focusActiveIdx, sections, planSecs, confirmedSet, featureState, featureCycle,
    effectiveProjectId, paneId, confirmPlanStage, skipPlanStage, autoCompleteGates, autoPlanActive,
  } = opts;

  // The active stage's drafted sections "approve & continue" confirms in one click (#807-followup)
  // — so the user approves a whole stage at once. Empty ⇒ nothing pending (the gate drives the button).
  const pendingConfirm = useMemo(() => {
    const activeKey = stages[focusActiveIdx]?.key;
    const activeSec = activeKey ? planSecs.find((s) => s.key === activeKey) : undefined;
    const base = stageConfirmKeys(activeKey, sections, !!activeSec?.gateRule, !!activeKey && confirmedSet.has(activeKey));
    // Features (#plan-db): once every feature in the roster is populated, offer the one-click confirm
    // that completes the stage. Until then the gate holds, so a single feature can't auto-advance.
    if (activeKey === FEATURES_KEY && featuresAwaitingConfirm(featureState, confirmedSet.has(FEATURES_KEY)) && featureCycle.length === 0) {
      return base.includes(FEATURES_KEY) ? base : [...base, FEATURES_KEY];
    }
    return base;
  }, [stages, focusActiveIdx, sections, planSecs, confirmedSet, featureState, featureCycle]);

  // The single stage-completion primitive (#1068): confirm each pending section + tell the planner to
  // continue. One path every gate advances through, so behaviour stays identical whether the user
  // clicks, the autopilot drives, or a gate self-advances.
  const confirmStageKeys = useCallback((keys: string[]) => {
    if (keys.length === 0) return;
    for (const k of keys) confirmPlanStage(effectiveProjectId, k);
    const name = keys.map((k) => titleForTopic(k)).join(", ") || "section";
    fireInvoke("pty_write", { paneId, data: buildSectionConfirmMessage(name) + "\r" }, console.error);
  }, [effectiveProjectId, paneId, confirmPlanStage]);

  // Auto-advance gates (#1068): when the global flag is on and the ACTIVE stage has drafted sections
  // awaiting confirmation, confirm them automatically after a short beat — the same action the
  // "approve & continue" button performs. Default off. Steps aside while the autopilot runs. The ref
  // stops a ready set from being re-confirmed on every render.
  const autoConfirmRef = useRef<string>("");
  useEffect(() => {
    if (!shouldAutoCompleteGate(autoCompleteGates, autoPlanActive, pendingConfirm)) return;
    const key = `${effectiveProjectId}|${pendingConfirm.join(",")}`;
    if (autoConfirmRef.current === key) return;
    const t = setTimeout(() => {
      autoConfirmRef.current = key;
      confirmStageKeys(pendingConfirm);
    }, 800);
    return () => clearTimeout(t);
  }, [autoCompleteGates, autoPlanActive, pendingConfirm, effectiveProjectId, confirmStageKeys]);

  // The user deliberately skips the active optional stage (#921): resolve its gate + tell the planner.
  const onSkipStage = useCallback(() => {
    const stage = stages[focusActiveIdx];
    if (!stage) return;
    skipPlanStage(effectiveProjectId, stage.key);
    fireInvoke("pty_write", { paneId, data: buildSectionSkipMessage(stage.name) + "\r" }, console.error);
  }, [stages, focusActiveIdx, skipPlanStage, effectiveProjectId, paneId]);

  return { pendingConfirm, confirmStageKeys, onSkipStage };
}

runtime.features/planner/session/usePlanFocusedP:
// usePlanFocusedPane (#1490/#652, extracted from Planning.tsx) — the focused-pane SELECTION and its
// derived advance-bar/pill/prompt-help. Owns `focusSel` (null = auto-follow the active stage; a
// number = a user-pinned selection), resets it on a project/blueprint switch, and derives:
//   • focusSelectedIdx — the clamped resolved index (selection ?? active).
//   • focusFooter — the advance-bar action (footerAction → resolveFooter); the primary is lit by
//     pendingConfirm, and a Skip control (skipEnabled) RENDERS only when the active stage is
//     skippable now (its `skipWhen` rule passes / it's optional) or gate-override is on (#2854).
//   • focusPill — the selected stage's gate pill.
//   • focusStagePrompt — the SINGLE current-step prompt for the SELECTED stage (the header "?"
//     helper), resolved from the stage's substep progress (#2859).
// The JSX wires `setFocusSel` into onSelect/onBack/onSkip/onPrimary. Behavior-preserving move — the
// state, reset effect, and derivations are verbatim; only their call-site moved below usePlanGates +
// usePlanConfirmations (whose `pendingConfirm` the footer reads). The skip/confirm/publish actions
// stay in the component (they close over usePlanConfirmations + usePlanPublish).
import { useState, useEffect, useMemo } from "react";
import { clampIndex, gatePill, footerAction, resolveFooter, type stagesFrom } from "../stages/focusedPlan";
import { activeStagePrompt } from "./plannerConductor";
import type { BlueprintStage } from "../stages/blueprints";

type Stages = ReturnType<typeof stagesFrom>;

export interface PlanFocusedPaneOpts {
  /** The blueprint-driven focused-pane stages (from usePlanGates). */
  stages: Stages;
  /** The live active-stage index (from usePlanGates). */
  focusActiveIdx: number;
  /** Whether the whole plan's gate is met (from usePlanGates). */
  planComplete: boolean;
  /** Whether the active stage's gate is satisfied (from usePlanGates). */
  focusGateReady: boolean;
  /** The active stage's drafted-but-unconfirmed sections (from usePlanConfirmations) — lights the
   *  "approve & continue" footer. */
  pendingConfirm: string[];
  /** Gate-override toggle (#1285) — allows force-advancing a blocking gate. */
  allowGateOverride: boolean;
  /** The blueprint's stages — resolves the selected stage's injectable prompts by key (#815). */
  planSecs: BlueprintStage[];
  /** #2859 — the substep keys already resolved for the current plan (a section file written or a
   *  step confirmed), so the "?" helper can pick the CURRENT-step prompt via `activeSubstep`. */
  stageDone: Set<string>;
  /** #2859 — whether the Features workshop loop is complete (every feature defined), the completion
   *  signal for the one loop substep the "?" helper can't infer from written section files. */
  featuresComplete: boolean;
  /** #2121 — the active UI stage's design is missing or stale (not routed / changed since routed),
   *  so its primary footer action becomes "route design" instead of "approve & continue". */
  uiNeedsRoute: boolean;
  /** Selection resets when either changes. */
  effectiveProjectId: string;
  effectiveBlueprintId: string;
}

export function usePlanFocusedPane(opts: PlanFocusedPaneOpts) {
  const {
    stages, focusActiveIdx, planComplete, focusGateReady, pendingConfirm,
    allowGateOverride, planSecs, effectiveProjectId, effectiveBlueprintId, uiNeedsRoute,
    stageDone, featuresComplete,
  } = opts;

  // The SELECTION — auto-follows the active stage (`focusSel` null) or pins to a user pick; reset on
  // project/blueprint switch. `stages`/`focusActiveIdx` come from usePlanGates.
  const [focusSel, setFocusSel] = useState<number | null>(null);
  useEffect(() => { setFocusSel(null); }, [effectiveProjectId, effectiveBlueprintId]);
  const focusSelectedIdx = clampIndex(focusSel ?? focusActiveIdx, stages.length);

  // Whether the active stage is SKIPPABLE right now (#2854) — its declarative `skipWhen` rule passes
  // (e.g. an empty Features stage) or it's intrinsically optional. This drives whether the footer
  // renders a Skip control AT ALL: a required stage like Discovery shows none (no disabled ghost).
  const activeSkippable = stages[focusActiveIdx]?.skippable === true;
  // #2121: on the active UI stage with missing/stale design, the primary action routes the design.
  const routeDesign = stages[focusActiveIdx]?.key === "ui" && uiNeedsRoute;
  const footerRaw = footerAction(focusSelectedIdx, focusActiveIdx, planComplete, focusGateReady, routeDesign);
  // Let "approve & continue" light up as soon as there are drafted sections to confirm (clicking
  // confirms them, see onPrimary); resolveFooter also sets `skipEnabled` from skippable + override.
  const focusFooter = resolveFooter(footerRaw, pendingConfirm.length, allowGateOverride, activeSkippable);
  const focusSelStage = stages[focusSelectedIdx];
  const focusPill = focusSelStage ? gatePill(focusSelStage) : "wait";
  // The SINGLE current-step prompt for the SELECTED stage — the header "?" helper shows one prompt at
  // a time (#2859), resolved from substep progress (`activeSubstep`). The only loop substep the helper
  // can't infer from written files is the Features workshop, so `loopDone` is fed only for that stage.
  // Resolve the section BY KEY (stages is a filtered subset of planSecs, #815).
  const selKey = focusSelStage?.key;
  const focusStagePrompt = useMemo(
    () => activeStagePrompt(planSecs.find(s => s.key === selKey), stageDone, selKey === "features" && featuresComplete),
    [planSecs, selKey, stageDone, featuresComplete]);

  return { setFocusSel, focusSelectedIdx, focusPill, focusFooter, focusStagePrompt };
}

runtime.features/planner/session/usePlanGates.ts:
// usePlanGates (#1474) — the planner's gate/`signals` derivation, extracted verbatim from
// Planning.tsx. Owns the live `stageState` snapshot, the lint/injection gates, the skip/confirm
// signal bags, the flat `signals` bag the declarative section gates read, and the focused-pane
// derivations (`stages`, active index, current-gate-ready, plan-complete, status label).
//
// Pure derivation, no side effects. `planSecs` (the blueprint sections) and the focused-pane
// SELECTION state (`focusSel`/`focusSelectedIdx`/`focusSelStage`) STAY in Planning and are passed
// in / read off this hook's outputs — only the auto-derived `stages`/`focusActiveIdx` move here.

import { useMemo } from "react";
import type { Section } from "../github/ghStructure";
import type { BlueprintStage } from "../stages/blueprints";
import { skippedSignal, confirmedSignal, planStagesComplete } from "../stages/blueprints";
import { derivePlanStageState, planStateToSignals } from "../stages/planStageDerive";
import { FEATURES_KEY } from "../stages/planTopics";
import { parseIssuesFile } from "../issues/planIssues";
import { featuresGateComplete, featuresSummary } from "../issues/featureList";
import { findPlanGaps } from "../lib/lintPlan";
import { findPlanInjections, injectionGate } from "../lib/planInjection";
import { deploymentDefined } from "../lib/deployConfig";
import { marketDefined } from "../lib/marketConfig";
import { transformationsConfirmed, type TransformationRow } from "../lib/transformations";
import { allSourcesConnected, migrationActive, dataModelSignals } from "../lib/sourceConfig";
import { unlockedSharedRepos } from "../issues/dependencies";
import { stagesFrom, activeIndex, currentGateReady } from "../stages/focusedPlan";
import { classifySignals, type ClassifyConfig } from "../lib/classifyConfig";

interface PlanGatesDeps {
  sections: Section[];
  /** The active blueprint's sections (stays in Planning; passed in as gate input). */
  planSecs: BlueprintStage[];
  ctxRequired: string[];
  publishRepos: string[];
  planFleet: Record<string, { streams: { id: string; repo: string }[] }>;
  planAutomations: Record<string, unknown[]>;
  featureIssues: unknown[];
  effectiveProjectId: string;
  requiresUi: boolean;
  uiCounts: { approved: number; total: number };
  featureState: ReturnType<typeof featuresSummary>;
  featureCycle: string[];
  confirmedSet: Set<string>;
  skippedSet: Set<string>;
  planDependencies: Parameters<typeof unlockedSharedRepos>[0];
  sourceCfg: Parameters<typeof migrationActive>[0];
  injectionHardGate: boolean;
  planInjectionAck: Record<string, string>;
  deployCfg: Parameters<typeof deploymentDefined>[0];
  /** The market-stage assessment (#2430) — drives the `marketDefined` gate signal. */
  marketCfg: Parameters<typeof marketDefined>[0];
  /** The transformations rows (#2509) — drive the `transformationsConfirmed` gate signal. */
  transformationRows: TransformationRow[];
  /** The planner's per-project classification (#3784) — drives the source/mcp/skills/automations
   *  visibility signals (all default OFF → those stages hidden until the planner opts in), plus the
   *  app-type / lifecycle signals (`appType:*`, `lifecycle:*`, `hasUserInterface`) a stage's
   *  `appliesWhen` keys on. */
  classifyCfg: ClassifyConfig | undefined;
  /** How many skills the project has (resolveSkills length) — the skills stage also shows when a
   *  project has >=1 skill even if the planner didn't pre-flag needsSkills (research -> skills). */
  projectSkillCount: number;
}

export function usePlanGates(deps: PlanGatesDeps) {
  const {
    sections, planSecs, ctxRequired, publishRepos, planFleet, planAutomations,
    featureIssues, effectiveProjectId, requiresUi, uiCounts, featureState, featureCycle,
    confirmedSet, skippedSet, planDependencies, sourceCfg, injectionHardGate, planInjectionAck,
    deployCfg, marketCfg, transformationRows, classifyCfg, projectSkillCount,
  } = deps;

  // The live snapshot the declarative section gates read.
  const stageState = useMemo(() => {
    const streams = planFleet[effectiveProjectId]?.streams ?? [];
    const issueCount =
      parseIssuesFile(sections.find(s => s.k === "issues")?.content ?? "").length + featureIssues.length;
    return derivePlanStageState({
      sections: sections.map(s => ({ k: s.k, state: s.state })),
      discoveryRequired: ctxRequired,
      repoCount: publishRepos.length,
      issueCount,
      fleetStreams: streams.length,
      // Unified role→profile model: every stream auto-gets its role's default profile at launch
      // (no per-stream generated profile to assign), so "profiles complete" simply means the fleet
      // has been planned — i.e. there are streams.
      fleetProfilesComplete: streams.length > 0,
      automationsAck: (planAutomations[effectiveProjectId]?.length ?? 0) > 0,
      // #3905: was hardcoded `false`, which made the Skills gate ("assign skills to the fleet")
      // UNSATISFIABLE — nothing ever set it true, so once the stage applied it blocked the plan
      // forever and triage became unreachable. Derived like `automationsAck` above: the fleet has
      // skills once the project resolves at least one. A project the planner flagged `needsSkills`
      // but assigned NO skills still blocks, which is exactly what the gate label means.
      skillsAck: projectSkillCount > 0,
      requiresUi,
      ui: uiCounts,
      // Routing dropped design files to the project completes the UI stage — recorded as a
      // confirmation of the `ui` section so it persists (#837).
      uiRouted: confirmedSet.has("ui"),
      // Features completes ONLY when every feature is populated AND the user has confirmed the set
      // (#plan-db) — `allConfirmed` (all-defined) alone used to auto-advance after a single feature.
      // Folding the user-confirm in here keeps the gate signal (`featuresConfirmed`) unchanged.
      features: { count: featureState.count, allConfirmed: featuresGateComplete(featureState, confirmedSet.has(FEATURES_KEY)) && featureCycle.length === 0 },
      // Dependencies (#1111/#1127): the Deploy gate passes once ≥1 library is locked in the manifest.
      dependencies: { count: planDependencies.length },
      // Source migration (#1205): the scan drives whether the source stage applies + its gate
      // signals, so the source-inferred schema can dictate features/structure.
      migrationSourceEnabled: migrationActive(sourceCfg),
      dataModelSignals: dataModelSignals(sourceCfg),
    });
  }, [sections, ctxRequired, publishRepos, planFleet, planAutomations, featureIssues, effectiveProjectId, requiresUi, uiCounts, featureState, featureCycle, confirmedSet, planDependencies, sourceCfg]);
  // lint-as-gate (#897 Phase 4b — lint-plan folded into the declarative gate). A WRITTEN section
  // (drafted/confirmed; pending ones aren't authored yet) must not carry a deliberate "fill this
  // in later" marker (TODO / TBD / FIXME / XXX / TKTK). Scanned ONLY over sections that belong to
  // the ACTIVE blueprint (so stale files from a prior blueprint can't block), and only those
  // markers — NOT ellipsis or the word "placeholder", which are normal prose and were
  // false-positiving (#918). Surfaced as `hasPlanGaps`; the gate requires it false, absent-safe.
  const hasPlanGaps = useMemo(() => {
    const enabled = new Set(planSecs.map((s) => s.key));
    const written: Record<string, string> = {};
    for (const s of sections) if (s.state !== "pending" && enabled.has(s.k)) written[`${s.k}.md`] = s.content ?? "";
    return findPlanGaps(written).some((g) => g.endsWith("unresolved placeholder"));
  }, [sections, planSecs]);
  // Plan-injection provenance gate (#1107): scan the planner-authored section prose for injected
  // instructions, then gate plan→fleet promotion. Acknowledge-to-clear by default; hard-block when
  // the `injectionHardGate` setting is on. Surfaced as a banner; `cleared` gates publish.
  const injectionGateState = useMemo(() => {
    const enabled = new Set(planSecs.map((s) => s.key));
    const written: Record<string, string> = {};
    for (const s of sections) if (s.state !== "pending" && enabled.has(s.k)) written[`${s.k}.md`] = s.content ?? "";
    return injectionGate(findPlanInjections(written), { hardGate: injectionHardGate, ackSig: planInjectionAck[effectiveProjectId] });
  }, [sections, planSecs, injectionHardGate, planInjectionAck, effectiveProjectId]);
  // User-skipped optional stages (#921) surface as `skipped:<key>` signals so the data-driven
  // gate model (`stageDone`) treats them as resolved.
  const skipSignals = useMemo(() => {
    const out: Record<string, boolean> = {};
    for (const k of skippedSet) out[skippedSignal(k)] = true;
    return out;
  }, [skippedSet]);
  // A gateless ("informational") section is done only once CONFIRMED (#664) — `stageDone` reads a
  // `confirmed:<key>` signal. Workspace those so a confirmed gateless stage (testing, cleanup, the data
  // stages, a user-authored stage, …) reads as complete and the frontier advances (#954).
  const confirmSignals = useMemo(() => {
    const out: Record<string, boolean> = {};
    for (const k of confirmedSet) out[confirmedSignal(k)] = true;
    return out;
  }, [confirmedSet]);
  const signals = useMemo(() => {
    // Shared-deps gate (#1429): every repo built by 2+ streams must have its deps locked; single-owner
    // repos (and no-fleet plans) auto-satisfy. Derived from the fleet streams' repos + the manifest.
    const repoStreams: Record<string, string[]> = {};
    for (const s of (planFleet[effectiveProjectId]?.streams ?? [])) { if (s.repo) (repoStreams[s.repo] ??= []).push(s.id); }
    const sharedDepsLocked = unlockedSharedRepos(planDependencies, repoStreams).length === 0;
    // The Structure/Plan gate (#1912): the feature DAG is defined (≥1 feature) and acyclic. This
    // replaced the old `featuresPhased` (every feature assigned a roadmap phase) — sequencing is now
    // expressed purely via feature `dependsOn`, with no milestone phases.
    const featuresDefined = featureState.count > 0 && featureCycle.length === 0;
    return { ...planStateToSignals(stageState), hasPlanGaps, featuresDefined, deploymentDefined: deploymentDefined(deployCfg), marketDefined: marketDefined(marketCfg), transformationsConfirmed: transformationsConfirmed(transformationRows), sharedDepsLocked, sourcesConnected: allSourcesConnected(sourceCfg), classified: classifyCfg !== undefined, needsMarket: !!classifyCfg?.needsMarket, needsSource: !!classifyCfg?.needsSource, needsMcp: !!classifyCfg?.needsMcp, needsAutomations: !!classifyCfg?.needsAutomations, needsSkills: !!classifyCfg?.needsSkills || projectSkillCount > 0, ...classifySignals(classifyCfg), ...skipSignals, ...confirmSignals };
  }, [stageState, hasPlanGaps, featureState, featureCycle, deployCfg, marketCfg, transformationRows, sourceCfg, skipSignals, confirmSignals, planFleet, effectiveProjectId, planDependencies, classifyCfg, projectSkillCount]);

  // Focused pane (#652): one stage at a time. `stages` derive from the blueprint sections +
  // signals; the active stage auto-follows the frontier (the user-pick SELECTION stays in Planning).
  const stages = useMemo(() => stagesFrom(planSecs, signals), [planSecs, signals]);
  const focusActiveIdx = useMemo(() => activeIndex(stages), [stages]);
  const focusGateReady = useMemo(() => currentGateReady(planSecs, signals), [planSecs, signals]);
  const planComplete = useMemo(() => planStagesComplete(planSecs, signals), [planSecs, signals]);
  const currentStage = stages[focusActiveIdx]?.key ?? "";
  const planStatusLabel = planComplete ? "complete" : currentStage ? "in_progress" : "starting";
  // Legacy alias kept for the publish/recovery readers (#854): the dynamic blueprint gate IS the
  // completion gate.
  const planReady = planComplete;

  return { injectionGateState, stages, focusActiveIdx, focusGateReady, planComplete, currentStage, planStatusLabel, planReady };
}

runtime.features/planner/session/usePlanMcpDownl:
// usePlanMcpDownloads (#1474) — the planner's MCP download-confirmation queue, extracted verbatim
// from Planning.tsx. A blueprint / planner-assigned first-party MCP server can install from source;
// rather than cloning that third-party code silently, each not-yet-installed server is queued here
// and surfaced in a modal for the user to confirm. `enqueueMcpDownloads` is a stable callback safe
// to call from the blueprint effect AND the plan.db poll without staleness; `confirm` clones+builds
// the queue; `cancel` dismisses it (keeping the seen-set so skipped servers don't re-prompt).

import { useCallback, useRef, useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { catalogLink, repoNameFromLink } from "@/features/mcp";
import { type McpDownloadItem } from "../pane/McpDownloadModal";
import { MCP_CATALOG } from "@/shared/data/mcpCatalog";

export interface PlanMcpDownloads {
  /** Queue downloadable catalog servers (by name) for the confirmation modal, skipping any already
   *  installed or already queued. */
  enqueueMcpDownloads: (names: string[]) => Promise<void>;
  /** The pending download queue (rendered by McpDownloadModal). */
  mcpDownloads: McpDownloadItem[];
  /** Download (clone + build) every still-pending/failed queued server, advancing its row status. */
  confirmMcpDownloads: () => Promise<void>;
  /** Dismiss the modal: drop the queue but keep the seen-set so skipped servers don't re-prompt. */
  cancelMcpDownloads: () => void;
}

export function usePlanMcpDownloads(): PlanMcpDownloads {
  // Download-confirmation queue (#1055): the blueprint a project uses and the servers the planner
  // assigns can pull in first-party MCP servers that install from source. Instead of cloning that
  // third-party code silently, we queue each not-yet-installed server here and surface a modal with
  // its repo link; the user confirms before anything downloads. `mcpDownloadSeen` guards against
  // re-queuing the same server (so a re-applied blueprint / poll tick doesn't nag).
  const [mcpDownloads, setMcpDownloads] = useState<McpDownloadItem[]>([]);
  const mcpDownloadSeen = useRef<Set<string>>(new Set());

  // Queue downloadable catalog servers (by name) for the confirmation modal, skipping any already
  // installed or already queued. State-free (refs + functional setState) so it's a stable callback
  // safe to invoke from the blueprint effect AND the plan.db poll without staleness.
  const enqueueMcpDownloads = useCallback(async (names: string[]) => {
    const fresh: McpDownloadItem[] = [];
    for (const name of names) {
      const link = catalogLink(name);
      if (!link) continue; // not a downloadable first-party server
      const key = name.toLowerCase();
      if (mcpDownloadSeen.current.has(key)) continue;
      const repo = repoNameFromLink(link);
      try {
        const r = await invoke<{ downloaded: boolean; built: boolean }>("mcp_status", { name: repo });
        if (r.downloaded && r.built) { mcpDownloadSeen.current.add(key); continue; } // already installed
      } catch { /* not installed → prompt */ }
      mcpDownloadSeen.current.add(key);
      const cat = MCP_CATALOG.find((c) => c.name.toLowerCase() === key);
      fresh.push({ name, repo, link, desc: cat?.desc, install: cat?.install, status: "pending" });
    }
    if (fresh.length) setMcpDownloads((prev) => [...prev, ...fresh]);
  }, []);

  // Download (clone + build) every still-pending/failed queued server, advancing its row status.
  const confirmMcpDownloads = useCallback(async () => {
    const setStatus = (name: string, status: McpDownloadItem["status"]) =>
      setMcpDownloads((p) => p.map((d) => (d.name === name ? { ...d, status } : d)));
    const targets = mcpDownloads.filter((d) => d.status === "pending" || d.status === "error");
    await Promise.all(targets.map(async (it) => {
      setStatus(it.name, "downloading");
      try { await invoke("mcp_clone", { name: it.repo, url: it.link }); }
      catch { setStatus(it.name, "error"); return; }
      setStatus(it.name, "building");
      try {
        const r = await invoke<{ ok: boolean }>("mcp_build", { name: it.repo });
        setStatus(it.name, r.ok ? "ready" : "error");
      } catch { setStatus(it.name, "error"); }
    }));
  }, [mcpDownloads]);

  // Dismiss the modal: drop the queue but keep the seen-set so skipped servers don't immediately
  // re-prompt (the user can still install them later from the MCP screen).
  const cancelMcpDownloads = useCallback(() => setMcpDownloads([]), []);

  return { enqueueMcpDownloads, mcpDownloads, confirmMcpDownloads, cancelMcpDownloads };
}

runtime.features/planner/session/usePlanMcpManag:
// usePlanMcpManagement (#1474) — the planner's MCP install lifecycle, extracted verbatim from
// Planning.tsx (the download-confirmation queue is its own hook, usePlanMcpDownloads). Owns the
// disk-probe, the blueprint-attached-MCP scoping, the project + planner-session MCP context writes,
// and the toggle/add/build/remove handlers.
//
// `mcpInstallState` STAYS in Planning (it feeds the paneData memo); this hook only WRITES it via the
// passed `setMcpInstallState` (always functional updates), which breaks the paneData→probe render
// cycle with no behavior change. Call it immediately after paneData so `mcpServersUi` is available.

import { useCallback, useEffect, useMemo, type Dispatch, type SetStateAction } from "react";
import { invoke } from "@tauri-apps/api/core";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import { useAppStore } from "@/store";
import { applyBlueprintMcp, collectBlueprintMcp } from "../blueprints/blueprintMcp";
import { writeProjectMcpContext } from "../lib/mcpContext";
import { catalogLink, repoNameFromLink, mcpRepoName } from "@/features/mcp";
import { applyMcpAssign } from "../lib/planExtensions";
import { MCP_CATALOG } from "@/shared/data/mcpCatalog";
import { roleCapability, roleWriteRules, roleDeniedCommands } from "@/shared/lib/session/sessionRoles";
import { TURN_ACCOUNTING_HOOKS } from "@/shared/lib/session/turnHooks";
import { resolveAllInstalledMcp, toSessionPayloads, mcpAllowRules } from "@/features/mcp";
import { type McpInstallState } from "../lib/mcpPaneData";
import { type Blueprint } from "../stages/blueprints";

type StoreMcpServers = Parameters<typeof resolveAllInstalledMcp>[0];
/** The probe only reads id/name/downloadable off paneData.mcpServers. */
interface ProbeServer { id: string; name: string; downloadable?: boolean }

interface McpManagementDeps {
  effectiveProjectId: string;
  effectiveBlueprintId: string;
  blueprints: Blueprint[];
  planningDir: string;
  /** paneData.mcpServers — the UI server list the probe filters for downloadable servers. */
  mcpServersUi: ProbeServer[] | undefined;
  /** The store's mcpServers value — drives the installed-server context writes. */
  mcpServers: StoreMcpServers;
  /** Writes install status (functional updates only — the value lives in Planning, feeding paneData). */
  setMcpInstallState: Dispatch<SetStateAction<McpInstallState>>;
  /** Queue first-party MCP servers for the download-confirmation modal (from usePlanMcpDownloads). */
  enqueueMcpDownloads: (names: string[]) => Promise<void>;
}

export interface PlanMcpManagement {
  onToggleMcp: (id: string) => void;
  onRemoveMcp: (id: string) => void;
  onAddMcp: (input: string) => void;
  onBuildMcp: (s: { id: string; name: string; status: string }) => Promise<void>;
}

export function usePlanMcpManagement(deps: McpManagementDeps): PlanMcpManagement {
  const { effectiveProjectId, effectiveBlueprintId, blueprints, planningDir, mcpServersUi, mcpServers, setMcpInstallState, enqueueMcpDownloads } = deps;

  // Probe each downloadable MCP server's on-disk state so the pane opens with real status
  // (downloaded? built?) instead of "available" for already-installed servers.
  useEffect(() => {
    const probe = mcpServersUi?.filter(s => s.downloadable) ?? [];
    if (probe.length === 0) return;
    let cancelled = false;
    Promise.all(probe.map(async (s) => {
      try {
        const r = await invoke<{ downloaded: boolean; built: boolean }>("mcp_status", { name: mcpRepoName(s.name) });
        return [s.id, r.built ? "ready" : r.downloaded ? "downloaded" : "available"] as const;
      } catch { return [s.id, "available"] as const; }
    })).then((rows) => {
      if (cancelled) return;
      setMcpInstallState((prev) => {
        const next = { ...prev };
        // Don't clobber an in-flight downloading/building status with a probe result.
        for (const [id, st] of rows) if (next[id] !== "downloading" && next[id] !== "building") next[id] = st;
        return next;
      });
    });
    return () => { cancelled = true; };
    // Re-probe only when the set of downloadable server ids changes.
  }, [mcpServersUi?.filter(s => s.downloadable).map(s => s.id).join(",")]); // eslint-disable-line react-hooks/exhaustive-deps

  // Scope the active blueprint's attached MCP servers to this project (#897 Phase 2), so the
  // planner + fleet get the tools the blueprint declares. Idempotent (applyMcpAssign enables +
  // scopes existing, or adds). The downloadable (first-party) ones are queued for the
  // download-confirmation modal (#1055) rather than cloned silently. Re-runs when the project or
  // the blueprint's attached-MCP set changes.
  const bpMcpKey = useMemo(() => {
    const bp = blueprints.find(b => b.id === effectiveBlueprintId);
    return bp ? collectBlueprintMcp(bp).join("\n") : "";
  }, [blueprints, effectiveBlueprintId]);
  useEffect(() => {
    if (!effectiveProjectId || !bpMcpKey) return;
    const store = useAppStore.getState();
    const bp = store.blueprints.find(b => b.id === effectiveBlueprintId);
    if (!bp) return;
    void enqueueMcpDownloads(applyBlueprintMcp(store, bp, effectiveProjectId, store.bscBaseDir));
  }, [bpMcpKey, effectiveProjectId, effectiveBlueprintId, enqueueMcpDownloads]);

  // Write the planner's live extensions.md — the installed MCP servers it can call + the per-worker
  // assignment directive (#1054). Supersedes the static catalogue setup_workspaces used to write;
  // re-runs whenever the installed-server set or the project changes.
  const installedMcpKey = useMemo(
    () => resolveAllInstalledMcp(mcpServers).map((e) => `${e.id}:${e.name}`).join("\n"),
    [mcpServers],
  );
  useEffect(() => {
    if (!effectiveProjectId) return;
    void writeProjectMcpContext({ projectKey: effectiveProjectId, servers: resolveAllInstalledMcp(useAppStore.getState().mcpServers) })
      .catch((e) => console.warn("writeProjectMcpContext failed:", e));
  }, [installedMcpKey, effectiveProjectId]);

  // Keep the planner session's .mcp.json current as servers are downloaded (#1054). Claude loads MCP
  // config at startup, so a newly downloaded server is picked up on the planner's next launch /
  // resume; this keeps the file ready. No-op until the planner dir is known.
  useEffect(() => {
    if (!planningDir) return;
    const cap = roleCapability("planner");
    const write = roleWriteRules(cap);
    const mcp = toSessionPayloads(resolveAllInstalledMcp(useAppStore.getState().mcpServers), []).mcp;
    fireInvoke("ensure_session_settings", {
      cwd:             planningDir,
      allowedCommands: [],
      deniedCommands:  roleDeniedCommands(cap),
      mcpServers:      mcp,
      // Turn accounting (#3455): re-assert on the MCP refresh too. replacePermissions:true would
      // otherwise clear the launch-time turn hooks and re-blind the planner's cost.
      hooks:           TURN_ACCOUNTING_HOOKS,
      // Auto-approve every MCP server the planner is given (Research included) so calling them
      // while planning never hits a per-tool prompt — replacePermissions:true here would otherwise
      // drop the launch-time rules, so this refresh must re-assert them too.
      allowToolRules:  [...write.allow, "Read", "WebFetch", ...mcpAllowRules(mcp)],
      denyToolRules:   write.deny,
      replacePermissions: true,
    }, (e: unknown) => console.warn("planner mcp refresh failed:", e));
  }, [installedMcpKey, planningDir]);

  // ── MCP stage handlers (#878) ──────────────────────────────────────────────
  const onToggleMcp = useCallback((id: string) => useAppStore.getState().toggleMcpServer(id), []);
  const onRemoveMcp = useCallback((id: string) => useAppStore.getState().removeMcpServer(id), []);
  const onAddMcp = useCallback((input: string) => {
    const store = useAppStore.getState();
    // A bare catalog name maps to its template; anything with a scheme is a remote URL; else a
    // stdio command line. New servers are enabled + scoped to this project so the fleet gets them.
    const link = catalogLink(input);
    if (link || MCP_CATALOG.some(c => c.name.toLowerCase() === input.toLowerCase())) {
      const name = MCP_CATALOG.find(c => c.name.toLowerCase() === input.toLowerCase())?.name ?? input;
      applyMcpAssign(store, name, effectiveProjectId, store.bscBaseDir);
      if (link) fireInvoke("mcp_clone", { name: repoNameFromLink(link), url: link });
      return;
    }
    const isUrl = /^https?:\/\//i.test(input);
    store.addMcpServer({
      name: input.split(/\s+/)[0].slice(0, 40) || "server", enabled: true, projects: [effectiveProjectId],
      transport: isUrl ? "http" : "stdio",
      ...(isUrl ? { url: input } : { command: input.split(/\s+/)[0], args: input.split(/\s+/).slice(1).join(" ") }),
      env: [],
    });
  }, [effectiveProjectId]);
  const onBuildMcp = useCallback(async (s: { id: string; name: string; status: string }) => {
    const repo = mcpRepoName(s.name);
    const link = catalogLink(s.name);
    // Ensure it's downloaded, then build, tracking status so the pane reflects progress.
    if (link && (s.status === "available")) {
      setMcpInstallState(p => ({ ...p, [s.id]: "downloading" }));
      try { await invoke("mcp_clone", { name: repo, url: link }); }
      catch { setMcpInstallState(p => ({ ...p, [s.id]: "available" })); return; }
    }
    setMcpInstallState(p => ({ ...p, [s.id]: "building" }));
    try {
      const r = await invoke<{ ok: boolean }>("mcp_build", { name: repo });
      setMcpInstallState(p => ({ ...p, [s.id]: r.ok ? "ready" : "error" }));
    } catch {
      setMcpInstallState(p => ({ ...p, [s.id]: "error" }));
    }
  }, [setMcpInstallState]);

  return { onToggleMcp, onRemoveMcp, onAddMcp, onBuildMcp };
}

runtime.features/planner/session/usePlannerBluep:
// usePlannerBlueprint (#1474) — the planner's blueprint lifecycle derivation (orientation),
// extracted verbatim from Planning.tsx.

import { useMemo } from "react";
import { type Blueprint } from "../stages/blueprints";
import { plannerTreatAsExisting } from "./plannerIntro";

interface BlueprintDeps {
  blueprints: Blueprint[];
  effectiveBlueprintId: string;
  /** Whether the project is published (activeProjectId set) — the save-state proxy. */
  isExisting: boolean;
}

export interface PlannerBlueprint {
  activeBlueprint: Blueprint | undefined;
  treatAsExisting: boolean;
}

export function usePlannerBlueprint(deps: BlueprintDeps): PlannerBlueprint {
  const { blueprints, effectiveBlueprintId, isExisting } = deps;

  const activeBlueprint = useMemo(() => blueprints.find(b => b.id === effectiveBlueprintId), [blueprints, effectiveBlueprintId]);
  // #1286: the planner's orientation (its intro greeting AND its generated CLAUDE.md spec) follows
  // the blueprint's lifecycle MODE — an operate-mode blueprint (transform/harden/maintain) takes the
  // "existing repos" orientation even on a fresh draft, where the bare `isExisting` (saved-project)
  // proxy would mis-greet it as a new greenfield project. Plain `isExisting` stays for the
  // drafting/expanding UI labels (genuinely about save-state).
  const treatAsExisting = plannerTreatAsExisting({ isSaved: isExisting, mode: activeBlueprint?.mode });

  return { activeBlueprint, treatAsExisting };
}

runtime.features/planner/session/usePlannerMessa:
// usePlannerMessages (#1775, extracted from Planning.tsx) — while the relay is paired, poll the
// planner PTY's transcript (newest 50 turns) so a phone mirrors the real chat, not the raw terminal.
// Empty + inert when not paired. (#934/#987)
import { useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { usePoll } from "@/shared/hooks/usePoll";
import type { PlanMessage } from "@/features/tunnel";

export function usePlannerMessages(tunnelRunning: boolean, paneId: string): PlanMessage[] {
  const [plannerMessages, setPlannerMessages] = useState<PlanMessage[]>([]);
  usePoll((isCancelled) => {
    if (!tunnelRunning) return;
    return invoke<PlanMessage[]>("read_pane_messages", { paneId, limit: 50 })
      .then((m) => { if (!isCancelled()) setPlannerMessages(m ?? []); })
      .catch(() => {});
  }, 3000, [tunnelRunning, paneId]);
  return plannerMessages;
}

runtime.features/planner/session/usePlannerPromp:
// Deliver a queued planner prompt into the live planning session (#1371). The focused pane
// queues an ad-hoc prompt via `requestPlannerPrompt` (e.g. the file-intake "Route to project"
// ROUTE_PROMPT, which tells the planner to route the dropped design/ files into the repo). That
// value used to be a dead drop — set in the store but never delivered — so design files were
// staged and the UI gate auto-completed, yet the planner was never told to route them.
//
// This hook closes that gap: when a prompt is queued for the active project, it injects it into
// the planner PTY (via the caller's `sendPrompt`) and clears it. Delivery is user-initiated (a
// button click queued it), so this does NOT resurrect the removed auto-injecting conductor.

import { useEffect } from "react";
import { useAppStore } from "@/store";

/**
 * Drain `pendingPlannerPrompt[projectId]` into the live planner session.
 * @param projectId  the active planning session key (`effectiveProjectId`)
 * @param sendPrompt injects one prompt into the planner PTY (Planning.tsx's `sendPrompt`)
 */
export function usePlannerPromptDelivery(projectId: string, sendPrompt: (prompt: string) => void) {
  const pending = useAppStore((s) => (projectId ? s.pendingPlannerPrompt[projectId] : undefined));
  const clearPlannerPrompt = useAppStore((s) => s.clearPlannerPrompt);
  useEffect(() => {
    if (!projectId || !pending) return;
    sendPrompt(pending);
    clearPlannerPrompt(projectId);
  }, [projectId, pending, sendPrompt, clearPlannerPrompt]);
}

runtime.features/planner/session/usePlannerRepoM:
// usePlannerRepoManagement (#1474) — the planner's headless repo auto-clone, extracted verbatim
// from Planning.tsx. Eagerly clones each linked repo into the project dir as it appears, persisting
// the link in plan.db. The linked set is DB-owned: the planner runs `bsc plan repo add owner/repo`,
// the section poll reflects `plan_list_repos` into `effectiveRepos`, and this effect clones each new
// entry. Side-effect only — returns nothing.

import { useEffect, useRef } from "react";
import { invoke } from "@tauri-apps/api/core";
import { bscRun } from "@/shared/lib/core/bsc";
import { useAppStore } from "@/store";

export function usePlannerRepoManagement(effectiveProjectId: string, effectiveRepos: string[]): void {
  // Eager auto-clone (#508): the visible repo strip was removed from the header, but its clone
  // engine lives on headlessly here. Each linked repo (surfaced via the plan.db poll) is cloned
  // into the project dir as soon as it appears, populating projectLocalRepos → linkedRepos →
  // setup_workspaces, so the planner can read repo contents during planning (triage launch
  // re-clones fail-soft, but that's too late for in-session context). Idempotent on the Rust side.
  const autoCloneRef = useRef<Set<string>>(new Set());
  useEffect(() => {
    if (!effectiveProjectId) return;
    const cloned = new Set(useAppStore.getState().projectLocalRepos[effectiveProjectId] ?? []);
    for (const fullName of effectiveRepos) {
      if (cloned.has(fullName) || autoCloneRef.current.has(fullName)) continue;
      autoCloneRef.current.add(fullName);
      invoke<string>("clone_repo", { project: effectiveProjectId, fullName })
        .then(() => {
          useAppStore.getState().addProjectRepo(effectiveProjectId, fullName);
          // Persist the link in the hub's plan.db (#1012) — durable across a store/app-state reset,
          // which the store-only persistence didn't survive.
          void bscRun(effectiveProjectId, ["plan", "repo", "add", fullName]);
        })
        .catch(e => console.error(`clone ${fullName} failed:`, e))
        .finally(() => autoCloneRef.current.delete(fullName));
    }
  }, [effectiveProjectId, effectiveRepos]);
}

runtime.features/planner/session/usePlannerTagSt:
// usePlannerTagStream (#1474) — the planner's PTY output buffer. Owns the two output buffers and a
// `processChunk` that, per PTY data chunk, strips ANSI, accumulates, and caps the buffer. The
// planner used to emit structured `<tag>`s parsed here; every one has since moved to plan.db via a
// `bsc plan …` command reflected by the section poll (the last, `<plan_focus>`, removed in #2017),
// so this hook no longer parses anything — it just maintains the buffers the autopilot reads.
//
//   bufRef         — the accumulated output buffer (the caller's restart clears it)
//   autopilotTxRef — an UN-consumed copy of the same output, read by the autopilot idle-detector
//
// Both refs are returned so the caller's restart (clears bufRef) and autopilot (reads
// autopilotTxRef) keep their existing access. `processChunk` is a stable callback, so the
// once-attached `pty_data` listener is set up a single time.

import { useCallback, useRef } from "react";
import { stripAnsi } from "./planningTerminal";

export interface PlannerTagStream {
  /** Feed one PTY data chunk: accumulate it and parse/dispatch any structured tags it completes. */
  processChunk: (payload: string) => void;
  /** The tag-scan buffer (the caller's restart clears it). */
  bufRef: React.MutableRefObject<string>;
  /** The un-consumed output copy the autopilot idle-detector reads. */
  autopilotTxRef: React.MutableRefObject<string>;
}

export function usePlannerTagStream(): PlannerTagStream {
  // Accumulated stripped output. Historically drained by the tag parsers as they consumed tags;
  // every planner tag now writes to plan.db via `bsc plan …` and is reflected by the section poll,
  // so nothing is parsed here anymore (the last, `<plan_focus>`, was removed in #2017). The buffer +
  // its un-consumed autopilot copy remain: the autopilot idle-detector (#746) reads them, and the
  // cap keeps them bounded.
  const bufRef = useRef("");
  // Autopilot (#746): an un-consumed copy of the planner's raw output, for idle-detection + user-sim.
  const autopilotTxRef = useRef("");

  const processChunk = useCallback((payload: string) => {
    bufRef.current += stripAnsi(payload);
    autopilotTxRef.current += stripAnsi(payload); // un-consumed copy for the autopilot (#746)

    // Cap buffer to prevent unbounded growth while preserving any partial
    // in-progress tag that hasn't received its closing counterpart yet.
    const MAX_BUF = 120_000;
    if (bufRef.current.length > MAX_BUF) {
      const lastTagStart = bufRef.current.lastIndexOf("<");
      bufRef.current = bufRef.current.slice(
        lastTagStart > 0 && lastTagStart > bufRef.current.length - MAX_BUF
          ? lastTagStart
          : bufRef.current.length - MAX_BUF
      );
    }
  }, []);

  return { processChunk, bufRef, autopilotTxRef };
}

runtime.features/planner/session/usePlannerTermi:
// usePlannerTerminal (#1775, extracted from Planning.tsx) — owns the planner's xterm.js terminal
// and its PTY lifecycle:
//   • mount — create the terminal + fit addon, subscribe to pty_data/pty_exit, run setup_workspaces
//     (the isolated planning dir + CLAUDE.md), write the plan-only role gate into session settings,
//     and spawn `claude` with the fresh-only intro prompt. pty_kill on unmount ends it cleanly.
//   • re-fit — re-measure when the panel becomes visible (hidden → shown), after a short delay, and
//     once the mono font loads (cell metrics are wrong until then).
//   • re-sync — re-run setup_workspaces when a linked repo resolves after the initial mount.
// This is a behavior-preserving move out of the component; the once-effect deps (and the two
// eslint-disables they require) are reproduced exactly — NO logic change.
import { useEffect, type RefObject, type MutableRefObject } from "react";
import type { Terminal } from "@xterm/xterm";
import { invoke } from "@tauri-apps/api/core";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { useAppStore } from "@/store";
import { roleCapability, roleDeniedCommands, roleWriteRules } from "@/shared/lib/session/sessionRoles";
import { useScreenSession } from "@/shared/lib/session/useScreenSession";
import { TURN_ACCOUNTING_HOOKS } from "@/shared/lib/session/turnHooks";
import { resolveAllInstalledMcp, toSessionPayloads, mcpAllowRules } from "@/features/mcp";
import { plannerIntroMode, composePlannerIntro } from "./plannerIntro";
import { plannerLaunchConfig } from "./plannerLaunch";
import { resolvePlannerSandbox } from "./plannerSandbox";
import { TERM_THEME } from "@/app/console/lib/terminalConstants";
import type { Command, Schedule } from "@/shared/data/mock";

export interface PlannerTerminalOpts {
  paneId: string;
  /** Whether the planning panel is on-screen — drives the re-fit effect. */
  visible: boolean;
  effectiveProjectId: string;
  /** full_names linked + cloned for this project; drives the post-mount workspace re-sync. */
  linkedRepos: string[];
  treatAsExisting: boolean;
  activeProjectName: string;
  activeProjectNumber: number;
  planningPitch: string;
  /** The blueprint's enabled stage ids for a project key — scopes the planner CLAUDE.md (#A). */
  stageIdsFor: (key: string) => string[];
  /** Re-read the setup baseline after a workspace setup (#756). */
  refreshSetupSig: () => void;
  /** Parse structured <tag>s out of the stripped PTY output stream (#1474, usePlannerTagStream). */
  processChunk: (chunk: string) => void;
  commands: Command[];
  schedules: Schedule[];
  /** Write the resolved planner hub dir up to the owning component (read by the MCP + tunnel wiring,
   *  so the state cell lives in Planning where those earlier hooks can see it) (#801). */
  setPlanningDir: (dir: string) => void;
}

export interface PlannerTerminalHandle {
  /** Host element for the xterm canvas — attach to the terminal container div. */
  containerRef: RefObject<HTMLDivElement | null>;
  /** The live xterm instance (null before mount / after unmount) — read by sendPrompt + restart. */
  termRef: MutableRefObject<Terminal | null>;
}

export function usePlannerTerminal(opts: PlannerTerminalOpts): PlannerTerminalHandle {
  const {
    paneId, visible, effectiveProjectId, linkedRepos, treatAsExisting,
    activeProjectName, activeProjectNumber, planningPitch, stageIdsFor, refreshSetupSig,
    processChunk, commands, schedules, setPlanningDir,
  } = opts;

  // The whole xterm + PTY lifecycle (terminal literal, subscribe-before-create ordering,
  // ResizeObserver, refit, cleanup) lives in the shared hook; this wrapper owns only the PLANNER
  // launch path (workspace setup → role gate + MCP → intro → sandbox → pty_create), the tag-parse
  // onData hook, and the repo-resync effect below. pty_kill is called on unmount so navigating away
  // ends the session cleanly. The once-effect launch is a behavior-preserving move — NO logic change.
  const { containerRef, termRef } = useScreenSession({
    paneId,
    termTheme: TERM_THEME,
    visible,
    exitBanner: "\r\n\x1b[33m[session ended — navigate away and back to restart]\x1b[0m\r\n",

    // Parse structured tags out of the stripped output stream (#1474, usePlannerTagStream).
    onData: (payload) => processChunk(payload),

    // Capture state at mount time (synchronously, before the RAF) for workspace sync.
    snapshot: () => ({
      repoSnapshot:        linkedRepos, // string[] of full_names
      treatAsExistingSnap: treatAsExisting,
      projNameSnap:        activeProjectName,
      projNumberSnap:      activeProjectNumber,
      pitchSnap:           planningPitch,
      projIdSnap:          effectiveProjectId,
      ghLoginSnap:         useAppStore.getState().githubUser?.login ?? "",
      ghNameSnap:          useAppStore.getState().githubUser?.name  ?? "",
      automationsSnap: [
        ...commands.map(c => ({ id: c.id, name: c.name, command: c.cmd, schedule: null })),
        ...schedules.map(sc => ({ id: sc.id, name: sc.name, command: sc.detail, schedule: sc.when })),
      ],
    }),

    launch: async (term, snap) => {
      const {
        repoSnapshot, treatAsExistingSnap, projNameSnap, projNumberSnap,
        pitchSnap, projIdSnap, ghLoginSnap, ghNameSnap, automationsSnap,
      } = snap;

      // Create the isolated planning workspace directory with settings.json + CLAUDE.md.
      const paths = await safeInvoke<{ planning_dir: string } | null>(
        "setup_workspaces",
        {
          repoFullNames: repoSnapshot,
          automations:   automationsSnap,
          isExisting:    treatAsExistingSnap,
          projectName:   projNameSnap,
          projectNumber: projNumberSnap,
          pitch:         pitchSnap,
          projectKey:    projIdSnap,
          githubLogin:   ghLoginSnap,
          githubName:    ghNameSnap,
          enabledStages: stageIdsFor(projIdSnap), // scope the planner CLAUDE.md to the blueprint (#A)
        },
        null,
        (e: unknown) => console.error("workspace setup failed:", e),
      );
      refreshSetupSig(); // baseline updated (#756)
      if (paths) setPlanningDir(paths.planning_dir); // for the relay planner-pane mirror (#801)

      // Launch claude inside the isolated planning directory.
      // Inject the stored GitHub token so `gh` CLI and direct API calls work
      // without requiring the user to separately authenticate the gh CLI.
      const token = useAppStore.getState().githubToken;
      const ghEnv: Record<string, string> = token ? { GH_TOKEN: token, GITHUB_TOKEN: token } : {};
      // Role gate (#219): the planner is plan-only — write git/gh write denies plus a
      // write-tool deny (#238) into its session settings before claude launches, so it
      // can read for context but neither edit files nor mutate the repo/GitHub
      // (publishing is an explicit, separately-gated step).
      const plannerCap = roleCapability("planner");
      const plannerWrite = roleWriteRules(plannerCap);
      // Expose EVERY installed MCP server to the planner (#1054), project scope ignored: the planner
      // is the assignment hub, so it sees all downloaded servers — it can call them while planning
      // (e.g. research sources for a skill) and assign them to the workers that need them.
      const plannerMcp = toSessionPayloads(resolveAllInstalledMcp(useAppStore.getState().mcpServers), []).mcp;
      // The role gate covers the planner's scoped plan-file writes + git/gh read-only.
      // WebFetch (docs / version / pricing lookups) and Read are added explicitly here so
      // this single role-launch path fully sources the planner's tools — replacing the
      // hardcoded settings.json literal that setup_workspaces used to write (#799).
      await safeInvoke("ensure_session_settings", {
        cwd:             paths?.planning_dir ?? "",
        allowedCommands: [],
        deniedCommands:  roleDeniedCommands(plannerCap),
        mcpServers:      plannerMcp,
        // Turn accounting (#3455): the planner's bespoke launch must ALSO register the observability
        // floor. bsc-tokens is the only per-session token source, so without it the planner's (often
        // large) planning cost is invisible to `bsc metrics`. Shared with the generic path.
        hooks:           TURN_ACCOUNTING_HOOKS,
        // Auto-approve every MCP server the planner sees (Research/Compliance + any downloaded one)
        // so it can call them while planning — e.g. the Research MCP when grounding a skill — without
        // a per-tool permission prompt. `enabledMcpjsonServers` only trusts the server to LOAD.
        allowToolRules:  [...plannerWrite.allow, "Read", "WebFetch", ...mcpAllowRules(plannerMcp)],
        denyToolRules:   plannerWrite.deny,
        replacePermissions: true,
      }, undefined, (e: unknown) => console.error("planner session settings failed:", e));
      // Planner introduction (#1240): a user-facing kickoff that has the planner OPEN the
      // conversation (introduce itself, sketch the stage journey, summarize capabilities, ask one
      // orienting question) instead of launching into a quiet terminal. Baked into the claude launch
      // arg as a FRESH-ONLY startup prompt — the backend (which knows the conversation history)
      // delivers it only on a genuinely new session and drops it on `--continue` resume, so a
      // returning user isn't re-greeted. For a new project the user's pitch rides along so the
      // planner acknowledges it rather than asking what they're building (replaces the old
      // idle-detection pitch-typing). On failure it's undefined → the launch falls back to initCmd.
      const introMode = plannerIntroMode({ isExisting: treatAsExistingSnap });
      const introText = await safeInvoke<string>("planner_intro_prompt", { mode: introMode }, "",
        (e: unknown) => console.error("planner intro prompt failed:", e));
      // Run the planner on the selected harness: Claude Code, or bsc-agent (any LLM) when chosen or
      // forced by a local/ollama provider Claude can't drive (#1078). bsc-agent gets the same plan-only
      // role gate, MCP, and provider/model/base-url via BSC_AGENT_* env; context + the intro prompt +
      // plan state come through identically.
      const launch = plannerLaunchConfig(useAppStore.getState(), ghEnv);
      // bsc-agent is a one-shot loop, so it never receives stage 1's directive via runtime injection
      // (Claude does). Bake the first active stage's directive into the intro so a weak local model
      // begins discovery instead of greeting and then waiting to be advanced (#qwen).
      let firstStageDirective: string | undefined;
      if (launch.providerId === "bsc-agent") {
        const firstStage = stageIdsFor(projIdSnap)[0];
        if (firstStage) {
          firstStageDirective = await safeInvoke<string>(
            "planner_stage_directive", { id: firstStage }, "",
            (e: unknown) => console.error("planner stage directive failed:", e),
          ) || undefined;
        }
      }
      const startupPrompt = composePlannerIntro(introText, introMode, pitchSnap ?? "", firstStageDirective) || undefined;
      // #1988: opt-in (off by default) — relocate the hub into the sealed WSL2 distro + spawn INSIDE
      // it when the sandbox toggle is on AND the planner runs on bsc-agent (shared with the restart
      // path so they can't drift; host fallback on failure). Toggling restarts the planner to convert.
      const sandbox = await resolvePlannerSandbox(launch.providerId, paths?.planning_dir ?? "", projIdSnap);
      await safeInvoke("pty_create", {
        paneId:  paneId,
        cols:    term.cols,
        rows:    term.rows,
        cwd:     sandbox.cwd,
        initCmd: launch.initCmd,
        startupPrompt,
        startupPromptFreshOnly: launch.startupPromptFreshOnly,
        continueSession: launch.continueSession,
        env:     launch.env,
        providerId: launch.providerId,
        wslDistro: sandbox.wslDistro,
      }, undefined, console.error);
    },
  });

  // Re-sync CLAUDE.md whenever a repo resolves after the initial mount.
  useEffect(() => {
    if (linkedRepos.length === 0) return;
    const { commands: cmds, schedules: scheds } = useAppStore.getState();
    invoke("setup_workspaces", {
      repoFullNames: linkedRepos,
      automations: [
        ...cmds.map(c => ({ id: c.id, name: c.name, command: c.cmd, schedule: null })),
        ...scheds.map(sc => ({ id: sc.id, name: sc.name, command: sc.detail, schedule: sc.when })),
      ],
      isExisting:    treatAsExisting,
      projectName:   activeProjectName,
      projectNumber: activeProjectNumber,
      pitch:         planningPitch,
      projectKey:    effectiveProjectId,
      githubLogin:   useAppStore.getState().githubUser?.login ?? "",
      githubName:    useAppStore.getState().githubUser?.name  ?? "",
      enabledStages: stageIdsFor(effectiveProjectId), // scope the planner CLAUDE.md (#A)
    }).then(() => refreshSetupSig()).catch(console.error); // baseline updated (#756)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [linkedRepos]);

  return { containerRef, termRef };
}

runtime.features/planner/session/usePlannerTunne:
// usePlannerTunnelSync (#1775, extracted from Planning.tsx) — the mobile-relay (#801/#934/#987)
// projection of the live planning session. Owns the canonical-plan derivation, the message poll,
// and every tunnel emit/listen effect, all of which no-op unless the relay is live:
//   • canonicalPlan — the project's plan files + stable id, routed to their canonical relpaths.
//   • (1) file-sync — push the plan files so a paired mobile planner reconciles over the relay (E2E).
//   • (2) PTY mirror — expose the planner pane so a paired phone can view/drive the terminal.
//   • (1b) plan_state — debounced snapshot; plan_status — cheap, un-debounced header update.
//   • plan_event — transient confirmed-section / stage-advanced / message-appended deltas (the refs
//     diff prev vs current at the transition sites).
//   • inbound DRIVE — confirm a section / advance a stage / chat into the PTY from the phone (gated
//     Rust-side behind the input grant; a view-only phone can't steer).
// Behavior-preserving move out of the component; NO logic change.
import { useEffect, useMemo, useRef } from "react";
import { invoke } from "@tauri-apps/api/core";
import { listen } from "@tauri-apps/api/event";
import { useAppStore } from "@/store";
import { hubToCanonical } from "@/features/planner/lib/plannerSync";
import {
  tunnelSetPlanState, tunnelEmitPlanState, tunnelEmitPlanStatus, tunnelEmitPlanEvent,
  publishTunnelDomain, recordTunnelAlerts, gateReadyAlert, plannerWaitingAlert,
} from "@/features/tunnel";
import { usePlannerMessages } from "./usePlannerMessages";
import { SKIPPED_KEY, FEATURES_KEY } from "../stages/planTopics";
import { FLEET_KEY } from "../fleet/planFleet";
import { DEPENDENCIES_KEY } from "../issues/dependencies";
import { buildPlanBoardPayload } from "./planBoardProjection";
import type { Stage } from "../stages/focusedPlan";

export interface PlannerTunnelSyncOpts {
  effectiveProjectId: string;
  /** The per-project section bucket — the canonical plan is derived from it. */
  savedSections: Record<string, string>;
  confirmedSet: Set<string>;
  /** The active stage key (from usePlanGates) — emitted in plan_state/status/events. */
  currentStage: string;
  planStatusLabel: string;
  /** The planner hub dir (from usePlannerTerminal) — gates the PTY mirror. */
  planningDir: string;
  paneId: string;
  projectTitle: string;
  confirmPlanStage: (projectId: string, key: string) => void;
  /** The focused-pane stage board (from usePlanGates, #2498) — published as the `plan`
   *  store_state domain the mobile Planner page renders. */
  stages: Stage[];
  /** The active stage's gate passed (awaiting the user-only confirm). */
  focusGateReady: boolean;
  planComplete: boolean;
}

export function usePlannerTunnelSync(opts: PlannerTunnelSyncOpts) {
  const {
    effectiveProjectId, savedSections, confirmedSet, currentStage, planStatusLabel,
    planningDir, paneId, projectTitle, confirmPlanStage,
    stages, focusGateReady, planComplete,
  } = opts;
  const tunnelRunning = useAppStore((s) => s.tunnelRunning);

  // The active project's canonical plan (files + the stable proj-<hex> id). Route the JSON
  // manifests to their canonical relpaths; everything else is a `.md` section. commands.json/
  // features.json are outside the canonical-sync contract (isPlanFile), so they're excluded.
  // Shared by the file-sync path (1) and the live-frame emit (1b).
  const canonicalPlan = useMemo(() => {
    if (Object.keys(savedSections).length === 0) return null;
    const md: Record<string, string> = {};
    let phasesJson, issuesJson, fleetJson, reposJson, skippedContent: string | undefined;
    for (const [k, v] of Object.entries(savedSections)) {
      if (k === "phases") phasesJson = v;
      else if (k === "issues") issuesJson = v;
      else if (k === FLEET_KEY) fleetJson = v;
      // Legacy `repos` SECTION-CONTENT key (not the stage key, #1914) — the mobile canonical-sync
      // contract still routes a `reposJson` relpath via hubToCanonical, so keep reading it if present.
      else if (k === "repos") reposJson = v;
      else if (k === SKIPPED_KEY) skippedContent = v;
      else if (k === FEATURES_KEY || k === DEPENDENCIES_KEY) continue;
      else md[k] = v;
    }
    return hubToCanonical({
      projectTitle: effectiveProjectId,
      sections: md,
      confirmedSections: [...confirmedSet],
      phasesJson, issuesJson, fleetJson, reposJson, skippedContent,
    });
  }, [savedSections, confirmedSet, effectiveProjectId]);

  // The planner is a PTY running `claude`, so the structured conversation lives in Claude's
  // transcript — poll it (newest 50 turns) while paired so the phone renders the real chat,
  // not the raw terminal. pipelineRuns stays empty: the planner runs no pipelines (#220).
  const plannerMessages = usePlannerMessages(tunnelRunning, paneId);

  // (1) Plan-sync — push the canonical plan files so a paired mobile planner reconciles over
  // the relay (E2E) instead of the API. Unchanged async file-sync path.
  useEffect(() => {
    if (!tunnelRunning || !canonicalPlan) return;
    tunnelSetPlanState(canonicalPlan.meta.projectId, canonicalPlan.files).catch(() => {});
  }, [tunnelRunning, canonicalPlan]);

  // (2) PTY mirror — register the planner pane in the session roster (keyed source, #2497)
  // so a paired phone can view (and, if granted, drive) the live planner terminal.
  // Unregistered when the planner unmounts or the relay stops.
  useEffect(() => {
    const register = useAppStore.getState().registerTunnelPanes;
    if (!tunnelRunning || !planningDir) { register("planner", []); return; }
    register("planner", [{
      id: paneId, cwd: planningDir, name: `Planner — ${projectTitle}`,
      status: "running" as const, kind: "planner" as const,
    }]);
    return () => useAppStore.getState().registerTunnelPanes("planner", []);
  }, [tunnelRunning, planningDir, paneId, projectTitle]);

  // (1b) plan_state — debounced snapshot (replayed to newly-paired clients Rust-side).
  useEffect(() => {
    if (!tunnelRunning || !canonicalPlan) return;
    const id = setTimeout(() => {
      tunnelEmitPlanState(canonicalPlan.meta.projectId, currentStage, [...confirmedSet], canonicalPlan.files, plannerMessages, []).catch(() => {});
    }, 500);
    return () => clearTimeout(id);
  }, [tunnelRunning, canonicalPlan, currentStage, confirmedSet, plannerMessages]);

  // plan_status — cheap header update, un-debounced on stage/status change.
  useEffect(() => {
    if (!tunnelRunning || !canonicalPlan) return;
    tunnelEmitPlanStatus(canonicalPlan.meta.projectId, currentStage, planStatusLabel).catch(() => {});
  }, [tunnelRunning, canonicalPlan, currentStage, planStatusLabel]);

  // plan_event — transient deltas at the transition sites (refs diff prev vs current).
  const prevConfirmedRef = useRef<Set<string>>(new Set());
  useEffect(() => {
    if (tunnelRunning && canonicalPlan) {
      for (const k of confirmedSet) {
        if (!prevConfirmedRef.current.has(k)) {
          tunnelEmitPlanEvent(canonicalPlan.meta.projectId, { kind: "section_confirmed", at: Date.now(), section: k }).catch(() => {});
        }
      }
    }
    prevConfirmedRef.current = new Set(confirmedSet);
  }, [confirmedSet, tunnelRunning, canonicalPlan]);

  const prevStageRef = useRef("");
  useEffect(() => {
    if (tunnelRunning && canonicalPlan && currentStage && currentStage !== prevStageRef.current) {
      tunnelEmitPlanEvent(canonicalPlan.meta.projectId, { kind: "stage_advanced", at: Date.now(), stage: currentStage }).catch(() => {});
    }
    prevStageRef.current = currentStage;
  }, [currentStage, tunnelRunning, canonicalPlan]);

  const prevMsgCountRef = useRef(0);
  useEffect(() => {
    if (tunnelRunning && canonicalPlan && plannerMessages.length > prevMsgCountRef.current) {
      const last = plannerMessages[plannerMessages.length - 1];
      tunnelEmitPlanEvent(canonicalPlan.meta.projectId, { kind: "message_appended", at: last.at || Date.now(), message: last }).catch(() => {});
    }
    prevMsgCountRef.current = plannerMessages.length;
  }, [plannerMessages, tunnelRunning, canonicalPlan]);

  // (1c) The `plan` store_state domain (#2498): the stage/gate board the mobile Planner page
  // renders — the same `stagesFrom` output the desktop stepper shows, plus fleet streams and
  // the deploy/market gate summaries. COMPLEMENTS plan_state (files + transcript, above); the
  // shared domain publisher debounces, dedups unchanged payloads, and stamps the rev.
  const planFleet = useAppStore((s) => s.planFleet);
  const planSkippedStages = useAppStore((s) => s.planSkippedStages);
  const planDeployConfig = useAppStore((s) => s.planDeployConfig);
  const planMarketConfig = useAppStore((s) => s.planMarketConfig);
  useEffect(() => {
    if (!tunnelRunning || !effectiveProjectId) return;
    publishTunnelDomain("plan", buildPlanBoardPayload({
      projectId: effectiveProjectId,
      title: projectTitle,
      currentStage,
      statusLabel: planStatusLabel,
      gateReady: focusGateReady,
      planComplete,
      stages,
      confirmed: confirmedSet,
      skipped: planSkippedStages[effectiveProjectId] ?? [],
      fleet: planFleet[effectiveProjectId],
      deploy: planDeployConfig[effectiveProjectId],
      market: planMarketConfig[effectiveProjectId],
    }));
  }, [
    tunnelRunning, effectiveProjectId, projectTitle, currentStage, planStatusLabel,
    focusGateReady, planComplete, stages, confirmedSet,
    planSkippedStages, planFleet, planDeployConfig, planMarketConfig,
  ]);

  // gate-ready alert (#2498): the active stage's gate JUST passed — only the USER can confirm,
  // so this is exactly the "come back and advance the plan" moment. Fires only on an OBSERVED
  // not-ready→ready transition per stage: the first run just primes the ref, so remounting the
  // planner over an already-passed gate never re-alerts (each alert mints a fresh id).
  const prevGateRef = useRef<{ stage: string; ready: boolean } | null>(null);
  useEffect(() => {
    const prev = prevGateRef.current;
    if (prev && tunnelRunning && focusGateReady && currentStage &&
        !(prev.ready && prev.stage === currentStage)) {
      recordTunnelAlerts([gateReadyAlert(effectiveProjectId, currentStage, Date.now())]);
    }
    prevGateRef.current = { stage: currentStage, ready: focusGateReady };
  }, [tunnelRunning, focusGateReady, currentStage, effectiveProjectId]);

  // planner-waiting alert (#2498): the planner's newest transcript turn is an ASSISTANT turn —
  // it finished and is waiting on the user. The poll re-delivers the same transcript every few
  // seconds, so the turn key ref (its `at`, falling back to the text) guards re-derivation and
  // the alert hub's id dedup backstops it — one alert per turn.
  const lastPlannerTurnRef = useRef("");
  useEffect(() => {
    if (!tunnelRunning || plannerMessages.length === 0) return;
    const last = plannerMessages[plannerMessages.length - 1];
    if (last.role !== "assistant") return;
    const turnKey = last.at ? String(last.at) : last.text;
    if (turnKey === lastPlannerTurnRef.current) return;
    lastPlannerTurnRef.current = turnKey;
    recordTunnelAlerts([plannerWaitingAlert(effectiveProjectId, paneId, last.text, last.at || Date.now())]);
  }, [tunnelRunning, plannerMessages, effectiveProjectId, paneId]);

  // Inbound DRIVE from the phone (#934): confirm a section, advance a stage, or chat into the
  // planner PTY. Gated Rust-side behind the input grant (a view-only phone can't steer).
  useEffect(() => {
    const subs = [
      listen<{ section: string }>("tunnel://plan-confirm", (e) => confirmPlanStage(effectiveProjectId, e.payload.section)),
      listen<{ stageKey: string }>("tunnel://plan-advance", (e) => confirmPlanStage(effectiveProjectId, e.payload.stageKey)),
      listen<{ text: string }>("tunnel://plan-chat", (e) => { void invoke("pty_write", { paneId, data: e.payload.text + "\r" }); }),
    ];
    return () => { for (const s of subs) void s.then((off) => off()); };
  }, [effectiveProjectId, paneId, confirmPlanStage]);
}

runtime.features/planner/session/usePlanningModa:
// usePlanningModals (#1642) — the planner's modal open/close state, extracted verbatim from
// Planning.tsx. Owns the clear-plan confirmation flag and the blueprint-update modal, including the
// auto-open state machine (#827/#1296): reset the auto-shown latch on a project switch, then open the
// modal exactly once when a true blueprint/template VERSION mismatch is detected over an existing plan
// (`shouldAutoOpenBlueprintModal` compares only the `v{version}` signature prefix, NOT the broad
// `contextStale` flag — benign setup tweaks keep driving the quiet "context updated" badge instead).
//
// STRICTLY behaviour-preserving: the two effects and their dependency arrays are moved unchanged.

import { useState, useEffect, type Dispatch, type SetStateAction } from "react";
import { shouldAutoOpenBlueprintModal } from "../stages/blueprints";

export interface PlanningModalsDeps {
  effectiveProjectId: string;
  /** The live context signature (from compute_context_signature); null until resolved. */
  currentSig: string | null;
  /** The baseline signature setup_workspaces last wrote; null until read. */
  lastSetupSig: string | null;
  /** Whether the project already has plan sections (gates the destructive auto-open). */
  hasExistingPlan: boolean;
}

export interface PlanningModals {
  /** Clear-plan confirmation dialog (#664). */
  showClearConfirm: boolean;
  setShowClearConfirm: Dispatch<SetStateAction<boolean>>;
  /** Blueprint-update modal (#827). */
  showBlueprintModal: boolean;
  setShowBlueprintModal: Dispatch<SetStateAction<boolean>>;
}

export function usePlanningModals({
  effectiveProjectId, currentSig, lastSetupSig, hasExistingPlan,
}: PlanningModalsDeps): PlanningModals {
  const [showClearConfirm, setShowClearConfirm] = useState(false); // clear-plan confirmation modal (#…)

  // Blueprint-update modal (#827): when a project is opened whose blueprint/planner-template
  // VERSION differs from the one it was seeded with AND it already has a plan, surface a modal so
  // the user explicitly chooses go-back / restart / keep — rather than the old silent refresh,
  // which restarted the planner into a destructive reconciliation that deleted plan files.
  //
  // #1296: gate the auto-open on a true template-version mismatch (`shouldAutoOpenBlueprintModal`,
  // which compares only the `v{version}` prefix of the two signatures), NOT the broad `contextStale`
  // flag. `contextStale` also flips on benign setup tweaks (link a repo, enable/
  // disable a stage) — those must keep driving only the quiet "context updated · refresh" badge
  // below, never this destructive restart dialog.
  const [showBlueprintModal, setShowBlueprintModal] = useState(false);
  const [bpModalAutoShown, setBpModalAutoShown] = useState(false);
  useEffect(() => { setBpModalAutoShown(false); setShowBlueprintModal(false); }, [effectiveProjectId]);
  useEffect(() => {
    if (shouldAutoOpenBlueprintModal({ currentSig, baselineSig: lastSetupSig, hasExistingPlan, alreadyShown: bpModalAutoShown })) {
      setShowBlueprintModal(true);
      setBpModalAutoShown(true);
    }
  }, [currentSig, lastSetupSig, hasExistingPlan, bpModalAutoShown]);

  return { showClearConfirm, setShowClearConfirm, showBlueprintModal, setShowBlueprintModal };
}

runtime.features/planner/session/usePlanningSess:
// usePlanningSession (#1642) — the planner's session-lifecycle state machine, extracted verbatim
// from Planning.tsx. Owns the `restarting` flag and the four lifecycle operations:
//   • regenerateWorkspace — rewrite CLAUDE.md + the context baseline for the CURRENT blueprint
//     version WITHOUT touching plan section files (shared by restart + "keep files").
//   • handleRestart       — kill the PTY, regenerate, and re-spawn `claude`. Resume-capable by
//     default (#2396); the destructive ops pass `fresh: true` for a brand-new session (#1240).
//   • keepPlanFiles       — adopt the new blueprint/template version on disk, clearing the staleness
//     WITHOUT wiping plan files or restarting into a destructive reconciliation (#827).
//   • doClearPlan         — delete on-disk plan files FIRST (awaited), wipe the store, unlink repos,
//     then restart with a blank slate (#664).
//
// STRICTLY behaviour-preserving: the function bodies, the order of their awaited steps, and every
// store/invoke call are moved unchanged — only the closed-over values become hook parameters.

import { useState, type MutableRefObject } from "react";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import type { Terminal } from "@xterm/xterm";
import type { Dispatch, SetStateAction } from "react";
import { useAppStore } from "@/store";
import { plannerIntroMode, composePlannerIntro } from "./plannerIntro";
import { plannerLaunchConfig } from "./plannerLaunch";
import { resolvePlannerSandbox } from "./plannerSandbox";

export interface PlanningSessionDeps {
  termRef: MutableRefObject<Terminal | null>;
  /** The planner tag-scan buffer — cleared on restart so a stale tag can't replay. */
  bufRef: MutableRefObject<string>;
  paneId: string;
  linkedRepos: string[];
  /** Whether the planner runs in the "operate" (existing-system) intro mode (#1286). */
  treatAsExisting: boolean;
  activeProjectName: string;
  activeProjectNumber: number;
  planningPitch: string;
  effectiveProjectId: string;
  /** The blueprint's enabled stage ids — scopes the planner CLAUDE.md (#A). */
  stageIdsFor: (key: string) => string[];
  /** Re-read the baseline signature the backend last wrote (#756). */
  refreshSetupSig: () => void;
  setShowBlueprintModal: Dispatch<SetStateAction<boolean>>;
  setShowClearConfirm: Dispatch<SetStateAction<boolean>>;
}

export interface PlanningSession {
  restarting: boolean;
  handleRestart: (opts?: { fresh?: boolean }) => Promise<void>;
  keepPlanFiles: () => Promise<void>;
  doClearPlan: () => Promise<void>;
}

export function usePlanningSession(deps: PlanningSessionDeps): PlanningSession {
  const {
    termRef, bufRef, paneId, linkedRepos, treatAsExisting,
    activeProjectName, activeProjectNumber, planningPitch, effectiveProjectId,
    stageIdsFor, refreshSetupSig,
    setShowBlueprintModal, setShowClearConfirm,
  } = deps;

  const [restarting, setRestarting] = useState(false);

  // Regenerate the on-disk workspace (CLAUDE.md + the context baseline) for the CURRENT blueprint
  // version, WITHOUT touching the plan section files. Shared by the restart flow and the "keep
  // files" choice of the blueprint-update modal (#827). refreshSetupSig() rebaselines the
  // signature so the staleness clears.
  async function regenerateWorkspace(): Promise<{ planning_dir: string } | null> {
    const store = useAppStore.getState();
    const currentAutomations = [
      ...store.commands.map(c => ({ id: c.id, name: c.name, command: c.cmd, schedule: null })),
      ...store.schedules.map(sc => ({ id: sc.id, name: sc.name, command: sc.detail, schedule: sc.when })),
    ];
    const paths = await safeInvoke<{ planning_dir: string } | null>(
      "setup_workspaces",
      {
        repoFullNames: linkedRepos,
        automations: currentAutomations,
        isExisting: treatAsExisting,
        projectName: activeProjectName,
        projectNumber: activeProjectNumber,
        pitch: planningPitch,
        projectKey: effectiveProjectId,
        githubLogin: store.githubUser?.login ?? "",
        githubName:  store.githubUser?.name  ?? "",
        enabledStages: stageIdsFor(effectiveProjectId), // scope the planner CLAUDE.md (#A)
      },
      null,
      (e: unknown) => console.error("workspace setup failed:", e),
    );
    refreshSetupSig(); // baseline updated (#756)
    return paths;
  }

  // Relaunch the planner session (#2396). RESUME-CAPABLE by default — the launch mirrors the mount
  // path exactly (`claude --continue || claude` + the fresh-only intro guard + a resume request), so
  // a non-destructive relaunch (sandbox-toggle flip, reopening a project) continues the prior
  // conversation instead of starting over. The destructive clear-plan op passes `fresh: true` to
  // launch a genuinely NEW session — plain `claude`, re-greeted with the intro even
  // though history exists (#1240), since the plan that conversation referred to was just wiped.
  async function handleRestart(opts?: { fresh?: boolean }) {
    const fresh = opts?.fresh === true;
    const term = termRef.current;
    if (!term || restarting) return;
    setRestarting(true);
    bufRef.current = "";
    term.clear();
    await safeInvoke("pty_kill", { paneId: paneId }, undefined, console.error);
    const paths = await regenerateWorkspace();
    const token = useAppStore.getState().githubToken;
    const ghEnv: Record<string, string> = token ? { GH_TOKEN: token, GITHUB_TOKEN: token } : {};
    // The intro rides along on every restart: a `fresh` restart always fires it (#1240 — the user
    // wiped the plan, so re-greet even though history exists); the default resume restart keeps the
    // fresh-only guard, so a returning user with history resumes quietly instead of being re-greeted.
    const introMode = plannerIntroMode({ isExisting: treatAsExisting });
    const introText = await safeInvoke<string>("planner_intro_prompt", { mode: introMode }, "",
      (e: unknown) => console.error("planner intro prompt failed:", e));
    // Relaunch on the selected harness (Claude Code or bsc-agent for any LLM, incl. a forced
    // local/ollama provider), carrying the plan-only role gate + provider/model/MCP via BSC_AGENT_*
    // env so a restarted local-model planner keeps the same context, prompt, state, and permissions.
    const launch = plannerLaunchConfig(useAppStore.getState(), ghEnv);
    // bsc-agent (one-shot) never gets stage 1's directive via runtime injection — bake it into the
    // intro so a weak local model begins the stage instead of waiting to be advanced (#qwen).
    let firstStageDirective: string | undefined;
    if (launch.providerId === "bsc-agent") {
      const firstStage = stageIdsFor(effectiveProjectId)[0];
      if (firstStage) {
        firstStageDirective = await safeInvoke<string>(
          "planner_stage_directive", { id: firstStage }, "",
          (e: unknown) => console.error("planner stage directive failed:", e),
        ) || undefined;
      }
    }
    const startupPrompt = composePlannerIntro(introText, introMode, planningPitch ?? "", firstStageDirective) || undefined;
    // #1988: honor the sandbox toggle on a restart too — shared with the mount path (plannerSandbox).
    // This is the path a sandbox-toggle flip relaunches through, so it MUST convert into/out of the cage
    // (a restart used to always spawn on the host, silently dropping a planner out of the sandbox).
    const sandbox = await resolvePlannerSandbox(launch.providerId, paths?.planning_dir ?? "", effectiveProjectId);
    await safeInvoke("pty_create", {
      paneId: paneId,
      cols: term.cols,
      rows: term.rows,
      cwd: sandbox.cwd,
      // Default (resume): the harness's own launch — for Claude the `--continue || claude` chain —
      // with the fresh-only intro guard + resume request, exactly like the mount path (#2396).
      // Destructive (`fresh`): plain `claude` + an always-firing intro, so the session starts over.
      initCmd: fresh && launch.providerId !== "bsc-agent" ? "claude" : launch.initCmd,
      startupPrompt,
      startupPromptFreshOnly: fresh ? false : launch.startupPromptFreshOnly,
      continueSession: fresh ? false : launch.continueSession,
      env: launch.env,
      providerId: launch.providerId,
      wslDistro: sandbox.wslDistro,
    }, undefined, console.error);
    setRestarting(false);
  }

  // "Keep the previous plan files" (#827): adopt the new blueprint/template version on disk and
  // clear the staleness, WITHOUT wiping plan files and WITHOUT restarting the planner into a
  // destructive reconciliation (the prior silent refresh let a fresh planner delete plan files).
  async function keepPlanFiles() {
    setShowBlueprintModal(false);
    await regenerateWorkspace();
  }

  // Clear/reset the plan (#664/#B) — delete the on-disk plan files FIRST (awaited, so the 2s
  // file poll can't re-read + re-populate the store), wipe the store, unlink the repos, then
  // restart the planner with a blank slate. (Restored: the refactor dropped this flow.)
  // Confirmation is the Dialog below (#…), not a native window.confirm.
  async function doClearPlan() {
    setShowClearConfirm(false);
    const store = useAppStore.getState();
    await safeInvoke("clear_project_plan_files", { projectKey: effectiveProjectId }, undefined, console.error);
    store.clearPlan(effectiveProjectId);
    store.setActiveProjectRepos([]);
    store.setPlanningContext(planningPitch, "");
    void handleRestart({ fresh: true }); // destructive — the plan is gone, start a NEW session (#2396)
  }

  return { restarting, handleRestart, keepPlanFiles, doClearPlan };
}

