// usePlanningTitle (#1775, extracted from Planning.tsx) — the editable project title for both
// lifecycles, KEEPING the frozen session key (#2409: renames are display-only — the folder keeps
// its birth-slug; a later reopen under the new name resolves via the reopen-mismatch modal):
//   • PUBLISHED rename (#1226) — commit updates the GitHub Project board title + local name.
//   • UNPUBLISHED draft (#1222) — commit persists to the draft record keyed by the frozen key.
import { useState, useCallback } from "react";
import { useAppStore } from "@/store";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import { githubGraphql } from "@/shared/lib/github/github";
import { planRename, applyRename } from "./renameProject";
import { planDraftCommit } from "./draftTitle";

type Store = ReturnType<typeof useAppStore.getState>;

export function usePlanningTitle(opts: {
  activeProjectId: Store["activeProjectId"];
  activeProjectName: Store["activeProjectName"];
  activeProjectNumber: Store["activeProjectNumber"];
  activeProjectRepos: Store["activeProjectRepos"];
  planningTitle: Store["planningTitle"];
  setPlanningTitle: Store["setPlanningTitle"];
  effectiveProjectId: string;
}) {
  const {
    activeProjectId, activeProjectName, activeProjectNumber, activeProjectRepos,
    planningTitle, setPlanningTitle, effectiveProjectId,
  } = opts;

  // ── Rename a PUBLISHED project (#1226) ──────────────────────────────────────────
  const [titleEdit, setTitleEdit] = useState<string | null>(null);
  const [renameErr, setRenameErr] = useState<string | null>(null);
  const commitRename = useCallback(async () => {
    // The duplicate guard compares against OTHER projects' frozen keys — the draft-map keys
    // (name-derived slugs, #2409). Renames are display-only (the folder keeps its birth-slug), so
    // a rename that slugs onto another key would only surface later as a reopen collision — this
    // guard catches it up front where the store knows the other keys.
    const st0 = useAppStore.getState();
    const otherKeys = new Set(
      Object.keys(st0.localDraftProjects).filter((k) => k !== effectiveProjectId),
    );
    const plan = planRename(titleEdit ?? "", activeProjectName, activeProjectId, otherKeys);
    setTitleEdit(null);
    if (plan.kind === "noop") { setRenameErr(null); return; }
    if (plan.kind === "error") { setRenameErr(plan.message); return; }
    const st = useAppStore.getState();
    setRenameErr(
      await applyRename(activeProjectId!, plan.title, {
        graphql: githubGraphql,
        setMeta: st.setActiveProjectMeta,
        repo: st.activeProjectRepo,
        number: activeProjectNumber,
        repos: activeProjectRepos,
      }),
    );
    // Keep the on-disk hub title (`projects/<key>/.title`) in step with the rename so the durable
    // name — read by list_local_projects and the session skill-group naming — reflects the new title.
    fireInvoke("set_project_title", { projectKey: effectiveProjectId, title: plan.title });
  }, [titleEdit, activeProjectName, activeProjectId, activeProjectNumber, activeProjectRepos, effectiveProjectId]);

  // ── Persist a DRAFT title edit (#1222) ──────────────────────────────────────────
  const [draftTitleErr, setDraftTitleErr] = useState<string | null>(null);
  const commitDraftTitle = useCallback(() => {
    const st = useAppStore.getState();
    const draft = st.localDraftProjects[effectiveProjectId];
    if (!draft) { setDraftTitleErr(null); return; } // not an unpublished draft — nothing to persist
    const otherKeys = new Set<string>();
    for (const k of Object.keys(st.localDraftProjects)) if (k !== effectiveProjectId) otherKeys.add(k);
    const plan = planDraftCommit(planningTitle, draft.title, otherKeys);
    if (plan.kind === "revert") { setPlanningTitle(draft.title); setDraftTitleErr(null); return; }
    if (plan.kind === "noop") { setDraftTitleErr(null); return; }
    if (plan.kind === "error") { setDraftTitleErr(plan.message); return; } // keep the typed value to fix
    st.updateDraftProject(effectiveProjectId, { title: plan.title });
    // Mirror the draft rename into the durable hub title (`.title`) so the on-disk name doesn't fall
    // back to a key-derived placeholder once goal.md/the store drift out of view.
    fireInvoke("set_project_title", { projectKey: effectiveProjectId, title: plan.title });
    setDraftTitleErr(null);
  }, [planningTitle, effectiveProjectId, setPlanningTitle]);

  return { titleEdit, setTitleEdit, renameErr, setRenameErr, commitRename, draftTitleErr, setDraftTitleErr, commitDraftTitle };
}

// usePlanPublish (#1490) — the publish → GitHub + triage-launch + GitHub→plan.db recovery cluster,
// extracted verbatim from Planning.tsx. Owns the triage/publish/recovery state (no render loop —
// just callbacks + a recovery probe effect); takes the plan data it reads as a params object so the
// bodies move unchanged. Returns the callbacks + the state the JSX consumes.

import { useState, useEffect } from "react";
import { invoke } from "@tauri-apps/api/core";
import { safeInvoke, fireInvoke } from "@/shared/lib/core/safeInvoke";
import { bscJson, bscWrite } from "@/shared/lib/core/bsc";
import { useAppStore } from "@/store";
import { useConfirmDialog } from "@/shared/ui/overlay/promptDialog";
import type { Section } from "../github/ghStructure";
import { type GhStatusMap } from "./GitHubStructureCard";
import { deriveProjectTitle } from "./projectTitle";
import { parseFeaturesFile } from "../issues/featureList";
import { parseDependencyManifest, depsForRepo } from "../issues/dependencies";
import { buildWorkerScope, toWorkerUiPairing } from "../fleet/workerScope";
import { effectiveHarness } from "@/shared/lib/core/llmConfig";
import { type PlanIssue } from "../issues/planIssues";
import { pruneCompletedStreams, doneIssueRefs } from "@/shared/lib/fleet/streamCompletion";
import { resolveClosedRefs } from "@/features/glance";
import { withDerivedStreamIssues } from "../fleet/planFleet";
import { teamRoleStreams } from "../fleet/teamFleet";
import { recoverIssues, type GitHubIssueLike } from "../issues/recoverIssues";
import { removeDbProject } from "../list/projectsDbBridge";
import { publishFleetRoster } from "@/shared/lib/fleet/fleetRoster";
import { canLaunchTriage, publishBlockReason } from "@/shared/lib/github/projectSync";
import {
  type GhApi, type Upd, seedPublishStatus,
  publishRepositories, scaffoldRepositories, ensureProjectBoard, createIssues, applyStreamLabels,
  materializeIssues,
} from "./publishSteps";

export type PublishPhase = "idle" | "running" | "done" | "error";

type Store = ReturnType<typeof useAppStore.getState>;

export interface PlanPublishDeps {
  githubToken: string;
  publishRepos: string[];
  injectionGateState: { cleared: boolean; findings: unknown[]; mode: string };
  sections: Section[];
  planningTitle: string;
  activeProjectName: string;
  planFleet: Store["planFleet"];
  effectiveProjectId: string;
  activeProjectId: Store["activeProjectId"];
  activeProjectNumber: Store["activeProjectNumber"];
  planFeatures: ReturnType<typeof parseFeaturesFile>;
  planDependencies: ReturnType<typeof parseDependencyManifest>["dependencies"];
  depManifest: ReturnType<typeof parseDependencyManifest>;
  repoPublic: Store["repoPublic"];
  reposPublic: Record<string, boolean>;
  projectTitle: string;
  planReady: boolean;
  visible: boolean;
  addProjectRepo: Store["addProjectRepo"];
  fleetStartProject: Store["fleetStartProject"];
}

export function usePlanPublish(deps: PlanPublishDeps) {
  const {
    githubToken, publishRepos, injectionGateState, sections, planningTitle,
    activeProjectName, planFleet, effectiveProjectId, activeProjectId, activeProjectNumber,
    planFeatures, planDependencies, depManifest, repoPublic, reposPublic,
    projectTitle, planReady, visible, addProjectRepo, fleetStartProject,
  } = deps;

  const [triaging, setTriaging] = useState(false);
  const [triageError, setTriageError] = useState<string | null>(null); // launch-failure surfacing (#551)
  const [triageNote, setTriageNote] = useState<string | null>(null);   // progress-gated relaunch summary (#1004)
  // GitHub→plan.db recovery (#plan-db): how many planner-published issues GitHub holds when the
  // local plan.db is empty (machine switch / data loss), and whether a recovery is in flight.
  const [recoverable, setRecoverable] = useState(0);
  const [recovering, setRecovering] = useState(false);
  const [publishPhase, setPublishPhase] = useState<PublishPhase>("idle");
  // Live status of each GitHub object, keyed by the ids in buildGhStructure.
  const [ghStatus, setGhStatus] = useState<GhStatusMap>({});
  // Confirm + clear stale warden quarantines before a triage relaunch (a denied command from a prior
  // run otherwise persists and immediately re-pauses the relaunched worker). `quarantineDialog` is the
  // self-rendering modal node the JSX mounts.
  const { confirm, dialog: quarantineDialog } = useConfirmDialog();

  async function launchTriage() {
    const fleet = planFleet[effectiveProjectId];
    // Pre-flight gate (#444/#551) — mirror the button's gate so a programmatic / Enter-key
    // path can't launch against an unpublished or plan-incomplete project. (Restored: the
    // refactor had weakened this to a repos/fleet-only check.)
    if (!canLaunchTriage({
      published: !!activeProjectId,
      hasRepos: publishRepos.length > 0,
      hasFleet: !!fleet && fleet.streams.length > 0,
      busy: triaging,
      planReady,
    })) return;
    // A stale warden quarantine from a PRIOR run persists (in quarantinedPanes + the bsc-audit log)
    // and would immediately re-pause the relaunched worker. On triage: show the user WHY each worker
    // was quarantined, then clear those flags and stamp a warden "since" floor so the relaunch is clean.
    const projQuarantines = Object.entries(useAppStore.getState().quarantinedPanes)
      .filter(([p]) => p.startsWith(`${effectiveProjectId}:`));
    if (projQuarantines.length > 0) {
      const reasons = projQuarantines.map(([, info]) => `${info.streamId} (${info.summary})`).join("; ");
      const ok = await confirm({
        title: projQuarantines.length === 1 ? "Clear worker quarantine?" : `Clear ${projQuarantines.length} worker quarantines?`,
        message: `${projQuarantines.length === 1 ? "A worker was" : `${projQuarantines.length} workers were`} `
          + `quarantined and paused — ${reasons}. Relaunching clears `
          + `${projQuarantines.length === 1 ? "it and resumes the worker" : "them and resumes the workers"}.`,
        confirmLabel: "Clear & relaunch",
        cancelLabel: "Cancel",
      });
      if (!ok) return;
    }
    // Always stamp the warden floor for the project's panes on relaunch (even with nothing currently
    // flagged) so a stale denied command that hasn't tripped the warden yet also can't re-pause.
    {
      const relaunchPanes = (fleet?.streams ?? []).map((st) => `${effectiveProjectId}:${st.id}`);
      useAppStore.getState().clearProjectQuarantine(effectiveProjectId, relaunchPanes, Date.now());
    }
    setTriageError(null);
    setTriageNote(null);
    setTriaging(true);
    try {
      // Materialize the project hub on disk (#2997 C, epic #2993): planning ran in an ephemeral
      // per-project workspace, so this creates projects/<key>/ and moves the planner's authored files
      // in — BEFORE any director/worker cwd (the hub dir or a worktree beneath it) resolves to it.
      // Idempotent: an already-materialized hub or a re-launch is a no-op. Fail-CLOSED — without the
      // hub the director + worktree cwds don't exist, so surface the failure and abort the launch
      // rather than dropping the fleet into a missing directory.
      try {
        await invoke("materialize_hub", { projectKey: effectiveProjectId });
      } catch (e) {
        setTriageError(`launch failed — could not materialize the project hub: ${String(e)}`);
        return;
      }
      // #1988: when the sandbox is on AND the fleet runs on the model-agnostic bsc-agent harness (the
      // only runtime baked into the sealed distro), the whole fleet launches INSIDE the WSL2 cage —
      // the hub is relocated to the distro's ext4, repos are cloned + worktrees created in-distro, and
      // every pane spawns via `wsl -d <distro>`. Otherwise it's the normal host launch.
      const store0 = useAppStore.getState();
      const sandbox = store0.sandboxConsoles === true
        && effectiveHarness(store0.llmProvider, store0.fleetHarness ?? "claude") === "bsc-agent";
      const SANDBOX_DISTRO = "bsc-agent-sandbox";
      // Host clones seed the on-disk repo list the UI reads; skip them for a sandboxed launch (repos
      // are git-cloned in-distro by ensure_sandbox_worktree — nothing lands on the Windows host).
      if (!sandbox) await Promise.all(publishRepos.map(fullName =>
        invoke<string>("clone_repo", { project: effectiveProjectId, fullName })
          .then(() => addProjectRepo(activeProjectId ?? effectiveProjectId, fullName))
          .catch(e => console.error(`clone ${fullName} failed:`, e)),
      ));
      // Each worker auto-runs under its ROLE's default profile at launch (worker → Autonomous,
      // director → Read-only review) — no per-stream profile to materialize here anymore.
      const fullPlan = useAppStore.getState().planFleet[effectiveProjectId] ?? fleet;
      // Progress-gated relaunch (#1004): read each issue's status from plan.db and DON'T restart a
      // worker whose issues are all complete/verified — it already finished. Prune those streams (their
      // worktrees/branches persist untouched); launch only the streams with outstanding work, plus the
      // director if enabled. On a first launch nothing is done, so every stream stays active.
      const dbIssues = await bscJson<PlanIssue[]>(effectiveProjectId, ["plan", "list", "--full", "--json"], []);
      // #1957: completed workers no longer skip — they relaunch INTO maintenance (alive + ready for the
      // director to dispatch new lane work), so launch BOTH active and maintenance streams. The
      // maintenance set drives a maintenance scope banner (buildWorkerScope) so they stand by, not rebuild.
      // #4103: plan.db's issue rows can be empty for a fleet assembled outside a full planner run, in
      // which case `doneIssueRefs` is empty and NO stream ever prunes as complete. GitHub's closed set
      // is the other evidence source; either one calling a ref done makes it done.
      const closedRefs = await resolveClosedRefs(fullPlan.streams);
      const done = new Set([...doneIssueRefs(dbIssues), ...closedRefs]);
      const { active, maintenance } = pruneCompletedStreams(fullPlan.streams, done);
      const maintenanceIds = new Set(maintenance.map(s => s.id));
      // #2611: a stream with no resolvable repo stays VISIBLE in the plan but can't spawn a worktree —
      // skip it here (rather than aborting the fail-closed launch on a broken ensure_worktree) and
      // surface which streams still need a repo assigned, so the gap is seen, not swallowed.
      // #2615: a stream can reach launch with an empty `issues[]` even though issues name it as their
      // owning `stream` — enrich each stream's issue list from the plan.db issues so a worker launches
      // with its concrete task list (feeding BOTH the scope below and the kickoff via fleetStartProject),
      // not the "(none yet — ask the director)" placeholder. A stream that already lists issues is kept.
      const launchable = withDerivedStreamIssues([...active, ...maintenance].filter(st => st.repo), dbIssues);
      const noRepo = [...active, ...maintenance].filter(st => !st.repo);
      // Team-driven fleet (#3101/#3103): a project's TEAM contributes its ROLE-ACTOR sessions (curator,
      // documentor, reviewer, tester, juror, issuer) — one per team position bound to such a persona,
      // deduped vs the planner's own streams. They run at the project HUB (no repo → no worktree; the
      // `fleetStartProject` repo-less branch routes them there), so they compose in AFTER `launchable`
      // and are deliberately NOT part of the worktree-creation loop below.
      const teamStore = useAppStore.getState();
      const projectTeam = teamStore.blueprints.find(b => b.id === teamStore.projectBlueprintId[effectiveProjectId])?.team;
      const roleStreams = teamRoleStreams(projectTeam, teamStore.personas, fullPlan.streams);
      const launchPlan = { ...fullPlan, streams: [...launchable, ...roleStreams] };
      if (launchPlan.streams.length === 0 && !launchPlan.director.enabled) {
        setTriageError(noRepo.length > 0
          ? `No workers to launch — ${noRepo.length} stream${noRepo.length === 1 ? "" : "s"} (${noRepo.map(s => s.id).join(", ")}) need a repo assigned.`
          : "No workers to launch.");
        return;
      }
      const launchNotes: string[] = [];
      if (noRepo.length > 0) {
        launchNotes.push(`${noRepo.length} stream${noRepo.length === 1 ? "" : "s"} `
          + `(${noRepo.map(s => s.id).join(", ")}) skipped — no repo assigned`);
      }
      if (maintenance.length > 0) {
        launchNotes.push(`${maintenance.length} completed worker${maintenance.length === 1 ? "" : "s"} `
          + `(${maintenance.map(s => s.id).join(", ")}) relaunching into maintenance`
          + (active.length > 0 ? `; ${active.length} active` : ""));
      }
      if (launchNotes.length > 0) setTriageNote(launchNotes.join(". ") + ".");
      // The project's {kit, theme} pairing (#2489): plan.db's `ui` blob (the planner's per-project
      // record, `bsc plan ui set` in the Test UI stage) with the project blueprint's pin filling
      // whatever it doesn't set — inlined into every worker's scope as the UI-palette lock block
      // (token layer read-only; palette = the swappable theme.css).
      const uiBlob = await bscJson<{ kit?: { id?: string; version?: string } | null; themeId?: string } | null>(
        effectiveProjectId, ["plan", "ui", "get", "--json"], null);
      const storeUi = useAppStore.getState();
      const uiPairing = toWorkerUiPairing(
        uiBlob, storeUi.blueprints.find(b => b.id === storeUi.projectBlueprintId[effectiveProjectId])?.uiKit);
      // Create each worker's git worktree FAIL-CLOSED (#551/#359): if any can't be created,
      // abort the launch so no agent starts in a fallback dir. (Restored: the refactor had
      // weakened this to a non-fatal .catch that let the launch continue.)
      // Only the repo'd WORKER streams get a worktree — the team's hub role-actors (repo-less) are
      // excluded (they run at the hub, no isolated tree). `launchable` is exactly those worker streams.
      const worktreeResults = await Promise.all(launchable.map(st => {
        // Seed each worktree's CLAUDE.local.md with the worker's SCOPE (owns/issues/deps) plus its
        // repo's LOCKED dependency manifest (#1111), not the full plan — the worktree lives outside
        // the hub so the planner spec is no longer an ancestor (#844). In-distro when sandboxed
        // (ensure_sandbox_worktree clones the repo + adds the worktree on the distro's ext4, #1988).
        const scopeMd = buildWorkerScope(st, depsForRepo(planDependencies, st.repo), maintenanceIds.has(st.id), uiPairing);
        const call = sandbox
          ? invoke<string>("ensure_sandbox_worktree", { projectKey: effectiveProjectId, repo: st.repo, agentId: st.id, scopeMd, token: githubToken })
          : invoke<string>("ensure_worktree", { projectKey: effectiveProjectId, repo: st.repo, agentId: st.id, scopeMd });
        return call
          .then(path => ({ id: st.id, path, err: null as string | null }))
          .catch(e => ({ id: st.id, path: null as string | null, err: String(e) }));
      }));
      const failed = worktreeResults.filter(r => r.err || !r.path);
      if (failed.length > 0) {
        setTriageError(`launch failed — ${failed[0].id}: ${failed[0].err ?? "empty path"}`);
        return;
      }
      // Carry the authoritative absolute paths into fleetStartProject (#905) so each pane's
      // cwd comes from the Rust backend, not the async-loaded `bscBaseDir` mirror (which, when
      // empty/malformed, silently drops every session at the user's home dir). Workers use the
      // worktree path ensure_worktree just returned; the director uses the hub dir.
      const worktreePaths: Record<string, string> = {};
      for (const r of worktreeResults) if (r.path) worktreePaths[r.id] = r.path;
      // The director's cwd is the hub. Sandboxed → relocate the host hub onto the distro's ext4 and use
      // its distro-native path (setup_sandbox_hub); otherwise the on-host hub dir (#905).
      const hubPath = sandbox
        ? await safeInvoke<string>("setup_sandbox_hub", { key: effectiveProjectId }, "")
        : await safeInvoke<string>("project_dir_path", { projectKey: effectiveProjectId }, "");
      // Give the director its standing protocol at the hub (#375) so it gets the bsc-fleet
      // roster instruction + answers worker questions (the refactor dropped this call; #734).
      if (launchPlan.director.enabled) {
        await safeInvoke("ensure_director_protocol", { projectKey: effectiveProjectId }, undefined,
          e => console.error("director protocol failed:", e));
      }
      const roster = fleetStartProject(projectTitle, launchPlan, effectiveProjectId, { hubPath, worktreePaths, wslDistro: sandbox ? SANDBOX_DISTRO : undefined });
      publishFleetRoster(effectiveProjectId, roster); // #734: hub fleet.roster.tsv for bsc-fleet
    } catch (e) {
      console.error("fleet launch failed:", e);
    } finally {
      setTriaging(false);
    }
  }

  /** The LOCAL commit (#3280) — materialize the plan's issues into plan.db and mark the project active,
   *  with NO GitHub round-trip. This is what lets the fleet launch offline: `activeProjectId` set to the
   *  local project key flips `published` true (`canLaunchTriage`) and works as a key everywhere; a later
   *  publish upgrades it to the GitHub node id over the SAME plan.db rows (upsert-by-ref, no dupes).
   *  Shares publish's injection gate — never promote unreviewed markers to the fleet. */
  async function commitLocal() {
    if (!injectionGateState.cleared) {
      const n = injectionGateState.findings.length;
      setTriageError(injectionGateState.mode === "blocked"
        ? `Commit blocked: ${n} possible prompt-injection marker${n !== 1 ? "s" : ""} in the plan must be removed (hard-block is on in Settings).`
        : `Review the ${n} possible prompt-injection marker${n !== 1 ? "s" : ""} flagged in the plan, then acknowledge them before committing.`);
      return;
    }
    setTriageError(null);
    const featuresContent = sections.find(s => s.k === "features")?.content ?? "";
    await materializeIssues(featuresContent, { upsertIssue: (iss) => bscWrite(effectiveProjectId, ["plan", "add"], iss) });
    const goalContent  = sections.find(s => s.k === "goal")?.content ?? "";
    const projectTitle = deriveProjectTitle(planningTitle, goalContent, activeProjectName);
    // The local key IS activeProjectId here (no GitHub number) — publish later overwrites it with the
    // ProjectV2 node id. Reopening from the board derives the hub key from the name, so nothing bridges.
    useAppStore.getState().setActiveProjectMeta(effectiveProjectId, projectTitle, publishRepos[0] ?? "", 0, publishRepos);
  }

  async function handlePublish() {
    // #3280 local-first: with no GitHub token, "publish" commits the plan LOCALLY (plan.db) instead of
    // erroring — the fleet can then launch offline. Publishing to GitHub stays the optional path when
    // connected. (publishBlockReason's no-token case is now unreachable from here; the no-repo case
    // below still fires when connected.)
    if (!githubToken) { await commitLocal(); return; }
    // Don't fail silently (#969): surface WHY publish can't proceed, so the user isn't left thinking
    // they published when nothing happened (which then leaves the fleet-launch button locked with no
    // explanation). The common case is a blueprint with no Repos stage ⇒ no repo ever linked.
    const blocked = publishBlockReason({ hasToken: !!githubToken, repoCount: publishRepos.length });
    if (blocked) { setTriageError(blocked); return; }
    // #1107: never promote a plan with unreviewed / hard-blocked injection markers to the fleet.
    if (!injectionGateState.cleared) {
      const n = injectionGateState.findings.length;
      setTriageError(injectionGateState.mode === "blocked"
        ? `Publish blocked: ${n} possible prompt-injection marker${n !== 1 ? "s" : ""} in the plan must be removed (hard-block is on in Settings).`
        : `Review the ${n} possible prompt-injection marker${n !== 1 ? "s" : ""} flagged in the plan, then acknowledge them before publishing.`);
      return;
    }
    setTriageError(null);
    const token = githubToken;

    const repos        = publishRepos;
    const goalContent  = sections.find(s => s.k === "goal")?.content ?? "";
    const projectTitle = deriveProjectTitle(planningTitle, goalContent, activeProjectName);
    const projectDesc  = goalContent.split(/\n/)[0].slice(0, 350);
    const fleet        = planFleet[effectiveProjectId];
    const streams      = fleet?.streams ?? [];

    // Seed every node as "planned" so the card shows the full structure upfront.
    const status = seedPublishStatus({ repos, streams });
    setGhStatus({ ...status });
    setPublishPhase("running");

    let anyError = false;
    const upd: Upd = (id, patch) => {
      status[id] = { ...(status[id] ?? { status: "planned" }), ...patch };
      if (patch.status === "error") anyError = true;
      setGhStatus({ ...status });
    };

    // The GitHub transport — the same closures the steps consume (injected so they're testable).
    const api: GhApi = {
      gql: (query, variables) => invoke<Record<string, unknown>>("github_graphql", { token, query, variables }),
      rest: <T,>(path: string) => invoke<T>("github_request", { token, path }),
      post: <T,>(path: string, body: unknown) => invoke<T>("github_post", { token, path, body }),
      put: (path, body) => invoke("github_put", { token, path, body }),
      patch: (path, body) => invoke("github_patch", { token, path, body }),
    };

    try {
      // 1. Repositories — verify/create.
      const { repoNodeIds, viewerLogin } = await publishRepositories(api, upd, {
        repos, projectDesc, repoPublic, reposPublic, effectiveProjectId,
      });

      // 1b. Repo presentation — description/topics/README/community files + locked dep manifests.
      await scaffoldRepositories(api, upd, {
        repos, projectDesc, projectTitle, goalContent,
        stackText: sections.find(s => s.k === "stack")?.content ?? "",
        scopeText: sections.find(s => s.k === "scope")?.content ?? "",
        archText:  sections.find(s => s.k === "architecture")?.content ?? "",
        features: planFeatures.map(f => ({ name: f.name, behavior: f.behavior })),
        planDependencies, registries: depManifest.registries,
      });

      // 2. Project board — reuse or create; the store writes for a new board happen here in the hook.
      const board = await ensureProjectBoard(api, upd, {
        activeProjectId, activeProjectNumber, repos, viewerLogin, projectTitle, repoNodeIds,
      });
      const projectId = board.projectId;
      if (board.created) {
        const pv = board.created;
        const store = useAppStore.getState();
        // Reflect in the store so the projects list + future syncs treat it as existing.
        store.setActiveProjectMeta(pv.id, projectTitle, repos[0] ?? "", pv.number, repos);
        // No node-id → key alias write anymore (#2409): reopening from the board DERIVES the hub
        // key from the project's name (`projectSlug(title)`), so publish records nothing to bridge.
        // Mark the hub published in place (#922) — the hub never moves, so --continue history survives.
        fireInvoke("mark_published", { projectKey: effectiveProjectId }, (e) => console.warn("mark_published failed (Projects page reconciles it):", e));
        // Drop the store's draft entry so the project can't linger as a ghost draft card, and mirror
        // that removal into the durable projects DB (#2995) so the published project doesn't re-surface
        // as a draft from the DB union. Fire-and-forget; degrades silently.
        store.removeDraftProject(effectiveProjectId);
        void removeDbProject(effectiveProjectId);
      }

      // 3. Issues — features → issues, on the board, assigned, sub-issues nested (no milestones, #1912).
      await createIssues(api, upd, {
        repos, featuresContent: sections.find(s => s.k === "features")?.content ?? "",
        projectId, streams, viewerLogin,
      }, {
        upsertIssue: (iss) => bscWrite(effectiveProjectId, ["plan", "add"], iss),
      });

      // 4. Stream labels.
      await applyStreamLabels(api, upd, { streams });

      setPublishPhase(anyError ? "error" : "done");
    } catch (e) {
      console.error("publish failed", e);
      setPublishPhase("error");
    }
  }

  // GitHub → plan.db recovery (#plan-db). The mirror of handlePublish: pull each repo's
  // planner-published issues back into the plan store so a lost or machine-switched plan.db
  // rehydrates from the durable GitHub copy. Paginates issues (state=all), drops PRs, and upserts
  // each reconstructed PlanIssue (ref/dependsOn from the hidden marker, stream from the label,
  // status from open/closed). The 2s section poll reflects the DB afterward.
  async function handleRecover() {
    if (!githubToken || publishRepos.length === 0 || recovering) return;
    setRecovering(true);
    setTriageError(null);
    const token = githubToken;
    const rest = <T,>(path: string) => invoke<T>("github_request", { token, path });
    try {
      let total = 0;
      for (const repo of publishRepos) {
        const rows: GitHubIssueLike[] = [];
        for (let page = 1; page <= 20; page++) {
          const batch = await rest<GitHubIssueLike[]>(`repos/${repo}/issues?state=all&per_page=100&page=${page}`)
            .catch(() => [] as GitHubIssueLike[]);
          if (!batch || batch.length === 0) break;
          rows.push(...batch);
          if (batch.length < 100) break; // last page
        }
        for (const iss of recoverIssues(rows, repo)) {
          await bscWrite(effectiveProjectId, ["plan", "add"], iss);
          total++;
        }
      }
      setRecoverable(0);
      if (total === 0) setTriageError("recover — GitHub had no planner-published issues for these repos");
    } catch (e) {
      setTriageError(`recover failed — ${String(e)}`);
    } finally {
      setRecovering(false);
    }
  }

  // Offer recovery when the local plan.db is empty but GitHub holds planner-published issues (the
  // machine-switch / data-loss case). Probes the first repo for issues carrying the ref marker and
  // surfaces the banner; the recovery itself stays user-initiated.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      if (!visible || !githubToken || publishRepos.length === 0) { setRecoverable(0); return; }
      const dbIssues = await bscJson<PlanIssue[]>(effectiveProjectId, ["plan", "list", "--full", "--json"], []);
      if (cancelled) return;
      if ((dbIssues?.length ?? 0) > 0) { setRecoverable(0); return; } // db already populated — nothing to recover
      const rows = await safeInvoke<GitHubIssueLike[]>("github_request", {
        token: githubToken, path: `repos/${publishRepos[0]}/issues?state=all&per_page=100`,
      }, []);
      if (cancelled) return;
      // Count only planner-published issues — those with a ref marker (a recovered ref isn't "#<n>").
      setRecoverable(recoverIssues(rows ?? [], publishRepos[0]).filter((i) => !i.ref.startsWith("#")).length);
    })();
    return () => { cancelled = true; };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [visible, githubToken, publishRepos.join(","), effectiveProjectId]);

  return { handlePublish, launchTriage, handleRecover, triaging, triageError, triageNote, recoverable, recovering, publishPhase, setPublishPhase, ghStatus, quarantineDialog };
}

runtime.features/planner/session/usePlanSkillsMa:
// usePlanSkillsManagement (#1474) — the planner's session skill-group + live skills refresh,
// extracted verbatim from Planning.tsx. Side-effect only (no state, no return).

import { useEffect } from "react";
import { useAppStore } from "@/store";
import { usePoll } from "@/shared/hooks/usePoll";

export function usePlanSkillsManagement(sessionGroupId: string, projectTitle: string): void {
  const ensureSessionGroup = useAppStore(s => s.ensureSessionGroup);
  const refreshSkills = useAppStore(s => s.refreshSkills);
  // Whether the per-project session group exists YET. It's created lazily by
  // `bsc-skill add --group "$BSC_SESSION_SKILL_GROUP"` the first time the planner authors a skill —
  // NOT on planner open, so a project that authors none never leaves an empty group behind (#1616).
  const groupExists = useAppStore(s => s.skillGroups.some(g => g.id === sessionGroupId));

  // Adopt the session group ONCE IT EXISTS (#1419/#1616): never pre-create it. When the planner authors
  // its first skill, bsc-skill creates the group (placeholder name = its id); the refresh poll below
  // surfaces it here, and we rename the placeholder to the project name — and again if the title later
  // changes — without clobbering members. Persistent: reopening the planner keeps collecting into it.
  useEffect(() => {
    if (groupExists && sessionGroupId && projectTitle) ensureSessionGroup(sessionGroupId, projectTitle);
  }, [groupExists, sessionGroupId, projectTitle, ensureSessionGroup]);

  // Re-read the global skills.db while planning so skills the planner authors with `bsc-skill add`
  // (and their session-group membership) surface live in the pane — the skills.json file-poll that
  // used to do this was retired (#1417/#1419). Cheap (no push-back); 2.5s ≈ the section-poll cadence.
  usePoll(() => { void refreshSkills(); }, 2500, [refreshSkills]);
}

runtime.features/planner/session/usePlanStagePol:
// usePlanStagePoll (#1474) — the planner's 2-second plan.db + section-file poll, extracted
// verbatim from Planning.tsx. While the planning page is visible it reflects every DB-owned
// artifact (issues / features / repos / fleet / deploy / deps / mcp) plus the
// `read_plan_stages` file poll into the store, with per-artifact change-guards so an unchanged
// blob never churns state. Side-effect only — owns its guard refs internally and returns nothing.

import { useRef } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import { invoke } from "@tauri-apps/api/core";
import { bscJson, bscRun, bscWrite } from "@/shared/lib/core/bsc";
import { hashString } from "@/shared/lib/core/hashString";
import { useAppStore, type AutomationSuggestion } from "@/store";
import { FLEET_KEY } from "../fleet/planFleet";
import { FEATURES_KEY, canonicalTopicKey } from "../stages/planTopics";
import { reconcileConfirmations, reconcileSkips, type ConfirmRow } from "../stages/confirmReconcile";
import { parseDependencyManifest, DEPENDENCIES_KEY } from "../issues/dependencies";
import { parseDeployConfigTag } from "../lib/deployConfig";
import { coerceMarketConfig } from "../lib/marketConfig";
import { coerceClassifyConfig } from "../lib/classifyConfig";
import { coerceTransformationRows } from "../lib/transformations";
import { applyMcpAssign } from "../lib/planExtensions";
import { catalogLink } from "@/features/mcp";
import { scriptDocRelpath } from "./planningSession";
import { sanitizeProjectKey } from "@/shared/lib/core/projectPaths";
import { wantsSandboxLaunch } from "./plannerSandbox";
import { plannerLaunchConfig } from "./plannerLaunch";

/** A per-repo startup script row from plan.db (`bsc plan startup`, #2010). */
interface StartupScriptRow { repo: string; mode: "dev" | "triage"; path: string }

interface StagePollDeps {
  visible: boolean;
  projectId: string;
  /** Linked repos, passed to the deploy-config coercion. */
  publishRepos: string[];
  /** Queue first-party MCP servers for the download-confirmation modal. */
  enqueueMcpDownloads: (names: string[]) => void;
  /** The host hub dir — non-empty once `setup_workspaces` resolves. Drives the sandbox-read decision
   *  (#1988): a planner launched into the WSL2 cage writes its sections into the distro hub. */
  planningDir: string;
}

export function usePlanStagePoll({ visible, projectId: effectiveProjectId, publishRepos, enqueueMcpDownloads, planningDir }: StagePollDeps): void {
  // Per-artifact change-guards: skip re-applying an unchanged DB blob each 2s tick. `depsImportedRef`
  // gates the one-time legacy dependencies.json import; `mcpAppliedRef` the per-name MCP resolve.
  const deployAppliedRef = useRef<Record<string, string>>({});
  const marketAppliedRef = useRef<Record<string, string>>({});
  const classifyAppliedRef = useRef<Record<string, string>>({});
  const transformationsAppliedRef = useRef<Record<string, string>>({});
  const depsAppliedRef = useRef<Record<string, string>>({});
  const depsImportedRef = useRef<Set<string>>(new Set());
  const mcpAppliedRef = useRef<Set<string>>(new Set());
  const autoAppliedRef = useRef<Record<string, string>>({});
  const startupAppliedRef = useRef<Record<string, string>>({});
  // Projects whose pre-#2256 app-state confirmations have already been forward-migrated into plan.db
  // (one-time per project, so the migration doesn't re-run every 2s tick).
  const confirmMigratedRef = useRef<Set<string>>(new Set());
  // The same one-time-per-project guard for the pre-#2267 app-state skips forward-migration.
  const skipMigratedRef = useRef<Set<string>>(new Set());

  // Poll the section files Claude writes every 2 seconds while visible. Each
  // documented topic is its own file ({key}.md / phases.json / _skipped.md);
  // read_plan_stages returns them all dynamically, keyed by file stem. Writing
  // to the store drives the derived `sections`/`skipped` — confirmed sections
  // stay frozen. This file poll is more reliable than the raw <plan_update>
  // stream and is what surfaces brand-new topics as their own cards.

  usePoll(() => {
    if (!visible) return;
    const poll = async () => {
      try {
        const store = useAppStore.getState();
        const saved = store.planStages[effectiveProjectId] ?? {};

        // Sandbox (#1988): a planner launched INSIDE the WSL2 cage writes plan.db + section files into
        // the distro hub. Mirror the in-distro plan.db back to the host FIRST, so the DB-owned reads
        // below (issues/features/fleet/deploy/deps/mcp/automations/startup/blueprint) — and publish +
        // fleet launch, which read the host plan.db — reflect the sandboxed planner's work. Sections
        // (file-based) are read from the distro directly further down.
        const sandboxed = wantsSandboxLaunch(store.sandboxConsoles, plannerLaunchConfig(store, {}).providerId, planningDir);
        if (sandboxed) {
          await invoke("sync_sandbox_plan_db", { key: effectiveProjectId }).catch(() => { /* no in-distro db yet — ignore */ });
        }

        // Every DB-owned artifact is reflected the SAME way: read it from plan.db, stringify it, and —
        // only when the serialized blob changed since the last tick — apply it to the store. The
        // per-artifact specifics (its `bsc plan` subcommand, its change-guard, its coercion, and its
        // store setter) live as one row per artifact in the descriptor TABLE below; `reflectArtifact`
        // runs one row. Semantics are identical to the former hand-rolled per-artifact blocks: the
        // stringify-compare change-guard, the silent "not created yet" try/catch, the same fetch/
        // stringify fallbacks, coercers, setters, and order. Three artifacts (repos / deps / mcp) don't
        // fit the shape (loop / one-time legacy import / per-name set) and stay as bespoke blocks below.
        // ── THE batched read (#3842) ──────────────────────────────────────────────────────────
        // One `bsc plan snapshot --json` — one process spawn, one SQLite open — replacing the 17
        // separate `bsc plan <noun>` spawns this tick used to make. At 150-660ms per spawn those cost
        // more than the 2s interval, so the Tauri command queue oversubscribed and the user's
        // keystrokes (`pty_write`) queued behind them. #3666 stopped ticks STACKING; this shrinks the
        // tick itself. An empty object on failure ⇒ every artifact falls back exactly as before.
        const snap = await bscJson<Record<string, unknown>>(
          effectiveProjectId, ["plan", "snapshot", "--json"], {},
        ) ?? {};

        interface ArtifactDescriptor {
          /** This artifact's key in the `bsc plan snapshot` payload (#3842). */
          key: string;
          /** Value used when the snapshot has no entry (bridge absent / plan.db not created yet).
           *  Identical to the `--json` fallback each artifact's standalone read used to pass. */
          fetchFallback: unknown;
          /** Skip the whole reflect on a null/empty read (the artifacts the old code wrapped in `if (db)`). */
          requireTruthy?: boolean;
          /** `db ?? this` before JSON.stringify (the non-`requireTruthy` artifacts' `?? []`). */
          stringifyFallback?: unknown;
          /** Current guard value — a per-project applied-ref, or the store-owned section blob. */
          applied: () => string | undefined;
          /** Record the applied guard value (no-op when the store write is itself the record). */
          setApplied: (raw: string) => void;
          /** Reflect the read into the store. */
          apply: (db: unknown, raw: string) => void;
        }
        const reflectArtifact = (d: ArtifactDescriptor): void => {
          try {
            // #3842: the value comes from the ONE snapshot read above, not a per-artifact spawn.
            // `?? fetchFallback` reproduces exactly what the standalone `--json` read returned when
            // plan.db had no such artifact, so every guard/coercer/setter below is unchanged.
            const db = snap[d.key] ?? d.fetchFallback;
            if (d.requireTruthy && !db) return;
            const raw = JSON.stringify(db ?? d.stringifyFallback);
            if (raw !== d.applied()) {
              d.setApplied(raw);
              d.apply(db, raw);
            }
          } catch { /* plan.db not created yet — ignore */ }
        };
        // One row per DB-owned artifact, in the same order the old blocks ran. (The bespoke shapes —
        // repos / deps / mcp — run just after as their own blocks; they're order-independent of these.)
        const ARTIFACTS: ArtifactDescriptor[] = [
          // Issues (#plan-db) → the "issues" section, so publish / structure card / grading / mobile mirror read unchanged.
          {
            key: "issues", fetchFallback: [], stringifyFallback: [],
            applied: () => saved["issues"] ?? "", setApplied: () => undefined,
            apply: (_db, raw) => store.setPlanStage(effectiveProjectId, "issues", raw),
          },
          // Features (#plan-db) → the "features" section (board + gate).
          {
            key: "features", fetchFallback: [], stringifyFallback: [],
            applied: () => saved[FEATURES_KEY] ?? "", setApplied: () => undefined,
            apply: (_db, raw) => store.setPlanStage(effectiveProjectId, FEATURES_KEY, raw),
          },
          // Fleet (#1018/#1805, plan.db is the SOLE fleet source) → the "fleet" section (parseFleetFile → setPlanFleet).
          {
            key: "fleet", fetchFallback: null, requireTruthy: true,
            applied: () => saved[FLEET_KEY] ?? "", setApplied: () => undefined,
            apply: (_db, raw) => store.setPlanStage(effectiveProjectId, FLEET_KEY, raw),
          },
          // Deploy config (#1020) → coerced through parseDeployConfigTag into planDeployConfig (the `deploy` gate).
          {
            key: "deploy", fetchFallback: null, requireTruthy: true,
            applied: () => deployAppliedRef.current[effectiveProjectId],
            setApplied: (raw) => { deployAppliedRef.current[effectiveProjectId] = raw; },
            apply: (_db, raw) => {
              const cfg = parseDeployConfigTag(raw, publishRepos);
              if (cfg) store.setPlanDeployConfig(effectiveProjectId, cfg);
            },
          },
          // Market assessment (#2430) → coerced into planMarketConfig (the `marketDefined` gate + Market body).
          {
            key: "market", fetchFallback: null, requireTruthy: true,
            applied: () => marketAppliedRef.current[effectiveProjectId],
            setApplied: (raw) => { marketAppliedRef.current[effectiveProjectId] = raw; },
            apply: (db) => {
              const cfg = coerceMarketConfig(db);
              if (cfg) store.setPlanMarketConfig(effectiveProjectId, cfg);
            },
          },
          // Classification (#3783/#3784) → the planner's discovery output: the UI mode (custom in-app
          // preview vs external drop-files) AND the source/mcp/skills/automations need-flags. Stored whole
          // into planClassification; FocusedBodies reads uiMode, usePlanGates derives the visibility signals.
          {
            key: "classify", fetchFallback: null, requireTruthy: true,
            applied: () => classifyAppliedRef.current[effectiveProjectId],
            setApplied: (raw) => { classifyAppliedRef.current[effectiveProjectId] = raw; },
            apply: (db) => {
              const cfg = coerceClassifyConfig(db);
              if (cfg) store.setPlanClassification(effectiveProjectId, cfg);
            },
          },
          // Transformations (#2509) → coerced rows into planTransformations (the bottom-up confirm queue + gate).
          {
            key: "transformations", fetchFallback: [], stringifyFallback: [],
            applied: () => transformationsAppliedRef.current[effectiveProjectId],
            setApplied: (raw) => { transformationsAppliedRef.current[effectiveProjectId] = raw; },
            apply: (db) => store.setPlanTransformations(effectiveProjectId, coerceTransformationRows(db)),
          },
          // Automations (#2009) → full replace of planAutomations (the `automations` gate).
          {
            key: "automations", fetchFallback: [], stringifyFallback: [],
            applied: () => autoAppliedRef.current[effectiveProjectId],
            setApplied: (raw) => { autoAppliedRef.current[effectiveProjectId] = raw; },
            apply: (db) => store.setPlanAutomations(effectiveProjectId, (db as AutomationSuggestion[] | null) ?? []),
          },
          // Startup scripts (#2010) → per-repo dev/triage startup prompt docs (each `path` resolved to a unified-store relpath).
          {
            key: "startup", fetchFallback: [], stringifyFallback: [],
            applied: () => startupAppliedRef.current[effectiveProjectId],
            setApplied: (raw) => { startupAppliedRef.current[effectiveProjectId] = raw; },
            apply: (db) => {
              const key = sanitizeProjectKey(effectiveProjectId);
              for (const sc of (db as StartupScriptRow[] | null) ?? []) {
                const relpath = scriptDocRelpath(key, sc.path);
                if (sc.mode === "triage") store.setRepoTriagePromptDoc(effectiveProjectId, sc.repo, relpath);
                else                      store.setRepoStartupPromptDoc(effectiveProjectId, sc.repo, relpath);
              }
            },
          },
        ];
        for (const d of ARTIFACTS) reflectArtifact(d);

        // Linked repos are DB-owned too (#1012) — restore them from the hub's plan.db into the store
        // so a zustand/app-state reset can't lose the links (the store-only persistence proved fragile).
        try {
          const dbRepos = (snap.repos as string[] | undefined) ?? [];
          for (const r of dbRepos ?? []) store.addProjectRepo(effectiveProjectId, r);
        } catch { /* plan.db not created until the first repo is linked — ignore */ }

        // Dependency manifest is DB-owned (#1191) — the planner records it with `bsc-plan deps set`
        // (was a raw `dependencies.json`). Reflect the stored blob into the DEPENDENCIES section so the
        // gate, DeployView, worker scope, and publish all read it from plan.db unchanged. When the DB is
        // still empty but a legacy `dependencies.json` exists in the section store, import it ONCE
        // (no data loss) so pre-#1191 projects migrate transparently; after that the DB is authoritative.
        try {
          const dbDeps = snap.deps ?? null;
          if (dbDeps) {
            const raw = JSON.stringify(dbDeps);
            if (raw !== depsAppliedRef.current[effectiveProjectId]) {
              depsAppliedRef.current[effectiveProjectId] = raw;
              if (raw !== (saved[DEPENDENCIES_KEY] ?? "")) store.setPlanStage(effectiveProjectId, DEPENDENCIES_KEY, raw);
            }
          } else if (!depsImportedRef.current.has(effectiveProjectId)) {
            // One-time legacy import: the file content surfaced as the DEPENDENCIES section by an earlier
            // `read_plan_stages` tick. Re-serialize through the tolerant parser so a bare-array (#1111)
            // file is normalized to the full manifest shape before it lands in plan.db.
            const legacy = saved[DEPENDENCIES_KEY] ?? "";
            const manifest = parseDependencyManifest(legacy);
            if (manifest.dependencies.length || Object.keys(manifest.registries).length) {
              depsImportedRef.current.add(effectiveProjectId);
              await bscWrite(effectiveProjectId, ["plan", "deps", "set"], manifest);
            }
          }
        } catch { /* plan.db not created until the planner sets deps — ignore */ }

        // MCP assignments are DB-owned (#1021) — resolve each assigned catalog name into the MCP-servers
        // store (idempotent). First-party servers are queued for the download-confirmation modal
        // (#1055) instead of cloned silently. The applied-set guards against re-applying the same name
        // every 2s tick (and the modal's seen-set guards against re-prompting).
        try {
          const dbMcp = (snap.mcp as string[] | undefined) ?? [];
          const toDownload: string[] = [];
          for (const name of dbMcp ?? []) {
            const key = `${effectiveProjectId}::${name.toLowerCase()}`;
            if (mcpAppliedRef.current.has(key)) continue;
            mcpAppliedRef.current.add(key);
            applyMcpAssign(store, name, effectiveProjectId, store.bscBaseDir);
            if (catalogLink(name)) toDownload.push(name);
          }
          if (toDownload.length) void enqueueMcpDownloads(toDownload);
        } catch { /* plan.db not created until the planner assigns an MCP server — ignore */ }

        // Section files: a planner launched INSIDE the WSL2 cage (#1988) writes them into the distro
        // hub, so read from there (via `read_sandbox_plan_stages`) when this session is sandboxed
        // (`sandboxed`, computed above) — else the host hub. Fall back to the host read if the distro
        // read is empty (e.g. the relocation fell back to host at launch), so sections never vanish.
        let result: Record<string, string>;
        if (sandboxed) {
          result = await invoke<Record<string, string>>("read_sandbox_plan_stages", { key: effectiveProjectId })
            .catch(() => ({} as Record<string, string>));
          if (Object.keys(result).length === 0) {
            result = await invoke<Record<string, string>>("read_plan_stages", { projectKey: effectiveProjectId });
          }
        } else {
          result = await invoke<Record<string, string>>("read_plan_stages", { projectKey: effectiveProjectId });
        }
        const entries = Object.entries(result);

        for (const [rawKey, content] of entries) {
          // Canonicalize the file stem (e.g. "Tech stack" → "stack") so a title-named file
          // still satisfies the gate (#…).
          const key = canonicalTopicKey(rawKey);
          if (key === "issues" || key === FEATURES_KEY || key === FLEET_KEY) continue; // DB-owned (#plan-db/#1018) — sourced from plan.db above, not a file
          // Dependencies are DB-owned (#1191): once plan.db has supplied the manifest, the DB blob wins
          // over any lingering legacy `dependencies.json`. Until then, let the file through so the
          // one-time legacy import (above) can read it.
          if (key === DEPENDENCIES_KEY && depsAppliedRef.current[effectiveProjectId]) continue;
          // A confirmed stage's content is NO LONGER frozen (#2256): let a changed section through so
          // the confirm-reconcile below can detect the change and reset just that one stage.
          if (content && content !== (saved[key] ?? "")) {
            store.setPlanStage(effectiveProjectId, key, content);
          }
        }

        // Stage confirmations (#2256) — plan.db is the durable store. Rehydrate the confirmed set on
        // revisit, RESET just the stages whose content changed since they were confirmed (fingerprint
        // mismatch), and forward-migrate any pre-#2256 app-state-only confirmations into plan.db once.
        // Runs AFTER all content writes above so the live fingerprints reflect this tick's sections.
        try {
          const rows = (snap.confirm as ConfirmRow[] | undefined) ?? [];
          const fresh = useAppStore.getState();
          const liveSections = fresh.planStages[effectiveProjectId] ?? {};
          const plan = reconcileConfirmations(
            rows, liveSections,
            new Set(fresh.planConfirmedStages[effectiveProjectId] ?? []),
            confirmMigratedRef.current.has(effectiveProjectId),
          );
          for (const k of plan.rehydrate) fresh.markStageConfirmedLocal(effectiveProjectId, k);
          for (const k of plan.reset) fresh.unconfirmPlanStage(effectiveProjectId, k);
          if (plan.migrate.length) {
            confirmMigratedRef.current.add(effectiveProjectId);
            for (const k of plan.migrate) {
              await bscRun(effectiveProjectId, ["plan", "confirm", "add", k, hashString(liveSections[k] ?? "")]);
            }
          }
        } catch { /* plan.db not created yet — ignore */ }

        // Skipped stages (#2267) — same durability as confirmations, minus the fingerprint/reset (a
        // skip is a plain decision, not content-based). Rehydrate the skipped set on revisit and
        // forward-migrate any pre-#2267 app-state-only skips into plan.db once.
        try {
          const rows = (snap.skip as string[] | undefined) ?? [];
          const fresh = useAppStore.getState();
          const plan = reconcileSkips(
            rows,
            new Set(fresh.planSkippedStages[effectiveProjectId] ?? []),
            skipMigratedRef.current.has(effectiveProjectId),
          );
          for (const k of plan.rehydrate) fresh.markStageSkippedLocal(effectiveProjectId, k);
          if (plan.migrate.length) {
            skipMigratedRef.current.add(effectiveProjectId);
            for (const k of plan.migrate) await bscRun(effectiveProjectId, ["plan", "skip", "add", k]);
          }
        } catch { /* plan.db not created yet — ignore */ }
      } catch {
        // plans dir may not exist yet — ignore
      }
    };
    return poll();
  }, 2000, [visible, effectiveProjectId]);
}

runtime.features/planner/session/useSetupSignatu:
// useSetupSignature (#1775, extracted from Planning.tsx) — the "context updated · refresh" badge
// signal (#175/#756). `currentSig` is the live signature of the inputs (computed in Rust so its
// format can't drift from the baseline); `lastSetupSig` is the baseline setup_workspaces last wrote.
// When they diverge (a repo linked / blueprint changed mid-session, or the planner template bumped)
// `contextStale` is true. `refreshSetupSig` re-reads the baseline — call after every workspace setup.
import { useState, useEffect, useCallback } from "react";
import { invoke } from "@tauri-apps/api/core";

export function useSetupSignature(
  effectiveProjectId: string,
  linkedRepos: string[],
  stageIdsFor: (key: string) => string[],
): { currentSig: string | null; lastSetupSig: string | null; refreshSetupSig: () => void; contextStale: boolean } {
  const [currentSig, setCurrentSig] = useState<string | null>(null);
  const [lastSetupSig, setLastSetupSig] = useState<string | null>(null);
  useEffect(() => {
    let live = true;
    invoke<string>("compute_context_signature", {
      repoFullNames: linkedRepos,
      enabledStages: stageIdsFor(effectiveProjectId),
    }).then(sig => { if (live) setCurrentSig(sig); }).catch(() => { if (live) setCurrentSig(null); });
    return () => { live = false; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [linkedRepos, effectiveProjectId]);
  // Re-read the baseline the backend last wrote — called on open and after every workspace setup
  // (mount / link / restart), so the badge reflects the most recent regeneration.
  const refreshSetupSig = useCallback(() => {
    invoke<string>("get_context_signature", { projectKey: effectiveProjectId })
      .then(s => setLastSetupSig(s || null)).catch(() => {});
  }, [effectiveProjectId]);
  useEffect(() => { refreshSetupSig(); }, [refreshSetupSig]);
  const contextStale = !!currentSig && !!lastSetupSig && currentSig !== lastSetupSig;
  return { currentSig, lastSetupSig, refreshSetupSig, contextStale };
}

runtime.features/planner/stages/blueprintBuiltin:
// Built-in blueprint LIBRARY + stage defs (#513/#514, split out #2148): the runtime DATA
// behind the Blueprints page — the packaged stage/section defs (STAGE_DEFS), the
// section-instance builder (mkStage), and the assembly of the built-in blueprint
// library (makeBlueprints). Pure (no React/Tauri) so it's unit-testable and the store can seed
// from it directly. Types live in blueprintTypes.ts; the pure helpers in blueprintStages.ts.

import { overlayGlob } from "@/shared/lib/core/configOverrides";
import type {
  SectionDef, BlueprintStage, Blueprint, BlueprintDef,
} from "./blueprintTypes";

// ── ids ──────────────────────────────────────────────────────────────────────
let _id = 0;
/** Ephemeral handle for a section/pipeline instance (stable within a session). */
export const uid = (p: string) => `${p}-${++_id}`;

// The blueprint-stage "pipeline" abstraction was removed in #897 Phase 4c: there was no
// production trigger engine, and the three surviving behaviors — render-preview, grade-plan,
// lint-plan — run by direct dispatch from their own modules. Capability now attaches to a
// blueprint as skills (#636) + MCP servers (#897); app-actions are the section `output`
// disposition + handlePublish.

// The canonical planning-stage data lives as one JSON file per stage under src-tauri/data/stages/
// (one file per key), the unified packaged-data root (#1462). Loaded + assembled into STAGE_DEFS here.
const sectionModules = import.meta.glob<{ default: SectionDef }>("@data/stages/*.json", { eager: true });

/** Every section definition, keyed by its filename stem (= the section key). The config-dir copy
 *  (#2047) overlays the Vite-embedded default per stage file. */
export const STAGE_DEFS: Record<string, SectionDef> = Object.fromEntries(overlayGlob("stages", sectionModules));

/** The packaged library kit id (= `REACT_UI_KIT_ID`) a fresh app is built on — stamped as a
 *  built-in blueprint's consumer `kit` so `recordBlueprintKit` files the `kit_usage` edge (#2277/#2810).
 *  A literal (not a `@/features/designs` import) to keep `planner` decoupled from `designs`. */
const PACKAGED_KIT_ID = "react-ui";

/** Dedup a blueprint's section list by stage key — a hand-edited or imported blueprint could carry
 *  two sections with the same key; keep the first so the focused pane / gates resolve a single stage. */
export function dedupeSections(sections: BlueprintStage[]): BlueprintStage[] {
  const seen = new Set<string>();
  const out: BlueprintStage[] = [];
  for (const s of sections) {
    if (seen.has(s.key)) continue;
    seen.add(s.key);
    out.push(s);
  }
  return out;
}

/** Build a section instance from a def key + per-blueprint overrides. */
export function mkStage(
  key: string,
  { enabled = true, expanded = false, optional }:
    { enabled?: boolean; expanded?: boolean; optional?: boolean } = {},
): BlueprintStage {
  const def = STAGE_DEFS[key];
  return {
    uid: uid("sec"), key, ...def, enabled, expanded,
    // explicit `optional` overrides the def's; otherwise inherit it
    optional: optional ?? def.optional,
  };
}

// The built-in blueprints live as one JSON file per blueprint under ./blueprints/ — each is just
// metadata + an ordered list of section keys that chain into ./sections/*.json (resolved below).
const blueprintModules = import.meta.glob<{ default: BlueprintDef }>("@data/blueprints/*.json", { eager: true });

/** RETIRED packaged blueprint ids — a TOMBSTONE list (#3840, same shape as the component-suppression
 *  tombstone in #3725).
 *
 *  Deleting a blueprint's `@data/blueprints/*.json` is NOT enough to retire it. `overlayGlob` matches
 *  the config-dir mirror (`~/.base-studio-code/config/blueprints/`) to the embedded set by filename
 *  stem and APPENDS any file it does not recognise — so on every install that once shipped the
 *  blueprint, the orphaned mirror copy keeps re-introducing it. `refreshBuiltIns` then sees it as
 *  code-owned and its prune (correctly) leaves it alone. Net effect: a retired blueprint is
 *  immortal.
 *
 *  Listing the id here drops it after the overlay, so a stale mirror cannot resurrect it. Retired:
 *    complete          — folded into `default` (the greenfield superset, #3785)
 *    feature-add       — the add-a-feature route, folded into the planner's own flow
 *    ui-kit            — obsolete once the designer generates UI in-app (#3783)
 *    blueprint-author  — superseded by the post-triage Generate-Blueprint promotion (#3785/#3831)
 *  (`serverless-function` is in the same orphaned state but was deliberately left in place.) */
export const RETIRED_BLUEPRINT_IDS: readonly string[] = [
  "complete", "feature-add", "ui-kit", "blueprint-author",
];

/** The built-in blueprint library, assembled from the per-blueprint JSON definitions: ordered by
 *  each def`s `order`, with its section keys resolved into section instances via mkStage.
 *  {@link RETIRED_BLUEPRINT_IDS} are dropped AFTER the overlay, so a stale config mirror cannot
 *  reintroduce a blueprint the app no longer ships. */
export function makeBlueprints(): Blueprint[] {
  return overlayGlob("blueprints", blueprintModules)
    .filter(([stem]) => !RETIRED_BLUEPRINT_IDS.includes(stem))
    .map(([, def]) => def)
    .filter((def) => !RETIRED_BLUEPRINT_IDS.includes(def.id))
    .sort((a, b) => (a.order ?? 0) - (b.order ?? 0))
    .map(({ order: _order, sections, ...meta }) => {
      // A CREATE blueprint ships a fresh UI on the packaged kit, so record it as the app's consumer
      // `kit` (#2277/#2810): `recordBlueprintKit` then files the `kit_usage` edge at every bind, so a kit
      // change fans out to the project. An explicit `kit` in the def wins; an `operate` blueprint runs
      // against existing repos and isn't tied to a shared kit → no key added. (Keyed off `mode` since
      // #3785 — the lifecycle `category` this used to read left the blueprint model for discovery.)
      const kit = meta.kit ?? (meta.mode !== "operate" ? PACKAGED_KIT_ID : undefined);
      return {
        ...meta,
        ...(kit ? { kit } : {}),
        sections: dedupeSections(sections.map((s) => mkStage(s.key, { optional: s.optional }))),
      };
    });
}

runtime.features/planner/stages/blueprints.ts:
// Blueprints (#513/#514): the model behind the Blueprints page. A blueprint is an
// ordered list of planning SECTIONS (stages) that seeds every new project. Each
// section owns its prompt module (the instructions Claude receives for that stage)
// and its PIPELINES — pluggable actions that run on the stage's output. Pure (no
// React/Tauri) so it's unit-testable and the store can seed from it directly.
//
// Mirrors design/base-studio-code-projects/Blueprints.html.
//
// Decomposed (#2148) into three colocated modules, re-exported here so this remains the
// single public entry point (every importer keeps `@/features/planner/stages/blueprints`):
//   • blueprintTypes.ts    — the pure type surface (SectionDef / Blueprint / status types).
//   • blueprintBuiltins.ts — the packaged stage defs + built-in library assembly (STAGE_DEFS,
//                            mkStage, makeBlueprints, CATEGORY_META, …).
//   • blueprintStages.ts   — the pure helpers (auth-lifecycle, filtering, the blueprint-driven
//                            stage status/progress engine, template-change detection).

export * from "./blueprintTypes";
export * from "./blueprintBuiltins";
export * from "./blueprintStages";

// Pure blueprint/stage HELPERS (#513/#514, split out #2148): the functions over blueprint +
// section data — the authoring-lifecycle checks, search filtering, section/dep/lock resolution,
// the built-in refresh/merge, the blueprint-driven stage status + progress engine, and the
// template-change detection. Pure (no React/Tauri). Types live in blueprintTypes.ts; the packaged
// data + library assembly in blueprintBuiltins.ts.

import { PLAN_STAGES, type StageConfig, type StageId } from "./planStages";
import { evalGate, gateApplies, type PlanSignals } from "./stageGate";
import type {
  Blueprint, BlueprintStage, SectionStatus,
  StageRenderStatus, IncompleteStage, SectionDef, ModelCapabilityTier, StageSeed,
} from "./blueprintTypes";
import { uid, makeBlueprints, dedupeSections } from "./blueprintBuiltins";

// ── Dynamic-blueprint resolution (#1854 Phase a) ──────────────────────────────

/** Resolve the prompt to use for a stage, adapting to the driving model's capability tier (#1854
 *  Phase a). When a `tier` is given and the stage declares a {@link SectionDef.promptVariants}
 *  override for exactly that tier, that variant wins; otherwise the stage's base `prompt` is used —
 *  so a stage with no variants (or no tier) behaves exactly as today (the base prompt). The lookup is
 *  DIRECT (no cross-tier cascade): an absent variant falls straight back to the base `prompt`, which
 *  is already the open-ended frontier prompt. Returns "" for a missing section. */
export function resolveStagePrompt(
  section: Pick<SectionDef, "prompt" | "promptVariants"> | undefined,
  tier?: ModelCapabilityTier,
): string {
  if (!section) return "";
  const variant = tier ? section.promptVariants?.[tier] : undefined;
  return variant?.trim() ? variant : section.prompt;
}

/** The archetype seed content for a stage, or undefined when the stage carries none (#1854 Phase a).
 *  A convenience accessor so callers don't reach into `section.seed` (and so an empty/whitespace
 *  `content` is treated as absent). */
export function stageSeed(section: Pick<SectionDef, "seed"> | undefined): StageSeed | undefined {
  const seed = section?.seed;
  return seed?.content?.trim() ? seed : undefined;
}

/** Filter blueprints by a free-text query over name/desc/tags. Pure; drives the Library's search.
 *  The lifecycle-category facet went away with #3785 — a blueprint is a goal/domain route now, and
 *  lifecycle is discovered per PROJECT (`ClassifyConfig.lifecycle`), not declared per blueprint. */
export function filterBlueprints(blueprints: Blueprint[], opts: { query?: string }): Blueprint[] {
  const q = (opts.query ?? "").trim().toLowerCase();
  if (!q) return blueprints;
  return blueprints.filter((b) =>
    `${b.name} ${b.desc} ${(b.tags ?? []).join(" ")}`.toLowerCase().includes(q));
}

export const DEFAULT_BLUEPRINT_ID = "default";

/** Seed blueprints — the starter library, depicting every section/pipeline state. */
/**
 * Replace persisted built-in blueprints with their current code definitions (by id) and
 * append any new built-ins, leaving user-created / forked / imported blueprints untouched.
 * Built-ins are code-owned templates, but `blueprints` is persisted — this lets improvements
 * (the optional UI stage, enabled repos, updated prompts, …) reach an already-seeded store
 * instead of being pinned to the version a user first ran (#677).
 */
export function refreshBuiltIns(persisted: Blueprint[]): Blueprint[] {
  const fresh = makeBlueprints();
  const byId = new Map(fresh.map((b) => [b.id, b]));
  // Drop persisted built-ins that no longer exist in code (removed templates), refresh the rest by
  // id, and leave user-created / forked / imported blueprints untouched (#923 cleanup).
  const merged = persisted
    .filter((b) => b.origin !== "built-in" || byId.has(b.id))
    // Built-ins are replaced by their fresh code def; everything else is a persisted
    // user/forked/imported blueprint — dedup its section keys defensively.
    .map((b) => (b.origin === "built-in" && byId.has(b.id) ? byId.get(b.id)! : { ...b, sections: dedupeSections(b.sections) }));
  for (const b of fresh) if (!merged.some((x) => x.id === b.id)) merged.push(b);
  return merged;
}

/**
 * Dependency / lock resolution. A section is LOCKED when it's enabled but a
 * dependency is off or itself locked. A dep this blueprint omits is treated as met.
 */
export function computeStatus(sections: BlueprintStage[]): Record<string, SectionStatus> {
  const byKey: Record<string, BlueprintStage> = Object.fromEntries(sections.map((s) => [s.key, s]));
  const memo: Record<string, boolean> = {};
  function satisfied(key: string, stack: Set<string>): boolean {
    if (key in memo) return memo[key];
    const s = byKey[key];
    if (!s) return true;
    if (!s.enabled) return (memo[key] = false);
    if (stack.has(key)) return true; // cycle guard
    stack.add(key);
    const ok = (s.deps || []).every((d) => satisfied(d, stack));
    stack.delete(key);
    return (memo[key] = ok);
  }
  const out: Record<string, SectionStatus> = {};
  for (const s of sections) {
    const present = (s.deps || []).filter((d) => byKey[d]);
    const unmet = present.filter((d) => !byKey[d].enabled || !satisfied(d, new Set()));
    out[s.key] = { locked: s.enabled && unmet.length > 0, unmet, satisfied: satisfied(s.key, new Set()) };
  }
  return out;
}

/** Move `fromUid` before/after `toUid` in a uid-keyed list (drag-reorder). */
export function reorder<T extends { uid: string }>(arr: T[], fromUid: string, toUid: string, before: boolean): T[] {
  const a = [...arr];
  const fi = a.findIndex((x) => x.uid === fromUid);
  if (fi < 0) return arr;
  const [item] = a.splice(fi, 1);
  let ti = a.findIndex((x) => x.uid === toUid);
  if (ti < 0) { a.push(item); return a; }
  if (!before) ti += 1;
  a.splice(ti, 0, item);
  return a;
}

/** Deep-copy sections with fresh uids (for duplicate). */
export function cloneStages(sections: BlueprintStage[]): BlueprintStage[] {
  return sections.map((s) => ({ ...s, uid: uid("sec") }));
}

/**
 * Derive the per-project StageConfig (enabled + order over the registry's known
 * StageIds) that the planning N-bar reads, from a blueprint's sections. Custom and
 * non-registry sections (e.g. testing) are omitted — they configure planning but
 * don't have a registry gate yet.
 */
/**
 * What to record when a project's planning opens (#647). A brand-new project (no stage
 * config) seeds from + records the active blueprint. An existing project with NO recorded
 * blueprint (planned before blueprint tracking) backfills to the default — so selecting a
 * different blueprint still triggers the reset prompt instead of silently doing nothing.
 * Otherwise the project already knows its blueprint, so nothing changes here.
 */
export function resolveProjectSeed(
  hasConfig: boolean, recordedBlueprintId: string | undefined, activeBlueprintId: string,
): { seedConfig: boolean; setBlueprintId?: string } {
  if (!hasConfig) return { seedConfig: true, setBlueprintId: activeBlueprintId };
  if (!recordedBlueprintId) return { seedConfig: false, setBlueprintId: DEFAULT_BLUEPRINT_ID };
  return { seedConfig: false };
}

export function blueprintToStageConfig(bp: Blueprint): StageConfig {
  const known = new Set<string>(PLAN_STAGES.map((s) => s.id));
  const enabled = Object.fromEntries(PLAN_STAGES.map((s) => [s.id, false])) as Record<StageId, boolean>;
  const order: StageId[] = [];
  for (const s of bp.sections) {
    if (!known.has(s.key)) continue;
    const id = s.key as StageId;
    enabled[id] = s.enabled;
    order.push(id);
  }
  return { enabled, order };
}

// ── Blueprint-driven status (#…) ──────────────────────────────────────────────
// These evaluate a blueprint's sections DIRECTLY against the published signal bag —
// no PLAN_STAGES enum, no per-stage hardcoding. Each section carries its own
// declarative gate (`gateRule`), applicability (`appliesWhen`), and `deps`, so a
// built-in section and a cloud-distributed one are evaluated by the exact same code.
// The progress bar, readiness check, current-section, and the "what's incomplete"
// feedback all read from here.

/** The signal that marks an informational (gateless) section confirmed/complete (#664). */
export const confirmedSignal = (key: string) => `confirmed:${key}`;

/** The signal that marks an OPTIONAL section the user deliberately SKIPPED (#921). A skipped
 *  section counts as resolved — the flow advances past it and it never blocks completion — but
 *  it renders distinctly ("skipped", not "complete"). */
export const skippedSignal = (key: string) => `skipped:${key}`;

/** Whether a section is done/resolved. A user-SKIPPED section (#921) is resolved regardless of
 *  its gate. Otherwise: a section WITH a declarative gate uses {@link evalGate}; a gateless
 *  ("informational") section is done only when confirmed (a `confirmed:<key>` signal), so a
 *  fresh/cleared plan shows it as in-progress rather than ✓ (#664). */
export function stageDone(section: BlueprintStage, signals: PlanSignals): { done: boolean; fraction: number } {
  if (signals[skippedSignal(section.key)] === true) return { done: true, fraction: 1 };
  if (section.gateRule) return evalGate(section.gateRule, signals);
  const ok = signals[confirmedSignal(section.key)] === true;
  return { done: ok, fraction: ok ? 1 : 0 };
}

/** Whether a section was resolved by a deliberate user SKIP (vs genuinely completed) — drives the
 *  distinct "skipped" rendering. (#921) */
export function stageSkipped(section: BlueprintStage, signals: PlanSignals): boolean {
  return signals[skippedSignal(section.key)] === true;
}

/** A dependency is satisfied when the blueprint omits it, it's disabled, it's N/A, or
 *  its own gate is complete. Mirrors the registry's dep rule, but over blueprint data. */
function depSatisfied(depKey: string, byKey: Record<string, BlueprintStage>, signals: PlanSignals): boolean {
  const dep = byKey[depKey];
  if (!dep) return true;        // this blueprint doesn't include the dep
  if (!dep.enabled) return true;
  if (dep.optional) return true;        // optional deps never block dependents (#676)
  if (!gateApplies(dep.appliesWhen, signals)) return true;
  return stageDone(dep, signals).done;
}

/**
 * Resolve a section's render status + bar fill from blueprint data alone: its
 * applicability rule, its declarative gate, and its (included, enabled) dependencies.
 */
export function stageStatus(
  section: BlueprintStage,
  sections: BlueprintStage[],
  signals: PlanSignals,
): { status: StageRenderStatus; fraction: number } {
  // An optional section is always shown (it bypasses appliesWhen) — it's just never
  // required; non-optional sections still go N/A when their applicability rule fails (#676).
  if (!section.optional && !gateApplies(section.appliesWhen, signals)) return { status: "na", fraction: 0 };
  const g = stageDone(section, signals);
  if (g.done) return { status: "complete", fraction: 1 };
  const byKey: Record<string, BlueprintStage> = Object.fromEntries(sections.map((s) => [s.key, s]));
  const locked = (section.deps || []).some((d) => !depSatisfied(d, byKey, signals));
  return { status: locked ? "locked" : "in-progress", fraction: g.fraction };
}

/** The enabled sections of a blueprint, in their declared order. */
export function enabledStages(sections: BlueprintStage[]): BlueprintStage[] {
  return sections.filter((s) => s.enabled);
}

/** Whether every enabled, applicable section is resolved — the triage readiness gate. An OPTIONAL
 *  section must be DECIDED (completed or user-skipped) just like a required one; a user-skip marks
 *  it done (#921). This is what lets the user, not the app, decide whether to skip an optional
 *  stage — the plan isn't "complete" until each enabled optional stage has been addressed. */
export function planStagesComplete(sections: BlueprintStage[], signals: PlanSignals): boolean {
  return enabledStages(sections).every((s) => {
    const { status } = stageStatus(s, sections, signals);
    return status === "complete" || status === "na";
  });
}

/**
 * The current ("reached") section: the first enabled + applicable section that is
 * in progress. When all are complete it falls back to the last enabled + applicable
 * one. Drives which pipelines' second screens render.
 */
export function currentStage(sections: BlueprintStage[], signals: PlanSignals): BlueprintStage | undefined {
  // The flow STOPS on an optional stage too, so the USER decides whether to do or skip it (#921) —
  // a skipped optional section is `stageDone` ⇒ not "in-progress", so the frontier advances past
  // it. Optional sections bypass `appliesWhen` (always shown), matching `stageStatus`.
  const applicable = enabledStages(sections).filter((s) => s.optional || gateApplies(s.appliesWhen, signals));
  const active = applicable.find((s) => stageStatus(s, sections, signals).status === "in-progress");
  return active ?? applicable[applicable.length - 1];
}

/**
 * Every enabled section that is not yet complete, in section order, each tagged with
 * its status and the section's own gate description as the reason. Fully blueprint-
 * driven — including unknown / cloud-distributed sections — so adding or reordering a
 * section flows through here with nothing hardcoded per stage. Powers the feedback
 * shown when the user clicks a locked Triage button.
 */
export function incompleteStages(sections: BlueprintStage[], signals: PlanSignals): IncompleteStage[] {
  const out: IncompleteStage[] = [];
  for (const s of enabledStages(sections)) {
    const { status } = stageStatus(s, sections, signals);
    if (status === "complete" || status === "na") continue;
    out.push({ key: s.key, name: s.name, reason: s.gate, status });
  }
  return out;
}

// ── Blueprint/template-change detection (#827/#1296) ──────────────────────────
// The context signature (planner/workspace.rs `context_signature`) is `v{TEMPLATE_VERSION}|
// repos|kb|stages`. Its FIRST `|`-delimited field is the blueprint/planner-template version;
// the rest is per-project SETUP (linked repos, KB blocks, enabled stages). A genuine
// "the blueprint has changed" event — the only thing that should auto-open the destructive
// BlueprintUpdateModal — is a change to that version field. Mere setup tweaks (link a repo,
// toggle a KB block, enable/disable a stage) change the later fields and drive only the quiet
// "context updated · refresh" badge, NOT the modal (#1296).

/** The blueprint/planner-template version component of a context signature (everything before
 *  the first `|`), or "" when the signature is empty/absent. */
export function signatureTemplateVersion(sig: string | null | undefined): string {
  if (!sig) return "";
  const bar = sig.indexOf("|");
  return bar === -1 ? sig : sig.slice(0, bar);
}

/** True only when two non-empty signatures carry DIFFERENT template-version prefixes — i.e. the
 *  blueprint/planner template was genuinely updated, not just the linked repos / KB / stages. */
export function blueprintTemplateChanged(currentSig: string | null | undefined, baselineSig: string | null | undefined): boolean {
  const cur = signatureTemplateVersion(currentSig);
  const base = signatureTemplateVersion(baselineSig);
  return !!cur && !!base && cur !== base;
}

/**
 * Whether the destructive "this project's blueprint has changed" modal should AUTO-open (#1296).
 * Gated on a true template-version mismatch (`blueprintTemplateChanged`) — never on benign setup
 * tweaks — plus an existing plan to protect, and the once-per-open `alreadyShown` guard.
 */
export function shouldAutoOpenBlueprintModal(args: {
  currentSig: string | null | undefined;
  baselineSig: string | null | undefined;
  hasExistingPlan: boolean;
  alreadyShown: boolean;
}): boolean {
  return blueprintTemplateChanged(args.currentSig, args.baselineSig)
    && args.hasExistingPlan
    && !args.alreadyShown;
}

runtime.features/planner/stages/blueprintTypes.t:
// Blueprint model TYPES (#513/#514, split out #2148): the pure type surface behind the
// Blueprints page — the substeps, the section/stage defs, the Blueprint shape, and the
// status result types. No runtime data or logic; the built-in library lives in
// blueprintBuiltins.ts and the pure helpers in blueprintStages.ts (both re-exported by
// the ./blueprints barrel).

import { type ClassificationSignals } from "./classification";
import { type StageGate, type Requirement } from "./stageGate";
import { type AgentFlow } from "../fleet/agentFlow";
// Type-only cross-feature import (allowed by the #1545 boundary): the blueprint team (#2450)
// reuses the org feature's graph shape rather than redeclaring it.
import type { Position, Relationship } from "@/features/teams";

// ── Substeps ─────────────────────────────────────────────────────────────────
// A discrete step WITHIN a stage. The conductor injects ONE substep's prompt at a time and
// advances when its artifact is written + confirmed — incremental, instead of front-loading
// the whole stage's instructions. A `loop` substep repeats once per dynamic item discovered
// during the stage (the feature workshop), so the conductor drives "one feature at a time".
export type SubStepLoop = "features" | "repos" | "topics";
export interface SubStep {
  /** Canonical key / artifact stem (e.g. "goal" → goal.md). For a loop, the loop's id. */
  key: string;
  label: string;
  /** Injected into the session when this substep becomes active. Plan-only — never describes
   *  publishing (the user owns that). */
  prompt: string;
  /** Human "done when…"; absent ⇒ informational (no gate of its own). */
  gate?: string;
  /** Repeat once per dynamic item (a feature, a repo). Absent ⇒ a single static substep. */
  loop?: SubStepLoop;
}

// ── Dynamic-blueprint additions (#1854 Phase a) ──────────────────────────────
// The first slice of the dynamic-blueprints epic: a stage can adapt its prompt to the DRIVING
// MODEL and can carry ARCHETYPE SEED CONTENT. Both are optional and additive — a stage without
// them behaves exactly as before (its single `prompt`, no seed).

/** A model CAPABILITY tier — the axis model-variant prompts key on (#1854 Phase a). Deliberately
 *  keyed by *capability*, not by a vendor model id, because blueprints are WAN-distributable and
 *  must not couple to a specific model/provider (they run on any {@link LlmProvider} via the
 *  bsc-agent "run on any model" track, #1078):
 *   - `frontier` — top frontier models (Claude Opus/Sonnet, GPT-4-class). The default open-ended
 *     prompt (the base `prompt`) is already written for this tier, so an explicit variant is only
 *     needed to override it.
 *   - `standard` — mid-capability hosted models (Haiku-class, smaller hosted models).
 *   - `local`    — weak local models. The headline payoff: a tight, schema-shaped, more-explicit
 *     directive prompt that lets a weak model plan reliably.
 *  A tier with no variant defined falls back to the base `prompt` (see {@link resolveStagePrompt}). */
export type ModelCapabilityTier = "frontier" | "standard" | "local";

/** Archetype seed content for a stage (#1854 Phase a) — starter content the stage can offer when it
 *  opens (e.g. a "twitter clone" archetype → a starter feature set for the Features stage). Additive:
 *  a stage with no `seed` behaves as today. Seeds; the planner + user still shape the final artifact. */
export interface StageSeed {
  /** The archetype this seed represents (a descriptive slug, e.g. "twitter-clone"). */
  archetype?: string;
  /** The starter content, as markdown — offered as an injectable option when the stage is active. */
  content: string;
}

// ── Sections (the canonical planning stages) ─────────────────────────────────

/** One discovery-checklist dimension. The editor-presentation fields (`icon`/`hue`/`blurb`)
 *  are present only for the dimensions that double as add-stage palette kinds (#1603); plain
 *  checklist dimensions carry just `key` + `title`. */
export interface DimensionMeta {
  key: string;
  title: string;
  /** Material/Lucide icon name (the editor `<Ic>` glyph). */
  icon?: string;
  /** Accent hue (oklch) for the palette card. */
  hue?: number;
  blurb?: string;
}

export interface SectionDef {
  name: string;
  /** Unicode symbol rendered as text in the focused-pane stepper (`focusedPlan.ts`). */
  glyph: string;
  /** Material/Lucide icon name for the editor/bar `<Ic>` component (#1603 — the editor
   *  presentation metadata, single-sourced here from the stage's own JSON). */
  icon: string;
  /** Accent hue (oklch) for the stage's editor/palette card (#1603). */
  hue: number;
  /** Human-readable gate description, shown in the editor and the readiness feedback. */
  gate: string;
  deps: string[];
  blurb: string;
  prompt: string;
  /** Model-variant prompts (#1854 Phase a) — per {@link ModelCapabilityTier} overrides of `prompt`,
   *  so a stage adapts its instructions to the DRIVING model (a tight, schema-shaped prompt for a
   *  weak `local` model alongside the open-ended default). Absent tier ⇒ the base `prompt` is used
   *  (resolved via {@link resolveStagePrompt}); the whole field absent ⇒ today's single-prompt
   *  behavior. Reference-by-tier; unknown tiers are simply ignored. */
  promptVariants?: Partial<Record<ModelCapabilityTier, string>>;
  /** Archetype seed content (#1854 Phase a) — starter content this stage offers when active (e.g. a
   *  starter feature set for a known archetype). Absent ⇒ no seed (today's behavior). */
  seed?: StageSeed;
  /** UI stage only (#604): the self-contained instruction the file-intake "Route" action injects
   *  into the planner to read the staged design files and route each to the right repo. Carried as
   *  stage DATA (like `prompt`) so it isn't hardcoded in the frontend. Absent ⇒ no route prompt. */
  routePrompt?: string;
  /** Declarative completion gate (#…) — the DATA that decides this section's
   *  done-ness. Carried on every section instance so a section is fully serializable
   *  and distributable; the app evaluates it via {@link evalGate}. Absent ⇒ the
   *  section is informational (vacuously complete). */
  gateRule?: StageGate;
  /** Optional applicability rule (e.g. UI only when the project needs a UI). Absent ⇒
   *  the section always applies. */
  appliesWhen?: Requirement;
  /** Declarative "skippable RIGHT NOW" rule (#2854) — the same {@link Requirement} shape as
   *  {@link appliesWhen}/gateRule, evaluated against the live signal bag, that makes a section's
   *  Skip control appear. It expresses the "empty ⇒ skippable, populated ⇒ required" pattern
   *  WITHOUT the stage disappearing (unlike `appliesWhen`, which drops it entirely): e.g. Features
   *  carries `{ signal: "featuresDefined", target: 0, op: "==" }`, so an empty Features stage is
   *  skippable but one with content is required. Absent ⇒ not skippable on its own (only an
   *  {@link optional} section or gate-override offers Skip). Drives `Stage.skippable`. */
  skipWhen?: Requirement;
  /** An OPTIONAL section is shown but never required: it doesn't block plan completion or
   *  downstream dependents, and it's off the critical path (currentStage skips it) — the
   *  user can fill it or skip it (#676). Equivalent to an always-passing {@link skipWhen}. */
  optional?: boolean;
  /** Context stage only (#1019): the baseline REQUIRED topics this section seeds into the project's
   *  dynamic context manifest (plan.db) when first adopted. The planner then adjusts the set with
   *  `bsc-plan context require/unrequire`. Absent ⇒ the universal {@link DISCOVERY_BASELINE}. */
  requires?: string[];
  /** Discovery stage only (#1603): the checklist dimensions, carried as data so the editor's
   *  add-stage palette + the dimension vocabulary (`KNOWN_DIMENSIONS`) single-source from here. */
  dimensions?: DimensionMeta[];
  /** Output disposition (#609) — what happens to this stage's artifact (a key into
   *  DISPOSITIONS: plan-file / issues / milestones / skill-index / knowledge / scratch).
   *  Editor metadata; the runtime doesn't read it. Absent ⇒ defaultDisposition(key). */
  output?: string;
  /** Attached skills/knowledge (#636) — library item ids (KB blocks or Skills) injected
   *  into the agent's context for this stage. Resolved at planning + fleet launch
   *  (slice b). Reference-by-id; unresolved ids surface a warning. */
  skills?: string[];
  /** Attached MCP servers (#897) — server NAMES (the portable ref, matching the catalog +
   *  `<mcp_assign>`), scoped to the project at launch so the planner/fleet can call them.
   *  Kept SEPARATE from `skills`: MCP servers are tools (research/analysis/grading), skills are
   *  knowledge. Reference-by-name; an unresolved name surfaces a warning in the editor. */
  mcp?: string[];
  /** Ordered substeps the conductor injects one at a time (#…). Absent ⇒ the stage is driven
   *  by a single prompt (its `prompt`). Pipeline `triggerTarget`s reference these by `key`. */
  substeps?: SubStep[];
  /** The planner-facing directive prose (#1462) — the single source of truth, shared byte-for-byte
   *  with the Rust `stage_directive`, read from this stage's `prompts/stages/<id>.json`. Only the
   *  duplicated stages carry one; stages without it use the generic Rust fallback. */
  directive?: string;
  /** Reserved (populated by #1395) — the classification signals that gate this stage's applicability,
   *  and its ordering tier. Typed now so #1395 fills them without re-churning files; unset today. */
  signals?: ClassificationSignals;
  phase?: "discover" | "decide" | "generate";
}

export interface BlueprintStage extends SectionDef {
  uid: string;
  key: string;
  enabled: boolean;
  expanded: boolean;
}

/** Where a blueprint came from (#609) — drives the card's origin tag. */
export type BlueprintOrigin = "built-in" | "local" | "forked" | "imported";

/** Whether a blueprint starts from a pitch (create) or runs against existing repos
 *  (operate) — selects the planner intro at launch. */
export type BlueprintMode = "create" | "operate";

/** Gist link state for a blueprint (#609) — the publish/sync state-machine. Slice 5
 *  populates this; the Library card reads it for the sync badge. Absent ⇒ local-only. */
export interface BlueprintGist {
  state: "local" | "dirty" | "synced" | "forked";
  /** Whether an upstream update is available (forked blueprints). */
  behind?: boolean;
  rev?: string;
  author?: string;
  id?: string;
  url?: string;
  public?: boolean;
  /** The upstream gist's `updated_at` recorded at import/sync. Compared against the gist's CURRENT
   *  `updated_at` on the import-from-gist page to detect an available update (#955). */
  updatedAt?: string;
}

/** Fleet POLICY a blueprint declares (#1854 Phase b) — the default per-stream {@link AgentProfile}
 *  and {@link AgentFlow} the planner instantiates when it generates this project type's fleet. A
 *  COMPOSED typed sub-model (epic discipline #1: not N flat top-level fields), carrying only the
 *  *recipe/policy* — the DEFAULTS — while the concrete per-stream config stays planner-GENERATED
 *  per-project (discipline #2: static template vs generation policy). Resolution precedence is
 *  stream-declared → this policy → the hard launch-time default (see `resolveStreamProfile` /
 *  `resolveStreamFlow` in `../fleet/fleetPolicy`). Both fields optional ⇒ when unset, today's
 *  launch-time defaults apply, byte-for-byte.
 *
 *  Trust boundary (discipline #3): a blueprint only *seeds* the launch default here — the role
 *  gate (#219) still caps the session. The request-vs-cap permission POSTURE is Phase (c), out of
 *  scope for this sub-model. */
export interface FleetPolicy {
  /** Default {@link AgentProfile} id for a WORKER stream that doesn't pin its own `profile` (#289).
   *  A reference-by-id; an unknown id just falls through to the role default at launch. Applies to
   *  worker streams only — never the director, which keeps its role's read-only review profile. */
  profile?: string;
  /** Default {@link AgentFlow} (autonomy + push + trigger + gate) for a stream that doesn't declare
   *  its own `flow` (#297). Absent ⇒ the launch path applies {@link DEFAULT_FLOW}. */
  flow?: AgentFlow;
}

/** The TEAM a blueprint carries (#2450) — an embedded org configuration: positions (personas
 *  referenced by id — personas stay a global library) wired by relationships, with the canvas
 *  layout coords on each position. The same graph shape the `bsc org` store holds, MINUS the
 *  library identity fields (`id`/`name`/`blurb`/`builtin`) — the blueprint itself is the identity.
 *
 *  FORK-ON-ATTACH: authoring starts by DEEP-COPYING a library org (or blank) into
 *  `blueprint.team` (see `forkTeamFromOrg`); the `bsc org` store remains the archetype library.
 *  Editing a blueprint's team never mutates the library org and vice versa — reproducibility of
 *  the blueprint artifact wins. Persisted inside the blueprint's JSON (the `bsc blueprint` store
 *  is verbatim JSON), so export/import carries it automatically. Optional — a blueprint without
 *  `team` behaves exactly as before; plan-time consumption (seeding fleet streams from the team)
 *  is a deliberate follow-up, not this field's contract. */
export interface BlueprintTeam {
  positions: Position[];
  relationships: Relationship[];
}

/** The UI KIT a blueprint pins (#2465) — a LOCKFILE entry, deliberately the opposite of `team`:
 *  the kit is REFERENCED, never embedded, because kits are immutable versioned artifacts shared
 *  across blueprints (one copy in the global store, `~/.base-studio-code/kits/<id>/<version>/`,
 *  no matter how many blueprints pin it). Exact pins only — no version ranges (reproducibility).
 *
 *  `hash` is the sha256 (lowercase hex) of the kit artifact's bytes, verified BEFORE a fetched
 *  kit is accepted into the store (resolve flow, `uiKitPin.ts`); `source` is the typed-gist URL
 *  to fetch from when `id@version` isn't in the local store yet. A new blueprint default-pins the
 *  packaged `bsc/react-ui` kit ({@link Blueprint.uiKit} set in `addBlueprint`); a blueprint
 *  without a pin behaves exactly as before. */
export interface BlueprintUiKit {
  /** Publisher-scoped kit id (e.g. `"bsc/react-ui"`). */
  id: string;
  /** Exact semver of the pinned artifact (immutable once published). */
  version: string;
  /** sha256 (lowercase hex) of the artifact bytes. */
  hash: string;
  /** Typed-gist URL to fetch from when the id@version is missing locally. */
  source?: string;
  /** The kit THEME paired with the pin (#2489) — a `bsc ui theme` id. Absent ⇒ `"default"`. An ID,
   *  never the vars: the theme resolves through `bsc ui theme get` at EMISSION time
   *  (`bsc ui emit-css --theme <id>` → the generated app's tokens.css + theme.css), so
   *  designer-authored themes apply the moment they exist. This is the blueprint-level default;
   *  the planned application's actual pair is recorded per project in plan.db (`bsc plan ui`). */
  themeId?: string;
}

/** The SOUND KIT a blueprint pins (#3372, epic #3071 phase 4) — the sounds twin of
 *  {@link BlueprintUiKit}, deliberately the SAME lockfile discipline: the kit is REFERENCED, never
 *  embedded, against the global versioned sound-kit release store
 *  (`~/.base-studio-code/sound-kits/<id>/<version>/`, the Rust `bsc sound release` CLI, #3371).
 *  Exact pins only — no ranges (reproducibility). A new blueprint default-pins the packaged
 *  `bsc/signal` kit ({@link Blueprint.soundKit} set in `addBlueprint`), which resolves against the
 *  store's embedded fallback and so needs no fetch.
 *
 *  NO `themeId` twin: a theme restyles a component kit's tokens, and a sound kit has no token
 *  contract to restyle — its cues ARE the palette. Adding a dead field "for symmetry" would invent
 *  a knob nothing reads. */
export interface BlueprintSoundKit {
  /** Publisher-scoped kit id (e.g. `"bsc/signal"`). */
  id: string;
  /** Exact semver of the pinned artifact (immutable once published). */
  version: string;
  /** sha256 (lowercase hex) of the artifact bytes — the canonical SoundKit object, NOT a wrapper. */
  hash: string;
  /** Typed-gist URL to fetch from when the id@version is missing locally. */
  source?: string;
}

/** A blueprint's DESIGN contribution (#2646, epic #2606) — the categorical dimensions it introduces
 *  that need design-token backing (a `simulation` node-kind, say), plus an optional theme by reference.
 *  Downloading a blueprint RECONCILES this against the local design contract: categories the contract
 *  doesn't define are surfaced (a dedicated confirm-list, 5b) and filled by the generator (#2636), so a
 *  shared blueprint brings its look with NO holes. Deliberately the opposite of embedding: categories
 *  are KEYS (the generator derives on-brand colours), `theme` is a `bsc ui theme` id (never the vars). */
export interface BlueprintDesign {
  /** Categorical keys the blueprint introduces — reconciled against the contract's graph-category group;
   *  any the contract doesn't define is a gap the generator fills (5b). */
  categories?: string[];
  /** Optional theme by reference — a `bsc ui theme` id (mirrors the uiKit pin's `themeId`; absent ⇒ default). */
  theme?: string;
}

export interface Blueprint {
  id: string;
  name: string;
  desc: string;
  sections: BlueprintStage[];
  /** The curated FEATURE LIST this blueprint seeds (#3785) — the raw `features` section content
   *  (`features.md`) captured when a completed project is promoted (`generateBlueprint`). A blueprint
   *  is a goal/domain planning ROUTE (its `sections`/stages) PLUS the features that route builds
   *  (this). Absent ⇒ no seeded features (the blueprint is a bare route); applying one with features
   *  seeds them into the new project's Features stage. */
  features?: string;
  /** Display + provenance metadata (#609). All optional — the Library derives sensible
   *  fallbacks (icon from the name, hue from the id, origin "local", local-only gist). */
  icon?: string;
  /** Accent hue (oklch) for the card/editor icon. */
  h?: number;
  origin?: BlueprintOrigin;
  tags?: string[];
  gist?: BlueprintGist;
  /** How many projects this blueprint has seeded. */
  uses?: number;
  updatedAt?: string;
  /** Blueprint-wide attached skills/knowledge (#636) — applied across every stage,
   *  in addition to each section's own `skills`. Library item ids. */
  skills?: string[];
  /** Blueprint-wide attached MCP servers (#897) — applied across every stage, in addition to
   *  each section's own `mcp`. Server NAMES (the portable ref). */
  mcp?: string[];
  /** The component KIT (#2277) an app seeded from this blueprint is built on — a `bsc ui` kit id
   *  (e.g. `"react-ui"`). Recording it makes every project seeded here a CONSUMER of that kit, so a kit
   *  change fans out to it (the `kit_usage` consumer index self-fills at planning). Absent ⇒ the blueprint
   *  isn't tied to a shared kit (an authoring blueprint, or one that operates on a repo's own UI). */
  kit?: string;
  /** Fleet policy (#1854 Phase b) — the DEFAULT per-stream profile + flow the planner instantiates
   *  when it generates this project type's fleet. A composed sub-model; see {@link FleetPolicy}.
   *  Absent ⇒ today's launch-time defaults apply (byte-identical). */
  fleetPolicy?: FleetPolicy;
  /** The blueprint's own TEAM (#2450) — an embedded org configuration forked from the org library
   *  (or authored blank). A composed sub-model; see {@link BlueprintTeam}. Absent ⇒ no team
   *  authored (today's behavior, byte-identical everywhere). */
  team?: BlueprintTeam;
  /** The UI kit this blueprint pins (#2465) — a lockfile entry referencing an immutable
   *  `id@version` artifact in the global kit store; see {@link BlueprintUiKit}. Absent ⇒ no pin
   *  (existing blueprints are unaffected); a NEW blueprint default-pins the packaged kit. */
  uiKit?: BlueprintUiKit;
  /** The SOUND kit this blueprint pins (#3372) — the same lockfile entry one pillar over, against
   *  the versioned sound-kit release store; see {@link BlueprintSoundKit}. Absent ⇒ no pin
   *  (existing blueprints are unaffected); a NEW blueprint default-pins the packaged `bsc/signal`. */
  soundKit?: BlueprintSoundKit;
  /** The blueprint's DESIGN contribution (#2646) — the categorical keys it introduces + an optional
   *  theme ref; reconciled against the local design contract on download. Absent ⇒ nothing to reconcile
   *  (existing blueprints unaffected). See {@link BlueprintDesign}. */
  design?: BlueprintDesign;
  /** Create (from a pitch) vs operate (against existing repos). Absent ⇒ create. */
  mode?: BlueprintMode;
  /** Catalog metadata: a one-line catalog pitch, the audience it serves, and the share visibility
   *  (used by the gist share/import flow). `tags` doubles as the "best for" catalog tags. */
  pitch?: string;
  audience?: string;
  visibility?: "local" | "private-gist" | "catalog";
}

/** The JSON shape of a built-in blueprint definition (stages/blueprints/*.json): blueprint
 *  metadata + an ordered list of section KEYS (chaining to stages/sections/*.json). The keys
 *  resolve to full section instances via mkStage at load — no blueprint data lives in TS. */
export interface BlueprintDef extends Omit<Blueprint, "sections"> {
  /** Display order within the built-in library. */
  order?: number;
  /** Ordered section refs: a key into STAGE_DEFS + an optional per-blueprint `optional` flag. */
  sections: { key: string; optional?: boolean }[];
}

export interface SectionStatus { locked: boolean; unmet: string[]; satisfied: boolean }

/** Render status of a blueprint section. `na` = not applicable to this project. */
export type StageRenderStatus = "locked" | "in-progress" | "complete" | "na";

/** A blueprint section that isn't satisfied yet — what the user still has to finish. */
export interface IncompleteStage {
  key: string;
  /** The section's display name, straight from the blueprint. */
  name: string;
  /** The section's own gate description (`gate`) — the human "what's left". */
  reason: string;
  /** Locked behind an unfinished dependency vs. simply in progress. */
  status: "locked" | "in-progress";
}

runtime.features/planner/stages/classification.t:
// Discovery classification signal types (#1395).
//
// The Discovery phase characterizes a project into a small set of SIGNALS. These types describe the
// shape of that signal set; `blueprints.ts` carries a `ClassificationSignals` on a blueprint. Pure
// (no React / store / Tauri).

export type Lifecycle = "greenfield" | "transform" | "harden" | "maintain";
export type Workspace = "ui" | "cli" | "api" | "service" | "library" | "data";
export type ServiceTopology = "none" | "split" | "combine";
export type DeployKind = "none" | "static" | "serverless" | "container" | "service";

/** Discovery's classification output (#1395) — the project's lifecycle, surfaces, and a few counts.
 *  Planner-set as it learns, plus counts derived from plan state. Carried on a blueprint. */
export interface ClassificationSignals {
  lifecycle: Lifecycle;
  /** ⊆ {ui, cli, api, service, library, data} — what the project exposes. */
  surfaces: Workspace[];
  provenance: "new" | "existing";
  migration: boolean;
  dataModel: boolean;
  serviceTopology: ServiceTopology;
  deploy: DeployKind;
  compliance: boolean;
  // derived from plan state:
  featureCount: number;
  repoCount: number;
  streamCount: number;
}

runtime.features/planner/stages/confirmReconcile:
// Confirm reconciliation (#2256) — the PURE decision behind the poll's durable-confirmation sync.
// plan.db is the durable store of which stages the user confirmed (each with a content fingerprint);
// the app-state mirrors it. Every poll tick this decides three disjoint actions from the plan.db rows,
// the live section content, and the current store set. Pure + serializable → unit-testable without
// Tauri; the poll just applies the result.

import { hashString } from "@/shared/lib/core/hashString";

/** One durable confirmation row from `bsc plan confirm list` — a stage + its confirm-time fingerprint. */
export interface ConfirmRow {
  stage: string;
  fingerprint: string;
}

export interface ConfirmReconcile {
  /** Durably-confirmed stages whose content is UNCHANGED but missing from the store — restore them
   *  (rehydrate on revisit). Applied via `markStageConfirmedLocal` (no plan.db echo). */
  rehydrate: string[];
  /** Confirmed stages whose content CHANGED since confirm — reset just these (the per-stage reset).
   *  Applied via `unconfirmPlanStage` (drops store + plan.db). */
  reset: string[];
  /** Store confirmations with no plan.db row yet — forward-migrate them into plan.db (one-time, when
   *  plan.db has none and we haven't migrated this project). */
  migrate: string[];
}

/**
 * Decide the confirm reconciliation for one poll tick.
 *
 * - When plan.db has NO rows but the store does and this project hasn't been migrated → forward-migrate
 *   the store's confirmations into plan.db (the pre-#2256 app-state-only set becomes durable).
 * - Otherwise plan.db is authoritative: a row whose live content fingerprint MATCHES is rehydrated into
 *   the store (if absent); a MISMATCH means the stage's content changed → reset just that stage.
 */
export function reconcileConfirmations(
  rows: ConfirmRow[],
  liveSections: Record<string, string>,
  storeConfirmed: Set<string>,
  migrated: boolean,
): ConfirmReconcile {
  if (rows.length === 0 && storeConfirmed.size > 0 && !migrated) {
    return { rehydrate: [], reset: [], migrate: [...storeConfirmed] };
  }
  const rehydrate: string[] = [];
  const reset: string[] = [];
  for (const { stage, fingerprint } of rows) {
    if (hashString(liveSections[stage] ?? "") === fingerprint) {
      if (!storeConfirmed.has(stage)) rehydrate.push(stage);
    } else {
      reset.push(stage);
    }
  }
  return { rehydrate, reset, migrate: [] };
}

export interface SkipReconcile {
  /** Durably-skipped stages missing from the store — restore them (rehydrate on revisit). */
  rehydrate: string[];
  /** Store skips with no plan.db row yet — forward-migrate them into plan.db (one-time). */
  migrate: string[];
}

/**
 * Decide the skipped-stage reconciliation for one poll tick (#2267). Simpler than confirmations: a
 * skip is a plain decision (no fingerprint / reset-on-change), so plan.db just needs to be the durable
 * mirror. When plan.db has NO rows but the store does and this project hasn't been migrated → forward-
 * migrate the store's skips into plan.db; otherwise restore any durable skip missing from the store.
 */
export function reconcileSkips(rows: string[], storeSkipped: Set<string>, migrated: boolean): SkipReconcile {
  if (rows.length === 0 && storeSkipped.size > 0 && !migrated) {
    return { rehydrate: [], migrate: [...storeSkipped] };
  }
  return { rehydrate: rows.filter((s) => !storeSkipped.has(s)), migrate: [] };
}

/** One section as the focused-plan derivation sees it — key + draft/confirm state. */
export interface SectionState {
  k: string;
  state: "confirmed" | "drafted" | "pending";
}

/**
 * Stages to auto-confirm when a PUBLISHED project is reopened with NO durable confirmations yet
 * (#2259 backfill for pre-#2256 projects): every **drafted** section (content present, not yet
 * confirmed). A published project's discovery sections were all confirmed to reach publish, so
 * restoring them avoids a pointless reconfirm pass on reopen. The CALLER gates this to published
 * projects with an empty confirmed set — this pure helper just picks the drafted sections. `pending`
 * (no content) sections are never backfilled (nothing was confirmed there).
 */
export function stagesToBackfill(sections: SectionState[], alreadyConfirmed: Set<string>): string[] {
  return sections.filter((s) => s.state === "drafted" && !alreadyConfirmed.has(s.k)).map((s) => s.k);
}

runtime.features/planner/stages/focusedPlan.ts:
// Focused planner pane (#652) — the pure model behind the one-stage-at-a-time right
// pane. It wraps the EXISTING blueprint/signal/gate logic (stageStatus / currentStage
// / evalGate) into a navigable "stage" view: which stages are visible, each one's status
// (complete / active / locked / upcoming), the gate pill, and the advance-bar action.
// Pure + serializable so it's fully unit-testable; no React/Tauri.

import {
  enabledStages, currentStage, stageStatus, stageSkipped,
  type BlueprintStage,
} from "./blueprints";
import { evalGate, evalRequirement, gateReasons, type PlanSignals } from "./stageGate";
import type { StagePrompt } from "../session/plannerConductor";

// "complete" = done IN sequence (at/behind the current position); "ahead" = done OUT of
// sequence (gate met past the current position — "banked"); "skipped" = an OPTIONAL section
// the USER deliberately skipped (#921 — the flow now STOPS on every optional stage; the only way
// past one without completing it is a user skip). The rail renders each distinctly so a future
// stage finishing early / a deliberately skipped stage don't read as in-order progress or as a
// not-yet-reached stage (#668).
export type StageStatus = "complete" | "ahead" | "active" | "skipped" | "locked" | "upcoming";

export interface Stage {
  key: string;
  name: string;
  glyph: string;
  blurb: string;
  /** The section's human gate description. */
  gate: string;
  index: number;
  total: number;
  status: StageStatus;
  /** Gate fill 0..1 for the in-progress fraction. */
  fraction: number;
  /** An optional stage — shown but never required (#676). */
  optional?: boolean;
  /** Whether the stage is SKIPPABLE right now (#2854): intrinsically `optional`, OR its declarative
   *  `skipWhen` rule passes against the live signals (e.g. an empty Features stage). Drives whether
   *  the footer renders a Skip control at all — a required stage (no rule) shows none, not a disabled
   *  ghost. Absent ⇒ not skippable. */
  skippable?: boolean;
  /** The Repos stage folds Deploy in as a "ship" substep (#1383) — drives the combined body. */
  ship?: boolean;
  /** The Structure stage folds Permissions in as a "fleet" substep → the "Streams" stage — drives
   *  the combined body (graph + coordination + permissions). */
  fleet?: boolean;
  /** The still-unmet gate requirements (label + progress detail) — drives the "why is this
   *  blocked" feedback on the gate pill (#805). Empty once the gate passes. */
  unmet?: { label: string; detail?: string }[];
}

/**
 * The visible stage list: enabled, non-N/A sections in declared order, each tagged with
 * its status — complete (gate passed), active (the current reached stage), locked (a
 * dependency is unmet), or upcoming (reachable but not yet current).
 */
export function stagesFrom(sections: BlueprintStage[], signals: PlanSignals): Stage[] {
  const current = currentStage(sections, signals);
  const visible = enabledStages(sections)
    .map((s) => ({ s, st: stageStatus(s, sections, signals) }))
    .filter(({ st }) => st.status !== "na");
  // The current position among visible stages; everything complete PAST it is "ahead".
  const activeIdx = current ? visible.findIndex(({ s }) => s.key === current.key) : visible.length;
  return visible.map(({ s, st }, i) => {
    let status: StageStatus;
    // A deliberately user-skipped optional stage reads as "skipped", not "complete" — even though
    // it counts as resolved for the frontier/gate (`stageDone`). Check this first (#921).
    if (stageSkipped(s, signals)) status = "skipped";
    else if (st.status === "complete") status = i > activeIdx ? "ahead" : "complete";
    else if (st.status === "locked") status = "locked";
    else status = current && s.key === current.key ? "active" : "upcoming";
    const unmet = gateReasons(s.gateRule, signals)
      .filter((r) => !r.pass)
      .map(({ label, detail }) => ({ label, detail }));
    // Skippable RIGHT NOW (#2854): intrinsically optional, or the declarative `skipWhen` rule passes
    // against the live signals (e.g. featuresDefined == 0). Drives whether the footer offers Skip.
    const skippable = s.optional === true || (s.skipWhen ? evalRequirement(s.skipWhen, signals).pass : false);
    return {
      key: s.key, name: s.name, glyph: s.glyph, blurb: s.blurb, gate: s.gate,
      index: i, total: visible.length, status, fraction: st.fraction, optional: s.optional, skippable, unmet,
      // #1383: the Repos stage folds Deploy in as a "ship" substep when a blueprint opts in — the
      // combined body renders the deploy block only then.
      ship: s.substeps?.some((ss) => ss.key === "ship"),
      fleet: s.substeps?.some((ss) => ss.key === "fleet"),
    };
  });
}

/**
 * The blueprint section for a stage, resolved BY KEY (#815). `stages` is a FILTERED subset of the
 * raw section list (disabled / not-applicable sections like `ui` are dropped by {@link stagesFrom}),
 * so indexing the raw sections with a stage index lands on the wrong section once any earlier one is
 * dropped. The conductor uses this to inject the *active stage's* prompt, not a neighbor's.
 */
export function sectionForStage<T extends { key: string }>(
  sections: T[], stage: { key: string } | undefined,
): T | undefined {
  return stage ? sections.find((s) => s.key === stage.key) : undefined;
}

export type ConnectorKind = "solid" | "partial" | "dashed" | "dim";

/** The rail connector AFTER node `i` (#668): solid traces the walked in-sequence path,
 *  partial leaves the current node, dashed reaches a banked-ahead node, dim otherwise. */
export function connectorKind(stages: Stage[], i: number): ConnectorKind {
  const role = stages[i]?.status;
  const next = stages[i + 1]?.status;
  // A banked-ahead node (done out of sequence) is reached by a dashed connector.
  if (role === "ahead" || next === "ahead") return "dashed";
  // The walked path is green UP TO the current node: every connector positioned BEFORE the
  // active node is solid — including the one leaving a skipped/optional section — so the
  // green leads INTO the current node, never out of it. Beyond the current node: dim (#668).
  const activeIdx = stages.findIndex((p) => p.status === "active");
  const frontier = activeIdx >= 0 ? activeIdx : stages.length;
  return i < frontier ? "solid" : "dim";
}

/** Index of the active stage (else the last) — what the selection auto-follows. */
export function activeIndex(stages: Stage[]): number {
  const a = stages.findIndex((p) => p.status === "active");
  return a >= 0 ? a : Math.max(0, stages.length - 1);
}

/** Clamp an index into [0, count-1] (0 when empty) — guards against a shrunk stage list
 *  after a blueprint switch / clear. */
export function clampIndex(i: number, count: number): number {
  if (count <= 0) return 0;
  return Math.min(Math.max(0, i), count - 1);
}

export type GatePill = "pass" | "wait";

/** Gate pill for a stage, from the declarative gate (#897 Phase 4c removed the legacy
 *  pipeline gate): "pass" once the stage's gateRule is satisfied, else "wait". */
export function gatePill(stage: Stage): GatePill {
  return stage.status === "complete" || stage.status === "ahead" ? "pass" : "wait";
}

/** Whether a stage has any GUIDANCE to reveal (#3257) — the gate's unmet requirements (while it's
 *  blocking) and/or a suggested next-step prompt. Drives whether the gate pill acts as a disclosure
 *  TOGGLE for the guidance card: with nothing to reveal the pill stays a plain status chip. */
export function hasStageGuidance(stage: Stage, pill: GatePill, prompt?: StagePrompt, onInject?: (text: string) => void): boolean {
  const showReqs = pill !== "pass" && (stage.unmet ?? []).length > 0;
  const showPrompt = !!prompt && !!onInject;
  return showReqs || showPrompt;
}

export type FooterKind = "back-to-current" | "jump-to-current" | "approve-continue" | "route-design" | "publish";

export interface FooterAction {
  kind: FooterKind;
  enabled: boolean;
  /** Whether this action KIND supports a Skip control — set by {@link footerAction} on the active-stage
   *  advance actions (approve-continue / route-design), never on navigation/publish. A marker only:
   *  {@link resolveFooter} decides whether Skip actually RENDERS (`skipEnabled`) from the live signals. */
  canSkip?: boolean;
  /** Whether the Skip control RENDERS as an actionable button (#2854): true only when the stage is
   *  skippable now (its `skipWhen` rule passes / it's intrinsically optional) OR the user enabled
   *  "allow gate override" (#1285). A required stage like Discovery shows NO Skip — not a disabled
   *  ghost (the #2533 always-visible-Skip behavior regressed into a greyed button beside "gate
   *  blocking…"). The footer renders Skip iff this is set. */
  skipEnabled?: boolean;
}

/**
 * The advance-bar's primary action, by where the selection sits relative to the active
 * stage. Browsing a future (locked) stage → back to current; a past stage → jump to
 * current; on the active stage → approve & continue (enabled when its gate is ready), or
 * publish when the whole plan is complete.
 *
 * `canSkip` marks the two active-stage advance actions (approve-continue, route-design) as
 * skip-ELIGIBLE — a marker, not a render decision. Whether Skip actually appears is decided later by
 * {@link resolveFooter} (`skipEnabled`) from the live signals: skippable stage or gate-override on.
 * Navigation and publish are never skip-eligible.
 */
export function footerAction(
  selectedIdx: number, activeIdx: number, planComplete: boolean, currentGateReady: boolean,
  routeDesign = false,
): FooterAction {
  if (selectedIdx > activeIdx) return { kind: "back-to-current", enabled: true };
  if (selectedIdx < activeIdx) return { kind: "jump-to-current", enabled: true };
  if (planComplete) return { kind: "publish", enabled: true };
  // #2121: the active UI stage whose design is missing or stale → the primary action ROUTES the
  // design (sync the skeleton + mark it current) instead of advancing. It's skip-eligible too —
  // routing and skipping are both valid choices — but resolveFooter still gates the actual Skip.
  if (routeDesign) return { kind: "route-design", enabled: true, canSkip: true };
  return { kind: "approve-continue", enabled: currentGateReady, canSkip: true };
}

/**
 * Resolve the final advance-bar action from the raw {@link footerAction}. Two independent axes:
 *
 * PRIMARY — a blocking "approve & continue" (gate not ready) lights up when `pendingCount > 0`:
 * there are drafted-but-unconfirmed sections and clicking confirms them (the one-click approval).
 * Otherwise the primary stays disabled ("gate blocking…").
 *
 * SKIP (#2854) — the Skip control RENDERS (`skipEnabled`) only when the KIND is skip-eligible
 * (`canSkip`) AND the active stage is skippable now (its `skipWhen` rule passes / it's intrinsically
 * optional) OR the user enabled gate override (#1285). A required stage (Discovery) shows NO Skip —
 * not a disabled ghost. When Skip renders it is always actionable, so there is no disabled state.
 *
 * Pure + unit-tested.
 */
export function resolveFooter(
  raw: FooterAction, pendingCount: number, allowOverride: boolean, skippable: boolean,
): FooterAction {
  // Skip renders only when its KIND is eligible AND the stage is skippable now (or override is on).
  const withSkip = raw.canSkip ? { ...raw, skipEnabled: skippable || allowOverride } : raw;
  // One-click confirm lights the blocking primary; nothing else force-enables it now.
  if (withSkip.kind !== "approve-continue" || withSkip.enabled) return withSkip;
  if (pendingCount > 0) return { ...withSkip, enabled: true };
  return withSkip;
}

/** Whether the active stage's gate is satisfied — enables "approve & continue". */
export function currentGateReady(sections: BlueprintStage[], signals: PlanSignals): boolean {
  const cur = currentStage(sections, signals);
  return !!cur && evalGate(cur.gateRule, signals).done;
}

/**
 * Whether the auto-complete-gates effect should confirm the active stage's pending sections (#1068):
 * the global flag is on, the planning autopilot is NOT driving (it owns confirmation then), and the
 * active stage actually has sections awaiting confirmation. The same "approve & continue" action the
 * user would click, minus the click — so it advances exactly the gates the manual path would.
 */
export function shouldAutoCompleteGate(autoOn: boolean, autopilotActive: boolean, pending: string[]): boolean {
  return autoOn && !autopilotActive && pending.length > 0;
}

// Map the live plan data into the normalized PlanStageState the stage gates read
// (#512). Pure + isolated from the giant Planning component so the categorization
// (which sections are "discovery" vs the structure anchor, core-topic confirmation)
// is unit-testable. The call site supplies the simpler primitives (repo/issue/fleet
// counts); this function owns the section categorization.

import { buildPlanStageState, type PlanStageState } from "./planStages";
import type { SectionState } from "../github/ghStructure";
import type { PlanSignals } from "./stageGate";

// Single-sourced from the Discovery stage data (`src-tauri/data/stages/discovery.json`, its
// `requires` array) so the baseline lives in ONE place — the same data file the planner prompt and
// gate read (#1591). Loaded directly via `import.meta.glob` (NOT through blueprints.ts STAGE_DEFS)
// to avoid a circular import.
const discoveryModules = import.meta.glob<{ default: { requires?: string[] } }>(
  "@data/stages/discovery.json",
  { eager: true },
);

/** The universal baseline context topics a project requires when nothing else seeds the manifest
 *  (#1019). A blueprint may seed a different set via its context section's `requires`; the planner
 *  then adjusts it with `bsc-plan context require/unrequire`. */
export const DISCOVERY_BASELINE: string[] = Object.values(discoveryModules)[0]?.default.requires ?? [];

// Data Model gate signals (#1446: the canonical Data Model lives in the project's DuckDB store,
// read/written via `bsc data model get` / `bsc data model set`). These boolean SIGNALS are derived
// from the live frontend SourceConfig (see `dataModelSignals` in lib/sourceGate.ts), NOT read back
// from that store — they track scan PROGRESS, while the model/scan themselves are persisted to
// DuckDB by the Source pane.
// Reader:  planner-plumbing (this file) — missing fields read as false
// Shape (all fields optional at the top level; absent ⇒ false):
// {
//   "sourceReachable": boolean,  // source system is reachable and has been inventoried
//   "modelInferred":   boolean,  // entities, fields, and identity key have been proposed
//   "schemaRefined":   boolean,  // user has confirmed / revised the proposed schema
//   "mappingComplete": boolean,  // field-by-field source→model mapping is complete
//   "loadVerified":    boolean   // load run has been verified against expectations
// }

export interface DerivePlanStageInput {
  /** Every surfaced plan section with its state (from the dynamic section model). */
  sections: { k: string; state: SectionState }[];
  /** The project's required context topics (#1019) — the dynamic required-set from plan.db. The
   *  Context gate (#1028) passes once every required topic's `context/<topic>.md` has been written. */
  discoveryRequired: string[];
  repoCount: number;
  issueCount: number;
  fleetStreams: number;
  fleetProfilesComplete: boolean;
  automationsAck: boolean;
  skillsAck: boolean;
  requiresUi: boolean;
  ui: { approved: number; total: number };
  /** The user routed dropped design files to the project — completes the UI stage without a
   *  screen-preview approval pass (#837). */
  uiRouted?: boolean;
  /** User-facing capabilities defined in the Features stage (each becomes a stream). */
  features: { count: number; allConfirmed: boolean };
  /** Libraries locked in the dependency manifest (#1111/#1191) — plan.db `deps` entry count. */
  dependencies?: { count: number };
  /** Whether a data migration source pipeline is active for this project. Absent ⇒ false. */
  migrationSourceEnabled?: boolean;
  /** Data Model progress signals derived from the live scan state (see the block comment above).
   *  Absent, or any absent field ⇒ false. */
  dataModelSignals?: DataModelSignals;
}

/**
 * The five Data Model progress booleans the source stage's gate reads. Derived from the live
 * `SourceConfig` scan state — NOT parsed from any file and NOT read back from the canonical Data
 * Model in DuckDB (#1446). Every field is optional; an absent field reads as false.
 *
 * `loadVerified` here is a Data Model signal (the load run was verified against expectations). It is
 * unrelated to any similarly-named store field — the dead `dataModels` store array that once shared
 * the name was removed in #3244.
 */
export interface DataModelSignals {
  sourceReachable?: boolean;
  modelInferred?: boolean;
  schemaRefined?: boolean;
  mappingComplete?: boolean;
  loadVerified?: boolean;
}

/**
 * The drafted-but-unconfirmed sections the focused pane's "approve & continue" confirms in ONE
 * click for the active stage (#807-followup). Confirming each discovery file individually was the
 * only way to satisfy the Context gate, but the focused pane has no per-file confirm control — so
 * a manual user was deadlocked. This collapses the per-file confirmation into a single per-stage
 * approval gesture.
 *
 * - **context** → nothing. Context files gate on GENERATION (#1028), not confirmation — they're
 *   done once written, so there's no per-file confirm step.
 * - other stages gate on counts (features, issues, fleet, …) or auto-derived signals, not section
 *   confirmation ⇒ nothing to confirm. (Milestone phases were removed in #1912, so the Structure
 *   stage no longer confirms a `phases` roadmap anchor — it gates on `featuresDefined`.)
 */
export function pendingStageConfirms(
  _activeStageKey: string | undefined,
  _sections: { k: string; state: SectionState }[],
): string[] {
  return [];
}

/**
 * The section keys "approve & continue" must confirm for the active stage to advance (#954).
 *
 * A **gateless** ("informational") stage completes ONLY via its own `confirmed:<key>` signal — it has
 * no `gateRule`, so the structure/context discovery anchors (which feed a GATE) don't apply to it.
 * This is the common case for an IMPORTED blueprint, whose gateRules are stripped on import so EVERY
 * stage is gateless: confirm the stage itself. Without this the focused pane left the approve button
 * enabled (an empty gate reads as met) yet nothing advanced.
 *
 * A **gated** stage completes via its gate; confirm the drafted anchors its gate reads
 * ({@link pendingStageConfirms}: structure → phases, context → the core discovery files).
 */
export function stageConfirmKeys(
  activeStageKey: string | undefined,
  sections: { k: string; state: SectionState }[],
  activeHasGate: boolean,
  activeAlreadyConfirmed: boolean,
): string[] {
  if (!activeStageKey) return [];
  if (!activeHasGate) return activeAlreadyConfirmed ? [] : [activeStageKey];
  return pendingStageConfirms(activeStageKey, sections);
}

export function derivePlanStageState(input: DerivePlanStageInput): PlanStageState {
  // Context (#1019/#1028): the gate is driven by the project's DYNAMIC required-set, not a hardcoded
  // core, and it passes on GENERATION — a topic is "ready" once its `context/<topic>.md` exists
  // (section state leaves `pending`). No confirmation: the files are done when written. There must be
  // ≥1 required topic (an empty set can't pass, which also retires the old "absent ⇒ satisfied" trap).
  const byKey = new Map(input.sections.map((s) => [s.k, s.state]));
  const present = (topic: string) => {
    const st = byKey.get(topic);
    return st !== undefined && st !== "pending";
  };
  const total = input.discoveryRequired.length;
  const resolved = input.discoveryRequired.filter(present).length;
  const requiredDiscoveryReady = total > 0 && resolved >= total;

  const sig = input.dataModelSignals ?? {};
  return buildPlanStageState({
    discovery: { resolved, total, requiredDiscoveryReady },
    repoCount: input.repoCount,
    requiresUi: input.requiresUi,
    ui: { ...input.ui, routed: input.uiRouted ?? false },
    features: input.features,
    dependencies: { count: input.dependencies?.count ?? 0 },
    issueCount: input.issueCount,
    fleet: { streams: input.fleetStreams, profilesComplete: input.fleetProfilesComplete },
    automationsAck: input.automationsAck,
    skillsAck: input.skillsAck,
    migrationSourceEnabled: input.migrationSourceEnabled ?? false,
    dataModel: {
      sourceReachable: sig.sourceReachable ?? false,
      modelInferred:   sig.modelInferred   ?? false,
      schemaRefined:   sig.schemaRefined   ?? false,
      mappingComplete: sig.mappingComplete ?? false,
      loadVerified:    sig.loadVerified    ?? false,
    },
  });
}

/**
 * Flatten the typed {@link PlanStageState} into the serializable {@link PlanSignals}
 * bag that declarative section gates read. This is the bridge between the app's live
 * state derivation and the data-driven gate evaluator — the published signal
 * vocabulary that built-in and cloud-distributed sections alike compose against.
 */
export function planStateToSignals(s: PlanStageState): PlanSignals {
  return {
    requiredDiscoveryReady: s.discovery.requiredDiscoveryReady,
    topicsResolved: s.discovery.resolved,
    topicsTotal: s.discovery.total,
    repoCount: s.repoCount,
    requiresUi: s.requiresUi,
    screensApproved: s.ui.approved,
    screensTotal: s.ui.total,
    // UI completes when the design is routed to the project OR every screen preview is
    // approved (#837) — the gate reads this combined signal.
    uiDone: s.ui.routed || (s.ui.total > 0 && s.ui.approved >= s.ui.total),
    featuresDefined: s.features.count,
    featuresConfirmed: s.features.allConfirmed,
    // Dependencies (#1111): the manifest gate passes once the planner has locked ≥1 library.
    dependenciesDefined: s.dependencies.count,
    issueCount: s.issueCount,
    fleetStreams: s.fleet.streams,
    profilesComplete: s.fleet.profilesComplete,
    automationsAck: s.automationsAck,
    skillsAck: s.skillsAck,
    // Data Model progress signals, derived from the live scan state (absent ⇒ false).
    sourceReachable: s.dataModel.sourceReachable,
    modelInferred:   s.dataModel.modelInferred,
    schemaRefined:   s.dataModel.schemaRefined,
    mappingComplete: s.dataModel.mappingComplete,
    loadVerified:    s.dataModel.loadVerified,
  };
}

