// Modular planning stages (#512/#515). The registry is the single source of
// truth for the canonical, ordered stage set and each stage's stable `id` — what
// the config/ordering layer (defaultStageConfig / enabledOrderedStages) and the
// blueprint seeder key off.
//
// Gating is NOT here. A stage's "done-ness" and applicability are declarative DATA
// — the `gateRule` / `appliesWhen` carried by each stage's prompt JSON
// (`src-tauri/data/stages/*.json`), evaluated by {@link evalGate} in stageGate.ts
// against the flat signal bag {@link planStateToSignals} publishes. That makes a
// stage authorable, shareable, and WAN-distributable as data; the executable code
// gates that used to live here (#1598) were dead duplicates that had drifted from
// the authoritative JSON, so they were removed.
//
// Everything here is pure — no React/Tauri — so the registry + config logic stays
// unit-testable, and both the bar and the Rust prompt assembler key off the same ids.
//
// The registry DATA (the ordered stage set + each stage's label/optional/deps/defaultEnabled) is
// externalized to `@data/planner/stage-registry.json` (#2027 P1) — editable without touching code and
// part of the exportable app-config bundle. (It lives OUTSIDE `@data/stages/`, whose per-stage prompt
// JSONs are loaded by a `@data/stages/*.json` glob that would otherwise grab the registry.) This
// module keeps the TYPES + the config logic (defaultStageConfig / enabledOrderedStages / STAGE_BY_ID).

import stageRegistryEmbedded from "@data/planner/stage-registry.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

// The config-dir copy (#2047) overlays the embedded default — editable without a rebuild.
const stageRegistry = overlayFile("planner/stage-registry.json", stageRegistryEmbedded);

/** All valid stage identifiers, in pipeline order.
 *  `load` is signal-only — it has no PLAN_STAGES entry and is never shown in the bar,
 *  but exists in the union so other stages and signal consumers can reference it by name. */
export type StageId =
  | "discovery"
  | "market"
  | "transformations"
  | "deployment"
  | "source"
  | "features"
  | "ui"
  | "streams"
  | "automations"
  | "skills"
  | "load";

/**
 * Normalized snapshot of live plan progress. A later slice builds this from the live
 * plan data (sections, repos, fleet, …) via {@link buildPlanStageState}, and
 * {@link planStateToSignals} (planStageDerive.ts) flattens it into the serializable
 * {@link PlanSignals} bag the declarative JSON gates read. Use buildPlanStageState to
 * construct one with safe defaults for any field not yet known.
 */
export interface PlanStageState {
  /** Discovery progress (#1019/#1028): required topics written (`resolved`) vs required total, plus
   *  `requiredDiscoveryReady` — every REQUIRED topic's file generated (≥1 required). No confirmation. */
  discovery: { resolved: number; total: number; requiredDiscoveryReady: boolean };
  /** Repositories linked to the project. */
  repoCount: number;
  /** Whether the project needs a UI at all — drives the UI stage's applicability. */
  requiresUi: boolean;
  /** Required screens approved vs total (only meaningful when requiresUi). `routed` is set
   *  when the user routes dropped design files to the project — an alternative completion to
   *  approving screen previews (#837). */
  ui: { approved: number; total: number; routed?: boolean };
  /** Features: how many user-facing capabilities are defined, and whether all are
   *  confirmed. Each feature becomes a fleet stream; the Plan stage reads them. */
  features: { count: number; allConfirmed: boolean };
  /** Dependencies (#1111/#1191): how many libraries the planner has locked in the dependency manifest
   *  (plan.db, via `bsc-plan deps set`). The Dependencies gate passes once ≥1 is defined. */
  dependencies: { count: number };
  issueCount: number;
  /** Fleet: streams defined, and each has a profile/flow set. */
  fleet: { streams: number; profilesComplete: boolean };
  /** Automations reviewed/acknowledged (may legitimately be zero). */
  automationsAck: boolean;
  /** Skills assigned/acknowledged (may legitimately be zero). */
  skillsAck: boolean;
  /** Whether a migration source pipeline is active for this project — drives the source
   *  stage's applicability. False for projects with no data migration component. */
  migrationSourceEnabled: boolean;
  /** Data Model progress signals, derived from the live source-scan state (#1446 — the canonical
   *  Data Model itself lives in the project's DuckDB store). Absent signals read as all-false. */
  dataModel: {
    sourceReachable: boolean;
    modelInferred: boolean;
    schemaRefined: boolean;
    mappingComplete: boolean;
    loadVerified: boolean;
  };
}

export interface Stage {
  id: StageId;
  /** Short display label shown in the PlanStageBar. */
  label: string;
  /** One-line description of what this stage produces (shown in Blueprint editor). */
  description: string;
  /** Whether the stage can be toggled off in a Blueprint.
   *  Only `discovery` is required (optional: false). All other stages — including
   *  `structure` — can be omitted by blueprints that don't need them (e.g. a
   *  refactor/cleanup blueprint skips the feature workshop). */
  optional: boolean;
  /** Whether this stage produces a visible output file the app polls for
   *  (e.g. phases.json, fleet.json). Informational only — drives tooltip copy. */
  hasOutputFile: boolean;
  /** Prerequisite stages (documentation of the canonical ordering). Live dependency
   *  gating is the blueprint section's declarative `deps`, not this field. */
  dependsOn: StageId[];
  defaultEnabled: boolean;
}

/** Per-project (or per-blueprint) on/off + ordering of the stages (#512). */
export interface StageConfig {
  enabled: Record<StageId, boolean>;
  order: StageId[];
}

// ── The canonical stage registry ─────────────────────────────────────────────
// From `@data/planner/stage-registry.json`. Ordering rationale baked into that file's order: `ui`
// sits after `features` so its Claude Design kickoff can reference the defined capabilities
// (#825/#1404); `deployment`/`streams` are the collapsed repos+deploy / structure+permissions stages
// (#1914). `dependsOn` DOCUMENTS the real prerequisites — runtime gating reads each stage's
// declarative `@data/stages/<id>.json` `gateRule`/`deps`, not this registry. (The signal-only `load`
// sibling has NO registry entry — it never shows in the bar — but exists in the StageId union.)
export const PLAN_STAGES: Stage[] = stageRegistry as Stage[];

export const STAGE_BY_ID: Record<StageId, Stage> = Object.fromEntries(
  PLAN_STAGES.map((s) => [s.id, s]),
) as Record<StageId, Stage>;

/** All-on config in the registry's default order — reproduces today's behavior. */
export function defaultStageConfig(): StageConfig {
  return {
    enabled: Object.fromEntries(PLAN_STAGES.map((s) => [s.id, s.defaultEnabled])) as Record<StageId, boolean>,
    order: PLAN_STAGES.map((s) => s.id),
  };
}

/**
 * The dynamic-stages seed (#1395 phase 1): ONLY Discovery is enabled; every other
 * stage starts OFF and lights up additively as Discovery's classification signals select it.
 * The full registry order is preserved so an additively-enabled stage slots into its place.
 * Distinct from {@link defaultStageConfig} (all-on), which reproduces the legacy blueprint behavior;
 * this is the source-of-truth seed a new project gets once blueprints stop hand-picking the set.
 */
export function discoveryOnlyStageConfig(): StageConfig {
  return {
    enabled: Object.fromEntries(PLAN_STAGES.map((s) => [s.id, s.id === "discovery"])) as Record<StageId, boolean>,
    order: PLAN_STAGES.map((s) => s.id),
  };
}

/** Fill a partial snapshot with safe defaults so callers needn't specify every field. */
export function buildPlanStageState(p: Partial<PlanStageState> = {}): PlanStageState {
  return {
    discovery: p.discovery ?? { resolved: 0, total: 0, requiredDiscoveryReady: false },
    repoCount: p.repoCount ?? 0,
    requiresUi: p.requiresUi ?? false,
    ui: p.ui ?? { approved: 0, total: 0, routed: false },
    features: p.features ?? { count: 0, allConfirmed: false },
    dependencies: p.dependencies ?? { count: 0 },
    issueCount: p.issueCount ?? 0,
    fleet: p.fleet ?? { streams: 0, profilesComplete: false },
    automationsAck: p.automationsAck ?? false,
    skillsAck: p.skillsAck ?? false,
    migrationSourceEnabled: p.migrationSourceEnabled ?? false,
    dataModel: p.dataModel ?? {
      sourceReachable: false,
      modelInferred: false,
      schemaRefined: false,
      mappingComplete: false,
      loadVerified: false,
    },
  };
}

/** The enabled stages, in the configured order (what the bar renders). */
export function enabledOrderedStages(cfg: StageConfig): Stage[] {
  return cfg.order.filter((id) => cfg.enabled[id]).map((id) => STAGE_BY_ID[id]).filter(Boolean);
}

runtime.features/planner/stages/planSubsteps.ts:
// Substep resolution (#…). Pure helpers over the blueprint section model: which substep the
// conductor injects next. No React/Tauri — fully unit-testable.
import type { SubStep } from "./blueprints";

/** A substep is done when: (static) its artifact key is confirmed; (loop) the conductor says
 *  the loop is finished — the model can't know per-item completion, so `loopDone` is supplied. */
export function substepDone(s: SubStep, confirmed: Set<string>, loopDone: boolean): boolean {
  return s.loop ? loopDone : confirmed.has(s.key);
}

/** The active substep = the first not-yet-done one, in order. Undefined ⇒ all substeps done
 *  (the conductor falls back to the stage's own gate). */
export function activeSubstep(
  substeps: SubStep[] | undefined,
  confirmed: Set<string>,
  loopDone = false,
): SubStep | undefined {
  return (substeps ?? []).find((s) => !substepDone(s, confirmed, loopDone));
}

runtime.features/planner/stages/planTopics.ts:
// Pure helpers for the dynamic, guided project planner.
//
// The planner no longer has a fixed list of sections. Claude documents whatever
// topics a given project warrants — each documented topic becomes its own file
// in the plan directory and is surfaced in the UI as it's written. These helpers
// turn raw section keys (file stems) into ordered, titled, tier-grouped sections
// for rendering, and parse the considered-but-skipped coverage record.
//
// Free of React / xterm / Tauri imports so the logic can be unit-tested in
// isolation and shared between Planning.tsx and its tests. (The fleet/agent-stream
// machinery that used to live here moved to fleet/planFleet.ts in #1615.)

import { FLEET_KEY } from "../fleet/planFleet";

/** The coverage record: topics considered but deliberately not documented. */
export const SKIPPED_KEY = "_skipped";

/** The feature list file (JSON: `features.json` — an array of feature objects). The
 *  authoritative artifact of the Features stage (#…): each entry is a user-facing capability
 *  and a fleet stream. Surfaced by the poll like `fleet.json`; not rendered as a plan section —
 *  it drives the Features board. See {@link parseFeaturesFile} in featureList. */
export const FEATURES_KEY = "features";

/**
 * Anchor sections that are always present in the UI even before Claude drafts
 * them, because the GitHub publish flow is keyed off them:
 *   - `goal`   → project board title + description
 */
export const ANCHOR_KEYS = ["goal"] as const;

/** Section keys for the per-repo tier are namespaced `repo__{short}__{topic}`. */
const REPO_PREFIX = "repo__";

/**
 * The curated checklist of dimensions covering modern application development,
 * in the order they should appear. Claude walks this list during discovery,
 * documenting the ones that apply and recording the rest as skipped. Custom
 * topics Claude invents sort after these (alphabetically). The title is what the
 * section card shows.
 *
 * Single-sourced from the Discovery stage data (`src-tauri/data/stages/discovery.json`,
 * its `dimensions` array) so the dimension vocabulary lives in ONE place — the same data
 * file the planner prompt and gate read (#1591). Loaded directly via `import.meta.glob`
 * (NOT through blueprints.ts `STAGE_DEFS`) to avoid a circular import.
 */
const discoveryModules = import.meta.glob<{ default: { dimensions?: { key: string; title: string }[] } }>(
  "@data/stages/discovery.json",
  { eager: true },
);
export const KNOWN_DIMENSIONS: { key: string; title: string }[] =
  Object.values(discoveryModules)[0]?.default.dimensions ?? [];

const TITLE_BY_KEY = new Map(KNOWN_DIMENSIONS.map(d => [d.key, d.title]));
const ORDER_BY_KEY = new Map(KNOWN_DIMENSIONS.map((d, i) => [d.key, i]));

// Reverse map (#…): a section the planner named after its DISPLAY TITLE ("Tech stack.md") or a
// casing/separator variant is canonicalized back to its key ("stack"), so the Context gate —
// which keys off goal/scope/stack/architecture — stays robust to how the file is named.
const KEY_BY_TITLE = new Map(KNOWN_DIMENSIONS.map(d => [d.title.toLowerCase(), d.key]));
// Synonyms with no separator / alternate wording the title map alone wouldn't catch.
const KEY_ALIASES: Record<string, string> = {
  techstack: "stack", "technology stack": "stack",
  "data schema": "schema", personas: "users",
  versioning: "release", releases: "release", "release schedule": "release",
  "versioning and release schedule": "release", "release plan": "release",
  // #3989 — the outage plan is prose-titled in a dozen ways; land them all on the one key.
  "outage response": "outage_response", "outage": "outage_response",
  "cloud outage": "outage_response", "cloud outage response plan": "outage_response",
  "outage response plan": "outage_response",
};
/**
 * Map a section key/stem the planner may have written as a display title or alias (e.g.
 * "Tech stack", "Tech_stack") back to its canonical key ("stack"). Canonical keys and unknown
 * custom topics pass through unchanged.
 */
export function canonicalTopicKey(key: string): string {
  const raw = key.trim();
  if (TITLE_BY_KEY.has(raw)) return raw; // already canonical
  const norm = raw.toLowerCase().replace(/[_-]+/g, " ").replace(/\s+/g, " ").trim();
  return KEY_BY_TITLE.get(norm) ?? KEY_ALIASES[norm] ?? key;
}

// Words that should keep a specific casing rather than be Title-cased.
const ACRONYMS: Record<string, string> = {
  api: "API", ui: "UI", ux: "UX", id: "ID", url: "URL", db: "DB", io: "IO",
  ci: "CI", cd: "CD", cli: "CLI", sdk: "SDK", cicd: "CI/CD", sql: "SQL",
  html: "HTML", css: "CSS", http: "HTTP", grpc: "gRPC", i18n: "i18n",
  a11y: "a11y", seo: "SEO", mvp: "MVP", kpi: "KPI", llm: "LLM", ml: "ML",
};

function humanize(topic: string): string {
  const words = topic.split(/[_\-\s]+/).filter(Boolean);
  if (words.length === 0) return "Section";
  return words
    .map(w => ACRONYMS[w.toLowerCase()] ?? (w.charAt(0).toUpperCase() + w.slice(1)))
    .join(" ");
}

export interface TopicKeyInfo {
  /** "project" for top-level plan sections, "repo" for a per-repo tier section. */
  tier: "project" | "repo";
  /** Short repo name for repo-tier sections; null for project-tier. */
  repo: string | null;
  /** The dimension/topic this section documents (e.g. "api", "security"). */
  topic: string;
}

/**
 * Decode a raw section key (file stem) into its tier and topic.
 *
 * Project-tier keys are bare (`api`, `security`, `data_lifecycle`).
 * Repo-tier keys are namespaced `repo__{short}__{topic}` — e.g. `repo__web__api`
 * → repo "web", topic "api". A repo key missing its topic falls back to
 * "overview".
 */
export function parseTopicKey(key: string): TopicKeyInfo {
  if (key.startsWith(REPO_PREFIX)) {
    const rest = key.slice(REPO_PREFIX.length);
    const sep = rest.indexOf("__");
    if (sep > 0) {
      return { tier: "repo", repo: rest.slice(0, sep), topic: rest.slice(sep + 2) || "overview" };
    }
    // `repo__web` with no topic — treat the remainder as the repo, topic generic.
    return { tier: "repo", repo: rest || "repo", topic: "overview" };
  }
  return { tier: "project", repo: null, topic: key };
}

/** Human-readable title for a section key, honoring the curated titles and acronyms. */
export function titleForTopic(key: string): string {
  if (key === SKIPPED_KEY) return "Considered & skipped";
  const { topic } = parseTopicKey(key);
  return TITLE_BY_KEY.get(topic) ?? humanize(topic);
}

/**
 * Order project-tier section keys: known dimensions in checklist order, then any
 * custom keys alphabetically. The `_skipped` record and repo-tier keys are not
 * expected here (callers filter them out first).
 */
export function orderTopicKeys(keys: string[]): string[] {
  const rank = (k: string) => ORDER_BY_KEY.get(k) ?? KNOWN_DIMENSIONS.length;
  return [...keys].sort((a, b) => {
    const ra = rank(a), rb = rank(b);
    return ra !== rb ? ra - rb : a.localeCompare(b);
  });
}

/**
 * Split a flat list of section keys into the project tier and per-repo groups.
 * Project keys are ordered by the curated checklist; each repo's topics are
 * ordered the same way (by topic). The `_skipped` record is excluded from both.
 */
export function groupTopics(keys: string[]): {
  project: string[];
  repos: { repo: string; keys: string[] }[];
} {
  const project: string[] = [];
  const byRepo = new Map<string, string[]>();
  for (const key of keys) {
    if (key === SKIPPED_KEY || key === FLEET_KEY || key === FEATURES_KEY) continue;
    const info = parseTopicKey(key);
    if (info.tier === "repo" && info.repo) {
      const list = byRepo.get(info.repo) ?? [];
      list.push(key);
      byRepo.set(info.repo, list);
    } else {
      project.push(key);
    }
  }
  const repos = [...byRepo.entries()]
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([repo, ks]) => ({
      repo,
      keys: [...ks].sort((a, b) => {
        const ta = parseTopicKey(a).topic, tb = parseTopicKey(b).topic;
        const ra = ORDER_BY_KEY.get(ta) ?? KNOWN_DIMENSIONS.length;
        const rb = ORDER_BY_KEY.get(tb) ?? KNOWN_DIMENSIONS.length;
        return ra !== rb ? ra - rb : ta.localeCompare(tb);
      }),
    }));
  return { project: orderTopicKeys(project), repos };
}

export interface SkippedItem { topic: string; reason: string; }

/**
 * Parse the `_skipped.md` coverage record into topic/reason pairs. Tolerant of a
 * few common line formats so Claude isn't forced into a rigid syntax:
 *
 *   - **topic** — reason
 *   - topic — reason
 *   - topic: reason
 *   - topic - reason
 *
 * Lines without a recognizable separator are treated as a topic with no reason.
 * Blank lines and markdown headers/horizontal rules are ignored.
 */
export function parseSkipped(content: string): SkippedItem[] {
  if (!content) return [];
  const out: SkippedItem[] = [];
  for (const raw of content.split(/\r?\n/)) {
    let line = raw.trim();
    if (!line) continue;
    if (/^#{1,6}(?:\s|$)/.test(line)) continue;  // markdown header — not a skip item
    line = line.replace(/^[-*+]\s+/, "");        // drop leading list marker
    if (!line || /^[-=_]{3,}$/.test(line)) continue;  // blank or horizontal rule
    // Split topic from reason on the first em dash, " - ", or ":".
    const m = line.match(/^(.*?)(?:\s+—\s+|\s+-\s+|:\s+)(.*)$/);
    if (m) {
      const topic = m[1].replace(/\*\*/g, "").trim();
      const reason = m[2].trim();
      if (topic) out.push({ topic, reason });
    } else {
      const topic = line.replace(/\*\*/g, "").trim();
      if (topic) out.push({ topic, reason: "" });
    }
  }
  return out;
}

runtime.features/planner/stages/stageGate.ts:
// Declarative, serializable completion gates for planning sections (#…).
//
// A section's "done-ness" used to be executable code hung off the PLAN_STAGES
// registry (`gate: (s) => …`). That made a section impossible to author, share, or
// distribute as data — you couldn't ship one over the WAN without shipping code.
//
// A StageGate is a pure DATA predicate over a flat bag of named SIGNALS the app
// publishes (repoCount, issueCount, requiredDiscoveryReady, …). The app evaluates the gate;
// the section — built-in OR cloud-distributed — only ever carries JSON. New sections
// compose the existing signal vocabulary but cannot invent signals or run code, which
// is the safety boundary that makes distribution viable.
//
// This module is pure (no React/Tauri) and has no dependency on the stage registry,
// so it can be reused by the desktop, the relay, and any future authoring tool.

/** The flat, serializable signal bag the app computes from live plan state.
 *  Missing keys read as 0 (numeric) / false (boolean) when evaluated. */
export type PlanSignals = Record<string, number | boolean>;

/** Comparison operators a numeric requirement may use. Default is ">=". */
export type GateOp = ">=" | ">" | "<=" | "<" | "==" | "!=";

/** One requirement of a gate: a single signal compared against a target. */
export interface Requirement {
  /** Signal this requirement reads. */
  signal: string;
  /** Pass threshold. Boolean ⇒ identity match; number ⇒ compared with {@link op}.
   *  Defaults to `true` (a presence/acknowledgement flag). */
  target?: number | boolean;
  /** Numeric comparison operator (ignored for boolean targets). Default ">=". */
  op?: GateOp;
  /** Denominator signal for an "X of Y" ratio. When set, progress = signal / of
   *  and the requirement passes only when `of > 0` and signal meets `of`. */
  of?: string;
  /** Weight of this requirement in the bar-fill fraction. Default 1.
   *  Use 0 for a must-pass flag that should not move the progress fill. */
  weight?: number;
  /** Optional per-requirement human reason (what's left), for richer feedback. */
  label?: string;
}

/** A completion gate: every requirement must pass (logical AND). An empty/absent
 *  gate is vacuously satisfied — the safe default for an informational section. */
export interface StageGate {
  require: Requirement[];
}

function asNumber(v: number | boolean | undefined): number {
  return typeof v === "number" ? v : v ? 1 : 0;
}
function asBool(v: number | boolean | undefined): boolean {
  return typeof v === "boolean" ? v : !!v;
}
function compare(a: number, b: number, op: GateOp): boolean {
  switch (op) {
    case ">":  return a > b;
    case "<":  return a < b;
    case "<=": return a <= b;
    case "==": return a === b;
    case "!=": return a !== b;
    case ">=":
    default:   return a >= b;
  }
}

/** Evaluate a single requirement → did it pass, and its 0..1 progress. */
export function evalRequirement(r: Requirement, signals: PlanSignals): { pass: boolean; progress: number } {
  // Ratio ("X of Y") takes precedence over the target default — `of` makes it numeric
  // even when no explicit numeric target is given.
  if (r.of) {
    const v = asNumber(signals[r.signal]);
    const denom = asNumber(signals[r.of]);
    // A zero denominator means there is nothing to resolve — the ratio is vacuously
    // satisfied (you can't fail to resolve zero of zero items). Treating it as a failure
    // deadlocks any gate whose denominator legitimately reaches 0 — e.g. the Context gate
    // when a lighter blueprint surfaces no discovery topics (#953). An author who needs
    // "at least one" should add a separate count requirement on the denominator signal.
    if (denom <= 0) return { pass: true, progress: 1 };
    const progress = Math.min(v / denom, 1);
    const pass = compare(v, denom, r.op ?? ">=");
    return { pass, progress };
  }
  const target = r.target ?? true;
  if (typeof target === "boolean") {
    const v = asBool(signals[r.signal]);
    const pass = r.op === "!=" ? v !== target : v === target;
    return { pass, progress: pass ? 1 : 0 };
  }
  const v = asNumber(signals[r.signal]);
  const pass = compare(v, target, r.op ?? ">=");
  const progress = pass ? 1 : target > 0 ? Math.min(v / target, 1) : 0;
  return { pass, progress };
}

/**
 * Evaluate a gate against the signal bag. `done` is the AND of every requirement;
 * `fraction` is the weight-averaged progress (requirements with weight 0 are must-pass
 * but contribute no fill). An empty gate is done with full fraction.
 */
export function evalGate(gate: StageGate | undefined, signals: PlanSignals): { done: boolean; fraction: number } {
  const reqs = gate?.require ?? [];
  if (reqs.length === 0) return { done: true, fraction: 1 };
  let done = true;
  let weightSum = 0;
  let fillSum = 0;
  for (const r of reqs) {
    const { pass, progress } = evalRequirement(r, signals);
    if (!pass) done = false;
    const w = r.weight ?? 1;
    weightSum += w;
    fillSum += w * progress;
  }
  const fraction = weightSum > 0 ? fillSum / weightSum : done ? 1 : 0;
  return { done, fraction };
}

/** Whether a section applies at all (e.g. UI only when the project needs a UI).
 *  An absent rule means the section always applies. */
export function gateApplies(rule: Requirement | undefined, signals: PlanSignals): boolean {
  return rule ? evalRequirement(rule, signals).pass : true;
}

/** Per-requirement reason for "why is this gate blocked" feedback: the human label,
 *  whether it passed, and a progress detail ("3 of 5") for ratio/numeric requirements. */
export interface GateReason {
  label: string;
  pass: boolean;
  detail?: string;
}

/** Humanize a signal name as a fallback label ("topicsResolved" → "topics resolved"). */
function humanizeSignal(signal: string): string {
  return signal
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .toLowerCase()
    .trim();
}

/**
 * Per-requirement breakdown for gate feedback — same pass logic as {@link evalGate}, but
 * keeps each requirement's human label (falling back to a humanized signal name) and a
 * progress detail. Filter to `!pass` for "what's still needed".
 */
export function gateReasons(gate: StageGate | undefined, signals: PlanSignals): GateReason[] {
  return (gate?.require ?? []).map((r) => {
    const { pass } = evalRequirement(r, signals);
    const label = r.label ?? humanizeSignal(r.signal);
    let detail: string | undefined;
    if (r.of) {
      detail = `${asNumber(signals[r.signal])} of ${asNumber(signals[r.of])}`;
    } else if (typeof (r.target ?? true) === "number") {
      detail = `${asNumber(signals[r.signal])} / ${asNumber(r.target)}`;
    }
    return { label, pass, detail };
  });
}

