// Security — Assignments tab (#1643 split from SecurityWorkspace).
//
// The always-present application sessions + the per-pane console assignments, each
// pane showing its resolved command allowlist (guaranteed ∪ profile ∪ project ∪
// repo). The pane-profile picker (#681) is the click-to-open `ProfileSelect`.

import { useEffect, useState } from "react";
import { GUARANTEED, resolveAllowlistFrom, type AgentProfile, type ConsoleSession } from "./lib/agentProfiles";
import { appSessionTag } from "./lib/appSession";
import { CardListRow } from "@/shared/ui/data/CardListRow";
import { Chip } from "@/shared/ui/data/Chip";
import { SectionHeader } from "@/shared/ui/layout/SectionHeader";
import { Button } from "@/shared/ui/controls/Button";
import { Box } from "@/shared/ui/layout/Box";
import { modeTone } from "./lib/badgeTone";

export interface AssignmentsTabProps {
  roles: AgentProfile[]; consoles: ConsoleSession[]; paneTotal: number;
  /** Assignable profiles (the user/custom profiles a pane can run under). */
  profiles: AgentProfile[];
  /** Assign a specific profile to a pane (#681 — replaces the old cycle-to-next). */
  onAssign: (consoleId: string, paneId: string, profileId: string) => void;
  onOpen: (id: string) => void;
  find: (id: string) => AgentProfile | undefined;
}

/** A click-to-open dropdown for picking a pane's profile (#681). */
export function ProfileSelect({ current, profiles, onPick }: {
  current?: AgentProfile; profiles: AgentProfile[]; onPick: (id: string) => void;
}) {
  const [open, setOpen] = useState(false);
  useEffect(() => {
    if (!open) return;
    const close = () => setOpen(false);
    window.addEventListener("click", close);
    return () => window.removeEventListener("click", close);
  }, [open]);
  return (
    <Box className="prof-select" style={{ position: "relative" }} onClick={(e) => { e.stopPropagation(); setOpen((o) => !o); }}>
      <Box as="span" className="sw" bg={current?.color} />
      <Box as="span" className="nm">{current?.name ?? "—"}</Box>
      {current && <Chip tone={modeTone(current.mode)} size="sm" style={{ marginLeft: 2 }}>{current.mode}</Chip>}
      <Box as="span" className="cv">▾</Box>
      {open && (
        <Box className="prof-menu" role="listbox" onClick={(e) => e.stopPropagation()}>
          {profiles.map((p) => (
            // eslint-disable-next-line no-restricted-syntax -- bespoke listbox option (role=option, .prof-opt styling), not a .btn
            <button
              key={p.id}
              type="button"
              role="option"
              aria-selected={p.id === current?.id}
              className={"prof-opt" + (p.id === current?.id ? " on" : "")}
              onClick={() => { onPick(p.id); setOpen(false); }}
            >
              <Box as="span" className="sw" bg={p.color} />
              <Box as="span" className="nm">{p.name}</Box>
              <Chip tone={modeTone(p.mode)} size="sm">{p.mode}</Chip>
            </button>
          ))}
        </Box>
      )}
    </Box>
  );
}

function AppSessionRow({ p, onOpen }: { p: AgentProfile; onOpen: (id: string) => void }) {
  const all = [
    ...GUARANTEED.map((c) => ({ cmd: c, origin: "guaranteed" as const })),
    ...p.commands.map((c) => ({ cmd: c, origin: "profile" as const })),
  ];
  return (
    <CardListRow
      variant="grouped"
      lead={<Box as="span" className="pdot running" />}
      title={appSessionTag(p)}
      subtitle={<Box as="span" className="mono">{p.session}</Box>}
      titleAside={
        <Box className="prof-select" onClick={() => onOpen(p.id)}>
          <Box as="span" className="sw" bg={p.color} />
          <Box as="span" className="nm">{p.name}</Box>
          <Chip tone="info" size="xs" style={{ marginLeft: 2 }}>locked</Chip>
        </Box>
      }
      body={
        <Box className="resolved">
          <Box as="span" className="lbl">runs:</Box>
          {all.map((r) => (
            <Box as="span" key={r.cmd} className={`rchip ${r.origin === "guaranteed" ? "guar" : ""}`} title={`from ${r.origin}`}>{r.cmd}</Box>
          ))}
          <Box as="span" className="rchip" style={{ borderStyle: "dashed" }}>owns {p.surface}</Box>
        </Box>
      }
      trailing={<Button variant="ghost" style={{ height: 24, fontSize: 10 }} onClick={() => onOpen(p.id)}>edit role →</Button>}
    />
  );
}

export function AssignmentsTab({ roles, consoles, paneTotal, profiles, onAssign, onOpen, find }: AssignmentsTabProps) {
  return (
    <>
      <SectionHeader title="Application sessions" hint="always present · one per workspace · role is fixed" meta={<>{roles.length} system roles</>} />
      <Box className="asn-grid" style={{ marginBottom: 14 }}>
        <Box className="console-card" style={{ borderColor: "color-mix(in oklch, var(--info), transparent 78%)" }}>
          <Box className="ch" bg="color-mix(in oklch, var(--info), transparent 92%)">
            <Box as="span" className="cdot" bg="var(--info)" />
            <Box as="span" className="cn">system</Box>
            <Box as="span" className="repo">workspace-wide</Box>
            <Box as="span" className="spacer" />
            <Box as="span" className="hint mono">launched at startup · not reassignable</Box>
          </Box>
          {roles.map((p) => <AppSessionRow key={p.id} p={p} onOpen={onOpen} />)}
        </Box>
      </Box>

      <SectionHeader title="Console sessions" hint="each pane runs under one profile · the resolved command allowlist shows what actually runs there" meta={<>{consoles.length} consoles · {paneTotal} panes</>} />
      <Box style={{ overflow: "auto", flex: 1, minHeight: 0 }}>
        <Box className="asn-grid">
          {consoles.map((c) => (
            <Box className="console-card" key={c.id}>
              <Box className="ch">
                <Box as="span" className="cdot" />
                <Box as="span" className="cn">{c.name}</Box>
                <Box as="span" className="repo">{c.repo}</Box>
                <Box as="span" className="spacer" />
                <Box as="span" className="hint mono">
                  project allow: {(c.projectAllow || []).join(", ") || "—"}{c.repoAllow ? ` · repo: ${c.repoAllow.join(", ")}` : ""}
                </Box>
              </Box>
              {c.panes.map((pane) => {
                const p = find(pane.profileId);
                const resolved = resolveAllowlistFrom(c, p);
                return (
                  <CardListRow
                    key={pane.id}
                    variant="grouped"
                    lead={<Box as="span" className={`pdot ${pane.status}`} />}
                    title={pane.agent}
                    subtitle={<Box as="span" className="mono">{pane.id}</Box>}
                    titleAside={<ProfileSelect current={p} profiles={profiles} onPick={(id) => onAssign(c.id, pane.id, id)} />}
                    body={
                      <Box className="resolved">
                        <Box as="span" className="lbl">runs:</Box>
                        {resolved.map((r) => (
                          <Box as="span" key={r.cmd} className={`rchip ${r.origin === "guaranteed" ? "guar" : ""}`} title={`from ${r.origin}`}>{r.cmd}</Box>
                        ))}
                        {resolved.length === 0 && <Box as="span" className="rchip">— prompt for everything —</Box>}
                      </Box>
                    }
                    trailing={<Button variant="ghost" style={{ height: 24, fontSize: 10 }} onClick={() => onOpen(pane.profileId)}>edit profile →</Button>}
                  />
                );
              })}
            </Box>
          ))}
        </Box>
      </Box>
    </>
  );
}

runtime.features/security/FlowTab.tsx:
// Security — Flow tab (#1643 split from SecurityWorkspace).
//
// The fleet's live work-flow: which sessions are parked on a dependency (#199) — each
// cross-referenced with the permission profile the session runs under. Coord state is
// rebuilt from the app-wide $BSC_COORD_LOG via read_coord_log + ingestCoordLog, so it
// needs no store wiring. Summary + status colors are pure (./lib/flowModel).

import { useCallback, useState } from "react";
import { StatusDot } from "@/shared/ui/feedback/StatusDot";
import { Chip } from "@/shared/ui/data/Chip";
import { StatTile } from "@/shared/ui/data/StatTile";
import { SectionHeader } from "@/shared/ui/layout/SectionHeader";
import { Card } from "@/shared/ui/data/Card";
import { Button } from "@/shared/ui/controls/Button";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { usePoll } from "@/shared/hooks/usePoll";
import {
  coordinationSummary, wakePromptFor, emptyCoordState,
  type BlockedView, type Waiter, type CoordState,
} from "@/shared/lib/fleet/coordination";
import { readCoordState } from "@/shared/lib/fleet/useCoordLog";
import { actuateWake } from "@/shared/lib/fleet/coordinatorActuate";
import type { AgentProfile } from "./lib/agentProfiles";
import { flowSummary, depColor } from "./lib/flowModel";

const COORD_POLL_MS = 3000;

export interface FlowTabProps {
  wakePane: (paneId: string, prompt: string) => boolean;
  profileFor: (session: string) => AgentProfile | undefined;
}

/** A compact "session @ profile" chip — the Agents-screen cross-reference. */
function SessionTag({ session, profile }: { session: string; profile?: AgentProfile }) {
  return (
    <Box as="span" style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
      <h3 className="mono" style={{ margin: 0, fontSize: 13 }}>{session}</h3>
      {profile && (
        <Box as="span" className="hint mono" style={{ display: "inline-flex", alignItems: "center", gap: 4, fontSize: 10 }}>
          <Box as="span" className="sw" bg={profile.color} radius={2} style={{ width: 8, height: 8, display: "inline-block" }} />
          {profile.name}
        </Box>
      )}
    </Box>
  );
}

export function FlowTab({ wakePane, profileFor }: FlowTabProps) {
  const [views, setViews] = useState<BlockedView[]>([]);
  const [ready, setReady] = useState<Waiter[]>([]);
  const [state, setState] = useState<CoordState>(emptyCoordState());
  const [err, setErr] = useState<string | null>(null);
  const [waking, setWaking] = useState<Set<string>>(new Set());

  // Polls only while this tab is mounted (the tab is conditionally rendered).
  // Reads via the shared readCoordState (#1495) — `null` on a read failure, which we
  // map to the existing `err` banner (last-good views/ready/state are kept).
  usePoll(async (isCancelled) => {
    const r = await readCoordState(1000);
    if (isCancelled()) return;
    if (!r) { setErr("Failed to read the coordination log"); return; }
    setViews(coordinationSummary(r.state));
    setReady(r.ready);
    setState(r.state);
    setErr(null);
  }, COORD_POLL_MS);

  const handleWake = useCallback(async (wtr: Waiter) => {
    setWaking((cur) => new Set(cur).add(wtr.session));
    try {
      await actuateWake(wtr.session, wakePromptFor(wtr, state), wakePane);
    } finally {
      setWaking((cur) => { const n = new Set(cur); n.delete(wtr.session); return n; });
    }
  }, [wakePane, state]);

  const { stalled, deadlocked, idle } = flowSummary(views, ready);

  return (
    <Box style={{ overflow: "auto", flex: 1, minWidth: 0 }}>
      <Box className="summary">
        <StatTile k="ready" v={ready.length} tone="success" sub="deps landed — wake" />
        <StatTile k="blocked" v={views.length} tone="accent" sub="parked on a dep" />
        <StatTile k="stalled / deadlocked" v={stalled + deadlocked} tone="danger" sub={<>{deadlocked} cyclic · escalate</>} />
      </Box>

      {deadlocked > 0 && (
        <Card style={{ margin: "0 0 14px", borderColor: "var(--danger)" }}>
          <Row gap={8} className="mono" style={{ color: "var(--danger)", fontSize: 12 }}>
            <Box as="span">⚠ deadlock</Box>
            <Text as="span" className="hint" tone="muted">
              {deadlocked} session{deadlocked === 1 ? "" : "s"} sit in a wait-for cycle — no producer can move. Escalate to the director / break the cycle (#199).
            </Text>
          </Row>
        </Card>
      )}

      {err && <Text as="div" mono size={11} tone="danger" style={{ marginBottom: 10 }}>{err}</Text>}

      {idle && !err && (
        <Text as="div" className="hint" mono size={11.5} style={{ padding: "8px 2px" }}>
          The fleet is flowing. Sessions appear here when a worker pauses for you (<code>bsc-wait</code>)
          or asks the director a question (<code>bsc-ask</code>).
        </Text>
      )}

      {ready.length > 0 && (
        <>
          <SectionHeader title="Ready" hint="dependencies landed — wake the parked pane" />
          <Box style={{ marginBottom: 14 }}>
            {ready.map((wtr) => (
              <Card key={wtr.session} style={{ marginBottom: 10, borderColor: "var(--success)" }}>
                <Row gap={10}>
                  <SessionTag session={wtr.session} profile={profileFor(wtr.session)} />
                  <Chip tone="success" style={{ fontSize: 9.5 }}><StatusDot style={{ marginRight: 4 }} />ready</Chip>
                  <Spacer />
                  {wtr.checkpoint && <Text as="span" className="hint" mono size={10}>↺ {wtr.checkpoint}</Text>}
                  <Button
                    variant="primary"
                    style={{ height: 24, padding: "0 12px", fontSize: 11 }}
                    disabled={waking.has(wtr.session)}
                    onClick={() => handleWake(wtr)}
                  >
                    {waking.has(wtr.session) ? "waking…" : "Wake"}
                  </Button>
                </Row>
              </Card>
            ))}
          </Box>
        </>
      )}

      {views.length > 0 && (
        <>
          <SectionHeader title="Blocked" hint="parked on a dependency · live from the coordination log" />
          {views.map((v) => (
            <Card key={v.session} style={{ marginBottom: 10, borderColor: v.deadlocked || v.stalled ? "var(--danger)" : undefined }}>
              <Row gap={10} style={{ marginBottom: 8 }}>
                <SessionTag session={v.session} profile={profileFor(v.session)} />
                {v.deadlocked
                  ? <Chip style={{ color: "var(--danger)", fontSize: 9.5 }}><StatusDot style={{ marginRight: 4 }} />deadlocked</Chip>
                  : v.stalled
                    ? <Chip style={{ color: "var(--danger)", fontSize: 9.5 }}><StatusDot style={{ marginRight: 4 }} />stalled</Chip>
                    : <Chip style={{ fontSize: 9.5 }}>waiting</Chip>}
                <Spacer />
                {v.checkpoint && <Text as="span" className="hint" mono size={10}>↺ {v.checkpoint}</Text>}
              </Row>
              <Row gap={6} wrap align="stretch">
                {v.deps.map((d) => (
                  <Box as="span" key={d.ref} className="mono" pad={[3, 8]} border="soft" radius={5} style={{
                    fontSize: 11, color: depColor(d.status),
                  }}>
                    {d.ref} · {d.status}
                  </Box>
                ))}
              </Row>
            </Card>
          ))}
        </>
      )}
    </Box>
  );
}

runtime.features/security/graphPlatform.ts:
// The security feature's graph-platform surface (#3646, epic #3604) — the feature-internal modules a
// graph-loaded Security page imports but does NOT redraw: the pure permission-profile / console / audit /
// flow domain logic. Registered HERE, inside the feature, because the shell must not reach a feature's
// internals (#1545) and eager-importing them from `app/` would de-lazy the feature at boot. The security
// host calls this synchronously before the graph page loads, so the modules are present when the compiled
// page's `require()` runs. Mirrors registerFleetPlatform / registerAutomationsPlatform.
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
import * as AgentProfiles from "./lib/agentProfiles";
import * as ConsoleModel from "./lib/consoleModel";
import * as AuditRows from "./lib/auditRows";
import * as BadgeTone from "./lib/badgeTone";
import * as AppSession from "./lib/appSession";
import * as FlowModel from "./lib/flowModel";

let done = false;

/** Register the security page's injected graph-platform modules by the specifiers it imports. Idempotent. */
export function registerSecurityPlatform(): void {
  if (done) return;
  done = true;
  registerAppModule("@/features/security/lib/agentProfiles", AgentProfiles);
  registerAppModule("@/features/security/lib/consoleModel", ConsoleModel);
  registerAppModule("@/features/security/lib/auditRows", AuditRows);
  registerAppModule("@/features/security/lib/badgeTone", BadgeTone);
  registerAppModule("@/features/security/lib/appSession", AppSession);
  registerAppModule("@/features/security/lib/flowModel", FlowModel);
}

runtime.features/security/index.tsx:
// Agents screen (#236, made real in #255; tab bodies split out in #1643) — permission
// profiles, console/pane assignments & an audit feed. Profiles + assignments are
// persisted in the store and ENFORCED at session launch via profileEnforcement →
// ensure_session_settings (the same gate as the role model). Shell allowlists resolve
// additively (guaranteed ∪ profile ∪ project ∪ repo); gh/git are guaranteed; a profile
// layers a base policy + per-tool tri-states + path scope. Data model + helpers live in
// ./lib; the four tab bodies in ./{Profiles,Assignments,Activity,Flow}Tab. This file is
// composition + light view state only.
import { useCallback, useMemo, useState } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import { logsTail } from "@/shared/lib/core/logsBridge";
import { slugify } from "@/shared/lib/core/format";
import { type TabItem } from "@/shared/ui/layouts/TabBar";
import { Screen } from "@/shared/ui/layouts/Screen";
import { usePageTabs } from "@/shared/hooks/usePageTabs";
import { usePromptDialog, useConfirmDialog } from "@/shared/ui/overlay/promptDialog";
import { APP_ROLES, type AgentProfile, type Tier, type ToolKey } from "./lib/agentProfiles";
import { deriveConsoles } from "./lib/consoleModel";
import {
  buildAuditRows, auditDecisionCounts, type AuditDisplayRow, type DecFilter,
} from "./lib/auditRows";
import { useAppStore } from "@/store";
import { ProfilesTab } from "./ProfilesTab";
import { AssignmentsTab } from "./AssignmentsTab";
import { ActivityTab } from "./ActivityTab";
import { FlowTab } from "./FlowTab";
import "./security.css";

// The graph-hosted workspace (#3646) — App.tsx/DetachedWindow render this via the lazy SecurityWorkspace.
export { SecurityGraphHost } from "./SecurityGraphHost";

// Re-exported for tests + back-compat: the pane-profile picker + app-session label
// helpers used to live here; they moved to ./AssignmentsTab and ./lib/appSession (#1643).
export { ProfileSelect } from "./AssignmentsTab";
export { appSessionTag, appSessionOpenLabel, appReachNote } from "./lib/appSession";

// #1545: public API for cross-feature consumers (planner, app/console, tunnel projector).
export { type AgentProfile, type Tier, type ToolKey, type ConsoleSession, type ConsolePane, APP_ROLES, PROFILES } from "./lib/agentProfiles";
export { resolveProfileSettings } from "./lib/profileEnforcement";
export { parseAuditLog, type AuditRecord } from "./lib/auditLog";
// #3754: the tunnel `security` projection derives its consoles + audit display rows the SAME way the
// desktop Security page does — one source of truth for the pane→console join and the allow/ask/block verdict.
export { deriveConsoles } from "./lib/consoleModel";
export { buildAuditRows, type AuditDisplayRow } from "./lib/auditRows";

export function SecurityWorkspace({ pageOverride }: { pageOverride?: string } = {}) {
  const [selectedId, setSelectedId] = useState("sys_planner");
  const [actDecision, setActDecision] = useState<DecFilter>("all");
  const [actConsole, setActConsole] = useState("all");

  // Persisted profiles + assignment (#255); console panes come from the real workspace.
  const profiles = useAppStore((s) => s.agentProfiles);
  const updateAgentProfile = useAppStore((s) => s.updateAgentProfile);
  const setAgentProfiles = useAppStore((s) => s.setAgentProfiles);
  const setPaneProfile = useAppStore((s) => s.setPaneProfile);
  const tabs = useAppStore((s) => s.tabs);
  const paneNames = useAppStore((s) => s.paneNames);
  const disabledPanes = useAppStore((s) => s.disabledPanes);
  const paneProfiles = useAppStore((s) => s.paneProfiles);
  const activeRepoName = useAppStore((s) => s.activeRepoName);

  // Coordination (the Flow tab): the fleet's live work-flow, cross-referenced with the
  // profile each session runs under — the Agents screen's angle on #199.
  const wakePane = useAppStore((s) => s.wakePane);

  // Application roles are app-managed singletons (display-only here).
  const roles = APP_ROLES;

  // Live console/pane model derived from the real workspace tabs (see ./lib/consoleModel).
  const consoles = useMemo(
    () => deriveConsoles({ tabs, paneNames, disabledPanes, paneProfiles, activeRepoName }),
    [tabs, paneNames, disabledPanes, paneProfiles, activeRepoName],
  );

  // Activity audit (#257): load the real per-pane tool log and derive each decision
  // from the pane's resolved gate (profile ∪ role) — the same rules the launch gate
  // applies. Refreshed while the Activity tab is open.
  const paneRoles = useAppStore((s) => s.paneRoles);
  const [auditRows, setAuditRows] = useState<AuditDisplayRow[]>([]);

  const agentDefs: TabItem[] = useMemo(() => [
    { id: "profiles", label: "Profiles", count: roles.length + profiles.length, hint: "· application + custom roles" },
    { id: "assignments", label: "Assignments", count: consoles.length, hint: "· consoles & panes" },
    { id: "activity", label: "Activity", count: auditRows.length },
    { id: "flow", label: "Flow", hint: "· coordination" },
  ], [roles.length, profiles.length, consoles.length, auditRows.length]);
  const { tabs: agentTabs, activeId, select, reorder, tearOff } = usePageTabs("security", agentDefs);
  const tab = pageOverride ?? activeId; // active section

  usePoll(async (isCancelled) => {
    if (tab !== "activity") return;
    const lines = await logsTail("audit", 300);
    const rows = buildAuditRows(lines, { consoles, profiles, paneProfiles, paneRoles });
    if (!isCancelled()) setAuditRows(rows);
  }, 3000, [tab, paneProfiles, profiles, paneRoles, consoles]);

  const find = (id: string) => [...roles, ...profiles].find((p) => p.id === id);
  const selected = find(selectedId) ?? profiles[0];

  // Resolve the profile a coordination session (a pane id like `t0p1`) runs under, so the
  // Flow tab can show who is parked and under which permission profile. Falls back to the
  // safe default when a pane has no explicit assignment.
  const profileFor = useCallback(
    (session: string): AgentProfile | undefined => find(paneProfiles[session] ?? "pf_sandbox"),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [paneProfiles, profiles],
  );

  // App-styled prompt/confirm dialogs (#1738) — replace the blocking, unstyled, untestable
  // native window.prompt/window.confirm. Each returns the value/decision as a promise; render
  // their `dialog` elements once at the page root below.
  const { prompt, dialog: promptDialog } = usePromptDialog();
  const { confirm, dialog: confirmDialog } = useConfirmDialog();

  // Edits persist to the store. Application-role ids won't match a stored profile, so
  // their controls are effectively read-only (they're system-managed).
  function setMode(m: Tier) { updateAgentProfile(selectedId, { mode: m }); }
  function setTool(t: ToolKey, v: Tier) {
    const p = find(selectedId);
    if (p) updateAgentProfile(selectedId, { tools: { ...p.tools, [t]: v } });
  }
  function removeCmd(c: string) {
    const p = find(selectedId);
    if (p) updateAgentProfile(selectedId, { commands: p.commands.filter((x) => x !== c) });
  }
  async function addCmd() {
    const v = await prompt({ title: "Allow a command", label: "Command to allow (e.g. cargo)", placeholder: "cargo", confirmLabel: "Allow" });
    const k = v?.trim().toLowerCase();
    const p = find(selectedId);
    if (k && p && !p.commands.includes(k)) updateAgentProfile(selectedId, { commands: [...p.commands, k] });
  }
  // Filesystem write-scope (#1795): add/edit/remove allow & deny globs. Mirrors addCmd/removeCmd
  // — updateAgentProfile no-ops for application-role ids (not in agentProfiles), so app roles
  // stay read-only even though find() resolves them.
  async function addPath(kind: "allow" | "deny") {
    const v = await prompt({
      title: kind === "allow" ? "Allow a write path" : "Block a path",
      label: kind === "allow" ? "Glob the agent may write to (e.g. src/**)" : "Glob the agent is blocked from (e.g. .env)",
      placeholder: kind === "allow" ? "src/**" : ".env",
      confirmLabel: kind === "allow" ? "Allow" : "Block",
    });
    const g = v?.trim();
    const p = find(selectedId);
    if (g && p && !p.paths[kind].includes(g)) updateAgentProfile(selectedId, { paths: { ...p.paths, [kind]: [...p.paths[kind], g] } });
  }
  function editPath(kind: "allow" | "deny", index: number, value: string) {
    const p = find(selectedId);
    if (!p) return;
    updateAgentProfile(selectedId, { paths: { ...p.paths, [kind]: p.paths[kind].map((g, i) => (i === index ? value : g)) } });
  }
  function removePath(kind: "allow" | "deny", index: number) {
    const p = find(selectedId);
    if (!p) return;
    updateAgentProfile(selectedId, { paths: { ...p.paths, [kind]: p.paths[kind].filter((_, i) => i !== index) } });
  }
  // Network allowlist (#1795): add/remove reachable hosts.
  async function addHost() {
    const v = await prompt({ title: "Allow a host", label: "Hostname the agent may reach (e.g. api.github.com, or * for all)", placeholder: "api.github.com", confirmLabel: "Allow" });
    const h = v?.trim();
    const p = find(selectedId);
    if (h && p && !p.net.allow.includes(h)) updateAgentProfile(selectedId, { net: { allow: [...p.net.allow, h] } });
  }
  function removeHost(host: string) {
    const p = find(selectedId);
    if (p) updateAgentProfile(selectedId, { net: { allow: p.net.allow.filter((h) => h !== host) } });
  }
  function toggleAssign(_consoleId: string, paneId: string) {
    setPaneProfile(paneId, paneProfiles[paneId] === selectedId ? null : selectedId);
  }
  function openProfile(id: string) { select("profiles"); setSelectedId(id); }

  // Create a new user profile (#259): sensible defaults, persisted, then selected.
  async function createProfile() {
    const name = (await prompt({ title: "New role", label: "Role name", placeholder: "e.g. Reviewer", confirmLabel: "Create" }))?.trim();
    if (!name) return;
    const taken = new Set(profiles.map((p) => p.id));
    const base = "pf_" + (slugify(name) || "role");
    let id = base;
    for (let n = 2; taken.has(id); n++) id = `${base}-${n}`;
    const colors = ["oklch(0.7 0.12 290)", "oklch(0.72 0.12 175)", "oklch(0.78 0.14 70)", "oklch(0.68 0.18 25)", "oklch(0.72 0.10 230)"];
    const next: AgentProfile = {
      id, name, color: colors[profiles.length % colors.length],
      category: "user", origin: "user-defined",
      desc: "Custom role.", mode: "ask", commands: [],
      tools: { read: "allow", grep: "allow", glob: "allow", edit: "ask", write: "ask", bash: "ask", web: "ask", task: "ask" },
      paths: { allow: [], deny: [] }, net: { allow: [] }, builtin: false,
    };
    setAgentProfiles([...profiles, next]);
    select("profiles");
    setSelectedId(id);
  }

  // Delete a custom profile (#259): drop it + any pane assignments pointing at it.
  async function deleteProfile(id: string) {
    const p = find(id);
    if (!p || p.category === "application" || p.builtin) return;
    if (!(await confirm({ title: "Delete role", message: `Delete the "${p.name}" role?`, danger: true, confirmLabel: "Delete" }))) return;
    setAgentProfiles(profiles.filter((x) => x.id !== id));
    for (const [paneId, pid] of Object.entries(paneProfiles)) {
      if (pid === id) setPaneProfile(paneId, null);
    }
    setSelectedId("sys_planner");
  }

  const editable = selected?.category !== "application";

  const paneTotal = consoles.reduce((a, c) => a + c.panes.length, 0);
  const { allow, ask, block } = auditDecisionCounts(auditRows);

  return (
    <Screen
      tabs={agentTabs}
      active={tab}
      onSelect={select}
      onReorder={reorder}
      onTearOff={tearOff}
      pageOverride={pageOverride}
      className="security-page"
      bodyClassName="body"
      overlay={<>{promptDialog}{confirmDialog}</>}
    >
      {tab === "profiles" && (
        <ProfilesTab
          roles={roles} profiles={profiles} consoles={consoles} selected={selected}
          onSelect={setSelectedId} setMode={setMode} setTool={setTool}
          removeCmd={removeCmd} addCmd={addCmd} toggleAssign={toggleAssign} find={find}
          addPath={addPath} editPath={editPath} removePath={removePath}
          addHost={addHost} removeHost={removeHost}
          editable={editable} onCreate={createProfile} onDelete={deleteProfile}
        />
      )}
      {tab === "assignments" && (
        <AssignmentsTab
          roles={roles} consoles={consoles} paneTotal={paneTotal}
          profiles={profiles} onAssign={(_c, paneId, profileId) => setPaneProfile(paneId, profileId)}
          onOpen={openProfile} find={find}
        />
      )}
      {tab === "activity" && (
        <ActivityTab
          rows={auditRows} consoles={consoles}
          actDecision={actDecision} setActDecision={setActDecision}
          actConsole={actConsole} setActConsole={setActConsole}
          allow={allow} ask={ask} block={block} find={find}
        />
      )}
      {tab === "flow" && (
        <FlowTab wakePane={wakePane} profileFor={profileFor} />
      )}
    </Screen>
  );
}

runtime.features/security/lib/agentProfiles.ts:
// Agents page (#236) — permission-profile data model, ported from design/Agents.html.
//
// A profile is the per-agent permission unit (#1457): its own shell-command allowlist
// (gh/git/bsc-plan guaranteed by the backend), a base policy + per-tool tri-states +
// filesystem/network scope. Assigned to console panes and applied at launch.
// Application roles (e.g. Project Planner) are always-present singleton sessions.
//
// The role/profile DEFINITIONS live as one JSON file per role under `src-tauri/data/roles/`,
// loaded at build time via `import.meta.glob` (mirrors `data/skills/`, #1715) — so the packaged
// set is data, edited without touching this module. Pure — free of React/Tauri imports so the
// resolution logic is unit-testable.

import { overlayGlob } from "@/shared/lib/core/configOverrides";

/** Tri-state permission: deny < ask < allow. */
export type Tier = "deny" | "ask" | "allow";

export type ToolKey = "read" | "grep" | "glob" | "edit" | "write" | "bash" | "web" | "task";

export interface Scope {
  allow: string[];
  deny: string[];
}

export interface AgentProfile {
  id: string;
  name: string;
  color: string;
  category: "application" | "user" | "generated";
  /** "built-in" | "user-defined" | "generated by Planner" (custom profiles). */
  origin?: string;
  desc: string;
  /** Base policy for anything not explicitly listed. */
  mode: Tier;
  /** Profile-scoped shell-command allowlist (unions with project/repo at run time). */
  commands: string[];
  tools: Record<ToolKey, Tier>;
  paths: Scope;
  net: { allow: string[] };
  builtin?: boolean;
  // Application-role only:
  surface?: string;
  surfaceGlyph?: string;
  session?: string;
  owns?: string;
}

// One JSON file per role under `src-tauri/data/roles/`, bundled at build time. Application roles
// (category "application") are the always-present singletons; every other entry is an assignable
// permission profile (the built-in set seeded into the store). Sorted by filename for a stable order.
const roleModules = import.meta.glob<{ default: AgentProfile }>("@data/roles/*.json", { eager: true });
const ALL_ROLES: AgentProfile[] = overlayGlob("roles", roleModules)
  .sort(([a], [b]) => a.localeCompare(b))
  .map(([, p]) => p);

/** Always-present, app-managed singleton sessions — not assignable to a pane. */
export const APP_ROLES: AgentProfile[] = ALL_ROLES.filter((r) => r.category === "application");

/** The assignable permission profiles (the packaged built-ins; user-created ones live in the store). */
export const PROFILES: AgentProfile[] = ALL_ROLES.filter((r) => r.category !== "application");

/** Profile ids retired from the packaged set — dropped from a persisted store on rehydrate. */
const RETIRED_PROFILE_IDS = new Set(["pf_build", "pf_docs"]);

/**
 * Reconcile a persisted profile list against the packaged built-ins (mirrors the blueprint
 * `refreshBuiltIns` migration): the built-ins always come FRESH from code (the role JSON), the
 * retired demos + any stale generated (`gen_*`) profiles are dropped, and the user's own custom
 * profiles are preserved. Run once in the store's `onRehydrateStorage`.
 */
export function reconcileBuiltInProfiles(stored: AgentProfile[]): AgentProfile[] {
  const builtinIds = new Set(PROFILES.map((p) => p.id));
  const customs = (stored ?? []).filter(
    (p) => !builtinIds.has(p.id) && p.category !== "generated" && !RETIRED_PROFILE_IDS.has(p.id),
  );
  return [...PROFILES, ...customs];
}

/** Tools rendered in the tri-state table: [key, description]. */
export const TOOL_DEFS: [ToolKey, string][] = [
  ["read", "Read files inside the repo"],
  ["grep", "Search file contents (ripgrep)"],
  ["glob", "Match files by pattern"],
  ["edit", "Modify existing files"],
  ["write", "Create or overwrite files"],
  ["bash", "Run arbitrary shell commands"],
  ["web", "Fetch URLs / browse docs"],
  ["task", "Spawn a scoped sub-agent"],
];

/** Commands the backend guarantees for every session (can't be removed). */
export const GUARANTEED = ["gh", "git"];

export interface ConsolePane {
  id: string;
  agent: string;
  status: "running" | "awaiting" | "idle";
  profileId: string;
}

export interface ConsoleSession {
  id: string;
  name: string;
  repo: string;
  status: string;
  projectAllow: string[];
  repoAllow?: string[];
  panes: ConsolePane[];
}

// ── Resolution helpers (pure) ───────────────────────────────────────────────────

/** Look up a profile or application role by id. */
export function findProfile(id: string): AgentProfile | undefined {
  return [...APP_ROLES, ...PROFILES].find((p) => p.id === id);
}

export interface ResolvedCommand {
  cmd: string;
  origin: "guaranteed" | "profile" | "project" | "repo";
}

/**
 * Resolve the effective shell allowlist from already-resolved objects: guaranteed ∪
 * profile ∪ console project ∪ console repo, deduped (case-insensitive), in precedence
 * order. The live UI calls this with its in-component (edited) copies.
 */
export function resolveAllowlistFrom(
  con: ConsoleSession | undefined,
  pf: AgentProfile | undefined,
): ResolvedCommand[] {
  const seen = new Set<string>();
  const out: ResolvedCommand[] = [];
  const push = (arr: string[] | undefined, origin: ResolvedCommand["origin"]) => {
    for (const c of arr ?? []) {
      const k = c.trim().toLowerCase();
      if (k && !seen.has(k)) { seen.add(k); out.push({ cmd: k, origin }); }
    }
  };
  push(GUARANTEED, "guaranteed");
  push(pf?.commands, "profile");
  push(con?.projectAllow, "project");
  push(con?.repoAllow, "repo");
  return out;
}

/** Number of panes governed by a profile across the given consoles. */
export function paneCount(profileId: string, consoles: ConsoleSession[]): number {
  return consoles.reduce((n, c) => n + c.panes.filter((p) => p.profileId === profileId).length, 0);
}

/** Number of consoles that have at least one pane on a profile. */
export function consoleCount(profileId: string, consoles: ConsoleSession[]): number {
  return consoles.filter((c) => c.panes.some((p) => p.profileId === profileId)).length;
}

export const MODE_LABEL: Record<Tier, string> = {
  deny: "Deny by default",
  ask: "Ask each time",
  allow: "Allow all",
};

