runtime.features/skills/LessonsTab.tsx:
// The "Pending lessons" review queue (#1362) — a tab in the Skills screen. Self-correction candidates
// an agent captured with `bsc-learned` (mistake → cause → rule) land in the active project's plan.db;
// here the USER reviews them and confirms one into a project-scoped skill or discards it. Only the
// user advances a lesson — mirroring the platform's "only the user confirms" posture. A confirmed
// lesson becomes a `review`-kind skill scoped to the project (globalize it later via the normal
// skill-scope UI, the #1338 promote path).

import { useState, useEffect, useCallback } from "react";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";
import { Box } from "@/shared/ui/layout/Box";
import { Grid } from "@/shared/ui/layout/Grid";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";
import { TextField } from "@/shared/ui/controls/Field";
import { useAppStore } from "@/store";
import {
  loadPendingLessons, confirmLesson, discardLesson, lessonToSkill, type Lesson,
} from "./lib/lessons";

/** A loading placeholder shaped like a {@link LessonCard} — two text lines + a trailing action row (#2245). */
function LessonSkeleton() {
  return (
    <Grid gap={8} style={{ border: "1px solid var(--border-soft)", borderRadius: 6, padding: "10px 12px", background: "var(--bg-elev)" }}>
      <Skeleton h={13} w="72%" />
      <Skeleton h={12} w="54%" />
      <Row gap={8}><Box as="span" style={{ flex: 1 }} /><Skeleton w={56} h={22} /><Skeleton w={56} h={22} /></Row>
    </Grid>
  );
}

/** One reviewable candidate, with inline edit of the mistake/rule before it's confirmed into a skill. */
function LessonCard({ lesson, projectKey, onResolved }: { lesson: Lesson; projectKey: string; onResolved: () => void }) {
  const upsertSkills = useAppStore((s) => s.upsertSkills);
  const [editing, setEditing] = useState(false);
  const [mistake, setMistake] = useState(lesson.mistake);
  const [rule, setRule] = useState(lesson.rule);
  const [busy, setBusy] = useState(false);

  const confirm = useCallback(async () => {
    setBusy(true);
    // Build the project skill from the (possibly edited) text, then record the verdict.
    const skill = lessonToSkill({ ...lesson, mistake, rule }, projectKey);
    if (skill) upsertSkills([skill]);
    await confirmLesson(projectKey, lesson.id);
    onResolved();
  }, [lesson, mistake, rule, projectKey, upsertSkills, onResolved]);

  const discard = useCallback(async () => {
    setBusy(true);
    await discardLesson(projectKey, lesson.id);
    onResolved();
  }, [lesson.id, projectKey, onResolved]);

  return (
    <Grid gap={8} style={{ border: "1px solid var(--border-soft)", borderRadius: 6, padding: "10px 12px", background: "var(--bg-elev)" }}>
      {editing ? (
        <>
          <TextField value={mistake} onChange={setMistake} placeholder="what went wrong" style={{ fontSize: 12 }} />
          <TextField value={rule} onChange={setRule} placeholder="the corrective rule" style={{ fontSize: 12 }} />
        </>
      ) : (
        <Grid gap={3}>
          <Box as="span" className="mono-value">{mistake || <Box as="span" className="hint">(no mistake)</Box>}</Box>
          <Text as="span" mono size={12} tone="accent">→ {rule || <Box as="span" className="hint">(no rule)</Box>}</Text>
          {lesson.cause.trim() && <Text as="span" className="hint" size={11}>{lesson.cause}</Text>}
        </Grid>
      )}
      <Row gap={8} style={{ fontSize: 11 }}>
        {lesson.seen > 1 && <Box as="span" className="pill" bg="var(--bg-panel)" style={{ color: "var(--fg-muted)" }}>seen ×{lesson.seen}</Box>}
        {lesson.provenance && <Box as="span" className="hint" style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{lesson.provenance}</Box>}
        <Box as="span" style={{ flex: 1 }} />
        <Button variant="ghost" disabled={busy} onClick={() => setEditing((e) => !e)}>{editing ? "done editing" : "edit"}</Button>
        <Button variant="ghost" disabled={busy} onClick={discard}>discard</Button>
        <Button disabled={busy} onClick={confirm}>confirm</Button>
      </Row>
    </Grid>
  );
}

/** The pending-lessons queue for the active project. `projectKey` empty ⇒ a prompt to pick a project. */
export function LessonsTab({ projectKey, projectName }: { projectKey: string; projectName?: string }) {
  const [lessons, setLessons] = useState<Lesson[]>([]);
  // Start loading when there's a project to fetch, so the first paint shows skeletons rather than a
  // one-frame "Nothing to review" flash before the effect fires the fetch (#2245).
  const [loading, setLoading] = useState(!!projectKey);

  const refresh = useCallback(() => {
    if (!projectKey) { setLessons([]); return; }
    setLoading(true);
    void loadPendingLessons(projectKey).then((ls) => { setLessons(ls); setLoading(false); });
  }, [projectKey]);

  useEffect(() => { refresh(); }, [refresh]);

  return (
    <Box as="section" className="an-page"><Box className="an-wrap">
      <Text as="h2" mono size="xl" style={{ margin: "0 0 4px" }}>Pending lessons</Text>
      <Text as="div" tone="muted" size={12} style={{ marginBottom: 14 }}>
        Mistakes agents caught with <code>bsc-learned</code>{projectName ? <> in <b>{projectName}</b></> : null} — confirm one into a project skill, or discard it. Only you confirm.
      </Text>

      {!projectKey ? (
        <EmptyState title="No active project" description="Open a project to review the lessons its agents have captured. Lessons are scoped to the project that produced them." />
      ) : loading ? (
        <Grid gap={10}>{Array.from({ length: 3 }).map((_, i) => <LessonSkeleton key={i} />)}</Grid>
      ) : lessons.length === 0 ? (
        <EmptyState title="Nothing to review" description={<>When an agent catches a mistake it runs <code>bsc-learned "&lt;what&gt;" --rule "&lt;fix&gt;"</code> and the candidate lands here for you to confirm. Recurring captures bump a "seen" counter instead of piling up.</>} />
      ) : (
        <Grid gap={10}>
          {lessons.map((l) => <LessonCard key={l.id} lesson={l} projectKey={projectKey} onResolved={refresh} />)}
        </Grid>
      )}
    </Box></Box>
  );
}

runtime.features/skills/lib/lessons.ts:
// Self-correction lessons — the frontend side of #1362. A lesson is a mistake an agent caught
// mid-session (captured by the `bsc-learned` helper into the project's plan.db); the user reviews the
// pending queue here and confirms it into a project skill or discards it. These drive the SAME
// `bsc plan lesson …` verbs the planner/agents use, through the generic `bsc` bridge (#2114/#2115) —
// UI↔planner parity over one store surface (they replaced the per-verb `plan_lesson_*` Tauri commands).
//
// Kept Tauri-light + React-free so the mapping helpers are unit-testable; the LessonsTab component
// does the rendering. Mirrors how skillBridge.ts isolates the skilldb bridge.

import { bscJson, bscRun } from "@/shared/lib/core/bsc";
import { truncate } from "@/shared/lib/core/format";
import { blankSkill, skillSlug, type SkillDef } from "./skills";

/** A captured lesson candidate — mirrors the Rust `plandb::Lesson` (camelCase). */
export interface Lesson {
  id: string;
  /** What went wrong. */
  mistake: string;
  /** Why it happened (optional). */
  cause: string;
  /** The corrective rule a future agent should follow. */
  rule: string;
  /** Origin tag set by the capture helper (`pane …, repo …`). */
  provenance: string;
  /** `pending` | `confirmed` | `discarded`. */
  status: string;
  /** How many times this same lesson was captured (dedup counter). */
  seen: number;
  createdAt: number;
  updatedAt: number;
}

/** The project's pending lesson candidates (the review queue). Returns [] when the bridge is absent
 *  (no Tauri host / no plan.db) so the UI degrades to an empty queue rather than throwing. */
export async function loadPendingLessons(projectKey: string): Promise<Lesson[]> {
  if (!projectKey) return [];
  // `bsc plan lesson list --status pending` emits the JSON array (the same `Vec<Lesson>` serde shape
  // the old `plan_lesson_list` command returned); bscJson degrades to [] when plan.db doesn't exist yet.
  return bscJson<Lesson[]>(projectKey, ["plan", "lesson", "list", "--status", "pending"], []);
}

/** Mark a candidate confirmed (the user accepted it). The caller also materializes it as a skill. */
export async function confirmLesson(projectKey: string, id: string): Promise<void> {
  await bscRun(projectKey, ["plan", "lesson", "confirm", id]);
}

/** Mark a candidate discarded (kept as a record; its seen count still grows if it recurs). */
export async function discardLesson(projectKey: string, id: string): Promise<void> {
  await bscRun(projectKey, ["plan", "lesson", "discard", id]);
}

/** A confirmed lesson's display title — the corrective rule (the actionable part), else the mistake,
 *  capped so it slugs to a sane skill directory name. */
export function lessonTitle(lesson: Pick<Lesson, "mistake" | "rule">): string {
  const base = (lesson.rule.trim() || lesson.mistake.trim()).replace(/\s+/g, " ");
  return truncate(base, 64, 61);
}

/**
 * Map a confirmed {@link Lesson} to a **project-scoped** {@link SkillDef} (the resolver then attaches
 * it to that project's future sessions). The skill is a `review`-kind corrective check: its body is
 * the transferable mistake → rule, scoped to `projectKey` (the user can later globalize it via the
 * normal skill-scope UI — that's the "promote to global" path, #1338). A stable id derived from the
 * lesson id keeps a re-confirm idempotent. Returns `null` when the lesson has nothing to name.
 */
export function lessonToSkill(lesson: Lesson, projectKey: string): (Omit<SkillDef, "id"> & { id: string }) | null {
  const name = lessonTitle(lesson);
  if (!skillSlug(name)) return null;
  const body = [
    lesson.mistake.trim() && `When: ${lesson.mistake.trim()}`,
    lesson.cause.trim() && `Why: ${lesson.cause.trim()}`,
    lesson.rule.trim() && `Do: ${lesson.rule.trim()}`,
  ].filter(Boolean).join("\n");
  return {
    ...blankSkill(),
    id: `lesson-skill-${lesson.id}`,
    name,
    kind: "review",
    source: "first-party",
    desc: lesson.mistake.trim() || lesson.rule.trim(),
    prompt: body,
    projects: projectKey ? [projectKey] : [],
    enabled: true,
  };
}

runtime.features/skills/lib/skillBridge.ts:
// The frontend ↔ global skills.db bridge (#1338 ph2). The desktop Skills library and every live
// console session share ONE global store (`~/.base-studio-code/skills.db`), reached here — and from a
// session's own shell — through the SAME `bsc skill …` CLI, over the generic `bsc` bridge (#2114/#2142;
// it replaced the parallel per-verb `skill_store_*`/`skill_group_*` Tauri commands). Skills are GLOBAL
// (no project key) so every call passes `null` as the bridge's `projectKey`. This is the only place the
// skills feature touches Tauri, so the pure model in `skills.ts` stays React/Tauri-free.
//
// Source-of-truth: skills.db. The Zustand slice is a write-through cache — `loadLibrary` hydrates it
// on boot; each library mutation pushes through here. Per-session toggles (overrides / toggled-on
// groups) are NOT part of the global library and stay store-local; only skills + groups round-trip.
//
// Mapping: the Rust `Skill` omits the display-only telemetry (`invocations`/`success`/`avgTokensK`/
// `trend`), so a loaded skill is re-defaulted to a full {@link SkillDef} here; pushing a SkillDef is
// serde-safe because the Rust side ignores the extra telemetry fields. `list --full` (#2142) emits the
// COMPLETE skill objects (prompt + tools/profiles/packaged), matching the old `skill_store_list` shape
// — the lean paginated `list` would drop the `prompt` body that a write-through would then blank.

import { bsc, bscRun, bscWrite } from "@/shared/lib/core/bsc";
import type { SkillDef, SkillGroup } from "./skills";
import type { SkillKind, SkillSource, SkillProfile } from "@/shared/data/skills";

/** The library as stored in skills.db (telemetry re-defaulted to zero on the way in). */
export interface Library {
  skills: SkillDef[];
  groups: SkillGroup[];
}

/** A skill row from the bridge → a full {@link SkillDef} (zero telemetry; packaged defaults false). */
function toDef(s: Partial<SkillDef> & { id: string; name: string }): SkillDef {
  return {
    id: s.id,
    name: s.name,
    kind: (s.kind as SkillKind) ?? "workflow",
    source: (s.source as SkillSource) ?? "first-party",
    desc: s.desc ?? "",
    prompt: s.prompt ?? "",
    tools: s.tools ?? [],
    profiles: (s.profiles as SkillProfile[]) ?? [],
    projects: s.projects ?? [],
    enabled: !!s.enabled,
    pinned: !!s.pinned,
    packaged: !!s.packaged,
    invocations: 0, success: 0, avgTokensK: 0, trend: [],
  };
}

/**
 * Hydrate the library from skills.db. Returns `null` when the bridge is unreachable (no Tauri host —
 * tests, the web shell, or an old binary), so the caller keeps its seeded in-memory set rather than
 * blanking the UI. Any single bad row is tolerated (the command itself either succeeds with the full
 * set or rejects).
 */
export async function loadLibrary(): Promise<Library | null> {
  // NOT `bscJson` here: its graceful degrade-to-fallback would return an EMPTY library when the bridge
  // is unreachable, and hydrate would then blank the seeded set. We need the explicit `null` (keep the
  // seeded set) the store depends on — so raw `bsc` + catch, exactly like the old per-command version.
  try {
    const [skillsOut, groupsOut] = await Promise.all([
      bsc(null, ["skill", "list", "--full"]), // full-fidelity array (incl. prompt) — the #2142 read
      bsc(null, ["skill", "group", "list"]),
    ]);
    const skills = JSON.parse(skillsOut.trim() || "[]") as Array<Partial<SkillDef> & { id: string; name: string }>;
    const groups = JSON.parse(groupsOut.trim() || "[]") as SkillGroup[];
    return { skills: (skills ?? []).map(toDef), groups: groups ?? [] };
  } catch {
    return null;
  }
}

/** Write-through a skill upsert (`bsc skill add` reads the JSON on stdin). Fire-and-forget; never throws. */
export async function pushSkill(skill: SkillDef): Promise<void> {
  await bscWrite(null, ["skill", "add"], skill);
}

/** Write-through a skill removal (`bsc skill remove <id>`). */
export async function dropSkill(id: string): Promise<void> {
  await bscRun(null, ["skill", "remove", id]);
}

/** Write-through a group upsert (`bsc skill group add` reads the JSON on stdin). */
export async function pushGroup(group: SkillGroup): Promise<void> {
  await bscWrite(null, ["skill", "group", "add"], group);
}

/** Write-through a group removal (`bsc skill group remove <id>`). */
export async function dropGroup(id: string): Promise<void> {
  await bscRun(null, ["skill", "group", "remove", id]);
}

runtime.features/skills/lib/skillGroups.ts:
// Task groups (#skills-groups): named, reusable bundles of skills toggled as one,
// their expansion into a member-id set, membership counting, and the planner's
// `skill_groups.json` parser.

import { skillSlug, type SkillDef } from "./skillsModel";

// ── Task groups (#skills-groups) ────────────────────────────────────────────────
// A "task group" is a named, reusable bundle of skills (the redesign's ⬡). Many-to-many with
// skills (a skill can belong to several groups), keyed by stable skill id. A group is the unit of
// bulk toggling: toggle a group onto a session (manually, Workspace B) or onto a fleet stream (the
// planner) and every member skill is enabled at once. Groups are LIVE references — editing a
// group's membership updates every session/stream that has it on, rather than freezing the set.

/** A named bundle of skills, toggled as one. */
export interface SkillGroup {
  id: string;
  name: string;
  /** Accent hue (a `--token` ref or oklch literal) for the group's ⬡ chip/tile. */
  hue: string;
  /** Member skill ids (stable — never names, which can change). */
  skillIds: string[];
}

/** The DISTINCT member skill ids across a set of enabled group ids (order-stable, de-duped). An
 *  unknown group id contributes nothing. Used to expand a session's/stream's toggled-on groups
 *  into the `groupSkillIds` set that {@link effectiveSessionSkills} folds in. */
export function expandGroups(groupIds: readonly string[], groups: SkillGroup[]): string[] {
  const byId = new Map(groups.map((g) => [g.id, g]));
  const out = new Set<string>();
  for (const gid of groupIds) for (const sid of byId.get(gid)?.skillIds ?? []) out.add(sid);
  return [...out];
}

/** Membership count of a group whose member skills still exist in `all` (the chip count). */
export function groupSkillCount(group: SkillGroup, all: SkillDef[]): number {
  const ids = new Set(all.map((s) => s.id));
  return group.skillIds.filter((id) => ids.has(id)).length;
}

/** Parse the planner's `skill_groups.json` (a JSON array of `{name, hue?, skills?: string[]}`) into
 *  clean groups. `skills` may be skill ids OR name-slugs (the planner authors by name); they're
 *  resolved against the library here so the stored group keys by id. Tolerant: malformed input →
 *  []; a row without a usable name is dropped. Mirrors {@link parseSkillsFile}. */
export function parseSkillGroupsFile(raw: string, all: SkillDef[]): Array<Omit<SkillGroup, "id"> & { id?: string }> {
  let data: unknown;
  try { data = JSON.parse(raw); } catch { return []; }
  if (!Array.isArray(data)) return [];
  const bySlug = new Map(all.map((s) => [skillSlug(s.name), s.id]));
  const byId = new Set(all.map((s) => s.id));
  const out: Array<Omit<SkillGroup, "id"> & { id?: string }> = [];
  for (const row of data) {
    if (!row || typeof row !== "object") continue;
    const r = row as Record<string, unknown>;
    const name = typeof r.name === "string" ? r.name.trim() : "";
    if (!name) continue;
    const refs = Array.isArray(r.skills) ? r.skills.filter((x): x is string => typeof x === "string") : [];
    const skillIds = Array.from(new Set(
      refs.map((ref) => (byId.has(ref) ? ref : bySlug.get(skillSlug(ref)))).filter((x): x is string => !!x),
    ));
    out.push({
      id: typeof r.id === "string" && r.id ? r.id : undefined,
      name,
      hue: typeof r.hue === "string" && r.hue ? r.hue : "var(--accent)",
      skillIds,
    });
  }
  return out;
}

