runtime.features/sounds/lib/crossGraphAdapter.ts:
// Cross-graph adapter (#3117, epic #3114) — the Sounds feature's map from its OWN store shape (a
// `SoundKit`) onto the feature-agnostic {@link NodeLookup} the shared cross-graph resolver composes,
// mirroring the Algorithms adapter (`algorithms/lib/crossGraphAdapter.ts`, #3116). The three pillars stay
// decoupled: `shared/lib/graph/crossGraph` knows nothing about a `SoundKit`; THIS module adapts it, and the
// consumer (the Design Studio preview + component graph, `designs/lib/libraryModules.ts`) wires it via
// `makeUrnResolver`. Pure + React-free.
//
// A node URN's `kit` is, for the sound graph, a SoundKit id (`signal`) and its `id` is the in-kit node id.
// A `@bsc/sounds/<id>` import a component author writes is KIT-LESS — the consumer picks the kit (the
// DEFAULT sound kit). `<id>` names, in priority order:
//   • a CUE (the playable product; primary) → `code` is a self-contained player module (`cuePlayerModule`),
//   • else a VOICE (a playable patch) → `code` is a player module for a synthetic one-shot cue of it,
//   • else a PRIMITIVE (a raw source descriptor) → resolves but carries NO `code`, so it's not
//     importable/vendorable — mirroring an algorithm primitive (a descriptor, not code).
// A sound has no JS source, so unlike an algorithm (whose `code` is real, vendored verbatim) the `code`
// here is SYNTHESIZED at resolve time — the one place a cue becomes a runnable module.
import type { NodeLookup, ResolvedNode } from "@/shared/lib/graph/crossGraph";
import type { Cue, SoundKit } from "./soundDescriptor";
import { BUILTIN_KITS } from "./soundKits";
import { cuePlayerModule } from "./cuePlayerModule";

/** A synthetic one-shot cue wrapping a single voice — so a VOICE (a playable patch) is importable +
 *  playable exactly like a cue: its emitted `code` is a player module for this one-layer wrapper. */
function voiceAsCue(voiceId: string, name: string): Cue {
  return { id: voiceId, name, category: "ui", layers: [{ voice: voiceId, at: 0 }] };
}

/**
 * A {@link NodeLookup} over the sound library for the `sound` graph. Given a `kit` (a SoundKit id) and an
 * in-kit `id`, resolve — in priority order — a CUE, else a VOICE, else a PRIMITIVE, to its
 * {@link ResolvedNode}, or `null` on a miss. Defaults to the packaged {@link BUILTIN_KITS}; a caller can
 * pass the live-hydrated kits. The returned node's `urn`/`graph`/`kit`/`id` are placeholders —
 * `makeUrnResolver` overwrites them from the URN — so only `label`/`kind`/`code` carry through (`id` is set
 * to the matched node's id so a caller can canonicalize the URN). A cue/voice carries the vendorable player
 * module in `code`; a primitive carries none (a descriptor). A broken kit (a dangling composes edge) makes
 * the player emit throw → this returns `null` rather than letting the resolver throw.
 */
export function soundNodeLookup(kits: SoundKit[] = BUILTIN_KITS): NodeLookup {
  return (kitId: string, id: string): ResolvedNode | null => {
    const kit = kits.find((k) => k.id === kitId);
    if (!kit) return null;

    // Build a resolved node; when `playable` is supplied, synthesize its self-contained player module as
    // `code` (a throw during compile — a broken kit — collapses to a clean miss).
    const resolved = (kind: string, label: string, playable: Cue | null): ResolvedNode | null => {
      let code: string | undefined;
      if (playable) {
        try {
          code = cuePlayerModule(playable, kit);
        } catch {
          return null;
        }
      }
      return { urn: "", graph: "sound", kit: kitId, id, label, kind, code };
    };

    const cue = kit.cues.find((c) => c.id === id);
    if (cue) return resolved("cue", cue.name, cue);
    const voice = kit.voices.find((v) => v.id === id);
    if (voice) return resolved("voice", voice.name, voiceAsCue(voice.id, voice.name));
    const prim = kit.primitives.find((p) => p.id === id);
    if (prim) return resolved("primitive", prim.name, null); // a descriptor — no code, not importable
    return null;
  };
}

runtime.features/sounds/lib/cuePlayerModule.ts:
// Self-contained sound-cue player emit (#3117, epic #3114) — the Sounds analog of an algorithm's
// vendorable `code` (libraryModules.ts, #3116). An algorithm ships real JS `code` the preview vendors
// verbatim; a sound has NO JS source, so we can't vendor a file. Instead we COMPILE the cue here (synth.ts
// `compileCue`) and EMIT A STRING that is a self-contained ES module: it embeds the resulting flat
// `SCHEDULE` and inlines a MINIMAL Web Audio player ported from `synth.ts` — the preview iframe runs in
// isolation and canNOT import the app's `synth`, so the player must travel with the cue. Pure — no Web
// Audio, no React (the emitted STRING touches Web Audio only when its `play()` runs inside the preview).
//
// EXPORT API (what a component author binds): `import { play } from "@bsc/sounds/<id>"` — `play()` plays
// the cue now and returns its duration in seconds (0 where Web Audio is unavailable — a safe no-op in
// SSR/jsdom), reading naturally in an `onClick={() => play()}`. A DEFAULT export mirrors it, so
// `import play from "@bsc/sounds/<id>"` binds too.
import { compileCue } from "./synth";
import type { Cue, SoundKit } from "./soundDescriptor";

/** The static player runtime inlined into every emitted module — a minimal port of synth.ts's
 *  `getCtx`/`whiteNoise`/`scheduleVoice`/`playCue` that reads the pre-compiled `SCHEDULE` the emit prepends.
 *  Kept as ONE literal so the emit is just `SCHEDULE` + this. MUST stay behaviorally in lockstep with
 *  `synth.ts` (the desktop player) — both realize the same compiled schedule on a Web Audio graph. */
const PLAYER_RUNTIME = `
let __ctx = null;
let __noise = null;

function __getCtx() {
  if (typeof window === "undefined") return null;
  const Ctor = window.AudioContext || window.webkitAudioContext;
  if (!Ctor) return null;
  if (!__ctx) __ctx = new Ctor();
  if (__ctx.state === "suspended") __ctx.resume();
  return __ctx;
}

function __whiteNoise(ctx) {
  if (__noise && __noise.sampleRate === ctx.sampleRate) return __noise;
  const buf = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
  __noise = buf;
  return buf;
}

function __scheduleVoice(ctx, v, t0) {
  const start = t0 + v.startAt;
  const { attack, decay, sustain, release } = v.env;
  const peak = Math.max(0.0001, v.gain);

  const amp = ctx.createGain();
  amp.gain.setValueAtTime(0.0001, start);
  amp.gain.linearRampToValueAtTime(peak, start + attack);
  amp.gain.linearRampToValueAtTime(Math.max(0.0001, sustain * peak), start + attack + decay);
  amp.gain.linearRampToValueAtTime(0.0001, start + attack + decay + release);

  let node;
  if (v.source === "noise") {
    const src = ctx.createBufferSource();
    src.buffer = __whiteNoise(ctx);
    src.loop = true;
    node = src;
  } else {
    const osc = ctx.createOscillator();
    osc.type = v.waveform;
    osc.detune.setValueAtTime(v.detune, start);
    osc.frequency.setValueAtTime(v.freq, start);
    if (v.pitchTo != null && v.pitchTo !== v.freq) {
      osc.frequency.linearRampToValueAtTime(v.pitchTo, start + v.duration);
    }
    node = osc;
  }

  let tail = node;
  if (v.filter) {
    const f = ctx.createBiquadFilter();
    f.type = v.filter.type;
    f.frequency.setValueAtTime(v.filter.cutoff, start);
    tail.connect(f);
    tail = f;
  }
  tail.connect(amp);
  amp.connect(ctx.destination);

  node.start(start);
  node.stop(start + v.duration + 0.02);
}

/** Play the cue now; returns its duration in seconds (0 where Web Audio is unavailable — a safe no-op). */
export function play() {
  const ctx = __getCtx();
  if (!ctx) return 0;
  const t0 = ctx.currentTime + 0.02;
  for (const v of SCHEDULE.voices) __scheduleVoice(ctx, v, t0);
  return SCHEDULE.duration;
}

export default play;
`;

/**
 * Emit a self-contained ES module (as a string) that plays `cue` — the vendorable "code" for a sound the
 * Design Studio preview imports as `@bsc/sounds/<id>` (#3117). Compiles `cue` against `kit` (synth.ts
 * `compileCue`) and embeds the resulting flat `SCHEDULE` ahead of the inlined {@link PLAYER_RUNTIME}.
 * Deterministic + pure.
 *
 * Throws only when the kit has a DANGLING composes edge (a broken user kit) — the packaged kits are
 * test-guarded, so the caller (the sounds `NodeLookup`) treats a throw as "not resolvable" and returns
 * `null`, exactly as an algorithm primitive (no `code`) is not vendorable.
 */
export function cuePlayerModule(cue: Cue, kit: SoundKit): string {
  const compiled = compileCue(cue, kit);
  const header =
    `// Generated player for the "${cue.name}" sound cue (@bsc/sounds/${cue.id}) — self-contained, no app\n` +
    `// imports (#3117). Embeds the compiled schedule + a minimal Web Audio player.\n`;
  return `${header}const SCHEDULE = ${JSON.stringify(compiled)};\n${PLAYER_RUNTIME}`;
}

