// The Sounds pillar's data model (#3072, epic #3071) — a sound is SYNTHESIZED from a descriptor, not a
// binary file, so it's diffable, seedable, and live-playable (Web Audio), exactly like a component's
// srcText or an algorithm's concept-IS-impl. The model is a composition graph mirroring the sibling
// pillars: Primitive → Voice → Cue.
//
//   Primitive — the base sound SOURCE (an oscillator or noise). The graph's Fundamentals band.
//   Voice     — a playable PATCH built on ONE primitive: pitch (+ optional sweep), an ADSR envelope,
//               an optional filter, and a peak gain. The Composables band; `primitive` is a composes edge.
//   Cue       — a UI-mapped SOUND: one or more voices LAYERED/SEQUENCED (each at an offset). The
//               "components" of this pillar; `layers[].voice` are composes edges.
//   SoundKit  — a cohesive named set a project adopts wholesale (its primitives + voices + cues).
//
// This module is PURE (no Web Audio, no React) — the synth compiler (`synth.ts`) turns a Cue into a flat
// schedule, and only the thin `playCue` touches the browser audio graph.

/** Oscillator wave shapes — the Web Audio `OscillatorNode` types. */
export type Waveform = "sine" | "square" | "sawtooth" | "triangle";

/** Where a cue sits in the library — drives the rail grouping (and, later, the graph swimlanes). */
export type SoundCategory = "ui" | "notify" | "transition" | "ambient" | "musical";

export const SOUND_CATEGORIES: readonly SoundCategory[] = ["ui", "notify", "transition", "ambient", "musical"];

/** Human labels for the categories (rail headers + inspector). */
export const CATEGORY_LABEL: Record<SoundCategory, string> = {
  ui: "UI feedback",
  notify: "Notifications",
  transition: "Transitions",
  ambient: "Ambient",
  musical: "Musical",
};

/** An ADSR-style one-shot envelope. Times in SECONDS; `sustain` is a 0..1 level (no sustain-hold time —
 *  a cue is one-shot, so release begins right after decay). A voice's duration = attack + decay + release. */
export interface Envelope {
  attack: number;
  decay: number;
  /** Level (0..1) held at the decay→release junction. */
  sustain: number;
  release: number;
}

/** A base sound source. `waveform` applies to `kind: "osc"`; `noise` is white noise (waveform ignored). */
export interface Primitive {
  id: string;
  name: string;
  kind: "osc" | "noise";
  waveform?: Waveform;
}

/** A tone filter applied to a voice. */
export interface VoiceFilter {
  type: "lowpass" | "highpass" | "bandpass";
  /** Cutoff / center frequency in Hz. */
  cutoff: number;
}

/** A playable patch built on exactly one primitive. */
export interface Voice {
  id: string;
  name: string;
  /** Primitive.id this voice is built on (the `composes` edge). */
  primitive: string;
  /** Base frequency in Hz (ignored for a noise primitive). */
  freq: number;
  /** Optional end frequency — the voice GLIDES freq→pitchTo over its life (a sweep/zap). */
  pitchTo?: number;
  /** Fine detune in cents. */
  detune?: number;
  env: Envelope;
  filter?: VoiceFilter;
  /** Peak gain, 0..1. */
  gain: number;
}

/** One voice within a cue, started at `at` seconds from the cue's start (0 = together = a layer). */
export interface CueLayer {
  /** Voice.id (the `composes` edge). */
  voice: string;
  at: number;
}

/** A UI-mapped sound: layered/sequenced voices. */
export interface Cue {
  id: string;
  name: string;
  category: SoundCategory;
  layers: CueLayer[];
}

/** A cohesive named library of sounds a project adopts wholesale. */
export interface SoundKit {
  id: string;
  name: string;
  primitives: Primitive[];
  voices: Voice[];
  cues: Cue[];
}

/**
 * Dangling-reference check for a kit — the dependency-integrity guard behind the playable UI (and, later,
 * a `bsc sound doctor`). Returns a human-readable problem per broken `composes` edge (a voice on a missing
 * primitive, a cue layer on a missing voice) or an empty layer; empty ⇒ the kit compiles + plays cleanly.
 */
export function validateKit(kit: SoundKit): string[] {
  const problems: string[] = [];
  const primIds = new Set(kit.primitives.map((p) => p.id));
  const voiceIds = new Set(kit.voices.map((v) => v.id));
  for (const v of kit.voices) {
    if (!primIds.has(v.primitive)) problems.push(`voice "${v.id}" composes a missing primitive "${v.primitive}"`);
  }
  for (const c of kit.cues) {
    if (c.layers.length === 0) problems.push(`cue "${c.id}" has no layers`);
    for (const l of c.layers) {
      if (!voiceIds.has(l.voice)) problems.push(`cue "${c.id}" layers a missing voice "${l.voice}"`);
    }
  }
  return problems;
}

runtime.features/sounds/lib/soundGraph.ts:
// The Sounds composition graph (#3077, Phase 2) — turns a SoundKit into a node/edge graph laid out in
// tier COLUMNS, the same shape as the Algorithms kit graph (`layoutKitGraph`) and the Designs graph:
// Primitives at the base (left), Voices next, Cues last (right), wired by `composes` edges
// (Cue→Voice→Primitive). Pure + deterministic — the canvas/rail/inspector all read this.
import type { Cue, SoundCategory, SoundKit } from "./soundDescriptor";

export type SoundNodeKind = "primitive" | "voice" | "cue";

/** A graph node. `id` is namespaced by kind (`p:`/`v:`/`c:`) so a primitive + cue sharing a raw id never
 *  collide; `refId` is the original id for kit lookups + playback. */
export interface SoundNode {
  id: string;
  kind: SoundNodeKind;
  label: string;
  refId: string;
  /** Cues only — drives the node tint + rail grouping. */
  category?: SoundCategory;
}

/** A `composes` edge, from the composer to the composed (Cue→Voice, Voice→Primitive). */
export interface SoundEdge { id: string; from: string; to: string }

export interface SoundGraph { nodes: SoundNode[]; edges: SoundEdge[] }

export interface NodePos { x: number; y: number }
export interface SoundLayout {
  pos: Map<string, NodePos>;
  world: { w: number; h: number };
  bounds: { x: number; y: number; w: number; h: number };
}

/** Node box size (world px) — shared by the layout and the canvas card (matches the Algorithms graph). */
export const NODE_W = 172;
export const NODE_H = 58;
const COL_PITCH = NODE_W + 208;
const ROW_PITCH = NODE_H + 22;
const PAD = 48;

/** Namespaced node ids — kept in one place so build + edge wiring agree. */
export const primNodeId = (id: string) => `p:${id}`;
export const voiceNodeId = (id: string) => `v:${id}`;
export const cueNodeId = (id: string) => `c:${id}`;

/** Column tier: primitives are the base (0), voices 1, cues 2 — so the graph flows base→product, L→R. */
export function nodeTier(kind: SoundNodeKind): number {
  return kind === "primitive" ? 0 : kind === "voice" ? 1 : 2;
}

/** Build the composition graph for a kit — every primitive/voice/cue a node, every `composes` an edge. */
export function buildSoundGraph(kit: SoundKit): SoundGraph {
  const nodes: SoundNode[] = [
    ...kit.primitives.map((p): SoundNode => ({ id: primNodeId(p.id), kind: "primitive", label: p.name, refId: p.id })),
    ...kit.voices.map((v): SoundNode => ({ id: voiceNodeId(v.id), kind: "voice", label: v.name, refId: v.id })),
    ...kit.cues.map((c): SoundNode => ({ id: cueNodeId(c.id), kind: "cue", label: c.name, refId: c.id, category: c.category })),
  ];
  const edges: SoundEdge[] = [];
  const seen = new Set<string>();
  const add = (from: string, to: string) => {
    const id = `${from}~${to}`;
    if (seen.has(id)) return; // a cue layering the same voice twice draws one edge
    seen.add(id);
    edges.push({ id, from, to });
  };
  for (const v of kit.voices) add(voiceNodeId(v.id), primNodeId(v.primitive));
  for (const c of kit.cues) for (const l of c.layers) add(cueNodeId(c.id), voiceNodeId(l.voice));
  return { nodes, edges };
}

/** Lay the graph out in tier columns (primitives→voices→cues, L→R), stacked in seed order within a
 *  column. Keyed by node id so the shared canvas/viewport draw it. Pure + deterministic. */
export function layoutSoundGraph(graph: SoundGraph): SoundLayout {
  const pos = new Map<string, NodePos>();
  const rowByCol = [0, 0, 0];
  for (const n of graph.nodes) {
    const col = nodeTier(n.kind);
    const row = rowByCol[col]++;
    pos.set(n.id, { x: PAD + col * COL_PITCH, y: PAD + row * ROW_PITCH });
  }
  const maxRows = Math.max(0, ...rowByCol);
  const world = {
    w: PAD * 2 + 2 * COL_PITCH + NODE_W,
    h: PAD * 2 + Math.max(maxRows - 1, 0) * ROW_PITCH + NODE_H,
  };
  const bounds = { x: PAD, y: PAD, w: world.w - PAD * 2, h: world.h - PAD * 2 };
  return { pos, world, bounds };
}

/**
 * The cue to PLAY for a node: a cue node plays its cue; a voice node plays an ephemeral single-layer cue
 * (hear the patch in isolation); a primitive has no envelope/pitch of its own, so it's not playable alone
 * (null). The ephemeral cue references only kit voices, so `compileCue` resolves it.
 */
export function playableCueForNode(node: SoundNode, kit: SoundKit): Cue | null {
  if (node.kind === "cue") return kit.cues.find((c) => c.id === node.refId) ?? null;
  if (node.kind === "voice") {
    const v = kit.voices.find((x) => x.id === node.refId);
    if (!v) return null;
    return { id: `_voice_${v.id}`, name: v.name, category: "ui", layers: [{ voice: v.id, at: 0 }] };
  }
  return null;
}

runtime.features/sounds/lib/soundKits.ts:
// The Sounds pillar's BUILT-IN kits (#3080) — loaded from the embedded seed JSON under
// `src-tauri/data/sounds/` (`@data` alias), the ONE source of truth. The durable `bsc-sound` store
// hydrates from these on first run; this replaces the former hardcoded TS seed (soundSeeds.ts), per the
// golden rule (seeds live in data/, the store is the source at runtime). Same `import.meta.glob` pattern
// as the personas + component built-ins.
import type { SoundKit } from "./soundDescriptor";

const kitModules = import.meta.glob<{ default: SoundKit }>("@data/sounds/*.json", { eager: true });

/** Every packaged sound kit, ordered by id for determinism. */
export const BUILTIN_KITS: SoundKit[] = Object.values(kitModules)
  .map((m) => m.default)
  .sort((a, b) => a.id.localeCompare(b.id));

/** The default starter kit — the first built-in (currently "Signal"). Kept for call sites that want one
 *  concrete kit without threading the whole list. */
export const STARTER_KIT: SoundKit = BUILTIN_KITS[0];

/**
 * Union the durable store rows with the packaged built-ins: built-ins first (stable order), a STORED kit
 * WINS for a shared id (user edits override the seed), and any built-in the store lacks is returned in
 * `toSeed` so the caller can push it back — first-run seeding. Pure.
 */
export function mergeKits(
  stored: SoundKit[],
  builtins: SoundKit[] = BUILTIN_KITS,
): { kits: SoundKit[]; toSeed: SoundKit[] } {
  const storedById = new Map(stored.map((k) => [k.id, k]));
  const builtinIds = new Set(builtins.map((b) => b.id));
  const toSeed = builtins.filter((b) => !storedById.has(b.id));
  const kits: SoundKit[] = [
    ...builtins.map((b) => storedById.get(b.id) ?? b), // built-ins first; a stored kit wins for its id
    ...stored.filter((s) => !builtinIds.has(s.id)),     // then any store-only kits
  ];
  return { kits, toSeed };
}

runtime.features/sounds/lib/synth.ts:
// The Sounds synth engine (#3072) — two halves, split so the logic is testable without a browser:
//   compileCue — PURE: resolves a Cue's composes edges (layer→voice→primitive) into a FLAT schedule of
//                voices with absolute start times + durations. No Web Audio; fully unit-tested.
//   playCue    — THIN: realizes that schedule on a Web Audio graph. No-op where AudioContext is absent
//                (SSR / jsdom), so it's safe to call from anywhere; not unit-tested (needs a real ctx).
import type { Cue, Envelope, SoundKit, VoiceFilter, Waveform } from "./soundDescriptor";

/** One voice of a cue, resolved to everything the player needs — no more kit lookups downstream. */
export interface CompiledVoice {
  source: "osc" | "noise";
  waveform: Waveform;
  freq: number;
  pitchTo?: number;
  detune: number;
  env: Envelope;
  filter?: VoiceFilter;
  gain: number;
  /** Seconds from the cue's start. */
  startAt: number;
  /** attack + decay + release. */
  duration: number;
}

export interface CompiledCue {
  voices: CompiledVoice[];
  /** Wall-clock length of the whole cue (max layer end). */
  duration: number;
}

/** A voice's one-shot length: attack → decay → release (sustain is a level, not a hold). */
export function voiceDuration(env: Envelope): number {
  return env.attack + env.decay + env.release;
}

/**
 * Resolve a cue into a flat, absolutely-timed schedule. Throws on a dangling composes edge (a missing
 * voice or primitive) — call `validateKit` first if the kit might be broken; the seed kits are
 * test-guarded, so a throw here is a real bug, not user data. Pure + deterministic.
 */
export function compileCue(cue: Cue, kit: SoundKit): CompiledCue {
  const voiceById = new Map(kit.voices.map((v) => [v.id, v]));
  const primById = new Map(kit.primitives.map((p) => [p.id, p]));
  const voices: CompiledVoice[] = [];
  let duration = 0;
  for (const layer of cue.layers) {
    const voice = voiceById.get(layer.voice);
    if (!voice) throw new Error(`cue "${cue.id}" layers a missing voice "${layer.voice}"`);
    const prim = primById.get(voice.primitive);
    if (!prim) throw new Error(`voice "${voice.id}" composes a missing primitive "${voice.primitive}"`);
    const dur = voiceDuration(voice.env);
    voices.push({
      source: prim.kind,
      waveform: prim.waveform ?? "sine",
      freq: voice.freq,
      pitchTo: voice.pitchTo,
      detune: voice.detune ?? 0,
      env: voice.env,
      filter: voice.filter,
      gain: voice.gain,
      startAt: layer.at,
      duration: dur,
    });
    duration = Math.max(duration, layer.at + dur);
  }
  return { voices, duration };
}

// ── Web Audio realization (thin; untested — needs a real AudioContext) ─────────────────────────────

let sharedCtx: AudioContext | null = null;
let noiseBuf: AudioBuffer | null = null;

type AudioCtor = typeof AudioContext;

/** The shared AudioContext, created lazily on first play (a user gesture) and resumed if suspended.
 *  Returns null where Web Audio is unavailable (SSR / jsdom) so callers degrade to a no-op. */
function getCtx(): AudioContext | null {
  if (typeof window === "undefined") return null;
  const Ctor: AudioCtor | undefined =
    window.AudioContext ?? (window as unknown as { webkitAudioContext?: AudioCtor }).webkitAudioContext;
  if (!Ctor) return null;
  if (!sharedCtx) sharedCtx = new Ctor();
  if (sharedCtx.state === "suspended") void sharedCtx.resume();
  return sharedCtx;
}

/** A one-second white-noise buffer, generated once and reused for every noise voice. */
function whiteNoise(ctx: AudioContext): AudioBuffer {
  if (noiseBuf && noiseBuf.sampleRate === ctx.sampleRate) return noiseBuf;
  const buf = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
  noiseBuf = buf;
  return buf;
}

/** Schedule one compiled voice on the graph, starting at absolute time `t0`. */
function scheduleVoice(ctx: AudioContext, v: CompiledVoice, t0: number): void {
  const start = t0 + v.startAt;
  const { attack, decay, sustain, release } = v.env;
  const peak = Math.max(0.0001, v.gain);

  // Envelope on a GainNode: 0 →(attack)→ peak →(decay)→ sustain·peak →(release)→ 0.
  const amp = ctx.createGain();
  amp.gain.setValueAtTime(0.0001, start);
  amp.gain.linearRampToValueAtTime(peak, start + attack);
  amp.gain.linearRampToValueAtTime(Math.max(0.0001, sustain * peak), start + attack + decay);
  amp.gain.linearRampToValueAtTime(0.0001, start + attack + decay + release);

  let node: OscillatorNode | AudioBufferSourceNode;
  if (v.source === "noise") {
    const src = ctx.createBufferSource();
    src.buffer = whiteNoise(ctx);
    src.loop = true;
    node = src;
  } else {
    const osc = ctx.createOscillator();
    osc.type = v.waveform;
    osc.detune.setValueAtTime(v.detune, start);
    osc.frequency.setValueAtTime(v.freq, start);
    if (v.pitchTo != null && v.pitchTo !== v.freq) {
      osc.frequency.linearRampToValueAtTime(v.pitchTo, start + v.duration);
    }
    node = osc;
  }

  let tail: AudioNode = node;
  if (v.filter) {
    const f = ctx.createBiquadFilter();
    f.type = v.filter.type;
    f.frequency.setValueAtTime(v.filter.cutoff, start);
    tail.connect(f);
    tail = f;
  }
  tail.connect(amp);
  amp.connect(ctx.destination);

  node.start(start);
  node.stop(start + v.duration + 0.02);
}

/**
 * Play a cue NOW. Compiles it (throws only on a broken kit — guarded by validateKit/tests), then schedules
 * every voice on the shared AudioContext. Returns the cue's duration in seconds (0 where audio is
 * unavailable — a safe no-op). Fire-and-forget; there's no stop handle in Phase 1 (cues are short one-shots).
 */
export function playCue(cue: Cue, kit: SoundKit): number {
  const ctx = getCtx();
  if (!ctx) return 0;
  const compiled = compileCue(cue, kit);
  const t0 = ctx.currentTime + 0.02; // a hair ahead so the first envelope point isn't in the past
  for (const v of compiled.voices) scheduleVoice(ctx, v, t0);
  return compiled.duration;
}

runtime.features/sounds/SoundsInspector.tsx:
// The Sounds page inspector (#3077) — the selected node's details: a cue's layers, a voice's synth
// params, or a primitive's source. Cues + voices get a Play button (a primitive has no envelope of its
// own, so it's shown but not played). Mirrors the Algorithms/Designs inspector shape.
import { Play } from "lucide-react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";
import { Eyebrow } from "@/shared/ui/typography/Eyebrow";
import { Button } from "@/shared/ui/controls/Button";
import { CATEGORY_LABEL, type SoundKit } from "./lib/soundDescriptor";
import { playableCueForNode, type SoundNode } from "./lib/soundGraph";

function Field({ label, value }: { label: string; value: string }) {
  return (
    <Row justify="between" align="baseline" gap="sm">
      <Text size="xs" tone="dim">{label}</Text>
      <Text mono size="xs" style={{ textAlign: "right" }}>{value}</Text>
    </Row>
  );
}

export function SoundsInspector({ node, kit, onPlay }: {
  node: SoundNode | null;
  kit: SoundKit;
  onPlay: (node: SoundNode) => void;
}) {
  if (!node) {
    return (
      <Box style={{ padding: 16 }}>
        <Text size="sm" tone="dim">Select a sound to inspect it — cues, voices, and primitives.</Text>
      </Box>
    );
  }

  const playable = playableCueForNode(node, kit) != null;

  return (
    <Box style={{ padding: 16 }}>
      <Stack gap="md">
        <Box>
          <Eyebrow size={10}>{node.kind}</Eyebrow>
          <Text as="div" size="md" weight={600}>{node.label}</Text>
        </Box>

        {node.kind === "cue" && (() => {
          const cue = kit.cues.find((c) => c.id === node.refId);
          if (!cue) return null;
          return (
            <Stack gap="sm">
              <Field label="category" value={CATEGORY_LABEL[cue.category]} />
              <Box>
                <Eyebrow size={9}>Layers</Eyebrow>
                <Stack gap="xs" style={{ marginTop: 4 }}>
                  {cue.layers.map((l, i) => {
                    const v = kit.voices.find((x) => x.id === l.voice);
                    return <Field key={i} label={v?.name ?? l.voice} value={`@ ${l.at}s`} />;
                  })}
                </Stack>
              </Box>
            </Stack>
          );
        })()}

        {node.kind === "voice" && (() => {
          const v = kit.voices.find((x) => x.id === node.refId);
          if (!v) return null;
          const prim = kit.primitives.find((p) => p.id === v.primitive);
          return (
            <Stack gap="sm">
              <Field label="source" value={prim ? prim.name : v.primitive} />
              <Field label="frequency" value={v.pitchTo != null ? `${v.freq} → ${v.pitchTo} Hz` : `${v.freq} Hz`} />
              {v.detune ? <Field label="detune" value={`${v.detune} cents`} /> : null}
              <Field label="envelope" value={`a ${v.env.attack} · d ${v.env.decay} · s ${v.env.sustain} · r ${v.env.release}`} />
              {v.filter ? <Field label="filter" value={`${v.filter.type} @ ${v.filter.cutoff} Hz`} /> : null}
              <Field label="gain" value={String(v.gain)} />
            </Stack>
          );
        })()}

        {node.kind === "primitive" && (() => {
          const p = kit.primitives.find((x) => x.id === node.refId);
          if (!p) return null;
          return (
            <Stack gap="sm">
              <Field label="kind" value={p.kind === "osc" ? "oscillator" : "noise"} />
              {p.waveform ? <Field label="waveform" value={p.waveform} /> : null}
              <Text size="xs" tone="dim" as="div">A primitive is a source — hear it through a voice built on it.</Text>
            </Stack>
          );
        })()}

        {playable && (
          <Button size="sm" variant="primary" onClick={() => onPlay(node)}>
            <Play size={13} fill="currentColor" /> Play
          </Button>
        )}
      </Stack>
    </Box>
  );
}

runtime.features/sounds/SoundsKitGraph.tsx:
// The Sounds composition graph canvas (#3077) — world-positioned node cards over an SVG edge layer, the
// same shape as AlgorithmsKitGraph (GraphCanvas owns the pan/zoom transform). Nodes are the kit's
// primitives / voices / cues; edges are `composes`. Clicking a node ACTIVATES it (select + play, via the
// workspace). Selection lights a node + its neighbours and dims the rest.
import { useMemo } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { graphEdge } from "@/shared/lib/graph/edgePath";
import { NODE_W, NODE_H, type SoundGraph, type SoundLayout } from "./lib/soundGraph";

interface EdgeGeom { id: string; d: string; arrow: string; labelX: number; labelY: number }

export function SoundsKitGraph({ graph, layout, selected, onActivate }: {
  graph: SoundGraph;
  layout: SoundLayout;
  /** The selected node id, or null. */
  selected: string | null;
  /** Select + play the node (the workspace decides what "play" means per kind). */
  onActivate: (id: string) => void;
}) {
  // Neighbours of the selection (either direction) + incident edges — the shared "focus dims the rest".
  const lit = useMemo(() => {
    if (!selected) return null;
    const nodes = new Set<string>([selected]);
    const edges = new Set<string>();
    for (const e of graph.edges) {
      if (e.from === selected) { nodes.add(e.to); edges.add(e.id); }
      if (e.to === selected) { nodes.add(e.from); edges.add(e.id); }
    }
    return { nodes, edges };
  }, [graph.edges, selected]);

  const geoms = useMemo<EdgeGeom[]>(() => {
    return graph.edges.flatMap((e) => {
      const a = layout.pos.get(e.from), b = layout.pos.get(e.to);
      if (!a || !b) return [];
      const g = graphEdge(
        { x: a.x, y: a.y, w: NODE_W, h: NODE_H },
        { x: b.x, y: b.y, w: NODE_W, h: NODE_H },
        { routing: "anchor" },
      );
      return [{ id: e.id, d: g.d, arrow: g.arrow, labelX: g.labelX, labelY: g.labelY }];
    });
  }, [graph.edges, layout.pos]);

  return (
    <>
      <svg width={layout.world.w} height={layout.world.h} style={{ position: "absolute", left: 0, top: 0, overflow: "visible", pointerEvents: "none" }}>
        {geoms.map((g) => {
          const isLit = !!lit && lit.edges.has(g.id);
          const dim = !!lit && !isLit;
          const stroke = isLit ? "var(--fg-dim)" : "var(--border)";
          return (
            <g key={g.id} style={{ opacity: dim ? 0.14 : 1, transition: "opacity 0.16s ease" }}>
              <path d={g.d} fill="none" stroke={stroke} strokeWidth={isLit ? 1.75 : 1.25} />
              <path d={g.arrow} fill={stroke} />
            </g>
          );
        })}
      </svg>

      {graph.nodes.map((n) => {
        const p = layout.pos.get(n.id);
        if (!p) return null;
        const dim = !!lit && !lit.nodes.has(n.id);
        return (
          <Box
            key={n.id}
            data-snd-node={n.id}
            className={`snd-node snd-${n.kind}${n.id === selected ? " on" : ""}${dim ? " dim" : ""}`}
            style={{ left: p.x, top: p.y, width: NODE_W, height: NODE_H }}
            onClick={(e) => { e.stopPropagation(); onActivate(n.id); }}
          >
            <Box as="span" className="snd-name">{n.label}</Box>
            <Box as="span" className="snd-meta mono">{n.category ?? n.kind}</Box>
          </Box>
        );
      })}
    </>
  );
}

