// The Sounds tab (#3072 · #3077) — the synthesis-first audio library, on the shared GraphCanvas stack
// like Components/Algorithms. The CENTER is the kit's composition graph (Primitives → Voices → Cues,
// wired by `composes`); the LEFT rail is a folder tree of cues/voices/primitives; the inspector shows the
// selected node. Clicking a graph node plays it; the rail browses quietly (Play is in the inspector).
import { useEffect, useMemo, useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Eyebrow } from "@/shared/ui/typography/Eyebrow";
import { Button } from "@/shared/ui/controls/Button";
import { GraphCanvas, ZoomControls } from "@/shared/ui/layouts/GraphCanvas";
import { useGraphViewport } from "@/shared/ui/layouts/useGraphViewport";
import { useCrumbEntity } from "@/shared/hooks/useCrumbEntity";
import { SoundsKitGraph } from "./SoundsKitGraph";
import { SoundsRail } from "./SoundsRail";
import { SoundsInspector } from "./SoundsInspector";
import { buildSoundGraph, layoutSoundGraph, playableCueForNode, NODE_W, NODE_H, type SoundNode } from "./lib/soundGraph";
import { playCue } from "./lib/synth";
import { BUILTIN_KITS } from "./lib/soundKits";
import { useSoundKits } from "./useSoundKits";
import "./sounds.css";

export function SoundsWorkspace() {
  // Seed-first, hydrated from the durable bsc-sound store (#3080). The first kit is active (multi-kit
  // selection lands later); BUILTIN_KITS[0] is the guaranteed non-empty fallback for the first paint.
  const kits = useSoundKits();
  const kit = kits[0] ?? BUILTIN_KITS[0];
  useCrumbEntity("sounds", kit.name);

  const graph = useMemo(() => buildSoundGraph(kit), [kit]);
  const layout = useMemo(() => layoutSoundGraph(graph), [graph]);
  const [selected, setSelected] = useState<string | null>(null);
  const selectedNode = selected ? graph.nodes.find((n) => n.id === selected) ?? null : null;

  const vp = useGraphViewport(layout.world, { contentBounds: () => layout.bounds });
  // Frame the graph once on mount (like AlgorithmsWorkspace) — we only want the initial fit.
  useEffect(() => { vp.fit(); }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const play = (node: SoundNode) => {
    const cue = playableCueForNode(node, kit);
    if (cue) playCue(cue, kit);
  };
  // Rail click: select + pan to the node, no sound (browse quietly).
  const select = (id: string) => {
    setSelected(id);
    const p = layout.pos.get(id);
    if (p) vp.centerOn(p.x + NODE_W / 2, p.y + NODE_H / 2);
  };
  // Graph-node click: select + play.
  const activate = (id: string) => {
    setSelected(id);
    const node = graph.nodes.find((n) => n.id === id);
    if (node) play(node);
  };

  const counts = useMemo(() => ({
    cues: graph.nodes.filter((n) => n.kind === "cue").length,
    voices: graph.nodes.filter((n) => n.kind === "voice").length,
    primitives: graph.nodes.filter((n) => n.kind === "primitive").length,
  }), [graph.nodes]);

  const toolbar = (
    <>
      <Eyebrow size={10}>Sounds</Eyebrow>
      <Text mono size="xxs" tone="dim">{kit.name} · {counts.cues} cues · {counts.voices} voices · {counts.primitives} primitives</Text>
      <Box style={{ flex: 1 }} />
      <ZoomControls vp={vp} />
      <Button size="sm" variant="ghost" onClick={vp.fit}>Fit</Button>
    </>
  );

  return (
    <GraphCanvas
      vp={vp}
      world={layout.world}
      grid
      toolbar={toolbar}
      rail={<SoundsRail graph={graph} selected={selected} onSelect={select} />}
      railResizable
      railWidth={230}
      inspector={<SoundsInspector node={selectedNode} kit={kit} onPlay={play} />}
      inspectorResizable
      inspectorWidth={320}
      onBackgroundClick={() => setSelected(null)}
    >
      <SoundsKitGraph graph={graph} layout={layout} selected={selected} onActivate={activate} />
    </GraphCanvas>
  );
}

runtime.features/sounds/useNotificationSounds.ts:
// useNotificationSounds (#3082, epic #3071 P4a) — the app dogfooding its own Sounds library. When the
// opt-in `soundNotifications` flag is ON (default OFF, Settings → Appearance), watch the coordination
// log and play a Signal-kit cue on each NEW completion/wait event since mount: landing/merge → success,
// failure → error, a worker pausing (`bsc-wait`) → notify. Mounted once app-wide (App.tsx).
//
// Baseline discipline: we never voice the backlog. On mount (and each time the flag is re-enabled) the
// first successful read just records the current line count; only lines appended AFTER that sound. A
// shrunk/replaced log re-baselines rather than replaying. While OFF the poll is a no-op (no I/O).
import { useRef } from "react";
import { useAppStore } from "@/store";
import { usePoll } from "@/shared/hooks/usePoll";
import { readCoordState } from "@/shared/lib/fleet/useCoordLog";
import { playCue } from "./lib/synth";
import { STARTER_KIT } from "./lib/soundKits";
import { cuesForLines } from "./lib/notifyCues";

/** Poll cadence for the coord-log watch (ms). Matches the coordinator's own 1 Hz read. */
const POLL_MS = 1000;

export function useNotificationSounds(): void {
  // Count of coord-log lines already accounted for; -1 = "not yet baselined" (re-baseline next read).
  const seen = useRef(-1);
  // Whether the flag was ON last tick — a false→true edge forces a re-baseline so enabling mid-session
  // starts from "now" instead of dumping the backlog.
  const wasOn = useRef(false);

  usePoll(async (isCancelled) => {
    const on = useAppStore.getState().soundNotifications;
    if (!on) { wasOn.current = false; return; }                     // OFF → no I/O
    if (!wasOn.current) { wasOn.current = true; seen.current = -1; } // just enabled → re-baseline

    const res = await readCoordState();
    if (isCancelled() || !res) return;                 // read failure → keep the baseline, retry next tick
    const n = res.lines.length;

    // First read after (re)baseline, or a shrunk/replaced log → set the baseline, voice nothing.
    if (seen.current < 0 || n < seen.current) { seen.current = n; return; }

    // De-dupe within the tick so a burst of e.g. merges doesn't stack identical cues over each other.
    const cues = [...new Set(cuesForLines(res.lines.slice(seen.current)))];
    seen.current = n;
    for (const id of cues) {
      const cue = STARTER_KIT.cues.find((c) => c.id === id);
      if (cue) playCue(cue, STARTER_KIT);
    }
  }, POLL_MS);
}

runtime.features/sounds/useSoundKits.ts:
// useSoundKits (#3080) — the Sounds tab's kit source, seed-first: renders the packaged built-ins
// immediately, then hydrates from the durable `bsc-sound` store and seeds any built-in the store is
// missing (first run). Mirrors the Algorithms knowledge-graph hydration (`useKnowledgeGraph`, #2856):
// a hook, not a store slice, since the library is read-mostly here (authoring lands in Phase 4).
import { useEffect, useState } from "react";
import type { SoundKit } from "./lib/soundDescriptor";
import { BUILTIN_KITS, mergeKits } from "./lib/soundKits";
import { loadKits, pushKit } from "./lib/soundBridge";

export function useSoundKits(): SoundKit[] {
  const [kits, setKits] = useState<SoundKit[]>(BUILTIN_KITS);
  useEffect(() => {
    let cancelled = false;
    void loadKits().then((rows) => {
      const { kits: merged, toSeed } = mergeKits(rows);
      // Push any built-in the store doesn't have yet, so `bsc sound get <id>` works from a session too.
      toSeed.forEach((k) => { void pushKit(k).catch(() => {}); });
      if (!cancelled && merged.length) setKits(merged);
    });
    return () => { cancelled = true; };
  }, []);
  return kits;
}

