// The app-owned STUDIO sessions (#3357) — the one place that describes the designer / librarian /
// architect singleton sessions: their stable pane id, role, workspace-setup command, persona, tunnel
// roster entry, and the page they dock on. Pure + React-free so the registry is unit-testable and can be
// read from the store slice, the mount, the page docks, and the Glance wiring without a cycle.
//
// WHY A REGISTRY: before #3357 each studio owned a bespoke `use*Terminal` hook that mounted its OWN xterm
// via `useScreenSession`. That terminal could not be re-parented, so the Glance graph could not morph a
// studio node into its live session (only the debugger, already on TerminalHost, could). All three now
// launch through the SHARED TerminalHost like every fleet terminal — which means their launch inputs must
// live as DATA the generic launch path (`TerminalView` + `buildSessionSettings`) reads, not as a bespoke
// `pty_create` call. This file is that data.
import type { SessionRole } from "@/shared/lib/session/sessionRoles";
import {
  DESIGN_STUDIO_SESSION_ID,
  ALGORITHMS_STUDIO_SESSION_ID,
  TEAMS_STUDIO_SESSION_ID,
  SOUND_STUDIO_SESSION_ID,
  INTEGRATION_STUDIO_SESSION_ID,
} from "@/shared/lib/session/systemSessions";

/** The five app-owned studio sessions. (The DEBUG session is app-owned too but is full-capability and
 *  Settings-toggled, so it keeps its own `DebugSessionMount` — see `@/features/debug`.) */
export type StudioId = "designer" | "librarian" | "architect" | "soundDesigner" | "integrator";

/** Every studio id, in rail order. */
export const STUDIO_IDS: readonly StudioId[] = ["designer", "librarian", "architect", "soundDesigner", "integrator"];

export interface StudioSessionDef {
  id: StudioId;
  /** The stable, app-owned pane id (`systemSessions.ts`) — so re-opening re-uses the SAME session. */
  paneId: string;
  /** The role gate (#219) the session launches under. Set as `paneRoles[paneId]` and NOTHING else:
   *  `restrictedRoleCommands(role)` then makes `buildSessionSettings` emit `restrictedAllow`, so the
   *  session's whole auto-run surface is its store CLI. A pane PROFILE must never be assigned — that
   *  would ADD auto-approved commands on top of the restricted surface. */
  role: SessionRole;
  /** Tauri command that creates the studio's global workspace dir + writes its spec CLAUDE.md. */
  setupCommand: string;
  /** Key on `setupCommand`'s return object holding the workspace dir (the session's cwd). */
  dirKey: string;
  /** The built-in persona whose `startPrompt` is baked into the launch as `claude --initial-message`. */
  personaId: string;
  /** Display name in the mobile session roster (#2497). */
  rosterName: string;
  /** `usePageTabs` page key + section id of the page this studio docks on — the tear-off signal
   *  (`detachedSections[pageKey]` containing `sectionId` ⇒ another WINDOW owns this studio's terminal). */
  pageKey: string;
  sectionId: string;
  /** The studio's CURATED default skill ids — resolved from the library into `paneSkills` at launch
   *  (#3766). Unlike the global-enabled firehose a normal session gets, a restricted studio session is
   *  pinned to exactly this set (absent/empty ⇒ none, preserving the confinement boundary). This is how
   *  a11y + compliance guidance rides with the designer by construction. */
  defaultSkillIds?: string[];
}

export const STUDIO_SESSIONS: Record<StudioId, StudioSessionDef> = {
  designer: {
    id: "designer",
    paneId: DESIGN_STUDIO_SESSION_ID,
    role: "designer",
    setupCommand: "setup_designer_workspace",
    dirKey: "design_dir",
    personaId: "persona-designer",
    rosterName: "Design Studio",
    pageKey: "projects",
    sectionId: "designs",
    // Build components accessible + compliant BY CONSTRUCTION (#3766) — the author-time skills, not
    // the post-hoc *-audit/*-review ones the reviewer runs.
    defaultSkillIds: ["author-accessible-components", "author-compliant-components"],
  },
  librarian: {
    id: "librarian",
    paneId: ALGORITHMS_STUDIO_SESSION_ID,
    role: "librarian",
    setupCommand: "setup_librarian_workspace",
    dirKey: "algorithms_dir",
    personaId: "persona-librarian",
    rosterName: "Algorithms Studio",
    pageKey: "projects",
    sectionId: "algorithms",
  },
  soundDesigner: {
    id: "soundDesigner",
    paneId: SOUND_STUDIO_SESSION_ID,
    role: "sound-designer",
    setupCommand: "setup_sound_designer_workspace",
    dirKey: "sound_dir",
    personaId: "persona-sound-designer",
    rosterName: "Sound Studio",
    pageKey: "projects",
    sectionId: "sounds",
  },
  integrator: {
    id: "integrator",
    paneId: INTEGRATION_STUDIO_SESSION_ID,
    role: "integrator",
    setupCommand: "setup_integrator_workspace",
    dirKey: "integrations_dir",
    personaId: "persona-integrator",
    rosterName: "Integration Studio",
    pageKey: "projects",
    sectionId: "integrations",
    // #4023: the studio ships with its playbook — the same secret-free probe→try→register procedure
    // its spec describes, so the guidance rides with the session by construction rather than being
    // re-derived per conversation.
    defaultSkillIds: ["build-integration"],
  },
  architect: {
    id: "architect",
    paneId: TEAMS_STUDIO_SESSION_ID,
    role: "architect",
    setupCommand: "setup_architect_workspace",
    dirKey: "teams_dir",
    personaId: "persona-architect",
    rosterName: "Teams Studio",
    pageKey: "projects",
    sectionId: "teams",
  },
};

/** Where a failed `--continue` writes its reason. Under `$BSC_LOG_DIR` (set per-pane by `pty_create`,
 *  alongside the audit/coord/perf streams), so it sits with the rest of a session's diagnostics. */
export const STUDIO_RESUME_LOG = "studio-resume.log";

/**
 * Resume the prior studio conversation across app restarts, else launch a fresh session.
 *
 * The `|| claude` fallback is deliberate — a genuinely first launch has nothing to resume. What was
 * NOT deliberate is that the old form (`claude --continue 2>/dev/null || claude`) **discarded the
 * reason** and degraded silently: a session that failed to resume looked identical to one that had
 * never run, with no log line and nothing in the pane. That made #3374 — studios starting a fresh
 * conversation across restarts — impossible to diagnose, because the one signal that would explain it
 * was being thrown away on every launch.
 *
 * So stderr now APPENDS to `$BSC_LOG_DIR/studio-resume.log` instead of `/dev/null`, and the fallback
 * announces itself in the pane. Behaviour is otherwise unchanged: resume when there is something to
 * resume, start fresh when there isn't.
 *
 * `${BSC_LOG_DIR:-/tmp}` guards the (unexpected) case of an unset log dir — a missing diagnostic must
 * never stop the session launching.
 */
export const STUDIO_INIT_CMD =
  `claude --continue 2>>"\${BSC_LOG_DIR:-/tmp}/${STUDIO_RESUME_LOG}"` +
  ` || { echo "[studio] no prior session resumed — starting fresh (why: \${BSC_LOG_DIR:-/tmp}/${STUDIO_RESUME_LOG})"; claude; }`;

/** Narrow an arbitrary string (a Glance node id, a persisted value) to a StudioId. */
export function isStudioId(value: string | null | undefined): value is StudioId {
  return !!value && (STUDIO_IDS as readonly string[]).includes(value);
}

/** The studio owning a pane id, or null for any other pane (fleet, planner, debug, manual). */
export function studioForPaneId(paneId: string): StudioId | null {
  return STUDIO_IDS.find((id) => STUDIO_SESSIONS[id].paneId === paneId) ?? null;
}

/**
 * The role gate a studio pane launches under, DERIVED from its pane id (#3423) — so confinement travels
 * with the session's identity instead of depending on setup having run first.
 *
 * `paneRoles[paneId]` is what makes a pane a designer, and it used to be written ONLY by
 * `seedStudioLaunchState` inside `StudioSessionMount`'s effect. That component renders only for studios in
 * `wantedStudios`, which is deliberately transient (absent from `partialize`), so after any app restart the
 * set is empty and nothing mounts. Opening a studio then created a terminal on a studio pane id with NO role
 * in the store — and `buildSessionSettings` applies no role gate, no `restrictedAllow` and no denies when it
 * finds none. The result was a fully UNCONFINED general shell on the app's most restricted surface.
 *
 * A studio's pane id is stable and app-owned, so it is sufficient on its own to establish the role. Null for
 * any other pane, where the store remains the only authority.
 */
export function studioRoleForPaneId(paneId: string): SessionRole | null {
  const id = studioForPaneId(paneId);
  return id ? STUDIO_SESSIONS[id].role : null;
}

/**
 * Whether this studio's page is TORN OFF into its own window (#430/#463). The detached window runs its
 * OWN React root + store + TerminalHost, so it becomes the sole owner of the studio's single terminal —
 * the main window must release it (not mount a second xterm onto the same PTY, which would fight over
 * `pty_resize`). `detachedSections` is transient per-window state, so the detached window itself always
 * reads `false` here and mounts the session normally. Pure.
 */
export function studioDetached(id: StudioId, detachedSections: Record<string, string[]>): boolean {
  const def = STUDIO_SESSIONS[id];
  return (detachedSections[def.pageKey] ?? []).includes(def.sectionId);
}

runtime.features/studio-sessions/store.ts:
// Studios feature store slice (#3357) — the LIFECYCLE of the app-owned designer / librarian / architect
// sessions, now that all three live on the shared TerminalHost instead of a page-owned xterm.
//
// Two transient (NEVER persisted) fields, both keyed by StudioId:
//   • `wantedStudios` — which studios should have a WARM session. A studio enters the list the first time
//     something shows it (its page dock or the Glance morph, via `useStudioViewer`) and leaves it when the
//     idle reaper fires. `StudioSessionHosts` renders one persistent `TerminalSlot` per wanted studio, so
//     "wanted" is exactly "this studio has a terminal on the host". (The backend PTY is killed explicitly
//     by whoever drops the studio — the reaper, or an "End session" from the Glance morph — because
//     `TerminalView`'s unmount deliberately leaves the session alive for reconnect.)
//   • `studioViewers` — a REF COUNT of the surfaces currently SHOWING each studio. Two independent
//     surfaces can show the same session at once (the studio page dock and the Glance node morph), so a
//     boolean would let whichever closed first cancel the other. Counting means the reaper only arms when
//     the LAST viewer goes away.
//
// Nothing here launches or kills a PTY directly — `wantedStudios` is a declaration and the mount/TerminalHost
// pair is what acts on it. That keeps the whole lifecycle unit-testable as plain state transitions.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import { STUDIO_IDS, type StudioId } from "./lib/studioSessions";

export interface StudiosSlice {
  /** Studios whose session should be kept warm on TerminalHost. Transient — nothing launches at boot. */
  wantedStudios: StudioId[];
  /** studio id → number of mounted surfaces currently SHOWING it (page dock + Glance morph). Transient. */
  studioViewers: Record<string, number>;
  /** Mark a studio as wanted — the lazy start. Idempotent, so every viewer can call it on mount. */
  openStudio: (id: StudioId) => void;
  /** Drop a studio from the wanted list → its persistent mount unmounts. Called by the idle reaper and by
   *  an explicit "End session" from the Glance morph, BOTH of which also `pty_kill` the session. */
  closeStudio: (id: StudioId) => void;
  /** A surface began showing this studio (cancels any armed reap). */
  addStudioViewer: (id: StudioId) => void;
  /** A surface stopped showing this studio (arms the reaper when the count reaches 0). */
  removeStudioViewer: (id: StudioId) => void;
}

export const createStudiosSlice: StateCreator<AppStore, [], [], StudiosSlice> = (set) => ({
  wantedStudios: [],
  studioViewers: {},

  openStudio: (id) =>
    set((s) => (s.wantedStudios.includes(id) ? {} : { wantedStudios: [...s.wantedStudios, id] })),

  closeStudio: (id) =>
    set((s) => (s.wantedStudios.includes(id) ? { wantedStudios: s.wantedStudios.filter((w) => w !== id) } : {})),

  addStudioViewer: (id) =>
    set((s) => ({ studioViewers: { ...s.studioViewers, [id]: (s.studioViewers[id] ?? 0) + 1 } })),

  // Clamp at 0: a double-unmount (StrictMode, a racing cleanup) must never drive the count negative —
  // a negative count would read as "still watched" forever and the reaper would never arm.
  removeStudioViewer: (id) =>
    set((s) => ({ studioViewers: { ...s.studioViewers, [id]: Math.max(0, (s.studioViewers[id] ?? 0) - 1) } })),
});

/** The studios currently WANTED, in canonical rail order (so the mounts render in a stable order). */
export function orderedWantedStudios(wanted: readonly StudioId[]): StudioId[] {
  return STUDIO_IDS.filter((id) => wanted.includes(id));
}

runtime.features/studio-sessions/StudioSessionHo:
// StudioSessionHosts (#3357) — the app-shell mount point for every WANTED studio session, rendered inside
// <TerminalHost> beside <DebugSessionMount />. One persistent, off-screen `primary` claim per wanted studio
// keeps its PTY warm across navigation; the idle reaper (30 min unwatched) kills the session and drops it
// from the wanted list, which unmounts the claim.
//
// A studio whose page is TORN OFF is skipped here: that window runs its own TerminalHost + hosts, and two
// windows each mounting an xterm onto the same PTY would fight over `pty_resize`. The single-owner handoff
// the pages already had (`KeptMountedPage`'s `gate`) thus survives the migration.
import { useAppStore } from "@/store";
import { StudioSessionMount } from "./StudioSessionMount";
import { useStudioReaper } from "./useStudioReaper";
import { orderedWantedStudios } from "./store";
import { studioDetached } from "./lib/studioSessions";

export function StudioSessionHosts() {
  useStudioReaper();
  const wantedStudios = useAppStore((s) => s.wantedStudios);
  const detachedSections = useAppStore((s) => s.detachedSections);
  const mounted = orderedWantedStudios(wantedStudios).filter((id) => !studioDetached(id, detachedSections));
  return <>{mounted.map((id) => <StudioSessionMount key={id} studio={id} />)}</>;
}

runtime.features/studio-sessions/StudioSessionMo:
// StudioSessionMount (#3357) — the persistent host that keeps ONE app-owned studio session (designer /
// librarian / architect) alive on the shared TerminalHost. The exact shape of `DebugSessionMount` (#3326),
// generalised over the studio registry.
//
// WHY A HIDDEN `primary` SLOT: TerminalHost renders a <TerminalView> for a paneId only WHILE that paneId
// has at least one claim; when the last claim deregisters, the view unmounts and the PTY is torn down. A
// fleet terminal survives a morph-close because its console GRID CELL is a permanent claim. A studio
// session has no cell — so THIS mount is its permanent `primary` claim. It:
//   • supplies the launch props (cwd + resume initCmd) as the primary, and
//   • sits OFF-SCREEN (NOT `display:none`, so the parked xterm still fits to a real size) — keeping the
//     PTY warm while the user is on another page.
// The studio page dock and the Glance node morph each drop a second, VISIBLE viewer slot for the same
// paneId; being the last claim, whichever is open owns the terminal, so the host re-parents the live
// terminal into it and back here on close. That re-parent is a plain appendChild MOVE, so the xterm
// scrollback and the PTY survive untouched — which is the whole point of the migration: before #3357 the
// studios ran their own single-mount xterm (`useScreenSession`), which the host could not re-parent, so
// their Glance nodes could not morph.
//
// POSTURE: unlike the DEBUG session (full-capability, role-less — the `isFullCapabilitySession` carve-out),
// a studio session is heavily RESTRICTED, and that posture is now fully role-derived. This mount sets
// `paneRoles[paneId]` and NOTHING permission-shaped beyond it: `buildSessionSettings` reads the role,
// computes `restrictedRoleCommands(role)` as the session's ONLY allowed commands, flips `restrictedAllow`
// (suppressing every Bash baseline tier), grants `Read`, renders the role's git/gh/write/web denies, and
// forces `bypass:false` for a restricted role. `buildAgentEnv` emits the same `BSC_SCOPES` the bespoke
// launch did. CRITICALLY, no `paneProfiles` entry is set — a profile's `allowedCommands` are ADDED to the
// restricted surface, so assigning one would WIDEN the session.
import { useEffect, useState } from "react";
import { useAppStore } from "@/store";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { Box } from "@/shared/ui/layout/Box";
import { TerminalSlot } from "@/app/console/terminal/TerminalSlot";
import { BUILTIN_PERSONAS } from "@/features/personas";
import { STUDIO_INIT_CMD, STUDIO_SESSIONS, type StudioId, type StudioSessionDef } from "./lib/studioSessions";

/** The studio persona's start prompt — the store copy (user edits win), else the packaged seed. */
export function studioStartPrompt(personaId: string): string {
  const fromStore = useAppStore.getState().personas.find((p) => p.id === personaId);
  return (fromStore ?? BUILTIN_PERSONAS.find((p) => p.id === personaId))?.startPrompt ?? "";
}

/**
 * Seed every store field the GENERIC launch path (`TerminalView` → `buildAgentEnv` /
 * `buildSessionSettings` / `pty_create`) reads for this pane, reproducing the bespoke `use*Terminal`
 * launch exactly:
 *   • `paneRoles`             → the whole restricted permission payload (see the file header).
 *   • `paneStartupPromptText` → the persona kickoff, BAKED into the launch arg (never typed after idle
 *                               detection). Omitted when the persona has no prompt, so `pty_create` gets
 *                               `undefined` rather than an empty initial message.
 *   • `paneContinue`          → `claude --continue`, so a relaunch resumes the prior conversation.
 *   • `paneMcpServers` / `paneHooks` → pinned EMPTY. Without these the generic path falls back to the
 *     GLOBAL sets, which would attach every configured MCP server (i.e. extra tools) to a session
 *     deliberately confined to one store CLI. The bespoke launch passed none; pinning empty keeps that
 *     boundary.
 *   • `paneSkills` → pinned to the studio's CURATED default skills (`def.defaultSkillIds`, #3766) —
 *     a specific, relevant set (e.g. the designer's a11y + compliance AUTHORING skills), NOT the global
 *     skill firehose. Empty when the studio declares no defaults, preserving the same confinement.
 * Exported for the unit test — the permission payload is the security-critical half of this migration.
 */
export function seedStudioLaunchState(def: StudioSessionDef): void {
  const prompt = studioStartPrompt(def.personaId);
  useAppStore.setState((st) => {
    const startupPrompts = { ...st.paneStartupPromptText };
    if (prompt) startupPrompts[def.paneId] = prompt;
    else delete startupPrompts[def.paneId];
    // The studio's CURATED default skills (#3766) — resolved from the library by id, enabled-only. NOT
    // the global firehose; empty when the studio declares no `defaultSkillIds`, so the boundary holds.
    const defaultIds = new Set(def.defaultSkillIds ?? []);
    const defaultSkills = st.skills.filter((sk) => sk.enabled && defaultIds.has(sk.id));
    return {
      paneRoles:             { ...st.paneRoles, [def.paneId]: def.role },
      paneStartupPromptText: startupPrompts,
      paneContinue:          { ...st.paneContinue, [def.paneId]: true },
      paneMcpServers:        { ...st.paneMcpServers, [def.paneId]: [] },
      paneHooks:             { ...st.paneHooks, [def.paneId]: [] },
      paneSkills:            { ...st.paneSkills, [def.paneId]: defaultSkills },
    };
  });
}

/**
 * Keeps ONE studio session's PTY warm on TerminalHost. Renders nothing visible (the terminal is shown by
 * the page dock / the Glance morph); returns null until the workspace command hands back a real cwd —
 * a studio session must never launch against an empty cwd, which would skip `ensure_session_settings`
 * and run it permission-less (#1819).
 */
export function StudioSessionMount({ studio }: { studio: StudioId }) {
  const def = STUDIO_SESSIONS[studio];
  // undefined = still resolving; null = setup failed (no session); string = the workspace cwd.
  const [cwd, setCwd] = useState<string | null | undefined>(undefined);

  useEffect(() => {
    let alive = true;
    void (async () => {
      // The studio's global workspace (e.g. ~/.base-studio-code/design-studio/) + its spec CLAUDE.md.
      const paths = await safeInvoke<Record<string, string> | null>(
        def.setupCommand, undefined, null,
        (e: unknown) => console.error(`${def.id} workspace setup failed:`, e),
      );
      if (!alive) return;
      const dir = paths?.[def.dirKey];
      if (!dir) { setCwd(null); return; }
      seedStudioLaunchState(def);
      // Session roster (#2497): register the studio session so a paired phone lists it alongside the
      // console/fleet/planner panes. Plain store state — useTunnelSync only pushes while the relay runs,
      // so this is inert without a tunnel. Deregistered in the cleanup below.
      useAppStore.getState().registerTunnelPanes(def.id, [{
        id: def.paneId, cwd: dir, name: def.rosterName, status: "running", kind: def.id,
      }]);
      setCwd(dir);
    })();
    return () => { alive = false; useAppStore.getState().registerTunnelPanes(def.id, []); };
  }, [def]);

  if (!cwd) return null;
  return (
    // Off-screen (NOT display:none, so the parked xterm still fits to a real size) permanent `primary`
    // claim. A visible viewer slot re-parents the terminal out of here when a surface opens it.
    <Box
      aria-hidden
      data-testid={`studio-mount-${def.id}`}
      style={{
        position: "absolute", left: -99999, top: 0, width: 800, height: 600,
        overflow: "hidden", pointerEvents: "none", display: "flex", flexDirection: "column",
      }}
    >
      {/* `parked`: this claim can register at ANY time (its cwd resolves async), so it must never take
          ownership away from a visible dock/morph that claimed first — it owns the terminal only when it
          is the last claim standing. */}
      <TerminalSlot paneId={def.paneId} primary parked visible={false} initialCwd={cwd} initCmd={STUDIO_INIT_CMD} />
    </Box>
  );
}

runtime.features/studio-sessions/useStudioPageSh:
// useStudioPageShowing (#3357) — is a studio's own page actually ON SCREEN right now?
//
// The studio pages are KEPT MOUNTED (`KeptMountedPage`): once visited they stay in the tree and are only
// CSS-hidden when the user switches away. So "my dock component is mounted" is NOT "the user is looking at
// this studio" — if the viewer ref-count keyed off mounting, it would stay ≥1 forever after the first visit
// and the idle reaper could never fire. This derives the real answer from the shell's page state.
import { useAppStore } from "@/store";
import { detachedSection } from "@/app/console/lib/detachWindow";
import { STUDIO_SESSIONS, type StudioId } from "./lib/studioSessions";

/** Pure rule: which page is showing, given the shell state and (for a tear-off) this window's identity. */
export function studioPageShowing(
  id: StudioId,
  s: { activeWorkspace: string; projectsPageMode: string },
  detached: { page: string; section: string } | null,
): boolean {
  const def = STUDIO_SESSIONS[id];
  // A torn-off section window renders exactly ONE page and has no rail — it is showing iff it IS this page.
  if (detached) return detached.page === def.pageKey && detached.section === def.sectionId;
  return s.activeWorkspace === "projects" && s.projectsPageMode === def.sectionId;
}

export function useStudioPageShowing(id: StudioId): boolean {
  const activeWorkspace = useAppStore((st) => st.activeWorkspace);
  const projectsPageMode = useAppStore((st) => st.projectsPageMode);
  return studioPageShowing(id, { activeWorkspace, projectsPageMode }, detachedSection());
}

runtime.features/studio-sessions/useStudioReaper:
// useStudioReaper (#3357) — the idle reaper for the app-owned studio sessions.
//
// A studio session deliberately OUTLIVES the surface that opened it: leaving the Design Studio page keeps
// the designer warm on TerminalHost so the Glance node can still morph into it. Something has to reclaim
// it eventually, or every studio ever opened runs a Claude process until the app quits.
//
// The rule: while a studio is wanted but NO surface is showing it (viewer count 0), a 30-minute timer runs.
// On expiry the session is killed and the studio leaves the wanted list, so its persistent mount unmounts
// with it. Anything that shows it again before expiry cancels the timer, and because the pane id is stable
// a later re-open resumes the same conversation (`claude --continue`) either way.
//
// NOTE: dropping the last TerminalHost claim is NOT itself a teardown — `TerminalView`'s cleanup keeps the
// backend PTY alive on purpose (a console tab-switch must reconnect, not respawn). So the reaper issues the
// `pty_kill` explicitly; the unmount only reclaims the xterm.
//
// ONE exception, checked at expiry rather than at arm time: if Claude is actively running in the session
// (`paneClaudeActive`), killing it would cut off work in flight. The reaper then RE-ARMS on a short recheck
// instead of reaping, so a busy session is deferred (indefinitely, while it stays busy) and reclaimed as
// soon as it goes quiet.
import { useEffect, useRef } from "react";
import { useAppStore } from "@/store";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";
// The reaping policy is ONE user-facing setting (Settings → Planner → "Reap idle background sessions"),
// so the studio threshold lives alongside the console pane thresholds in `ReaperConfig` rather than in a
// second config the user would have to find separately. Pure leaf import, like `detachWindow` above.
import { DEFAULT_STUDIO_IDLE_MS, studioIdleMs } from "@/app/console/lib/idleReaper";
import { STUDIO_IDS, STUDIO_SESSIONS, type StudioId } from "./lib/studioSessions";

/** Default idle grace before an unwatched studio session is reclaimed. The EFFECTIVE value is the
 *  user's `idleReaper.studioIdleMs` setting; this is the packaged default (and the test baseline). */
export const STUDIO_IDLE_MS = DEFAULT_STUDIO_IDLE_MS;
/** Recheck interval while a due-to-be-reaped session still has Claude working in it. */
export const STUDIO_BUSY_RECHECK_MS = 60 * 1000;

export function useStudioReaper(): void {
  const wantedStudios = useAppStore((s) => s.wantedStudios);
  const studioViewers = useAppStore((s) => s.studioViewers);
  // The user's reaping policy (Settings → Planner). `enabled` is the master switch for ALL idle
  // reaping, so turning it off keeps studio sessions warm indefinitely too — one predictable rule.
  const reaperCfg = useAppStore((s) => s.idleReaper);
  const idleMs = studioIdleMs(reaperCfg);
  const enabled = reaperCfg.enabled;
  // studio id → its armed reap timer + the duration it was armed with. A ref (not state) so re-arming
  // never re-renders; the effect below reconciles it against the current wanted/viewer/config state.
  // The duration is tracked so a settings change re-arms rather than silently keeping the old clock.
  const timers = useRef<Map<StudioId, { t: ReturnType<typeof setTimeout>; ms: number; busy?: boolean }>>(new Map());

  useEffect(() => {
    const armed = timers.current;
    for (const id of STUDIO_IDS) {
      const idle = enabled && wantedStudios.includes(id) && (studioViewers[id] ?? 0) === 0;
      const timer = armed.get(id);
      if (!idle) {
        // Watched again, already reaped, or reaping switched off → cancel. This is the
        // "re-opening before expiry" path (and the master-switch-off path).
        if (timer) { clearTimeout(timer.t); armed.delete(id); }
        continue;
      }
      // Already counting down at the CURRENT threshold → leave it alone; an unrelated change (another
      // studio's churn) must not restart this clock. A changed threshold DOES re-arm, so editing the
      // setting takes effect immediately rather than only on the next idle transition. A BUSY deferral
      // is left alone either way: it is on the short recheck loop and re-evaluates itself, so treating
      // its recheck interval as a "changed threshold" would reset a working session to a full idle wait.
      if (timer && (timer.busy || timer.ms === idleMs)) continue;
      if (timer) { clearTimeout(timer.t); armed.delete(id); }

      const fire = () => {
        const st = useAppStore.getState();
        // Re-read at expiry: the arm-time snapshot is as stale as the configured threshold (30 min by
        // default, and the user can set it much longer).
        if (!st.wantedStudios.includes(id) || (st.studioViewers[id] ?? 0) > 0) { armed.delete(id); return; }
        if (!st.idleReaper.enabled) { armed.delete(id); return; } // switched off while counting down
        if (st.paneClaudeActive[STUDIO_SESSIONS[id].paneId]) {
          // Busy → defer, never cut off a turn. Re-armed at the RECHECK interval, so `ms` records that
          // (a settings change during a deferral re-arms it at the new threshold on the next reconcile).
          armed.set(id, { t: setTimeout(fire, STUDIO_BUSY_RECHECK_MS), ms: STUDIO_BUSY_RECHECK_MS, busy: true });
          return;
        }
        armed.delete(id);
        // Kill the PTY EXPLICITLY. Dropping the last TerminalHost claim only unmounts the <TerminalView>
        // (its cleanup deliberately leaves the backend session alive so a console tab-switch reconnects
        // rather than respawns) — so without this the xterm would go away while the `claude` process kept
        // running forever. Killing first, then dropping the mount, means the reclaim is complete.
        fireInvoke("pty_kill", { paneId: STUDIO_SESSIONS[id].paneId }, console.error);
        st.closeStudio(id);
      };
      armed.set(id, { t: setTimeout(fire, idleMs), ms: idleMs });
    }
  }, [wantedStudios, studioViewers, idleMs, enabled]);

  // Drop every pending timer when the host unmounts (app teardown / a test cleanup).
  useEffect(() => {
    const armed = timers.current;
    return () => { for (const { t } of armed.values()) clearTimeout(t); armed.clear(); };
  }, []);
}

runtime.features/studio-sessions/useStudioViewer:
// useStudioViewer (#3357) — the ONE way a surface says "I am showing this studio session".
//
// Both surfaces that can show a studio terminal call it: the studio page's `SessionDock` and the Glance
// node morph. On the first call the studio becomes WANTED (the lazy start — nothing launches at app boot),
// and for as long as the caller is showing it the studio's viewer count is held above zero, which keeps the
// idle reaper disarmed. When the last viewer goes away the reaper arms; the session stays warm on
// TerminalHost throughout, so re-opening inside the window reattaches to the SAME conversation.
import { useEffect } from "react";
import { useAppStore } from "@/store";
import type { StudioId } from "./lib/studioSessions";

/**
 * Register this component as a viewer of `id`'s studio session while `showing` is true.
 *
 * @param id      the studio, or null when this surface currently shows no studio (the hook then no-ops,
 *                so a caller with a conditional target — the Glance morph — can still call it
 *                unconditionally, as the rules of hooks require).
 * @param showing whether the surface is ACTUALLY on screen. A page dock stays MOUNTED but CSS-hidden when
 *                the user switches pages (`KeptMountedPage`), and a mounted-but-hidden dock must not pin
 *                the session alive forever — otherwise the reaper could never fire after a first visit.
 */
export function useStudioViewer(id: StudioId | null | undefined, showing = true): void {
  useEffect(() => {
    if (!id || !showing) return;
    const st = useAppStore.getState();
    // Showing it is what STARTS it: opening a studio page (or its Glance node) is the lazy launch.
    st.openStudio(id);
    st.addStudioViewer(id);
    return () => { useAppStore.getState().removeStudioViewer(id); };
  }, [id, showing]);
}

/**
 * The MANY form of {@link useStudioViewer} — register this surface as a viewer of every studio in `ids`.
 *
 * Needed since #3361, where several node morphs can be open at once: the single-id hook cannot be called
 * in a loop (a variable hook count breaks the rules of hooks), and calling it once with only the
 * most-recently-opened id would leave every other open studio unpinned — so the reaper could kill a
 * session the user is looking at in another morph.
 *
 * Keyed on the joined id list, so opening a second studio re-runs the effect: the cleanup decrements the
 * already-open studios and the body immediately re-increments them. That transient dip to 0 is harmless —
 * the reaper only ARMS a timer at 0 and re-checks the live count when it fires (tens of minutes later),
 * by which point the count is back up.
 */
export function useStudioViewers(ids: readonly StudioId[], showing = true): void {
  const key = ids.join(",");
  useEffect(() => {
    if (!showing || !key) return;
    const list = key.split(",") as StudioId[];
    const st = useAppStore.getState();
    for (const id of list) { st.openStudio(id); st.addStudioViewer(id); }
    return () => {
      const s = useAppStore.getState();
      for (const id of list) s.removeStudioViewer(id);
    };
  }, [key, showing]);
}

runtime.features/teams/ArchitectTerminal.tsx:
// ArchitectTerminal (#2755/#3357) — the Teams Studio's docked bottom panel showing the app-owned
// team-architect session. Renders the shared SessionDock shell (#2808). It is docked below the graph on
// BOTH levels (the Teams overview AND an entered team) and stays mounted across that switch (#2759).
//
