// The frontend ↔ teams store bridge (#2193, verb renamed org → teams in #2700). The desktop Team
// designer and every live console session + the planner share ONE global store
// (`~/.base-studio-code/orgs/<id>.json` — the on-disk dir keeps its `orgs/` name so existing data is
// not orphaned), reached here — and from a session's own shell — through the SAME `bsc teams …` CLI
// (with `bsc org` still a deprecated alias), over the generic `bsc` bridge (#2114). Teams are GLOBAL
// (no project key) so every call passes `null` as the projectKey. This is the only place the teams
// feature touches Tauri, so the pure model in `team.ts` stays React/Tauri-free. Mirrors
// personaBridge.ts exactly; the store is a write-through cache over this.
import { bsc, bscRun, bscWrite } from "@/shared/lib/core/bsc";
import type { Team } from "./team";

/**
 * Load every org from the store via `bsc org list --full`. Returns `null` when the bridge is
 * unreachable (no Tauri host — tests, the web shell, or an old binary) so the caller keeps its seeded
 * in-memory built-ins rather than blanking the library. NOT `bscJson` (its degrade-to-fallback would
 * return an empty array, which would then blank the seeded set).
 */
export async function loadOrgs(): Promise<Team[] | null> {
  try {
    const out = await bsc(null, ["teams", "list", "--full"]);
    const rows = JSON.parse(out.trim() || "[]") as Partial<Team>[];
    // Defensive: keep only well-formed rows (id present), defaulting the rest so an odd file never
    // crashes hydration.
    return (rows ?? [])
      .filter((o): o is Team => typeof o.id === "string" && !!o.id)
      .map((o) => ({
        id: o.id, name: o.name ?? "Untitled", blurb: o.blurb ?? "",
        positions: o.positions ?? [], relationships: o.relationships ?? [], builtin: o.builtin,
      }));
  } catch {
    return null;
  }
}

/** Write-through a team upsert (`bsc teams set` reads the JSON on stdin). Fire-and-forget; never throws,
 *  so an old bundled `bsc` without the `teams` subcommand degrades to store-only silently. */
export async function pushOrg(org: Team): Promise<void> {
  try { await bscWrite(null, ["teams", "set"], org); } catch { /* store unreachable — cache-only */ }
}

/** Write-through a team removal (`bsc teams remove <id>`). Never throws (see {@link pushOrg}). */
export async function dropOrg(id: string): Promise<void> {
  try { await bscRun(null, ["teams", "remove", id]); } catch { /* store unreachable — cache-only */ }
}

runtime.features/teams/lib/orgLayout.ts:
// Team canvas geometry (#2193) — pure math for the relationship graph, ported from the Claude Design
// prototype. Kept React-free so it's unit-testable and the canvas component stays a thin renderer.
// The graph lives in a fixed 1120×800 design space; the canvas scales it by a zoom factor.
import { forceSimulation, forceLink, forceManyBody, forceX, forceCollide, type SimulationNodeDatum } from "d3-force";
import { graphEdge } from "@/shared/lib/graph/edgePath";
import { layerDag } from "@/shared/lib/graph/layers";
import { findBackEdges } from "@/shared/lib/graph/cycles";
import { orderLayers } from "@/shared/lib/graph/order";
import type { GraphEdge } from "@/shared/lib/graph/types";
import type { Team, Position, PositionKind } from "./team";

/** The fixed design coordinate space every node's x/y is authored in. */
export const CANVAS_W = 1120;
export const CANVAS_H = 800;

/** Node box size per kind (design-space px) — person cards are the largest; resource/external smaller.
 *  The agent card carries the persona blurb, so it's sized to fit ~4 clamped lines comfortably (#3335,
 *  was 190×96) — longer blurbs ellipsis rather than overflow (see AgentFace). */
export const NODE_SIZE: Record<PositionKind, { w: number; h: number }> = {
  agent: { w: 206, h: 116 },
  resource: { w: 156, h: 82 },
  external: { w: 152, h: 80 },
};

export interface Box { x: number; y: number; w: number; h: number }

/** The design-space box for a position (its authored x/y + the size for its kind; 0,0 if unplaced). */
export function nodeBox(pos: Position): Box {
  const { w, h } = NODE_SIZE[pos.kind];
  return { x: pos.x ?? 0, y: pos.y ?? 0, w, h };
}

/** The tight bounding box around every placed node in `positions` (design-space), or null when there are
 *  none. Framing (fit / saved-zoom restore) centers on THIS — where the nodes actually are — instead of
 *  the fixed CANVAS box, so the graph isn't parked high / clipped when the layout fills only part of (or
 *  overflows) the canvas (#2673). Pure. */
export function contentBounds(positions: Position[]): Box | null {
  if (positions.length === 0) return null;
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const p of positions) {
    const b = nodeBox(p);
    minX = Math.min(minX, b.x);
    minY = Math.min(minY, b.y);
    maxX = Math.max(maxX, b.x + b.w);
    maxY = Math.max(maxY, b.y + b.h);
  }
  return { x: minX, y: minY, w: maxX - minX, h: maxY - minY };
}

export interface EdgeGeometry {
  /** SVG cubic-bezier path `d`. */
  d: string;
  /** The midpoint where the edge label pill sits. */
  lx: number;
  ly: number;
}

/** The bezier path + label point between two boxes, bowed by `bow` px off the straight line so parallel
 *  edges fan apart. The end is pulled back 9px to leave room for the arrowhead. Ported from `_geom`. */
export function edgeGeometry(A: Box, B: Box, bow = 0): EdgeGeometry {
  // The shared graph line-type (#2222); Team keeps its own arrowhead markers, so it only takes the
  // curve + the label midpoint. Byte-identical to the previous inline geometry.
  const { d, labelX, labelY } = graphEdge(A, B, { bow });
  return { d, lx: labelX, ly: labelY };
}

/** SVG dash-array for an archetype line style. */
export function styleDash(style: string): string {
  switch (style) {
    case "dashed": return "7 5";
    case "gated": return "3 5";
    case "dotted": return "1 6";
    case "resource": return "4 6";
    default: return "0"; // solid
  }
}

// ── Auto-organize ────────────────────────────────────────────────────────────
/** Archetypes that impose a top-down hierarchy (a parent → child flow); peers/consults are lateral and
 *  don't drive layering. */
const HIERARCHY_ARCHETYPES = new Set(["manages", "serves", "oversees", "stewards"]);

const AUTO_COL = 230; // seed horizontal spacing between nodes in a layer (before force refinement)
/** Vertical gap between hierarchy layers (fixed once assigned — keeps rows clean). Exported for the
 *  #2451 row-alignment regression tests (center-y deltas between laid-out nodes are multiples of it). */
export const AUTO_ROW = 200;

// Force-refinement tuning (fixed; the user never tunes these — #2199 follow-up). y is pinned per layer,
// so the simulation only moves nodes HORIZONTALLY: repulsion spreads a crowded row, link springs pull
// related nodes together, and a weak x-centering keeps the whole graph framed.
const LINK_DIST = 210;   // preferred edge length (a spring rest length)
const LINK_STR = 0.35;   // how hard edges pull (0–1) — gentle, so repulsion can still spread siblings
const CHARGE = -1600;    // many-body repulsion (negative = push apart) — the readability "breathing room"
const X_STR = 0.08;      // weak pull toward the horizontal center (keeps rows from drifting off-canvas)
const COLLIDE_PAD = 16;  // extra gap enforced around each card so nothing visually overlaps
const TICKS = 320;       // headless ticks to convergence (d3-force's seeded LCG makes this deterministic)
// These are tuned so a typical fleet settles well inside the 1120×800 design space (the default fleet
// lands at ~978×536) — no user knobs by design (#2199 follow-up); the graph just finds its own shape.

interface LayerResult { layer: Map<string, number>; order: Map<number, string[]> }

/** Assign each node a hierarchy layer (longest path from a root, cycle-guarded) and a crossing-reduced
 *  order within its layer (barycenter passes). The shared skeleton both the seed placement and the
 *  fixed-y force refinement build on. Exported for the #2418 layer-parity tests.
 *
 *  Since #2418 this delegates to the shared graph core: `layerDag` (longest-path layering, #2214) over
 *  the hierarchy edges with `findBackEdges` (#2217) as the cycle-break set, then `orderLayers` (the
 *  shared barycenter sweep) with org's tunables — 4 sequential passes, cross-layer hierarchy neighbors.
 *  Acyclic layer assignments are identical to the old private layerer; a cycle now breaks by DROPPING
 *  the DFS back-edge (the forward edge still layers parent-above-child) instead of the old zero-the-
 *  on-stack-parent artifact. */
export function layerNodes(org: Team): LayerResult {
  const ids = org.positions.map((p) => p.nodeId);
  const idSet = new Set(ids);
  // The hierarchy sub-graph: only top-down archetypes drive layering; parent → child is exactly
  // layerDag's "from → deeper" convention.
  const hierarchy: GraphEdge[] = org.relationships
    .filter((r) => HIERARCHY_ARCHETYPES.has(r.archetype) && idSet.has(r.from) && idSet.has(r.to))
    .map((r) => ({ id: r.id, from: r.from, to: r.to }));

  const { backEdgeIds } = findBackEdges(ids, hierarchy);
  const layerRec = layerDag(ids, hierarchy, backEdgeIds);
  const layer = new Map<string, number>(ids.map((n) => [n, layerRec[n]]));

  // Crossing reduction: a node's pull comes from its hierarchy parents+children in OTHER layers
  // (lateral archetypes don't reorder rows; back-edges still pull, as before).
  const parents = new Map<string, string[]>(ids.map((n) => [n, []]));
  const children = new Map<string, string[]>(ids.map((n) => [n, []]));
  for (const e of hierarchy) { parents.get(e.to)!.push(e.from); children.get(e.from)!.push(e.to); }
  const order = orderLayers(
    ids,
    (n) => layer.get(n)!,
    (n) => { const l = layer.get(n)!; return [...parents.get(n)!, ...children.get(n)!].filter((m) => layer.get(m) !== l); },
    { passes: 4 },
  );
  return { layer, order };
}

interface SimNode extends SimulationNodeDatum { id: string; w: number; h: number }

/** A deterministic hierarchical FORCE layout (#2199): every node is pinned to its hierarchy row (so the
 *  manager-above-reports structure stays razor-clean and same-layer nodes share an exact y), then a
 *  d3-force pass moves nodes only HORIZONTALLY — many-body repulsion gives each node breathing room,
 *  link springs pull related nodes together, and a weak centering keeps the graph framed. The result is
 *  the "natural structure" the graph finds on its own, so the user never has to hand-place a node.
 *
 *  Deterministic: d3-force seeds a fixed LCG (not `Math.random`) and the seed positions are computed, so
 *  re-running "Auto organize" reproduces the same layout. Returns fresh top-left `{x,y}` per nodeId.
 *
 *  `sizes` optionally overrides a node's box per nodeId (#2451): a synthetic pool node in a collapsed
 *  org renders as a STACKED card (agent card + shadow-stack overhang), so the collision pass must see
 *  that real footprint — not the plain agent size its `kind` implies. */
export function autoLayout(org: Team, sizes?: Record<string, { w: number; h: number }>): Record<string, { x: number; y: number }> {
  const { layer, order } = layerNodes(org);
  const rowY = (l: number) => 60 + l * AUTO_ROW;

  // Seed each node at its row (center coords), spread horizontally by its in-layer order so the force
  // pass starts from a sane, crossing-reduced arrangement rather than a random cloud.
  const nodes: SimNode[] = org.positions.map((p) => {
    const l = layer.get(p.nodeId)!;
    const row = order.get(l)!;
    const idx = row.indexOf(p.nodeId);
    const { w, h } = sizes?.[p.nodeId] ?? NODE_SIZE[p.kind];
    return {
      id: p.nodeId,
      w, h,
      x: CANVAS_W / 2 + (idx - (row.length - 1) / 2) * AUTO_COL,
      y: rowY(l),
      fy: rowY(l), // pin y to the layer row — the simulation only optimizes x
    };
  });
  const byId = new Map(nodes.map((n) => [n.id, n]));
  const links = org.relationships
    .filter((r) => byId.has(r.from) && byId.has(r.to))
    .map((r) => ({ source: r.from, target: r.to }));

  const sim = forceSimulation<SimNode>(nodes)
    .force("link", forceLink<SimNode, { source: string; target: string }>(links).id((d) => d.id).distance(LINK_DIST).strength(LINK_STR))
    .force("charge", forceManyBody<SimNode>().strength(CHARGE))
    .force("x", forceX<SimNode>(CANVAS_W / 2).strength(X_STR))
    .force("collide", forceCollide<SimNode>((d) => Math.max(d.w, d.h) / 2 + COLLIDE_PAD))
    .stop();
  for (let i = 0; i < TICKS; i++) sim.tick();

  // Convert sim centers → top-left boxes, then shift the whole graph into a padded positive space.
  const boxes = nodes.map((n) => ({ id: n.id, x: (n.x ?? 0) - n.w / 2, y: (n.y ?? 0) - n.h / 2 }));
  const minX = Math.min(...boxes.map((b) => b.x));
  const minY = Math.min(...boxes.map((b) => b.y));
  const out: Record<string, { x: number; y: number }> = {};
  for (const b of boxes) out[b.id] = { x: Math.round(b.x - minX + 60), y: Math.round(b.y - minY + 48) };
  return out;
}

runtime.features/teams/lib/orgPools.ts:
// Team pools (#2199, #2436, #3143) — consolidating a swarm of agents into ONE stacked node so large
// graphs stay readable. A POOL is positions on the same STACKABLE persona: `pooled`, or worker-role by
// default (explicit `pooled:false` opts out) — the org graph is the SCAFFOLD (director · reviewer ·
// auditor · intake · anchors) plus a stacked engineer slot per worker persona. The planner owns how many
// engineers exist (#2388), so a WORKER-role (planner-sized) slot collapses to a stack even from ONE
// placement and its card shows NO count (#3143) — a single engineer node still means "the planner
// creates however many". Other stackable personas need a real swarm (≥2) to collapse and show `×N`.
// Per-engineer wiring detail belongs in the DRILL-IN, not the top view. Heterogeneous external wiring no longer prevents stacking (#2436 — it kept Fleet Alpha's own
// engineers from ever collapsing): the collapse UNIONS external edges onto the stack, and the pool's
// `homogeneous` flag records whether members are truly interchangeable (identical external relationship
// signatures) so the UI can mark mixed-wiring stacks. Edges among members (a peer mesh) are internal —
// they show on drill-in. Pure model (React-free) so it's unit-testable, canvas stays thin.
import type { Team, Position, Relationship } from "./team";
import { autoLayout, NODE_SIZE } from "./orgLayout";
import { BUILTIN_PERSONAS, type Persona } from "@/features/personas";

/** Whether a persona's positions stack. An explicit (hydrated) `pooled` always wins — a user who
 *  un-pooled a persona is respected. Otherwise: the PACKAGED built-in's flag (covers a store copy
 *  seeded before the field existed — reconcile #2220 fixes it on next boot, this shows the pool
 *  WITHOUT a restart), and worker-role personas stack BY DEFAULT (#2436 — the engineer slot; the
 *  scaffold roles stay singletons). */
const BUILTIN_POOLED = new Map(BUILTIN_PERSONAS.map((p) => [p.id, !!p.pooled]));
function isStackable(p: Persona): boolean {
  if (p.pooled !== undefined) return p.pooled;
  return (BUILTIN_POOLED.get(p.id) ?? false) || p.role === "worker";
}

export interface Pool {
  /** Synthetic node id for the collapsed group in the parent graph (`pool:<personaId>`). */
  nodeId: string;
  /** The pooled persona every member embodies. */
  personaId: string;
  /** The member position nodeIds (the real positions the pool stands in for). */
  memberNodeIds: string[];
  /** How many instances (= memberNodeIds.length). Not shown for a `plannerSized` slot (#3143). */
  count: number;
  /** True when every member has the identical external relationship signature (truly interchangeable);
   *  false = mixed wiring, unioned onto the stack — the drill-in shows who has what. */
  homogeneous: boolean;
  /** A WORKER-role (planner-sized) slot: the planner owns the count (#2388), so the card renders as a
   *  countless "planner-sized" stack rather than `×N` — and it collapses even from a SINGLE member. */
  plannerSized: boolean;
}

/** The external relationship signature of a position: every edge to a node OUTSIDE `memberSet`, as a
 *  sorted `dir|archetype|counterpart` string. Members with equal signatures are interchangeable; edges
 *  among members (a peer mesh) are excluded. */
function externalSignature(org: Team, nodeId: string, memberSet: Set<string>): string {
  const parts: string[] = [];
  for (const r of org.relationships) {
    if (r.from === nodeId && !memberSet.has(r.to)) parts.push(`out|${r.archetype}|${r.to}`);
    else if (r.to === nodeId && !memberSet.has(r.from)) parts.push(`in|${r.archetype}|${r.from}`);
  }
  return parts.sort().join("~");
}

/** Detect the pools: every STACKABLE persona (pooled, or worker-role — the engineer stack, #2436)
 *  placed ≥2× collapses. Mixed external wiring doesn't block the stack; it only clears `homogeneous`
 *  (e.g. Fleet Alpha's engineers — one overseen by the reviewer, one by the auditor — now stack, with
 *  both oversee edges unioned onto the stack node). Non-worker singletons (the scaffold) never stack.
 *  Deterministic (positions in author order). */
export function detectPools(org: Team, personas: Persona[]): Pool[] {
  const stackable = new Set(personas.filter(isStackable).map((p) => p.id));
  // Planner-sized personas (worker role — the planner owns the count, #2388/#3143): their slot collapses
  // to a countless stack even from ONE placement, since a single engineer node still means "the planner
  // creates however many". Every OTHER stackable persona needs a real swarm (≥2) to collapse.
  const plannerSizedIds = new Set(personas.filter((p) => p.role === "worker").map((p) => p.id));
  const byPersona = new Map<string, Position[]>();
  for (const p of org.positions) {
    if (p.kind === "agent" && p.personaId && stackable.has(p.personaId)) {
      (byPersona.get(p.personaId) ?? byPersona.set(p.personaId, []).get(p.personaId)!).push(p);
    }
  }
  const pools: Pool[] = [];
  for (const [personaId, members] of byPersona) {
    const plannerSized = plannerSizedIds.has(personaId);
    if (members.length < 2 && !plannerSized) continue;
    const memberSet = new Set(members.map((m) => m.nodeId));
    const sig0 = externalSignature(org, members[0].nodeId, memberSet);
    const homogeneous = members.every((m) => externalSignature(org, m.nodeId, memberSet) === sig0);
    pools.push({ nodeId: `pool:${personaId}`, personaId, memberNodeIds: members.map((m) => m.nodeId), count: members.length, homogeneous, plannerSized });
  }
  return pools;
}

export interface CollapsedOrg {
  /** The parent graph with each pool's members replaced by one synthetic pool node. */
  org: Team;
  /** Pool metadata keyed by the synthetic pool nodeId — the canvas renders these as stacked cards. */
  poolInfo: Record<string, Pool>;
}

const avg = (xs: number[]): number => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : 0);

/** Collapse an org for the parent view: each pool's members become ONE synthetic pool position at the
 *  members' centroid; external edges are rerouted to the pool node and deduped (by from|to|archetype);
 *  internal edges (both endpoints inside one pool) are dropped. A no-op when there are no pools. */
export function collapseOrg(org: Team, pools: Pool[]): CollapsedOrg {
  if (!pools.length) return { org, poolInfo: {} };
  const memberToPool = new Map<string, Pool>();
  for (const pool of pools) for (const m of pool.memberNodeIds) memberToPool.set(m, pool);

  const positions: Position[] = org.positions.filter((p) => !memberToPool.has(p.nodeId));
  const poolInfo: Record<string, Pool> = {};
  for (const pool of pools) {
    const members = org.positions.filter((p) => memberToPool.get(p.nodeId) === pool);
    positions.push({
      nodeId: pool.nodeId, kind: "agent", personaId: pool.personaId,
      x: Math.round(avg(members.map((m) => m.x ?? 0))), y: Math.round(avg(members.map((m) => m.y ?? 0))),
    });
    poolInfo[pool.nodeId] = pool;
  }

  const remap = (nodeId: string) => memberToPool.get(nodeId)?.nodeId ?? nodeId;
  const seen = new Set<string>();
  const relationships: Relationship[] = [];
  for (const r of org.relationships) {
    const from = remap(r.from), to = remap(r.to);
    if (from === to) continue; // an internal edge, folded away
    const key = `${from}|${to}|${r.archetype}`;
    if (seen.has(key)) continue; // duplicate collapsed edge (N members → one pool edge)
    seen.add(key);
    relationships.push({ ...r, id: `pool-edge:${key}`, from, to });
  }
  return { org: { ...org, positions, relationships }, poolInfo };
}

/** The pool's OWN graph, shown when you drill in: the members, every edge touching a member (the internal
 *  peer mesh + their edges out), and the boundary neighbor nodes those edges reach (context). Positions
 *  are the members' real stored coords, so drilling reads as zooming into that cluster. */
export function poolSubgraph(org: Team, pool: Pool): Team {
  const memberSet = new Set(pool.memberNodeIds);
  const relationships = org.relationships.filter((r) => memberSet.has(r.from) || memberSet.has(r.to));
  const nodeIds = new Set<string>(pool.memberNodeIds);
  for (const r of relationships) { nodeIds.add(r.from); nodeIds.add(r.to); }
  return { ...org, id: `${org.id}::${pool.nodeId}`, positions: org.positions.filter((p) => nodeIds.has(p.nodeId)), relationships };
}

// ── Auto-organize over pools (#2451) ─────────────────────────────────────────
// `autoLayout(org)` on the FULL org laid out every pooled member as an individual node while the
// canvas renders the COLLAPSED org — so the pool card (drawn at the members' centroid) landed at the
// row center, or BETWEEN hierarchy rows when mixed wiring (#2436) put members on different layers,
// and no collision pass ever saw the stacked card. The fix: lay out the graph the user is LOOKING AT
// (the collapsed org, with the pool node carrying its real stacked-card footprint), then write back
// through the pool abstraction — translate each member cluster so its centroid is the pool's
// laid-out spot, preserving the members' relative arrangement for drill-in (#2439).

/** The stacked card's shadow-card offset (design px) — TeamsCanvas renders the outermost shadow card
 *  at `translate(POOL_STACK_OFFSET, POOL_STACK_OFFSET)`, so a pool's true render footprint is the
 *  agent card plus this overhang in each axis. The layout must see THAT size (via `poolLayoutSizes`)
 *  so collision spaces the stack like the card the user actually sees. */
export const POOL_STACK_OFFSET = 11;

/** Per-node size overrides for `autoLayout` over a COLLAPSED org: each synthetic pool node takes the
 *  stacked card's real footprint (agent card + shadow-stack overhang). */
export function poolLayoutSizes(pools: Pool[]): Record<string, { w: number; h: number }> {
  const size = { w: NODE_SIZE.agent.w + POOL_STACK_OFFSET, h: NODE_SIZE.agent.h + POOL_STACK_OFFSET };
  return Object.fromEntries(pools.map((p) => [p.nodeId, size]));
}

// The degenerate-cluster spread: when every member sits on the SAME point (typically all unplaced at
// 0,0), a pure translation would keep them exactly coincident — so instead they get a small
// deterministic grid around the pool's laid-out spot (centroid still lands ON the spot). Steps are
// deliberately smaller than a card: the parent view shows one stack either way, and the drill-in's
// own auto-organize is the real untangler.
const SPREAD_X = 60;
const SPREAD_Y = 44;

/** Write a collapsed-org layout back onto the FULL org's positions (#2451). Non-pooled nodes take
 *  their laid-out spot directly. Each pool's members are TRANSLATED by one shared delta so their
 *  centroid — where the stacked card renders (`collapseOrg`) — equals the pool node's laid-out spot,
 *  preserving the members' relative arrangement (the #2439 drill-in contract). A coincident/unplaced
 *  member cluster gets a small deterministic spread around the spot instead (see above). Pure +
 *  deterministic; returns a fresh positions array. */
export function applyPoolLayout(org: Team, pools: Pool[], layout: Record<string, { x: number; y: number }>): Position[] {
  const moved = new Map<string, { x: number; y: number }>();
  for (const pool of pools) {
    const target = layout[pool.nodeId];
    if (!target) continue; // pool absent from the laid-out graph — leave its members untouched
    const members = org.positions.filter((p) => pool.memberNodeIds.includes(p.nodeId));
    const xs = members.map((m) => m.x ?? 0);
    const ys = members.map((m) => m.y ?? 0);
    if (xs.every((x) => x === xs[0]) && ys.every((y) => y === ys[0])) {
      // Degenerate: all members coincident — deterministic compact grid, centered so centroid = target.
      const cols = Math.ceil(Math.sqrt(members.length));
      const offs = members.map((_, i) => ({ x: (i % cols) * SPREAD_X, y: Math.floor(i / cols) * SPREAD_Y }));
      const cx = avg(offs.map((o) => o.x)), cy = avg(offs.map((o) => o.y));
      members.forEach((m, i) => moved.set(m.nodeId, { x: Math.round(target.x + offs[i].x - cx), y: Math.round(target.y + offs[i].y - cy) }));
    } else {
      // One shared delta for the whole cluster (integer inputs keep relative offsets EXACT through
      // the rounding, since every member rounds with the same fractional part).
      const dx = target.x - avg(xs), dy = target.y - avg(ys);
      members.forEach((m, i) => moved.set(m.nodeId, { x: Math.round(xs[i] + dx), y: Math.round(ys[i] + dy) }));
    }
  }
  return org.positions.map((p) => {
    const next = moved.get(p.nodeId) ?? layout[p.nodeId];
    return next ? { ...p, ...next } : p;
  });
}

/** Auto-organize INSIDE a drilled pool (#2451): re-lay out ONLY the members (over their internal peer
 *  mesh), then anchor the new cluster at the members' previous centroid so the surrounding context
 *  doesn't jump. Boundary neighbors belong to the PARENT view and are never moved — chosen over
 *  layering members against pinned boundary nodes because the members are one persona (a flat
 *  row/grid near their old spot reads well) and "context stays put" is the simplest honest contract
 *  from inside a drill. Returns the full org's positions with only the members changed. */
export function organizeDrilledPool(org: Team, pool: Pool): Position[] {
  const memberSet = new Set(pool.memberNodeIds);
  const members = org.positions.filter((p) => memberSet.has(p.nodeId));
  if (!members.length) return org.positions;
  const sub: Team = {
    ...org,
    positions: members,
    relationships: org.relationships.filter((r) => memberSet.has(r.from) && memberSet.has(r.to)),
  };
  const layout = autoLayout(sub);
  const dx = avg(members.map((m) => m.x ?? 0)) - avg(members.map((m) => layout[m.nodeId].x));
  const dy = avg(members.map((m) => m.y ?? 0)) - avg(members.map((m) => layout[m.nodeId].y));
  const moved = new Map(members.map((m) => [m.nodeId, { x: Math.round(layout[m.nodeId].x + dx), y: Math.round(layout[m.nodeId].y + dy) }]));
  return org.positions.map((p) => {
    const next = moved.get(p.nodeId);
    return next ? { ...p, ...next } : p;
  });
}

runtime.features/teams/lib/orgView.ts:
// Team view models (#2193) — pure presentation helpers that turn the org graph + the persona library +
// the vocabulary into the shapes the canvas + inspector render. React-free + unit-testable; the design
// prototype's per-role glyph/department metadata lives here (presentation only, not in the data model).
import type { SessionRole } from "@/shared/lib/session/sessionRoles";
import { roleCapability } from "@/shared/lib/session/sessionRoles";
import type { Persona } from "@/features/personas";
import { archetypeById, deriveCommunication, type CommunicationForm, type Team, type Position } from "./team";

/** Per-role display metadata — the department bucket (left-rail grouping) + a glyph. Presentation-only
 *  (the role gate itself carries no glyph); a role not listed falls back to a neutral default.
 *  Intentionally inline: a view-layer glyph/label map, not seed library state — kept here by design
 *  rather than externalized to `data/` (reviewed in #2912; config-vs-presentation golden rule). */
export const ROLE_META: Record<string, { dept: string; glyph: string }> = {
  planner:    { dept: "Leadership",  glyph: "◆" },
  director:   { dept: "Leadership",  glyph: "◆" },
  worker:     { dept: "Engineering", glyph: "●" },
  issuer:     { dept: "Support",     glyph: "◇" },
  triage:     { dept: "Support",     glyph: "◇" },
  reviewer:   { dept: "Quality",     glyph: "◈" },
  tester:     { dept: "Quality",     glyph: "◈" },
  juror:      { dept: "Quality",     glyph: "▲" },
};

const KIND_GLYPH = { resource: "⬢", external: "◍" } as const;

export interface PositionDisplay {
  name: string;
  glyph: string;
  dept: string;
  /** The role tag (agents) — undefined for resource/external nodes. */
  role?: SessionRole;
  blurb: string;
  kind: Position["kind"];
}

/** Resolve a position's display fields, reading through to its persona for agent nodes. */
export function positionDisplay(pos: Position, personas: Persona[]): PositionDisplay {
  if (pos.kind !== "agent") {
    return {
      name: pos.label ?? pos.nodeId,
      glyph: KIND_GLYPH[pos.kind],
      dept: pos.kind === "resource" ? "Resource" : "External",
      blurb: pos.kind === "resource" ? "A shared resource the org stewards." : "An actor outside the org.",
      kind: pos.kind,
    };
  }
  const persona = personas.find((p) => p.id === pos.personaId);
  const role = persona?.role;
  const meta = (role && ROLE_META[role]) || { dept: "Team", glyph: "●" };
  return {
    name: pos.label ?? persona?.name ?? pos.nodeId,
    glyph: meta.glyph,
    dept: meta.dept,
    role,
    blurb: persona?.blurb ?? "",
    kind: "agent",
  };
}

export interface TierChip { label: string; tier: string }

/** The capability tiers a role carries, as `git·write`-style labels — omitting the `none` capabilities
 *  but always stating net as on/off (mirrors the design's node-card tier row). */
export function tierChips(role: SessionRole): TierChip[] {
  const cap = roleCapability(role);
  const out: TierChip[] = [];
  for (const k of ["git", "github", "code"] as const) {
    if (cap[k] !== "none") out.push({ label: `${k}·${cap[k]}`, tier: cap[k] });
  }
  out.push({ label: `net·${cap.net === "none" ? "off" : "on"}`, tier: cap.net === "none" ? "off" : "on" });
  return out;
}

export interface CommSummary {
  /** The relationship's other end. */
  counterpartNode: string;
  counterpartName: string;
  archetype: string;
  archetypeLabel: string;
  hue: number;
  /** Forms this position SENDS across the edge. */
  sends: CommunicationForm[];
  /** Forms this position RECEIVES across the edge. */
  receives: CommunicationForm[];
}

/** The per-relationship communication summary for a position — `deriveCommunication` grouped by
 *  counterpart+archetype, so the inspector shows one card per relationship (head = who, then the forms
 *  sent/received). This is the auto-derived "who I talk to and how", the generate-from-facets payoff. */
export function positionComms(org: Team, pos: Position, personas: Persona[]): CommSummary[] {
  const byKey = new Map<string, CommSummary>();
  for (const edge of deriveCommunication(org, pos.nodeId)) {
    const key = `${edge.withNode}:${edge.archetype}`;
    let sum = byKey.get(key);
    if (!sum) {
      const arch = archetypeById(edge.archetype);
      const other = org.positions.find((p) => p.nodeId === edge.withNode);
      sum = {
        counterpartNode: edge.withNode,
        counterpartName: other ? positionDisplay(other, personas).name : edge.withNode,
        archetype: edge.archetype,
        archetypeLabel: arch?.label ?? edge.archetype,
        hue: arch?.hue ?? 0,
        sends: [],
        receives: [],
      };
      byKey.set(key, sum);
    }
    (edge.dir === "out" ? sum.sends : sum.receives).push(edge.form);
  }
  return [...byKey.values()];
}

/** A CSS color for an archetype hue (oklch, so it sits in the same space as the app's tokens). */
export function hueColor(hue: number, l = 0.72, c = 0.13): string {
  return `oklch(${l} ${c} ${hue})`;
}

/** The accent color for a communication form, by its semantics (mirrors the design): authority-bearing
 *  forms are amber, blocking/advisory forms blue, the review gate purple, the rest neutral. */
export function formColor(form: CommunicationForm): string {
  if (form.id === "review") return hueColor(300, 0.75, 0.12);
  if (form.authority) return hueColor(70, 0.78, 0.12);
  if (form.id === "escalation" || form.id === "consult") return hueColor(250, 0.75, 0.12);
  return "var(--fg-dim)";
}

/** The direction glyph shown on a form chip (↓ down · ↑ up · ↔ lateral · → in/out · ⊘ the review gate). */
export function formArrow(form: CommunicationForm): string {
  if (form.id === "review") return "⊘";
  switch (form.direction) {
    case "down": return "↓";
    case "up": return "↑";
    case "lateral": return "↔";
    default: return "→";
  }
}

runtime.features/teams/lib/team.ts:
// Team relationships (#2193) — the persona-relationship graph. A PERSONA is a job POSITION; an ORG
// wires positions together with RELATIONSHIPS, each an archetype (Manages / Serves / Oversees /
// Consults / Peers / Stewards) that expands into directed COMMUNICATION FORMS. This makes a fleet's
// interaction topology + coordination prose composable DATA (continuing #2185 / #2027) instead of
// prose hardcoded in fleet/*-protocol.md. Pure model (no React/Tauri) so it's unit-testable and the
// store seeds from it directly. The closed vocabulary (forms + archetypes) is externalized to
// @data/teams/*; the built-in orgs to @data/teams/orgs/*.json — overlay-editable + in the config bundle.
import { poolNodeId } from "@/shared/lib/session/requestSpawn";
import formsEmbedded from "@data/teams/communication-forms.json";
import archetypesEmbedded from "@data/teams/archetypes.json";
import { overlayFile, overlayGlob } from "@/shared/lib/core/configOverrides";
import { slugify } from "@/shared/lib/core/format";

/** The canonical orientation a form typically flows (a HINT; an archetype's lane placement wins). */
export type FormDirection = "down" | "up" | "lateral" | "in" | "out";
/** How the receiver handles the message — the part that isn't "just a command". */
export type FormDelivery =
  | "inject" | "park" | "resume" | "fire-and-forget" | "queue" | "artifact" | "transfer";

/** A communication form — one typed interaction (#2193). The closed core vocabulary; each carries the
 *  runtime properties an edge needs: who blocks, whether it bears authority, and its transport verb. */
export interface CommunicationForm {
  id: string;
  label: string;
  direction: FormDirection;
  delivery: FormDelivery;
  /** Bears authority (a directive/decision/verdict) vs a peer/advisory message. */
  authority: boolean;
  /** Parks the caller until answered (only `escalation`/`review` block today). */
  blocks: boolean;
  /** The `bsc-*` shell verb that carries it at runtime, if one exists yet. */
  transport?: string;
  blurb: string;
}

/** Edge line-style for the canvas, per archetype. */
export type ArchetypeStyle = "solid" | "dashed" | "dotted" | "gated" | "resource";

/** A relationship archetype (#2193) — a named bundle of communication forms per direction. The user
 *  connects two positions with an archetype; it expands into the concrete forms flowing each way. */
export interface RelationshipArchetype {
  id: string;
  label: string;
  style: ArchetypeStyle;
  /** Hue (0–360) for the edge color + legend. */
  hue: number;
  /** Human labels for the two ends (e.g. manager / report). */
  fromLabel: string;
  toLabel: string;
  /** Form ids flowing from → to. */
  forward: string[];
  /** Form ids flowing to → from. */
  backward: string[];
  /** A symmetric relationship (peer/consult) — the canvas draws a double-headed arrow. */
  bidirectional?: boolean;
  /** A CYCLICAL relationship (#2578) — the two positions form a deliberate feedback LOOP (auditor ⟳
   *  subject), so it is allowed to close a cycle in the graph and renders as an intentional iteration
   *  loop rather than the red mutual-dependency HAZARD. Only `iterates` carries this today. */
  cyclical?: boolean;
  blurb: string;
}

/** A position's kind: an agent (a persona), an external actor (a human/system outside the org), or a
 *  resource the org stewards (e.g. the shared commons). */
export type PositionKind = "agent" | "external" | "resource";

/** A node in an org graph — a placed position. `nodeId` is unique WITHIN the org (an org may place the
 *  same persona twice, e.g. Engineer A / Engineer B, so the persona id is not the node identity). */
export interface Position {
  nodeId: string;
  kind: PositionKind;
  /** For `agent` positions: the persona this node embodies (its behavior/role/skills). */
  personaId?: string;
  /** Display override — required for external/resource nodes; optional label for a duplicated persona. */
  label?: string;
  /** Canvas layout (optional; the designer places them). */
  x?: number;
  y?: number;
}

/** A directed relationship edge between two positions (by `nodeId`). A two-way relationship is a
 *  complementary pair of forms within one archetype, not two edges. */
export interface Relationship {
  id: string;
  archetype: string;
  from: string;
  to: string;
  /** Optional curvature (px) for the canvas edge, to fan parallel edges apart. */
  bow?: number;
}

/** An org — a named composition of positions wired by relationships (like a blueprint composes stages).
 *  The unit the `bsc org` store round-trips and the Team designer edits. */
export interface Team {
  id: string;
  name: string;
  blurb?: string;
  positions: Position[];
  relationships: Relationship[];
  /** A packaged org: seeded from code, restored on refresh; clonable + editable but not deletable. */
  builtin?: boolean;
}

/** A packaged org definition (@data/teams/orgs/*.json) — an {@link Team} plus a load-time-only `order`. */
interface OrgDef extends Omit<Team, "builtin"> {
  order?: number;
}

// ── The closed vocabulary (externalized, config-dir-overlaid, in the config bundle) ──────────────
/** Every communication form, cheapest-authority first. */
export const COMMUNICATION_FORMS: CommunicationForm[] =
  overlayFile("teams/communication-forms.json", formsEmbedded as CommunicationForm[]);

/** Every relationship archetype. */
export const RELATIONSHIP_ARCHETYPES: RelationshipArchetype[] =
  overlayFile("teams/archetypes.json", archetypesEmbedded as RelationshipArchetype[]);

const FORM_BY_ID = new Map(COMMUNICATION_FORMS.map((f) => [f.id, f]));
const ARCHETYPE_BY_ID = new Map(RELATIONSHIP_ARCHETYPES.map((a) => [a.id, a]));

/** Look up a communication form by id (undefined if the vocabulary doesn't define it). */
export const formById = (id: string): CommunicationForm | undefined => FORM_BY_ID.get(id);
/** Look up a relationship archetype by id. */
export const archetypeById = (id: string): RelationshipArchetype | undefined => ARCHETYPE_BY_ID.get(id);

// ── Built-in orgs ────────────────────────────────────────────────────────────────────────────────
const orgModules = import.meta.glob<{ default: OrgDef }>("@data/teams/orgs/*.json", { eager: true });

/** Assemble the packaged org library from the per-org JSON defs: overlay the config-dir copies, order
 *  them, strip the load-time `order`, and stamp `builtin`. */
export function makeBuiltinOrgs(): Team[] {
  return overlayGlob<OrgDef>("teams/orgs", orgModules)
    .map(([, def]) => def)
    .sort((a, b) => (a.order ?? 0) - (b.order ?? 0))
    .map(({ order: _order, ...o }) => ({
      ...o,
      positions: o.positions ?? [],
      relationships: o.relationships ?? [],
      builtin: true,
    }));
}

/** The packaged orgs (currently the Default fleet), so the designer is populated on day one. */
export const BUILTIN_ORGS: Team[] = makeBuiltinOrgs();

/** The built-in Studio Network team (#2940) — the id the debug overlay below keys off. */
export const STUDIO_NETWORK_ID = "org-planning-studio";
const DEBUGGER_NODE = "debugger";

/**
 * A RUNTIME overlay on the Studio Network (#3317): when the debug session is toggled on (Settings,
 * `debugSession`, #3298), the **debugger** joins the graph and SERVES the designer — it drains the
 * `bsc request` queue, fixing the `bsc ui` tooling the designer reports. Backed by the `persona-debugger`
 * identity (the app's full-capability `debugger` role, #3322); the live session launches bypass on the
 * shared TerminalHost via `DebugSessionMount` (#3326). Not persisted — the seed stays the always-on
 * network; dragging the overlay
 * no-ops against the stored team. A no-op when off, for a non-studio team, or if already present.
 */
export function augmentStudioNetworkForDebug(org: Team, debugOn: boolean): Team {
  if (!debugOn || org.id !== STUDIO_NETWORK_ID) return org;
  if (org.positions.some((p) => p.nodeId === DEBUGGER_NODE)) return org;
  return {
    ...org,
    positions: [
      ...org.positions,
      { nodeId: DEBUGGER_NODE, kind: "agent", personaId: "persona-debugger", x: 144, y: 48 },
    ],
    relationships: [
      ...org.relationships,
      { id: "r-serves-debugger", archetype: "serves", from: DEBUGGER_NODE, to: "designer", bow: -30 },
    ],
  };
}

/**
 * Add a node per LIVE auto-spawned request session (#3498), so each one is visible and openable in the
 * Glance graph instead of a hidden background actor. An auto-spawned session the user cannot see is one
 * they cannot supervise or stop, which is the whole reason this exists.
 *
 * Each relates `serves → designer`, exactly as the standing debugger node does — a request session
 * serves the designer's report. Deliberately NOT related to the `debugger` node: that node only exists
 * while the `debugSession` flag is on, and an edge to an absent node would dangle. Idempotent, and a
 * no-op off the Studio Network or with no live sessions.
 */
export function augmentStudioNetworkForRequests(org: Team, poolSlots: readonly number[]): Team {
  if (!poolSlots.length || org.id !== STUDIO_NETWORK_ID) return org;
  const present = new Set(org.positions.map((p) => p.nodeId));
  const add = poolSlots.filter((slot) => !present.has(poolNodeId(slot)));
  if (!add.length) return org;
  return {
    ...org,
    positions: [
      ...org.positions,
      // Fanned in a row beneath the debugger's slot so N sessions never stack on one point.
      ...add.map((slot, i) => ({
        nodeId: poolNodeId(slot),
        kind: "agent" as const,
        personaId: "persona-debugger",
        x: 96 + i * 72,
        y: 132,
      })),
    ],
    relationships: [
      ...org.relationships,
      ...add.map((slot) => ({
        id: `r-serves-${poolNodeId(slot)}`,
        archetype: "serves",
        from: poolNodeId(slot),
        to: "designer",
        bow: -18,
      })),
    ],
  };
}

// ── Derivation: the communication summary the UI shows (the generate-from-facets payoff) ─────────
/** One derived communication edge for a position: a form flowing IN or OUT, the other node, and the
 *  archetype it came from. */
export interface CommEdge {
  form: CommunicationForm;
  /** The nodeId on the other end. */
  withNode: string;
  archetype: string;
  dir: "in" | "out";
}

/** Derive a position's full communication surface from the org's relationships — every form flowing in
 *  and out across its edges. This is the auto-generated "who I talk to and how" the panel/prompt read
 *  from, so the topology has one source of truth (the graph), never hand-written per persona. */
export function deriveCommunication(org: Team, nodeId: string): CommEdge[] {
  const out: CommEdge[] = [];
  for (const rel of org.relationships) {
    const arch = archetypeById(rel.archetype);
    if (!arch) continue;
    const push = (formIds: string[], withNode: string, dir: "in" | "out") => {
      for (const fid of formIds) {
        const form = formById(fid);
        if (form) out.push({ form, withNode, archetype: rel.archetype, dir });
      }
    };
    if (rel.from === nodeId) {
      push(arch.forward, rel.to, "out");
      push(arch.backward, rel.to, "in");
    } else if (rel.to === nodeId) {
      push(arch.forward, rel.from, "in");
      push(arch.backward, rel.from, "out");
    }
  }
  return out;
}

// ── Validation ───────────────────────────────────────────────────────────────────────────────────
/** Structural problems in an org: an edge to/from a missing node, or an unknown archetype. Empty means
 *  the graph is well-formed. The designer surfaces these; tests assert built-ins are clean. */
export function orgIssues(org: Team): string[] {
  const issues: string[] = [];
  const nodes = new Set(org.positions.map((p) => p.nodeId));
  for (const r of org.relationships) {
    if (!nodes.has(r.from)) issues.push(`relationship ${r.id}: unknown from-node "${r.from}"`);
    if (!nodes.has(r.to)) issues.push(`relationship ${r.id}: unknown to-node "${r.to}"`);
    if (!archetypeById(r.archetype)) issues.push(`relationship ${r.id}: unknown archetype "${r.archetype}"`);
  }
  return issues;
}

// ── CRUD helpers (mirror personas) ───────────────────────────────────────────────────────────────
/** Slugify an org name into an id fragment. */
export function orgSlug(name: string): string {
  return slugify(name) || "org";
}

/** A blank user team — the "new team" template (the data entity is still an `Team`; the display noun is
 *  "team", #org→team-rename). */
export function blankOrg(id: string): Team {
  return { id, name: "New team", blurb: "", positions: [], relationships: [] };
}

/** Merge the packaged built-ins with the persisted set: every built-in is present (re-seeded if
 *  dropped), user edits to a built-in are kept, and user-authored orgs are preserved. Keyed by id;
 *  built-in identity is restored so a stale persisted `builtin:false` can't make a packaged org
 *  deletable. Mirrors `reconcilePersonas`. */
export function reconcileOrgs(persisted: Team[]): Team[] {
  const byId = new Map(persisted.map((o) => [o.id, o]));
  const out: Team[] = BUILTIN_ORGS.map((base) => {
    // A built-in team's STRUCTURE is PACKAGED-AUTHORITATIVE (#3330). The app evolves its own built-in teams
    // (the Studio Network grew across #3317/#3322/#2940), but the on-disk store (`~/.base-studio-code/orgs/`)
    // is seeded once and frozen at that version — so a `{ ...base, ...saved }` merge let the stale on-disk
    // copy shadow every later packaged update. We now always take the packaged `base` for a built-in id, so
    // updates to the packaged JSON reach every install. To customize a built-in, CLONE it (→ a user team,
    // carried through untouched below). The on-disk copy is refreshed to match by `hydrateOrgs`.
    byId.delete(base.id);
    return base;
  });
  // On-disk-only USER teams (non-built-in ids) are preserved verbatim — only their `builtin` flag is forced
  // false so a stale/hand-set flag can't masquerade a user team as a built-in.
  for (const o of byId.values()) out.push({ ...o, builtin: false });
  return out;
}

/** A stable content key for a team's authored STRUCTURE (name + blurb + positions + relationships), used to
 *  detect on-disk drift from the packaged built-in (#3330) so `hydrateOrgs` re-pushes only what changed —
 *  never the `builtin` flag or ids, which are structural constants. */
export function orgStructureKey(o: Team): string {
  return JSON.stringify([o.name, o.blurb, o.positions, o.relationships]);
}

runtime.features/teams/lib/teamsLayout.ts:
// Teams-overview layout (#2742) — the NEW top graph level: every team is a card laid out in a grid, so
// the user navigates teams IN the graph (click a card to enter) instead of a header dropdown. Pure +
// deterministic (no Date/Math.random), so `teamsBounds` can drive the viewport fit exactly like the
// per-team `contentBounds`. Card boxes are in the same design space as position `nodeBox`es.
import type { Box } from "./orgLayout";
import { positionDisplay } from "./orgView";
import type { Team } from "./team";
import type { Persona } from "@/features/personas";

export const TEAM_CARD_W = 288;
export const TEAM_CARD_H = 160;
const GAP_X = 40;
const GAP_Y = 44;
const ORIGIN_X = 60;
const ORIGIN_Y = 56;

/** Column count for `count` cards — a squarish grid, capped at 3 wide so cards stay readable. */
function columns(count: number): number {
  return Math.max(1, Math.min(3, Math.ceil(Math.sqrt(Math.max(1, count)))));
}

/** Grid boxes for `count` cells (team cards + the trailing "new team" card), row-major. */
export function teamsGrid(count: number): Box[] {
  const cols = columns(count);
  return Array.from({ length: count }, (_, i) => {
    const r = Math.floor(i / cols), c = i % cols;
    return {
      x: ORIGIN_X + c * (TEAM_CARD_W + GAP_X),
      y: ORIGIN_Y + r * (TEAM_CARD_H + GAP_Y),
      w: TEAM_CARD_W, h: TEAM_CARD_H,
    };
  });
}

/** The tight bounding box around all `count` cells — what the viewport fits/centers on (#2673-style). */
export function teamsBounds(count: number): Box | null {
  if (count <= 0) return null;
  const boxes = teamsGrid(count);
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const b of boxes) {
    minX = Math.min(minX, b.x); minY = Math.min(minY, b.y);
    maxX = Math.max(maxX, b.x + b.w); maxY = Math.max(maxY, b.y + b.h);
  }
  return { x: minX, y: minY, w: maxX - minX, h: maxY - minY };
}

export interface TeamStats {
  positions: number;
  agents: number;
  resources: number;
  externals: number;
  /** Distinct departments present (from each position's `positionDisplay(...).dept`). */
  depts: string[];
}

/** Headline counts for a team card (positions by kind + the department spread). Pure. */
export function teamStats(team: Team, personas: Persona[]): TeamStats {
  const positions = team.positions.length;
  const agents = team.positions.filter((p) => p.kind === "agent").length;
  const resources = team.positions.filter((p) => p.kind === "resource").length;
  const externals = team.positions.filter((p) => p.kind === "external").length;
  const depts = [...new Set(team.positions.map((p) => positionDisplay(p, personas).dept))];
  return { positions, agents, resources, externals, depts };
}

runtime.features/teams/store.ts:
// Team feature store slice (#2193) — the persona-relationship graph library, a WRITE-THROUGH cache over
// the global teams store (`~/.base-studio-code/orgs/`, reached via `bsc teams` — see orgBridge.ts). The
// desktop Team designer, live sessions, and the planner share ONE store. On boot `hydrateOrgs` loads
// through the bridge + reconciles the packaged built-ins; every mutation below pushes through. The
// persisted `teams` in app-state is just a fast first-paint cache; hydrate is authoritative.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import {
  BUILTIN_ORGS, blankOrg, orgSlug, reconcileOrgs, orgStructureKey,
  type Team, type Position, type Relationship,
} from "./lib/team";
import { loadOrgs, pushOrg, dropOrg } from "./lib/orgBridge";

export interface OrgSlice {
  /** The org library — packaged built-ins (reconciled on load) + user-authored. */
  teams: Team[];
  /** Last canvas zoom per org id (view state, persisted) so reopening an org restores its framing. */
  teamsZoom: Record<string, number>;
  /** Remember an org's canvas zoom. */
  setTeamsZoom: (orgId: string, zoom: number) => void;
  /** Hydrate the library from the global org store on boot (#2193): load via the bridge, reconcile the
   *  packaged built-ins, and push any newly-seeded built-in back so the store has it. No-op (keeps the
   *  seeded set) when the bridge is unreachable — tests, the web shell, or an old binary. */
  hydrateOrgs: () => Promise<void>;
  /** Create a user org and return its new id. */
  addOrg: () => string;
  /** Clone any org (incl. a built-in) into a new editable user org; returns the new id. */
  cloneOrg: (id: string) => string;
  /** Patch an org's editable fields. Built-ins keep their builtin identity; only user teams can be
   *  deleted. */
  updateOrg: (id: string, patch: Partial<Omit<Team, "id" | "builtin">>) => void;
  /** Remove a USER org (built-ins are not deletable — no-op). */
  removeOrg: (id: string) => void;
  /** Add a position (node) to an org. */
  addPosition: (orgId: string, position: Position) => void;
  /** Patch a position's fields (label, persona, x/y, …) by nodeId. */
  updatePosition: (orgId: string, nodeId: string, patch: Partial<Omit<Position, "nodeId">>) => void;
  /** Remove a position and every relationship touching it. */
  removePosition: (orgId: string, nodeId: string) => void;
  /** Add a relationship edge to an org. */
  addRelationship: (orgId: string, relationship: Relationship) => void;
  /** Patch a relationship (e.g. change its archetype) by id. */
  updateRelationship: (orgId: string, relationshipId: string, patch: Partial<Omit<Relationship, "id">>) => void;
  /** Remove a relationship by id. */
  removeRelationship: (orgId: string, relationshipId: string) => void;
}

/** Mint a fresh, collision-free user-org id from a name (or a generic seed). */
function mintOrgId(existing: Team[], name: string): string {
  const base = `org-${orgSlug(name)}`;
  if (!existing.some((o) => o.id === base)) return base;
  let n = 2;
  while (existing.some((o) => o.id === `${base}-${n}`)) n++;
  return `${base}-${n}`;
}

export const createOrgSlice: StateCreator<AppStore, [], [], OrgSlice> = (set, get) => {
  /** Patch one org in place, push the result through the bridge. Central so every mutation converges. */
  const mutate = (id: string, fn: (o: Team) => Team) => {
    let updated: Team | undefined;
    set((s) => ({
      teams: s.teams.map((o) => {
        if (o.id !== id) return o;
        updated = fn(o);
        return updated;
      }),
    }));
    if (updated) void pushOrg(updated);
  };

  return {
    teams: BUILTIN_ORGS,
    teamsZoom: {},

    setTeamsZoom: (orgId, zoom) => set((s) => ({ teamsZoom: { ...s.teamsZoom, [orgId]: zoom } })),

    hydrateOrgs: async () => {
      const loaded = await loadOrgs();
      if (!loaded) return; // bridge unreachable — keep the seeded built-ins
      const reconciled = reconcileOrgs(loaded);
      set({ teams: reconciled });
      // Refresh the on-disk store so `bsc teams` (sessions + the planner) sees the SAME reconciled library
      // the UI does (#3330). Push back any built-in that's MISSING (first run / a new packaged org) OR whose
      // on-disk copy has DRIFTED from the packaged def — the latter is the stale-seed fix: a built-in seeded
      // at an old version (frozen on disk) is re-pushed to the current packaged structure. User teams are
      // never touched here (they aren't in BUILTIN_ORGS / reconciled built-ins).
      const savedKey = new Map(loaded.map((o) => [o.id, orgStructureKey(o)]));
      for (const o of reconciled) {
        if (!o.builtin) continue;
        const prior = savedKey.get(o.id);
        if (prior === undefined || prior !== orgStructureKey(o)) void pushOrg(o);
      }
    },

    addOrg: () => {
      const id = mintOrgId(get().teams, "new team");
      const org = blankOrg(id);
      set((s) => ({ teams: [...s.teams, org] }));
      void pushOrg(org);
      return id;
    },

    cloneOrg: (id) => {
      const src = get().teams.find((o) => o.id === id);
      if (!src) return id;
      const name = `${src.name} copy`;
      const newId = mintOrgId(get().teams, name);
      const clone: Team = { ...src, id: newId, name, builtin: false };
      set((s) => ({ teams: [...s.teams, clone] }));
      void pushOrg(clone);
      return newId;
    },

    updateOrg: (id, patch) => mutate(id, (o) => ({ ...o, ...patch, id: o.id, builtin: o.builtin })),

    removeOrg: (id) => {
      const target = get().teams.find((o) => o.id === id);
      if (!target || target.builtin) return; // built-ins are not deletable
      set((s) => ({ teams: s.teams.filter((o) => o.id !== id) }));
      void dropOrg(id);
    },

    addPosition: (orgId, position) =>
      mutate(orgId, (o) => ({ ...o, positions: [...o.positions, position] })),

    updatePosition: (orgId, nodeId, patch) =>
      mutate(orgId, (o) => ({
        ...o,
        positions: o.positions.map((p) => (p.nodeId === nodeId ? { ...p, ...patch, nodeId: p.nodeId } : p)),
      })),

    removePosition: (orgId, nodeId) =>
      mutate(orgId, (o) => ({
        ...o,
        positions: o.positions.filter((p) => p.nodeId !== nodeId),
        // Drop every edge that touched the removed node so the graph stays well-formed.
        relationships: o.relationships.filter((r) => r.from !== nodeId && r.to !== nodeId),
      })),

    addRelationship: (orgId, relationship) =>
      mutate(orgId, (o) => ({ ...o, relationships: [...o.relationships, relationship] })),

    updateRelationship: (orgId, relationshipId, patch) =>
      mutate(orgId, (o) => ({
        ...o,
        relationships: o.relationships.map((r) => (r.id === relationshipId ? { ...r, ...patch, id: r.id } : r)),
      })),

    removeRelationship: (orgId, relationshipId) =>
      mutate(orgId, (o) => ({ ...o, relationships: o.relationships.filter((r) => r.id !== relationshipId) })),
  };
};

runtime.features/teams/TeamsCanvas.tsx:
// The org canvas (#2193, interactive #2199) — the relationship graph: nodes (positions) + curved edges
// (relationships). Renders the WORLD-LAYER content (grid + edges + labels + nodes) and owns NODE-DRAG
// (a local preview that commits to the store on drop). The pan/zoom viewport frame is owned by the
// shared GraphCanvas template + useGraphViewport in the parent (#2208, epic #2197 slice 2) — a press
// on a node's `[data-node]` element does not start a background pan. Pure geometry lives in
// orgLayout.ts, view metadata in orgView.ts. The relationship legend is OrgLegend (a fixed overlay).
import { useRef, useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import { SectionLabel } from "@/shared/ui/layout/SectionLabel";
import { RELATIONSHIP_ARCHETYPES, archetypeById, type Team } from "./lib/team";
import { CANVAS_W, CANVAS_H, nodeBox, edgeGeometry, styleDash } from "./lib/orgLayout";
import { positionDisplay, hueColor, type PositionDisplay } from "./lib/orgView";
import { Chip } from "@/shared/ui/data/Chip";
import { POOL_STACK_OFFSET, type Pool } from "./lib/orgPools";
import type { Persona } from "@/features/personas";

export interface Selection { type: "node" | "edge"; id: string }

interface CanvasProps {
  org: Team;
  personas: Persona[];
  sel: Selection;
  /** Current viewport scale — converts a client-pixel drag delta into design-space. */
  scale: number;
  /** Connect-mode is active — a node press is a connect click, never a drag. */
  connecting: boolean;
  /** True during a background pan-drag — suppresses the edge click that ends it. */
  dragMoved: React.MutableRefObject<boolean>;
  /** Synthetic pool nodes (a collapsed swarm) keyed by nodeId — rendered as stacked cards: a click
   *  drills in, a drag moves the whole stack (#2439). Empty inside a pool's own sub-graph. */
  poolInfo?: Record<string, Pool>;
  onSelectNode: (nodeId: string) => void;
  onSelectEdge: (relId: string) => void;
  onMoveNode: (nodeId: string, x: number, y: number) => void;
  /** A pool card was DRAGGED by (dx, dy) design-space units (#2439). The pool node is synthetic —
   *  rendered at its members' centroid — so the owner shifts every member by the delta; the centroid
   *  then lands where the user dropped the stack. */
  onMovePool?: (poolNodeId: string, dx: number, dy: number) => void;
  /** Right-click a node/edge → open the canvas context menu (delete, …). #2385. */
  onContext?: (sel: Selection, e: React.MouseEvent) => void;
}

const DRAG_THRESHOLD = 4; // px of movement before a press becomes a drag (vs a click)

/** The agent card face (glyph · name + role pill · blurb) — shared by a normal agent node and the top
 *  card of a pool's stack. */
function AgentFace({ d, isSel }: { d: PositionDisplay; isSel: boolean }) {
  return (
    <Box style={{ width: "100%", height: "100%", boxSizing: "border-box", padding: "10px 12px",
      display: "flex", flexDirection: "column", gap: 8, borderRadius: 13, background: "var(--bg-elev)",
      border: `1px solid ${isSel ? "var(--accent)" : "var(--border)"}`,
      boxShadow: isSel ? "0 0 0 4px color-mix(in oklch, var(--accent) 18%, transparent)" : "0 3px 12px rgba(0,0,0,.3)" }}>
      <Row gap={9} align="start">
        <Box style={{ width: 27, height: 27, borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center",
          fontSize: 13, color: isSel ? "#fff" : "var(--accent)", background: isSel ? "var(--accent)" : "color-mix(in oklch, var(--accent) 14%, transparent)", flex: "none" }}>{d.glyph}</Box>
        <Box style={{ minWidth: 0, flex: 1 }}>
          <Row gap={6} align="center">
            <Text as="span" weight={600} size={13.5} style={{ lineHeight: 1.15, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{d.name}</Text>
            {d.role && <Chip color="var(--accent)" style={{ flex: "none" }}>{d.role}</Chip>}
          </Row>
          {/* Clamp the blurb to 4 lines (#3335) so a long persona description ellipsis-truncates inside the
              card instead of overflowing the node box; the full text stays in the inspector. */}
          <Text as="div" size={10.5} tone="muted" style={{ lineHeight: 1.3, marginTop: 2,
            display: "-webkit-box", WebkitLineClamp: 4, WebkitBoxOrient: "vertical", overflow: "hidden" }}>{d.blurb}</Text>
        </Box>
      </Row>
    </Box>
  );
}

/** The world-layer content — placed inside GraphCanvas's transformed world box. */
export function TeamsCanvas(props: CanvasProps) {
  const { org, personas, sel, scale, connecting, dragMoved, poolInfo,
    onSelectNode, onSelectEdge, onMoveNode, onMovePool, onContext } = props;
  /** Right-click a node/edge → open the context menu at the cursor (delete). */
  const context = (s: Selection) => (e: React.MouseEvent) => { e.preventDefault(); e.stopPropagation(); onContext?.(s, e); };

  const boxes = new Map(org.positions.map((p) => [p.nodeId, nodeBox(p)]));
  // Live node-drag preview (design-space x/y). Commits to the store on drop.
  const [drag, setDrag] = useState<{ nodeId: string; x: number; y: number } | null>(null);
  const gesture = useRef<{ nodeId: string; sx: number; sy: number; bx: number; by: number; moved: boolean } | null>(null);
  // A pool card shares the node drag machinery (#2439) — the live preview moves the stacked card via
  // `at()` like any node. Only the drop differs: a drag reports the DELTA (the owner shifts every
  // member, since the synthetic node re-renders at the members' centroid); a plain click just SELECTS
  // the pool node (the drill into pool members was dropped, #2750).
  const onPoolDown = (poolNodeId: string) => (e: React.PointerEvent) => {
    e.stopPropagation();
    const b = boxes.get(poolNodeId)!;
    gesture.current = { nodeId: poolNodeId, sx: e.clientX, sy: e.clientY, bx: b.x, by: b.y, moved: false };
    (e.currentTarget as HTMLElement).setPointerCapture?.(e.pointerId);
  };
  const onPoolUp = (poolNodeId: string) => (e: React.PointerEvent) => {
    const g = gesture.current;
    gesture.current = null;
    setDrag(null);
    (e.currentTarget as HTMLElement).releasePointerCapture?.(e.pointerId);
    if (g && g.moved) onMovePool?.(poolNodeId, Math.round((e.clientX - g.sx) / scale), Math.round((e.clientY - g.sy) / scale));
    else onSelectNode(poolNodeId);
  };

  /** The x/y to render a node at — its live drag preview if being dragged, else its stored box. */
  const at = (nodeId: string) => (drag?.nodeId === nodeId ? drag : boxes.get(nodeId)!);
  /** The box for edge geometry, with the (possibly dragged) live position substituted in. */
  const liveBox = (nodeId: string) => ({ ...boxes.get(nodeId)!, ...at(nodeId) });

  /** An edge click, suppressed if a background pan-drag just ended over it. stopPropagation so it
   *  doesn't bubble to the canvas backdrop's deselect handler (#2230). */
  const edgeClick = (relId: string) => (e: React.MouseEvent) => { e.stopPropagation(); if (!dragMoved.current) onSelectEdge(relId); };

  // Whether something is actually selected. The empty sentinel {type:"node", id:""} means "nothing
  // focused" (a background-click deselect, or a pool drill) — then the whole graph renders at full
  // opacity rather than dimming everything (#2230).
  const focused = !(sel.type === "node" && sel.id === "");

  const nodeActive = (id: string): boolean => {
    if (sel.type === "node") return id === sel.id;
    const e = org.relationships.find((r) => r.id === sel.id);
    return !!e && (e.from === id || e.to === id);
  };
  const edgeActive = (from: string, to: string): boolean =>
    sel.type === "edge" ? false : from === sel.id || to === sel.id;

  const onNodeDown = (nodeId: string) => (e: React.PointerEvent) => {
    e.stopPropagation(); // don't start a background pan
    const b = boxes.get(nodeId)!;
    gesture.current = { nodeId, sx: e.clientX, sy: e.clientY, bx: b.x, by: b.y, moved: false };
    (e.currentTarget as HTMLElement).setPointerCapture?.(e.pointerId);
  };
  const onNodeMove = (e: React.PointerEvent) => {
    const g = gesture.current;
    if (!g || connecting) return;
    if (!g.moved && Math.hypot(e.clientX - g.sx, e.clientY - g.sy) < DRAG_THRESHOLD) return;
    g.moved = true;
    setDrag({ nodeId: g.nodeId, x: Math.round(g.bx + (e.clientX - g.sx) / scale), y: Math.round(g.by + (e.clientY - g.sy) / scale) });
  };
  const onNodeUp = (nodeId: string) => (e: React.PointerEvent) => {
    const g = gesture.current;
    gesture.current = null;
    setDrag(null);
    (e.currentTarget as HTMLElement).releasePointerCapture?.(e.pointerId);
    if (g && g.moved && !connecting) onMoveNode(nodeId, Math.round(g.bx + (e.clientX - g.sx) / scale), Math.round(g.by + (e.clientY - g.sy) / scale));
    else onSelectNode(nodeId); // a click (also drives connect-mode)
  };

  return (
    <>
      {/* The dotted graph-paper backdrop is owned by the shared GraphCanvas (an infinite viewport grid),
          so it fills the whole canvas instead of stopping at the world box this content overflows. */}

      {/* edges */}
      <svg viewBox={`0 0 ${CANVAS_W} ${CANVAS_H}`} style={{ position: "absolute", left: 0, top: 0, width: CANVAS_W, height: CANVAS_H, overflow: "visible" }}>
        <defs>
          <marker id="org-ah" markerWidth={10} markerHeight={10} refX={7} refY={3.4} orient="auto" markerUnits="userSpaceOnUse">
            <path d="M0,0 L7.5,3.4 L0,6.8 Z" fill="context-stroke" />
          </marker>
          <marker id="org-ah-s" markerWidth={10} markerHeight={10} refX={7} refY={3.4} orient="auto-start-reverse" markerUnits="userSpaceOnUse">
            <path d="M0,0 L7.5,3.4 L0,6.8 Z" fill="context-stroke" />
          </marker>
        </defs>
        {org.relationships.map((r) => {
          const arch = archetypeById(r.archetype);
          if (!arch || !boxes.get(r.from) || !boxes.get(r.to)) return null;
          const { d } = edgeGeometry(liveBox(r.from), liveBox(r.to), r.bow ?? 0);
          const act = edgeActive(r.from, r.to);
          const isSelEdge = sel.type === "edge" && r.id === sel.id;
          const color = hueColor(arch.hue);
          return (
            <g key={r.id}>
              <path d={d} fill="none" stroke="transparent" strokeWidth={18} style={{ cursor: "pointer" }} onClick={edgeClick(r.id)} onContextMenu={context({ type: "edge", id: r.id })} />
              <path d={d} fill="none" stroke={color} strokeWidth={isSelEdge ? 2.8 : act ? 2 : 1.7}
                strokeDasharray={styleDash(arch.style)} strokeLinecap="round"
                markerEnd="url(#org-ah)" markerStart={arch.bidirectional ? "url(#org-ah-s)" : undefined}
                opacity={!focused ? 1 : (isSelEdge || act ? 1 : 0.26)} style={{ cursor: "pointer", transition: "opacity .15s" }} onClick={edgeClick(r.id)} />
            </g>
          );
        })}
      </svg>

      {/* edge labels */}
      <Box style={{ position: "absolute", inset: 0, pointerEvents: "none" }}>
        {org.relationships.map((r) => {
          const arch = archetypeById(r.archetype);
          if (!arch || !boxes.get(r.from) || !boxes.get(r.to)) return null;
          const { lx, ly } = edgeGeometry(liveBox(r.from), liveBox(r.to), r.bow ?? 0);
          const act = edgeActive(r.from, r.to);
          const isSelEdge = sel.type === "edge" && r.id === sel.id;
          const color = hueColor(arch.hue);
          return (
            <Box key={r.id} onClick={edgeClick(r.id)} onContextMenu={context({ type: "edge", id: r.id })}
              style={{ position: "absolute", left: lx, top: ly, transform: "translate(-50%,-50%)",
                display: "inline-flex", alignItems: "center", gap: 5, padding: "2.5px 8px", borderRadius: 999,
                background: "var(--bg-elev)", border: `1px solid ${color}`, color: "var(--fg)", fontSize: 10, fontWeight: 600,
                whiteSpace: "nowrap", pointerEvents: "auto", cursor: "pointer", opacity: !focused ? 1 : (isSelEdge || act ? 1 : 0.32), transition: "opacity .15s" }}>
              <Box style={{ width: 6, height: 6, borderRadius: "50%", background: color, flex: "none" }} />
              {arch.label}
            </Box>
          );
        })}
      </Box>

      {/* nodes */}
      {org.positions.map((pos) => {
        const xy = at(pos.nodeId);
        const box = boxes.get(pos.nodeId)!;
        const d = positionDisplay(pos, personas);
        const isSel = sel.type === "node" && sel.id === pos.nodeId;
        const dim = focused && !nodeActive(pos.nodeId);
        const pool = poolInfo?.[pos.nodeId];

        // A pool: a stacked card (offset shadow cards behind + a ×N badge). A click selects it; a drag
        // moves the whole stack (#2439 — the drop shifts every member). The pool-member drill was
        // dropped (#2750) — a homogeneous swarm is already fully shown by the ×N stacked card.
        if (pool) {
          return (
            // eslint-disable-next-line no-restricted-syntax -- data-node marks it as owning its own press gesture (no background pan)
            <div key={pos.nodeId} data-node={pos.nodeId}
              onPointerDown={onPoolDown(pos.nodeId)} onPointerMove={onNodeMove} onPointerUp={onPoolUp(pos.nodeId)}
              style={{ position: "absolute", left: xy.x, top: xy.y, width: box.w, height: box.h,
                cursor: "pointer", zIndex: isSel ? 6 : 3, opacity: dim ? 0.5 : 1, transition: drag ? "none" : "opacity .15s", touchAction: "none", userSelect: "none" }}>
              {/* stacked shadow cards behind the face — the "N of them" cue. The outer card's offset
                  IS the stack's extra footprint, so it comes from POOL_STACK_OFFSET (the constant
                  poolLayoutSizes feeds autoLayout, #2451) and layout collision matches the render. */}
              <Box style={{ position: "absolute", inset: 0, transform: `translate(${POOL_STACK_OFFSET}px,${POOL_STACK_OFFSET}px)`, borderRadius: 13, background: "var(--bg-elev)", border: "1px solid var(--border)", opacity: 0.45 }} />
              <Box style={{ position: "absolute", inset: 0, transform: "translate(6px,6px)", borderRadius: 13, background: "var(--bg-elev)", border: "1px solid var(--border)", opacity: 0.7 }} />
              <Box style={{ position: "relative", width: "100%", height: "100%" }}><AgentFace d={d} isSel={isSel} /></Box>
              {/* A count badge + a pool caption. A `plannerSized` engineer slot (#3143) shows NO count —
                  the planner owns how many exist (#2388) — just the stacked cards + a "planner-sized"
                  caption. A mixed-wiring stack (members with differing external edges, unioned onto this
                  node — #2436) says so, since the top view can't show who has what. */}
              {!pool.plannerSized && (
                <Box style={{ position: "absolute", top: -9, right: -9, minWidth: 22, height: 22, padding: "0 6px", borderRadius: 11,
                  background: "var(--accent)", color: "var(--bg-canvas)", fontSize: 11, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 2px 8px rgba(0,0,0,.35)" }}>×{pool.count}</Box>
              )}
              <Text as="div" mono size={8.5} tone="dim" style={{ position: "absolute", left: 0, right: 0, bottom: -14, textAlign: "center", pointerEvents: "none" }}>
                {pool.plannerSized ? "planner-sized" : pool.homogeneous ? "pooled swarm" : "mixed wiring"}
              </Text>
            </div>
          );
        }

        return (
          // eslint-disable-next-line no-restricted-syntax, jsx-a11y/no-static-element-interactions -- node needs the data-node marker + pointer-capture on the element for drag; pointer-capture drag node, not a button
          <div key={pos.nodeId} data-node={pos.nodeId}
            onPointerDown={onNodeDown(pos.nodeId)} onPointerMove={onNodeMove} onPointerUp={onNodeUp(pos.nodeId)}
            onContextMenu={context({ type: "node", id: pos.nodeId })}
            style={{ position: "absolute", left: xy.x, top: xy.y, width: box.w, height: box.h,
              cursor: connecting ? "crosshair" : "grab", zIndex: isSel ? 6 : 3, opacity: dim ? 0.5 : 1, transition: drag ? "none" : "opacity .15s", touchAction: "none", userSelect: "none" }}>
            {pos.kind === "agent" && <AgentFace d={d} isSel={isSel} />}
            {pos.kind === "resource" && (
              <Box style={{ width: "100%", height: "100%", boxSizing: "border-box", padding: "11px 13px", display: "flex", flexDirection: "column", justifyContent: "center",
                clipPath: "polygon(12% 0,88% 0,100% 50%,88% 100%,12% 100%,0 50%)",
                background: isSel ? hueColor(340, 0.5, 0.09) : "color-mix(in oklch, var(--fg) 4%, transparent)",
                border: `1px solid ${isSel ? hueColor(340) : "var(--border)"}` }}>
                <Text as="span" mono size={9} tone="dim" style={{ letterSpacing: ".1em", textTransform: "uppercase" }}>Resource</Text>
                <Row gap={7} align="center" style={{ marginTop: 3 }}>
                  <Text as="span" style={{ fontSize: 15, color: hueColor(340) }}>{d.glyph}</Text>
                  <Text as="span" weight={600} size={13}>{d.name}</Text>
                </Row>
              </Box>
            )}
            {pos.kind === "external" && (
              <Box style={{ width: "100%", height: "100%", boxSizing: "border-box", padding: "11px 13px", display: "flex", flexDirection: "column", justifyContent: "center",
                borderRadius: 12, background: "color-mix(in oklch, var(--fg) 2%, transparent)",
                border: `1.5px dashed ${isSel ? "var(--accent)" : "var(--border)"}` }}>
                <Text as="span" mono size={9} tone="dim" style={{ letterSpacing: ".1em", textTransform: "uppercase" }}>External · person</Text>
                <Row gap={8} align="center" style={{ marginTop: 4 }}>
                  <Box style={{ width: 22, height: 22, borderRadius: "50%", border: "1.5px dashed var(--fg-dim)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11, color: "var(--fg-muted)" }}>{d.glyph}</Box>
                  <Text as="span" weight={600} size={13}>{d.name}</Text>
                </Row>
              </Box>
            )}
          </div>
        );
      })}
    </>
  );
}

/** The relationship legend — a fixed overlay (bottom-left), not transformed with the world. */
export function OrgLegend() {
  return (
    <Box style={{ position: "absolute", left: 16, bottom: 16, background: "color-mix(in oklch, var(--bg-elev) 92%, transparent)",
