runtime.features/tunnel/lib/alertHub.ts:
// Alert hub (#2498) — the one place alert candidates from every source (the coord pump, the
// focus queue, the planner's gate/turn transitions) converge. Folds them into the capped
// rolling inbox (pure model: alerts.ts), publishes the inbox as the `alerts` store_state
// domain, and fires one FCM push per FRESH alert via the thin `tunnel_emit_alert` command —
// so a backgrounded/quit phone is notified even while off the relay.
//
// The hub is a factory (`createAlertHub`) so the fold→publish→push flow is testable with
// injected transports; the app-wide instance below binds the real publisher + push command.

import { foldAlerts, alertPushFields, type AlertEvent } from "./alerts";
import { buildAlertsPayload } from "./storeProjections";
import { publishTunnelDomain } from "./tunnelDomains";
import { tunnelEmitAlert } from "./tunnelClient";
import { log } from "@/shared/lib/core/log";

export interface AlertHub {
  /** Fold candidates into the inbox; publish + push whatever is genuinely new. */
  record(candidates: ReadonlyArray<AlertEvent>): void;
  /** Fold + publish WITHOUT pushing — for the first coord-log read after the relay starts,
   *  so the historical log seeds the mobile inbox without firing a burst of stale FCM
   *  notifications. Everything folded here is known, so a later `record` won't push it. */
  seed(candidates: ReadonlyArray<AlertEvent>): void;
  /** The current inbox (newest last). Exposed for tests/diagnostics. */
  inbox(): ReadonlyArray<AlertEvent>;
}

export function createAlertHub(deps: {
  publish: (payload: unknown) => void;
  push: (alert: AlertEvent, title: string, body: string) => Promise<void>;
  onError?: (err: unknown) => void;
}): AlertHub {
  let inbox: ReadonlyArray<AlertEvent> = [];
  const onError = deps.onError ?? (() => {});
  const fold = (candidates: ReadonlyArray<AlertEvent>, push: boolean): void => {
    const { inbox: next, fresh } = foldAlerts(inbox, candidates);
    if (fresh.length === 0) return;
    inbox = next;
    deps.publish(buildAlertsPayload(inbox));
    if (!push) return;
    for (const a of fresh) {
      const { title, body } = alertPushFields(a);
      deps.push(a, title, body).catch(onError);
    }
  };
  return {
    record: (candidates) => fold(candidates, true),
    seed: (candidates) => fold(candidates, false),
    inbox: () => inbox,
  };
}

const hub = createAlertHub({
  publish: (payload) => publishTunnelDomain("alerts", payload),
  push: (a, title, body) => tunnelEmitAlert(a.kind, title, body, a.paneId ?? null, a.at),
  onError: (e) => log.error(`tunnel: alert push failed: ${e}`),
});

/** Record alert candidates on the app-wide hub. Callers gate on the tunnel being live —
 *  alerts are a mobile-companion feature (the desktop has its own inbox surfaces). */
export function recordTunnelAlerts(candidates: ReadonlyArray<AlertEvent>): void {
  hub.record(candidates);
}

/** Seed the app-wide hub without pushing (the first coord-log read — see {@link AlertHub.seed}). */
export function seedTunnelAlerts(candidates: ReadonlyArray<AlertEvent>): void {
  hub.seed(candidates);
}

runtime.features/tunnel/lib/alerts.ts:
// Alert taxonomy (#2498) — ONE event model for everything that should reach the user's phone:
// the push-worthy moments of a running fleet/planner, derived from the SAME sources the desktop
// surfaces them from (the coordination pump's CoordState, the focus queue's awaiting set, the
// planner's gate/turn transitions). Pure — no React/Tauri — so the derivation, dedup, and the
// capped rolling inbox are unit-testable. The inbox rides the `alerts` store_state domain; each
// FRESH alert additionally fires an FCM push (see alertHub.ts / tunnel_emit_alert).

import type { CoordState } from "@/shared/lib/fleet/coordination";

/** The alert vocabulary (#2498). Fixed — mobile switches its notification routing on it. */
export type AlertKind =
  | "agent-paused"     // bsc-wait: an agent parked itself for the user (#297)
  | "prompt-waiting"   // a console pane flipped to awaiting-input (the user_request moment)
  | "worker-question"  // bsc-ask: a worker asked the director a question (#369)
  | "fleet-failed"     // a dep/issue latch FAILED — a stalled chain needing attention
  | "fleet-landed"     // a dep/issue latch satisfied (landed/merged/closed)
  | "gate-ready"       // the active plan stage's gate passed — awaiting the USER's confirm
  | "planner-waiting"; // the planner finished a turn and is waiting on the user

/** One alert. `id` is the stable dedup key — derivation is idempotent per source event. */
export interface AlertEvent {
  id: string;
  kind: AlertKind;
  /** The pane/session the alert is about, when it has one. */
  paneId?: string;
  /** The owning project key, when known. */
  project?: string;
  /** Short human-facing line (also the push body). */
  text: string;
  /** Epoch ms. */
  at: number;
}

/** Rolling-inbox cap: the newest N alerts are kept. */
export const ALERT_INBOX_CAP = 100;

const truncate = (s: string, max = 140): string => {
  const collapsed = s.split(/\s+/).join(" ").trim();
  return collapsed.length > max ? `${collapsed.slice(0, max - 1)}…` : collapsed;
};

// ── Coord-log sources ────────────────────────────────────────────────────────────
// CoordState entries carry their own `at` from the log line, so the derived ids are stable
// across polls — re-deriving from the same log yields the same alerts and foldAlerts dedups.

/** Derive the coord-sourced alert candidates from a replayed {@link CoordState}. */
export function coordAlerts(state: CoordState): AlertEvent[] {
  const out: AlertEvent[] = [];
  for (const w of state.waiting) {
    out.push({
      id: `agent-paused:${w.session}:${w.at}`,
      kind: "agent-paused",
      paneId: w.session,
      text: w.reason ? truncate(w.reason) : `${w.session} paused and is waiting for you.`,
      at: w.at,
    });
  }
  for (const a of state.asking) {
    out.push({
      id: `worker-question:${a.session}:${a.at}`,
      kind: "worker-question",
      paneId: a.session,
      text: truncate(a.question || `${a.session} asked the director a question.`),
      at: a.at,
    });
  }
  for (const [ref, latch] of Object.entries(state.latches)) {
    if (latch.state === "failed") {
      out.push({
        id: `fleet-failed:${ref}:${latch.at}`,
        kind: "fleet-failed",
        text: truncate(`${ref} failed${latch.reason ? `: ${latch.reason}` : ""}`),
        at: latch.at,
      });
    } else {
      out.push({
        id: `fleet-landed:${ref}:${latch.at}`,
        kind: "fleet-landed",
        text: `${ref} ${latch.source}`,
        at: latch.at,
      });
    }
  }
  return out;
}

// ── Transition sources ───────────────────────────────────────────────────────────
// These have no durable log to key off, so a NEW alert is an entry present now but not in the
// previous snapshot; `now` stamps it. A pane that resolves and awaits again re-alerts.

/** One awaiting console pane (from the focus queue, resolved to its identity id). */
export interface AwaitingPane {
  paneId: string;
  name: string;
}

/** Derive prompt-waiting alerts for panes that JUST entered the awaiting set. */
export function promptAlerts(
  prev: ReadonlyArray<AwaitingPane>,
  next: ReadonlyArray<AwaitingPane>,
  now: number,
): AlertEvent[] {
  const seen = new Set(prev.map((p) => p.paneId));
  return next
    .filter((p) => !seen.has(p.paneId))
    .map((p) => ({
      id: `prompt-waiting:${p.paneId}:${now}`,
      kind: "prompt-waiting" as const,
      paneId: p.paneId,
      text: `${p.name} is waiting for your input.`,
      at: now,
    }));
}

/** A gate-ready alert for a stage whose gate JUST passed (false→true per stage). */
export function gateReadyAlert(
  project: string,
  stage: string,
  now: number,
): AlertEvent {
  return {
    id: `gate-ready:${project}:${stage}:${now}`,
    kind: "gate-ready",
    project,
    text: `Stage "${stage}" gate passed — awaiting your confirm.`,
    at: now,
  };
}

/** A planner-waiting alert: the planner finished a turn (its newest transcript message is an
 *  assistant turn) and is waiting on the user. Keyed by the message timestamp, so the same turn
 *  never re-alerts. */
export function plannerWaitingAlert(
  project: string,
  paneId: string,
  lastText: string,
  at: number,
): AlertEvent {
  return {
    id: `planner-waiting:${paneId}:${at}`,
    kind: "planner-waiting",
    paneId,
    project,
    text: truncate(lastText) || "The planner is waiting for you.",
    at,
  };
}

// ── The rolling inbox ────────────────────────────────────────────────────────────

/** Fold candidate alerts into the inbox: candidates whose `id` is already present are dropped,
 *  the rest append in `at` order, and the inbox keeps only the newest {@link ALERT_INBOX_CAP}.
 *  Returns the (possibly unchanged — same reference) inbox plus the FRESH alerts to push. */
export function foldAlerts(
  inbox: ReadonlyArray<AlertEvent>,
  candidates: ReadonlyArray<AlertEvent>,
): { inbox: ReadonlyArray<AlertEvent>; fresh: AlertEvent[] } {
  const known = new Set(inbox.map((a) => a.id));
  const fresh = candidates.filter((a) => !known.has(a.id));
  // Dedup WITHIN the batch too (two sources could mint the same id in one tick).
  const uniqueFresh: AlertEvent[] = [];
  const batch = new Set<string>();
  for (const a of fresh) {
    if (batch.has(a.id)) continue;
    batch.add(a.id);
    uniqueFresh.push(a);
  }
  if (uniqueFresh.length === 0) return { inbox, fresh: [] };
  uniqueFresh.sort((a, b) => a.at - b.at);
  const next = [...inbox, ...uniqueFresh];
  return { inbox: next.slice(Math.max(0, next.length - ALERT_INBOX_CAP)), fresh: uniqueFresh };
}

/** The FCM banner fields for one alert (title per kind; body = the alert text). Pure so the
 *  push contract is pinned by tests. */
export function alertPushFields(a: AlertEvent): { title: string; body: string } {
  const titles: Record<AlertKind, string> = {
    "agent-paused": "Agent paused",
    "prompt-waiting": "Agent awaiting input",
    "worker-question": "Worker question",
    "fleet-failed": "Fleet: dependency failed",
    "fleet-landed": "Fleet: landed",
    "gate-ready": "Plan stage ready",
    "planner-waiting": "Planner waiting",
  };
  const who = a.paneId ?? a.project;
  return {
    title: who ? `${titles[a.kind]} — ${who}` : titles[a.kind],
    body: a.text,
  };
}

runtime.features/tunnel/lib/automationControl.ts:
// Pure helpers for the automations tunnel surface (#937): project a store Automation to
// the wire frame, and decide whether a phone's arm/disarm request is allowed. The desktop
// owns schedule validity — a phone can arm/disarm/run, but an invalid cron is rejected
// here rather than silently armed (and the phone never runs schedules itself).

import { isValidCron, type Automation, type AutomationWhen } from "@/features/automations";
import type { AutomationFrame } from "./tunnelClient";

/** A compact, human-readable schedule string for the phone (cron expr, or "every day · 09:00"). */
export function whenExpr(when: AutomationWhen): string {
  if (when.kind === "cron") return when.expr;
  return `every ${when.every}${when.every !== "minute" ? " · " + when.at : ""}`;
}

/** Project one automation to its read-only wire frame. */
export function automationToFrame(a: Automation): AutomationFrame {
  return {
    id: a.id,
    name: a.name,
    armed: a.armed,
    whenExpr: whenExpr(a.when),
    lastRunAt: a.lastRunAt,
    nextRunAt: a.nextRunAt,
    lastStatus: a.runs[0]?.status ?? null,
  };
}

export type ArmDecision =
  | { ok: true; id: string; armed: boolean }
  | { ok: false; id: string; name: string; error: string };

/**
 * Decide a phone's arm/disarm request:
 *  - unknown id → rejected.
 *  - arming a cron automation with an invalid expression → rejected (the schedule would
 *    never fire, and the desktop is the source of truth for validity).
 *  - disarming, or arming a valid schedule → allowed.
 */
export function planArm(a: Automation | undefined, id: string, armed: boolean): ArmDecision {
  if (!a) return { ok: false, id, name: id, error: "unknown automation" };
  if (armed && a.when.kind === "cron" && !isValidCron(a.when.expr)) {
    return { ok: false, id, name: a.name, error: `invalid cron expression: ${a.when.expr}` };
  }
  return { ok: true, id, armed };
}

runtime.features/tunnel/lib/coordControl.ts:
// Mobile → desktop coordination control (#935). The phone can ask the desktop to WAKE a
// parked worker (its blocking dependency landed) or APPROVE a worker paused for the user
// (a checkpoint / push-confirm gate). Both arrive as Tauri events the desktop already
// decodes from the tunnel (`tunnel://coord-wake` / `tunnel://coord-approve`, src-tauri/
// src/tunnel.rs); this module decides — purely, from the coordination state — how to
// honor one. Launching the fleet is deliberately NOT reachable from the phone.

import {
  wakePromptFor,
  waitingWakePrompt,
  type CoordState,
  type Waiter,
} from "@/shared/lib/fleet/coordination";

export type CoordControlKind = "wake" | "approve";

export interface MobileResume {
  session: string;
  /** The wake/resume prompt delivered to the session. */
  prompt: string;
  /**
   * How to deliver it:
   *  - "fresh"  → relaunch the parked pane (a dependency waiter; matches the inbox Wake).
   *  - "inject" → deliver into the live, paused pane (a user-paused gate; keeps context).
   */
  via: "fresh" | "inject";
}

/**
 * Decide how to honor a mobile coordination request for `session`, given the current
 * coordination state and the set of dependency waiters whose deps have landed (`ready`).
 *
 * Returns `null` when the session isn't in a state that request can resolve — we never
 * wake or approve an arbitrary session a phone names, only one the coordination log shows
 * actually parked. So:
 *  - `approve` resolves ONLY a session paused for the user (`state.waiting`).
 *  - `wake` resolves a ready dependency waiter, and also a user-paused session (a phone
 *    "wake" on a paused gate is a reasonable resume), never an unknown session.
 */
export function planMobileResume(
  kind: CoordControlKind,
  session: string,
  state: CoordState,
  ready: Waiter[],
): MobileResume | null {
  const paused = state.waiting.find((w) => w.session === session);

  if (kind === "approve") {
    return paused ? { session, prompt: waitingWakePrompt(paused), via: "inject" } : null;
  }

  // kind === "wake"
  const readyWaiter = ready.find((w) => w.session === session);
  if (readyWaiter) return { session, prompt: wakePromptFor(readyWaiter, state), via: "fresh" };
  if (paused) return { session, prompt: waitingWakePrompt(paused), via: "inject" };
  return null;
}

runtime.features/tunnel/lib/domainPublisher.ts:
// Domain publisher (#2498) — the rev/dedup/debounce engine behind the generic `store_state`
// projections. One instance fans every domain's pushes through the single `tunnel_set_store_state`
// entry point (#2497) with three guarantees:
//   • DEBOUNCE — rapid store churn coalesces into one frame per domain per window (~300ms).
//   • DEDUP    — an unchanged payload (byte-equal serialized JSON) is never re-sent, so poll-driven
//                sources (faults, coord log) that rebuild identical objects cost nothing on the wire.
//   • REV      — a monotonically increasing per-domain revision stamps each send, so mobile can
//                cheap-skip stale replays. The counter never resets while the app lives.
// Pure (no Tauri/React imports): the transport is injected, so the whole engine is unit-testable
// with fake timers. The app-wide singleton bound to `tunnelSetStoreState` lives in tunnelDomains.ts.

/** Injected transport — the shape of `tunnelSetStoreState`. */
export type DomainSend = (domain: string, rev: number, json: string) => Promise<void>;

export interface DomainPublisherOpts {
  send: DomainSend;
  /** Per-domain debounce window in ms (default 300). `0` sends synchronously (tests). */
  debounceMs?: number;
  /** Error sink for a failed send (default: swallow — the tunnel may simply be down). */
  onError?: (domain: string, err: unknown) => void;
}

export interface DomainPublisher {
  /** Queue one domain's projection. Serializes now (a later mutation can't corrupt the frame),
   *  debounces per domain, and skips the send entirely when the payload is byte-identical to the
   *  last one sent for that domain. */
  publish(domain: string, payload: unknown): void;
  /** Cancel pending timers and forget the last-sent cache so the next publish re-sends each domain
   *  (used when the relay restarts). Rev counters are NOT reset — they stay monotonic. */
  reset(): void;
  /** The current revision for a domain (0 = never sent). Exposed for tests/diagnostics. */
  rev(domain: string): number;
}

export function createDomainPublisher(opts: DomainPublisherOpts): DomainPublisher {
  const debounceMs = opts.debounceMs ?? 300;
  const onError = opts.onError ?? (() => {});
  const revs = new Map<string, number>();
  const lastSent = new Map<string, string>();
  const pending = new Map<string, { json: string; timer: ReturnType<typeof setTimeout> | null }>();

  const fire = (domain: string): void => {
    const p = pending.get(domain);
    if (!p) return;
    pending.delete(domain);
    if (lastSent.get(domain) === p.json) return; // unchanged since the last send — drop
    const rev = (revs.get(domain) ?? 0) + 1;
    revs.set(domain, rev);
    lastSent.set(domain, p.json);
    opts.send(domain, rev, p.json).catch((e) => onError(domain, e));
  };

  return {
    publish(domain, payload) {
      const json = JSON.stringify(payload);
      const p = pending.get(domain);
      if (p) {
        // A send is already scheduled — just refresh the payload it will carry.
        p.json = json;
        return;
      }
      if (lastSent.get(domain) === json) return; // no change at all — nothing to schedule
      if (debounceMs <= 0) {
        pending.set(domain, { json, timer: null });
        fire(domain);
        return;
      }
      const timer = setTimeout(() => fire(domain), debounceMs);
      pending.set(domain, { json, timer });
    },
    reset() {
      for (const p of pending.values()) if (p.timer) clearTimeout(p.timer);
      pending.clear();
      lastSent.clear();
    },
    rev(domain) {
      return revs.get(domain) ?? 0;
    },
  };
}

runtime.features/tunnel/lib/relayProbe.ts:
// Relay self-test — the "Test relay" probe behind Settings → Mobile tunnel (#930).
//
// Pairing depends on three independent things working, and a single pass/fail hides
// WHICH one is broken. So the probe runs three distinct legs and reports each:
//   1. reach — the relay answers `GET /health` and identifies itself (DNS/TLS/HTTP +
//      "is this actually a tunnel relay?").
//   2. join  — a WebSocket upgrade to `/connect` is accepted into a room (the Durable
//      Object path, not just the static health endpoint).
//   3. relay — two peers in the same room can exchange a frame end-to-end (the blind
//      pipe the Noise handshake itself rides on). We can't run a real Noise IK handshake
//      solo — that needs the phone — so we loopback a nonce host→guest, which exercises
//      exactly the forwarding path the handshake uses.
//
// Transport-free: `fetch` and the WebSocket factory are injected, so the orchestration
// is unit-testable without a live relay (see relayProbe.test.ts).

/**
 * Map a user-entered relay URL (any of `http(s)://` / `ws(s)://`, with or without a
 * scheme or trailing slash) to its `https` `/health` probe endpoint. The relay serves
 * `/health` over plain HTTPS GET (the `wss://` form is only for the tunnel upgrade), so
 * the Test button normalizes to `https` before probing.
 */
export function relayHealthUrl(relayUrl: string): string {
  const trimmed = relayUrl.trim().replace(/\/+$/, "");
  const normalized = trimmed
    .replace(/^wss:\/\//i, "https://")
    .replace(/^ws:\/\//i, "http://");
  const withScheme = /^https?:\/\//i.test(normalized) ? normalized : `https://${normalized}`;
  return `${withScheme}/health`;
}

/** Normalize a relay URL to its `wss`/`ws` base (no path) for the `/connect` upgrade. */
export function relayWsBase(relayUrl: string): string {
  const trimmed = relayUrl.trim().replace(/\/+$/, "");
  const normalized = trimmed
    .replace(/^https:\/\//i, "wss://")
    .replace(/^http:\/\//i, "ws://");
  return /^wss?:\/\//i.test(normalized) ? normalized : `wss://${normalized}`;
}

/** Build a `/connect?room=&role=` upgrade URL for a probe peer. */
export function relayConnectUrl(relayUrl: string, room: string, role: "host" | "guest"): string {
  return `${relayWsBase(relayUrl)}/connect?room=${encodeURIComponent(room)}&role=${role}`;
}

/**
 * A throwaway, well-formed room id (base64url, within the relay's 16–64 char window).
 * High-entropy so the probe never collides with a live pairing room; the room idle-times
 * out on its own and we close our sockets immediately, so it leaves nothing behind.
 */
export function freshRoomId(): string {
  const bytes = new Uint8Array(24);
  crypto.getRandomValues(bytes);
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

export type LegStatus = "pending" | "running" | "ok" | "fail" | "skip";
export interface ProbeLeg {
  status: LegStatus;
  detail?: string;
}
export interface ProbeLegs {
  reach: ProbeLeg;
  join: ProbeLeg;
  relay: ProbeLeg;
}
export interface ProbeResult {
  legs: ProbeLegs;
  /** Relay version reported by `/health`, when reachable. */
  version?: string;
}

/** The legs at the moment the probe starts: reachability running, the rest queued. */
export function emptyLegs(): ProbeLegs {
  return { reach: { status: "running" }, join: { status: "pending" }, relay: { status: "pending" } };
}

/** The minimal WebSocket surface the probe uses — the browser `WebSocket` satisfies it. */
export interface MinimalSocket {
  onopen: ((ev: unknown) => void) | null;
  onmessage: ((ev: { data: unknown }) => void) | null;
  onerror: ((ev: unknown) => void) | null;
  onclose: ((ev: unknown) => void) | null;
  send(data: string): void;
  close(code?: number, reason?: string): void;
}

export interface ProbeDeps {
  fetchFn: typeof fetch;
  makeSocket: (url: string) => MinimalSocket;
  /** Per-leg deadline. */
  timeoutMs: number;
  /** Override for tests; defaults to {@link freshRoomId}. */
  genId?: () => string;
  /** Fired after every leg-status change so the UI can update progressively. */
  onLeg?: (legs: ProbeLegs) => void;
}

const SERVICE_ID = "msc-tunnel-relay";

/**
 * Run the three-leg relay probe against `target`. Resolves once a leg fails (skipping the
 * rest) or all three pass; never rejects — every failure is reported as a leg detail.
 */
export async function runRelayProbe(target: string, deps: ProbeDeps): Promise<ProbeResult> {
  const genId = deps.genId ?? freshRoomId;
  const legs = emptyLegs();
  const emit = () => deps.onLeg?.({ reach: { ...legs.reach }, join: { ...legs.join }, relay: { ...legs.relay } });

  // Leg 1 — reachability + identity via /health.
  let version: string | undefined;
  const reachOk = await (async (): Promise<boolean> => {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), deps.timeoutMs);
    try {
      const res = await deps.fetchFn(relayHealthUrl(target), { signal: ctrl.signal });
      if (!res.ok) {
        legs.reach = { status: "fail", detail: `relay returned HTTP ${res.status}` };
        return false;
      }
      const body = (await res.json().catch(() => null)) as { service?: string; version?: string } | null;
      if (body?.service !== SERVICE_ID) {
        legs.reach = { status: "fail", detail: "reachable, but not a tunnel relay" };
        return false;
      }
      version = body.version;
      legs.reach = { status: "ok", detail: version ? `v${version}` : undefined };
      return true;
    } catch (e) {
      const aborted = e instanceof DOMException && e.name === "AbortError";
      legs.reach = { status: "fail", detail: aborted ? "timed out" : "could not reach relay" };
      return false;
    } finally {
      clearTimeout(timer);
    }
  })();
  emit();
  if (!reachOk) {
    legs.join = { status: "skip" };
    legs.relay = { status: "skip" };
    emit();
    return { legs, version };
  }

  // Legs 2 & 3 — open a host socket (join), then a guest socket in the same room and
  // loopback a nonce through the relay (relay). Both sockets are closed when we settle.
  legs.join = { status: "running" };
  emit();
  await new Promise<void>((resolve) => {
    const room = genId();
    const nonce = genId();
    const host = deps.makeSocket(relayConnectUrl(target, room, "host"));
    let guest: MinimalSocket | null = null;
    let done = false;

    const timer = setTimeout(() => {
      if (legs.join.status === "running") {
        legs.join = { status: "fail", detail: "room join timed out" };
        legs.relay = { status: "skip" };
      } else if (legs.relay.status === "running") {
        legs.relay = { status: "fail", detail: "no relayed frame (timed out)" };
      }
      settle();
    }, deps.timeoutMs);

    const settle = () => {
      if (done) return;
      done = true;
      clearTimeout(timer);
      try { host.close(1000); } catch { /* already closing */ }
      try { guest?.close(1000); } catch { /* already closing */ }
      emit();
      resolve();
    };

    host.onerror = () => {
      if (legs.join.status === "running") {
        legs.join = { status: "fail", detail: "room join failed" };
        legs.relay = { status: "skip" };
      }
      settle();
    };
    host.onopen = () => {
      legs.join = { status: "ok" };
      legs.relay = { status: "running" };
      emit();
      guest = deps.makeSocket(relayConnectUrl(target, room, "guest"));
      guest.onerror = () => {
        legs.relay = { status: "fail", detail: "second peer couldn't join the room" };
        settle();
      };
      guest.onmessage = (ev) => {
        if (typeof ev.data === "string" && ev.data === nonce) {
          legs.relay = { status: "ok" };
          settle();
        }
      };
      guest.onopen = () => {
        try {
          host.send(nonce);
        } catch {
          legs.relay = { status: "fail", detail: "could not send a probe frame" };
          settle();
        }
      };
    };
  });

  return { legs, version };
}

runtime.features/tunnel/lib/storeProjections.ts:
// Store projections (#2498) — the PURE per-domain payload builders behind the generic
// `store_state` frame (#2497). Each builder maps the SAME store data the desktop pages read
// into the compact JSON a mobile page renders; the projector hook (useStoreProjector) feeds
// them live store slices and pushes the result through the domain publisher. Pure + typed —
// only `import type` crosses feature boundaries (erased at build), so this module wires no
// runtime coupling and every payload shape is unit-testable from plain fixtures.
//
// Deliberately OUT (maintainer): telemetry/analytics — skill telemetry counters, hook
// analytics, usage charts. Mobile is state + alerts, not dashboards.

import type { ProjectLite, GlanceFault, GHealth } from "@/features/glance";
import type { ProjectLink } from "@/features/glance/lib/projectLinks";
import type { FleetPlan } from "@/features/planner/fleet/planFleet";
import type { Team } from "@/features/teams";
import type { Persona } from "@/features/personas";
import type { Blueprint, BlueprintTeam } from "@/features/planner/stages/blueprintTypes";
import type { SkillDef } from "@/features/skills/lib/skillsModel";
import type { SkillGroup } from "@/features/skills/lib/skillGroups";
import type { Lesson } from "@/features/skills/lib/lessons";
import type { Kit, ComponentRecord, KitConsumer, KitLibraryRef } from "@/features/designs";
import type { KitThemeRecord } from "@/features/designs/lib/themes";
import type { Automation, AutomationRun } from "@/features/automations/lib/scheduler";
import type { McpServer } from "@/features/mcp/lib/mcpServers";
import type { Hook } from "@/features/mcp/lib/hooks";
import type { AgentProfile, ConsoleSession, AuditDisplayRow } from "@/features/security";
import type { AlertEvent } from "./alerts";

// ── glance ───────────────────────────────────────────────────────────────────────
// The project network + the drilled project's fleet: the same inputs the desktop Glance
// workspace feeds `buildGlanceData` / `buildRealFleetData`. Mobile rebuilds the graph with
// the vendored shared graph core, so the payload is the MODEL, not layout.

export interface GlancePayload {
  /** Published + local-draft projects, keyed by plan key, with fault badges merged on. */
  projects: ProjectLite[];
  /** The real project→project edges (`bsc project link`). */
  links: ProjectLink[];
  /** The drilled project key (L1 fleet view), or null at the L0 network. Synced drill state. */
  drill: string | null;
  /** The drilled project's fleet plan (streams/director/edges) — derived from {@link fleets}; kept
   *  for the mobile L1 view. Null at the network level or when the drilled fleet isn't loaded. */
  drillFleet: FleetPlan | null;
  /** Every project whose fleet is currently loaded, keyed by project key (#2530) — so ANY project
   *  node can drill into its agents on mobile, not only the currently-drilled one. */
  fleets: Record<string, FleetPlan>;
  /** persona id → resolved session role (#2530) — a stream carries a persona id but no role, and the
   *  glance payload has no personas, so mobile defaulted every agent node to `worker`. This map lets
   *  mobile colour each stream's node by its real role. */
  personaRoles: Record<string, string>;
  /** The remaining THREE `buildGlanceData` inputs (#3743), so mobile rebuilds the FULL cockpit — not just
   *  the project network. Without these mobile fed `buildGlanceData` empty kit/library sets and lost the
   *  UI-kit nodes (#2571) + the algorithm/sound library band (#3133). */
  /** (project, kit) consumer edges — the `uses-kit` band. */
  kitUsage: KitConsumer[];
  /** The kits in use, pared to id + name (a kit node reads its name, else the id). */
  kits: { id: string; name: string }[];
  /** The kit→library `requires` roll-up (`resolveKitLibraryRefs`) — the algorithm/sound band. */
  libraryRefs: KitLibraryRef[];
}

export function buildGlancePayload(input: {
  projects: ProjectLite[];
  links: ProjectLink[];
  faults: Record<string, GlanceFault>;
  drill: string | null;
  /** All loaded fleets, keyed by project key (the projector merges the on-demand drilled fleet in). */
  fleets: Record<string, FleetPlan>;
  /** The persona library — only `id` + `role` are read (start prompts stay desktop-side). */
  personas: { id: string; role: string }[];
  /** (project, kit) consumer edges — the same `kitUsage` the desktop feeds `buildGlanceData` (#3743).
   *  Optional (defaults empty) so a caller without a kit dimension still builds a valid project-only graph. */
  kitUsage?: KitConsumer[];
  /** The kit library — only `id` + `name` are read for the wire (extra Kit fields stay desktop-side). */
  kits?: Kit[];
  /** The kit→library `requires` roll-up (`resolveKitLibraryRefs(components)`, #3133/#3743). */
  libraryRefs?: KitLibraryRef[];
}): GlancePayload {
  return {
    // Mirror the desktop HEALTH overlay (#2541): a project's worst open fault escalates its health to
    // warning/error and carries the fault title as the reason (matches `applyFaultHealth`).
    projects: input.projects.map((p) => {
      const f = input.faults[p.id];
      if (!f) return p;
      const health: GHealth = f.level === "warn" ? "warning" : "error";
      return { ...p, health, reason: f.title, faults: f.count };
    }),
    links: input.links,
    drill: input.drill,
    fleets: input.fleets,
    drillFleet: input.drill ? input.fleets[input.drill] ?? null : null,
    personaRoles: Object.fromEntries(input.personas.map((p) => [p.id, p.role])),
    // The kit + library bands (#3743): pass kitUsage/libraryRefs verbatim; pare kits to id+name so mobile's
