// The app-wide store_state publisher (#2498) — the singleton the projector hook and the
// planner's plan-domain push share, bound to the real `tunnel_set_store_state` command.
// Kept apart from domainPublisher.ts so the engine stays Tauri-free and unit-testable.

import { createDomainPublisher } from "./domainPublisher";
import { tunnelSetStoreState, type StoreDomain } from "./tunnelClient";
import { log } from "@/shared/lib/core/log";

const publisher = createDomainPublisher({
  send: tunnelSetStoreState,
  onError: (domain, e) => log.error(`tunnel: store_state[${domain}] push failed: ${e}`),
});

/** Publish one domain's projection over the tunnel — debounced, deduped, rev-stamped.
 *  Safe to call on every derivation: an unchanged payload never reaches the wire. */
export function publishTunnelDomain(domain: StoreDomain, payload: unknown): void {
  publisher.publish(domain, payload);
}

/** Forget the last-sent cache (the next publish per domain re-sends). Called when the relay
 *  (re)starts so a fresh Rust-side store is repopulated even if the store didn't change. */
export function resetTunnelDomains(): void {
  publisher.reset();
}

runtime.features/tunnel/lib/useTunnelAutomations:
// The automations tunnel surface (#937): project the automations store to a paired phone
// and accept its arm / disarm / run-now control. Mounted once at the app root.
//
// Outbound — push the list (id/name/schedule/armed/next-run/last-status) whenever it
//   changes; the relay replays the last push on connect.
// Inbound — route the phone's control through the SAME store + scheduler the desktop uses:
//   arm/disarm validates the cron (an invalid one is rejected back to the phone, never
//   silently armed); run-now fires the automation through the shared dispatch. The phone
//   never runs schedules itself — it only asks the desktop to.

import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { dispatchAutomation } from "@/features/automations";
import { automationToFrame, planArm } from "./automationControl";
import { tunnelSetAutomations, tunnelAutomationFailed } from "./tunnelClient";
import { log } from "@/shared/lib/core/log";

export function useTunnelAutomations(): void {
  const tunnelRunning = useAppStore((s) => s.tunnelRunning);
  const automations = useAppStore((s) => s.automations);

  // Outbound projection — re-push whenever the list changes (no-op until a phone is paired).
  useEffect(() => {
    if (!tunnelRunning) return;
    tunnelSetAutomations(automations.map(automationToFrame))
      .catch((e) => log.error(`tunnel: set_automations failed: ${e}`));
  }, [tunnelRunning, automations]);

  // Inbound control — arm/disarm + run-now from the phone.
  useEffect(() => {
    let cancelled = false;

    const onArm = async (id: string, armed: boolean): Promise<void> => {
      const s = useAppStore.getState();
      const decision = planArm(s.automations.find((a) => a.id === id), id, armed);
      if (!decision.ok) {
        log.warn(`tunnel: rejecting mobile arm of "${id}" — ${decision.error}`);
        // Workspace the rejection back to the phone (also FCM-pushed, A4).
        await tunnelAutomationFailed(decision.id, Date.now(), decision.error, decision.name).catch(() => {});
        return;
      }
      log.info(`tunnel: mobile ${decision.armed ? "armed" : "disarmed"} automation "${decision.id}"`);
      s.setAutomationArmed(decision.id, decision.armed);
    };

    const onRunNow = async (id: string): Promise<void> => {
      const s = useAppStore.getState();
      const a = s.automations.find((x) => x.id === id);
      if (!a) {
        log.warn(`tunnel: run-now for unknown automation "${id}"`);
        return;
      }
      log.info(`tunnel: mobile run-now of automation "${id}"`);
      await dispatchAutomation(a, {
        tabs: s.tabs,
        disabledPanes: s.disabledPanes,
        write: (paneId, data) => invoke<void>("pty_write", { paneId, data }),
        recordRun: s.recordAutomationRun,
        now: () => Date.now(),
      });
    };

    const subs = [
      listen<{ id: string; armed: boolean }>("tunnel://automation-arm", (e) => {
        if (!cancelled) void onArm(e.payload.id, e.payload.armed);
      }),
      listen<{ id: string }>("tunnel://automation-run-now", (e) => {
        if (!cancelled) void onRunNow(e.payload.id);
      }),
    ];
    return () => {
      cancelled = true;
      for (const s of subs) void s.then((off) => off());
    };
  }, []);
}

runtime.features/tunnel/lib/useTunnelCoordContro:
// Wire the tunnel's inbound coordination control into the desktop wake path (#935).
// src-tauri/src/tunnel.rs decodes a phone's wake/approve frames and re-emits them as
// Tauri events; without a listener they fell on the floor. This hook routes them through
// the SAME actuation the local Coordinator inbox uses, so a paired phone can wake a parked
// worker or approve a paused gate. Mount once at the app root (runs on any screen).

import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { useAppStore } from "@/store";
import { readCoordState } from "@/shared/lib/fleet/useCoordLog";
import { actuateWake, injectWake } from "@/shared/lib/fleet/coordinatorActuate";
import { planMobileResume, type CoordControlKind } from "./coordControl";
import { log } from "@/shared/lib/core/log";

export function useTunnelCoordControl(): void {
  useEffect(() => {
    let cancelled = false;

    const handle = async (kind: CoordControlKind, session: string): Promise<void> => {
      const res = await readCoordState(1000);
      if (cancelled || !res) return;
      const { state, ready } = res;
      const plan = planMobileResume(kind, session, state, ready);
      if (!plan) {
        // The phone named a session that isn't parked — ignore rather than wake blindly.
        log.warn(`tunnel: ignoring mobile ${kind} for "${session}" — not a parked session`);
        return;
      }
      log.info(`tunnel: mobile ${kind} → ${plan.via} resume of "${plan.session}"`);
      if (plan.via === "fresh") {
        await actuateWake(plan.session, plan.prompt, useAppStore.getState().wakePane);
      } else {
        await injectWake(plan.session, plan.prompt);
      }
    };

    const subs = [
      listen<{ session: string }>("tunnel://coord-wake", (e) => void handle("wake", e.payload.session)),
      listen<{ session: string }>("tunnel://coord-approve", (e) => void handle("approve", e.payload.session)),
    ];
    return () => {
      cancelled = true;
      for (const s of subs) void s.then((off) => off());
    };
  }, []);
}

runtime.features/tunnel/lib/useTunnelHookTelemet:
// The hook-telemetry tunnel surface (#937): project the desktop's aggregated hook-fire
// analytics to a paired phone. READ-ONLY — mobile displays the counts but never controls
// hooks (there is no inbound frame). Mounted once at the app root.
//
// The same summary the Hook Analytics tab renders (`aggregateHookTelemetry` over the
// `hooks.log` tail from `bsc logs tail hook`) is pushed whenever the tunnel comes up; the
// relay replays the last push on connect so a freshly-paired phone mirrors it immediately.

import { useEffect } from "react";
import { useAppStore } from "@/store";
import { logsTail } from "@/shared/lib/core/logsBridge";
import { parseHookLog, aggregateHookTelemetry } from "@/features/mcp";
import { tunnelSetHookTelemetry, type HookTelemetryFrame } from "./tunnelClient";
import { log } from "@/shared/lib/core/log";

// Match the Hook Analytics tab's window so the phone shows the same numbers.
const DAYS = 14;

/** Aggregate the hook-fire log into the read-only wire frame the phone renders. Pure over
 *  its inputs so it's unit-testable without Tauri. */
export function toHookTelemetryFrame(logLines: string[], now: Date): HookTelemetryFrame {
  const an = aggregateHookTelemetry(parseHookLog(logLines.join("\n")), now, DAYS);
  return {
    total: an.total,
    blocks: an.blocks,
    allows: an.allows,
    allowRate: an.allowRate,
    daily: an.daily.map((d) => ({ day: d.day, allows: d.allows, blocks: d.blocks })),
    perHook: an.perHook.map((h) => ({ hook: h.hook, event: h.event, fires: h.fires })),
  };
}

export function useTunnelHookTelemetry(): void {
  const tunnelRunning = useAppStore((s) => s.tunnelRunning);

  // Outbound projection — read + aggregate the hook log and push it whenever the tunnel
  // comes up (no-op until a phone is paired; the relay replays the last push on connect).
  useEffect(() => {
    if (!tunnelRunning) return;
    let cancelled = false;
    logsTail("hook", 8000)
      .then((lines) => {
        if (cancelled) return;
        const frame = toHookTelemetryFrame(lines ?? [], new Date());
        return tunnelSetHookTelemetry(frame);
      })
      .catch((e) => log.error(`tunnel: set_hook_telemetry failed: ${e}`));
    return () => {
      cancelled = true;
    };
  }, [tunnelRunning]);
}

