import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Grid } from "@/shared/ui/layout/Grid";
import { Card } from "@/shared/ui/data/Card";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { listen } from "@tauri-apps/api/event";
import { openUrl } from "@tauri-apps/plugin-opener";
import { QRCodeSVG } from "qrcode.react";
import { useAppStore } from "@/store";
import { pairingPayload, type TunnelStatus } from "./lib/tunnel";
import {
  tunnelStart,
  tunnelStop,
  tunnelStatus,
  tunnelSetInputGranted,
  tunnelUnpair,
  applyPushedPlanPush,
} from "./lib/tunnelClient";
import type { CanonicalFile } from "@/features/planner";
import {
  runRelayProbe,
  emptyLegs,
  freshRoomId,
  type ProbeLegs,
  type ProbeLeg,
  type MinimalSocket,
} from "./lib/relayProbe";

// `relayHealthUrl` now lives with the probe orchestration; re-exported here so existing
// importers (and tests) keep resolving it from this module.
export { relayHealthUrl } from "./lib/relayProbe";

// A "Deploy to Cloudflare" link prefilled with the relay workspace, so a user can
// stand up their own zero-knowledge relay in their own account (BYO).
const DEPLOY_URL =
  "https://deploy.workers.cloudflare.com/?url=https://github.com/kevinthelago/base-studio-code/tree/main/relay";

/**
 * Deep-link to the user's Cloudflare dashboard for their relay. Cloudflare resolves the `:account`
 * placeholder to whoever's logged in, so we never need their account id (which the app can't know).
 * When the relay is a `*.workers.dev` URL we extract the worker NAME (the first host label) and link
 * straight to that Worker; otherwise (custom domain, or no URL yet) we fall back to the Workers &
 * Pages list.
 */
export function cloudflareDashUrl(relayUrl: string): string {
  const base = "https://dash.cloudflare.com/?to=/:account";
  const trimmed = relayUrl.trim().replace(/^wss?:\/\//i, "https://");
  let host = "";
  try {
    host = new URL(/^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`).hostname;
  } catch { /* unparseable / empty → fall through to the generic Workers list */ }
  // `<worker>.<account-subdomain>.workers.dev` → the first label is the Worker's name.
  const m = host.match(/^([a-z0-9][a-z0-9-]*)\.[a-z0-9-]+\.workers\.dev$/i);
  return m ? `${base}/workers/services/view/${m[1]}/production` : `${base}/workers-and-pages`;
}

/** Per-leg deadline for the relay probe before that leg is called a failure. */
const TEST_TIMEOUT_MS = 6000;

type RelayTest =
  | { state: "idle" }
  | { state: "running"; legs: ProbeLegs; version?: string }
  | { state: "done"; legs: ProbeLegs; version?: string };

const LEG_LABELS: Array<{ key: keyof ProbeLegs; label: string }> = [
  { key: "reach", label: "Reachable" },
  { key: "join", label: "Room join" },
  { key: "relay", label: "Relay handshake" },
];

/** Glyph + color for a single probe leg's status. */
function legGlyph(status: ProbeLeg["status"]): { glyph: string; color: string } {
  switch (status) {
    case "ok": return { glyph: "✓", color: "var(--success, #2ea043)" };
    case "fail": return { glyph: "✗", color: "var(--danger)" };
    case "running": return { glyph: "◌", color: "var(--fg-muted)" };
    case "skip": return { glyph: "–", color: "var(--fg-muted)" };
    default: return { glyph: "·", color: "var(--fg-muted)" };
  }
}

export function TunnelSettings() {
  const tunnelRelayUrl = useAppStore((s) => s.tunnelRelayUrl);
  const setTunnelRelayUrl = useAppStore((s) => s.setTunnelRelayUrl);
  const setTunnelRunning = useAppStore((s) => s.setTunnelRunning);

  const [status, setStatus] = useState<TunnelStatus | null>(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  // Result of the "Test relay" probe (a /health round-trip), shown inline under the URL.
  const [test, setTest] = useState<RelayTest>({ state: "idle" });
  // Set when a view-only phone tries to send input, so the grant control is highlighted
  // until the desktop responds (#B-wan-viewonly). Cleared once input is granted/revoked.
  const [inputRequested, setInputRequested] = useState(false);

  // Mirror the Rust client's running state into the store so ConsoleWorkspace knows
  // whether to push live pane metadata.
  const sync = useCallback((s: TunnelStatus) => {
    setStatus(s);
    setTunnelRunning(s.running);
  }, [setTunnelRunning]);

  useEffect(() => {
    tunnelStatus().then(sync).catch((e) => setErr(String(e)));
  }, [sync]);

  // While connected, poll so the client count / pairing updates without interaction.
  // `sync` is stable (useCallback over the stable store setter), so this re-runs only
  // when the running state flips.
  const running = status?.running ?? false;
  usePoll(() => {
    if (!running) return;
    tunnelStatus().then(sync).catch(() => { /* transient; keep last */ });
  }, 2000, [running, sync], { immediate: false });

  // A view-only phone that tries to type fires this once; surface it so the desktop can
  // decide to grant input. The badge clears as soon as the desktop grants or revokes.
  useEffect(() => {
    if (!running) return;
    const unlisten = listen("tunnel://input-requested", () => setInputRequested(true));
    return () => { unlisten.then((off) => off()); };
  }, [running]);

  // #3248: complete the mobile→desktop flows that had no listener. A plan PUSH from the phone is
  // applied to the hub dir (path-safe) and acked back; an EXPIRED room is surfaced so the card doesn't
  // read as connected.
  useEffect(() => {
    if (!running) return;
    const push = listen<{ projectId: string; files: CanonicalFile[] }>(
      "tunnel://plan-sync-push",
      (e) => { void applyPushedPlanPush(e.payload.projectId, e.payload.files); },
    );
    const expired = listen("tunnel://room-expired", () => {
      setErr("The tunnel room expired — re-pair from the phone to reconnect.");
      tunnelStatus().then(sync).catch(() => { /* transient; keep last */ });
    });
    return () => { push.then((off) => off()); expired.then((off) => off()); };
  }, [running, sync]);

  const onToggleInput = useCallback(async () => {
    const next = !(status?.inputGranted ?? false);
    setBusy(true);
    setErr(null);
    try {
      sync(await tunnelSetInputGranted(next));
      setInputRequested(false);
    } catch (e) {
      setErr(String(e));
    } finally {
      setBusy(false);
    }
  }, [status, sync]);

  const onUnpair = useCallback(async () => {
    setBusy(true);
    setErr(null);
    try {
      sync(await tunnelUnpair());
      setInputRequested(false);
    } catch (e) {
      setErr(String(e));
    } finally {
      setBusy(false);
    }
  }, [sync]);

  // Probe the relay across three distinct legs — reachability, room-join, and an
  // end-to-end relayed frame — so a failure points at WHICH layer is broken rather than a
  // single opaque pass/fail. Each leg updates inline as it resolves (via onLeg).
  const onTest = useCallback(async () => {
    const target = tunnelRelayUrl.trim();
    if (!target) return;
    setTest({ state: "running", legs: emptyLegs() });
    const result = await runRelayProbe(target, {
      fetchFn: fetch,
      // The browser WebSocket's strict DOM event types are wider than the minimal surface
      // the probe uses (onopen/onmessage/send/close); adapt it through the interface.
      makeSocket: (url) => new WebSocket(url) as unknown as MinimalSocket,
      timeoutMs: TEST_TIMEOUT_MS,
      genId: freshRoomId,
      onLeg: (legs) =>
        setTest((prev) => (prev.state === "running" ? { ...prev, legs } : prev)),
    });
    setTest({ state: "done", legs: result.legs, version: result.version });
  }, [tunnelRelayUrl]);

  const onConnect = useCallback(async () => {
    setBusy(true);
    setErr(null);
    try {
      sync(running ? await tunnelStop() : await tunnelStart(tunnelRelayUrl.trim()));
    } catch (e) {
      setErr(String(e));
    } finally {
      setBusy(false);
    }
  }, [running, tunnelRelayUrl, sync]);

  const payload = status ? pairingPayload(status) : null;
  const qrValue = payload ? JSON.stringify(payload) : "";
  const clients = status?.clientCount ?? 0;
  const inputGranted = status?.inputGranted ?? false;
  const paired = clients > 0;
  const canConnect = tunnelRelayUrl.trim().length > 0;

  return (
    <Box style={{ maxWidth: 820 }}>
      <Text as="h2" mono size="xl" weight={600} style={{ margin: "0 0 4px" }}>Mobile tunnel</Text>
      <Text as="p" tone="muted" size="md" style={{ margin: "0 0 22px", lineHeight: 1.6 }}>
        Pair <code>mobile-studio-code</code> to mirror these consoles from your phone — from
        anywhere. Traffic flows through a <b>zero-knowledge relay</b> you deploy into your own
        Cloudflare account; it's end-to-end encrypted (Noise), so the relay never sees your
        terminal.
      </Text>

      <Card>
        <Row gap={12} style={{ marginBottom: 14 }}>
          <Text as="h3" style={{ margin: 0 }}>Relay connection</Text>
          <Chip tone={running ? "success" : "neutral"}>
            {running ? (clients > 0 ? `● paired · ${clients} device${clients === 1 ? "" : "s"}` : "● waiting for a device") : "○ disconnected"}
          </Chip>
          <Box as="span" style={{ flex: 1 }} />
          <Button disabled={busy || (!running && !canConnect)} onClick={onConnect}>
            {running ? "disconnect" : busy ? "connecting…" : "connect"}
          </Button>
        </Row>

        {err && (
          <Box className="mono" pad={[8, 10]} bg="var(--bg-elev)" border="soft" radius={6} style={{
            fontSize: 11, color: "var(--danger)", marginBottom: 14,
          }}>{err}</Box>
        )}

        <Field label="Relay URL" style={{ marginBottom: running && payload ? 18 : 0 }}>
          <Row gap={8} align="stretch">
            {/* eslint-disable-next-line no-restricted-syntax -- input shares a Row with multiple action buttons; TextField's .field wrapper would break the inline layout */}
            <input
              className="input"
              placeholder="https://msc-tunnel-relay.<you>.workers.dev"
              value={tunnelRelayUrl}
              disabled={running}
              onChange={(e) => {
                setTunnelRelayUrl(e.target.value);
                setTest({ state: "idle" }); // a fresh URL invalidates the last probe
              }}
            />
            <Button
              disabled={busy || running || test.state === "running" || !canConnect}
              onClick={onTest}
            >
              {test.state === "running" ? "testing…" : "test"}
            </Button>
            <Button onClick={() => openUrl(DEPLOY_URL)}>
              deploy a relay →
            </Button>
            <Button
              title="Open this relay's Worker in your Cloudflare dashboard"
              onClick={() => openUrl(cloudflareDashUrl(tunnelRelayUrl))}
            >
              manage in Cloudflare ↗
            </Button>
          </Row>
          {test.state === "idle" ? (
            <Box className="hint">
              Your own Cloudflare Worker (free tier is enough). Deploy once, paste the URL it prints.
            </Box>
          ) : (
            <Stack
              className="hint"
              gap={3}
              style={{ marginTop: 8 }}
              role="status"
              aria-live="polite"
            >
              {LEG_LABELS.map(({ key, label }) => {
                const leg = test.legs[key];
                const { glyph, color } = legGlyph(leg.status);
                return (
                  <Row key={key} align="baseline" gap={8}>
                    <Box as="span" className="mono" style={{ color, width: 12, textAlign: "center" }}>{glyph}</Box>
                    <Box as="span" style={{ color: leg.status === "fail" ? "var(--danger)" : "var(--fg)", minWidth: 110 }}>{label}</Box>
                    {leg.detail && <Text as="span" tone="muted">{leg.detail}</Text>}
                  </Row>
                );
              })}
            </Stack>
          )}
        </Field>

        {running && payload ? (
          <Grid cols="auto 1fr" gap={20} align="start">
            {/* QR — rendered on white for reliable scanning regardless of theme. */}
            <Stack align="center" gap={8} style={{ background: "#ffffff", padding: 12, borderRadius: 10 }}>
              <QRCodeSVG value={qrValue} size={184} bgColor="#ffffff" fgColor="#000000" level="M" />
              <Text as="div" mono size={9.5} style={{ color: "#666", letterSpacing: ".04em" }}>
                SCAN IN MOBILE-STUDIO-CODE
              </Text>
            </Stack>

            <Stack gap={14} style={{ minWidth: 0 }}>
              <TextField
                label="Room"
                readOnly
                value={status?.room ?? ""}
                onChange={() => {}}
                style={{ fontSize: 11 }}
                hint="A fresh, high-entropy room is allocated each time you connect."
              />
              <TextField
                label="Host key (Noise)"
                readOnly
                value={status?.hostPubKey ?? ""}
                onChange={() => {}}
                style={{ fontSize: 10.5 }}
                hint={<>
                  The phone pins this from the QR — it's how it knows it's talking to <i>your</i>
                  desktop, not the relay.
                </>}
              />
              <Field label="Input control">
                <Row gap={10}>
                  <Chip tone={inputGranted ? "success" : "neutral"}>
                    {inputGranted ? "● input granted" : "○ view-only"}
                  </Chip>
                  <Box as="span" style={{ flex: 1 }} />
                  <Button
                    disabled={busy || !paired}
                    onClick={onToggleInput}
                    style={inputRequested && !inputGranted
                      ? { borderColor: "var(--accent)", color: "var(--accent)" }
                      : undefined}
                  >
                    {inputGranted ? "revoke input" : "grant input"}
                  </Button>
                </Row>
                <Box className="hint">
                  {!paired
                    ? "A paired phone starts view-only — it mirrors these panes but cannot type."
                    : inputRequested && !inputGranted
                      ? "The paired phone is asking to send input. Grant it to let the phone drive a pane."
                      : inputGranted
                        ? "The paired phone can drive panes. Revoke to return it to view-only."
                        : "The phone is view-only — keystrokes are dropped until you grant input."}
                </Box>
              </Field>
              {paired && (
                <Field label="Paired device">
                  <Row gap={10}>
                    <Box as="span" style={{ flex: 1 }} />
                    <Button disabled={busy} onClick={onUnpair}>
                      unpair device
                    </Button>
                  </Row>
                  <Box className="hint">
                    Drops the connected phone, rotates the room + pairing secret (the old QR
                    stops working), and shows a fresh QR to pair again.
                  </Box>
                </Field>
              )}
              <Text as="div" className="hint mono" size={10.5}>
                The pairing secret is carried inside the QR only — never shown or logged.
              </Text>
            </Stack>
          </Grid>
        ) : (
          <Box className="hint" style={{ padding: "8px 0 0" }}>
            {running
              ? "Connecting to the relay…"
              : "Connect to allocate a room and generate a pairing QR."}
          </Box>
        )}
      </Card>
    </Box>
  );
}

runtime.features/tunnel/useStoreProjector.ts:
// useStoreProjector (#2498) — the generic mobile projector, mounted ONCE in App beside
// useTunnelSync. Subscribes to each scoped store_state domain's sources (the SAME data the
// desktop pages read — see the #2496 inventory) and pushes the pure projections
// (lib/storeProjections.ts) through the shared domain publisher, which debounces per domain,
// dedups unchanged payloads, and stamps monotonic revs. Everything no-ops while the relay is
// down. The `plan` domain is the one exception published elsewhere: the stage/gate board only
// exists inside the live planner (usePlannerTunnelSync), so the planner pushes it.
//
// Alerts: this hook also drives the app-wide alert pipeline — coord-log alerts (agent-paused /
// worker-question / fleet-failed / fleet-landed) from the polled CoordState, and prompt-waiting
// from the focus queue's awaiting set. The planner contributes gate-ready + planner-waiting
// from its own transitions. All converge on the alert hub (inbox domain + FCM push).

import { useEffect, useMemo, useRef, useState } from "react";
import { useAppStore } from "@/store";
import { usePoll } from "@/shared/hooks/usePoll";
import { readCoordState } from "@/shared/lib/fleet/useCoordLog";
import { logsTail } from "@/shared/lib/core/logsBridge";
import { paneIdFor } from "@/app/console/lib/paneIdentity";
import { useGlanceProjects, useGlanceFaults, useProjectFleet } from "@/features/glance";
import { resolveKitLibraryRefs } from "@/features/designs";
import { loadPendingLessons } from "@/features/skills";
import { resolveAllInstalledMcp } from "@/features/mcp";
import { deriveConsoles, buildAuditRows, APP_ROLES } from "@/features/security";
import type { Lesson } from "@/features/skills/lib/lessons";
import {
  buildGlancePayload, buildOrgPayload, buildBlueprintsPayload, buildSkillsPayload,
  buildComponentsPayload, buildThemesPayload, buildAutomationsPayload, buildMcpPayload,
  buildSecurityPayload,
} from "./lib/storeProjections";
import { publishTunnelDomain, resetTunnelDomains } from "./lib/tunnelDomains";
import { recordTunnelAlerts, seedTunnelAlerts } from "./lib/alertHub";
import { coordAlerts, promptAlerts, type AwaitingPane } from "./lib/alerts";

const LESSONS_POLL_MS = 15_000;
const COORD_POLL_MS = 2_000;
// The audit log is a CLI read (no store slice); poll it modestly for the mobile mirror — the
// desktop Agents page polls faster (3s) but only while its Activity tab is open (#2530).
const AUDIT_POLL_MS = 15_000;

export function useStoreProjector(): void {
  const tunnelRunning = useAppStore((s) => s.tunnelRunning);

  // A relay (re)start forgets the last-sent cache so the fresh Rust-side store repopulates
  // even when the frontend store hasn't changed since the previous run.
  const wasRunning = useRef(false);
  useEffect(() => {
    if (tunnelRunning && !wasRunning.current) resetTunnelDomains();
    wasRunning.current = tunnelRunning;
  }, [tunnelRunning]);

  // Personas: read once, shared by the glance payload (stream-role resolution, #2530) + the org payload.
  const personas = useAppStore((s) => s.personas);

  // Components/kits/kit-usage: read once — shared by the glance kit + library BANDS (#3743) and the
  // `components` domain below. `libraryRefs` is the cross-graph algorithm/sound roll-up (#3133), the same
  // `resolveKitLibraryRefs(components)` the Glance workspace feeds `buildGlanceData`.
  const components = useAppStore((s) => s.components);
  const kits = useAppStore((s) => s.kits);
  const kitUsage = useAppStore((s) => s.kitUsage);
  const libraryRefs = useMemo(() => resolveKitLibraryRefs(components), [components]);

  // ── glance — projects + links + faults + drill + PER-PROJECT fleets + stream roles (#2530) ──
  const projects = useGlanceProjects(tunnelRunning);
  const faults = useGlanceFaults(tunnelRunning ? projects.map((p) => p.id) : []);
  const links = useAppStore((s) => s.projectLinks);
  const drill = useAppStore((s) => s.glanceDrill);
  const planFleet = useAppStore((s) => s.planFleet);
  // The active project's fleet is already mirrored in the store; any other drilled project's is
  // loaded from its own plan.db — the same preference the Glance workspace applies. Ship EVERY loaded
  // fleet keyed by project (not just the drilled one) so any project node drills on mobile (#2530),
  // merging the on-demand drilled fleet in when the store doesn't already hold it.
  const drillFleetLoaded = useProjectFleet(tunnelRunning ? drill : null);
  const fleets = useMemo(
    () => (drill && drillFleetLoaded && !planFleet[drill] ? { ...planFleet, [drill]: drillFleetLoaded } : planFleet),
    [planFleet, drill, drillFleetLoaded],
  );
  useEffect(() => {
    if (!tunnelRunning) return;
    // #3743: carry the kit + library bands (kitUsage/kits/libraryRefs) so mobile rebuilds the FULL cockpit.
    publishTunnelDomain(
      "glance",
      buildGlancePayload({ projects, links, faults, drill, fleets, personas, kitUsage, kits, libraryRefs }),
    );
  }, [tunnelRunning, projects, links, faults, drill, fleets, personas, kitUsage, kits, libraryRefs]);

  // ── org — the org library + pared persona refs ────────────────────────────────
  const teams = useAppStore((s) => s.teams);
  useEffect(() => {
    if (!tunnelRunning) return;
    // Wire domain + payload field stay "org"/`orgs` (mobile tunnel contract, #2700); only the store read renamed.
    publishTunnelDomain("org", buildOrgPayload({ orgs: teams, personas }));
  }, [tunnelRunning, teams, personas]);

  // ── blueprints — library cards + the active blueprint's team graph ────────────
  const blueprints = useAppStore((s) => s.blueprints);
  const activeBlueprintId = useAppStore((s) => s.activeBlueprintId);
  useEffect(() => {
    if (!tunnelRunning) return;
    publishTunnelDomain("blueprints", buildBlueprintsPayload({ blueprints, activeBlueprintId }));
  }, [tunnelRunning, blueprints, activeBlueprintId]);

  // ── skills — library + groups + the active project's pending lessons ──────────
  const skills = useAppStore((s) => s.skills);
  const skillGroups = useAppStore((s) => s.skillGroups);
  const activeKey = useAppStore((s) => s.planningSessionKey || s.activeProjectId || "");
  const [lessons, setLessons] = useState<{ project: string; pending: Lesson[] } | null>(null);
  usePoll(async (isCancelled) => {
    if (!tunnelRunning || !activeKey) {
      setLessons(null); // React bails out when already null
      return;
    }
    const pending = await loadPendingLessons(activeKey);
    if (isCancelled()) return;
    setLessons({ project: activeKey, pending });
  }, LESSONS_POLL_MS, [tunnelRunning, activeKey]);
  useEffect(() => {
    if (!tunnelRunning) return;
    publishTunnelDomain("skills", buildSkillsPayload({ skills, groups: skillGroups, lessons }));
  }, [tunnelRunning, skills, skillGroups, lessons]);

  // ── components + themes — kits/components summaries · the theme registry ──────
  // (components/kits/kitUsage are read once above — shared with the glance bands, #3743.)
  useEffect(() => {
    if (!tunnelRunning) return;
    publishTunnelDomain("components", buildComponentsPayload({ kits, components, usage: kitUsage }));
  }, [tunnelRunning, kits, components, kitUsage]);

  const kitThemes = useAppStore((s) => s.kitThemes);
  const kitTheme = useAppStore((s) => s.kitTheme);
  useEffect(() => {
    if (!tunnelRunning) return;
    publishTunnelDomain("themes", buildThemesPayload({ themes: kitThemes, active: kitTheme }));
  }, [tunnelRunning, kitThemes, kitTheme]);

  // ── automations + mcp ──────────────────────────────────────────────────────────
  const automations = useAppStore((s) => s.automations);
  const hooks = useAppStore((s) => s.hooks);
  useEffect(() => {
    if (!tunnelRunning) return;
    publishTunnelDomain("automations", buildAutomationsPayload({ automations, hooks }));
  }, [tunnelRunning, automations, hooks]);

  const mcpServers = useAppStore((s) => s.mcpServers);
  useEffect(() => {
    if (!tunnelRunning) return;
    const installedIds = resolveAllInstalledMcp(mcpServers).map((s) => s.id);
    publishTunnelDomain("mcp", buildMcpPayload({ servers: mcpServers, installedIds }));
  }, [tunnelRunning, mcpServers]);

  // ── security — application roles + assignable profiles + console model + per-pane assignments +
  // recent audit (#2530 / #3754) ──
  // Profiles + assignments are live store slices; the console model is derived from the workspace tabs
  // (the SAME deriveConsoles the desktop Security page uses), and the audit log is a CLI read (no store
  // slice), polled like lessons/coord. The audit `decision` + pane→console name are computed HERE via
  // buildAuditRows (the desktop's one source of truth) so mobile never re-derives a security verdict.
  const agentProfiles = useAppStore((s) => s.agentProfiles);
  const paneRoles = useAppStore((s) => s.paneRoles);
  const paneProfiles = useAppStore((s) => s.paneProfiles);
  const tabs = useAppStore((s) => s.tabs);
  const paneNames = useAppStore((s) => s.paneNames);
  const disabledPanes = useAppStore((s) => s.disabledPanes);
  const activeRepoName = useAppStore((s) => s.activeRepoName);
  const secConsoles = useMemo(
    () => deriveConsoles({ tabs, paneNames, disabledPanes, paneProfiles, activeRepoName }),
    [tabs, paneNames, disabledPanes, paneProfiles, activeRepoName],
  );
  const [auditLines, setAuditLines] = useState<string[]>([]);
  usePoll(async (isCancelled) => {
    if (!tunnelRunning) { setAuditLines([]); return; } // React bails when already []
    const lines = await logsTail("audit", 300);
    if (isCancelled()) return;
    setAuditLines(lines);
  }, AUDIT_POLL_MS, [tunnelRunning]);
  const auditRows = useMemo(
    () => buildAuditRows(auditLines, { consoles: secConsoles, profiles: agentProfiles, paneProfiles, paneRoles }),
    [auditLines, secConsoles, agentProfiles, paneProfiles, paneRoles],
  );
  useEffect(() => {
    if (!tunnelRunning) return;
    publishTunnelDomain("security", buildSecurityPayload({
      appRoles: APP_ROLES, profiles: agentProfiles, consoles: secConsoles, paneRoles, paneProfiles, auditRows,
    }));
  }, [tunnelRunning, agentProfiles, secConsoles, paneRoles, paneProfiles, auditRows]);

  // ── alerts — coord-log events + the focus queue's awaiting set ────────────────
  // Coord entries carry their own `at`, so re-derivation is idempotent (the hub dedups by id).
  // The FIRST successful read after the relay starts SEEDS the inbox without pushing — the
  // historical log fills the mobile inbox but never fires a burst of stale FCM notifications.
  const coordSeeded = useRef(false);
  useEffect(() => {
    if (!tunnelRunning) coordSeeded.current = false;
  }, [tunnelRunning]);
  usePoll(async (isCancelled) => {
    if (!tunnelRunning) return;
    const res = await readCoordState(1000);
    if (isCancelled() || !res) return;
    const candidates = coordAlerts(res.state);
    if (coordSeeded.current) {
      recordTunnelAlerts(candidates);
    } else {
      coordSeeded.current = true;
      seedTunnelAlerts(candidates);
    }
  }, COORD_POLL_MS, [tunnelRunning]);

  // Prompt-waiting is a transition (no durable log): diff the awaiting set against the previous
  // tick; a pane that resolves and awaits again re-alerts. (`tabs`/`paneNames` are read once above
  // for the security console model.)
  const focusQueue = useAppStore((s) => s.focusQueue);
  const prevAwaiting = useRef<AwaitingPane[]>([]);
  useEffect(() => {
    if (!tunnelRunning) {
      prevAwaiting.current = [];
      return;
    }
    const awaiting: AwaitingPane[] = focusQueue.map((q) => ({
      paneId: paneIdFor(tabs[q.tab], q.tab, q.pane),
      name: paneNames[q.tab]?.[q.pane] ?? `console-${q.tab + 1}-${q.pane + 1}`,
    }));
    recordTunnelAlerts(promptAlerts(prevAwaiting.current, awaiting, Date.now()));
    prevAwaiting.current = awaiting;
  }, [tunnelRunning, focusQueue, tabs, paneNames]);
}

runtime.features/tunnel/useTunnelSync.ts:
// Always-on tunnel pane-sync (#801). Pushes the relay's pane list + session metadata
// from the store, regardless of which screen is mounted — previously this lived in
// Console.tsx, so the mirror went stale (and excluded the planner) the moment you left
// the Console screen. Mounted once in App. PTY *bytes* are teed in Rust; this is the
// low-volume names/cwds/statuses + every registered extra session (planner/designer,
// via the keyed `tunnelExtraPanes` registry, #2497).
//
// Roster identity (#2497): panes ride under their IDENTITY id (`paneIdFor`, #1176) — the
// same id their PTY/status/cwd are keyed by — with a `kind` derived from the id grammar,
// so fleet workers (`<key>:<stream>`), the director, triage panes, and manual consoles
// are all addressable from mobile.

import { useEffect } from "react";
import { useAppStore } from "@/store";
import { paneIdFor } from "@/app/console/lib/paneIdentity";
import { buildPanePayload } from "./lib/tunnel";
import { tunnelSetPanes, tunnelSetSessions } from "./lib/tunnelClient";
import { log } from "@/shared/lib/core/log";

export function useTunnelSync(): void {
  const tunnelRunning = useAppStore((s) => s.tunnelRunning);
  const tabs          = useAppStore((s) => s.tabs);
  const paneNames     = useAppStore((s) => s.paneNames);
  const paneCwds      = useAppStore((s) => s.paneCwds);
  const paneStatuses  = useAppStore((s) => s.paneStatus);
  const disabledPanes = useAppStore((s) => s.disabledPanes);
  const focusQueue    = useAppStore((s) => s.focusQueue);
  const extraPanes    = useAppStore((s) => s.tunnelExtraPanes);

  useEffect(() => {
    if (!tunnelRunning) return;
    // The focus queue is positional (tab/pane indices) — resolve each entry to the same
    // identity id the payload keys panes by.
    const awaiting = new Set(focusQueue.map((q) => paneIdFor(tabs[q.tab], q.tab, q.pane)));
    // Flatten the keyed extra-pane registry in stable (sorted-source) order so re-registration
    // by one source never reorders another's panes.
    const extras = Object.keys(extraPanes).sort().flatMap((source) => extraPanes[source]);
    const { panes, sessions } = buildPanePayload({
      tabs, paneNames, paneCwds, paneStatuses, disabledPanes, awaiting,
      nowIso: new Date().toISOString(),
      extraPanes: extras,
    });
    tunnelSetPanes(panes).catch((e) => log.error(`tunnel: set_panes failed: ${e}`));
    tunnelSetSessions(sessions).catch((e) => log.error(`tunnel: set_sessions failed: ${e}`));
  }, [tunnelRunning, tabs, paneNames, paneCwds, paneStatuses, disabledPanes, focusQueue, extraPanes]);
}

