import { useEffect } from "react";
import { useAppStore } from "@/store";

/**
 * Report the navigated ENTITY label for a graph to the titlebar location crumb (#3041) — the thing you're
 * INSIDE the graph: the drilled project (Glance), the entered team (Teams), the active kit (Components),
 * the active language (Algorithms). `key` is the page id (`glance`/`teams`/`designs`/`algorithms`);
 * `label` is the current entity name, `""` when none (e.g. a graph overview). `locationCrumb` appends it
 * after the page name, so the crumb reads e.g. "Planner — Components — react-ui".
 *
 * The graph resolves the label itself (it has the local selection + the data), so the store just carries
 * the resolved string — App.tsx needs no per-graph knowledge. The store write is idempotent, so calling
 * this every render is cheap.
 */
export function useCrumbEntity(key: string, label: string): void {
  const setCrumbEntity = useAppStore((s) => s.setCrumbEntity);
  // Block body (not `() => setCrumbEntity(...)`) so the effect returns undefined — an implicit return of
  // the action's value would be mistaken for a cleanup fn ("destroy is not a function" on unmount).
  useEffect(() => { setCrumbEntity(key, label); }, [key, label, setCrumbEntity]);
}

runtime.shared/hooks/useDockEntrance.ts:
// useDockEntrance (#2905) — the session dock's ENTRANCE GROW. Replaces the CSS slide/fade
// (`session-dock-in`, #2837), which animated only transform/opacity: it never changed layout size, so it
// never resized the xterm and needed a fragile post-animation "settle fit". This animates the dock's REAL
// height up into place via the caller's `useDragResize` setter, so the height change itself drives the
// terminal's ResizeObserver fit — no transform, no settle hack.
//
// Runs before paint (useLayoutEffect) so the grow starts small with no full-height flash, and steps by a
// frame COUNT rather than wall-clock so the synchronous `requestAnimationFrame` stub in tests terminates.
// A reduced-motion viewer jumps straight to the resting height.
import { useLayoutEffect } from "react";

/** easeOutCubic — fast start, gentle settle. */
const ease = (x: number): number => 1 - Math.pow(1 - x, 3);
/** Frames the grow spans (~340ms at 60fps). */
const FRAMES = 20;

/**
 * Animate `setSize` from a fraction of `target` up to `target` once, on mount — the dock entrance grow.
 * `setSize` is the `useDragResize` setter (unclamped) and `target` is the resting dock height (px).
 */
export function useDockEntrance(setSize: (n: number) => void, target: number): void {
  useLayoutEffect(() => {
    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches ?? false;
    const from = Math.round(target * 0.35);
    if (reduce || from >= target || typeof requestAnimationFrame !== "function") {
      setSize(target);
      return;
    }
    setSize(from); // before paint (useLayoutEffect) → the grow starts small, no full-height flash
    let frame = 0;
    let raf = 0;
    let cancelled = false;
    const step = () => {
      if (cancelled) return;
      frame += 1;
      const p = Math.min(1, frame / FRAMES);
      setSize(p >= 1 ? target : Math.round(from + (target - from) * ease(p)));
      if (p < 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => { cancelled = true; cancelAnimationFrame(raf); };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps -- run once on mount
}

runtime.shared/hooks/useDraft.ts:
// useDraft (#1824) — the selection + draft-editor state every list+detail surface hand-rolls.
// One `selectedId`/`draft` pair drives a `<Pane>`: selecting an existing item edits it through to
// the store; starting a draft edits an in-memory copy until committed. Pairs with `<Pane>`.
//
//   const d = useDraft<Skill>({ items: skills, newDraft, onUpdate: updateSkill, onCreate });
//   d.selected   // draft ?? items.find(selectedId)   — the item the pane is editing (or null)
//   d.isDraft    // editing an uncommitted new item
//   d.select(id) // open an existing item (clears any draft)
//   d.startDraft()       // begin a new item (requires `newDraft`)
//   d.patch(partial)     // draft → in-memory merge; existing → onUpdate(id, partial)
//   d.commit()           // draft → onCreate(draft) then select the new id (requires `onCreate`)
//   d.close()            // clear selection + draft
import { useCallback, useState } from "react";

export interface UseDraftOptions<T extends { id: string }> {
  /** The live list of committed items (from the store). */
  items: T[];
  /** Factory for a fresh draft (with a sentinel id). Omit for selection-only surfaces. */
  newDraft?: () => T;
  /** Patch an existing committed item in the store. */
  onUpdate: (id: string, patch: Partial<T>) => void;
  /** Commit a draft → returns the new item's id. Required for `startDraft`/`commit`. */
  onCreate?: (draft: T) => string;
}

export interface Draft<T extends { id: string }> {
  selectedId: string | null;
  /** The draft, else the selected committed item, else null. */
  selected: T | null;
  isDraft: boolean;
  select: (id: string | null) => void;
  startDraft: () => void;
  patch: (patch: Partial<T>) => void;
  commit: () => void;
  close: () => void;
}

export function useDraft<T extends { id: string }>({ items, newDraft, onUpdate, onCreate }: UseDraftOptions<T>): Draft<T> {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [draft, setDraft] = useState<T | null>(null);

  const existing = selectedId ? items.find(i => i.id === selectedId) ?? null : null;
  const selected = draft ?? existing;
  const isDraft = !!draft;

  const select = useCallback((id: string | null) => { setDraft(null); setSelectedId(id); }, []);

  const startDraft = useCallback(() => {
    if (!newDraft) return;
    setSelectedId(null);
    setDraft(newDraft());
  }, [newDraft]);

  const patch = useCallback((p: Partial<T>) => {
    // Draft edits merge in memory (pure functional update); existing items patch through to the store.
    if (draft) setDraft(d => (d ? { ...d, ...p } : d));
    else if (selectedId) onUpdate(selectedId, p);
  }, [draft, selectedId, onUpdate]);

  const commit = useCallback(() => {
    if (!draft || !onCreate) return;
    const id = onCreate(draft);
    setDraft(null);
    setSelectedId(id);
  }, [draft, onCreate]);

  const close = useCallback(() => { setDraft(null); setSelectedId(null); }, []);

  return { selectedId, selected, isDraft, select, startDraft, patch, commit, close };
}

runtime.shared/hooks/useDragResize.ts:
import { useCallback, useRef, useState, type PointerEvent as ReactPointerEvent } from "react";
import { clamp } from "@/shared/lib/core/math";

interface DragResizeOptions {
  /** Starting size in px. */
  initial: number;
  /** Lower bound in px. */
  min: number;
  /** Upper bound in px. */
  max: number;
  /** Which axis the handle drags along. */
  axis: "x" | "y";
  /**
   * Invert the delta. Use when the resized panel sits *after* the handle along
   * the axis (e.g. a right-hand panel grows as the pointer moves left).
   */
  invert?: boolean;
}

/**
 * Drag-to-resize state for a splitter handle. Spread `handleProps` onto the
 * divider element; `size` is the live, clamped dimension to apply to the panel.
 *
 * Uses pointer capture on the handle so the drag keeps tracking even when the
 * cursor leaves the thin divider — no global listeners to register or clean up.
 */
export function useDragResize({ initial, min, max, axis, invert = false }: DragResizeOptions) {
  const [size, setSize] = useState(() => clamp(initial, min, max));
  // Pointer position + panel size captured at drag start; null when not dragging.
  const start = useRef<{ pos: number; size: number } | null>(null);

  const onPointerDown = useCallback((e: ReactPointerEvent) => {
    e.preventDefault();
    (e.currentTarget as Element).setPointerCapture?.(e.pointerId);
    start.current = { pos: axis === "x" ? e.clientX : e.clientY, size };
  }, [axis, size]);

  const onPointerMove = useCallback((e: ReactPointerEvent) => {
    if (!start.current) return;
    const cur = axis === "x" ? e.clientX : e.clientY;
    const delta = (cur - start.current.pos) * (invert ? -1 : 1);
    setSize(clamp(start.current.size + delta, min, max));
  }, [axis, invert, min, max]);

  const onPointerUp = useCallback((e: ReactPointerEvent) => {
    start.current = null;
    (e.currentTarget as Element).releasePointerCapture?.(e.pointerId);
  }, []);

  return { size, setSize, handleProps: { onPointerDown, onPointerMove, onPointerUp } };
}

runtime.shared/hooks/useExpandable.ts:
import { useState, useCallback } from "react";

/** useExpandable — Set-based expand/collapse (toggle-membership) state. Replaces the hand-rolled
 *  `useState<Set<string>>` + toggle that every expandable list (focused bodies, blueprint stages,
 *  scan entities, …) re-declares. `toggle(id)` flips membership; `isOpen(id)` reads it; `open` and
 *  `setOpen` are exposed for direct use. */
export function useExpandable(initial?: Iterable<string>) {
  const [open, setOpen] = useState<Set<string>>(() => new Set(initial));
  const toggle = useCallback((id: string) => {
    setOpen((s) => {
      const n = new Set(s);
      if (n.has(id)) n.delete(id); else n.add(id);
      return n;
    });
  }, []);
  const isOpen = useCallback((id: string) => open.has(id), [open]);
  return { open, isOpen, toggle, setOpen };
}

runtime.shared/hooks/useLogStream.ts:
// useLogStream (#3638) — the event-driven replacement for `usePoll` over a `bsc logs` stream. The
// frontend used to poll each unified log stream every ~1s; instead, the backend watcher
// (`observability::log_watch`) emits `logs://<stream>` when a stream file changes, and this hook
// re-reads (via the in-process `logs_*` commands, #3630) ONLY on that event. So reads happen on
// CHANGE, not on a clock — an idle app makes zero log reads.
//
// It keeps `usePoll`'s callback contract (an `isCancelled()` guard) so the pump bodies move over
// unchanged. A slow safety-net interval (default 60s) is the sole remaining "poll", a backstop against
// a missed change event — 60× rarer than the ~1s polls it replaces, and effectively silent.

import { useEffect, useRef, type DependencyList } from "react";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";
import { usePoll } from "@/shared/hooks/usePoll";
import { logEventName } from "@/shared/lib/core/logsBridge";

interface LogStreamOptions {
  /** Safety-net re-read interval (ms) — a backstop against a missed change event. Default 60000. */
  safetyMs?: number;
  /** When false, don't subscribe or read at all — the caller-side gate (e.g. page visibility, #3627).
   *  Default true. */
  active?: boolean;
}

/**
 * Re-run `fn` when any of `streams` changes (the `logs://<stream>` event), plus once on mount and on a
 * slow safety-net interval. `fn` gets the same `isCancelled` guard as {@link usePoll}. Pass the read
 * alias(es) the body reads (`"coord"`, `"activity"`, `"audit"`, …) — canonicalized to match the emit.
 *
 * @param streams one stream alias, or several (a body that reads more than one stream re-runs on any).
 * @param fn the read/process body — identical shape to a `usePoll` callback.
 * @param deps re-subscribe deps (like `usePoll`'s).
 * @param opts `safetyMs` (backstop interval) and `active` (caller-side gate).
 */
export function useLogStream(
  streams: string | string[],
  fn: (isCancelled: () => boolean) => void | Promise<void>,
  deps: DependencyList = [],
  opts: LogStreamOptions = {},
): void {
  const { safetyMs = 60_000, active = true } = opts;
  const list = Array.isArray(streams) ? streams : [streams];
  const key = list.join(",");
  const fnRef = useRef(fn);
  useEffect(() => { fnRef.current = fn; });

  // Initial read on mount + a slow backstop poll. `immediate` gives the current state right away;
  // `active:false` short-circuits both this and the subscription below.
  usePoll((isCancelled) => (active ? fnRef.current(isCancelled) : undefined), safetyMs, [key, active, ...deps]);

  // Re-read on any watched stream's change event.
  useEffect(() => {
    if (!active) return;
    let cancelled = false;
    const isCancelled = () => cancelled;
    const uns: UnlistenFn[] = [];
    for (const s of list) {
      void listen(logEventName(s), () => { if (!cancelled) void fnRef.current(isCancelled); })
        .then((un) => { if (cancelled) un(); else uns.push(un); });
    }
    return () => { cancelled = true; uns.forEach((un) => un()); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, active, ...deps]);
}

runtime.shared/hooks/useModalDismiss.ts:
// useModalDismiss (#1541) — the Escape-to-close + overlay-click-to-close pattern that was
// hand-rolled inline across the app's modals (`Dialog.tsx` is the reference implementation).
//
//  - useModalDismiss(onClose, { enabled }) — a window keydown Escape listener → onClose, with
//    cleanup on unmount / deps-change. `enabled` (default true) gates it, e.g. `{ enabled: !busy }`.
//  - overlayDismiss(onClose?) — an onMouseDown/onClick handler that fires onClose ONLY when the
//    event hits the overlay itself (`e.target === e.currentTarget`), so clicks on the inner card
//    don't dismiss. Pass `undefined` (e.g. while busy/deleting) to disable dismissal entirely.

import { useEffect, type MouseEvent } from "react";

export function useModalDismiss(onClose: () => void, opts?: { enabled?: boolean }): void {
  const enabled = opts?.enabled ?? true;
  useEffect(() => {
    if (!enabled) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose, enabled]);
}

/** An overlay click/mousedown handler that dismisses only when the overlay itself is the target.
 *  `onClose === undefined` makes it a no-op (use for a busy/locked modal). */
export function overlayDismiss(onClose?: () => void) {
  return (e: MouseEvent) => {
    if (onClose && e.target === e.currentTarget) onClose();
  };
}

runtime.shared/hooks/usePageTabs.ts:
// usePageTabs -- the shared per-page tab model (#463). Every page's tab bar uses
// this so behavior is identical: the tab order is persisted per page, the page
// "opens the first tab" (so the user's preferred view = whatever they drag to the
// front), reordering persists, and tear-off is wired in by the page.

import { useCallback, useEffect, useMemo } from "react";
import { useAppStore } from "@/store";
import { moveInArray } from "@/shared/lib/core/arrayMove";
import { openDetachedSection } from "@/shared/lib/core/detachSection";
import type { TabItem } from "@/shared/ui/layouts/TabBar";

const EMPTY: string[] = [];

/**
 * Order `defs` by a persisted id list: known ids first (in persisted order),
 * then any defs not in the list (new tabs) appended in their canonical order;
 * stale ids in the list are ignored. Pure — unit-tested.
 */
export function orderTabs(defs: TabItem[], order: string[] | undefined): TabItem[] {
  if (!order || order.length === 0) return defs;
  const byId = new Map(defs.map((d) => [d.id, d]));
  const out: TabItem[] = [];
  for (const id of order) {
    const d = byId.get(id);
    if (d) { out.push(d); byId.delete(id); }
  }
  for (const d of defs) if (byId.has(d.id)) out.push(d);
  return out;
}

export interface PageTabs {
  /** Visible tabs (persisted order, detached sections filtered out). */
  tabs: TabItem[];
  activeId: string;
  select: (id: string) => void;
  reorder: (from: number, to: number) => void;
  /** Tear a section into its own window: opens it, hides it from the bar, and
   *  moves focus off it if it was active. Returns on close/restart. */
  tearOff: (id: string) => void;
}

/**
 * Drive a page's tab bar: returns the persisted-ordered, detached-filtered tabs,
 * the active id (defaults to the first/front visible tab — the user's
 * preference), and select/reorder/tearOff handlers. `pageKey` namespaces both
 * the persisted order and the (session-only) detached set.
 *
 * Pass `controlled` when the active tab lives in the store and is shared across
 * components (e.g. the Projects board, where the bar and the content are separate
 * components) — the hook then reads/writes that instead of the persisted map.
 *
 * The uncontrolled active page is **persisted** per `pageKey` (`activePageTab`), so a
 * workspace reopens on the Page the user last viewed — across an in-session workspace
 * switch and across restart — falling back to the front tab (#463) when there's no
 * memory. A stale persisted id self-heals to the front tab via the validity effect.
 */
export function usePageTabs(
  pageKey: string,
  defs: TabItem[],
  controlled?: { activeId: string; setActive: (id: string) => void },
): PageTabs {
  const order = useAppStore((s) => s.pageTabOrder[pageKey]);
  const setOrder = useAppStore((s) => s.setPageTabOrder);
  const detached = useAppStore((s) => s.detachedSections[pageKey]) ?? EMPTY;
  const setDetached = useAppStore((s) => s.setSectionDetached);
  const persistedActive = useAppStore((s) => s.activePageTab[pageKey]);
  const setPersistedActive = useAppStore((s) => s.setActivePageTab);

  const ordered = useMemo(() => orderTabs(defs, order), [defs, order]);
  const tabs = useMemo(() => ordered.filter((t) => !detached.includes(t.id)), [ordered, detached]);
  const setUncontrolled = useCallback((id: string) => setPersistedActive(pageKey, id), [pageKey, setPersistedActive]);
  const activeId = controlled ? controlled.activeId : (persistedActive ?? tabs[0]?.id ?? "");
  const setActiveId = controlled ? controlled.setActive : setUncontrolled;

  // Keep the active id valid if the visible set changes (order/defs/detach shift):
  // a persisted id that no longer resolves to a visible tab heals to the front tab.
  // Skip while there are no tabs yet so we don't persist an empty selection.
  useEffect(() => {
    if (tabs.length > 0 && !tabs.some((t) => t.id === activeId)) setActiveId(tabs[0].id);
  }, [tabs, activeId, setActiveId]);

  // Reorder operates on visible positions; translate to the full ordered list so
  // detached sections keep their place.
  const reorder = useCallback((from: number, to: number) => {
    const fullIds = ordered.map((t) => t.id);
    const fromFull = fullIds.indexOf(tabs[from]?.id);
    const toFull = fullIds.indexOf(tabs[to]?.id);
    if (fromFull < 0 || toFull < 0) return;
    setOrder(pageKey, moveInArray(fullIds, fromFull, toFull));
  }, [pageKey, ordered, tabs, setOrder]);

  const tearOff = useCallback((id: string) => {
    const def = ordered.find((t) => t.id === id);
    openDetachedSection(pageKey, id, def?.label, () => setDetached(pageKey, id, false));
    setDetached(pageKey, id, true);
    if (activeId === id) {
      const next = tabs.find((t) => t.id !== id);
      if (next) setActiveId(next.id);
    }
  }, [pageKey, ordered, tabs, activeId, setDetached, setActiveId]);

  return { tabs, activeId, select: setActiveId, reorder, tearOff };
}

runtime.shared/hooks/usePoll.ts:
// usePoll (#1494) — the one polling primitive. Replaces the ~identical
// `useEffect` + `setInterval` + `clearInterval` + cancelled-guard blocks scattered across the
// app (per-pane token usage, the idle reaper, worker audit, skills refresh, …).
//
// Contract, matching the hand-rolled blocks it replaces:
//  - runs `fn` once immediately, then every `ms` (pass `{ immediate: false }` to skip the first run
//    — e.g. the idle reaper, which must honor its grace window before the first tick);
//  - re-subscribes only when `ms` or `deps` change (the latest `fn` is always called via a ref, so
//    a fresh closure each render does NOT thrash the interval);
//  - on cleanup, clears the interval AND flips the `isCancelled()` the callback receives, so an
//    in-flight async `fn` can bail before it touches state after unmount.

import { useEffect, useRef, type DependencyList } from "react";

interface PollOptions {
  /** Run `fn` once immediately on mount / deps-change. Default true. */
  immediate?: boolean;
}

export function usePoll(
  fn: (isCancelled: () => boolean) => void | Promise<void>,
  ms: number,
  deps: DependencyList = [],
  opts: PollOptions = {},
): void {
  const { immediate = true } = opts;
  const fnRef = useRef(fn);
  useEffect(() => { fnRef.current = fn; });

  useEffect(() => {
    let cancelled = false;
    let running = false; // #3666: don't RE-ENTER while the previous async run is still pending.
    const isCancelled = () => cancelled;
    const tick = () => {
      // A run that outlasts `ms` must NOT stack: overlapping runs pile invokes into the backend queue
      // (the planner's ~13 `bsc plan` reads per 2s tick jammed every pty_write, #3666). Skip a tick
      // while the previous async run is in flight; a sync (void-returning) `fn` is unaffected.
      if (running) return;
      const r = fnRef.current(isCancelled);
      if (r && typeof (r as Promise<unknown>).then === "function") {
        running = true;
        void (r as Promise<unknown>).finally(() => { running = false; });
      }
    };
    if (immediate) tick();
    const id = setInterval(tick, ms);
    return () => { cancelled = true; clearInterval(id); };
    // `fn` is intentionally read via ref, not a dep; callers declare their own deps.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ms, immediate, ...deps]);
}

runtime.shared/hooks/useRailSections.ts:
// useRailSections (#2797) — the open/closed state for a left rail's collapsible sections, keyed by a
// stable section id. Sections default OPEN (the common case); toggling a key flips it. Shared so every
// graph rail (Algorithms, Teams, …) manages its sections identically. Pairs with `RailSection`.
import { useState } from "react";

export interface RailSections {
  /** Whether the section `key` is expanded (defaults to `defaultOpen`). */
  isOpen: (key: string) => boolean;
  /** Flip the section `key`. */
  toggle: (key: string) => void;
}

/** Collapsible-section open state for a rail. `defaultOpen` (default true) is the state before any
 *  toggle. See {@link RailSections}. */
export function useRailSections(defaultOpen = true): RailSections {
  const [open, setOpen] = useState<Record<string, boolean>>({});
  return {
    isOpen: (key) => open[key] ?? defaultOpen,
    toggle: (key) => setOpen((o) => ({ ...o, [key]: !(o[key] ?? defaultOpen) })),
  };
}

runtime.shared/lib/a11y/speech.ts:
// App-owned text-to-speech (#3804, a11y epic #2725 Tier 1) — a thin wrapper over the WebView's
// SpeechSynthesis API (`window.speechSynthesis`). This is DISTINCT from #3770's ARIA live region
// (`announcer.ts`): that pushes text to a live region the user's OWN screen reader speaks; this is the
// app speaking with its own voice, for the streaming-fleet surfaces a screen reader handles badly.
// Every entry guards for absence so it's a safe no-op in a stripped WebView or the jsdom test env.

export interface SpeakOpts {
  /** Speech rate, 0.1–10 (default 1). */
  rate?: number;
  /** A `SpeechSynthesisVoice.voiceURI` to select; falls back to the platform default when absent/unknown. */
  voiceURI?: string;
}

/** How much of the fleet stream is spoken: `terse` = only the needs-you / went-wrong events; `verbose`
 *  = those plus the progress events (a PR landed, a gate is ready). */
export type TtsVerbosity = "terse" | "verbose";

/** The live `SpeechSynthesis` object, or `null` when the environment has none (SSR / jsdom / a stripped
 *  WebView). Coalesces a present-but-undefined value to `null` so `isSpeechSupported` reads correctly. */
function synth(): SpeechSynthesis | null {
  if (typeof window === "undefined") return null;
  return window.speechSynthesis ?? null;
}

/** Whether the WebView exposes SpeechSynthesis (false in tests / a stripped WebView). */
export function isSpeechSupported(): boolean {
  return synth() !== null && typeof SpeechSynthesisUtterance !== "undefined";
}

/** The voices the platform offers (empty when unsupported or the list hasn't loaded yet). */
export function listVoices(): SpeechSynthesisVoice[] {
  return synth()?.getVoices() ?? [];
}

/** Speak `text` at the given rate/voice. No-op when unsupported or the text is blank. Utterances QUEUE
 *  (coord events shouldn't cut each other off); call [`cancelSpeech`] to flush. */
export function speak(text: string, opts: SpeakOpts = {}): void {
  const s = synth();
  if (!s || !isSpeechSupported() || !text.trim()) return;
  const u = new SpeechSynthesisUtterance(text);
  if (opts.rate != null) u.rate = opts.rate;
  if (opts.voiceURI) {
    const v = s.getVoices().find((voice) => voice.voiceURI === opts.voiceURI);
    if (v) u.voice = v;
  }
  s.speak(u);
}

/** Stop + flush any queued or in-flight speech. */
export function cancelSpeech(): void {
  synth()?.cancel();
}

runtime.shared/lib/algorithms/groupTotals.ts:
/**
 * Group rows by a key and total a set of numeric fields — per group AND overall — in ONE pass.
 *
 * The back half of every "spend by X" / "usage by Y" rollup: you have a flat list of rows, each with
 * several numbers, and you want both the grand totals and the same totals broken down by some
 * secondary key. Written by hand it is three separate reductions plus a `Map` accumulator, and the
 * usual bug is the group subtotals and the grand total drifting apart because they were summed
 * independently — here they come from the same traversal, so they cannot disagree.
 *
 * The fields to sum are DATA: a record of named numeric accessors. Adding a tracked metric is adding
 * one entry, not editing three reducers. Every field is totalled at both levels; a caller wanting only
 * some grouped just reads the ones it needs.
 *
 * Group order is FIRST-SEEN (insertion order of the backing Map), so the result is deterministic for a
 * given input and a caller that wants a different order sorts the returned groups itself — this does
 * not bake a sort in, because "by first appearance" is the one order that needs no opinion.
 *
 * Harvested from the Fleet page's cost panel (#3462/#3465), where it rolls per-worker token usage up
 * to fleet totals and a by-model breakdown.
 */

/** The totals for one field set — the same keys as the `fields` record, each a summed number. */
export type FieldTotals<F extends string> = Record<F, number>;

/** One group: its key, how many rows fell into it, and the per-field totals for those rows. */
export interface Group<K, F extends string> {
  key: K;
  count: number;
  totals: FieldTotals<F>;
}

/** The rollup: the grand totals over every row, and the per-group breakdown (first-seen order). */
export interface GroupTotals<K, F extends string> {
  totals: FieldTotals<F>;
  count: number;
  groups: Array<Group<K, F>>;
}

/**
 * Total `fields` over `rows`, grouped by `keyOf`.
 *
 * @param rows   the flat input.
 * @param keyOf  the grouping key for a row (the secondary axis — e.g. model name).
 * @param fields named numeric accessors; each is summed at both the group and grand-total level.
 */
export function groupTotals<T, K, F extends string>(
  rows: readonly T[],
  keyOf: (row: T) => K,
  fields: Record<F, (row: T) => number>,
): GroupTotals<K, F> {
  const names = Object.keys(fields) as F[];
  const zero = (): FieldTotals<F> => Object.fromEntries(names.map((n) => [n, 0])) as FieldTotals<F>;

  const grand = zero();
  const groups = new Map<K, Group<K, F>>();

  for (const row of rows) {
    const key = keyOf(row);
    let group = groups.get(key);
    if (!group) {
      group = { key, count: 0, totals: zero() };
      groups.set(key, group);
    }
    group.count += 1;
    for (const name of names) {
      const v = fields[name](row);
      group.totals[name] += v;
      grand[name] += v;
    }
  }

  return { totals: grand, count: rows.length, groups: [...groups.values()] };
}

runtime.shared/lib/algorithms/llmEnergy.ts:
/** Wh per 1k tokens by model tier — directional coefficients, not metered readings. */
const WH_PER_1K: Record<"large" | "medium" | "small" | "local", { in: number; out: number }> = {
  large: { in: 0.05, out: 0.9 },
  medium: { in: 0.03, out: 0.4 },
  small: { in: 0.01, out: 0.15 },
  local: { in: 0, out: 0 },
};

/** Classify a model name into an energy tier by name pattern; unknown hosted models fall to medium. */
function tier(model: string): keyof typeof WH_PER_1K {
  const m = model.toLowerCase();
  if (/local|ollama|llama|mistral|qwen|deepseek|phi/.test(m)) return "local";
  if (/opus|ultra|gpt-4(?!o)|gpt4(?!o)/.test(m)) return "large";
  if (/haiku|mini|flash|nano|small|lite/.test(m)) return "small";
  return "medium";
}

/** Estimated Wh for an input/output token split at the model's tier. Directional, not metered. */
export function estimateEnergyWh(model: string, inputTokens: number, outputTokens: number): number {
  const k = WH_PER_1K[tier(model)];
  return (inputTokens / 1000) * k.in + (outputTokens / 1000) * k.out;
}

runtime.shared/lib/algorithms/orderByRank.ts:
/**
 * Sort items by a DECLARED priority ranking of a category — an order that is deliberately NOT the
 * category's natural or alphabetical one.
 *
 * The everyday case is an "attention queue": items fall into a few states and the useful order is by
 * urgency, which no property of the state gives you. Written by hand it becomes a bare comparator with
 * the ranking buried in a chain of ternaries (`s === "blocked" ? 0 : s === "running" ? 1 : …`) — the
 * priority is real domain knowledge but exists only as magic numbers inside a sort, where it cannot be
 * read as a list, reused, or reordered without recounting.
 *
 * Here the ranking is DATA: an array, first = highest priority. That array is the decision; the sort
 * is mechanical. A category not in the ranking sorts AFTER every ranked one (rather than silently
 * becoming rank 0 and jumping the queue) — an unranked value is "no stated priority", not "top
 * priority". The sort is STABLE, so items of equal rank keep their input order.
 *
 * Harvested from the Fleet page's merge queue (#3462/#3465).
 */

/**
 * A stable copy of `items` ordered by the priority of each item's category.
 *
 * `ranking[0]` is highest priority. An item whose category is not in `ranking` sorts after every
 * ranked item, in input order among its unranked peers.
 */
export function orderByRank<T, R>(
  items: readonly T[],
  categoryOf: (item: T) => R,
  ranking: readonly R[],
): T[] {
  const rankOf = new Map<R, number>(ranking.map((r, i) => [r, i]));
  // Unranked → after everything ranked. `ranking.length` sits past the last real rank.
  const rank = (item: T) => rankOf.get(categoryOf(item)) ?? ranking.length;
  // Decorate-sort-undecorate keeps it stable AND calls `categoryOf` once per item rather than O(n log n)
  // times — the naive `.sort((a,b) => rank(a) - rank(b))` re-derives the category on every comparison.
  return items
    .map((item, i) => ({ item, i, r: rank(item) }))
    .sort((a, b) => a.r - b.r || a.i - b.i)
    .map((d) => d.item);
}

/**
 * Resolve ONE state from N independent signal sources, by a declared precedence order.
 *
 * The everyday shape of "which status is this thing in?" when several sources can each claim it at
 * once and the answer must be single-valued and stable. The ordering is DATA, not control flow: the
 * common alternative is a chain of `if` returns, where the precedence exists only in the sequence of
 * the statements and cannot be read, tested, or changed without editing the branch order.
 *
 * The first source (in order) that claims the subject wins. Sources are consulted lazily, so an
 * expensive predicate placed low in the order is not paid for when something above it already matched.
 *
 * Harvested from the Fleet page's per-worker status (#3462/#3465), where coordination signals
 * (asking / waiting / blocked) outrank the raw run/idle sample, which in turn outranks a parked
 * maintenance worker — an order chosen so a worker that needs a human is never hidden behind a
 * mechanical "running".
 */

/** One candidate state and the test that claims it. `when` is only called until one matches. */
export interface PrecedenceRule<TSubject, TState> {
  /** The state this rule resolves to when it claims the subject. */
  state: TState;
  /** Does this source claim the subject? */
  when: (subject: TSubject) => boolean;
}

/**
 * The first rule (in order) whose `when` claims `subject`, else `fallback`.
 *
 * Total by construction — a `fallback` is required rather than optional, so there is no "resolved to
 * nothing" case for a caller to forget. That matters here: the states this resolves are rendered, and
 * an undefined status is a blank badge rather than a visible problem.
 */
export function resolveByPrecedence<TSubject, TState>(
  subject: TSubject,
  rules: ReadonlyArray<PrecedenceRule<TSubject, TState>>,
  fallback: TState,
): TState {
  for (const rule of rules) {
    if (rule.when(subject)) return rule.state;
  }
  return fallback;
}

/**
 * The rules that claimed `subject`, in precedence order — every match, not just the winner.
 *
 * The winner alone answers "what is it?"; this answers "what else was true?", which is what an
 * explanation needs. A worker resolving to `running` while also matching `maintenance` is a different
 * situation from one that matches `running` only, and a UI that can say so is more use than one that
 * silently discards the runners-up.
 */
export function matchingPrecedence<TSubject, TState>(
  subject: TSubject,
  rules: ReadonlyArray<PrecedenceRule<TSubject, TState>>,
): TState[] {
  return rules.filter((r) => r.when(subject)).map((r) => r.state);
}

runtime.shared/lib/algorithms/streamMerge.ts:
/**
 * Merge K differently-shaped event streams into ONE recent-first feed, with a distinguished class
 * pinned ABOVE the time sort, plus a count per kind.
 *
 * The shape behind every "activity" / "what needs attention" panel that draws from several sources at
 * once (errors, warnings, denials, …). Three things it gets right that the hand-written version gets
 * wrong under maintenance:
 *
 * 1. **Heterogeneous in, homogeneous out.** Each stream has its OWN shape and its own projection to a
 *    common item; the merge never sees the source shapes. Adding a stream is adding a `(source,
 *    project)` pair, not editing a growing sort.
 * 2. **A pinned class outranks recency.** Some items are LIVE ("this is happening now") and must sit
 *    at the top regardless of timestamp — a currently-stalled worker above yesterday's resolved error.
 *    Modelled as a real flag (`pinned`), not the sentinel `sortKey: Infinity` the original used, which
 *    silently breaks the moment a second pinned item needs ordering among its peers.
 * 3. **Counts come from the merged feed, not recomputed.** One pass, so the badge can never disagree
 *    with the list it summarises.
 *
 * Sort is STABLE within a rank: pinned-vs-unpinned first, then `sortKey` descending, ties keeping
 * input order — so equal-timestamp items don't reshuffle between renders. Harvested from the Fleet
 * page's health panel (#3462/#3465).
 */

/** One normalized feed entry. `kind` is the caller's classification (counted); `pinned` lifts it above
 *  the time sort; `sortKey` orders the rest (a timestamp, descending = newest first). */
export interface FeedItem<TKind extends string> {
  kind: TKind;
  pinned: boolean;
  sortKey: number;
}

/** One input stream: its raw items plus how to project each to a {@link FeedItem}. Generic over the
 *  source shape AND the extra payload `P` the projection carries through (label, detail, …). */
export interface FeedStream<TKind extends string, P> {
  items: readonly unknown[];
  project: (raw: unknown) => (FeedItem<TKind> & P) | null;
}

/** Build one typed stream — a small helper so the source type is inferred rather than cast at the
 *  call site (each stream keeps its own element type until `project` normalizes it). */
export function feedStream<TRaw, TKind extends string, P>(
  items: readonly TRaw[],
  project: (raw: TRaw) => (FeedItem<TKind> & P) | null,
): FeedStream<TKind, P> {
  return { items, project: (raw) => project(raw as TRaw) };
}

/** The merged result: the ordered feed and a count per kind (every kind in `kinds` present, zeros
 *  included, so a caller can render a fixed set of badges without guarding for missing keys). */
export interface MergedFeed<TKind extends string, P> {
  items: Array<FeedItem<TKind> & P>;
  counts: Record<TKind, number>;
  total: number;
  hasItems: boolean;
}

/**
 * Merge the streams into one ordered feed with per-kind counts.
 *
 * `kinds` is the closed set of classifications, passed IN so `counts` has a zero for every one — the
 * feed alone can only count kinds that occurred, and a badge row that appears and disappears with the
 * data is worse than one that reads `0`.
 *
 * A stream's `project` returning null drops that raw item (a "done" verdict is not an error), so
 * filtering is part of the projection rather than a separate pass the caller has to remember.
 */
export function mergeFeeds<TKind extends string, P>(
  streams: ReadonlyArray<FeedStream<TKind, P>>,
  kinds: readonly TKind[],
): MergedFeed<TKind, P> {
  const items: Array<FeedItem<TKind> & P> = [];
  for (const stream of streams) {
    for (const raw of stream.items) {
      const item = stream.project(raw);
      if (item) items.push(item);
    }
  }
  // Stable: pinned first, then newest first, ties keeping insertion order (Array.sort is stable).
  items.sort((a, b) => (a.pinned === b.pinned ? b.sortKey - a.sortKey : a.pinned ? -1 : 1));

  const counts = Object.fromEntries(kinds.map((k) => [k, 0])) as Record<TKind, number>;
  for (const it of items) counts[it.kind] += 1;

  return { items, counts, total: items.length, hasItems: items.length > 0 };
}

runtime.shared/lib/algorithms/windowedTally.ts:
/**
 * Bucket K timestamp streams into per-day counts over a rolling N-day window, aligned to one label
 * axis — the shape every "activity over the last N days" chart needs.
 *
 * Two properties are the whole point, and both are easy to get wrong by hand:
 *
 * 1. **Empty days are present.** The window is built first and every stream is tallied INTO it, so a
 *    day with no events is a `0`, not a missing entry. Deriving labels from the data instead (the
 *    obvious shortcut) silently compresses quiet days out of the axis, which makes a gap look like a
 *    dip and misstates the trend.
 * 2. **The series are aligned.** Every returned series has exactly `days` entries in the same order as
 *    `labels`, so index `i` means the same day in all of them. A chart layering two series cannot check
 *    this and will happily plot them against each other misaligned.
 *
 * Days are UTC — a rolling window whose bucket boundaries move with the viewer's timezone would make
 * the same data tell two stories. Timestamps are ISO-8601; anything unparseable or outside the window
 * is dropped rather than clamped, because a bad timestamp landing on an edge day is a fabricated event.
 *
 * Harvested from the Fleet page's throughput panel (#3462/#3465).
 */

/** The day axis: display labels and the `YYYY-MM-DD` keys they bucket by, oldest → newest. */
export interface DayWindow {
  labels: string[];
  keys: string[];
}

/** The aligned result: one label axis and one equal-length numeric series per input stream. */
export interface WindowedTally<TName extends string> {
  labels: string[];
  series: Record<TName, number[]>;
}

/**
 * The last `days` UTC days ending at `now` (inclusive), oldest first.
 *
 * `days <= 0` yields an empty window rather than throwing — a caller asking for no window gets no
 * window, and every tally over it is correctly empty.
 */
export function dayWindow(days: number, now: Date): DayWindow {
  const labels: string[] = [];
  const keys: string[] = [];
  for (let i = Math.max(0, Math.floor(days)) - 1; i >= 0; i--) {
    const d = new Date(now.getTime() - i * 86_400_000);
    labels.push(`${d.getUTCMonth() + 1}/${d.getUTCDate()}`);
    keys.push(d.toISOString().slice(0, 10));
  }
  return { labels, keys };
}

/**
 * Count the timestamps falling on each day of `win`, in window order.
 *
 * Null/undefined/unparseable entries are skipped — these streams come from APIs where "not merged
 * yet" is a null timestamp, so filtering at the call site would be required of every caller.
 */
export function tallyByDay(win: DayWindow, timestamps: ReadonlyArray<string | null | undefined>): number[] {
  const index = new Map(win.keys.map((k, i) => [k, i]));
  const out = new Array<number>(win.keys.length).fill(0);
  for (const ts of timestamps) {
    if (!ts) continue;
    const at = index.get(ts.slice(0, 10));
    if (at !== undefined) out[at] += 1;
  }
  return out;
}

/**
 * Tally several named streams over ONE window, so the result is aligned by construction.
 *
 * Preferred over calling {@link tallyByDay} per stream: sharing the window is what guarantees the
 * series line up, and doing it here removes the caller's opportunity to build two windows a
 * millisecond apart and land the boundary event in different buckets.
 */
export function windowedTally<TName extends string>(
  streams: Record<TName, ReadonlyArray<string | null | undefined>>,
  days: number,
  now: Date,
): WindowedTally<TName> {
  const win = dayWindow(days, now);
  const series = {} as Record<TName, number[]>;
  for (const name of Object.keys(streams) as TName[]) {
    series[name] = tallyByDay(win, streams[name]);
  }
  return { labels: win.labels, series };
}

runtime.shared/lib/core/achievements.ts:
// Achievement registry (#365 Easter egg). Definitions are DATA: one JSON file per achievement under
// `src-tauri/data/achievements/`, loaded via the `@data` glob (mirrors `data/roles/*.json`, #1715), so
// adding an achievement is a single JSON file (+ its icon asset) — no code change. The UNLOCKED state
// lives in the persisted store (`achievements: id -> unlockedAt`), so each fires exactly once, ever.

import type { AppStore } from "@/store/types";

/** A declarative unlock condition authored in JSON: compare a numeric store field to a threshold. */
export interface TriggerSpec {
  /** A numeric field on the app store the condition reads (e.g. "liveAgents"). */
  field: string;
  /** Comparison operator. */
  op: "gt" | "gte" | "lt" | "lte" | "eq";
  value: number;
}

/** The raw JSON shape authored under `data/achievements/*.json`. */
interface RawAchievement {
  id: string;
  title: string;
  description: string;
  /** OPTIONAL emblem asset filename under `src/assets/`. Absent ⇒ the shared trophy glyph (#3939):
   *  the toast renders from tokens now, so an achievement no longer needs a bespoke image. */
  icon?: string;
  /** Optional unlock-toast sound filename under `src/assets/` (defaults to the shared sound). */
  sound?: string;
  /** Optional live unlock condition (omit for an achievement unlocked imperatively elsewhere). */
  trigger?: TriggerSpec;
}

/** The resolved achievement the UI consumes (asset filenames → URLs, trigger spec → selector). */
export interface AchievementDef {
  /** Stable id (the store key). */
  id: string;
  title: string;
  description: string;
  /** Resolved emblem URL, or "" when the achievement ships no image (the common case, #3939). */
  icon: string;
  /** Resolved unlock-toast sound URL (undefined ⇒ the shared default). */
  sound?: string;
  /** Live unlock condition as a pure store selector (undefined ⇒ no live toast). */
  trigger?: (s: AppStore) => boolean;
}

// One JSON file per achievement, bundled at build time (mirrors data/roles, #1715).
const achievementModules = import.meta.glob<{ default: RawAchievement }>(
  "@data/achievements/*.json",
  { eager: true },
);
// Every image/audio asset as its URL, so a JSON `icon`/`sound` filename resolves without a per-asset
// import (the default export of an asset module is its URL — same as `import x from "…png"`). A
// RELATIVE glob (not the `@` alias) so it resolves identically under Vite and Vitest.
const assetUrls = import.meta.glob<string>(
  "../../../assets/*.{png,jpg,jpeg,svg,webp,mp3,wav,ogg}",
  { eager: true, import: "default" },
);

/** Resolve an asset filename (e.g. "x.png") to its built URL, or "" when absent. Matches on the
 *  basename so it's robust to `/` vs `\` in glob keys across platforms. */
function assetUrl(filename: string | undefined): string {
  if (!filename) return "";
  const hit = Object.entries(assetUrls).find(([path]) => path.split(/[\\/]/).pop() === filename);
  return hit?.[1] ?? "";
}

/** Compile a declarative trigger into a pure store selector. Fail-safe: a missing/non-numeric field
 *  or unknown op never fires, so a malformed JSON can't spuriously unlock an achievement. */
export function compileTrigger(t: TriggerSpec | undefined): ((s: AppStore) => boolean) | undefined {
  if (!t) return undefined;
  return (s) => {
    const v = (s as unknown as Record<string, unknown>)[t.field];
    if (typeof v !== "number") return false;
    switch (t.op) {
      case "gt":  return v > t.value;
      case "gte": return v >= t.value;
      case "lt":  return v < t.value;
      case "lte": return v <= t.value;
      case "eq":  return v === t.value;
      default:    return false;
    }
  };
}

/** Resolve a raw JSON achievement into the runtime {@link AchievementDef}. */
function resolveAchievement(raw: RawAchievement): AchievementDef {
  return {
    id: raw.id,
    title: raw.title,
    description: raw.description,
    icon: assetUrl(raw.icon),
    sound: raw.sound ? assetUrl(raw.sound) : undefined,
    trigger: compileTrigger(raw.trigger),
  };
}

/** Every packaged achievement, sorted by filename for a stable order. */
export const ACHIEVEMENTS: AchievementDef[] = Object.entries(achievementModules)
  .sort(([a], [b]) => a.localeCompare(b))
  .map(([, m]) => resolveAchievement(m.default));

export function achievementById(id: string): AchievementDef | undefined {
  return ACHIEVEMENTS.find((a) => a.id === id);
}

/** Pure: whether `id` is unlocked in the given map. */
export function isUnlocked(unlocked: Record<string, number>, id: string): boolean {
  return Object.prototype.hasOwnProperty.call(unlocked, id);
}

/** Pure: decide the next unlocked-map for an unlock attempt. Returns `null` when `id`
 *  is already unlocked (idempotent — caller should NOT re-fire the toast), else the
 *  new map with `id` stamped at `now`. Keeps the once-ever guarantee testable. */
export function unlock(
  unlocked: Record<string, number>,
  id: string,
  now: number,
): Record<string, number> | null {
  if (isUnlocked(unlocked, id)) return null;
  return { ...unlocked, [id]: now };
}

runtime.shared/lib/core/arrayMove.ts:
// arrayMove -- pure, feature/app-agnostic array reordering helper.
//
// Lives in shared/ so both the console tab-reorder machinery (app/console) and
// the per-page tab model (shared/hooks/usePageTabs) can reuse it without shared/
// reaching into app/ (#1703).

/** Move the element at `from` to `to` in a new array (no mutation). Out-of-range
 *  or no-op moves return a shallow copy unchanged. */
export function moveInArray<T>(arr: T[], from: number, to: number): T[] {
  const out = arr.slice();
  if (from < 0 || from >= out.length || to < 0 || to >= out.length || from === to) return out;
  const [m] = out.splice(from, 1);
  out.splice(to, 0, m);
  return out;
}

runtime.shared/lib/core/bsc.ts:
// The `bsc` bridge (epic #2114) — the UI drives the SAME complete `bsc` interaction set the project
// planner + agents use from a live session's shell, over ONE shared store surface, via the generic
// `bsc` Tauri command (#2115). This replaces the parallel, hand-maintained per-verb `plan_*`/`data_*`
// Tauri commands: `bsc plan …` / `bsc data …` route to the bundled binary's subcommand, and the Rust
// bridge wires the project's stores ($BSC_PLAN_DB/$BSC_DATA_DB from `projectKey`) + the global skills
// store, so the UI reaches parity with the planner — the user can make the same actions.
//
// The `bsc` subcommands emit JSON to stdout (structured reads) and return the same serde shapes the
// old per-verb commands did (both wrap the same store crates), so a migrated read parses to the exact
// same type. Kept React-free so it's unit-testable, mirroring safeInvoke.ts.

import { invoke } from "@tauri-apps/api/core";
import { startInvokeTimer, bscLabel } from "@/shared/lib/core/invokeTiming";

/**
 * Run the bundled `bsc` CLI with `args` against `projectKey`'s stores; resolves to its raw stdout.
 * `projectKey` `null` (or empty) scopes to global-only subcommands (e.g. `bsc skill …`). Rejects when
 * the bundled binary can't be resolved or `bsc` exits non-zero (its stderr becomes the rejection).
 * The one choke point for every bsc-bridge call, so timing it here (#3626, labelled by subcommand)
 * covers `bscJson`/`bscRun`/`bscWrite` — a slow `bsc <sub> <verb>` gets a `[invoke]` app-log line.
 */
export async function bsc(projectKey: string | null, args: string[], stdin?: string): Promise<string> {
  const done = startInvokeTimer(bscLabel(args), "bsc");
  try {
    // Only include `stdin` when given, so read/positional calls keep their exact 2-key payload.
    return await invoke<string>("bsc", stdin === undefined ? { projectKey, args } : { projectKey, args, stdin });
  } finally {
    done();
  }
}

/**
 * Run `bsc` and JSON-parse its stdout as `T`; returns `fallback` when the output is empty (a void
 * verb) OR the invoke rejected (bridge/binary absent, or a project's plan.db not created yet). Mirrors
 * safeInvoke's degrade-gracefully contract, so a not-yet-existing store yields the fallback rather than
 * throwing — the same behavior the per-command `invoke(...).catch(() => fallback)` sites had.
 */
export async function bscJson<T>(projectKey: string | null, args: string[], fallback: T): Promise<T> {
  try {
    const out = (await bsc(projectKey, args)).trim();
    return out ? (JSON.parse(out) as T) : fallback;
  } catch {
    return fallback;
  }
}

/** Fire a `bsc` write/void verb and swallow any error (the bridge/store may be absent). */
export async function bscRun(projectKey: string | null, args: string[]): Promise<void> {
  try {
    await bsc(projectKey, args);
  } catch {
    /* bridge/store absent — ignore, matching the old per-command catch sites */
  }
}

/**
 * Drive a `bsc … set`/`add` verb whose JSON body is read from the child's **stdin** (#2123) — the
 * write analogue of `bscRun` for the CLI verbs that take a manifest/object on stdin (e.g.
 * `bsc plan deps set`, `bsc plan issue add`). Serializes `body` to JSON and feeds it in; swallows any
 * error like the other void helpers.
 */
export async function bscWrite(projectKey: string | null, args: string[], body: unknown): Promise<void> {
  try {
    await bsc(projectKey, args, JSON.stringify(body));
  } catch {
    /* bridge/store absent — ignore */
  }
}

runtime.shared/lib/core/claudeComplete.ts:
// One-shot LLM completion (#624; provider-agnostic since #1085) — a thin wrapper over
// the llm_complete Tauri command for features that need a single structured/short reply
// (the blueprint assistant's prose, the LLM grader, the cleanup verifier, the preview
// reviewer, …) rather than a streaming session. Routed through the active LlmConfig
// (provider + model + key), so it works on any provider. Returns the concatenated text
// blocks; throws on missing key / network (callers fall back as appropriate).

import { invoke } from "@tauri-apps/api/core";
import { type LlmConfig, hasLlmKey } from "./llmConfig";

interface LlmReply { content: { type: string; text?: string }[] }

/** Join the text blocks of an llm_complete reply into one trimmed string. */
function replyText(res: LlmReply): string {
  return (res.content ?? []).filter((b) => b.type === "text").map((b) => b.text ?? "").join("\n").trim();
}

export async function oneShotComplete(cfg: LlmConfig, system: string, user: string): Promise<string> {
  if (!hasLlmKey(cfg)) throw new Error(`No API key configured for ${cfg.provider}. Add it in Settings → Integrations.`);
  const res = await invoke<LlmReply>("llm_complete", {
    messages: [{ role: "user", content: user }], system, tools: [],
    apiKey: cfg.apiKey, provider: cfg.provider, model: cfg.model, baseUrl: cfg.baseUrl,
  });
  return replyText(res);
}

/** A captured image to send with a vision prompt — a `data:<mime>;base64,<…>` URL. */
export type ImageDataUrl = string;

/** Providers whose Messages API accepts image content blocks in the shape we build below. Claude Code
 *  only ever speaks Anthropic; OpenAI's chat API takes `image_url`. Gemini/local use different shapes we
 *  don't build here, so vision falls back to a clear error rather than silently dropping the image. */
export function providerSupportsVision(p: LlmConfig["provider"]): boolean {
  return p === "anthropic" || p === "openai";
}

/** Split a `data:<mime>;base64,<data>` URL into its media type + base64 payload. */
function splitDataUrl(url: ImageDataUrl): { mediaType: string; data: string } {
  const m = /^data:([^;]+);base64,(.*)$/s.exec(url);
  if (!m) throw new Error("vision image must be a base64 data URL");
  return { mediaType: m[1], data: m[2] };
}

/** Build the provider-specific `content` array (a text block + one block per image) for a vision message.
 *  Anthropic → `{type:"image",source:{type:"base64",…}}`; OpenAI → `{type:"image_url",image_url:{url}}`. */
function visionContent(provider: LlmConfig["provider"], text: string, images: ImageDataUrl[]): unknown[] {
  const blocks: unknown[] = [{ type: "text", text }];
  for (const url of images) {
    if (provider === "openai") {
      blocks.push({ type: "image_url", image_url: { url } });
    } else {
      const { mediaType, data } = splitDataUrl(url);
      blocks.push({ type: "image", source: { type: "base64", media_type: mediaType, data } });
    }
  }
  return blocks;
}

/**
 * One-shot MULTIMODAL completion — `text` plus one or more screenshots, for the preview reviewer (#2623)
 * and any future see-the-screen feature. Builds provider-appropriate image content blocks and sends them
 * through the same `llm_complete` path (which forwards `messages` verbatim to the provider's API).
 * @throws when no key is configured, or the active provider can't take images (see {@link providerSupportsVision}).
 */
export async function oneShotVision(
  cfg: LlmConfig,
  system: string,
  text: string,
  images: ImageDataUrl[],
): Promise<string> {
  if (!hasLlmKey(cfg)) throw new Error(`No API key configured for ${cfg.provider}. Add it in Settings → Integrations.`);
  if (!providerSupportsVision(cfg.provider)) {
    throw new Error(`Image review needs Claude or OpenAI — ${cfg.provider} can't read screenshots. Switch provider in Settings → Integrations.`);
  }
  const res = await invoke<LlmReply>("llm_complete", {
    messages: [{ role: "user", content: visionContent(cfg.provider, text, images) }], system, tools: [],
    apiKey: cfg.apiKey, provider: cfg.provider, model: cfg.model, baseUrl: cfg.baseUrl,
  });
  return replyText(res);
}

runtime.shared/lib/core/configOverrides.ts:
// #2047 — frontend runtime config loading (parity of the backend's P2). The app's config surfaces
// (blueprints / roles / skills / stage defs / taxonomies) are Vite-embedded via `import.meta.glob` +
// direct `@data/*` imports as the DEFAULT; this module overlays the runtime config dir
// (~/.base-studio-code/config/) over those defaults, primed at boot BEFORE the config modules build
// their consts — so editing a `@data` file under the config dir takes effect on next launch, no rebuild.
//
// Fail-safe by design: `overrides` stays empty in browser-dev (no Tauri) or if the fetch fails, so
// every overlay falls back to the embedded default and behavior is unchanged without a backend.

/** The primed config-dir files (`rel-path → contents`). Empty until `primeConfigOverrides` resolves. */
let overrides: Record<string, string> = {};
let primed = false;

/** Fetch the config-dir files once, before App (and the config modules) are imported. Must be awaited
 *  in the entry (`main.tsx`) ahead of the dynamic `App` import. No-ops safely on any failure. */
export async function primeConfigOverrides(): Promise<void> {
  if (primed) return;
  primed = true;
  try {
    // Dynamic import so the pure `overlay*` consumers (deployEnv/sessionRoles/…) don't statically
    // pull in the Tauri API — only this boot-time primer touches it.
    const { invoke } = await import("@tauri-apps/api/core");
    const files = await invoke<Record<string, string>>("get_config_files");
    if (files && typeof files === "object") overrides = files;
  } catch {
    // No Tauri backend (browser dev) or a read failure — the embedded defaults stand.
  }
}

/** Overlay the config-dir copies over an eager `import.meta.glob` surface, matched by filename stem.
 *  Returns `[stem, parsedValue][]` (embedded order, overrides replacing in place; new files appended) —
 *  the caller shapes it into a Record or a values list. `dir` is the config-dir subdir (e.g. "stages"). */
export function overlayGlob<T>(dir: string, embedded: Record<string, { default: T }>): [string, T][] {
  const out = new Map<string, T>(); // stem → value
  for (const [path, mod] of Object.entries(embedded)) out.set(stem(path), mod.default);
  for (const [rel, content] of Object.entries(overrides)) {
    if (dirOf(rel) !== dir) continue;
    const parsed = tryParse<T>(content);
    if (parsed !== undefined) out.set(stem(rel), parsed);
  }
  return [...out.entries()];
}

/** Overlay a single direct-import `@data` file: the config-dir copy parsed, else the embedded default.
 *  `rel` is the config-dir-relative path (e.g. "planner/blueprint-meta.json"). */
export function overlayFile<T>(rel: string, embedded: T): T {
  const content = overrides[rel];
  if (content === undefined) return embedded;
  return tryParse<T>(content) ?? embedded;
}

/** Overlay a single RAW (non-JSON) `@data` file — e.g. a markdown prompt/protocol imported with
 *  `?raw`: the config-dir copy's text verbatim if present, else the embedded default. The raw analogue
 *  of {@link overlayFile} (no parse), giving markdown surfaces the same edit-without-rebuild parity the
 *  Rust `load_str` gives them backend-side. */
export function overlayRaw(rel: string, embedded: string): string {
  const content = overrides[rel];
  return content === undefined ? embedded : content;
}

/** Test-only: reset the primed state so a spec can re-prime with a fresh mock. */
export function resetConfigOverridesForTest(): void {
  overrides = {};
  primed = false;
}

function basename(p: string): string { return p.slice(p.lastIndexOf("/") + 1); }
function stem(p: string): string { const b = basename(p); return b.endsWith(".json") ? b.slice(0, -5) : b; }
function dirOf(rel: string): string { const i = rel.lastIndexOf("/"); return i < 0 ? "" : rel.slice(0, i); }
function tryParse<T>(s: string): T | undefined { try { return JSON.parse(s) as T; } catch { return undefined; } }

runtime.shared/lib/core/detachSection.ts:
// detachSection -- open a page's section (e.g. github → repos, the projects
// board) in its own OS window (section tear-off, #430).
//
// Lives in shared/ (#1703) because it's a generic, feature/app-agnostic window
// helper: it depends only on the Tauri webview API + window.location, not on any
// app/ or feature/ module. Both the per-page tab model (shared/hooks/usePageTabs)
// and the projects summary (a feature) drive section tear-off through it.
//
// The detached window loads the same app with `?detach=<page>&section=<id>`;
// the shell reads that (via detachedSection) and renders just that section.

import { WebviewWindow } from "@tauri-apps/api/webviewWindow";

let seq = 0;

/** Open a page's section (e.g. github → repos) in its own window (tear-off).
 *  `onClose` fires when that window is destroyed (best-effort re-dock). */
export function openDetachedSection(page: string, section: string, title?: string, onClose?: () => void): void {
  seq += 1;
  const label = `tab-${page}-${section}-${seq}`.replace(/[^A-Za-z0-9/:_-]/g, "_");
  const u = new URL(window.location.href);
  u.hash = "";
  u.search = `?detach=${encodeURIComponent(page)}&section=${encodeURIComponent(section)}`;
  try {
    // `dragDropEnabled: false` is NOT optional (#3925). Tauri's WebView captures drag/drop for OS
    // file-drop by default and swallows `dragstart`/`dragover`/`drop` before the DOM sees them — the bug
    // #461 fixed for the main window via tauri.conf.json. A RUNTIME window does not inherit that config,
    // so without this the torn-off window's tab cannot be dragged at all, and dock-back can never fire.
    const w = new WebviewWindow(label, {
      url: u.href, title: title || section, width: 1100, height: 800,
      decorations: false, dragDropEnabled: false,
    });
    if (onClose) w.once("tauri://destroyed", () => onClose());
  } catch (e) {
    console.error("openDetachedSection failed:", e);
  }
}

runtime.shared/lib/core/diagnostics.ts:
// Interpretation + report caching for the host-environment diagnostics (#446/#447).
//
// The backend `preflight` probe (`src-tauri/src/lib.rs`) runs the prerequisite
// checks in the same login shell + env an agent's subshells use and returns one
// `PrereqStatus` per external dependency (Git Bash, `claude`, `git`, `gh`, plus
// `gh` auth), each with presence/version/path and an install hint. This module
// turns that raw list into a single user-facing verdict — overall severity, a
// headline, and a per-prerequisite explanation of what specifically breaks when
// it is missing (a missing Git Bash or `claude` gets its own message, not a
// generic failure) — and caches the last report so the Diagnostics view can
// render immediately on open. The console-shell selection + its persistence
// lives in `shellConfig.ts` (split out in #1711).
//
// Free of React/Tauri imports so it can be unit-tested and shared. Mirrors
// `githubReadiness.ts` (the GitHub-readiness probe interpreter).

/**
 * One prerequisite's detected state. Field names match the backend `PrereqStatus`
 * (`src-tauri/src/lib.rs`) so the probe result deserializes straight into this.
 */
export interface PrereqStatus {
  /** Display name: "Git Bash", "claude", "git", "gh", or "gh auth". */
  name: string;
  /** Whether the tool was located (and, for "gh auth", authenticated). */
  found: boolean;
  /** First line of `<tool> --version`, when found. */
  version: string | null;
  /** Resolved on-disk path, when found. */
  path: string | null;
  /** Actionable install/fix hint from the backend — empty when `found`. */
  hint: string;
}

/** How badly a missing prerequisite degrades the app. */
export type PrereqSeverity = "critical" | "warning";

/**
 * A prerequisite plus the interpreted consequence of its current state. `ok`
 * mirrors `found`; when not ok, `severity` says how bad it is and `consequence`
 * explains, in user terms, what stops working until it is fixed.
 */
export interface PrereqVerdict extends PrereqStatus {
  ok: boolean;
  /** Only meaningful when `!ok`. */
  severity: PrereqSeverity;
  /** What breaks while this is missing — empty when `ok`. */
  consequence: string;
}

/** The whole-host verdict the Diagnostics view renders. */
export interface DiagnosticsReport {
  prereqs: PrereqVerdict[];
  /** True only when every prerequisite is satisfied. */
  allOk: boolean;
  /** Worst severity among the missing prerequisites; null when `allOk`. */
  worst: PrereqSeverity | null;
  /** One-line summary — "All prerequisites satisfied." or a count of what's missing. */
  headline: string;
}

/**
 * What stops working when a given prerequisite is missing, and how severe that is.
 * Critical prerequisites block agents from running at all; warnings degrade a
 * specific capability (PR creation). Names not listed default to a critical,
 * generic consequence so a newly-probed tool is never silently treated as benign.
 */
function consequenceFor(name: string): { severity: PrereqSeverity; consequence: string } {
  switch (name) {
    case "Git Bash":
      return {
        severity: "critical",
        consequence:
          "Console sessions can't launch — Git Bash is the shell that runs agents on Windows. Install Git for Windows, then relaunch.",
      };
    case "claude":
      return {
        severity: "critical",
        consequence:
          "Agents can't run — the `claude` CLI is what every console session executes. Install it, then relaunch.",
      };
    case "git":
      return {
        severity: "critical",
        consequence:
          "Repository operations fail — agents can't clone, commit, or create worktrees without `git`.",
      };
    case "gh":
      return {
        severity: "warning",
        consequence:
          "Agents can't open pull requests — install the GitHub CLI (`gh`) to enable PR creation and review.",
      };
    case "gh auth":
      return {
        severity: "warning",
        consequence:
          "`gh` is installed but not authenticated — set `GH_TOKEN` or run `gh auth login` so agents can push and open PRs.",
      };
    default:
      return {
        severity: "critical",
        consequence: "This prerequisite is required for agents to run.",
      };
  }
}

/**
 * Pure: turn the backend probe's prerequisite list into the full host verdict.
 * Each entry gains an `ok`/`severity`/`consequence`; the report's `allOk`,
 * `worst`, and `headline` summarize the set. A single missing critical
 * prerequisite makes `worst` critical even if warnings also exist.
 */
export function interpretDiagnostics(prereqs: PrereqStatus[]): DiagnosticsReport {
  const verdicts: PrereqVerdict[] = prereqs.map((p) => {
    if (p.found) {
      return { ...p, ok: true, severity: "warning", consequence: "" };
    }
    const { severity, consequence } = consequenceFor(p.name);
    return { ...p, ok: false, severity, consequence };
  });

  const missing = verdicts.filter((v) => !v.ok);
  const allOk = missing.length === 0;
  const worst: PrereqSeverity | null = allOk
    ? null
    : missing.some((m) => m.severity === "critical")
      ? "critical"
      : "warning";

  let headline: string;
  if (allOk) {
    headline = "All prerequisites satisfied.";
  } else {
    const names = missing.map((m) => m.name).join(", ");
    const noun = missing.length === 1 ? "prerequisite" : "prerequisites";
    headline = `${missing.length} ${noun} need attention: ${names}.`;
  }

  return { prereqs: verdicts, allOk, worst, headline };
}

// ── Diagnostics report cache (#447) ─────────────────────────────────────────

const REPORT_KEY = "bsc.diagnostics.report.v1";

/** A persisted diagnostics report plus when it was taken (epoch ms). */
export interface StoredReport {
  report: DiagnosticsReport;
  takenAt: number;
}

/** Cache the latest report so the view can render instantly on open. Best-effort. */
export function saveReport(report: DiagnosticsReport, takenAt: number): void {
  try {
    globalThis.localStorage?.setItem(REPORT_KEY, JSON.stringify({ report, takenAt }));
  } catch {
    /* storage unavailable — the view re-probes on open anyway */
  }
}

/** Read the cached report, or null when absent/unparseable. */
export function loadReport(): StoredReport | null {
  try {
    const raw = globalThis.localStorage?.getItem(REPORT_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as StoredReport;
    if (!parsed || !parsed.report || !Array.isArray(parsed.report.prereqs)) return null;
    return parsed;
  } catch {
    return null;
  }
}

// ── PTY-session readiness bridge (#564) ─────────────────────────────────────
// Adapts the DiagnosticsReport produced by interpretDiagnostics() into the
// simpler blocking/warning interface the pane's SessionFailure/SessionReadinessBanner
// components need. The backend `preflight` command returns Vec<PrereqStatus>; call
// interpretDiagnostics() first, then sessionVerdictFromReport().

export type CheckSeverity = "critical" | "warning" | "ok";

export interface ReadinessCheck {
  /** Stable id for the check — used as a React key and for filtering. */
  id: string;
  severity: CheckSeverity;
  /** User-facing one-liner. Empty string when severity is "ok". */
  message: string;
  /** Official download/install URL extracted from the backend hint, when present. */
  installUrl?: string;
}

export interface SessionVerdict {
  /** All checks, including passing ones. */
  checks: ReadinessCheck[];
  /** Worst severity across all checks. */
  worstSeverity: CheckSeverity;
  /** True when any critical check failed — the session cannot run until resolved. */
  blocking: boolean;
  /** Checks that did not pass (severity !== "ok"). */
  failed: ReadinessCheck[];
}

function toReadinessCheck(v: PrereqVerdict): ReadinessCheck {
  if (v.ok) return { id: v.name, severity: "ok", message: "" };
  const urlMatch = v.hint.match(/https?:\/\/\S+/);
  return {
    id: v.name,
    severity: v.severity,
    message: v.consequence,
    installUrl: urlMatch?.[0],
  };
}

/**
 * Convert a `DiagnosticsReport` into the pane-level `SessionVerdict` used by
 * `SessionFailure` and `SessionReadinessBanner`. Call after `interpretDiagnostics`.
 */
export function sessionVerdictFromReport(report: DiagnosticsReport): SessionVerdict {
  const checks = report.prereqs.map(toReadinessCheck);
  const failed = checks.filter((c) => c.severity !== "ok");
  const blocking = report.worst === "critical";
  const worstSeverity: CheckSeverity = report.worst ?? "ok";
  return { checks, worstSeverity, blocking, failed };
}

runtime.shared/lib/core/folderTree.ts:
// The rail FOLDER TREE (#4128) — the ONE nested-folder model both library rails render.
//
// Components (`RailTree`) and Algorithms (`AlgorithmsRail`) each browse a library organized like a
// completed project's folders: a `/`-delimited path per record (derived from its source by the shared
// `bsc_util::folder_from_src`, so a component and an algorithm harvested from the same tree land in the
// same place) split into nested folders. Until #4128 each feature owned its own builder — components'
// `groupComponentsByFolder` (#3048/#3582) and algorithms' `folderTree` (#4107) — which had silently
// diverged on the two decisions that are actually visible in the rail:
//
//   * an item with NO folder: components bucketed it into a trailing "ungrouped" folder, algorithms
//     spilled it flat beside the tree;
//   * folder order: components kept first-appearance order (of already-sorted rows), algorithms re-sorted
//     alphabetically and ignored the caller's ordering.
//
// Two implementations of "the same structure" cannot stay the same by agreement, so this is the single
// one. Generic over the record type — it only ever asks for a record's folder path — so neither feature's
// model leaks into `shared/`.
//
// Pure and React-free: the tree shape is testable without a render, and both rails' tests exercise the
// same code the app does.

/** Header label of the trailing bucket holding the records that carry no folder. */
export const UNGROUPED_LABEL = "ungrouped";

/** The stable expand-state key of the trailing {@link UNGROUPED_LABEL} folder. A sentinel, so it can
 *  never collide with a real single-segment folder path (a source folder is never literally named this). */
export const UNGROUPED_KEY = "__ungrouped__";

/**
 * One folder of a library's tree — a folder that mirrors a segment of its records' folder paths
 * (`shared` › `ui` › `controls`).
 *
 * A folder holds BOTH sub-`folders` (deeper path segments) AND direct `items` (records whose path ends
 * exactly here — a component grouped `shared/ui` sits directly under the `ui` folder alongside its
 * `controls`/`data` subfolders).
 */
export interface FolderNode<T> {
  /** Stable expand-state key — the folder's FULL path (`shared/ui/controls`), or {@link UNGROUPED_KEY}
   *  for the trailing bucket. Unique within one tree. */
  key: string;
  /** Header label — the LAST path segment (`controls`), or {@link UNGROUPED_LABEL} for the bucket. */
  label: string;
  /** Whether this is the forced-last bucket of records carrying no folder. */
  ungrouped: boolean;
  /** Child folders (deeper path segments), in first-appearance order. */
  folders: FolderNode<T>[];
  /** Records whose folder path ENDS at this folder (its direct members). */
  items: T[];
}

/** Total records under a folder, transitively (its own + every descendant's) — the header count. A
 *  collapsed folder still has to say how much is inside it, or a deep tree gives no sense of where the
 *  work lives. */
export function folderItemCount<T>(f: FolderNode<T>): number {
  return f.items.length + f.folders.reduce((n, sub) => n + folderItemCount(sub), 0);
}

/**
 * Partition records into a nested FOLDER TREE by their folder path — split each path on `/` and nest
 * (`shared/ui/controls` → `shared` › `ui` › `controls`), so a library browses like a project's folders.
 * A record sits at the LEAF of its path.
 *
 * Order is the CALLER's: folders appear in the first-appearance order of the passed (already-sorted)
 * records, and a folder's own records keep their relative order — so a rail that sorts pages first, or
 * primitives before algorithms, keeps that reading inside every folder. The "ungrouped" bucket is forced
 * LAST at the root.
 *
 * Returns `null` when NO record carries a folder, so a caller renders its flat list exactly as it would
 * without folders at all — a library that has not been foldered yet must not collapse under one blank
 * node. A depth-1 path (`forms`) yields a single root folder with no subfolders: the flat case is just
 * the shallow case of this tree.
 *
 * @param items    the records to organize, in the order they should read
 * @param folderOf a record's `/`-delimited folder path; blank/absent ⇒ the ungrouped bucket
 */
export function buildFolderTree<T>(
  items: readonly T[],
  folderOf: (item: T) => string | undefined,
): FolderNode<T>[] | null {
  if (!items.some((it) => (folderOf(it) ?? "").trim())) return null;

  // Mutable builder: `children` is a Map so it preserves first-appearance insertion order.
  interface Build {
    key: string;
    label: string;
    ungrouped: boolean;
    children: Map<string, Build>;
    items: T[];
  }
  const mk = (key: string, label: string, ungrouped = false): Build => ({
    key,
    label,
    ungrouped,
    children: new Map(),
    items: [],
  });

  const roots = new Map<string, Build>();
  let ungrouped: Build | null = null;

  for (const it of items) {
    const path = (folderOf(it) ?? "").trim();
    if (!path) {
      ungrouped ??= mk(UNGROUPED_KEY, UNGROUPED_LABEL, true);
      ungrouped.items.push(it);
      continue;
    }
    const segs = path.split("/").map((s) => s.trim()).filter(Boolean);
    // A path of only separators/blanks (`"/"`, `"  /  "`) has no usable segment — treat it as unfoldered
    // rather than manufacturing a `""` node the rail would render as a nameless folder.
    if (segs.length === 0) {
      ungrouped ??= mk(UNGROUPED_KEY, UNGROUPED_LABEL, true);
      ungrouped.items.push(it);
      continue;
    }
    let level = roots;
    let node: Build | null = null;
    let acc = "";
    for (const seg of segs) {
      acc = acc ? `${acc}/${seg}` : seg;
      let child = level.get(seg);
      if (!child) {
        child = mk(acc, seg);
        level.set(seg, child);
      }
      node = child;
      level = child.children;
    }
    // `node` is non-null: a non-empty `segs` yields at least one iteration.
    node!.items.push(it);
  }

  const freeze = (b: Build): FolderNode<T> => ({
    key: b.key,
    label: b.label,
    ungrouped: b.ungrouped,
    folders: [...b.children.values()].map(freeze),
    items: b.items,
  });

  const out = [...roots.values()].map(freeze);
  if (ungrouped) out.push(freeze(ungrouped)); // forced last
  return out;
}

