// Shared presentation helpers (#1471) — feature-agnostic, pure. Used by the GitHub and
// planner summaries. Extracted to remove byte-identical copies in ProjectsSummary +
// GitHubSummary.

/**
 * A coarse "time since" label from an ISO timestamp: `5s ago` / `3m ago` / `2h ago` /
 * `4d ago` / `2mo ago`. Returns "" for an empty, non-finite, or future timestamp.
 */
export function timeAgo(iso: string): string {
  return sinceLabel(iso, " ago");
}

/** Compact variant of {@link timeAgo} without the trailing " ago": `5s` / `4d` / `2mo`. */
export function timeAgoShort(iso: string): string {
  return sinceLabel(iso, "");
}

function sinceLabel(iso: string, suffix: string): string {
  if (!iso) return "";
  const s = Math.floor((Date.now() - new Date(iso).getTime()) / 1000);
  if (!isFinite(s) || s < 0) return "";
  if (s < 60) return `${s}s${suffix}`;
  const m = Math.floor(s / 60); if (m < 60) return `${m}m${suffix}`;
  const h = Math.floor(m / 60); if (h < 24) return `${h}h${suffix}`;
  const d = Math.floor(h / 24); if (d < 30) return `${d}d${suffix}`;
  return `${Math.floor(d / 30)}mo${suffix}`;
}

/** A coarse "time since" label from epoch millis; "—" when non-positive. */
export function timeAgoMs(ms: number): string {
  return ms > 0 ? timeAgo(new Date(ms).toISOString()) : "—";
}

/**
 * A stable 32-bit unsigned hash of a string (`h = h*31 + charCode`, truncated to
 * uint32 each step). Deterministic, so the same string always hashes the same — the
 * shared core behind the continuous-hue color helpers ({@link loginColor} + the fleet
 * board's profile color). Callers map the hash to their own space (e.g. `% 360` for a hue).
 *
 * Note: `hueFor` (per-step `% 360`) and the discrete `avatarColor` (per-step `& 0xffff`)
 * use *different* reductions and are intentionally NOT built on this — they'd produce
 * different colors.
 */
export function hashString(s: string): number {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return h;
}

/** A stable oklch color hashed from a login, so the same user always renders the same hue. */
export function loginColor(login: string): string {
  return `oklch(0.68 0.12 ${hashString(login) % 360})`;
}

/** A deterministic hue (0–359) hashed from a string — a tile/category accent. */
export function hueFor(s: string): number {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) % 360;
  return h;
}

/** Human-readable byte size: `0 B` / `1.5 KB` / `2.3 GB` / `1.1 TB`. */
export function fmtBytes(n: number): string {
  if (n <= 0) return "0 B";
  const u = ["B", "KB", "MB", "GB", "TB"];
  const i = Math.min(u.length - 1, Math.floor(Math.log(n) / Math.log(1024)));
  return `${(n / Math.pow(1024, i)).toFixed(i === 0 ? 0 : 1)} ${u[i]}`;
}

/**
 * Truncate `s` with a `…` when it exceeds `max` characters (#2421 — the one home for the
 * five hand-rolled ellipsis chains).
 *
 * `keep` is how many characters survive before the ellipsis and defaults to `max` — the
 * "hard cap" shape (`s.slice(0, max) + "…"` only when longer, e.g. an issue body preview).
 * Pass a smaller `keep` for the "display budget" shape the label sites use, where the
 * truncated form must fit the same budget as the untruncated one (e.g. `truncate(s, 20, 18)`).
 */
export function truncate(s: string, max: number, keep = max): string {
  return s.length > max ? `${s.slice(0, keep)}…` : s;
}

/**
 * Kebab-case slug: lowercase, every run of non-alphanumerics collapsed to a single `-`,
 * edge dashes stripped, optionally capped at `max` characters (#2421 — the one home for the
 * planner/source/DesignsWorkbench copies). Returns `""` for input with no alphanumerics — callers
 * that need a fallback apply their own (`slugify(x, 40) || "source"`).
 *
 * NOT {@link sanitizeProjectKey} (../core/projectPaths.ts): that mirrors the Rust backend
 * byte-for-byte (keeps case, `_` replacement, cap 80) and must not change; this is the
 * display/id kebab-case convention.
 *
 * Note: the cap is applied AFTER edge-stripping (matching every former copy), so a capped
 * slug can still end in a `-` when the cut lands on a word boundary.
 */
export function slugify(s: string, max?: number): string {
  const slug = s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  return max != null ? slug.slice(0, max) : slug;
}

/** Local wall-clock `HH:MM` (or `HH:MM:SS` with `{ seconds: true }`) for an epoch-ms
 *  timestamp; `—` for null (#2421 — automations' HH:MM + MCP Analytics' HH:MM:SS unified). */
export function fmtClock(ms: number | null, opts: { seconds?: boolean } = {}): string {
  if (ms == null) return "—";
  const d = new Date(ms);
  const hm = `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
  return opts.seconds ? `${hm}:${String(d.getSeconds()).padStart(2, "0")}` : hm;
}

/** Local `YYYY-MM-DD` for an epoch-ms timestamp — the daily-bucket key the telemetry
 *  aggregators and their charts share (#2421; was byte-identical in hook/mcp telemetry). */
export function dayKey(ts: number): string {
  const d = new Date(ts);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

runtime.shared/lib/core/hashString.ts:
// hashString (#2256) — a tiny, stable, non-cryptographic content fingerprint. Used to detect when a
// confirmed planning stage's content has CHANGED since it was confirmed (so just that stage resets).
// Not for security — only for change detection — so a cheap 32-bit rolling hash (djb2 variant) is
// plenty. Deterministic across runs/processes for the same input, which is the whole contract: the
// store's write-through and the poll's reconcile must agree on the same string → same fingerprint.

/** A stable base36 fingerprint of `content` (empty string → a fixed sentinel). Same input ⇒ same
 *  output, in any process — so the confirm-time and revisit-time fingerprints compare equal. */
export function hashString(content: string): string {
  let h = 5381;
  for (let i = 0; i < content.length; i++) {
    // h * 33 + c, kept in 32-bit range so the result is process-independent.
    h = (Math.imul(h, 33) + content.charCodeAt(i)) | 0;
  }
  // >>> 0 → unsigned, so the base36 string has no leading '-'. Prefix with the length as a cheap
  // extra discriminator (collisions on the 32-bit hash still differ if the lengths do).
  return `${content.length.toString(36)}-${(h >>> 0).toString(36)}`;
}

runtime.shared/lib/core/invokeTiming.ts:
// Invoke round-trip timing (#3626) — surfaces WHICH backend command is slow when the app feels laggy
// but the frontend `[perf]` line is clean (the signature of backend saturation delaying invokes; see
// [[perf-lag-diagnosis]]/[[fleet-gc-split-brain]]). Every `safeInvoke`/`fireInvoke`/`bsc` round-trip is
// timed; a call slower than `SLOW_INVOKE_MS` gets a `[invoke] <label> Nms` warn line in the app log's
// `perf` scope — the same file sink `log.warn(msg, "perf")` reaches.
//
// It writes STRAIGHT to `frontend_log` (not via `log`) on purpose: `log.ts` imports `safeInvoke`, so
// routing back through `log` would form a `safeInvoke ↔ log` import cycle in the lowest-level invoke
// path. Talking to the sink directly keeps that path cycle-free. The pure `slowInvokeLine` carries the
// threshold + format so it can be unit-tested with no Tauri/`log` dependency.

import { invoke } from "@tauri-apps/api/core";

/** A round-trip at/over this many ms is logged. 100ms ≈ "this call visibly stalled the caller". */
export const SLOW_INVOKE_MS = 100;

/** Commands never timed: the logging subsystem's own invokes. `frontend_log` is our sink (would be
 *  self-referential) and `log_get_scopes` is polled by `log.ts` — excluding both keeps the signal about
 *  app work, not about logging. Keyed by the real Tauri command, so `bsc …` labels are unaffected. */
const EXCLUDED = new Set(["frontend_log", "log_get_scopes"]);

/**
 * The `[invoke] <label> Nms` line for a call that took `ms`, or `null` when it's under threshold or the
 * `command` is excluded. Pure (no I/O) so the threshold/format is unit-testable.
 * @param label human-readable call label (the Tauri command, or `bsc <sub> <verb>` for the bsc bridge)
 * @param ms measured round-trip in milliseconds
 * @param command the real Tauri command, checked against the exclusion set (defaults to `label`)
 */
export function slowInvokeLine(label: string, ms: number, command: string = label): string | null {
  if (EXCLUDED.has(command)) return null;
  if (ms < SLOW_INVOKE_MS) return null;
  return `[invoke] ${label} ${Math.round(ms)}ms`;
}

/**
 * Start a round-trip timer; call the returned `stop()` in a `finally` so both fulfilled and rejected
 * invokes are measured. Emits a `[invoke]` warn line to the app-log `perf` scope when the call ran
 * `>= SLOW_INVOKE_MS`. Fire-and-forget — the sink write never blocks or throws into the caller.
 * @param label human-readable call label
 * @param command the real Tauri command for the exclusion check (defaults to `label`)
 */
export function startInvokeTimer(label: string, command: string = label): () => void {
  const t0 = performance.now();
  return () => {
    const line = slowInvokeLine(label, performance.now() - t0, command);
    if (line) void invoke("frontend_log", { level: "warn", scope: "perf", message: line }).catch(() => {});
  };
}

/** The `bsc <sub> <verb>` label for a bsc-bridge call — the first two args identify the subcommand,
 *  without logging (potentially large) positional/JSON payloads. */
export function bscLabel(args: string[]): string {
  const head = args.slice(0, 2).join(" ").trim();
  return head ? `bsc ${head}` : "bsc";
}

runtime.shared/lib/core/llmConfig.ts:
// API-tier LLM provider config (#1085 / epic #1078) — which provider + model + key
// powers llm_complete-backed (planning / assistant) calls: the planning autopilot, the
// LLM grader, the cleanup-scan verifier. This is DISTINCT from the per-pane runtime
// model (ModelId / defaultModel / paneModels → `claude --model`), which the harness
// adapter owns (P0/P2) — do not conflate them.

import modelDefaultsEmbedded from "@data/console/model-defaults.json";
import { overlayFile } from "./configOverrides";

export type LlmProvider = "anthropic" | "openai" | "gemini" | "local" | "ollama";

/** A selectable provider for the Settings UI: id + display label + API-key placeholder. */
export interface LlmProviderOption {
  id: LlmProvider;
  label: string;
  /** The key-field placeholder (empty for local providers, which need no key). */
  keyPlaceholder: string;
}

// The model-ID defaults (+ provider list) are externalized to `@data/console/model-defaults.json`
// (#2416) — the ONE source for every model default, editable without touching code + part of the
// exportable config bundle; the config-dir copy (#2047) overlays the embedded default via
// `overlayFile`. (The per-pane tier default in the same file is consumed by the model catalog,
// `@/app/console/lib/models` — a separate surface; see the note above about not conflating them.)
const MODEL_DEFAULTS = overlayFile("console/model-defaults.json", modelDefaultsEmbedded);

export interface LlmConfig {
  provider: LlmProvider;
  model: string;
  apiKey: string;
  /** OpenAI-compatible endpoint for the `local` / `ollama` provider (ignored by hosted ones). */
  baseUrl: string;
}

/** The store fields `resolveLlmConfig` reads — a structural subset of the app store,
 *  so the resolver is unit-testable with a plain object. */
export interface LlmConfigSource {
  llmProvider: LlmProvider;
  llmModel: string;
  claudeApiKey: string;
  openaiKey: string;
  geminiKey: string;
  localBaseUrl: string;
}

/** Default model for a local runtime (Ollama / OpenAI-compatible). A hosted `claude-*` model can
 *  never run locally, so a local provider falls back to this. (`ollama run qwen3-coder`.) */
export const DEFAULT_LOCAL_MODEL: string = MODEL_DEFAULTS.localModel;
/** The packaged Anthropic default, restored when switching back to a hosted provider. */
export const DEFAULT_ANTHROPIC_MODEL: string = MODEL_DEFAULTS.anthropicModel;
/** The default OpenAI-compatible endpoint for the `local`/`ollama` provider (Ollama's port). */
export const DEFAULT_LOCAL_BASE_URL: string = MODEL_DEFAULTS.localBaseUrl;
/** The selectable providers, in Settings display order. */
export const LLM_PROVIDERS: LlmProviderOption[] = MODEL_DEFAULTS.providers as LlmProviderOption[];

/** The model to actually send for a config. A `local`/`ollama` provider substitutes
 *  {@link DEFAULT_LOCAL_MODEL} when the stored model is empty or a hosted `claude-*` model (which
 *  404s on Ollama), so a stale Anthropic default never reaches the local runtime. */
export function resolveModel(provider: LlmProvider, model: string): string {
  if (providerNeedsBscAgent(provider) && (model.trim() === "" || /^claude/i.test(model))) {
    return DEFAULT_LOCAL_MODEL;
  }
  return model;
}

/** The model-field value after the user switches provider — keeps the field runnable on the new
 *  provider without clobbering a model the user explicitly typed:
 *   • → local/ollama: use {@link DEFAULT_LOCAL_MODEL} when the field is empty or a hosted `claude-*`.
 *   • → a hosted provider: restore {@link DEFAULT_ANTHROPIC_MODEL} when the field is empty or still
 *     holds the local default. Any other (custom) model is preserved as-is. */
export function modelOnProviderSwitch(provider: LlmProvider, currentModel: string): string {
  const m = currentModel.trim();
  if (providerNeedsBscAgent(provider)) {
    return m === "" || /^claude/i.test(m) ? DEFAULT_LOCAL_MODEL : currentModel;
  }
  return m === "" || m === DEFAULT_LOCAL_MODEL ? DEFAULT_ANTHROPIC_MODEL : currentModel;
}

/** Resolve the active provider + model and the API key for THAT provider.
 *  `local` & `ollama` (OpenAI-compatible, e.g. Ollama) need no key but carry a base URL. */
export function resolveLlmConfig(s: LlmConfigSource): LlmConfig {
  const apiKey =
    s.llmProvider === "openai" ? s.openaiKey :
    s.llmProvider === "gemini" ? s.geminiKey :
    (s.llmProvider === "local" || s.llmProvider === "ollama") ? "" :
    s.claudeApiKey;
  return {
    provider: s.llmProvider,
    model: resolveModel(s.llmProvider, s.llmModel),
    apiKey,
    baseUrl: s.localBaseUrl,
  };
}

/** Whether the config can make a call — a key is present, or it's `local`/`ollama` (no key). */
export function hasLlmKey(cfg: LlmConfig): boolean {
  return cfg.provider === "local" || cfg.provider === "ollama" || !!cfg.apiKey;
}

/** Providers Claude Code (the `claude` CLI) cannot drive — it only ever speaks to Anthropic. A
 *  SESSION (planner / worker / director) on one of these MUST run on the `bsc-agent` harness, so
 *  picking it implies bsc-agent regardless of the fleet-harness toggle. */
export function providerNeedsBscAgent(p: LlmProvider): boolean {
  return p === "local" || p === "ollama";
}

/** The harness a session should actually launch on. A provider Claude Code can't run (`local` /
 *  `ollama`) forces `bsc-agent` — otherwise selecting Ollama would silently launch Claude Code and
 *  ignore the choice. Every other provider honors the user's explicit `fleetHarness` toggle. So
 *  setting the provider to Ollama runs the planner, workers, and directors on Ollama with no second
 *  switch to flip. */
export function effectiveHarness(
  provider: LlmProvider,
  fleetHarness: "claude" | "bsc-agent",
): "claude" | "bsc-agent" {
  return providerNeedsBscAgent(provider) ? "bsc-agent" : fleetHarness;
}

/** The `BSC_AGENT_*` env a bsc-agent session needs to reach the configured LLM (#1078 P3b).
 *  The runtime reads provider/model/key (+ base URL for `local`/`ollama`) from these. */
export function bscAgentEnv(cfg: LlmConfig): Record<string, string> {
  const e: Record<string, string> = {
    BSC_AGENT_PROVIDER: cfg.provider,
    BSC_AGENT_MODEL: cfg.model,
  };
  if (cfg.apiKey) e.BSC_AGENT_API_KEY = cfg.apiKey;
  if (cfg.baseUrl) e.BSC_AGENT_BASE_URL = cfg.baseUrl;
  return e;
}

/** Map an {@link LlmConfig} to Aider's `--model` selector (#1172). Aider (via litellm) namespaces
 *  models by provider — `anthropic/…`, `gemini/…` — takes OpenAI models bare, and reaches a
 *  local / OpenAI-compatible endpoint through the `openai/…` prefix (paired with `OPENAI_API_BASE`,
 *  see {@link aiderEnv}). A model already carrying a `provider/` prefix is passed through untouched. */
export function aiderModelArg(cfg: LlmConfig): string {
  const m = cfg.model.trim();
  if (m.includes("/")) return m;
  switch (cfg.provider) {
    case "anthropic": return `anthropic/${m}`;
    case "gemini":    return `gemini/${m}`;
    case "openai":    return m;
    case "local":
    case "ollama":    return `openai/${m}`;
  }
}

/** The environment an Aider session needs to reach the configured LLM (#1172): the provider's API key
 *  under the variable Aider/litellm reads (`ANTHROPIC_API_KEY` / `OPENAI_API_KEY` / `GEMINI_API_KEY`),
 *  plus an `OPENAI_API_BASE` for a local / OpenAI-compatible endpoint. A local server needs no real
 *  key, so a placeholder satisfies the OpenAI client's non-empty check. Mirrors {@link bscAgentEnv}. */
export function aiderEnv(cfg: LlmConfig): Record<string, string> {
  const e: Record<string, string> = {};
  switch (cfg.provider) {
    case "anthropic": if (cfg.apiKey) e.ANTHROPIC_API_KEY = cfg.apiKey; break;
    case "openai":    if (cfg.apiKey) e.OPENAI_API_KEY = cfg.apiKey; break;
    case "gemini":    if (cfg.apiKey) e.GEMINI_API_KEY = cfg.apiKey; break;
    case "local":
    case "ollama":
      if (cfg.baseUrl) e.OPENAI_API_BASE = cfg.baseUrl;
      // A keyless local server still needs a non-empty OPENAI_API_KEY for the client to init.
      e.OPENAI_API_KEY = cfg.apiKey || "sk-local-none";
      break;
  }
  return e;
}

runtime.shared/lib/core/log.ts:
// Unified frontend logger — routed through the runtime log-scope graph (#1389).
//
// Two sinks, split by POLICY (mirroring the backend `GraphLogger`):
//   1. FILE — always. Every call forwards to the `frontend_log` command, which routes through the
//      backend GraphLogger so the record is ALWAYS audited to the rotating app-log file. This is the
//      security property: an agent/dev can quiet the console VIEW but can never suppress the record.
//   2. DEVTOOLS CONSOLE — a view, gated per feature scope by the synced scope registry
//      (`log_get_scopes`). A scope toggled off/below-level silences its devtools output; the file
//      record is unaffected.
//
// The backend hop is DEFERRED (#1033): the `invoke` never fires synchronously inside a logging call
// (which could land in a render/PTY hot path during cold start). Calls are queued and drained on a
// short debounced timer, off the caller's stack. The console output stays immediate.

import { invoke } from "@tauri-apps/api/core";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";

/** A frontend log level. Ranks mirror the backend (`log::Level`): error=1 … debug=4. */
type Level = "error" | "warn" | "info" | "debug";

const LEVEL_RANK: Record<Level, number> = { error: 1, warn: 2, info: 3, debug: 4 };

/** The app crate's log-target root — frontend records are namespaced beneath it so they join the
 *  ONE scope tree the backend + `bsc log` share. Keep in sync with `logs::scope::CRATE_ROOT`. */
const CRATE_ROOT = "base_studio_code_lib";

/** The default feature scope when a caller doesn't name one. */
const DEFAULT_SCOPE = "core";

/** How long (ms) to coalesce queued backend-sink writes before draining them. */
const FLUSH_MS = 250;
/** How stale (ms) the cached scope config may get before a lazy background refresh. */
const SCOPES_TTL_MS = 5_000;

/** The full `::`-joined target for a frontend feature scope (`…::frontend::planner`). */
function targetFor(scope: string): string {
  const leaf = scope.trim();
  return leaf ? `${CRATE_ROOT}::frontend::${leaf}` : `${CRATE_ROOT}::frontend`;
}

// ── Synced scope registry (the devtools-console gate) ────────────────────────────────────────────
// A local mirror of the backend scope graph (`log_get_scopes`), refreshed lazily. Seeded with the
// backend defaults (root=warn, app crate=info) so behavior pre-fetch matches post-fetch.

const scopeThreshold: Map<string, number> = new Map([
  ["", LEVEL_RANK.warn],
  [CRATE_ROOT, LEVEL_RANK.info],
]);
let scopesFetchedAt = 0;

/** Map a backend level label to a rank; `off` → 0 (never shows). */
function labelRank(label: string): number {
  if (label === "off") return 0;
  return (LEVEL_RANK as Record<string, number>)[label] ?? LEVEL_RANK.warn;
}

/** Refresh the cached scope graph from the backend (fire-and-forget; degrades to the current cache). */
async function refreshScopes(): Promise<void> {
  scopesFetchedAt = Date.now();
  const nodes = await safeInvoke<{ scope: string; level: string }[]>("log_get_scopes", undefined, []);
  if (!Array.isArray(nodes) || nodes.length === 0) return;
  scopeThreshold.clear();
  for (const n of nodes) scopeThreshold.set(n.scope, labelRank(n.level));
}

/** Whether a record at `scope`/`levelRank` passes the devtools-console gate: the longest scope key
 *  that prefix-matches the target governs (cascade to subtree), mirroring `ScopeConfig::console_level`. */
function consolePermits(scope: string, levelRank: number): boolean {
  // Kick a lazy refresh when the cache is stale (never blocks the log call).
  if (Date.now() - scopesFetchedAt > SCOPES_TTL_MS) void refreshScopes();

  const target = targetFor(scope);
  let bestLen = -1;
  let threshold = LEVEL_RANK.warn; // floor if nothing matches (root is usually present)
  for (const [key, rank] of scopeThreshold) {
    const matches = key === "" || target === key || target.startsWith(`${key}::`);
    if (matches && key.length > bestLen) {
      bestLen = key.length;
      threshold = rank;
    }
  }
  return threshold > 0 && levelRank <= threshold;
}

// ── The deferred backend queue (#1033) ───────────────────────────────────────────────────────────

const queue: { level: Level; scope: string; message: string }[] = [];
let flushTimer: ReturnType<typeof setTimeout> | null = null;

function drain(): void {
  flushTimer = null;
  const batch = queue.splice(0, queue.length);
  // Fire-and-forget, in order; swallow failures so logging never breaks flow.
  for (const { level, scope, message } of batch) {
    void invoke("frontend_log", { level, scope, message }).catch(() => { /* backend unavailable */ });
  }
}

function scheduleFlush(): void {
  if (flushTimer === null) flushTimer = setTimeout(drain, FLUSH_MS);
}

const consoleFn: Record<Level, (...args: unknown[]) => void> = {
  error: console.error,
  warn: console.warn,
  info: console.info,
  debug: console.debug,
};

function route(level: Level, message: string, scope: string): void {
  // FILE sink — ALWAYS (the security property): queue the deferred backend hop.
  queue.push({ level, scope, message });
  scheduleFlush();
  // DEVTOOLS CONSOLE sink — gated per scope by the synced registry.
  if (consolePermits(scope, LEVEL_RANK[level])) consoleFn[level](message);
}

/**
 * The app logger. Every call is audited to the file sink; the devtools-console output is gated per
 * feature `scope` (default `"core"`) by the runtime scope graph — so `bsc log set frontend::planner
 * off` or the graph UI can quiet a feature's console noise without losing the audit record.
 */
export const log = {
  debug: (message: string, scope: string = DEFAULT_SCOPE) => route("debug", message, scope),
  info:  (message: string, scope: string = DEFAULT_SCOPE) => route("info", message, scope),
  warn:  (message: string, scope: string = DEFAULT_SCOPE) => route("warn", message, scope),
  error: (message: string, scope: string = DEFAULT_SCOPE) => route("error", message, scope),
};

runtime.shared/lib/core/logsBridge.ts:
// In-process log-stream reads (#3630) — the perf-critical replacement for polling the unified log
// streams through the `bsc` bridge, which SPAWNED a `bsc.exe` subprocess per read (`console::bsc`).
// The always-on fleet/console pumps (`useCoordLog`, `useWorkerAutoEnd`, the pane-activity poll) hit
// these every ~1s; at 5–10 spawns/sec the Tauri invoke backlog grew without bound and the app froze.
// These native commands (`observability::logs::logs_*`) read the SAME files in-process via the `logs`
// crate — a file read, not a process — so the hot polls stop saturating the backend.
//
// Same JSON shape the `bsc logs …` subcommands emitted (the native commands return the same serde
// types), so these are drop-ins for the prior `bscJson(null, ["logs", …])` calls. Low-frequency
// `bsc logs …` reads (cost, analytics one-shots) stay on the `bsc` bridge.

import { safeInvoke } from "@/shared/lib/core/safeInvoke";

/** One pane's latest turn-boundary state — the `logs::PaneActivity` shape (`bsc logs pane-activity`). */
export interface PaneActivityRow {
  pane: string;
  state: string;
  at: number;
}

/**
 * Newest `limit` raw lines of a unified log stream (`coord`/`audit`/`skill`/`hook`/`mcp`/`ui`/…),
 * read in-process. `oldest` keeps chronological (oldest-first) order — pass `true` for the coord/ui
 * logs the replayers walk forward. An unknown/missing stream resolves to `fallback` (default `[]`);
 * pass `null` where a caller must distinguish "read failed → skip this tick" from an empty log.
 */
export function logsTail(stream: string, limit: number, oldest?: boolean): Promise<string[]>;
export function logsTail<F>(stream: string, limit: number, oldest: boolean, fallback: F): Promise<string[] | F>;
export function logsTail(stream: string, limit: number, oldest = false, fallback: unknown = []): Promise<unknown> {
  return safeInvoke("logs_tail", { stream, limit, oldest }, fallback);
}

/** The latest turn-boundary state per pane (`run`/`idle`), newest pane first — `bsc logs pane-activity`.
 *  Generic `T` lets a caller keep its own row type; the wire shape is always `{ pane, state, at }`. */
export function logsPaneActivity<T = PaneActivityRow>(): Promise<T[]> {
  return safeInvoke<T[]>("logs_pane_activity", undefined, []);
}

/** The deduped set of panes that self-reported `done` (#1379), newest first — `bsc logs done-panes`. */
export function logsDonePanes(): Promise<string[]> {
  return safeInvoke<string[]>("logs_done_panes", undefined, []);
}

/**
 * The canonical stream key for a read alias — mirrors Rust `logs::canonical_stream`. The UI reads a few
 * streams by alias (`audit`→`tool`, `skills`→`skill`); everything else is already canonical. Used to
 * line a read alias up with the backend's `logs://<canonical>` change event (#3638), so a subscriber
 * never misses an emit because it named the stream differently than the watcher did.
 */
export function canonicalStream(alias: string): string {
  switch (alias) {
    case "audit":
    case "tools":
      return "tool";
    case "skills":
      return "skill";
    default:
      return alias;
  }
}

/** The Tauri event the backend log watcher (`observability::log_watch`) emits when `stream` changes —
 *  the event `useLogStream` subscribes to. Accepts a read alias (canonicalized). MUST stay in sync with
 *  the Rust `event_name` (#3638). */
export function logEventName(stream: string): string {
  return `logs://${canonicalStream(stream)}`;
}

runtime.shared/lib/core/math.ts:
// Shared numeric helpers (#2421) — feature-agnostic, pure. The one home for the clamp
// that was written three ways (useDragResize's clampSize, useGraphViewport's local const,
// and many inline Math.min/Math.max chains).

/**
 * Clamp `value` into the inclusive `[min, max]` range.
 *
 * Equivalent to `Math.max(min, Math.min(max, value))` — so like every prior inline chain,
 * a caller passing an inverted range (min > max) gets `min` back.
 */
export function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

runtime.shared/lib/core/perf.ts:
// Lightweight frontend performance monitor.
//
// Emits ONE aggregated metrics line on a steady ~2s cadence (logging per-event
// would add IPC + file-write work on the already-overloaded main thread). The
// line combines:
//   • jank      — main-thread long tasks (count / worst / total blocked ms)
//   • pty       — pty_data events reaching the frontend (count / KB / ms spent
//                 synchronously in the term.write handler)
//   • terms     — number of mounted terminals
// Together these tell us whether the lag is rendering load (jank high, terms high)
// vs. data volume (pty high) vs. handler cost (pty ms high).

import { fireInvoke } from "./safeInvoke";
import { log } from "./log";

/** Long tasks at or above this many ms count toward the jank tally. */
const LONG_TASK_MS = 100;
/** How often (ms) to flush the aggregated metrics line. */
const FLUSH_MS = 2000;
/** Heap usage above this fraction of the limit gets its own warning. */
const HEAP_WARN_RATIO = 0.85;

/** JS heap snapshot (MB), or null when the runtime doesn't expose it. */
export interface HeapInfo { usedMB: number; limitMB: number; }

/**
 * Reads the WebView's JS heap usage. `performance.memory` is a non-standard
 * Chromium API (present in the WebView2 renderer) — absent elsewhere, hence the
 * guard. Used to spot renderer memory growth, e.g. a 4×4 triage's 16 terminals.
 */
export function readHeap(): HeapInfo | null {
  const m = (performance as unknown as {
    memory?: { usedJSHeapSize: number; jsHeapSizeLimit: number };
  }).memory;
  if (!m || !m.jsHeapSizeLimit) return null;
  return {
    usedMB: Math.round(m.usedJSHeapSize / 1048576),
    limitMB: Math.round(m.jsHeapSizeLimit / 1048576),
  };
}

interface PerfStats {
  jankCount: number;
  jankTotalMs: number;
  jankWorstMs: number;
  ptyEvents: number;
  ptyBytes: number;
  ptyHandlerMs: number;
  renders: number;
  /** Per-window count of how often each store key changed (finds re-render loops). */
  storeWrites: Record<string, number>;
  terminals: number;
}

const stats: PerfStats = {
  jankCount: 0, jankTotalMs: 0, jankWorstMs: 0,
  ptyEvents: 0, ptyBytes: 0, ptyHandlerMs: 0,
  renders: 0,
  storeWrites: {},
  terminals: 0,
};

function resetWindow(): void {
  stats.jankCount = 0; stats.jankTotalMs = 0; stats.jankWorstMs = 0;
  stats.ptyEvents = 0; stats.ptyBytes = 0; stats.ptyHandlerMs = 0;
  stats.renders = 0;
  stats.storeWrites = {};
  // terminals is a live count, not a per-window tally — leave it.
}

/** Build the aggregated metrics line, or null when there was no activity. Pure. */
export function formatPerfSummary(s: PerfStats, elapsedMs: number, heap?: HeapInfo | null): string | null {
  // Report on any activity — including a re-render/store-write loop that produces
  // no long-task jank and no pty traffic (exactly the case we're chasing).
  const idle = s.jankCount === 0 && s.ptyEvents === 0 && s.renders === 0
    && Object.keys(s.storeWrites).length === 0;
  if (idle) return null;
  const parts: string[] = [];
  if (s.jankCount > 0) {
    parts.push(`jank ${s.jankCount}× (worst ${Math.round(s.jankWorstMs)}ms, total ${Math.round(s.jankTotalMs)}ms)`);
  }
  if (s.ptyEvents > 0) {
    parts.push(`pty ${s.ptyEvents} evt, ${Math.round(s.ptyBytes / 1024)}KB, ${Math.round(s.ptyHandlerMs)}ms write`);
  }
  if (s.renders > 0) {
    parts.push(`${s.renders} renders`);
  }
  // Workspace the top 2 most-frequently-written store keys — a re-render loop shows
  // up here as one key changing hundreds of times per window.
  const top = Object.entries(s.storeWrites).sort((a, b) => b[1] - a[1]).slice(0, 2);
  if (top.length > 0) {
    parts.push(`store ${top.map(([k, n]) => `${k}×${n}`).join(", ")}`);
  }
  parts.push(`${s.terminals} terms`);
  if (heap) {
    parts.push(`heap ${heap.usedMB}/${heap.limitMB}MB`);
  }
  return `[perf] ${(elapsedMs / 1000).toFixed(1)}s · ${parts.join(" · ")}`;
}

/** Record one pty_data event: payload size + synchronous handler time. Hot path — keep cheap. */
export function recordPtyData(bytes: number, handlerMs: number): void {
  stats.ptyEvents += 1;
  stats.ptyBytes += bytes;
  stats.ptyHandlerMs += handlerMs;
}

/** Adjust the live mounted-terminal count (+1 on mount, -1 on unmount). */
export function bumpTerminals(delta: number): void {
  stats.terminals = Math.max(0, stats.terminals + delta);
}

/** Count one React commit of an instrumented component (e.g. ConsoleWorkspace). */
export function recordRender(): void {
  stats.renders += 1;
}

/** Count one change to a store key (for spotting which key drives a re-render loop). */
export function recordStoreWrite(key: string): void {
  stats.storeWrites[key] = (stats.storeWrites[key] ?? 0) + 1;
}

let observer: PerformanceObserver | null = null;
let timer: ReturnType<typeof setInterval> | null = null;
let lastFlush = 0;

/** Fire-and-forget: push the current window's metrics into the backend time-series. */
function emitFrontendSample(s: PerfStats, heap: HeapInfo | null): void {
  fireInvoke("perf_record_frontend_sample", {
    heapUsedMb: heap?.usedMB ?? null,
    jankCount: s.jankCount,
    jankTotalMs: s.jankTotalMs,
    ptyEvents: s.ptyEvents,
    ptyBytes: s.ptyBytes,
  });
}

/** Start the long-task observer + the periodic metrics flush. Idempotent. */
export function startPerfMonitor(): void {
  if (timer) return;
  if (typeof PerformanceObserver !== "undefined") {
    try {
      observer = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          if (entry.duration >= LONG_TASK_MS) {
            stats.jankCount += 1;
            stats.jankTotalMs += entry.duration;
            stats.jankWorstMs = Math.max(stats.jankWorstMs, entry.duration);
          }
        }
      });
      observer.observe({ entryTypes: ["longtask"] });
    } catch {
      observer = null;
    }
  }
  lastFlush = performance.now();
  timer = setInterval(() => {
    const now = performance.now();
    const heap = readHeap();
    const line = formatPerfSummary(stats, now - lastFlush, heap);
    // Emit a snapshot to the backend time-series before resetting the window.
    emitFrontendSample(stats, heap);
    lastFlush = now;
    resetWindow();
    if (line) log.warn(line);
    // Fire even when otherwise idle — a heap creeping toward the limit (e.g. a
    // 4×4 triage's terminals) is exactly the signal we want, regardless of jank.
    if (heap && heap.usedMB / heap.limitMB >= HEAP_WARN_RATIO) {
      log.warn(`[perf] high heap: ${heap.usedMB}/${heap.limitMB}MB (${Math.round(100 * heap.usedMB / heap.limitMB)}%)`);
    }
  }, FLUSH_MS);
}

/**
 * Time an async operation, logging a warning when it exceeds `thresholdMs`.
 * Returns the operation's result untouched (and still times on throw).
 */
export async function timed<T>(label: string, fn: () => Promise<T>, thresholdMs = 50): Promise<T> {
  const t0 = performance.now();
  try {
    return await fn();
  } finally {
    const ms = performance.now() - t0;
    if (ms >= thresholdMs) log.warn(`[perf] ${label} took ${Math.round(ms)}ms`);
  }
}

/**
 * Time a SYNC operation, logging a warning when it exceeds `thresholdMs` (default one frame, 16ms).
 * Returns the result untouched (and still times on throw). For hot render-path compute an async `timed`
 * doesn't fit — e.g. the Glance graph layout (#3618), where we want to separate layout-compute time from
 * React-render time.
 */
export function timedSync<T>(label: string, fn: () => T, thresholdMs = 16): T {
  const t0 = performance.now();
  try {
    return fn();
  } finally {
    const ms = performance.now() - t0;
    if (ms >= thresholdMs) log.warn(`[perf] ${label} took ${Math.round(ms)}ms`);
  }
}

runtime.shared/lib/core/projectFiles.ts:
// Shared project-hub file capability — the persistence primitive a pipeline calls from
// inside its own save/confirm behavior (#…). Pipelines decide what/where/when to write;
// this is just the path-safe transport to `~/.base-studio-code/projects/<key>/`. Thin
// wrappers over the Rust `write_project_file` / `read_project_files` commands.

import { invoke } from "@tauri-apps/api/core";

/** Write one file under the project hub. `relpath` is resolved under the project dir;
 *  the Rust side rejects any path that would escape it. */
export function writeProjectFile(projectKey: string, relpath: string, contents: string): Promise<void> {
  return invoke("write_project_file", { projectKey, relpath, contents });
}

