// Inter-session coordination core (#199): the lost-wakeup-safe readiness model.
//
// The key correctness insight: readiness is **state** (a queryable latch), not an
// edge-triggered ping. A producer that finishes *before* the waiter registers must not
// cause a lost wakeup and a permanent hang. So a blocking session both registers as a
// waiter AND immediately checks the latch (proceed now if already satisfied); satisfy
// events set the latch and return the waiters whose **all** deps are now satisfied.
//
// This module is pure (no PTY/store/IO) so it's exhaustively unit-testable. The wiring —
// `bsc-blocked --on` -> register, the director's merge/close -> satisfy, and waking the
// parked pane -- lands on top of it in later slices. `failed` is deliberately NOT a
// satisfy: dependents stay blocked and surface as a stalled chain (finished != succeeded).
import type {
  CoordRef,
  SatisfySource,
  Waiter,
  CoordState,
} from "./coordination.types";

export function emptyCoordState(): CoordState {
  return { latches: {}, waiters: [], waiting: [], asking: [], issues: [], maintaining: [], briefs: [], forks: [], commissions: [], requests: [] };
}

/** Canonical string key for a ref -- the `bsc-blocked --on <token>` wire form too. */
export function refKey(ref: CoordRef): string {
  switch (ref.kind) {
    case "issue": return `#${ref.number}`;
    case "contract": return `contract:${ref.name}`;
    case "file": return `file:${ref.path}`;
    case "predicate": return `predicate:${ref.expr}`;
    case "session": return `session:${ref.id}`;
  }
}

/** Parse a `bsc-blocked --on` token (`#42`, `contract:X`, `file:path`, `predicate:expr`)
 *  back into a ref. Returns null for an unrecognized/empty token. A bare `42` or `#42`
 *  is an issue; an unprefixed non-numeric token is treated as a predicate. */
export function parseRef(token: string): CoordRef | null {
  const t = token.trim();
  if (!t) return null;
  if (t.startsWith("#")) {
    const n = Number(t.slice(1));
    return Number.isInteger(n) && n > 0 ? { kind: "issue", number: n } : null;
  }
  const colon = t.indexOf(":");
  if (colon > 0) {
    const prefix = t.slice(0, colon);
    const rest = t.slice(colon + 1).trim();
    if (!rest) return null;
    if (prefix === "contract") return { kind: "contract", name: rest };
    if (prefix === "file") return { kind: "file", path: rest };
    if (prefix === "predicate") return { kind: "predicate", expr: rest };
    if (prefix === "session") return { kind: "session", id: rest };
    return null;
  }
  if (/^\d+$/.test(t)) return { kind: "issue", number: Number(t) };
  return { kind: "predicate", expr: t };
}

/** Whether `ref` is satisfied (truly done -- not merely failed). */
export function isSatisfied(s: CoordState, ref: CoordRef): boolean {
  return s.latches[refKey(ref)]?.state === "satisfied";
}

/** Whether all of a waiter's deps are satisfied. */
export function isReady(s: CoordState, w: Waiter): boolean {
  return w.deps.every((d) => isSatisfied(s, d));
}

/** Waiters currently blocked on a ref that has *failed* -- a stalled chain to escalate. */
export function stalledWaiters(s: CoordState, ref: CoordRef): Waiter[] {
  const key = refKey(ref);
  if (s.latches[key]?.state !== "failed") return [];
  return s.waiters.filter((w) => w.deps.some((d) => refKey(d) === key));
}

/**
 * Register a blocking session. Returns the next state and `ready`: whether all its deps
 * are ALREADY satisfied (the register-then-check that defeats lost wakeups -- the caller
 * should proceed immediately when `ready`). When already ready, the waiter is not added
 * (nothing to wait for); otherwise it's added/replaced by `session` id (idempotent).
 */
export function registerWaiter(s: CoordState, w: Waiter): { state: CoordState; ready: boolean } {
  const ready = isReady(s, w);
  const others = s.waiters.filter((x) => x.session !== w.session);
  const state: CoordState = {
    latches: s.latches,
    waiters: ready ? others : [...others, w],
    waiting: s.waiting,
    asking: s.asking,
    issues: s.issues,
    maintaining: s.maintaining,
    briefs: s.briefs,
    forks: s.forks,
    requests: s.requests,
    commissions: s.commissions,
  };
  return { state, ready };
}

/**
 * Mark a ref satisfied (a `landed`/`merged`/`closed` event). Sets the latch and returns
 * the waiters that are now fully ready (all deps satisfied), removing them from the
 * table. Idempotent: re-delivering the same satisfy is harmless (readiness is state).
 */
export function satisfy(
  s: CoordState,
  ref: CoordRef,
  source: SatisfySource,
  at: number,
): { state: CoordState; woken: Waiter[] } {
  const latches = { ...s.latches, [refKey(ref)]: { state: "satisfied" as const, source, at } };
  const probe: CoordState = { latches, waiters: s.waiters, waiting: s.waiting, asking: s.asking, issues: s.issues, maintaining: s.maintaining, briefs: s.briefs, forks: s.forks, commissions: s.commissions, requests: s.requests };
  const woken = s.waiters.filter((w) => isReady(probe, w));
  const wokenIds = new Set(woken.map((w) => w.session));
  return { state: { latches, waiters: s.waiters.filter((w) => !wokenIds.has(w.session)), waiting: s.waiting, asking: s.asking, issues: s.issues, maintaining: s.maintaining, briefs: s.briefs, forks: s.forks, commissions: s.commissions, requests: s.requests }, woken };
}

/**
 * Mark a ref failed (a `failed` event). Does NOT satisfy the latch -- dependents stay
 * blocked. Returns the waiters now stalled on this failed ref so the caller can raise a
 * blocked-chain alert. Idempotent.
 */
export function fail(
  s: CoordState,
  ref: CoordRef,
  reason: string,
  at: number,
): { state: CoordState; stalled: Waiter[] } {
  const latches = { ...s.latches, [refKey(ref)]: { state: "failed" as const, reason, at } };
  const next: CoordState = { latches, waiters: s.waiters, waiting: s.waiting, asking: s.asking, issues: s.issues, maintaining: s.maintaining, briefs: s.briefs, forks: s.forks, commissions: s.commissions, requests: s.requests };
  return { state: next, stalled: stalledWaiters(next, ref) };
}

runtime.shared/lib/fleet/coordinationWakes.ts:
// -- Wake planning + inbox view (#199 slice 3) ----------------------------------
// Pure "decide + present": given the ingested latch state, what to wake (with what
// prompt) and what the inbox/health view shows. The store/PTY execution (relaunch the
// pane, render the panel) is a thin layer on top of these in a later slice.
import type {
  CoordRef,
  Waiter,
  CoordState,
  AssignedWork,
  AnsweredWake,
  WaitingSession,
  WakeAction,
  BlockedView,
  ProducerOf,
} from "./coordination.types";
import { refKey } from "./coordinationState";
import { detectDeadlocks, defaultProducerOf } from "./coordinationDeadlock";

/** A ref's latch status as a short label (for prompts + the inbox view). */
function statusOf(s: CoordState, ref: CoordRef): "satisfied" | "failed" | "pending" {
  const l = s.latches[refKey(ref)];
  return l?.state === "satisfied" ? "satisfied" : l?.state === "failed" ? "failed" : "pending";
}

/**
 * Compose the token-aware wake prompt for a woken waiter -- names the landed deps (with
 * how they were satisfied) and points at the checkpoint, so the FRESH session resumes
 * without re-deriving context (never `--continue` on a fat transcript; see #199).
 */
export function wakePromptFor(w: Waiter, s: CoordState): string {
  const landed = w.deps
    .map((d) => {
      const l = s.latches[refKey(d)];
      const via = l?.state === "satisfied" ? l.source : "ready";
      return `${refKey(d)} (${via})`;
    })
    .join(", ");
  const lines = [
    `Your blocking ${w.deps.length === 1 ? "dependency has" : "dependencies have"} landed -- resume now.`,
    `Satisfied: ${landed}.`,
  ];
  if (w.checkpoint) {
    lines.push(`Resume from your checkpoint: ${w.checkpoint} -- read it first, then continue from where you left off.`);
  }
  return lines.join("\n");
}

/**
 * Compose the wake prompt for a session that paused for the USER (#297 checkpoint/
 * confirm flow) — names the reason it paused and points at the checkpoint so the
 * fresh session resumes in context. Unlike {@link wakePromptFor}, there are no deps
 * to report; the user has decided to resume it.
 */
export function waitingWakePrompt(w: WaitingSession): string {
  const lines = [
    w.reason.trim()
      ? `You paused for confirmation: ${w.reason.trim()} — the user has resumed you; proceed.`
      : "You paused for the user — you have been resumed; proceed.",
  ];
  if (w.checkpoint) {
    lines.push(`Resume from your checkpoint: ${w.checkpoint} — read it first, then continue from where you left off.`);
  }
  return lines.join("\n");
}

/**
 * Compose the wake prompt for a session the DIRECTOR answered (#369). Carries the
 * director's answer and points at the checkpoint, so the fresh session resumes on that
 * basis without re-asking. This is what makes "defer to the director" a real round-trip.
 */
export function answerWakePrompt(a: AnsweredWake): string {
  const lines = [
    `The director responded: ${a.answer.trim() || "(see the director's notes)"} — proceed on that basis; you are no longer parked. Do not ask the user.`,
  ];
  if (a.checkpoint) {
    lines.push(`Resume from your checkpoint: ${a.checkpoint} — read it first, then continue.`);
  }
  return lines.join("\n");
}

/**
 * Compose the injection prompt for a worker the director assigned new work (#376).
 * States it is new work routed by the director, carries the title + body, and points
 * at the checkpoint so a resumed worker re-grounds before starting. The worker then
 * flows into its normal implement → integrate loop.
 */
export function assignWakePrompt(a: AssignedWork): string {
  const lines = [
    `The director assigned you new work${a.title ? `: ${a.title}` : ""}. Start on it now and carry it through your normal loop (implement → gate → integrate). Do not ask the user.`,
  ];
  if (a.body.trim()) lines.push("", a.body.trim());
  if (a.checkpoint) {
    lines.push("", `First re-read your checkpoint: ${a.checkpoint}, then begin the new work.`);
  }
  return lines.join("\n");
}

/** Map newly-woken waiters to wake actions (the prompt-injection payloads slice 4 runs). */
export function planWakes(woken: Waiter[], s: CoordState): WakeAction[] {
  return woken.map((w) => ({ session: w.session, deps: w.deps, prompt: wakePromptFor(w, s) }));
}

/** Derive the inbox/health view from latch state: every still-parked waiter, each dep's
 *  status, whether the chain is stalled (a failed dep), and whether it sits in a wait-for
 *  cycle (a deadlock). `producerOf` resolves which session satisfies a dep (defaults to
 *  the `session:` self-resolver -- see {@link detectDeadlocks}). */
export function coordinationSummary(s: CoordState, producerOf: ProducerOf = defaultProducerOf): BlockedView[] {
  const deadlocked = new Set(detectDeadlocks(s, producerOf).flatMap((d) => d.cycle));
  return s.waiters.map((w) => {
    const deps = w.deps.map((d) => ({ ref: refKey(d), status: statusOf(s, d) }));
    return {
      session: w.session,
      checkpoint: w.checkpoint,
      deps,
      stalled: deps.some((d) => d.status === "failed"),
      deadlocked: deadlocked.has(w.session),
    };
  });
}

// -- Auto-wake recency gate (#199) ----------------------------------------------
// The always-on coordinator only auto-relaunches a ready session if its deps landed
// RECENTLY, so an app restart (which replays the whole log) can't relaunch sessions whose
// dependencies were satisfied long ago and were never woken. The manual Wake button has
// no such limit. Kept pure (takes `now`) so it's testable.

/** Newest moment among a waiter's deps at which one became satisfied (ms epoch), or 0. */
export function readinessAt(w: Waiter, s: CoordState): number {
  let newest = 0;
  for (const d of w.deps) {
    const l = s.latches[refKey(d)];
    if (l?.state === "satisfied" && l.at > newest) newest = l.at;
  }
  return newest;
}

/** Whether `w` became ready within `windowMs` of `now`. */
export function isFreshlyReady(w: Waiter, s: CoordState, now: number, windowMs: number): boolean {
  const at = readinessAt(w, s);
  return at > 0 && now - at < windowMs;
}

runtime.shared/lib/fleet/coordinatorActuate.ts:
// Shared wake actuation (#199): kill the parked pane, relaunch it fresh via the store's
// wakePane, then record the `woke` event so it isn't offered again. Used by both the
// inbox "Wake" button and the always-on auto-wake coordinator.
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { injectPrompt } from "./paneInject";

export async function actuateWake(
  session: string,
  prompt: string,
  wakePane: (paneId: string, prompt: string) => boolean,
): Promise<boolean> {
  // Kill first so the runId-bump remount spawns a FRESH session (not a reconnect).
  await safeInvoke("pty_kill", { paneId: session }, undefined);
  const ok = wakePane(session, prompt);
  if (ok) await safeInvoke("append_coord_woke", { session }, undefined);
  return ok;
}

/**
 * Deliver a wake to a LIVE (parked) session by injecting the prompt straight into its pane
 * (#374) — instant, keeps the session's own context, and consistent with how the director
 * pump + CI watcher deliver. Records the `woke` event so it isn't re-fired. This is the
 * automatic path; the manual inbox button still uses actuateWake (a fresh relaunch).
 */
export async function injectWake(session: string, prompt: string): Promise<boolean> {
  await injectPrompt(session, prompt);
  await safeInvoke("append_coord_woke", { session }, undefined);
  return true;
}

runtime.shared/lib/fleet/faultTriage.ts:
// Runtime fault → routed fix loop (#2265, part of #2258). The PURE decision core that turns a project's
// unresolved runtime faults (read from `bsc errors list --unresolved --json`, the errordb store #2260)
// into a bounded, deduped set of fix DISPATCHES — the director then routes each via the existing
// coordination emitters `bsc-issue` (capture) → `bsc-assign` (route to a worker), and clears it on land
// with `bsc errors resolve <fingerprint>`.
//
// Kept React/Tauri-free so the three guarantees the acceptance turns on are unit-tested in isolation:
//   • GATE     — the per-project auto-triage toggle. OFF ⇒ surface-only, dispatch nothing.
//   • DEDUP    — never dispatch the same fingerprint twice while it stays open (idempotent per fault).
//   • RATE-LIMIT — a fault storm (N occurrences, or many faults at once) never exceeds the fan-out cap.
//
// The `useFaultTriage` hook is the thin poll+inject actuator over this; the maintenance/kickoff prose
// (director-protocol.md) primes the director to expect the injected fault and to resolve it on land.

import { clamp } from "@/shared/lib/core/math";

export type FaultLevel = "warn" | "error" | "fatal";

/** The minimal fault shape the triage core reads — a projection of the errordb `Fault` row (#2260). */
export interface FaultLite {
  fingerprint: string;
  level: FaultLevel;
  title: string;
  count: number;
  /** ms epoch when resolved; absent/null ⇒ open. (`--unresolved` lists only opens, but the fn is total
   *  over any list so a mixed list still behaves.) */
  resolvedAt?: number | null;
}

/** Per-project triage policy. `enabled` is the auto-triage toggle; the rest are the rate/severity knobs. */
export interface FaultTriageConfig {
  /** The per-project auto-triage toggle. `false` ⇒ surface-only (default): faults are shown, none routed. */
  enabled: boolean;
  /** Minimum occurrence `count` before a fault is worth routing a fix for. */
  threshold: number;
  /** Minimum severity to route (below it, surface-only). */
  minLevel: FaultLevel;
  /** Fan-out cap: at most this many concurrently dispatched-but-still-open fixes for the project. */
  maxInFlight: number;
  /** Storm guard: at most this many NEW dispatches emitted in a single poll cycle. */
  maxPerCycle: number;
}

/** The default knobs (the toggle itself defaults OFF, supplied separately per project). Conservative:
 *  error+ only, a small fan-out, ≤2 new fixes per cycle — a storm can't spawn a fleet. */
export const DEFAULT_FAULT_TRIAGE: Omit<FaultTriageConfig, "enabled"> = {
  threshold: 1,
  minLevel: "error",
  maxInFlight: 3,
  maxPerCycle: 2,
};

/** One fault chosen for routing this cycle. */
export interface FaultDispatch {
  fingerprint: string;
  level: FaultLevel;
  title: string;
  count: number;
}

export interface FaultTriagePlan {
  /** Faults to route THIS cycle (the director captures + assigns one fix each). */
  dispatch: FaultDispatch[];
  /** The fingerprints now considered handled — carry this back in as `dispatched` next cycle. Pruned to
   *  still-open faults, so a resolved fault drops out (freeing its fan-out slot) and a later recurrence
   *  re-dispatches. */
  nextDispatched: string[];
}

const LEVEL_RANK: Record<FaultLevel, number> = { warn: 1, error: 2, fatal: 3 };
function rank(l: FaultLevel): number {
  return LEVEL_RANK[l] ?? 0;
}

/**
 * Decide which unresolved faults to route this poll cycle. Pure + deterministic.
 *
 * @param faults      the project's fault list (typically `bsc errors list --unresolved --json`).
 * @param dispatched  fingerprints already routed in prior cycles (the dedup ledger; carry `nextDispatched`).
 * @param cfg         the per-project policy (gate + rate/severity knobs).
 *
 * Guarantees:
 *  - GATE: `cfg.enabled === false` ⇒ `dispatch` is empty (surface-only).
 *  - DEDUP: a fingerprint already in `dispatched` (and still open) is never re-dispatched.
 *  - RATE-LIMIT: `dispatch.length ≤ maxPerCycle` AND `inFlight + dispatch.length ≤ maxInFlight`.
 */
export function planFaultDispatch(
  faults: FaultLite[],
  dispatched: Iterable<string>,
  cfg: FaultTriageConfig,
): FaultTriagePlan {
  const already = new Set(dispatched);
  const open = faults.filter((f) => !f.resolvedAt);
  const openFps = new Set(open.map((f) => f.fingerprint));

  // Prune the dedup ledger to fingerprints that are still open. A resolved (or aged-out) fault drops out
  // — this is the resolve→clear path: clearing a fault frees its fan-out slot and lets a genuine
  // recurrence (errordb re-opens the same fingerprint) re-dispatch.
  const pruned = [...already].filter((fp) => openFps.has(fp));

  // GATE: toggle OFF ⇒ surface only. Still return the pruned ledger so turning it on later doesn't
  // re-dispatch faults resolved while it was off.
  if (!cfg.enabled) return { dispatch: [], nextDispatched: pruned };

  // In-flight = dispatched fingerprints still open (fixes routed but not yet resolved). `pruned` is
  // exactly `already ∩ open`, so its size is the live fan-out.
  const inFlight = pruned.length;
  const slots = clamp(cfg.maxInFlight - inFlight, 0, cfg.maxPerCycle);
  if (slots === 0) return { dispatch: [], nextDispatched: pruned };

  const minRank = rank(cfg.minLevel);
  const candidates = open
    .filter((f) => !already.has(f.fingerprint) && f.count >= cfg.threshold && rank(f.level) >= minRank)
    // Worst first (so under a cap the most severe/frequent faults win the slots): severity, then volume,
    // then fingerprint for a stable, deterministic order.
    .sort((a, b) =>
      rank(b.level) - rank(a.level) || b.count - a.count || a.fingerprint.localeCompare(b.fingerprint),
    );

  const chosen = candidates.slice(0, slots);
  return {
    dispatch: chosen.map((f) => ({ fingerprint: f.fingerprint, level: f.level, title: f.title, count: f.count })),
    nextDispatched: [...pruned, ...chosen.map((f) => f.fingerprint)],
  };
}

/** Count of unresolved faults in a list — the number the Glance inspector shows. */
export function unresolvedCount(faults: FaultLite[]): number {
  return faults.reduce((n, f) => (f.resolvedAt ? n : n + 1), 0);
}

/** The single worst OPEN fault — highest severity, then highest volume, then a stable fingerprint tie-
 *  break — or null when nothing is open. Drives the Glance health dot's colour + reason text (#2541). */
export function worstFault(faults: FaultLite[]): FaultLite | null {
  return faults
    .filter((f) => !f.resolvedAt)
    .sort((a, b) => rank(b.level) - rank(a.level) || b.count - a.count || a.fingerprint.localeCompare(b.fingerprint))[0] ?? null;
}

/** The director-facing message routing this cycle's faults. One paste covers the batch; the director
 *  runs the emitters (`bsc-issue` → `bsc-assign`) per its protocol and resolves each on land. */
export function faultDispatchPrompt(dispatch: FaultDispatch[]): string {
  const lines = dispatch
    .map((d) => `• [${d.level} · ${d.count}×] ${d.title} (fp ${d.fingerprint})`)
    .join("\n");
  return [
    "[fault-triage] New runtime fault(s) crossed the auto-triage threshold — route a fix for each:",
    lines,
    "For each fault: capture it with `bsc-issue` (a well-formed title + the detail from " +
      "`bsc errors get <fingerprint>`), then `bsc-assign <session>` the worker in whose `owns` lane the " +
      "fault lives (open a GitHub issue first if it should be tracked). When the fix merges to develop, " +
      "clear it: `bsc errors resolve <fingerprint>`.",
  ].join("\n");
}

runtime.shared/lib/fleet/fleetLive.ts:
// Live Fleet data (#412) — PURE mappers from the running app state to the Fleet
// board shapes. The roster comes from the store's launched fleet
// (`fleetPaneStreams`), run/idle from the live `paneStatus` map (#412), and
// blocked/asking/waiting from the coordination log (CoordState). No fabrication —
// GitHub-derived analytics (throughput, merge queue, time-to-land) and token/cost
// accounting are deferred to follow-ups and rendered as explicit "not wired" states.
//
// Framework-free + unit-tested; the store/coord wiring lives in hooks/useFleetLive.

import { hashString } from "@/shared/lib/core/format";
import { resolveByPrecedence, type PrecedenceRule } from "@/shared/lib/algorithms/precedenceResolve";
import type { CoordState } from "./coordination";
import type { AgentStream } from "@/features/planner/fleet/planFleet";
import type { WorkerStatus } from "@/shared/data/fleet";

/** Minimal AgentProfile fields we need for labels/colors (avoids a hard dep). */
export interface ProfileLike { id: string; name: string }

export interface LiveWorker {
  /** pane id, e.g. "t2p0" — the coordination `session` key too. */
  id: string;
  /** display name (the stream name). */
  name: string;
  /** stream/worktree repo. */
  repo: string;
  /** resolved profile label + a stable color. */
  profileLabel: string;
  profileColor: string;
  status: WorkerStatus;
  /** the work item it's on (first owned issue, else the stream name). */
  issue: string;
  /** a short sub-note: the block dep / question / wait reason, when parked. */
  note: string;
  /** count of issues this stream owns. */
  ownedTotal: number;
}

/** Stable color from a string (profile id), matching the loginColor convention. */
function hashColor(s: string): string {
  return `oklch(0.72 0.13 ${hashString(s) % 360})`;
}

/**
 * The live status for a worker pane: coordination wins (a parked worker is
 * asking / waiting / blocked), otherwise the raw run/idle from `paneStatus`
 * ("run" → running, anything else → idle).
 *
 * The precedence is DATA (#3465) — the `PRECEDENCE` table below, resolved by the generic
 * `resolveByPrecedence`. As a chain of `if` returns the ordering existed only in statement order:
 * unreadable as a whole, untestable on its own, and reorderable by accident. The order itself is the
 * decision worth being explicit about — a worker that needs a human must never be hidden behind a
 * mechanical "running", which is why the coordination states sit above the run sample.
 */
const PRECEDENCE: PrecedenceRule<{ paneId: string; coord: CoordState; paneStatus: Record<string, "run" | "on" | "idle"> }, WorkerStatus>[] = [
  { state: "asking", when: ({ paneId, coord }) => coord.asking.some(a => a.session === paneId) },
  { state: "waiting", when: ({ paneId, coord }) => coord.waiting.some(w => w.session === paneId) },
  { state: "blocked", when: ({ paneId, coord }) => coord.waiters.some(w => w.session === paneId) },
  // Active work wins over a parked state (a dispatched maintenance worker is running, not parked).
  { state: "running", when: ({ paneId, paneStatus }) => paneStatus[paneId] === "run" },
  // A finished worker parked in maintenance (#1957) reads `maintenance`, not plain idle.
  { state: "maintenance", when: ({ paneId, coord }) => coord.maintaining.some(m => m.session === paneId) },
];

export function statusForPane(
  paneId: string, coord: CoordState, paneStatus: Record<string, "run" | "on" | "idle">,
): WorkerStatus {
  return resolveByPrecedence({ paneId, coord, paneStatus }, PRECEDENCE, "idle");
}

/** The parked-state note for a pane (question / wait reason / block deps), or "". */
function noteForPane(paneId: string, coord: CoordState): string {
  const ask = coord.asking.find(a => a.session === paneId);
  if (ask) return ask.question;
  const wait = coord.waiting.find(w => w.session === paneId);
  if (wait) return wait.reason;
  const blocked = coord.waiters.find(w => w.session === paneId);
  if (blocked) {
    const deps = blocked.deps.map(d => (d.kind === "issue" ? `#${d.number}` : d.kind === "contract" ? `contract:${d.name}` : d.kind)).join(", ");
    return deps ? `blocked on ${deps}` : "blocked";
  }
  const maint = coord.maintaining.find(m => m.session === paneId);
  if (maint) return maint.note || "owned issues complete — standing by";
  return "";
}

export interface BuildWorkersInput {
  /** the launched fleet: pane id → its stream, keyed by the #1176 IDENTITY id (`<key>:<stream>`). */
  fleetPaneStreams: Record<string, AgentStream>;
  paneStatus: Record<string, "run" | "on" | "idle">;
  coord: CoordState;
  /** The open tabs (with their minted `paneIds`), so a worker whose tab was closed is dropped. */
  tabs: { paneIds?: string[] }[];
  disabledPanes: Record<string, boolean>;
  profiles: ProfileLike[];
}

/** Build the live worker roster from the running fleet. Only panes whose tab is
 *  still open and not disabled are included (a launched-then-closed fleet drops). */
export function buildLiveWorkers(input: BuildWorkersInput): LiveWorker[] {
  const { fleetPaneStreams, paneStatus, coord, tabs, disabledPanes, profiles } = input;
  const profById = new Map(profiles.map(p => [p.id, p]));
  // A worker is live only while its pane is still one of an OPEN tab's minted cells (#1176): the
  // fleet/triage launch records each pane's IDENTITY id (`<key>:<stream>`) on the tab's `paneIds`, so
  // a closed tab drops its workers. (The old positional `tabOfPane` parse matched only `t<idx>p<idx>`
  // and so silently dropped EVERY identity-keyed pane — the "No fleet running" bug.)
  const livePaneIds = new Set(tabs.flatMap(t => t.paneIds ?? []));
  const workers: LiveWorker[] = [];
  for (const [paneId, stream] of Object.entries(fleetPaneStreams)) {
    if (!livePaneIds.has(paneId) || disabledPanes[paneId]) continue;
    const prof = stream.profile ? profById.get(stream.profile) : undefined;
    workers.push({
      id: paneId,
      name: stream.name,
      repo: stream.repo,
      profileLabel: prof?.name ?? stream.profile ?? "—",
      profileColor: stream.profile ? hashColor(stream.profile) : "var(--fg-dim)",
      status: statusForPane(paneId, coord, paneStatus),
      issue: stream.issues[0] ?? stream.name,
      note: noteForPane(paneId, coord),
      ownedTotal: stream.issues.length,
    });
  }
  // Stable order: by tab/pane id.
  return workers.sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }));
}

/** Worker counts per status (drives the donut). */
export function statusCounts(workers: LiveWorker[]): Partial<Record<WorkerStatus, number>> {
  const c: Partial<Record<WorkerStatus, number>> = {};
  for (const w of workers) c[w.status] = (c[w.status] ?? 0) + 1;
  return c;
}

export interface FleetKpis {
  total: number;
  active: number;       // running
  needAttention: number; // blocked | asking | waiting
  idle: number;
  maintenance: number;  // parked & ready — finished every owned issue, standing by (#1957)
}
export function deriveFleetKpis(workers: LiveWorker[]): FleetKpis {
  const is = (s: WorkerStatus) => workers.filter(w => w.status === s).length;
  return {
    total: workers.length,
    active: is("running"),
    needAttention: is("blocked") + is("asking") + is("waiting"),
    idle: is("idle"),
    maintenance: is("maintenance"),
  };
}

runtime.shared/lib/fleet/fleetRoster.ts:
// Fleet roster (#734) — persists the launched fleet's session roster to the project hub as
// `fleet.roster.tsv`, so the director's `bsc-fleet` shell helper can enumerate every worker
// (console id / stream / repo / branch / role) and, joined with coord.log, each one's state.
//
// The store builds the rows (it knows the pane keys) but stays Tauri-free; this is the
// component-side writer the launch callers use. It ALSO records the durable session ledger (#2405)
// from the same rows, so recovery reads a fact instead of inferring from disk.

import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import { bscWrite } from "@/shared/lib/core/bsc";

/** Write the roster rows to `<hub>/fleet.roster.tsv` AND record each launched agent in the durable
 *  per-project session ledger (#2405). No-op on an empty roster. */
export function publishFleetRoster(projectKey: string, rosterRows: string[]): void {
  if (rosterRows.length === 0) return;
  fireInvoke("write_project_file", {
    projectKey, relpath: "fleet.roster.tsv", contents: rosterRows.join("\n") + "\n",
  }, (e) => console.error("write fleet.roster.tsv failed:", e));
  recordFleetSessions(projectKey, rosterRows);
}

/** Record each launched agent in the durable session ledger (#2405) — the authoritative "these agents
 *  were launched" that survives a clean quit, so recovery can offer to restart the fleet. Best-effort,
 *  fire-and-forget per agent: a failed write never blocks the launch. Fields come straight from the
 *  roster row (`paneId/stream/repo/branch/role`); `cwd` is re-derived from the plan on restart, so it's
 *  left blank here. Exported for the callers/tests; `publishFleetRoster` already invokes it. */
export function recordFleetSessions(projectKey: string, rosterRows: string[]): void {
  for (const row of rosterRows) {
    const [paneId, stream, , , role] = row.split("\t");
    if (!paneId) continue;
    void bscWrite(projectKey, ["plan", "fleet", "session", "set"], {
      paneId,
      // The director row carries "director" in the stream column; a real stream id only for workers.
      streamId: role === "director" ? "" : (stream ?? ""),
      role: role ?? "",
      status: "running",
    }).catch((e) => console.error("record fleet session failed:", e));
  }
}

runtime.shared/lib/fleet/launchGate.ts:
/**
 * Serializes `claude` cold-starts so they don't stampede the shared OAuth
 * credential store.
 *
 * Why: every console launches the `claude` CLI, which on startup reads (and, if
 * the access token is near expiry, refreshes) credentials in the user's home.
 * The OAuth refresh token is single-use and, on Windows, the credentials file is
 * subject to mandatory locking. When a triage/project tab opens it mounts N panes
 * at once, firing N `claude` processes within milliseconds — they race on the
 * same credentials, one wins the refresh, the rest read an invalidated token,
 * fail, and clear the shared store. The visible symptom is *every* session (and
 * any prior login) being asked to log in again. Launching them one at a time,
 * spaced far enough apart for each to finish authenticating, avoids the race.
 *
 * An API key would sidestep this entirely (no refresh dance), but subscription
 * (OAuth) auth is the only option here.
 *
 * NOTE: the inter-launch gap is currently 0 — cold-starts are still serialized
 * (one per tick, strictly ordered via the chain below) but no longer spaced by a
 * wall-clock wait. If multi-pane opens start logging sessions out again, raise
 * {@link CLAUDE_LAUNCH_GAP_MS} to re-introduce spacing.
 */

/** Milliseconds between consecutive `claude` cold-starts.
 *
 *  0 = no wall-clock spacing; launches stay serialized but ramp as fast as the
 *  event loop allows. Raise this (e.g. 2000) if sessions get logged out on
 *  multi-pane opens, which means the OAuth credential race has resurfaced. */
export const CLAUDE_LAUNCH_GAP_MS = 0;

/** Tail of the launch queue — each new cold-start chains after this. */
let chain: Promise<void> = Promise.resolve();
/** Pane ids that have already cold-started, so tab-switch reconnects skip the gate. */
const launched = new Set<string>();

/**
 * Gate a `claude` cold-start for `key` (a pane id).
 *
 * The first launch resolves immediately; each subsequent *new* launch resolves
 * one `gapMs` after the previous, so launches happen strictly one-at-a-time and
 * spaced out. A `key` that has already launched once resolves immediately and is
 * not re-queued — tab-switch remounts (which reconnect rather than re-spawn) are
 * never delayed.
 *
 * @param key  pane id identifying the session (e.g. `t1p0`)
 * @param gapMs spacing to enforce after this launch (defaults to {@link CLAUDE_LAUNCH_GAP_MS})
 * @returns a promise that resolves when it is this launch's turn to start
 */
export function gateClaudeLaunch(key: string, gapMs: number = CLAUDE_LAUNCH_GAP_MS): Promise<void> {
  if (launched.has(key)) return Promise.resolve();
  launched.add(key);
  const myTurn = chain;
  chain = myTurn.then(() => new Promise<void>((resolve) => setTimeout(resolve, gapMs)));
  return myTurn;
}

/**
 * Forget that `key` has launched, so its next cold-start is gated again. Call
 * this when a session is killed (e.g. console disabled) so a later batch
 * re-enable doesn't bypass the gate.
 */
export function resetLaunchGate(key: string): void {
  launched.delete(key);
}

/** Test-only: clear all gate state. */
export function __resetLaunchGateForTest(): void {
  chain = Promise.resolve();
  launched.clear();
}

runtime.shared/lib/fleet/paneInject.ts:
// Shared app-to-agent message injection (#375). We deliver coordination messages by typing
// into a live claude pane's stdin; doing that naively dumps the text character-by-character
// into the TUI input box, where it interleaves with the TUI's own rendering and reads as a
// garbled wall of text. Wrapping it in BRACKETED PASTE markers makes the terminal hand the
// whole string to the TUI as a single atomic paste (Claude Code shows a "[Pasted text]"
// chip), after which Enter submits it cleanly. Built from char codes so no literal escape
// bytes live in the source. Used by the director pump, CI watcher, and coordinator wakes.
import { safeInvoke } from "@/shared/lib/core/safeInvoke";

const ESC = String.fromCharCode(27);
const CR = String.fromCharCode(13);
const PASTE_START = ESC + "[200~";
const PASTE_END = ESC + "[201~";

/**
 * Inject `text` into a pane as one atomic bracketed paste, then submit with a SEPARATE Enter.
 * The two must be separate writes with a small gap: Claude Code debounces a paste, so a CR
 * glued onto the same write is swallowed as content (a trailing newline) instead of being
 * treated as the submit keypress — which left the message sitting in the input box unsent.
 */
export async function injectPrompt(paneId: string, text: string): Promise<void> {
  await safeInvoke("pty_write", { paneId, data: PASTE_START + text + PASTE_END }, undefined);
  await new Promise((r) => setTimeout(r, 60));
  await safeInvoke("pty_write", { paneId, data: CR }, undefined);
}

runtime.shared/lib/fleet/streamCompletion.ts:
// Progress-gated relaunch (#1004): a triage / fleet re-run reads each issue's status from plan.db and
// must NOT restart a worker whose work is already done. These pure helpers decide, from the current
// issue statuses, which streams have finished and which still have outstanding work to (re)launch.

import type { AgentStream } from "@/features/planner/fleet/planFleet";
import type { PlanIssue } from "@/features/planner/issues/planIssues";

/** Refs of issues a worker has nothing left to do on — `complete` (landed) or `verified` (accepted). */
export function doneIssueRefs(issues: PlanIssue[]): Set<string> {
  return new Set(
    issues.filter((i) => i.status === "complete" || i.status === "verified").map((i) => i.ref),
  );
}

/**
 * Whether a project's BUILD is complete (#2619) — it has planned issues and EVERY one is done
 * (`complete` = landed, `verified` = accepted). The signal the "application complete" banner fires on:
 * all the planned work has landed, so the user can do a verify/preview run. An empty issue set is not
 * "complete" (nothing was planned yet). Pure.
 */
export function projectComplete(issues: PlanIssue[]): boolean {
  return issues.length > 0 && issues.every((i) => i.status === "complete" || i.status === "verified");
}

/**
 * A stream is complete when it owns at least one issue and EVERY one is done — so a relaunch puts its
 * worker into maintenance, not back to building (it already finished). A stream that owns no issues is
 * never "complete" (there's no
 * evidence of finished work; let it launch — e.g. a standing / open-ended worker).
 */
export function streamComplete(stream: AgentStream, done: Set<string>): boolean {
  return stream.issues.length > 0 && stream.issues.every((r) => done.has(r));
}

/**
 * Partition a fleet's streams for a progress-gated relaunch: `active` still have outstanding work and
 * (re)launch to keep building; `maintenance` already finished every owned issue and relaunch INTO the
 * maintenance posture (#1957) — they stay alive + ready for the director to dispatch new lane work,
 * rather than being skipped/ended. Order is preserved.
 */
export function pruneCompletedStreams(
  streams: AgentStream[],
  done: Set<string>,
): { active: AgentStream[]; maintenance: AgentStream[] } {
  const active: AgentStream[] = [];
  const maintenance: AgentStream[] = [];
  for (const st of streams) (streamComplete(st, done) ? maintenance : active).push(st);
  return { active, maintenance };
}

/**
 * Of the live worker panes (`fleetPaneStreams`: pane id → its stream), the ones whose stream has
 * finished every owned issue — so the always-on warden must NOT quarantine them: they're in
 * maintenance (#1957), not building, so post-completion activity is expected, not drift. The warden
 * also lifts any existing quarantine on these. `doneFor(paneId)` yields that pane's project's
 * done-issue refs (the warden reads issue statuses from plan.db per project). Pure (no IPC/store).
 */
export function completedWorkerPanes(
  fleetPaneStreams: Record<string, AgentStream>,
  doneFor: (paneId: string) => Set<string> | undefined,
): Set<string> {
  const out = new Set<string>();
  for (const [paneId, stream] of Object.entries(fleetPaneStreams)) {
    const done = doneFor(paneId);
    if (done && streamComplete(stream, done)) out.add(paneId);
  }
  return out;
}

runtime.shared/lib/fleet/streamGate.ts:
// The dependency gate (#3931) — decide, from a fleet's `dependsOn` graph, which streams may START.
//
// #199 built a lost-wakeup-safe readiness model; #1039 removed its only producer (`bsc-blocked --on`),
// leaving half a circuit: workers still DECLARE COMPLETION, nothing declares DEPENDENCE. This reconnects
// it at LAUNCH rather than mid-task, which is what makes it compatible with #1039 — that issue's
// objection was that a PARKED worker is a worker not working, and nothing here ever parks a started
// session. A stream is simply not started until its upstreams have landed, and once started it never
// waits again.
//
// The launcher is also a better producer than the shell helper ever was: it reads `dependsOn` from
// plan.db, so dependence comes from the PLAN rather than from an agent remembering to run a command.
//
// ── What counts as "landed" ────────────────────────────────────────────────────────────────────────
// Measured on both live fleets before this was written, because the obvious answers are empty:
//
//   | signal                          | network-monitor | cli-typer |
//   |---------------------------------|-----------------|-----------|
//   | issues in plan.db               | 0               | 0         |
//   | coord-log events for the project| 0               | free-text refs, never `session:` |
//   | stream branches merged into HEAD| 38 / 38         | 3 / 10    |
//
// So an issue-keyed latch never satisfies, and a session latch is worse than useless — it HANGS: with
// zero coord events, `network-monitor` would start its 1 root stream and leave the other 37 dark
// forever. Branch-merge state is the signal that actually exists, so the rule is three tiers OR'd —
// each is independent positive evidence that the work is done, and requiring all three reproduces the
// hang this is meant to avoid:
//
//   1. ISSUES DONE   — owns issues and every one is complete/verified. Strongest; needs issues.
//   2. BRANCH MERGED — its branch is an ancestor of the clone's HEAD. The durable floor (#3931).
//   3. SESSION LATCH — a landed/merged/closed coord event on its session, or it is `maintaining`.
//
// Pure (no IO, no store) so the whole rule is exhaustively unit-testable; the callers probe the three
// signals and inject them.

/** The slice of a fleet stream this module reasons about. */
export interface GateStream {
  id: string;
  /** Upstream stream ids. Planning-time sequencing (#1039) — now also the launch gate. */
  dependsOn?: string[];
  /** Issue refs this stream owns. */
  issues?: string[];
}

/** The three landing signals, probed by the caller. */
export interface LandedEvidence {
  /** Issue refs that are `complete`/`verified` (see {@link doneIssueRefs}). */
  doneIssues: ReadonlySet<string>;
  /** Stream ids whose branch is merged into its clone's HEAD (`fleet_landed_streams`). */
  mergedBranches: ReadonlySet<string>;
  /** Stream ids whose SESSION reported done — a coord latch or the maintenance posture. */
  sessionDone: ReadonlySet<string>;
}

/** A stream held back by the gate, and what it is waiting for. */
export interface HeldStream {
  streamId: string;
  /** The unlanded upstreams it is waiting on. Empty only when `deadlocked`. */
  waitingOn: string[];
  /** True when the stream sits in a `dependsOn` CYCLE — it can never become ready on its own. */
  deadlocked: boolean;
}

export interface GatePartition {
  /** Every dep landed — start these now. */
  ready: GateStream[];
  /** Already landed — these relaunch into MAINTENANCE, not build. */
  landed: GateStream[];
  /** Not started; registered as waiters until their upstreams land. */
  held: HeldStream[];
}

/**
 * Which streams have LANDED — tier 1 OR tier 2 OR tier 3 (see the module header for why it is an OR).
 *
 * Tier 1 mirrors `streamComplete`: a stream must own at least one issue for its issue set to be
 * evidence — a stream with no issues has nothing to be "all done", so an empty `issues[]` is NOT
 * vacuous completion. Without that guard every stream on a 0-issue fleet would read as finished.
 */
export function landedStreams(streams: readonly GateStream[], ev: LandedEvidence): Set<string> {
  const out = new Set<string>();
  for (const s of streams) {
    const issues = s.issues ?? [];
    const byIssues = issues.length > 0 && issues.every((r) => ev.doneIssues.has(r));
    if (byIssues || ev.mergedBranches.has(s.id) || ev.sessionDone.has(s.id)) out.add(s.id);
  }
  return out;
}

/**
 * The stream ids that can never become ready because they sit in (or downstream of) a `dependsOn`
 * cycle among UNLANDED streams. A landed stream breaks a cycle — its dep edges no longer matter — so
 * the search runs over the unlanded subgraph only.
 *
 * Iterative Kahn peel rather than an SCC pass: repeatedly remove unlanded streams whose deps are all
 * satisfiable, and whatever cannot be peeled is either in a cycle or downstream of one. Both cases are
 * equally stuck and equally worth surfacing, so they are reported together (#3931 slice 4 renders them).
 */
export function deadlockedStreams(streams: readonly GateStream[], landed: ReadonlySet<string>): Set<string> {
  const unlanded = streams.filter((s) => !landed.has(s.id));
  const known = new Set(streams.map((s) => s.id));
  // Seed with everything already satisfiable: landed streams, plus any dep naming a stream that isn't
  // in this fleet at all (a dangling id can never land, but it also isn't a CYCLE — treating it as a
  // cycle would mislabel a plan typo as a deadlock, so it stays a plain unmet dep).
  const settled = new Set<string>(landed);
  let progressed = true;
  const remaining = new Map(unlanded.map((s) => [s.id, s.dependsOn ?? []]));
  while (progressed) {
    progressed = false;
    for (const [id, deps] of remaining) {
      // A dep outside the fleet is not resolvable here — it blocks, but it is not a cycle. Skip it
      // for the peel so it doesn't make its dependents look deadlocked.
      if (deps.every((d) => settled.has(d) || !known.has(d))) {
        settled.add(id);
        remaining.delete(id);
        progressed = true;
      }
    }
  }
  return new Set(remaining.keys());
}

/**
 * Partition a fleet for launch: what starts now, what is already done, and what waits.
 *
 * Readiness does NOT cascade within one pass — a stream is ready only when every dep has actually
 * LANDED, never when a dep is merely *about to start*. That is the whole point of the gate: `B` waits
 * for `A` to finish, not for `A` to launch. Order is preserved within each bucket.
 */
export function partitionByDeps(streams: readonly GateStream[], ev: LandedEvidence): GatePartition {
  const landedIds = landedStreams(streams, ev);
  const deadlocked = deadlockedStreams(streams, landedIds);
  const ready: GateStream[] = [];
  const landed: GateStream[] = [];
  const held: HeldStream[] = [];
  for (const s of streams) {
    if (landedIds.has(s.id)) { landed.push(s); continue; }
    const waitingOn = (s.dependsOn ?? []).filter((d) => !landedIds.has(d));
    if (waitingOn.length === 0) { ready.push(s); continue; }
    held.push({ streamId: s.id, waitingOn, deadlocked: deadlocked.has(s.id) });
  }
  return { ready, landed, held };
}

/** A user-facing reason for why a stream is held — the string the Glance node overlay shows (#3931). */
export function heldReason(h: HeldStream): string {
  const list = h.waitingOn.join(", ");
  if (h.deadlocked) return `dependency cycle — cannot start (waiting on ${list})`;
  return h.waitingOn.length === 1
    ? `waiting on ${list} to land`
    : `waiting on ${h.waitingOn.length} upstreams to land (${list})`;
}

/**
 * Tier 3's producer: the stream ids of a project's sessions that reported DONE (#3931 slice 3).
 *
 * A worker that finishes its lane parks in maintenance (#1957) by emitting `bsc-maintain`, which the
 * coord replay folds into `CoordState.maintaining`. That is the one per-session completion signal that
 * is actually populated in the live log — unlike `landed`, whose payload refs are free text and whose
 * emitting session is dropped by the parse. Entries are pane ids (`<projectKey>:<streamId>`), so this
 * keeps only the rows for THIS project and strips the prefix back to a stream id.
 *
 * Matching is on the exact `<projectKey>:` prefix, and only the FIRST separator is consumed — a triage
 * pane (`<key>:<repo>:triage`) therefore yields `<repo>:triage`, which is not a stream id and simply
 * never matches a `dependsOn` entry. Pure.
 */
export function sessionDoneStreams(
  maintaining: ReadonlyArray<{ session: string }>,
  projectKey: string,
): Set<string> {
  const prefix = `${projectKey}:`;
  const out = new Set<string>();
  for (const m of maintaining) {
    if (m.session.startsWith(prefix)) {
      const id = m.session.slice(prefix.length);
      if (id) out.add(id);
    }
  }
  return out;
}

runtime.shared/lib/fleet/studioNetworkDrive.ts:
// The studio-network pump's PURE decision core (#2940). The app-owned studio sessions
// (planner · designer · librarian) commission artifacts from each other over `coord.log`
// (the `commission`/`deliver` edge, slice 1). This module turns the folded `CoordState.commissions`
// into the two actuations the pump performs — with NO React, Tauri, or timers — so every routing
// rule is unit-tested. The thin actuator (`useStudioNetworkPump`) owns polling, `injectPrompt`,
// the once-guards, and the lazy-mount store flag.
//
// The two actuations:
//   1. AUTHOR TASK — an open, undelivered commission's spec is injected into the TARGET studio
//      session (designer → `bsc ui`, librarian → `bsc graph`), once the target has been reachable
//      long enough to accept input (the settle gate; Claude queues input typed mid-turn).
//   2. DELIVER-BACK — once a `deliver` stamps `delivered` on a commission, the authored artifact id
//      is injected back into the REQUESTER's pane (which is the live planning/designer session).
import type { OpenCommission } from "./coordination.types";
import { refKey } from "./coordinationState";
import {
  DESIGN_STUDIO_SESSION_ID,
  ALGORITHMS_STUDIO_SESSION_ID,
} from "@/shared/lib/session/systemSessions";

/** The commissionable studio nodes. The planner is a requester, never a target (plan-only). */
export type StudioTarget = "designer" | "librarian";

/** Target → its app-owned studio session pane id (where the author task is injected). */
export const STUDIO_PANE: Record<StudioTarget, string> = {
  designer: DESIGN_STUDIO_SESSION_ID,
  librarian: ALGORITHMS_STUDIO_SESSION_ID,
};

/** Human label + the store CLI a target authors into — for the injected task prose. */
const TARGET_KIT: Record<StudioTarget, { noun: string; list: string; deliver: string }> = {
  designer:  { noun: "component", list: "bsc ui list",         deliver: "bsc ui" },
  librarian: { noun: "algorithm", list: "bsc graph impl list", deliver: "bsc graph impl set" },
};

export function isStudioTarget(t: string): t is StudioTarget {
  return t === "designer" || t === "librarian";
}

/** A commission is "open" until a `deliver` stamps its artifact id. */
export function isOpen(c: OpenCommission): boolean {
  return c.delivered === undefined;
}

/** A stable per-commission key for the pump's once-guards (the commission id already is one). */
export function commissionKey(c: OpenCommission): string {
  return c.id;
}

/** Distinct studio targets that have at least one OPEN commission — the set of sessions the pump
 *  must keep reachable (drives the lazy-mount hosts). Unknown targets (a stray/bad line) are ignored. */
export function activeTargets(commissions: OpenCommission[]): StudioTarget[] {
  const out: StudioTarget[] = [];
  for (const c of commissions) {
    if (isOpen(c) && isStudioTarget(c.target) && !out.includes(c.target)) out.push(c.target);
  }
  return out;
}

/** The prompt injected into a target studio session to author (or reuse) the commissioned artifact.
 *  Reuse-first is baked in (slice 3 makes the requester check too); the deliver line closes the loop
 *  so the pump can route the id back. */
export function authorTaskPrompt(c: OpenCommission, target: StudioTarget): string {
  const t = TARGET_KIT[target];
  const ref = c.ref ? ` (ref: ${refKey(c.ref)})` : "";
  return (
    `A planning session commissioned a ${t.noun}${ref}: ${c.body}\n` +
    `First reuse-check with \`${t.list}\` — if an existing ${t.noun} fits, use it. ` +
    `Otherwise author it with \`${t.deliver}\`. ` +
    `When done, run \`bsc-deliver ${c.id} <${t.noun}Id>\` so the requester receives it.`
  );
}

/** The prompt injected back into the REQUESTER's pane once the target delivers. */
export function deliverBackPrompt(c: OpenCommission): string {
  const noun = isStudioTarget(c.target) ? TARGET_KIT[c.target].noun : "artifact";
  return (
    `The ${c.target} delivered the ${noun} you commissioned ("${c.body}"): ` +
    `\`${c.delivered}\`. You can bind/reference it now.`
  );
}

/** One actuation the pump should perform this tick. */
export interface Injection {
  paneId: string;
  prompt: string;
  /** Once-guard key (`author:<id>` / `deliver:<id>`) so the same message is never re-injected. */
  key: string;
}

/** AUTHOR-TASK injections due now: open, undelivered commissions to a known target whose session has
 *  been reachable for at least `settleMs` (so `pty_create` + boot are past) and which have not been
 *  injected yet. `activatedAt` maps target → the ms the pump first saw it active. */
export function authorInjections(
  commissions: OpenCommission[],
  activatedAt: Partial<Record<StudioTarget, number>>,
  now: number,
  settleMs: number,
  alreadyInjected: ReadonlySet<string>,
): Injection[] {
  const out: Injection[] = [];
  for (const c of commissions) {
    if (!isOpen(c) || !isStudioTarget(c.target)) continue;
    const key = `author:${c.id}`;
    if (alreadyInjected.has(key)) continue;
    const since = activatedAt[c.target];
    if (since === undefined || now - since < settleMs) continue;
    out.push({ paneId: STUDIO_PANE[c.target], prompt: authorTaskPrompt(c, c.target), key });
  }
  return out;
}

/** DELIVER-BACK injections due now: commissions whose `delivered` is set and whose result has not
 *  been surfaced to the requester yet. The requester (`from`) is a live session (the planner/designer
 *  that emitted the commission), so no settle gate is needed. */
export function deliverBackInjections(
  commissions: OpenCommission[],
  alreadySurfaced: ReadonlySet<string>,
): Injection[] {
  const out: Injection[] = [];
  for (const c of commissions) {
    if (c.delivered === undefined) continue;
    const key = `deliver:${c.id}`;
    if (alreadySurfaced.has(key)) continue;
    out.push({ paneId: c.from, prompt: deliverBackPrompt(c), key });
  }
  return out;
}

runtime.shared/lib/fleet/useCoordLog.ts:
// useCoordLog (#1495) — one home for reading + replaying the coordination log. The
// `read coord log → ingestCoordLog(lines, emptyCoordState())` pair was hand-rolled in
// every fleet hook (the coordinator, the director pump, the worker auto-end, the live fleet view,
// the tunnel control). This centralizes the read so a change to the log format or the limit lands
// in one place. The read is `bsc logs tail coord --oldest` over the `bsc` bridge (#2144) — raw,
// chronological (oldest-first) lines, the same shape the old `read_coord_log` command returned.
//
//  - readCoordState(limit): the imperative read. Returns `null` on a read FAILURE (so the actuator
//    loops keep their "skip this tick, don't touch ref state" guard) and the full ingest result
//    otherwise. A successful read of an EMPTY log returns an empty-but-non-null result.
//  - useCoordLog({ limit }): the hook for views that just want the latest state — re-reads
//    event-driven on `logs://coord` changes and returns the latest `{ state, ready, answered }`,
//    keeping the last good result across a transient read failure.

import { useState } from "react";
import { logsTail } from "@/shared/lib/core/logsBridge";
import { useLogStream } from "@/shared/hooks/useLogStream";
import { ingestCoordLog, emptyCoordState } from "./coordination";

/** The replayed coord state (`state`/`ready`/`answered`) plus the raw `lines` — the director
 *  pump still needs the unparsed log for its cursor-based heartbeat. */
export type CoordResult = ReturnType<typeof ingestCoordLog> & { lines: string[] };

/** Read + replay the coordination log. `null` on a read failure; the replay + raw lines otherwise. */
export async function readCoordState(limit = 1000): Promise<CoordResult | null> {
  // In-process read (#3630) — `null` fallback preserves the "read failed → skip this tick" guard.
  const lines = await logsTail("coord", limit, true, null);
  if (!lines) return null;
  return { lines, ...ingestCoordLog(lines, emptyCoordState()) };
}

interface UseCoordLogOptions {
  /** Lines to read from the tail of the log (default 1000). */
  limit?: number;
}

/** Poll the coordination log and return the latest replay. Keeps the last good result on a
 *  transient read failure rather than blanking. */
export function useCoordLog(opts: UseCoordLogOptions = {}): CoordResult {
  const { limit = 1000 } = opts;
  const [result, setResult] = useState<CoordResult>(() => ({ lines: [], ...ingestCoordLog([], emptyCoordState()) }));
  // Event-driven (#3638): re-read + replay only when the coord log changes (plus mount + a slow
  // backstop), instead of polling on a fixed cadence — the `logs://coord` change event drives the read.
  useLogStream("coord", async (isCancelled) => {
    const res = await readCoordState(limit);
    if (isCancelled() || !res) return;
    setResult(res);
  }, [limit]);
  return result;
}

runtime.shared/lib/fleet/workerAudit.ts:
// Done-time per-worker audit (#920). Assembles the concrete output of a finished worker —
// what it changed (diff/commits), where it shipped (the PR), and the raw conversation
// (Claude's transcript) — by reading the worktree + GitHub at view time. Every piece is
// tolerant (the backend commands return empty/None on failure), so a partial worktree still
// renders what it can. The durable, structured record (tool/coord/decisions) is already shown
// on the worker page; this is the snapshot it was missing.

import { safeInvoke } from "@/shared/lib/core/safeInvoke";

export interface WorktreeCommit {
  hash: string;
  subject: string;
  author: string;
  date: string;
}

export interface BranchPr {
  number: number;
  url: string;
  /** OPEN | CLOSED | MERGED */
  state: string;
  merged: boolean;
}

export interface DoneAudit {
  /** Current branch of the worktree. */
  branch: string;
  /** Recent commits on the branch, newest first. */
  commits: WorktreeCommit[];
  /** Uncommitted changed files (vs HEAD + untracked). */
  changedFiles: string[];
  /** The PR opened from the branch, or null when there's none / gh is unavailable. */
  pr: BranchPr | null;
  /** Path to Claude's transcript `.jsonl`, or null when there's no history. */
  transcriptPath: string | null;
}

/**
 * Assemble the done-time audit for a worker's worktree `cwd` (and its `repo`, for the PR
 * lookup). Never rejects — each command failure degrades to an empty value.
 */
export async function loadDoneAudit(cwd: string, repo: string): Promise<DoneAudit> {
  if (!cwd) return { branch: "", commits: [], changedFiles: [], pr: null, transcriptPath: null };
  const [branch, commits, changedFiles, transcriptPath] = await Promise.all([
    safeInvoke<string>("read_worktree_branch", { cwd }, ""),
    safeInvoke<WorktreeCommit[]>("read_worktree_commits", { cwd, limit: 20 }, []),
    safeInvoke<string[]>("read_worktree_changes", { cwd }, []),
    safeInvoke<string | null>("claude_transcript_path", { cwd }, null),
  ]);
  const pr = branch && repo
    ? await safeInvoke<BranchPr | null>("find_branch_pr", { repo, branch }, null)
    : null;
  return { branch, commits, changedFiles, pr, transcriptPath };
}

runtime.shared/lib/fleet/workerEnd.ts:
// Worker completeness classifier (#920). When a fleet worker's PTY exits, we decide its
// resting state from plan.db OWNED-ISSUE STATUS — the structured, per-issue, recovery-durable
// source of truth — NOT the worker's free-text "I'm done". coord.log landed/merged is a
// tiebreaker that surfaces the "marked complete but the PR never merged" gap, but does not
// block the card: a worker's card closes on worker-finished (`complete`), while `verified` /
// merged is the director's separate confirmation, surfaced in the summary.

import { isSatisfied, parseRef, type CoordState } from "./coordination";
import type { WorkerEndState } from "@/store/types";

/** One owned issue's ref + plan.db lifecycle status. */
export interface OwnedIssue {
  ref: string;
  /** open | in_progress | blocked | complete | verified | failed */
  status: string;
  /** Owning fleet stream id (#3944). Present on `bsc plan list --full` rows; lets a caller read a
   *  project's issues ONCE and partition by stream in memory instead of querying per stream. */
  stream?: string;
}

export interface WorkerEndVerdict {
  state: WorkerEndState;
  summary: string;
}

// plan.db issue lifecycle buckets (crates/plandb STATUSES).
/** The worker did its part. EXPORTED (#4050) so the progress bar counts "done" the same way the
 *  finished-verdict does — a second definition would eventually disagree with the card that says
 *  "finished", and the two would drift silently. */
export const TERMINAL_GOOD = new Set(["complete", "verified"]); // the worker did its part
const STILL_RUNNING = new Set(["open", "in_progress"]);   // stopped early
const TERMINAL_BAD = new Set(["blocked", "failed"]);      // needs attention

/**
 * Classify a finished worker from its owned issues + the coordination state.
 *
 * Precedence: any blocked/failed ⇒ `blocked`; else any still-open ⇒ `needs-attention`
 * (stopped early — never silently "done"); else all complete/verified ⇒ `done`. An empty
 * owned-issue set is `needs-attention` (we can't confirm completion from the DB).
 *
 * The `landed` count (coord.log merged/landed/closed for the owned refs) is reported in the
 * summary so "worker finished" reads distinctly from "work shipped".
 */
export function classifyWorkerEnd(issues: OwnedIssue[], coord: CoordState): WorkerEndVerdict {
  if (issues.length === 0) {
    return { state: "needs-attention", summary: "no owned issues in plan.db — can't confirm completion" };
  }

  let good = 0, running = 0, bad = 0;
  for (const i of issues) {
    if (TERMINAL_BAD.has(i.status)) bad++;
    else if (STILL_RUNNING.has(i.status)) running++;
    else if (TERMINAL_GOOD.has(i.status)) good++;
    else running++; // unknown status ⇒ treat as not-done (conservative)
  }

  const landed = issues.filter((i) => {
    const ref = parseRef(i.ref);
    return ref ? isSatisfied(coord, ref) : false;
  }).length;

  const n = issues.length;
  if (bad > 0) {
    return { state: "blocked", summary: `${bad}/${n} blocked or failed · ${good}/${n} complete` };
  }
  if (running > 0) {
    return { state: "needs-attention", summary: `stopped early — ${running}/${n} still open · ${good}/${n} complete` };
  }
  return { state: "done", summary: `${n}/${n} complete · ${landed}/${n} landed` };
}

