// Shared GitHub display colors (#1492) — one home for the avatar palette and ProjectV2
// option colors that were copy-pasted byte-for-byte across the planner/github views
// (ProjectBoard, Issues, Insights). Feature-agnostic and pure.

/**
 * The discrete avatar palette. Distinct from the continuous-hue `loginColor` in
 * `core/format.ts`: this hashes a login into one of six fixed swatches, which the
 * planner/github board + issue views use for assignee/author avatars.
 */
export const AVATAR_PALETTE = [
  "oklch(0.7 0.13 30)", "oklch(0.7 0.10 220)", "oklch(0.68 0.13 145)",
  "oklch(0.7 0.12 290)", "oklch(0.7 0.14 50)", "oklch(0.65 0.08 195)",
];

/** A stable avatar color hashed from a login into {@link AVATAR_PALETTE}. */
export function avatarColor(login: string): string {
  let h = 0;
  for (const c of login) h = (h * 31 + c.charCodeAt(0)) & 0xffff;
  return AVATAR_PALETTE[h % AVATAR_PALETTE.length];
}

/** GitHub ProjectV2 single-select option color enum → CSS token. */
export const GH_OPTION_COLORS: Record<string, string> = {
  GRAY:   "var(--fg-dim)",
  BLUE:   "var(--info)",
  GREEN:  "var(--success)",
  YELLOW: "oklch(0.78 0.14 70)",
  ORANGE: "var(--accent)",
  RED:    "var(--danger)",
  PINK:   "oklch(0.7 0.18 340)",
  PURPLE: "oklch(0.68 0.13 290)",
};

runtime.shared/lib/github/fleetGithub.ts:
// Fleet GitHub-derived panels (#415) — PURE mappers over GitHub REST payloads
// aggregated across the fleet's repos: throughput (issues landed vs PRs merged),
// the director merge queue (open PRs + CI status), and time-to-land (merged-PR
// durations). Reuses the day-bucketing + review-latency helpers from
// repoPulseLive. Framework-free + unit-tested; fetch orchestration is in
// hooks/useFleetGithub.
import { mapReviewLatency, medianLatencyH, type GhPull } from "./repoPulseLive";
import { orderByRank } from "@/shared/lib/algorithms/orderByRank";
import { windowedTally } from "@/shared/lib/algorithms/windowedTally";
import type { GhIssueItem } from "@/shared/lib/github/types";

export type { GhPull };
// The issue-row shape (the `issues` endpoint also returns PRs — rows with `pull_request` set are
// PRs, excluded from "issues"). Canonical now lives in shared/lib/github/types (#1528); re-exported
// so existing importers (useFleetGithub, the tests) keep their `from "./fleetGithub"` import.
export type { GhIssueItem };

/** Combined commit status for a PR head (`commits/{sha}/status`). */
export type GhStatusState = "success" | "pending" | "failure" | "error" | string;

export interface ThroughputSlice { labels: string[]; landed: number[]; merged: number[] }

/**
 * Issues landed (closed, non-PR) vs PRs merged, per day over the window.
 *
 * The bucketing is the generic `windowedTally` (#3465), which is what guarantees the two series are
 * ALIGNED — one shared window, one entry per label in both. Tallying each series separately (as this
 * did) leaves nothing checking that they line up, and a chart layering them cannot tell.
 */
export function mapThroughput(pulls: GhPull[], issues: GhIssueItem[], days: number, now: Date): ThroughputSlice {
  const { labels, series } = windowedTally(
    {
      landed: issues.filter(i => !i.pull_request && i.closed_at).map(i => i.closed_at),
      merged: pulls.map(p => p.merged_at),
    },
    days,
    now,
  );
  return { labels, landed: series.landed, merged: series.merged };
}

/** A PR awaiting integration, with its repo + CI state. */
export interface MergeQueueInput {
  pr: GhPull;
  repo: string;
  /** combined commit status for the head, or null if unknown. */
  status: GhStatusState | null;
}
export interface MergeQueueRow {
  pr: string;
  repo: string;
  title: string;
  state: "green" | "running" | "blocked" | "draft";
  checks: string;
}

/** The merge queue's ATTENTION order (#3465): ready-but-failing first (needs a human), then running,
 *  then green, then drafts. Declared as data + applied by the generic `orderByRank` — it was a chain
 *  of magic numbers inside a comparator, where this domain decision could not be read as a list. */
const MERGE_QUEUE_ORDER: MergeQueueRow["state"][] = ["blocked", "running", "green", "draft"];

/** Map open PRs (+ CI status) to merge-queue rows. Draft PRs read "draft";
 *  otherwise green/running/blocked from the combined commit status. */
export function mapMergeQueue(items: MergeQueueInput[]): MergeQueueRow[] {
  const rows = items.map(({ pr, repo, status }): MergeQueueRow => {
    const state: MergeQueueRow["state"] =
      pr.draft ? "draft"
      : status === "success" ? "green"
      : status === "pending" || status === null ? "running"
      : "blocked";
    const checks = pr.draft ? "draft" : status ?? "—";
    return { pr: `#${pr.number}`, repo, title: pr.title, state, checks };
  });
  return orderByRank(rows, (r) => r.state, MERGE_QUEUE_ORDER);
}

// Re-export the shared latency mappers so the Fleet hook imports from one place.
export { mapReviewLatency as mapTimeToLand, medianLatencyH };

export interface FleetThroughputKpis {
  landedToday: number;
  prsMergedWeek: number;
  avgLandH: number;
}
export function deriveThroughputKpis(throughput: ThroughputSlice, pulls: GhPull[], now: Date): FleetThroughputKpis {
  const within = (iso: string | null, ms: number) => !!iso && (now.getTime() - new Date(iso).getTime()) <= ms;
  return {
    landedToday: throughput.landed[throughput.landed.length - 1] ?? 0,
    prsMergedWeek: pulls.filter(p => within(p.merged_at, 7 * 86_400_000)).length,
    avgLandH: medianLatencyH(pulls.filter(p => within(p.merged_at, 14 * 86_400_000))),
  };
}

runtime.shared/lib/github/github.ts:
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { resolveGithubToken } from "./repoCredentials";

/**
 * Default in-memory freshness window. Within this many seconds of the last fetch,
 * a revisit is served straight from the backend cache with **no network call** —
 * so navigating between screens doesn't refetch GitHub every time. After the
 * window the next call revalidates cheaply (ETag → 304). `force` (manual refresh)
 * always bypasses it; pass `maxAgeSecs: 0` to always revalidate-on-view.
 */
export const DEFAULT_MAX_AGE_SECS = 300;

export interface GithubRequestOpts {
  /** Serve the cached body without any network call when it's younger than this
   *  (seconds). Defaults to {@link DEFAULT_MAX_AGE_SECS}; pass 0 to always revalidate. */
  maxAgeSecs?: number;
  /** Bypass the cache + ETag and force a fresh fetch (manual refresh). */
  force?: boolean;
}

/** A `github_request` failure that is a 401 — the stored token is expired/revoked. */
export function isGithubAuthError(e: unknown): boolean {
  const s = String(e);
  return s.includes("401") || s.includes("Bad credentials");
}

/**
 * Match the backend's typed rate-limit error (#2448): `github rate-limited until <epoch secs>` —
 * raised when GitHub's quota is exhausted (403/429 + `X-RateLimit-Remaining: 0` / `Retry-After`)
 * and while the backend's in-memory gate short-circuits further requests.
 *
 * @returns the reset time in epoch **milliseconds**, or null for any other failure.
 */
export function rateLimitedUntil(e: unknown): number | null {
  const m = /github rate-limited until (\d+)/.exec(String(e));
  return m ? Number(m[1]) * 1000 : null;
}

/** The quiet inline wording for a rate-limited query (#2448), or null for any other error —
 *  callers render this as a dim note instead of the red error banner. */
export function rateLimitNote(e: unknown): string | null {
  const until = rateLimitedUntil(e);
  if (until === null) return null;
  const at = new Date(until).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
  return `GitHub rate limit reached — showing cached data; retrying after ${at}.`;
}

/**
 * Call the GitHub REST API through the ETag-validated backend cache (`github_request`).
 *
 * - Pulls the token from the store, so callers just pass a path.
 * - Passes `maxAgeSecs`/`force` through to the cache: within `maxAgeSecs` the cached
 *   body is served with no network call; `force` bypasses the cache for a manual refresh.
 *   Otherwise the backend revalidates cheaply with `If-None-Match` (304 → cached).
 * - On a 401 (expired/revoked PAT) it flips the app to disconnected via
 *   {@link markGithubTokenInvalid} so the UI prompts a reconnect instead of
 *   silently 401-looping, then rethrows.
 */
export async function githubRequest<T>(path: string, opts: GithubRequestOpts = {}): Promise<T> {
  // Repo-scoped credentials (#158): a request targeting a repo with an assigned
  // fine-grained token uses it instead of the global PAT (so a session can't reach
  // other repos via the proxy); everything else uses the global token.
  const s = useAppStore.getState();
  const token = resolveGithubToken(path, s.repoGithubTokens, s.githubToken);
  try {
    return await invoke<T>("github_request", {
      token,
      path,
      maxAgeSecs: opts.maxAgeSecs ?? DEFAULT_MAX_AGE_SECS,
      force: opts.force,
    });
  } catch (e) {
    if (isGithubAuthError(e)) useAppStore.getState().markGithubTokenInvalid();
    throw e;
  }
}

/**
 * Call the GitHub GraphQL API through the backend cache (`github_graphql`).
 * GraphQL has no ETag, so the cache is purely time-windowed: within `maxAgeSecs`
 * (default {@link DEFAULT_MAX_AGE_SECS}) the cached result is served with no
 * network call; otherwise it re-POSTs. `force` bypasses. 401 → disconnect, as with
 * {@link githubRequest}.
 */
export async function githubGraphql<T>(
  query: string,
  variables: Record<string, unknown> | null,
  opts: GithubRequestOpts = {},
): Promise<T> {
  const token = useAppStore.getState().githubToken;
  try {
    return await invoke<T>("github_graphql", {
      token,
      query,
      variables,
      maxAgeSecs: opts.maxAgeSecs ?? DEFAULT_MAX_AGE_SECS,
      force: opts.force,
    });
  } catch (e) {
    if (isGithubAuthError(e)) useAppStore.getState().markGithubTokenInvalid();
    throw e;
  }
}

/** Drop the backend's cached GitHub responses (call on connect / disconnect / re-auth). */
export function clearGithubCache(): Promise<void> {
  return invoke("github_cache_clear");
}

runtime.shared/lib/github/githubProbe.ts:
// Incremental GitHub sync via updatedAt probes (#2448, epic #2444) — the "version-probe pass" the
// api.rs cache comment anticipated. GraphQL has no ETag, so past the backend TTL a heavy query
// always re-POSTs; these probes make that re-POST conditional on the boards actually having MOVED:
//
//  - Projects set (the planner/glance PROJECTS_QUERY): a light `projectsV2 { id updatedAt }` probe
//    diffs against the persisted githubState records (#2446). Unchanged ⇒ the records themselves
//    are returned (expanded via minimalToGhProject — the round-trip is exact), so the caller's
//    setGithubState re-stamps fetchedAt and the heavy `items(first:100)` scan is skipped entirely.
//    The heavy query is ONE shot for all boards, so the probe gates the whole query, not per board.
//  - Single board (the BOARD/ISSUES/INSIGHTS `node(id)` queries): probe that board's updatedAt and
//    compare with the updatedAt recorded at the LAST heavy fetch of that board. Unchanged ⇒ the
//    heavy query runs with a LONG maxAgeSecs, so the backend TTL cache serves its copy past the
//    default window (extending the maxAgeSecs semantics, not fighting them); moved ⇒ force a
//    fresh POST.
//
// The probes ride the same backend TTL cache (default window), so within the window they are
// cache-hits too — the steady-state cost past the TTL is one light probe per window, and the
// heavy POST only when something actually changed.

import { githubGraphql } from "./github";
import { minimalToGhProject, type GhProjectShape, type MinimalGhProject } from "./githubState";

/** One board as the probes carry it — identity + version cursor only. */
export interface ProbeNode {
  id: string;
  updatedAt: string;
}

/** The light whole-set probe — same `viewer.projectsV2(first:20)` window as PROJECTS_QUERY, but
 *  only the version cursor per board (no items scan, no repositories). */
export const PROJECTS_PROBE_QUERY = `{ viewer { projectsV2(first: 20) { nodes { id updatedAt } } } }`;

/** The light single-board probe for the `node(id)` screens (Board / Issues / Insights). */
export const BOARD_PROBE_QUERY = `query($id:ID!){ node(id:$id){ ... on ProjectV2 { updatedAt } } }`;

/** How long an unchanged board's heavy `node(id)` query may serve the backend's TTL-cached copy.
 *  Long but bounded — the entry is in-memory (process-lifetime) and any real change moves
 *  `updatedAt`, which forces a fresh POST on the next probe. */
export const BOARD_UNCHANGED_MAX_AGE_SECS = 6 * 3600;

/**
 * True when the probe set matches the persisted records exactly — same board ids, same
 * `updatedAt`, nothing added or removed. Any mismatch (a moved board, a new board, a deletion)
 * means the heavy fetch must run.
 */
export function probeMatchesRecords(
  probe: ProbeNode[],
  records: Array<Pick<MinimalGhProject, "id" | "updatedAt">>,
): boolean {
  if (probe.length !== records.length) return false;
  const byId = new Map(records.map((r) => [r.id, r.updatedAt]));
  return probe.every((n) => byId.get(n.id) === n.updatedAt);
}

async function defaultProjectsProbe(): Promise<ProbeNode[]> {
  const d = await githubGraphql<{ viewer?: { projectsV2?: { nodes?: ProbeNode[] } } }>(
    PROJECTS_PROBE_QUERY,
    null,
  );
  return d.viewer?.projectsV2?.nodes ?? [];
}

/**
 * Fetch the published-projects set with the updatedAt probe gating the heavy query (#2448).
 *
 * With a persisted baseline (`records`) and no `force`, the light probe runs first; when nothing
 * moved, the records are re-served (expanded — the minimal round-trip is exact) and the heavy
 * fetch is skipped. A probe failure (offline / rate-limited) falls through to the heavy call,
 * which serves the backend cache or surfaces the real error — exactly the pre-probe behavior.
 *
 * @param fetchHeavy the heavy PROJECTS_QUERY fetch (injected: the query lives in the planner feature).
 * @param records    the persisted githubState records to diff against (null/empty ⇒ no baseline ⇒ heavy).
 * @param force      manual refresh — skip the probe and go straight to the heavy fetch.
 * @param fetchProbe probe override for tests; defaults to the live {@link PROJECTS_PROBE_QUERY}.
 */
export async function fetchProjectsWithProbe(args: {
  fetchHeavy: () => Promise<GhProjectShape[]>;
  records: MinimalGhProject[] | null | undefined;
  force?: boolean;
  fetchProbe?: () => Promise<ProbeNode[]>;
}): Promise<GhProjectShape[]> {
  const { fetchHeavy, records, force, fetchProbe = defaultProjectsProbe } = args;
  if (!force && records?.length) {
    let probe: ProbeNode[] | null = null;
    try {
      probe = await fetchProbe();
    } catch {
      // Fall through to the heavy call (see the contract above).
    }
    if (probe && probeMatchesRecords(probe, records)) return records.map(minimalToGhProject);
  }
  return fetchHeavy();
}

// boardId → the board's updatedAt at the LAST heavy fetch through fetchBoardWithProbe.
// Module-level (like glance's localPublishedCache) so it survives screen remounts;
// process-lifetime, matching the backend cache entries it gates.
const boardBaselines = new Map<string, string>();

/** Test hook: drop the recorded per-board baselines. */
export function resetBoardProbeBaselines(): void {
  boardBaselines.clear();
}

/**
 * The heavy `node(id)` query's cache opts for a probe result vs the recorded baseline (pure).
 * No signal (probe failed, or no baseline yet) ⇒ `{}` — today's default-TTL behavior; unchanged ⇒
 * a long maxAgeSecs so the backend serves its cached copy; moved ⇒ `force` a fresh POST.
 */
export function boardFetchOpts(
  probeUpdatedAt: string | null,
  baseline: string | undefined,
): { maxAgeSecs?: number; force?: boolean } {
  if (!probeUpdatedAt || !baseline) return {};
  if (probeUpdatedAt === baseline) return { maxAgeSecs: BOARD_UNCHANGED_MAX_AGE_SECS };
  return { force: true };
}

/**
 * Run a heavy Projects-v2 `node(id)` query gated by the board's updatedAt probe (#2448): the
 * probe (itself TTL-cached) decides whether the heavy query may serve the backend's cached copy
 * past the default window (unchanged) or must POST fresh (moved).
 *
 * Baseline caveat: the heavy body recorded against the probe's updatedAt may be a TTL-cache copy
 * up to the default window older than the probe — bounded staleness we accept, since any real
 * change moves `updatedAt` again and forces a refresh.
 */
export async function fetchBoardWithProbe<T>(query: string, id: string): Promise<T> {
  let probeUpdatedAt: string | null = null;
  try {
    const d = await githubGraphql<{ node?: { updatedAt?: string } | null }>(BOARD_PROBE_QUERY, { id });
    probeUpdatedAt = d.node?.updatedAt ?? null;
  } catch {
    // Probe failed — run the heavy query exactly as before (default TTL); it serves the backend
    // cache or surfaces the real error itself.
  }
  const data = await githubGraphql<T>(query, { id }, boardFetchOpts(probeUpdatedAt, boardBaselines.get(id)));
  if (probeUpdatedAt) boardBaselines.set(id, probeUpdatedAt);
  return data;
}

runtime.shared/lib/github/githubState.ts:
// Persisted GitHub board state (#2446, epic #2444) — the pure model behind the last-known-projects
// cache. A successful `PROJECTS_QUERY` fetch is boiled down to one MINIMAL record per board
// (identity + lifecycle + progress counts + repos — enough for the Projects column, the Glance
// nodes, and the progress meters offline) and stored as `{ records, fetchedAt }`:
//   - in the zustand store (persisted; the fast-paint CACHE — golden rule: cache, not source of truth),
//   - mirrored into the bsc-project store (`~/.base-studio-code/github-state.json`, via
//     `bsc project github-state set`) so the durable copy is `bsc`-reachable (golden rule #2).
//
// Precedence at the consumers (useGlanceProjects + ProjectsList): live fetch > persisted records >
// local-inventory-only (#2445). The persisted fallback is always FILTERED to projects that still
// exist locally ({@link filterRecordsToLocal}) — a record whose hub was deleted must not resurrect
// the project; only the LIVE fetch can vouch for a GitHub-only board.
//
// Board/Issues/Insights detail (fieldValues, labels, comments) deliberately stays refetch-on-view —
// only this entry-point set persists.

import { projectSlug, sanitizeProjectKey } from "@/shared/lib/core/projectPaths";

/** One `projectsV2` item as the wire carries it (structural twin of publishedModel's GhProjectItem). */
interface GhItemShape { content: { __typename?: string; state?: string } | null }

/**
 * The `projectsV2` node shape this module reads/synthesizes — a structural twin of the planner's
 * `GhProject` (publishedModel.ts), declared here so `shared/` stays feature-agnostic. Anything
 * matching this shape (including `GhProject` itself) interoperates both ways.
 */
export interface GhProjectShape {
  id: string;
  number: number;
  title: string;
  shortDescription: string | null;
  url: string;
  closed: boolean;
  updatedAt: string;
  items: { totalCount: number; nodes: GhItemShape[] };
  repositories: { nodes: Array<{ nameWithOwner: string }> };
}

/** The minimal per-board record that persists (#2446) — identity + lifecycle + progress + repos. */
export interface MinimalGhProject {
  id: string;
  number: number;
  title: string;
  shortDescription: string | null;
  url: string;
  closed: boolean;
  updatedAt: string;
  /** True item count (the fetched item page is capped at 100; this is the headline number). */
  itemsTotalCount: number;
  /** Open issues/PRs among the fetched items (mirrors publishedModel's `projectProgress`). */
  openCount: number;
  /** Closed/merged issues/PRs among the fetched items. */
  closedCount: number;
  /** `nameWithOwner` per linked repository. */
  repos: string[];
}

/** The persisted state: the last successful fetch's records + when it landed (epoch ms). */
export interface GithubState {
  records: MinimalGhProject[];
  fetchedAt: number;
}

/**
 * Boil a fetched `projectsV2` set down to the minimal persisted records. Open/closed counts derive
 * from the fetched item states exactly like `projectProgress` (MERGED counts as closed; a draft
 * item — `content: null` — counts as neither).
 */
export function toMinimalGhProjects(projects: GhProjectShape[]): MinimalGhProject[] {
  return projects.map((p) => {
    let openCount = 0, closedCount = 0;
    for (const n of p.items?.nodes ?? []) {
      const s = n.content?.state;
      if (s === "OPEN") openCount++;
      else if (s === "CLOSED" || s === "MERGED") closedCount++;
    }
    return {
      id: p.id, number: p.number, title: p.title, shortDescription: p.shortDescription,
      url: p.url, closed: p.closed, updatedAt: p.updatedAt,
      itemsTotalCount: p.items?.totalCount ?? 0, openCount, closedCount,
      repos: (p.repositories?.nodes ?? []).map((r) => r.nameWithOwner),
    };
  });
}

/**
 * Expand a persisted record back into the `GhProject` shape the existing published rendering
 * consumes, synthesizing `openCount`/`closedCount` item stubs so `projectProgress` computes the
 * exact same open count + closed fraction the record was derived from. This is what lets the stale
 * overlay reuse the live `ProjectRow`/merge paths untouched.
 */
export function minimalToGhProject(r: MinimalGhProject): GhProjectShape {
  const nodes: GhItemShape[] = [
    ...Array.from({ length: r.openCount }, () => ({ content: { state: "OPEN" } })),
    ...Array.from({ length: r.closedCount }, () => ({ content: { state: "CLOSED" } })),
  ];
  return {
    id: r.id, number: r.number, title: r.title, shortDescription: r.shortDescription,
    url: r.url, closed: r.closed, updatedAt: r.updatedAt,
    items: { totalCount: r.itemsTotalCount, nodes },
    repositories: { nodes: r.repos.map((nameWithOwner) => ({ nameWithOwner })) },
  };
}

/**
 * Keep only the records that still correspond to a LOCAL project — the don't-resurrect rule (#2446).
 * Matching mirrors the #2445 overlay (`buildLocalPublished` / the `mark_published` reconcile): a
 * record covers a local entry when the entry's key equals the record's name-derived
 * `projectSlug(title)` (today's keys) or the legacy `sanitizeProjectKey(title)` (grandfathered
 * title-keyed hubs), or when the titles match case-insensitively.
 *
 * @param records the persisted records (the last-known board state).
 * @param locals  the projects that exist locally — on-disk hubs and/or store drafts (`key` + `title`).
 */
export function filterRecordsToLocal(
  records: MinimalGhProject[],
  locals: Array<{ key: string; title: string }>,
): MinimalGhProject[] {
  if (records.length === 0 || locals.length === 0) return [];
  const keys = new Set(locals.map((l) => l.key));
  const titles = new Set(locals.map((l) => l.title.toLowerCase()));
  return records.filter((r) =>
    keys.has(projectSlug(r.title)) || keys.has(sanitizeProjectKey(r.title)) || titles.has(r.title.toLowerCase()),
  );
}

