runtime.shared/lib/github/useGithubQuery.ts:
// useGithubQuery (#1496) — the GitHub fetch orchestration the planner/github screens hand-rolled:
// the `{ data, loading, error }` triple, the token gate, the cancel-guard, and the
// loading/error transitions. The screen-specific PARSE of the response stays in the screen (as a
// useMemo over `data`) — this hook only owns the fetch lifecycle.
//
// Mirrors the established pattern in useRepoPulse / useFleetGithub, generalized to any fetcher.

import { useEffect, useState, type DependencyList } from "react";
import { useAppStore } from "@/store";

export interface GithubQuery<T> {
  data: T | null;
  loading: boolean;
  error: string | null;
}

/**
 * Run `fetcher(token)` whenever `deps` (or the token) change, tracking `{ data, loading, error }`.
 * Skips while `enabled` is false or there's no token — leaving the last result in place, matching
 * the `if (!token || !x) return` gate the screens used. A stale in-flight request never lands
 * (cancel-guard), so rapid dep changes don't clobber the newest result.
 */
export function useGithubQuery<T>(
  fetcher: (token: string) => Promise<T>,
  deps: DependencyList,
  enabled = true,
): GithubQuery<T> {
  const githubToken = useAppStore((s) => s.githubToken);
  const [state, setState] = useState<GithubQuery<T>>({ data: null, loading: false, error: null });

  useEffect(() => {
    if (!githubToken || !enabled) return;
    let cancelled = false;
    setState((s) => ({ ...s, loading: true, error: null }));
    fetcher(githubToken)
      .then((data) => { if (!cancelled) setState({ data, loading: false, error: null }); })
      .catch((e) => { if (!cancelled) setState((s) => ({ ...s, loading: false, error: String(e) })); });
    return () => { cancelled = true; };
    // `fetcher` is intentionally not a dep — callers declare the inputs it closes over via `deps`.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [githubToken, enabled, ...deps]);

  return state;
}

runtime.shared/lib/graph/crossGraph.ts:
// Cross-graph resolution + the `requires` edge (#3115, epic #3114). Builds on the URN grammar in
// ./nodeUrn: a URN NAMES a node; this module RESOLVES it to a normalized record, models the cross-graph
// `requires` edge, and lays foreign nodes out in a fenced band (the shape generalized from Glance's UI-kit
// band, #3007). All pure + feature-agnostic — a feature adapts its own hydrated store into a `NodeLookup`
// (it never imports another feature's types), and the consumer composes the per-graph lookups into one
// resolver via {@link makeUrnResolver}.
import { parseNodeUrn, type NodeGraph } from "./nodeUrn";

/** A node resolved across graphs — the normalized shape every pillar maps its own record onto, so a
 *  consumer (the component preview, the app graph) can treat an algorithm, a component, and a sound cue
 *  uniformly. Deliberately minimal: identity + label + kind, plus the reusable implementation when the
 *  graph carries one (an algorithm's `code`), which is what the preview vendors (#3116). */
export interface ResolvedNode {
  /** The canonical `<graph>:<kit>/<id>` URN this node resolved from. */
  urn: string;
  graph: NodeGraph;
  kit: string;
  id: string;
  /** Human label for the node card (the node's display name). */
  label: string;
  /** The graph-specific kind slug — `algorithm`/`primitive`, a component `role`, or `cue`/`voice`/
   *  `primitive`. Opaque here; the consumer/legend interprets it per graph. */
  kind: string;
  /** The reusable implementation source when the graph has one (an algorithm's `code`). Absent for a
   *  descriptor-only node (a sounds primitive, a spec component). The preview vendors this (#3116). */
  code?: string;
}

/** A single graph's lookup: given a kit + in-kit id, return the resolved node or null. A feature builds
 *  this from its hydrated store data (e.g. algorithms: find the impl with `tech === kit && id === id`). */
export type NodeLookup = (kit: string, id: string) => ResolvedNode | null;

/** Resolve any node URN to its {@link ResolvedNode}, or null (unknown graph, or the target doesn't exist). */
export type UrnResolver = (urn: string) => ResolvedNode | null;

/**
 * Compose per-graph {@link NodeLookup}s into one {@link UrnResolver}. A missing graph in the registry (or
 * a lookup miss) resolves to null — so a resolver wired with only `{ algo }` cleanly returns null for a
 * `sound:` URN instead of throwing. The returned node's `urn`/`graph`/`kit`/`id` are always overwritten
 * from the URN, so a lookup can't mislabel identity (it only supplies `label`/`kind`/`code`).
 */
export function makeUrnResolver(registry: Partial<Record<NodeGraph, NodeLookup>>): UrnResolver {
  return (urn: string): ResolvedNode | null => {
    const parts = parseNodeUrn(urn);
    if (!parts) return null;
    const lookup = registry[parts.graph];
    if (!lookup) return null;
    const found = lookup(parts.kit, parts.id);
    if (!found) return null;
    return { ...found, urn, graph: parts.graph, kit: parts.kit, id: parts.id };
  };
}

/** The only cross-graph relationship today — a node `requires` a node in another graph (a UI component
 *  requires an algorithm). Kept distinct from an in-kit `composes` so "built from my siblings" never
 *  blurs with "pulls in a foreign capability". */
export type CrossGraphRel = "requires";

/** A directed edge between two graphs: the node at `fromUrn` requires the node at `toUrn`. */
export interface CrossGraphEdge {
  id: string;
  fromUrn: string;
  toUrn: string;
  rel: CrossGraphRel;
}

/** Stable, collision-proof id for a cross-graph edge (`<fromUrn>~requires~<toUrn>`). */
export function crossGraphEdgeId(fromUrn: string, toUrn: string, rel: CrossGraphRel = "requires"): string {
  return `${fromUrn}~${rel}~${toUrn}`;
}

// ── The fenced band (#3007, generalized) — foreign/library nodes lifted OUT of a graph's main layout into
// a single row across the top, reading as a separate dimension. Glance does exactly this for UI-kit nodes;
// this is that math, parameterized, so the component graph (#3116/#3117) and the app graph (#3119) all
// render their pulled-in library nodes the same way. Pure + deterministic. ──

/** Inputs for {@link layoutBand} — all in world (design) coordinates. */
export interface BandOpts {
  /** Left edge of the content span the band centers over (Glance uses its layout's 70px left pad). */
  spanX0: number;
  /** Right edge of the content span (Glance uses the max project-node x). */
  spanX1: number;
  /** y of the band cards' TOP edge. */
  topPad: number;
  /** Band card height (so the divider clears the cards). */
  nodeH: number;
  /** Clearance from the cards' bottom down to the fence divider. */
  gap: number;
  /** Cap on the horizontal step between cards, so a couple of nodes cluster in the middle instead of
   *  stretching the full width (Glance caps at one column gap). */
  maxStep: number;
}

/** A laid-out band: each node's top-left position, plus the band's vertical extent + fence divider y. */
export interface BandLayout {
  positions: { x: number; y: number }[];
  /** Top of the band zone. */
  y0: number;
  /** Bottom of the band zone (== `dividerY`) — the rest of the graph shifts down by this much. */
  y1: number;
  /** y of the fence divider drawn under the band. */
  dividerY: number;
}

/**
 * Lay `count` foreign nodes out in a single centered row across the top, and report the fence divider the
 * main graph shifts below. Mirrors Glance's kit-band math (#3007): evenly spaced over [spanX0, spanX1] but
 * the step never exceeds `maxStep`. `count === 0` → no positions (the caller omits the band entirely).
 * Deterministic.
 */
export function layoutBand(count: number, opts: BandOpts): BandLayout {
  const { spanX0, spanX1, topPad, nodeH, gap, maxStep } = opts;
  const dividerY = topPad + nodeH + gap;
  const positions: { x: number; y: number }[] = [];
  if (count > 0) {
    const span = Math.max(0, spanX1 - spanX0);
    const step = count > 1 ? Math.min(span / (count - 1), maxStep) : 0;
    const rowW = step * (count - 1);
    const startX = spanX0 + (span - rowW) / 2;
    for (let i = 0; i < count; i++) positions.push({ x: startX + i * step, y: topPad });
  }
  return { positions, y0: 0, y1: dividerY, dividerY };
}

runtime.shared/lib/graph/cycles.ts:
// Cycle detection (#2217, graph-core epic #2214) — the shared primitives the graphs use to find cycles
// in a directed graph. Two flavours, matching what the features already do:
//   • findBackEdges — DFS (white/grey/black) back-edge detection: finds ANY-length cycle and returns
//     the edges that close one. Used for topological layering (exclude back-edges so a cycle can't
//     explode the layout) and to flag coordination deadlocks. This is the relationship graph's algorithm.
//   • mutualPairs — the 2-cycle special case (a↔b): the cheap "mutual dependency" check the Glance
//     network surfaces as coordination hazards.
// Both are pure; the caller pre-filters to whichever edge subset is order-bearing.
import type { GraphEdge } from "./types";

/**
 * DFS back-edge detection over `edges` restricted to `nodeIds`. Returns the set of edge ids that close
 * a cycle (grey-target back-edges) and whether any cycle exists. Nodes are visited in `nodeIds` order
 * and each node's out-edges in `edges` order, so the result is deterministic.
 */
export function findBackEdges(nodeIds: readonly string[], edges: readonly GraphEdge[]): { backEdgeIds: Set<string>; hasCycle: boolean } {
  const idSet = new Set(nodeIds);
  const adj = new Map<string, { to: string; id: string }[]>(nodeIds.map((i) => [i, []]));
  for (const e of edges) {
    if (idSet.has(e.from) && idSet.has(e.to)) adj.get(e.from)!.push({ to: e.to, id: e.id });
  }
  const color = new Map<string, 0 | 1 | 2>(); // 0 white · 1 grey (on stack) · 2 black
  const backEdgeIds = new Set<string>();
  let hasCycle = false;
  const dfs = (n: string) => {
    color.set(n, 1);
    for (const { to, id } of adj.get(n) ?? []) {
      const c = color.get(to) ?? 0;
      if (c === 1) { hasCycle = true; backEdgeIds.add(id); } // back-edge → a cycle
      else if (c === 0) dfs(to);
    }
    color.set(n, 2);
  };
  for (const i of nodeIds) if ((color.get(i) ?? 0) === 0) dfs(i);
  return { backEdgeIds, hasCycle };
}

/**
 * Mutual pairs (a↔b) — every pair of nodes with edges in both directions. Returns the pairs (each once,
 * `from < to`), the ids of ALL edges in a mutual pair (both directions), and the node ids involved.
 */
export function mutualPairs(edges: readonly GraphEdge[]): { pairs: [string, string][]; edgeIds: Set<string>; nodeIds: Set<string> } {
  const pairs: [string, string][] = [];
  const edgeIds = new Set<string>();
  const nodeIds = new Set<string>();
  for (const a of edges) for (const b of edges) {
    if (a.from === b.to && a.to === b.from && a.from < a.to) {
      edgeIds.add(a.id); edgeIds.add(b.id);
      pairs.push([a.from, a.to]);
      nodeIds.add(a.from); nodeIds.add(a.to);
    }
  }
  return { pairs, edgeIds, nodeIds };
}

runtime.shared/lib/graph/edgePath.ts:
// Shared edge geometry (#2222, graph design-language #2221) — the ONE line-type every graph draws its
// edges with: a cubic bezier + a filled-triangle arrowhead + a label midpoint, in a shared grammar.
// Only the ROUTING (where the curve meets each card) is layout-dependent (#2226), via `routing`:
//   • "anchor" — perimeter-anchor: leaves each card at the point on its border facing the other card.
//     Right for FREE / ORGANIC layouts (the Org designer's force graph).
//   • "ports"  — side ports: leaves the right (or left) edge at the vertical middle with horizontal
//     control handles. Right for LAYERED left→right graphs (Glance's dependency DAG) — clean columnar
//     flow. (Restores Glance's pre-#2222 geometry; the perimeter router read messy on a layered graph.)
// Both share the arrowhead + label + `bow` (perpendicular separation for parallel/bidirectional/cycle
// edges) + `doubleEnded` (a source arrow for bidirectional relationships). Pure.

export interface EdgeBox { x: number; y: number; w: number; h: number }

export type EdgeRouting = "anchor" | "ports";

export interface GraphEdgeOpts {
  /** Where the curve meets each card. Default "anchor" (perimeter); "ports" for layered graphs. */
  routing?: EdgeRouting;
  /** Perpendicular bow (px) so parallel/bidirectional/cycle edges separate. Default 0. */
  bow?: number;
  /** ("anchor" only) how far short of the target border the curve ends, for the arrow. Default 9. */
  endGap?: number;
  /** Arrowhead length (px); half-width ≈ 0.58×. Default 9. */
  arrowSize?: number;
  /** Also draw an arrowhead at the source (bidirectional). Default false. */
  doubleEnded?: boolean;
}

export interface GraphEdgeGeom {
  /** The cubic-bezier path `d`. */
  d: string;
  /** Filled-triangle arrowhead path at the target border. */
  arrow: string;
  /** Filled-triangle arrowhead at the source border (only when `doubleEnded`). */
  arrowStart?: string;
  /** The curve midpoint — where an edge label pill sits. */
  labelX: number;
  labelY: number;
}

const f = (v: number): number => Math.round(v * 10) / 10;

/** The point on box `a`'s perimeter along the ray toward (tx,ty), with a 3px outset so the line clears
 *  the border. (The Org designer's `anchor` — exported since #2418 replaced org's byte-identical copy;
 *  its feature barrel re-exports this one.) */
export function anchor(a: EdgeBox, tx: number, ty: number): [number, number] {
  const cx = a.x + a.w / 2, cy = a.y + a.h / 2, dx = tx - cx, dy = ty - cy;
  const hw = a.w / 2 + 3, hh = a.h / 2 + 3;
  const sx = dx === 0 ? 1e9 : hw / Math.abs(dx);
  const sy = dy === 0 ? 1e9 : hh / Math.abs(dy);
  const s = Math.min(sx, sy);
  return [cx + dx * s, cy + dy * s];
}

/** A filled-triangle arrow with its tip at (tipx,tipy), pointing along `ang`. */
function arrowPath(tipx: number, tipy: number, ang: number, len: number): string {
  const w = len * 0.58;
  const bx = tipx - Math.cos(ang) * len, by = tipy - Math.sin(ang) * len;
  const nx = -Math.sin(ang), ny = Math.cos(ang);
  return `M ${f(tipx)} ${f(tipy)} L ${f(bx + nx * w)} ${f(by + ny * w)} L ${f(bx - nx * w)} ${f(by - ny * w)} Z`;
}

/** Assemble the geometry from the four control points (source, two handles, arrow tip). Shared by both
 *  routers: the curve ends at `tip`, the arrow sits there, the label is the cubic midpoint. */
function assemble(p1x: number, p1y: number, c1x: number, c1y: number, c2x: number, c2y: number, tipx: number, tipy: number, arrowSize: number, doubleEnded: boolean): GraphEdgeGeom {
  const d = `M ${f(p1x)} ${f(p1y)} C ${f(c1x)} ${f(c1y)} ${f(c2x)} ${f(c2y)} ${f(tipx)} ${f(tipy)}`;
  // The cubic's midpoint (t=0.5) via the Bernstein weights (1/8, 3/8, 3/8, 1/8).
  const labelX = 0.125 * p1x + 0.375 * c1x + 0.375 * c2x + 0.125 * tipx;
  const labelY = 0.125 * p1y + 0.375 * c1y + 0.375 * c2y + 0.125 * tipy;
  const arrow = arrowPath(tipx, tipy, Math.atan2(tipy - c2y, tipx - c2x), arrowSize);
  const arrowStart = doubleEnded ? arrowPath(p1x, p1y, Math.atan2(p1y - c1y, p1x - c1x), arrowSize) : undefined;
  return { d, arrow, arrowStart, labelX, labelY };
}

/** Perimeter-anchor routing — for free/organic layouts. Byte-identical to the Org designer's geometry. */
function anchorEdge(from: EdgeBox, to: EdgeBox, opts: GraphEdgeOpts): GraphEdgeGeom {
  const bow = opts.bow ?? 0, endGap = opts.endGap ?? 9, arrowSize = opts.arrowSize ?? 9;
  const acx = from.x + from.w / 2, acy = from.y + from.h / 2, bcx = to.x + to.w / 2, bcy = to.y + to.h / 2;
  const [p1x, p1y] = anchor(from, bcx, bcy);
  const [b2x, b2y] = anchor(to, acx, acy);       // the target border point — the arrow tip
  const dx0 = b2x - p1x, dy0 = b2y - p1y, L = Math.hypot(dx0, dy0) || 1;
  const p2x = b2x - (dx0 / L) * endGap;          // curve ends short of the border
  const p2y = b2y - (dy0 / L) * endGap;
  const dx = p2x - p1x, dy = p2y - p1y;
  const nx = -dy / L, ny = dx / L;
  const c1x = p1x + dx * 0.35 + nx * bow, c1y = p1y + dy * 0.35 + ny * bow;
  const c2x = p1x + dx * 0.65 + nx * bow, c2y = p1y + dy * 0.65 + ny * bow;
  // NB: the arrow tip is the border point; the curve ends short of it (p2).
  return {
    ...assemble(p1x, p1y, c1x, c1y, c2x, c2y, p2x, p2y, arrowSize, !!opts.doubleEnded),
    arrow: arrowPath(b2x, b2y, Math.atan2(p2y - c2y, p2x - c2x), arrowSize),
  };
}

/** Side-port routing — for layered left→right graphs. Leaves the right (or left) edge at the vertical
 *  middle with horizontal control handles, giving a clean columnar flow. Restores Glance's geometry. */
function portsEdge(from: EdgeBox, to: EdgeBox, opts: GraphEdgeOpts): GraphEdgeGeom {
  const bow = opts.bow ?? 0, arrowSize = opts.arrowSize ?? 9;
  const fRight = from.x < to.x;
  const p1x = from.x + (fRight ? from.w : 0), p1y = from.y + from.h / 2;
  const tLeftPort = to.x >= from.x;
  const tx = to.x + (tLeftPort ? 0 : to.w), ty = to.y + to.h / 2;   // target port — the arrow tip
  const k = Math.max(46, Math.abs(tx - p1x) * 0.5);
  const c1x = p1x + (fRight ? k : -k), c1y = p1y + bow;
  const c2x = tx + (tLeftPort ? -k : k), c2y = ty + bow;
  return assemble(p1x, p1y, c1x, c1y, c2x, c2y, tx, ty, arrowSize, !!opts.doubleEnded);
}

/** The shared line-type between two boxes; `routing` picks the router. See the module header. */
export function graphEdge(from: EdgeBox, to: EdgeBox, opts: GraphEdgeOpts = {}): GraphEdgeGeom {
  return opts.routing === "ports" ? portsEdge(from, to, opts) : anchorEdge(from, to, opts);
}

runtime.shared/lib/graph/layers.ts:
// Topological layering (#2214, graph-core epic) — the ONE longest-path layerer the graphs share. A
// dependency/coordination DAG flows across LAYERS: each node lands as deep as its longest incoming
// chain, so a source (no in-edges) sits at layer 0. The caller hands in a cycle-break set (the
// back-edges it already computed via `cycles.ts`, or its 2-cycle mutual pairs) so a loop can't diverge
// the layout. Pure; the callers own the layer→pixel PLACEMENT (Glance's grid, Relationship's swimlanes)
// — this only assigns the layer number.
import type { GraphEdge } from "./types";

/**
 * Longest-path topological layering. Assigns each node in `nodeIds` an integer layer so that for every
 * kept edge `from→to`, `layer[to] >= layer[from] + 1` — sources sit at layer 0 and each node lands as
 * deep as its longest incoming chain. Edges in `backEdgeIds` (the caller's cycle-break set), self-loops,
 * and edges touching an id outside `nodeIds` are ignored, so a cycle can't diverge the assignment. The
 * result is the DAG's unique longest-path layering, so it's independent of the relaxation order (and
 * identical to a Kahn / memoized-DFS layerer over the same acyclic edge set).
 *
 * Edge direction is "from → deeper": a node points to the nodes that must sit BELOW it. A "depends-on"
 * DAG — where the dependency should sit at a LOWER layer than its dependent — reverses its edges before
 * calling (see Glance's `buildGraph`).
 */
export function layerDag(
  nodeIds: readonly string[],
  edges: readonly GraphEdge[],
  backEdgeIds?: ReadonlySet<string>,
): Record<string, number> {
  const idSet = new Set(nodeIds);
  const kept = edges.filter(
    (e) => e.from !== e.to && idSet.has(e.from) && idSet.has(e.to) && !backEdgeIds?.has(e.id),
  );
  const layer: Record<string, number> = {};
  for (const id of nodeIds) layer[id] = 0;
  // Relax to the fixpoint: the longest path on a DAG spans ≤ nodeIds.length edges, so that many sweeps
  // always converge; the `changed` guard usually breaks far sooner. Same result as Kahn — order-free.
  for (let iter = 0; iter <= nodeIds.length; iter++) {
    let changed = false;
    for (const e of kept) {
      if (layer[e.to] < layer[e.from] + 1) { layer[e.to] = layer[e.from] + 1; changed = true; }
    }
    if (!changed) break;
  }
  return layer;
}

runtime.shared/lib/graph/nodeUrn.ts:
// Cross-graph node addressing (#3115, epic #3114) — the universal "part number" that lets a node in one
// kit graph (Algorithms / Designs / Sounds) reference a node in ANOTHER. Today the three graphs are
// siloed: `composes` only resolves inside one kit of one pillar, so a UI component that needs `fibonacci`
// re-codes it. This module is the pure, feature-agnostic substrate that makes a cross-graph reference
// EXPRESSIBLE — the URN grammar + the reserved import-namespace mapping. Resolution + the `requires` edge
// live in ./crossGraph; the feature wiring (which store to look in) lives in the consuming features.
//
// React/Tauri-free and it imports NO feature code (this is `shared/`) — the three pillars stay decoupled
// from each other; each just adapts its own store to the generic resolver in ./crossGraph.

/** The three kit-graph pillars a node can live in. The URN's leading token. */
export type NodeGraph = "algo" | "ui" | "sound";

/** All graphs, in display order. */
export const NODE_GRAPHS: NodeGraph[] = ["algo", "ui", "sound"];

/** The reserved npm-style root for a library import (`@bsc/<segment>/<name>`). Chosen so it can never
 *  collide with a real package a user installs, and so the existing import resolver can key on it. */
export const LIBRARY_ROOT = "@bsc";

/** graph → the `@bsc/<segment>` path segment used in a library import specifier. */
export const LIBRARY_SEGMENT: Record<NodeGraph, string> = { algo: "algorithms", ui: "ui", sound: "sounds" };

/** The reverse of {@link LIBRARY_SEGMENT} — an import path segment back to its graph. */
const SEGMENT_GRAPH: Record<string, NodeGraph> = { algorithms: "algo", ui: "ui", sounds: "sound" };

/** The decomposed parts of a node URN `<graph>:<kit>/<id>`. */
export interface NodeUrnParts {
  graph: NodeGraph;
  /** The kit the node lives in — a language for algorithms (`typescript`), a kit id for designs/sounds.
   *  MAY contain `/`: sound kits are scoped (`acme/neon`). */
  kit: string;
  /** The node's in-kit id (`fibonacci.ts`, `Sparkline`, `click`). Must NOT contain `/` — see
   *  {@link parseNodeUrn} for which side of the `<kit>/<id>` ambiguity the grammar takes. */
  id: string;
}

/** Is `g` one of the known graphs? (Type guard.) */
export function isNodeGraph(g: string): g is NodeGraph {
  return (NODE_GRAPHS as string[]).includes(g);
}

/**
 * Format a node URN — `<graph>:<kit>/<id>`, e.g. `algo:typescript/fibonacci.ts`, `ui:react-ui/Sparkline`,
 * `sound:default/click`. Returns null if any component is empty (so callers can't mint a malformed URN).
 */
export function formatNodeUrn(graph: NodeGraph, kit: string, id: string): string | null {
  if (!isNodeGraph(graph) || !kit || !id) return null;
  return `${graph}:${kit}/${id}`;
}

/**
 * Parse a node URN back into its parts, or null when it doesn't match `<graph>:<kit>/<id>` with a known
 * graph and non-empty kit + id. Tolerant: never throws (malformed input → null).
 *
 * `<kit>/<id>` is ambiguous when either half contains a `/`, so the split has to pick a side. It splits
 * on the LAST `/`: the KIT may contain slashes, the id may not.
 *
 * This reversed the original choice (#3514). Splitting on the FIRST `/` was chosen so an id could
 * contain slashes — with the caveat, written right here, "though today none do". Meanwhile kit ids
 * demonstrably DO: a sound kit is scoped (`acme/neon`), which is the exact form #3412 taught blueprints
 * to pin. So `sound:acme/neon/zap` parsed as kit `acme` + id `neon/zap`, missed every lookup, and a
 * pinned sound kit resolved NOTHING — silently, because a miss is indistinguishable from "no such cue".
 * The grammar was guarding a case that has never existed at the cost of one that ships.
 */
export function parseNodeUrn(urn: string): NodeUrnParts | null {
  if (typeof urn !== "string") return null;
  const colon = urn.indexOf(":");
  if (colon <= 0) return null;
  const graph = urn.slice(0, colon);
  if (!isNodeGraph(graph)) return null;
  const rest = urn.slice(colon + 1);
  const slash = rest.lastIndexOf("/");
  if (slash <= 0) return null; // need a non-empty kit before the last '/'
  const kit = rest.slice(0, slash);
  const id = rest.slice(slash + 1);
  if (!kit || !id) return null;
  return { graph, kit, id };
}

/** Is `s` a well-formed node URN? */
export function isNodeUrn(s: string): boolean {
  return parseNodeUrn(s) !== null;
}

/** A library import specifier `@bsc/<segment>/<name>` — the KIT-LESS reference a component author writes
 *  (`import { fibonacci } from "@bsc/algorithms/fibonacci"`). The consuming store picks the kit (a TS
 *  component resolves an algorithm in the `typescript` kit), so a spec carries only graph + name. */
export interface LibrarySpec {
  graph: NodeGraph;
  /** The node name/id as written in the import (`fibonacci` or `fibonacci.ts` — the resolver accepts both). */
  name: string;
}

/** Is `spec` under the reserved `@bsc/…` library root? A cheap pre-check before {@link parseLibrarySpec}. */
export function isLibrarySpec(spec: string): boolean {
  return typeof spec === "string" && spec.startsWith(LIBRARY_ROOT + "/");
}

/**
 * Parse a library import specifier `@bsc/<segment>/<name>` into `{ graph, name }`, or null when it isn't
 * a `@bsc/…` spec with a known segment and a non-empty name. `name` keeps any remaining path (e.g. a
 * hypothetical `@bsc/ui/forms/Field` → name `forms/Field`) so ids with `/` survive. Never throws.
 */
export function parseLibrarySpec(spec: string): LibrarySpec | null {
  if (!isLibrarySpec(spec)) return null;
  const after = spec.slice(LIBRARY_ROOT.length + 1); // drop "@bsc/"
  const slash = after.indexOf("/");
  if (slash <= 0) return null;
  const segment = after.slice(0, slash);
  const name = after.slice(slash + 1);
  const graph = SEGMENT_GRAPH[segment];
  if (!graph || !name) return null;
  return { graph, name };
}

/**
 * The canonical library import specifier for a node URN — `@bsc/<segment>/<id>`. The inverse of routing a
 * spec to a node; used to REWRITE an inline reimplementation into a library import (#3118) and to label a
 * cross-graph edge. Returns null for a malformed URN.
 */
export function urnToImportSpec(urn: string): string | null {
  const parts = parseNodeUrn(urn);
  if (!parts) return null;
  return `${LIBRARY_ROOT}/${LIBRARY_SEGMENT[parts.graph]}/${parts.id}`;
}

runtime.shared/lib/graph/order.ts:
// Barycenter layer ordering (#2418, graph-core epic #2214) — the ONE crossing-reduction sweep the
// layered graphs share. Given a layer assignment (from `layerDag` or any layerer), order the nodes
// WITHIN each layer so each sits near the mean in-layer index of its neighbors — the classic Sugiyama
// barycenter heuristic. What VARIES per graph is tunable: the neighbor gathering (org pulls only from
// cross-layer hierarchy parents/children; Glance from every edge endpoint), the pass count, and the
// sweep discipline. Pure; the caller owns the layer→pixel placement.

export interface OrderLayersOpts {
  /** Barycenter sweeps over the whole layer set. Default 4. */
  passes?: number;
  /** How fresh the neighbor indexes are within one pass:
   *   • "sequential" (default) — sorting layer L reads the ALREADY re-sorted order of the layers
   *     sorted earlier in the same pass, so an improvement propagates immediately (org's discipline).
   *   • "snapshot" — every layer sorts against the order at the START of the pass (Glance's). */
  sweep?: "sequential" | "snapshot";
}

/**
 * Order the nodes within each layer by the barycenter heuristic: each layer is sorted by the mean
 * in-layer index of each node's neighbors; a node with no (known) neighbors keeps its current index.
 * The initial order is `nodeIds` order filtered per layer; ties keep the pre-sort order (stable sort).
 *
 * @param nodeIds Every node, in the initial (seed) order.
 * @param layerOf The layer assignment (e.g. `layerDag`'s).
 * @param neighborsOf The ids whose in-layer positions pull on a node — the caller's neighbor
 *   gathering. Multiplicity counts (a doubly-connected neighbor pulls twice); ids outside `nodeIds`
 *   are ignored.
 * @returns layer → its node ids in final order (layers in ascending order).
 */
export function orderLayers(
  nodeIds: readonly string[],
  layerOf: (id: string) => number,
  neighborsOf: (id: string) => readonly string[],
  opts: OrderLayersOpts = {},
): Map<number, string[]> {
  const passes = opts.passes ?? 4;
  const sweep = opts.sweep ?? "sequential";
  const layers = [...new Set(nodeIds.map(layerOf))].sort((a, b) => a - b);
  const order = new Map<number, string[]>(layers.map((l) => [l, nodeIds.filter((n) => layerOf(n) === l)]));
  const idx = new Map<string, number>();
  const reindex = (l: number) => order.get(l)!.forEach((n, i) => idx.set(n, i));
  layers.forEach(reindex);

  const bary = (n: string): number => {
    const neigh = neighborsOf(n).filter((m) => idx.has(m));
    if (neigh.length === 0) return idx.get(n)!;
    return neigh.reduce((s, m) => s + idx.get(m)!, 0) / neigh.length;
  };
  const sortLayer = (l: number, b: Map<string, number>) => {
    order.get(l)!.sort((x, y) => b.get(x)! - b.get(y)!);
    reindex(l);
  };

  for (let pass = 0; pass < passes; pass++) {
    if (sweep === "snapshot") {
      const b = new Map(nodeIds.map((n) => [n, bary(n)] as const));
      for (const l of layers) sortLayer(l, b);
    } else {
      for (const l of layers) sortLayer(l, new Map(order.get(l)!.map((n) => [n, bary(n)] as const)));
    }
  }
  return order;
}

runtime.shared/lib/graph/selectionNeighborhood.t:
// Selection neighborhood (#2523, promoted to shared #2719) — a pure graph query used by every graph
// canvas that highlights a selection: given the edge set and a selected node id, return the edges
// incident to it and the nodes on the far end of those edges. React-free and layout-agnostic (it
// only needs `from`/`to`/`id` on each edge), so it lives alongside the other shared graph model
// helpers rather than in any one feature.
import type { GraphEdge } from "./types";

export interface SelectionNeighborhood {
  /** Edge ids incident to the selected node (`from === selId || to === selId`). */
  incidentEdges: Set<string>;
  /** Node ids directly connected to the selected node — the selection itself is never included. */
  relatedNodes: Set<string>;
}

/** The selection neighborhood of a node: the edges touching it and the nodes on the far end. A
 *  GraphView highlights the incident edges in accent and softly rings the related nodes. Empty when
 *  `selId` is falsy (nothing selected). A self-loop never marks the selection as its own relation. */
export function selectionNeighborhood(edges: readonly GraphEdge[], selId: string): SelectionNeighborhood {
  const incidentEdges = new Set<string>();
  const relatedNodes = new Set<string>();
  if (!selId) return { incidentEdges, relatedNodes };
  for (const e of edges) {
    if (e.from === selId) { incidentEdges.add(e.id); relatedNodes.add(e.to); }
    else if (e.to === selId) { incidentEdges.add(e.id); relatedNodes.add(e.from); }
  }
  relatedNodes.delete(selId); // a self-loop must not mark the selection as its own relation
  return { incidentEdges, relatedNodes };
}

runtime.shared/lib/graph/spotlight.ts:
// Neighbor spotlight (#2215, graph-core epic #2214) — the shared "focus dims the rest" primitive. Given
// a node in focus (hovered/selected), it returns the node itself + its direct neighbors (in either
// direction) and every edge touching it, so the view can brighten those and dim everything else. Both
// Glance (focusSets) and the agent-relationship graph (computeSpotlight) resolve their node/agent focus
// this way; each layers its own domain extras on top (Glance's edge/cycle branches; the relationship
// graph's artifact lighting).
import type { GraphEdge } from "./types";

export interface Spotlight {
  /** The focused node + its direct neighbors. */
  litNodes: Set<string>;
  /** Every edge incident to the focused node. */
  litEdges: Set<string>;
}

/** The node in focus + its neighbors (either direction) + the edges touching it. Pure. */
export function neighborSpotlight(edges: readonly GraphEdge[], focusId: string): Spotlight {
  const litNodes = new Set<string>([focusId]);
  const litEdges = new Set<string>();
  for (const e of edges) {
    if (e.from === focusId) { litNodes.add(e.to); litEdges.add(e.id); }
    if (e.to === focusId) { litNodes.add(e.from); litEdges.add(e.id); }
  }
  return { litNodes, litEdges };
}

runtime.shared/lib/graph/types.ts:
// Shared graph core (#2214, epic) — the pure (React-free) graph primitives that Glance, the Org
// designer, and the agent-relationship graph all build on, so layering/cycle/focus logic lives once
// instead of being re-copied per domain (#2204: "layout is a function of the data structure"). The
// render layer is already shared (GraphCanvas + useGraphViewport, #2208); this is the model layer.
//
// Each feature extends these bases with its own domain fields (role/status/kind/hardness/…) and
// palettes — the core only knows ids + direction.

/** The minimum a node needs to participate in the shared graph algorithms. */
export interface GraphNode {
  id: string;
}

/** A directed edge; `from`/`to` are node ids. Direction matters for layering + cycle detection. */
export interface GraphEdge {
  id: string;
  from: string;
  to: string;
}

runtime.shared/lib/logs/sessionLog.ts:
// Per-session log drill-down — pure shaping for the `bsc logs` reads (#1607 slice 3).
//
// The unified log engine lives in `crates/logs` and is reached the SAME way every other frontend log
// surface reaches it: `bsc logs …` over the `bsc` bridge (#2144), never a per-verb Tauri command. This
// module owns only the pure (React-free, unit-testable) shaping of two of those reads —
// `bsc logs sessions --json` (the session picker) and `bsc logs session <id> --json` (one session's
// full, time-merged story across tools/skills/mcp/hooks/perm/coord/activity/done + its cost rollup) —
// so the drill-down card stays a thin renderer. The JSON shapes mirror the crate's serde structs
// (snake_case field names, no `rename_all`): `SessionRow`, `LogEvent`, `Cost`, and the `session`
// command's `{ session, role, events, cost }` envelope.

/** One row of `bsc logs sessions --json` — the crate's `SessionRow` (snake_case). */
export interface LogSessionRow {
  session: string;
  role: string;
  tools: number;
  skills: number;
  mcp: number;
  coord: number;
  cost_usd: number;
  activity: string;
}

/** One normalized event — the crate's `LogEvent`. `stream` is the canonical category key. */
export interface SessionLogEvent {
  ts_ms: number;
  session: string;
  stream: string;
  summary: string;
  fields: string[];
}

/** The token/cost rollup — the crate's `Cost` (snake_case). */
export interface SessionCost {
  session: string;
  model: string;
  input: number;
  output: number;
  cache_creation: number;
  cache_read: number;
  cost_usd: number;
}

/** `bsc logs session <id> --json` — the merged story envelope. `cost` is null when untracked. */
export interface SessionStory {
  session: string;
  role: string;
  events: SessionLogEvent[];
  cost: SessionCost | null;
}

/** The event-category streams a session drill-down surfaces, in display order. Mirrors the crate's
 *  `canonical_stream` targets (minus the writer-only `tokens`, surfaced as the cost rollup instead). */
export const SESSION_STREAMS = [
  "tool",
  "skill",
  "mcp",
  "hook",
  "perm",
  "coord",
  "activity",
  "done",
] as const;
export type SessionStreamKey = (typeof SESSION_STREAMS)[number];

/** Short display label per stream key (the drill-down filter chips + timeline tag). */
export const STREAM_LABEL: Record<string, string> = {
  tool: "Tools",
  skill: "Skills",
  mcp: "MCP",
  hook: "Hooks",
  perm: "Denials",
  coord: "Coord",
  activity: "Activity",
  done: "Done",
};

/** A token per stream key so the timeline + chips read as one system. `perm` (a denial) reads as a
 *  warning; the rest map onto the shared semantic tokens. Unknown keys fall back to the muted tone. */
export const STREAM_TONE: Record<string, string> = {
  tool: "var(--accent)",
  skill: "var(--info)",
  mcp: "var(--success)",
  hook: "var(--fg-muted)",
  perm: "var(--danger)",
  coord: "var(--warning)",
  activity: "var(--fg-dim)",
  done: "var(--success)",
};

export function streamLabel(key: string): string {
  return STREAM_LABEL[key] ?? key;
}

export function streamTone(key: string): string {
  return STREAM_TONE[key] ?? "var(--fg-muted)";
}

/** `ts_ms` → `HH:MM:SS` (UTC), matching the crate CLI's lean-TSV `hms`. A negative/NaN ts clamps to
 *  `00:00:00` rather than throwing, so a malformed row still renders. */
export function eventTime(tsMs: number): string {
  // `trunc` (toward zero), not `floor`, so a small negative ts matches the crate CLI's Rust integer
  // division (`ms/1000`) exactly rather than wrapping to 23:59:59.
  const total = Math.trunc((Number.isFinite(tsMs) ? tsMs : 0) / 1000);
  const s = ((total % 86400) + 86400) % 86400;
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${pad(Math.floor(s / 3600))}:${pad(Math.floor((s % 3600) / 60))}:${pad(s % 60)}`;
}

/** Count events per stream key (every `SESSION_STREAMS` key present, zero-filled). Drives the filter
 *  chip badges + the header summary. */
export function streamCounts(events: SessionLogEvent[]): Record<string, number> {
  const out: Record<string, number> = {};
  for (const k of SESSION_STREAMS) out[k] = 0;
  for (const e of events) out[e.stream] = (out[e.stream] ?? 0) + 1;
  return out;
}

/** Events for the selected stream, newest first (a drill-down reads top-down); `null` ⇒ all streams.
 *  The crate emits ascending-by-time, so we reverse a shallow copy without mutating the input. */
export function filterEvents(events: SessionLogEvent[], stream: string | null): SessionLogEvent[] {
  const kept = stream ? events.filter((e) => e.stream === stream) : events.slice();
  return kept.reverse();
}

/** Total tokens (in + out + both cache buckets) for the cost rollup, or 0 when untracked. */
export function totalTokens(cost: SessionCost | null): number {
  if (!cost) return 0;
  return cost.input + cost.output + cost.cache_creation + cost.cache_read;
}

/** A one-glance rollup of a story: role, total event count, per-stream counts, and USD cost. */
export function summarizeStory(story: SessionStory | null): {
  role: string;
  total: number;
  byStream: Record<string, number>;
  costUsd: number;
  tokens: number;
} {
  const events = story?.events ?? [];
  return {
    role: story?.role ?? "session",
    total: events.length,
    byStream: streamCounts(events),
    costUsd: story?.cost?.cost_usd ?? 0,
    tokens: totalTokens(story?.cost ?? null),
  };
}

runtime.shared/lib/preview/captureFrame.ts:
// captureFrame (#2623 slice 5b) — screenshot the running preview for the reviewer. The web preview is a
// cross-origin iframe (localhost:PORT ≠ the app origin), so its canvas is TAINTED — JS can't read those
// pixels with html2canvas / drawImage(iframe). `getDisplayMedia` reads the actual RENDERED pixels at the
// OS level (untainted), which also means it captures a NATIVE preview window (the user shares that
// window) — one capture path for every PreviewSource kind, and zero dependencies (WebView2 supports it).
//
// The DOM-heavy grab (getDisplayMedia + <video> + canvas) isn't exercised in jsdom; the pure guards
// (availability + track teardown) are unit-tested, and the grab itself is runtime-verified.

/** Whether screen capture is available in this webview (feature-detect before offering the action). */
export function screenCaptureAvailable(): boolean {
  return typeof navigator !== "undefined" && !!navigator.mediaDevices?.getDisplayMedia;
}

/** Start a display-capture stream — prompts the user once to pick the window/screen to review. Reused
 *  across captures (kept by the caller) so the picker isn't shown on every shot. */
export async function startPreviewCapture(): Promise<MediaStream> {
  if (!screenCaptureAvailable()) {
    throw new Error("Screen capture isn't available here — can't grab a preview shot to review.");
  }
  return navigator.mediaDevices.getDisplayMedia({ video: { frameRate: 1 }, audio: false });
}

/** Grab the stream's current frame as a `data:image/png;base64,…` URL (drawn through a `<video>` +
 *  `<canvas>`; the frame is untainted since it came from screen capture). */
export async function grabFrame(stream: MediaStream): Promise<string> {
  if (!stream.getVideoTracks()[0]) throw new Error("capture stream has no video track");
  const video = document.createElement("video");
  video.srcObject = stream;
  video.muted = true;
  await video.play();
  if (video.readyState < 2) {
    await new Promise<void>((resolve) => { video.onloadeddata = () => resolve(); });
  }
  const w = video.videoWidth, h = video.videoHeight;
  const canvas = document.createElement("canvas");
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("no 2d canvas context for the capture");
  ctx.drawImage(video, 0, 0, w, h);
  video.pause();
  video.srcObject = null;
  return canvas.toDataURL("image/png");
}

/** Stop every track of a capture stream (ends the OS "sharing" indicator). Safe on null. */
export function stopCapture(stream: MediaStream | null): void {
  stream?.getTracks().forEach((t) => t.stop());
}

