export const useWindowDimensions = () => Dimensions.get();
export default { View, Text, ScrollView, Pressable, TouchableOpacity, TextInput, Image, FlatList, SectionList, ActivityIndicator, SafeAreaView, Modal, Switch, Button, StyleSheet, Platform, Dimensions, Alert, Keyboard, PanResponder, Animated, Easing, Linking, AppState };
`;

// ── react-native-svg → real SVG DOM ─────────────────────────────────────────────────────────────────────
// RN-svg component names map 1:1 to SVG elements, and React already accepts RN-svg's camelCase attributes
// (strokeWidth, strokeLinecap, …) on SVG elements — so a component's shapes actually draw in the preview.
const REACT_NATIVE_SVG_SHIM = `import { createElement as h } from "react";
const svg = (tag) => (props = {}) => { const { children, ...rest } = props; return h(tag, rest, children); };
export const Svg = svg("svg");
export const Circle = svg("circle");
export const Rect = svg("rect");
export const Path = svg("path");
export const Line = svg("line");
export const Polyline = svg("polyline");
export const Polygon = svg("polygon");
export const Ellipse = svg("ellipse");
export const G = svg("g");
export const Defs = svg("defs");
export const Stop = svg("stop");
export const LinearGradient = svg("linearGradient");
export const RadialGradient = svg("radialGradient");
export const ClipPath = svg("clipPath");
export const Mask = svg("mask");
export const Pattern = svg("pattern");
export const Use = svg("use");
export const Symbol = svg("symbol");
export const TSpan = svg("tspan");
export const TextPath = svg("textPath");
export const Text = svg("text");
export const Image = svg("image");
export const ForeignObject = svg("foreignObject");
export const Marker = svg("marker");
export default Svg;
`;

/** Bare specifiers that get a DEDICATED fidelity shim (real layout / real SVG) instead of the universal
 *  stub. Everything else bare (that isn't a curated external) falls through to `UNIVERSAL_STUB`. */
export const DEDICATED_SHIMS: Record<string, string> = {
  "react-native": REACT_NATIVE_SHIM,
  "react-native-svg": REACT_NATIVE_SVG_SHIM,
};

/** The esbuild namespace a locally-shimmed bare import is loaded from. */
export const PREVIEW_SHIM_NAMESPACE = "preview-shim";

/**
 * Scan `files` for the NAMED bindings each universal-stubbed package is imported with — so a generated stub
 * can export exactly those names. A specifier is universal-stubbed when it's bare (not relative / `@/` /
 * `@bsc/`), NOT a curated external, and NOT a dedicated shim (those have static exports, no scan needed).
 * Pure; over-collection is harmless (an extra export never hurts). Returns spec → the union of its imported
 * names across all files.
 */
export function scanStubImports(files: Record<string, string>, isExternal: (spec: string) => boolean): Map<string, string[]> {
  const importRe = /import\s+([^;'"]*?)\s+from\s*['"]([^'"]+)['"]/g;
  const acc = new Map<string, Set<string>>();
  for (const src of Object.values(files)) {
    importRe.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = importRe.exec(src))) {
      const [, clause, spec] = m;
      if (/^[./]/.test(spec) || spec.startsWith("@/") || spec.startsWith("@bsc/")) continue; // relative / first-party / library
      if (isExternal(spec) || spec in DEDICATED_SHIMS) continue;                              // real resolution, not a stub
      const set = acc.get(spec) ?? new Set<string>();
      const braces = /\{([^}]*)\}/.exec(clause);
      if (braces) {
        for (const part of braces[1].split(",")) {
          const name = part.trim().replace(/^type\s+/, "").split(/\s+as\s+/)[0].trim();
          if (name) set.add(name);
        }
      }
      acc.set(spec, set);
    }
  }
  return new Map(Array.from(acc, ([spec, set]) => [spec, Array.from(set)]));
}

/** The local module source a bare specifier resolves to when it is NOT a curated external — its dedicated
 *  fidelity shim, else a universal stub exporting the `exportNames` the component imports it with. Bundled
 *  in (no network), so resolution can never fail. */
export function shimModuleFor(spec: string, exportNames: string[] = []): string {
  return DEDICATED_SHIMS[spec] ?? universalStub(exportNames);
}

// ── The preview iframe CSP ───────────────────────────────────────────────────────────────────────────────
/**
 * Content-Security-Policy for the preview iframe (embedded as a `<meta http-equiv>` in the srcdoc, on TOP of
 * `sandbox="allow-scripts"`). The sandbox already blocks same-origin access (a compromised dependency can't
 * read the host app); this CLOSES THE EXFILTRATION + EXECUTION channels:
 *   - `connect-src 'none'`  — no fetch / XHR / WebSocket / sendBeacon: a compromised esm.sh dependency can
 *     render but can never phone home with anything it sees.
 *   - `script-src 'unsafe-inline' https://esm.sh` — runs the inlined bundle + our shims, and the curated
 *     esm.sh externals, and NOTHING else (no `data:` scripts, no other host).
 *   - `default-src 'none'` — every other fetch class (frames, workers, manifest, media) is denied.
 * Images/fonts allow `data:`/`https:` so previews still show art. All local stubs are bundled (not `data:`
 * URLs), which is what lets `script-src` stay this tight.
 */
export const PREVIEW_CSP =
  "default-src 'none'; " +
  "script-src 'unsafe-inline' https://esm.sh; " +
  "style-src 'unsafe-inline'; " +
  "img-src data: https:; " +
  "font-src data: https://esm.sh; " +
  "connect-src 'none'";

/** The `<meta http-equiv>` CSP tag for a preview srcdoc `<head>`. */
export function previewCspMeta(): string {
  return `<meta http-equiv="Content-Security-Policy" content="${PREVIEW_CSP}" />`;
}

runtime.shared/lib/preview/previewSource.ts:
// PreviewSource (#2623) — the TARGET-AGNOSTIC contract between the verify-build (which builds + serves a
// finished application) and the preview node in the graph (which RENDERS it in place). The build picks
// the `kind` from the project's stack; the node switches on `kind`. Decoupling "how it's built/served"
// from "how it renders" means a new render target slots in behind the seam WITHOUT touching the node. A
// wgpu/`wasm32` Rust 3D app compiles to a canvas → the SAME iframe as a web app (the `bundle`/`web` kinds),
// so only a pure native-window binary needs the `native` kind — which the verify-build builds and launches
// as its OWN desktop window (host-native, or a Linux GUI passed through WSLg). In-graph frame capture is a
// future render surface behind this same seam (slice 5+); v1 renders native as a launched external window.
// Pure (no React/Tauri) so it's unit-testable and shared by both features (planner build · glance render).

/** What the verify-build produced for a completed project to preview. */
export type PreviewSource =
  | { kind: "web"; url: string }        // a served local dev/preview URL — a Node web app
  | { kind: "bundle"; srcDoc: string }  // a static HTML/JS/WASM bundle — rendered as an iframe srcdoc
  | { kind: "native"; label: string };  // a native binary launched as its own desktop window (WSLg/host)

/** How a {@link PreviewSource} renders — the descriptor the preview node's frame reads. `iframe` covers
 *  a web URL, a static bundle, AND a wgpu/wasm app compiled to the web; `external` is a native app running
 *  as its own OS window (WSLg / host) — it renders on the desktop, not inside the node. */
export type PreviewRender =
  | { mode: "iframe"; src?: string; srcDoc?: string }
  | { mode: "external"; label: string };

/** Map a {@link PreviewSource} to its render descriptor — the one place `kind` is switched on. Pure. */
export function previewRender(source: PreviewSource): PreviewRender {
  switch (source.kind) {
    case "web":    return { mode: "iframe", src: source.url };
    case "bundle": return { mode: "iframe", srcDoc: source.srcDoc };
    case "native": return { mode: "external", label: source.label };
  }
}

/** Whether a source renders in the sandboxed iframe (web / bundle / wasm) vs on the desktop as its own
 *  native window — the split the preview node uses to pick its render surface. */
export function isIframeSource(source: PreviewSource): boolean {
  return source.kind !== "native";
}

runtime.shared/lib/preview/reviewShot.ts:
// reviewShot (#2623 slice 5c) — the I/O actuator that turns one captured preview shot into review
// findings. It composes the pure review prompts + parser (slice 5a, previewReview.ts) with the multimodal
// LLM call (oneShotVision): send the screenshot to Claude, parse the JSON reply into ReviewFinding[]. The
// caller (the inbox, slice 5d) folds the result into the confirm-gated inbox via mergeFindings. Kept thin
// so the pure logic stays in previewReview.ts and the only side effect here is the model call.

import type { LlmConfig } from "@/shared/lib/core/llmConfig";
import { oneShotVision } from "@/shared/lib/core/claudeComplete";
import {
  reviewSystemPrompt,
  reviewUserPrompt,
  parseFindings,
  type PreviewShot,
  type ReviewFinding,
} from "./previewReview";

/** Mint a stable-enough id for a finding of `shot` — the inbox dedups by shot+title (findingKey), so this
 *  only needs to be unique per (shot, review pass). `seq` disambiguates a batch that lands in one pass. */
function findingId(shot: PreviewShot, index: number, seq: number): string {
  return `${shot.id}:${seq}:${index}`;
}

/**
 * Review one captured shot with the vision model → its findings (all `status: "pending"`). Throws only on
 * a call failure (no key / unsupported provider / network) — a well-formed-but-unparseable reply yields
 * `[]` (parseFindings is tolerant), so a bad review surfaces as "no findings", never a crash.
 *
 * @param seq  a per-pass discriminator for the minted finding ids (default `0`); pass the shot index when
 *             reviewing several shots so their ids don't collide.
 */
export async function reviewShot(cfg: LlmConfig, shot: PreviewShot, seq = 0): Promise<ReviewFinding[]> {
  const reply = await oneShotVision(cfg, reviewSystemPrompt(), reviewUserPrompt(shot), [shot.image]);
  return parseFindings(reply, shot.id, (i) => findingId(shot, i, seq));
}

runtime.shared/lib/runtime/componentLoader.ts:
// The runtime component loader (#3605, epic #3604) — compile a component's source FROM THE GRAPH and run
// it in the LIVE app, with its imports wired to the app's real modules ([`moduleRegistry`]).
//
// This is the deliberate OPPOSITE of the preview bundler (`componentBundle.ts`): the preview ISOLATES —
// it stubs React from a CDN and forbids `@/` first-party imports, so a component runs in a sandboxed
// iframe with no access to the real store/hooks. The loader CONNECTS — it keeps every import external and
// resolves it, at run time, to the app's OWN running module, so a loaded page fires real hooks and reads
// live state. That is the whole point: the graph, not the bundler, is the source of the app's UI.
//
// HOW:
//   1. esbuild-wasm transforms the source (JSX → `jsx()` calls) to CommonJS. A PLATFORM import (a
//      registered live module) is marked external — so `import … from "@/store"` becomes `require("@/store")`
//      in the output. A GRAPH-SIBLING import (one the app can resolve to another graph component's source,
//      #3606) is instead VENDORED — esbuild pulls that source into this build and bundles it, recursively —
//      so a page and its panels compile as one module. Anything else stays external.
//   2. The output is evaluated via `new Function("require","module","exports", code)` and handed a
//      `require` that returns the LIVE module from the registry. An unregistered specifier throws a named
//      error (never a silent stub), so a missing platform module surfaces loudly.
//   3. The component export is returned for a host to mount.
//
// `new Function` runs graph-authored code in the app context — the premise of graph-as-source (the graph
// is the user's own app), but the reason a graph render MUST be wrapped in an error boundary + fallback
// (`GraphComponent`), so a bad node can never white-screen the shell.
import type * as Esbuild from "esbuild-wasm";
import type { ComponentType } from "react";
import { ensureEsbuild } from "@/shared/lib/preview/componentBundle";
import { resolveAppModule, isAppModule, registeredSpecifiers } from "./moduleRegistry";

/** Resolve a first-party specifier to another graph component's SOURCE (its `srcText`), so the loader can
 *  vendor siblings into one compile. Returns `null`/`undefined` when the specifier is NOT a graph component
 *  (then it stays external → the registry). The app supplies a store-backed resolver; the loader stays
 *  store-agnostic. Sibling specifiers must be absolute (a stable key like `graph:<id>`), not relative —
 *  virtual modules have no directory to resolve `./x` against. */
export type GraphSourceResolver = (specifier: string) => string | null | undefined;

/** How the loader treats an import specifier found in graph source. */
export type ImportKind =
  | "platform" //  a registered live app module (react, @/store, a shared/ui primitive) → external `require`
  | "graph" //     a first-party sibling (`@/…` / relative) NOT registered → a graph component to load (#3606)
  | "library"; //  a bare npm specifier → must ALSO be registered (the app owns the dependency), else error

/**
 * Classify an import specifier. Pure — `registered` is injected so this is unit-testable without the
 * live registry. A registered specifier is always `platform` (the app owns it); an unregistered first-
 * party path is a `graph` sibling; anything else bare is a `library` (which, unresolved, is an error at
 * eval time — the app must register every dependency it lets graph code reach).
 */
export function classifyImport(spec: string, registered: (s: string) => boolean): ImportKind {
  if (registered(spec)) return "platform";
  if (spec.startsWith("@/") || spec.startsWith(".") || spec.startsWith("/")) return "graph";
  return "library";
}

/** The esbuild namespace holding vendored graph-sibling sources (kept out of the filesystem resolver). */
const GRAPH_NS = "graph-sibling";

/**
 * Route ONE non-entry import (pure over the live registry + the injected resolver, so it's unit-testable
 * without esbuild — the real compile is browser-only). Three outcomes:
 *   - `{ external: true }` — a registered PLATFORM module (→ `require()`, resolved via the registry), OR a
 *     bare library / unresolved sibling (→ `require` throws a named error at eval time);
 *   - `{ vendor: source }` — a graph SIBLING the app resolved to source: bundle it in, recursively.
 */
export function routeImport(
  path: string,
  resolveGraphSource?: GraphSourceResolver,
): { external: true } | { vendor: string } {
  // GRAPH-FIRST (#3660): consult the resolver BEFORE the registry, so a graph component that PROVIDES a
  // platform specifier (a shared/ui primitive authored as data) overrides the bundled module. An unmatched
  // specifier (a registered module the graph doesn't override, a library, or an unresolved sibling) returns
  // null → external → `makeRequire` resolves it via the registry or throws — identical to the pre-#3660
  // behaviour, so this is inert until a component opts in with `provides`.
  const source = resolveGraphSource?.(path);
  return source != null ? { vendor: source } : { external: true };
}

/** esbuild plugin applying [`routeImport`]: platform + libraries stay external (→ registry `require`),
 *  graph siblings are vendored into this build. Without a resolver it degrades to "everything external" —
 *  the single-component behaviour of #3605. */
function loaderPlugin(resolveGraphSource?: GraphSourceResolver): Esbuild.Plugin {
  return {
    name: "runtime-loader",
    setup(build) {
      build.onResolve({ filter: /.*/ }, (args) => {
        if (args.kind === "entry-point") return undefined;
        const route = routeImport(args.path, resolveGraphSource);
        return "vendor" in route
          ? { path: args.path, namespace: GRAPH_NS, pluginData: { source: route.vendor } }
          : { path: args.path, external: true };
      });
      build.onLoad({ filter: /.*/, namespace: GRAPH_NS }, (args) => ({
        contents: (args.pluginData as { source: string }).source,
        loader: "tsx",
      }));
    },
  };
}

/**
 * Compile graph `source` (a self-standing module string) to CommonJS. Exported for tests + the loader.
 * `jsx: "automatic"` emits `require("react/jsx-runtime")`, so that MUST be a registered platform module.
 * `resolveGraphSource` (optional) vendors sibling graph components into the same build (#3606).
 */
export async function compileToCjs(source: string, resolveGraphSource?: GraphSourceResolver): Promise<string> {
  const esbuild = await ensureEsbuild();
  const result = await esbuild.build({
    stdin: { contents: source, loader: "tsx", sourcefile: "graph-component.tsx" },
    bundle: true,
    format: "cjs",
    write: false,
    jsx: "automatic",
    logLevel: "silent",
    plugins: [loaderPlugin(resolveGraphSource)],
  });
  return result.outputFiles?.[0]?.text ?? "";
}

/** The `require` a loaded module runs against — the registry, with a loud error for an unresolved specifier
 *  so a missing platform registration is a named failure, not a silent `undefined` that throws deep in React. */
export function makeRequire(): (specifier: string) => unknown {
  return (specifier: string) => {
    if (isAppModule(specifier)) return resolveAppModule(specifier);
    throw new Error(
      `runtime loader: import "${specifier}" is not a registered app module. ` +
        `Register it (registerAppModule) or vendor it as a graph component. Available: ${registeredSpecifiers().join(", ")}`,
    );
  };
}

/** Evaluate compiled CJS with the registry-backed `require`, returning its `module.exports`. Pure over its
 *  inputs (the require is injected) so a test can drive it with a fake registry. */
export function evalCjsModule(cjs: string, require: (s: string) => unknown): Record<string, unknown> {
  const module = { exports: {} as Record<string, unknown> };
  // `new Function` runs graph-authored code in the app context — the feature (#3604); the caller wraps it
  // in an error boundary + fallback (GraphComponent) so a bad module can never white-screen the shell.
  const factory = new Function("require", "module", "exports", cjs);
  factory(require, module, module.exports);
  return module.exports;
}

/** Pick the component export from a loaded module: a `default` export, else the first exported function
 *  (React components are functions). `null` when the module exports no component. */
export function pickComponent(exports: Record<string, unknown>): ComponentType<Record<string, unknown>> | null {
  const cand = exports.default ?? Object.values(exports).find((v) => typeof v === "function");
  return typeof cand === "function" ? (cand as ComponentType<Record<string, unknown>>) : null;
}

/**
 * Load a component from its graph `source`: compile → eval against the live registry → pick the component.
 * `resolveGraphSource` (optional) vendors sibling graph components (#3606) — a page pulls in its panels.
 * Throws (compile error / unresolved import / no component export) — the host catches it. NOT memoized here;
 * the host memoizes per (id, source) so a store edit re-loads.
 */
export async function loadComponentFromSource(
  source: string,
  resolveGraphSource?: GraphSourceResolver,
): Promise<ComponentType<Record<string, unknown>>> {
  const cjs = await compileToCjs(source, resolveGraphSource);
  const exports = evalCjsModule(cjs, makeRequire());
  const comp = pickComponent(exports);
  if (!comp) throw new Error("runtime loader: the graph source exports no component (need a default export or an exported function)");
  return comp;
}

runtime.shared/lib/runtime/GraphComponent.tsx:
// GraphComponent (#3605, epic #3604) — mount a component LOADED FROM THE GRAPH, live, in the app tree.
//
// The whole point of the epic: the app's UI comes from the components graph, not bundled files. This host
// reads a component's `srcText` from the store, hands it to the runtime loader (compile → eval → real
// modules), and renders the result — with an ERROR BOUNDARY + fallback around it, because the loaded code
// is graph-authored: a compile error, an unresolved import, or a render throw must degrade to a fallback,
// never white-screen the shell. Re-loads when the store's source changes (a designer edit shows live).
import { Component, useEffect, useState, type ComponentType, type ReactNode } from "react";
import { useAppStore } from "@/store";
import { loadComponentFromSource } from "@/shared/lib/runtime/componentLoader";
import { resolveGraphSource } from "./graphResolver";
import { log } from "@/shared/lib/core/log";
import { ThemeProvider } from "@/shared/ui/kit";

// Per-id COMPILE counter (module-level, survives re-renders) — the loop probe. A healthy page compiles
// ONCE (`#1`) and never again, because the load effect keys on the srcText VALUE and a re-hydrate re-reads
// the same string (`Object.is` true → effect skipped). A fast-climbing `#N` in the `graph-loader` log means
// the source is churning (a new srcText value each hydrate) and the page is recompiling — the real lag risk.
const compileCounts = new Map<string, number>();

/** Catches a RENDER throw from the loaded component (load-time throws are caught by the effect below).
 *  Keyed by the caller so a new source remounts a fresh boundary (React boundaries don't self-reset).
 *
 *  It LOGS what it caught (#3874). A load failure has always logged; a render throw did not, so the two
 *  outcomes were indistinguishable from outside: the log said `mounted "projectspage"` while the screen
 *  showed the fallback, and finding the cause meant patching this class by hand. A graph page that renders
 *  its fallback is exactly when someone needs the reason, so it goes to the log with its stack. */
class GraphErrorBoundary extends Component<{ id: string; fallback: ReactNode; children: ReactNode }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError(): { failed: boolean } {
    return { failed: true };
  }
  componentDidCatch(error: unknown, info: { componentStack?: string | null }): void {
    // One line per frame: the sink caps a single message, and a stack folded into one line gets truncated
    // to uselessness — which is what the by-hand version of this hit first.
    log.warn(`graph-loader: "${this.props.id}" RENDER THREW - falling back: ${String(error)}`, "graph-loader");
    for (const frame of String((error as Error)?.stack ?? "").split("\n").slice(1, 9)) {
      if (frame.trim()) log.warn(`graph-loader:   at ${frame.trim().slice(0, 200)}`, "graph-loader");
    }
    for (const frame of String(info?.componentStack ?? "").split("\n").slice(0, 8)) {
      if (frame.trim()) log.warn(`graph-loader:   in ${frame.trim().slice(0, 160)}`, "graph-loader");
    }
  }
  render(): ReactNode {
    return this.state.failed ? this.props.fallback : this.props.children;
  }
}

/**
 * Render the graph component `id`, passing `props` through. `fallback` shows while loading and on any
 * failure (compile / unresolved import / render throw) — a graph render can never break the shell.
 */
export function GraphComponent({
  id,
  props,
  fallback = null,
  themeId,
}: {
  id: string;
  props?: Record<string, unknown>;
  fallback?: ReactNode;
  /** The theme to resolve for a `themeSystem: "js"` component (#3715) — passed to the wrapping
   *  `<ThemeProvider>`. Ignored for a CSS component (it follows the cascade). Absent ⇒ the base theme. */
  themeId?: string;
}): ReactNode {
  const source = useAppStore((s) => s.components.find((c) => c.id === id)?.srcText);
  // The theme SYSTEM this component renders under (#3715): "js" → wrap in <ThemeProvider> so it can read the
  // resolved token VALUES; "css"/absent → it follows the CSS cascade as today. A primitive selector (string
  // | undefined), so it never churns re-renders (mirrors the `srcText` selector above).
  const themeSystem = useAppStore((s) => s.components.find((c) => c.id === id)?.themeSystem);
  const [Loaded, setLoaded] = useState<ComponentType<Record<string, unknown>> | null>(null);

  useEffect(() => {
    let cancelled = false;
    /* eslint-disable react-hooks/set-state-in-effect -- reset to loading on each (id, source) change */
    setLoaded(null);
    /* eslint-enable react-hooks/set-state-in-effect */
    if (!source) return;
    const n = (compileCounts.get(id) ?? 0) + 1;
    compileCounts.set(id, n);
    const startedAt = performance.now();
    log.info(`graph-loader: compile #${n} "${id}" (source ${source.length} chars)`, "graph-loader");
    loadComponentFromSource(source, resolveGraphSource) // vendor sibling panels (#3606)
      // setState((prev) => …) treats a function arg as an UPDATER — a component IS a function, so wrap it.
      .then((c) => {
        if (cancelled) return;
        log.info(`graph-loader: mounted "${id}" (compile #${n}) in ${Math.round(performance.now() - startedAt)}ms`, "graph-loader");
        setLoaded(() => c);
      })
      .catch((e) => {
        if (cancelled) return;
        log.warn(`graph-loader: "${id}" failed to load — falling back: ${String(e).slice(0, 160)}`, "graph-loader");
        setLoaded(null); // fall through to fallback (a load error → fallback)
      });
    return () => { cancelled = true; };
  }, [id, source]);

  if (!Loaded) return fallback;
  // A `themeSystem: "js"` component renders to a non-CSS surface — wrap it so `useResolvedTheme()` reaches it
  // (#3715). A "css"/absent component renders bare and follows the cascade, byte-identical to before.
  const el = <Loaded {...(props ?? {})} />;
  return (
    <GraphErrorBoundary key={`${id}:${source?.length ?? 0}`} id={id} fallback={fallback}>
      {themeSystem === "js" ? <ThemeProvider themeId={themeId}>{el}</ThemeProvider> : el}
    </GraphErrorBoundary>
  );
}

runtime.shared/lib/runtime/GraphPageFallback.tsx:
// GraphPageFallback (#3648/#3652, epic #3604) — the shared fallback for a graph-hosted page (Fleet /
// Automations / Security / GitHub …) whose source isn't loadable from the components graph. It offers TWO
// in-app recoveries, because the two failure modes need DIFFERENT fixes:
//
//   • "Reload to apply" — `window.location.reload()`. A JUST-MERGED/updated page brings NEW platform-module
//     registrations (appModules + register<X>Platform — BOOT-bound + guarded) and a NEW `SEED_COMPONENTS`
//     glob entry (`import.meta.glob` resolves at module-eval). Neither can be applied mid-session by a
//     re-seed — only a fresh boot re-runs registration + re-globs the seed + re-hydrates. This reload does
//     exactly that, so it reliably applies a new/updated page live without hunting for F5. (#3652)
//
//   • "Re-seed in place" — `hydrateComponents()` reconciles the store toward the packaged seed and pushes
//     missing built-ins. Fixes the lighter case where the library only LOST this page's record but its
//     platform is already live (the common shipped-app case). GraphComponent subscribes to the page's
//     srcText, so a successful re-seed makes the source appear and the host re-renders into the real page.
import { useState, type ReactNode } from "react";
import { useAppStore } from "@/store";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { Button } from "@/shared/ui/controls/Button";

export function GraphPageFallback({ page, icon = "⑃" }: { page: string; icon?: ReactNode }) {
  const hydrateComponents = useAppStore((s) => s.hydrateComponents);
  const [status, setStatus] = useState<"idle" | "seeding" | "seeded" | "error">("idle");

  async function reseed() {
    setStatus("seeding");
    try {
      // If the record seeds AND its platform is already registered, GraphComponent re-renders into the page
      // and this unmounts. If it's still here after, the page was just added/updated → Reload to apply.
      await hydrateComponents();
      setStatus("seeded");
    } catch {
      setStatus("error");
    }
  }

  const description =
    status === "seeded"
      ? `Re-seeded the library in place. If ${page} is still blank it was just added or updated — use Reload to apply it.`
      : status === "error"
        ? "Re-seed failed. Use Reload to apply the latest."
        : `${page} loads from the components graph. If ${page} was just added or updated, Reload to apply it; if the library only lost its record, Re-seed restores it in place.`;

  return (
    <EmptyState
      icon={icon}
      title={`${page} page unavailable`}
      description={description}
      actions={
        <>
          <Button variant="primary" onClick={() => window.location.reload()}>Reload to apply</Button>
          <Button onClick={reseed} disabled={status === "seeding"}>
            {status === "seeding" ? "Re-seeding…" : "Re-seed in place"}
          </Button>
        </>
      }
      style={{ padding: 48 }}
    />
  );
}

runtime.shared/lib/runtime/graphResolver.ts:
// The store-backed graph-sibling resolver (#3606, epic #3604) — lets a graph component import ANOTHER graph
// component by id, so a page can compose its panels. Feature-agnostic (it only reads `@/store`, which shared/
// may import), so it sits with the loader in shared/lib/runtime; the loader stays store-agnostic and takes
// this as an injected [`GraphSourceResolver`].
import { useAppStore } from "@/store";
import type { GraphSourceResolver } from "@/shared/lib/runtime/componentLoader";

/** How a graph component imports a SIBLING by id: `import … from "@/components/<id>"`. There is no physical
 *  `@/components/` dir (feature-first killed the layer dirs, #1309), so this specifier never resolves to a
 *  real module — the loader intercepts it and vendors the sibling's source in its place. */
export const GRAPH_SIBLING_PREFIX = "@/components/";

/** Resolve a graph import to `srcText` the loader vendors — reading a snapshot (`getState`), not a
 *  subscription: a page re-loads on ITS OWN source change (the host keys on that); a sibling/override edit
 *  reflects on the page's next load. Two forms resolve to graph source; anything else returns `null` so it
 *  stays external (→ the registry):
 *    1. `@/components/<id>` — a SIBLING by id (a page composing its panels, #3606).
 *    2. a component whose `provides` field equals the specifier — a graph component OVERRIDING a registered
 *       PLATFORM module (#3660), e.g. a shared/ui primitive authored as DATA. Graph-first: this is why
 *       `routeImport` consults the resolver before the registry. */
export const resolveGraphSource: GraphSourceResolver = (specifier) => {
  const components = useAppStore.getState().components;
  if (specifier.startsWith(GRAPH_SIBLING_PREFIX)) {
    const id = specifier.slice(GRAPH_SIBLING_PREFIX.length);
    return components.find((c) => c.id === id)?.srcText ?? null;
  }
  return components.find((c) => c.provides === specifier)?.srcText ?? null;
};

runtime.shared/lib/runtime/moduleRegistry.ts:
// The runtime module registry (#3605, epic #3604) — the bridge that lets graph-loaded code run INSIDE the
// live app instead of in the preview's isolated sandbox.
//
// A component loaded from the components graph is real React source with real imports — `import { useApp
// Store } from "@/store"`, `import { jsx } from "react/jsx-runtime"`. For its hooks to fire and its store
// reads to be LIVE, those imports must resolve to the app's OWN running modules — the SAME React instance
// (a second copy silently breaks hooks: "Invalid hook call") and the SAME Zustand store. This registry is
// how: the shell registers each platform module by its import specifier at boot, and the loader's runtime
// `require` reads them back here. Everything NOT registered is either a graph sibling (loaded from the
// graph) or an honest "unresolved platform module" error — never a stub.
//
// Pure + framework-free (a Map) so it's unit-testable and has no import cycle with the shell.

const registry = new Map<string, unknown>();

/** Register the app's LIVE module for an import specifier (e.g. `"react"`, `"@/store"`). Idempotent —
 *  a re-register replaces (an HMR re-eval must not double up). */
export function registerAppModule(specifier: string, mod: unknown): void {
  registry.set(specifier, mod);
}

/** The registered live module for a specifier, or `undefined` if none — the loader's `require` lookup. */
export function resolveAppModule(specifier: string): unknown | undefined {
  return registry.get(specifier);
}

/** Is this specifier backed by a real app module? Drives the loader's import classification. */
export function isAppModule(specifier: string): boolean {
  return registry.has(specifier);
}

/** Every registered specifier — for diagnostics + a loader error that names what IS available. */
export function registeredSpecifiers(): string[] {
  return [...registry.keys()].sort();
}

/** Clear the registry (tests only — the app registers once at boot and never clears). */
export function __resetRegistry(): void {
  registry.clear();
}

runtime.shared/lib/security/injectionScan.ts:
// Prompt-injection detector (#1107). A pure, deterministic scan for the high-signal markers of an
// injected/hijacking instruction — the kind a poisoned repo or web page tries to smuggle through the
// planner into the fleet's trusted kickoffs. Used two ways:
//
//   1. The planner provenance gate (#1107): scan planner-authored artifacts (section files,
//      kickoffs, profiles) BEFORE they seed a worker, and surface flags to the user at the existing
//      confirmation boundary. A flag is human-reviewed, not auto-rejected — the planner's output
//      legitimately contains instructions, so the goal is to catch the *malicious* ones.
//   2. Shared detectors for the #1102 fleet warden, which can run the same `scanText` over what a
//      worker reads/writes.
//
// Deterministic + no LLM on purpose: the scan can't itself be prompt-injected. Patterns are tuned
// for HIGH SIGNAL (override phrasing, secret exfiltration, permission/safety bypass) over recall —
// false positives are a quick user dismissal; missed injections are a fleet compromise, but a noisy
// scan gets ignored, so the bar is "rarely appears in a legitimate plan".

/** A category of injection marker — drives how a finding is explained and grouped. */
export type InjectionCategory =
  | "override"      // "ignore previous instructions", role/identity hijack
  | "exfiltration"  // send secrets/env or repo contents to an external destination
  | "perms"         // skip/disable permissions, sandbox, or safety checks
  | "destructive"   // force-push, delete repo, self-merge, rm -rf
  | "ci";           // disable/bypass CI, workflows, or git hooks

export interface InjectionFinding {
  /** The artifact the marker was found in (e.g. `prompts/auth-kickoff.md`). */
  file: string;
  /** 1-based line number of the match. */
  line: number;
  category: InjectionCategory;
  /** Human label for the category. */
  label: string;
  /** The matched substring, trimmed for display. */
  match: string;
  /** The whole line (trimmed/clamped), so the user sees the marker in context. */
  context: string;
}

interface Pattern { category: InjectionCategory; label: string; re: RegExp }

// Each pattern targets a marker that is hostile in any plan deliverable and rare in legitimate ones.
// Verbs are required (not bare nouns) so that *describing* a subsystem ("the CI pipeline", "stores a
// token") doesn't trip — only *instructing* a hostile action does.
const PATTERNS: Pattern[] = [
  // Classic prompt-injection override / identity hijack. A legitimate plan never instructs this.
  { category: "override", label: "instruction-override phrasing",
    re: /\b(ignore|disregard|forget|override)\b[^.\n]{0,40}\b(previous|prior|above|earlier|all|the)?\s*(instructions?|directions?|rules?|prompts?|protocol|guardrails?|system\s*prompt)\b/i },
  { category: "override", label: "role / identity hijack",
    re: /(\byou are now\b|\bact as (an?\s+)?(unrestricted|jailbro|root|admin)|new\s+instructions\s*:|from now on[, ]+(ignore|disregard|you)|^\s*system\s*:\s*)/im },

  // Secret / environment / repo-content exfiltration. Each noun carries its own boundary so the
  // dot-prefixed forms (`.env`) match; `[^\n]` keeps it on one line but tolerates dots between.
  { category: "exfiltration", label: "secret or environment exfiltration",
    re: /\b(send|post|upload|exfiltrate|transmit|leak|curl|wget|fetch)\b[^\n]{0,60}(\benv(ironment)?\b|\bsecrets?\b|\btokens?\b|\bcredentials?\b|\bapi[\s_-]?keys?\b|\bpasswords?\b|\.env\b|\bprintenv\b)/i },
  { category: "exfiltration", label: "post data to an external destination",
    re: /\b(send|post|upload|exfiltrate|transmit|curl|wget)\b[^\n]{0,60}https?:\/\//i },

  // Permission / safety / sandbox bypass.
  { category: "perms", label: "permission or safety bypass",
    re: /(--dangerously[\w-]*|\bskip[\s-]?permissions?\b|\bdisable\b[^.\n]{0,30}\b(security|safety|sandbox|guard|protection|check|review|audit)\b|\bsudo\s|\bchmod\s+777\b|\bbypass\b[^.\n]{0,30}\b(security|permission|guard|sandbox|gate)\b)/i },

  // Destructive or out-of-lane git / GitHub operations.
  { category: "destructive", label: "destructive or out-of-lane git/GitHub op",
    re: /(git\s+push\s+(-f\b|--force)|\bforce[\s-]?push\b|gh\s+repo\s+delete\b|\brm\s+-rf\s+[/~]|git\s+push\b[^.\n]{0,40}\b(main|master)\b)/i },

  // CI / workflow / git-hook tampering — hostile verbs only (authoring a workflow is fine).
  { category: "ci", label: "CI/CD or git-hook tampering",
    re: /\b(disable|skip|bypass|turn\s+off|remove|delete)\b[^.\n]{0,30}(\.github\/workflows|\.git\/hooks|ci\/cd|\bci\b|pipeline|pre-?commit|\bhooks?\b|workflow)\b/i },
];

/** Scan one text blob for injection markers — first match per line per pattern. Pure. */
export function scanText(text: string): Omit<InjectionFinding, "file">[] {
  const out: Omit<InjectionFinding, "file">[] = [];
  const lines = (text ?? "").split(/\r?\n/);
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    for (const p of PATTERNS) {
      const m = p.re.exec(line);
      if (m) {
        out.push({
          line: i + 1,
          category: p.category,
          label: p.label,
          match: m[0].trim().slice(0, 120),
          context: line.trim().slice(0, 200),
        });
      }
    }
  }
  return out;
}

/** Scan a set of named artifacts (file → content). Pure; the planner gate's entry point. */
export function scanArtifacts(artifacts: Record<string, string>): InjectionFinding[] {
  const findings: InjectionFinding[] = [];
  for (const [file, content] of Object.entries(artifacts)) {
    for (const f of scanText(content)) findings.push({ file, ...f });
  }
  return findings;
}

runtime.shared/lib/session/assignments.ts:
// Document-assignment model — the single source of truth for *which* unified-store
// document seeds a session's kickoff message:
//
//   • startupPrompt — the ONE document that seeds a session's kickoff message.
//
// ─── Mental model: "global default + overrides" ───────────────────────────────
//
// `startupPrompt` is assigned along a four-level cascade, from broadest to most
// specific:
//
//   default  →  project  →  repo  →  session
//
// `default` is the global baseline that applies everywhere. Each narrower level
// refines it for a smaller scope (one project, one repo within a project, one
// live session/pane):
//
//   startupPrompt — OVERRIDE. Exactly one document wins. The most specific level
//                   that names a document supplies it; an absent / null entry
//                   means "inherit" and falls through to the next broader level.
//                   Nothing assigned anywhere → null (the caller uses its
//                   built-in default prompt).
//
// Resolution is PURE — no I/O, no store access. Callers (session launch in #326)
// hold the {@link DocAssignments} state and call {@link resolveStartupPrompt} at
// launch time.

/** A unified-store document, identified by its base-relative path (see documents.ts). */
export type DocRef = string;

/** The scope a session runs in. Any level may be absent (e.g. an ad-hoc console
 *  with no project). Resolution only consults the levels a scope provides. */
export interface AssignmentScope {
  /** Sanitized project key, or null/absent for an unscoped session. */
  projectId?: string | null;
  /** Full repo name (e.g. `owner/web`), or null/absent. */
  repo?: string | null;
  /** Live session / pane id, or null/absent. The narrowest level. */
  session?: string | null;
}

/** Composite key for a per-repo assignment, scoped to its project so the same
 *  repo under two projects never collides. */
export function scopeKey(projectId: string, repo: string): string {
  return `${projectId}::${repo}`;
}

// ─── Startup prompt: single-doc override cascade ──────────────────────────────

/** Per-level assignment of the kickoff document. A `null`/absent value at a
 *  level means "inherit" (fall through to the next broader level). */
export interface StartupPromptCascade {
  /** Global default kickoff document, or null for the built-in prompt. */
  default: DocRef | null;
  /** Overrides keyed by project id. */
  project: Record<string, DocRef | null>;
  /** Overrides keyed by {@link scopeKey}. */
  repo: Record<string, DocRef | null>;
  /** Overrides keyed by session/pane id. */
  session: Record<string, DocRef | null>;
}

/** The complete assignment state for a workspace. */
export interface DocAssignments {
  startupPrompt: StartupPromptCascade;
}

/** A fresh, fully-empty assignment state. */
export function emptyAssignments(): DocAssignments {
  return {
    startupPrompt: { default: null, project: {}, repo: {}, session: {} },
  };
}

/**
 * The cascade levels that apply to a scope, broadest → narrowest. Levels whose
 * scope key is absent are skipped (an unscoped console only ever sees `default`).
 */
function startupLevels(a: StartupPromptCascade, scope: AssignmentScope): (DocRef | null | undefined)[] {
  const out: (DocRef | null | undefined)[] = [a.default];
  if (scope.projectId) out.push(a.project[scope.projectId]);
  if (scope.projectId && scope.repo) out.push(a.repo[scopeKey(scope.projectId, scope.repo)]);
  if (scope.session) out.push(a.session[scope.session]);
  return out;
}

/**
 * Resolves the single kickoff document for a scope, following
 * session → repo → project → default. The most specific level that names a
 * document wins; a `null`/absent entry inherits from the next broader level.
 * Returns `null` when nothing is assigned at any applicable level, in which case
 * the caller uses its built-in default prompt.
 */
export function resolveStartupPrompt(
  assignments: DocAssignments,
  scope: AssignmentScope,
): DocRef | null {
  const levels = startupLevels(assignments.startupPrompt, scope);
  // Walk narrowest → broadest; first explicit (truthy) value wins.
  for (let i = levels.length - 1; i >= 0; i--) {
    const v = levels[i];
    if (v) return v;
  }
  return null;
}

runtime.shared/lib/session/autoSpawn.ts:
// The AUTO-SPAWN GATE (#3498) — the ONE place that may authorise starting a session without a human
// asking for it. Nothing else in the app is allowed to make that call.
//
// ── WHY THIS IS A GATE AND NOT A CONDITION ──────────────────────────────────────────────────────────
// Automatic session spawning is the highest-consequence capability in the app: a session runs a real
// LLM against a real repo with real credentials, and one that spawns itself can do so repeatedly. The
// maintainer's constraint is therefore explicit — ONLY the debug session may ever be spawned
// automatically, and only while a Settings toggle is on. This module is the enforcement point, kept
// separate from the spawning mechanism so the lock can exist (and be tested) before any door does.
//
// ── THE THREE INDEPENDENT CONDITIONS, ALL FAIL-CLOSED ───────────────────────────────────────────────
//  1. The setting is ON. Default OFF; anything that is not literally `true` reads as off, so a missing,
//     undefined, or corrupted value disables auto-spawn rather than enabling it.
//  2. The role is EXACTLY {@link AUTO_SPAWNABLE_ROLE}. This is an ALLOW-LIST of one, never a deny-list:
//     a role added to `SessionRole` later is refused by default instead of quietly inheriting the
//     capability. That is the same reasoning that makes the restricted-role command surface an
//     allow-list — the failure mode of a deny-list is silent over-permission.
//  3. The caller is the request-intake path. Enforced by this being the only exported authoriser: a
//     second spawn path is the bug to prevent, so `autoSpawnDecision` is the single funnel and its
//     refusals carry a reason rather than returning a bare `false`.
//
// A refusal is never silent — {@link autoSpawnDecision} names WHY, so a blocked spawn is diagnosable
// instead of looking like nothing happened (the failure shape that hid the request queue for a day).

import { ROLE_DEFAULTS, type SessionRole } from "./roleModel";

/**
 * The ONLY role that may ever be auto-spawned (#3498).
 *
 * `satisfies SessionRole` is load-bearing: if the `debugger` role is renamed or removed, this stops
 * compiling rather than silently becoming a string that matches nothing (which would disable the
 * feature quietly) or, worse, matching a different role.
 */
export const AUTO_SPAWNABLE_ROLE = "debugger" satisfies SessionRole;

/** What the caller wants to auto-spawn, and whether the user has enabled auto-spawn at all. */
export interface AutoSpawnRequest {
  /** The role of the session that WOULD be started. */
  role: SessionRole | null | undefined;
  /** The Settings toggle (`autoSpawnDebugSessions`). Anything but `true` is treated as off. */
  enabled: boolean | null | undefined;
}

/** Allowed, or refused WITH the reason — a refusal must be diagnosable, never a bare `false`. */
export type AutoSpawnDecision = { allowed: true } | { allowed: false; reason: string };

/**
 * THE single authoriser for starting a session automatically (#3498). Every auto-spawn call site must
 * route through this; there is deliberately no other exported way to authorise one.
 *
 * Order matters for the reason text: the setting is checked FIRST so that with auto-spawn off, the
 * refusal says so plainly for every role rather than blaming the role.
 */
export function autoSpawnDecision(req: AutoSpawnRequest): AutoSpawnDecision {
  // Fail-closed: only a literal `true` enables. Undefined/null/missing ⇒ off.
  if (req.enabled !== true) {
    return {
      allowed: false,
      reason: "auto-spawn is disabled — turn it on in Settings → Security (it is off by default)",
    };
  }
  if (req.role !== AUTO_SPAWNABLE_ROLE) {
    return {
      allowed: false,
      reason:
        `only the '${AUTO_SPAWNABLE_ROLE}' session may be auto-spawned; ` +
        `'${req.role ?? "(none)"}' must be started explicitly`,
    };
  }
  return { allowed: true };
}

/** {@link autoSpawnDecision} as a boolean, for call sites that don't surface the reason. */
export function mayAutoSpawn(req: AutoSpawnRequest): boolean {
  return autoSpawnDecision(req).allowed;
}

/**
 * Every role the app defines, at RUNTIME — so the gate's tests enumerate the real union rather than a
 * hand-copied list that would drift the moment a role is added. `ROLE_DEFAULTS` is
 * `Record<SessionRole, …>`, so its keys ARE the union.
 */
export function allSessionRoles(): SessionRole[] {
  return Object.keys(ROLE_DEFAULTS) as SessionRole[];
}

runtime.shared/lib/session/checkpoint.ts:
// Triage session continuity ("begin where we left off").
//
// A triage session writes a short "where we left off" note via the `bsc-checkpoint`
// shell helper, which overwrites a per-repo *checkpoint document* in the unified
// store (plain file — no Tauri IPC). At the next triage launch the checkpoint is
// composed onto the triage prompt so the agent resumes with that context.
//
// Pure logic only; the wiring lives in the store (assigns the per-pane checkpoint
// doc), TerminalView (composes at launch), and pty_create (env + helper injection).

/** Heading the previous session's checkpoint is appended under, in the next prompt. */
export const CHECKPOINT_HEADING = "# Where we left off (from your previous session)";

/**
 * Compose the prompt baked into a triage launch: the base triage prompt, plus —
 * when a prior session left a non-empty checkpoint — that checkpoint under a clear
 * heading so the agent resumes with it. Returns `base` unchanged when there's no
 * checkpoint (first run, or it was never written).
 *
 * @param base the triage prompt (verbatim TRIAGE_PROMPT or a resolved doc).
 * @param checkpoint the prior session's checkpoint text, or null/undefined/empty.
 */
export function composeStartupPrompt(base: string, checkpoint: string | null | undefined): string {
  const note = (checkpoint ?? "").trim();
  if (!note) return base;
  return `${base}\n\n${CHECKPOINT_HEADING}\n\n${note}`;
}

/**
 * Unified-store relpath for a repo's triage checkpoint document. `sanitizedKey` is
 * the on-disk project folder (sanitize_project_key); `repo` is the full name
 * (owner/name) — only the name segment is used, slugged to a filesystem-safe stem.
 * Mirrors {@link scriptDocRelpath}'s `projects/{key}/prompts/…` layout so it lands
 * beside the planner-authored startup scripts.
 */
export function checkpointDocRelpath(sanitizedKey: string, repo: string): string {
  const name = (repo.split("/").pop() || repo).trim();
  const slug = (name.replace(/[^A-Za-z0-9._-]/g, "-") || "repo").toLowerCase();
  return `projects/${sanitizedKey}/prompts/${slug}-checkpoint.md`;
}

/**
 * Unified-store relpath for a fleet *agent's* checkpoint document, keyed by the
 * agent/stream id rather than the repo — so two agents sharing one repo clone keep
 * separate "where we left off" notes instead of clobbering each other. `agentId` is
 * a stream id (already slug-like); it is re-slugged defensively.
 */
export function agentCheckpointDocRelpath(sanitizedKey: string, agentId: string): string {
  const slug = (agentId.replace(/[^A-Za-z0-9._-]/g, "-") || "agent").toLowerCase();
  return `projects/${sanitizedKey}/prompts/${slug}-checkpoint.md`;
}

runtime.shared/lib/session/commandGate.ts:
// Role gate (#219) — command classification + the role's command check. Classifies a shell command
// as a `git`/`gh` read or write, then decides whether a role's tier permits it. Pure enforcement
// core, free of React / xterm / Tauri. Re-exported from `sessionRoles.ts`.

import type { RoleCapability } from "./roleModel";

// ── Command classification ──────────────────────────────────────────────────────

const GIT_WRITE = new Set([
  "push", "commit", "merge", "rebase", "reset", "revert", "cherry-pick", "tag", "am",
  "apply", "branch", "checkout", "switch", "restore", "stash", "mv", "rm", "add", "clean",
]);

const GH_WRITE_VERBS = new Set([
  "create", "edit", "delete", "close", "reopen", "merge", "comment", "add", "remove",
  "develop", "ready", "lock", "unlock", "transfer", "pin", "unpin", "rename", "sync",
]);

const HTTP_WRITE = new Set(["POST", "PATCH", "PUT", "DELETE"]);

export interface CommandClass {
  /** The leading binary (`git`, `gh`, `npm`, …). */
  tool: string;
  /** True when the command mutates state (a write). */
  mutating: boolean;
}

/**
 * Classify a shell command as a `git`/`gh` read or write (other tools are reported as
 * non-mutating — they're gated elsewhere). `gh api` is mutating when its method
 * (`--method` / `-X`) is a write verb.
 */
export function classifyCommand(cmd: string): CommandClass {
  const tokens = cmd.trim().split(/\s+/).filter(Boolean);
  const tool = tokens[0] ?? "";

  if (tool === "git") {
    return { tool, mutating: GIT_WRITE.has(tokens[1] ?? "") };
  }
  if (tool === "gh") {
    if (tokens[1] === "api") {
      const flag = tokens.indexOf("--method") >= 0 ? "--method" : "-X";
      const i = tokens.indexOf(flag);
      const method = (i >= 0 ? tokens[i + 1] ?? "" : "GET").toUpperCase();
      return { tool, mutating: HTTP_WRITE.has(method) };
    }
    return { tool, mutating: GH_WRITE_VERBS.has(tokens[2] ?? "") };
  }
  return { tool, mutating: false };
}

export interface CommandDecision {
  allowed: boolean;
  /** A clear, non-technical reason when denied. */
  reason?: string;
}

/**
 * Decide whether a role may run a command. Only `git`/`gh` are gated here (other
 * tools pass — they're handled by the command allowlist). Tier rules: `none` denies
 * all, `read` allows non-mutating only, `write` allows all.
 */
export function checkCommand(cap: RoleCapability, cmd: string): CommandDecision {
  const { tool, mutating } = classifyCommand(cmd);
  const tier = tool === "gh" ? cap.github : tool === "git" ? cap.git : null;
  if (tier === null) return { allowed: true };
  if (tier === "none") {
    return { allowed: false, reason: `the ${cap.role} role has no ${tool} access` };
  }
  if (mutating && tier === "read") {
    return { allowed: false, reason: `the ${cap.role} role can read but not modify via ${tool}` };
  }
  return { allowed: true };
}

runtime.shared/lib/session/commons.ts:
// Director-owned commons (#851) — the repo-root shared files that EVERY stream depends on and
// that feature-decomposition can't carve apart: the ignore file, the dependency manifest +
// lockfile, the TS/build config, CI workflows, the env template, and formatter/linter config.
//
// Worktrees isolate the working *directory*, not the *merge*: each worker that appends to one of
// these on its own branch collides at integration. The fix is a single owner + dependency-gating,
// with the **director** as that owner (it lives at the project root, sees every worktree, and is
// the integrator — and these commons are integration concerns). This module is the pure source of
// truth for the commons set: which paths they are (derived from the stack), the owns-exclusion that
// keeps every feature stream OUT of them, and the union-merge subset. Free of React / Tauri imports
// so it's unit-testable in isolation (matches sessionRoles.ts).

/** A stack tag describing the project's tech (lowercased identifiers like `react`, `rust`, `node`). */
export type StackTag = string;

/**
 * Repo-root commons present in EVERY project regardless of stack — the ignore file, CI workflows,
 * the env template, and the common formatter/linter configs. These are the director's lane and are
 * excluded from every feature stream's `owns`.
 */
const BASE_COMMONS: string[] = [
  ".gitignore",
  ".gitattributes",
  ".github/workflows/**",
  ".env.example",
  // Formatter / linter config (cross-stack — present for JS, Rust, Python projects alike).
  ".editorconfig",
  ".prettierrc",
  ".prettierrc.*",
  "prettier.config.*",
  ".eslintrc",
  ".eslintrc.*",
  "eslint.config.*",
];

/**
 * Stack-specific commons keyed by a tag substring. Each entry's globs are added when ANY of the
 * project's stack tags contains the key (case-insensitive) — so `react`/`node`/`typescript`/`vite`
 * all pull in the JS/TS manifest + tsconfig, and `rust`/`cargo` pull in the Cargo manifest.
 */
const STACK_COMMONS: Array<{ match: string[]; globs: string[] }> = [
  {
    // JS/TS ecosystems: the package manifest + every lockfile flavor, and the TS/build config.
    match: ["node", "npm", "pnpm", "yarn", "react", "vue", "svelte", "next", "vite", "typescript", "ts", "javascript", "js", "tauri"],
    globs: [
      "package.json",
      "package-lock.json",
      "pnpm-lock.yaml",
      "yarn.lock",
      "tsconfig.json",
      "tsconfig.*.json",
    ],
  },
  {
    // Rust: the Cargo manifest + lockfile (workspace root).
    match: ["rust", "cargo", "tauri"],
    globs: ["Cargo.toml", "Cargo.lock"],
  },
  {
    // Python: the project manifests + common lockfiles.
    match: ["python", "py", "poetry", "pip"],
    globs: ["pyproject.toml", "setup.py", "setup.cfg", "requirements*.txt", "poetry.lock", "Pipfile", "Pipfile.lock"],
  },
  {
    // Go: the module manifest + checksum file.
    match: ["go", "golang"],
    globs: ["go.mod", "go.sum"],
  },
];

/**
 * The line-additive commons whose merges should use git's `merge=union` driver: files that streams
 * only ever APPEND lines to (ignore entries, env keys), so concatenating both sides on merge is the
 * correct resolution and any residual race auto-resolves without a conflict. (NOT the structured
 * files — package.json/tsconfig/Cargo.toml — where a blind union would produce invalid JSON/TOML.)
 */
export const UNION_MERGE_COMMONS: string[] = [".gitignore", ".env.example"];

/**
 * Pull candidate stack tags out of the free-text `stack.md` section the planner writes (#851). The
 * stack section is prose, not a tag list, so we tokenize it into lowercase words and let {@link
 * commonsGlobsForStack}'s substring match recognize the technologies (`react`, `rust`, `node`, …).
 * Cheap and order-independent; unrecognized words simply don't match any stack entry.
 */
export function stackTagsFromSection(stackSection: string): StackTag[] {
  if (!stackSection) return [];
  const seen = new Set<string>();
  for (const tok of stackSection.toLowerCase().match(/[a-z][a-z0-9+.#-]*/g) ?? []) {
    if (tok.length >= 2) seen.add(tok);
  }
  return [...seen];
}

/**
 * Derive the repo-root commons set from the project's stack tags. Always includes {@link
 * BASE_COMMONS}; adds each stack entry whose `match` key is a substring of any tag. Deduped and
 * stable-ordered (base first, then stack additions in declaration order). With no recognized tag the
 * caller still gets the universal base commons.
 */
export function commonsGlobsForStack(stack: StackTag[]): string[] {
  const tags = stack.map((t) => t.toLowerCase().trim()).filter(Boolean);
  const out = [...BASE_COMMONS];
  for (const entry of STACK_COMMONS) {
    if (entry.match.some((m) => tags.some((t) => t.includes(m)))) {
      for (const g of entry.globs) if (!out.includes(g)) out.push(g);
    }
  }
  return out;
}

/** True when `path` is one of the commons globs in `commons` (uses the same glob matcher the role
 *  gate uses; imported lazily to avoid a cycle isn't needed — sessionRoles has no commons import). */
function pathInCommons(path: string, commons: string[], match: (glob: string, p: string) => boolean): boolean {
  return commons.some((g) => g === path || match(g, path));
}

/**
 * Strip any commons path from a feature stream's `owns` (the owns-exclusion, #851 step 1): the
 * director owns the commons, so no feature stream may list one. A stream that owned `.gitignore` or
 * `package.json` would re-introduce the parallel-append collision; this enforces the single-owner
 * rule by construction. `match` is the glob matcher (injected to avoid importing the heavier
 * sessionRoles here for a one-liner).
 */
export function excludeCommonsFromOwns(owns: string[], commons: string[], match: (glob: string, p: string) => boolean): string[] {
  return owns.filter((o) => {
    // Drop an exact commons glob the stream declared, and any concrete path that falls inside one.
    if (commons.includes(o)) return false;
    return !pathInCommons(o, commons, match);
  });
}

runtime.shared/lib/session/ensureClaudeRunning.t:
// Resume for a pane whose PTY is ALREADY ALIVE (#3998).
//
// Every Resume site in the app ultimately relies on `pty_create` to launch the agent — but
// `pty_create` returns before it ever reads `init_cmd` when a session already exists for the pane
// ("reconnect to existing session"). So for a live pane, the carefully-resolved
// `claude --continue 2>/dev/null || claude` is computed, handed to the backend, and thrown away.
// The pane gets a Ctrl+L repaint of its bash prompt and nothing else. That is why Resume appeared to
// do nothing on a session whose agent had already exited.
//
// `TerminalView` never remounts such a pane either: it is portal-hosted keyed by `paneId`, so the
// `runId` bump a resume performs re-keys the SLOT, not the terminal. Only a pane in a placeholder
// state (ended / disabled / dormant) unmounts and remounts.
//
// So the fix cannot live in the launch path — the launch path is unreachable. It has to act on the
// live shell directly: ask what the pane is actually doing, and if it is sitting at a prompt, type
// the resume command into it.

import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { log } from "@/shared/lib/core/log";

/** `claude --continue`, degrading to a fresh session when there is no conversation to resume (#3937).
 *  Defined here rather than in `app/console/lib/resumeClaude.ts` so BOTH the mount-time launch path
 *  and this live-shell path emit the byte-identical command — a resumed pane must not depend on which
 *  of the two routes happened to reach it. stderr is dropped because claude's "no session" message is
 *  expected on the first `--continue` of a fresh worktree. */
export const CONTINUE_OR_FRESH = "claude --continue 2>/dev/null || claude";

/** What the backend reports for one pane (`pty_pane_runtime`). */
export type PaneRuntime = {
  paneId: string;
  /** A PTY session exists — `pty_create` would RECONNECT rather than launch. */
  live: boolean;
  /** Its shell has a live descendant, i.e. something is running in it. */
  busy: boolean;
};

/** Why a pane was or wasn't started, for logging and tests. */
export type ResumeOutcome = "started" | "already-running" | "not-live";

/**
 * Decide what a resume should do with each pane, given the backend's runtime report.
 *
 * Pure so the policy is testable without a live PTY. The three cases:
 *  - `not-live`     — no PTY yet. Do nothing: the pane's mount will run the normal launch path,
 *                     which handles `--continue` properly. Typing into a shell that doesn't exist
 *                     would be dropped anyway.
 *  - `already-running` — the shell has a descendant. Do nothing. This is the guard that stops a
 *                     resume from injecting a second `claude` into an agent that is mid-turn, and it
 *                     is why the backend probe asks about DESCENDANTS rather than trying to spot a
 *                     process named `claude` (which is `node.exe` on Windows).
 *  - `started`      — live, at a prompt. Type the resume command in.
 */
export function planResume(runtimes: readonly PaneRuntime[]): Map<string, ResumeOutcome> {
  const out = new Map<string, ResumeOutcome>();
  for (const r of runtimes) {
    out.set(r.paneId, !r.live ? "not-live" : r.busy ? "already-running" : "started");
  }
  return out;
}

/**
 * Make sure claude is running in each of `paneIds` whose PTY is alive but idle.
 *
 * Batched: the backend's busy check walks the process table, so asking about every pane at once costs
 * one walk instead of N — a project-wide resume touches dozens of panes.
 *
 * Returns the per-pane outcome so callers can report "started N" honestly instead of claiming a
 * resume that didn't happen.
 */
export async function ensureClaudeRunning(paneIds: readonly string[]): Promise<Map<string, ResumeOutcome>> {
  if (paneIds.length === 0) return new Map();
  const runtimes = await safeInvoke<PaneRuntime[]>("pty_pane_runtime", { paneIds: [...paneIds] }, []);
  const plan = planResume(runtimes);

  const started: string[] = [];
  for (const [paneId, outcome] of plan) {
    if (outcome !== "started") continue;
    // A plain write, NOT `injectPrompt`: that wraps text in bracketed-paste markers for claude's TUI,
    // and this is going to a bash prompt, where the markers would be echoed as literal characters.
    // The trailing newline is the Enter that runs it.
    await safeInvoke("pty_write", { paneId, data: `${CONTINUE_OR_FRESH}\n` }, undefined);
    started.push(paneId);
  }
  if (started.length > 0) {
    log.info(`resume: started claude in ${started.length} idle pane(s): ${started.join(", ")}`);
  }
  return plan;
}

runtime.shared/lib/session/launchRules.ts:
// Role gate (#219) — launch wiring. Renders a role's capability into the concrete permission
// artifacts a session is launched with: the write-tool `permissions.allow`/`deny` rules
// ({@link roleWriteRules}), whole-tool denies ({@link roleDeniedTools}), the command-prefix denies
// merged into the allowlist ({@link roleDeniedCommands}), and the bsc-agent-native permission doc
// ({@link bscAgentPerms}). Pure enforcement core, free of React / xterm / Tauri. Re-exported from
// `sessionRoles.ts`.

import type { AccessTier, RoleCapability } from "./roleModel";
import { DB_OWNED_PLAN_FILES, DEP_MANIFEST_FILES, hasScopedWriteCarveOut, isRestrictedRole, mayFileToolingRequest, TOOLING_REQUEST_COMMAND } from "./roleModel";

// ── Launch wiring: write-tool permission rules ──────────────────────────────────

/** The file-mutating tools gated by a WHOLE-TOOL deny (bare tool name, no path). Claude Code has no
 *  `MultiEdit` tool (removed) and a bare `Edit` deny does NOT cover `Write`/`NotebookEdit` — they are
 *  separate tools — so all three must be listed to block every file write (#3534). */
const WRITE_TOOLS = ["Edit", "Write", "NotebookEdit"];

/** A PATH-SCOPED file rule uses ONLY `Edit(<glob>)`: Claude Code matches file-permission rules on the
 *  `Edit` tool alone, and that ONE rule covers every file-editing tool (Write/NotebookEdit). Emitting
 *  `Write(<glob>)`/`NotebookEdit(<glob>)`/`MultiEdit(<glob>)` produces rules Claude Code never matches —
 *  a silent no-op for an allow, and (worse) an unenforced deny (#3534). */
export const editPathRule = (glob: string): string => `Edit(${glob})`;

export interface ToolPermissionRules {
  /** Rules to auto-approve (Claude Code `permissions.allow`). */
  allow: string[];
  /** Rules to block (`permissions.deny`; deny wins over allow). */
  deny: string[];
}

/**
 * Declarative `settings.json` permission rules that encode {@link canWritePath} for
 * the file-write tools at session launch — the write-tool counterpart to
 * {@link roleDeniedCommands}.
 *
 * - `code: "none"` (planner/director/triage) — {@link canWritePath} is always false,
 *   so deny every write tool outright (bare tool names = whole-tool deny).
 * - `code: "write"` with a boundary — auto-approve each `writeGlob` as
 *   `Tool(<glob>)` allow rules (exactly the paths {@link canWritePath} accepts).
 *   Writes outside the boundary fall through to Claude Code's default prompt; a
 *   hard outside-boundary *block* is the PreToolUse-hook follow-on.
 * - `code: "write"` with no boundary yet — no rules (writes follow the default),
 *   since the ownership globs aren't assigned to the pane.
 *
 * {@link canWritePath} stays the authoritative runtime predicate; these rules mirror
 * it into the tools at launch.
 */
export function roleWriteRules(cap: RoleCapability): ToolPermissionRules {
  if (cap.code === "none") {
    // Scoped carve-out (#851): a `code: "none"` role WITH explicit writeGlobs (the director's
    // commons) auto-approves the write tools for EXACTLY those globs. Claude Code's precedence is
    // deny > allow, so the whole-tool deny would mask any narrower allow — instead of denying the
    // bare tools we emit only the per-glob allows. Any write OUTSIDE the commons falls through to
    // the default prompt and is hard-blocked by the bsc-scope hook ({@link scopeWriteGlobs}), so
    // the director can write the commons and is denied all other code writes.
    if (hasScopedWriteCarveOut(cap)) {
      return { allow: cap.writeGlobs.map(editPathRule), deny: [] };
    }
    return { allow: [], deny: [...WRITE_TOOLS] };
  }
  const allow = cap.writeGlobs.map(editPathRule);
  // Role-specific deny set, layered over the write-glob allows (deny wins over allow):
  // - planner: the DB-owned plan-state artifacts (#1070) — its *.md/*.json globs would otherwise
  //   auto-approve a stray `deploy.md`/`phases.json`; force it to the `bsc-plan` CLI.
  // - worker: the dependency manifests + lockfiles (#1111) — the planner locks deps once and
  //   publish seeds them, so a worker editing its own manifest is the parallel-redefinition that
  //   collides at integration; a new dep routes through the director.
  const denyFiles = cap.role === "planner" ? DB_OWNED_PLAN_FILES
    : cap.role === "worker" ? DEP_MANIFEST_FILES
    : [];
  const deny = denyFiles.map(editPathRule);
  return { allow, deny };
}

/**
 * Whole-tool denies by role BEYOND the write-path tools (#1036) — currently the sub-agent **Task**
 * tool for **workers**. A worker must not spawn its OWN sub-agents: each spawned agent reads as
 * fresh activity that the always-on coordinator keeps trying to relaunch the worker for (a wake
 * request every poll), and it blurs the worker's lane. A worker does its assigned issue directly;
 * spinning up helper sessions is the director's job. Denied by bare tool name — the same whole-tool
 * deny {@link roleWriteRules} uses for Edit/Write — so it's a hard block at launch, no prompt, no
 * delay. Merged into `denyToolRules` at session launch.
 */
export function roleDeniedTools(cap: RoleCapability): string[] {
  const out: string[] = [];
  if (cap.role === "worker") out.push("Task");
  // Network gate (#1107): `net: "none"` denies the web tools outright at launch — the lever that
  // turns OFF the planner's (or any agent's) live injection surface. `read` (the default) leaves
  // them allowed, with results framed as untrusted data.
  if (cap.net === "none") out.push("WebFetch", "WebSearch");
  return out;
}

// ── Launch wiring: command-allowlist denies ────────────────────────────────────

/** git write subcommand prefixes (the backend wraps each as `Bash(<prefix> *)`). */
const GIT_WRITE_DENY = [
  "git push", "git commit", "git merge", "git rebase", "git reset", "git revert",
  "git cherry-pick", "git tag", "git am", "git apply",
];

/** gh write command prefixes + writing `gh api` methods. */
const GH_WRITE_DENY = [
  "gh issue create", "gh issue edit", "gh issue close", "gh issue reopen",
  "gh issue comment", "gh issue delete", "gh issue lock", "gh issue transfer", "gh issue pin",
  "gh pr create", "gh pr merge", "gh pr close", "gh pr edit", "gh pr comment", "gh pr ready", "gh pr review",
  "gh label create", "gh label edit", "gh label delete",
  "gh release create", "gh release edit", "gh release delete",
  "gh repo create", "gh repo edit", "gh repo delete",
  "gh api --method POST", "gh api --method PATCH", "gh api --method PUT", "gh api --method DELETE",
  "gh api -X POST", "gh api -X PATCH", "gh api -X PUT", "gh api -X DELETE",
];

/** `bsc ui` (component/kit store) mutating verb prefixes (#2470) — denied at `ui: "read"` so a
 *  session can READ the kit it implements against but never redefine it. Includes the deprecated
 *  `bsc component` alias's verbs while that alias lives (#2469); deny-wins keeps these solid over
 *  the baseline's broad `bsc` allow. */
const UI_WRITE_DENY = [
  "bsc ui set", "bsc ui remove", "bsc ui kit set", "bsc ui kit remove",
  "bsc component set", "bsc component remove", "bsc component kit set", "bsc component kit remove",
];

/** File-mutating shell commands denied for a WRITE-LESS role (#2932) — the bash counterpart to the
 *  whole-tool Edit/Write deny in {@link roleWriteRules}. A `code: "none"` role with no scoped write
 *  carve-out writes NOTHING: not via the Edit/Write tools (already denied), and not via bash either —
 *  otherwise (as happened) a session bypasses the tool-deny with `tee`/`cp`/`echo > file` and mutates
 *  the repo (e.g. `src-tauri/data/`, triggering a rebuild). Denies the common file writers; shell
 *  redirection (`>`) can't be prefix-denied and is caught by the always-on `bsc-confine` FS hook.
 *  Carve-out roles (documentor/marketer/a commons director) and writers (planner/worker) are EXCLUDED —
 *  they write their scoped globs via the Write tool, not bash. */
const FILE_WRITE_DENY = [
  "tee", "dd", "truncate", "install", "cp", "mv", "ln", "patch", "sponge",
  "sed -i", "sed --in-place", "perl -i",
  "vi", "vim", "nano", "emacs", "ed", "ex",
];

/**
 * Command-prefix denies to apply at session launch for a role, merged into the
 * session's `deniedCommands` (the backend wraps each as `Bash(<prefix> *)`, and a
 * specific deny overrides the broad `git`/`gh` allow). A first-layer gate: blocks the
 * args-bearing mutating commands while leaving reads alone. `none` tiers deny the tool
 * outright.
 *
 * This is the launch-time allowlist layer; complete subcommand-granular enforcement
 * (incl. no-arg variants) is a PreToolUse hook (follow-on), and the authoritative
 * publish gate is `checkCommand` at the executor call site.
 */
export function roleDeniedCommands(cap: RoleCapability): string[] {
  const out: string[] = [];
  if (cap.git === "none") out.push("git");
  else if (cap.git === "read") out.push(...GIT_WRITE_DENY);
  if (cap.github === "none") out.push("gh");
  else if (cap.github === "read") out.push(...GH_WRITE_DENY);
  // UI store tier (#2470), rendered like git/gh. FAIL-CLOSED on the tier: only an explicit
  // `"write"` skips the mutating-verb denies, so a capability read from a STALE config-dir
  // override that predates the `ui` field (#2325 floor-merge hazard — the merged role OBJECT can
  // lack it) behaves as `"read"`, never as an accidental grant.
  if (cap.ui === "none") out.push("bsc ui", "bsc component");
  else if (cap.ui !== "write") out.push(...UI_WRITE_DENY);
  // A write-less role (code:none, no carve-out) writes NOTHING — deny the file-mutating bash commands
  // too, the counterpart to its whole-tool Edit/Write deny (#2932). Shell redirection (`>`) can't be
  // prefix-denied; the always-on `bsc-confine` FS hook is the complete layer.
  //
  // A RESTRICTED role keeps these denies even though it HAS a carve-out (#3373). Its carve-out is a
  // tool-only staging dir: it writes `scratch/**` with the Write tool and applies it with its one store
  // CLI. It has no business running `cp`/`mv`/`tee`/`sed -i` at all — its spec says in as many words
  // not to reach for bash to sidestep the file rules — so the shell mutation set stays denied. Without
  // this clause the carve-out would silently UN-deny them, widening the session well past the staging
  // dir the design intended.
  const carveOutWritesViaShell = hasScopedWriteCarveOut(cap) && !isRestrictedRole(cap.role);
  if (cap.code === "none" && !carveOutWritesViaShell) out.push(...FILE_WRITE_DENY);
  // The global tooling-request queue (#4000). `bsc` sits in the permission model's `mandatory` tier —
  // ALWAYS allowed, every role, every posture — so without this deny any worker could file straight
  // into the queue a full-capability session drains to edit base-studio-code itself. Not granting it
  // is not enough; only a deny keeps it out, because the hook is the sole layer that fires under
  // bypass (where `permissions.deny` is ignored).
  //
  // The pattern carries a SPACE, which matters: `deny_matches` (bsc-util/src/deny.rs) treats a bare
  // program name as a program-TOKEN match, but keeps substring semantics for anything else — so
  // "bsc request" matches `bsc request new …` while a bare "bsc" would have denied the entire CLI.
  if (!mayFileToolingRequest(cap.role)) out.push(TOOLING_REQUEST_COMMAND);
  return out;
}

/** The permission doc the `bsc-agent` runtime reads from `$BSC_AGENT_PERMS` (#1078 P3) — the
 *  generic role model rendered to bsc-agent's native shape (vs the Claude `.claude/settings.json`
 *  syntax {@link roleWriteRules}/{@link roleDeniedTools} produce). `code: "none"` denies the
 *  write/edit tools outright; `deny_bash` reuses {@link roleDeniedCommands} (substring-matched by
 *  bsc-agent — coarser than Claude's prefix allowlist); `write_globs` scopes a writer to its lane. */
export interface BscAgentPerms {
  deny_tools: string[];
  deny_bash: string[];
  write_globs: string[];
}

/** Render the role capability to bsc-agent's native permission doc. `granted` are the
 *  GitHub-propagation commands the pane's *flow* permits (from {@link flowGrantedPushCommands}):
 *  the flow owns `git push` / `gh pr create`, so they're lifted from the role denies when it
 *  permits pushing/PRing — mirroring the Claude role↔flow reconciliation (#304) so an `auto-pr`
 *  bsc-agent worker (github:read) can open its own PR. Everything else the role denies stays
 *  denied. With no flow grant (the default), behavior is unchanged.
 *
 *  `cap` may be `null` for a role-less (ad-hoc) bsc-agent console — then only `extraDenyBash`
 *  applies. `extraDenyBash` is the user's global command denylist (`store.deniedCommands`), the
 *  parallel to the `...deniedCommands` the Claude path passes to `ensure_session_settings`; bsc-agent
 *  has no `.claude/settings.json`, so they must ride in here to be enforced. The catastrophic
 *  base floor (sudo / `rm -rf /` / force-push) is NOT listed here — it's an always-on floor inside
 *  the bsc-agent runtime ({@link ../../../../crates/bsc-agent BASE_DANGEROUS_BASH}), so it can't be
 *  dropped by an empty perm doc. */
export function bscAgentPerms(
  cap: RoleCapability | null,
  granted: string[] = [],
  extraDenyBash: string[] = [],
): BscAgentPerms {
  // The scoped carve-out (#851) applies here too: a `code: "none"` director WITH commons writeGlobs
  // keeps its write tools (scoped to the commons) rather than having them denied outright.
  const carveOut = cap ? hasScopedWriteCarveOut(cap) : false;
  const roleDenies = cap ? roleDeniedCommands(cap).filter((d) => !granted.includes(d)) : [];
  return {
    deny_tools: cap && cap.code === "none" && !carveOut ? ["write_file", "edit_file"] : [],
    deny_bash: [...new Set([...roleDenies, ...extraDenyBash.map((c) => c.trim()).filter(Boolean)])],
    write_globs: cap && (cap.code === "write" || carveOut) ? cap.writeGlobs : [],
  };
}

/** The per-store access-scope doc rendered into a gated session's `$BSC_SCOPES` env (#2470) — the
 *  runtime, defense-in-depth twin of the launch-time verb denies above. A store CLI reads it via
 *  `bsc_cli_util::scope_allows_write` and refuses its mutating verbs when the store is scoped
 *  read-only. Explicitly NOT a security boundary (a session owns its own env) — it guards accidents
 *  and non-Claude runtimes (`bsc-agent`, raw shells); {@link roleDeniedCommands} is the boundary.
 *  Currently just `ui`; other stores (`plan`, `skill`, `data`, …) adopt incrementally by adding
 *  their tier here. Missing tier ⇒ `"read"` (the same fail-closed floor as the deny rendering). */
export function sessionScopes(cap: RoleCapability): Record<string, AccessTier> {
  return { ui: cap.ui ?? "read" };
}

runtime.shared/lib/session/poolPlan.ts:
// The warm-pool PLAN for debugger overflow sessions (#3535, slice 2) — decides, each poll, whether to
// spawn ONE more overflow session, which sessions to close, and each live session's reconciled state.
//
// The MODEL (approved): the standing debug session (`DebugSessionMount`) is the always-on primary — it
// self-serves the request queue. This pool is the OVERFLOW: when the primary is busy and there is more
// CLAIMABLE work, it spins up an additional generic-charter debugger; when all are busy it spins up
// another, up to a hard cap; each overflow session claims a request, fixes it, resolves it with a note,
// and is CLOSED when its claim resolves. So this module never touches the standing session — it only
// sizes the overflow beside it.
//
// PACED, not blasted: at most ONE session is "warming" (launched, not yet claimed) at a time, so the
// pool grows one step per cycle — "prefer this one until it's running; if it's running, spin up another"
// — rather than launching `cap` sessions the instant a burst of requests lands.
//
// PURE and separate from the launcher (mirrors #3498's planner/launcher split): every rule that bounds
// blast radius — the gate, the cap, the pacing, the reap — is here and exhaustively testable without
// starting a single session. The mount's only job is to obey the plan.

import { autoSpawnDecision, AUTO_SPAWNABLE_ROLE } from "./autoSpawn";

/** A request row as `bsc request list --json` returns it (the fields the pool reads). */
export interface RequestRow {
  id: number;
  /** `open` (claimable) · `claimed` (a session holds it) · `resolved` (done). */
  status: string;
  /** The pane id of the session holding a claimed request (#3535 `claimed_by`). */
  claimedBy?: string | null;
}

/** One overflow session the pool has launched (NOT the standing session). */
export interface PoolSession {
  paneId: string;
  /** The request id this session has claimed, or null while WARMING (launched, hasn't claimed yet). */
  claimedId: number | null;
  /** Consecutive polls this session has been warming with no claim — a session that never claims (it
   *  lost the race, or the queue drained before it ran `claim`) is reaped once this exceeds
   *  {@link MAX_WARM_POLLS}, so a warming slot can't wedge the pacing forever. Ignored once claimed. */
  pollsWarming: number;
}

export interface PoolPlanInput {
  /** The full request list (`bsc request list --json`), any status. */
  requests: RequestRow[];
  /** The overflow sessions currently launched, with their last-known state. */
  sessions: PoolSession[];
  /** The Settings toggle (`autoSpawnDebugSessions`). Anything but `true` is off. */
  enabled: boolean | null | undefined;
  /** Max TOTAL concurrent debuggers, INCLUDING the always-on standing session — so overflow is capped
   *  at `cap - 1`. Bounds a runaway: one never-resolving request can never fill the machine. */
  cap: number;
}

export interface PoolPlan {
  /** Launch ONE more overflow session this cycle? Never more than one — the pool grows one step/poll. */
  spawn: boolean;
  /** Overflow pane ids to CLOSE now: their claim resolved (work done), or they warmed out / lost it. */
  close: string[];
  /** Every still-live overflow session, with `claimedId`/`pollsWarming` reconciled against the queue.
   *  The mount replaces its tracked set with this (then appends a freshly-launched one when `spawn`). */
  sessions: PoolSession[];
  /** When not spawning, why — so a stalled pool is diagnosable, never a silent non-decision. */
  reason?: string;
  /** True when the ONLY thing blocking a spawn is the cap: there is claimable work and no session is
   *  warming, but the overflow is already at `cap - 1`. This is the "we need more but can't" signal the
   *  mount logs (#3535) — capacity pressure the user asked to be told about. */
  atCapacity: boolean;
  /** How many claimable (`open`) requests are waiting with no session free to take them — the size of
   *  the pressure when {@link atCapacity}. Zero otherwise. */
  waiting: number;
}

/** A warming session is reaped after this many consecutive claim-less polls (~1 min at a 20s poll). */
export const MAX_WARM_POLLS = 3;

/**
 * Plan the overflow pool for one cycle (#3535). Pure — starts and stops nothing.
 *
 * Steps:
 *  1. **Gate.** Auto-spawn off ⇒ spawn nothing and CLOSE every overflow session (the pool drains to just
 *     the standing session), each carrying the gate's own reason.
 *  2. **Reconcile + reap.** For each session: if the queue shows a request claimed BY it, it's busy on
 *     that id; if it previously held a claim that's no longer its (resolved / unclaimed / regrabbed),
 *     it's done → close; if it's still warming, bump the counter and close only once it exceeds
 *     {@link MAX_WARM_POLLS}.
 *  3. **Pace + cap.** Spawn one more only when there is claimable (`open`) work, NO session is currently
 *     warming, and the live count is under `cap - 1`.
 */
export function planPool(input: PoolPlanInput): PoolPlan {
  const gate = autoSpawnDecision({ role: AUTO_SPAWNABLE_ROLE, enabled: input.enabled });
  if (!gate.allowed) {
    return {
      spawn: false,
      close: input.sessions.map((s) => s.paneId),
      sessions: [],
      reason: gate.reason,
      atCapacity: false,
      waiting: 0,
    };
  }

  // paneId → the request id it currently holds (claimed).
  const heldByPane = new Map<string, number>();
  for (const r of input.requests) {
    if (r.status === "claimed" && r.claimedBy) heldByPane.set(r.claimedBy, r.id);
  }

  const kept: PoolSession[] = [];
  const close: string[] = [];
  for (const s of input.sessions) {
    const held = heldByPane.get(s.paneId);
    if (held != null) {
      kept.push({ paneId: s.paneId, claimedId: held, pollsWarming: 0 }); // busy on `held`
    } else if (s.claimedId != null) {
      close.push(s.paneId); // had a claim, no longer holds it ⇒ resolved/done ⇒ reap
    } else {
      const polls = s.pollsWarming + 1;
      if (polls > MAX_WARM_POLLS) close.push(s.paneId); // warmed out — never claimed anything
      else kept.push({ paneId: s.paneId, claimedId: null, pollsWarming: polls });
    }
  }

  const claimable = input.requests.filter((r) => r.status === "open").length;
  const warming = kept.filter((s) => s.claimedId == null).length;
  const overflowCap = Math.max(0, (Number.isFinite(input.cap) ? Math.trunc(input.cap) : 0) - 1);

  let reason: string | undefined;
  if (claimable === 0) reason = "no claimable (open) requests";
  else if (warming > 0) reason = "a session is still warming — pace one at a time";
  else if (kept.length >= overflowCap) reason = `at the overflow cap (${overflowCap})`;

  // Capacity pressure: claimable work AND nothing warming AND we are wedged against the cap. That is the
  // one non-spawn where the ANSWER is "we need more but may not have them" — everything under the cap
  // spawns next cycle instead. `waiting` sizes it (the claimable requests no session can take right now).
  const atCapacity = claimable > 0 && warming === 0 && kept.length >= overflowCap;
  return { spawn: reason === undefined, close, sessions: kept, reason, atCapacity, waiting: atCapacity ? claimable : 0 };
}

runtime.shared/lib/session/requestSpawn.ts:
// Pool-slot identity for warm-pool debugger sessions (#3535). The overflow sessions are POOL SLOTS, not
// per-request: a slot is a small stable integer, and a session claims a request only AFTER it launches
// (via `bsc request claim`), so its identity can't be the request id. These helpers name a slot's pane
// (the PTY), its Glance node, and the inverse the graph uses to resolve a node back to its pane.
//
// The spawn DECISION lives in `poolPlan.ts` (pure, tested); this file is only identity, imported by the
// mount (`RequestSessionsMount`), the Glance graph (`studioProject`), and the team augment (`team.ts`) —
// none of which may reach into the others — so it sits here in shared.

/** The PTY pane id for pool slot `n`. Under the `debug-studio:` prefix so it is full-capability like the
 *  standing debug session (`isFullCapabilitySession`, #3520). */
export function poolPaneId(slot: number): string {
  return `debug-studio:pool-${slot}`;
}

/** The Glance node id for pool slot `n` — distinct from the pane id because the Studio Network's node ids
 *  are team-position ids; {@link poolSlotFromNodeId} is the inverse the graph uses to open the slot. */
export function poolNodeId(slot: number): string {
  return `debugger-pool-${slot}`;
}

/** The pool slot behind a graph node, or null when the node is not a pool session. */
export function poolSlotFromNodeId(nodeId: string): number | null {
  const m = /^debugger-pool-(\d+)$/.exec(nodeId);
  return m ? Number(m[1]) : null;
}

/** The pool slot behind a PANE id, or null when the pane is not a pool session. The mount tracks sessions
 *  by pane id and needs the slot back to allocate the lowest free one and to publish live slots. */
export function poolSlotFromPaneId(paneId: string): number | null {
  const m = /^debug-studio:pool-(\d+)$/.exec(paneId);
  return m ? Number(m[1]) : null;
}

