runtime.shared/lib/session/systemSessions.ts:
// App-owned "studio" sessions (#3137) — the single source of truth for the fixed pane ids of the
// dedicated, app-launched singleton terminal sessions: the DESIGNER (Design Studio), the LIBRARIAN
// (Algorithms), the ARCHITECT (Teams), and the SOUND-DESIGNER (Sounds). Each is a singleton session the app owns and re-creates on
// demand — NOT a fleet worker and NOT something the user restores. Since #3357 all three (like the DEBUG
// session, #3326) run on the shared TerminalHost via `@/features/studio-sessions`, not on their own page-owned
// xterm; their ids stay fixed here so the lifecycle, the Glance morph, and recovery all agree.
//
// Their ids follow the `<key>:<tail>` grammar, so `parsePaneIdentity` would otherwise classify them as
// fleet WORKERS and the crash-recovery banner would offer to restore them (#3137). This module names
// them in ONE feature-agnostic place so both the feature hooks (which import their `*_PANE_ID` from here)
// and the recovery reconcile (`reconcileSessions`, which excludes them) agree — a new studio added here
// is excluded everywhere at once. The PLANNER is the sibling app-owned session, but it has a DYNAMIC
// per-project id (`planning_<key>`) and its own `isPlanningPaneId` guard, so it isn't listed here.

/** The Design Studio's app-owned designer session. */
export const DESIGN_STUDIO_SESSION_ID = "design-studio:designer";
/** The Algorithms studio's app-owned librarian session. */
export const ALGORITHMS_STUDIO_SESSION_ID = "algorithms-studio:librarian";
/** The Teams studio's app-owned architect session. */
export const TEAMS_STUDIO_SESSION_ID = "teams-studio:architect";
/** The Sound studio's app-owned sound-designer session (#3369, epic #3071 phase 4). */
export const SOUND_STUDIO_SESSION_ID = "sound-studio:sound-designer";
/** The Integration studio's app-owned integrator session (#4023) — builds and maintains the app's
 *  integrations with existing applications/APIs through `bsc data connector`. */
export const INTEGRATION_STUDIO_SESSION_ID = "integration-studio:integrator";
/** The Debug studio's app-owned debugger session (#3298) — a full-capability session in the
 *  base-studio-code SOURCE tree that works the `bsc request` improvement queue (fixing `bsc ui`),
 *  hosted in its own OS window and toggled from Settings. */
export const DEBUG_STUDIO_SESSION_ID = "debug-studio:debugger";

/** The pane-id prefix shared by EVERY session in the debug studio: the standing debugger
 *  (`debug-studio:debugger`) and each auto-spawned per-request session (`debug-studio:req-<id>`,
 *  {@link poolPaneId}). Every one of them is the app's full-capability maintenance session in the
 *  source tree, so the prefix — not the singleton id — is what `isFullCapabilitySession` keys on. */
export const DEBUG_STUDIO_PANE_PREFIX = "debug-studio:";

/** Every fixed, app-owned studio session pane id. */
export const STUDIO_SESSION_PANE_IDS: readonly string[] = [
  DESIGN_STUDIO_SESSION_ID,
  ALGORITHMS_STUDIO_SESSION_ID,
  TEAMS_STUDIO_SESSION_ID,
  SOUND_STUDIO_SESSION_ID,
  INTEGRATION_STUDIO_SESSION_ID,
  DEBUG_STUDIO_SESSION_ID,
];

/** Whether `id` is a fixed, app-owned studio session (designer / librarian / architect / sound-designer /
 *  integrator) — excluded from
 *  crash recovery the way the planner (`isPlanningPaneId`) is: re-created when its workspace opens, never
 *  restored from the recovery banner. */
export function isStudioSessionPaneId(id: string): boolean {
  return STUDIO_SESSION_PANE_IDS.includes(id);
}

/** Whether `id` is a FULL-CAPABILITY app-owned session that must ALWAYS launch bypass + role-less,
 *  regardless of the global permission posture (`bypassPermissions`) — ANY session in the debug studio
 *  (#3326/#3520). Unlike a fleet/console pane, whose posture comes from the store (role/profile/flow + the
 *  global bypass toggle), a debug-studio session is BY DEFINITION the unrestricted maintenance session in
 *  the base-studio-code source tree; `buildSessionSettings` forces `bypass:true` for it. Role-less is
 *  automatic — no `paneRoles` entry is set for these panes and `studioRoleForPaneId` matches only the four
 *  fixed studios, so no role gate applies.
 *
 *  Matches the whole `debug-studio:` family, not just the singleton (#3520): the standing debugger AND each
 *  auto-spawned per-request session (`debug-studio:req-<id>`, #3498). A req session is the same kind of
 *  actor as the standing one — app-owned, in the source tree, working the request queue — and the control
 *  gate is the human reviewing its PR, not a per-tool permission prompt. Keying on the singleton id left
 *  the spawned sessions falling through to the global toggle, so they stopped to ask for every edit. */
export function isFullCapabilitySession(id: string): boolean {
  return id.startsWith(DEBUG_STUDIO_PANE_PREFIX);
}

runtime.shared/lib/session/terminalClipboard.ts:
// Terminal clipboard (#3157) — copy-on-select + paste for the app's xterm terminals (both the console
// panes, `TerminalView`, and the app-owned screen sessions, `useScreenSession`). The terminals had NO
// clipboard handling: Ctrl+C is SIGINT (can't be copy), and Ctrl+Shift+C — the usual terminal copy chord —
// is claimed by the WebView2 DevTools "inspect" accelerator AND the app's broadcast-toggle. So:
//   • COPY-ON-SELECT — selecting text auto-copies (writeText, already proven in this app). No key needed,
//     which sidesteps the Ctrl+Shift+C conflict entirely.
//   • PASTE — Ctrl+Shift+V / Shift+Insert / right-click read the clipboard and `pty_write` it (these chords
//     don't collide with the DevTools accelerator, so paste works standalone).
// Feature-agnostic (shared/), so both terminal sites wire the identical behavior. Must be called AFTER
// `term.open()` — it needs `term.element` for the mouse listeners.
import type { Terminal } from "@xterm/xterm";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";

/**
 * Wire copy-on-select + paste onto an open xterm `term`, sending pasted text to the PTY `paneId`.
 * Returns a disposer to call on terminal teardown (removes the DOM listeners; xterm keeps a single custom
 * key handler that goes away when the terminal is disposed).
 */
export function attachTerminalClipboard(term: Terminal, paneId: string): () => void {
  const el = term.element;
  const disposers: Array<() => void> = [];

  // ── COPY-ON-SELECT ── on mouse-up, copy the current selection (one write per finished selection, vs
  // `onSelectionChange` which fires continuously during a drag). A no-selection mouse-up (a plain click,
  // or a click that clears a selection) writes nothing, so it never clobbers the clipboard with "".
  const onMouseUp = () => {
    const sel = term.getSelection();
    if (sel) void navigator.clipboard?.writeText(sel).catch(() => {});
  };
  el?.addEventListener("mouseup", onMouseUp);
  if (el) disposers.push(() => el.removeEventListener("mouseup", onMouseUp));

  // ── PASTE ── read the clipboard and send it to the PTY (the shell / TUI echoes it back). A blocked/denied
  // read is a silent no-op (the caller can escalate to a native clipboard plugin if a webview ever refuses).
  const paste = () => {
    const read = navigator.clipboard?.readText?.();
    if (!read) return;
    void read
      .then((text) => { if (text) fireInvoke("pty_write", { paneId, data: text }, console.error); })
      .catch(() => {});
  };

  // Right-click pastes (terminal convention); suppress the browser context menu so it doesn't also open.
  const onContextMenu = (e: MouseEvent) => { e.preventDefault(); paste(); };
  el?.addEventListener("contextmenu", onContextMenu);
  if (el) disposers.push(() => el.removeEventListener("contextmenu", onContextMenu));

  // Ctrl+Shift+V / Shift+Insert paste. Returning FALSE stops xterm from ALSO sending the keys to the PTY,
  // and `preventDefault` stops a native paste event from double-firing. Ctrl+Shift+C copy is deliberately
  // NOT bound here — copy-on-select covers it, and on Windows that chord is eaten by the DevTools
  // accelerator until the separate layer-1 fix disables the WebView2 browser accelerator keys.
  term.attachCustomKeyEventHandler((e) => {
    if (e.type !== "keydown") return true;
    const paste_v = e.ctrlKey && e.shiftKey && !e.altKey && !e.metaKey && (e.key === "V" || e.key === "v");
    const paste_ins = e.shiftKey && !e.ctrlKey && !e.altKey && !e.metaKey && e.key === "Insert";
    if (paste_v || paste_ins) {
      e.preventDefault();
      paste();
      return false;
    }
    return true;
  });

  return () => { for (const d of disposers) d(); };
}

runtime.shared/lib/session/turnHooks.ts:
// Turn-accounting hooks (#3455) — the un-gated, pure-observability Claude Code hooks EVERY
// claude-launching session must register, kept in ONE place.
//
// WHY A SHARED CONSTANT. This exact set has now silently fallen out of a launch path TWICE:
//   · #3452 — the generic fleet/console path (`sessionLaunch.ts`) never registered `bsc-tokens`, so
//     tokens.log went dead for ~3 weeks and the whole cost subsystem read $0.
//   · #3455 — the bespoke planner launch passed `hooks: null`, so NO hook fired for the planner and
//     its (often large) planning cost was invisible.
// Both are the same failure mode: a session that logs nothing because the registration drifted out of
// one code path. A single exported constant that every launch path spreads makes that drift structural
// rather than silent — you cannot forget the list if there is only one list.
//
// SCOPE — observability only. These two hooks have NO behavioral effect (they only append a log line):
//   · bsc-activity (#1184) — authoritative turn boundaries (`run` on prompt, `idle` on Stop), so the
//     status dot doesn't false-idle a thinking session.
//   · bsc-tokens (#416) — `pane → session → transcript_path` to tokens.log at every turn end; the ONLY
//     per-session token source (Claude Code hooks don't expose usage), read by `bsc logs cost`, the
//     desktop cost UI, and `bsc metrics` (#3449).
// The GATING hooks (bsc-confine / bsc-deny / bsc-audit / bsc-scope / bsc-taint / bsc-defer) are NOT
// here — they change behavior and their per-path inclusion is a policy decision (the planner, plan-only
// in allow-list posture, deliberately omits them). This constant is the accounting floor, not the
// permission floor.

/** One Claude Code hook registration — `{event, matcher, command}`, the shape `ensure_session_settings`
 *  writes into `.claude/settings.json`. `matcher: ""` means "every tool / no matcher". */
export interface SessionHook {
  event: string;
  matcher: string;
  command: string;
}

/**
 * The turn-accounting hooks every claude session registers (see the module header). Spread into each
 * launch path's hook list — the generic `sessionHooks` (`sessionLaunch.ts`) AND the planner's two
 * `ensure_session_settings` calls (`usePlannerTerminal` / `usePlanMcpManagement`).
 *
 * A fresh array per read is not needed (the value is never mutated), but keep it readonly-in-spirit:
 * callers spread it, never push to it.
 */
export const TURN_ACCOUNTING_HOOKS: SessionHook[] = [
  { event: "UserPromptSubmit", matcher: "", command: "bsc-activity run" },
  // #4005 — Claude Code fires `Notification` when it needs the USER: most importantly "Claude needs
  // your permission to use <tool>", which under the default allow-list posture (#2050) is any command
  // outside `base.json`. That session is STOPPED, and until now nothing in the app could tell it apart
  // from one that was merely quiet — so the user had no way to know WHICH pane was asking.
  //
  // `Notification` also fires after a long input idle. That is likewise "needs you", so it is a
  // feature rather than a false positive. It is cleared by the ordinary turn boundaries below: the
  // next UserPromptSubmit records `run`, a Stop records `idle`. Without that a pane would stay
  // flagged forever after a single prompt.
  { event: "Notification", matcher: "", command: "bsc-activity attn" },
  { event: "Stop", matcher: "", command: "bsc-activity idle" },
  { event: "SubagentStop", matcher: "", command: "bsc-activity idle" },
  { event: "Stop", matcher: "", command: "bsc-tokens" },
  { event: "SubagentStop", matcher: "", command: "bsc-tokens" },
];

runtime.shared/lib/session/useScreenSession.ts:
// useScreenSession (#2707) — the shared xterm.js + PTY lifecycle behind the app's dedicated,
// app-owned terminal sessions. Its remaining user is the PLANNER (`usePlannerTerminal`): the debug
// session (#3326) and the designer/librarian/architect studios (#3357) were migrated onto the shared
// TerminalHost, precisely because a single-mount xterm CANNOT be re-parented into the Glance morph.
// The hooks it was extracted from were near-verbatim copies of the same skeleton:
//   • mount — create the `Terminal` (the shared theme/font/scrollback literal) + `FitAddon`, wire
//     `onData → pty_write`, then in a `requestAnimationFrame`: fit, subscribe `pty_data_<id>` /
//     `pty_exit_<id>` BEFORE spawning the PTY (so no early output is missed), and run the caller's
//     divergent launch path (workspace resolve → `ensure_session_settings` → `pty_create`).
//   • re-fit — re-measure when the surface becomes visible (hidden → shown), after a short delay, and
//     once the mono font loads (cell metrics are wrong until then).
//   • cleanup — unlisten×2, disconnect the ResizeObserver, dispose the term, null the refs, and
//     `pty_kill` the session.
// The LAUNCH path itself is deliberately NOT shared — the planner and designer differ in their
// workspace command, role gate, MCP/sandbox wiring, and env — so it stays a `launch` callback each
// wrapper owns, keeping every invoke/pty_create arg byte-identical to the pre-extraction hooks.
//
// TERM_THEME is passed IN as a param (never imported here): pulling the planner's theme leaf into
// `shared/` would invert the dependency direction (shared must stay feature-agnostic, #1626).
import { useEffect, useRef, type RefObject, type MutableRefObject } from "react";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";
import { Terminal, type ITheme } from "@xterm/xterm";
import { FitAddon } from "@xterm/addon-fit";
import { attachTerminalClipboard } from "./terminalClipboard";
import "@xterm/xterm/css/xterm.css";

export interface ScreenSessionConfig<S = void> {
  /** Stable pane id — the pty_* event channel + write/resize/kill key. */
  paneId: string;
  /** xterm theme (passed in so `shared/` never imports a feature's theme leaf). */
  termTheme: ITheme;
  /** Whether the surface is on-screen — drives the re-fit effect. */
  visible: boolean;
  /** Text written to the terminal on `pty_exit` (include the leading/trailing CRLF + ANSI reset). */
  exitBanner: string;
  /** Called with each raw `pty_data` payload AFTER it is written to the term (e.g. tag parsing). */
  onData?: (payload: string) => void;
  /** Runs SYNCHRONOUSLY in the mount effect body (before the RAF), so callers can snapshot store /
   *  prop state at exactly mount time. Its return value is handed to `launch`. */
  snapshot?: () => S;
  /** Owns the divergent launch path — workspace resolve → session settings → `pty_create` (+ any
   *  post-launch registration). Runs inside the mount RAF, AFTER `pty_data`/`pty_exit` are
   *  subscribed. `term` gives `cols`/`rows`; `snap` is the `snapshot()` return. */
  launch: (term: Terminal, snap: S) => Promise<void>;
  /** Runs in cleanup, just before `pty_kill` (e.g. deregister a tunnel roster). */
  onUnmount?: () => void;
}

export interface ScreenSessionHandle {
  /** Host element for the xterm canvas — attach to the terminal container div. */
  containerRef: RefObject<HTMLDivElement | null>;
  /** The live xterm instance (null before mount / after unmount). */
  termRef: MutableRefObject<Terminal | null>;
}

export function useScreenSession<S = void>(config: ScreenSessionConfig<S>): ScreenSessionHandle {
  const { paneId, termTheme, visible, exitBanner } = config;

  const containerRef = useRef<HTMLDivElement>(null);
  const termRef      = useRef<Terminal | null>(null);
  const fitRef       = useRef<FitAddon | null>(null);
  const unlistenData = useRef<UnlistenFn | null>(null);
  const unlistenExit = useRef<UnlistenFn | null>(null);

  // Mount xterm.js and spawn the PTY (once per surface lifecycle). pty_kill runs only in this
  // cleanup so tearing the session down is tied to the surface unmounting.
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    const term = new Terminal({
      theme: termTheme,
      fontFamily: '"JetBrains Mono", monospace',
      fontSize: 12,
      lineHeight: 1.4,
      cursorBlink: true,
      cursorStyle: "bar",
      scrollback: 10000,
    });

    const fitAddon = new FitAddon();
    term.loadAddon(fitAddon);
    term.open(el);
    termRef.current = term;
    fitRef.current  = fitAddon;
    const disposeClipboard = attachTerminalClipboard(term, paneId); // copy-on-select + paste (#3157)

    term.onData((data) => {
      fireInvoke("pty_write", { paneId, data }, console.error);
    });

    // Snapshot mount-time state synchronously (before the RAF), so callers capture the same instant
    // the pre-extraction hooks did.
    const snap = (config.snapshot?.() as S);

    requestAnimationFrame(async () => {
      // Only fit when the host has real dimensions. Fitting a 0-size host — a KeptMountedPage surface
      // mounted before layout, or a collapsed/zero-height dock — sets the terminal to 0 rows, and the
      // first `pty_data` write to a 0-row terminal dereferences a non-existent buffer line and crashes
      // xterm ("Cannot set properties of undefined (setting 'isWrapped')"), taking the page down via the
      // ErrorBoundary (#2832). A fresh xterm defaults to 80×24, so skipping the fit keeps a valid buffer;
      // the ResizeObserver below fits it once the host is actually sized (e.g. when KeptMountedPage flips
      // it to display:flex). Same guard the ResizeObserver already applies.
      if (el.clientWidth > 0 && el.clientHeight > 0) fitAddon.fit();

      // Subscribe before creating the PTY so we never miss early output.
      unlistenData.current = await listen<string>(`pty_data_${paneId}`, (ev) => {
        term.write(ev.payload);
        config.onData?.(ev.payload);
      });
      unlistenExit.current = await listen<unknown>(`pty_exit_${paneId}`, () => {
        term.write(exitBanner);
      });

      // The divergent launch path (workspace → settings → pty_create) is owned by the caller.
      await config.launch(term, snap);
    });

    // DEBOUNCED refit (#2832): a resize DRAG fires the observer dozens of times per second. Calling
    // `fit()` — which resizes the terminal and REFLOWS its buffer — on every frame while the PTY is
    // streaming output races xterm's async write loop and corrupts the buffer, throwing
    // "Cannot set properties of undefined (setting 'isWrapped')" from a later write (an UNCAUGHT error
    // that takes the page down). Coalescing to a single fit ~90ms after the drag settles reflows once,
    // off the streaming path. A hidden (display:none) host is 0-size → skipped.
    let resizeTimer: ReturnType<typeof setTimeout> | undefined;
    const ro = new ResizeObserver(() => {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        const t = termRef.current;
        if (!t || el.clientWidth === 0 || el.clientHeight === 0) return;
        fitAddon.fit();
        fireInvoke("pty_resize", { paneId, cols: t.cols, rows: t.rows }, console.error);
        t.refresh?.(0, t.rows - 1); // repaint the buffer cleanly at the settled size (#2837)
      }, 90);
    });
    ro.observe(el);

    // The dock's ENTRANCE GROW (#2905, `useDockEntrance`) animates the panel's REAL height up into place,
    // so the ResizeObserver above fires as it grows and its debounced fit lands the authoritative size
    // once the grow settles — no separate post-animation "settle fit" needed (that was the transform-only
    // slide's workaround, #2837, now removed).

    return () => {
      clearTimeout(resizeTimer);
      unlistenData.current?.();
      unlistenExit.current?.();
      ro.disconnect();
      disposeClipboard();
      term.dispose();
      termRef.current = null;
      fitRef.current  = null;
      config.onUnmount?.();
      fireInvoke("pty_kill", { paneId }, console.error);
    };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // Re-fit when the surface becomes visible (hidden → shown): the collapsed host is display:none, so
  // the mount-time fit measured nothing. Re-fit on the frame, after a short delay, and once the mono
  // font loads (cell metrics are wrong until then) so it reliably fills the available space.
  useEffect(() => {
    if (!visible) return;
    const refit = (focusToo: boolean) => {
      const fit = fitRef.current, term = termRef.current, el = containerRef.current;
      if (!fit || !term || !el || el.clientWidth === 0 || el.clientHeight === 0) return;
      fit.fit();
      fireInvoke("pty_resize", { paneId, cols: term.cols, rows: term.rows }, console.error);
      term.refresh?.(0, term.rows - 1); // repaint cleanly at the shown size (#2837)
      if (focusToo) term.focus();
    };
    let cancelled = false;
    const raf = requestAnimationFrame(() => refit(true));
    const delayed = setTimeout(() => refit(false), 120);
    document.fonts?.ready?.then(() => { if (!cancelled) refit(false); }).catch(() => {});
    return () => { cancelled = true; cancelAnimationFrame(raf); clearTimeout(delayed); };
  }, [visible]); // eslint-disable-line react-hooks/exhaustive-deps

  return { containerRef, termRef };
}

