import type { CSSProperties, KeyboardEvent, ReactNode } from "react";

export interface SearchFieldProps {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  "aria-label"?: string;
  /** Leading glyph. Defaults to the search icon; pass `null` to omit (e.g. a paste box). */
  icon?: ReactNode;
  /** Optional trailing slot — a result count, a `⌘K` kbd, etc. */
  trailing?: ReactNode;
  /** Container style overrides (bg, height, radius, flex/width) merged over the base look. */
  style?: CSSProperties;
  className?: string;
  /** Input style overrides (e.g. a per-site font-size). */
  inputStyle?: CSSProperties;
  onKeyDown?: (e: KeyboardEvent<HTMLInputElement>) => void;
}

const boxBase: CSSProperties = {
  display: "flex",
  alignItems: "center",
  gap: 8,
  height: 32,
  padding: "0 11px",
  background: "var(--bg-soft)",
  border: "1px solid var(--border)",
  borderRadius: 8,
};

const inputBase: CSSProperties = {
  flex: 1,
  minWidth: 0,
  background: "none",
  border: "none",
  color: "var(--fg)",
  fontSize: 12.5,
  fontFamily: "inherit",
  outline: "none",
};

/**
 * A small bordered search box: a leading `⌕` glyph, a bare `<input>`, and an
 * optional `trailing` slot. Consolidates the icon+borderless-input pattern that
 * was hand-rolled at several sites (#2708).
 */
export function SearchField({
  value,
  onChange,
  placeholder,
  icon = <span style={{ color: "var(--fg-dim)", fontSize: 13 }}>⌕</span>,
  trailing,
  style,
  className,
  inputStyle,
  onKeyDown,
  "aria-label": ariaLabel,
}: SearchFieldProps) {
  return (
    <div className={className} style={{ ...boxBase, ...style }}>
      {icon}
      {/* eslint-disable-next-line no-restricted-syntax -- this primitive intentionally wraps a bare
          borderless <input>; Field/TextField impose a labelled .field layout that doesn't fit an
          inline search box. This is the ONE justified bare input, centralized here. */}
      <input
        value={value}
        onChange={(e) => onChange(e.target.value)}
        onKeyDown={onKeyDown}
        placeholder={placeholder}
        aria-label={ariaLabel}
        style={{ ...inputBase, ...inputStyle }}
      />
      {trailing}
    </div>
  );
}

runtime.shared/ui/feedback/CardStates.tsx:
// Per-card loading + empty states, shared across dashboards (#3246 — consolidated from the GitHub
// summary #2244, Fleet #2234, Insights #2243, and MCP/Hook analytics #2246/#2247 copies).
//
// A dashboard card keeps its frame + head; its BODY is one of three — a shimmer skeleton while its
// source loads · a compact empty state when there's no data · the content. Shared here so a card's
// body states don't each re-declare the pair.
import type { ReactNode } from "react";
import { Stack } from "@/shared/ui/layout/Stack";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";

/** A compact empty state for a card body — the card frame + head stay; the body shows this. */
export function CardEmpty({ icon = "○", title, hint }: { icon?: ReactNode; title: string; hint?: string }) {
  return <EmptyState size="sm" iconVariant="dashed" icon={icon} title={title} description={hint} style={{ padding: "20px 12px" }} />;
}

/** A stack of shimmer rows — a loading placeholder for a list/table/chart card body. */
export function SkeletonRows({ rows = 4, h = 30, gap = 6, radius = 6 }: { rows?: number; h?: number; gap?: number; radius?: number }) {
  return (
    <Stack gap={gap}>
      {Array.from({ length: rows }).map((_, i) => <Skeleton key={i} h={h} radius={radius} />)}
    </Stack>
  );
}

