// The `algo-viz` kit's MOTION library as DATA (#2942/#3194, epic #3171) — the compare / swap / set /
// sorted (+ the search pair probe / found, #3220) animations authored as {@link KitAnimation} data,
// compiled by the kit-motion engine
// (`compileAnimationsCss`), NOT as hand-written CSS `@keyframes`. This is the epic's core vision: motion
// is data, so it's editable in the Designer's Animations menu instead of baked into a renderer's
// stylesheet.
//
// ── WHY THIS LIVES IN shared/ui/kit (not in either feature) ──────────────────────────────────────────
// It has EXACTLY TWO consumers, in two different features, and must be ONE definition (change `swap` once
// → every array visualization AND the Design-Studio kit shelf update in lockstep):
//   1. the Algorithms ArrayView renderer (`features/algorithms/.../arrayViewMotion.ts`,
//      `ensureArrayViewMotion`) — injects the compiled CSS into the live visualization; and
//   2. the Designs seed (`features/designs/lib/algoVizKit.ts` → `seed.ts`) — registers `algo-viz` as a
//      recoverable builtin kit so the set is visible + editable in the Design Studio's AnimationsMenu.
// Importing the Algorithms barrel from the Designs seed would eagerly pull the whole algorithms feature
// (its Workspace + graph) into the store-boot module graph and risks a designs↔algorithms seed cycle. The
// data is genuinely feature-agnostic viz-motion, so it lives HERE — a leaf both features import cheaply.
//
// ── THE STATE-TRIGGER SEAM (#3058) — "verb → data-state → animation" ─────────────────────────────────
// The current engine has no `trigger: "state"`; a state trigger is a KitAnimation whose `selector` IS the
// data-state (`[data-op="swap"]`). The engine compiles it to a rule
//
//     .algo-viz-anim-swap [data-op="swap"] { animation: bsc-algo-viz-swap …; }
//
// which plays whenever a DESCENDANT of the applying-class root matches that state — i.e. exactly when
// `ArrayView` stamps `data-op="swap"` on a cell. The renderer's root carries the applying classes; its
// cells only stamp `data-op` / `data-mark`. Change an animation's data here → every array visualization
// (and the kit's Design-Studio preview) updates, no renderer change.

import type { KitAnimation } from "./animations";

/** The array-visualization motion kit id — `.algo-viz-anim-<name>` + `@keyframes bsc-algo-viz-<name>`. */
export const ALGO_VIZ_KIT_ID = "algo-viz";

/**
 * The `algo-viz` kit's animations as DATA (#2942), each a STATE trigger keyed on the data-state selector
 * `ArrayView` stamps — so the compiled rule fires on exactly `[data-op="compare"]` / `[data-op="swap"]`
 * / `[data-op="set"]` / `[data-mark="sorted"]`. Token-based colors + durations; the engine wraps every
 * applying rule in `@media (prefers-reduced-motion: no-preference)`, so reduced-motion is handled for
 * free. This is the single source of truth the ArrayView renderer AND the Designs `algo-viz` builtin kit
 * both consume — one definition, two consumers.
 */
export const ALGO_VIZ_ANIMATIONS: KitAnimation[] = [
  // compare — a highlight pulse on the two compared cells.
  {
    name: "compare",
    selector: '[data-op="compare"]',
    duration: "500ms",
    easing: "var(--ease-standard)",
    set: { "z-index": "1" },
    keyframes: {
      "0%": { "box-shadow": "0 0 0 0 transparent", "border-color": "var(--border)" },
      "45%": {
        "box-shadow": "0 0 0 2px color-mix(in oklch, var(--state-wait), transparent 45%)",
        "border-color": "var(--state-wait)",
      },
      "100%": { "box-shadow": "0 0 0 0 transparent", "border-color": "var(--border)" },
    },
  },
  // swap — the two cells lift, tint to the accent, and settle back as they exchange.
  {
    name: "swap",
    selector: '[data-op="swap"]',
    duration: "420ms",
    easing: "cubic-bezier(0.34, 1.4, 0.5, 1)",
    set: { "z-index": "2" },
    keyframes: {
      "0%": {
        transform: "translateY(0)",
        "border-color": "var(--accent)",
        background: "color-mix(in oklch, var(--accent), var(--bg-elev) 62%)",
      },
      "40%": { transform: "translateY(-12px) scale(1.05)" },
      "100%": { transform: "translateY(0)" },
    },
  },
  // set — a value flash (a fresh write into the cell).
  {
    name: "set",
    selector: '[data-op="set"]',
    duration: "500ms",
    easing: "var(--ease-standard)",
    keyframes: {
      "0%": { background: "color-mix(in oklch, var(--accent), transparent 20%)" },
      "100%": { background: "var(--bg-elev)" },
    },
  },
  // probe — the SEARCH verb (#3220): ONE cell examined against an external target. Deliberately unlike
  // `compare` (which pulses a PAIR): a tight accent ring that closes in on the single cell, so a search
  // reads as "inspect this one" rather than "weigh these two".
  {
    name: "probe",
    selector: '[data-op="probe"]',
    duration: "460ms",
    easing: "var(--ease-standard)",
    set: { "z-index": "1" },
    keyframes: {
      "0%": { "box-shadow": "0 0 0 6px transparent", "border-color": "var(--border)" },
      "50%": {
        "box-shadow": "0 0 0 2px color-mix(in oklch, var(--accent), transparent 35%)",
        "border-color": "var(--accent)",
      },
      "100%": { "box-shadow": "0 0 0 0 transparent", "border-color": "var(--border)" },
    },
  },
  // found — the search's terminal hit (#3220): a one-shot pop as the target is located (its DURABLE accent
  // resting look is a static element style in arrayView.css, since the mark ends the trace).
  {
    name: "found",
    selector: '[data-mark="found"]',
    duration: "420ms",
    easing: "cubic-bezier(0.34, 1.4, 0.5, 1)",
    set: { "z-index": "2" },
    keyframes: {
      "0%": { transform: "scale(1)" },
      "45%": { transform: "scale(1.12)" },
      "100%": { transform: "scale(1)" },
    },
  },
  // sorted — a one-shot settle as a cell reaches its final place (its DURABLE green resting look is a
  // static element style in arrayView.css, since a mark persists across frames — this is only the motion).
  {
    name: "sorted",
    selector: '[data-mark="sorted"]',
    duration: "300ms",
    easing: "var(--ease-standard)",
    keyframes: {
      "0%": { transform: "translateY(-3px)" },
      "100%": { transform: "translateY(0)" },
    },
  },
];

runtime.shared/ui/kit/animations.ts:
// Data-defined KIT animations (#2942, epic #2865/#2553) — the RENDER path for motion an LLM authors
// as data on a KIT (`Kit.animations`), the motion sibling of themes. Each definition compiles to a
// `@keyframes bsc-<kit>-<name>` block + an applying rule on `.<kit>-anim-<name>`, injected into ONE
// managed `<style>`, so a kit's motion plays on any of its components with zero component changes.
// A component BINDS an animation by name (`ComponentRecord.animations: string[]`) — the renderer puts
// `.<kit>-anim-<name>` on the element; the kit owns the keyframes + timing + trigger.
//
// Motion is per-KIT, not global and not baked per-component: a kit is a structurally-distinct
// component set (its own DOM/CSS architecture), so a 3D / non-DOM kit carries a different motion
// representation, and two kits may reuse a name (`fade-in`) with different keyframes without colliding.
// Mirrors the variant render path (variants.ts): compiled on boot + re-applied on a `ui-touch` write.
// The applying rule is wrapped in `@media (prefers-reduced-motion: no-preference)`, so motion is
// suppressed for users who ask for less of it.
//
// DEFENSE IN DEPTH: like variants, this compiles LLM-authored data into live CSS, so a kit /
// animation name must be a safe CSS identifier, a keyframe stop must be `from`/`to`/`N%`, a property
// must be `[a-z-]+`, and no value may carry a declaration-ending / injection sequence. An optional
// child `selector` must pass `SAFE_SELECTOR` (only selector-safe characters — it cannot break out of
// the selector position). Anything failing is skipped, never emitted.

/** When an authored animation plays. `mount` (the default) plays once as the element is INSERTED — so a
 *  child `selector` + `mount` voices a STATE-TRIGGERED conditional render (e.g. a tooltip pop-in): CSS
 *  restarts a `1 both` animation each time the matched subtree (re)mounts, so no dedicated "state" trigger
 *  is needed (#3058). `exit` is DORMANT until the preview exit-runtime lands (#3057). */
export type AnimationTrigger = "mount" | "hover" | "always" | "exit";

/** One authored animation in a kit's motion library (the shape carried on a `Kit`'s `animations`).
 *  A component references it by {@link name} to play it — the kit owns the keyframes/timing/trigger. */
export interface KitAnimation {
  /** Animation name — a safe CSS identifier → `.<kit>-anim-<name>` + `@keyframes bsc-<kit>-<name>`. */
  name: string;
  /** Keyframe stops: a selector (`from`/`to`/`N%`) → CSS declarations (property → value). */
  keyframes: Record<string, Record<string, string>>;
  /** Duration — a motion-token ref (`var(--dur-base)`) or a time (`220ms`). Default `var(--dur-base)`. */
  duration?: string;
  /** Easing — a motion-token ref (`var(--ease-standard)`) or a timing-function. Default `var(--ease-standard)`. */
  easing?: string;
  /** Animation-level delay (#3056) — a time (`120ms`), slotted after easing in the shorthand. Default none. */
  delay?: string;
  /** When it plays. Default `mount`. `exit` (#3057) keys the rule on a `[data-bsc-exit]` marker so it
   *  plays as a subtree LEAVES — DORMANT until the preview exit-runtime sets that marker on the leaving
   *  element (nothing sets it today, so an exit animation compiles the keyframes + rule but plays
   *  nothing yet; a follow-up slice adds the runtime that flips the marker). */
  trigger?: AnimationTrigger;
  /** Scope the applying rule to a CHILD element (#3054) — a descendant combinator
   *  (`.<kit>-anim-<name> <selector>`). Absent ⇒ the animation applies to the root class as before. */
  selector?: string;
  /** STATIC declarations set on the applying rule (#3054) — for `transform-origin` / `transform-box`
   *  etc. that can't live in keyframes. Each `property: value` is guarded like a keyframe declaration. */
  set?: Record<string, string>;
  /** Per-matched-element delay STEP (#3055) — a time (`14ms`) added cumulatively across the elements a
   *  {@link selector} matches, so a heatmap wave / scatter cascade / per-series line ripples in. Only
   *  meaningful WITH a `selector` (a root has no siblings to step); capped at ~`STAGGER_MAX` elements
   *  (siblings past the cap gracefully fall back to the base `delay`). Absent ⇒ no per-element step. */
  stagger?: string;
  /** VARIATION SLOT (#3069) — the ORGANIZATIONAL grouping for a component's alternative animations, the
   *  motion analog of a component variant. Two or more animations a component binds that share a `group`
   *  are VARIATIONS of one another for the SAME slot (e.g. "bars entering"), and only ONE of the group
   *  PLAYS — the {@link default} (or the first in appearance order, if none is marked). Ungrouped
   *  animations are unaffected: they all play, exactly as before. Purely ORGANIZATIONAL: it is NOT
   *  emitted to CSS — {@link compileAnimationsCss} and the Rust `validate_animation` ignore it, so it
   *  never touches the keyframes / applying rule. Resolved by `resolveComponentAnimations`. Absent ⇒
   *  ungrouped (always plays). */
  group?: string;
  /** The DEFAULT variation of its {@link group} (#3069) — the one that plays. At most one variation per
   *  group is the default; if none is marked, the FIRST in appearance order plays. Meaningful only WITH a
   *  `group`. Like `group` it is ORGANIZATIONAL — never emitted to CSS. Absent ⇒ not the group's default. */
  default?: boolean;
}

/** A kit animation + its owning kit's CSS class base (the flat shape the compiler takes). */
export interface AnimationDef extends KitAnimation {
  /** The kit's CSS class base (its id, e.g. `react-ui`). */
  kit: string;
  /** The OWNING COMPONENT (#3163) — when set, the compiled `@keyframes` + applying class are namespaced
   *  `bsc-<kit>-<component>-<name>` / `.<kit>-<component>-anim-<name>` so two DIFFERENT components' same-
   *  named animations compile to DISTINCT keyframes instead of one silently clobbering the other (the
   *  invisible collision a multi-component preview hit when a chart + a composed piece both named an
   *  animation `draw-in`). Absent ⇒ the plain, un-namespaced `bsc-<kit>-<name>` / `.<kit>-anim-<name>`
   *  (a single-component preview — existing behavior). Sanitized to a safe ident segment by the compiler
   *  ({@link animClassName}), so a PascalCase component name (`Sparkline`) is accepted. */
  component?: string;
}

const STYLE_ID = "bsc-ui-animations";
/** A safe CSS identifier for a class / keyframes-name segment (mirrors the CLI's sanitize_variant_name). */
const SAFE_IDENT = /^[a-z][a-z0-9-]*$/;
/** A keyframe stop selector — `from`, `to`, or a percentage (`0%`, `50%`, `100%`). */
const SAFE_STOP = /^(from|to|\d{1,3}%)$/;
/** A CSS property name — lowercase letters + hyphens (`opacity`, `transform`, `background-color`). */
const SAFE_PROP = /^[a-z-]+$/;
/** A child selector for the applying rule (#3054) — ONLY selector-safe characters, so it structurally
 *  cannot break out of the selector position into a declaration / new rule / comment (no `{ } ; < \ /`).
 *  Allows classes, tags, `#`ids, `>`/space/`+`/`~` combinators, `[attr="v"]`, `:nth-child(2n)`, `,` lists, `*`. */
const SAFE_SELECTOR = /^[a-zA-Z0-9 ._#>[\]="'\-:(),*+~]+$/;
/** A value that could END the declaration or INJECT CSS — refused even though the CLI already guards. */
const UNSAFE_VALUE = /[;{}<>\\]|url\(|expression\(|@import|\/\*/i;
const DUR_DEFAULT = "var(--dur-base)";
const EASE_DEFAULT = "var(--ease-standard)";
/** Cap on the stagger nth-child ramp (#3055): pure-CSS stagger needs one rule per position, so it's
 *  bounded — 32 covers typical charts, and elements past it fall back to the base delay (graceful,
 *  documented). */
const STAGGER_MAX = 32;

function safeValue(v: unknown): v is string {
  return typeof v === "string" && v.length > 0 && !UNSAFE_VALUE.test(v);
}

/** Sanitize a component name/id into a safe CSS-identifier SEGMENT for keyframe/class namespacing
 *  (#3163): lowercased, every non-`[a-z0-9-]` run collapsed to `-`, leading/trailing `-` stripped. Empty
 *  (or an all-unsafe input) ⇒ "" — the caller then falls back to the un-namespaced form. So a PascalCase
 *  component name (`Sparkline` → `sparkline`, `Bar Chart` → `bar-chart`) namespaces cleanly. */
function identSegment(s: string): string {
  const slug = (s ?? "").toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-+|-+$/g, "");
  return SAFE_IDENT.test(slug) ? slug : "";
}

/** The `@keyframes` NAME for a def — namespaced by its owning {@link AnimationDef.component} when one is
 *  set (#3163), so two components' same-named animations compile to DISTINCT keyframes instead of one
 *  clobbering the other. Absent/unsafe `component` ⇒ the plain `bsc-<kit>-<name>` (existing behavior). */
function animKeyframeName(d: AnimationDef): string {
  const seg = identSegment(d.component ?? "");
  return seg ? `bsc-${d.kit}-${seg}-${d.name}` : `bsc-${d.kit}-${d.name}`;
}

/** The applying CLASS hook for a def — the component-namespaced twin of {@link animKeyframeName}
 *  (#3163): `.<kit>-<component>-anim-<name>` when a `component` is set, else `.<kit>-anim-<name>`. The
 *  renderer (ComponentPreviewFrame) stamps this EXACT class on `#root`, so it always matches the compiled
 *  rule — exported so the preview derives the class the same way the compiler names the keyframes. */
export function animClassName(d: { kit: string; name: string; component?: string }): string {
  const seg = identSegment(d.component ?? "");
  return seg ? `${d.kit}-${seg}-anim-${d.name}` : `${d.kit}-anim-${d.name}`;
}

/** Compile one animation's `@keyframes` block, or "" when no stop/declaration passes the guards. */
function keyframesCss(d: AnimationDef): string {
  const stops: string[] = [];
  for (const [stop, decls] of Object.entries(d.keyframes ?? {})) {
    if (!SAFE_STOP.test(stop)) continue;
    const lines = Object.entries(decls ?? {})
      .filter(([prop, value]) => SAFE_PROP.test(prop) && safeValue(value))
      .map(([prop, value]) => `    ${prop}: ${value};`);
    if (lines.length) stops.push(`  ${stop} {\n${lines.join("\n")}\n  }`);
  }
  return stops.length ? `@keyframes ${animKeyframeName(d)} {\n${stops.join("\n")}\n}` : "";
}

/**
 * Compile animation definitions into CSS: a `@keyframes bsc-<kit>-<name>` block + a
 * reduced-motion-guarded rule applying it on `.<kit>-anim-<name>` (`:hover` for a hover
 * trigger; `[data-bsc-exit]` for an `exit` trigger — dormant until the exit-runtime, #3057;
 * `infinite` for `always`, else played once). A valid {@link KitAnimation.selector}
 * scopes the applying rule to a CHILD (`.<kit>-anim-<name> <selector>`, #3054); {@link KitAnimation.set}
 * adds static declarations to the rule body; {@link KitAnimation.delay} slots into the shorthand after
 * easing (#3056). A {@link KitAnimation.stagger} with a valid `selector` (#3055) adds, after the base
 * rule, a bounded `:nth-child(2..STAGGER_MAX)` `animation-delay` ramp so the matched elements cascade.
 * Pure + guarded — skips any definition whose kit/name isn't a safe identifier, whose
 * duration/easing/delay looks like an injection, or with no valid keyframes; an unsafe selector falls
 * back to the root class (and drops the stagger ramp) and an unsafe `set` pair is dropped. Empty string
 * when nothing is renderable.
 */
export function compileAnimationsCss(defs: AnimationDef[]): string {
  const blocks: string[] = [];
  for (const d of defs) {
    if (!d || !SAFE_IDENT.test(d.kit ?? "") || !SAFE_IDENT.test(d.name ?? "")) continue;
    const frames = keyframesCss(d);
    if (!frames) continue;
    const dur = safeValue(d.duration) ? d.duration! : DUR_DEFAULT;
    const ease = safeValue(d.easing) ? d.easing! : EASE_DEFAULT;
    const delay = safeValue(d.delay) ? ` ${d.delay}` : "";
    // #3163: the keyframe name + applying class are namespaced by `component` (when set) so a chart and
    // its composed pieces can each carry a same-named animation without one clobbering the other.
    const anim = animKeyframeName(d);
    const cls = `.${animClassName(d)}`;
    // #3054: scope to a child when a safe selector is given (descendant combinator); else the root class.
    const scoped = SAFE_SELECTOR.test(d.selector ?? "") ? `${cls} ${d.selector!.trim()}` : cls;
    // #3057: `exit` keys the rule on a `[data-bsc-exit]` marker — DORMANT until the exit-runtime sets it
    // on a leaving element (nothing sets it today, so an exit rule compiles but never matches → inert).
    const rule =
      d.trigger === "hover" ? `${scoped}:hover`
      : d.trigger === "exit" ? `${scoped}[data-bsc-exit]`
      : scoped;
    const iter = d.trigger === "always" ? "infinite" : "1";
    // #3054: static declarations on the applying rule, guarded exactly like a keyframe declaration.
    const setCss = Object.entries(d.set ?? {})
      .filter(([prop, value]) => SAFE_PROP.test(prop) && safeValue(value))
      .map(([prop, value]) => `${prop}: ${value};`)
      .join(" ");
    const body = `${setCss ? `${setCss} ` : ""}animation: ${anim} ${dur} ${ease}${delay} ${iter} both;`;
    // #3055: with a valid child selector AND a valid stagger step, cascade the matched elements by a
    // bounded nth-child `animation-delay` ramp AFTER the base rule (same scoped(+hover) selector, so
    // specificity + trigger match — `… :hover:nth-child(k)` overrides the base delay). nth-child(1) is
    // already the base delay (the shorthand), so the ramp starts at k=2; each step is (k-1) × stagger,
    // added onto the base delay when one is present. Elements past STAGGER_MAX keep the base delay.
    let staggerRamp = "";
    if (SAFE_SELECTOR.test(d.selector ?? "") && safeValue(d.stagger)) {
      const baseTerm = safeValue(d.delay) ? `${d.delay} + ` : "";
      const steps: string[] = [];
      for (let k = 2; k <= STAGGER_MAX; k++) {
        steps.push(`  ${rule}:nth-child(${k}) { animation-delay: calc(${baseTerm}${k - 1} * ${d.stagger}); }`);
      }
      staggerRamp = `\n${steps.join("\n")}`;
    }
    blocks.push(
      `${frames}\n@media (prefers-reduced-motion: no-preference) {\n  ${rule} { ${body} }${staggerRamp}\n}`,
    );
  }
  return blocks.join("\n\n");
}

/** Flatten a kit list's authored `animations` into the flat `AnimationDef[]` the compiler takes,
 *  keying each by its kit's CSS class base (the kit id — the kit convention). */
export function kitAnimations(
  kits: { id: string; animations?: KitAnimation[] }[],
): AnimationDef[] {
  const out: AnimationDef[] = [];
  for (const k of kits) {
    const kit = k.id ?? "";
    for (const a of k.animations ?? []) out.push({ ...a, kit });
  }
  return out;
}

/**
 * Inject / update / clear the managed `<style id="bsc-ui-animations">` holding the compiled animation
 * CSS. Removing the last animation removes the element. `doc` is param'd for tests. Mirrors
 * {@link applyVariantsToRoot} — one global stylesheet the whole app follows.
 */
export function applyAnimationsToRoot(defs: AnimationDef[], doc: Document = document): void {
  const css = compileAnimationsCss(defs);
  let el = doc.getElementById(STYLE_ID) as HTMLStyleElement | null;
  if (!css) {
    el?.remove();
    return;
  }
  if (!el) {
    el = doc.createElement("style");
    el.id = STYLE_ID;
    doc.head.appendChild(el);
  }
  el.textContent = css;
}

runtime.shared/ui/kit/baseAnimations.ts:
// The `base` kit's MOTION library as DATA (#3451, epic #3260) — the base-studio-code app's OWN
// foundational animations (`lift` / `fade-in` / `pulse`) authored as {@link KitAnimation} data, compiled
// by the kit-motion engine (`compileAnimationsCss`) into `@keyframes bsc-base-<name>` + `.base-anim-<name>`.
//
// ── WHY A DEDICATED `base` KIT (not welded to `react-ui`) ────────────────────────────────────────────
// These three motions are a base vocabulary the whole platform leans on, but they lived inside the
// `react-ui` DEMO kit (its primitives' authored `animations`). That made one demo kit the owner of shared
// motion: any project adopting a different kit lost them, and the app's own UI couldn't reference them as
// shared graph nodes. They now live in ONE place — this kit — and every consumer (react-ui's Button /
// Card / StatusDot, and any future kit) REFERENCES them by name. Edit `lift` here once → every consumer's
// preview updates in lockstep, no regeneration. That shared resolution IS the propagation mechanic applied
// to motion (the resolver falls back to this kit for any name a consumer's own kit doesn't define —
// `resolveComponentAnimationDefs` in `features/designs/lib/model.ts`).
//
// ── WHY THIS LIVES IN shared/ui/kit ──────────────────────────────────────────────────────────────────
// Same reasoning as {@link file://./algoVizAnimations.ts}: it is genuinely feature-agnostic motion DATA
// with more than one consumer (the `manifest.ts` primitives that bind these names + the Designs `base`
// builtin kit), so it's a leaf both import cheaply — importing a feature barrel from the seed would risk a
// module cycle. The base kit is assembled from this const in `features/designs/lib/baseKit.ts` and seeded
// UNCONDITIONALLY (like the viz kits) so a consumer's reference always resolves.

import type { KitAnimation } from "./animations";

/** The base-motion kit id — `.base-anim-<name>` + `@keyframes bsc-base-<name>`. The store id (`bsc/base`)
 *  is added when the kit joins the Rust `bsc ui` store (a follow-up slice of #3451). */
export const BASE_KIT_ID = "base";

