    return (
      <Box as="button" className={cls} aria-expanded={open} onClick={onToggle} title={title} style={style}>
        <Box as="span" className={`rail-caret${open ? " open" : ""}`}>▸</Box>
        <SectionLabel size={size} style={{ flex: 1 }}>{children}</SectionLabel>
        {right}
