// The spec-first UI SDK (#1852 Phase 2) — public barrel. An AI emits a node tree as data;
// `validateGeneralNode` checks it against the shared primitive contract (`@data/ui/primitives.json`,
// generated from `shared/ui/manifest.ts` and also served + enforced by `bsc ui schema` / `validate`);
// `KitRenderer` renders it through the real kit primitives, wiring `binds` (host state in) and
// `actions` (host behaviour out). See `demoSpec` for a real end-to-end example.
//
// #3500 collapsed the closed `KitNode` vocabulary — the 8 hardcoded kinds (card/header/field/button/
// row/toggle/tag/text) and the hand-written renderer branch behind each — into this ONE open node
// over the whole manifest. A spec now names real components, so adding a primitive makes it
// authorable with no edit to the renderer, the validator, or the contract.

export type { GeneralNode } from "./generalNode";
export { validateGeneralNode, PRIMITIVE_NAMES, VALIDATION_COVERAGE } from "./generalNode";
export { KitRenderer } from "./KitRenderer";
export type { KitRendererProps, KitBindings } from "./KitRenderer";
export { SelfWiredKitRenderer } from "./SelfWiredKitRenderer";
export type { SelfWiredKitRendererProps } from "./SelfWiredKitRenderer";
export { visitNodes, collectActions } from "./specWalk";
export { demoSpec } from "./demoSpec";

runtime.shared/ui/spec/KitRenderer.tsx:
// KitRenderer (#1852 Phase 2) — renders a declarative node tree through the shared UI primitives,
// wiring each node's `binds` (host state a control reads) and `actions` (host callbacks it fires) to
// the values/handlers the host passes in. The agent authors the spec as data; the host owns the
// wiring — the agent never writes an onChange or an onClick. Switching the underlying kit/theme later
// is a renderer change here, never a change to the spec the agent emitted.
//
// #3500 — there is no per-node branch left. The renderer used to carry a hand-written `switch` over 8
// hardcoded kinds, so the authorable vocabulary was whatever this file happened to implement; a new
// primitive meant editing the union, the contract, the validator AND this switch. Now a node names a
// REAL component and everything is resolved from the manifest: adding a primitive makes it authorable
// with no edit here at all.

import { Fragment, type ComponentType, type ReactNode } from "react";
import { Text } from "@/shared/ui/typography/Text";
import { componentFor } from "@/shared/ui/registry";
import { UI_KIT } from "@/shared/ui/manifest";
import type { GeneralNode } from "./generalNode";

/** Primitive name → its manifest spec, for looking up a prop's declared TYPE at render time. */
const SPEC_BY_NAME = new Map(UI_KIT.map((p) => [p.name as string, p]));

/** A node-ish value — matching what the validator will descend into, so anything that validates renders. */
function isNodeLike(v: unknown): boolean {
  return (
    typeof v === "object" && v !== null && !Array.isArray(v) &&
    typeof (v as Record<string, unknown>).type === "string"
  );
}

/** Render a slot value: a list of nodes, a single node, or plain text — mirroring what the validator
 *  accepts for a `node`-typed prop. */
function renderSlot(value: unknown, ctx: KitBindings, key: string): ReactNode {
  if (Array.isArray(value)) {
    return value.map((v, i) =>
      isNodeLike(v) ? renderNode(v as GeneralNode, ctx, `${key}[${i}]`) : (v as ReactNode),
    );
  }
  if (isNodeLike(value)) return renderNode(value as GeneralNode, ctx, key);
  return value as ReactNode;
}

/**
 * Render a node by resolving its `type` through the registry (#3494) — no per-primitive branch.
 *
 * Props pass through except where the manifest declares their TYPE, which is how the renderer knows
 * what to do without guessing from names:
 * - `function` ⇒ the value is an ACTION NAME (the 3a contract), resolved against `ctx.on`. A data tree
 *   never carries a function, so this is the ONLY way a handler can arrive.
 * - `node` ⇒ a slot, rendered recursively.
 *
 * An unresolvable `type` renders a VISIBLE error rather than null: a silent blank in a data-driven UI
 * is indistinguishable from "the data said render nothing", which is precisely the failure this whole
 * migration must not introduce. It does not throw — that would white-screen a production surface over
 * one bad node.
 */
function renderNode(node: GeneralNode, ctx: KitBindings, key: string): ReactNode {
  // `Slot` (#3504) is the ONE structural node the renderer resolves itself, because it is not a
  // component: it is a hole the host fills. Everything else resolves through the registry, and this
  // is deliberately not the start of a per-type switch — a slot has no rendering of its own to pick.
  // An unfilled name falls through to the `Slot` component, which states the problem visibly rather
  // than rendering nothing (a blank panel is indistinguishable from an intentionally empty layout).
  if (node.type === "Slot") {
    const name = String(node.props?.name ?? "");
    const filled = ctx.slots?.[name];
    if (filled !== undefined) return <Fragment key={key}>{filled}</Fragment>;
  }
  const Comp = componentFor(node.type);
  if (!Comp) {
    return (
      <Text key={key} tone="danger" size="sm">
        {`[unknown primitive "${node.type}" — not in the UI registry]`}
      </Text>
    );
  }
  const spec = SPEC_BY_NAME.get(node.type);
  const props: Record<string, unknown> = {};
  for (const [name, value] of Object.entries(node.props ?? {})) {
    const declared = spec?.props.find((p) => p.name === name);
    if (declared?.type === "function") {
      // The value is an action name; bind it to the host callback. An unknown name becomes a no-op
      // rather than a crash — the same tolerance the legacy `button` branch always had.
      // Arguments are FORWARDED: a handler like `TextField.onChange(next)` carries the new value, and
      // dropping it would make every text/select field in a data-driven UI unwritable.
      const action = typeof value === "string" ? value : "";
      props[name] = (...args: unknown[]) => {
        ctx.on?.[action]?.(...args);
        ctx.emit?.({ type: node.type, prop: name, args });
      };
      continue;
    }
    if (declared?.type === "node") {
      props[name] = renderSlot(value, ctx, `${key}.${name}`);
      continue;
    }
    props[name] = value;
  }

  // `binds` (#3500): read host state INTO a prop — the mirror of `actions`, state in / behaviour out.
  // Writes are NOT derived here: that would mean knowing `on` pairs with `onClick`, a pairing the
  // manifest does not declare, so the host names its intent as an action instead.
  for (const [propName, stateKey] of Object.entries(node.binds ?? {})) {
    props[propName] = ctx.values?.[stateKey];
  }

  // `actions` (#3496). Applied AFTER the declared-prop pass so it wins on a conflict: it is the more
  // explicit statement, and letting the implicit path override an explicit one would be surprising
  // precisely when an author is trying to be unambiguous. This is also the ONLY way to bind a handler
  // on a `passthrough` primitive (e.g. `Button.onClick`), whose handlers are undeclared.
  for (const [propName, actionName] of Object.entries(node.actions ?? {})) {
    props[propName] = (...args: unknown[]) => {
      ctx.on?.[actionName]?.(...args);
      ctx.emit?.({ type: node.type, prop: propName, args });
    };
  }

  // Node-level `children` is sugar for the `children` prop (the 3a normalisation) — resolved here too,
  // so a tree that validates renders.
  const children =
    node.children !== undefined ? renderSlot(node.children, ctx, `${key}.children`) : props.children;
  delete props.children;
  const C = Comp as ComponentType<Record<string, unknown>>;
  return (
    <C key={key} {...props}>
      {children as ReactNode}
    </C>
  );
}

/** The host-supplied wiring a rendered spec binds to. */
export interface KitBindings {
  /** Current host state, keyed by a node's `binds` values. */
  values?: Record<string, unknown>;
  /** Host-supplied React, keyed by a `Slot` node's `name` (#3504) — the seam for the parts of a page a
   *  spec cannot express (a feature component owning hooks, queries or app state). The spec says
   *  where; this says what. */
  slots?: Record<string, ReactNode>;
  /** Host callbacks, keyed by an action name (a node's `actions` map, or a `function`-typed prop whose
   *  value is the name). Called with whatever the underlying handler was called with — a click event
   *  for `onClick`, the new value for `onChange` — so a host can write a field back. */
  on?: Record<string, (...args: unknown[]) => void>;
  /** Analytics EMIT hook (#3816, epic #3809 slice 3). Called AFTER a bound handler fires, with the
   *  node's component `type`, the action PROP that fired, and its args. A host-supplied, manifest-driven
   *  runtime (`makeAnalyticsEmit` in `@/features/designs`) turns this into a `bsc usage record` call —
   *  so a spec composed from instrumented components self-reports BY CONSTRUCTION. Absent ⇒ no
   *  instrumentation: the default render path is byte-for-byte unchanged (the dev-only / opt-in gate).
   *  The renderer never reads a component's analytics manifest itself — that lives in the components
   *  store, a feature the shared renderer cannot import — so the host wires the lookup into this hook. */
  emit?: (fire: { type: string; prop: string; args: unknown[] }) => void;
}

export interface KitRendererProps extends KitBindings {
  /** The spec tree to render (typically the agent's emitted JSON, validated before rendering). */
  node: GeneralNode;
}

/** Render a node tree. `values`/`on` wire the spec's `binds`/`actions` to host state and behaviour. */
export function KitRenderer({ node, values, on, slots, emit }: KitRendererProps) {
  return <>{renderNode(node, { values, on, slots, emit }, "$")}</>;
}

runtime.shared/ui/spec/SelfWiredKitRenderer.tsx:
// SelfWiredKitRenderer (#2868) — a KitRenderer that supplies its OWN interaction host.
//
// The spec model's interactions are declarative but HOST-DRIVEN: a control's value comes from
// `values[key]` (its `binds`) and its behaviour fires `on[action]` (its `actions`). In a real app the
// host wires both. But in the HOST-LESS contexts — the Design Studio / kit preview, a nested composed
// spec rendered with no app behind it — there is no host, so a previewed toggle renders in its default
// state and does nothing on click. This wrapper is the self-wiring default: it keeps a local
// bind-keyed state so every control exhibits its EXPECTED behavior (toggles toggle, selects select,
// fields type), COMPOSING per bind key so a page → composite → toggle each behave independently, and
// resolves every action so clicks are observable instead of dead.
//
// Use this wherever a spec is previewed without an app host. In a real app, pass explicit bindings to
// KitRenderer directly — this never overrides host wiring, it stands in for its absence.
//
// #3500 — HOW A PREVIEW DECIDES WHAT AN ACTION WRITES. The general vocabulary deliberately refuses to
// infer that `onClick` writes `on`: only the host knows what a click MEANS, so a real app names the
// intent as an action. A preview has no host to ask, and the alternative is dead controls, so it
// adopts one rule — driven by the MANIFEST's declared prop types, never by guessing from prop names:
//
//   the bound prop is `boolean` → the action FLIPS it   (a switch switches)
//   otherwise                   → the action SETS it from the handler's first argument
//                                 (`onChange(next)` on a field)
//
// That rule lives here and ONLY here. It is a stand-in for absent behaviour, not part of the contract;
// nothing outside a preview may rely on it.

import { useMemo, useState } from "react";
import { UI_KIT } from "@/shared/ui/manifest";
import { KitRenderer } from "./KitRenderer";
import { visitNodes, collectActions } from "./specWalk";
import type { GeneralNode } from "./generalNode";

/** Primitive name → its manifest spec, for looking up a bound prop's declared type. */
const SPEC_BY_NAME = new Map(UI_KIT.map((p) => [p.name as string, p]));

/** What a fired action should do to the local preview state. */
interface PreviewWrite {
  /** The bind key it writes. */
  key: string;
  /** Flip the boolean (a switch) vs set it from the handler's first argument (a field). */
  flip: boolean;
}

/**
 * Map each action name in the spec to the local state write it should perform, by pairing a node's
 * `actions` with its `binds` and consulting the manifest for the bound prop's type.
 *
 * A node with no `binds` yields no write — its action is observed only (a Save button has nothing to
 * write). If the same action name appears on several bound nodes, the FIRST wins; a preview showing
 * one of them behaving is strictly better than neither, and a real host would have disambiguated.
 */
function previewWrites(root: GeneralNode): Map<string, PreviewWrite> {
  const writes = new Map<string, PreviewWrite>();
  visitNodes(root, (n) => {
    const binds = Object.entries(n.binds ?? {});
    const actions = Object.values(n.actions ?? {});
    if (!binds.length || !actions.length) return;
    const spec = SPEC_BY_NAME.get(n.type);
    const typeOf = (prop: string) => spec?.props.find((p) => p.name === prop)?.type;
    // Prefer a boolean-typed bind (the switch case); otherwise take the first bind as the value.
    const boolBind = binds.find(([prop]) => typeOf(prop) === "boolean");
    const [prop, key] = boolBind ?? binds[0];
    if (typeof key !== "string" || !key) return;
    for (const action of actions) {
      if (typeof action !== "string" || !action || writes.has(action)) continue;
      writes.set(action, { key, flip: typeOf(prop) === "boolean" });
    }
  });
  return writes;
}

export interface SelfWiredKitRendererProps {
  /** The spec tree to render (typically validated via `validateGeneralNode`). */
  node: GeneralNode;
  /** Seed values for the local bind-keyed state (e.g. a toggle that should start on). Defaults empty
   *  — toggles start off, fields start blank. Read once at mount (a preview seed, not a controlled prop). */
  initial?: Record<string, unknown>;
  /** Observe a fired action — the preview host can flash/log it. Defaults to a no-op, so a nested
   *  control is clickable without an app behind it. */
  onAction?: (action: string) => void;
}

export function SelfWiredKitRenderer({ node, initial, onAction }: SelfWiredKitRendererProps) {
  const [values, setValues] = useState<Record<string, unknown>>(() => ({ ...initial }));
  // Resolve EVERY action in the spec so no control is dead: the ones paired with a bind also write
  // the local state, the rest are observed. Rebuilt only when the spec or observer changes.
  const on = useMemo(() => {
    const writes = previewWrites(node);
    const map: Record<string, (...args: unknown[]) => void> = {};
    for (const action of collectActions(node)) {
      const write = writes.get(action);
      map[action] = (...args: unknown[]) => {
        if (write) {
          setValues((v) => ({
            ...v,
            [write.key]: write.flip ? !v[write.key] : args[0],
          }));
        }
        onAction?.(action);
      };
    }
    return map;
  }, [node, onAction]);
  return <KitRenderer node={node} values={values} on={on} />;
}

runtime.shared/ui/spec/specWalk.ts:
// Pure node-tree helpers (#2868) — depth-first traversal + derived collections over a spec tree.
// No React; the interaction-defaults host (SelfWiredKitRenderer) and future behavior slices read from
// here.
//
// Generalised in #3500. The old walk descended two hardcoded kinds (`card`'s header + children, and
// `row`'s children) and treated everything else as a leaf — so a node nested in ANY other slot was
// invisible to it. The general vocabulary has no fixed set of container types, so the walk now
// descends STRUCTURALLY: any prop value that is (or contains) a node is followed, as is the
// node-level `children` sugar. A spec that renders is therefore a spec that walks — the two can no
// longer disagree about where the children are.

import { UI_KIT } from "@/shared/ui/manifest";
import type { GeneralNode } from "./generalNode";

/** Primitive name → the set of its props the manifest declares as handlers. */
const FUNCTION_PROPS = new Map(
  UI_KIT.map((p) => [
    p.name as string,
    new Set(p.props.filter((x) => x.type === "function").map((x) => x.name)),
  ]),
);

/** Is this a node? Structural, matching what the renderer will actually descend into. */
function isNode(v: unknown): v is GeneralNode {
  return (
    typeof v === "object" && v !== null && !Array.isArray(v) &&
    typeof (v as { type?: unknown }).type === "string"
  );
}

/** Follow a slot value: a node, a list of them, or plain text (a leaf). */
function visitSlot(value: unknown, fn: (n: GeneralNode) => void): void {
  if (Array.isArray(value)) {
    for (const v of value) visitSlot(v, fn);
    return;
  }
  if (isNode(value)) visitNodes(value, fn);
}

/** Visit every node in a tree depth-first (self, then every node found in its props and children).
 *  Pure — the visitor sees each node exactly once. */
export function visitNodes(node: GeneralNode, fn: (n: GeneralNode) => void): void {
  fn(node);
  for (const value of Object.values(node.props ?? {})) visitSlot(value, fn);
  if (node.children !== undefined) visitSlot(node.children, fn);
}

/** Every distinct action name in a spec (#2868) — the actions a self-wiring host must resolve so a
 *  nested control's click never no-ops. Order is first-seen; duplicates collapse.
 *
 *  BOTH routes count, because the renderer honours both: the node-level `actions` map, and a
 *  `function`-typed prop whose value is an action name. A host that resolved only one of them would
 *  leave the other half of its own specs dead. */
export function collectActions(node: GeneralNode): string[] {
  const out = new Set<string>();
  visitNodes(node, (n) => {
    for (const name of Object.values(n.actions ?? {})) {
      if (typeof name === "string" && name) out.add(name);
    }
    const handlers = FUNCTION_PROPS.get(n.type);
    if (!handlers) return;
    for (const [prop, value] of Object.entries(n.props ?? {})) {
      if (handlers.has(prop) && typeof value === "string" && value) out.add(value);
    }
  });
  return [...out];
}

runtime.shared/ui/typography/Eyebrow.tsx:
// Eyebrow — the uppercase-mono micro-label (#2720). A thin wrapper over Text that fixes the
// one recurring recipe: mono + dim + uppercase + letter-spacing. It replaces the per-feature
// `.ds-eyebrow` / `.themes-eyebrow` CSS rules (which differed only in font-size), so `size`
// keeps each site's exact px (9.5 vs 10). Any extra prop (className, as, title, …) passes through.

import type { ReactNode, ElementType, CSSProperties } from "react";
import { Text } from "./Text";

export interface EyebrowProps {
  children?: ReactNode;
  /** Font size in px — keeps existing sites lossless (ds sites use 9.5, themes uses 10). */
  size?: number;
  /** The rendered element (default `"span"`). */
  as?: ElementType;
  className?: string;
  style?: CSSProperties;
  /** Any other prop passes straight through to Text. */
  [key: string]: unknown;
}

export function Eyebrow({ children, size = 10, as = "span", style, ...rest }: EyebrowProps) {
  return (
    <Text
      mono
      size={size}
      tone="dim"
      as={as}
      style={{ letterSpacing: ".08em", textTransform: "uppercase", ...style }}
      {...rest}
    >
      {children}
    </Text>
  );
}

runtime.shared/ui/typography/type.ts:
// type.ts — the shared vocabulary the Text primitive is built on (#2057).
//
// One type scale, one semantic tone mapping. The named `TextSize` rungs mirror the `--fs-*` CSS
// tokens in tokens.css (xxs=9 … xl=18) so the primitive and the stylesheet speak the same scale —
// chosen from the real fontSize distribution (11/10/12/14/18 dominate). But a raw pixel number is
// always legal too (the off-scale half-sizes 9.5/10.5/11.5/13 stay `size={10.5}`), which keeps
// mechanical `<span style={{ fontSize }}>` → primitive conversions lossless.

/** A font size: a named scale rung, or a raw pixel number for the off-scale cases. */
export type TextSize = number | "xxs" | "xs" | "sm" | "md" | "lg" | "xl";

/** A semantic tone: maps to a foreground color token. Omit to inherit (no color forced). */
export type Tone = "dim" | "muted" | "accent" | "danger" | "success";

const SCALE: Record<Exclude<TextSize, number>, number> = { xxs: 9, xs: 10, sm: 11, md: 12, lg: 14, xl: 18 };

const TONE: Record<Tone, string> = {
  dim: "var(--fg-dim)",
  muted: "var(--fg-muted)",
  accent: "var(--accent)",
  danger: "var(--danger)",
  success: "var(--success)",
};

/** Resolve a `TextSize` to a pixel number (named rung → scale, number → itself). */
export function fontSize(v: TextSize | undefined): number | undefined {
  if (v == null) return undefined;
  return typeof v === "number" ? v : SCALE[v];
}

/** Resolve a semantic `Tone` to its color token (undefined → inherit, no color set). */
export function toneColor(v: Tone | undefined): string | undefined {
  return v == null ? undefined : TONE[v];
}

runtime.store/appState.ts:
// App-state snapshot (#2272) — the pure core behind the "demoable" app-state feature: a curated,
// shareable snapshot of the store that makes every workspace look ALIVE (projects, the Glance graph,
// the libraries, per-project plans/fleets, automations), loaded on a certain occasion as a demo.
//
// The snapshot is an ALLOWLIST (`DEMOABLE_KEYS`) — this is the security boundary. It deliberately
// EXCLUDES secrets (GitHub/LLM tokens + keys), the GitHub connection + real repos, machine-specific
// state (tabs/panes/cwds/local repo paths), and pure user prefs/toggles. So a snapshot published to a
// gist can never leak a token, and loading an untrusted app-state gist can never set an arbitrary
// store field — `pickDemoable` filters an incoming payload down to exactly these keys.
//
// Pure (no React/Tauri/store access) so it's unit-testable; the store action + gist transport that
// hydrate from this land in the wiring slice.

import type { AppStore } from "./types";

/**
 * The store keys that make up a shareable app-state snapshot. Grouped by what they populate. Adding a
 * key here makes it travel in a demo; removing one drops it. NOTHING secret or machine-specific
 * belongs here (see the module header).
 */
export const DEMOABLE_KEYS = [
  // Projects + the Glance project-network graph
  "localDraftProjects", "triagedProjects", "projectLinks", "issueLinks", "hiddenProjectIds", "achievements",
  // Libraries (built-ins are reconciled on load; these carry the user/demo additions + selection)
  "blueprints", "activeBlueprintId", "skills", "skillGroups", "personas", "teams", "teamsZoom",
  "mcpServers", "hooks",
  // Automations
  "schedules", "commands", "automations",
  // Per-project plan / fleet / UI-plan data
  "planStages", "planConfirmedStages", "planSkippedStages", "planDeployConfig", "planMarketConfig", "planTransformations",
  "planAutomations", "planStageConfig", "projectBlueprintId", "planClassification", "uiScreens", "uiApproved",
  "planFleet", "planFleetTopology", "planFleetDirectorDrive", "pinnedContext",
  // Agent config · startup/triage prompt docs · repo visibility · per-session skill mapping
  "agentProfiles", "configProfiles",
  "defaultStartupPromptDoc", "projectStartupPromptDoc", "repoStartupPromptDoc", "repoTriagePromptDoc",
  "reposPublic", "repoPublic", "sessionSkillOverrides", "sessionSkillGroups",
] as const;

/** A demoable store key. */
export type DemoableKey = typeof DEMOABLE_KEYS[number];

/** A curated app-state snapshot — a partial of the store, restricted to {@link DEMOABLE_KEYS}. */
export type AppStateSnapshot = Partial<Pick<AppStore, DemoableKey>>;

const DEMOABLE_SET = new Set<string>(DEMOABLE_KEYS);

/**
 * Filter an arbitrary object down to the demoable keys (present + defined). The single security
 * boundary for BOTH directions: snapshotting the store to publish, and sanitizing an untrusted gist
 * payload before it touches the store. Anything not in {@link DEMOABLE_KEYS} — a token, a machine
 * path, or a bogus injected field — is dropped.
 */
export function pickDemoable(source: unknown): AppStateSnapshot {
  if (!source || typeof source !== "object") return {};
  const o = source as Record<string, unknown>;
  const out: Record<string, unknown> = {};
  for (const k of DEMOABLE_KEYS) {
    if (k in o && o[k] !== undefined) out[k] = o[k];
  }
  return out as AppStateSnapshot;
}

/** Produce a shareable snapshot from the current store state (allowlist-filtered). */
export function snapshotAppState(state: Partial<Pick<AppStore, DemoableKey>>): AppStateSnapshot {
  return pickDemoable(state);
}

/** Whether `key` is a demoable store key (would be included in / accepted from a snapshot). */
export function isDemoableKey(key: string): key is DemoableKey {
  return DEMOABLE_SET.has(key);
}

const isPlainObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v);

/** Dedupe-union two arrays by each item's `id` (or the item itself for primitives); `inc` wins on a
 *  collision. Keeps existing order, then appends genuinely-new incoming items. */
function mergeArrayById(cur: unknown[], inc: unknown[]): unknown[] {
  const keyOf = (x: unknown) => (x && typeof x === "object" && "id" in x ? (x as { id: unknown }).id : x);
  const map = new Map<unknown, unknown>();
  for (const x of cur) map.set(keyOf(x), x);
  for (const x of inc) map.set(keyOf(x), x); // incoming overrides a same-id/-value item
  return [...map.values()];
}

/**
 * Merge a snapshot INTO current `state` (an additive load) — the partial to `set()`. Per demoable key:
 * arrays union by `id` (incoming wins), plain objects shallow-merge by key (incoming wins), scalars
 * replace. So loading a demo AUGMENTS the built-in libraries (personas/orgs/blueprints) + your data
 * instead of clobbering them (#2288). Unknown/undefined incoming keys are skipped. `state` is read-only.
 */
export function mergeSnapshotInto(state: Record<string, unknown>, snapshot: AppStateSnapshot): AppStateSnapshot {
  const inc = snapshot as Record<string, unknown>;
  const out: Record<string, unknown> = {};
  for (const k of DEMOABLE_KEYS) {
    if (!(k in inc) || inc[k] === undefined) continue;
    const incoming = inc[k];
    const current = state[k];
    if (Array.isArray(incoming) && Array.isArray(current)) out[k] = mergeArrayById(current, incoming);
    else if (isPlainObject(incoming) && isPlainObject(current)) out[k] = { ...current, ...incoming };
    else out[k] = incoming;
  }
  return out as AppStateSnapshot;
}

runtime.store/constants.ts:
// Console kickoff prompts sent as the first message to a launched session. Plain text only
// (no double quotes / $ / backticks) so each is safe to pass as `claude "<prompt>"`. Extracted
// from store/index.ts (store split, stage 1).
//
// The prompt PROSE is externalized to `@data/console/kickoff-prompts.json` (#2416) — editable
// without touching code + part of the exportable config bundle; the config-dir copy (#2047)
// overlays the embedded default via `overlayFile`. This module keeps only the interpolation
// (`fillTemplate` over `{{…}}` placeholders) and the assembly.

import { BSC_ISSUE_LABEL, triageIssueListArgs } from "@/shared/lib/github/issueProvenance";
import kickoffPromptsEmbedded from "@data/console/kickoff-prompts.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";
import { fillTemplate } from "@/shared/lib/core/template";

const PROMPTS = overlayFile("console/kickoff-prompts.json", kickoffPromptsEmbedded);

// Sent as the first message to each console when a project tab is opened, so the
// session starts by reading and executing the laid-out plan. Plain text only — no
// double quotes / $ / backticks — so it's safe to pass as `claude "<prompt>"`.
export const PROJECT_INIT_PROMPT = PROMPTS.projectInit;

// Sent verbatim as the first message to each triage console. Drives an issue
// triage pass over the pane's repo. Plain text only (no double quotes / $ /
// backticks) so it is safe to type into the PTY as a single line.
/**
 * Render the since-last-run delta (#1004) into a one-line lead for the triage prompt, so a re-run
 * resumes cheaply from what changed instead of re-ingesting the whole project. `changed` is the
 * plan.db `issues_changed_since(T)` result; `lastRun` is the marker (null ⇒ first triage). Empty
 * string when there's no marker (a fresh triage gets the full prompt).
 */
export function renderTriageDelta(
  changed: { ref: string; title: string; status: string }[],
  lastRun: number | null,
): string {
  if (lastRun === null) return ""; // never triaged → no delta lead; do the full pass
  if (changed.length === 0) return PROMPTS.triageDelta.noChanges;
  const by = (s: string) => changed.filter((i) => i.status === s).map((i) => i.ref);
  const groups: string[] = [];
  const landed = [...by("complete"), ...by("verified")];
  const stuck = [...by("blocked"), ...by("failed")];
  if (landed.length) groups.push(PROMPTS.triageDelta.groupLanded + landed.join(", "));
  if (stuck.length) groups.push(PROMPTS.triageDelta.groupStuck + stuck.join(", "));
  const detail = groups.length ? ` (${groups.join("; ")})` : "";
  return fillTemplate(PROMPTS.triageDelta.changed, { COUNT: String(changed.length), DETAIL: detail });
}

/**
 * The triage kickoff. When `restrictToBsc` (the secure default, #738), triage works ONLY
 * issues authored by base-studio-code (the `bsc-generated` label) and treats every other open
 * issue as untrusted — so a hand-created or injected issue isn't acted on. Off → all open issues.
 */
export function buildTriagePrompt(restrictToBsc: boolean, delta?: string, local?: boolean): string {
  // #1004: a non-empty delta leads the prompt so the agent resumes from what changed (token-aware).
  const resume = delta && delta.length > 0 ? delta + " " : "";
  // #3281 local-first: with no GitHub, the issues live in plan.db — fetch + work them via `bsc plan`,
  // not `gh`. Every plan.db issue is planner-authored, so the #738 restrict-to-bsc untrusted-external-
  // issue guard doesn't apply (there is no external channel) — the local path ignores `restrictToBsc`.
  if (local) {
    return resume + PROMPTS.triage.leadLocal + PROMPTS.triage.fetchLocal + PROMPTS.triage.rubricLocal;
  }
  const fetch = restrictToBsc
    ? fillTemplate(PROMPTS.triage.fetchRestricted, {
        LABEL: BSC_ISSUE_LABEL,
        LIST_ARGS: triageIssueListArgs(true),
      })
    : fillTemplate(PROMPTS.triage.fetchAll, { LIST_ARGS: triageIssueListArgs(false) });
  return resume + PROMPTS.triage.lead + fetch + PROMPTS.triage.rubric;
}

/** The secure-default triage prompt (bsc-authored issues only). */
export const TRIAGE_PROMPT = buildTriagePrompt(true);

runtime.store/demoSnapshot.ts:
// Curated demo world (#2282, follow-up to #2272) — ONE coherent, internally-consistent app-state
// snapshot that makes every workspace look ALIVE and tells a single story. It is authored over the
// `DEMOABLE_KEYS` shape (the security allowlist), so it can be loaded locally via `loadDemoState`
// OR published verbatim as the official public demo gist and offered from the empty states.
//
// THE STORY — "Northwind", a ~14-service e-commerce microservices platform being built and operated
// by an AI agent org. The SAME names cross-reference across every workspace:
//   • Glance    — the 14 projects (reusing the SAMPLE_GRAPH spine, #2272) as a NETWORK: infra at the
//                 base (auth-core, events-bus), services + data in the middle (billing/ledger/…), the
//                 clients on top (web/mobile/admin), wired by api/data/events edges — INCLUDING the
//                 reporting⇄analytics dependency CYCLE the map flags as a coordination hazard.
//   • Fleets    — three projects carry a live agent fleet (billing-svc, payments-gw, user-api); every
//                 worker stream launches AS one of the demo PERSONAS below.
//   • Libraries — the personas reference the demo SKILLS; the ORG places those personas and wires them
//                 with relationships; the demo BLUEPRINT attaches the same skills; the AUTOMATIONS act
//                 on the same projects. Nothing dangles: every id points at something in this world.
//
// The FIXTURE CONTENT (project meta, skills, personas, org, blueprint meta, fleets, automations) is
// externalized to `@data/demo/*.json` (#2419, epic #2027 tail); this module is the thin ASSEMBLER that
// owns the types and fills the runtime/default fields. The demo seeds are plain embedded imports, NOT
// config-dir-overlaid — the snapshot must stay byte-deterministic (stable across builds → stable gist
// bytes), so an edited config-dir copy never leaks into the published demo.
//
// Pure (no React/Tauri/store access) so it's unit-testable and the round-trip test can assert the
// snapshot is DEMOABLE_KEYS-only. Loading MERGES onto the built-in libraries (personas/orgs/skills/
// blueprints) rather than replacing them (mergeSnapshotInto, #2288).

import projectMetaData from "@data/demo/project-meta.json";
import skillsData from "@data/demo/skills.json";
import personasData from "@data/demo/personas.json";
import orgData from "@data/demo/org.json";
import blueprintData from "@data/demo/blueprint.json";
import fleetsData from "@data/demo/fleets.json";
import automationsData from "@data/demo/automations.json";
import { SAMPLE_GRAPH, type GRole, type GHealth, type GActivity } from "@/features/glance";
import { projectLinkId, type ProjectLink } from "@/features/glance/lib/projectLinks";
import type { Persona } from "@/features/personas/lib/persona";
import type { Team } from "@/features/teams/lib/team";
import type { SkillDef } from "@/features/skills/lib/skillsModel";
import type { SkillGroup } from "@/features/skills/lib/skillGroups";
import { makeBlueprints, DEFAULT_BLUEPRINT_ID, type Blueprint } from "@/features/planner/stages/blueprints";
import type { FleetPlan, AgentStream } from "@/features/planner/fleet/planFleet";
import type { Schedule, Command } from "@/shared/data/mock";
import type { Automation } from "@/features/automations/lib/scheduler";
import type { AppStateSnapshot } from "./appState";

/**
 * The gist the empty states offer as the official one-click demo. EMPTY by default — the local
 * {@link demoSnapshot} is the functional path (no auth needed). Publishing the gist is a MAINTAINER
 * manual step: run `saveDemoToGist` (Settings → Demo app-state → "Save current state…") from an
 * account with the `gist` scope AFTER loading the bundled demo, make it PUBLIC, then paste the
 * resulting `https://gist.github.com/<user>/<id>` URL here so the remote "Load demo" resolves it.
 * TODO(maintainer): bake the published demo-gist URL here.
 */
export const DEMO_GIST_URL = "" as const;

/** A fixed timestamp so the snapshot is deterministic (stable across builds → stable gist bytes). */
const DEMO_EPOCH = Date.UTC(2026, 0, 15); // 2026-01-15

// ── Projects — the Glance spine ──────────────────────────────────────────────────────────────────
// Display name + one-line pitch for each SAMPLE_GRAPH node (`@data/demo/project-meta.json`).
// role/health/activity come straight from the sample graph so the loaded Glance network matches the
// packaged sample exactly (the cycle hazard + the curated warning/error nodes included).
const PROJECT_META: Record<string, { title: string; pitch: string }> = projectMetaData;

type DemoProject = { title: string; pitch: string; createdAt: number; role?: GRole; health?: GHealth; activity?: GActivity; reason?: string };

/** The 14 demo projects, keyed by the SAMPLE_GRAPH node id (also the Glance node id + fleet/plan key). */
function demoProjects(): Record<string, DemoProject> {
  const out: Record<string, DemoProject> = {};
  for (const n of SAMPLE_GRAPH.rawNodes) {
    const meta = PROJECT_META[n.id] ?? { title: n.id, pitch: "" };
    out[n.id] = { title: meta.title, pitch: meta.pitch, createdAt: DEMO_EPOCH, role: n.role, health: n.health, activity: n.activity, reason: n.reason };
  }
  return out;
}

/** The Glance edges — the SAMPLE_GRAPH topology (incl. the reporting⇄analytics cycle) as user-drawn links. */
function demoLinks(): ProjectLink[] {
  return SAMPLE_GRAPH.rawEdges.map((e) => ({ id: projectLinkId(e.from, e.to, e.kind), from: e.from, to: e.to, kind: e.kind }));
}

// JSON module imports are shared singletons — clone at every seed boundary so each demoSnapshot()
// call mints fresh objects (the pre-#2419 behavior) and a later store mutation can't pollute the seed.
const clone = <T,>(v: T): T => structuredClone(v);

// ── Skills — the platform playbook (`@data/demo/skills.json`) ────────────────────────────────────
// The JSON carries the authored fields; the assembler fills the library defaults (team source,
// global + enabled + pinned) and the zeroed display-only telemetry.
function demoSkills(): SkillDef[] {
  return clone(skillsData.skills).map((s) => ({
    ...s,
    kind: s.kind as SkillDef["kind"],
    profiles: s.profiles as SkillDef["profiles"],
    source: "team" as const,
    projects: [], enabled: true, pinned: true,
    invocations: 0, success: 0, avgTokensK: 0, trend: [],
  }));
}

function demoSkillGroups(): SkillGroup[] {
  return clone(skillsData.groups);
}

// ── Personas — the agent identities the fleet launches as (`@data/demo/personas.json`) ───────────
function demoPersonas(): Persona[] {
  return clone(personasData) as Persona[];
}

// ── Team — the persona-relationship graph (`@data/demo/org.json`) ─────────────────────────────────
function demoOrg(): Team {
  return clone(orgData) as Team;
}

// ── Blueprint — the reusable template that seeds the platform's projects ─────────────────────────
const DEMO_BLUEPRINT_ID = blueprintData.id;

/** Clone the default built-in blueprint into the demo one (id/name/desc/skills overridden from
 *  `@data/demo/blueprint.json`) so the full, valid stage set rides along without hand-authoring it.
 *  Attaches the demo skills so the blueprint cross-references the same playbook the personas use. */
function demoBlueprint(): Blueprint {
  const builtins = makeBlueprints();
  const base = builtins.find((b) => b.id === DEFAULT_BLUEPRINT_ID) ?? builtins[0];
  return {
    ...base,
    id: DEMO_BLUEPRINT_ID,
    name: blueprintData.name,
    desc: blueprintData.desc,
    origin: "local",
    skills: skillsData.skills.map((s) => s.id),
    uses: blueprintData.uses,
    updatedAt: new Date(DEMO_EPOCH).toISOString(),
    gist: undefined,
  };
}

// ── Fleets — the live agent streams per project (`@data/demo/fleets.json`) ───────────────────────
// The JSON carries the planned streams; the assembler adds the shared fleet posture (an event-driven
// director over a director topology).
function demoFleets(): Record<string, FleetPlan> {
  const out: Record<string, FleetPlan> = {};
  for (const [key, f] of Object.entries(fleetsData)) {
    out[key] = {
      recommended: f.recommended,
      reasoning: f.reasoning,
      streams: clone(f.streams) as AgentStream[],
      director: { enabled: true, drive: "event" },
      topology: "director",
    };
  }
  return out;
}

// ── Automations — schedules · commands · cron rules (`@data/demo/automations.json`) ──────────────
function demoSchedules(): Schedule[] {
  return clone(automationsData.schedules) as Schedule[];
}

function demoCommands(): Command[] {
  return clone(automationsData.commands) as Command[];
}

/** The JSON carries the authored rule; the assembler zeroes the runtime state (never-yet-run). */
function demoAutomations(): Automation[] {
  return clone(automationsData.automations).map((a) => ({
    ...a,
    when: a.when as Automation["when"],
    action: a.action as Automation["action"],
    lastRunAt: null,
    nextRunAt: null,
    runs: [],
  }));
}

/**
 * Build the curated demo snapshot — a valid {@link AppStateSnapshot} over `DEMOABLE_KEYS`, internally
 * consistent (personas ↔ skills ↔ org ↔ fleets ↔ blueprint ↔ projects all cross-reference the same
 * names). Pass to `loadDemoState` to overlay it, or publish via `saveDemoToGist`.
 */
export function demoSnapshot(): AppStateSnapshot {
  const projects = demoProjects();
  const projectBlueprintId: Record<string, string> = {};
  for (const key of Object.keys(projects)) projectBlueprintId[key] = DEMO_BLUEPRINT_ID;

  const org = demoOrg();
  return {
    // Glance — the project network. Every demo project is TRIAGED (#2541) so the curated network
    // renders (the drafted→triaged gate would otherwise hide un-worked projects).
    localDraftProjects: projects,
    triagedProjects: Object.fromEntries(Object.keys(projects).map((k) => [k, DEMO_EPOCH])),
    projectLinks: demoLinks(),
    achievements: { "super-user": DEMO_EPOCH },

    // Libraries
    skills: demoSkills(),
    skillGroups: demoSkillGroups(),
    personas: demoPersonas(),
    teams: [org],
    teamsZoom: { [org.id]: 1 },
    blueprints: [demoBlueprint()],
    activeBlueprintId: DEMO_BLUEPRINT_ID,

    // Per-project plan / fleet
    planFleet: demoFleets(),
    projectBlueprintId,

    // Automations
    schedules: demoSchedules(),
    commands: demoCommands(),
    automations: demoAutomations(),
  };
}

runtime.store/helpers.ts:
// Shared store helpers used by index.ts (rehydrate) + the projects slice (launch actions).
// Extracted from store/index.ts during the store split (stage 2).
import type { AppStore } from "./types";
import type { DocAssignments } from "@/shared/lib/session/assignments";
import type { AgentStream } from "@/features/planner/fleet/planFleet";
import { type IntegrationStrategy, DEFAULT_STRATEGY, strategySettings } from "@/features/planner/lib/integrationStrategy";
import { resolveFlow } from "@/features/planner/fleet/agentFlow";
import { flowKickoffText } from "@/features/planner/fleet/flowKickoff";
import { type Automation, suggestionToAutomation, computeNextRun } from "@/features/automations/lib/scheduler";

/** Mint a stable tab id (#463). Prefers crypto.randomUUID; falls back for older
 *  webviews. Used for every tab the store creates + backfilled on hydration. */
export function newTabId(): string {
  try {
    if (typeof crypto !== "undefined" && crypto.randomUUID) return `tab_${crypto.randomUUID()}`;
  } catch { /* fall through */ }
  return `tab_${Date.now()}_${Math.floor(Math.random() * 1e9).toString(36)}`;
}

/**
 * Grid geometry for an N-pane console tab (#2712): the `cols`/`rows` a fleet or triage tab uses to
 * lay out `count` sessions. Byte-identical to the formula both launch reducers used inline — 1 col
 * for ≤1, 2 for ≤4, 3 for ≤9, else 4; rows = ceil(count / cols). Callers derive `paneCount =
 * cols * rows` (a full grid may have empty trailing cells).
 */
export function gridLayout(count: number): { cols: number; rows: number } {
  const cols = count <= 1 ? 1 : count <= 2 ? 2 : count <= 4 ? 2 : count <= 9 ? 3 : 4;
  const rows = Math.ceil(count / cols);
  return { cols, rows };
}

/**
 * Lifts the store's flat startup-prompt assignment fields into the
 * {@link DocAssignments} cascade the resolution module (#324) consumes. The
 * per-repo map is keyed by `repoPromptKey`, which is byte-identical to the
 * module's `scopeKey`, so it drops straight in. The session level is unused at
 * launch (assignment happens at the project/repo level).
 */
export function buildAssignments(s: {
  defaultStartupPromptDoc: string | null;
  projectStartupPromptDoc: Record<string, string | null>;
  repoStartupPromptDoc: Record<string, string | null>;
}): DocAssignments {
  return {
    startupPrompt: {
      default: s.defaultStartupPromptDoc,
      project: s.projectStartupPromptDoc,
      repo: s.repoStartupPromptDoc,
      session: {},
    },
  };
}


// Fallback first message for a fleet worker whose stream has no planner-authored
// kickoff script. Plain text only (no double quotes / $ / backticks) so it is safe
// to pass as claude's initial-message arg. The worker's SCOPE (owned globs, issues,
// dependencies) lives in CLAUDE.local.md — NOT the full plan (#844): the worktree is
// outside the hub, so the worker loads only its lane; high-level context is the
// director's. This points the session at that scope file and the autonomy rules.
export function buildStreamPrompt(stream: AgentStream, strategy?: IntegrationStrategy): string {
  const owns   = stream.owns.length   ? stream.owns.join(", ")   : "the files for your area";
  const issues = stream.issues.length ? stream.issues.join(", ") : "the issues assigned to your area";
  const strat = strategy ?? DEFAULT_STRATEGY;
  const effPush = strategySettings(strat).integrate;
  const effFlow = { ...resolveFlow(stream.flow), push: stream.flow?.push ?? effPush };
  const kick = flowKickoffText(effFlow, stream.id);
  return (
    `You are the ${stream.name} work stream, one of several Claude sessions building this project in parallel. ` +
    `Your scope — the files and issues you own, and what you depend on — is in CLAUDE.local.md; read it first. ` +
    `You do not have the full project plan; for high-level context, defer to the director. ` +
    `You are working in your own git worktree on branch ${stream.id}; do not switch branches or touch other worktrees. ` +
    `Your lane: you own ${owns}. Do not modify files outside your owned paths — another session owns them; ` +
    `coordinate through the director instead. Your issues: ${issues}. ` +
    `Integration interfaces between features live in the contracts directory — read them as the source of truth, ` +
    `and if one is unclear or must change, ask the director rather than reaching into another stream. ` +
    `${kick.autonomy} ` +
    `${kick.push} ` +
    `When you pause or finish a work session, pipe a short note of where you left off and the next step into bsc-checkpoint on stdin so your next session resumes there. ` +
    `Verify your work against the repo tests and CI rather than asking whether it is correct.`
  );
}


// #174: promote a project's planning-assigned automations into the real scheduler on
// launch. Idempotent (skips ones already present by name+command); scheduled (cron)
// suggestions arm, on-demand ones are saved unarmed. Each fires into `targetTab`.
export function activateAutomations(s: AppStore, projectId: string, targetTab: string): Automation[] {
  const suggestions = projectId ? s.planAutomations[projectId] ?? [] : [];
  if (suggestions.length === 0) return [];
  const have = new Set(s.automations.map((a) => `${a.name}�${a.command ?? ""}`));
  const added: Automation[] = [];
  for (const sug of suggestions) {
    const k = `${sug.name}�${sug.command}`;
    if (have.has(k)) continue;
    have.add(k);
    const input = suggestionToAutomation(sug, targetTab);
    added.push({
      ...input,
      id: `auto_${Math.random().toString(36).slice(2, 8)}`,
      lastRunAt: null,
      nextRunAt: input.armed ? computeNextRun(input.when, Date.now()) : null,
      runs: [],
    });
  }
  return added;
}

