/** Plan-session slice of {@link AppStore}. */
export interface PlanState {
  // Claude config profiles (persisted)
  configProfiles: ConfigProfile[];
  addConfigProfile: (profile: Omit<ConfigProfile, "id">) => void;
  updateConfigProfile: (id: string, patch: Partial<Omit<ConfigProfile, "id">>) => void;
  removeConfigProfile: (id: string) => void;

  // Plan session data — persisted per project so navigation away doesn't lose state.
  planStages:    Record<string, Record<string, string>>;
  setPlanStage:  (projectId: string, key: string, content: string) => void;
  planConfirmedStages: Record<string, string[]>;
  confirmPlanStage:   (projectId: string, key: string) => void;
  unconfirmPlanStage: (projectId: string, key: string) => void;
  /** Add a confirmation to the store ONLY (no plan.db write-through) — the poll uses this to
   *  rehydrate the durable confirmed set (#2256) from plan.db on revisit without echoing it back. */
  markStageConfirmedLocal: (projectId: string, key: string) => void;
  /** Per-project deployment & infrastructure config (#919) — edited by the planner's Deploy
   *  stage pane; the `deploymentDefined` gate signal derives from it. */
  planDeployConfig: Record<string, DeployConfig>;
  setPlanDeployConfig: (projectId: string, cfg: DeployConfig) => void;
  /** Per-project market assessment (#2430) — the scored desk-research rubric the planner records
   *  via `bsc plan market set` (reflected from plan.db by the stage poll); the `marketDefined`
   *  gate signal derives from it. */
  planMarketConfig: Record<string, MarketConfig>;
  setPlanMarketConfig: (projectId: string, cfg: MarketConfig) => void;
  /** Per-project transformations list (#2509) — the verb-shaped modification rows the planner
   *  records via `bsc plan transformation add` (reflected from plan.db by the stage poll); the
   *  `transformationsConfirmed` gate signal derives from it. */
  planTransformations: Record<string, TransformationRow[]>;
  setPlanTransformations: (projectId: string, rows: TransformationRow[]) => void;
  /** Per-project migration SOURCE config (#source-pane) — the legacy systems a project migrates
   *  from, declared + connected read-only in the Source stage pane; the `sourcesConnected` gate
   *  signal derives from it. Secret credentials are NEVER stored here (they live in the OS keychain). */
  planSourceConfig: Record<string, SourceConfig>;
  setPlanSourceConfig: (projectId: string, cfg: SourceConfig) => void;
  /** Per-project DEFAULT GitHub repo visibility for new repos at publish (#…). Absent ⇒ false ⇒
   *  PRIVATE; a per-repo override (`repoPublic`) wins over it. Set the default for the project (and
   *  the fallback for repos with no override). */
  reposPublic: Record<string, boolean>;
  setReposPublic: (projectId: string, isPublic: boolean) => void;
  /** Per-REPO GitHub visibility override (#1227), keyed `<projectKey>::<repoFullName>`. Wins over
   *  the project default `reposPublic`; absent ⇒ falls back to the default ⇒ private. Resolved by
   *  `resolveRepoPublic` at the Repos card + at publish. */
  repoPublic: Record<string, boolean>;
  setRepoPublic: (projectKey: string, repoId: string, isPublic: boolean) => void;
  /** #1107: per-project signature of the injection findings the user acknowledged (acknowledge-to-
   *  clear). Cleared when findings change; ignored when the hard-gate setting is on. */
  planInjectionAck: Record<string, string>;
  acknowledgePlanInjections: (projectId: string, signature: string) => void;
  /** Optional stages the user deliberately SKIPPED (#921). The flow stops on every optional stage;
   *  skipping marks it resolved (frontier advances, never blocks completion) but renders distinctly. */
  planSkippedStages:  Record<string, string[]>;
  skipPlanStage:      (projectId: string, key: string) => void;
  unskipPlanStage:    (projectId: string, key: string) => void;
  /** Add a skip to the store ONLY (no plan.db write-through) — the poll uses this to rehydrate the
   *  durable skipped set (#2267) from plan.db on revisit without echoing it back. */
  markStageSkippedLocal: (projectId: string, key: string) => void;
  /** Collapse non-canonical section keys (e.g. "Tech stack" → "stack") for a project,
   *  merging content into the canonical key (and deduping confirmed keys) — repairs a gate
   *  stuck on a stale title-named section (#803). */
  canonicalizePlanStages: (projectId: string) => void;
  planAutomations:    Record<string, AutomationSuggestion[]>;
  /** Replace a project's automations with the DB-owned list (reflected by the section poll from
   *  `bsc plan automations`, #2009). */
  setPlanAutomations: (projectId: string, list: AutomationSuggestion[]) => void;
  clearPlanAutomations: (projectId: string) => void;
  // Modular planning stages (#512): per-project on/off + ordering of the planning
  // stages. Defaults (all-on, registry order) are resolved lazily via
  // defaultStageConfig, so an unset project behaves exactly as today.
  planStageConfig:    Record<string, StageConfig>;
  setStageEnabled:    (projectId: string, stageId: StageId, enabled: boolean) => void;
  reorderStages:      (projectId: string, order: StageId[]) => void;
  /** Wholesale-set a project's stage config (used to seed it from a blueprint). */
  setProjectStageConfig: (projectId: string, config: StageConfig) => void;
  /** Seed a NEW project with the dynamic-stages baseline (#1395): Discovery (`context`) only,
   *  every other stage off + lighting up additively from classification signals. Idempotent —
   *  a no-op once the project has a stage config, so it never clobbers an existing plan. */
  seedDiscoveryOnlyStages: (projectId: string) => void;
  // Blueprints (#513/#514): named, reusable configs — an ordered list of planning
  // sections, each owning its prompt module + pipelines. The active one seeds new
  // projects. Seeded with the starter library; persisted. Section/pipeline edits go
  // through setBlueprintStages (the component computes the new sections array).
  blueprints:         Blueprint[];
  activeBlueprintId:  string;
  setActiveBlueprint: (id: string) => void;
  // Which blueprint each project was last seeded/reset from (#647), keyed by project key.
  // Lets the planner detect when the selected blueprint differs from the project's and
  // offer to reset. Set on first seed + on an explicit blueprint switch.
  projectBlueprintId: Record<string, string>;
  setProjectBlueprintId: (projectId: string, blueprintId: string) => void;
  /** The planner's per-project classification (#3783/#3784) — UI mode + which optional stages the
   *  project needs. Set at discovery via `bsc plan classify`, polled in; drives the UI-stage surface
   *  and the source/mcp/skills/automations visibility signals. */
  planClassification: Record<string, ClassifyConfig>;
  setPlanClassification: (projectId: string, cfg: ClassifyConfig) => void;
  addBlueprint:       () => string;
  /** Promote a completed project's plan into a reusable blueprint (#3785); returns the new id. */
  generateBlueprint:  (projectKey: string) => string;
  duplicateBlueprint: (id: string) => string;
  updateBlueprintMeta: (id: string, patch: Partial<Omit<Blueprint, "id" | "sections">>) => void;
  setBlueprintStages: (id: string, sections: BlueprintStage[]) => void;
  /** Delete a blueprint; if it was active, the active id falls back to the first
   *  remaining (or the default). */
  removeBlueprint: (id: string) => void;
  /** Add an imported blueprint under a fresh id + fresh section uids (never overwrites
   *  an existing one). Returns the new id. */
  importBlueprint: (bp: Blueprint) => string;
  // Stage-pipeline run state (#528/#529): per-project, per-pipeline run status, keyed
  // projectKey -> stageUid -> state. Session-only (not persisted).
  stageRuns: Record<string, Record<string, StageRunState>>;
  setStageRun: (projectKey: string, stageUid: string, state: StageRunState) => void;
  // The current UI preview per project (#531): the render-preview pipeline writes the
  // bundled iframe srcdoc here; PlanPreviewPane renders it. `screen` names which screen
  // is showing (#546), so its approve button targets the right one. Session-only.
  stagePreview: Record<string, { srcDoc: string; mode: "2d" | "3d"; screen?: string } | null>;
  setStagePreview: (projectKey: string, value: { srcDoc: string; mode: "2d" | "3d"; screen?: string } | null) => void;
  // Per-screen UI approval (#544/#546). `uiScreens` is the set of screens the planner
  // has declared via <ui_preview> tags (the denominator); `uiApproved` is the names the
  // user has signed off in the preview pane (the numerator). The UI stage completes only
  // when every declared screen is approved. Both persisted — real approval signals.
  uiScreens: Record<string, string[]>;
  addUiScreen: (projectKey: string, screen: string) => void;
  uiApproved: Record<string, string[]>;
  setUiScreenApproved: (projectKey: string, screen: string, approved: boolean) => void;
  // Agent fleet — the parallel-execution plan (work streams + optional director +
  // the optimal concurrent session count). Persisted per project.
  planFleet:             Record<string, FleetPlan>;
  setPlanFleet:          (projectId: string, fleet: FleetPlan) => void;       // wholesale (from fleet.json poll)
  /** Per-project set of context-file names pinned in the project pane (overrides the
   *  confirmed-section default). projectId -> pinned file names. */
  pinnedContext:         Record<string, string[]>;
  togglePinnedContext:   (projectId: string, name: string) => void;
  addPlanAgentStream:    (projectId: string, stream: AgentStream) => void;    // merge-by-id (from inline tag)
  removePlanAgentStream: (projectId: string, id: string) => void;
  /** #289: assign an AgentProfile id to a stream (null clears). */
  setPlanAgentStreamProfile: (projectId: string, streamId: string, profileId: string | null) => void;
  /** #297: set one or more flow fields on a stream (merged into its resolved flow). */
  setPlanAgentStreamFlow: (projectId: string, streamId: string, patch: Partial<AgentFlow>) => void;
  /** #…: set a stream's per-agent LLM model (undefined clears it so the stream inherits the
   *  global `defaultModel`). Applied at fleet launch as `claude --model <tier>`. */
  setPlanAgentStreamModel: (projectId: string, streamId: string, model: ModelId | undefined) => void;
  /** #378: set a stream's per-stream integration-strategy override (undefined clears
   *  it so the stream inherits the fleet default). */
  setPlanAgentStreamStrategy: (projectId: string, streamId: string, strategy: IntegrationStrategy | undefined) => void;
  /** #2094: set (or clear, with null) the persona a stream launches as — resolves role/prompt/skills/
   *  model at fleet launch. */
  setPlanAgentStreamPersona: (projectId: string, streamId: string, personaId: string | null) => void;
  setPlanFleetMeta:      (projectId: string, recommended: number, reasoning: string, strategy?: IntegrationStrategy) => void;
  /** Per-project coordination-topology override (#…), set in the Permissions pane. Wins
   *  over the planner's fleet.json topology and survives a fleet re-poll. */
  planFleetTopology:     Record<string, Topology>;
  setPlanFleetTopology:  (projectId: string, topology: Topology) => void;
  /** Per-project director-drive override (#…), set in the Permissions pane alongside the
   *  topology. Wins over fleet.json's `director.drive` and survives a fleet re-poll. */
  planFleetDirectorDrive:    Record<string, DirectorDrive>;
  setPlanFleetDirectorDrive: (projectId: string, drive: DirectorDrive) => void;
  setPlanDirector:       (projectId: string, enabled: boolean, role?: string) => void;
  setPlanDirectorDrive:  (projectId: string, drive: DirectorDrive) => void;
  clearPlanFleet:        (projectId: string) => void;
  clearPlan:             (key: string) => void;
}

runtime.store/types/projects.ts:
// Projects domain — page mode/view, active-project meta, drafts, startup-prompt + reference-context
// assignment, planning-session context, triage + fleet launch. Split from store/types (#1634).
import type { FleetPlan, AgentStream } from "@/features/planner/fleet/planFleet";
import type { ProjectLink, ContractTarget } from "@/features/glance/lib/projectLinks";
import type { GEdgeKind, GRole, GHealth, GActivity } from "@/features/glance/lib/glanceGraph";
import type { PreviewSource } from "@/shared/lib/preview/previewSource";
import type { ReviewFinding } from "@/shared/lib/preview/previewReview";

/** Projects slice of {@link AppStore}. */
export interface ProjectsState {
  // Projects (transient). "designs" is the Designs studio page (#move-to-planner) — formerly its own rail
  // Workspace, folded in as a Planner tab; it owns the structure axis AND, since #2834, the theme try-on,
  // so the standalone "themes" tab was retired (#2850). "algorithms" is the knowledge graph, folded in
  // the same way (formerly its own rail Workspace).
  projectsPageMode: "projects" | "teams" | "designs" | "algorithms" | "sounds";
  setProjectsPageMode: (v: "projects" | "teams" | "designs" | "algorithms" | "sounds") => void;
  // Glance drill target (#…): the project whose fleet graph is open on the Glance Network page, or null
  // for the project network. Lifted into the store (transient, not persisted) so the app-wide navigation
  // history (mouse back/forward) can drive it alongside the active workspace. See useNavHistory.
  glanceDrill: string | null;
  setGlanceDrill: (id: string | null) => void;
  // Verify-preview (#2623, transient): the PreviewSource the verify-build produced per project (what the
  // graph's preview node renders), and whether a build is in flight. Not persisted — a served preview
  // URL dies with its process, so it's re-built on demand.
  previewSources: Record<string, PreviewSource>;
  setPreviewSource: (key: string, source: PreviewSource) => void;
  previewBuilding: Record<string, boolean>;
  setPreviewBuilding: (key: string, building: boolean) => void;
  // Preview REVIEW findings (#2623 slice 5b, transient): what the reviewer (Claude) flagged about the
  // running preview, per project key, in the confirm-gated inbox (pending → user confirms/dismisses;
  // confirmed ones route to the fleet, 5d). Not persisted — findings belong to a live preview session.
  reviewFindings: Record<string, ReviewFinding[]>;
  setReviewFindings: (key: string, findings: ReviewFinding[]) => void;
  // Teams drill target (#2492): the pool nodeId whose sub-graph is open in the Teams designer, or null for
  // the parent graph. Transient like glanceDrill and lifted into the store for the same reason — the
  // app-wide navigation history (mouse back/forward) steps drill in/out. See useNavHistory.
  teamsDrill: string | null;
  setTeamsDrill: (id: string | null) => void;
  // Inter-app contracts (#2253 → #3786 Phase 2) — the edges of the Glance L0 network. A write-through
  // cache over the global `bsc project link` store (agent-reachable): `addProjectLink` (idempotent,
  // deterministic id) + `removeProjectLink` push through the bridge; `hydrateProjectLinks` loads
  // authoritative on boot; the persisted copy is a fast-first-paint fallback. `target` (#3786) names a
  // NON-project endpoint (an external service / mcp server); absent ⇒ a project↔project contract.
  projectLinks: ProjectLink[];
  addProjectLink: (from: string, to: string, kind: GEdgeKind, target?: ContractTarget) => void;
  removeProjectLink: (id: string) => void;
  /** Hydrate the links from the global `bsc project link` store on boot (write-through cache). No-op when
   *  the bridge is unreachable (keeps the persisted cache). */
  hydrateProjectLinks: () => Promise<void>;
  // The Projects page is list ↔ planning (#499): the board moved to the GitHub
  // page (#498) and the execution tabs were removed.
  projectsView: "list" | "planning";
  setProjectsView: (v: "list" | "planning") => void;
  activeProjectId: string | null;
  activeProjectName: string;
  activeProjectRepo: string;
  activeProjectRepos: string[];
  activeProjectNumber: number;
  setActiveProject: (id: string | null) => void;
  setActiveProjectMeta: (id: string | null, name: string, repo: string, number: number, repos?: string[]) => void;
  setActiveProjectRepos: (repos: string[]) => void;
  // Purge a project's local footprint from the store: the per-project plan/config
  // maps and repo-scoped (`<key>::<repo>`) maps for every key in `keys` (pass the
  // name-derived slug, plus any legacy forms — the raw title and the GitHub node id —
  // so grandfathered entries drop too, #2409), plus the active-project meta if it
  // matches. Pairs with the backend delete_project_dir for the on-disk hub.
  deleteLocalProject: (keys: string[]) => void;
  /** New, not-yet-published projects (drafts, #379). Keyed by the planning session key —
   *  the name-derived slug (`projectSlug(name)`, #2409) frozen at creation, or a legacy key
   *  (minted `p-…` id / title-sanitized) for grandfathered drafts. The record's `title` is
   *  display-only: renaming edits it in place (`updateDraftProject`) and never moves the
   *  on-disk hub (the folder keeps its birth-slug). */
  /** `role`/`health`/`activity` (#2284/#2541) are OPTIONAL Glance-node hints: when set they give the
   *  project's node its curated colour/state on the Glance network (`infra/service/data/client` ·
   *  health `idle/healthy/warning/error` · activity `building/waiting/review/…`), else
   *  `useGlanceProjects` derives them. Lets a project (or a loaded demo) declare its own colouring. */
  localDraftProjects: Record<string, { title: string; pitch: string; createdAt: number; role?: GRole; health?: GHealth; activity?: GActivity; reason?: string }>;
  addDraftProject: (key: string, draft: { title: string; pitch: string; createdAt: number; role?: GRole; health?: GHealth; activity?: GActivity; reason?: string }) => void;
  /** Patch a draft record in place (#1222) — persists a title edit so it survives a reopen;
   *  keyed by the FROZEN key so the on-disk folder doesn't move. No-ops if the draft is gone. */
  updateDraftProject: (key: string, patch: Partial<{ title: string; pitch: string }>) => void;
  removeDraftProject: (key: string) => void;
  /** TRIAGED projects (#2541): the durable set of projects whose triage/fleet has been launched — the
   *  drafted→triaged transition. Keyed by the plan key → the ms epoch it was first triaged. This is what
   *  gates the Glance network: a project appears there only once it's WORKING (`useGlanceProjects` filters
   *  to these keys), so a mere draft/plan never shows. Stamped by `triageStartProject`/`fleetStartProject`. */
  triagedProjects: Record<string, number>;
  /** Mark a project triaged (idempotent — keeps the first timestamp). */
  markProjectTriaged: (key: string) => void;
  /** Union the durable triaged markers from projects.db into the cache (#4088). */
  hydrateTriaged: (fromDb: Record<string, number>) => void;
  /**
   * Move every per-project store entry from `oldKey` to `newKey` (#2409) — the store half of the
   * one-time hub relink (`relink_project_hub`) that migrates a legacy-keyed project onto its
   * name-derived slug. Covers the per-project data maps (plans, fleet, repos, drafts, toggles),
   * the repo-scoped (`<key>::<repo>`) prompt maps, and extension/skill scope lists. Target-wins:
   * an entry already present under `newKey` is never clobbered (the old one is dropped). Console
   * tab/pane state is NOT rewritten — a relinked project relaunches its fleet under the new key.
   */
  rekeyProjectData: (oldKey: string, newKey: string) => void;
  // Dev reset: clears all project/plan-scoped state (keeps auth, profiles, UI).
  resetProjectData: () => void;
  // GitHub project ids the user removed in-app (persisted). The Projects list is
  // re-fetched from GitHub on every sync, so without this a deleted-but-still-
  // returned project (closed, delete denied, or stale) would reappear. The list
  // is filtered against this set so removal sticks.
  hiddenProjectIds: string[];
  dismissProject: (id: string) => void;
  // Startup-prompt assignment (persisted). Values are unified-store document
  // relpaths, or null = inherit. Resolution: repo → project → global default →
  // built-in. See lib/startupPrompt.ts.
  defaultStartupPromptDoc: string | null;
  setDefaultStartupPromptDoc: (doc: string | null) => void;
  projectStartupPromptDoc: Record<string, string | null>;
  setProjectStartupPromptDoc: (projectId: string, doc: string | null) => void;
  repoStartupPromptDoc: Record<string, string | null>;
  setRepoStartupPromptDoc: (projectId: string, repo: string, doc: string | null) => void;
  // Per-repo TRIAGE starting script (persisted). relpath of a unified-store doc,
  // or null. Used by triageStartProject for that repo's triage pane; falls back
  // to the verbatim TRIAGE_PROMPT when unset. Keyed by repoPromptKey.
  repoTriagePromptDoc: Record<string, string | null>;
  setRepoTriagePromptDoc: (projectId: string, repo: string, doc: string | null) => void;
  // The GitHub page's active top tab (summary | projects | repos), store-controlled
  // so other screens can deep-link to it (e.g. the Projects list signpost → projects).
  githubTab: string;
  setGithubTab: (t: string) => void;
  // The GitHub Projects v2 board now lives on the GitHub page (#498). When a project
  // is opened from the GitHub portfolio, this flips on and its board renders there
  // with `githubBoardTab` selecting the sub-view. Session-only (not persisted).
  githubBoardOpen: boolean;
  githubBoardTab: "board" | "roadmap" | "issues" | "insights";
  /** Open the GitHub-page board for the active project at a given sub-tab. */
  openGithubBoard: (tab?: "board" | "roadmap" | "issues" | "insights") => void;
  setGithubBoardTab: (t: "board" | "roadmap" | "issues" | "insights") => void;
  closeGithubBoard: () => void;
  projectsDrawerIssue: number | null;
  setProjectsDrawerIssue: (n: number | null) => void;
  planningPitch: string;
  planningRepo: string;
  planningTitle: string;
  setPlanningContext: (pitch: string, repo: string) => void;
  setPlanningTitle: (title: string) => void;
  // Stable per-session key for the planning directory, PTY slot, and plan
  // buckets. Frozen the moment a planning session begins so that neither the
  // publish flow assigning a GitHub Project id, nor the user editing the title,
  // can move the working directory out from under an active session. This is the
  // name-derived slug (`projectSlug(name)`, #2409) frozen at creation — renames are
  // display-only (the folder keeps its birth-slug); grandfathered projects pass
  // their legacy key (minted `p-…` id / title-sanitized) here unchanged.
  planningSessionKey: string;
  setPlanningSession: (key: string) => void;
  /** A prompt queued for the live planner session of a project, keyed by project key.
   *  Planning.tsx writes it into the planner PTY (a deliberate, user-triggered inject —
   *  e.g. the file-intake "Route" action) and clears it. (#604) */
  pendingPlannerPrompt: Record<string, string>;
  requestPlannerPrompt: (projectKey: string, text: string) => void;
  clearPlannerPrompt: (projectKey: string) => void;
  // Per-project AUTO-TRIAGE toggle (#2265). When ON, the fault-fix loop (useFaultTriage) routes a fix
  // for a new unresolved runtime fault (errordb, #2260) into the project's director via bsc-issue →
  // bsc-assign; when OFF (the default) faults are surfaced (the Glance node badge) but never
  // auto-dispatched. Keyed by the project's plan key (the same key the errordb/plan.db resolve under).
  autoTriage: Record<string, boolean>;
  /** Flip a project's auto-triage toggle (persisted). Default (absent) is OFF = surface-only. */
  setAutoTriage: (projectKey: string, on: boolean) => void;
  // Per-node Glance OFF toggle (#3239) — the user has DEACTIVATED this node from its details pane, so
  // it renders greyed (health `off`) on the network and reads "off" over any live status. Persisted so it
  // continues from the last session; keyed by the Glance node id (a project's plan key). Sparse map:
  // absent ⇒ the node is ON (its normal derived status). Cleaned on project delete/rename.
  glanceOff: Record<string, boolean>;
  /** Turn a Glance node off (deactivate, greyed) or back on (persisted). Default (absent) is ON. */
  setGlanceNodeOff: (nodeId: string, off: boolean) => void;
  // Per-project KIT AUTO-DISPATCH toggle (#2277). When ON, the kit-change drain (useKitDispatch) delivers
  // a BREAKING kit change queued for this consumer to a rail — a live fleet → its director via bsc-issue →
  // bsc-assign; no live fleet → a plain kit-update GitHub issue in the consumer repo. When OFF (the
  // default) queued changes are surface-only (KitChangesCard). Keyed by the consumer project's plan key.
  autoKitDispatch: Record<string, boolean>;
  /** Flip a project's kit auto-dispatch toggle (persisted). Default (absent) is OFF = notify-only. */
  setAutoKitDispatch: (projectKey: string, on: boolean) => void;
  // project key -> structure node id -> linked GitHub issue (#393).
  issueLinks: Record<string, Record<string, { number: number; url: string }>>;
  // Merge links for a project (idempotent upsert; never drops existing entries).
  setIssueLinks: (projectKey: string, links: Record<string, { number: number; url: string }>) => void;
  // Repository resolution — base dir is `~/.base-studio-code` (the base); repo
  // clone paths are derived as `<base>/projects/<key>/<repo>`.
  bscBaseDir: string;
  setBscBaseDir: (dir: string) => void;
  projectLocalRepos: Record<string, string[]>;
  addProjectRepo: (projectId: string, fullName: string) => void;
  // `deltas` (#1004): optional per-repo (fullName → lead) since-last-run summary, prepended to
  // each pane's default triage prompt so a re-run resumes from what changed instead of re-ingesting.
  // Built by `prepareTriageRun` (which also records the new run marker) and passed in at launch.
  // `clonePaths` (#1819): optional per-repo (fullName → absolute clone dir) cwds resolved from the
  // Rust backend (`repo_dir_path`), mirroring `fleetStartProject`'s `paths`. Used verbatim so a
  // triage launch never depends on the async-loaded `bscBaseDir` mirror (empty at crash-recovery
  // startup → empty cwd → the settings.json writer is skipped → a permission-less session); falls
  // back to the `bscBaseDir`-derived path per repo when an entry is absent.
  triageStartProject: (projectName: string, repos: string[], projectId?: string, deltas?: Record<string, string>, clonePaths?: Record<string, string>) => void;
  // #1004: read each repo's last-triage marker + the since-then changed-issue delta from plan.db,
  // render a one-line resume lead per repo, and STAMP a fresh run marker (read-before-write). Keyed
  // by the project's plan.db key (effectiveProjectId). Returns the fullName → lead map for `deltas`.
  prepareTriageRun: (projectKey: string, repos: string[]) => Promise<Record<string, string>>;
  // Index of this project's triage tab, matched on its STABLE projectKey — the
  // name-derived key (#457/#2409), not the derived "· triage" name — so a rename never
  // forks a duplicate. Pass the same projectName used to launch it. -1 when none.
  findTriageTabIdx: (projectName: string) => number;
  // Launch the agent fleet: a "· build" tab with the director (if enabled) at the
  // project root and one worker pane per launched stream in its repo clone. Path
  // keys off projectKey (the planning session key — where repos/prompts live).
  /** Launches the fleet; returns the fleet roster rows (paneId/stream/repo/branch/role TSV,
   *  one per live session) for the caller to persist via publishFleetRoster (#734). */
  fleetStartProject: (
    projectName: string,
    fleet: FleetPlan,
    projectKey: string,
    /** Authoritative absolute cwds from the Rust backend (#905): the hub dir
     *  (`project_dir_path`) for the director and each stream's worktree path
     *  (`ensure_worktree`) for its worker. Used verbatim so the launch never
     *  depends on the async-loaded `bscBaseDir` mirror; falls back to the
     *  `bscBaseDir`-derived path per pane when an entry is absent. */
    paths?: { hubPath?: string; worktreePaths?: Record<string, string>;
      /** When set (#1988), the fleet spawns INSIDE this WSL2 distro: hubPath/worktreePaths are
       *  distro-native paths and each pane records `paneWslDistro` so pty_create runs in the cage. */
      wslDistro?: string },
  ) => string[];
  // Index of this project's primary "· build" tab, matched on its STABLE projectKey
  // (#457) — pass the same projectKey used to launch the fleet. -1 when none.
  findFleetTabIdx: (projectKey: string) => number;
  // Coordination (#199 AC#7): paneId ("t{tab}p{pane}") → the AgentStream launched into
  // it. The coordination log keys waiters/producers by PANE id (BSC_AUDIT_PANE), but a
  // stream's produced contracts/issues/owned globs live on the stream by its slug. This
  // map bridges the two so the inbox can build a producer resolver (buildProducerOf) and
  // light up file/issue wait-for cycles. Written at fleet launch, persisted, global
  // (pane ids are unique across all tabs). Only worker panes are recorded.
  fleetPaneStreams: Record<string, AgentStream>;
}

runtime.store/types/session.ts:
// Session-behavior domain — denied shell commands + the console-behavior toggles (auto-focus,
// auto-resume, gate overrides, default/per-pane model, fleet harness). Split from store/types (#1634).
import type { ConsoleAutoFocusMode } from "@/app/console/lib/focusQueue";
import type { ModelId } from "@/app/console/panes/PaneMenu";
import type { StudioTarget } from "@/shared/lib/fleet/studioNetworkDrive";

/** Session-behavior slice of {@link AppStore}. */
export interface SessionState {
  // Blocked shell commands. Sessions allow Bash broadly (start-and-go); the
  // backend always denies a curated dangerous set, and these are the user's
  // additional global denies. Deny wins
  // over allow.
  deniedCommands: string[];
  addDeniedCommand: (cmd: string) => void;
  removeDeniedCommand: (cmd: string) => void;
  setDeniedCommands: (commands: string[]) => void;

  // Console behavior
  // Selectable auto-focus mode (#434): controls whether and when focus advances
  // after you reply. Persisted; configured in Settings → Integrations.
  // Replaces the old boolean; autoAdvanceOnReply is kept for Console.tsx back-compat.
  autoFocusMode: ConsoleAutoFocusMode;
  setAutoFocusMode: (mode: ConsoleAutoFocusMode) => void;
  // Back-compat derived field: true when autoFocusMode is not "off".
  autoAdvanceOnReply: boolean;
  setAutoAdvanceOnReply: (v: boolean) => void;
  // When true, panes that had claude running at last shutdown auto-relaunch
  // it with --continue on next mount (persisted; configured in Settings →
  // Integrations). Gated per pane by paneWasClaude — off by default for
  // panes that never used claude (#36).
  autoResumeClaude: boolean;
  /** #1107: hard-gate plan publishing on detected prompt-injection markers. ON ⇒ a flagged plan
   *  cannot publish until the marker is removed; OFF (default) ⇒ acknowledge-to-clear. */
  injectionHardGate: boolean;
  setInjectionHardGate: (v: boolean) => void;
  /** Permission posture (#1916): true ⇒ agents (and manual consoles) auto-run and the PreToolUse hooks
   *  do the gating (the deny-list); false ⇒ Claude's `default` mode enforces the enumerated allow-list
   *  (require approval). Default true. Threaded to `write_session_settings` via `buildSessionSettings`. */
  bypassPermissions: boolean;
  setBypassPermissions: (v: boolean) => void;
  /** #1988: launch console panes INSIDE the sealed WSL2 sandbox distro (`bsc-agent-sandbox`) — a clean
   *  bash at the distro home. Opt-in; off by default. Your Windows repos aren't mounted in (the seal),
   *  so it's a scratch/verification shell until project files are relocated into the distro. */
  sandboxConsoles: boolean;
  setSandboxConsoles: (v: boolean) => void;
  /** #3298: whether the DEBUG session's window is open — a full-capability Claude session in the
   *  base-studio-code SOURCE tree that works the `bsc request` improvement queue (fixing `bsc ui`).
   *  SESSION-ONLY (not persisted): the OS window is session-only, so this defaults off each start and
   *  the toggle opens/closes the window. */
  debugSession: boolean;
  setDebugSession: (v: boolean) => void;
  /** #3498: may a session be started AUTOMATICALLY (by the `bsc request` intake), without a human
   *  asking? OFF by default and the outer gate of the auto-spawn boundary — the inner one being that
   *  ONLY the `debugger` role is ever auto-spawnable (`shared/lib/session/autoSpawn.ts`, the single
   *  authoriser). Auto-spawn is the highest-consequence capability in the app — a session that starts
   *  itself runs a real model against a real repo — so it is opt-in, per-machine, and fails closed:
   *  anything that is not literally `true` reads as off. */
  autoSpawnDebugSessions: boolean;
  setAutoSpawnDebugSessions: (v: boolean) => void;
  /** #3498: the request ids that currently have a spawned debug session. Lives in the STORE, not in the
   *  mount's local state, because the Glance graph must render a node per live session — an auto-spawned
   *  session that appears nowhere is one the user cannot open, supervise or stop. Session-only. */
  /** Live debugger OVERFLOW pool SLOT indices (#3535) — one per running overflow session, published by
   *  RequestSessionsMount so the Glance graph can render a node per slot. Not request ids: a slot claims
   *  a request only after it launches. Session-only. */
  activeDebugSlots: number[];
  setActiveDebugSlots: (slots: number[]) => void;
  /** #3509: the base-studio-code source tree this app was built from, or null on a shipped binary.
   *  Resolved ONCE at boot so a launch can turn a role's symbolic `app-repo` harvest root into a real
   *  path synchronously. Session-only — it is a property of the machine, not of the user's state. */
  appRepoRoot: string | null;
  setAppRepoRoot: (p: string | null) => void;
  /** #2372: show the legacy Console page as a rail destination. OFF by default — the graph (Glance)
   *  is the execution surface; the console page is being retired. When off, its rail entry is hidden
   *  and a console-active workspace falls back to Glance (derived in App). */
  showConsolePage: boolean;
  setShowConsolePage: (v: boolean) => void;
  /** #2940 (studio network): the app-owned studio sessions the pump currently wants reachable —
   *  targets ("designer"/"librarian") with at least one open commission. Written by
   *  `useStudioNetworkPump` each tick; read by ConsoleWorkspace's lazy-mount hosts, which launch the
   *  target session on demand and tear it down when the list empties. SESSION-ONLY (not persisted). */
  activeStudioTargets: StudioTarget[];
  setActiveStudioTargets: (t: StudioTarget[]) => void;
  /** #199: auto-relaunch a parked pane when its deps land (opt-in; off by default). */
  coordAutoWake: boolean;
  setCoordAutoWake: (v: boolean) => void;
  setAutoResumeClaude: (v: boolean) => void;
  /** #682: let Claude auto-drive the planning phase from a pitch (opt-in; off by default).
   *  Enables the "Auto-plan" control on the planner page. */
  autoPlanWithClaude: boolean;
  setAutoPlanWithClaude: (v: boolean) => void;
  /** #1068: auto-advance planner gates — when a stage's sections are ready, confirm them without
   *  the manual "approve & continue" click (opt-in; off by default). One global flag every gate
   *  follows; steps aside while the planning autopilot is running (it owns confirmation then). */
  autoCompleteGates: boolean;
  setAutoCompleteGates: (v: boolean) => void;
  /** Allow the user to override a blocking planner stage gate and advance anyway (#1285). Off by
   *  default; surfaces a cautionary "override gate & continue" action in the planner footer. */
  allowGateOverride: boolean;
  setAllowGateOverride: (v: boolean) => void;
  /** #738 (security): restrict agents that pull live GitHub issues (triage) to issues
   *  base-studio-code authored — the `bsc-generated` label. ON by default so a hand-created
   *  or injected issue isn't acted on; off works every open issue. */
  restrictToBscIssues: boolean;
  setRestrictToBscIssues: (v: boolean) => void;
  /** Default Claude model new console panes open with (persisted; configured in
   *  Settings → General). Per-pane override lives in the pane hamburger menu. */
  defaultModel: ModelId;
  setDefaultModel: (m: ModelId) => void;
  /** Which harness the agent fleet launches on (#1078 P5): "claude" (default) or
   *  "bsc-agent" — our model-agnostic runtime, on the provider configured in
   *  Settings → Integrations. Persisted. */
  fleetHarness: "claude" | "bsc-agent";
  setFleetHarness: (h: "claude" | "bsc-agent") => void;
  /** Per-pane model override, keyed by paneId. A pane with no entry falls back to
   *  {@link defaultModel}. Applied to `claude --model` at the pane's next launch. */
  paneModels: Record<string, ModelId>;
  setPaneModel: (paneId: string, m: ModelId) => void;
}

runtime.store/types/shell.ts:
// App-chrome domain — automations/settings sub-tabs, per-page tab order, detached tabs/sections,
// and perf + log config. Split from store/types (#1634).
import type { PerfConfig } from "./perf";
import type { LogConfig } from "./log";
import type { AppStateSnapshot } from "../appState";

/** App-chrome slice of {@link AppStore}. */
export interface ShellState {
  // Automations
  automationsTab: "schedules" | "history";
  setAutomationsTab: (tab: ShellState["automationsTab"]) => void;
  /** Persisted, user-arranged tab order per page (keyed by page id). A page opens
   *  whatever tab the user dragged to the front, so the order IS the preference
   *  (#463). Unknown/new tabs append; stale ids are ignored. */
  pageTabOrder: Record<string, string[]>;
  setPageTabOrder: (page: string, order: string[]) => void;
  /** Persisted last-selected page (tab id) per page (keyed by page id). Lets a
   *  workspace reopen on the Page the user last viewed — across an in-session
   *  workspace switch (most workspaces unmount when inactive) and across restart —
   *  instead of always snapping back to the front tab. Falls back to the front tab
   *  (see {@link pageTabOrder}, #463) when there's no memory; a stale id self-heals
   *  to the front tab via `usePageTabs`'s validity effect. */
  activePageTab: Record<string, string>;
  setActivePageTab: (page: string, id: string) => void;
  /** The navigated ENTITY label per graph, keyed by page id (`glance`/`teams`/`designs`/`algorithms`),
   *  reported by each graph via `useCrumbEntity` so the titlebar location crumb can name where you are
   *  INSIDE a graph — the drilled project, entered team, active kit, active language (#3041). Session-only
   *  transient (NOT persisted): each graph re-reports on mount, so it's always live. Empty = no entity. */
  crumbEntity: Record<string, string>;
  setCrumbEntity: (key: string, label: string) => void;
  /** Console tab ids currently shown in their own window (#430). Session-only
   *  (NOT persisted): hidden from this window's tab bar while detached, cleared
   *  on re-dock or app restart — so the tab returns to its persisted place. */
  detachedTabIds: string[];
  setTabDetached: (id: string, detached: boolean) => void;
  /** Per-page section ids currently shown in their own window (#430). Session-only
   *  (NOT persisted), like detachedTabIds — hidden from the page's tab bar while
   *  detached, returned on re-dock/restart to their persisted place. */
  detachedSections: Record<string, string[]>;
  setSectionDetached: (page: string, id: string, detached: boolean) => void;

  // Settings
  settingsSection: string;
  setSettingsSection: (section: string) => void;
  /**
   * First-run OS-sandbox setup nudge (#1916). How many times the user has DISMISSED the banner
   * (pressed the ✕). The banner shows on launch while the deny-list posture is on and the sandbox
   * isn't ready, and stays hidden once this reaches `SANDBOX_NUDGE_MAX_DISMISSALS`. Counting
   * dismissals (not shows) means the nudge persists across launches until the user actually
   * acknowledges it, rather than silently vanishing after a render they may have missed.
   */
  sandboxNudgeDismissCount: number;
  /** Record a ✕ dismissal of the sandbox nudge. */
  dismissSandboxNudge: () => void;

  // Performance monitoring (#569)
  perfConfig: PerfConfig;
  setPerfConfig: (config: PerfConfig) => void;

  // Log management (#1060)
  logConfig: LogConfig;
  setLogConfig: (config: LogConfig) => void;

  // Demo app-state (#2272) — a loaded demo overlays the demoable store slices; the pre-demo values
  // are stashed in `demoBackup` so clearing restores exactly what was there (empty → empty). Both
  // persist so a demo survives restart and stays clearable.
  /** Whether a demo app-state is currently loaded over the user's real state. */
  demoActive: boolean;
  /** The demoable slice values captured just before the demo was loaded (null when no demo active). */
  demoBackup: AppStateSnapshot | null;
  /** Overlay a demo snapshot onto the store, backing up the current demoable state first (once). */
  loadDemoState: (snapshot: AppStateSnapshot) => void;
  /** Restore the pre-demo state (no-op when no demo is active). */
  clearDemoState: () => void;
}

runtime.store/updateHelpers.ts:
// Pure, non-mutating immutable-update helpers for the Zustand slices (#1704).
//
// The slices repeat the same immutable idioms hundreds of times — `{ ...map, [key]: val }` to set a
// record entry, `const n = { ...map }; delete n[key]` to drop one, and `arr.map((x, i) => i === idx
// ? { ...x, ...patch } : x)` to patch one array item. These helpers name those idioms so the call
// sites read by intent. Each returns a NEW value and never mutates its argument, so they're safe to
// use directly inside a Zustand `set((s) => …)` updater.

/** Return a NEW record with `key` set to `value`; the input map is not mutated. */
export function setMapEntry<K extends PropertyKey, V>(
  map: Record<K, V>,
  key: K,
  value: V,
): Record<K, V> {
  return { ...map, [key]: value } as Record<K, V>;
}

/** Return a NEW record with `key` removed; the input map is not mutated. A missing key is a no-op. */
export function deleteMapEntry<K extends PropertyKey, V>(
  map: Record<K, V>,
  key: K,
): Record<K, V> {
  const next: Record<K, V> = { ...map };
  delete (next as Partial<Record<K, V>>)[key];
  return next;
}

/** Return a NEW record with every key in `keys` removed; the input map is not mutated. Missing keys
 *  are no-ops. */
export function deleteMapEntries<K extends PropertyKey, V>(
  map: Record<K, V>,
  keys: Iterable<K>,
): Record<K, V> {
  const next: Record<K, V> = { ...map };
  for (const key of keys) delete (next as Partial<Record<K, V>>)[key];
  return next;
}

/** Return a NEW array with the item at `index` shallow-merged with `patch`; the input array is not
 *  mutated. An out-of-range index leaves the array unchanged (a fresh copy with identical items). */
export function updateArrayItem<T extends object>(
  arr: T[],
  index: number,
  patch: Partial<T>,
): T[] {
  return arr.map((item, i) => (i === index ? { ...item, ...patch } : item));
}
